export default AIProposedMatches;

﻿/**
 * AccessCodeScreen - Gate screen requiring access code before viewing the app
 * Controlled via admin settings - can be disabled when going live
 */
import React, { useState, useEffect } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { Lock, Loader2, Waves } from 'lucide-react';
import { Button } from './ui/button';
import { Input } from './ui/input';

const ACCESS_CODE_KEY = 'site_access_code'; // Stores the actual code for re-validation

export const AccessCodeScreen = ({ children }) => {
  const [checking, setChecking] = useState(true);
  const [accessRequired, setAccessRequired] = useState(false);
  const [accessGranted, setAccessGranted] = useState(false);
  const [code, setCode] = useState('');
  const [error, setError] = useState('');
  const [verifying, setVerifying] = useState(false);

  useEffect(() => {
    checkAccess();
  }, []);

  const checkAccess = async () => {
    try {
      // First check if access code is even enabled
      const response = await apiClient.get(`/site-access`);
      
      if (!response.data.access_code_enabled) {
        // Access code not required - grant access
        setAccessGranted(true);
        setChecking(false);
        return;
      }
      
      // Access code IS required - check if we have a stored code
      const storedCode = localStorage.getItem(ACCESS_CODE_KEY);
      
      if (storedCode) {
        // Verify the stored code is still valid against the backend
        try {
          const verifyResponse = await apiClient.post(`/site-access/verify`, { code: storedCode });
          if (verifyResponse.data.valid) {
            setAccessGranted(true);
            setChecking(false);
            return;
          } else {
            // Code is no longer valid (admin changed it) - clear and require re-entry
            localStorage.removeItem(ACCESS_CODE_KEY);
          }
        } catch {
          // Verification failed - clear stored code
          localStorage.removeItem(ACCESS_CODE_KEY);
        }
      }
      
      // No valid stored code - require entry
      setAccessRequired(true);
    } catch (err) {
      // If endpoint fails, assume no access code needed
      setAccessGranted(true);
    } finally {
      setChecking(false);
    }
  };

  const verifyCode = async (e) => {
    e.preventDefault();
    if (!code.trim()) {
      setError('Please enter an access code');
      return;
    }

    setVerifying(true);
    setError('');

    try {
      const response = await apiClient.post(`/site-access/verify`, { code: code.trim() });
      if (response.data.valid) {
        // Store the actual code for future re-validation
        localStorage.setItem(ACCESS_CODE_KEY, code.trim().toUpperCase());
        setAccessGranted(true);
      } else {
        setError('Invalid access code');
      }
    } catch (err) {
      setError('Failed to verify code. Please try again.');
    } finally {
      setVerifying(false);
    }
  };

  // Loading state
  if (checking) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
      </div>
    );
  }

  // Access granted - show the app
  if (accessGranted || !accessRequired) {
    return children;
  }

  // Access code required - show gate screen
  return (
    <div className="min-h-screen bg-gradient-to-br from-black via-zinc-900 to-black flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        {/* Logo/Brand */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-gradient-to-br from-cyan-500 to-blue-600 mb-4">
            <Waves className="w-10 h-10 text-white" />
          </div>
          <h1 className="text-3xl font-bold text-white mb-2">Raw Surf</h1>
          <p className="text-zinc-400">Private Beta Access</p>
        </div>

        {/* Access Code Form */}
        <div className="bg-zinc-900/50 border border-zinc-800 rounded-2xl p-6">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-2 rounded-full bg-cyan-500/10">
              <Lock className="w-5 h-5 text-cyan-400" />
            </div>
            <div>
              <h2 className="text-white font-semibold">Enter Access Code</h2>
              <p className="text-zinc-500 text-sm">This site is currently in private beta</p>
            </div>
          </div>

          <form onSubmit={verifyCode} className="space-y-4">
            <div>
              <Input
                type="text"
                placeholder="Access code"
                value={code}
                onChange={(e) => {
                  setCode(e.target.value.toUpperCase());
                  setError('');
                }}
                className="bg-zinc-800 border-zinc-700 text-white placeholder-zinc-500 text-center text-lg tracking-widest uppercase"
                autoComplete="off"
                autoFocus
              />
              {error && (
                <p className="text-red-400 text-sm mt-2 text-center">{error}</p>
              )}
            </div>

            <Button
              type="submit"
              disabled={verifying || !code.trim()}
              className="w-full bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white font-semibold py-3"
            >
              {verifying ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Verifying...
                </>
              ) : (
                'Enter Site'
              )}
            </Button>
          </form>

          <p className="text-zinc-600 text-xs text-center mt-6">
            Don't have a code? Contact the site owner for access.
          </p>
        </div>
      </div>
    </div>
  );
};

export default AccessCodeScreen;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  Trophy, CheckCircle, XCircle, Loader2, ExternalLink,
  Calendar, MapPin, Medal, Eye, Shield, Award
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Button } from './ui/button';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';
import { Badge } from './ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';


/**
 * Admin Competition Result Verification
 * Allows admins to verify/reject pending competition results
 */
export const AdminCompetitionVerification = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  
  const [pendingResults, setPendingResults] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedResult, setSelectedResult] = useState(null);
  const [showProofModal, setShowProofModal] = useState(false);
  const [processing, setProcessing] = useState(false);

  const isLight = theme === 'light';
  const cardBg = isLight ? 'bg-white border-gray-200' : 'bg-card border-border';
  const textPrimary = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  useEffect(() => {
    fetchPendingResults();
  }, []);

  const fetchPendingResults = async () => {
    setLoading(true);
    try {
      const res = await apiClient.get(`/career/admin/pending-verifications`);
      setPendingResults(res.data?.results || []);
    } catch (error) {
      logger.error('Failed to fetch pending results:', error);
      // If endpoint doesn't exist yet, show empty
      setPendingResults([]);
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async (resultId, approved) => {
    setProcessing(true);
    try {
      const _res = await apiClient.post(`/career/competition-results/${resultId}/verify`, null, {
        params: {
          approved
        }
      });
      
      toast.success(approved ? 'Result verified! XP awarded.' : 'Result rejected.');
      
      // Remove from list
      setPendingResults(prev => prev.filter(r => r.id !== resultId));
      setShowProofModal(false);
      setSelectedResult(null);
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to process verification');
    } finally {
      setProcessing(false);
    }
  };

  const getPlaceBadge = (placing) => {
    if (placing === 1) return <Badge className="bg-yellow-500/20 text-yellow-400 border-yellow-500/30">1st</Badge>;
    if (placing === 2) return <Badge className="bg-gray-300/20 text-gray-300 border-gray-300/30">2nd</Badge>;
    if (placing === 3) return <Badge className="bg-amber-600/20 text-amber-500 border-amber-600/30">3rd</Badge>;
    return <Badge className="bg-zinc-500/20 text-zinc-400 border-zinc-500/30">{placing}th</Badge>;
  };

  const getTierBadge = (tier) => {
    const tiers = {
      'WSL_CT': { color: 'bg-purple-500/20 text-purple-400 border-purple-500/30', label: 'WSL CT' },
      'WSL_QS': { color: 'bg-blue-500/20 text-blue-400 border-blue-500/30', label: 'WSL QS' },
      'Regional': { color: 'bg-cyan-500/20 text-cyan-400 border-cyan-500/30', label: 'Regional' },
      'Local': { color: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30', label: 'Local' },
      'Grom_Series': { color: 'bg-pink-500/20 text-pink-400 border-pink-500/30', label: 'Grom Series' }
    };
    const tierInfo = tiers[tier] || { color: 'bg-zinc-500/20 text-zinc-400 border-zinc-500/30', label: tier || 'N/A' };
    return <Badge className={`${tierInfo.color}`}>{tierInfo.label}</Badge>;
  };

  if (!user?.is_admin) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <Shield className="w-12 h-12 text-red-400 mx-auto mb-3" />
          <p className={textPrimary}>Admin access required</p>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 text-yellow-400 animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-6" data-testid="admin-competition-verification">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className={`text-xl font-bold ${textPrimary} flex items-center gap-2`} style={{ fontFamily: 'Oswald' }}>
            <Trophy className="w-6 h-6 text-yellow-400" />
            Competition Verification
          </h2>
