// Invite Modal Content Component - handles both code sharing and handle-based invites
const InviteModalContent = ({ booking, user, isLight, textPrimaryClass, textSecondaryClass, onCopyCode, onClose, onRefresh }) => {
  const [activeTab, setActiveTab] = useState('handle'); // 'handle' or 'code'
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [searching, setSearching] = useState(false);
  const [inviting, setInviting] = useState(null);
  const [sentInvites, setSentInvites] = useState([]);
  const [inviteMessage, setInviteMessage] = useState('');
  
  // Debounced search for users
  useEffect(() => {
    if (!booking?.id || searchQuery.length < 2) {
      setSearchResults([]);
      return;
    }
    
    const timeoutId = setTimeout(async () => {
      setSearching(true);
      try {
        const response = await apiClient.get(
          `/bookings/${booking.id}/search-users?query=${encodeURIComponent(searchQuery)}`
        );
        setSearchResults(response.data || []);
      } catch (error) {
        logger.error('Search error:', error);
        setSearchResults([]);
      } finally {
        setSearching(false);
      }
    }, 300);
    
    return () => clearTimeout(timeoutId);
  }, [searchQuery, booking?.id, user?.id]);
  
  const handleInviteByHandle = async (targetUser) => {
    setInviting(targetUser.user_id);
    try {
      const _response = await apiClient.post(
        `/bookings/${booking.id}/invite-by-handle`,
        {
          // Use username if available, otherwise fall back to full_name
          handle_query: targetUser.username || targetUser.full_name,
          message: inviteMessage || null
        }
      );
      
      const displayName = targetUser.username ? `@${targetUser.username}` : targetUser.full_name;
      toast.success(`Invite sent to ${displayName}!`);
      setSentInvites(prev => [...prev, targetUser.user_id]);
      setSearchQuery('');
      setSearchResults([]);
      onRefresh?.();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to send invite');
    } finally {
      setInviting(null);
    }
  };
  
  return (
    <div className="py-4 space-y-4">
      {/* Tab Switcher */}
      <div className="flex border-b border-zinc-700">
        <button
          onClick={() => setActiveTab('handle')}
          className={`flex-1 py-2 text-sm font-medium flex items-center justify-center gap-2 transition-colors ${
            activeTab === 'handle' 
              ? `${textPrimaryClass} border-b-2 border-cyan-400` 
              : textSecondaryClass
          }`}
        >
          <AtSign className="w-4 h-4" />
          Invite by Name
        </button>
        <button
          onClick={() => setActiveTab('code')}
          className={`flex-1 py-2 text-sm font-medium flex items-center justify-center gap-2 transition-colors ${
            activeTab === 'code' 
              ? `${textPrimaryClass} border-b-2 border-cyan-400` 
              : textSecondaryClass
          }`}
        >
          <Copy className="w-4 h-4" />
          Share Code
        </button>
      </div>
      
      {/* Handle-based Invite Tab */}
      {activeTab === 'handle' && (
        <div className="space-y-4">
          <p className={`text-sm ${textSecondaryClass}`}>
            Search for friends by name to send them an invite notification.
          </p>
          
          {/* Search Input */}
          <div className="relative">
            <Search className={`absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 ${textSecondaryClass}`} />
            <Input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Type a name to search..."
              className={`pl-10 ${isLight ? 'bg-gray-100' : 'bg-muted'} ${textPrimaryClass}`}
              autoFocus
            />
            {searching && (
              <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin text-cyan-400" />
            )}
          </div>
          
          {/* Optional Message */}
          <div>
            <Label className={`text-sm ${textSecondaryClass}`}>Message (optional)</Label>
            <Input
              value={inviteMessage}
              onChange={(e) => setInviteMessage(e.target.value)}
              placeholder="e.g., Join me for the session!"
              className={`mt-1 ${isLight ? 'bg-gray-100' : 'bg-muted'} ${textPrimaryClass}`}
            />
          </div>
          
          {/* Search Results */}
          {searchResults.length > 0 && (
            <div className={`rounded-lg border ${isLight ? 'border-gray-200' : 'border-zinc-700'} overflow-hidden`}>
              {searchResults.map((result) => {
                const alreadySent = sentInvites.includes(result.user_id);
                
                return (
                  <div
                    key={result.user_id}
                    className={`flex items-center justify-between p-3 ${isLight ? 'hover:bg-gray-50' : 'hover:bg-muted'} border-b last:border-b-0 ${isLight ? 'border-gray-100' : 'border-zinc-700'}`}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full overflow-hidden bg-zinc-700">
                        {result.avatar_url ? (
                          <img src={getFullUrl(result.avatar_url)} alt="" className="w-full h-full object-cover" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-muted-foreground">
                            {result.full_name?.[0] || '?'}
                          </div>
                        )}
                      </div>
                      <div>
                        <p className={`font-medium ${textPrimaryClass}`}>{result.full_name}</p>
                        <p className={`text-xs ${textSecondaryClass}`}>
                          @{result.handle}
                          {result.is_following && (
                            <span className="ml-2 text-cyan-400">Following</span>
                          )}
                        </p>
                      </div>
                    </div>
                    
                    <Button
                      size="sm"
                      onClick={() => handleInviteByHandle(result)}
                      disabled={inviting === result.user_id || alreadySent}
                      className={alreadySent 
                        ? 'bg-green-500/20 text-green-400 cursor-default'
                        : 'bg-cyan-500 hover:bg-cyan-600 text-black'
                      }
                    >
                      {inviting === result.user_id ? (
                        <Loader2 className="w-4 h-4 animate-spin" />
                      ) : alreadySent ? (
                        <>
                          <Send className="w-3 h-3 mr-1" />
                          Sent
                        </>
                      ) : (
                        <>
                          <Send className="w-3 h-3 mr-1" />
                          Invite
                        </>
                      )}
                    </Button>
                  </div>
                );
              })}
            </div>
          )}
          
          {/* Empty state */}
          {searchQuery.length >= 2 && !searching && searchResults.length === 0 && (
            <div className={`text-center py-6 ${textSecondaryClass}`}>
              <Users className="w-8 h-8 mx-auto mb-2 opacity-50" />
              <p>No users found matching "{searchQuery}"</p>
            </div>
          )}
          
          {/* Sent invites summary */}
          {sentInvites.length > 0 && (
            <div className={`p-3 rounded-lg ${isLight ? 'bg-green-50' : 'bg-green-500/10'} border ${isLight ? 'border-green-200' : 'border-green-500/30'}`}>
              <p className={`text-sm ${isLight ? 'text-green-700' : 'text-green-400'}`}>
                ✓ {sentInvites.length} invite{sentInvites.length > 1 ? 's' : ''} sent! They'll receive a notification.
              </p>
            </div>
          )}
        </div>
      )}
      
      {/* Code Sharing Tab */}
      {activeTab === 'code' && (
        <div className="space-y-4">
          <p className={textSecondaryClass}>
            Share this code with friends to split the session cost.
          </p>
          {booking && booking.invite_code ? (
            <>
              <div className={`p-4 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-muted'} text-center`}>
                <p className={`text-sm ${textSecondaryClass} mb-2`}>Invite Code</p>
                <div className="flex items-center justify-center gap-2">
                  <span className={`font-mono text-2xl font-bold tracking-widest ${textPrimaryClass}`}>
                    {booking.invite_code}
                  </span>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => onCopyCode(booking.invite_code)}
                    className="text-cyan-400"
                  >
                    <Copy className="w-4 h-4" />
                  </Button>
                </div>
              </div>
              <div className={`p-3 rounded-lg ${isLight ? 'bg-yellow-50' : 'bg-yellow-500/10'}`}>
                <p className={`text-sm ${textSecondaryClass}`}>
                  When friends join, the total session cost will be split equally among all participants.
                </p>
              </div>
            </>
          ) : (
            <div className={`p-4 rounded-lg ${isLight ? 'bg-orange-50' : 'bg-orange-500/10'} text-center`}>
              <p className={`text-sm ${isLight ? 'text-orange-700' : 'text-orange-400'}`}>
                No invite code available. This session was booked without split payment enabled.
              </p>
            </div>
          )}
        </div>
      )}
      
      <DialogFooter>
        <Button variant="outline" onClick={onClose}>
          Close
        </Button>
      </DialogFooter>
    </div>
  );
};


export const Bookings = () => {
  const { user, updateUser } = useAuth();
  const { theme } = useTheme();
  const { getEffectiveRole } = usePersona();
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const tabFromUrl = searchParams.get('tab');
  const [activeTab, setActiveTab] = useState(tabFromUrl || 'lineup');  // Default to The Lineup tab, or use URL param
  const tabScrollRef = useRef(null);
  const stickyTabRef = useRef(null);
  const [showLeftArrow, setShowLeftArrow] = useState(false);
  const [showRightArrow, setShowRightArrow] = useState(false);
  const isDraggingRef = useRef(false);
  const dragStartXRef = useRef(0);
  const scrollStartRef = useRef(0);

  // Swipe-to-navigate state for mobile tab switching
  const swipeStartXRef = useRef(0);
  const swipeStartYRef = useRef(0);
  const swipeActiveRef = useRef(false);
  const swipeDragRef = useRef(0);
  const swipeLockedRef = useRef(false); // true once we commit to horizontal swipe
  const contentRef = useRef(null);
  const [slideDirection, setSlideDirection] = useState(null); // 'left' | 'right' | null
  const [isAnimating, setIsAnimating] = useState(false);

  // Check if scroll arrows should show (desktop only)
  const updateArrows = () => {
    const el = tabScrollRef.current;
    if (!el) return;
    setShowLeftArrow(el.scrollLeft > 4);
    setShowRightArrow(el.scrollLeft + el.clientWidth < el.scrollWidth - 4);
  };

  // Scroll arrows handler
  const scrollTabs = (dir) => {
    const el = tabScrollRef.current;
    if (!el) return;
    el.scrollBy({ left: dir * 160, behavior: 'smooth' });
  };

  // loading must be declared before the useEffect that depends on it
  const [loading, setLoading] = useState(true);


  // Sliding indicator bar position (left + width track the active tab button)
  const [indicatorStyle, setIndicatorStyle] = useState({ left: 0, width: 0 });

  // Auto-scroll the active tab pill into view whenever activeTab changes
  // or when loading finishes (so the tab strip DOM is actually available).
  // Uses direct scrollTo math instead of scrollIntoView because scrollIntoView
  // is unreliable on mobile for horizontal centering in nested scroll containers.
  useEffect(() => {
    if (loading) return; // Tab strip not rendered yet
    const tabStrip = tabScrollRef.current;
    if (!tabStrip) return;

    // Wait one frame for DOM layout to complete before measuring
    requestAnimationFrame(() => {
      const activeBtn = tabStrip.querySelector(`[data-testid="tab-${activeTab}"]`);
      if (activeBtn) {
        const stripWidth = tabStrip.offsetWidth;
        const btnLeft = activeBtn.offsetLeft;
        const btnWidth = activeBtn.offsetWidth;
        const targetScroll = btnLeft - (stripWidth / 2) + (btnWidth / 2);
        // Always instant scroll — the sliding indicator CSS transition provides
        // the smooth visual feedback. Smooth scroll + indicator transition together
        // create competing animations that look like "spinning".
        tabStrip.scrollTo({ left: targetScroll, behavior: 'instant' });
        // Update the sliding indicator position
        setIndicatorStyle({ left: btnLeft, width: btnWidth });
      }
      updateArrows();
    });
    setTimeout(updateArrows, 350);
  }, [activeTab, loading]);

  // Keep arrows synced on resize
  useEffect(() => {
    window.addEventListener('resize', updateArrows);
    requestAnimationFrame(updateArrows);
    return () => window.removeEventListener('resize', updateArrows);
  }, []);

  // Scroll <main> to top on mount so page always loads at the top
  useEffect(() => {
    const main = document.querySelector('main');
    if (main) main.scrollTop = 0;
  }, []);

  const [bookings, setBookings] = useState([]);
  const [liveSessions, setLiveSessions] = useState([]);
  const [sessionHistory, setSessionHistory] = useState([]);  // Past live session participations

  const [livePhotographers, setLivePhotographers] = useState([]);
  const [pendingInvites, setPendingInvites] = useState([]);
  const [crewInvites, setCrewInvites] = useState([]);  // On-demand crew invites
  const [nearbyBookings, setNearbyBookings] = useState([]);
  const [selectedSkillFilter, setSelectedSkillFilter] = useState(null);

  const [showJoinCodeModal, setShowJoinCodeModal] = useState(false);
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [joinCode, setJoinCode] = useState('');
  const [userCreditBalance, setUserCreditBalance] = useState(0);  // Local state for credits
  
  // Photographer Directory state (for Scheduled bookings)
  const [showPhotographerDirectory, setShowPhotographerDirectory] = useState(false);
  const [selectedScheduledPhotographer, setSelectedScheduledPhotographer] = useState(null);
  const [showScheduledBookingDrawer, setShowScheduledBookingDrawer] = useState(false);
  
  // Unified Drawer state for Jump In flow
  const [showJumpInDrawer, setShowJumpInDrawer] = useState(false);
  const [selectedPhotographer, setSelectedPhotographer] = useState(null);
  
  // The Crew view drawer state
  const [showCrewViewDrawer, setShowCrewViewDrawer] = useState(false);
  const [selectedCrewBooking, setSelectedCrewBooking] = useState(null);
  
  // On-Demand Request state
  const [onDemandPhotographers, setOnDemandPhotographers] = useState([]);
  const [onDemandLoading, setOnDemandLoading] = useState(false);
  const [userLocation, setUserLocation] = useState(null);
  const [gpsUnavailable, setGpsUnavailable] = useState(false);
  const [showOnDemandDrawer, setShowOnDemandDrawer] = useState(false);
  const [selectedOnDemandPro, setSelectedOnDemandPro] = useState(null);
  const [resumeDispatchId, setResumeDispatchId] = useState(null);
  
  // Crew Payment Modal state
  const [showCrewPaymentModal, setShowCrewPaymentModal] = useState(false);
  const [selectedCrewInvite, setSelectedCrewInvite] = useState(null);
  
  // Active On-Demand Request state (for returning to "Finding Your Photographer")
  const [activeDispatch, setActiveDispatch] = useState(null);
  
  // Get effective role (respects God Mode persona)
  const effectiveRole = getEffectiveRole(user?.role);
  const canJoinSessions = SURFER_ROLES.includes(effectiveRole);

  // Theme-specific classes
  const isLight = theme === 'light';
  const isBeach = theme === 'beach';
  const mainBgClass = isLight ? 'bg-gray-50' : isBeach ? 'bg-background' : 'bg-card';
  const _cardBgClass = isLight ? 'bg-white border-gray-200' : isBeach ? 'bg-zinc-950 border-border' : 'bg-muted/50 border-zinc-700';
  const textPrimaryClass = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondaryClass = isLight ? 'text-gray-600' : isBeach ? 'text-gray-300' : 'text-muted-foreground';
  const borderClass = isLight ? 'border-gray-200' : isBeach ? 'border-border' : 'border-zinc-700';
  const inputBgClass = isLight ? 'bg-white' : 'bg-card';

  // Get subscription tier info
  const subscriptionTier = user?.subscription_tier || 'Free';
  const trackingRadius = subscriptionTier === 'Premium' ? 'Unlimited' : subscriptionTier === 'Basic' ? '5 Miles' : '1 Mile';

  // Update active tab when URL changes
  useEffect(() => {
    if (tabFromUrl && tabFromUrl !== activeTab) {
      setActiveTab(tabFromUrl);
    }
  }, [tabFromUrl]);

  // Fetch all data on mount (when user is available).
  // fetchData() loads everything in parallel regardless of active tab,
  // so there's no reason to re-fetch when switching tabs.
  useEffect(() => {
    if (user?.id) {
      fetchData();
    }
  }, [user?.id]);

  // Fetch on-demand photographers when On-Demand tab is selected
  useEffect(() => {
    if (activeTab === 'on_demand' && user?.id) {
      fetchOnDemandPhotographers();
    }
  }, [activeTab, user?.id]);

  // Sync selectedCrewBooking with latest bookings data when bookings update
  useEffect(() => {
    if (bookings.length > 0) {
      setSelectedCrewBooking(prev => {
        if (!prev) return null;
        const updatedBooking = bookings.find(b => b.id === prev.id);
        return updatedBooking || prev;
      });
    }
  }, [bookings]);

  // Poll for active dispatch and crew invites updates (only when On-Demand tab is active)
  useEffect(() => {
    if (!user?.id || activeTab !== 'on_demand') return;
    
    const pollInterval = setInterval(async () => {
      // Skip polling when browser tab is hidden (saves battery & bandwidth)
      if (document.visibilityState === 'hidden') return;
      
      // Refresh active dispatch
      try {
        const activeRes = await apiClient.get(`/dispatch/user/${user.id}/active`);
        // Show dispatch for requester, crew_member, or photographer roles
        if (activeRes.data.active_dispatch && 
            ['requester', 'crew_member', 'photographer'].includes(activeRes.data.active_dispatch.role)) {
          setActiveDispatch(activeRes.data.active_dispatch);
        } else {
          setActiveDispatch(null);
        }
      } catch (e) {
        // Silent fail
      }
      
      // Refresh crew invites
      try {
        const crewRes = await apiClient.get(`/dispatch/user/${user.id}/crew-invites`);
        setCrewInvites(crewRes.data.crew_invites || []);
      } catch (e) {
        // Silent fail
      }
    }, 5000); // Poll every 5 seconds
    
    return () => clearInterval(pollInterval);
  }, [user?.id, activeTab]);

  // Ref to prevent duplicate Stripe payment completion calls (race condition fix)
  const paymentProcessedRef = useRef(false);
  
  // Handle return from Stripe session payment
  useEffect(() => {
    const sessionPayment = searchParams.get('session_payment');
    const checkoutSessionId = searchParams.get('checkout_session_id');
    
    // Wait for user to be loaded
    if (!user?.id) return;
    
    if (sessionPayment === 'success' && checkoutSessionId) {
      // Guard: Only process once per mount/redirect
      if (paymentProcessedRef.current) {
        return;
      }
      paymentProcessedRef.current = true;
      
      // Complete the session join after successful payment
      const completeSessionJoin = async () => {
        try {
          const response = await apiClient.post(`/sessions/complete-payment`, {
            checkout_session_id: checkoutSessionId
          });
          
          
          if (response.data.success) {
            toast.success(`You're in the session with ${response.data.photographer_name || 'the photographer'}! 🏄`, { duration: 5000 });
            // Switch to live_sessions tab to show the active session
            setActiveTab('live_sessions');
            // Refresh live sessions
            const sessionsRes = await apiClient.get(`/sessions/user/${user.id}`);
            setLiveSessions(sessionsRes.data || []);
          }
        } catch (error) {
          logger.error('Complete session payment error:', error);
          toast.error(error.response?.data?.detail || 'Payment received - session will be activated shortly');
        }
        
        // Clear the URL params
        navigate('/bookings?tab=live_sessions', { replace: true });
      };
      
      completeSessionJoin();
    } else if (sessionPayment === 'cancelled') {
      toast.info('Payment cancelled');
      navigate('/bookings', { replace: true });
    }
  }, [searchParams, user?.id, navigate]);

  const fetchData = async () => {
    setLoading(true);
    try {
      // Fire all independent API calls in parallel for ~2-3x faster load
      const [creditsRes, bookingsRes, sessionsRes, liveRes, invitesRes, crewRes, activeRes, historyRes] = await Promise.allSettled([
        apiClient.get(`/credits/${user.id}/balance`),
        apiClient.get(`/bookings/user/${user.id}`),
        apiClient.get(`/sessions/user/${user.id}`),
        apiClient.get(`/photographers/live`),
        apiClient.get(`/bookings/invites/${user.id}`),
        apiClient.get(`/dispatch/user/${user.id}/crew-invites`),
        apiClient.get(`/dispatch/user/${user.id}/active`),
        apiClient.get(`/sessions/user/${user.id}/history`),
      ]);

      // Credits
      if (creditsRes.status === 'fulfilled' && creditsRes.value.data?.balance !== undefined) {
        setUserCreditBalance(creditsRes.value.data.balance);
        updateUser({ credit_balance: creditsRes.value.data.balance });
      }

      // Bookings
      setBookings(bookingsRes.status === 'fulfilled' ? (bookingsRes.value.data || []) : []);

      // Live sessions
      setLiveSessions(sessionsRes.status === 'fulfilled' ? (sessionsRes.value.data || []) : []);

      // Live photographers
      setLivePhotographers(liveRes.status === 'fulfilled' ? (liveRes.value.data || []) : []);

      // Pending invites
      setPendingInvites(invitesRes.status === 'fulfilled' ? (invitesRes.value.data || []) : []);

      // Crew invites
      setCrewInvites(crewRes.status === 'fulfilled' ? (crewRes.value.data?.crew_invites || []) : []);

      // Active dispatch
      if (activeRes.status === 'fulfilled') {
        const dispatch = activeRes.value.data?.active_dispatch;
        if (dispatch && ['requester', 'crew_member', 'photographer'].includes(dispatch.role)) {
          setActiveDispatch(dispatch);
        } else {
          setActiveDispatch(null);
        }
      } else {
        setActiveDispatch(null);
      }

      // Past live session history (completed/left live sessions)
      setSessionHistory(historyRes.status === 'fulfilled' ? (historyRes.value.data || []) : []);
      
      // Fetch nearby splittable bookings (if user has location) — kept async since geolocation is callback-based
      try {
        if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(async (position) => {
            const { latitude, longitude } = position.coords;
            const params = new URLSearchParams({
              latitude,
              longitude,
              radius: 10
            });
            if (selectedSkillFilter) {
              params.append('skill_level', selectedSkillFilter);
            }
            const nearbyRes = await apiClient.get(`/bookings/nearby?${params}`);
            setNearbyBookings(nearbyRes.data || []);
          }, () => {
            // Location denied - skip nearby bookings
            setNearbyBookings([]);
          });
        }
      } catch (e) {
        setNearbyBookings([]);
      }
    } catch (error) {
      logger.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleJumpIn = async (photographer) => {
    // Check if user is logged in
    if (!user) {
      toast.error('Please log in to join sessions');
      return;
    }
    
    // Check if user has a surfer-capable role
    if (!canJoinSessions) {
      toast.error(`Your current role (${effectiveRole}) cannot join sessions. Switch to a surfer role.`);
      return;
    }
    
    // Open the Unified Drawer with photographer info
    setSelectedPhotographer({
      ...photographer,
      current_spot_name: photographer.location || photographer.spot_name || 'Live Session'
    });
    setShowJumpInDrawer(true);
  };
  
  // Handle successful join from drawer
  const _handleJumpInSuccess = (data) => {
    setShowJumpInDrawer(false);
    setSelectedPhotographer(null);
    if (data?.remaining_credits !== undefined) {
      updateUser({ credit_balance: data.remaining_credits });
    }
    toast.success('Successfully joined session!');
    fetchData();
  };

  const handleJoinByCode = async () => {
    if (!joinCode.trim()) {
      toast.error('Please enter an invite code');
      return;
    }
    try {
      const _response = await apiClient.post(`/bookings/join-by-code?invite_code=${joinCode.toUpperCase()}`);
      toast.success('Successfully joined the booking!');
      setShowJoinCodeModal(false);
      setJoinCode('');
      fetchData();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Invalid invite code');
    }
  };

  const handleRespondToInvite = async (inviteId, accept) => {
    try {
      await apiClient.post(`/bookings/invites/${inviteId}/respond?accept=${accept}`);
      toast.success(accept ? 'Invite accepted!' : 'Invite declined');
      fetchData();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to respond to invite');
    }
  };

  const handleJoinNearbyBooking = async (bookingId) => {
    try {
      const response = await apiClient.post(`/bookings/${bookingId}/join`);
      toast.success(`Joined booking! Paid ${response.data.amount_paid} credits`);
      fetchData();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to join booking');
    }
  };
  
  // Auto-open crew payment modal when coming from notification (fixes race condition)
  useEffect(() => {
    if (!location.state?.openCrewInvite || !location.state?.dispatchId) return;
    const dispatchId = location.state.dispatchId;

    const tryOpen = (invites) => {
      const invite = invites.find(inv => inv.dispatch_id === dispatchId);
      if (invite) {
        setActiveTab('on_demand'); // Ensure correct tab is visible
        setSelectedCrewInvite(invite);
        setShowCrewPaymentModal(true);
        navigate(location.pathname + location.search, { replace: true, state: {} });
      }
    };

    if (crewInvites.length > 0) {
      // Already loaded — open immediately
      tryOpen(crewInvites);
    } else {
      // Race condition: invites not loaded yet — fetch directly and open
      apiClient.get(`/dispatch/user/${user?.id}/crew-invites`)
        .then(res => {
          const fresh = res.data?.crew_invites || [];
          setCrewInvites(fresh);
          tryOpen(fresh);
        })
        .catch(() => {/* silent */});
    }
  }, [location.state?.openCrewInvite, location.state?.dispatchId]); // eslint-disable-line

  const fetchNearbyWithSkillFilter = async (skillLevel) => {
    setSelectedSkillFilter(skillLevel);
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(async (position) => {
        const { latitude, longitude } = position.coords;
        const params = new URLSearchParams({
          latitude: latitude.toString(),
          longitude: longitude.toString(),
          radius: '10',
          user_id: user.id
        });
        if (skillLevel) {
          params.append('skill_level', skillLevel);
        }
        try {
          const nearbyRes = await apiClient.get(`/bookings/nearby?${params}`);
          setNearbyBookings(nearbyRes.data || []);
        } catch (e) {
          logger.error('Error fetching nearby bookings:', e);
        }
      });
    }
  };

  const copyInviteCode = (code) => {
    navigator.clipboard.writeText(code);
    toast.success('Invite code copied!');
  };

  // Handle crew share payment - opens the payment modal
  const handlePayCrewShare = (invite) => {
    setSelectedCrewInvite(invite);
    setShowCrewPaymentModal(true);
  };

  // Helper: sort photographers by priority
  const sortPhotographers = (photographers) => {
    return (photographers || []).sort((a, b) => {
      const priorityOrder = { 'Approved Pro': 0, 'Pro': 1, 'Photographer': 2, 'Hobbyist': 3 };
      return (priorityOrder[a.role] ?? 99) - (priorityOrder[b.role] ?? 99);
    });
  };

  // Fetch on-demand photographers based on user location (GPS)
  const fetchOnDemandPhotographers = async () => {
    setOnDemandLoading(true);
    try {
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
          async (position) => {
            const { latitude, longitude } = position.coords;
            setUserLocation({ latitude, longitude });
            setGpsUnavailable(false);
            
            try {
              const response = await apiClient.get(`/photographers/on-demand`, {
                params: { latitude, longitude, radius: 25 }
              });
              setOnDemandPhotographers(sortPhotographers(response.data));
            } catch (e) {
              logger.error('Error fetching on-demand photographers:', e);
              setOnDemandPhotographers([]);
            }
            setOnDemandLoading(false);
          },
          (_error) => {
            // GPS denied/unavailable — show manual location selector
            setGpsUnavailable(true);
            setOnDemandLoading(false);
          }
        );
      } else {
        setGpsUnavailable(true);
        setOnDemandLoading(false);
      }
    } catch (e) {
      logger.error('Error in fetchOnDemandPhotographers:', e);
      setOnDemandLoading(false);
    }
  };

  // Fetch on-demand photographers by manual location (fallback when GPS unavailable)
  const fetchOnDemandByManualLocation = async (latitude, longitude, locationLabel) => {
    setOnDemandLoading(true);
    setUserLocation({ latitude, longitude, label: locationLabel });
    try {
      const response = await apiClient.get(`/photographers/on-demand`, {
        params: { latitude, longitude, radius: 50 }
      });
      setOnDemandPhotographers(sortPhotographers(response.data));
    } catch (e) {
      logger.error('Error fetching on-demand photographers by manual location:', e);
      setOnDemandPhotographers([]);
    } finally {
      setOnDemandLoading(false);
    }
  };

  // Handle On-Demand pro selection
  const handleSelectOnDemandPro = (pro) => {
    setSelectedOnDemandPro(pro);
    setShowOnDemandDrawer(true);
  };

  // Handle On-Demand request success
  const handleOnDemandSuccess = (data) => {
    setShowOnDemandDrawer(false);
    setSelectedOnDemandPro(null);
    if (data?.remaining_credits !== undefined) {
      updateUser({ credit_balance: data.remaining_credits });
    }
    toast.success('On-Demand request sent!');
    fetchData();
  };

  const openInviteModal = async (booking) => {
    // If needs to enable splitting first
    if (booking.needsEnableSplitting) {
      try {
        const response = await apiClient.post(`/bookings/${booking.id}/enable-splitting`);
        if (response.data.success) {
          toast.success('Crew splitting enabled!');
          // Refresh booking with new invite code
          await fetchData();
          setSelectedBooking({ ...booking, invite_code: response.data.invite_code });
          setShowInviteModal(true);
        }
      } catch (error) {
        toast.error(error.response?.data?.detail || 'Failed to enable splitting');
      }
      return;
    }
    
    setSelectedBooking(booking);
    setShowInviteModal(true);
  };

  // ─── Date-based booking lifecycle helper ────────────────────────────────────
  // A booking is "past" if its session_date + duration has elapsed.
  // This catches sessions the photographer never explicitly ended.
  const isBookingPast = (b) => {
    if (!b.session_date) return false;
    const sessionEnd = new Date(b.session_date);
    sessionEnd.setMinutes(sessionEnd.getMinutes() + (b.duration || 60));
    return sessionEnd < new Date();
  };

  const LOBBY_PHASE = ['open', 'filling', 'ready'];

  // ─── Derived lists ─────────────────────────────────────────────────────────
  // Scheduled = future confirmed/pending bookings only
  const scheduledBookings = bookings.filter(b => {
    if (isBookingPast(b)) return false; // past-dated → Past tab
    if (b.status === 'Confirmed') return true;
    if (b.status === 'Pending' && LOBBY_PHASE.includes(b.lineup_status)) return false;
    return b.status === 'Pending';
  });

  // Past = explicitly completed OR past-dated sessions (expired/missed)
  // Also merge in past live session participations
  const pastBookings = [
    ...bookings.filter(b => {
      if (b.status === 'Completed') return true;
      // Past-dated sessions that were never completed
      if (isBookingPast(b) && ['Confirmed', 'Pending'].includes(b.status)) return true;
      return false;
    }),
    ...sessionHistory, // Past live session participations (already normalized by backend)
  ].sort((a, b) => new Date(b.session_date || b.created_at) - new Date(a.session_date || a.created_at));

  const tabs = [
    { id: 'lineup', label: 'The Lineup', icon: Users, count: 0, highlight: true },
    { id: 'directory', label: 'Find Photogs', icon: Search, count: 0 },
    { id: 'live_sessions', label: 'Live Sessions', icon: Zap, count: liveSessions.length },
    { id: 'on_demand', label: 'On-Demand', icon: Target, count: onDemandPhotographers.length },
    { id: 'find_buddies', label: 'Open Sessions', icon: Users, count: nearbyBookings.length },
    { id: 'scheduled', label: 'Scheduled', icon: CalendarClock, count: scheduledBookings.length },
    { id: 'past', label: 'Past', icon: History, count: pastBookings.length },
    { id: 'live_now', label: 'Live Now', icon: Radio, count: livePhotographers.length },
    { id: 'subscriptions', label: 'Subscriptions', icon: RefreshCw, count: 0 },
  ];

  if (loading) {
    return (
      <div className={`flex items-center justify-center min-h-screen ${mainBgClass}`}>
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-yellow-400"></div>
      </div>
    );
  }

  return (
    <div className={`pb-20 min-h-screen ${mainBgClass} transition-colors duration-300`} data-testid="bookings-page">
      <div className="max-w-lg mx-auto p-4">
        <div className="flex items-center justify-between mb-6">
          <h1 className={`text-3xl font-bold ${textPrimaryClass}`} style={{ fontFamily: 'Oswald' }} data-testid="bookings-title">
            Sessions & Bookings
          </h1>
          <div className="flex items-center gap-2">
            <Button
              onClick={() => setActiveTab('directory')}
              size="sm"
              className="bg-gradient-to-r from-yellow-500 to-amber-500 hover:from-yellow-600 hover:to-amber-600 text-black font-semibold"
            >
              <Search className="w-4 h-4 mr-1.5" />
              Find Photogs
            </Button>
            <Button
              onClick={() => setShowJoinCodeModal(true)}
              variant="outline"
              size="sm"
              className={isLight ? 'border-gray-300' : 'border-zinc-700'}
            >
              <UserPlus className="w-4 h-4 mr-1.5" />
              Join Code
            </Button>
          </div>
        </div>

        {/* Pending Invites Banner */}
        {pendingInvites.length > 0 && (
          <Card className="mb-4 bg-gradient-to-r from-yellow-500/20 to-orange-500/20 border-yellow-500/30">
            <CardContent className="py-3 px-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Mail className="w-5 h-5 text-yellow-400" />
                  <span className={`text-sm font-medium ${textPrimaryClass}`}>
                    You have {pendingInvites.length} pending invite{pendingInvites.length > 1 ? 's' : ''}
                  </span>
                </div>
                <Button
                  size="sm"
                  variant="ghost"
                  className="text-yellow-400"
                  onClick={() => setActiveTab('scheduled')}
                >
                  View
                </Button>
              </div>
            </CardContent>
          </Card>
        )}


        {/* Tabs — scrolls with content */}
        <div
          ref={stickyTabRef}
          className="relative z-10"
          style={{
            backgroundColor: isLight ? '#f9fafb' : isBeach ? '#09090b' : '#18181b',
            backgroundImage: 'none',
          }}
        >
          <div className="relative">
            {/* Scrollable tab strip with orange underline indicator */}
            <div
              ref={tabScrollRef}
              onScroll={updateArrows}
              onMouseDown={(e) => {
                isDraggingRef.current = true;
                dragStartXRef.current = e.pageX;
                scrollStartRef.current = tabScrollRef.current?.scrollLeft || 0;
                e.currentTarget.style.cursor = 'grabbing';
                e.currentTarget.style.userSelect = 'none';
              }}
              onMouseMove={(e) => {
                if (!isDraggingRef.current) return;
                const delta = dragStartXRef.current - e.pageX;
                if (tabScrollRef.current) tabScrollRef.current.scrollLeft = scrollStartRef.current + delta;
              }}
              onMouseUp={(e) => {
                isDraggingRef.current = false;
                e.currentTarget.style.cursor = '';
                e.currentTarget.style.userSelect = '';
              }}
              onMouseLeave={(e) => {
                if (isDraggingRef.current) {
                  isDraggingRef.current = false;
                  e.currentTarget.style.cursor = '';
                  e.currentTarget.style.userSelect = '';
                }
              }}
              className={`flex border-b ${borderClass} overflow-x-auto scrollbar-hide cursor-grab select-none relative`}
              style={{ scrollbarWidth: 'none', msOverflowStyle: 'none', WebkitOverflowScrolling: 'touch' }}
            >
              {tabs.map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button
                    key={tab.id}
                    data-active={isActive ? 'true' : 'false'}
                    onClick={() => {
                      if (Math.abs((tabScrollRef.current?.scrollLeft || 0) - scrollStartRef.current) < 4) {
                        setActiveTab(tab.id);
                      }
                    }}
                    className={`flex items-center gap-2 px-4 py-3 text-sm font-medium whitespace-nowrap transition-colors flex-shrink-0 ${
                      isActive ? textPrimaryClass : textSecondaryClass
                    }`}
                    style={{
                      borderBottom: '3px solid transparent',
                      marginBottom: '-1px',
                    }}
                    data-testid={`tab-${tab.id}`}
                  >
                    <Icon className="w-4 h-4" />
                    {tab.label}
                    {tab.count > 0 && (
                      <span className={`ml-1 px-1.5 py-0.5 text-xs rounded-full ${
                        isActive ? 'bg-amber-500/20 text-amber-500' : isLight ? 'bg-gray-200 text-gray-600' : 'bg-zinc-700 text-gray-300'
                      }`}>
                        {tab.count}
                      </span>
                    )}
                  </button>
                );
              })}
              {/* Sliding orange indicator bar */}
              <div
                style={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  height: 3,
                  backgroundColor: '#f59e0b',
                  borderRadius: '2px 2px 0 0',
                  transform: `translateX(${indicatorStyle.left}px)`,
                  width: indicatorStyle.width,
                  transition: 'transform 0.25s ease, width 0.25s ease',
                  pointerEvents: 'none',
                }}
              />
            </div>

            {/* Left fade + arrow */}
            {showLeftArrow && (
              <button
                onClick={() => scrollTabs(-1)}
                className={`absolute left-0 top-0 bottom-0 z-10 flex items-center justify-center w-8 ${
                  isLight ? 'bg-gradient-to-r from-gray-50 to-transparent' : isBeach ? 'bg-gradient-to-r from-background to-transparent' : 'bg-gradient-to-r from-card to-transparent'
                }`}
                aria-label="Scroll tabs left"
              >
                <ChevronLeft className={`w-4 h-4 ${textSecondaryClass}`} />
              </button>
            )}

            {/* Right fade + arrow */}
            {showRightArrow && (
              <button
                onClick={() => scrollTabs(1)}
                className={`absolute right-0 top-0 bottom-0 z-10 flex items-center justify-center w-8 ${
                  isLight ? 'bg-gradient-to-l from-gray-50 to-transparent' : isBeach ? 'bg-gradient-to-l from-background to-transparent' : 'bg-gradient-to-l from-card to-transparent'
                }`}
                aria-label="Scroll tabs right"
              >
                <ChevronRight className={`w-4 h-4 ${textSecondaryClass}`} />
              </button>
            )}
          </div>
        </div>

        {/* Tab Content -- swipeable on mobile with simple fast transition */}
        <div
          className="relative overflow-hidden"
          onTouchStart={(e) => {
            if (isAnimating) return;
            swipeStartXRef.current = e.touches[0].clientX;
            swipeStartYRef.current = e.touches[0].clientY;
            swipeActiveRef.current = true;
            swipeLockedRef.current = false;
            swipeDragRef.current = 0;
          }}
          onTouchMove={(e) => {
            if (!swipeActiveRef.current || isAnimating) return;
            const dx = e.touches[0].clientX - swipeStartXRef.current;
            const dy = e.touches[0].clientY - swipeStartYRef.current;

            // Determine direction lock on first significant movement
            if (!swipeLockedRef.current) {
              if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 10) {
                // Vertical scroll -- cancel swipe entirely
                swipeActiveRef.current = false;
                return;
              }
              if (Math.abs(dx) > 10) {
                swipeLockedRef.current = true;
              } else {
                return; // Not enough movement yet
              }
            }

            // Prevent vertical scrolling while swiping horizontally
            e.preventDefault();

            const tabIds = tabs.map(t => t.id);
            const currentIdx = tabIds.indexOf(activeTab);
            // Add resistance at edges
            const atEdge = (dx > 0 && currentIdx === 0) || (dx < 0 && currentIdx === tabIds.length - 1);
            const dampened = atEdge ? dx * 0.2 : dx;
            swipeDragRef.current = dampened;
          }}
          onTouchEnd={() => {
            if (!swipeActiveRef.current || isAnimating) {
              swipeActiveRef.current = false;
              return;
            }
            swipeActiveRef.current = false;

            const dragX = swipeDragRef.current;
            const MIN_SWIPE = 50;
            const tabIds = tabs.map(t => t.id);
            const currentIdx = tabIds.indexOf(activeTab);

            if (Math.abs(dragX) >= MIN_SWIPE && swipeLockedRef.current) {
              const goingLeft = dragX < 0;
              const nextIdx = goingLeft ? currentIdx + 1 : currentIdx - 1;

              if (nextIdx >= 0 && nextIdx < tabIds.length) {
                // Simple instant switch — no multi-stage animation
                setActiveTab(tabIds[nextIdx]);
                return;
              }
            }
          }}
        >
          <div
            ref={contentRef}
            className="space-y-4"
          >
          {/* The Lineup Tab - Surf Session Lobby */}
          <div style={{ display: activeTab === 'lineup' ? 'block' : 'none' }}>
            <LineupTab
              user={user}
              theme={theme}
              onOpenDirectory={() => setShowPhotographerDirectory(true)}
              onRefresh={fetchData}
            />
          </div>

          {/* Live Sessions Tab */}
          <div style={{ display: activeTab === 'live_sessions' ? 'block' : 'none' }}>
            <LiveSessionsTab
              liveSessions={liveSessions}
              onGoToLiveNow={() => setActiveTab('live_now')}
              onSessionLeft={(sessionId) => {
                setLiveSessions(prev => prev.filter(s => s.id !== sessionId));
              }}
              userId={user?.id}
              theme={theme}
            />
          </div>

          {/* On-Demand Tab - Request a Photographer */}
          <div style={{ display: activeTab === 'on_demand' ? 'block' : 'none' }}>
            <OnDemandTab
              user={user}
              onDemandPhotographers={onDemandPhotographers}
              onDemandLoading={onDemandLoading}
              userLocation={userLocation}
              gpsUnavailable={gpsUnavailable}
              activeDispatch={activeDispatch}
              onRefresh={fetchOnDemandPhotographers}
              onManualLocationSelect={fetchOnDemandByManualLocation}
              onSelectPhotographer={handleSelectOnDemandPro}
              onResumeDispatch={(dispatch) => {
                // If photographer already accepted/en_route/arrived, go directly to interactive lobby
                if (['accepted', 'en_route', 'arrived'].includes(dispatch.status)) {
                  navigate(`/dispatch/${dispatch.id}/lobby`);
                  return;
                }
                // Otherwise resume the "Finding Your Photographer" workflow drawer
                setSelectedOnDemandPro({ 
                  id: dispatch.photographer_id || 'unknown', 
                  full_name: dispatch.photographer_name || 'Photographer'
                });
                setResumeDispatchId(dispatch.id);
                setShowOnDemandDrawer(true);
              }}
              crewInvites={crewInvites}
              onPayCrewShare={handlePayCrewShare}
              theme={theme}
            />
          </div>

          {/* Scheduled Tab */}
          <div style={{ display: activeTab === 'scheduled' ? 'block' : 'none' }}>
            <ScheduledTab
              user={user}
              scheduledBookings={scheduledBookings}
              pendingInvites={pendingInvites}
              crewInvites={crewInvites}
              onOpenDirectory={() => setShowPhotographerDirectory(true)}
              onInvite={openInviteModal}
              onRespondToInvite={handleRespondToInvite}
              onPayCrewShare={handlePayCrewShare}
              onRefresh={fetchData}
              onOpenCrewHub={(booking) => {
                // Open the invite modal for crew management
                openInviteModal(booking);
              }}
              onOpenModify={(booking) => {
                // Navigate to modify booking - use scheduled booking drawer with existing data
                setSelectedScheduledPhotographer({ id: booking.photographer_id, full_name: booking.photographer_name });
                setShowScheduledBookingDrawer(true);
                toast.info('Modify session: Select a new time slot');
              }}
              onOpenCrewView={(booking) => {
                // Open The Crew lineup visualization drawer
                setSelectedCrewBooking(booking);
                setShowCrewViewDrawer(true);
              }}
              theme={theme}
            />
          </div>

          {/* Find Buddies Tab */}
          <div style={{ display: activeTab === 'find_buddies' ? 'block' : 'none' }}>
            <FindBuddiesTab
              nearbyBookings={nearbyBookings}
              selectedSkillFilter={selectedSkillFilter}
              onSkillFilterChange={fetchNearbyWithSkillFilter}
              onJoinNearbyBooking={handleJoinNearbyBooking}
              theme={theme}
            />
          </div>

          {/* Past Tab */}
          <div style={{ display: activeTab === 'past' ? 'block' : 'none' }}>
            <PastTab
              pastBookings={pastBookings}
              theme={theme}
              userId={user?.id}
            />
          </div>

          {/* Live Now Tab */}
          <div style={{ display: activeTab === 'live_now' ? 'block' : 'none' }}>
            <LiveNowTab
              livePhotographers={livePhotographers}
              subscriptionTier={subscriptionTier}
              trackingRadius={trackingRadius}
              onJumpIn={handleJumpIn}
              onNavigateToMap={() => navigate('/map')}
              theme={theme}
            />
          </div>

          {/* Directory Tab */}
          <div style={{ display: activeTab === 'directory' ? 'block' : 'none' }}>
            <DirectoryTab
              user={user}
              theme={theme}
              subscriptionTier={subscriptionTier}
              onSelectPhotographer={(photographer) => {
                setSelectedScheduledPhotographer(photographer);
                setShowScheduledBookingDrawer(true);
              }}
            />
          </div>

          {/* Subscriptions Tab */}
          <div style={{ display: activeTab === 'subscriptions' ? 'block' : 'none' }}>
            <SubscriptionsTab />
          </div>
          </div>
        </div>
      </div>

      {/* Join by Code Modal */}
      <Dialog open={showJoinCodeModal} onOpenChange={setShowJoinCodeModal}>
        <DialogContent className={`${isLight ? 'bg-white' : 'bg-card'} border ${borderClass}`}>
          <DialogHeader>
            <DialogTitle className={textPrimaryClass}>Join with Invite Code</DialogTitle>
          </DialogHeader>
          <div className="py-4">
            <Label className={textSecondaryClass}>Invite Code</Label>
            <Input
              value={joinCode}
              onChange={(e) => setJoinCode(e.target.value.toUpperCase())}
              placeholder="Enter 6-character code"
              maxLength={6}
              className={`${inputBgClass} ${textPrimaryClass} uppercase tracking-widest text-center text-xl`}
            />
            <p className={`text-sm ${textSecondaryClass} mt-2`}>
              Enter the code shared by your friend to join their session.
            </p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowJoinCodeModal(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleJoinByCode}
              className="bg-gradient-to-r from-yellow-400 to-orange-400 text-black"
            >
              Join Session
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Invite Friends Modal */}
      <Dialog open={showInviteModal} onOpenChange={setShowInviteModal}>
        <DialogContent className={`${isLight ? 'bg-white' : 'bg-card'} border ${borderClass}`}>
          <DialogHeader>
            <DialogTitle className={textPrimaryClass}>Invite Friends</DialogTitle>
          </DialogHeader>
          <InviteModalContent
            booking={selectedBooking}
            user={user}
            isLight={isLight}
            textPrimaryClass={textPrimaryClass}
            textSecondaryClass={textSecondaryClass}
            onCopyCode={copyInviteCode}
            onClose={() => setShowInviteModal(false)}
            onRefresh={fetchData}
          />
        </DialogContent>
      </Dialog>
      
      {/* Jump In Session Modal - Direct render without UnifiedSpotDrawer */}
      {showJumpInDrawer && selectedPhotographer && (
        <JumpInSessionModal
          photographer={selectedPhotographer}
          onClose={() => {
            setShowJumpInDrawer(false);
            setSelectedPhotographer(null);
          }}
          onSuccess={() => {
            setShowJumpInDrawer(false);
            setSelectedPhotographer(null);
            toast.success('Successfully joined session!');
          }}
        />
      )}
      
      {/* On-Demand Request Drawer */}
      {selectedOnDemandPro && (
        <OnDemandRequestDrawer
          photographer={selectedOnDemandPro}
          isOpen={showOnDemandDrawer}
          onClose={() => {
            setShowOnDemandDrawer(false);
            setSelectedOnDemandPro(null);
            setResumeDispatchId(null);
          }}
          onSuccess={handleOnDemandSuccess}
          userLocation={userLocation}
          userCredits={userCreditBalance || user?.credit_balance || 0}
          resumeDispatchId={resumeDispatchId}
        />
      )}
      
      {/* Photographer Directory for Scheduled Bookings */}
      <PhotographerDirectory
        isOpen={showPhotographerDirectory}
        onClose={() => setShowPhotographerDirectory(false)}
        onSelectPhotographer={(photographer) => {
          // Open the scheduled booking drawer with selected photographer
          setSelectedScheduledPhotographer(photographer);
          setShowPhotographerDirectory(false);
          setShowScheduledBookingDrawer(true);
        }}
      />
      
      {/* Scheduled Booking Drawer - Full booking flow */}
      <ScheduledBookingDrawer
        isOpen={showScheduledBookingDrawer}
        onClose={() => {
          setShowScheduledBookingDrawer(false);
          setSelectedScheduledPhotographer(null);
        }}
        photographer={selectedScheduledPhotographer}
        onSuccess={(_booking) => {
          setShowScheduledBookingDrawer(false);
          setSelectedScheduledPhotographer(null);
          fetchData();
          toast.success('Session booked! Check your scheduled sessions.');
        }}
      />

      {/* The Crew View Drawer - Surfboard lineup visualization */}
      <LineupManagerDrawer
        isOpen={showCrewViewDrawer}
        onClose={() => {
          setShowCrewViewDrawer(false);
          setSelectedCrewBooking(null);
        }}
        lineup={selectedCrewBooking}
        user={user}
        onRefresh={fetchData}
        onLineupUpdate={(updatedFields) => {
          // Immediately update the selectedCrewBooking with the new fields
          setSelectedCrewBooking(prev => prev ? { ...prev, ...updatedFields } : null);
          // Also update in bookings array
          setBookings(prev => prev.map(b => 
            b.id === selectedCrewBooking?.id ? { ...b, ...updatedFields } : b
          ));
        }}
      />
      
      {/* Crew Payment Modal for On-Demand Session Invites */}
      <CrewPaymentModal
        invite={selectedCrewInvite}
        isOpen={showCrewPaymentModal}
        onClose={() => {
          setShowCrewPaymentModal(false);
          setSelectedCrewInvite(null);
        }}
        onSuccess={() => {
          fetchData();
          setShowCrewPaymentModal(false);
          setSelectedCrewInvite(null);
          // Switch to "Live Now" tab so crew member can see their active session
          setActiveTab('on_demand');
          toast.success('Check your active session below!');
        }}
      />
    </div>
  );
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Compass, Plus, Camera, MessageCircle, Waves } from 'lucide-react';
import { useTheme } from '../contexts/ThemeContext';
import { useAuth } from '../contexts/AuthContext';
import { usePersona } from '../contexts/PersonaContext';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';
import { PhotoToolsDrawer } from './PhotoToolsDrawer';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';
import { ROLES } from '../constants/roles';


/**
 * Animated Wave Home Icon - Simple Lucide Waves with gentle animation
 */
const AnimatedWaveIcon = ({ isActive, isPressed, hasNewContent, className = '' }) => {
  const [frame, setFrame] = useState(0);
  
  useEffect(() => {
    const interval = setInterval(() => {
      setFrame(prev => (prev + 1) % 40);
    }, 80);
    return () => clearInterval(interval);
  }, []);
  
  const scale = isPressed ? 0.85 : isActive ? 1.1 : 1;
  const t = frame / 40;
  
  // Gentle wave motion - subtle rotation and bob
  const rotate = Math.sin(t * Math.PI * 2) * 4;
  const translateY = Math.sin(t * Math.PI * 2) * 1.5;
  
  return (
    <div 
      className={`relative ${className}`}
      style={{
        transform: `scale(${scale}) rotate(${rotate}deg) translateY(${translateY}px)`,
        transition: 'transform 0.1s ease-out',
        filter: isActive ? 'drop-shadow(0 0 4px rgba(56, 189, 248, 0.6))' : 'none'
      }}
    >
      <Waves 
        size={24} 
        strokeWidth={2.5}
        className={isActive ? 'text-cyan-400' : 'text-gray-500'}
      />
      {hasNewContent && (
        <span className="absolute -top-1 -right-1 w-2 h-2 bg-cyan-400 rounded-full animate-pulse" />
      )}
    </div>
  );
};

/**
 * Home Wave Button - Wrapper component for proper hooks usage
 */
const HomeWaveButton = ({ textActiveClass, textInactiveClass, onNavigate }) => {
  const [isPressed, setIsPressed] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const isActive = location.pathname === '/feed' || location.pathname === '/';
  
  const handleClick = (e) => {
    e.preventDefault();
    if (onNavigate) onNavigate('/feed');
    else navigate('/feed');
  };
  
  return (
    <button
      onClick={handleClick}
      className={`flex flex-col items-center gap-0.5 min-w-[56px] py-1 ${isActive ? textActiveClass : textInactiveClass}`}
      data-testid="bottomnav-home"
    >
      <div 
        className="flex flex-col items-center gap-0.5"
        onTouchStart={() => setIsPressed(true)}
        onTouchEnd={() => setIsPressed(false)}
        onMouseDown={() => setIsPressed(true)}
        onMouseUp={() => setIsPressed(false)}
        onMouseLeave={() => setIsPressed(false)}
      >
        <AnimatedWaveIcon 
          isActive={isActive}
          isPressed={isPressed}
          hasNewContent={false}
          className={`w-6 h-6 ${isActive ? 'text-cyan-400' : textInactiveClass}`}
        />
        <span className={`text-[10px] font-medium ${isActive ? textActiveClass : textInactiveClass}`}>Home</span>
      </div>
    </button>
  );
};

/**
 * Mobile Bottom Navigation - Restructured April 2026
 * 
 * NEW LAYOUT - Thumb-Zone Optimized with Messages:
 * 
 * Tab 1: Home - Global (Social Feed)
 * Tab 2: Action Center (Role-Based):
 *        - Surfers: Explore Tab
 *        - Photographers: Photo Tools Tab
 * Tab 3: Create Post - Center Action (prominent, high-contrast)
 * Tab 4: Messages - HIGH-FREQUENCY THUMB ACCESS (moved from TopNav)
 * Tab 5: Me - Universal Profile (Mini Photo)
 * 
 * NOTE: Results Center (Gear/Stoked/Impact/Grom HQ) moved to TopNav as Dynamic Persona Icon
 */
export const BottomNav = () => {
  const { theme } = useTheme();
  const { user } = useAuth();
  const { getEffectiveRole } = usePersona();
  const navigate = useNavigate();
  const location = useLocation();
  
  // State for Photo Tools drawer and unread messages
  const [showPhotoTools, setShowPhotoTools] = useState(false);
  const [unreadMessages, setUnreadMessages] = useState(0);
  const [freshAvatarUrl, setFreshAvatarUrl] = useState(null);
  
  // Fetch fresh avatar URL from profile API to avoid stale cached data
  useEffect(() => {
    const fetchFreshAvatar = async () => {
      if (!user?.id) return;
      try {
        const response = await apiClient.get(`/profiles/${user.id}`);
        const avatarFromApi = response.data.avatar_url;
        // Store raw URL — never add ?v= to data: or blob: URLs
        setFreshAvatarUrl(avatarFromApi || null);
      } catch (error) {
        logger.error('Failed to fetch fresh avatar:', error);
      }
    };
    fetchFreshAvatar();
  }, [user?.id, user?.avatar_url, user?.updated_at]);

  // Helper: add cache-buster only for real HTTP paths (not data:/blob:/CDN URLs)
  const withCacheBuster = (url, version) => {
    if (!url) return url;
    if (url.startsWith('data:') || url.startsWith('blob:') || url.startsWith('//')) return url;
    const sep = url.includes('?') ? '&' : '?';
    return `${url}${sep}v=${version}`;
  };

  // Use fresh avatar URL if available, otherwise fallback to context
  const avatarUrl = useMemo(() => {
    const raw = freshAvatarUrl || user?.avatar_url;
    if (!raw) return null;
    const version = user?.updated_at ? new Date(user.updated_at).getTime() : Date.now();
    return withCacheBuster(raw, version);
  }, [user?.avatar_url, user?.updated_at, freshAvatarUrl]);
  
  // Get effective role for UI rendering (respects God Mode masking)
  const effectiveRole = getEffectiveRole(user?.role);
  
  // Role categorization
  const photographerRoles = ['Grom Parent', 'Hobbyist', 'Photographer', 'Approved Pro'];
  const isPhotographer = photographerRoles.includes(effectiveRole);
  const _isGromParent = effectiveRole === ROLES.GROM_PARENT || user?.is_grom_parent === true;
  
  // Theme-specific classes
  const isLight = theme === 'light';
  const isBeach = theme === 'beach';
  const navBgClass = isLight ? 'bg-white border-gray-200' : isBeach ? 'bg-black border-zinc-900' : 'bg-zinc-950 border-zinc-800';
  const textActiveClass = isLight ? 'text-gray-900' : 'text-white';
  const textInactiveClass = isLight ? 'text-gray-500' : 'text-zinc-500';

  // Fetch unread messages count
  const fetchUnreadMessages = useCallback(async () => {
    if (!user?.id) return;
    try {
      const response = await apiClient.get(`/messages/unread-counts/${user.id}`);
      setUnreadMessages(response.data.total || 0);
    } catch (error) {
      logger.error('Failed to fetch message count:', error);
    }
  }, [user?.id]);

  useEffect(() => {
    if (user?.id) {
      fetchUnreadMessages();
      // Poll every 30 seconds for new messages
      const interval = setInterval(() => {
        fetchUnreadMessages();
      }, 30000);
      return () => clearInterval(interval);
    }
  }, [user?.id, fetchUnreadMessages]);

  // Dynamically track BottomNav height and expose as --bottomnav-h CSS variable.
  // This drives the safe-bottom clearance system used by all modals and drawers.
  const navRef = React.useRef(null);
  useEffect(() => {
    const el = navRef.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(([entry]) => {
      const h = entry.contentRect.height;
      document.documentElement.style.setProperty('--bottomnav-h', `${h}px`);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // Close Photo Tools drawer when route changes (e.g., navigation from TopNav)
  useEffect(() => {
    setShowPhotoTools(false);
  }, [location.pathname]);


  // Tab 2: Action Center destination & icon (Role-Based)
  const getActionCenterConfig = () => {
    const isDedicatedGromParent = effectiveRole === ROLES.GROM_PARENT;
    // DEDICATED Grom Parent accounts: Photo Tools (archive-only, no commerce)
    if (isDedicatedGromParent) {
      return {
        path: '/gallery',
        icon: Camera,
        label: 'Photo Tools',
        activeColor: 'text-cyan-400'
      };
    }
    
    if (isPhotographer) {
      return {
        path: '/photographer/sessions',
        icon: Camera,
        label: 'Photo Tools',
        activeColor: 'text-cyan-400'
      };
    }
    // Default for surfers (including surfer+Grom Parent): Explore
    return {
      path: '/explore',
      icon: Compass,
      label: 'Explore',
      activeColor: 'text-yellow-400'
    };
  };

  // Tab 5: Me - Profile destination (ALWAYS goes to personal profile page)
  const getProfileDestination = () => {
    return '/profile';
  };

  const actionConfig = getActionCenterConfig();
  const ActionIcon = actionConfig.icon;

  // Check if current path matches
  const isPathActive = (path) => {
    if (path === '/feed') {
      return location.pathname === '/feed' || location.pathname === '/';
    }
    return location.pathname.startsWith(path);
  };

  // Handler to close any open drawers and navigate
  const handleNavigation = (path) => {
    setShowPhotoTools(false); // Close Photo Tools drawer if open
    navigate(path);
  };

  return (
    <nav 
      ref={navRef}
      className={`fixed bottom-0 left-0 right-0 z-[100] ${navBgClass} border-t md:hidden`}
      style={{ 
        paddingBottom: 'env(safe-area-inset-bottom, 0px)',
        backgroundColor: isLight ? '#ffffff' : isBeach ? '#000000' : '#09090b'
      }}
      data-testid="bottom-nav"
    >
      <div className="flex items-center justify-around py-2 px-1">
        {/* Tab 1: Home - Animated Wave Icon */}
        <HomeWaveButton 
          textActiveClass={textActiveClass}
          textInactiveClass={textInactiveClass}
          onNavigate={handleNavigation}
        />

        {/* Tab 2: Action Center - Role-Based (Explore / Photo Tools) */}
        {isPhotographer ? (
          // Photographers get Photo Tools Drawer
          <button
            onClick={() => setShowPhotoTools(true)}
            className={`flex flex-col items-center gap-0.5 min-w-[56px] py-1 ${
              showPhotoTools ? actionConfig.activeColor : textInactiveClass
            }`}
            data-testid="bottomnav-action-center"
          >
            <ActionIcon className={`w-6 h-6 ${showPhotoTools ? actionConfig.activeColor : textInactiveClass}`} />
            <span className={`text-[10px] font-medium ${showPhotoTools ? actionConfig.activeColor : textInactiveClass}`}>
              {actionConfig.label}
            </span>
          </button>
        ) : (
          // Surfers get Explore navigation + new photos badge
          <button
            onClick={() => handleNavigation(actionConfig.path)}
            className={`flex flex-col items-center gap-0.5 min-w-[56px] py-1 ${isPathActive(actionConfig.path) ? actionConfig.activeColor : textInactiveClass}`}
            data-testid="bottomnav-action-center"
          >
            <div className="relative">
              <ActionIcon className={`w-6 h-6 ${isPathActive(actionConfig.path) ? actionConfig.activeColor : textInactiveClass}`} />
            </div>
            <span className={`text-[10px] font-medium ${isPathActive(actionConfig.path) ? actionConfig.activeColor : textInactiveClass}`}>
              {actionConfig.label}
            </span>
          </button>
        )}

        {/* Tab 3: Create Post - Center Action Button */}
        <button
          onClick={() => handleNavigation('/create')}
          className="flex flex-col items-center gap-0.5 -mt-4 relative"
          data-testid="bottomnav-create"
          style={{ zIndex: 110 }}
        >
          <div className="w-14 h-14 rounded-full bg-gradient-to-r from-yellow-400 via-orange-400 to-pink-500 flex items-center justify-center shadow-lg shadow-orange-500/30 border-4 border-zinc-950">
            <Plus className="w-7 h-7 text-black stroke-[3]" />
          </div>
          <span className={`text-[10px] font-bold text-yellow-400 mt-0.5`}>Create</span>
        </button>

        {/* Tab 4: Messages - HIGH-FREQUENCY THUMB ACCESS (moved from TopNav) */}
        <button
          onClick={() => handleNavigation('/messages')}
          className={`flex flex-col items-center gap-0.5 min-w-[56px] py-1 relative ${isPathActive('/messages') ? 'text-blue-400' : textInactiveClass}`}
          data-testid="bottomnav-messages"
        >
          <div className="relative">
            <MessageCircle className={`w-6 h-6 ${isPathActive('/messages') ? 'text-blue-400' : textInactiveClass}`} />
            {unreadMessages > 0 && (
              <span className="absolute -top-1 -right-1 min-w-[16px] h-[16px] px-0.5 flex items-center justify-center bg-red-500 text-white text-[9px] font-bold rounded-full">
                {unreadMessages > 99 ? '99+' : unreadMessages}
              </span>
            )}
          </div>
          <span className={`text-[10px] font-medium ${isPathActive('/messages') ? 'text-blue-400' : textInactiveClass}`}>
            Messages
          </span>
        </button>

        {/* Tab 5: Me - Universal Profile with Mini Photo */}
        <button
          onClick={() => handleNavigation(getProfileDestination())}
          className="flex flex-col items-center gap-0.5 min-w-[56px] py-1"
          data-testid="bottomnav-me"
        >
          <Avatar className="w-7 h-7 border-2 border-zinc-700">
            <AvatarImage src={avatarUrl} key={avatarUrl} />
            <AvatarFallback className="text-[10px] bg-zinc-800 text-white">
              {user?.full_name?.charAt(0) || user?.email?.charAt(0) || 'U'}
            </AvatarFallback>
          </Avatar>
          <span className={`text-[10px] font-medium ${textInactiveClass}`}>
            Me
          </span>
        </button>
      </div>
      
      {/* Photo Tools Drawer - Only rendered for photographers */}
      {isPhotographer && (
        <PhotoToolsDrawer 
          isOpen={showPhotoTools} 
          onClose={() => setShowPhotoTools(false)} 
        />
      )}
    </nav>
  );
};

export default BottomNav;

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { 
  Camera, Upload, X, Video, FileText, 
  CheckCircle2, AlertCircle, Loader2, CloudSun, Waves, RefreshCw
} from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { Button } from './ui/button';
import { Textarea } from './ui/textarea';
import { Badge } from './ui/badge';
import { toast } from 'sonner';
import logger from '../utils/logger';

/**
 * ConditionsModal - Mandatory "Go Live" Gatekeeper
 * 
 * This modal ensures photographers provide critical context before starting a session:
 * 1. Capture or upload a condition photo/video (REQUIRED)
 * 2. Add spot notes for surfers (optional but encouraged)
 * 
 * The 'Go Live' button is disabled until media is attached.
 */
const ConditionsModal = ({ 
  isOpen, 
  onClose, 
  onConfirm, 
  spotName, 
  isLoading = false 
}) => {
  // State
  const [conditionMedia, setConditionMedia] = useState(null);
  const [mediaPreview, setMediaPreview] = useState(null);
  const [mediaType, setMediaType] = useState(null); // 'image' | 'video'
  const [spotNotes, setSpotNotes] = useState('');
  const [cameraActive, setCameraActive] = useState(false);
  const [cameraMode, setCameraMode] = useState('photo'); // 'photo' | 'video'
  const [cameraFacing, setCameraFacing] = useState('environment'); // 'environment' = rear, 'user' = front
  const [isRecording, setIsRecording] = useState(false);
  const [recordingSeconds, setRecordingSeconds] = useState(0); // Recording timer
  const [_uploadMode, setUploadMode] = useState('capture'); // 'capture' | 'upload'
  
  // Refs
  const videoRef = useRef(null);         // Live camera feed
  const previewVideoRef = useRef(null);  // Recorded video preview (separate from live feed)
  const streamRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunksRef = useRef([]);
  const fileInputRef = useRef(null);
  const recordingTimerRef = useRef(null); // Auto-stop timer
  const recordingIntervalRef = useRef(null); // Countdown interval
  const MAX_RECORD_SECONDS = 60;

  // Cleanup camera on unmount or modal close
  useEffect(() => {
    return () => stopCamera();
  }, []);

  // When modal opens/closes, stop camera
  useEffect(() => {
    if (!isOpen) {
      stopCamera();
      setMediaPreview(null);
      setMediaType(null);
      setConditionMedia(null);
      setSpotNotes('');
      setCameraActive(false);
      setUploadMode('capture');
    }
  }, [isOpen]);

  // Set src on the preview <video> element imperatively to avoid srcObject conflicts.
  // If we use the same videoRef for live feed and preview, the browser may keep
  // the last srcObject (stopped stream) and show black instead of the blob URL.
  useEffect(() => {
    if (mediaType === 'video' && mediaPreview && previewVideoRef.current) {
      const vid = previewVideoRef.current;
      // Clear any stale srcObject first
      vid.srcObject = null;
      vid.src = mediaPreview;
      vid.load();
      vid.play().catch(() => {}); // auto-play (muted not required for recorded blobs)
    }
  }, [mediaType, mediaPreview]);

  // Camera functions
  const startCamera = async (mode = 'photo', facing = cameraFacing) => {
    try {
      setCameraMode(mode);
      
      // Stop existing stream first
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
        streamRef.current = null;
      }
      
      let stream;
      const baseConstraints = {
        width: { ideal: 1280 },
        height: { ideal: 720 }
      };
      
      // Try multiple constraint variations for better mobile compatibility
      const constraintOptions = [
        // Option 1: Simple string facingMode (most compatible)
        { video: { facingMode: facing, ...baseConstraints }, audio: mode === 'video' },
        // Option 2: Object with ideal (recommended)
        { video: { facingMode: { ideal: facing }, ...baseConstraints }, audio: mode === 'video' },
        // Option 3: Object with exact (strict)
        { video: { facingMode: { exact: facing }, ...baseConstraints }, audio: mode === 'video' },
        // Option 4: No facingMode (last resort)
        { video: baseConstraints, audio: mode === 'video' }
      ];
      
      for (let i = 0; i < constraintOptions.length; i++) {
        try {
          logger.debug(`Trying camera constraint option ${i + 1}:`, constraintOptions[i]);
          stream = await navigator.mediaDevices.getUserMedia(constraintOptions[i]);
          logger.debug(`Camera initialized with option ${i + 1}`);
          break;
        } catch (err) {
          logger.warn(`Camera option ${i + 1} failed:`, err.name);
          if (i === constraintOptions.length - 1) {
            throw err; // Rethrow on last attempt
          }
        }
      }
      
      if (!stream) {
        throw new Error('Could not acquire camera stream');
      }
      
      streamRef.current = stream;
      
      // IMPORTANT: Set cameraActive FIRST so the video element renders
      // Then attach the stream in the next tick when videoRef is available
      setCameraActive(true);
      
    } catch (error) {
      logger.error('Camera error:', error);
      toast.error('Could not access camera. Please use file upload instead.');
      setUploadMode('upload');
    }
  };
  
  // Effect to attach stream to video element when it becomes available
  useEffect(() => {
    // Use a small delay to ensure the video element is fully mounted
    const attachStream = () => {
      if (cameraActive && streamRef.current && videoRef.current) {
        logger.debug('Attaching stream to video element');
        videoRef.current.srcObject = streamRef.current;
        // Ensure video plays
        videoRef.current.play().catch((err) => {
          logger.warn('Video play warning:', err);
        });
      }
    };
    
    // Small timeout to ensure React has rendered the video element
    const timeoutId = setTimeout(attachStream, 50);
    return () => clearTimeout(timeoutId);
  }, [cameraActive]);

  // Flip camera between front and back
  const flipCamera = async () => {
    const newFacing = cameraFacing === 'environment' ? 'user' : 'environment';
    setCameraFacing(newFacing);
    // Small delay to ensure state is updated before restarting camera
    await startCamera(cameraMode, newFacing);
    toast.success(`Switched to ${newFacing === 'environment' ? 'rear' : 'front'} camera`);
  };

  const stopCamera = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
    }
    setCameraActive(false);
    setIsRecording(false);
  }, [isRecording]);

  // Capture photo
  const capturePhoto = () => {
    if (!videoRef.current) return;
    
    const canvas = document.createElement('canvas');
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(videoRef.current, 0, 0);
    
    const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
    setMediaPreview(dataUrl);
    setMediaType('image');
    
    // Convert to blob for upload
    canvas.toBlob((blob) => {
      setConditionMedia(blob);
    }, 'image/jpeg', 0.85);
    
    stopCamera();
    toast.success('Photo captured!');
  };

  // Start/Stop video recording
  const toggleVideoRecording = () => {
    if (!isRecording) {
      // Start recording
      recordedChunksRef.current = [];
      const stream = streamRef.current;

      if (!stream) return;

      // Detect supported mimeType
      const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp9')
        ? 'video/webm;codecs=vp9'
        : MediaRecorder.isTypeSupported('video/webm')
        ? 'video/webm'
        : '';

      const mediaRecorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);
      mediaRecorderRef.current = mediaRecorder;

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          recordedChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = () => {
        // Clear timers
        clearTimeout(recordingTimerRef.current);
        clearInterval(recordingIntervalRef.current);
        setRecordingSeconds(0);

        const usedMime = mimeType || 'video/webm';
        const blob = new Blob(recordedChunksRef.current, { type: usedMime });
        const url = URL.createObjectURL(blob);
        setMediaPreview(url);
        setMediaType('video');
        setConditionMedia(blob);
        stopCamera();
        toast.success('Video recorded!');
      };

      // Use 250ms timeslice so data flows continuously (fixes mobile onstop)
      mediaRecorder.start(250);
      setIsRecording(true);
      setRecordingSeconds(0);

      // Auto-stop at MAX_RECORD_SECONDS
      recordingTimerRef.current = setTimeout(() => {
        if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
          mediaRecorderRef.current.stop();
          setIsRecording(false);
          toast.info('Max recording time reached (60s)');
        }
      }, MAX_RECORD_SECONDS * 1000);

      // Countdown interval
      recordingIntervalRef.current = setInterval(() => {
        setRecordingSeconds(prev => {
          if (prev >= MAX_RECORD_SECONDS - 1) {
            clearInterval(recordingIntervalRef.current);
            return MAX_RECORD_SECONDS;
          }
          return prev + 1;
        });
      }, 1000);

    } else {
      // Manual stop
      clearTimeout(recordingTimerRef.current);
      clearInterval(recordingIntervalRef.current);
      mediaRecorderRef.current?.stop();
      setIsRecording(false);
    }
  };

  // Handle file upload
  const handleFileSelect = (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    
    // Validate file type
    const isImage = file.type.startsWith('image/');
    const isVideo = file.type.startsWith('video/');
    
    if (!isImage && !isVideo) {
      toast.error('Please select an image or video file');
      return;
    }
    
    // Check file size (max 50MB for video, 10MB for image)
    const maxSize = isVideo ? 50 * 1024 * 1024 : 10 * 1024 * 1024;
    if (file.size > maxSize) {
      toast.error(`File too large. Max ${isVideo ? '50MB' : '10MB'}`);
      return;
    }
    
    setConditionMedia(file);
    setMediaType(isImage ? 'image' : 'video');
    setMediaPreview(URL.createObjectURL(file));
    toast.success(`${isImage ? 'Photo' : 'Video'} selected!`);
  };

  // Clear media
  const clearMedia = () => {
    if (mediaPreview && mediaPreview.startsWith('blob:')) {
      URL.revokeObjectURL(mediaPreview);
    }
    setConditionMedia(null);
    setMediaPreview(null);
    setMediaType(null);
  };

  // Handle confirm
  const handleConfirm = (e) => {
    e.preventDefault();
    if (!conditionMedia) {
      toast.error('Please add a condition photo or video first');
      return;
    }
    
    onConfirm({
      media: conditionMedia,
      mediaType,
      spotNotes: spotNotes.trim()
    });
  };

  // Check if go live is enabled
  const canGoLive = !!conditionMedia;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent 
        className="bg-background border-border text-foreground sm:max-w-md"
        overlayClassName="z-[9998]"
        data-testid="conditions-modal"
        style={{ zIndex: 9999 }}
      >
        <DialogHeader className="border-b border-border">
          <DialogTitle className="text-xl font-bold flex items-center gap-2 text-foreground">
            <CloudSun className="w-5 h-5 text-cyan-400" />
            Conditions Check
          </DialogTitle>
        </DialogHeader>

        {/* Scrollable content area */}
        <div className="flex-1 overflow-y-auto px-4 sm:px-6">
          <div className="space-y-4 py-4">
          {/* Spot Info */}
          <div className="flex items-center gap-2 p-3 bg-muted/50 rounded-lg">
            <Waves className="w-4 h-4 text-blue-400" />
            <span className="text-muted-foreground text-sm">Going live at</span>
            <span className="text-foreground font-medium">{spotName}</span>
          </div>

          {/* Instructions */}
          <div className="p-3 bg-cyan-500/10 border border-cyan-500/30 rounded-lg">
            <p className="text-cyan-600 dark:text-cyan-300 text-sm">
              <span className="font-medium">Required:</span> Share current conditions with surfers 
              by taking a quick photo or video of the waves.
            </p>
          </div>

          {/* Media Capture/Upload Section */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className="text-muted-foreground text-sm flex items-center gap-2">
                <Camera className="w-4 h-4" />
                Condition Media <span className="text-red-400">*</span>
              </label>
              {conditionMedia && (
                <Badge className="bg-green-500/20 text-green-400">
                  <CheckCircle2 className="w-3 h-3 mr-1" />
                  Ready
                </Badge>
              )}
            </div>

            {/* Preview or Capture Area */}
            {mediaPreview ? (
              <div className="relative aspect-video bg-black rounded-xl overflow-hidden">
                {mediaType === 'video' ? (
                  <video 
                    ref={previewVideoRef}
                    className="w-full h-full object-cover" 
                    controls
                    playsInline
                    autoPlay
                    muted={false}
                    data-testid="media-preview-video"
                  />
                ) : (
                  <img 
                    src={mediaPreview} 
                    alt="Conditions preview" 
                    className="w-full h-full object-cover"
                    data-testid="media-preview-image" 
                  />
                )}
                <button
                  onClick={clearMedia}
                  className="absolute top-2 right-2 w-8 h-8 bg-black/70 rounded-full flex items-center justify-center text-white hover:bg-red-500/70 transition-colors"
                  data-testid="clear-media-btn"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            ) : cameraActive ? (
              <div className="relative aspect-video bg-black rounded-xl overflow-hidden">
                <video
                  ref={(el) => {
                    videoRef.current = el;
                    // Immediately attach stream when video element mounts
                    if (el && streamRef.current && !el.srcObject) {
                      el.srcObject = streamRef.current;
                      el.play().catch(() => {});
                    }
                  }}
                  autoPlay
                  playsInline
                  muted
                  className="w-full h-full object-cover"
                  onLoadedMetadata={(e) => {
                    // Ensure video plays when metadata is loaded (iOS fix)
                    e.target.play().catch(() => {});
                  }}
                />
                {/* Recording indicator */}
                {isRecording && (
                  <div className="absolute top-3 left-3 flex items-center gap-2 px-2 py-1 bg-red-500/90 rounded-full">
                    <span className="w-2 h-2 bg-white rounded-full animate-pulse" />
                    <span className="text-white text-xs font-medium">REC {recordingSeconds}s / {MAX_RECORD_SECONDS}s</span>
                  </div>
                )}
                
                {/* Camera controls */}
                <div className="absolute bottom-3 left-0 right-0 flex justify-center items-center gap-3">
                  {/* Flip Camera Button */}
                  <Button
                    onClick={flipCamera}
                    variant="outline"
                    className="w-10 h-10 rounded-full border-border text-white hover:bg-black/50 p-0"
                    data-testid="flip-camera-btn"
                  >
                    <RefreshCw className="w-5 h-5" />
                  </Button>
                  
                  {/* Main Capture Button */}
                  {cameraMode === 'photo' ? (
                    <Button
                      onClick={capturePhoto}
                      className="w-14 h-14 rounded-full bg-white hover:bg-gray-100"
                      data-testid="capture-photo-btn"
                    >
                      <Camera className="w-6 h-6 text-black" />
                    </Button>
                  ) : (
                    <Button
                      onClick={toggleVideoRecording}
                      className={`w-14 h-14 rounded-full ${isRecording ? 'bg-red-500 hover:bg-red-600' : 'bg-red-500 hover:bg-red-600'}`}
                      data-testid="record-video-btn"
                    >
                      {isRecording ? (
                        <span className="w-5 h-5 bg-white rounded-sm" />
                      ) : (
                        <Video className="w-6 h-6 text-white" />
                      )}
                    </Button>
                  )}
                  
                  {/* Cancel Button */}
                  <Button
                    onClick={stopCamera}
                    variant="outline"
                    className="border-border text-white hover:bg-black/50"
                    data-testid="cancel-camera-btn"
                  >
                    Cancel
                  </Button>
                </div>
                
                {/* Camera facing indicator */}
                <div className="absolute top-3 right-3 px-2 py-1 bg-black/50 rounded-full text-xs text-white">
                  {cameraFacing === 'environment' ? 'Rear' : 'Front'}
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-3">
                {/* Capture Photo */}
                <button
                  onClick={() => startCamera('photo')}
                  className="flex flex-col items-center justify-center gap-2 p-4 bg-card hover:bg-muted border border-border hover:border-cyan-500/50 rounded-xl transition-all"
                  data-testid="start-photo-capture"
                >
                  <div className="w-12 h-12 rounded-full bg-cyan-500/20 flex items-center justify-center">
                    <Camera className="w-6 h-6 text-cyan-400" />
                  </div>
                  <span className="text-foreground text-sm font-medium">Take Photo</span>
                  <span className="text-muted-foreground text-xs">Use camera</span>
                </button>
                
                {/* Capture Video */}
                <button
                  onClick={() => startCamera('video')}
                  className="flex flex-col items-center justify-center gap-2 p-4 bg-card hover:bg-muted border border-border hover:border-purple-500/50 rounded-xl transition-all"
                  data-testid="start-video-capture"
                >
                  <div className="w-12 h-12 rounded-full bg-purple-500/20 flex items-center justify-center">
                    <Video className="w-6 h-6 text-purple-400" />
                  </div>
                  <span className="text-foreground text-sm font-medium">Record Video</span>
                  <span className="text-muted-foreground text-xs">60 sec max</span>
                </button>
                
                {/* Upload from Gallery */}
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="col-span-2 flex items-center justify-center gap-3 p-3 bg-muted/50 hover:bg-muted border border-dashed border-border hover:border-muted-foreground rounded-xl transition-all"
                  data-testid="upload-media-btn"
                >
                  <Upload className="w-5 h-5 text-muted-foreground" />
                  <span className="text-muted-foreground text-sm">Upload from gallery</span>
                </button>
                
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*,video/*"
                  onChange={handleFileSelect}
                  className="hidden"
                  data-testid="file-input"
                />
              </div>
            )}
          </div>

          {/* Spot Notes */}
          <div className="space-y-2">
            <label className="text-muted-foreground text-sm flex items-center gap-2">
              <FileText className="w-4 h-4" />
              Spot Notes <span className="text-muted-foreground/60">(optional)</span>
            </label>
            <Textarea
              value={spotNotes}
              onChange={(e) => setSpotNotes(e.target.value)}
              placeholder="E.g., Clean 3-4ft sets, offshore winds, best at mid-tide..."
              className="bg-card border-border text-foreground placeholder-muted-foreground resize-none h-20"
              maxLength={200}
              data-testid="spot-notes-input"
            />
            <p className="text-muted-foreground/60 text-xs text-right">{spotNotes.length}/200</p>
          </div>

          {/* Requirement Notice */}
          {!conditionMedia && (
            <div className="flex items-center gap-2 p-2 bg-yellow-500/10 border border-yellow-500/30 rounded-lg">
              <AlertCircle className="w-4 h-4 text-yellow-500 dark:text-yellow-400 shrink-0" />
              <p className="text-yellow-600 dark:text-yellow-300 text-xs">
                Add a condition photo or video to enable Go Live
              </p>
            </div>
          )}
          </div>
        </div>

        <DialogFooter className="flex flex-row gap-3 border-t border-border">
          <Button
            variant="outline"
            onClick={onClose}
            className="flex-1 border-border text-foreground hover:bg-muted"
            disabled={isLoading}
            data-testid="cancel-conditions-btn"
          >
            Cancel
          </Button>
          <Button
            onClick={handleConfirm}
            disabled={!canGoLive || isLoading}
            className={`flex-1 font-bold transition-all ${
              canGoLive 
                ? 'bg-gradient-to-r from-green-400 to-emerald-500 text-black hover:from-green-500 hover:to-emerald-600' 
                : 'bg-muted text-muted-foreground cursor-not-allowed'
            }`}
            data-testid="go-live-final-btn"
          >
            {isLoading ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>
                <CheckCircle2 className="w-4 h-4 mr-2" />
                Go Live
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default ConditionsModal;

﻿/**
 * CreateAdModal - User-facing ad submission for Self-Serve Ad Engine
 * Similar flow to creating a social post - supports images and videos
 */
import React, { useState, useRef } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import {
  Megaphone, Image, Video, X, Upload, Loader2, DollarSign,
  CheckCircle, AlertCircle, ExternalLink, Sparkles
} from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from './ui/dialog';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Textarea } from './ui/textarea';
import { Badge } from './ui/badge';
import { toast } from 'sonner';
import logger from '../utils/logger';


// Ad type options
const AD_TYPES = [
  { value: 'sponsored', label: 'Sponsored', description: 'Promote your business or service' },
  { value: 'promo', label: 'Promotion', description: 'Special offers and deals' },
];

// Target role options
const TARGET_ROLES = [
  { value: '', label: 'All Users' },
  { value: 'Surfer', label: 'Surfers' },
  { value: 'Photographer', label: 'Photographers' },
  { value: 'Grom Parent', label: 'Parents' },
  { value: 'School', label: 'Schools & Coaches' },
];

export const CreateAdModal = ({ isOpen, onClose, onSuccess }) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';
  const fileInputRef = useRef(null);

  // Form state
  const [headline, setHeadline] = useState('');
  const [description, setDescription] = useState('');
  const [cta, setCta] = useState('Learn More');
  const [ctaLink, setCtaLink] = useState('');
  const [adType, setAdType] = useState('sponsored');
  const [targetRole, setTargetRole] = useState('');
  const [budgetCredits, setBudgetCredits] = useState(10);
  
  // Media state
  const [mediaUrl, setMediaUrl] = useState(null);
  const [mediaType, setMediaType] = useState(null); // 'image' or 'video'
  const [thumbnailUrl, setThumbnailUrl] = useState(null);
  const [mediaPreview, setMediaPreview] = useState(null);
  const [uploadingMedia, setUploadingMedia] = useState(false);
  
  // Submission state
  const [submitting, setSubmitting] = useState(false);
  const [step, setStep] = useState(1); // 1: content, 2: targeting, 3: preview

  const handleMediaSelect = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    
    const isVideo = file.type.startsWith('video/');
    const isImage = file.type.startsWith('image/');
    
    if (!isVideo && !isImage) {
      toast.error('Please select an image or video file');
      return;
    }

    // Check file size (max 10MB for images, 50MB for videos)
    const maxSize = isVideo ? 50 * 1024 * 1024 : 10 * 1024 * 1024;
    if (file.size > maxSize) {
      toast.error(`File too large. Max ${isVideo ? '50MB' : '10MB'}`);
      return;
    }
    
    setUploadingMedia(true);
    setMediaType(isVideo ? 'video' : 'image');
    
    try {
      // Create preview
      const reader = new FileReader();
      reader.onload = (e) => {
        setMediaPreview(e.target.result);
      };
      reader.readAsDataURL(file);

      // Upload to server
      const formData = new FormData();
      formData.append('file', file);
      formData.append('user_id', user.id);
      formData.append('upload_type', 'ad_creative');

      const response = await apiClient.post(`/uploads/media`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      if (isVideo) {
        setMediaUrl(response.data.video_url || response.data.url);
        setThumbnailUrl(response.data.thumbnail_url);
      } else {
        setMediaUrl(response.data.url);
      }
      
      toast.success('Media uploaded successfully');
    } catch (error) {
      logger.error('Upload error:', error);
      toast.error('Failed to upload media');
      clearMedia();
    } finally {
      setUploadingMedia(false);
    }
  };

  const clearMedia = () => {
    setMediaUrl(null);
    setMediaType(null);
    setThumbnailUrl(null);
    setMediaPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = async () => {
    if (!headline.trim() || !description.trim() || !ctaLink.trim()) {
      toast.error('Please fill in all required fields');
      return;
    }

    if (budgetCredits < 10) {
      toast.error('Minimum budget is $10');
      return;
    }

    if ((user?.credit_balance || 0) < budgetCredits) {
      toast.error(`Insufficient credits. You have $${user?.credit_balance || 0}`);
      return;
    }

    setSubmitting(true);
    try {
      const response = await apiClient.post(`/ads/submit`, {
        headline: headline.trim(),
        description: description.trim(),
        cta: cta.trim() || 'Learn More',
        cta_link: ctaLink.trim(),
        ad_type: adType,
        target_roles: targetRole ? [targetRole] : [],
        image_url: mediaType === 'image' ? mediaUrl : null,
        video_url: mediaType === 'video' ? mediaUrl : null,
        thumbnail_url: thumbnailUrl,
        media_type: mediaType,
        budget_credits: budgetCredits
      });

      toast.success('Ad submitted for approval!', {
        description: `$${budgetCredits} deducted. New balance: $${response.data.new_balance}`
      });

      // Reset form
      resetForm();
      onSuccess?.();
      onClose();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to submit ad');
    } finally {
      setSubmitting(false);
    }
  };

  const resetForm = () => {
    setHeadline('');
    setDescription('');
    setCta('Learn More');
    setCtaLink('');
    setAdType('sponsored');
    setTargetRole('');
    setBudgetCredits(10);
    clearMedia();
    setStep(1);
  };

  const canProceedToStep2 = headline.trim() && description.trim();
  const canProceedToStep3 = ctaLink.trim();
  const canSubmit = canProceedToStep2 && canProceedToStep3 && budgetCredits >= 10;

  const cardBg = isLight ? 'bg-white' : 'bg-zinc-900';
  const textClass = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  const inputClass = isLight 
    ? 'bg-gray-50 border-gray-300 text-gray-900' 
    : 'bg-zinc-800 border-zinc-700 text-white';

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className={`${cardBg} border-zinc-800 sm:max-w-md`}>
        <DialogHeader className="shrink-0 border-b border-zinc-700 px-4 sm:px-6 pt-4 pb-3">
          <DialogTitle className={`${textClass} flex items-center gap-2`}>
            <Megaphone className="w-5 h-5 text-purple-500" />
            Create Ad
            <Badge className="bg-zinc-700 text-gray-300 text-xs">
              Step {step}/3
            </Badge>
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-4 sm:px-6 py-4 space-y-4">
          {/* Step 1: Content */}
          {step === 1 && (
            <>
              {/* Media Upload */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-2 block`}>
                  Ad Creative (Optional)
                </label>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*,video/*"
                  onChange={handleMediaSelect}
                  className="hidden"
                />
                
                {mediaPreview ? (
                  <div className="relative rounded-xl overflow-hidden border border-zinc-700">
                    {mediaType === 'video' ? (
                      <video 
                        src={mediaPreview} 
                        className="w-full h-40 object-cover" 
                        controls 
                      />
                    ) : (
                      <img 
                        src={mediaPreview} 
                        alt="Ad preview" 
                        className="w-full h-40 object-cover" 
                      />
                    )}
                    <button
                      onClick={clearMedia}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 rounded-full hover:bg-black/80 transition-colors"
                    >
                      <X className="w-4 h-4 text-white" />
                    </button>
                    <div className="absolute bottom-2 left-2">
                      <Badge className={mediaType === 'video' ? 'bg-red-500' : 'bg-blue-500'}>
                        {mediaType === 'video' ? <Video className="w-3 h-3 mr-1" /> : <Image className="w-3 h-3 mr-1" />}
                        {mediaType}
                      </Badge>
                    </div>
                  </div>
                ) : (
                  <button
                    onClick={() => fileInputRef.current?.click()}
                    disabled={uploadingMedia}
                    className={`w-full h-32 border-2 border-dashed rounded-xl flex flex-col items-center justify-center gap-2 transition-colors ${
                      isLight 
                        ? 'border-gray-300 hover:border-purple-400 hover:bg-purple-50' 
                        : 'border-zinc-700 hover:border-purple-500 hover:bg-purple-500/10'
                    }`}
                  >
                    {uploadingMedia ? (
                      <Loader2 className="w-6 h-6 animate-spin text-purple-500" />
                    ) : (
                      <>
                        <Upload className={`w-6 h-6 ${textSecondary}`} />
                        <span className={`text-sm ${textSecondary}`}>
                          Upload Image or Video
                        </span>
                        <span className={`text-xs ${textSecondary}`}>
                          Max 10MB image, 50MB video
                        </span>
                      </>
                    )}
                  </button>
                )}
              </div>

              {/* Headline */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-2 block`}>
                  Headline *
                </label>
                <Input
                  value={headline}
                  onChange={(e) => setHeadline(e.target.value)}
                  placeholder="e.g., Get 50% Off Your First Session"
                  maxLength={60}
                  className={inputClass}
                />
                <span className={`text-xs ${textSecondary}`}>
                  {headline.length}/60 characters
                </span>
              </div>

              {/* Description */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-2 block`}>
                  Description *
                </label>
                <Textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Tell users what you're offering..."
                  maxLength={150}
                  rows={3}
                  className={`${inputClass} resize-none`}
                />
                <span className={`text-xs ${textSecondary}`}>
                  {description.length}/150 characters
                </span>
              </div>

              <Button
                onClick={() => setStep(2)}
                disabled={!canProceedToStep2}
                className="w-full bg-purple-600 hover:bg-purple-700"
              >
                Continue to Targeting
              </Button>
            </>
          )}

          {/* Step 2: Targeting */}
          {step === 2 && (
            <>
              {/* CTA Button */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-2 block`}>
                  Button Text
                </label>
                <Input
                  value={cta}
                  onChange={(e) => setCta(e.target.value)}
                  placeholder="Learn More"
                  maxLength={20}
                  className={inputClass}
                />
              </div>

              {/* CTA Link */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-2 block`}>
                  Link URL *
                </label>
                <Input
                  value={ctaLink}
                  onChange={(e) => setCtaLink(e.target.value)}
                  placeholder="https://yoursite.com/offer"
                  className={inputClass}
                />
              </div>

              {/* Ad Type */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-2 block`}>
                  Ad Type
                </label>
                <div className="grid grid-cols-2 gap-2">
                  {AD_TYPES.map((type) => (
                    <button
                      key={type.value}
                      onClick={() => setAdType(type.value)}
                      className={`p-3 rounded-lg border-2 text-left transition-colors ${
                        adType === type.value
                          ? 'border-purple-500 bg-purple-500/10'
                          : `border-zinc-700 ${isLight ? 'hover:border-gray-400' : 'hover:border-zinc-500'}`
                      }`}
                    >
                      <p className={`font-medium ${textClass}`}>{type.label}</p>
                      <p className={`text-xs ${textSecondary}`}>{type.description}</p>
                    </button>
                  ))}
                </div>
              </div>

              {/* Target Audience */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-2 block`}>
                  Target Audience
                </label>
                <select
                  value={targetRole}
                  onChange={(e) => setTargetRole(e.target.value)}
                  className={`w-full h-10 px-3 rounded-lg border ${inputClass}`}
                >
                  {TARGET_ROLES.map((role) => (
                    <option key={role.value} value={role.value}>
                      {role.label}
                    </option>
                  ))}
                </select>
              </div>

              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={() => setStep(1)}
                  className="flex-1 border-zinc-700"
                >
                  Back
                </Button>
                <Button
                  onClick={() => setStep(3)}
                  disabled={!canProceedToStep3}
                  className="flex-1 bg-purple-600 hover:bg-purple-700"
                >
                  Review & Pay
                </Button>
              </div>
            </>
          )}

          {/* Step 3: Preview & Budget */}
          {step === 3 && (
            <>
              {/* Ad Preview */}
              <div className="rounded-xl border border-purple-500/30 overflow-hidden">
                <div className="bg-gradient-to-r from-purple-500/20 to-pink-500/20 px-3 py-2 flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-purple-400" />
                  <span className={`text-sm font-medium ${textClass}`}>Ad Preview</span>
                </div>
                <div className="p-4 space-y-3">
                  {mediaPreview && (
                    <div className="rounded-lg overflow-hidden">
                      {mediaType === 'video' ? (
                        <video src={mediaPreview} className="w-full h-32 object-cover" />
                      ) : (
                        <img src={mediaPreview} alt="Ad" className="w-full h-32 object-cover" />
                      )}
                    </div>
                  )}
                  <div>
                    <h3 className={`font-bold ${textClass}`}>{headline || 'Your Headline'}</h3>
                    <p className={`text-sm ${textSecondary} mt-1`}>
                      {description || 'Your description here...'}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button size="sm" className="bg-purple-600 hover:bg-purple-700">
                      {cta || 'Learn More'}
                      <ExternalLink className="w-3 h-3 ml-1" />
                    </Button>
                    {targetRole && (
                      <Badge className="bg-zinc-700 text-gray-300">
                        Targeting: {targetRole}
                      </Badge>
                    )}
                  </div>
                </div>
              </div>

              {/* Budget */}
              <div className="rounded-xl border border-green-500/30 p-4">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <DollarSign className="w-5 h-5 text-green-500" />
                    <span className={`font-medium ${textClass}`}>Ad Budget</span>
                  </div>
                  <span className={`text-sm ${textSecondary}`}>
                    Balance: ${user?.credit_balance?.toFixed(2) || '0.00'}
                  </span>
                </div>
                
                <div className="flex items-center gap-3">
                  <Input
                    type="number"
                    value={budgetCredits}
                    onChange={(e) => setBudgetCredits(Math.max(10, parseInt(e.target.value) || 10))}
                    min={10}
                    className={`${inputClass} w-24`}
                  />
                  <span className={textSecondary}>credits</span>
                </div>
                
                <p className={`text-xs ${textSecondary} mt-2`}>
                  Minimum $10. Higher budgets get more impressions.
                </p>
              </div>

              {/* Submit Info */}
              <div className={`rounded-lg p-3 ${isLight ? 'bg-blue-50' : 'bg-blue-500/10'} flex items-start gap-2`}>
                <AlertCircle className="w-4 h-4 text-blue-400 mt-0.5" />
                <p className={`text-xs ${textSecondary}`}>
                  Your ad will be reviewed by our team within 24 hours. 
                  Credits are held until approval. Rejected ads get a full refund.
                </p>
              </div>

              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={() => setStep(2)}
                  className="flex-1 border-zinc-700"
                >
                  Back
                </Button>
                <Button
                  onClick={handleSubmit}
                  disabled={!canSubmit || submitting || (user?.credit_balance || 0) < budgetCredits}
                  className="flex-1 bg-green-600 hover:bg-green-700"
                >
                  {submitting ? (
                    <Loader2 className="w-4 h-4 animate-spin mr-2" />
                  ) : (
                    <CheckCircle className="w-4 h-4 mr-2" />
                  )}
                  Submit Ad (${budgetCredits})
                </Button>
              </div>
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
};

