 * Provides the same full-featured experience as the Feed's "+ Post" button
 */
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { MapPin, Loader2, Navigation, Image, Video, Upload, Camera, Megaphone, Waves, ChevronDown, Wind, ArrowUpDown, X, Check, ChevronLeft, ChevronRight, Smile, AtSign, Play, HelpCircle, Clock, Music, VolumeX, Radio } from 'lucide-react';
import { toast } from 'sonner';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Textarea } from './ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from './ui/dialog';
import { CreateAdModal } from './CreateAdModal';
import CreateWaveModal from './CreateWaveModal';
import EmojiPicker from './EmojiPicker';
import MentionAutocomplete from './MentionAutocomplete';
import HashtagAutocomplete from './HashtagAutocomplete';
import logger from '../utils/logger';
import GoLiveModal from './GoLiveModal';
import WebcamCaptureModal from './WebcamCaptureModal';


export const CreatePost = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();

  // Theme-aware classes
  const isLight = theme === 'light';
  const isBeach = theme === 'beach';
  const bgInput = isLight ? 'bg-gray-100' : isBeach ? 'bg-black' : 'bg-zinc-900';
  const borderInput = isLight ? 'border-gray-300' : isBeach ? 'border-zinc-800' : 'border-zinc-700';
  const textInput = isLight ? 'text-gray-900' : 'text-white';
  const labelClass = isLight ? 'text-gray-500' : isBeach ? 'text-zinc-300' : 'text-zinc-400';
  const cardBg = isLight ? 'bg-gray-50' : isBeach ? 'bg-zinc-950' : 'bg-zinc-800/50';
  const cardBorder = isLight ? 'border-gray-200' : isBeach ? 'border-zinc-800' : 'border-zinc-700';
  const pillBg = isLight ? 'bg-gray-100 hover:bg-gray-200 text-gray-800' : 'bg-zinc-700 hover:bg-zinc-600 text-white';
  const hoverBg = isLight ? 'hover:bg-gray-100' : 'hover:bg-zinc-700';
  const selectContentBg = isLight ? 'bg-white border-gray-200' : 'bg-zinc-800 border-zinc-700';
  const selectItemClass = isLight ? 'text-gray-900 hover:bg-gray-100' : 'text-white hover:bg-zinc-700';
  const toggleInactive = isLight
    ? 'bg-gray-50 border-gray-200 text-gray-600 hover:border-cyan-400/50'
    : 'bg-zinc-800/50 border-zinc-700 text-zinc-300 hover:border-cyan-500/30';
  
  // Multi-file support for carousel posts
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [previewUrls, setPreviewUrls] = useState([]);
  const [currentPreviewIndex, setCurrentPreviewIndex] = useState(0);
  
  const [mediaType, setMediaType] = useState('image');
  const [caption, setCaption] = useState('');
  const [location, setLocation] = useState('');
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showCreateAdModal, setShowCreateAdModal] = useState(false);
  const [showCreateWaveModal, setShowCreateWaveModal] = useState(false);
  const [showVideoInfoModal, setShowVideoInfoModal] = useState(false);
  const [showGoLiveModal, setShowGoLiveModal] = useState(false);
  const [showWebcamModal, setShowWebcamModal] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const photoInputRef = useRef(null);
  const videoInputRef = useRef(null);
  const cameraInputRef = useRef(null);
  const cameraVideoInputRef = useRef(null);
  const captionRef = useRef(null);

  // Session metadata state
  const [showSessionData, setShowSessionData] = useState(false);
  const [sessionDate, setSessionDate] = useState(new Date().toISOString().split('T')[0]);
  const [sessionStartTime, setSessionStartTime] = useState('');
  const [sessionEndTime, setSessionEndTime] = useState('');
  const [waveHeightFt, setWaveHeightFt] = useState('');
  const [wavePeriodSec, setWavePeriodSec] = useState('');
  const [waveDirection, setWaveDirection] = useState('');
  const [waveDirectionDegrees, setWaveDirectionDegrees] = useState(null);
  const [windSpeedMph, setWindSpeedMph] = useState('');
  const [windDirection, setWindDirection] = useState('');
  const [tideStatus, setTideStatus] = useState('');
  const [tideHeightFt, setTideHeightFt] = useState('');
  const [conditionsLoading, setConditionsLoading] = useState(false);
  const [conditionsSource, setConditionsSource] = useState('manual');
  const [knownSpots, setKnownSpots] = useState([]);
  const [selectedSpot, setSelectedSpot] = useState('');
  const [recentLocations, setRecentLocations] = useState([]);
  const [showRecentLocations, setShowRecentLocations] = useState(false);

  // GPS + Location hierarchy state (mirrors Feed check-in flow)
  const [gpsLoading, setGpsLoading] = useState(false);
  const [userLat, setUserLat] = useState(null);
  const [userLon, setUserLon] = useState(null);
  const [nearestSpot, setNearestSpot] = useState(null);
  const [allSpots, setAllSpots] = useState([]);
  const [locationHierarchy, setLocationHierarchy] = useState({ countries: [] });
  const [selectedCountry, setSelectedCountry] = useState('');
  const [selectedState, setSelectedState] = useState('');
  const [selectedCity, setSelectedCity] = useState('');
  const [showLocationPicker, setShowLocationPicker] = useState(false);
  
  // Mention state
  const [mentions, setMentions] = useState([]);
  const [cursorPosition, setCursorPosition] = useState(0);
  const [showMentionAutocomplete, setShowMentionAutocomplete] = useState(false);
  const [mentionPosition, setMentionPosition] = useState({ top: 0, left: 0 });
  const mentionRef = useRef(null);
  
  // Hashtag autocomplete state
  const [showHashtagAutocomplete, setShowHashtagAutocomplete] = useState(false);
  const [hashtagQuery, setHashtagQuery] = useState('');
  const [hashtagIndex, setHashtagIndex] = useState(-1);
  const [hashtagEndIndex, setHashtagEndIndex] = useState(-1);
  const [hashtagPosition, setHashtagPosition] = useState({ top: 0, left: 0 });
  const hashtagRef = useRef(null);

  // Fetch known spots on mount
  useEffect(() => {
    const fetchSpots = async () => {
      try {
        const response = await apiClient.get(`/surf-conditions/known-spots`);
        setKnownSpots(response.data.spots || []);
      } catch (e) {
        // Silent fail
      }
    };
    fetchSpots();
  }, []);

  // Fetch user's recent locations
  useEffect(() => {
    const fetchRecentLocations = async () => {
      if (!user?.id) return;
      try {
        const response = await apiClient.get(`/posts/user/${user.id}/recent-locations`);
        setRecentLocations(response.data || []);
        if (response.data && response.data.length > 0) {
          setShowRecentLocations(true);
        }
      } catch (e) {
        // Silent fail
      }
    };
    if (user?.id) fetchRecentLocations();
  }, [user?.id]);

  // Fetch all spots + location hierarchy for GPS/manual location picker
  useEffect(() => {
    const fetchAllSpots = async () => {
      try {
        const response = await apiClient.get(`/surf-spots`);
        setAllSpots(response.data || []);
      } catch (e) { /* silent */ }
    };
    const fetchLocationHierarchy = async () => {
      try {
        const response = await apiClient.get(`/surf-spots/locations`);
        setLocationHierarchy(response.data || { countries: [] });
      } catch (e) { /* silent */ }
    };
    fetchAllSpots();
    fetchLocationHierarchy();
  }, []);

  // Calculate distance between two GPS points (km)
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
              Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
  };

  // Get GPS location and find nearest spots
  const getGpsLocation = () => {
    if (!navigator.geolocation) {
      toast.error('Geolocation is not supported by your browser');
      return;
    }
    setGpsLoading(true);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setUserLat(latitude);
        setUserLon(longitude);

        // Find nearest spot
        let nearest = null;
        let minDistance = Infinity;
        allSpots.forEach(spot => {
          if (!spot.latitude || !spot.longitude) return;
          const distance = calculateDistance(latitude, longitude, spot.latitude, spot.longitude);
          if (distance < minDistance) {
            minDistance = distance;
            nearest = { ...spot, distance: distance.toFixed(1) };
          }
        });

        setNearestSpot(nearest);
        if (nearest && minDistance < 10) {
          setLocation(nearest.name);
          toast.success(`📍 Near ${nearest.name} (${nearest.distance}km)`);
        } else if (nearest) {
          toast.success(`📍 Location found. Nearest: ${nearest.name} (${nearest.distance}km)`);
        } else {
          toast.success('📍 Location detected — select your spot below');
        }
        setGpsLoading(false);
      },
      (error) => {
        toast.error('Could not get your location. Please select manually.');
        setGpsLoading(false);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  // Handle spot selection from hierarchy picker
  const handleHierarchySpotSelect = (spotId) => {
    const spot = allSpots.find(s => s.id === spotId);
    if (spot) {
      setLocation(spot.name);
      if (spot.latitude && spot.longitude) {
        fetchConditions(spot.latitude, spot.longitude, spot.name);
      }
    }
  };

  const handleRecentLocationSelect = async (recentLoc) => {
    setLocation(recentLoc.location);
    setShowRecentLocations(false);
    if (recentLoc.latitude && recentLoc.longitude) {
      await fetchConditions(recentLoc.latitude, recentLoc.longitude, recentLoc.location);
    }
  };

  const handleSpotSelect = async (spotKey) => {
    setSelectedSpot(spotKey);
    const spot = knownSpots.find(s => s.key === spotKey);
    if (spot) {
      setLocation(spot.name);
      await fetchConditions(spot.lat, spot.lon, spot.name);
    }
  };

  const fetchConditions = async (lat, lon, spotName) => {
    setConditionsLoading(true);
    try {
      const response = await apiClient.get(`/surf-conditions`, {
        params: { latitude: lat, longitude: lon, spot_name: spotName }
      });
      
      if (response.data.wave_height_ft) setWaveHeightFt(response.data.wave_height_ft.toString());
      if (response.data.wave_period_sec) setWavePeriodSec(response.data.wave_period_sec.toString());
      if (response.data.wave_direction) setWaveDirection(response.data.wave_direction);
      if (response.data.wave_direction_degrees) setWaveDirectionDegrees(response.data.wave_direction_degrees);
      if (response.data.wind_speed_mph) setWindSpeedMph(response.data.wind_speed_mph.toString());
      if (response.data.wind_direction) setWindDirection(response.data.wind_direction);
      if (response.data.tide_status) setTideStatus(response.data.tide_status);
      if (response.data.tide_height_ft) setTideHeightFt(response.data.tide_height_ft.toString());
      setConditionsSource('auto');
      setShowSessionData(true);
      toast.success('Conditions auto-filled! Feel free to adjust.');
    } catch (e) {
      toast.error('Could not fetch conditions. Enter manually.');
    } finally {
      setConditionsLoading(false);
    }
  };

  const fetchConditionsByLocation = async () => {
    if (!navigator.geolocation) {
      toast.error('Geolocation not supported');
      return;
    }

    setConditionsLoading(true);
    try {
      const position = await new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: true,
          timeout: 10000
        });
      });

      await fetchConditions(position.coords.latitude, position.coords.longitude, location || 'Current Location');
    } catch (e) {
      toast.error('Could not get location. Select a spot instead.');
    } finally {
      setConditionsLoading(false);
    }
  };

  // Handle caption change and detect @ mentions and # hashtags
  const handleCaptionChange = (e) => {
    const newCaption = e.target.value;
    const newCursorPos = e.target.selectionStart;
    
    setCaption(newCaption);
    setCursorPosition(newCursorPos);
    
    const textBeforeCursor = newCaption.substring(0, newCursorPos);
    
    // Check for @ mentions
    const lastAtIndex = textBeforeCursor.lastIndexOf('@');
    if (lastAtIndex !== -1) {
      const charBefore = lastAtIndex > 0 ? newCaption[lastAtIndex - 1] : ' ';
      const textAfterAt = textBeforeCursor.substring(lastAtIndex + 1);
      
      // Show autocomplete if @ is after space/newline/start and no space after @
      if ((charBefore === ' ' || charBefore === '\n' || lastAtIndex === 0) && 
          !textAfterAt.includes(' ') && !textAfterAt.includes('\n')) {
        setShowMentionAutocomplete(true);
        setShowHashtagAutocomplete(false); // Close hashtag autocomplete
        
        // Position the dropdown below the textarea
        const textarea = captionRef.current;
        if (textarea) {
          setMentionPosition({
            top: 85,
            left: 0
          });
        }
        return;
      }
    }
    
    // Check for # hashtags
    const lastHashIndex = textBeforeCursor.lastIndexOf('#');
    if (lastHashIndex !== -1) {
      const charBefore = lastHashIndex > 0 ? newCaption[lastHashIndex - 1] : ' ';
      const textAfterHash = textBeforeCursor.substring(lastHashIndex + 1);
      
      // Show autocomplete if # is after space/newline/start and no space after #
      if ((charBefore === ' ' || charBefore === '\n' || lastHashIndex === 0) && 
          !textAfterHash.includes(' ') && !textAfterHash.includes('\n')) {
        setShowHashtagAutocomplete(true);
        setShowMentionAutocomplete(false); // Close mention autocomplete
        setHashtagQuery(textAfterHash);
        setHashtagIndex(lastHashIndex);
        setHashtagEndIndex(newCursorPos);
        
        // Position the dropdown below the textarea
        setHashtagPosition({
          top: 85,
          left: 0
        });
        return;
      }
    }
    
    // Close both autocompletes if no trigger found
    setShowMentionAutocomplete(false);
    setShowHashtagAutocomplete(false);
  };

  // Handle mention selection
  const handleMentionSelect = (mention, atIndex, endIndex) => {
    // Replace @query with @username
    const newCaption = caption.substring(0, atIndex) + 
                       `@${mention.username} ` + 
                       caption.substring(endIndex);
    
    setCaption(newCaption);
    
    // Add to mentions list (avoid duplicates)
    setMentions(prev => {
      const exists = prev.find(m => m.user_id === mention.user_id);
      if (exists) return prev;
      return [...prev, mention];
    });
    
    setShowMentionAutocomplete(false);
    
    // Focus back to textarea
    setTimeout(() => {
      if (captionRef.current) {
        const newCursorPos = atIndex + mention.username.length + 2; // +2 for @ and space
        captionRef.current.focus();
        captionRef.current.setSelectionRange(newCursorPos, newCursorPos);
        setCursorPosition(newCursorPos);
      }
    }, 0);
  };
  
  // Handle hashtag selection
  const handleHashtagSelect = (hashtag, hashIndex, endIndex) => {
    // Replace #query with #hashtag
    const tagToInsert = typeof hashtag === 'string' ? hashtag : hashtag.tag;
    const newCaption = caption.substring(0, hashIndex) + 
                       `#${tagToInsert} ` + 
                       caption.substring(endIndex);
    
    setCaption(newCaption);
    setShowHashtagAutocomplete(false);
    
    // Focus back to textarea
    setTimeout(() => {
      if (captionRef.current) {
        const newCursorPos = hashIndex + tagToInsert.length + 2; // +2 for # and space
        captionRef.current.focus();
        captionRef.current.setSelectionRange(newCursorPos, newCursorPos);
        setCursorPosition(newCursorPos);
      }
    }, 0);
  };

  // Handle keyboard events for mention and hashtag navigation
  const handleCaptionKeyDown = (e) => {
    // Handle mention autocomplete
    if (showMentionAutocomplete && mentionRef.current) {
      const handled = mentionRef.current.handleKeyDown(e);
      if (handled) return;
    }
    
    // Handle hashtag autocomplete
    if (showHashtagAutocomplete && hashtagRef.current) {
      const handled = hashtagRef.current.handleKeyDown(e);
      if (handled) return;
    }
    
    // If Enter is pressed with hashtag autocomplete open but no suggestions, insert the typed hashtag
    if (showHashtagAutocomplete && e.key === 'Enter' && hashtagQuery) {
      e.preventDefault();
      handleHashtagSelect(hashtagQuery, hashtagIndex, hashtagEndIndex);
    }
  };

  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    const firstFile = files[0];
    const isVideo = firstFile.type.startsWith('video/');
    const isImage = firstFile.type.startsWith('image/');

    if (!isVideo && !isImage) {
      toast.error('Please select image or video files');
      return;
    }

    // Video: only single file allowed
    if (isVideo) {
      const maxSize = 100 * 1024 * 1024;
      if (firstFile.size > maxSize) {
        toast.error('Video too large. Maximum size is 100MB');
        return;
      }
      previewUrls.forEach(url => URL.revokeObjectURL(url));
      setSelectedFiles([firstFile]);
      setPreviewUrls([URL.createObjectURL(firstFile)]);
      setMediaType('video');
      setCurrentPreviewIndex(0);
      return;
    }

    // Images: allow up to 10
    const imageFiles = files.filter(f => f.type.startsWith('image/'));
    const maxImages = 10;
    const totalImages = selectedFiles.length + imageFiles.length;
    
    if (totalImages > maxImages) {
      toast.error(`Maximum ${maxImages} photos allowed. You have ${selectedFiles.length}, can add ${maxImages - selectedFiles.length} more.`);
      return;
    }

    const maxSize = 50 * 1024 * 1024;
    const validFiles = [];
    const newPreviews = [];
    
    for (const file of imageFiles) {
      if (file.size > maxSize) {
        toast.error(`${file.name} is too large. Maximum size is 50MB`);
        continue;
      }
      validFiles.push(file);
      newPreviews.push(URL.createObjectURL(file));
    }

    if (validFiles.length > 0) {
      setSelectedFiles(prev => [...prev, ...validFiles]);
      setPreviewUrls(prev => [...prev, ...newPreviews]);
      setMediaType('image');
      setCurrentPreviewIndex(selectedFiles.length);
    }
  };
  
  const removeImage = (index) => {
    URL.revokeObjectURL(previewUrls[index]);
    setSelectedFiles(prev => prev.filter((_, i) => i !== index));
    setPreviewUrls(prev => prev.filter((_, i) => i !== index));
    if (currentPreviewIndex >= index && currentPreviewIndex > 0) {
      setCurrentPreviewIndex(prev => prev - 1);
    }
  };

  // Compress an image File to a base64 string (max 1200px, 85% quality)
  const compressImageToBase64 = (file) => new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new window.Image();
      img.src = e.target.result;
      img.onload = () => {
        const MAX = 1200;
        let w = img.width, h = img.height;
        if (w > MAX || h > MAX) {
          if (w > h) { h = Math.round(h * MAX / w); w = MAX; }
          else { w = Math.round(w * MAX / h); h = MAX; }
        }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.onerror = reject;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });

  const handleUpload = async () => {
    if (selectedFiles.length === 0) return;

    setLoading(true);
    setUploadProgress(0);

    try {
      const uploadedMedia = [];
      const isCarousel = selectedFiles.length > 1;
      
      for (let i = 0; i < selectedFiles.length; i++) {
        const file = selectedFiles[i];
        const isVideo = file.type.startsWith('video/');

        setProcessingStatus(
          isCarousel 
            ? `Processing photo ${i + 1} of ${selectedFiles.length}...` 
            : (isVideo ? 'Uploading & processing video...' : 'Processing...')
        );

        if (isVideo) {
          // Videos still go through server upload for transcoding
          const formData = new FormData();
          formData.append('file', file);
          formData.append('user_id', user.id);
          const uploadResponse = await apiClient.post(`/upload/feed`, formData, {
            headers: { 'Content-Type': 'multipart/form-data' },
            onUploadProgress: (progressEvent) => {
              const fileProgress = Math.round((progressEvent.loaded * 100) / progressEvent.total);
              const overallProgress = Math.round(((i + fileProgress / 100) / selectedFiles.length) * 100);
              setUploadProgress(overallProgress);
            }
          });
          uploadedMedia.push({
            url: uploadResponse.data.media_url,
            type: uploadResponse.data.media_type,
            thumbnail_url: uploadResponse.data.thumbnail_url,
            width: uploadResponse.data.final_width,
            height: uploadResponse.data.final_height
          });
        } else {
          // Images: compress and store as base64 directly in DB (no ephemeral disk)
          const base64 = await compressImageToBase64(file);
          setUploadProgress(Math.round(((i + 1) / selectedFiles.length) * 100));
          uploadedMedia.push({
            url: base64,
            type: 'image',
            thumbnail_url: null,
            width: null,
            height: null
          });
        }
      }

      setProcessingStatus('Creating post...');

      const postData = {
        media_url: uploadedMedia[0].url,
        media_type: uploadedMedia[0].type,
        thumbnail_url: uploadedMedia[0].thumbnail_url || null,
        caption: caption || null,
        location: location || null,
        video_width: uploadedMedia[0].width || null,
        video_height: uploadedMedia[0].height || null,
        is_carousel: isCarousel,
        carousel_media: isCarousel ? uploadedMedia : []
      };
      
      // Store mentions separately for notification purposes (not on Post model)
      const _mentionsToNotify = mentions.length > 0 ? mentions.map(m => ({
        user_id: m.user_id,
        username: m.username,
        full_name: m.full_name
      })) : [];

      // Add session metadata if enabled
      if (showSessionData) {
        if (sessionDate) postData.session_date = new Date(sessionDate).toISOString();
        if (sessionStartTime) postData.session_start_time = sessionStartTime;
        if (sessionEndTime) postData.session_end_time = sessionEndTime;
        if (waveHeightFt) postData.wave_height_ft = parseFloat(waveHeightFt);
        if (wavePeriodSec) postData.wave_period_sec = parseInt(wavePeriodSec);
        if (waveDirection) postData.wave_direction = waveDirection;
        if (waveDirectionDegrees) postData.wave_direction_degrees = waveDirectionDegrees;
        if (windSpeedMph) postData.wind_speed_mph = parseFloat(windSpeedMph);
        if (windDirection) postData.wind_direction = windDirection;
        if (tideStatus) postData.tide_status = tideStatus;
        if (tideHeightFt) postData.tide_height_ft = parseFloat(tideHeightFt);
        postData.conditions_source = conditionsSource;
      }

      await apiClient.post(`/posts?author_id=${user.id}`, postData);

      if (isCarousel) {
        toast.success(`Posted ${selectedFiles.length} photos!`);
      } else {
        toast.success('Post created successfully!');
      }
      
      navigate('/feed');
    } catch (error) {
      logger.error('Upload error:', error);
      toast.error(error.response?.data?.detail || 'Failed to create post');
    } finally {
      setLoading(false);
      setUploadProgress(0);
      setProcessingStatus('');
    }
  };

  const clearSelection = () => {
    previewUrls.forEach(url => URL.revokeObjectURL(url));
    setSelectedFiles([]);
    setPreviewUrls([]);
    setCurrentPreviewIndex(0);
    setMediaType('image');
  };

  return (
    <div className="pb-20 bg-background min-h-screen" data-testid="create-post-page">
      <div className="max-w-lg mx-auto p-4">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold text-foreground" style={{ fontFamily: 'Oswald' }}>
            Create Post
          </h1>
          {selectedFiles.length > 0 && (
            <Button
              onClick={handleUpload}
              disabled={loading}
              className="bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black font-bold"
              data-testid="share-post-btn"
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Share'}
            </Button>
          )}
        </div>

        {/* Hidden File Inputs */}
        <input
          ref={photoInputRef}
          type="file"
          accept="image/*,image/jpeg,image/png,image/heic,image/webp"
          multiple
          onChange={handleFileSelect}
          className="hidden"
        />
        <input
          ref={videoInputRef}
          type="file"
          accept="video/*,video/mp4,video/quicktime,video/webm,video/mov"
          onChange={handleFileSelect}
          className="hidden"
        />
        <input
          ref={cameraInputRef}
          type="file"
          accept="image/*"
          capture="environment"
          onChange={handleFileSelect}
          className="hidden"
        />
        <input
          ref={cameraVideoInputRef}
          type="file"
          accept="video/*"
          capture="environment"
          onChange={handleFileSelect}
          className="hidden"
        />

        {selectedFiles.length === 0 ? (
          <div className="space-y-4">
            {/* Upload Area */}
            <div className="w-full rounded-2xl border-2 border-dashed border-border p-6 bg-muted/50">
              <p className="text-foreground font-medium text-lg text-center mb-2">Select media to post</p>
              <p className="text-muted-foreground text-sm text-center mb-6">Up to 10 photos or 1 video</p>
              
              <div className="flex justify-center gap-4 mb-4">
                {/* Photo Button */}
                <button
                  onClick={() => photoInputRef.current?.click()}
                  className="flex flex-col items-center gap-3 p-5 rounded-2xl bg-muted hover:bg-accent border-2 border-transparent hover:border-blue-500 transition-all active:scale-95"
                  data-testid="photo-select-btn"
                >
                  <div className="w-16 h-16 rounded-full bg-blue-500/20 flex items-center justify-center">
                    <Image className="w-8 h-8 text-blue-400" />
                  </div>
                  <span className="text-foreground font-medium">Photo</span>
                  <span className="text-xs text-muted-foreground">JPG, PNG, HEIC</span>
                </button>

                {/* Video Button */}
                <button
                  onClick={() => videoInputRef.current?.click()}
                  className="flex flex-col items-center gap-3 p-5 rounded-2xl bg-muted hover:bg-accent border-2 border-transparent hover:border-purple-500 transition-all active:scale-95"
                  data-testid="video-select-btn"
                >
                  <div className="w-16 h-16 rounded-full bg-purple-500/20 flex items-center justify-center">
                    <Video className="w-8 h-8 text-purple-400" />
                  </div>
                  <span className="text-foreground font-medium">Video</span>
                  <span className="text-xs text-muted-foreground">MP4, MOV</span>
                </button>
                
                {/* Wave (Short Video) Button */}
                <button
                  onClick={() => setShowCreateWaveModal(true)}
                  className="flex flex-col items-center gap-3 p-5 rounded-2xl bg-muted hover:bg-accent border-2 border-transparent hover:border-cyan-500 transition-all active:scale-95"
                  data-testid="wave-select-btn"
                >
                  <div className="w-16 h-16 rounded-full bg-gradient-to-br from-cyan-500/20 to-blue-500/20 flex items-center justify-center">
                    <Play className="w-8 h-8 text-cyan-400" />
                  </div>
                  <span className="text-foreground font-medium">Wave</span>
                  <span className="text-xs text-muted-foreground">60s max</span>
                </button>
              </div>

              <p className="text-muted-foreground text-sm text-center">
                Videos auto-optimized to 1080p
              </p>
              
              {/* Help Link - Video vs Wave */}
              <button
                onClick={() => setShowVideoInfoModal(true)}
                className="flex items-center justify-center gap-2 text-sm text-cyan-400 hover:text-cyan-300 mx-auto mt-2"
              >
                <HelpCircle className="w-4 h-4" />
                What's the difference between Video and Wave?
              </button>
            </div>

            {/* Camera shortcut */}
            <Button
              onClick={() => setShowWebcamModal(true)}
              variant="outline"
              className="w-full h-12 border-border text-foreground hover:bg-muted font-medium"
            >
              <Camera className="w-5 h-5 mr-3 text-cyan-500 font-bold" />
              Capture Photo or Video
            </Button>

            {/* Go Live Option */}
            <Button
              onClick={() => setShowGoLiveModal(true)}
              className="w-full h-12 bg-red-500 hover:bg-red-600 text-white border-0 font-bold"
            >
              <Radio className="w-5 h-5 mr-3 animate-pulse" />
              Go Live
            </Button>

            {/* Create Ad Option */}
            <Button
              onClick={() => setShowCreateAdModal(true)}
              variant="outline"
              className="w-full h-12 border-purple-500/50 text-purple-500 dark:text-purple-400 hover:bg-purple-500/10 hover:border-purple-500"
              data-testid="create-ad-btn"
            >
              <Megaphone className="w-5 h-5 mr-2" />
              Create Ad
            </Button>
          </div>
        ) : (
          <div className="space-y-4 max-h-[calc(100vh-200px)] overflow-y-auto pr-1">
            {/* Preview with Carousel Controls */}
            <div className={`relative rounded-xl overflow-hidden ${isLight ? 'bg-gray-100' : 'bg-zinc-900'}`}>
              {mediaType === 'video' ? (
                <video
                  src={previewUrls[0]}
                  controls
                  className="w-full aspect-square object-cover"
                  playsInline
                />
              ) : (
                <div className="relative">
                  <img
                    src={previewUrls[currentPreviewIndex]}
                    alt={`Preview ${currentPreviewIndex + 1}`}
                    className="w-full aspect-square object-cover"
                  />
                  {/* Carousel Navigation */}
                  {previewUrls.length > 1 && (
                    <>
                      {currentPreviewIndex > 0 && (
                        <button
                          onClick={() => setCurrentPreviewIndex(prev => prev - 1)}
                          className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-black/70 rounded-full flex items-center justify-center hover:bg-black"
                        >
                          <ChevronLeft className="w-5 h-5 text-white" />
                        </button>
                      )}
                      {currentPreviewIndex < previewUrls.length - 1 && (
                        <button
                          onClick={() => setCurrentPreviewIndex(prev => prev + 1)}
                          className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-black/70 rounded-full flex items-center justify-center hover:bg-black"
                        >
                          <ChevronRight className="w-5 h-5 text-white" />
                        </button>
                      )}
                      {/* Dot indicators */}
                      <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-1.5">
                        {previewUrls.map((_, i) => (
                          <button
                            key={i}
                            onClick={() => setCurrentPreviewIndex(i)}
                            className={`w-2 h-2 rounded-full transition-all ${
                              i === currentPreviewIndex ? 'bg-white w-4' : 'bg-white/50'
                            }`}
                          />
                        ))}
                      </div>
                    </>
                  )}
                </div>
              )}
              <button
                onClick={clearSelection}
                className="absolute top-3 right-3 p-2 bg-black/70 rounded-full hover:bg-black"
              >
                <X className="w-5 h-5 text-white" />
              </button>
              {/* Photo count badge */}
              {previewUrls.length > 1 && (
                <div className="absolute top-3 left-3 bg-black/70 px-2 py-1 rounded text-xs text-white">
                  {currentPreviewIndex + 1} / {previewUrls.length}
                </div>
              )}
            </div>

            {/* Thumbnail Strip for Multiple Images */}
            {mediaType === 'image' && previewUrls.length > 0 && (
              <div className="flex gap-2 overflow-x-auto pb-2">
                {previewUrls.map((url, i) => (
                  <div key={i} className="relative flex-shrink-0">
                    <img
                      src={url}
                      alt={`Thumb ${i + 1}`}
                      onClick={() => setCurrentPreviewIndex(i)}
                      className={`w-16 h-16 rounded-lg object-cover cursor-pointer border-2 transition-all ${
                        i === currentPreviewIndex ? 'border-yellow-400' : 'border-transparent hover:border-zinc-500'
                      }`}
                    />
                    <button
                      onClick={(e) => { e.stopPropagation(); removeImage(i); }}
                      className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 rounded-full flex items-center justify-center hover:bg-red-600"
                    >
                      <X className="w-3 h-3 text-white" />
                    </button>
                  </div>
                ))}
                {/* Add More Button */}
                {previewUrls.length < 10 && (
                  <button
                    onClick={() => photoInputRef.current?.click()}
                    className={`w-16 h-16 rounded-lg border-2 border-dashed ${isLight ? 'border-gray-300 hover:border-gray-500' : 'border-zinc-600 hover:border-zinc-400'} flex items-center justify-center flex-shrink-0`}
                  >
                    <span className={`text-2xl ${isLight ? 'text-gray-400' : 'text-zinc-500'}`}>+</span>
                  </button>
                )}
              </div>
            )}

            {/* Caption with Emoji and @Mentions */}
            <div className="relative">
              <Textarea
                ref={captionRef}
                value={caption}
                onChange={handleCaptionChange}
                onKeyDown={handleCaptionKeyDown}
                onSelect={(e) => setCursorPosition(e.target.selectionStart)}
                placeholder="Write a caption... Use @ to mention someone"
                className={`${bgInput} ${borderInput} ${textInput} min-h-[80px] resize-none pr-20`}
                data-testid="caption-input"
              />
              <div className="absolute right-3 top-3 flex items-center gap-1">
                <button
                  type="button"
                  onClick={() => {
                    const textarea = captionRef.current;
                    if (textarea) {
                      const pos = textarea.selectionStart || caption.length;
                      const newCaption = caption.slice(0, pos) + '@' + caption.slice(pos);
                      setCaption(newCaption);
                      setCursorPosition(pos + 1);
                      setShowMentionAutocomplete(true);
                      setTimeout(() => {
                        textarea.focus();
                        textarea.setSelectionRange(pos + 1, pos + 1);
                      }, 0);
                    }
                  }}
                  className={`p-2 rounded-full ${hoverBg} ${labelClass} hover:text-cyan-400 transition-colors`}
                  title="Mention someone"
                >
                  <AtSign className="w-4 h-4" />
                </button>
                <button
                  type="button"
                  onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                  className={`p-2 rounded-full transition-colors ${
                    showEmojiPicker ? 'bg-yellow-500/20 text-yellow-400' : `${hoverBg} ${labelClass} hover:text-white`
                  }`}
                >
                  <Smile className="w-5 h-5" />
                </button>
              </div>
              
              {/* Mention Autocomplete */}
              <MentionAutocomplete
                ref={mentionRef}
                text={caption}
                cursorPosition={cursorPosition}
                onSelect={handleMentionSelect}
                isVisible={showMentionAutocomplete}
                onClose={() => setShowMentionAutocomplete(false)}
                position={mentionPosition}
              />
              
              {/* Hashtag Autocomplete */}
              {showHashtagAutocomplete && (
                <HashtagAutocomplete
                  ref={hashtagRef}
                  query={hashtagQuery}
                  onSelect={handleHashtagSelect}
                  hashIndex={hashtagIndex}
                  endIndex={hashtagEndIndex}
                  position={hashtagPosition}
                  onClose={() => setShowHashtagAutocomplete(false)}
                />
              )}
              
              <EmojiPicker
                isOpen={showEmojiPicker}
                onClose={() => setShowEmojiPicker(false)}
                onSelect={(emoji) => {
                  const textarea = captionRef.current;
                  if (textarea) {
                    const start = textarea.selectionStart || caption.length;
                    const end = textarea.selectionEnd || caption.length;
                    const newCaption = caption.slice(0, start) + emoji + caption.slice(end);
                    setCaption(newCaption);
                    setTimeout(() => {
                      textarea.focus();
                      textarea.setSelectionRange(start + emoji.length, start + emoji.length);
                    }, 0);
                  } else {
                    setCaption(caption + emoji);
                  }
                }}
                position="below"
              />
              
              {/* Mentions preview */}
              {mentions.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1">
                  {mentions.map((m, idx) => (
                    <span 
                      key={m.user_id || idx}
                      className="px-2 py-0.5 bg-cyan-500/20 text-cyan-400 rounded-full text-xs flex items-center gap-1"
                    >
                      @{m.username}
                      <button
                        type="button"
                        onClick={() => setMentions(prev => prev.filter(x => x.user_id !== m.user_id))}
                        className="hover:text-red-400"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </span>
                  ))}
                </div>
              )}
            </div>

            {/* Location Picker */}
            <div className={`rounded-xl border ${cardBorder} overflow-hidden`}>
              {/* Location header / selected value */}
              <button
                type="button"
                onClick={() => setShowLocationPicker(!showLocationPicker)}
                className={`w-full flex items-center justify-between p-3 ${cardBg} transition-all`}
              >
                <div className="flex items-center gap-2">
                  <MapPin className={`w-5 h-5 ${location ? 'text-cyan-500' : labelClass}`} />
                  <span className={location ? 'text-foreground font-medium' : labelClass}>
                    {location || 'Add a location'}
                  </span>
                  {nearestSpot && userLat && (
                    <span className="text-xs text-cyan-500 bg-cyan-500/10 px-2 py-0.5 rounded-full">
                      📍 {nearestSpot.distance}km
                    </span>
                  )}
                </div>
                <ChevronDown className={`w-4 h-4 ${labelClass} transition-transform ${showLocationPicker ? 'rotate-180' : ''}`} />
              </button>

              {/* Expanded location picker */}
              {showLocationPicker && (
                <div className={`p-3 space-y-3 border-t ${cardBorder}`}>
                  {/* GPS Button */}
                  <Button
                    type="button"
                    onClick={getGpsLocation}
                    disabled={gpsLoading}
                    variant="outline"
                    className={`w-full border-cyan-500/50 text-cyan-500 hover:bg-cyan-500/10 ${isLight ? 'hover:text-cyan-600' : ''}`}
                  >
                    {gpsLoading ? (
                      <Loader2 className="w-4 h-4 animate-spin mr-2" />
                    ) : (
                      <Navigation className="w-4 h-4 mr-2" />
                    )}
                    {gpsLoading ? 'Finding location...' : 'Use My GPS Location'}
                  </Button>

                  {/* Nearest spot result */}
                  {nearestSpot && userLat && (
                    <div className={`p-3 rounded-lg ${isLight ? 'bg-cyan-50 border border-cyan-200' : 'bg-cyan-500/10 border border-cyan-500/20'}`}>
                      <p className={`text-xs ${labelClass} mb-1`}>Nearest spot detected</p>
                      <button
                        type="button"
                        onClick={() => {
                          setLocation(nearestSpot.name);
                          if (nearestSpot.latitude && nearestSpot.longitude) {
                            fetchConditions(nearestSpot.latitude, nearestSpot.longitude, nearestSpot.name);
                          }
                          setShowLocationPicker(false);
                        }}
                        className={`flex items-center gap-2 w-full text-left p-2 rounded-lg ${isLight ? 'hover:bg-cyan-100' : 'hover:bg-cyan-500/20'} transition-colors`}
                      >
                        <MapPin className="w-4 h-4 text-cyan-500 flex-shrink-0" />
                        <div>
                          <p className="text-foreground font-medium text-sm">{nearestSpot.name}</p>
                          <p className="text-xs text-cyan-500">{nearestSpot.distance}km away</p>
                        </div>
                      </button>
                    </div>
                  )}

                  {/* Divider */}
                  <div className="flex items-center gap-3">
                    <div className={`flex-1 h-px ${isLight ? 'bg-gray-200' : 'bg-zinc-700'}`} />
                    <span className={`text-xs ${labelClass}`}>or select manually</span>
                    <div className={`flex-1 h-px ${isLight ? 'bg-gray-200' : 'bg-zinc-700'}`} />
                  </div>

                  {/* Hierarchical Pickers: Country → State → City → Spot */}
                  <div className="space-y-2">
                    {/* Country */}
                    <Select value={selectedCountry} onValueChange={(val) => { setSelectedCountry(val); setSelectedState(''); setSelectedCity(''); }}>
                      <SelectTrigger className={`${bgInput} ${borderInput} ${textInput} text-sm`}>
                        <SelectValue placeholder="Country" />
                      </SelectTrigger>
                      <SelectContent className={selectContentBg}>
                        {(locationHierarchy.countries || []).map(c => (
                          <SelectItem key={c.name} value={c.name} className={selectItemClass}>{c.name}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>

                    {/* State / Region */}
                    {selectedCountry && (() => {
                      const country = (locationHierarchy.countries || []).find(c => c.name === selectedCountry);
                      const states = country?.states || [];
                      if (states.length === 0) return null;
                      return (
                        <Select value={selectedState} onValueChange={(val) => { setSelectedState(val); setSelectedCity(''); }}>
                          <SelectTrigger className={`${bgInput} ${borderInput} ${textInput} text-sm`}>
                            <SelectValue placeholder="State / Region" />
                          </SelectTrigger>
                          <SelectContent className={selectContentBg}>
                            {states.map(s => (
                              <SelectItem key={s.name} value={s.name} className={selectItemClass}>{s.name}</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      );
                    })()}

                    {/* City / Area */}
                    {selectedState && (() => {
                      const country = (locationHierarchy.countries || []).find(c => c.name === selectedCountry);
                      const state = (country?.states || []).find(s => s.name === selectedState);
                      const cities = state?.cities || [];
                      if (cities.length === 0) return null;
                      return (
                        <Select value={selectedCity} onValueChange={setSelectedCity}>
                          <SelectTrigger className={`${bgInput} ${borderInput} ${textInput} text-sm`}>
                            <SelectValue placeholder="City / Area" />
                          </SelectTrigger>
                          <SelectContent className={selectContentBg}>
                            {cities.map(c => (
                              <SelectItem key={c.name} value={c.name} className={selectItemClass}>{c.name}</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      );
                    })()}

                    {/* Spots in selected city */}
                    {selectedCity && (() => {
                      const country = (locationHierarchy.countries || []).find(c => c.name === selectedCountry);
                      const state = (country?.states || []).find(s => s.name === selectedState);
                      const city = (state?.cities || []).find(c => c.name === selectedCity);
                      const citySpots = city?.spots || [];
                      if (citySpots.length === 0) {
                        // No spots? Set city as location
                        return (
                          <Button
                            type="button"
                            variant="outline"
                            className="w-full border-cyan-500/50 text-cyan-500"
                            onClick={() => {
                              setLocation(`${selectedCity}, ${selectedState}`);
                              setShowLocationPicker(false);
                            }}
                          >
                            <MapPin className="w-4 h-4 mr-2" />
                            Use "{selectedCity}, {selectedState}"
                          </Button>
                        );
                      }
                      return (
                        <div className={`rounded-lg ${cardBg} p-2 space-y-1`}>
                          <p className={`text-xs ${labelClass} px-2 py-1`}>Surf spots in {selectedCity}</p>
                          {citySpots.map(spot => (
                            <button
                              key={spot.id || spot.name}
                              type="button"
                              onClick={() => {
                                setLocation(spot.name);
                                handleHierarchySpotSelect(spot.id);
                                setShowLocationPicker(false);
                              }}
                              className={`w-full text-left px-3 py-2 rounded-lg text-sm text-foreground ${hoverBg} transition-colors flex items-center gap-2`}
                            >
                              <MapPin className="w-3.5 h-3.5 text-cyan-500 flex-shrink-0" />
                              <span>{spot.name}</span>
                              {userLat && spot.latitude && (
                                <span className="ml-auto text-xs text-cyan-500">
                                  {calculateDistance(userLat, userLon, spot.latitude, spot.longitude).toFixed(1)}km
                                </span>
                              )}
                            </button>
                          ))}
                        </div>
                      );
                    })()}
                  </div>

                  {/* Recent Locations */}
                  {recentLocations.length > 0 && (
                    <div>
                      <p className={`text-xs ${labelClass} mb-2`}>Recent locations</p>
                      <div className="flex flex-wrap gap-2">
                        {recentLocations.slice(0, 5).map((loc, i) => (
                          <button
                            key={i}
                            type="button"
                            onClick={() => {
                              handleRecentLocationSelect(loc);
                              setShowLocationPicker(false);
                            }}
                            className={`px-3 py-1.5 ${pillBg} rounded-full text-sm flex items-center gap-1`}
                          >
                            <MapPin className="w-3 h-3" />
                            {loc.location}
                          </button>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Quick Select Dropdown — populated from city spots or knownSpots */}
                  {(() => {
                    // If a city is selected, show spots from that city directly
                    if (selectedCity && selectedCountry && selectedState) {
                      const country = (locationHierarchy.countries || []).find(c => c.name === selectedCountry);
                      const state = (country?.states || []).find(s => s.name === selectedState);
                      const city = (state?.cities || []).find(c => c.name === selectedCity);
                      const citySpots = city?.spots || [];
                      
                      if (citySpots.length > 0) {
                        return (
                          <div>
                            <p className={`text-xs ${labelClass} mb-1`}>
                              Surf spots in {selectedCity}
                            </p>
                            <Select 
                              value="" 
                              onValueChange={(spotName) => {
                                // Find this spot in allSpots for lat/lon to fetch conditions
                                const fullSpot = allSpots.find(s => s.name === spotName);
                                setLocation(spotName);
                                if (fullSpot?.latitude && fullSpot?.longitude) {
                                  fetchConditions(fullSpot.latitude, fullSpot.longitude, spotName);
                                }
                                setShowLocationPicker(false);
                              }}
                            >
                              <SelectTrigger className={`${bgInput} ${borderInput} ${textInput} text-sm`}>
                                <SelectValue placeholder={`Select from ${citySpots.length} spots...`} />
                              </SelectTrigger>
                              <SelectContent className={selectContentBg}>
                                {citySpots.map(spot => (
                                  <SelectItem key={spot.id || spot.name} value={spot.name} className={selectItemClass}>
                                    {spot.name}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </div>
                        );
                      }
                    }
                    
                    // Fallback: show all knownSpots (conditions-enabled)
                    if (knownSpots.length === 0) return null;
                    return (
                      <div>
                        <p className={`text-xs ${labelClass} mb-1`}>Quick select (auto-fills conditions)</p>
                        <Select value={selectedSpot} onValueChange={handleSpotSelect}>
                          <SelectTrigger className={`${bgInput} ${borderInput} ${textInput} text-sm`}>
                            <SelectValue placeholder="Select a surf spot..." />
                          </SelectTrigger>
                          <SelectContent className={selectContentBg}>
                            {knownSpots.map(spot => (
                              <SelectItem key={spot.key} value={spot.key} className={selectItemClass}>
                                {spot.name}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    );
                  })()}

                  {/* Manual input fallback */}
                  <div className="relative">
                    <Input
                      value={location}
                      onChange={(e) => setLocation(e.target.value)}
                      placeholder="Or type a location..."
                      className={`${bgInput} ${borderInput} ${textInput} text-sm`}
                      data-testid="location-input"
                    />
                  </div>
                </div>
              )}
            </div>

            {/* Session Conditions Toggle */}
            <button
              onClick={() => setShowSessionData(!showSessionData)}
              className={`w-full flex items-center justify-between p-3 rounded-lg border transition-all ${
                showSessionData 
                  ? 'bg-cyan-500/10 border-cyan-500/50 text-cyan-400' 
                  : toggleInactive
              }`}
            >
              <div className="flex items-center gap-2">
                <Waves className="w-5 h-5" />
                <span className="font-medium">Add Session Conditions</span>
              </div>
              <ChevronDown className={`w-5 h-5 transition-transform ${showSessionData ? 'rotate-180' : ''}`} />
            </button>

            {/* Session Data Fields */}
            {showSessionData && (
              <div className={`space-y-4 p-4 ${cardBg} rounded-lg border ${cardBorder}`}>
                {/* Auto-fetch Button */}
                <Button
                  onClick={fetchConditionsByLocation}
                  disabled={conditionsLoading}
                  variant="outline"
                  className="w-full border-cyan-500/50 text-cyan-400 hover:bg-cyan-500/10"
                >
                  {conditionsLoading ? (
                    <Loader2 className="w-4 h-4 animate-spin mr-2" />
                  ) : (
                    <Navigation className="w-4 h-4 mr-2" />
                  )}
                  Auto-fill from Current Location
                </Button>

                {/* Session Time */}
                <div className="grid grid-cols-3 gap-3">
                  <div>
                    <label className={`text-xs ${labelClass} block mb-1`}>Date</label>
                    <Input
                      type="date"
                      value={sessionDate}
                      onChange={(e) => setSessionDate(e.target.value)}
                      className={`${bgInput} ${borderInput} ${textInput} text-sm`}
                    />
                  </div>
                  <div>
                    <label className={`text-xs ${labelClass} block mb-1`}>Start</label>
                    <Input
                      type="time"
                      value={sessionStartTime}
                      onChange={(e) => setSessionStartTime(e.target.value)}
                      className={`${bgInput} ${borderInput} ${textInput} text-sm`}
                    />
                  </div>
                  <div>
                    <label className={`text-xs ${labelClass} block mb-1`}>End</label>
                    <Input
                      type="time"
                      value={sessionEndTime}
                      onChange={(e) => setSessionEndTime(e.target.value)}
                      className={`${bgInput} ${borderInput} ${textInput} text-sm`}
                    />
                  </div>
                </div>

                {/* Wave Conditions */}
                <div className="space-y-2">
                  <div className="flex items-center gap-2 text-cyan-400">
                    <Waves className="w-4 h-4" />
                    <span className="text-sm font-medium">Wave Conditions</span>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    <div>
                      <label className={`text-xs ${labelClass} block mb-1`}>Height (ft)</label>
                      <Input
                        type="number"
                        step="0.5"
                        value={waveHeightFt}
                        onChange={(e) => setWaveHeightFt(e.target.value)}
                        placeholder="3.5"
                        className={`${bgInput} ${borderInput} ${textInput} text-sm`}
                      />
                    </div>
                    <div>
                      <label className={`text-xs ${labelClass} block mb-1`}>Period (sec)</label>
                      <Input
                        type="number"
                        value={wavePeriodSec}
                        onChange={(e) => setWavePeriodSec(e.target.value)}
                        placeholder="12"
                        className={`${bgInput} ${borderInput} ${textInput} text-sm`}
                      />
                    </div>
                    <div>
                      <label className={`text-xs ${labelClass} block mb-1`}>Direction</label>
                      <Select value={waveDirection} onValueChange={setWaveDirection}>
                        <SelectTrigger className={`${bgInput} ${borderInput} ${textInput} text-sm h-9`}>
                          <SelectValue placeholder="Dir" />
                        </SelectTrigger>
                        <SelectContent className={selectContentBg}>
                          {['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'].map(dir => (
                            <SelectItem key={dir} value={dir} className={textInput}>{dir}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                </div>

                {/* Wind Conditions */}
                <div className="space-y-2">
                  <div className="flex items-center gap-2 text-emerald-400">
                    <Wind className="w-4 h-4" />
                    <span className="text-sm font-medium">Wind</span>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className={`text-xs ${labelClass} block mb-1`}>Speed (mph)</label>
                      <Input
                        type="number"
                        value={windSpeedMph}
                        onChange={(e) => setWindSpeedMph(e.target.value)}
                        placeholder="8"
                        className={`${bgInput} ${borderInput} ${textInput} text-sm`}
                      />
                    </div>
                    <div>
                      <label className={`text-xs ${labelClass} block mb-1`}>Direction</label>
                      <Select value={windDirection} onValueChange={setWindDirection}>
                        <SelectTrigger className={`${bgInput} ${borderInput} ${textInput} text-sm h-9`}>
                          <SelectValue placeholder="Direction" />
                        </SelectTrigger>
                        <SelectContent className={selectContentBg}>
                          {['Offshore', 'Onshore', 'Cross-shore', 'N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'].map(dir => (
                            <SelectItem key={dir} value={dir} className={textInput}>{dir}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                </div>

                {/* Tide Conditions */}
                <div className="space-y-2">
                  <div className="flex items-center gap-2 text-blue-400">
                    <ArrowUpDown className="w-4 h-4" />
                    <span className="text-sm font-medium">Tide</span>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className={`text-xs ${labelClass} block mb-1`}>Status</label>
                      <Select value={tideStatus} onValueChange={setTideStatus}>
                        <SelectTrigger className={`${bgInput} ${borderInput} ${textInput} text-sm h-9`}>
                          <SelectValue placeholder="Status" />
                        </SelectTrigger>
                        <SelectContent className={selectContentBg}>
                          {['High', 'Low', 'Rising', 'Falling', 'Mid'].map(status => (
                            <SelectItem key={status} value={status} className={textInput}>{status}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div>
                      <label className={`text-xs ${labelClass} block mb-1`}>Height (ft)</label>
                      <Input
                        type="number"
                        step="0.1"
                        value={tideHeightFt}
                        onChange={(e) => setTideHeightFt(e.target.value)}
                        placeholder="2.5"
                        className={`${bgInput} ${borderInput} ${textInput} text-sm`}
                      />
                    </div>
                  </div>
                </div>

                {conditionsSource === 'auto' && (
                  <div className="flex items-center gap-2 text-xs text-emerald-400">
                    <Check className="w-3 h-3" />
                    <span>Conditions auto-filled from weather data</span>
                  </div>
                )}
              </div>
            )}

            {/* Progress */}
            {loading && (
              <div className="space-y-2">
                <div className={`h-2 ${isLight ? 'bg-gray-200' : 'bg-zinc-800'} rounded-full overflow-hidden`}>
                  <div
                    className="h-full bg-gradient-to-r from-yellow-400 to-orange-400 transition-all"
                    style={{ width: `${uploadProgress}%` }}
                  />
                </div>
                <p className={`text-xs ${labelClass} text-center`}>{processingStatus}</p>
              </div>
            )}

            {/* Submit Button */}
            <Button
              onClick={handleUpload}
              disabled={loading}
              className="w-full h-14 bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black font-bold text-lg"
              data-testid="post-submit-btn"
            >
              {loading ? (
                <Loader2 className="w-6 h-6 animate-spin" />
              ) : (
                <>
                  <Upload className="w-5 h-5 mr-2" />
                  Share Post
                </>
              )}
            </Button>
          </div>
        )}
      </div>

      {/* Create Ad Modal */}
      <CreateAdModal
        isOpen={showCreateAdModal}
        onClose={() => setShowCreateAdModal(false)}
        onSuccess={() => {
          setShowCreateAdModal(false);
          navigate('/wallet');
        }}
      />
      
      {/* Create Wave Modal */}
      <CreateWaveModal
        isOpen={showCreateWaveModal}
        onClose={() => setShowCreateWaveModal(false)}
        onSuccess={() => {
          setShowCreateWaveModal(false);
          navigate('/feed?tab=waves');
          toast.success('Wave posted!');
        }}
      />
      
      {/* Video vs Wave Info Modal */}
      <Dialog open={showVideoInfoModal} onOpenChange={setShowVideoInfoModal}>
        <DialogContent className="bg-background border-border text-foreground max-w-md w-[95vw] sm:w-full p-0 overflow-hidden sm:border sm:rounded-xl shadow-2xl flex flex-col max-h-[75vh] my-auto">
          <div className="overflow-y-auto w-full p-6 pb-12 custom-scrollbar">
            <DialogHeader className="mb-4">
              <DialogTitle className="flex items-center gap-2 text-xl font-bold text-foreground">
                <HelpCircle className="w-6 h-6 text-cyan-500" />
                Video vs Wave
              </DialogTitle>
            </DialogHeader>
            
            <div className="space-y-5">
              {/* Wave Section */}
              <div className="p-5 rounded-xl bg-gradient-to-br from-cyan-500/10 to-blue-500/10 border border-cyan-500/20 shadow-sm relative overflow-hidden">
                <div className="absolute -right-4 -top-4 w-24 h-24 bg-cyan-500/10 rounded-full blur-xl pointer-events-none"></div>
                <div className="flex items-center gap-3 mb-4 relative z-10">
                  <div className="w-12 h-12 rounded-full bg-cyan-500/20 flex items-center justify-center border border-cyan-500/30">
                    <Play className="w-6 h-6 text-cyan-600 dark:text-cyan-400 translate-x-0.5" />
                  </div>
                  <div>
                    <h3 className="font-extrabold text-lg text-cyan-700 dark:text-cyan-400">Wave</h3>
                    <p className="text-sm text-foreground/70 font-medium">Short-form vertical video</p>
                  </div>
                </div>
                <ul className="space-y-3 text-sm text-foreground/90 relative z-10">
                  <li className="flex items-start gap-3">
                    <Clock className="w-5 h-5 text-cyan-600 dark:text-cyan-400 flex-shrink-0 mt-0.5" />
                    <span><strong className="text-foreground">60 seconds max</strong> - Quick highlights & clips</span>
                  </li>
                  <li className="flex items-start gap-3">
                    <Play className="w-5 h-5 text-cyan-600 dark:text-cyan-400 flex-shrink-0 mt-0.5" />
                    <span><strong className="text-foreground">Vertical format</strong> - Full-screen TikTok-style</span>
                  </li>
                  <li className="flex items-start gap-3">
                    <Music className="w-5 h-5 text-cyan-600 dark:text-cyan-400 flex-shrink-0 mt-0.5" />
                    <span><strong className="text-foreground">Licensed music</strong> - Coming soon via Adaptr</span>
                  </li>
                </ul>
                <div className="mt-4 pt-3 border-t border-cyan-500/10">
                  <p className="text-xs font-medium text-cyan-700 dark:text-cyan-500/80">
                    Best for: Tricks, highlights, funny moments, quick clips
                  </p>
                </div>
              </div>
              
              {/* Video Section */}
              <div className="p-5 rounded-xl bg-purple-500/10 border border-purple-500/20 shadow-sm relative overflow-hidden">
                <div className="absolute -right-4 -top-4 w-24 h-24 bg-purple-500/10 rounded-full blur-xl pointer-events-none"></div>
                <div className="flex items-center gap-3 mb-4 relative z-10">
                  <div className="w-12 h-12 rounded-full bg-purple-500/20 flex items-center justify-center border border-purple-500/30">
                    <Video className="w-6 h-6 text-purple-600 dark:text-purple-400" />
                  </div>
                  <div>
                    <h3 className="font-extrabold text-lg text-purple-700 dark:text-purple-400">Video Post</h3>
                    <p className="text-sm text-foreground/70 font-medium">Standard video in feed</p>
                  </div>
                </div>
                <ul className="space-y-3 text-sm text-foreground/90 relative z-10">
                  <li className="flex items-start gap-3">
                    <Clock className="w-5 h-5 text-purple-600 dark:text-purple-400 flex-shrink-0 mt-0.5" />
                    <span><strong className="text-foreground">Longer duration</strong> - Full session clips</span>
                  </li>
                  <li className="flex items-start gap-3">
                    <Video className="w-5 h-5 text-purple-600 dark:text-purple-400 flex-shrink-0 mt-0.5" />
                    <span><strong className="text-foreground">Any aspect ratio</strong> - Landscape, square, portrait</span>
                  </li>
                  <li className="flex items-start gap-3">
                    <Music className="w-5 h-5 text-purple-600 dark:text-purple-400 flex-shrink-0 mt-0.5" />
                    <span><strong className="text-foreground">Licensed music</strong> - Coming soon via Epidemic Sound</span>
                  </li>
                </ul>
                <div className="mt-4 pt-3 border-t border-purple-500/10">
                  <p className="text-xs font-medium text-purple-700 dark:text-purple-500/80">
                    Best for: Session recaps, tutorials, vlogs, longer content
                  </p>
                </div>
              </div>
              
              {/* Music Note */}
              <div className="flex items-start gap-3 p-4 rounded-xl bg-amber-500/10 border border-amber-500/30">
                <VolumeX className="w-5 h-5 text-amber-600 dark:text-amber-500 flex-shrink-0 mt-0.5" />
                <div className="text-sm text-foreground/80 leading-relaxed">
                  <strong className="text-amber-700 dark:text-amber-400 font-bold block mb-1">Music Note</strong>
                  Videos with unlicensed copyrighted music may have audio muted. Licensed music libraries coming soon!
                </div>
              </div>
            </div>
          </div>
        </DialogContent>
      </Dialog>
      
      {/* Broadcast Launch Modal */}
      <GoLiveModal 
        isOpen={showGoLiveModal} 
        onClose={() => setShowGoLiveModal(false)} 
      />

      {/* WebRTC Native Camera Interface */}
      <WebcamCaptureModal
        isOpen={showWebcamModal}
        onClose={() => setShowWebcamModal(false)}
        onCapture={(files) => {
          handleFileSelect({ target: { files } });
        }}
      />
    </div>
  );
};

/**
 * CreatePostModal - Extracted from Feed.js for better maintainability
 * Handles media upload (photo/video), session metadata, and post creation
 */
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useAuth } from '../contexts/AuthContext';
import { MapPin, Loader2, Navigation, Image, Video, Upload, Camera, Megaphone, Waves, ChevronDown, Wind, ArrowUpDown, X, Check } from 'lucide-react';
import { toast } from 'sonner';
import { Button } from './ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from './ui/dialog';
import { Input } from './ui/input';
import { Textarea } from './ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import { CreateAdModal } from './CreateAdModal';
import logger from '../utils/logger';


const CreatePostModal = ({ isOpen, onClose, onCreated }) => {
  const { user } = useAuth();
  const navigate = useNavigate();
  
  // Multi-file support for carousel posts
  const [selectedFiles, setSelectedFiles] = useState([]);  // Array of files
  const [previewUrls, setPreviewUrls] = useState([]);      // Array of preview URLs
  const [currentPreviewIndex, setCurrentPreviewIndex] = useState(0);
  
  const [mediaType, setMediaType] = useState('image');
  const [caption, setCaption] = useState('');
  const [location, setLocation] = useState('');
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showCreateAdModal, setShowCreateAdModal] = useState(false);
  const photoInputRef = useRef(null);
  const videoInputRef = useRef(null);
  const cameraInputRef = useRef(null);

  // Session metadata state
  const [showSessionData, setShowSessionData] = useState(false);
  // Helper: get today's date in local time (avoids UTC day-shift — e.g. 11 PM EDT = next day UTC)
  const todayLocal = () => {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };
  const [sessionDate, setSessionDate] = useState(todayLocal());
  const [sessionStartTime, setSessionStartTime] = useState('');
  const [sessionEndTime, setSessionEndTime] = useState('');
  const [waveHeightFt, setWaveHeightFt] = useState('');
  const [wavePeriodSec, setWavePeriodSec] = useState('');
  const [waveDirection, setWaveDirection] = useState('');
  const [waveDirectionDegrees, setWaveDirectionDegrees] = useState(null);
  const [windSpeedMph, setWindSpeedMph] = useState('');
  const [windDirection, setWindDirection] = useState('');
  const [tideStatus, setTideStatus] = useState('');
  const [tideHeightFt, setTideHeightFt] = useState('');
  const [conditionsLoading, setConditionsLoading] = useState(false);
  const [conditionsSource, setConditionsSource] = useState('manual');
  const [knownSpots, setKnownSpots] = useState([]);
  const [selectedSpot, setSelectedSpot] = useState('');
  const [recentLocations, setRecentLocations] = useState([]);
  const [showRecentLocations, setShowRecentLocations] = useState(false);

  // Fetch known spots on mount
  useEffect(() => {
    const fetchSpots = async () => {
      try {
        const response = await apiClient.get(`/surf-conditions/known-spots`);
        setKnownSpots(response.data.spots || []);
      } catch (e) {
        // Silent fail
      }
    };
    if (isOpen) fetchSpots();
  }, [isOpen]);

  // Fetch user's recent locations on mount
  useEffect(() => {
    const fetchRecentLocations = async () => {
      if (!user?.id) return;
      try {
        const response = await apiClient.get(`/posts/user/${user.id}/recent-locations`);
        setRecentLocations(response.data || []);
        if (response.data && response.data.length > 0) {
          setShowRecentLocations(true);
        }
      } catch (e) {
        // Silent fail - recent locations are optional
      }
    };
    if (isOpen && user?.id) fetchRecentLocations();
  }, [isOpen, user?.id]);

  // Handle selecting a recent location
  const handleRecentLocationSelect = async (recentLoc) => {
    setLocation(recentLoc.location);
    setShowRecentLocations(false);
    
    // Auto-fetch conditions if we have coordinates
    if (recentLoc.latitude && recentLoc.longitude) {
      await fetchConditions(recentLoc.latitude, recentLoc.longitude, recentLoc.location);
    }
  };

  // Auto-fetch conditions when spot is selected
  const handleSpotSelect = async (spotKey) => {
    setSelectedSpot(spotKey);
    const spot = knownSpots.find(s => s.key === spotKey);
    if (spot) {
      setLocation(spot.name);
      await fetchConditions(spot.lat, spot.lon, spot.name);
    }
  };

  // Fetch surf conditions
  const fetchConditions = async (lat, lon, spotName) => {
    setConditionsLoading(true);
    try {
      const response = await apiClient.get(`/surf-conditions`, {
        params: { latitude: lat, longitude: lon, spot_name: spotName }
      });
      
      if (response.data.wave_height_ft) setWaveHeightFt(response.data.wave_height_ft.toString());
      if (response.data.wave_period_sec) setWavePeriodSec(response.data.wave_period_sec.toString());
      if (response.data.wave_direction) setWaveDirection(response.data.wave_direction);
      if (response.data.wave_direction_degrees) setWaveDirectionDegrees(response.data.wave_direction_degrees);
      if (response.data.wind_speed_mph) setWindSpeedMph(response.data.wind_speed_mph.toString());
      if (response.data.wind_direction) setWindDirection(response.data.wind_direction);
      if (response.data.tide_status) setTideStatus(response.data.tide_status);
      if (response.data.tide_height_ft) setTideHeightFt(response.data.tide_height_ft.toString());
      setConditionsSource('auto');
      setShowSessionData(true);
      toast.success('Conditions auto-filled! Feel free to adjust.');
    } catch (e) {
      toast.error('Could not fetch conditions. Enter manually.');
    } finally {
      setConditionsLoading(false);
    }
  };

  // Fetch conditions by current location
  const fetchConditionsByLocation = async () => {
    if (!navigator.geolocation) {
      toast.error('Geolocation not supported');
      return;
    }

    setConditionsLoading(true);
    try {
      const position = await new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: true,
          timeout: 10000
        });
      });

      await fetchConditions(position.coords.latitude, position.coords.longitude, location || 'Current Location');
    } catch (e) {
      toast.error('Could not get location. Select a spot instead.');
    } finally {
      setConditionsLoading(false);
    }
  };

  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    const firstFile = files[0];
    const isVideo = firstFile.type.startsWith('video/');
    const isImage = firstFile.type.startsWith('image/');

    if (!isVideo && !isImage) {
      toast.error('Please select image or video files');
      return;
    }

    // Video: only single file allowed
    if (isVideo) {
      const maxSize = 100 * 1024 * 1024;
      if (firstFile.size > maxSize) {
        toast.error('Video too large. Maximum size is 100MB');
        return;
      }
      // Clear any existing and set single video
      previewUrls.forEach(url => URL.revokeObjectURL(url));
      setSelectedFiles([firstFile]);
      setPreviewUrls([URL.createObjectURL(firstFile)]);
      setMediaType('video');
      setCurrentPreviewIndex(0);
      return;
    }

    // Images: allow up to 10
    const imageFiles = files.filter(f => f.type.startsWith('image/'));
    const maxImages = 10;
    const totalImages = selectedFiles.length + imageFiles.length;
    
    if (totalImages > maxImages) {
      toast.error(`Maximum ${maxImages} photos allowed. You have ${selectedFiles.length}, can add ${maxImages - selectedFiles.length} more.`);
      return;
    }

    // Check each image file size (50MB max)
    const maxSize = 50 * 1024 * 1024;
    const validFiles = [];
    const newPreviews = [];
    
    for (const file of imageFiles) {
      if (file.size > maxSize) {
        toast.error(`${file.name} is too large. Maximum size is 50MB`);
        continue;
      }
      validFiles.push(file);
      newPreviews.push(URL.createObjectURL(file));
    }

    if (validFiles.length > 0) {
      setSelectedFiles(prev => [...prev, ...validFiles]);
      setPreviewUrls(prev => [...prev, ...newPreviews]);
      setMediaType('image');
      // Show the first newly added image
      setCurrentPreviewIndex(selectedFiles.length);
    }
  };
  
  const removeImage = (index) => {
    URL.revokeObjectURL(previewUrls[index]);
    setSelectedFiles(prev => prev.filter((_, i) => i !== index));
    setPreviewUrls(prev => prev.filter((_, i) => i !== index));
    if (currentPreviewIndex >= index && currentPreviewIndex > 0) {
      setCurrentPreviewIndex(prev => prev - 1);
    }
  };

  const handleUpload = async () => {
    if (selectedFiles.length === 0) return;

    setLoading(true);
    setUploadProgress(0);

    try {
      const uploadedMedia = [];
      const isCarousel = selectedFiles.length > 1;
      
      // Upload each file
      for (let i = 0; i < selectedFiles.length; i++) {
        const file = selectedFiles[i];
        const formData = new FormData();
        formData.append('file', file);
        formData.append('user_id', user.id);

        setProcessingStatus(
          isCarousel 
            ? `Uploading photo ${i + 1} of ${selectedFiles.length}...` 
            : (mediaType === 'video' ? 'Uploading & processing video (may transcode to 1080p)...' : 'Uploading...')
        );

        const uploadResponse = await apiClient.post(`/upload/feed`, formData, {
          headers: { 'Content-Type': 'multipart/form-data' },
          onUploadProgress: (progressEvent) => {
            const fileProgress = Math.round((progressEvent.loaded * 100) / progressEvent.total);
            const overallProgress = Math.round(((i + fileProgress / 100) / selectedFiles.length) * 100);
            setUploadProgress(overallProgress);
          }
        });
        
        uploadedMedia.push({
          url: uploadResponse.data.media_url,
          type: uploadResponse.data.media_type,
          thumbnail_url: uploadResponse.data.thumbnail_url,
          width: uploadResponse.data.final_width,
          height: uploadResponse.data.final_height
        });
      }

      setProcessingStatus('Creating post...');

      // Build post data with session metadata
      const postData = {
        media_url: uploadedMedia[0].url,
        media_type: uploadedMedia[0].type,
        thumbnail_url: uploadedMedia[0].thumbnail_url || null,
        caption: caption || null,
        location: location || null,
        video_width: uploadedMedia[0].width || null,
        video_height: uploadedMedia[0].height || null,
        is_carousel: isCarousel,
        carousel_media: isCarousel ? uploadedMedia : []
      };

      // Add session metadata if enabled
      if (showSessionData) {
        if (sessionDate) {
          // Send as noon UTC for the selected date — avoids timezone boundary issues on the backend
          postData.session_date = sessionDate + 'T12:00:00.000Z';
        }
        if (sessionStartTime) postData.session_start_time = sessionStartTime;
        if (sessionEndTime) postData.session_end_time = sessionEndTime;
        if (waveHeightFt) postData.wave_height_ft = parseFloat(waveHeightFt);
        if (wavePeriodSec) postData.wave_period_sec = parseInt(wavePeriodSec);
        if (waveDirection) postData.wave_direction = waveDirection;
        if (waveDirectionDegrees) postData.wave_direction_degrees = waveDirectionDegrees;
        if (windSpeedMph) postData.wind_speed_mph = parseFloat(windSpeedMph);
        if (windDirection) postData.wind_direction = windDirection;
        if (tideStatus) postData.tide_status = tideStatus;
        if (tideHeightFt) postData.tide_height_ft = parseFloat(tideHeightFt);
        postData.conditions_source = conditionsSource;
      }

      // Create post
      await apiClient.post(`/posts?author_id=${user.id}`, postData);

      if (isCarousel) {
        toast.success(`Posted ${selectedFiles.length} photos!`);
      } else {
        toast.success('Post created successfully!');
      }
      
      onCreated();
      handleClose();
    } catch (error) {
      logger.error('Upload error:', error);
      toast.error(error.response?.data?.detail || 'Failed to create post');
    } finally {
      setLoading(false);
      setUploadProgress(0);
      setProcessingStatus('');
    }
  };

  const handleClose = () => {
    // Clean up preview URLs
    previewUrls.forEach(url => URL.revokeObjectURL(url));
    setSelectedFiles([]);
    setPreviewUrls([]);
    setCurrentPreviewIndex(0);
    setMediaType('image');
    setCaption('');
    setLocation('');
    // Reset session metadata
    setShowSessionData(false);
    setSessionDate(todayLocal());
    setSessionStartTime('');
    setSessionEndTime('');
    setWaveHeightFt('');
    setWavePeriodSec('');
    setWaveDirection('');
    setWaveDirectionDegrees(null);
    setWindSpeedMph('');
    setWindDirection('');
    setTideStatus('');
    setTideHeightFt('');
    setConditionsSource('manual');
    setSelectedSpot('');
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent 
        className="bg-zinc-900 border-zinc-800 text-white sm:max-w-lg" 
        aria-describedby="create-post-description"
      >
        <DialogHeader className="shrink-0 border-b border-zinc-800">
          <DialogTitle className="text-xl font-bold flex items-center gap-2">
            <Upload className="w-5 h-5 text-yellow-400" />
            Create Post
          </DialogTitle>
          <DialogDescription id="create-post-description" className="sr-only">
            Upload media and create a new post
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-4 sm:px-6 py-4 space-y-4">
          {/* Hidden File Inputs - Separate for Photo, Video, and Camera */}
          <input
            ref={photoInputRef}
            type="file"
            accept="image/*,image/jpeg,image/png,image/heic,image/webp"
            multiple
            onChange={handleFileSelect}
            className="hidden"
          />
          <input
            ref={videoInputRef}
            type="file"
            accept="video/*,video/mp4,video/quicktime,video/webm,video/mov"
            onChange={handleFileSelect}
            className="hidden"
          />
          <input
            ref={cameraInputRef}
            type="file"
            accept="image/*"
            capture="environment"
            onChange={handleFileSelect}
            className="hidden"
          />

          {selectedFiles.length === 0 ? (
            <div className="w-full aspect-video rounded-lg border-2 border-dashed border-zinc-600 flex flex-col items-center justify-center gap-4 bg-zinc-800/50 p-6">
              <p className="text-white font-medium">Select media to post</p>
              
              {/* Media Selection Buttons */}
              <div className="flex gap-4">
                {/* Photo Button */}
                <button
                  onClick={() => photoInputRef.current?.click()}
                  className="flex flex-col items-center gap-2 p-4 rounded-xl bg-zinc-700/50 hover:bg-zinc-700 border border-zinc-600 hover:border-blue-500 transition-all"
                  data-testid="post-photo-select"
                >
                  <Image className="w-8 h-8 text-blue-400" />
                  <span className="text-sm text-white font-medium">Photos</span>
                  <span className="text-xs text-gray-500">Up to 10</span>
                </button>

                {/* Video Button */}
                <button
                  onClick={() => videoInputRef.current?.click()}
                  className="flex flex-col items-center gap-2 p-4 rounded-xl bg-zinc-700/50 hover:bg-zinc-700 border border-zinc-600 hover:border-purple-500 transition-all"
                  data-testid="post-video-select"
                >
                  <Video className="w-8 h-8 text-purple-400" />
                  <span className="text-sm text-white font-medium">Video</span>
                  <span className="text-xs text-gray-500">MP4, MOV</span>
                </button>

                {/* Camera Button - Mobile only shows camera app */}
                <button
                  onClick={() => cameraInputRef.current?.click()}
                  className="flex flex-col items-center gap-2 p-4 rounded-xl bg-zinc-700/50 hover:bg-zinc-700 border border-zinc-600 hover:border-yellow-500 transition-all"
                  data-testid="post-camera-capture"
                >
                  <Camera className="w-8 h-8 text-yellow-400" />
                  <span className="text-sm text-white font-medium">Camera</span>
                  <span className="text-xs text-gray-500">Take photo</span>
                </button>
              </div>

              <p className="text-xs text-gray-500 mt-2">
                Select up to 10 photos for a carousel post
              </p>

              {/* Divider */}
              <div className="w-full h-px bg-zinc-700 my-2" />

              {/* Create Ad Button */}
              <button
                onClick={() => setShowCreateAdModal(true)}
                className="flex items-center justify-center gap-3 w-full p-3 rounded-xl bg-purple-500/10 hover:bg-purple-500/20 border border-purple-500/30 hover:border-purple-500 transition-all"
                data-testid="post-create-ad"
              >
                <Megaphone className="w-5 h-5 text-purple-400" />
                <span className="text-sm text-purple-400 font-medium">Create Ad</span>
              </button>
            </div>
          ) : (
            <div className="space-y-3">
              {/* Main Preview */}
              <div className="relative">
                {mediaType === 'video' ? (
                  <video
                    src={previewUrls[0]}
                    controls
                    className="w-full aspect-video object-cover rounded-lg"
                  />
                ) : (
                  <img
                    src={previewUrls[currentPreviewIndex]}
                    alt={`Preview ${currentPreviewIndex + 1}`}
                    className="w-full aspect-video object-cover rounded-lg"
                  />
                )}
                
                {/* Navigation arrows for carousel */}
                {previewUrls.length > 1 && (
                  <>
                    <button
                      onClick={() => setCurrentPreviewIndex(prev => (prev - 1 + previewUrls.length) % previewUrls.length)}
                      className="absolute left-2 top-1/2 -translate-y-1/2 p-1.5 bg-black/70 rounded-full hover:bg-black"
                    >
                      <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                      </svg>
                    </button>
                    <button
                      onClick={() => setCurrentPreviewIndex(prev => (prev + 1) % previewUrls.length)}
                      className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-black/70 rounded-full hover:bg-black"
                    >
                      <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                      </svg>
                    </button>
                    {/* Dots indicator */}
                    <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex gap-1">
                      {previewUrls.map((_, idx) => (
                        <button
                          key={idx}
                          onClick={() => setCurrentPreviewIndex(idx)}
                          className={`w-1.5 h-1.5 rounded-full transition-colors ${
                            idx === currentPreviewIndex ? 'bg-white' : 'bg-white/50'
                          }`}
                        />
                      ))}
                    </div>
                  </>
                )}
                
                {/* Image count badge */}
                {previewUrls.length > 1 && (
                  <div className="absolute top-2 right-2 bg-black/70 px-2 py-1 rounded text-xs text-white">
                    {currentPreviewIndex + 1} / {previewUrls.length}
                  </div>
                )}
              </div>
              
              {/* Thumbnail strip for carousel */}
              {previewUrls.length > 1 && (
                <div className="flex gap-2 overflow-x-auto pb-2">
                  {previewUrls.map((url, idx) => (
                    <div key={idx} className="relative flex-shrink-0">
                      <button
                        onClick={() => setCurrentPreviewIndex(idx)}
                        className={`w-16 h-16 rounded-lg overflow-hidden border-2 transition-colors ${
                          idx === currentPreviewIndex ? 'border-blue-500' : 'border-transparent'
                        }`}
                      >
                        <img src={url} alt={`Thumb ${idx + 1}`} className="w-full h-full object-cover" />
                      </button>
                      <button
                        onClick={() => removeImage(idx)}
                        className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 rounded-full flex items-center justify-center hover:bg-red-600"
                      >
                        <X className="w-3 h-3 text-white" />
                      </button>
                    </div>
                  ))}
                  {/* Add more photos button */}
                  {previewUrls.length < 10 && mediaType === 'image' && (
                    <button
                      onClick={() => photoInputRef.current?.click()}
                      className="w-16 h-16 rounded-lg border-2 border-dashed border-zinc-600 flex items-center justify-center hover:border-zinc-500 transition-colors flex-shrink-0"
                    >
                      <svg className="w-6 h-6 text-zinc-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                      </svg>
                    </button>
                  )}
                </div>
              )}
              
              {/* Single image remove button */}
              {previewUrls.length === 1 && (
                <div className="flex justify-between items-center">
                  <button
                    onClick={() => {
                      previewUrls.forEach(url => URL.revokeObjectURL(url));
                      setSelectedFiles([]);
                      setPreviewUrls([]);
                    }}
                    className="text-sm text-red-400 hover:text-red-300"
                  >
                    Remove
                  </button>
                  {mediaType === 'image' && (
                    <button
                      onClick={() => photoInputRef.current?.click()}
                      className="text-sm text-blue-400 hover:text-blue-300"
                    >
                      + Add more photos
                    </button>
                  )}
                </div>
              )}
              
              {mediaType === 'video' && (
                <p className="text-xs text-blue-400">
                  Videos over 1080p will be automatically optimized
                </p>
              )}
            </div>
          )}

          {/* Caption */}
          <div>
            <label className="text-sm text-gray-400 mb-2 block">Caption (optional)</label>
            <Textarea
              value={caption}
              onChange={(e) => setCaption(e.target.value)}
              placeholder="What's happening?"
              className="bg-zinc-800 border-zinc-700 text-white"
              rows={2}
            />
          </div>

          {/* Recent Locations Quick Select */}
          {recentLocations.length > 0 && (
            <div className="space-y-2" data-testid="recent-locations-section">
              <div className="flex items-center justify-between">
                <label className="text-sm text-gray-400 flex items-center gap-2">
                  <MapPin className="w-4 h-4 text-cyan-400" />
                  Recent Locations
                </label>
                <button
                  type="button"
                  onClick={() => setShowRecentLocations(!showRecentLocations)}
                  className="text-xs text-cyan-400 hover:text-cyan-300"
                >
                  {showRecentLocations ? 'Hide' : 'Show'}
                </button>
              </div>
              {showRecentLocations && (
                <div className="flex flex-wrap gap-2">
                  {recentLocations.slice(0, 5).map((loc, idx) => (
                    <button
                      key={idx}
                      type="button"
                      onClick={() => handleRecentLocationSelect(loc)}
                      className="flex items-center gap-1.5 px-3 py-1.5 bg-zinc-800 hover:bg-zinc-700 border border-zinc-700 rounded-full text-sm text-white transition-colors group"
                      data-testid={`recent-location-${idx}`}
                    >
                      <MapPin className="w-3 h-3 text-cyan-400 group-hover:text-cyan-300" />
                      <span>{loc.spot_name || loc.location}</span>
                      {loc.use_count > 1 && (
                        <span className="text-xs text-gray-500">x{loc.use_count}</span>
                      )}
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Location */}
          <div>
            <label className="text-sm text-gray-400 mb-2 block">Location (optional)</label>
            <Input
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              placeholder="e.g., Sebastian Inlet, FL"
              className="bg-zinc-800 border-zinc-700 text-white"
            />
          </div>

          {/* Session Data Toggle */}
          <div className="border border-zinc-700 rounded-lg overflow-hidden">
            <button
              type="button"
              onClick={() => setShowSessionData(!showSessionData)}
              className="w-full flex items-center justify-between p-3 bg-zinc-800/50 hover:bg-zinc-800 transition-colors"
              data-testid="toggle-session-data"
            >
              <div className="flex items-center gap-2">
                <Waves className="w-4 h-4 text-cyan-400" />
                <span className="text-sm font-medium text-white">Add Session Conditions</span>
                {conditionsSource === 'auto' && (
                  <span className="text-xs bg-green-500/20 text-green-400 px-2 py-0.5 rounded-full">Auto-filled</span>
                )}
              </div>
              <ChevronDown className={`w-4 h-4 text-gray-400 transition-transform ${showSessionData ? 'rotate-180' : ''}`} />
            </button>

            {showSessionData && (
              <div className="p-4 space-y-4 bg-zinc-800/30">
                {/* Spot Selector & Auto-fetch */}
                <div className="flex gap-2">
                  <Select value={selectedSpot} onValueChange={handleSpotSelect}>
                    <SelectTrigger className="flex-1 bg-zinc-800 border-zinc-700 text-white">
                      <SelectValue placeholder="Select a surf spot..." />
                    </SelectTrigger>
                    <SelectContent className="bg-zinc-800 border-zinc-700 max-h-60">
                      {knownSpots.map((spot) => (
                        <SelectItem key={spot.key} value={spot.key} className="text-white hover:bg-zinc-700">
                          {spot.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={fetchConditionsByLocation}
                    disabled={conditionsLoading}
                    className="border-cyan-500/50 text-cyan-400 hover:bg-cyan-500/10"
                    data-testid="fetch-conditions-gps"
                  >
                    {conditionsLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Navigation className="w-4 h-4" />}
                  </Button>
                </div>

                {/* Session Date & Time */}
                <div className="grid grid-cols-3 gap-2">
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block">Date</label>
                    <Input
                      type="date"
                      value={sessionDate}
                      onChange={(e) => setSessionDate(e.target.value)}
                      max={todayLocal()}
                      className="bg-zinc-800 border-zinc-700 text-white text-sm"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block">Start</label>
                    <Input
                      type="time"
                      value={sessionStartTime}
                      onChange={(e) => setSessionStartTime(e.target.value)}
                      className="bg-zinc-800 border-zinc-700 text-white text-sm"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block">End</label>
                    <Input
                      type="time"
                      value={sessionEndTime}
                      onChange={(e) => setSessionEndTime(e.target.value)}
                      className="bg-zinc-800 border-zinc-700 text-white text-sm"
                    />
                  </div>
                </div>

                {/* Wave Conditions */}
                <div className="grid grid-cols-3 gap-2">
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block flex items-center gap-1">
                      <Waves className="w-3 h-3" /> Wave Height (ft)
                    </label>
                    <Input
                      type="number"
                      step="0.5"
                      value={waveHeightFt}
                      onChange={(e) => { setWaveHeightFt(e.target.value); setConditionsSource('manual'); }}
                      placeholder="e.g., 4.5"
                      className="bg-zinc-800 border-zinc-700 text-white text-sm"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block">Period (sec)</label>
                    <Input
                      type="number"
                      value={wavePeriodSec}
                      onChange={(e) => { setWavePeriodSec(e.target.value); setConditionsSource('manual'); }}
                      placeholder="e.g., 12"
                      className="bg-zinc-800 border-zinc-700 text-white text-sm"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block">Wave Dir</label>
                    <Select value={waveDirection} onValueChange={(v) => { setWaveDirection(v); setConditionsSource('manual'); }}>
                      <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white text-sm">
                        <SelectValue placeholder="Dir" />
                      </SelectTrigger>
                      <SelectContent className="bg-zinc-800 border-zinc-700">
                        {['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'].map((dir) => (
                          <SelectItem key={dir} value={dir} className="text-white hover:bg-zinc-700">{dir}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {/* Wind Conditions */}
                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block flex items-center gap-1">
                      <Wind className="w-3 h-3" /> Wind (mph)
                    </label>
                    <Input
                      type="number"
                      step="0.5"
                      value={windSpeedMph}
                      onChange={(e) => { setWindSpeedMph(e.target.value); setConditionsSource('manual'); }}
                      placeholder="e.g., 8"
                      className="bg-zinc-800 border-zinc-700 text-white text-sm"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block">Direction</label>
                    <Select value={windDirection} onValueChange={(v) => { setWindDirection(v); setConditionsSource('manual'); }}>
                      <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white text-sm">
                        <SelectValue placeholder="Select..." />
                      </SelectTrigger>
                      <SelectContent className="bg-zinc-800 border-zinc-700">
                        {['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'].map((dir) => (
                          <SelectItem key={dir} value={dir} className="text-white hover:bg-zinc-700">{dir}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {/* Tide */}
                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block flex items-center gap-1">
                      <ArrowUpDown className="w-3 h-3" /> Tide Status
                    </label>
                    <Select value={tideStatus} onValueChange={(v) => { setTideStatus(v); setConditionsSource('manual'); }}>
                      <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white text-sm">
                        <SelectValue placeholder="Select..." />
                      </SelectTrigger>
                      <SelectContent className="bg-zinc-800 border-zinc-700">
                        {['Rising', 'High', 'Falling', 'Low'].map((status) => (
                          <SelectItem key={status} value={status} className="text-white hover:bg-zinc-700">{status}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <label className="text-xs text-gray-400 mb-1 block">Tide Height (ft)</label>
                    <Input
                      type="number"
                      step="0.1"
                      value={tideHeightFt}
                      onChange={(e) => { setTideHeightFt(e.target.value); setConditionsSource('manual'); }}
                      placeholder="e.g., 2.3"
                      className="bg-zinc-800 border-zinc-700 text-white text-sm"
                    />
                  </div>
                </div>

                <p className="text-xs text-gray-500 flex items-center gap-1">
                  {conditionsSource === 'auto' ? (
                    <>
                      <Check className="w-3 h-3 text-green-400" />
                      <span className="text-green-400">Auto-filled from Open-Meteo</span>
                      <span>- Edit values to override</span>
                    </>
                  ) : (
                    <>Conditions will be shown on your post</>
                  )}
                </p>
              </div>
            )}
          </div>

          {/* Progress */}
          {loading && (
            <div className="space-y-2">
              <div className="h-2 bg-zinc-800 rounded-full overflow-hidden">
                <div
                  className="h-full bg-yellow-400 transition-all"
                  style={{ width: `${uploadProgress}%` }}
                />
              </div>
              <p className="text-xs text-gray-400 text-center">{processingStatus}</p>
            </div>
          )}
        </div>

        {/* Fixed Footer with Submit Button */}
        <div className="shrink-0 px-4 sm:px-6 py-4 border-t border-zinc-800" style={{ paddingBottom: 'max(1rem, env(safe-area-inset-bottom, 0px))' }}>
          <Button
            onClick={handleUpload}
            disabled={loading || selectedFiles.length === 0}
            className="w-full h-12 bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black font-bold"
            data-testid="post-submit-btn"
          >
            {loading ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : selectedFiles.length > 1 ? (
              `Share ${selectedFiles.length} Photos`
            ) : (
              'Share Post'
            )}
          </Button>
        </div>
      </DialogContent>

      {/* Create Ad Modal */}
      <CreateAdModal
        isOpen={showCreateAdModal}
        onClose={() => setShowCreateAdModal(false)}
        onSuccess={() => {
          setShowCreateAdModal(false);
          handleClose();
          navigate('/wallet');
        }}
      />
    </Dialog>
  );
};

export default CreatePostModal;

/**
 * CreateWaveModal - Upload short-form vertical video (max 60 seconds)
 */
import React, { useState, useRef, useCallback } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from './ui/dialog';
import { Button } from './ui/button';
import { TextareaWithEmoji } from './EmojiPicker';
import { Input } from './ui/input';
import { 
  Upload, Video, Loader2, MapPin, Clock, AlertCircle, 
  CheckCircle, Play, Pause, Volume2, Volume1, VolumeX, RotateCcw
} from 'lucide-react';
import { toast } from 'sonner';
import logger from '../utils/logger';

const MAX_DURATION = 60; // seconds
const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB

export const CreateWaveModal = ({ isOpen, onClose, onSuccess }) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';
  
  const fileInputRef = useRef(null);
  const videoRef = useRef(null);
  
  const [step, setStep] = useState('select'); // 'select', 'preview', 'details', 'uploading'
  const [selectedFile, setSelectedFile] = useState(null);
  const [videoPreview, setVideoPreview] = useState(null);
  const [videoInfo, setVideoInfo] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(true);
  const [volume, setVolume] = useState(0.7);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);
  const volumeTimerRef = useRef(null);
  
  const [caption, setCaption] = useState('');
  const [location, setLocation] = useState('');
  const [uploadProgress, setUploadProgress] = useState(0);
  const [error, setError] = useState(null);
  
  const bgClass = isLight ? 'bg-white' : 'bg-zinc-900';
  const textClass = isLight ? 'text-zinc-900' : 'text-white';
  const mutedClass = isLight ? 'text-zinc-500' : 'text-zinc-400';
  const borderClass = isLight ? 'border-zinc-200' : 'border-zinc-700';
  
  const resetState = () => {
    setStep('select');
    setSelectedFile(null);
    setVideoPreview(null);
    setVideoInfo(null);
    setCaption('');
    setLocation('');
    setUploadProgress(0);
    setError(null);
    setIsPlaying(false);
  };
  
  const handleClose = () => {
    resetState();
    onClose();
  };
  
  const handleFileSelect = useCallback(async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    
    setError(null);
    
    // Validate file type
    if (!file.type.startsWith('video/')) {
      setError('Please select a video file');
      return;
    }
    
    // Validate file size
    if (file.size > MAX_FILE_SIZE) {
      setError(`File too large. Maximum size is ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
      return;
    }
    
    // Create preview URL
    const previewUrl = URL.createObjectURL(file);
    setVideoPreview(previewUrl);
    setSelectedFile(file);
    
    // Get video metadata
    const video = document.createElement('video');
    video.preload = 'metadata';
    
    video.onloadedmetadata = () => {
      const duration = video.duration;
      const width = video.videoWidth;
      const height = video.videoHeight;
      
      // Check duration
      if (duration > MAX_DURATION) {
        setError(`Video must be ${MAX_DURATION} seconds or less. Your video is ${Math.round(duration)} seconds.`);
        setVideoPreview(null);
        setSelectedFile(null);
        URL.revokeObjectURL(previewUrl);
        return;
      }
      
      // Calculate aspect ratio
      let aspectRatio = '9:16';
      const ratio = height / width;
      if (ratio >= 1.7) aspectRatio = '9:16';
      else if (ratio >= 1.2) aspectRatio = '4:5';
      else if (ratio >= 0.9) aspectRatio = '1:1';
      else aspectRatio = '16:9';
      
      setVideoInfo({
        duration,
        width,
        height,
        aspectRatio,
        isVertical: height > width
      });
      
      setStep('preview');
    };
    
    video.onerror = () => {
      setError('Could not read video file');
      URL.revokeObjectURL(previewUrl);
    };
    
    video.src = previewUrl;
  }, []);
  
  const handleUpload = async () => {
    if (!selectedFile || !user) return;
    
    setStep('uploading');
    setError(null);
    
    try {
      // Step 1: Upload video
      const formData = new FormData();
      formData.append('file', selectedFile);
      formData.append('user_id', user.id);
      
      const uploadResponse = await apiClient.post(`/upload/wave`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
        onUploadProgress: (progressEvent) => {
          const progress = Math.round((progressEvent.loaded * 100) / progressEvent.total);
          setUploadProgress(progress);
        }
      });
      
      // Step 2: Create Wave post
      const waveData = {
        author_id: user.id,
        media_url: uploadResponse.data.media_url,
        thumbnail_url: uploadResponse.data.thumbnail_url,
        caption: caption.trim() || null,
        location: location.trim() || null,
        aspect_ratio: uploadResponse.data.aspect_ratio,
        video_width: uploadResponse.data.final_width || uploadResponse.data.original_width,
        video_height: uploadResponse.data.final_height || uploadResponse.data.original_height,
        video_duration: uploadResponse.data.duration
      };
      
      await apiClient.post(`/waves`, null, { params: waveData });
      
      toast.success('Wave posted!');
      handleClose();
      onSuccess?.();
      
    } catch (err) {
      logger.error('Upload error:', err);
      setError(err.response?.data?.detail || 'Failed to upload wave');
      setStep('details');
    }
  };
  
  const formatDuration = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };
  
  const togglePlayPause = () => {
    if (videoRef.current) {
      if (videoRef.current.paused) {
        videoRef.current.play();
        setIsPlaying(true);
      } else {
        videoRef.current.pause();
        setIsPlaying(false);
      }
    }
  };
  
  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className={`${bgClass} ${textClass} max-w-md mx-auto p-0 overflow-hidden`}>
        <DialogHeader className={`p-4 border-b ${borderClass}`}>
          <DialogTitle className="flex items-center gap-2">
            <Video className="w-5 h-5 text-cyan-500" />
            Create Wave
          </DialogTitle>
        </DialogHeader>
        
        <div className="p-4">
          {/* Step 1: Select Video */}
          {step === 'select' && (
            <div className="space-y-4">
              <div 
                onClick={() => fileInputRef.current?.click()}
                className={`border-2 border-dashed ${borderClass} rounded-xl p-8 text-center cursor-pointer hover:border-cyan-500 transition-colors`}
                data-testid="wave-upload-dropzone"
              >
                <Upload className={`w-12 h-12 mx-auto mb-4 ${mutedClass}`} />
                <p className={`font-medium mb-1 ${textClass}`}>Select a video</p>
                <p className={`text-sm ${mutedClass}`}>
                  MP4, MOV, or WebM • Max {MAX_DURATION} seconds
                </p>
              </div>
              
              <input
                ref={fileInputRef}
                type="file"
                accept="video/*"
                onChange={handleFileSelect}
                className="hidden"
                data-testid="wave-file-input"
              />
              
              {error && (
                <div className="flex items-center gap-2 text-red-500 text-sm">
                  <AlertCircle className="w-4 h-4" />
                  {error}
                </div>
              )}
              
              <div className={`text-xs ${mutedClass} space-y-1`}>
                <p className="flex items-center gap-1">
                  <Clock className="w-3 h-3" />
                  Videos must be 60 seconds or less (music label compliance)
                </p>
                <p>Vertical videos (9:16) work best for Waves</p>
              </div>
            </div>
          )}
          
          {/* Step 2: Preview */}
          {step === 'preview' && videoPreview && (
            <div className="space-y-4">
              <div className="relative aspect-[9/16] max-h-[400px] bg-black rounded-xl overflow-hidden mx-auto">
                <video
                  ref={videoRef}
                  src={videoPreview}
                  className="w-full h-full object-contain"
                  loop
                  playsInline
                  muted={isMuted}
                />
                
                {/* Video controls */}
                <div className="absolute bottom-0 left-0 right-0 p-3 bg-gradient-to-t from-black/80 to-transparent">
                  <div className="flex items-center justify-between text-white">
                    <button onClick={togglePlayPause} className="p-2">
                      {isPlaying ? <Pause className="w-5 h-5" /> : <Play className="w-5 h-5" />}
                    </button>
                    
                    <div
                      className="flex items-center gap-1.5"
                      onMouseEnter={() => {
                        setShowVolumeSlider(true);
                        if (volumeTimerRef.current) clearTimeout(volumeTimerRef.current);
                      }}
                      onMouseLeave={() => {
                        volumeTimerRef.current = setTimeout(() => setShowVolumeSlider(false), 1200);
                      }}
                    >
                      <span className="text-sm">
                        {formatDuration(videoInfo?.duration || 0)}
                      </span>
                      {/* Volume slider — progressive disclosure */}
                      <div
                        className="overflow-hidden transition-all duration-300 ease-out flex items-center"
                        style={{
                          width: showVolumeSlider ? '60px' : '0px',
                          opacity: showVolumeSlider ? 1 : 0,
                        }}
                      >
                        <input
                          type="range"
                          min="0"
                          max="1"
                          step="0.05"
                          value={isMuted ? 0 : volume}
                          onChange={(e) => {
                            const newVol = parseFloat(e.target.value);
                            setVolume(newVol);
                            if (videoRef.current) {
                              videoRef.current.volume = newVol;
                              if (newVol === 0) {
                                setIsMuted(true);
                                videoRef.current.muted = true;
                              } else if (isMuted) {
                                setIsMuted(false);
                                videoRef.current.muted = false;
                              }
                            }
                            if (volumeTimerRef.current) clearTimeout(volumeTimerRef.current);
                            volumeTimerRef.current = setTimeout(() => setShowVolumeSlider(false), 2000);
                          }}
                          className="w-full h-1 appearance-none bg-white/30 rounded-full cursor-pointer"
                          aria-label="Volume"
                          style={{
                            background: `linear-gradient(to right, rgba(255,255,255,0.9) ${(isMuted ? 0 : volume) * 100}%, rgba(255,255,255,0.2) ${(isMuted ? 0 : volume) * 100}%)`,
                          }}
                        />
                      </div>
                      <button
                        onClick={() => {
                          const newMuted = !isMuted;
                          setIsMuted(newMuted);
                          if (videoRef.current) {
                            videoRef.current.muted = newMuted;
                            if (!newMuted) videoRef.current.volume = volume;
                          }
                          setShowVolumeSlider(true);
                          if (volumeTimerRef.current) clearTimeout(volumeTimerRef.current);
                          volumeTimerRef.current = setTimeout(() => setShowVolumeSlider(false), 2000);
                        }}
                        className="p-2"
                        aria-label={isMuted ? 'Unmute' : 'Mute'}
                      >
                        {isMuted || volume === 0 ? <VolumeX className="w-5 h-5" /> : volume < 0.5 ? <Volume1 className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                      </button>
                    </div>
                  </div>
                </div>
                
                {/* Aspect ratio badge */}
                <div className="absolute top-3 left-3 bg-black/50 px-2 py-1 rounded text-white text-xs">
                  {videoInfo?.aspectRatio}
                </div>
              </div>
              
              {/* Video info */}
              <div className={`flex items-center justify-center gap-4 text-sm ${mutedClass}`}>
                <span>{videoInfo?.width}x{videoInfo?.height}</span>
                <span>•</span>
                <span>{formatDuration(videoInfo?.duration || 0)}</span>
                {videoInfo?.isVertical && (
                  <>
                    <span>•</span>
                    <span className="text-green-500 flex items-center gap-1">
                      <CheckCircle className="w-3 h-3" /> Vertical
                    </span>
                  </>
                )}
              </div>
              
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={resetState}
                  className={`flex-1 ${isLight ? '' : 'border-zinc-700 hover:bg-zinc-800'}`}
                >
                  <RotateCcw className="w-4 h-4 mr-2" />
                  Choose Different
                </Button>
                <Button
                  onClick={() => setStep('details')}
                  className="flex-1 bg-cyan-500 hover:bg-cyan-600 text-white"
                  data-testid="wave-continue-btn"
                >
                  Continue
                </Button>
              </div>
            </div>
          )}
          
          {/* Step 3: Add Details */}
          {step === 'details' && (
            <div className="space-y-4">
              {/* Thumbnail preview */}
              <div className="relative aspect-video bg-black rounded-xl overflow-hidden">
                <video
                  src={videoPreview}
                  className="w-full h-full object-contain"
                  muted
                />
                <div className="absolute bottom-2 right-2 bg-black/50 px-2 py-1 rounded text-white text-xs">
                  {formatDuration(videoInfo?.duration || 0)}
                </div>
              </div>
              
              {/* Caption with Emoji Picker */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-1 block`}>
                  Caption
                </label>
                <TextareaWithEmoji
                  value={caption}
                  onChange={(val) => setCaption(val.length <= 500 ? val : val.slice(0, 500))}
                  placeholder="Add a caption... 🤙"
                  rows={3}
                  isLight={isLight}
                />
                <p className={`text-xs ${mutedClass} mt-1 text-right`}>
                  {caption.length}/500
                </p>
              </div>
              
              {/* Location */}
              <div>
                <label className={`text-sm font-medium ${textClass} mb-1 block`}>
                  Location
                </label>
                <div className="relative">
                  <MapPin className={`absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 ${mutedClass}`} />
                  <Input
                    value={location}
                    onChange={(e) => setLocation(e.target.value)}
                    placeholder="Add location..."
                    className={`pl-9 ${isLight ? 'bg-white border-zinc-300' : 'bg-zinc-800 border-zinc-700'}`}
                    data-testid="wave-location-input"
                  />
                </div>
              </div>
              
              {error && (
                <div className="flex items-center gap-2 text-red-500 text-sm">
                  <AlertCircle className="w-4 h-4" />
                  {error}
                </div>
              )}
              
              <div className="flex gap-2 pt-2">
                <Button
                  variant="outline"
                  onClick={() => setStep('preview')}
                  className={`flex-1 ${isLight ? '' : 'border-zinc-700 hover:bg-zinc-800'}`}
                >
                  Back
                </Button>
                <Button
                  onClick={handleUpload}
                  className="flex-1 bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white"
                  data-testid="wave-post-btn"
                >
                  Post Wave
                </Button>
              </div>
            </div>
          )}
          
          {/* Step 4: Uploading */}
          {step === 'uploading' && (
            <div className="py-8 text-center space-y-4">
              <Loader2 className="w-12 h-12 mx-auto text-cyan-500 animate-spin" />
              <div>
                <p className={`font-medium ${textClass}`}>Uploading your Wave...</p>
                <p className={`text-sm ${mutedClass}`}>{uploadProgress}%</p>
              </div>
              
              {/* Progress bar */}
              <div className={`w-full h-2 rounded-full ${isLight ? 'bg-zinc-200' : 'bg-zinc-700'}`}>
                <div 
                  className="h-full rounded-full bg-gradient-to-r from-cyan-500 to-blue-500 transition-all duration-300"
                  style={{ width: `${uploadProgress}%` }}
                />
              </div>
              
              <p className={`text-xs ${mutedClass}`}>
                Please don't close this window
              </p>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default CreateWaveModal;

﻿import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { Wallet, CreditCard, ArrowUpRight, ArrowDownLeft, History, Plus, RefreshCw, TrendingUp, TrendingDown } from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { toast } from 'sonner';
import logger from '../utils/logger';


export const CreditWallet = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [balance, setBalance] = useState(0);
  const [transactions, setTransactions] = useState([]);
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showBuyModal, setShowBuyModal] = useState(false);
  const [selectedAmount, setSelectedAmount] = useState(25);
  const [purchasing, setPurchasing] = useState(false);

  // Theme-specific classes
  const isLight = theme === 'light';
  const isBeach = theme === 'beach';
  const mainBgClass = isLight ? 'bg-gray-50' : isBeach ? 'bg-black' : 'bg-zinc-900';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : isBeach ? 'bg-zinc-950 border-zinc-800' : 'bg-zinc-800/50 border-zinc-700';
  const textPrimaryClass = isLight ? 'text-gray-900' : 'text-white';
  const textSecondaryClass = isLight ? 'text-gray-600' : isBeach ? 'text-gray-300' : 'text-gray-400';
  const borderClass = isLight ? 'border-gray-200' : isBeach ? 'border-zinc-800' : 'border-zinc-700';

  const creditPackages = [
    { amount: 10, bonus: 0, label: '$10' },
    { amount: 25, bonus: 0, label: '$25' },
    { amount: 50, bonus: 5, label: '$50', popular: true },
    { amount: 100, bonus: 15, label: '$100', bestValue: true },
  ];

  useEffect(() => {
    // Check for payment success/cancel
    const sessionId = searchParams.get('session_id');
    if (sessionId) {
      verifyPayment(sessionId);
    } else {
      fetchWalletData();
    }
  }, [user?.id]);

  const fetchWalletData = async () => {
    if (!user?.id) return;
    setLoading(true);
    try {
      // Fetch balance
      const balanceRes = await apiClient.get(`/credits/balance/${user.id}`);
      setBalance(balanceRes.data.balance || 0);

      // Fetch transaction history
      try {
        const historyRes = await apiClient.get(`/credits/history/${user.id}?limit=20`);
        setTransactions(historyRes.data.transactions || []);
      } catch (e) {
        setTransactions([]);
      }

      // Fetch summary
      try {
        const summaryRes = await apiClient.get(`/credits/summary/${user.id}`);
        setSummary(summaryRes.data);
      } catch (e) {
        setSummary(null);
      }
    } catch (error) {
      logger.error('Error fetching wallet data:', error);
    } finally {
      setLoading(false);
    }
  };

  const verifyPayment = async (sessionId) => {
    try {
      const res = await apiClient.get(`/credits/status/${sessionId}`);
      if (res.data.payment_status === 'paid') {
        toast.success(`Successfully added ${res.data.amount} credits!`);
      }
      // Clear URL params
      navigate('/wallet', { replace: true });
      fetchWalletData();
    } catch (error) {
      toast.error('Failed to verify payment');
      navigate('/wallet', { replace: true });
      fetchWalletData();
    }
  };

  const handleBuyCredits = async () => {
    if (!user?.id) return;
    setPurchasing(true);
    try {
      const res = await apiClient.post(`/credits/purchase`, {
        amount: selectedAmount,
        origin_url: window.location.origin
      });
      if (res.data.checkout_url) {
        window.location.href = res.data.checkout_url;
      }
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to start purchase');
      setPurchasing(false);
    }
  };

  const getTransactionIcon = (type) => {
    if (type.includes('earning') || type.includes('sale') || type === 'stripe_topup' || type === 'refund') {
      return <ArrowDownLeft className="w-4 h-4 text-green-400" />;
    }
    return <ArrowUpRight className="w-4 h-4 text-red-400" />;
  };

  const getTransactionLabel = (type) => {
    const labels = {
      'stripe_topup': 'Credit Purchase',
      'live_session_buyin': 'Live Session Buy-in',
      'live_session_earning': 'Session Earning',
      'live_photo_purchase': 'Photo Purchase',
      'booking_payment': 'Booking Payment',
      'booking_earning': 'Booking Earning',
      'gallery_purchase': 'Gallery Purchase',
      'gallery_sale': 'Gallery Sale',
      'refund': 'Refund'
    };
    return labels[type] || type.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  };

  if (loading) {
    return (
      <div className={`flex items-center justify-center min-h-screen ${mainBgClass}`}>
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-400"></div>
      </div>
    );
  }

  return (
    <div className={`pb-20 min-h-screen ${mainBgClass} transition-colors duration-300`} data-testid="credit-wallet-page">
      <div className="max-w-lg mx-auto p-4">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <h1 className={`text-3xl font-bold ${textPrimaryClass}`} style={{ fontFamily: 'Oswald' }}>
            Credit Wallet
          </h1>
          <Button
            onClick={fetchWalletData}
            variant="ghost"
            size="icon"
            className={textSecondaryClass}
          >
            <RefreshCw className="w-5 h-5" />
          </Button>
        </div>

        {/* Balance Card */}
        <Card className="mb-6 bg-gradient-to-br from-green-500/20 via-emerald-500/20 to-teal-500/20 border-green-500/30">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className={textSecondaryClass}>Available Balance</p>
                <div className="flex items-baseline gap-2 mt-1">
                  <span className={`text-4xl font-bold ${textPrimaryClass}`}>
                    ${balance.toFixed(2)}
                  </span>
                  <span className={`text-sm ${textSecondaryClass}`}>credits</span>
                </div>
                <p className={`text-xs ${textSecondaryClass} mt-2`}>1 credit = $1 USD</p>
              </div>
              <div className="w-16 h-16 rounded-full bg-green-500/20 flex items-center justify-center">
                <Wallet className="w-8 h-8 text-green-400" />
              </div>
            </div>
            <Button
              onClick={() => setShowBuyModal(true)}
              className="w-full mt-4 bg-gradient-to-r from-green-400 to-emerald-500 hover:from-green-500 hover:to-emerald-600 text-black font-medium"
              data-testid="add-credits-btn"
            >
              <Plus className="w-4 h-4 mr-2" />
              Add Credits
            </Button>
          </CardContent>
        </Card>

        {/* Summary Stats */}
        {summary && (
          <div className="grid grid-cols-2 gap-4 mb-6">
            <Card className={cardBgClass}>
              <CardContent className="p-4">
                <div className="flex items-center gap-2">
                  <TrendingUp className="w-5 h-5 text-green-400" />
                  <span className={`text-sm ${textSecondaryClass}`}>Total Earned</span>
                </div>
                <p className={`text-xl font-bold ${textPrimaryClass} mt-1`}>
                  ${(summary.total_earned || 0).toFixed(2)}
                </p>
              </CardContent>
            </Card>
            <Card className={cardBgClass}>
              <CardContent className="p-4">
                <div className="flex items-center gap-2">
                  <TrendingDown className="w-5 h-5 text-orange-400" />
                  <span className={`text-sm ${textSecondaryClass}`}>Total Spent</span>
                </div>
                <p className={`text-xl font-bold ${textPrimaryClass} mt-1`}>
                  ${(summary.total_spent || 0).toFixed(2)}
                </p>
              </CardContent>
            </Card>
          </div>
        )}

        {/* Transaction History */}
        <div>
          <div className="flex items-center gap-2 mb-4">
            <History className={`w-5 h-5 ${textSecondaryClass}`} />
            <h2 className={`text-lg font-bold ${textPrimaryClass}`}>Recent Activity</h2>
          </div>

          {transactions.length === 0 ? (
            <Card className={cardBgClass}>
              <CardContent className="py-12 text-center">
                <div className={`w-16 h-16 mx-auto mb-4 rounded-full ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} flex items-center justify-center`}>
                  <History className={`w-8 h-8 ${textSecondaryClass}`} />
                </div>
                <h3 className={`text-lg font-medium ${textPrimaryClass} mb-2`}>No Transactions Yet</h3>
                <p className={textSecondaryClass}>
                  Your credit activity will appear here.
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-2">
              {transactions.map((tx) => (
                <Card key={tx.id} className={cardBgClass}>
                  <CardContent className="p-3">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-full ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} flex items-center justify-center`}>
                          {getTransactionIcon(tx.transaction_type)}
                        </div>
                        <div>
                          <p className={`text-sm font-medium ${textPrimaryClass}`}>
                            {getTransactionLabel(tx.transaction_type)}
                          </p>
                          <p className={`text-xs ${textSecondaryClass}`}>
                            {new Date(tx.created_at).toLocaleString()}
                          </p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className={`font-bold ${tx.amount >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                          {tx.amount >= 0 ? '+' : ''}{tx.amount.toFixed(2)}
                        </p>
                        <p className={`text-xs ${textSecondaryClass}`}>
                          Balance: ${tx.balance_after.toFixed(2)}
                        </p>
                      </div>
                    </div>
                    {tx.description && (
                      <p className={`text-xs ${textSecondaryClass} mt-2 ml-13`}>
                        {tx.description}
                      </p>
                    )}
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Buy Credits Modal */}
      <Dialog open={showBuyModal} onOpenChange={setShowBuyModal}>
        <DialogContent className={`${isLight ? 'bg-white' : 'bg-zinc-900'} border ${borderClass}`}>
          <DialogHeader>
            <DialogTitle className={textPrimaryClass}>Add Credits</DialogTitle>
          </DialogHeader>
          <div className="py-4">
            <p className={`text-sm ${textSecondaryClass} mb-4`}>
              Select a credit package. 1 credit = $1 USD.
            </p>
            <div className="grid grid-cols-2 gap-3">
              {creditPackages.map((pkg) => (
                <button
                  key={pkg.amount}
                  onClick={() => setSelectedAmount(pkg.amount)}
                  className={`p-4 rounded-lg border-2 transition-all relative ${
                    selectedAmount === pkg.amount
                      ? 'border-green-400 bg-green-400/10'
                      : `${borderClass} ${isLight ? 'bg-white hover:bg-gray-50' : 'bg-zinc-800/50 hover:bg-zinc-800'}`
                  }`}
                >
                  {pkg.popular && (
                    <Badge className="absolute -top-2 -right-2 bg-orange-500 text-white text-xs">
                      Popular
                    </Badge>
                  )}
                  {pkg.bestValue && (
                    <Badge className="absolute -top-2 -right-2 bg-green-500 text-white text-xs">
                      Best Value
                    </Badge>
                  )}
                  <p className={`text-2xl font-bold ${selectedAmount === pkg.amount ? 'text-green-400' : textPrimaryClass}`}>
                    {pkg.label}
                  </p>
                  <p className={`text-sm ${textSecondaryClass}`}>
                    {pkg.amount} credits
                  </p>
                  {pkg.bonus > 0 && (
                    <p className="text-xs text-green-400 mt-1">
                      +{pkg.bonus} bonus credits
                    </p>
                  )}
                </button>
              ))}
            </div>
            
            <div className={`mt-4 p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'}`}>
              <div className="flex justify-between items-center">
                <span className={textSecondaryClass}>You pay:</span>
                <span className={`text-xl font-bold ${textPrimaryClass}`}>${selectedAmount}</span>
              </div>
              <div className="flex justify-between items-center mt-1">
                <span className={textSecondaryClass}>You get:</span>
                <span className="text-xl font-bold text-green-400">
                  {selectedAmount + (creditPackages.find(p => p.amount === selectedAmount)?.bonus || 0)} credits
                </span>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowBuyModal(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleBuyCredits}
              disabled={purchasing}
              className="bg-gradient-to-r from-green-400 to-emerald-500 text-black"
            >
              {purchasing ? (
                <>
                  <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                  Processing...
                </>
              ) : (
                <>
                  <CreditCard className="w-4 h-4 mr-2" />
                  Pay ${selectedAmount}
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, useSearchParams, useLocation } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { DollarSign, CreditCard, CheckCircle, Coins, Loader2 } from 'lucide-react';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { toast } from 'sonner';
import logger from '../utils/logger';
import { isGrom } from '../lib/roles';
import { submitPurchaseRequest } from '../utils/gromPurchase';


export const Credits = () => {
  const { user, updateUser } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const [amount, setAmount] = useState(25);
  const [loading, setLoading] = useState(false);
  const [checkingStatus, setCheckingStatus] = useState(false);
  const [purchaseSuccess, setPurchaseSuccess] = useState(false);
  const [creditsAdded, setCreditsAdded] = useState(0);
  
  // Get return info from location state or localStorage
  const returnTo = location.state?.returnTo || localStorage.getItem('credits_return_to');
  const returnReason = location.state?.reason || localStorage.getItem('credits_return_reason');
  const openCrewInvite = location.state?.openCrewInvite || localStorage.getItem('credits_open_crew_invite') === 'true';
  const dispatchId = location.state?.dispatchId || localStorage.getItem('credits_dispatch_id');
  
  // Store return info when coming from another page
  useEffect(() => {
    if (location.state?.returnTo) {
      localStorage.setItem('credits_return_to', location.state.returnTo);
      localStorage.setItem('credits_return_reason', location.state.reason || '');
    }
    if (location.state?.openCrewInvite) {
      localStorage.setItem('credits_open_crew_invite', 'true');
      localStorage.setItem('credits_dispatch_id', location.state.dispatchId || '');
    }
    if (location.state?.requiredAmount) {
      setAmount(Math.ceil(location.state.requiredAmount));
    }
  }, [location.state]);

  useEffect(() => {
    const sessionId = searchParams.get('session_id');
    if (sessionId) {
      checkPaymentStatus(sessionId);
    }
  }, [searchParams]);

  const checkPaymentStatus = async (sessionId) => {
    setCheckingStatus(true);
    let attempts = 0;
    const maxAttempts = 10;

    const poll = async () => {
      if (attempts >= maxAttempts) {
        toast.error('Payment verification timeout. Please contact support.');
        setCheckingStatus(false);
        return;
      }

      try {
        const response = await apiClient.get(`/credits/status/${sessionId}`);
        if (response.data.status === 'completed') {
          setPurchaseSuccess(true);
          setCreditsAdded(response.data.credits_added || 0);
          updateUser({ credit_balance: response.data.new_balance });
          toast.success(`${response.data.credits_added} credits added to your account!`);
          setCheckingStatus(false);
        } else if (response.data.status === 'paid') {
          setPurchaseSuccess(true);
          setCheckingStatus(false);
        } else {
          attempts++;
          setTimeout(poll, 2000);
        }
      } catch (error) {
        logger.error('Error checking status:', error);
        attempts++;
        setTimeout(poll, 2000);
      }
    };

    poll();
  };

  const handlePurchase = async () => {
    if (!user) {
      toast.error('Please log in to purchase credits');
      return;
    }
    if (isGrom(user)) {
      await submitPurchaseRequest({
        gromId: user.id,
        itemType: 'credit_pack',
        itemName: `${amount} Credit Pack`,
        amount: amount
      });
      return;
    }

    if (amount < 1) {
      toast.error('Minimum purchase is 1 credit ($1)');
      return;
    }

    setLoading(true);

    try {
      const originUrl = window.location.origin;
      const response = await apiClient.post(`/credits/purchase`, {
        amount: parseFloat(amount),
        origin_url: originUrl
      });

      window.location.href = response.data.checkout_url;
    } catch (error) {
      logger.error('Error creating checkout:', error);
      toast.error(error.response?.data?.detail || 'Failed to create checkout session');
      setLoading(false);
    }
  };

  // Payment verification screen
  if (checkingStatus) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] p-4">
        <Loader2 className="w-12 h-12 text-yellow-400 animate-spin mb-4" />
        <h2 className="text-xl font-bold text-white mb-2" style={{ fontFamily: 'Oswald' }}>
          Verifying Payment
        </h2>
        <p className="text-gray-400">Please wait while we confirm your purchase...</p>
      </div>
    );
  }

  // Handle navigation after success
  const handleSuccessNavigate = () => {
    // Clear stored return info
    const savedOpenCrewInvite = localStorage.getItem('credits_open_crew_invite') === 'true';
    const savedDispatchId = localStorage.getItem('credits_dispatch_id');
    
    localStorage.removeItem('credits_return_to');
    localStorage.removeItem('credits_return_reason');
    localStorage.removeItem('credits_open_crew_invite');
    localStorage.removeItem('credits_dispatch_id');
    
    if (returnTo) {
      // Pass state to re-open crew payment modal if needed
      if (openCrewInvite || savedOpenCrewInvite) {
        navigate(returnTo, { 
          state: { 
            openCrewInvite: true, 
            dispatchId: dispatchId || savedDispatchId 
          } 
        });
      } else {
        navigate(returnTo);
      }
    } else {
      navigate('/feed');
    }
  };

  // Success screen
  if (purchaseSuccess) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] p-4 text-center">
        <div className="w-20 h-20 rounded-full bg-emerald-500/20 flex items-center justify-center mb-6">
          <CheckCircle className="w-10 h-10 text-emerald-400" />
        </div>
        <h2 className="text-3xl font-bold text-white mb-2" style={{ fontFamily: 'Oswald' }}>
          Purchase Complete!
        </h2>
        <p className="text-gray-400 mb-6">
          {creditsAdded > 0 ? `${creditsAdded} credits have been added to your account` : 'Your credits have been added'}
        </p>
        <div className="bg-zinc-800 rounded-xl p-6 mb-6">
          <div className="text-gray-400 text-sm mb-1">New Balance</div>
          <div className="text-4xl font-bold text-yellow-400">${(user?.credit_balance || 0).toFixed(2)}</div>
        </div>
        <Button
          onClick={handleSuccessNavigate}
          className="bg-gradient-to-r from-yellow-400 to-orange-400 text-black font-bold"
        >
          {returnReason === 'crew_session_payment' ? 'Complete Your Booking' : 'Back to Feed'}
        </Button>
      </div>
    );
  }

  const packages = [
    { amount: 10, bonus: 0 },
    { amount: 25, bonus: 0 },
    { amount: 50, bonus: 5 },
    { amount: 100, bonus: 15 },
  ];

  return (
    <div className="p-4 md:p-8 max-w-2xl mx-auto" data-testid="credits-page">
      {/* Header */}
      <div className="text-center mb-8">
        <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-gradient-to-r from-yellow-400 to-orange-400 flex items-center justify-center">
          <Coins className="w-8 h-8 text-black" />
        </div>
        <h1 className="text-3xl font-bold text-white mb-2" style={{ fontFamily: 'Oswald' }}>
          Buy Credits
        </h1>
        <p className="text-gray-400">1 Credit = $1 USD • Use for sessions, tips, and more</p>
      </div>

      {/* Current Balance */}
      <div className="bg-zinc-900 rounded-xl p-6 mb-6 border border-zinc-800">
        <div className="flex items-center justify-between">
          <div>
            <div className="text-gray-400 text-sm">Current Balance</div>
            <div className="text-3xl font-bold text-white">${(user?.credit_balance || 0).toFixed(2)}</div>
          </div>
          <div className="w-12 h-12 rounded-full bg-yellow-400/20 flex items-center justify-center">
            <DollarSign className="w-6 h-6 text-yellow-400" />
          </div>
        </div>
      </div>

      {/* Quick Packages */}
      <div className="mb-6">
        <h3 className="text-lg font-bold text-white mb-4" style={{ fontFamily: 'Oswald' }}>
          Quick Packages
        </h3>
        <div className="grid grid-cols-2 gap-3">
          {packages.map((pkg) => (
            <button
              key={pkg.amount}
              onClick={() => setAmount(pkg.amount)}
              className={`relative p-4 rounded-xl border-2 transition-all ${
                amount === pkg.amount
                  ? 'border-yellow-400 bg-yellow-400/10'
                  : 'border-zinc-700 bg-zinc-800 hover:border-zinc-600'
              }`}
              data-testid={`package-${pkg.amount}`}
            >
              {pkg.bonus > 0 && (
                <div className="absolute -top-2 -right-2 px-2 py-0.5 bg-emerald-500 rounded-full text-xs font-bold text-white">
                  +{pkg.bonus} FREE
                </div>
              )}
              <div className="text-2xl font-bold text-white">${pkg.amount}</div>
              <div className="text-sm text-gray-400">
                {pkg.amount} credits{pkg.bonus > 0 ? ` + ${pkg.bonus} bonus` : ''}
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Custom Amount */}
      <div className="bg-zinc-900 rounded-xl p-4 mb-6 border border-zinc-800">
        <h3 className="text-sm font-medium text-gray-400 mb-3">Custom Amount</h3>
        <div className="flex gap-3">
          <div className="relative flex-1">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">$</span>
            <Input
              type="number"
              min="1"
              step="1"
              value={amount}
              onChange={(e) => setAmount(Math.max(1, parseInt(e.target.value) || 1))}
              className="pl-8 bg-zinc-800 border-zinc-700 text-white h-12"
              data-testid="custom-amount-input"
            />
          </div>
        </div>
      </div>

      {/* Purchase Button */}
      <Button
        onClick={handlePurchase}
        disabled={loading || amount < 1}
        className="w-full h-14 text-lg bg-gradient-to-r from-emerald-400 via-yellow-400 to-orange-400 hover:from-emerald-500 hover:via-yellow-500 hover:to-orange-500 text-black font-bold"
        data-testid="purchase-credits-button"
      >
        {loading ? (
          <Loader2 className="w-5 h-5 animate-spin" />
        ) : (
          <>
            <CreditCard className="w-5 h-5 mr-2" />
            Purchase {amount} Credits for ${amount}
          </>
        )}
      </Button>

      {/* Footer */}
      <p className="text-center text-gray-500 text-sm mt-4">
        Secure payment powered by Stripe
      </p>
    </div>
  );
};

﻿import React, { useState, useEffect, useMemo } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { DollarSign, Clock, CheckCircle2, AlertTriangle, 
  Send, Calculator, Loader2, Shield, Wallet, ArrowRight, Crown, Timer, Bell, MessageCircle
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Progress } from './ui/progress';
import { Input } from './ui/input';
import { Switch } from './ui/switch';
import { Slider } from './ui/slider';
import { Card, CardHeader, CardTitle, CardContent } from './ui/card';
import { toast } from 'sonner';
import logger from '../utils/logger';


/**
 * CrewHub - Captain's Command Center for Split Bookings
 * 
 * Features:
 * - Granular payment control: custom percentages per crew member
 * - "Paid by Me" toggle for Captain to cover specific members
 * - Real-time balance calculation with remaining balance display
 * - Payment window countdown (60min On-Demand / 24hr Scheduled)
 * - 1-click nudge for reminders via OneSignal
 */

export const CrewHub = ({ 
  booking, 
  crewMembers: initialCrew = [], 
  totalPrice,
  onUpdate,
  onPaymentComplete,
  isCheckoutMode = false  // True when in checkout flow, false when viewing existing booking
}) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  const isLight = theme === 'light';
  
  // Crew state with custom split data
  const [crewMembers, setCrewMembers] = useState(initialCrew);
  const [loading, setLoading] = useState(false);
  const [savingSplits, setSavingSplits] = useState(false);
  const [sendingNudge, setSendingNudge] = useState(null);
  
  // Captain's view state
  const isCaptain = booking?.creator_id === user?.id || isCheckoutMode;
  const bookingTotal = totalPrice || booking?.total_price || 0;
  
  // Payment window countdown
  const [timeRemaining, setTimeRemaining] = useState(null);
  const paymentWindowExpires = booking?.payment_window_expires_at;
  
  // Computed values
  const totalCrew = crewMembers.length + 1; // +1 for captain
  const equalShare = bookingTotal / totalCrew;
  
  // Calculate totals from custom splits
  const assignedTotal = useMemo(() => {
    return crewMembers.reduce((sum, m) => sum + (m.share_amount || equalShare), 0);
  }, [crewMembers, equalShare]);
  
  const captainShare = useMemo(() => {
    // Captain pays: their share + any covered members
    const captainBase = bookingTotal - assignedTotal;
    const coveredAmount = crewMembers
      .filter(m => m.covered_by_captain)
      .reduce((sum, m) => sum + (m.share_amount || equalShare), 0);
    return Math.max(0, captainBase + coveredAmount);
  }, [bookingTotal, assignedTotal, crewMembers, equalShare]);
  
  const remainingBalance = useMemo(() => {
    const paid = crewMembers.reduce((sum, m) => 
      sum + (m.payment_status === 'Paid' || m.covered_by_captain ? (m.share_amount || equalShare) : 0), 0
    );
    const captainPaid = booking?.captain_hold_paid ? captainShare : 0;
    return bookingTotal - paid - captainPaid;
  }, [crewMembers, bookingTotal, captainShare, equalShare, booking?.captain_hold_paid]);
  
  const paidCount = crewMembers.filter(m => m.payment_status === 'Paid' || m.covered_by_captain).length;
  const pendingCount = crewMembers.filter(m => m.payment_status === 'Pending' && !m.covered_by_captain).length;
  const paymentProgress = totalCrew > 0 ? ((paidCount + (booking?.captain_hold_paid ? 1 : 0)) / totalCrew) * 100 : 0;

  // Update countdown timer
  useEffect(() => {
    if (!paymentWindowExpires) return;
    
    const updateTimer = () => {
      const now = new Date();
      const expires = new Date(paymentWindowExpires);
      const diff = expires - now;
      
      if (diff <= 0) {
        setTimeRemaining({ expired: true });
      } else {
        const hours = Math.floor(diff / (1000 * 60 * 60));
        const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        const seconds = Math.floor((diff % (1000 * 60)) / 1000);
        setTimeRemaining({ hours, minutes, seconds, expired: false });
      }
    };
    
    updateTimer();
    const interval = setInterval(updateTimer, 1000);
    return () => clearInterval(interval);
  }, [paymentWindowExpires]);

  // Fetch crew status for existing bookings
  useEffect(() => {
    if (booking?.id && !isCheckoutMode) {
      fetchCrewStatus();
    }
  }, [booking?.id, isCheckoutMode]);

  const fetchCrewStatus = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(`/bookings/${booking.id}/crew-hub-status?captain_id=${user.id}`);
      setCrewMembers(response.data?.crew || []);
    } catch (error) {
      logger.error('Failed to fetch crew status:', error);
    } finally {
      setLoading(false);
    }
  };

  // Handle percentage slider change
  const handlePercentageChange = (memberId, percentage) => {
    const newAmount = (percentage / 100) * bookingTotal;
    setCrewMembers(prev => prev.map(m => 
      m.id === memberId || m.participant_id === memberId
        ? { ...m, share_percentage: percentage, share_amount: newAmount }
        : m
    ));
  };

  // Handle direct amount input
  const handleAmountChange = (memberId, amount) => {
    const numAmount = parseFloat(amount) || 0;
    const percentage = (numAmount / bookingTotal) * 100;
    setCrewMembers(prev => prev.map(m => 
      m.id === memberId || m.participant_id === memberId
        ? { ...m, share_amount: numAmount, share_percentage: percentage }
        : m
    ));
  };

  // Handle "Paid by Me" toggle
  const handleCoverToggle = (memberId, covered) => {
    setCrewMembers(prev => prev.map(m => 
      m.id === memberId || m.participant_id === memberId
        ? { ...m, covered_by_captain: covered, payment_status: covered ? 'Paid' : 'Pending' }
        : m
    ));
  };

  // Save custom splits to backend
  const handleSaveSplits = async () => {
    // Validate total
    const totalAssigned = crewMembers.reduce((sum, m) => sum + (m.share_amount || 0), 0) + captainShare;
    if (Math.abs(totalAssigned - bookingTotal) > 0.01) {
      toast.error(`Split amounts must equal $${bookingTotal.toFixed(2)}. Current: $${totalAssigned.toFixed(2)}`);
      return;
    }

    setSavingSplits(true);
    try {
      await apiClient.post(`/bookings/${booking.id}/crew-hub/update-splits`, {
        captain_id: user.id,
        splits: crewMembers.map(m => ({
          participant_id: m.participant_id || m.id,
          share_amount: m.share_amount || equalShare,
          share_percentage: m.share_percentage || (100 / totalCrew),
          covered_by_captain: m.covered_by_captain || false
        })),
        captain_share: captainShare
      });
      toast.success('Payment splits updated!');
      onUpdate?.();
    } catch (error) {
      toast.error('Failed to update splits');
    } finally {
      setSavingSplits(false);
    }
  };

  // Send nudge to pending member
  const handleNudge = async (memberId) => {
    setSendingNudge(memberId);
    try {
      await apiClient.post(`/bookings/${booking.id}/nudge`, {
        participant_id: memberId,
        captain_id: user.id
      });
      toast.success('Reminder sent!');
    } catch (error) {
      toast.error('Failed to send reminder');
    } finally {
      setSendingNudge(null);
    }
  };

  // Nudge all pending members
  const handleNudgeAll = async () => {
    const pendingIds = crewMembers
      .filter(m => m.payment_status === 'Pending' && !m.covered_by_captain)
      .map(m => m.participant_id || m.id);
    
    if (pendingIds.length === 0) {
      toast.info('All crew members have paid!');
      return;
    }

    setSendingNudge('all');
    try {
      await apiClient.post(`/bookings/${booking.id}/nudge-all`, {
        captain_id: user.id
      });
      toast.success(`Reminders sent to ${pendingIds.length} crew members!`);
    } catch (error) {
      toast.error('Failed to send reminders');
    } finally {
      setSendingNudge(null);
    }
  };

  // Captain covers remaining balance
  const handleCoverRemaining = async () => {
    if (!window.confirm(`Cover the remaining $${remainingBalance.toFixed(2)} for your crew?`)) return;
    
    setLoading(true);
    try {
      await apiClient.post(`/bookings/${booking.id}/crew-hub/captain-cover-remaining`, {
        captain_id: user.id,
        cover_amount: remainingBalance
      });
      toast.success('You covered the remaining balance! Session confirmed.');
      fetchCrewStatus();
      onUpdate?.();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to cover balance');
    } finally {
      setLoading(false);
    }
  };

  // Distribute evenly
  const handleDistributeEvenly = () => {
    const evenShare = bookingTotal / totalCrew;
    const evenPercentage = 100 / totalCrew;
    setCrewMembers(prev => prev.map(m => ({
      ...m,
      share_amount: evenShare,
      share_percentage: evenPercentage,
      covered_by_captain: false
    })));
    toast.info(`Set to even split: $${evenShare.toFixed(2)} each`);
  };

  if (!isCaptain && !isCheckoutMode) {
    return null; // Only captain sees the hub
  }

  return (
    <Card className={`${isLight ? 'bg-white border-gray-200' : 'bg-zinc-900/50 border-zinc-800'}`} data-testid="crew-hub">
      <CardHeader className="pb-2">
        <CardTitle className={`text-lg flex items-center justify-between ${isLight ? 'text-gray-900' : 'text-white'}`}>
          <div className="flex items-center gap-2">
            <Crown className="w-5 h-5 text-yellow-400" />
            Crew Hub
            <Badge className="bg-gradient-to-r from-yellow-400 to-orange-400 text-black text-xs">
              Captain
            </Badge>
          </div>
          {booking?.id && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => navigate(`/bookings/${booking.id}/chat`)}
              className={`flex items-center gap-1.5 ${isLight ? 'border-cyan-500 text-cyan-600 hover:bg-cyan-50' : 'border-cyan-500/50 text-cyan-400 hover:bg-cyan-500/10'}`}
              data-testid="crew-hub-chat-btn"
            >
              <MessageCircle className="w-4 h-4" />
              Chat
            </Button>
          )}
        </CardTitle>
      </CardHeader>
      
      <CardContent className="space-y-4">
        {/* Payment Window Countdown */}
        {paymentWindowExpires && !booking?.payment_window_expired && (
          <div className={`p-3 rounded-lg flex items-center justify-between ${
            timeRemaining?.expired 
              ? (isLight ? 'bg-red-50 border border-red-200' : 'bg-red-500/10 border border-red-500/30')
              : (isLight ? 'bg-amber-50 border border-amber-200' : 'bg-amber-500/10 border border-amber-500/30')
          }`}>
            <div className="flex items-center gap-2">
              <Timer className={`w-5 h-5 ${timeRemaining?.expired ? 'text-red-500' : 'text-amber-500'}`} />
              <div>
                <p className={`text-sm font-medium ${isLight ? 'text-gray-900' : 'text-white'}`}>
                  {timeRemaining?.expired ? 'Payment Window Expired' : 'Crew Payment Window'}
                </p>
                <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
                  {booking?.booking_type === 'on_demand' ? '60-minute window' : '24-hour window'}
                </p>
              </div>
            </div>
            {!timeRemaining?.expired && timeRemaining && (
              <div className="text-right">
                <p className={`text-lg font-bold font-mono ${isLight ? 'text-amber-600' : 'text-amber-400'}`}>
                  {String(timeRemaining.hours).padStart(2, '0')}:
                  {String(timeRemaining.minutes).padStart(2, '0')}:
                  {String(timeRemaining.seconds).padStart(2, '0')}
                </p>
              </div>
            )}
          </div>
        )}

        {/* Real-Time Balance Summary */}
        <div className={`p-4 rounded-xl ${isLight ? 'bg-gradient-to-br from-cyan-50 to-blue-50' : 'bg-gradient-to-br from-cyan-500/10 to-blue-500/10'} border border-cyan-400/30`}>
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Wallet className="w-5 h-5 text-cyan-400" />
              <span className={`font-bold ${isLight ? 'text-gray-900' : 'text-white'}`}>Session Total</span>
            </div>
            <span className="text-2xl font-bold text-cyan-400">${bookingTotal.toFixed(2)}</span>
          </div>
          
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className={isLight ? 'text-gray-600' : 'text-gray-400'}>Your Share (Captain)</span>
              <span className={`font-medium ${isLight ? 'text-gray-900' : 'text-white'}`}>${captainShare.toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className={isLight ? 'text-gray-600' : 'text-gray-400'}>Crew ({crewMembers.length})</span>
              <span className={`font-medium ${isLight ? 'text-gray-900' : 'text-white'}`}>${assignedTotal.toFixed(2)}</span>
            </div>
            <div className={`flex justify-between text-sm pt-2 border-t ${isLight ? 'border-cyan-200' : 'border-cyan-500/30'}`}>
              <span className={`font-medium ${remainingBalance > 0 ? 'text-amber-500' : 'text-green-500'}`}>
                {remainingBalance > 0 ? 'Remaining Balance' : 'Fully Covered'}
              </span>
              <span className={`font-bold ${remainingBalance > 0 ? 'text-amber-500' : 'text-green-500'}`}>
                ${remainingBalance.toFixed(2)}
              </span>
            </div>
          </div>
          
          {/* Progress Bar */}
          <div className="mt-3">
            <Progress value={paymentProgress} className="h-2" />
            <p className={`text-xs mt-1 ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
              {paidCount + (booking?.captain_hold_paid ? 1 : 0)}/{totalCrew} paid
            </p>
          </div>
        </div>

        {/* Quick Actions */}
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={handleDistributeEvenly}
            className={`flex-1 ${isLight ? 'border-gray-300' : 'border-zinc-600'}`}
          >
            <Calculator className="w-4 h-4 mr-1" />
            Even Split
          </Button>
          {pendingCount > 0 && (
            <Button
              size="sm"
              variant="outline"
              onClick={handleNudgeAll}
              disabled={sendingNudge === 'all'}
              className={`flex-1 ${isLight ? 'border-cyan-300 text-cyan-700' : 'border-cyan-500/50 text-cyan-400'}`}
            >
              {sendingNudge === 'all' ? <Loader2 className="w-4 h-4 animate-spin mr-1" /> : <Bell className="w-4 h-4 mr-1" />}
              Nudge All
            </Button>
          )}
        </div>

        {/* Crew Members with Granular Controls */}
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 animate-spin text-cyan-400" />
          </div>
        ) : (
          <div className="space-y-3">
            <h4 className={`text-sm font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>
              Crew Payment Controls
            </h4>
            
            {crewMembers.map((member, idx) => {
              const memberId = member.participant_id || member.id;
              const memberShare = member.share_amount || equalShare;
              const memberPercentage = member.share_percentage || (100 / totalCrew);
              const isPaid = member.payment_status === 'Paid';
              const isCovered = member.covered_by_captain;
              
              return (
                <div 
                  key={memberId}
                  className={`p-4 rounded-xl ${isLight ? 'bg-gray-50 border border-gray-100' : 'bg-zinc-800/50 border border-zinc-700/50'}`}
                  data-testid={`crew-member-${idx}`}
                >
                  {/* Member Header */}
                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${
                        isPaid || isCovered
                          ? 'bg-green-500/20 text-green-400'
                          : 'bg-amber-500/20 text-amber-400'
                      }`}>
                        {member.name?.charAt(0) || member.value?.charAt(0) || 'C'}
                      </div>
                      <div>
                        <p className={`text-sm font-medium ${isLight ? 'text-gray-900' : 'text-white'}`}>
                          {member.name || member.value || `Crew ${idx + 1}`}
                        </p>
                        <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
                          {member.email || member.type === 'email' ? 'Email invite' : 'Username invite'}
                        </p>
                      </div>
                    </div>
                    
                    <div className="flex items-center gap-2">
                      {isPaid ? (
                        <Badge className="bg-green-500/20 text-green-400">
                          <CheckCircle2 className="w-3 h-3 mr-1" />
                          Paid
                        </Badge>
                      ) : isCovered ? (
                        <Badge className="bg-purple-500/20 text-purple-400">
                          <Shield className="w-3 h-3 mr-1" />
                          You Covered
                        </Badge>
                      ) : (
                        <>
                          <Badge className="bg-amber-500/20 text-amber-400">
                            <Clock className="w-3 h-3 mr-1" />
                            Pending
                          </Badge>
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => handleNudge(memberId)}
                            disabled={sendingNudge === memberId}
                            className="p-1 h-7"
                          >
                            {sendingNudge === memberId ? (
                              <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                              <Send className="w-4 h-4 text-cyan-400" />
                            )}
                          </Button>
                        </>
                      )}
                    </div>
                  </div>

                  {/* Payment Controls (only show for unpaid members) */}
                  {!isPaid && (
                    <div className="space-y-3">
                      {/* Percentage Slider */}
                      <div>
                        <div className="flex items-center justify-between mb-1">
                          <span className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
                            Share: {memberPercentage.toFixed(1)}%
                          </span>
                          <span className={`text-sm font-bold ${isLight ? 'text-gray-900' : 'text-white'}`}>
                            ${memberShare.toFixed(2)}
                          </span>
                        </div>
                        <Slider
                          value={[memberPercentage]}
                          onValueChange={([val]) => handlePercentageChange(memberId, val)}
                          max={100}
                          step={1}
                          disabled={isCovered}
                          className="cursor-pointer"
                        />
                      </div>

                      {/* Direct Amount Input */}
                      <div className="flex items-center gap-2">
                        <span className={`text-sm ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>Or set amount:</span>
                        <div className="flex items-center gap-1 flex-1">
                          <DollarSign className="w-4 h-4 text-gray-400" />
                          <Input
                            type="number"
                            step="0.01"
                            min="0"
                            max={bookingTotal}
                            value={memberShare.toFixed(2)}
                            onChange={(e) => handleAmountChange(memberId, e.target.value)}
                            disabled={isCovered}
                            className={`h-8 w-24 ${isLight ? 'bg-white' : 'bg-zinc-900 border-zinc-600'}`}
                          />
                        </div>
                      </div>

                      {/* "Paid by Me" Toggle */}
                      <div className={`flex items-center justify-between p-2 rounded-lg ${isLight ? 'bg-purple-50' : 'bg-purple-500/10'}`}>
                        <div className="flex items-center gap-2">
                          <Shield className="w-4 h-4 text-purple-400" />
                          <span className={`text-sm ${isLight ? 'text-purple-700' : 'text-purple-300'}`}>
                            I'll cover this member
                          </span>
                        </div>
                        <Switch
                          checked={isCovered}
                          onCheckedChange={(checked) => handleCoverToggle(memberId, checked)}
                          className="data-[state=checked]:bg-purple-500"
                        />
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex flex-col gap-2 pt-2">
          {/* Save Splits */}
          {booking?.id && (
            <Button
              onClick={handleSaveSplits}
              disabled={savingSplits}
              className="w-full bg-cyan-500 hover:bg-cyan-400 text-black"
            >
              {savingSplits ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <CheckCircle2 className="w-4 h-4 mr-2" />}
              Save Payment Splits
            </Button>
          )}
          
          {/* Cover Remaining (only if there's remaining balance) */}
          {remainingBalance > 0 && booking?.id && (
            <Button
              onClick={handleCoverRemaining}
              disabled={loading}
              variant="outline"
              className={`w-full ${isLight ? 'border-purple-300 text-purple-700' : 'border-purple-500/50 text-purple-400'}`}
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Wallet className="w-4 h-4 mr-2" />}
              Cover Remaining ${remainingBalance.toFixed(2)}
            </Button>
          )}
          
          {/* Proceed to Payment (checkout mode) */}
          {isCheckoutMode && onPaymentComplete && (
            <Button
              onClick={() => onPaymentComplete({ crewMembers, captainShare })}
              className="w-full bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black font-bold"
            >
              <ArrowRight className="w-4 h-4 mr-2" />
              Confirm & Pay ${captainShare.toFixed(2)}
            </Button>
          )}
        </div>

        {/* Payment Locked Message */}
        {paymentProgress < 100 && booking?.id && !isCheckoutMode && (
          <div className={`p-3 rounded-lg ${isLight ? 'bg-amber-50 border border-amber-200' : 'bg-amber-500/10 border border-amber-500/30'}`}>
            <p className={`text-sm ${isLight ? 'text-amber-700' : 'text-amber-400'} flex items-center gap-2`}>
              <AlertTriangle className="w-4 h-4" />
              Session locked until all crew payments complete. Photographer cannot see this booking yet.
            </p>
          </div>
        )}

        {/* All Paid Confirmation */}
        {paymentProgress === 100 && (
          <div className={`p-3 rounded-lg ${isLight ? 'bg-green-50 border border-green-200' : 'bg-green-500/10 border border-green-500/30'}`}>
            <p className={`text-sm ${isLight ? 'text-green-700' : 'text-green-400'} flex items-center gap-2`}>
              <CheckCircle2 className="w-4 h-4" />
              All payments received! Session is confirmed and visible to photographer.
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

