};

/**
 * Crew Card Component
 */
const CrewCard = ({ crew, onClick, isLight }) => {
  const cardBg = isLight ? 'bg-white' : 'bg-zinc-800/50';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  
  return (
    <Card 
      className={`${cardBg} cursor-pointer hover:ring-2 ring-cyan-500/50 transition-all`}
      onClick={onClick}
      data-testid={`crew-card-${crew.crew_hash || crew.id}`}
    >
      <CardContent className="p-4">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            {/* Member Avatars Stack */}
            <div className="flex -space-x-2">
              {crew.members?.slice(0, 4).map((member, idx) => (
                <div 
                  key={member.user_id} 
                  className="w-8 h-8 rounded-full border-2 border-black bg-gradient-to-br from-cyan-400 to-blue-500 flex items-center justify-center overflow-hidden"
                  style={{ zIndex: 4 - idx }}
                >
                  {member.avatar_url ? (
                    <img src={getFullUrl(member.avatar_url)} alt={member.full_name} className="w-full h-full object-cover" />
                  ) : (
                    <span className="text-white text-xs font-bold">
                      {member.full_name?.charAt(0) || '?'}
                    </span>
                  )}
                </div>
              ))}
              {crew.members?.length > 4 && (
                <div className="w-8 h-8 rounded-full border-2 border-black bg-zinc-700 flex items-center justify-center text-xs text-gray-300">
                  +{crew.members.length - 4}
                </div>
              )}
            </div>
            <div>
              <p className={`font-medium ${textPrimary}`}>{crew.name || 'Unnamed Crew'}</p>
              <p className={`text-xs ${textSecondary}`}>
                {crew.crew_size || crew.members?.length || 0} surfers
              </p>
            </div>
          </div>
          
          {!crew.is_public && (
            <Lock className="w-4 h-4 text-gray-500" />
          )}
        </div>
        
        {/* Stats Row */}
        <div className="grid grid-cols-3 gap-2 mb-3">
          <div className="text-center">
            <p className="text-lg font-bold text-cyan-400">{crew.total_sessions || 0}</p>
            <p className={`text-xs ${textSecondary}`}>Sessions</p>
          </div>
          <div className="text-center">
            <p className="text-lg font-bold text-green-400">${(crew.total_money_saved || 0).toFixed(0)}</p>
            <p className={`text-xs ${textSecondary}`}>Saved</p>
          </div>
          <div className="text-center">
            <p className="text-lg font-bold text-yellow-400">{crew.badges_count || 0}</p>
            <p className={`text-xs ${textSecondary}`}>Badges</p>
          </div>
        </div>
        
        <ChevronRight className={`w-4 h-4 ${textSecondary} ml-auto`} />
      </CardContent>
    </Card>
  );
};

/**
 * Leaderboard Entry Component
 */
const LeaderboardEntry = ({ entry, isLight }) => {
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  
  const rankColors = {
    1: 'text-yellow-400',
    2: 'text-gray-300',
    3: 'text-amber-600'
  };
  
  return (
    <div className={`flex items-center gap-3 p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800/50'}`}>
      {/* Rank */}
      <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold ${
        entry.rank <= 3 
          ? `${rankColors[entry.rank]} bg-zinc-900` 
          : `${textSecondary} bg-zinc-800`
      }`}>
        {entry.rank <= 3 ? (
          <Trophy className="w-4 h-4" />
        ) : (
          entry.rank
        )}
      </div>
      
      {/* Crew Info */}
      <div className="flex-1">
        <div className="flex items-center gap-2">
          <div className="flex -space-x-1">
            {entry.members?.slice(0, 3).map((m, _idx) => (
              <div 
                key={m.user_id}
                className="w-6 h-6 rounded-full border border-black bg-gradient-to-br from-cyan-400 to-blue-500 flex items-center justify-center overflow-hidden"
              >
                {m.avatar_url ? (
                  <img src={getFullUrl(m.avatar_url)} alt="" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-white text-xs">{m.full_name?.charAt(0)}</span>
                )}
              </div>
            ))}
          </div>
          <p className={`font-medium ${textPrimary} text-sm`}>{entry.crew_name || 'Crew'}</p>
        </div>
      </div>
      
      {/* Metric Value */}
      <div className="text-right">
        <p className="font-bold text-cyan-400">
          {entry.metric_name?.includes('money') || entry.metric_name?.includes('saved') 
            ? `$${entry.metric_value?.toFixed(0)}` 
            : entry.metric_value}
        </p>
        <p className={`text-xs ${textSecondary}`}>{entry.metric_name}</p>
      </div>
    </div>
  );
};

/**
 * Main Crew Leaderboard Component
 */
export const CrewLeaderboard = ({ 
  userId, 
  variant = 'full',  // 'full', 'compact', 'profile'
  showPrivacyControls = false
}) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';
  
  const [activeTab, setActiveTab] = useState('my-crews');
  const [leaderboardMetric, setLeaderboardMetric] = useState('total_sessions');
  const [userSummary, setUserSummary] = useState(null);
  const [leaderboard, setLeaderboard] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedCrew, setSelectedCrew] = useState(null);
  const [showCrewDetail, setShowCrewDetail] = useState(false);
  
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  const cardBg = isLight ? 'bg-white' : 'bg-zinc-900';
  
  const targetUserId = userId || user?.id;
  
  useEffect(() => {
    if (targetUserId) {
      fetchData();
    }
  }, [targetUserId, leaderboardMetric]);
  
  const fetchData = async () => {
    setLoading(true);
    try {
      const [summaryRes, leaderboardRes] = await Promise.all([
        apiClient.get(`/users/${targetUserId}/crew-summary`),
        apiClient.get(`/crew/leaderboard?metric=${leaderboardMetric}&limit=20`)
      ]);
      
      setUserSummary(summaryRes.data);
      setLeaderboard(leaderboardRes.data.leaderboard || []);
    } catch (error) {
      logger.error('Failed to fetch crew data:', error);
    } finally {
      setLoading(false);
    }
  };
  
  const handleCrewClick = async (crew) => {
    try {
      const res = await apiClient.get(`/crew/stats/${crew.crew_hash}`);
      setSelectedCrew(res.data);
      setShowCrewDetail(true);
    } catch (error) {
      if (error.response?.status === 403) {
        toast.error("This crew's stats are private");
      } else {
        toast.error("Failed to load crew details");
      }
    }
  };
  
  const handlePrivacyToggle = async (crewHash, isPublic) => {
    try {
      await apiClient.put(`/crew/${crewHash}/settings`, {
        is_public: isPublic
      });
      toast.success(`Crew is now ${isPublic ? 'public' : 'private'}`);
      fetchData();
    } catch (error) {
      toast.error('Failed to update privacy');
    }
  };
  
  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-400"></div>
      </div>
    );
  }
  
  // Compact variant for embedding in other components
  if (variant === 'compact') {
    return (
      <div className="space-y-3">
        {/* Quick Stats */}
        <div className="grid grid-cols-3 gap-2">
          <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} text-center`}>
            <Users className="w-5 h-5 mx-auto mb-1 text-cyan-400" />
            <p className="text-lg font-bold text-cyan-400">{userSummary?.total_crew_sessions || 0}</p>
            <p className={`text-xs ${textSecondary}`}>Crew Sessions</p>
          </div>
          <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} text-center`}>
            <DollarSign className="w-5 h-5 mx-auto mb-1 text-green-400" />
            <p className="text-lg font-bold text-green-400">${(userSummary?.total_saved_via_splits || 0).toFixed(0)}</p>
            <p className={`text-xs ${textSecondary}`}>Saved</p>
          </div>
          <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} text-center`}>
            <Medal className="w-5 h-5 mx-auto mb-1 text-yellow-400" />
            <p className="text-lg font-bold text-yellow-400">{userSummary?.badges?.length || 0}</p>
            <p className={`text-xs ${textSecondary}`}>Badges</p>
          </div>
        </div>
        
        {/* Badges Preview */}
        {userSummary?.badges?.length > 0 && (
          <div className="flex flex-wrap gap-2 justify-center">
            {userSummary.badges.slice(0, 4).map((badge, idx) => (
              <BadgeCard key={idx} badge={badge} size="sm" />
            ))}
          </div>
        )}
      </div>
    );
  }
  
  // Profile variant - slightly more detail
  if (variant === 'profile') {
    return (
      <Card className={cardBg}>
        <CardHeader className="pb-2">
          <CardTitle className={`text-lg flex items-center gap-2 ${textPrimary}`}>
            <Users className="w-5 h-5 text-cyan-400" />
            Crew Stats
          </CardTitle>
        </CardHeader>
        <CardContent>
          {/* Stats Grid */}
          <div className="grid grid-cols-3 gap-3 mb-4">
            <div className="text-center">
              <p className="text-2xl font-bold text-cyan-400">{userSummary?.total_crew_sessions || 0}</p>
              <p className={`text-xs ${textSecondary}`}>Sessions</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-green-400">{userSummary?.total_unique_buddies || 0}</p>
              <p className={`text-xs ${textSecondary}`}>Buddies</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-yellow-400">${(userSummary?.total_saved_via_splits || 0).toFixed(0)}</p>
              <p className={`text-xs ${textSecondary}`}>Saved</p>
            </div>
          </div>
          
          {/* Favorite Buddy */}
          {userSummary?.favorite_buddy && (
            <div className={`flex items-center gap-3 p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} mb-4`}>
              <Crown className="w-5 h-5 text-yellow-400" />
              <div className="flex items-center gap-2 flex-1">
                <div className="w-8 h-8 rounded-full bg-gradient-to-br from-cyan-400 to-blue-500 flex items-center justify-center overflow-hidden">
                  {userSummary.favorite_buddy.avatar_url ? (
                    <img src={getFullUrl(userSummary.favorite_buddy.avatar_url)} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <span className="text-white text-sm">{userSummary.favorite_buddy.full_name?.charAt(0)}</span>
                  )}
                </div>
                <div>
                  <p className={`text-sm font-medium ${textPrimary}`}>{userSummary.favorite_buddy.full_name}</p>
                  <p className={`text-xs ${textSecondary}`}>Favorite Buddy</p>
                </div>
              </div>
            </div>
          )}
          
          {/* Badges */}
          {userSummary?.badges?.length > 0 && (
            <div>
              <p className={`text-sm font-medium ${textSecondary} mb-2`}>Badges Earned</p>
              <div className="flex flex-wrap gap-3 justify-center">
                {userSummary.badges.map((badge, idx) => (
                  <BadgeCard key={idx} badge={badge} size="md" />
                ))}
              </div>
            </div>
          )}
          
          {/* Top Crews */}
          {userSummary?.top_crews?.length > 0 && (
            <div className="mt-4">
              <p className={`text-sm font-medium ${textSecondary} mb-2`}>Your Top Crews</p>
              <div className="space-y-2">
                {userSummary.top_crews.slice(0, 3).map((crew, idx) => (
                  <CrewCard 
                    key={idx} 
                    crew={crew} 
                    isLight={isLight}
                    onClick={() => handleCrewClick(crew)}
                  />
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    );
  }
  
  // Full variant - complete leaderboard experience
  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h2 className={`text-xl font-bold ${textPrimary} flex items-center gap-2`}>
          <Trophy className="w-6 h-6 text-yellow-400" />
          Crew Leaderboard
        </h2>
      </div>
      
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="w-full">
          <TabsTrigger value="my-crews" className="flex-1">My Crews</TabsTrigger>
          <TabsTrigger value="leaderboard" className="flex-1">Leaderboard</TabsTrigger>
          <TabsTrigger value="badges" className="flex-1">Badges</TabsTrigger>
        </TabsList>
        
        {/* My Crews Tab */}
        <TabsContent value="my-crews" className="space-y-4">
          {/* Personal Stats */}
          <Card className={cardBg}>
            <CardContent className="p-4">
              <div className="grid grid-cols-3 gap-4">
                <div className="text-center">
                  <Users className="w-6 h-6 mx-auto mb-1 text-cyan-400" />
                  <p className="text-2xl font-bold text-cyan-400">{userSummary?.total_crew_sessions || 0}</p>
                  <p className={`text-xs ${textSecondary}`}>Crew Sessions</p>
                </div>
                <div className="text-center">
                  <Star className="w-6 h-6 mx-auto mb-1 text-purple-400" />
                  <p className="text-2xl font-bold text-purple-400">{userSummary?.total_unique_buddies || 0}</p>
                  <p className={`text-xs ${textSecondary}`}>Unique Buddies</p>
                </div>
                <div className="text-center">
                  <DollarSign className="w-6 h-6 mx-auto mb-1 text-green-400" />
                  <p className="text-2xl font-bold text-green-400">${(userSummary?.total_saved_via_splits || 0).toFixed(0)}</p>
                  <p className={`text-xs ${textSecondary}`}>Total Saved</p>
                </div>
              </div>
            </CardContent>
          </Card>
          
          {/* Crews List */}
          <div className="space-y-3">
            <h3 className={`font-medium ${textPrimary}`}>Your Crews</h3>
            {userSummary?.top_crews?.length > 0 ? (
              userSummary.top_crews.map((crew, idx) => (
                <CrewCard 
                  key={idx} 
                  crew={crew} 
                  isLight={isLight}
                  onClick={() => handleCrewClick(crew)}
                />
              ))
            ) : (
              <p className={textSecondary}>No crew sessions yet. Start surfing with friends!</p>
            )}
          </div>
        </TabsContent>
        
        {/* Leaderboard Tab */}
        <TabsContent value="leaderboard" className="space-y-4">
          {/* Metric Filter */}
          <div className="flex gap-2 overflow-x-auto pb-2">
            {[
              { value: 'total_sessions', label: 'Sessions', icon: <Flame className="w-4 h-4" /> },
              { value: 'total_money_saved', label: 'Savings', icon: <DollarSign className="w-4 h-4" /> },
              { value: 'current_streak', label: 'Streak', icon: <TrendingUp className="w-4 h-4" /> },
            ].map((metric) => (
              <Button
                key={metric.value}
                variant={leaderboardMetric === metric.value ? 'default' : 'outline'}
                size="sm"
                onClick={() => setLeaderboardMetric(metric.value)}
                className={leaderboardMetric === metric.value ? 'bg-cyan-500 text-black' : ''}
              >
                {metric.icon}
                <span className="ml-1">{metric.label}</span>
              </Button>
            ))}
          </div>
          
          {/* Leaderboard List */}
          <div className="space-y-2">
            {leaderboard.length > 0 ? (
              leaderboard.map((entry, idx) => (
                <LeaderboardEntry key={idx} entry={entry} isLight={isLight} />
              ))
            ) : (
              <p className={textSecondary}>No crews on the leaderboard yet.</p>
            )}
          </div>
        </TabsContent>
        
        {/* Badges Tab */}
        <TabsContent value="badges" className="space-y-4">
          <div className="grid grid-cols-3 gap-4">
            {userSummary?.badges?.length > 0 ? (
              userSummary.badges.map((badge, idx) => (
                <div key={idx} className={`p-4 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} text-center`}>
                  <BadgeCard badge={badge} size="lg" />
                  <p className={`text-xs ${textSecondary} mt-2`}>{badge.description}</p>
                  {badge.progress < badge.target && (
                    <div className="mt-2">
                      <div className={`h-1 rounded-full ${isLight ? 'bg-gray-200' : 'bg-zinc-700'}`}>
                        <div 
                          className="h-1 rounded-full bg-cyan-400"
                          style={{ width: `${(badge.progress / badge.target) * 100}%` }}
                        />
                      </div>
                      <p className={`text-xs ${textSecondary} mt-1`}>{badge.progress}/{badge.target}</p>
                    </div>
                  )}
                </div>
              ))
            ) : (
              <div className="col-span-3 text-center py-8">
                <Medal className="w-12 h-12 mx-auto mb-3 text-gray-500" />
                <p className={textSecondary}>No badges earned yet. Keep surfing with your crew!</p>
              </div>
            )}
          </div>
        </TabsContent>
      </Tabs>
      
      {/* Crew Detail Modal */}
      <Dialog open={showCrewDetail} onOpenChange={setShowCrewDetail}>
        <DialogContent className={`${cardBg} max-w-md`}>
          <DialogHeader>
            <DialogTitle className={textPrimary}>
              {selectedCrew?.name || 'Crew Details'}
            </DialogTitle>
          </DialogHeader>
          
          {selectedCrew && (
            <div className="space-y-4">
              {/* Members */}
              <div>
                <p className={`text-sm font-medium ${textSecondary} mb-2`}>Members</p>
                <div className="flex flex-wrap gap-2">
                  {selectedCrew.members?.map((member, idx) => (
                    <div key={idx} className="flex items-center gap-2 bg-zinc-800 rounded-full px-3 py-1">
                      <div className="w-6 h-6 rounded-full bg-gradient-to-br from-cyan-400 to-blue-500 flex items-center justify-center overflow-hidden">
                        {member.avatar_url ? (
                          <img src={getFullUrl(member.avatar_url)} alt="" className="w-full h-full object-cover" />
                        ) : (
                          <span className="text-white text-xs">{member.full_name?.charAt(0)}</span>
                        )}
                      </div>
                      <span className={`text-sm ${textPrimary}`}>{member.full_name}</span>
                    </div>
                  ))}
                </div>
              </div>
              
              {/* Stats */}
              <div className="grid grid-cols-2 gap-3">
                <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'}`}>
                  <p className="text-xl font-bold text-cyan-400">{selectedCrew.stats?.total_sessions || 0}</p>
                  <p className={`text-xs ${textSecondary}`}>Total Sessions</p>
                </div>
                <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'}`}>
                  <p className="text-xl font-bold text-green-400">${(selectedCrew.stats?.total_money_saved || 0).toFixed(0)}</p>
                  <p className={`text-xs ${textSecondary}`}>Total Saved</p>
                </div>
                <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'}`}>
                  <p className="text-xl font-bold text-yellow-400">{selectedCrew.stats?.sunrise_sessions || 0}</p>
                  <p className={`text-xs ${textSecondary}`}>Dawn Patrols</p>
                </div>
                <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'}`}>
                  <p className="text-xl font-bold text-orange-400">{selectedCrew.stats?.sunset_sessions || 0}</p>
                  <p className={`text-xs ${textSecondary}`}>Sunset Sessions</p>
                </div>
              </div>
              
              {/* Badges */}
              {selectedCrew.badges?.length > 0 && (
                <div>
                  <p className={`text-sm font-medium ${textSecondary} mb-2`}>Crew Badges</p>
                  <div className="flex flex-wrap gap-3 justify-center">
                    {selectedCrew.badges.map((badge, idx) => (
                      <BadgeCard key={idx} badge={badge} size="md" />
                    ))}
                  </div>
                </div>
              )}
              
              {/* Privacy Toggle */}
              {showPrivacyControls && selectedCrew.member_ids?.includes(targetUserId) && (
                <div className="flex items-center justify-between pt-3 border-t border-zinc-700">
                  <div className="flex items-center gap-2">
                    {selectedCrew.is_public ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                    <Label>Public Crew Stats</Label>
                  </div>
                  <Switch
                    checked={selectedCrew.is_public}
                    onCheckedChange={(checked) => handlePrivacyToggle(selectedCrew.crew_hash, checked)}
                  />
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default CrewLeaderboard;

﻿import React, { useState, useEffect } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  Users, DollarSign, Clock, CheckCircle2, AlertTriangle, 
  Send, Calculator, Loader2, ChevronDown, ChevronUp
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Progress } from './ui/progress';
import { Input } from './ui/input';
import { Card, CardHeader, CardTitle, CardContent } from './ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { toast } from 'sonner';
import logger from '../utils/logger';


/**
 * CrewPaymentDashboard - Host Surfer's real-time crew payment management
 * 
 * Features:
 * - Real-time crew payment status
 * - Custom split tool for adjusting amounts per crew member
 * - 1-click nudge for reminders
 * - Payment lock until 100% verified
 */

export const CrewPaymentDashboard = ({ booking, onUpdate }) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';
  
  const [crewMembers, setCrewMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCustomSplit, setShowCustomSplit] = useState(false);
  const [customAmounts, setCustomAmounts] = useState({});
  const [sendingNudge, setSendingNudge] = useState(null);
  const [expanded, setExpanded] = useState(true);

  const isHost = booking.creator_id === user?.id || booking.host_id === user?.id;
  const totalCrew = booking.max_participants || 1;
  const totalAmount = booking.total_price || 0;
  const equalShare = totalAmount / totalCrew;
  
  // Calculate payment progress
  const paidCount = crewMembers.filter(m => m.payment_status === 'Paid').length;
  const pendingCount = crewMembers.filter(m => m.payment_status === 'Pending').length;
  const paymentProgress = totalCrew > 0 ? (paidCount / totalCrew) * 100 : 0;
  const totalPaid = crewMembers.reduce((sum, m) => sum + (m.amount_paid || 0), 0);

  useEffect(() => {
    if (booking.id) {
      fetchCrewStatus();
    }
  }, [booking.id]);

  const fetchCrewStatus = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(`/bookings/${booking.id}/crew-status`);
      setCrewMembers(response.data?.crew || []);
      
      // Initialize custom amounts
      const amounts = {};
      (response.data?.crew || []).forEach(m => {
        amounts[m.participant_id] = m.share_amount || equalShare;
      });
      setCustomAmounts(amounts);
    } catch (error) {
      logger.error('Failed to fetch crew status:', error);
      // Fallback: use booking participants if available
      if (booking.participants) {
        setCrewMembers(booking.participants.map(p => ({
          participant_id: p.participant_id || p.id,
          name: p.name || 'Crew Member',
          email: p.email,
          payment_status: p.payment_status || 'Pending',
          amount_paid: p.amount_paid || 0,
          share_amount: p.share_amount || equalShare
        })));
      }
    } finally {
      setLoading(false);
    }
  };

  const handleNudge = async (memberId) => {
    setSendingNudge(memberId);
    try {
      await apiClient.post(`/bookings/${booking.id}/nudge`, {
        participant_id: memberId
      });
      toast.success('Reminder sent!');
    } catch (error) {
      toast.error('Failed to send reminder');
    } finally {
      setSendingNudge(null);
    }
  };

  const handleNudgeAll = async () => {
    const pendingIds = crewMembers
      .filter(m => m.payment_status === 'Pending')
      .map(m => m.participant_id);
    
    if (pendingIds.length === 0) {
      toast.info('All crew members have paid!');
      return;
    }

    setSendingNudge('all');
    try {
      await apiClient.post(`/bookings/${booking.id}/nudge-all`);
      toast.success(`Reminders sent to ${pendingIds.length} crew members!`);
    } catch (error) {
      toast.error('Failed to send reminders');
    } finally {
      setSendingNudge(null);
    }
  };

  const handleUpdateSplits = async () => {
    // Validate total equals booking amount
    const customTotal = Object.values(customAmounts).reduce((sum, amt) => sum + parseFloat(amt || 0), 0);
    if (Math.abs(customTotal - totalAmount) > 0.01) {
      toast.error(`Custom splits must equal $${totalAmount.toFixed(2)}. Current total: $${customTotal.toFixed(2)}`);
      return;
    }

    try {
      await apiClient.post(`/bookings/${booking.id}/update-splits`, {
        splits: Object.entries(customAmounts).map(([id, amount]) => ({
          participant_id: id,
          share_amount: parseFloat(amount)
        }))
      });
      toast.success('Payment splits updated!');
      setShowCustomSplit(false);
      fetchCrewStatus();
      onUpdate?.();
    } catch (error) {
      toast.error('Failed to update splits');
    }
  };

  if (!isHost) return null;

  return (
    <Card className={`${isLight ? 'bg-white border-gray-200' : 'bg-zinc-900/50 border-zinc-800'}`}>
      <CardHeader className="pb-2">
        <button 
          onClick={() => setExpanded(!expanded)}
          className="flex items-center justify-between w-full"
        >
          <CardTitle className={`text-base flex items-center gap-2 ${isLight ? 'text-gray-900' : 'text-white'}`}>
            <Users className="w-5 h-5 text-cyan-400" />
            Crew Payment Dashboard
            <Badge 
              className={paymentProgress === 100 
                ? 'bg-green-500/20 text-green-400' 
                : 'bg-amber-500/20 text-amber-400'
              }
            >
              {paidCount}/{totalCrew} Paid
            </Badge>
          </CardTitle>
          {expanded ? <ChevronUp className="w-4 h-4 text-gray-500" /> : <ChevronDown className="w-4 h-4 text-gray-500" />}
        </button>
      </CardHeader>
      
      {expanded && (
        <CardContent className="space-y-4">
          {/* Payment Progress Summary */}
          <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-50' : 'bg-zinc-800/50'}`}>
            <div className="flex items-center justify-between mb-2">
              <span className={`text-sm font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>
                Payment Progress
              </span>
              <span className={`text-sm font-bold ${isLight ? 'text-gray-900' : 'text-white'}`}>
                ${totalPaid.toFixed(2)} / ${totalAmount.toFixed(2)}
              </span>
            </div>
            <Progress value={paymentProgress} className="h-2" />
            
            {paymentProgress < 100 && (
              <p className={`mt-2 text-xs ${isLight ? 'text-amber-600' : 'text-amber-400'}`}>
                <AlertTriangle className="w-3 h-3 inline mr-1" />
                Session locked until all crew members pay. Photographer cannot see this booking yet.
              </p>
            )}
            
            {paymentProgress === 100 && (
              <p className={`mt-2 text-xs ${isLight ? 'text-green-600' : 'text-green-400'}`}>
                <CheckCircle2 className="w-3 h-3 inline mr-1" />
                All payments received! Session is confirmed.
              </p>
            )}
          </div>

          {/* Crew Members List */}
          {loading ? (
            <div className="flex items-center justify-center py-4">
              <Loader2 className="w-5 h-5 animate-spin text-cyan-400" />
            </div>
          ) : (
            <div className="space-y-2">
              {crewMembers.map((member) => (
                <div 
                  key={member.participant_id}
                  className={`flex items-center justify-between p-3 rounded-lg ${
                    isLight ? 'bg-gray-50 border border-gray-100' : 'bg-zinc-800/30 border border-zinc-700/50'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
                      member.payment_status === 'Paid' 
                        ? 'bg-green-500/20 text-green-400' 
                        : 'bg-amber-500/20 text-amber-400'
                    }`}>
                      {member.name?.charAt(0) || 'C'}
                    </div>
                    <div>
                      <p className={`text-sm font-medium ${isLight ? 'text-gray-900' : 'text-white'}`}>
                        {member.name || 'Crew Member'}
                        {member.participant_id === user?.id && (
                          <Badge className="ml-2 text-xs bg-cyan-500/20 text-cyan-400">You (Host)</Badge>
                        )}
                      </p>
                      <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
                        Share: ${(member.share_amount || equalShare).toFixed(2)}
                      </p>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    {member.payment_status === 'Paid' ? (
                      <Badge className="bg-green-500/20 text-green-400">
                        <CheckCircle2 className="w-3 h-3 mr-1" />
                        Paid
                      </Badge>
                    ) : (
                      <>
                        <Badge className="bg-amber-500/20 text-amber-400">
                          <Clock className="w-3 h-3 mr-1" />
                          Pending
                        </Badge>
                        {member.participant_id !== user?.id && (
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={() => handleNudge(member.participant_id)}
                            disabled={sendingNudge === member.participant_id}
                            className="p-1 h-7"
                          >
                            {sendingNudge === member.participant_id ? (
                              <Loader2 className="w-4 h-4 animate-spin" />
                            ) : (
                              <Send className="w-4 h-4 text-cyan-400" />
                            )}
                          </Button>
                        )}
                      </>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Action Buttons */}
          <div className="flex gap-2 pt-2">
            {pendingCount > 0 && (
              <Button
                size="sm"
                variant="outline"
                onClick={handleNudgeAll}
                disabled={sendingNudge === 'all'}
                className={`flex-1 ${
                  isLight 
                    ? 'border-cyan-300 text-cyan-700 hover:bg-cyan-50' 
                    : 'border-cyan-500/50 text-cyan-400 hover:bg-cyan-500/20'
                }`}
              >
                {sendingNudge === 'all' ? (
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                ) : (
                  <Send className="w-4 h-4 mr-2" />
                )}
                Nudge All Pending
              </Button>
            )}
            
            <Button
              size="sm"
              variant="outline"
              onClick={() => setShowCustomSplit(true)}
              className={`${
                isLight 
                  ? 'border-gray-300 text-gray-700 hover:bg-gray-50' 
                  : 'border-zinc-600 text-gray-300 hover:bg-zinc-700'
              }`}
            >
              <Calculator className="w-4 h-4 mr-2" />
              Custom Split
            </Button>
          </div>
        </CardContent>
      )}

      {/* Custom Split Dialog */}
      <Dialog open={showCustomSplit} onOpenChange={setShowCustomSplit}>
        <DialogContent className={`${isLight ? 'bg-white' : 'bg-zinc-900 border-zinc-700'}`}>
          <DialogHeader>
            <DialogTitle className={`flex items-center gap-2 ${isLight ? 'text-gray-900' : 'text-white'}`}>
              <Calculator className="w-5 h-5 text-cyan-400" />
              Custom Payment Split
            </DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4 py-4">
            <p className={`text-sm ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>
              Adjust individual share amounts. Total must equal ${totalAmount.toFixed(2)}.
            </p>
            
            {crewMembers.map((member) => (
              <div key={member.participant_id} className="flex items-center gap-3">
                <div className="flex-1">
                  <p className={`text-sm font-medium ${isLight ? 'text-gray-900' : 'text-white'}`}>
                    {member.name || 'Crew Member'}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <DollarSign className="w-4 h-4 text-gray-400" />
                  <Input
                    type="number"
                    step="0.01"
                    min="0"
                    value={customAmounts[member.participant_id] || ''}
                    onChange={(e) => setCustomAmounts({
                      ...customAmounts,
                      [member.participant_id]: e.target.value
                    })}
                    className={`w-24 ${isLight ? 'bg-white' : 'bg-zinc-800 border-zinc-600'}`}
                  />
                </div>
              </div>
            ))}
            
            <div className={`flex items-center justify-between pt-2 border-t ${isLight ? 'border-gray-200' : 'border-zinc-700'}`}>
              <span className={`text-sm font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>
                Total:
              </span>
              <span className={`font-bold ${
                Math.abs(Object.values(customAmounts).reduce((sum, amt) => sum + parseFloat(amt || 0), 0) - totalAmount) < 0.01
                  ? (isLight ? 'text-green-600' : 'text-green-400')
                  : (isLight ? 'text-red-600' : 'text-red-400')
              }`}>
                ${Object.values(customAmounts).reduce((sum, amt) => sum + parseFloat(amt || 0), 0).toFixed(2)}
                <span className={`text-sm font-normal ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
                  {' '}/ ${totalAmount.toFixed(2)}
                </span>
              </span>
            </div>
          </div>
          
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowCustomSplit(false)}>
              Cancel
            </Button>
            <Button onClick={handleUpdateSplits} className="bg-cyan-500 hover:bg-cyan-400 text-black">
              Update Splits
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Card>
  );
};

export default CrewPaymentDashboard;

﻿import React, { useState, useEffect, useCallback } from 'react';

import { useParams, useNavigate } from 'react-router-dom';

import { useAuth } from '../contexts/AuthContext';

import { useTheme } from '../contexts/ThemeContext';

import apiClient, { BACKEND_URL } from '../lib/apiClient';

import { 

  DollarSign, Clock, MapPin, Users, Check, 
  Loader2, ArrowLeft, CreditCard, Wallet, Timer,
  AlertCircle, Crown, Camera, CalendarCheck, MessageCircle
} from 'lucide-react';
import { Button } from './ui/button';

import { Card, CardHeader, CardTitle, CardContent } from './ui/card';

import { Progress } from './ui/progress';

import { Avatar, AvatarImage, AvatarFallback } from './ui/avatar';

import { toast } from 'sonner';

import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';



/**
 * CrewPaymentPage - Deep link destination for crew payment notifications
 * Accessed via /bookings/pay/:bookingId
 * 
 * Shows:
 * - Booking details (location, time, photographer)
 * - Captain info
 * - User's share amount
 * - Payment countdown timer
 * - Pay now button
 */

const CrewPaymentPage = () => {
  const { bookingId } = useParams();
  const navigate = useNavigate();
  const { user, updateUser } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';
  
  const [booking, setBooking] = useState(null);
  const [loading, setLoading] = useState(true);
  const [paying, setPaying] = useState(false);
  const [_paymentMethod, _setPaymentMethod] = useState('credits');
  const [timeRemaining, setTimeRemaining] = useState(null);
  const [myShare, setMyShare] = useState(null);
  const [captain, setCaptain] = useState(null);

  const fetchBookingDetails = useCallback(async () => {
    try {
      const response = await apiClient.get(`/bookings/${bookingId}/crew-payment-details`);
      setBooking(response.data.booking);
      setMyShare(response.data.my_share);
      setCaptain(response.data.captain);
    } catch (error) {
      logger.error('Failed to fetch booking:', error);
      toast.error('Failed to load booking details');
      navigate('/bookings');
    } finally {
      setLoading(false);
    }
  }, [bookingId, user?.id, navigate]);

  useEffect(() => {
    if (user?.id && bookingId) {
      fetchBookingDetails();
    }
  }, [user?.id, bookingId, fetchBookingDetails]);

  // Payment window countdown
  useEffect(() => {
    if (!booking?.payment_window_expires_at) return;
    
    const updateTimer = () => {
      const now = new Date();
      const expires = new Date(booking.payment_window_expires_at);
      const diff = expires - now;
      
      if (diff <= 0) {
        setTimeRemaining({ expired: true });
      } else {
        const hours = Math.floor(diff / (1000 * 60 * 60));
        const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        const seconds = Math.floor((diff % (1000 * 60)) / 1000);
        setTimeRemaining({ hours, minutes, seconds, expired: false });
      }
    };
    
    updateTimer();
    const interval = setInterval(updateTimer, 1000);
    return () => clearInterval(interval);
  }, [booking?.payment_window_expires_at]);

  const handlePayWithCredits = async () => {
    if (!myShare || myShare.payment_status === 'Paid') {
      toast.info('Already paid!');
      return;
    }
    
    if ((user?.credit_balance || 0) < myShare.share_amount) {
      toast.error(`Insufficient credits. You need $${myShare.share_amount.toFixed(2)} but have $${(user?.credit_balance || 0).toFixed(2)}`);
      return;
    }
    
    setPaying(true);
    try {
      const response = await apiClient.post(
        `/bookings/${bookingId}/crew-pay`,
        {
          participant_id: user.id,
          amount: myShare.share_amount,
          payment_method: 'credits'
        }
      );
      
      // Update user balance
      updateUser({ credit_balance: response.data.new_balance });
      
      toast.success('Payment successful! You\'re in the crew.');
      
      // Refresh the page data
      fetchBookingDetails();
    } catch (error) {
      logger.error('Payment failed:', error);
      toast.error(error.response?.data?.detail || 'Payment failed');
    } finally {
      setPaying(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
      </div>
    );
  }

  if (!booking) {
    return (
      <div className="p-4 text-center">
        <p className={isLight ? 'text-gray-600' : 'text-gray-400'}>Booking not found</p>
        <Button onClick={() => navigate('/bookings')} className="mt-4">
          Go to Bookings
        </Button>
      </div>
    );
  }

  const isPaid = myShare?.payment_status === 'Paid';
  const isExpired = timeRemaining?.expired;

  return (
    <div className="max-w-lg mx-auto p-4 space-y-6" data-testid="crew-payment-page">
      {/* Back Button */}
      <button
        onClick={() => navigate('/bookings')}
        className={`flex items-center gap-2 ${isLight ? 'text-gray-600' : 'text-gray-400'} hover:text-white transition-colors`}
      >
        <ArrowLeft className="w-4 h-4" />
        Back to Bookings
      </button>

      {/* Header */}
      <div className="text-center">
        <h1 className={`text-2xl font-bold ${isLight ? 'text-gray-900' : 'text-white'}`} style={{ fontFamily: 'Oswald' }}>
          Crew Payment
        </h1>
        <p className={`${isLight ? 'text-gray-600' : 'text-gray-400'}`}>
          {isPaid ? 'You\'re all set!' : 'Complete your payment to join'}
        </p>
      </div>

      {/* Payment Window Timer */}
      {!isPaid && !isExpired && timeRemaining && (
        <Card className={`${isLight ? 'bg-amber-50 border-amber-200' : 'bg-amber-500/10 border-amber-500/30'}`}>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Timer className="w-5 h-5 text-amber-500" />
                <span className={isLight ? 'text-amber-700' : 'text-amber-400'}>
                  {booking.booking_type === 'on_demand' ? '60-minute window' : '24-hour window'}
                </span>
              </div>
              <div className={`text-xl font-bold font-mono ${isLight ? 'text-amber-600' : 'text-amber-400'}`}>
                {String(timeRemaining.hours).padStart(2, '0')}:
                {String(timeRemaining.minutes).padStart(2, '0')}:
                {String(timeRemaining.seconds).padStart(2, '0')}
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Expired Warning */}
      {isExpired && !isPaid && (
        <Card className={`${isLight ? 'bg-red-50 border-red-200' : 'bg-red-500/10 border-red-500/30'}`}>
          <CardContent className="p-4">
            <div className="flex items-center gap-2">
              <AlertCircle className="w-5 h-5 text-red-500" />
              <span className={isLight ? 'text-red-700' : 'text-red-400'}>
                Payment window expired. Contact the Captain.
              </span>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Captain Info */}
      {captain && (
        <Card className={isLight ? 'bg-white border-gray-200' : 'bg-zinc-900 border-zinc-800'}>
          <CardContent className="p-4">
            <div className="flex items-center gap-4">
              <div className="relative">
                <Avatar className="w-14 h-14 border-2 border-yellow-400">
                  <AvatarImage src={getFullUrl(captain.avatar_url)} />
                  <AvatarFallback className="bg-yellow-400/20 text-yellow-400">
                    {captain.full_name?.charAt(0)}
                  </AvatarFallback>
                </Avatar>
                <Crown className="absolute -top-1 -right-1 w-5 h-5 text-yellow-400 fill-yellow-400" />
              </div>
              <div>
                <p className={`font-bold ${isLight ? 'text-gray-900' : 'text-white'}`}>
                  {captain.full_name}
                </p>
                <p className={`text-sm ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
                  Captain
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Session Details */}
      <Card className={isLight ? 'bg-white border-gray-200' : 'bg-zinc-900 border-zinc-800'}>
        <CardHeader>
          <CardTitle className={`text-lg flex items-center gap-2 ${isLight ? 'text-gray-900' : 'text-white'}`}>
            <Camera className="w-5 h-5 text-cyan-400" />
            Session Details
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex items-center gap-3">
            <MapPin className="w-4 h-4 text-gray-400" />
            <span className={isLight ? 'text-gray-700' : 'text-gray-300'}>{booking.location}</span>
          </div>
          <div className="flex items-center gap-3">
            <CalendarCheck className="w-4 h-4 text-gray-400" />
            <span className={isLight ? 'text-gray-700' : 'text-gray-300'}>
              {new Date(booking.session_date).toLocaleDateString()} at {new Date(booking.session_date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>
          </div>
          <div className="flex items-center gap-3">
            <Clock className="w-4 h-4 text-gray-400" />
            <span className={isLight ? 'text-gray-700' : 'text-gray-300'}>{booking.duration} minutes</span>
          </div>
          <div className="flex items-center gap-3">
            <Users className="w-4 h-4 text-gray-400" />
            <span className={isLight ? 'text-gray-700' : 'text-gray-300'}>
              {booking.participant_count || 1} crew member{(booking.participant_count || 1) > 1 ? 's' : ''}
            </span>
          </div>
        </CardContent>
      </Card>

      {/* Your Share */}
      <Card className={`${isPaid ? 
        (isLight ? 'bg-green-50 border-green-200' : 'bg-green-500/10 border-green-500/30') :
        (isLight ? 'bg-gradient-to-br from-cyan-50 to-blue-50 border-cyan-200' : 'bg-gradient-to-br from-cyan-500/10 to-blue-500/10 border-cyan-500/30')
      }`}>
        <CardContent className="p-6">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <DollarSign className={`w-6 h-6 ${isPaid ? 'text-green-500' : 'text-cyan-400'}`} />
              <span className={`text-lg font-bold ${isLight ? 'text-gray-900' : 'text-white'}`}>
                Your Share
              </span>
            </div>
            <span className={`text-3xl font-bold ${isPaid ? 'text-green-500' : 'text-cyan-400'}`}>
              ${myShare?.share_amount?.toFixed(2) || '0.00'}
            </span>
          </div>
          
          {isPaid ? (
            <div className="flex items-center justify-center gap-2 py-4">
              <Check className="w-6 h-6 text-green-500" />
              <span className={`text-lg font-medium ${isLight ? 'text-green-700' : 'text-green-400'}`}>
                Payment Complete!
              </span>
            </div>
          ) : (
            <>
              {/* Credit Balance */}
              <div className={`flex items-center justify-between p-3 rounded-lg mb-4 ${isLight ? 'bg-white' : 'bg-zinc-900/50'}`}>
                <span className={isLight ? 'text-gray-600' : 'text-gray-400'}>Your Balance:</span>
                <span className={`font-bold ${(user?.credit_balance || 0) >= (myShare?.share_amount || 0) ? 'text-green-500' : 'text-red-500'}`}>
                  ${(user?.credit_balance || 0).toFixed(2)}
                </span>
              </div>

              {/* Pay Button */}
              <Button
                onClick={handlePayWithCredits}
                disabled={paying || isExpired || (user?.credit_balance || 0) < (myShare?.share_amount || 0)}
                className="w-full bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-400 hover:to-blue-400 text-white font-bold py-6 text-lg"
                data-testid="pay-crew-share-btn"
              >
                {paying ? (
                  <Loader2 className="w-5 h-5 animate-spin mr-2" />
                ) : (
                  <Wallet className="w-5 h-5 mr-2" />
                )}
                Pay ${myShare?.share_amount?.toFixed(2)} with Credits
              </Button>
              
              {(user?.credit_balance || 0) < (myShare?.share_amount || 0) && (
                <div className="mt-3 text-center">
                  <Button
                    variant="outline"
                    onClick={() => navigate('/credits')}
                    className={isLight ? 'border-gray-300 text-gray-600' : 'border-zinc-600 text-gray-400'}
                  >
                    <CreditCard className="w-4 h-4 mr-2" />
                    Add Credits
                  </Button>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Session Progress */}
      {booking.payment_progress !== undefined && (
        <Card className={isLight ? 'bg-white border-gray-200' : 'bg-zinc-900 border-zinc-800'}>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-2">
              <span className={isLight ? 'text-gray-600' : 'text-gray-400'}>Session Payment Progress</span>
              <span className={isLight ? 'text-gray-900' : 'text-white'}>
                {booking.paid_count}/{booking.participant_count} paid
              </span>
            </div>
            <Progress value={booking.payment_progress} className="h-2" />
            {booking.payment_progress === 100 && (
              <p className="text-green-500 text-sm mt-2 flex items-center gap-1">
                <Check className="w-4 h-4" />
                All crew paid - session confirmed!
              </p>
            )}
          </CardContent>
        </Card>
      )}

      {/* Crew Chat Button */}
      <Button
        onClick={() => navigate(`/bookings/${bookingId}/chat`)}
        variant="outline"
        className={`w-full flex items-center justify-center gap-2 ${isLight ? 'border-cyan-500 text-cyan-600 hover:bg-cyan-50' : 'border-cyan-500/50 text-cyan-400 hover:bg-cyan-500/10'}`}
        data-testid="crew-payment-chat-btn"
      >
        <MessageCircle className="w-5 h-5" />
        Chat with Crew
      </Button>
    </div>
  );
};

export default CrewPaymentPage;

/**
 * Dispatch Payment Success Page
 * Handles Stripe payment confirmation for on-demand dispatch sessions
 * Shows selfie upload modal after payment confirmation
 */
import React, { useEffect, useState, useRef } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import apiClient from '../lib/apiClient';
import { CheckCircle, Loader2, XCircle, Camera, Sparkles, Upload } from 'lucide-react';
import { Button } from './ui/button';
import { toast } from 'sonner';
import { RequestProSelfieModal } from './RequestProSelfieModal';
import logger from '../utils/logger';


const DispatchPaymentSuccess = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { user, updateUser } = useAuth();
  
  const sessionId = searchParams.get('session_id');
  const dispatchId = searchParams.get('dispatch_id');
  
  const [status, setStatus] = useState('checking');
  const [showSelfieModal, setShowSelfieModal] = useState(false);
  
  // Refs to prevent duplicate work across re-renders
  const confirmedRef = useRef(false);
  const pollCountRef = useRef(0);
  const maxAttempts = 5;

  useEffect(() => {
    if (!sessionId || !dispatchId) {
      setStatus('error');
      return;
    }

    // If we already confirmed, do not re-run
    if (confirmedRef.current) return;

    const confirmDispatchPayment = async () => {
      // Double-check inside async in case of race
      if (confirmedRef.current) return;

      try {
        // Step 1: Confirm payment with Stripe
        const response = await apiClient.get(
          `/dispatch/payment-success?session_id=${sessionId}&dispatch_id=${dispatchId}`
        );
        
        if (response.data.success) {
          // Mark as confirmed IMMEDIATELY to prevent any re-entry
          confirmedRef.current = true;

          // Step 2: VERIFICATION - Check that participant record was created with metadata
          try {
            const verifyResponse = await apiClient.get(
              `/dispatch/${dispatchId}/verify-payment`
            );
            
            if (!verifyResponse.data.verified && pollCountRef.current < maxAttempts) {
              // Metadata not stored yet — retry verification only, not the whole flow
              confirmedRef.current = false; // allow one more attempt
              pollCountRef.current += 1;
              setTimeout(confirmDispatchPayment, 2000);
              return;
            }
            
            // Check if selfie is needed
            if (verifyResponse.data.needs_selfie) {
              setShowSelfieModal(true);
            }
          } catch (verifyError) {
            logger.warn('Could not verify payment record:', verifyError);
          }
          
          setStatus('success');
          toast.success('Payment confirmed! Now add your selfie so the photographer can find you.', {
            id: 'payment-confirmed', // Deduplicate by ID
          });
          
          // Show selfie modal
          setShowSelfieModal(true);
          
          // Refresh user data
          try {
            const profileResponse = await apiClient.get(`/profiles/${user?.id}`);
            if (profileResponse.data?.credit_balance !== undefined) {
              updateUser({ credit_balance: profileResponse.data.credit_balance });
            }
          } catch (e) {
            logger.warn('Could not refresh user data');
          }
        } else {
          // Payment not yet confirmed — poll again
          if (pollCountRef.current < maxAttempts) {
            pollCountRef.current += 1;
            setTimeout(confirmDispatchPayment, 2000);
          } else {
            setStatus('timeout');
          }
        }
      } catch (error) {
        logger.error('Dispatch payment confirmation error:', error);
        
        if (pollCountRef.current < maxAttempts && error.response?.status !== 400) {
          pollCountRef.current += 1;
          setTimeout(confirmDispatchPayment, 2000);
        } else {
          setStatus('error');
        }
      }
    };

    confirmDispatchPayment();
  }, [sessionId, dispatchId]);

  const handleSelfieSuccess = (_selfieUrl) => {
    setShowSelfieModal(false);
    toast.success('Selfie uploaded! The photographer can now find you.');
    // Navigate to lobby instead of bookings for better flow
    navigate(`/dispatch/${dispatchId}/lobby`);
  };

  const handleSkipSelfie = () => {
    setShowSelfieModal(false);
    toast.info('You can add a selfie later from the booking screen.');
    navigate(`/dispatch/${dispatchId}/lobby`);
  };

  const renderContent = () => {
    switch (status) {
      case 'checking':
        return (
          <div className="text-center">
            <Loader2 className="w-16 h-16 text-amber-400 animate-spin mx-auto mb-4" />
            <h2 className="text-2xl font-bold text-white mb-2">Confirming Your Payment...</h2>
            <p className="text-gray-400">Please wait while we process your payment</p>
          </div>
        );
      
      case 'success':
        return (
          <div className="text-center">
            {/* Success Animation */}
            <div className="relative inline-block mb-6">
              <div className="w-24 h-24 rounded-full bg-gradient-to-r from-amber-500 to-orange-500 flex items-center justify-center animate-pulse">
                <CheckCircle className="w-12 h-12 text-white" />
              </div>
              <div className="absolute -top-2 -right-2 w-8 h-8 rounded-full bg-green-400 flex items-center justify-center">
                <Sparkles className="w-4 h-4 text-black" />
              </div>
            </div>
            
            <h2 className="text-2xl font-bold text-white mb-2">Payment Successful!</h2>
            <p className="text-gray-400 mb-6">
              Your on-demand session request is being processed.
            </p>
            
            {/* Next Step Card */}
            <div className="bg-zinc-800 rounded-xl p-6 text-left mb-6 max-w-md mx-auto">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-12 h-12 rounded-full bg-amber-500/20 flex items-center justify-center">
                  <Camera className="w-6 h-6 text-amber-400" />
                </div>
                <div>
                  <p className="font-semibold text-white">Next Step: Add Your Selfie</p>
                  <p className="text-xs text-gray-400">Help the photographer find you</p>
                </div>
              </div>
              
              <p className="text-sm text-gray-400 mb-4">
                Take a quick selfie with your surfboard so the photographer can identify you when they arrive.
              </p>
              
              <Button
                onClick={() => setShowSelfieModal(true)}
                className="w-full bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-black font-bold"
                data-testid="add-selfie-btn"
              >
                <Upload className="w-4 h-4 mr-2" />
                Add Selfie Now
              </Button>
            </div>
            
            {/* Skip Option */}
            <Button
              variant="ghost"
              onClick={handleSkipSelfie}
              className="text-gray-400 hover:text-white"
              data-testid="skip-selfie-btn"
            >
              Skip for now
            </Button>
          </div>
        );
      
      case 'timeout':
        return (
          <div className="text-center">
            <div className="w-20 h-20 rounded-full bg-amber-500/20 flex items-center justify-center mx-auto mb-4">
              <Loader2 className="w-12 h-12 text-amber-400" />
            </div>
            <h2 className="text-2xl font-bold text-white mb-2">Still Processing...</h2>
            <p className="text-gray-400 mb-6">
              Your payment is being processed. This may take a moment.
            </p>
            <Button
              onClick={() => {
                confirmedRef.current = false;
                pollCountRef.current = 0;
                setStatus('checking');
                // Re-trigger by navigating to self
                window.location.reload();
              }}
              className="bg-amber-500 hover:bg-amber-600 text-black"
            >
              Check Again
            </Button>
          </div>
        );
      
      case 'error':
      default:
        return (
          <div className="text-center">
            <div className="w-20 h-20 rounded-full bg-red-500/20 flex items-center justify-center mx-auto mb-4">
              <XCircle className="w-12 h-12 text-red-400" />
            </div>
            <h2 className="text-2xl font-bold text-white mb-2">Something Went Wrong</h2>
            <p className="text-gray-400 mb-6">
              We couldn't confirm your payment. Please check your bookings or contact support.
            </p>
            <div className="flex flex-col sm:flex-row gap-3 justify-center">
              <Button
                onClick={() => navigate(`/bookings?tab=on_demand&highlight=${dispatchId}`)}
                className="bg-amber-500 hover:bg-amber-600 text-black"
              >
                View Bookings
              </Button>
              <Button
                variant="outline"
                onClick={() => navigate('/messages')}
                className="border-zinc-700"
              >
                Contact Support
              </Button>
            </div>
          </div>
        );
    }
  };

  return (
    <>
      <div className="min-h-screen bg-zinc-950 flex items-center justify-center p-4">
        <div className="max-w-lg w-full" data-testid="dispatch-payment-success">
          {renderContent()}
        </div>
      </div>
      
      {/* Selfie Modal */}
      <RequestProSelfieModal
        dispatchId={dispatchId}
        isOpen={showSelfieModal}
        onClose={() => setShowSelfieModal(false)}
        onSuccess={handleSelfieSuccess}
      />
    </>
  );
};

export default DispatchPaymentSuccess;

/**
 * DutyStationDrawer - Unified Photographer Duty Management
 * 
 * Features:
 * - Mode Selector (Live vs On-Demand) - mutually exclusive
 * - Role-based visibility (Hobbyists only see Live mode)
 * - GPS validation for Live mode (must be within 0.2 miles of spot)
 * - Multi-spot selection for On-Demand mode with role-based radius:
 *   - Regular Photographer: 10-20 miles
 *   - Approved Pro: up to 50 miles
 * - Deselection capability for both modes
 * - Warning messages for GPS issues and compliance
 */

import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { usePersona } from '../contexts/PersonaContext';
import { 
