          <MessageCircle className={`w-3 h-3 ${colors.secondaryText}`} />
        </button>
      </div>
    </motion.div>
  );
});

/**
 * Live Comments Feed - Real-time with delta sync
 * Broadcaster can comment and reply, viewers can like comments
 */
const LiveCommentsFeed = ({ streamId, colors, onSendComment, onLikeComment, isExpanded, onToggleExpand, currentUserId }) => {
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');
  const [sending, setSending] = useState(false);
  const [replyingTo, setReplyingTo] = useState(null);
  const commentsRef = useRef(null);
  const lastFetchRef = useRef(Date.now());
  
  // Delta sync - only fetch new comments since last fetch
  useEffect(() => {
    if (!streamId) return;
    
    const fetchComments = async () => {
      try {
        const response = await apiClient.get(`/social-live/${streamId}/comments`);
        if (response.data?.comments) {
          // Lightweight update check — compare length + latest ID instead of full JSON serialize
          setComments(prev => {
            const newComments = response.data.comments;
            const lastPrevId = prev.length > 0 ? prev[prev.length - 1]?.id : null;
            const lastNewId = newComments.length > 0 ? newComments[newComments.length - 1]?.id : null;
            if (prev.length !== newComments.length || lastPrevId !== lastNewId) {
              return newComments;
            }
            return prev;
          });
          lastFetchRef.current = Date.now();
        }
      } catch (err) {
        // Silent fail
      }
    };

    fetchComments();
    const interval = setInterval(fetchComments, 2000);
    return () => clearInterval(interval);
  }, [streamId]);

  // Auto-scroll to bottom
  useEffect(() => {
    if (commentsRef.current) {
      commentsRef.current.scrollTop = commentsRef.current.scrollHeight;
    }
  }, [comments]);

  const handleSend = async (e) => {
    e?.preventDefault();
    if (!newComment.trim() || sending) return;
    
    setSending(true);
    const text = replyingTo 
      ? `@${replyingTo.user_name} ${newComment.trim()}`
      : newComment.trim();
    
    try {
      await onSendComment(text);
      setNewComment('');
      setReplyingTo(null);
    } catch (err) {
      // Error already handled in onSendComment
      logger.error('Comment send error:', err);
    } finally {
      setSending(false);
    }
  };

  const handleReply = (comment) => {
    setReplyingTo(comment);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: isExpanded ? '100%' : 'auto', overflow: 'hidden', background: 'rgba(9,9,11,0.92)', backdropFilter: 'blur(12px)' }}>
      {/* Header — Live pulse + count */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 14px', borderBottom: '1px solid rgba(39,39,42,0.8)', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          {/* Animated live pulse dot */}
          <div style={{ position: 'relative', width: 10, height: 10, flexShrink: 0 }}>
            <div className="animate-ping" style={{ position: 'absolute', inset: 0, borderRadius: '50%', background: '#f59e0b', opacity: 0.6 }} />
            <div style={{ position: 'absolute', inset: 0, borderRadius: '50%', background: '#f59e0b' }} />
          </div>
          <span style={{ fontSize: 13, fontWeight: 700, color: '#fff', letterSpacing: '0.02em' }}>LIVE CHAT</span>
          <span style={{ fontSize: 11, color: '#71717a', background: 'rgba(39,39,42,0.7)', padding: '1px 6px', borderRadius: 8 }}>{comments.length}</span>
        </div>
        <button onClick={onToggleExpand} className={`sm:hidden p-1.5 rounded-lg ${colors.buttonBg} transition-colors`}>
          {isExpanded ? <ChevronDown className={`w-4 h-4 ${colors.secondaryText}`} /> : <ChevronUp className={`w-4 h-4 ${colors.secondaryText}`} />}
        </button>
      </div>

      {isExpanded && (
        <>
          {/* Comments list - flex-1 fills all remaining height */}
          <div
            ref={commentsRef}
            style={{ flex: 1, overflowY: 'auto', padding: '8px', display: 'flex', flexDirection: 'column', gap: 6, minHeight: 0 }}
          >
            <AnimatePresence mode="popLayout">
              {comments.slice(-50).map((comment) => (
                <CommentTile
                  key={comment.id}
                  comment={comment}
                  colors={colors}
                  onReply={handleReply}
                  onLike={onLikeComment}
                  currentUserId={currentUserId}
                />
              ))}
            </AnimatePresence>

            {comments.length === 0 && (
              <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: '#52525b' }}>
                <MessageCircle style={{ width: 28, height: 28, opacity: 0.3, marginBottom: 8 }} />
                <p style={{ fontSize: 13, margin: 0 }}>No comments yet</p>
                <p style={{ fontSize: 11, opacity: 0.5, marginTop: 4 }}>Be the first to say something!</p>
              </div>
            )}
          </div>

          {/* Reply indicator */}
          <AnimatePresence>
            {replyingTo && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                style={{ padding: '6px 12px', borderTop: '1px solid #27272a', background: '#18181b', display: 'flex', alignItems: 'center', gap: 6, flexShrink: 0 }}
              >
                <span className={`text-xs ${colors.secondaryText}`}>Replying to</span>
                <span className={`text-xs font-semibold ${colors.accentText}`}>@{replyingTo.user_name}</span>
                <button onClick={() => setReplyingTo(null)} className="ml-auto">
                  <X className={`w-3 h-3 ${colors.secondaryText}`} />
                </button>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Input - pinned to bottom */}
          <form onSubmit={handleSend} style={{ padding: '10px 12px', borderTop: '1px solid #27272a', background: '#09090b', flexShrink: 0 }}>
            <div style={{ display: 'flex', gap: 8 }}>
              <Input
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder={replyingTo ? `Reply to @${replyingTo.user_name}...` : 'Say something...'}
                className={`flex-1 h-9 text-sm bg-zinc-800 border-zinc-700 text-white placeholder:text-zinc-500`}
                maxLength={200}
                disabled={sending}
              />
              <Button
                type="submit"
                size="sm"
                disabled={!newComment.trim() || sending}
                className={`${colors.accentBg} text-white h-9 px-3`}
              >
                {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
              </Button>
            </div>
          </form>
        </>
      )}
    </div>
  );
};

/**
 * Quick Reaction Buttons - Surf-themed emoji reactions with haptic burst animation
 * Best practice: keep to 6 reactions max, most-used first (Instagram Live pattern)
 */
const QuickReactions = ({ onReact, colors }) => {
  const reactions = [
    { emoji: '🤙', label: 'shaka' },
    { emoji: '🌊', label: 'wave' },
    { emoji: '🔥', label: 'fire' },
    { emoji: '❤️', label: 'love' },
    { emoji: '🏄', label: 'surf' },
    { emoji: '😮', label: 'wow' },
  ];

  return (
    <div className={`flex items-center gap-1.5 px-2 py-1.5 rounded-full ${colors.overlayBg} backdrop-blur-md border ${colors.border}`}>
      {reactions.map(({ emoji, label }) => (
        <button
          key={emoji}
          onClick={() => onReact(emoji)}
          aria-label={label}
          className="text-lg sm:text-xl hover:scale-130 transition-all duration-150 active:scale-90 p-1 rounded-full hover:bg-white/10"
        >
          {emoji}
        </button>
      ))}
    </div>
  );
};

/**
 * End Stream Confirmation Dialog - Theme-aware
 */
const EndStreamDialog = ({ isOpen, onConfirm, onCancel, duration, colors }) => {
  if (!isOpen) return null;

  const formatDuration = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}m ${secs}s`;
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-sm">
      <motion.div 
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        className={`${colors.overlayBg} ${colors.border} border rounded-2xl p-6 max-w-sm mx-4`}
      >
        <div className="flex items-center justify-center mb-4">
          <div className="w-16 h-16 rounded-full bg-red-500/20 flex items-center justify-center">
            <AlertTriangle className="w-8 h-8 text-red-500" />
          </div>
        </div>
        
        <h3 className={`${colors.primaryText} text-xl font-bold text-center mb-2`}>
          End Live Stream?
        </h3>
        
        <p className={`${colors.secondaryText} text-center mb-4`}>
          You've been live for <span className={`${colors.primaryText} font-semibold`}>{formatDuration(duration)}</span>. 
          Are you sure you want to end your broadcast?
        </p>
        
        <div className="flex gap-3">
          <Button
            onClick={onCancel}
            variant="outline"
            className={`flex-1 ${colors.border} ${colors.primaryText} ${colors.buttonBg}`}
          >
            Keep Streaming
          </Button>
          <Button
            onClick={onConfirm}
            className="flex-1 bg-red-600 hover:bg-red-700 text-white font-bold"
          >
            End Live
          </Button>
        </div>
      </motion.div>
    </div>
  );
};

/**
 * Broadcaster Controls Component - Main broadcasting interface
 * Modern features: Connection quality, surfer video filters, comment likes
 */
const BroadcasterControls = ({ 
  _onEnd, 
  onEndRequest, 
  streamDuration, 
  viewerCount,
  streamId,
  userId,
  userName,
  userAvatar
}) => {
  const { theme } = useTheme();
  const colors = useMemo(() => getThemeColors(theme), [theme]);
  
  const { localParticipant } = useLocalParticipant();
  const connectionState = useConnectionState();
  
  const [isMuted, setIsMuted] = useState(false);
  const [isCameraOff, setIsCameraOff] = useState(false);
  const [isFrontCamera, setIsFrontCamera] = useState(true);
  const [showComments, _setShowComments] = useState(true);
  const [isChatOpen, setIsChatOpen] = useState(true); // Desktop sidebar toggle
  const [commentsExpanded, setCommentsExpanded] = useState(false);
  const [emojiBursts, setEmojiBursts] = useState([]);
  const [likeCount, setLikeCount] = useState(0);
  const [showFilters, setShowFilters] = useState(false);
  const [showHairPicker, setShowHairPicker] = useState(false);
  const [activeHairStyle, setActiveHairStyle] = useState(null);
  const [videoFilters, setVideoFilters] = useState({ 
    brightness: 100, 
    contrast: 100,
    saturation: 100,
    warmth: 100,
    vignette: 0
  });
  
  const videoRef = useRef(null);
  const hairCanvasRef = useRef(null);
  const hairEngineRef = useRef(null);

  const tracks = useTracks([Track.Source.Camera], { onlySubscribed: false });
  const _localVideoTrack = tracks.find(t => t.participant?.isLocal);

  const toggleMute = async () => {
    if (localParticipant) {
      await localParticipant.setMicrophoneEnabled(isMuted);
      setIsMuted(!isMuted);
    }
  };

  const toggleCamera = async () => {
    if (localParticipant) {
      await localParticipant.setCameraEnabled(isCameraOff);
      setIsCameraOff(!isCameraOff);
    }
  };

  const flipCamera = async () => {
    if (localParticipant) {
      try {
        const newFacingMode = isFrontCamera ? 'environment' : 'user';
        
        // Stop current camera, then re-enable with new facing mode
        // This is more reliable on mobile than restartTrack
        await localParticipant.setCameraEnabled(false);
        
        // Small delay to let hardware release
        await new Promise(r => setTimeout(r, 300));
        
        await localParticipant.setCameraEnabled(true, {
          facingMode: newFacingMode,
        });
        
        setIsFrontCamera(!isFrontCamera);
        toast.success(isFrontCamera ? 'Switched to back camera' : 'Switched to front camera');
      } catch (err) {
        logger.error('Failed to flip camera:', err);
        // Try fallback: just re-enable camera without specifying facing mode
        try {
          await localParticipant.setCameraEnabled(true);
        } catch { /* silent */ }
        toast.error('Camera switch not supported on this device');
      }
    }
  };

  const handleFilterChange = useCallback((filter, value) => {
    setVideoFilters(prev => ({ ...prev, [filter]: value }));
  }, []);

  // Apply preset filter values mapping directly to WebGL state string bounds
  const handlePresetSelect = useCallback((preset) => {
    setVideoFilters({
      ...preset.values,
      presetName: preset.name
    });
    setShowFilters(false); // Auto-close panel on selection
    toast.success('AI Filter applied!');
  }, []);

  // Handle comment likes
  const handleLikeComment = useCallback(async (commentId, isLiked) => {
    await apiClient.post(`/social-live/${streamId}/comments/${commentId}/like`, {
      user_id: userId,
      liked: isLiked
    });
    // Throws on error so CommentTile can revert the optimistic update
  }, [streamId, userId]);

  const handleReaction = useCallback((emoji) => {
    // Add emoji burst animation
    const id = Date.now();
    const x = Math.random() * 100 + 100; // Random x position
    const y = window.innerHeight - 200;
    
    setEmojiBursts(prev => [...prev, { id, emoji, x, y }]);
    setLikeCount(prev => prev + 1);
    
    // Remove after animation
    setTimeout(() => {
      setEmojiBursts(prev => prev.filter(b => b.id !== id));
    }, 1500);
  }, []);

  // ── Hair Filter Engine lifecycle ──
  useEffect(() => {
    const engine = new HairFilterEngine();
    hairEngineRef.current = engine;
    engine.init().catch(() => {});
    
    return () => {
      engine.dispose();
      hairEngineRef.current = null;
    };
  }, []);
  
  // Start/stop hair engine when video element changes or camera toggles
  useEffect(() => {
    const engine = hairEngineRef.current;
    if (!engine) return;
    
    if (isCameraOff) {
      engine.stop();
      return;
    }
    
    // Find the video element inside the ref container
    const videoContainer = videoRef.current;
    if (!videoContainer) return;
    
    // Retry finding video element (LiveKit may render it async)
    const tryStart = () => {
      const videoEl = videoContainer.querySelector('video');
      const canvasEl = hairCanvasRef.current;
      
      if (videoEl && canvasEl && videoEl.readyState >= 1) {
        engine.start(videoEl, canvasEl); // start() now awaits init internally
        return true;
      }
      return false;
    };
    
    // Try immediately, then retry a few times
    if (!tryStart()) {
      const timer = setInterval(() => {
        if (tryStart()) clearInterval(timer);
      }, 500);
      
      // Give up after 5 seconds
      const timeout = setTimeout(() => clearInterval(timer), 5000);
      return () => { clearInterval(timer); clearTimeout(timeout); engine.stop(); };
    }
    
    return () => { engine.stop(); };
  }, [isCameraOff, connectionState]);
  
  // Update hair style when selection changes
  useEffect(() => {
    const engine = hairEngineRef.current;
    if (engine) {
      engine.setHairStyle(activeHairStyle);
    }
  }, [activeHairStyle]);
  
  const handleSelectHairStyle = useCallback((styleId) => {
    setActiveHairStyle(styleId);
    setShowHairPicker(false); // Auto-close picker on selection
    if (styleId) {
      toast.success('Hair filter applied! 💇');
    }
  }, []);

  const handleSendComment = useCallback(async (text) => {
    logger.info('[GoLiveModal] Attempting to send comment, streamId:', streamId, 'userName:', userName);
    if (!streamId) {
      logger.error('[GoLiveModal] No streamId available');
      toast.error('Stream not ready yet');
      return;
    }
    if (!userId) {
      logger.error('[GoLiveModal] No userId available');
      toast.error('Not logged in');
      return;
    }
    try {
      const response = await apiClient.post(`/social-live/${streamId}/comments`, {
        user_id: userId,
        user_name: userName || 'You',
        avatar_url: userAvatar || '',
        text
      });
      logger.info('[GoLiveModal] Comment sent successfully:', response.data);
    } catch (err) {
      logger.error('[GoLiveModal] Failed to send comment:', err.response?.data || err.message);
      toast.error('Failed to send comment');
    }
  }, [streamId, userId, userName, userAvatar]);

  const handleShare = useCallback(async () => {
    const shareUrl = `${window.location.origin}/live/${streamId}`;
    
    if (navigator.share) {
      try {
        await navigator.share({
          title: `${userName} is LIVE!`,
          text: 'Watch my live stream on Raw Surf',
          url: shareUrl
        });
      } catch (err) {
        if (err.name !== 'AbortError') {
          toast.error('Failed to share');
        }
      }
    } else {
      // Fallback: copy to clipboard
      try {
        await navigator.clipboard.writeText(shareUrl);
        toast.success('Stream link copied!');
      } catch {
        toast.error('Failed to copy link');
      }
    }
  }, [streamId, userName]);

  const formatDuration = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // CSS filter styles for video - includes all surfer-specific filters
  const videoFilterStyle = useMemo(() => {
    // Calculate AI mapping: warmth controls hue-rotate shift aggressively
    let warmthDegrees = (videoFilters.warmth - 100) * 0.8;
    
    // Extreme overrides for AI Lenses (if warmth is pushed to max/min limits, it triggers hyper-neon shifts)
    if (videoFilters.warmth >= 150) warmthDegrees = 300; // Neon blue/purple (AI Bioluminescence)
    if (videoFilters.warmth <= 50) warmthDegrees = 180; // Negative inversion vibe (Cyber)
    
    return {
      filter: `brightness(${videoFilters.brightness}%) contrast(${videoFilters.contrast}%) saturate(${videoFilters.saturation}%) hue-rotate(${warmthDegrees}deg)`,
      position: 'relative'
    };
  }, [videoFilters]);

  // Vignette overlay style
  const vignetteStyle = useMemo(() => {
    if (videoFilters.vignette === 0) return null;
    return {
      position: 'absolute',
      inset: 0,
      pointerEvents: 'none',
      background: `radial-gradient(circle, transparent ${100 - videoFilters.vignette}%, rgba(0,0,0,${videoFilters.vignette / 100}) 100%)`
    };
  }, [videoFilters.vignette]);

  return (
    <div className="w-full h-full flex flex-col sm:flex-row overflow-hidden" data-theme={theme}>
      {/* ── Main Video Section ── */}
      <div className="flex-1 relative bg-black flex flex-col min-w-0">
        {/* Actual Video */}
        <div className="flex-1 relative overflow-hidden">
          {!isCameraOff ? (
            <div ref={videoRef} className="w-full h-full relative" style={videoFilterStyle}>
              <WebGLBroadcastController 
                activeFilter={videoFilters.presetName || 'none'}
                isCameraOff={isCameraOff}
                isFrontCamera={isFrontCamera}
              />
              {/* Hair filter canvas overlay — matches WebGL canvas: video-resolution buffer + object-cover + mirror */}
              <canvas
                ref={hairCanvasRef}
                className={`absolute inset-0 w-full h-full object-cover pointer-events-none ${isFrontCamera ? 'scale-x-[-1]' : ''}`}
                style={{ zIndex: 5 }}
              />
              {/* Vignette overlay */}
              {vignetteStyle && <div style={vignetteStyle} />}
            </div>
          ) : (
            <div className="w-full h-full flex items-center justify-center bg-zinc-900">
              <CameraOff className="w-20 h-20 text-zinc-600" />
            </div>
          )}

          {/* Emoji burst animations */}
          <AnimatePresence>
            {emojiBursts.map(burst => (
              <EmojiBurst key={burst.id} {...burst} theme={theme} />
            ))}
          </AnimatePresence>

          {/* Top bar - Overlaid ONLY on video */}
          <div className={`absolute top-0 left-0 right-0 p-3 sm:p-4 bg-gradient-to-b ${colors.gradientTop} safe-area-top z-10`}>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 sm:gap-3 flex-wrap">
                <div className="flex items-center gap-2 bg-red-600 px-3 py-1.5 rounded-full animate-pulse">
                  <Radio className="w-4 h-4 text-white" />
                  <span className="text-white font-bold text-sm">LIVE</span>
                </div>
                
                <div className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-full ${colors.overlayBg}`}>
                  <Clock className={`w-3.5 h-3.5 ${colors.primaryText}`} />
                  <span className={`${colors.primaryText} font-mono text-sm`}>{formatDuration(streamDuration)}</span>
                </div>
                
                <div className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-full ${colors.overlayBg}`}>
                  <Eye className={`w-3.5 h-3.5 ${colors.primaryText}`} />
                  <span className={`${colors.primaryText} text-sm`}>{viewerCount}</span>
                </div>
                
                <ConnectionQualityBadge state={connectionState} />
              </div>

              <div className="flex items-center gap-2">
                <div className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-full ${colors.overlayBg}`}>
                  <Heart className={`w-3.5 h-3.5 text-red-500 ${likeCount > 0 ? 'fill-red-500' : ''}`} />
                  <span className={`${colors.primaryText} text-sm`}>{likeCount}</span>
                </div>
                
                {/* Desktop: Sidebar Toggle Button */}
                <button
                  onClick={() => setIsChatOpen(!isChatOpen)}
                  className={`hidden sm:flex p-2 rounded-full ${colors.overlayBg} ${isChatOpen ? colors.accentBg : ''} transition-all`}
                  title={isChatOpen ? "Close Chat" : "Open Chat"}
                >
                  <MessageCircle className={`w-4 h-4 ${isChatOpen ? 'text-white' : colors.primaryText}`} />
                </button>

                <button
                  onClick={handleShare}
                  className={`p-2 rounded-full ${colors.overlayBg} transition-transform active:scale-95`}
                  title="Share Stream"
                >
                  <Share2 className={`w-4 h-4 ${colors.primaryText}`} />
                </button>
              </div>
            </div>
          </div>

          {/* Floating Side items - Filters/Camera Flip (Desktop & Mobile Matrix Shifted vertically) */}
          <div className="absolute right-3 top-1/4 sm:top-1/2 -translate-y-1/2 flex flex-col gap-3 z-10">
            <button
              onClick={flipCamera}
              className={`p-3 rounded-full ${colors.overlayBg} ${colors.border} border transition-all active:scale-95 shadow-md`}
              title="Flip Camera"
            >
              <RefreshCw className={`w-5 h-5 ${colors.primaryText}`} />
            </button>

            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`p-3 rounded-full ${colors.overlayBg} ${colors.border} border transition-all active:scale-95 shadow-md ${showFilters ? colors.accentBg : ''}`}
              title="Surf Filters"
            >
              <Sparkles className={`w-5 h-5 ${showFilters ? 'text-white' : colors.primaryText}`} />
            </button>

            <button
              onClick={() => setShowHairPicker(!showHairPicker)}
              className={`p-3 rounded-full ${colors.overlayBg} ${colors.border} border transition-all active:scale-95 shadow-md ${showHairPicker ? 'bg-yellow-500' : activeHairStyle ? 'bg-yellow-500/30 border-yellow-500/50' : ''}`}
              title="Hair Filters"
            >
              <Scissors className={`w-5 h-5 ${showHairPicker || activeHairStyle ? 'text-white' : colors.primaryText}`} />
            </button>
          </div>

          {/* Video Filter Panel */}
          <AnimatePresence>
            {showFilters && (
              <VideoFilterPanel
                isOpen={showFilters}
                onClose={() => setShowFilters(false)}
                filters={videoFilters}
                onFilterChange={handleFilterChange}
                onPresetSelect={handlePresetSelect}
                colors={colors}
              />
            )}
          </AnimatePresence>

          {/* Hair Filter Picker Panel */}
          <AnimatePresence>
            {showHairPicker && (
              <HairFilterPicker
                isOpen={showHairPicker}
                onClose={() => setShowHairPicker(false)}
                activeStyleId={activeHairStyle}
                onSelectHair={handleSelectHairStyle}
                colors={colors}
              />
            )}
          </AnimatePresence>
          
          {/* Reaction Overlay */}
          <div className="absolute bottom-[84px] left-4 z-10">
            <QuickReactions onReact={handleReaction} colors={colors} />
          </div>

          {/* ── BROADCASTER CONTROLS: float over video bottom ── */}
          <div style={{
            position: 'absolute', bottom: 0, left: 0, right: 0, zIndex: 20,
            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            padding: '16px 24px',
            background: 'linear-gradient(to top, rgba(0,0,0,0.92) 0%, rgba(0,0,0,0.55) 60%, transparent 100%)'
          }}>
            {/* Left: Mic + Camera */}
            <div style={{ display: 'flex', gap: 10 }}>
              <button
                onClick={toggleMute}
                style={{ padding: 11, borderRadius: '50%', border: 'none', cursor: 'pointer', backdropFilter: 'blur(6px)', background: isMuted ? '#dc2626' : 'rgba(255,255,255,0.18)', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                title={isMuted ? 'Unmute' : 'Mute'}
              >
                {isMuted ? <MicOff style={{ width: 20, height: 20 }} /> : <Mic style={{ width: 20, height: 20 }} />}
              </button>
              <button
                onClick={toggleCamera}
                style={{ padding: 11, borderRadius: '50%', border: 'none', cursor: 'pointer', backdropFilter: 'blur(6px)', background: isCameraOff ? '#dc2626' : 'rgba(255,255,255,0.18)', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                title={isCameraOff ? 'Camera On' : 'Camera Off'}
              >
                {isCameraOff ? <CameraOff style={{ width: 20, height: 20 }} /> : <Camera style={{ width: 20, height: 20 }} />}
              </button>
            </div>

            {/* Center: End Live */}
            <button
              onClick={onEndRequest}
              style={{ padding: '11px 28px', background: '#dc2626', color: '#fff', fontWeight: 700, fontSize: 15, borderRadius: 999, border: 'none', cursor: 'pointer', boxShadow: '0 4px 18px rgba(220,38,38,0.45)' }}
            >
              End Live
            </button>

            {/* Right: Status */}
            <p style={{ color: 'rgba(255,255,255,0.5)', fontSize: 11, textAlign: 'right', maxWidth: 110, margin: 0, lineHeight: 1.4 }}>
              {connectionState === ConnectionState.Connected
                ? (viewerCount > 0 ? `${viewerCount} watching` : 'Waiting for surfers...')
                : 'Connection issue'}
            </p>
          </div>
        </div>{/* end video+overlay area */}
      </div>{/* end video column */}

      {/* ── Desktop Sidebar: Live Chat ── */}
      <AnimatePresence>
        {isChatOpen && (
          <motion.div
            className="hidden sm:flex flex-col"
            initial={{ width: 0, opacity: 0 }}
            animate={{ width: 310, opacity: 1 }}
            exit={{ width: 0, opacity: 0 }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            style={{ height: '100%', background: '#09090b', borderLeft: '1px solid #27272a', flexShrink: 0, overflow: 'hidden' }}
          >
            <LiveCommentsFeed
              streamId={streamId}
              colors={colors}
              onSendComment={handleSendComment}
              onLikeComment={handleLikeComment}
              currentUserId={userId}
              isExpanded={true} // Always expanded in sidebar
              onToggleExpand={() => {}} // No toggle in sidebar
            />
          </motion.div>
        )}
      </AnimatePresence>

      {/* Mobile-only overlay elements */}
      <div className="sm:hidden absolute bottom-[140px] left-3 right-3 z-30 pointer-events-none">
        {showComments && (
          <div className="pointer-events-auto">
            <LiveCommentsFeed
              streamId={streamId}
              colors={colors}
              onSendComment={handleSendComment}
              onLikeComment={handleLikeComment}
              currentUserId={userId}
              isExpanded={commentsExpanded}
              onToggleExpand={() => setCommentsExpanded(!commentsExpanded)}
            />
          </div>
        )}
      </div>

      <RoomAudioRenderer />
    </div>
  );
};

/**
 * GoLiveModal - Full-screen live streaming with LiveKit
 * Phase machine: pre_live → countdown → live
 * No auto-start. User must explicitly press Go Live.
 */
const GoLiveModal = ({ isOpen, onClose, onStreamEnded }) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const colors = useMemo(() => getThemeColors(theme), [theme]);
  
  // Phase state: 'pre_live' | 'countdown' | 'live'
  const [phase, setPhase] = useState('pre_live');
  const [streamTitle, setStreamTitle] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [broadcasterToken, setBroadcasterToken] = useState(null);
  const [streamData, setStreamData] = useState(null);
  const [streamDuration, setStreamDuration] = useState(0);
  const [viewerCount, setViewerCount] = useState(0);
  const [showEndDialog, setShowEndDialog] = useState(false);
  const [_isConnected, setIsConnected] = useState(false);
  const [countdownValue, setCountdownValue] = useState(3);
  const [signalQuality, setSignalQuality] = useState('unknown'); // 'excellent'|'good'|'poor'|'unknown'
  const [cameraPreviewStream, setCameraPreviewStream] = useState(null);
  const previewVideoRef = useRef(null);
  
  const streamDurationRef = useRef(0);
  const durationIntervalRef = useRef(null);
  const viewerPollRef = useRef(null);
  const streamDataRef = useRef(null);
  const userIdRef = useRef(user?.id);

  useEffect(() => {
    streamDataRef.current = streamData;
  }, [streamData]);

  // Keep userIdRef in sync to avoid stale closure in cleanup
  useEffect(() => {
    userIdRef.current = user?.id;
  }, [user?.id]);

  // ── Reset phase when modal opens/closes ──
  useEffect(() => {
    if (isOpen) {
      setPhase('pre_live');
      setError(null);
      setBroadcasterToken(null);
      setStreamData(null);
      setStreamDuration(0);
      setViewerCount(0);
      setCountdownValue(3);
      startCameraPreview();
      checkSignalQuality();
    } else {
      stopCameraPreview();
    }
    return () => {
      if (durationIntervalRef.current) clearInterval(durationIntervalRef.current);
      if (viewerPollRef.current) clearInterval(viewerPollRef.current);
      // Auto-teardown orphan stream if user force-closes while live
      if (streamDataRef.current?.id && userIdRef.current) {
        logger.info('[GoLiveModal] Unmount trapped active stream. Firing orphan teardown.');
        apiClient.post(`/livekit/end-stream/${streamDataRef.current.id}?broadcaster_id=${userIdRef.current}`).catch(() => {});
      }
    };
  }, [isOpen]);

  // ── Camera preview for pre-live screen ──
  const startCameraPreview = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false });
      setCameraPreviewStream(stream);
      if (previewVideoRef.current) {
        previewVideoRef.current.srcObject = stream;
      }
    } catch (err) {
      logger.warn('[GoLiveModal] Camera preview unavailable:', err);
      // Not fatal — user may grant camera on actual go-live
    }
  }, []);

  const stopCameraPreview = useCallback(() => {
    setCameraPreviewStream(prev => {
      if (prev) prev.getTracks().forEach(t => t.stop());
      return null;
    });
  }, []);

  // Wire preview video element to stream when ref + stream are both ready
  useEffect(() => {
    if (previewVideoRef.current && cameraPreviewStream) {
      previewVideoRef.current.srcObject = cameraPreviewStream;
    }
  }, [cameraPreviewStream]);

  // ── Signal quality estimation via navigator.connection or RTT probe ──
  const checkSignalQuality = useCallback(async () => {
    setSignalQuality('unknown');
    try {
      // navigator.connection (Chrome/Android)
      const conn = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
      if (conn) {
        const rtt = conn.rtt || 0;
        const downlink = conn.downlink || 10;
        if (rtt > 300 || downlink < 1) {
          setSignalQuality('poor');
        } else if (rtt > 100 || downlink < 5) {
          setSignalQuality('good');
        } else {
          setSignalQuality('excellent');
        }
        return;
      }
      // Fallback: time a small fetch
      const start = Date.now();
      await fetch(`${process.env.REACT_APP_BACKEND_URL}/api/health`, { method: 'HEAD', cache: 'no-store' }).catch(() => {});
      const rtt = Date.now() - start;
      if (rtt > 500) setSignalQuality('poor');
      else if (rtt > 200) setSignalQuality('good');
      else setSignalQuality('excellent');
    } catch {
      setSignalQuality('unknown');
    }
  }, []);

  // ── Start stream (called after countdown) ──
  const startStream = useCallback(async () => {
    if (!user?.id) {
      setError('Please log in to go live');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      logger.info('[GoLiveModal] Starting social live stream...');
      
      const response = await apiClient.post(`/livekit/start-social-live`, {
        broadcaster_id: user.id,
        broadcaster_name: user.full_name || user.username || 'Broadcaster',
        title: streamTitle || undefined
      });

      logger.info('[GoLiveModal] Stream started:', response.data);

      // Stop camera preview — LiveKit will take over camera
      stopCameraPreview();

      setBroadcasterToken({
        token: response.data.token,
        server_url: response.data.server_url
      });
      
      setStreamData({
        id: response.data.stream_id,
        room_name: response.data.room_name
      });

      // Duration timer
      streamDurationRef.current = 0;
      durationIntervalRef.current = setInterval(() => {
        streamDurationRef.current += 1;
        setStreamDuration(streamDurationRef.current);
      }, 1000);

      // Viewer count polling
      viewerPollRef.current = setInterval(async () => {
        try {
          const activeStreams = await apiClient.get(`/livekit/active-streams`);
          const myStream = activeStreams.data.streams?.find(
            s => s.room_name === response.data.room_name
          );
          if (myStream) setViewerCount(myStream.viewer_count);
        } catch (e) { /* non-critical */ }
      }, 5000);

      setPhase('live');

    } catch (err) {
      logger.error('[GoLiveModal] Failed to start stream:', err);
      setError(err.response?.data?.detail || 'Failed to start live stream');
      setPhase('pre_live'); // Return to pre-live on error
    } finally {
      setIsLoading(false);
    }
  }, [user, streamTitle, stopCameraPreview]);

  // ── Initiate countdown then start stream ──
  const handleGoLive = useCallback(() => {
    if (signalQuality === 'poor') {
      toast.warning('⚠️ Poor signal detected. Your stream may be unstable.');
      // Don't block — let user decide
    }
    setPhase('countdown');
    setCountdownValue(3);
  }, [signalQuality]);

  // ── Countdown tick → triggers startStream when done ──
  useEffect(() => {
    if (phase !== 'countdown') return;
    if (countdownValue <= 0) {
      startStream();
      return;
    }
    const timer = setTimeout(() => setCountdownValue(v => v - 1), 1000);
    return () => clearTimeout(timer);
  }, [phase, countdownValue, startStream]);

  // ── End stream ──
  const endStream = useCallback(async () => {
    logger.info('[GoLiveModal] Ending stream...');
    
    if (durationIntervalRef.current) {
      clearInterval(durationIntervalRef.current);
      durationIntervalRef.current = null;
    }
    if (viewerPollRef.current) {
      clearInterval(viewerPollRef.current);
      viewerPollRef.current = null;
    }

    if (streamData?.id) {
      try {
        await apiClient.post(`/livekit/end-stream/${streamData.id}?broadcaster_id=${user.id}`);
      } catch (e) {
        logger.error('[GoLiveModal] Error ending stream on backend:', e);
      }
    }

    setBroadcasterToken(null);
    setStreamData(null);
    setStreamDuration(0);
    setViewerCount(0);
    setShowEndDialog(false);
    setIsConnected(false);
    setPhase('pre_live');
    
    onStreamEnded?.();
    onClose();
  }, [streamData, user, onStreamEnded, onClose]);

  // ── Phase-aware close handler ──
  const handleClose = useCallback(() => {
    if (phase === 'live' || phase === 'countdown') {
      // During live or countdown: require confirmation
      if (phase === 'countdown') {
        // Abort countdown — just go back to pre-live
        setPhase('pre_live');
        return;
      }
      setShowEndDialog(true);
    } else {
      // Pre-live: clean close
      stopCameraPreview();
      onClose();
    }
  }, [phase, stopCameraPreview, onClose]);

  // Prevent body scroll
  useEffect(() => {
    if (isOpen) document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = ''; };
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    /* ── Mobile: fullscreen  |  Desktop: centred popup ── */
    <div className="fixed inset-0 z-[99999] flex items-center justify-center p-0 sm:p-6" data-testid="go-live-modal" data-theme={theme}>
      {/* Dark backdrop — click away closes only if pre-live or shows confirmation if live */}
      <div
        className="fixed inset-0 bg-black/80 backdrop-blur-sm hidden sm:block"
        onClick={handleClose}
      />
      {/* Inner container — fullscreen on mobile, popup on desktop */}
      <div className="relative w-full h-full sm:w-[1100px] sm:h-[720px] sm:max-h-[90vh] sm:rounded-2xl sm:overflow-hidden bg-black shadow-2xl shadow-black/60">

        {/* ── PRE-LIVE SCREEN ── */}
        <AnimatePresence>
          {phase === 'pre_live' && (
            <motion.div
              key="pre-live"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 flex flex-col bg-zinc-950"
            >
              {/* Header */}
              <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-800 flex-shrink-0">
                <button
                  onClick={handleClose}
                  className="p-2 rounded-full hover:bg-zinc-800 transition-colors"
                >
                  <X className="w-5 h-5 text-zinc-400" />
                </button>
                <span className="text-white font-semibold text-base">Live Video</span>
                <div className="w-9" />{/* spacer */}
              </div>

              {/* Camera Preview */}
              <div className="flex-1 relative bg-zinc-900 overflow-hidden">
                <video
                  ref={previewVideoRef}
                  autoPlay
                  muted
                  playsInline
                  className="w-full h-full object-cover"
                  style={{ transform: 'scaleX(-1)' }}
                />
                {/* Mirror front camera for natural selfie view */}
                {/* No camera fallback */}
                {!cameraPreviewStream && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center gap-3">
                    <CameraOff className="w-16 h-16 text-zinc-600" />
                    <p className="text-zinc-500 text-sm">Camera preview unavailable</p>
                    <p className="text-zinc-600 text-xs">Camera access will be requested when you go live</p>
                  </div>
                )}

                {/* Signal quality overlay — top right */}
                <div className="absolute top-3 right-3">
                  <ConnectionQualityBadge quality={signalQuality} />
                  {signalQuality === 'poor' && (
                    <motion.div
                      initial={{ opacity: 0, y: -8 }}
                      animate={{ opacity: 1, y: 0 }}
                      className="mt-2 flex items-start gap-2 bg-red-950/90 border border-red-700/50 rounded-xl px-3 py-2 max-w-[200px]"
                    >
                      <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                      <p className="text-red-300 text-xs leading-snug">
                        Poor signal detected. Your stream may buffer or disconnect.
                      </p>
                    </motion.div>
                  )}
                </div>

                {/* Recheck signal button */}
                <button
                  onClick={checkSignalQuality}
                  className="absolute bottom-3 right-3 flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-zinc-800/80 text-zinc-400 text-xs hover:bg-zinc-700/80 transition-colors"
                >
                  <RefreshCw className="w-3 h-3" />
                  Check signal
                </button>
              </div>

              {/* Bottom controls */}
              <div className="flex-shrink-0 bg-zinc-950 border-t border-zinc-800 p-4">
                {/* Stream title input */}
                <div className="mb-4">
                  <input
                    type="text"
                    value={streamTitle}
                    onChange={e => setStreamTitle(e.target.value)}
                    placeholder="Add a title for your live (optional)"
                    maxLength={80}
                    className="w-full bg-zinc-800 border border-zinc-700 rounded-xl px-4 py-2.5 text-white text-sm placeholder:text-zinc-500 focus:outline-none focus:border-red-500/60 transition-colors"
                  />
                </div>

                {/* Tips row */}
                <div className="flex items-center gap-2 mb-4 text-zinc-500">
                  <Info className="w-3.5 h-3.5 flex-shrink-0" />
                  <p className="text-xs">Your followers will be notified when you go live. You can mute or flip your camera at any time.</p>
                </div>

                {/* Go Live button */}
                <button
                  onClick={handleGoLive}
                  className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl bg-red-600 hover:bg-red-500 active:scale-[0.98] transition-all font-bold text-white text-lg shadow-lg shadow-red-900/40"
                >
                  <Radio className="w-5 h-5" />
                  Go Live
                  <ChevronRight className="w-5 h-5" />
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* ── COUNTDOWN OVERLAY ── */}
        <AnimatePresence>
          {phase === 'countdown' && (
            <motion.div
              key="countdown"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 flex flex-col items-center justify-center bg-black z-50"
            >
              {/* Abort countdown button */}
              <button
                onClick={() => setPhase('pre_live')}
                className="absolute top-4 left-4 flex items-center gap-2 px-3 py-2 rounded-full bg-zinc-800/80 text-zinc-400 text-sm hover:bg-zinc-700 transition-colors"
              >
                <ArrowLeft className="w-4 h-4" />
                Cancel
              </button>

              <AnimatePresence mode="wait">
                {countdownValue > 0 ? (
                  <motion.div
                    key={countdownValue}
                    initial={{ scale: 2, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0.5, opacity: 0 }}
                    transition={{ duration: 0.4, ease: 'easeOut' }}
                    className="text-center"
                  >
                    <div className="relative w-48 h-48 mx-auto mb-6">
                      {/* Pulsing ring */}
                      <div className="absolute inset-0 rounded-full border-4 border-red-500/30 animate-ping" />
                      <div className="absolute inset-0 rounded-full border-4 border-red-500/60" />
                      {/* Countdown number */}
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-8xl font-black text-white tabular-nums">{countdownValue}</span>
                      </div>
                    </div>
                    <p className="text-zinc-400 text-lg font-medium">Get ready...</p>
                    <p className="text-zinc-600 text-sm mt-1">Your live stream is about to begin</p>
                  </motion.div>
                ) : (
                  <motion.div
                    key="go"
                    initial={{ scale: 0.5, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    className="text-center"
                  >
                    <div className="w-24 h-24 rounded-full bg-red-600 flex items-center justify-center mx-auto mb-4 animate-pulse">
                      <Radio className="w-12 h-12 text-white" />
                    </div>
                    <p className="text-white text-2xl font-black tracking-widest">LIVE</p>
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Signal quality reminder */}
              {signalQuality === 'poor' && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="absolute bottom-8 flex items-center gap-2 bg-red-950/80 border border-red-700/40 rounded-xl px-4 py-2.5"
                >
                  <AlertTriangle className="w-4 h-4 text-red-400" />
                  <span className="text-red-300 text-sm">Poor signal — stream may be unstable</span>
                </motion.div>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        {/* ── LOADING (connecting after countdown) ── */}
        {isLoading && (
          <div className="absolute inset-0 flex items-center justify-center bg-black z-40">
            <div className="text-center">
              <div className="relative w-20 h-20 mx-auto mb-6">
                <div className="absolute inset-0 rounded-full border-4 border-red-500/30 animate-ping" />
                <div className="absolute inset-0 rounded-full border-4 border-red-500 border-t-transparent animate-spin" />
              </div>
              <p className="text-white text-lg">Connecting your live stream...</p>
              <p className="text-zinc-500 text-sm mt-1">Hang tight, almost there</p>
            </div>
          </div>
        )}

        {/* ── ERROR STATE ── */}
        {error && !isLoading && (
          <div className="absolute inset-0 flex items-center justify-center bg-black p-6 z-40">
            <div className={`${colors.overlayBg} rounded-2xl p-6 max-w-sm text-center`}>
              <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
              <h3 className={`${colors.primaryText} text-lg font-bold mb-2`}>Unable to Go Live</h3>
              <p className={`${colors.secondaryText} mb-6`}>{error}</p>
              <div className="flex gap-3">
                <Button onClick={handleClose} variant="outline" className="flex-1">
                  Cancel
                </Button>
                <Button onClick={() => { setError(null); handleGoLive(); }} className="flex-1 bg-red-600 hover:bg-red-700 text-white">
                  Try Again
                </Button>
              </div>
            </div>
          </div>
        )}

        {/* ── LIVE BROADCAST ── */}
        {phase === 'live' && broadcasterToken && !error && (
          <div className="relative w-full h-full">
            <LiveKitRoom
              token={broadcasterToken.token}
              serverUrl={broadcasterToken.server_url}
              video={false}
              audio={true}
              connect={true}
              onConnected={() => setIsConnected(true)}
              onDisconnected={() => {
                logger.info('[GoLiveModal] Disconnected from room');
              }}
              style={{ position: 'relative', width: '100%', height: '100%' }}
            >
              <BroadcasterControls
                onEnd={endStream}
                onEndRequest={() => setShowEndDialog(true)}
                streamDuration={streamDuration}
                viewerCount={viewerCount}
                streamId={streamData?.id}
                userId={user?.id}
                userName={user?.username ? `@${user.username}` : (user?.full_name || user?.email?.split('@')[0] || 'You')}
                userAvatar={user?.avatar_url}
              />
            </LiveKitRoom>
          </div>
        )}

        {/* ── End stream confirmation dialog ── */}
        <EndStreamDialog
          isOpen={showEndDialog}
          onConfirm={endStream}
          onCancel={() => setShowEndDialog(false)}
          duration={streamDuration}
          colors={colors}
        />
      </div>{/* End of inner container */}
    </div>
  );
};

export default GoLiveModal;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 

  Shield, Users, DollarSign, Clock, Trophy, Plus,
  Settings, ChevronRight, CheckCircle, XCircle,
  ShoppingBag, Activity, Bell, UserPlus,
  CreditCard, ShieldCheck, ShieldAlert, ArrowRight, Loader2, Unlink,
  KeyRound, UserX
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import {

  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from './ui/dialog';
import apiClient from '../lib/apiClient';
import { toast } from 'sonner';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';
import { PurchaseRequestsPanel } from './grom/PurchaseRequestsPanel';



/**
 * Grom HQ - Parental Management Dashboard
 * For Grom Parent users to manage their linked Grom children
 * Features: Linked Groms list, Activity monitoring, Spending controls, Safety settings, Age Verification
 */
export const GromHQ = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  
  const [loading, setLoading] = useState(true);
  const [linkedGroms, setLinkedGroms] = useState([]);
  const [pendingRequests, setPendingRequests] = useState([]);
  const [stats, setStats] = useState({
    totalEarnings: 0,
    totalSessions: 0,
    totalScreenTime: 0,
    achievementsUnlocked: 0
  });
  const [ageVerified, setAgeVerified] = useState(false);
  const [verifyingAge, setVerifyingAge] = useState(false);
  
  // Unlink modal state
  const [unlinkModalOpen, setUnlinkModalOpen] = useState(false);
  const [unlinkPassword, setUnlinkPassword] = useState('');
  const [unlinkingGrom, setUnlinkingGrom] = useState(null);
  const [unlinkLoading, setUnlinkLoading] = useState(false);
  
  // Spending alerts state
  const [spendingAlerts, setSpendingAlerts] = useState([]);
  
  // Family Activity Feed state
  const [activityFeed, setActivityFeed] = useState([]);
  const [activityLoading, setActivityLoading] = useState(false);
  const [showActivityFeed, setShowActivityFeed] = useState(false);

  // Theme classes
  const isLight = theme === 'light';
  const cardBg = isLight ? 'bg-white' : 'bg-zinc-900';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  const borderColor = isLight ? 'border-gray-200' : 'border-zinc-800';

  useEffect(() => {
    fetchGromData();
    checkAgeVerification();
    fetchSpendingAlerts();
    fetchActivityFeed();
  }, [user?.id]);

  const fetchGromData = async () => {
    if (!user?.id) return;
    setLoading(true);
    
    try {
      // Fetch linked Groms
      const gromsResponse = await apiClient.get(`/grom-hq/linked-groms/${user.id}`);
      setLinkedGroms(gromsResponse.data.linked_groms || []);
      setPendingRequests(gromsResponse.data.pending_requests || []);
      setStats(gromsResponse.data.stats || {
        totalEarnings: 0,
        totalSessions: 0,
        totalScreenTime: 0,
        achievementsUnlocked: 0
      });
    } catch (error) {
      logger.error('Failed to fetch Grom HQ data:', error);
      // Use defaults on error
      setLinkedGroms([]);
      setPendingRequests([]);
    } finally {
      setLoading(false);
    }
  };

  const checkAgeVerification = async () => {
    if (!user?.id) return;
    try {
      const response = await apiClient.get(`/grom-hq/age-verification-status/${user.id}`);
      setAgeVerified(response.data.age_verified || false);
    } catch (error) {
      logger.error('Failed to check age verification:', error);
    }
  };

  const fetchSpendingAlerts = async () => {
    if (!user?.id) return;
    try {
      const response = await apiClient.get(`/grom-hq/spending-alerts/${user.id}?limit=5`);
      setSpendingAlerts(response.data.alerts || []);
    } catch (error) {
      logger.error('Failed to fetch spending alerts:', error);
    }
  };
  
  const fetchActivityFeed = async () => {
    if (!user?.id) return;
    setActivityLoading(true);
    try {
      const response = await apiClient.get(`/grom-hq/family-activity/${user.id}?limit=20`);
      setActivityFeed(response.data.activities || []);
    } catch (error) {
      logger.error('Failed to fetch activity feed:', error);
      setActivityFeed([]);
    } finally {
      setActivityLoading(false);
    }
  };

  const handleMarkAlertRead = async (alertId) => {
    try {
      await apiClient.post(`/grom-hq/spending-alerts/${alertId}/read`);
      setSpendingAlerts(prev => prev.filter(a => a.id !== alertId));
    } catch (error) {
      logger.error('Failed to mark alert read:', error);
    }
  };

  const startAgeVerification = async () => {
    setVerifyingAge(true);
    try {
      const response = await apiClient.post(`/grom-hq/create-age-verification/${user.id}`, {
        return_url: window.location.href
      });
      
      if (response.data.already_verified) {
        setAgeVerified(true);
        toast.success('You are already age verified!');
        return;
      }
      
      // Open Stripe Identity verification
      if (response.data.verification_session_id) {
        const sessionId = response.data.verification_session_id;
        
        toast.info('Opening secure identity verification...');
        
        // Open Stripe hosted verification page
        window.open(
          `https://verify.stripe.com/start/${sessionId}`,
          '_blank'
        );
        
        // Poll for verification completion
        toast.info('Complete the verification in the new window. We\'ll update your status automatically.');
        
        const checkStatus = async () => {
          try {
            const statusResponse = await apiClient.post(
              `/grom-hq/verify-age-complete/${user.id}?verification_session_id=${sessionId}`
            );
            
            if (statusResponse.data.success && statusResponse.data.age_verified) {
              setAgeVerified(true);
              toast.success('Guardian Verified! You can now link and manage Grom accounts.');
              return true;
            } else if (statusResponse.data.status === 'verified') {
              setAgeVerified(true);
              toast.success('Guardian Verified!');
              return true;
            }
            return false;
          } catch (e) {
            return false;
          }
        };
        
        // Poll every 5 seconds for up to 5 minutes
        let attempts = 0;
        const maxAttempts = 60;
        const pollInterval = setInterval(async () => {
          attempts++;
          const verified = await checkStatus();
          if (verified || attempts >= maxAttempts) {
            clearInterval(pollInterval);
            if (!verified && attempts >= maxAttempts) {
              toast.info('Verification check timed out. Click "Verify Age" again if you completed it.');
            }
          }
        }, 5000);
      } else {
        toast.error('Failed to create verification session. Please try again.');
      }
      
    } catch (error) {
      logger.error('Failed to start age verification:', error);
      const errorMessage = error.response?.data?.detail || 'Failed to start age verification';
      toast.error(errorMessage);
    } finally {
      setVerifyingAge(false);
    }
  };

  const handleUnlinkGrom = async () => {
    if (!unlinkingGrom || !unlinkPassword) return;
    
    setUnlinkLoading(true);
    try {
      await apiClient.post(
        `/grom-hq/unlink-grom/${unlinkingGrom.id}?parent_id=${user.id}`,
        { password: unlinkPassword }
      );
      
      toast.success(`Unlinked ${unlinkingGrom.full_name}`);
      setUnlinkModalOpen(false);
      setUnlinkPassword('');
      setUnlinkingGrom(null);
      
      // Refresh data
      fetchGromData();
    } catch (error) {
      if (error.response?.status === 401) {
        toast.error('Incorrect password');
      } else {
        toast.error('Failed to unlink Grom');
      }
    } finally {
      setUnlinkLoading(false);
    }
  };

  const openUnlinkModal = (grom) => {
    setUnlinkingGrom(grom);
    setUnlinkPassword('');
    setUnlinkModalOpen(true);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${isLight ? 'bg-gray-50' : 'bg-black'} pb-24 md:pb-8`}>
      {/* Header */}
      <div className="bg-gradient-to-r from-cyan-500 to-blue-600 px-4 py-6">
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-12 h-12 rounded-full bg-white/20 flex items-center justify-center">
              <Shield className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-white">Grom HQ</h1>
              <p className="text-cyan-100 text-sm">Parental Management Dashboard</p>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 py-6 space-y-6">
        {/* Quick Stats */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Card className={`${cardBg} ${borderColor}`}>
            <CardContent className="p-4 text-center">
              <Users className="w-6 h-6 text-cyan-400 mx-auto mb-2" />
              <div className={`text-2xl font-bold ${textPrimary}`}>{linkedGroms.length}</div>
              <div className={`text-xs ${textSecondary}`}>Linked Groms</div>
            </CardContent>
          </Card>
          
          <Card className={`${cardBg} ${borderColor}`}>
            <CardContent className="p-4 text-center">
              <DollarSign className="w-6 h-6 text-emerald-400 mx-auto mb-2" />
              <div className={`text-2xl font-bold ${textPrimary}`}>${stats.totalEarnings?.toFixed(0) || 0}</div>
              <div className={`text-xs ${textSecondary}`}>Total Earnings</div>
            </CardContent>
          </Card>
          
          <Card className={`${cardBg} ${borderColor}`}>
            <CardContent className="p-4 text-center">
              <Clock className="w-6 h-6 text-yellow-400 mx-auto mb-2" />
              <div className={`text-2xl font-bold ${textPrimary}`}>{stats.totalSessions || 0}</div>
              <div className={`text-xs ${textSecondary}`}>Sessions Joined</div>
            </CardContent>
          </Card>
          
          <Card className={`${cardBg} ${borderColor}`}>
            <CardContent className="p-4 text-center">
              <Trophy className="w-6 h-6 text-amber-400 mx-auto mb-2" />
              <div className={`text-2xl font-bold ${textPrimary}`}>{stats.achievementsUnlocked || 0}</div>
              <div className={`text-xs ${textSecondary}`}>Achievements</div>
            </CardContent>
          </Card>
        </div>

        {/* Pending Link Requests */}
        {pendingRequests.length > 0 && (
          <Card className={`${cardBg} border-2 border-yellow-500/50`}>
            <CardHeader className="pb-2">
              <CardTitle className={`${textPrimary} flex items-center gap-2 text-base`}>
                <Bell className="w-5 h-5 text-yellow-400" />
                Pending Link Requests
                <Badge className="ml-auto bg-yellow-500/20 text-yellow-400 border-0">
                  {pendingRequests.length} NEW
                </Badge>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              {pendingRequests.map((request) => (
                <div 
                  key={request.id}
                  className={`flex items-center gap-3 p-3 rounded-xl ${isLight ? 'bg-gray-50' : 'bg-zinc-800'}`}
                >
                  <Avatar className="w-12 h-12 border-2 border-yellow-500/30">
                    <AvatarImage src={getFullUrl(request.avatar_url)} />
                    <AvatarFallback className="bg-yellow-500/20 text-yellow-400">
                      {request.full_name?.[0] || 'G'}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex-1">
                    <p className={`font-medium ${textPrimary}`}>{request.full_name}</p>
                    <p className={`text-xs ${textSecondary}`}>Requesting to link as your Grom</p>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" className="bg-emerald-500 hover:bg-emerald-600 text-white">
                      <CheckCircle className="w-4 h-4" />
                    </Button>
                    <Button size="sm" variant="outline" className="border-red-500/50 text-red-400">
                      <XCircle className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              ))}
            </CardContent>
          </Card>
        )}

        {/* Spending Alerts */}
        {spendingAlerts.length > 0 && (
          <Card className={`${cardBg} border-2 border-orange-500/50`} data-testid="spending-alerts-card">
            <CardHeader className="pb-2">
              <CardTitle className={`${textPrimary} flex items-center gap-2 text-base`}>
                <CreditCard className="w-5 h-5 text-orange-400" />
                Spending Alerts
                <Badge className="ml-auto bg-orange-500/20 text-orange-400 border-0">
                  {spendingAlerts.length} ALERT{spendingAlerts.length > 1 ? 'S' : ''}
                </Badge>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              {spendingAlerts.map((alert) => (
                <div 
                  key={alert.id}
                  className={`flex items-center gap-3 p-3 rounded-xl ${isLight ? 'bg-orange-50' : 'bg-orange-500/10'}`}
                  data-testid={`spending-alert-${alert.id}`}
                >
                  <div className="w-10 h-10 rounded-full bg-orange-500/20 flex items-center justify-center shrink-0">
                    <DollarSign className="w-5 h-5 text-orange-400" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={`font-medium text-sm ${textPrimary}`}>{alert.title}</p>
                    <p className={`text-xs ${textSecondary} truncate`}>{alert.body}</p>
                    <p className={`text-xs ${textSecondary} mt-1`}>
                      {new Date(alert.created_at).toLocaleDateString()} at {new Date(alert.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                    </p>
                  </div>
                  <Button 
                    size="sm" 
                    variant="ghost"
                    className="text-orange-400 hover:text-orange-500 shrink-0"
                    onClick={() => handleMarkAlertRead(alert.id)}
                  >
                    <XCircle className="w-4 h-4" />
                  </Button>
                </div>
              ))}
            </CardContent>
          </Card>
        )}

        {/* Purchase Requests (Grom Purchase Queue) */}
        <PurchaseRequestsPanel />

        {/* Family Activity Feed - Timeline of Grom activities */}
        <Card className={`${cardBg} border-2 border-emerald-500/30`} data-testid="family-activity-feed">
          <CardHeader className="pb-2">
            <div className="flex items-center justify-between">
              <CardTitle className={`${textPrimary} flex items-center gap-2 text-base`}>
                <Activity className="w-5 h-5 text-emerald-400" />
                Family Activity
                {activityFeed.length > 0 && (
                  <Badge className="ml-2 bg-emerald-500/20 text-emerald-400 border-0">
                    {activityFeed.length}
                  </Badge>
                )}
              </CardTitle>
              <Button 
                variant="ghost" 
                size="sm"
                onClick={() => setShowActivityFeed(!showActivityFeed)}
                className="text-emerald-400"
              >
                {showActivityFeed ? 'Hide' : 'Show'}
              </Button>
            </div>
          </CardHeader>
          {showActivityFeed && (
            <CardContent className="space-y-3 max-h-[400px] overflow-y-auto">
              {activityLoading ? (
                <div className="flex items-center justify-center py-8">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-500"></div>
                </div>
              ) : activityFeed.length === 0 ? (
                <div className="text-center py-8">
                  <Activity className="w-8 h-8 mx-auto mb-2 text-gray-500" />
                  <p className={`text-sm ${textSecondary}`}>No recent activity from your Groms</p>
                </div>
              ) : (
                activityFeed.map((activity, index) => (
                  <div 
                    key={`${activity.type}-${activity.id}-${index}`}
                    className={`flex items-start gap-3 p-3 rounded-xl ${
                      isLight ? 'bg-gray-50' : 'bg-zinc-800/50'
                    }`}
                  >
                    {/* Activity Icon */}
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ${
                      activity.type === 'post' ? 'bg-blue-500/20' :
                      activity.type === 'session' ? 'bg-cyan-500/20' :
                      activity.type === 'badge' ? 'bg-yellow-500/20' :
                      'bg-purple-500/20'
                    }`}>
                      <span className="text-lg">{activity.icon}</span>
                    </div>
                    
                    {/* Activity Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <Avatar className="w-5 h-5">
                          <AvatarImage src={activity.grom_avatar} />
                          <AvatarFallback className="bg-cyan-500/20 text-cyan-400 text-xs">
                            {activity.grom_name?.[0] || 'G'}
                          </AvatarFallback>
                        </Avatar>
                        <span className={`text-sm font-medium ${textPrimary}`}>
                          {activity.grom_name}
                        </span>
                        <span className={`text-xs ${textSecondary}`}>
                          {activity.created_at ? new Date(activity.created_at).toLocaleDateString() : ''}
                        </span>
                      </div>
                      
                      <p className={`text-sm font-medium ${textPrimary}`}>{activity.title}</p>
                      
                      {activity.content && (
                        <p className={`text-xs ${textSecondary} mt-0.5`}>{activity.content}</p>
                      )}
                      
                      {/* Media preview for posts/highlights */}
                      {(activity.thumbnail_url || activity.media_url) && (
                        <div className="mt-2 rounded-lg overflow-hidden max-w-[200px]">
                          {activity.media_type === 'video' ? (
                            <video src={getFullUrl(activity.media_url)} poster={getFullUrl(activity.thumbnail_url)} className="w-full h-auto" muted />
                          ) : (
                            <img src={getFullUrl(activity.thumbnail_url || activity.media_url)} alt="Activity" className="w-full h-auto" />
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                ))
              )}
              
              {activityFeed.length > 0 && (
                <Button 
                  variant="ghost" 
                  className="w-full text-emerald-400 hover:text-emerald-300"
                  onClick={fetchActivityFeed}
                >
                  Refresh
                </Button>
              )}
            </CardContent>
          )}
        </Card>

        {/* Linked Groms */}
        <Card className={`${cardBg} ${borderColor}`}>
          <CardHeader className="pb-2">
            <CardTitle className={`${textPrimary} flex items-center gap-2 text-base`}>
              <ShieldCheck className="w-5 h-5 text-cyan-400" />
              Linked Groms
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {linkedGroms.length === 0 ? (
              <div className="text-center py-8">
                <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-zinc-800 flex items-center justify-center">
                  <UserPlus className="w-8 h-8 text-gray-500" />
                </div>
                <h3 className={`font-semibold mb-1 ${textPrimary}`}>No Linked Groms</h3>
                <p className={`text-sm mb-4 ${textSecondary}`}>
                  Invite your child to link their Grom account
                </p>
                <Button className="bg-gradient-to-r from-cyan-500 to-blue-500 text-white">
                  <Plus className="w-4 h-4 mr-2" />
                  Send Invite
                </Button>
              </div>
            ) : (
              linkedGroms.map((grom) => (
                <div 
                  key={grom.id}
                  className={`flex flex-col gap-3 p-4 rounded-xl transition-all ${
                    isLight ? 'bg-gray-50' : 'bg-zinc-800'
                  }`}
                  data-testid={`grom-card-${grom.id}`}
                >
                  <div className="flex items-center gap-3">
                    <Avatar className="w-14 h-14 border-2 border-cyan-500/30">
                      <AvatarImage src={getFullUrl(grom.avatar_url)} />
                      <AvatarFallback className="bg-cyan-500/20 text-cyan-400 text-lg">
                        {grom.full_name?.[0] || 'G'}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <p className={`font-semibold ${textPrimary}`}>{grom.full_name}</p>
                        <Badge className="bg-cyan-500/20 text-cyan-400 border-0 text-xs">Grom</Badge>
                        {grom.elite_tier === 'grom_rising' && (
                          <Badge className="bg-yellow-500/20 text-yellow-400 border-0 text-xs">
                            <Trophy className="w-3 h-3 mr-1" />
                            Competes
                          </Badge>
                        )}
                      </div>
                      <div className="flex items-center gap-4 mt-1">
                        <span className={`text-xs ${textSecondary}`}>
                          <DollarSign className="w-3 h-3 inline" /> ${grom.credits_balance?.toFixed(0) || 0}
                        </span>
                        <span className={`text-xs ${textSecondary}`}>
                          <Trophy className="w-3 h-3 inline" /> {grom.achievements_count || 0} badges
                        </span>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Button 
                        size="sm" 
                        variant="ghost"
                        className="text-gray-400 hover:text-red-400"
                        onClick={(e) => {
                          e.stopPropagation();
                          openUnlinkModal(grom);
                        }}
                      >
                        <Unlink className="w-4 h-4" />
                      </Button>
                      <ChevronRight 
                        className={`w-5 h-5 ${textSecondary} cursor-pointer`}
                        onClick={() => navigate(`/grom-hq/manage/${grom.id}`)}
                      />
                    </div>
                  </div>
                  
                  {/* Competition Status Toggle */}
                  <div className={`flex items-center justify-between p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-700/50'}`}>
                    <div className="flex items-center gap-2">
                      <Trophy className="w-4 h-4 text-yellow-400" />
                      <span className={`text-sm ${textPrimary}`}>Competition Mode</span>
                    </div>
                    <button
                      onClick={async (e) => {
                        e.stopPropagation();
                        const newStatus = grom.elite_tier !== 'grom_rising';
                        try {
                          await apiClient.post(`/grom-hq/toggle-competition/${grom.id}?parent_id=${user.id}`, {
                            competes: newStatus
                          });
                          // Update local state
                          setLinkedGroms(prev => prev.map(g => 
                            g.id === grom.id 
                              ? { ...g, elite_tier: newStatus ? 'grom_rising' : null }
                              : g
                          ));
                          toast.success(newStatus 
                            ? `${grom.full_name} is now a competitive Grom!` 
                            : `${grom.full_name} competition mode disabled`
                          );
                        } catch (err) {
                          toast.error('Failed to update competition status');
                        }
                      }}
                      className={`w-11 h-6 rounded-full transition-colors ${
                        grom.elite_tier === 'grom_rising' ? 'bg-yellow-500' : 'bg-zinc-600'
                      }`}
                      data-testid={`grom-competition-toggle-${grom.id}`}
                    >
                      <div
                        className={`w-5 h-5 bg-white rounded-full shadow transform transition-transform ${
                          grom.elite_tier === 'grom_rising' ? 'translate-x-5' : 'translate-x-0.5'
                        }`}
                      />
                    </button>
                  </div>
                </div>
              ))
            )}
          </CardContent>
        </Card>

        {/* Quick Actions */}
        <Card className={`${cardBg} ${borderColor}`}>
          <CardHeader className="pb-2">
            <CardTitle className={`${textPrimary} flex items-center gap-2 text-base`}>
              <Settings className="w-5 h-5 text-gray-400" />
              Quick Actions
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <Button 
              variant="outline" 
              className={`w-full justify-start h-auto py-4 ${borderColor}`}
              onClick={() => toast.info('Have your Grom sign up with a Grom account, then use the link request from the "Linked Groms" section above.')}
            >
              <div className="w-10 h-10 rounded-full bg-cyan-500/20 flex items-center justify-center mr-3">
                <UserPlus className="w-5 h-5 text-cyan-400" />
              </div>
              <div className="text-left flex-1">
                <div className={`font-semibold ${textPrimary}`}>Invite a Grom</div>
                <div className={`text-xs ${textSecondary}`}>Send a link request to your child</div>
              </div>
              <ArrowRight className="w-5 h-5 text-cyan-400" />
            </Button>
            
            <Button 
              variant="outline" 
              className={`w-full justify-start h-auto py-4 ${borderColor}`}
              onClick={() => { if (linkedGroms.length > 0) { navigate(`/grom-hq/manage/${linkedGroms[0].id}`); } else { toast.info('Link a Grom first to manage spending controls.'); } }}
            >
              <div className="w-10 h-10 rounded-full bg-emerald-500/20 flex items-center justify-center mr-3">
                <CreditCard className="w-5 h-5 text-emerald-400" />
              </div>
              <div className="text-left flex-1">
                <div className={`font-semibold ${textPrimary}`}>Spending Controls</div>
                <div className={`text-xs ${textSecondary}`}>Set limits and approve purchases</div>
              </div>
              <ArrowRight className="w-5 h-5 text-emerald-400" />
            </Button>
            
            <Button 
              variant="outline" 
              className={`w-full justify-start h-auto py-4 ${borderColor}`}
              onClick={() => { setShowActivityFeed(true); toast.success('Scroll up to see the Family Activity feed'); }}
            >
              <div className="w-10 h-10 rounded-full bg-yellow-500/20 flex items-center justify-center mr-3">
                <Activity className="w-5 h-5 text-yellow-400" />
              </div>
              <div className="text-left flex-1">
                <div className={`font-semibold ${textPrimary}`}>Activity Monitor</div>
                <div className={`text-xs ${textSecondary}`}>View screen time and session history</div>
              </div>
              <ArrowRight className="w-5 h-5 text-yellow-400" />
            </Button>
            
            <Button 
              variant="outline" 
              className={`w-full justify-start h-auto py-4 ${borderColor}`}
              onClick={() => navigate('/settings')}
            >
              <div className="w-10 h-10 rounded-full bg-red-500/20 flex items-center justify-center mr-3">
                <ShieldAlert className="w-5 h-5 text-red-400" />
              </div>
              <div className="text-left flex-1">
                <div className={`font-semibold ${textPrimary}`}>Safety Settings</div>
                <div className={`text-xs ${textSecondary}`}>Manage privacy and content filters</div>
              </div>
              <ArrowRight className="w-5 h-5 text-red-400" />
            </Button>
            
            <Button 
              variant="outline" 
              className={`w-full justify-start h-auto py-4 ${borderColor}`}
              onClick={() => navigate('/gear-hub')}
            >
              <div className="w-10 h-10 rounded-full bg-purple-500/20 flex items-center justify-center mr-3">
                <ShoppingBag className="w-5 h-5 text-purple-400" />
              </div>
              <div className="text-left flex-1">
                <div className={`font-semibold ${textPrimary}`}>Gear Hub</div>
                <div className={`text-xs ${textSecondary}`}>Buy gear for your Grom</div>
              </div>
              <ArrowRight className="w-5 h-5 text-purple-400" />
            </Button>
          </CardContent>
        </Card>

        {/* Parent Age Verification Status */}
        <Card className={`${cardBg} border-2 ${ageVerified ? 'border-emerald-500/30' : 'border-yellow-500/30'}`}>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className={`w-12 h-12 rounded-full ${ageVerified ? 'bg-emerald-500/20' : 'bg-yellow-500/20'} flex items-center justify-center`}>
                {ageVerified ? (
                  <ShieldCheck className="w-6 h-6 text-emerald-400" />
                ) : (
                  <ShieldAlert className="w-6 h-6 text-yellow-400" />
                )}
              </div>
              <div className="flex-1">
                <p className={`font-semibold ${textPrimary}`}>
                  {ageVerified ? 'Guardian Verified' : 'Age Verification Required'}
                </p>
                <p className={`text-xs ${textSecondary}`}>
                  {ageVerified 
                    ? 'Your identity is verified to manage Grom accounts'
                    : 'Verify your age to link Grom accounts'}
                </p>
              </div>
              {ageVerified ? (
                <Badge className="bg-emerald-500/20 text-emerald-400 border-0">
                  <ShieldCheck className="w-3 h-3 mr-1" />
                  GUARDIAN
                </Badge>
              ) : (
                <Button 
                  size="sm"
                  className="bg-yellow-500 hover:bg-yellow-600 text-black"
                  onClick={startAgeVerification}
                  disabled={verifyingAge}
                >
                  {verifyingAge ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <>Verify Now</>
                  )}
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Unlink Confirmation Modal */}
      <Dialog open={unlinkModalOpen} onOpenChange={setUnlinkModalOpen}>
        <DialogContent className="bg-zinc-900 border-zinc-800">
          <DialogHeader>
            <DialogTitle className="text-white flex items-center gap-2">
              <UserX className="w-5 h-5 text-red-400" />
              Unlink {unlinkingGrom?.full_name}?
            </DialogTitle>
            <DialogDescription className="text-gray-400">
              This will remove the link between your account and this Grom. 
              They will be locked out of the app until re-linked to a parent.
            </DialogDescription>
          </DialogHeader>
          
          <div className="space-y-4 py-4">
            <div className="flex items-center gap-3 p-3 bg-zinc-800 rounded-lg">
              <Avatar className="w-10 h-10">
                <AvatarImage src={getFullUrl(unlinkingGrom?.avatar_url)} />
                <AvatarFallback className="bg-cyan-500/20 text-cyan-400">
                  {unlinkingGrom?.full_name?.[0]}
                </AvatarFallback>
              </Avatar>
              <div>
                <p className="text-white font-medium">{unlinkingGrom?.full_name}</p>
                <p className="text-xs text-gray-500">Grom Account</p>
              </div>
            </div>
            
            <div>
              <label className="text-sm text-gray-400 mb-2 block">
                <KeyRound className="w-4 h-4 inline mr-1" />
                Enter your password to confirm
              </label>
              <Input
                type="password"
                placeholder="Your password"
                value={unlinkPassword}
                onChange={(e) => setUnlinkPassword(e.target.value)}
                className="bg-zinc-800 border-zinc-700 text-white"
              />
            </div>
          </div>
          
          <DialogFooter>
            <Button 
              variant="outline" 
              onClick={() => setUnlinkModalOpen(false)}
              className="border-zinc-700 text-gray-400"
            >
              Cancel
            </Button>
            <Button 
              onClick={handleUnlinkGrom}
              disabled={!unlinkPassword || unlinkLoading}
              className="bg-red-500 hover:bg-red-600 text-white"
            >
              {unlinkLoading ? (
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
              ) : (
                <Unlink className="w-4 h-4 mr-2" />
              )}
              Unlink
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default GromHQ;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  Shield, Lock, Copy, CheckCircle, Loader2, Heart, MessageCircle,
  ShieldAlert, Clock, Users, Camera
} from 'lucide-react';
import { Button } from './ui/button';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { toast } from 'sonner';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';


/**
 * GromLimitedFeed - Shows a limited preview feed for unlinked Groms
 * Displays up to 3 posts from other Groms only, with a CTA to complete parent linking
 */
const GromLimitedFeed = ({ gromStatus, _onCopyCode }) => {
  const { _user } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';
  
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [codeCopied, setCodeCopied] = useState(false);

  const cardBg = isLight ? 'bg-white' : 'bg-zinc-900';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  const borderColor = isLight ? 'border-gray-200' : 'border-zinc-800';

  useEffect(() => {
    fetchGromPosts();
  }, []);

  const fetchGromPosts = async () => {
    try {
      // Fetch posts from other Groms only, limited to 3
      const response = await apiClient.get(`/posts/grom-preview?limit=3`);
      setPosts(response.data || []);
    } catch (error) {
      logger.error('Failed to fetch grom posts:', error);
      setPosts([]);
    } finally {
      setLoading(false);
    }
  };

  const copyGuardianCode = () => {
    if (gromStatus?.guardian_code) {
      navigator.clipboard.writeText(gromStatus.guardian_code);
      setCodeCopied(true);
      toast.success('Guardian code copied!');
      setTimeout(() => setCodeCopied(false), 3000);
    }
  };

  return (
    <div className={`min-h-screen ${isLight ? 'bg-gray-50' : 'bg-black'} pb-24`}>
      {/* Safety Banner */}
      <div className="sticky top-0 z-40 bg-gradient-to-r from-cyan-600 to-blue-600 px-4 py-3">
        <div className="flex items-center gap-3 max-w-lg mx-auto">
          <div className="w-10 h-10 rounded-full bg-white/20 flex items-center justify-center shrink-0">
            <Shield className="w-5 h-5 text-white" />
          </div>
          <div className="flex-1">
            <p className="text-white font-semibold text-sm">Parent Link Required</p>
            <p className="text-cyan-100 text-xs">Complete setup to unlock all features</p>
          </div>
          <Badge className="bg-white/20 text-white border-0 text-xs">
            LIMITED
          </Badge>
        </div>
      </div>

      {/* Guardian Code Card */}
      <div className="px-4 py-4">
        <Card className={`${cardBg} ${borderColor} border`}>
          <CardContent className="p-4">
            <div className="flex items-center gap-3 mb-3">
              <Clock className="w-5 h-5 text-yellow-500" />
              <div>
                <p className={`font-semibold text-sm ${textPrimary}`}>
                  {gromStatus?.is_linked ? "Pending Parent Approval" : "Share Your Code"}
                </p>
                <p className={`text-xs ${textSecondary}`}>
                  {gromStatus?.is_linked 
                    ? "Waiting for your parent to approve" 
                    : "Give this code to your parent"}
                </p>
              </div>
            </div>
            
            {gromStatus?.guardian_code && (
              <div className={`${isLight ? 'bg-gray-100' : 'bg-zinc-800'} rounded-xl p-3 flex items-center justify-between`}>
                <div className="text-2xl font-mono font-bold text-cyan-500 tracking-wider">
                  {gromStatus.guardian_code}
                </div>
                <Button 
                  size="sm" 
                  variant="outline"
                  className="border-cyan-500/50 text-cyan-500"
                  onClick={copyGuardianCode}
                >
                  {codeCopied ? <CheckCircle className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                </Button>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Limited Feed Header */}
      <div className="px-4 pb-2">
        <div className="flex items-center gap-2">
          <Users className="w-4 h-4 text-cyan-500" />
          <h2 className={`font-semibold ${textPrimary}`}>Grom Community Preview</h2>
          <Badge className="bg-cyan-500/20 text-cyan-500 border-0 text-xs ml-auto">
            3 POSTS
          </Badge>
        </div>
        <p className={`text-xs ${textSecondary} mt-1`}>
          Connect with your parent to see the full feed and post your own sessions
        </p>
      </div>

      {/* Limited Posts */}
      <div className="px-4 space-y-4">
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-8 h-8 text-cyan-500 animate-spin" />
          </div>
        ) : posts.length > 0 ? (
          <>
            {posts.map((post) => (
              <Card key={post.id} className={`${cardBg} ${borderColor} border overflow-hidden`}>
                <CardContent className="p-0">
                  {/* Post Header */}
                  <div className="flex items-center gap-3 p-3">
                    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-cyan-500 to-blue-500 flex items-center justify-center">
                      {post.author_avatar ? (
                        <img src={getFullUrl(post.author_avatar)} alt="" className="w-10 h-10 rounded-full object-cover" />
                      ) : (
                        <span className="text-white font-bold text-sm">
                          {post.author_name?.charAt(0) || 'G'}
                        </span>
                      )}
                    </div>
                    <div className="flex-1">
                      <p className={`font-semibold text-sm ${textPrimary}`}>{post.author_name || 'Grom'}</p>
                      <p className={`text-xs ${textSecondary}`}>
                        {post.spot_name || 'Surfing'}
                      </p>
                    </div>
                    <Badge className="bg-cyan-500/20 text-cyan-500 border-0 text-xs">
                      GROM
                    </Badge>
                  </div>
                  
                  {/* Post Media */}
                  {(post.thumbnail_url || post.media_url) && (
                    <div className="relative aspect-square bg-zinc-800">
                      <img 
                        src={getFullUrl(post.thumbnail_url || post.media_url)} 
                        alt="" 
                        className="w-full h-full object-cover"
                      />
                    </div>
                  )}
                  
                  {/* Post Actions (Disabled) */}
                  <div className="p-3 flex items-center gap-4">
                    <div className="flex items-center gap-1.5 opacity-50">
                      <Heart className="w-5 h-5" />
                      <span className={`text-sm ${textSecondary}`}>{post.likes_count || 0}</span>
                    </div>
                    <div className="flex items-center gap-1.5 opacity-50">
                      <MessageCircle className="w-5 h-5" />
                      <span className={`text-sm ${textSecondary}`}>{post.comments_count || 0}</span>
                    </div>
                  </div>
                  
                  {/* Caption */}
                  {post.caption && (
                    <div className="px-3 pb-3">
                      <p className={`text-sm ${textPrimary}`}>
                        <span className="font-semibold">{post.author_name}</span>{' '}
                        {post.caption.length > 100 ? `${post.caption.slice(0, 100)}...` : post.caption}
                      </p>
                    </div>
                  )}
                </CardContent>
              </Card>
            ))}
            
            {/* Unlock More CTA */}
            <Card className={`${cardBg} border-2 border-dashed ${isLight ? 'border-cyan-300' : 'border-cyan-500/50'}`}>
              <CardContent className="p-6 text-center">
                <Lock className="w-12 h-12 text-cyan-500 mx-auto mb-3 opacity-60" />
                <p className={`font-semibold ${textPrimary} mb-1`}>Want to see more?</p>
                <p className={`text-sm ${textSecondary} mb-4`}>
                  Complete parent linking to unlock the full feed, post your own sessions, and connect with the community
                </p>
                <div className={`${isLight ? 'bg-gray-100' : 'bg-zinc-800'} rounded-lg p-3`}>
                  <p className={`text-xs ${textSecondary} mb-2`}>Your Guardian Code:</p>
                  <p className="text-xl font-mono font-bold text-cyan-500">{gromStatus?.guardian_code}</p>
                </div>
              </CardContent>
            </Card>
          </>
        ) : (
          <Card className={`${cardBg} ${borderColor} border`}>
            <CardContent className="p-8 text-center">
              <Camera className="w-12 h-12 text-cyan-500 mx-auto mb-3 opacity-60" />
              <p className={`font-semibold ${textPrimary} mb-1`}>No Grom Posts Yet</p>
              <p className={`text-sm ${textSecondary}`}>
                Be the first! Complete parent linking and share your surf sessions
              </p>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Locked Features Reminder */}
      <div className="px-4 py-6">
        <Card className={`${isLight ? 'bg-red-50' : 'bg-red-500/10'} border ${isLight ? 'border-red-200' : 'border-red-500/30'}`}>
          <CardContent className="p-4">
            <p className={`text-sm font-medium ${isLight ? 'text-red-800' : 'text-red-400'} mb-3 flex items-center gap-2`}>
              <ShieldAlert className="w-4 h-4" />
              Features locked until parent approval:
            </p>
            <div className="grid grid-cols-2 gap-2">
              {['Full Feed', 'Go Live', 'Messages', 'Post Content'].map((feature) => (
                <div 
                  key={feature}
                  className={`flex items-center gap-2 p-2 ${isLight ? 'bg-red-100' : 'bg-red-500/20'} rounded-lg`}
                >
                  <Lock className={`w-4 h-4 ${isLight ? 'text-red-600' : 'text-red-400'}`} />
                  <span className={`text-xs ${isLight ? 'text-red-700' : 'text-red-300'}`}>{feature}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default GromLimitedFeed;

﻿import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  ArrowLeft, Activity, CreditCard, Shield, Clock, DollarSign, 
  ShoppingBag, Camera, MessageSquare, Edit3, Radio, Loader2,
  TrendingUp, TrendingDown, AlertCircle, Save, Users
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Avatar, AvatarFallback } from './ui/avatar';
import { Input } from './ui/input';
import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';


/**
 * GromManage - Activity monitoring and spending controls for a specific Grom
 */
export const GromManage = () => {
  const { gromId } = useParams();
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('activity'); // 'activity', 'spending', 'controls'
  const [activityData, setActivityData] = useState(null);
  const [spendingData, setSpendingData] = useState(null);
  const [controls, setControls] = useState({
    can_post: false,
    can_stream: false,
    can_message: false,
    can_message_grom_channel: true,
    can_comment: true,
    view_only: false
  });
  const [spendingLimit, setSpendingLimit] = useState('');
  const [approvalThreshold, setApprovalThreshold] = useState('');
  const [saving, setSaving] = useState(false);

  const isLight = theme === 'light';
  const cardBg = isLight ? 'bg-white' : 'bg-zinc-900';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  const borderColor = isLight ? 'border-gray-200' : 'border-zinc-800';

  useEffect(() => {
    if (gromId && user?.id) {
      fetchData();
    }
  }, [gromId, user?.id]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [activityRes, spendingRes] = await Promise.all([
        apiClient.get(`/grom-hq/activity/${gromId}?parent_id=${user.id}`),
        apiClient.get(`/grom-hq/spending-summary/${gromId}?parent_id=${user.id}`)
      ]);
      
      setActivityData(activityRes.data);
      setSpendingData(spendingRes.data);
      
      // Set controls from response
      if (activityRes.data.parental_controls) {
        setControls(activityRes.data.parental_controls);
        if (activityRes.data.parental_controls.spending_limit) {
          setSpendingLimit(activityRes.data.parental_controls.spending_limit.toString());
        }
        if (activityRes.data.parental_controls.require_approval_above) {
          setApprovalThreshold(activityRes.data.parental_controls.require_approval_above.toString());
        }
      }
    } catch (error) {
      logger.error('Failed to fetch Grom data:', error);
      toast.error('Failed to load Grom data');
    } finally {
      setLoading(false);
    }
  };

  const saveControls = async () => {
    setSaving(true);
    try {
      await apiClient.post(
        `/grom-hq/update-parental-controls/${gromId}?parent_id=${user.id}`,
        controls
      );
      toast.success('Controls updated');
    } catch (error) {
      toast.error('Failed to update controls');
    } finally {
      setSaving(false);
    }
  };

  const saveSpendingControls = async () => {
    setSaving(true);
    try {
      await apiClient.post(
        `/grom-hq/spending-controls/${gromId}?parent_id=${user.id}`,
        {
          monthly_limit: spendingLimit ? parseFloat(spendingLimit) : null,
          require_approval_above: approvalThreshold ? parseFloat(approvalThreshold) : null
        }
      );
      toast.success('Spending controls updated');
    } catch (error) {
      toast.error('Failed to update spending controls');
    } finally {
      setSaving(false);
    }
  };

  const toggleControl = (key) => {
    setControls(prev => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
      </div>
    );
  }

  const gromName = activityData?.grom_name || 'Grom';

  return (
    <div className={`min-h-screen ${isLight ? 'bg-gray-50' : 'bg-black'} pb-24 md:pb-8`}>
      {/* Header */}
      <div className="bg-gradient-to-r from-cyan-500 to-blue-600 px-4 py-4">
        <div className="max-w-4xl mx-auto">
          <button 
            onClick={() => navigate('/grom-hq')}
            className="flex items-center gap-2 text-white/80 hover:text-white mb-3"
          >
            <ArrowLeft className="w-5 h-5" />
            Back to Grom HQ
          </button>
          <div className="flex items-center gap-3">
            <Avatar className="w-12 h-12 border-2 border-white/30">
              <AvatarFallback className="bg-white/20 text-white">
                {gromName[0]}
              </AvatarFallback>
            </Avatar>
            <div>
              <h1 className="text-xl font-bold text-white">{gromName}</h1>
              <p className="text-cyan-100 text-sm">Manage Activity & Controls</p>
            </div>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="max-w-4xl mx-auto px-4 py-4">
        <div className="flex gap-2 overflow-x-auto pb-2">
          {[
            { id: 'activity', icon: Activity, label: 'Activity' },
            { id: 'spending', icon: CreditCard, label: 'Spending' },
            { id: 'controls', icon: Shield, label: 'Controls' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all ${
                activeTab === tab.id
                  ? 'bg-gradient-to-r from-cyan-500 to-blue-500 text-white'
                  : `${isLight ? 'bg-gray-200 text-gray-700' : 'bg-zinc-800 text-gray-400'}`
              }`}
            >
              <tab.icon className="w-4 h-4" />
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 space-y-4">
        {/* Activity Tab */}
        {activeTab === 'activity' && activityData && (
          <>
            {/* Stats Grid */}
            <div className="grid grid-cols-2 gap-3">
              <Card className={`${cardBg} ${borderColor}`}>
                <CardContent className="p-4 text-center">
                  <Edit3 className="w-6 h-6 text-blue-400 mx-auto mb-2" />
                  <div className={`text-2xl font-bold ${textPrimary}`}>
                    {activityData.activity.total_posts}
                  </div>
                  <div className={`text-xs ${textSecondary}`}>Total Posts</div>
                </CardContent>
              </Card>
              
              <Card className={`${cardBg} ${borderColor}`}>
                <CardContent className="p-4 text-center">
                  <TrendingUp className="w-6 h-6 text-green-400 mx-auto mb-2" />
                  <div className={`text-2xl font-bold ${textPrimary}`}>
                    {activityData.activity.posts_this_week}
                  </div>
                  <div className={`text-xs ${textSecondary}`}>Posts This Week</div>
                </CardContent>
              </Card>
              
              <Card className={`${cardBg} ${borderColor}`}>
                <CardContent className="p-4 text-center">
                  <Camera className="w-6 h-6 text-yellow-400 mx-auto mb-2" />
                  <div className={`text-2xl font-bold ${textPrimary}`}>
                    {activityData.activity.sessions_joined}
                  </div>
                  <div className={`text-xs ${textSecondary}`}>Sessions Joined</div>
                </CardContent>
              </Card>
              
              <Card className={`${cardBg} ${borderColor}`}>
                <CardContent className="p-4 text-center">
                  <DollarSign className="w-6 h-6 text-emerald-400 mx-auto mb-2" />
                  <div className={`text-2xl font-bold ${textPrimary}`}>
                    ${activityData.activity.credits_balance.toFixed(0)}
                  </div>
                  <div className={`text-xs ${textSecondary}`}>Credits Balance</div>
                </CardContent>
              </Card>
            </div>

            {/* Recent Transactions */}
            <Card className={`${cardBg} ${borderColor}`}>
              <CardHeader className="pb-2">
                <CardTitle className={`${textPrimary} text-base flex items-center gap-2`}>
                  <Clock className="w-5 h-5 text-gray-400" />
                  Recent Activity
                </CardTitle>
              </CardHeader>
              <CardContent>
                {activityData.recent_transactions.length === 0 ? (
                  <div className="text-center py-6">
                    <Activity className="w-8 h-8 text-gray-500 mx-auto mb-2" />
                    <p className={`text-sm ${textSecondary}`}>No recent activity</p>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {activityData.recent_transactions.map((t) => (
                      <div 
                        key={t.id}
                        className={`flex items-center gap-3 p-3 rounded-lg ${isLight ? 'bg-gray-50' : 'bg-zinc-800'}`}
                      >
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                          t.amount < 0 ? 'bg-red-500/20' : 'bg-green-500/20'
                        }`}>
                          {t.amount < 0 ? (
                            <TrendingDown className="w-4 h-4 text-red-400" />
                          ) : (
                            <TrendingUp className="w-4 h-4 text-green-400" />
                          )}
                        </div>
                        <div className="flex-1">
                          <p className={`text-sm ${textPrimary}`}>{t.description || t.type}</p>
                          <p className={`text-xs ${textSecondary}`}>
                            {new Date(t.created_at).toLocaleDateString()}
                          </p>
                        </div>
                        <span className={`font-bold ${t.amount < 0 ? 'text-red-400' : 'text-green-400'}`}>
                          {t.amount < 0 ? '-' : '+'}${Math.abs(t.amount).toFixed(0)}
                        </span>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </>
        )}

        {/* Spending Tab */}
        {activeTab === 'spending' && spendingData && (
          <>
            {/* Spending Overview */}
            <Card className={`${cardBg} border-2 border-emerald-500/30`}>
              <CardContent className="p-6 text-center">
                <div className={`text-4xl font-bold ${textPrimary}`}>
                  ${spendingData.monthly_spending.toFixed(0)}
                </div>
                <p className={`${textSecondary} text-sm mt-1`}>Spent This Month</p>
                {spendingData.spending_limit && (
                  <div className="mt-3">
                    <div className="flex justify-between text-xs mb-1">
                      <span className={textSecondary}>Limit: ${spendingData.spending_limit}</span>
                      <span className={spendingData.monthly_spending > spendingData.spending_limit ? 'text-red-400' : 'text-green-400'}>
                        {Math.round((spendingData.monthly_spending / spendingData.spending_limit) * 100)}%
                      </span>
                    </div>
                    <div className="w-full bg-zinc-700 rounded-full h-2">
                      <div 
                        className={`h-2 rounded-full ${spendingData.monthly_spending > spendingData.spending_limit ? 'bg-red-500' : 'bg-emerald-500'}`}
