      const response = await apiClient.post(
        `/auth/convert-to-hobbyist`,
        {
          tier_id: plan.tier_id,
          origin_url: window.location.origin
        }
      );

      if (response.data.checkout_url) {
        // Paid tier - redirect to Stripe
        window.location.href = response.data.checkout_url;
      } else {
        // Free tier - update user and redirect
        updateUser({
          ...user,
          role: 'Hobbyist',
          subscription_tier: 'free',
          is_ad_supported: true
        });
        
        toast.success('Welcome to the Hobbyist community!');
        
        if (onComplete) {
          onComplete();
        } else {
          navigate('/feed');
        }
      }
    } catch (error) {
      logger.error('Hobbyist conversion error:', error);
      toast.error(error.response?.data?.detail || 'Failed to process. Please try again.');
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-black p-4 py-8">
      <div className="max-w-2xl mx-auto">
        {/* Back Button */}
        {onBack && (
          <button
            onClick={onBack}
            className="flex items-center gap-2 text-gray-400 hover:text-white mb-6 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to Photographer Plans
          </button>
        )}

        {/* Header */}
        <div className="text-center mb-8">
          <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-gradient-to-br from-orange-400 to-pink-500 flex items-center justify-center">
            <Heart className="w-10 h-10 text-white" />
          </div>
          <h1 className="text-3xl font-bold text-white mb-3" style={{ fontFamily: 'Oswald' }}>
            Join as a Hobbyist
          </h1>
          <p className="text-gray-400 text-lg max-w-xl mx-auto">
            Share your surf photography for free and support the community. 
            Your earnings go to Gear Credits that help young surfers.
          </p>
        </div>

        {/* Info Banner */}
        <div className="bg-gradient-to-r from-orange-500/20 to-pink-500/20 border border-orange-400/30 rounded-xl p-4 mb-8">
          <div className="flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-orange-400 flex-shrink-0 mt-0.5" />
            <div>
              <h3 className="text-white font-medium mb-1">What's a Hobbyist?</h3>
              <p className="text-gray-300 text-sm">
                Hobbyists are passionate photographers who contribute to the surf community 
                without commercial goals. Your photo earnings become <span className="text-orange-400 font-medium">Gear Credits</span> that 
                can be used to buy surf gear or donated to support young surfers (Groms).
              </p>
            </div>
          </div>
        </div>

        {/* Comparison: Hobbyist vs Photographer */}
        <div className="grid md:grid-cols-2 gap-4 mb-8">
          <div className="bg-zinc-900 rounded-xl p-4 border border-zinc-800">
            <div className="flex items-center gap-2 mb-3">
              <Heart className="w-5 h-5 text-orange-400" />
              <h3 className="text-white font-medium">Hobbyist</h3>
              <span className="ml-auto text-emerald-400 text-sm font-bold">FREE</span>
            </div>
            <ul className="space-y-2 text-sm">
              <li className="flex items-center gap-2 text-gray-300">
                <Check className="w-4 h-4 text-emerald-400" />
                Upload & share photos
              </li>
              <li className="flex items-center gap-2 text-gray-300">
                <Check className="w-4 h-4 text-emerald-400" />
                Earn Gear Credits
              </li>
              <li className="flex items-center gap-2 text-gray-300">
                <Check className="w-4 h-4 text-emerald-400" />
                Support Groms & Causes
              </li>
              <li className="flex items-center gap-2 text-gray-400">
                <X className="w-4 h-4 text-zinc-600" />
                Bank withdrawals
              </li>
              <li className="flex items-center gap-2 text-gray-400">
                <X className="w-4 h-4 text-zinc-600" />
                Priority placement
              </li>
            </ul>
          </div>
          
          <div className="bg-zinc-900 rounded-xl p-4 border border-zinc-800">
            <div className="flex items-center gap-2 mb-3">
              <Camera className="w-5 h-5 text-purple-400" />
              <h3 className="text-white font-medium">Photographer</h3>
              <span className="ml-auto text-yellow-400 text-sm font-bold">$18+/mo</span>
            </div>
            <ul className="space-y-2 text-sm">
              <li className="flex items-center gap-2 text-gray-300">
                <Check className="w-4 h-4 text-emerald-400" />
                Everything in Hobbyist
              </li>
              <li className="flex items-center gap-2 text-gray-300">
                <Check className="w-4 h-4 text-emerald-400" />
                Withdrawable earnings
              </li>
              <li className="flex items-center gap-2 text-gray-300">
                <Check className="w-4 h-4 text-emerald-400" />
                Priority in search results
              </li>
              <li className="flex items-center gap-2 text-gray-300">
                <Check className="w-4 h-4 text-emerald-400" />
                AI tagging credits
              </li>
              <li className="flex items-center gap-2 text-gray-300">
                <Check className="w-4 h-4 text-emerald-400" />
                Lower platform fee
              </li>
            </ul>
          </div>
        </div>

        {/* Hobbyist Plans */}
        <h2 className="text-xl font-bold text-white mb-4" style={{ fontFamily: 'Oswald' }}>
          Choose Your Hobbyist Plan
        </h2>
        
        <div className="grid md:grid-cols-2 gap-4 mb-8">
          {hobbyistPlans.map((plan) => {
            const Icon = plan.icon;
            return (
              <Card
                key={plan.id}
                className={`relative overflow-hidden transition-all hover:scale-[1.02] cursor-pointer ${
                  plan.popular
                    ? 'border-2 border-orange-400 bg-gradient-to-b from-orange-400/10 to-zinc-900'
                    : 'border-zinc-700 bg-zinc-900'
                }`}
                onClick={() => !loading && handleSelectPlan(plan)}
                data-testid={`hobbyist-plan-${plan.id}`}
              >
                {plan.badge && (
                  <div className="absolute top-0 right-0 bg-gradient-to-r from-orange-400 to-pink-400 text-black text-xs font-bold px-3 py-1 rounded-bl-lg">
                    {plan.badge}
                  </div>
                )}
                <CardContent className="p-5">
                  <div className="flex items-center gap-3 mb-4">
                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${plan.bgColor}`}>
                      <Icon className={`w-5 h-5 ${plan.iconColor}`} />
                    </div>
                    <div>
                      <h3 className="text-lg font-bold text-white">{plan.name}</h3>
                      <p className="text-gray-400 text-sm">{plan.description}</p>
                    </div>
                  </div>
                  
                  <div className="flex items-baseline gap-1 mb-4">
                    <span className="text-3xl font-bold text-white">${plan.price}</span>
                    <span className="text-gray-400">/{plan.period}</span>
                  </div>

                  <ul className="space-y-2 mb-4">
                    {plan.features.slice(0, 4).map((feature, idx) => (
                      <li key={idx} className="flex items-start gap-2">
                        {feature.included ? (
                          <Check className={`w-4 h-4 flex-shrink-0 mt-0.5 ${
                            feature.highlight ? 'text-orange-400' : 
                            feature.negative ? 'text-yellow-500' : 'text-emerald-400'
                          }`} />
                        ) : (
                          <X className="w-4 h-4 flex-shrink-0 mt-0.5 text-zinc-600" />
                        )}
                        <span className={`text-sm ${
                          feature.included 
                            ? feature.highlight ? 'text-orange-400' :
                              feature.negative ? 'text-yellow-500' : 'text-gray-300'
                            : 'text-zinc-600'
                        }`}>
                          {feature.text}
                        </span>
                      </li>
                    ))}
                  </ul>

                  <Button
                    disabled={loading && selectedPlan === plan.id}
                    className={`w-full ${
                      plan.popular
                        ? 'bg-gradient-to-r from-orange-400 to-pink-400 hover:from-orange-500 hover:to-pink-500 text-black'
                        : 'bg-zinc-800 hover:bg-zinc-700 text-white'
                    }`}
                  >
                    {loading && selectedPlan === plan.id ? (
                      <Loader2 className="w-5 h-5 animate-spin" />
                    ) : (
                      plan.cta
                    )}
                  </Button>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {/* Benefits */}
        <div className="grid grid-cols-3 gap-4 mb-8">
          <div className="text-center p-4 bg-zinc-900 rounded-xl">
            <Gift className="w-8 h-8 text-orange-400 mx-auto mb-2" />
            <h4 className="text-white font-medium text-sm">Gear Credits</h4>
            <p className="text-gray-400 text-xs">Earn credits for surf gear</p>
          </div>
          <div className="text-center p-4 bg-zinc-900 rounded-xl">
            <Users className="w-8 h-8 text-pink-400 mx-auto mb-2" />
            <h4 className="text-white font-medium text-sm">Support Groms</h4>
            <p className="text-gray-400 text-xs">Help young surfers grow</p>
          </div>
          <div className="text-center p-4 bg-zinc-900 rounded-xl">
            <Sparkles className="w-8 h-8 text-yellow-400 mx-auto mb-2" />
            <h4 className="text-white font-medium text-sm">Community</h4>
            <p className="text-gray-400 text-xs">Join passionate creators</p>
          </div>
        </div>

        {/* Back to Pro Option */}
        <div className="text-center">
          <p className="text-gray-400 text-sm mb-3">
            Want to earn real money from your photos?
          </p>
          <Button
            variant="outline"
            onClick={onBack}
            className="border-purple-500/50 text-purple-400 hover:bg-purple-500/10"
          >
            <Camera className="w-4 h-4 mr-2" />
            View Photographer Plans ($18+/mo)
          </Button>
        </div>
      </div>
    </div>
  );
};

export default HobbyistFunnel;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Avatar, AvatarImage, AvatarFallback } from './ui/avatar';
import { Badge } from './ui/badge';
import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import {

  Heart, Target, Search, Users, DollarSign, TrendingUp, Loader2, ExternalLink, Check, Waves, Star, Gift, Settings
} from 'lucide-react';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';
import { ROLES } from '../constants/roles';



const IMPACT_LEVELS = {
  Legend: { emoji: '🏆', color: 'from-yellow-400 to-amber-600' },
  Champion: { emoji: '🥇', color: 'from-amber-400 to-orange-500' },
  Hero: { emoji: '🦸', color: 'from-purple-400 to-indigo-500' },
  Patron: { emoji: '🌟', color: 'from-blue-400 to-cyan-500' },
  Supporter: { emoji: '💪', color: 'from-green-400 to-emerald-500' },
  Contributor: { emoji: '🤝', color: 'from-teal-400 to-cyan-500' },
  Starter: { emoji: '🌱', color: 'from-gray-400 to-zinc-500' }
};

const CAUSE_CATEGORIES = {
  ocean_conservation: { label: 'Ocean Conservation', color: 'bg-blue-500/20 text-blue-400' },
  environmental: { label: 'Environmental', color: 'bg-green-500/20 text-green-400' },
  youth_surfing: { label: 'Youth Surfing', color: 'bg-amber-500/20 text-amber-400' },
  community: { label: 'Community', color: 'bg-purple-500/20 text-purple-400' }
};

export const ImpactDashboard = () => {
  const { user } = useAuth();
  const [dashboard, setDashboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  
  // Check if user is a Hobbyist (no payout access)
  const isHobbyist = user?.role === ROLES.HOBBYIST || user?.role === ROLES.GROM_PARENT || user?.is_grom_parent === true;
  
  // Search states
  const [causes, setCauses] = useState([]);
  const [groms, setGroms] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [searching, setSearching] = useState(false);
  
  // Settings states
  const [selectedDestination, setSelectedDestination] = useState(null);
  const [splitPercentage, setSplitPercentage] = useState(50);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (user?.id) {
      fetchDashboard();
      fetchCauses();
    }
  }, [user?.id]);

  const fetchDashboard = async () => {
    try {
      const res = await apiClient.get(`/impact/dashboard/${user.id}`);
      setDashboard(res.data);
      if (res.data.donation_settings?.split_percentage) {
        setSplitPercentage(res.data.donation_settings.split_percentage);
      }
    } catch (err) {
      logger.error('Failed to fetch impact dashboard:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchCauses = async () => {
    try {
      const res = await apiClient.get(`/impact/causes`);
      setCauses(res.data);
    } catch (err) {
      logger.error('Failed to fetch causes:', err);
    }
  };

  const searchGroms = async (query) => {
    if (!query) {
      setGroms([]);
      return;
    }
    setSearching(true);
    try {
      const res = await apiClient.get(`/impact/search-groms?search=${encodeURIComponent(query)}`);
      setGroms(res.data);
    } catch (err) {
      logger.error('Failed to search groms:', err);
    } finally {
      setSearching(false);
    }
  };

  const selectDestination = (type, item) => {
    setSelectedDestination({
      type,
      id: item.id,
      name: item.name || item.full_name,
      avatar_url: item.avatar_url || item.logo_url,
      is_cause: type === 'cause'
    });
  };

  const saveSettings = async () => {
    if (!selectedDestination) {
      toast.error('Please select a destination for your donations');
      return;
    }

    setSaving(true);
    try {
      await apiClient.put(`/impact/settings/${user.id}`, {
        donation_destination_type: selectedDestination.type,
        donation_destination_id: selectedDestination.is_cause ? null : selectedDestination.id,
        donation_cause_name: selectedDestination.is_cause ? selectedDestination.name : null,
        donation_split_percentage: dashboard?.is_pro ? splitPercentage : 100
      });
      toast.success('Impact settings saved!');
      fetchDashboard();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to save settings');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-cyan-500 dark:text-cyan-400 animate-spin" />
      </div>
    );
  }

  const level = dashboard?.impact_score ? IMPACT_LEVELS[
    dashboard.impact_score.total_credits_given >= 10000 ? 'Legend' :
    dashboard.impact_score.total_credits_given >= 5000 ? 'Champion' :
    dashboard.impact_score.total_credits_given >= 2500 ? 'Hero' :
    dashboard.impact_score.total_credits_given >= 1000 ? 'Patron' :
    dashboard.impact_score.total_credits_given >= 500 ? 'Supporter' :
    dashboard.impact_score.total_credits_given >= 100 ? 'Contributor' : 'Starter'
  ] : IMPACT_LEVELS.Starter;

  const levelName = dashboard?.impact_score?.total_credits_given >= 10000 ? 'Legend' :
    dashboard?.impact_score?.total_credits_given >= 5000 ? 'Champion' :
    dashboard?.impact_score?.total_credits_given >= 2500 ? 'Hero' :
    dashboard?.impact_score?.total_credits_given >= 1000 ? 'Patron' :
    dashboard?.impact_score?.total_credits_given >= 500 ? 'Supporter' :
    dashboard?.impact_score?.total_credits_given >= 100 ? 'Contributor' : 'Starter';

  return (
    <div 
      className="min-h-screen bg-background pb-24 md:pb-6"
      style={{ paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) + 80px)' }}
      data-testid="impact-dashboard"
    >
      {/* Header */}
      <div className="relative bg-gradient-to-r from-cyan-600/20 via-blue-500/10 to-cyan-600/20 border-b border-cyan-500/20">
        <div className="max-w-6xl mx-auto px-4 py-8">
          <div className="flex items-center gap-3 mb-4">
            <div className={`p-3 rounded-xl bg-gradient-to-br ${level.color}`}>
              <Heart className="w-7 h-7 text-white" />
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-foreground">Impact Dashboard</h1>
              <p className="text-muted-foreground text-sm">Track your contributions to the surf community</p>
            </div>
          </div>
          
          {/* Impact Level Card */}
          <div className={`mt-6 p-6 rounded-xl bg-gradient-to-br ${level.color} bg-opacity-20`}>
            <div className="flex items-center justify-between">
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-3xl">{level.emoji}</span>
                  <span className="text-foreground font-bold text-xl">{levelName}</span>
                </div>
                <p className="text-foreground/80 text-sm">Impact Level</p>
              </div>
              <div className="text-right">
                <p className="text-3xl font-bold text-foreground">
                  {dashboard?.impact_score?.total_credits_given?.toFixed(0) || 0}
                </p>
                <p className="text-foreground/80 text-sm">Credits Given</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="max-w-6xl mx-auto px-4 mt-6">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Card className="bg-card border-border">
            <CardContent className="p-4 text-center">
              <Users className="w-8 h-8 text-amber-400 mx-auto mb-2" />
              <p className="text-2xl font-bold text-foreground">{dashboard?.impact_score?.total_groms_supported || 0}</p>
              <p className="text-muted-foreground text-sm">Groms Supported</p>
            </CardContent>
          </Card>
          <Card className="bg-card border-border">
            <CardContent className="p-4 text-center">
              <Waves className="w-8 h-8 text-blue-400 mx-auto mb-2" />
              <p className="text-2xl font-bold text-foreground">{dashboard?.impact_score?.total_causes_supported || 0}</p>
              <p className="text-muted-foreground text-sm">Causes Supported</p>
            </CardContent>
          </Card>
          <Card className="bg-card border-border">
            <CardContent className="p-4 text-center">
              <Gift className="w-8 h-8 text-green-400 mx-auto mb-2" />
              <p className="text-2xl font-bold text-foreground">{dashboard?.impact_score?.sponsorships_given || 0}</p>
              <p className="text-muted-foreground text-sm">Sponsorships Given</p>
            </CardContent>
          </Card>
          <Card className="bg-card border-border">
            <CardContent className="p-4 text-center">
              <DollarSign className="w-8 h-8 text-cyan-400 mx-auto mb-2" />
              <p className="text-2xl font-bold text-foreground">
                {dashboard?.is_pro && !isHobbyist
                  ? dashboard?.credits?.withdrawable?.toFixed(2) 
                  : dashboard?.credits?.gear_only?.toFixed(2) || '0.00'}
              </p>
              <p className="text-muted-foreground text-sm">
                {isHobbyist 
                  ? 'Community Impact' 
                  : dashboard?.is_pro 
                    ? 'Withdrawable' 
                    : 'Gear Credits'}
              </p>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Tabs */}
      <div className="max-w-6xl mx-auto px-4 mt-8">
        <div className="flex gap-2 border-b border-border pb-2">
          {['overview', 'causes', 'groms', 'settings'].map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-4 py-2 rounded-t-lg font-medium transition-all capitalize ${
                activeTab === tab
                  ? 'bg-cyan-500/20 text-cyan-500 dark:text-cyan-400 border-b-2 border-cyan-500'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
              data-testid={`impact-tab-${tab}`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      {/* Tab Content */}
      <div className="max-w-6xl mx-auto px-4 mt-6">
        {activeTab === 'overview' && (
          <div className="space-y-6">
            {/* Athlete Stoke Generated - NEW */}
            <Card className="bg-gradient-to-br from-pink-500/10 via-background to-yellow-500/10 border-2 border-pink-500/30">
              <CardHeader className="pb-2">
                <CardTitle className="flex items-center gap-2 text-foreground">
                  <Heart className="w-5 h-5 text-pink-500 dark:text-pink-400" />
                  Athlete Stoke Generated
                  <Badge className="ml-auto bg-pink-500/20 text-pink-600 dark:text-pink-400 border-0 text-xs">YOUR IMPACT</Badge>
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-2 gap-4 mb-4">
                  <div className="p-4 bg-pink-500/10 rounded-lg text-center">
                    <div className="text-3xl font-bold text-pink-500 dark:text-pink-400">
                      ${dashboard?.impact_score?.total_credits_given?.toFixed(0) || 0}
                    </div>
                    <div className="text-sm text-muted-foreground">Total Credits Given</div>
                  </div>
                  <div className="p-4 bg-yellow-500/10 rounded-lg text-center">
                    <div className="text-3xl font-bold text-yellow-500 dark:text-yellow-400">
                      {dashboard?.impact_score?.total_groms_supported || 0}
                    </div>
                    <div className="text-sm text-muted-foreground">Athletes Supported</div>
                  </div>
                </div>
                <p className="text-sm text-muted-foreground text-center">
                  You helped Groms earn <span className="text-pink-500 dark:text-pink-400 font-bold">${dashboard?.impact_score?.total_credits_given?.toFixed(0) || 0}</span> in gear credits this month
                </p>
                <Button 
                  variant="outline"
                  className="w-full mt-4 border-pink-500/50 text-pink-600 dark:text-pink-400 hover:bg-pink-500/10"
                  onClick={() => window.location.href = '/career/stoke-sponsor'}
                >
                  <Heart className="w-4 h-4 mr-2" />
                  Sponsor More Athletes
                </Button>
              </CardContent>
            </Card>
            
            {/* Current Destination */}
            {dashboard?.donation_settings?.destination_info && (
              <Card className="bg-card border-cyan-500/30">
                <CardHeader>
                  <CardTitle className="text-foreground flex items-center gap-2">
                    <Target className="w-5 h-5 text-cyan-500 dark:text-cyan-400" />
                    Current Impact Destination
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="flex items-center gap-4">
                    <Avatar className="w-16 h-16">
                      <AvatarImage src={getFullUrl(dashboard.donation_settings.destination_info.avatar_url || dashboard.donation_settings.destination_info.logo_url)} />
                      <AvatarFallback className="bg-cyan-900 text-cyan-400">
                        {dashboard.donation_settings.destination_info.name?.[0] || '?'}
                      </AvatarFallback>
                    </Avatar>
                    <div>
                      <p className="text-foreground font-semibold text-lg">
                        {dashboard.donation_settings.destination_info.name}
                      </p>
                      <Badge className={`${
                        dashboard.donation_settings.destination_type === 'grom' 
                          ? 'bg-amber-500/20 text-amber-600 dark:text-amber-400' 
                          : 'bg-blue-500/20 text-blue-600 dark:text-blue-400'
                      }`}>
                        {dashboard.donation_settings.destination_type === 'grom' ? 'Grom' : 'Cause'}
                      </Badge>
                    </div>
                    {dashboard?.is_pro && (
                      <div className="ml-auto text-right">
                        <p className="text-3xl font-bold text-cyan-500 dark:text-cyan-400">
                          {dashboard.donation_settings.split_percentage || 50}%
                        </p>
                        <p className="text-muted-foreground text-sm">of earnings donated</p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            )}

            {/* Recent Sponsorships */}
            <Card className="bg-card border-border">
              <CardHeader>
                <CardTitle className="text-foreground flex items-center gap-2">
                  <TrendingUp className="w-5 h-5 text-green-500 dark:text-green-400" />
                  Recent Impact
                </CardTitle>
              </CardHeader>
              <CardContent>
                {dashboard?.recent_sponsorships?.length > 0 ? (
                  <div className="space-y-3">
                    {dashboard.recent_sponsorships.map(s => (
                      <div key={s.id} className="flex items-center gap-4 p-3 bg-muted/50 rounded-lg">
                        <Avatar>
                          <AvatarImage src={s.recipient_avatar} />
                          <AvatarFallback className="bg-muted">
                            {s.recipient_name?.[0] || '?'}
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex-1">
                          <p className="text-foreground font-medium">{s.recipient_name}</p>
                          <p className="text-muted-foreground text-sm">{s.recipient_type}</p>
                        </div>
                        <div className="text-right">
                          <p className="text-green-500 dark:text-green-400 font-bold">${s.amount?.toFixed(2)}</p>
                          <p className="text-muted-foreground text-xs">
                            {new Date(s.created_at).toLocaleDateString()}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-muted-foreground text-center py-8">
                    No sponsorships yet. Set a destination to start making an impact!
                  </p>
                )}
              </CardContent>
            </Card>
          </div>
        )}

        {activeTab === 'causes' && (
          <div className="grid md:grid-cols-2 gap-4">
            {causes.map(cause => (
              <Card 
                key={cause.id}
                className={`bg-card border-border hover:border-cyan-500/50 transition-all cursor-pointer ${
                  selectedDestination?.id === cause.id ? 'ring-2 ring-cyan-500' : ''
                }`}
                onClick={() => selectDestination('cause', cause)}
              >
                <CardContent className="p-4">
                  <div className="flex items-start gap-4">
                    <div className="w-12 h-12 bg-blue-500/20 dark:bg-blue-900/30 rounded-lg flex items-center justify-center">
                      <Waves className="w-6 h-6 text-blue-500 dark:text-blue-400" />
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="text-foreground font-semibold">{cause.name}</h3>
                        {cause.is_featured && (
                          <Star className="w-4 h-4 text-amber-400" />
                        )}
                      </div>
                      <p className="text-muted-foreground text-sm mb-2">{cause.description}</p>
                      <div className="flex items-center gap-2">
                        <Badge className={CAUSE_CATEGORIES[cause.category]?.color || 'bg-muted'}>
                          {CAUSE_CATEGORIES[cause.category]?.label || cause.category}
                        </Badge>
                        {cause.website_url && (
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              window.open(cause.website_url, '_blank');
                            }}
                            className="text-muted-foreground hover:text-cyan-500 dark:hover:text-cyan-400"
                          >
                            <ExternalLink className="w-4 h-4" />
                          </button>
                        )}
                      </div>
                    </div>
                    {selectedDestination?.id === cause.id && (
                      <Check className="w-6 h-6 text-cyan-500 dark:text-cyan-400" />
                    )}
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}

        {activeTab === 'groms' && (
          <div className="space-y-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
              <Input
                type="text"
                placeholder="Search for a Grom to support..."
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  searchGroms(e.target.value);
                }}
                className="pl-10 bg-card border-border text-foreground"
              />
            </div>

            {searching ? (
              <div className="flex justify-center py-8">
                <Loader2 className="w-6 h-6 text-cyan-500 dark:text-cyan-400 animate-spin" />
              </div>
            ) : groms.length > 0 ? (
              <div className="grid md:grid-cols-2 gap-4">
                {groms.map(grom => (
                  <Card 
                    key={grom.id}
                    className={`bg-card border-border hover:border-amber-500/50 transition-all cursor-pointer ${
                      selectedDestination?.id === grom.id ? 'ring-2 ring-amber-500' : ''
                    }`}
                    onClick={() => selectDestination('grom', grom)}
                  >
                    <CardContent className="p-4">
                      <div className="flex items-center gap-4">
                        <Avatar className="w-14 h-14">
                          <AvatarImage src={getFullUrl(grom.avatar_url)} />
                          <AvatarFallback className="bg-amber-900 text-amber-400">
                            {grom.full_name?.[0] || '?'}
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex-1">
                          <h3 className="text-foreground font-semibold">{grom.full_name}</h3>
                          <p className="text-muted-foreground text-sm">{grom.location}</p>
                          {grom.skill_level && (
                            <Badge className="bg-amber-500/20 text-amber-600 dark:text-amber-400 mt-1">
                              {grom.skill_level}
                            </Badge>
                          )}
                        </div>
                        {selectedDestination?.id === grom.id && (
                          <Check className="w-6 h-6 text-amber-400" />
                        )}
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : searchQuery ? (
              <p className="text-muted-foreground text-center py-8">No Groms found matching "{searchQuery}"</p>
            ) : (
              <p className="text-muted-foreground text-center py-8">
                Search for a Grom to support their surfing journey
              </p>
            )}
          </div>
        )}

        {activeTab === 'settings' && (
          <Card className="bg-card border-border">
            <CardHeader>
              <CardTitle className="text-foreground flex items-center gap-2">
                <Settings className="w-5 h-5 text-muted-foreground" />
                Impact Settings
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Selected Destination */}
              <div>
                <label className="text-muted-foreground text-sm block mb-2">
                  Donation Destination
                </label>
                {selectedDestination ? (
                  <div className="flex items-center gap-4 p-4 bg-muted/50 rounded-lg">
                    <Avatar>
                      <AvatarImage src={getFullUrl(selectedDestination.avatar_url)} />
                      <AvatarFallback className="bg-cyan-900 text-cyan-400">
                        {selectedDestination.name?.[0] || '?'}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1">
                      <p className="text-foreground font-medium">{selectedDestination.name}</p>
                      <Badge className={selectedDestination.type === 'grom' ? 'bg-amber-500/20 text-amber-600 dark:text-amber-400' : 'bg-blue-500/20 text-blue-600 dark:text-blue-400'}>
                        {selectedDestination.type === 'grom' ? 'Grom' : 'Cause'}
                      </Badge>
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setSelectedDestination(null)}
                      className="text-muted-foreground"
                    >
                      Change
                    </Button>
                  </div>
                ) : (
                  <p className="text-muted-foreground p-4 bg-muted/50 rounded-lg">
                    Select a Grom or Cause from the tabs above
                  </p>
                )}
              </div>

              {/* Split Percentage (Pros only) */}
              {dashboard?.is_pro && (
                <div>
                  <label className="text-muted-foreground text-sm block mb-2">
                    Donation Split ({splitPercentage}% to destination)
                  </label>
                  <input
                    type="range"
                    min="10"
                    max="100"
                    value={splitPercentage}
                    onChange={(e) => setSplitPercentage(parseInt(e.target.value))}
                    className="w-full h-2 bg-muted rounded-lg appearance-none cursor-pointer accent-cyan-500"
                  />
                  <div className="flex justify-between text-xs text-muted-foreground mt-1">
                    <span>10%</span>
                    <span>50%</span>
                    <span>100%</span>
                  </div>
                  <p className="text-muted-foreground text-sm mt-2">
                    {splitPercentage}% of your session earnings will go to your selected destination.
                    {splitPercentage < 100 && !isHobbyist && ` The remaining ${100 - splitPercentage}% goes to your withdrawable balance.`}
                  </p>
                </div>
              )}

              {/* Hobbyist Info - Focus on Community Impact */}
              {(dashboard?.is_hobbyist || isHobbyist) && (
                <div className="p-4 bg-gradient-to-r from-pink-500/10 to-cyan-500/10 border border-pink-500/30 rounded-lg">
                  <div className="flex items-center gap-2 mb-2">
                    <Heart className="w-5 h-5 text-pink-500 dark:text-pink-400" />
                    <span className="text-pink-600 dark:text-pink-400 font-medium">Your Impact Matters</span>
                  </div>
                  <p className="text-foreground/80 text-sm">
                    As a community photographer, your focus is on the 'Stoke' you generate for athletes. 
                    Every session you shoot helps surfers build their portfolios and attract sponsors.
                  </p>
                  <div className="mt-3 p-2 bg-pink-500/10 rounded-lg text-center">
                    <p className="text-pink-600 dark:text-pink-300 text-xs">
                      You've helped athletes earn <span className="font-bold">${dashboard?.impact_score?.total_credits_given?.toFixed(0) || 0}</span> in gear credits
                    </p>
                  </div>
                </div>
              )}

              <Button
                onClick={saveSettings}
                disabled={saving || !selectedDestination}
                className="w-full bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white"
                data-testid="save-impact-settings"
              >
                {saving ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                Save Impact Settings
              </Button>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
};

﻿import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  Trophy, Target, TrendingUp, Users, Calendar, 
  ChevronRight, Loader2, Plus, CheckCircle, Clock, Medal,
  Flame, Award, Video, MapPin, Star
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { Input } from './ui/input';
import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';


/**
 * The Impact Zone - Career Hub for Competitive Surfers
 * Features: Competition Stats, Rankings, Contest Calendar, Heat Analysis, Comp Crew
 */
export const ImpactZoneHub = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  
  const [_competitionStats, setCompetitionStats] = useState(null);
  const [upcomingContests, setUpcomingContests] = useState([]);
  const [competitionResults, setCompetitionResults] = useState([]);
  const [rankings, setRankings] = useState(null);
  const [_compCrewMembers, setCompCrewMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAddResultModal, setShowAddResultModal] = useState(false);

  const isLight = theme === 'light';
  const cardBg = isLight ? 'bg-white border-gray-200' : 'bg-zinc-900 border-zinc-800';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';

  useEffect(() => {
    if (user?.id) {
      fetchCompetitionData();
    }
  }, [user?.id]);

  const fetchCompetitionData = async () => {
    setLoading(true);
    try {
      const [statsRes, contestsRes, resultsRes, rankingsRes, crewRes] = await Promise.all([
        apiClient.get(`/career/stats/${user.id}`).catch(() => ({ data: null })),
        apiClient.get(`/career/upcoming-contests`).catch(() => ({ data: { contests: [] } })),
        apiClient.get(`/career/competition-results/${user.id}`).catch(() => ({ data: { results: [] } })),
        apiClient.get(`/career/rankings/${user.id}`).catch(() => ({ data: null })),
        apiClient.get(`/social/followers/${user.id}?filter=comp`).catch(() => ({ data: [] }))
      ]);
      
      setCompetitionStats(statsRes.data);
      setUpcomingContests(contestsRes.data?.contests || mockUpcomingContests);
      setCompetitionResults(resultsRes.data?.results || []);
      setRankings(rankingsRes.data || mockRankings);
      setCompCrewMembers(crewRes.data?.slice?.(0, 5) || []);
    } catch (error) {
      logger.error('Failed to fetch competition data:', error);
    } finally {
      setLoading(false);
    }
  };

  // Mock data for upcoming contests
  const mockUpcomingContests = [
    { id: 1, name: "Regional QS 1000", location: "Huntington Beach, CA", date: "Apr 15-17, 2026", division: "Men's Open", status: "registered" },
    { id: 2, name: "Local Club Championship", location: "Trestles, CA", date: "Apr 22, 2026", division: "Men's Open", status: "pending" },
    { id: 3, name: "State Championships", location: "Santa Cruz, CA", date: "May 5-8, 2026", division: "Men's Open", status: "open" },
  ];

  // Mock rankings data
  const mockRankings = {
    regional: { rank: 24, total: 156, points: 1250 },
    local: { rank: 8, total: 42, points: 890 },
    club: { rank: 3, total: 28, points: 450 }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-orange-500" />
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className={`text-2xl font-bold ${textPrimary} flex items-center gap-2`}>
            <Target className="w-7 h-7 text-orange-500" />
            The Impact Zone
          </h1>
          <p className={`${textSecondary} text-sm mt-1`}>Your competitive surfing hub</p>
        </div>
        <Badge className="bg-gradient-to-r from-orange-500 to-red-500 text-white border-0">
          <Flame className="w-3 h-3 mr-1" /> Competitor
        </Badge>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-3 gap-3">
        <Card className={`${cardBg}`}>
          <CardContent className="p-4 text-center">
            <Trophy className="w-6 h-6 mx-auto mb-2 text-yellow-500" />
            <p className={`text-2xl font-bold ${textPrimary}`}>{competitionResults.length || 0}</p>
            <p className={`text-xs ${textSecondary}`}>Competitions</p>
          </CardContent>
        </Card>
        <Card className={`${cardBg}`}>
          <CardContent className="p-4 text-center">
            <Medal className="w-6 h-6 mx-auto mb-2 text-orange-500" />
            <p className={`text-2xl font-bold ${textPrimary}`}>{rankings?.regional?.rank || '--'}</p>
            <p className={`text-xs ${textSecondary}`}>Regional Rank</p>
          </CardContent>
        </Card>
        <Card className={`${cardBg}`}>
          <CardContent className="p-4 text-center">
            <TrendingUp className="w-6 h-6 mx-auto mb-2 text-green-500" />
            <p className={`text-2xl font-bold ${textPrimary}`}>{rankings?.regional?.points || 0}</p>
            <p className={`text-xs ${textSecondary}`}>Points</p>
          </CardContent>
        </Card>
      </div>

      {/* Rankings Card */}
      <Card className={`${cardBg}`}>
        <CardHeader className="pb-2">
          <CardTitle className={`${textPrimary} text-lg flex items-center gap-2`}>
            <TrendingUp className="w-5 h-5 text-orange-500" />
            Your Rankings
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {rankings && (
            <>
              <div className="flex items-center justify-between p-3 bg-orange-500/10 rounded-lg">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-orange-500/20 flex items-center justify-center">
                    <Trophy className="w-5 h-5 text-orange-400" />
                  </div>
                  <div>
                    <p className={`font-medium ${textPrimary}`}>Regional</p>
                    <p className={`text-xs ${textSecondary}`}>{rankings.regional.points} pts</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-2xl font-bold text-orange-400">#{rankings.regional.rank}</p>
                  <p className={`text-xs ${textSecondary}`}>of {rankings.regional.total}</p>
                </div>
              </div>
              
              <div className="flex items-center justify-between p-3 bg-cyan-500/10 rounded-lg">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-cyan-500/20 flex items-center justify-center">
                    <MapPin className="w-5 h-5 text-cyan-400" />
                  </div>
                  <div>
                    <p className={`font-medium ${textPrimary}`}>Local</p>
                    <p className={`text-xs ${textSecondary}`}>{rankings.local.points} pts</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-2xl font-bold text-cyan-400">#{rankings.local.rank}</p>
                  <p className={`text-xs ${textSecondary}`}>of {rankings.local.total}</p>
                </div>
              </div>
              
              <div className="flex items-center justify-between p-3 bg-purple-500/10 rounded-lg">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-purple-500/20 flex items-center justify-center">
                    <Users className="w-5 h-5 text-purple-400" />
                  </div>
                  <div>
                    <p className={`font-medium ${textPrimary}`}>Club</p>
                    <p className={`text-xs ${textSecondary}`}>{rankings.club.points} pts</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-2xl font-bold text-purple-400">#{rankings.club.rank}</p>
                  <p className={`text-xs ${textSecondary}`}>of {rankings.club.total}</p>
                </div>
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {/* Upcoming Contests */}
      <Card className={`${cardBg}`}>
        <CardHeader className="pb-2">
          <div className="flex items-center justify-between">
            <CardTitle className={`${textPrimary} text-lg flex items-center gap-2`}>
              <Calendar className="w-5 h-5 text-yellow-500" />
              Upcoming Contests
            </CardTitle>
            <Button variant="ghost" size="sm" className="text-orange-400" onClick={() => navigate('/contest-calendar')}>
              View All <ChevronRight className="w-4 h-4 ml-1" />
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-3">
          {upcomingContests.map((contest) => (
            <div key={contest.id} className="flex items-center justify-between p-3 bg-zinc-800/50 rounded-lg">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                  contest.status === 'registered' ? 'bg-green-500/20' : 
                  contest.status === 'pending' ? 'bg-yellow-500/20' : 'bg-zinc-700'
                }`}>
                  <Trophy className={`w-5 h-5 ${
                    contest.status === 'registered' ? 'text-green-400' : 
                    contest.status === 'pending' ? 'text-yellow-400' : 'text-gray-400'
                  }`} />
                </div>
                <div>
                  <p className={`font-medium ${textPrimary}`}>{contest.name}</p>
                  <p className={`text-xs ${textSecondary}`}>{contest.location}</p>
                  <p className={`text-xs ${textSecondary}`}>{contest.date}</p>
                </div>
              </div>
              <div className="text-right">
                {contest.status === 'registered' && (
                  <Badge className="bg-green-500/20 text-green-400 border-green-500/30">
                    <CheckCircle className="w-3 h-3 mr-1" /> Registered
                  </Badge>
                )}
                {contest.status === 'pending' && (
                  <Badge className="bg-yellow-500/20 text-yellow-400 border-yellow-500/30">
                    <Clock className="w-3 h-3 mr-1" /> Pending
                  </Badge>
                )}
                {contest.status === 'open' && (
                  <Button size="sm" className="bg-orange-500 hover:bg-orange-600 text-white">
                    Register
                  </Button>
                )}
              </div>
            </div>
          ))}
        </CardContent>
      </Card>

      {/* Competition Results */}
      <Card className={`${cardBg}`}>
        <CardHeader className="pb-2">
          <div className="flex items-center justify-between">
            <CardTitle className={`${textPrimary} text-lg flex items-center gap-2`}>
              <Award className="w-5 h-5 text-purple-500" />
              Competition Results
            </CardTitle>
            <Button 
              variant="outline" 
              size="sm" 
              className="border-orange-500/50 text-orange-400 hover:bg-orange-500/10"
              onClick={() => setShowAddResultModal(true)}
            >
              <Plus className="w-4 h-4 mr-1" /> Add Result
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {competitionResults.length > 0 ? (
            <div className="space-y-3">
              {competitionResults.map((result, idx) => (
                <div key={idx} className="flex items-center justify-between p-3 bg-zinc-800/50 rounded-lg">
                  <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                      result.placement <= 3 ? 'bg-yellow-500/20' : 'bg-zinc-700'
                    }`}>
                      {result.placement <= 3 ? (
                        <Medal className="w-5 h-5 text-yellow-400" />
                      ) : (
                        <Trophy className="w-5 h-5 text-gray-400" />
                      )}
                    </div>
                    <div>
                      <p className={`font-medium ${textPrimary}`}>{result.contest_name}</p>
                      <p className={`text-xs ${textSecondary}`}>{result.date}</p>
                    </div>
                  </div>
                  <Badge className={
                    result.placement === 1 ? 'bg-yellow-500/20 text-yellow-400' :
                    result.placement === 2 ? 'bg-gray-400/20 text-gray-300' :
                    result.placement === 3 ? 'bg-amber-600/20 text-amber-500' :
                    'bg-zinc-700 text-gray-400'
                  }>
                    {result.placement === 1 ? '1st' : 
                     result.placement === 2 ? '2nd' : 
                     result.placement === 3 ? '3rd' : 
                     `${result.placement}th`}
                  </Badge>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8">
              <Trophy className="w-12 h-12 mx-auto mb-3 text-zinc-600" />
              <p className={textSecondary}>No competition results yet</p>
              <p className={`text-xs ${textSecondary} mt-1`}>Add your first result to track your progress</p>
              <Button 
                className="mt-4 bg-orange-500 hover:bg-orange-600"
                onClick={() => setShowAddResultModal(true)}
              >
                <Plus className="w-4 h-4 mr-2" /> Add Competition Result
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Heat Analysis */}
      <Card className={`${cardBg}`}>
        <CardHeader className="pb-2">
          <CardTitle className={`${textPrimary} text-lg flex items-center gap-2`}>
            <Video className="w-5 h-5 text-cyan-500" />
            Heat Analysis
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center py-6">
