export default ImpactZoneHub;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';


/**
 * LivePhotographers - Shows users who are SOCIALLY LIVE (broadcasting to followers)
 * This is Instagram Live style - NOT photographers who are actively shooting at spots.
 * The red gradient ring indicates social broadcasting.
 */
export const LivePhotographers = () => {
  const [liveUsers, setLiveUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    fetchSocialLiveUsers();
  }, []);

  const fetchSocialLiveUsers = async () => {
    try {
      // Fetch users who are SOCIALLY live (is_live=true), NOT just shooting (is_shooting)
      const response = await apiClient.get(`/profiles?is_live=true`);
      // Filter to ensure only is_live users (not is_shooting)
      const socialLiveUsers = (response.data || []).filter(u => u.is_live === true);
      setLiveUsers(socialLiveUsers);
    } catch (error) {
      logger.error('Failed to fetch live users:', error);
      setLiveUsers([]);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex gap-4 p-4">
        {[1, 2, 3].map((i) => (
          <div key={i} className="flex flex-col items-center gap-2 animate-pulse">
            <div className="w-16 h-16 rounded-full bg-zinc-700" />
            <div className="w-12 h-3 bg-zinc-700 rounded" />
          </div>
        ))}
      </div>
    );
  }

  // Don't show section if no one is socially live
  if (liveUsers.length === 0) {
    return null;
  }

  return (
    <div className="px-4 py-3">
      <p className="text-xs text-gray-500 mb-2">Broadcasting Now</p>
      <div className="flex gap-4 overflow-x-auto pb-2">
        {liveUsers.map((user) => (
          <div 
            key={user.id} 
            onClick={() => navigate(`/profile/${user.id}`)}
            className="flex flex-col items-center cursor-pointer flex-shrink-0"
          >
            {/* Avatar with Instagram-style gradient ring for SOCIAL LIVE */}
            <div className="relative">
              <div 
                className="w-14 h-14 rounded-full p-[2px]"
                style={{
                  background: 'linear-gradient(135deg, #f97316 0%, #ec4899 50%, #8b5cf6 100%)'
                }}
              >
                <div className="w-full h-full rounded-full bg-black flex items-center justify-center overflow-hidden p-[2px]">
                  {user.avatar_url ? (
                    <img 
                      src={getFullUrl(user.avatar_url)} 
                      alt={user.full_name}
                      className="w-full h-full object-cover rounded-full"
                    />
                  ) : (
                    <div className="w-full h-full rounded-full bg-zinc-700 flex items-center justify-center">
                      <span className="text-lg text-gray-400">
                        {user.full_name?.charAt(0) || '?'}
                      </span>
                    </div>
                  )}
                </div>
              </div>
              {/* Live badge */}
              <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 px-1.5 py-0.5 bg-red-500 rounded text-[9px] text-white font-bold">
                LIVE
              </div>
            </div>
            
            {/* Name - no Message button */}
            <span className="text-xs text-gray-300 mt-2 truncate max-w-[60px]">
              {user.full_name?.split(' ')[0] || 'User'}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { toast } from 'sonner';
import { ScanFace, RefreshCw } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from './ui/dialog';
import SelfieCapture from './SelfieCapture';


export const LockerSelfieModal = ({ isOpen, onClose, user, fetchClaimQueue, spotId = null, spotName = null, photographerId = null, photographerName = null }) => {
  const [scanning, setScanning] = useState(false);

  const handleCapture = async (selfieUrl) => {
    setScanning(true);
    try {
      await apiClient.post(`/surfer-gallery/scan-locker?surfer_id=${user?.id}`, {
        selfie_url: selfieUrl,
        spot_id: spotId,
        photographer_id: photographerId
      });
      
      let msg = "AI scanning initiated! Your locker will update shortly with matches.";
      if (spotName) msg = `Scanning ${spotName} initiated! Matches will appear in your locker.`;
      if (photographerName) msg = `Scanning ${photographerName}'s galleries initiated! Matches will appear in your locker.`;
      
      toast.success(msg);
      
      if (fetchClaimQueue) {
          setTimeout(() => fetchClaimQueue(), 4000);
          setTimeout(() => fetchClaimQueue(), 12000);
      }
    } catch (err) {
      toast.error("Failed to start scan");
    } finally {
      setScanning(false);
      onClose();
    }
  };

  let title = "Scan Recent Galleries";
  if (spotName) title = `Scan ${spotName}`;
  if (photographerName) title = `Scan ${photographerName}'s Photos`;

  let desc = "Hold your surfboard up! We'll search recent public galleries for your face, wetsuit, and board colors.";
  if (spotName) desc = `Hold your surfboard up! We'll search the last 30 days of ${spotName} galleries for your face, wetsuit, and board colors.`;
  if (photographerName) desc = `Hold your surfboard up! We'll search the last 30 days of ${photographerName}'s galleries for your face, wetsuit, and board colors.`;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-zinc-900 border border-zinc-700 sm:max-w-[450px]">
        <DialogHeader>
          <DialogTitle className="text-white flex items-center gap-2">
            <ScanFace className="w-5 h-5 text-cyan-400" />
            {title}
          </DialogTitle>
          <div className="text-gray-400 text-sm">
            {desc}
          </div>
        </DialogHeader>
        {scanning ? (
          <div className="py-12 flex flex-col items-center">
            <RefreshCw className="w-10 h-10 text-cyan-400 animate-spin mb-4" />
            <p className="text-white">Mapping Neural Networks...</p>
          </div>
        ) : (
          <div className="flex-1 min-h-0 overflow-y-auto px-4 pb-4">
            <SelfieCapture onCapture={handleCapture} onSkip={onClose} skipAllowed={false} />
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};

import React, { useEffect, useState, useRef, useCallback, useMemo } from 'react';

