            {/* Surfer Identification Section */}
            {(request.requester_stance || request.requester_board_description) && (
              <div className="p-3 rounded-xl bg-cyan-500/10 border border-cyan-400/20 space-y-2">
                <p className={`text-xs font-semibold ${textSecondary} uppercase tracking-wider`}>🏄 Surfer ID</p>
                {request.requester_stance && (
                  <div className="flex items-center gap-2 text-sm">
                    <span className={textSecondary}>Stance:</span>
                    <span className={`font-medium ${textPrimary} capitalize`}>
                      {request.requester_stance === 'goofy' ? '🦶 Goofy Foot' : '🦶 Regular'}
                    </span>
                  </div>
                )}
                {request.requester_board_description && (
                  <div className="flex items-start gap-2 text-sm">
                    <span className={`${textSecondary} flex-shrink-0`}>Board:</span>
                    <span className={`font-medium ${textPrimary}`}>{request.requester_board_description}</span>
                  </div>
                )}
              </div>
            )}
            {request.requester_selfie && (
              <div className="mt-3">
                <p className={`text-xs ${textSecondary} mb-2`}>Surfer Photo (for identification):</p>
                <img 
                  src={getImageUrl(request.requester_selfie)} 
                  alt="Surfer" 
                  className="w-24 h-24 rounded-xl object-cover border-2 border-cyan-400/30"
                />
              </div>
            )}
          </div>
        )}
        
        <button 
          onClick={() => setIsExpanded(!isExpanded)}
          className={`w-full text-center text-sm ${textSecondary} mb-4 flex items-center justify-center gap-1 hover:text-cyan-400 transition-colors`}
        >
          {isExpanded ? 'Less details' : 'More details'}
          {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
        </button>
        
        {/* Action Buttons */}
        <div className="flex gap-3">
          <Button
            onClick={() => onDecline(request.dispatch_id)}
            variant="outline"
            className="flex-1 py-5 border-zinc-600 hover:bg-zinc-800"
            disabled={isAccepting}
            data-testid="decline-request-btn"
          >
            <X className="w-5 h-5 mr-2" />
            Decline
          </Button>
          <Button
            onClick={() => onAccept(request.dispatch_id)}
            className="flex-1 py-5 bg-gradient-to-r from-green-400 to-cyan-400 hover:from-green-500 hover:to-cyan-500 text-black font-bold"
            disabled={isAccepting}
            data-testid="accept-request-btn"
          >
            {isAccepting ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>
                <Check className="w-5 h-5 mr-2" />
                Accept
              </>
            )}
          </Button>
        </div>
      </CardContent>
    </Card>
    
    {/* Selfie Modal with Profile Info */}
    {showSelfieModal && (
      <div 
        className="fixed inset-0 z-50 bg-black/80 flex items-start justify-center p-4 overflow-y-auto"
        onClick={() => setShowSelfieModal(false)}
      >
        <div 
          className="bg-zinc-900 rounded-2xl w-full max-w-md my-8 overflow-hidden shadow-2xl border border-zinc-700"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Close Button */}
          <button 
            onClick={() => setShowSelfieModal(false)}
            className="absolute top-4 right-4 z-10 w-10 h-10 rounded-full bg-black/50 flex items-center justify-center text-white hover:bg-black/70 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
          
          {/* Large Selfie */}
          <div className="relative aspect-square">
            <img 
              src={getImageUrl(request.requester_selfie)} 
              alt="Surfer Identification" 
              className="w-full h-full object-cover"
            />
            <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent p-4">
              <Badge className="bg-cyan-500/80 text-white mb-2">
                <Camera className="w-3 h-3 mr-1" />
                ID Photo for Session
              </Badge>
            </div>
          </div>
          
          {/* Profile Info */}
          <div className="p-5 space-y-4">
            {/* Name & Basic Info */}
            <div className="flex items-center gap-4">
              {request.requester_avatar ? (
                <img src={getFullUrl(getImageUrl(request.requester_avatar))} alt="" className="w-14 h-14 rounded-full object-cover ring-2 ring-cyan-400" />
              ) : (
                <div className="w-14 h-14 rounded-full bg-cyan-500/20 flex items-center justify-center">
                  <User className="w-7 h-7 text-cyan-400" />
                </div>
              )}
              <div>
                <h3 className="text-xl font-bold text-white">{request.requester_name || 'Surfer'}</h3>
                <p className="text-sm text-gray-400">Requesting on-demand session</p>
              </div>
            </div>
            
            {/* Session Details */}
            <div className="grid grid-cols-2 gap-3">
              <div className="p-3 rounded-xl bg-zinc-800">
                <div className="flex items-center gap-2 text-cyan-400 mb-1">
                  <MapPin className="w-4 h-4" />
                  <span className="text-xs">Location</span>
                </div>
                <p className="text-sm text-white font-medium truncate">{request.location?.name || 'Nearby'}</p>
              </div>
              <div className="p-3 rounded-xl bg-zinc-800">
                <div className="flex items-center gap-2 text-purple-400 mb-1">
                  <Navigation className="w-4 h-4" />
                  <span className="text-xs">Distance</span>
                </div>
                <p className="text-sm text-white font-medium">{request.distance_miles?.toFixed(1) || '?'} miles</p>
              </div>
              <div className="p-3 rounded-xl bg-zinc-800">
                <div className="flex items-center gap-2 text-amber-400 mb-1">
                  <Clock className="w-4 h-4" />
                  <span className="text-xs">Duration</span>
                </div>
                <p className="text-sm text-white font-medium">{((request.estimated_duration || 1) * 60).toFixed(0)} min</p>
              </div>
              <div className="p-3 rounded-xl bg-zinc-800">
                <div className="flex items-center gap-2 text-green-400 mb-1">
                  <DollarSign className="w-4 h-4" />
                  <span className="text-xs">Your Rate</span>
                </div>
                <p className="text-sm text-white font-medium">${request.hourly_rate || 75}/hr</p>
              </div>
            </div>
            
            {/* Crew Info if shared */}
            {request.is_shared && (
              <div className="p-4 rounded-xl bg-purple-500/10 border border-purple-500/30">
                <div className="flex items-center gap-2 mb-3">
                  <Users className="w-5 h-5 text-purple-400" />
                  <span className="font-medium text-white">Group Session ({request.crew_count} surfers)</span>
                </div>
                <div className="space-y-3">
                  {/* Requester/Captain */}
                  <div className="flex items-center gap-3 p-2 rounded-lg bg-zinc-800/50 border border-cyan-500/30">
                    <div className="relative">
                      {request.requester_selfie ? (
                        <img 
                          src={getImageUrl(request.requester_selfie)} 
                          alt="" 
                          className="w-12 h-12 rounded-full object-cover ring-2 ring-cyan-400 cursor-pointer hover:ring-cyan-300"
                          onClick={() => window.open(getImageUrl(request.requester_selfie), '_blank')}
                        />
                      ) : request.requester_avatar ? (
                        <img src={getFullUrl(getImageUrl(request.requester_avatar))} alt="" className="w-12 h-12 rounded-full object-cover ring-2 ring-cyan-400/50" />
                      ) : (
                        <div className="w-12 h-12 rounded-full bg-cyan-500/30 flex items-center justify-center text-lg text-cyan-300 ring-2 ring-cyan-400/30">
                          {request.requester_name?.[0]?.toUpperCase() || '?'}
                        </div>
                      )}
                      <div className="absolute -bottom-1 -right-1 w-5 h-5 rounded-full bg-cyan-500 flex items-center justify-center">
                        <Camera className="w-3 h-3 text-white" />
                      </div>
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm text-white font-medium truncate">{request.requester_name}</p>
                      <p className="text-xs text-cyan-400">
                        {request.requester_username ? `@${request.requester_username} • ` : ''}Captain (Paid)
                      </p>
                    </div>
                    <Badge className="text-xs flex-shrink-0 bg-cyan-500/20 text-cyan-400">
                      Captain
                    </Badge>
                  </div>
                  
                  {/* Crew Members */}
                  {request.crew?.map((member, idx) => (
                    <div key={member.id || idx} className="flex items-center gap-3 p-2 rounded-lg bg-zinc-800/50">
                      <div className="relative">
                        {member.selfie_url ? (
                          <img 
                            src={getImageUrl(member.selfie_url)} 
                            alt="" 
                            className="w-12 h-12 rounded-full object-cover ring-2 ring-purple-400/50 cursor-pointer hover:ring-purple-400"
                            onClick={() => setSelectedCrewSelfie(member)}
                          />
                        ) : member.avatar_url ? (
                          <img src={getFullUrl(getImageUrl(member.avatar_url))} alt="" className="w-12 h-12 rounded-full object-cover ring-2 ring-purple-400/30" />
                        ) : (
                          <div className="w-12 h-12 rounded-full bg-purple-500/30 flex items-center justify-center text-lg text-purple-300 ring-2 ring-purple-400/30">
                            {member.name?.[0]?.toUpperCase() || '?'}
                          </div>
                        )}
                        {member.selfie_url && (
                          <div className="absolute -bottom-1 -right-1 w-5 h-5 rounded-full bg-cyan-500 flex items-center justify-center">
                            <Camera className="w-3 h-3 text-white" />
                          </div>
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm text-white font-medium truncate">{member.name}</p>
                        {member.username && (
                          <p className="text-xs text-purple-400">@{member.username}</p>
                        )}
                      </div>
                      <Badge className={`text-xs flex-shrink-0 ${member.status === 'paid' ? 'bg-green-500/20 text-green-400' : 'bg-amber-500/20 text-amber-400'}`}>
                        {member.status === 'paid' ? 'Paid' : 'Pending'}
                      </Badge>
                    </div>
                  ))}
                </div>
              </div>
            )}
            
            {/* Quick Accept Button */}
            <Button
              onClick={() => {
                setShowSelfieModal(false);
                onAccept(request.dispatch_id);
              }}
              className="w-full py-5 bg-gradient-to-r from-green-400 to-cyan-400 hover:from-green-500 hover:to-cyan-500 text-black font-bold"
              disabled={isAccepting}
            >
              {isAccepting ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <>
                  <Check className="w-5 h-5 mr-2" />
                  Accept This Session
                </>
              )}
            </Button>
          </div>
        </div>
      </div>
    )}
    
    {/* Crew Member Selfie Enlargement Modal */}
    {selectedCrewSelfie && (
      <div 
        className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4"
        onClick={() => setSelectedCrewSelfie(null)}
      >
        <div 
          className="bg-zinc-900 rounded-2xl w-full max-w-md overflow-hidden shadow-2xl border border-purple-500/50"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Close Button */}
          <button 
            onClick={() => setSelectedCrewSelfie(null)}
            className="absolute top-4 right-4 z-10 w-10 h-10 rounded-full bg-black/50 flex items-center justify-center text-white hover:bg-black/70 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
          
          {/* Large Selfie */}
          <div className="relative aspect-square">
            <img 
              src={getImageUrl(selectedCrewSelfie.selfie_url)} 
              alt="Crew Member Identification" 
              className="w-full h-full object-cover"
            />
            <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent p-4">
              <Badge className="bg-purple-500/80 text-white mb-2">
                <Camera className="w-3 h-3 mr-1" />
                Crew Member ID Photo
              </Badge>
            </div>
          </div>
          
          {/* Profile Info */}
          <div className="p-5 space-y-4">
            <div className="flex items-center gap-4">
              {selectedCrewSelfie.avatar_url ? (
                <img src={getFullUrl(getImageUrl(selectedCrewSelfie.avatar_url))} alt="" className="w-14 h-14 rounded-full object-cover ring-2 ring-purple-400" />
              ) : (
                <div className="w-14 h-14 rounded-full bg-purple-500/20 flex items-center justify-center">
                  <User className="w-7 h-7 text-purple-400" />
                </div>
              )}
              <div>
                <h3 className="text-xl font-bold text-white">{selectedCrewSelfie.name || 'Crew Member'}</h3>
                {selectedCrewSelfie.username && (
                  <p className="text-purple-400">@{selectedCrewSelfie.username}</p>
                )}
              </div>
              <Badge className="bg-green-500/20 text-green-400 ml-auto">
                {selectedCrewSelfie.status === 'paid' ? 'Paid' : 'Pending'}
              </Badge>
            </div>
            
            <p className="text-sm text-gray-400">
              Part of the crew session. Look for this surfer in the water!
            </p>
            
            <Button
              onClick={() => setSelectedCrewSelfie(null)}
              variant="outline"
              className="w-full border-purple-500/50 text-purple-400 hover:bg-purple-500/10"
            >
              Close
            </Button>
          </div>
        </div>
      </div>
    )}
    </>
  );
};

// ============ ACTIVE SESSION CARD ============
const ActiveSessionCard = ({ 
  session, 
  onMarkArrived, 
  onComplete, 
  onCancel,
  onOpenChat,
  _cardBg,
  textPrimary, 
  textSecondary,
  sectionBg,
  chatUnreadCount = 0,
  chatLatestMessage = null
}) => {
  const [elapsedTime, setElapsedTime] = useState(0);
  
  useEffect(() => {
    if (session.status !== 'arrived') return;
    
    const startTime = session.arrived_at ? new Date(session.arrived_at) : new Date();
    const updateTimer = () => {
      setElapsedTime(Math.floor((Date.now() - startTime.getTime()) / 1000));
    };
    updateTimer();
    const interval = setInterval(updateTimer, 1000);
    return () => clearInterval(interval);
  }, [session.status, session.arrived_at]);
  
  const formatTime = formatDuration;
  
  const isEnRoute = session.status === 'en_route';
  const isArrived = session.status === 'arrived';
  
  return (
    <Card className={`overflow-hidden ${isArrived 
      ? 'bg-gradient-to-r from-green-500/20 to-cyan-500/20 border-green-400/50' 
      : 'bg-gradient-to-r from-amber-500/20 to-orange-500/20 border-amber-400/50'}`}
      data-testid="active-session-card"
    >
      {/* Status Header */}
      <div className={`px-4 py-3 flex items-center justify-between ${isArrived ? 'bg-green-500/30' : 'bg-amber-500/30'}`}>
        <div className="flex items-center gap-2 text-white">
          {isArrived ? (
            <Camera className="w-5 h-5" />
          ) : (
            <Navigation className="w-5 h-5" />
          )}
          <span className="font-bold">{isArrived ? 'In Session' : 'En Route'}</span>
        </div>
        {isArrived && (
          <div className="text-white font-mono text-xl font-bold">
            {formatTime(elapsedTime)}
          </div>
        )}
        {isEnRoute && session.eta_minutes && (
          <div className="text-white font-bold">
            ETA: ~{session.eta_minutes} min
          </div>
        )}
      </div>
      
      <CardContent className="p-4 space-y-4">
        {/* Surfer Info */}
        <div className="flex items-center gap-4">
          <div className="w-16 h-16 rounded-xl overflow-hidden bg-zinc-700 flex-shrink-0 ring-2 ring-cyan-400/30">
            {session.requester_selfie ? (
              <img src={getImageUrl(session.requester_selfie)} alt="Surfer" className="w-full h-full object-cover" />
            ) : session.requester_avatar ? (
              <img src={getFullUrl(getImageUrl(session.requester_avatar))} alt="Surfer" className="w-full h-full object-cover" />
            ) : (
              <div className="w-full h-full flex items-center justify-center">
                <User className="w-8 h-8 text-zinc-500" />
              </div>
            )}
          </div>
          <div className="flex-1">
            <p className={`font-bold text-lg ${textPrimary}`}>{session.requester_name || 'Surfer'}</p>
            {session.requester_username && (
              <button
                onClick={(e) => { e.stopPropagation(); window.open(`/profile/${session.requester_username}`, '_blank'); }}
                className="text-sm text-cyan-400 hover:text-cyan-300 hover:underline transition-colors"
              >
                @{session.requester_username}
              </button>
            )}
            <div className="flex items-center gap-2 mt-1">
              <MapPin className="w-4 h-4 text-cyan-400" />
              <span className={`text-sm ${textSecondary}`}>{session.location_name || 'Meeting Point'}</span>
            </div>
          </div>
        </div>
        
        {/* Session Details */}
        <div className={`grid grid-cols-2 gap-3 p-4 rounded-xl ${sectionBg}`}>
          <div>
            <p className={`text-xs ${textSecondary}`}>Duration</p>
            <p className={`font-bold ${textPrimary}`}>{(session.estimated_duration || 1) * 60} min</p>
          </div>
          <div>
            <p className={`text-xs ${textSecondary}`}>Earnings</p>
            <p className="font-bold text-green-400">${((session.hourly_rate || 75) * (session.estimated_duration || 1)).toFixed(0)}</p>
          </div>
        </div>

        {/* Surfer Identification Details */}
        {(session.requester_stance || session.requester_board_description) && (
          <div className={`p-3 rounded-xl bg-cyan-500/10 border border-cyan-400/20`}>
            <p className={`text-[10px] font-semibold ${textSecondary} uppercase tracking-wider mb-2`}>🏄 Surfer Identification</p>
            <div className="flex flex-wrap items-center gap-2">
              {session.requester_stance && (
                <span className="text-xs font-medium px-2 py-1 rounded-full bg-purple-500/20 text-purple-400">
                  {session.requester_stance === 'goofy' ? '🦶 Goofy Foot' : '🦶 Regular'}
                </span>
              )}
              {session.requester_board_description && (
                <span className={`text-xs font-medium ${textPrimary}`}>🏄‍♂️ {session.requester_board_description}</span>
              )}
            </div>
          </div>
        )}
        
        {/* Crew Selfies Section - Show all surfers the photographer needs to identify */}
        {session.is_shared && session.crew && session.crew.length > 0 && (
          <div className={`p-4 rounded-xl ${sectionBg}`}>
            <p className={`text-xs font-semibold ${textSecondary} uppercase tracking-wider mb-3`}>
              Crew Members ({session.crew.length + 1} total surfers)
            </p>
            <div className="grid grid-cols-2 gap-3">
              {/* Captain's selfie */}
              <div 
                className="flex items-center gap-3 p-2 rounded-lg bg-zinc-800/50 cursor-pointer hover:bg-zinc-700/50"
                onClick={() => session.requester_selfie && window.open(getImageUrl(session.requester_selfie), '_blank')}
              >
                <div className="w-12 h-12 rounded-full overflow-hidden ring-2 ring-amber-400/50 flex-shrink-0">
                  {session.requester_selfie ? (
                    <img src={getImageUrl(session.requester_selfie)} alt="" className="w-full h-full object-cover" />
                  ) : session.requester_avatar ? (
                    <img src={getFullUrl(getImageUrl(session.requester_avatar))} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full bg-amber-500/30 flex items-center justify-center">
                      <User className="w-6 h-6 text-amber-400" />
                    </div>
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm text-white font-medium truncate">{session.requester_name}</p>
                  <p className="text-xs text-amber-400">Captain</p>
                </div>
              </div>
              
              {/* Crew member selfies */}
              {session.crew.filter(m => m.paid).map((member, idx) => (
                <div 
                  key={member.id || idx}
                  className="flex items-center gap-3 p-2 rounded-lg bg-zinc-800/50 cursor-pointer hover:bg-zinc-700/50"
                  onClick={() => member.selfie_url && window.open(getImageUrl(member.selfie_url), '_blank')}
                >
                  <div className="w-12 h-12 rounded-full overflow-hidden ring-2 ring-purple-400/50 flex-shrink-0">
                    {member.selfie_url ? (
                      <img src={getImageUrl(member.selfie_url)} alt="" className="w-full h-full object-cover" />
                    ) : member.avatar_url ? (
                      <img src={getFullUrl(getImageUrl(member.avatar_url))} alt="" className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full bg-purple-500/30 flex items-center justify-center">
                        <User className="w-6 h-6 text-purple-400" />
                      </div>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm text-white font-medium truncate">{member.name}</p>
                    <p className="text-xs text-purple-400">@{member.username}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
        
        {/* Pro Tip */}
        {isEnRoute && session.requester_selfie && (
          <div className={`p-3 rounded-xl bg-cyan-500/10 border border-cyan-400/30`}>
            <p className="text-cyan-400 text-sm font-medium flex items-center gap-2">
              <Eye className="w-4 h-4" />
              Surfer uploaded an ID photo - check above!
            </p>
          </div>
        )}
        
        {/* Inline Message Preview (shows latest surfer message) */}
        {chatLatestMessage && (
          <button
            onClick={onOpenChat}
            className={`w-full flex items-start gap-3 p-3 rounded-xl border transition-all active:scale-[0.99] ${
              chatUnreadCount > 0
                ? 'bg-cyan-500/10 border-cyan-400/40 ring-1 ring-cyan-400/30'
                : 'bg-zinc-800/50 border-zinc-700/50'
            }`}
            data-testid="inline-message-preview"
          >
            <div className="relative flex-shrink-0">
              <MessageCircle className={`w-5 h-5 mt-0.5 ${
                chatUnreadCount > 0 ? 'text-cyan-400' : 'text-zinc-500'
              }`} />
              {chatUnreadCount > 0 && (
                <span className="absolute -top-1.5 -right-1.5 w-4 h-4 rounded-full bg-red-500 text-[9px] font-bold text-white flex items-center justify-center animate-bounce">
                  {chatUnreadCount > 9 ? '9+' : chatUnreadCount}
                </span>
              )}
            </div>
            <div className="flex-1 min-w-0 text-left">
              <div className="flex items-center justify-between gap-2">
                <p className={`text-xs font-semibold ${
                  chatUnreadCount > 0 ? 'text-cyan-400' : 'text-zinc-400'
                }`}>
                  {session.requester_name || 'Surfer'}
                </p>
                <span className="text-[10px] text-zinc-500 flex-shrink-0">
                  {new Date(chatLatestMessage.created_at).toLocaleTimeString([], {
                    hour: '2-digit', minute: '2-digit'
                  })}
                </span>
              </div>
              <p className={`text-sm truncate ${
                chatUnreadCount > 0 ? 'text-white font-medium' : 'text-zinc-400'
              }`}>
                {chatLatestMessage.message_type === 'voice_note'
                  ? '🎤 Voice note'
                  : (chatLatestMessage.content || '📎 Media')}
              </p>
            </div>
          </button>
        )}

        {/* Action Buttons */}
        <div className="space-y-3">
          {/* Communication Buttons */}
          <div className="grid grid-cols-2 gap-3">
            <button
              onClick={onOpenChat}
              className="relative flex items-center justify-center gap-2 py-3 rounded-xl font-semibold text-sm transition-all active:scale-[0.97] bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white"
              data-testid="photographer-chat-btn"
            >
              <MessageCircle className="w-4 h-4" />
              Chat Surfer
              {chatUnreadCount > 0 && (
                <span className="absolute -top-2 -right-2 w-5 h-5 rounded-full bg-red-500 text-[10px] font-bold text-white flex items-center justify-center animate-bounce shadow-lg">
                  {chatUnreadCount > 9 ? '9+' : chatUnreadCount}
                </span>
              )}
            </button>
            <button
              onClick={onOpenChat}
              className="flex items-center justify-center gap-2 py-3 rounded-xl font-semibold text-sm transition-all active:scale-[0.97] bg-zinc-800 hover:bg-zinc-700 text-white border border-zinc-700"
              data-testid="photographer-voice-btn"
            >
              <Mic className="w-4 h-4" />
              Voice Note
            </button>
          </div>

          {isEnRoute && (
            <Button
              onClick={() => onMarkArrived(session.id)}
              className="w-full py-5 bg-gradient-to-r from-green-400 to-cyan-400 hover:from-green-500 hover:to-cyan-500 text-black font-bold"
              data-testid="mark-arrived-btn"
            >
              <Check className="w-5 h-5 mr-2" />
              I've Arrived - Start Session
            </Button>
          )}
          
          {isArrived && (
            <Button
              onClick={() => onComplete(session.id)}
              className="w-full py-5 bg-gradient-to-r from-amber-400 to-orange-500 hover:from-amber-500 hover:to-orange-600 text-black font-bold"
              data-testid="complete-session-btn"
            >
              <Square className="w-5 h-5 mr-2" />
              Complete Session
            </Button>
          )}
          
          <Button
            onClick={() => onCancel(session.id)}
            variant="outline"
            className="w-full border-zinc-600 hover:bg-zinc-800"
            data-testid="cancel-session-btn"
          >
            Cancel Session
          </Button>
        </div>
      </CardContent>
    </Card>
  );
};

// ============ EARNINGS STATS CARD ============
const EarningsStatsCard = ({ stats, cardBg, textPrimary, textSecondary, _sectionBg, borderClass }) => {
  const hasStreak = (stats.streak || 0) >= 3;
  
  return (
    <Card className={cardBg} data-testid="earnings-stats-card">
      <CardContent className="p-4">
        <div className="flex items-center justify-between mb-4">
          <h3 className={`font-bold text-lg ${textPrimary} flex items-center gap-2`}>
            <Wallet className="w-5 h-5 text-green-400" />
            Today's Earnings
          </h3>
          <Badge className="bg-green-500/20 text-green-400 border-green-500/30">
            {stats.sessions_today || 0} sessions
          </Badge>
        </div>
        
        <div className="text-center py-6">
          <p className="text-5xl font-bold text-green-400">${(stats.earnings_today || 0).toFixed(2)}</p>
          <p className={`text-sm ${textSecondary} mt-2`}>Net earnings after fees</p>
        </div>
        
        <div className={`grid grid-cols-3 gap-3 pt-4 border-t ${borderClass}`}>
          <div className="text-center">
            <p className={`text-xl font-bold ${textPrimary}`}>{stats.sessions_week || 0}</p>
            <p className={`text-xs ${textSecondary}`}>This Week</p>
          </div>
          <div className="text-center">
            <p className="text-xl font-bold text-amber-400">{stats.streak || 0}</p>
            <p className={`text-xs ${textSecondary}`}>Day Streak</p>
          </div>
          <div className="text-center">
            <p className="text-xl font-bold text-purple-400">{stats.total_sessions || 0}</p>
            <p className={`text-xs ${textSecondary}`}>All Time</p>
          </div>
        </div>
        
        {/* Streak Bonus Indicator */}
        {hasStreak && (
          <div className={`mt-4 p-4 rounded-xl bg-gradient-to-r from-amber-500/10 to-orange-500/10 border border-amber-400/30`}>
            <div className="flex items-center gap-3">
              <Flame className="w-6 h-6 text-amber-400" />
              <div>
                <p className="text-amber-400 font-bold">Hot Streak Active!</p>
                <p className={`text-sm ${textSecondary}`}>2x XP on all sessions</p>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

// ============ MAIN COMPONENT ============
export const OnDemandSessionManager = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const location = useLocation();
  
  // Check for deep link to specific request
  const highlightDispatchId = location.state?.highlightDispatchId;
  const autoExpandRequest = location.state?.autoExpandRequest;
  
  // Status state
  const [isOnline, setIsOnline] = useState(false);
  const [isTogglingStatus, setIsTogglingStatus] = useState(false);
  const [selectedOnDemandSpot, setSelectedOnDemandSpot] = useState(null);
  const [isLiveShooting, setIsLiveShooting] = useState(false);
  
  // Session state
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [activeSession, setActiveSession] = useState(null);
  const [isAccepting, setIsAccepting] = useState(false);
  const [expandedRequestId, setExpandedRequestId] = useState(null);  // For auto-expanding specific request
  
  // Settings state
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [baseRate, setBaseRate] = useState(75);
  const [peakPricingEnabled, setPeakPricingEnabled] = useState(false);
  const [peakMultiplier, setPeakMultiplier] = useState(1.5);
  const [onDemandPhotosIncluded, setOnDemandPhotosIncluded] = useState(3);
  const [onDemandFullGallery, setOnDemandFullGallery] = useState(false);

  // On-Demand independent resolution pricing
  const [odPriceWeb, setOdPriceWeb] = useState(5);
  const [odPriceStandard, setOdPriceStandard] = useState(10);
  const [odPriceHigh, setOdPriceHigh] = useState(18);
  const [odVideo720p, setOdVideo720p] = useState(12);
  const [odVideo1080p, setOdVideo1080p] = useState(20);
  const [odVideo4k, setOdVideo4k] = useState(40);

  // Cancellation fee state
  const [cancellationFeePct, setCancellationFeePct] = useState(100);

  // Exception requests state
  const [exceptionRequests, setExceptionRequests] = useState([]);
  const [resolvingExceptionId, setResolvingExceptionId] = useState(null);
  
  // Coverage spots state
  const [nearbySpots, setNearbySpots] = useState([]);
  const [selectedSpots, setSelectedSpots] = useState([]);
  const [userLocation, setUserLocation] = useState(null);
  const [locationLoading, setLocationLoading] = useState(false);
  const [showSpotsList, setShowSpotsList] = useState(true);
  const [showPricingSection, setShowPricingSection] = useState(true);
  
  // Stats and history
  const [stats, setStats] = useState({});
  const [sessionHistory, setSessionHistory] = useState([]);
  const [showHistoryDrawer, setShowHistoryDrawer] = useState(false);
  const [selectedHistorySession, setSelectedHistorySession] = useState(null);
  
  // UI state
  const [activeTab, setActiveTab] = useState('dashboard');
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [showCancelConfirm, setShowCancelConfirm] = useState(false);
  const [cancelTargetId, setCancelTargetId] = useState(null);
  const [isCancelling, setIsCancelling] = useState(false);

  // Session chat state
  const [showSessionChat, setShowSessionChat] = useState(false);
  const [chatUnreadCount, setChatUnreadCount] = useState(0);

  // Background chat sync (runs even when drawer is closed)
  const {
    unreadCount: bgUnreadCount,
    latestMessage: bgLatestMessage,
  } = useSessionChatSync({
    userId: user?.id,
    otherUserId: activeSession?.requester_id,
    otherUserName: activeSession?.requester_name || 'Surfer',
    drawerOpen: showSessionChat,
    enabled: !!activeSession,
  });

  // Sync background unread count to state (when drawer is closed, background hook is authoritative)
  useEffect(() => {
    if (!showSessionChat) {
      setChatUnreadCount(bgUnreadCount);
    }
  }, [bgUnreadCount, showSessionChat]);
  
  const pollIntervalRef = useRef(null);
  const audioRef = useRef(null);
  const highlightedRequestRef = useRef(null);
  
  // Auto-expand and scroll to highlighted request when it loads
  useEffect(() => {
    if (highlightDispatchId && autoExpandRequest && incomingRequests.length > 0) {
      const targetRequest = incomingRequests.find(r => r.dispatch_id === highlightDispatchId);
      if (targetRequest) {
        setExpandedRequestId(highlightDispatchId);
        // Scroll to the request after a short delay
        setTimeout(() => {
          highlightedRequestRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 300);
      }
    }
  }, [highlightDispatchId, autoExpandRequest, incomingRequests]);
  
  // ============ THEME CLASSES ============
  const isLight = theme === 'light';
  const isBeach = theme === 'beach';
  const cardBg = isLight ? 'bg-white border-gray-200' : isBeach ? 'bg-zinc-950 border-zinc-800' : 'bg-zinc-900 border-zinc-800';
  const borderClass = isLight ? 'border-gray-200' : 'border-zinc-800';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-500' : 'text-gray-400';
  const sectionBg = isLight ? 'bg-gray-50' : isBeach ? 'bg-zinc-900' : 'bg-zinc-800/50';
  
  // Geographic Range Logic (Role-Based)
  const getGeographicRadius = () => {
    if (user?.role === ROLES.APPROVED_PRO) return { min: 30, max: 50, default: 40 };
    if (user?.role === ROLES.PRO) return { min: 30, max: 50, default: 40 };
    return { min: 10, max: 20, default: 15 };
  };
  const geoRadius = getGeographicRadius();
  const isPro = ['Approved Pro', 'Pro'].includes(user?.role);
  
  // ============ FETCH FUNCTIONS ============
  useEffect(() => {
    if (!user?.id) return;
    
    fetchOnDemandStatus();
    fetchSettings();
    fetchStats();
    fetchSessionHistory();
    fetchExceptionRequests();
    requestLocation();
  }, [user?.id]);
  
  // Polling for incoming requests when online
  useEffect(() => {
    if (!isOnline || !user?.id) {
      if (pollIntervalRef.current) {
        clearInterval(pollIntervalRef.current);
        pollIntervalRef.current = null;
      }
      return;
    }
    
    fetchIncomingRequests();
    fetchActiveSession();
    
    pollIntervalRef.current = setInterval(() => {
      // Skip polling when browser tab is hidden (saves battery & bandwidth)
      if (document.visibilityState === 'hidden') return;
      fetchIncomingRequests();
      fetchActiveSession();
    }, 10000);
    
    return () => {
      if (pollIntervalRef.current) {
        clearInterval(pollIntervalRef.current);
      }
    };
  }, [isOnline, user?.id]);
  
  // Play sound when new request arrives
  useEffect(() => {
    if (incomingRequests.length > 0 && soundEnabled) {
      playNotificationSound();
    }
  }, [incomingRequests.length]);
  
  const playNotificationSound = () => {
    try {
      if (!audioRef.current) {
        audioRef.current = new Audio('/sounds/notification.mp3');
        audioRef.current.volume = 0.7;
      }
      audioRef.current.currentTime = 0;
      audioRef.current.play().catch(() => {});
    } catch (e) {
      logger.debug('Could not play notification sound');
    }
  };
  
  const requestLocation = () => {
    setLocationLoading(true);
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const location = {
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          };
          setUserLocation(location);
          fetchNearbySpots(location);
          setLocationLoading(false);
        },
        (error) => {
          logger.error('Geolocation error:', error);
          setLocationLoading(false);
          toast.error('Unable to get location. Please enable GPS.');
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    } else {
      setLocationLoading(false);
      toast.error('Geolocation not supported by your browser');
    }
  };
  
  const fetchNearbySpots = async (location) => {
    try {
      const response = await apiClient.get(`/surf-spots/nearby`, {
        params: {
          latitude: location.latitude,
          longitude: location.longitude,
          radius_miles: geoRadius.default
        }
      });
      setNearbySpots(response.data || []);
    } catch (error) {
      logger.error('Failed to fetch nearby spots:', error);
      try {
        const fallbackResponse = await apiClient.get(`/surf-spots?limit=30`);
        setNearbySpots(fallbackResponse.data || []);
      } catch (e) {
        logger.error('Fallback also failed:', e);
      }
    }
  };
  
  const fetchOnDemandStatus = async () => {
    try {
      const response = await apiClient.get(`/photographer/${user.id}/on-demand-status`);
      setIsOnline(response.data.is_available || false);
      if (response.data.active_spot) {
        setSelectedOnDemandSpot(response.data.active_spot);
      }
      setIsLiveShooting(response.data.is_live_shooting || false);
    } catch (error) {
      logger.error('Failed to fetch on-demand status:', error);
    }
  };
  
  const fetchSettings = async () => {
    try {
      const response = await apiClient.get(`/photographer/${user.id}/on-demand-settings`);
      if (response.data) {
        setBaseRate(response.data.base_rate || 75);
        setPeakPricingEnabled(response.data.peak_pricing_enabled || false);
        setPeakMultiplier(response.data.peak_multiplier || 1.5);
        setOnDemandPhotosIncluded(response.data.on_demand_photos_included || 3);
        setOnDemandFullGallery(response.data.on_demand_full_gallery || false);
        setSelectedSpots(response.data.claimed_spots || []);
        // Resolution pricing
        setOdPriceWeb(response.data.on_demand_price_web || 5);
        setOdPriceStandard(response.data.on_demand_price_standard || 10);
        setOdPriceHigh(response.data.on_demand_price_high || 18);
        setOdVideo720p(response.data.on_demand_video_720p || 12);
        setOdVideo1080p(response.data.on_demand_video_1080p || 20);
        setOdVideo4k(response.data.on_demand_video_4k || 40);
        // Cancellation fee
        setCancellationFeePct(response.data.on_demand_cancellation_fee_pct ?? 100);
      }
      setLoading(false);
    } catch (error) {
      logger.error('Failed to fetch settings:', error);
      setLoading(false);
    }
  };
  
  const fetchStats = async () => {
    try {
      const response = await apiClient.get(`/dispatch/photographer/${user.id}/stats`);
      setStats(response.data);
    } catch (error) {
      logger.error('Failed to fetch stats:', error);
      setStats({
        earnings_today: 0,
        sessions_today: 0,
        sessions_week: 0,
        streak: 0,
        total_sessions: 0
      });
    }
  };
  
  const fetchIncomingRequests = async () => {
    if (activeSession) return;
    
    try {
      const response = await apiClient.get(`/dispatch/photographer/${user.id}/pending`);
      const pending = response.data.pending_dispatches || [];
      
      // The pending endpoint already returns all needed data including crew with selfies
      // No need to fetch additional details
      setIncomingRequests(pending);
    } catch (error) {
      logger.debug('No pending requests');
      setIncomingRequests([]);
    }
  };
  
  const fetchActiveSession = async () => {
    try {
      const response = await apiClient.get(`/dispatch/user/${user.id}/active`);
      const active = response.data.active_dispatch;
      
      if (active && active.role === 'photographer') {
        // Use the selfie from active dispatch response (includes crew selfies too)
        const requesterSelfie = active.requester_selfie;
        
        // Also fetch full details for additional info
        const detailResponse = await apiClient.get(`/dispatch/${active.id}`);
        
        setActiveSession({
          id: active.id,
          status: detailResponse.data.status,
          requester_id: active.requester_id || detailResponse.data.requester?.id,
          requester_name: active.requester_name || detailResponse.data.requester?.name,
          requester_avatar: active.requester_avatar || detailResponse.data.requester?.avatar,
          requester_username: active.requester_username || detailResponse.data.requester?.username,
          requester_stance: active.requester_stance,
          requester_board_description: active.requester_board_description,
          requester_selfie: requesterSelfie || detailResponse.data.selfie_url,  // Prefer active dispatch selfie
          location_name: active.location_name || detailResponse.data.location?.name,
          estimated_duration: detailResponse.data.pricing?.estimated_duration,
          hourly_rate: detailResponse.data.pricing?.hourly_rate,
          eta_minutes: active.eta_minutes || detailResponse.data.gps?.eta_minutes,
          arrived_at: detailResponse.data.timestamps?.arrived,
          is_shared: active.is_shared,
          crew: active.crew  // Include crew with their selfies
        });
      } else {
        setActiveSession(null);
      }
    } catch (error) {
      setActiveSession(null);
    }
  };
  
  const fetchSessionHistory = async () => {
    try {
      const response = await apiClient.get(`/dispatch/photographer/${user.id}/history?limit=20`);
      setSessionHistory(response.data.history || []);
    } catch (error) {
      logger.error('Failed to fetch history:', error);
      setSessionHistory([]);
    }
  };

  const fetchExceptionRequests = async () => {
    try {
      const response = await apiClient.get(`/dispatch/photographer/${user.id}/exception-requests?status_filter=pending`);
      setExceptionRequests(response.data.exception_requests || []);
    } catch (error) {
      logger.error('Failed to fetch exception requests:', error);
    }
  };
  
  // ============ HANDLERS ============
  const handleToggleOnline = async () => {
    setIsTogglingStatus(true);
    try {
      // Check if live shooting is active
      if (isLiveShooting && !isOnline) {
        toast.error('Cannot go on-demand while Live Shooting is active. Please end your live session first.');
        setIsTogglingStatus(false);
        return;
      }
      
      // Get location
      let lat = userLocation?.latitude;
      let lng = userLocation?.longitude;
      
      if (!lat || !lng) {
        try {
          const position = await new Promise((resolve, reject) => {
            navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 10000 });
          });
          lat = position.coords.latitude;
          lng = position.coords.longitude;
        } catch {
          toast.error('Location required. Please enable location services.');
          setIsTogglingStatus(false);
          return;
        }
      }
      
      // Find the first selected spot to use
      const spotToUse = nearbySpots.find(s => selectedSpots.includes(s.id));
      
      const response = await apiClient.post(
        `/photographer/${user.id}/on-demand-toggle`,
        { 
          is_available: !isOnline,
          latitude: spotToUse?.latitude || lat, 
          longitude: spotToUse?.longitude || lng,
          spot_id: spotToUse?.id,
          spot_name: spotToUse?.name
        }
      );
      
      const newStatus = response.data.is_available;
      setIsOnline(newStatus);
      
      if (newStatus) {
        setSelectedOnDemandSpot(spotToUse);
        toast.success(`On-Demand activated${spotToUse ? ` at ${spotToUse.name}` : ''}!`);
      } else {
        setSelectedOnDemandSpot(null);
        toast.info("You're now offline");
        setIncomingRequests([]);
      }
    } catch (error) {
      const detail = error.response?.data?.detail;
      if (detail?.includes('live')) {
        toast.error('Cannot go on-demand while Live Shooting is active. Please end your live session first.');
      } else {
        toast.error(detail || 'Failed to update status');
      }
    } finally {
      setIsTogglingStatus(false);
    }
  };
  
  const handleAcceptRequest = async (dispatchId) => {
    setIsAccepting(true);
    try {
      await apiClient.post(`/dispatch/${dispatchId}/accept`, {
        photographer_id: user.id
      });
      
      toast.success('Request accepted! Head to the location.');
      setIncomingRequests([]);
      fetchActiveSession();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to accept request');
    } finally {
      setIsAccepting(false);
    }
  };
  
  const handleDeclineRequest = useCallback(async (dispatchId, isTimeout = false) => {
    try {
      // Call backend to decline
      await apiClient.post(`/dispatch/${dispatchId}/decline?photographer_id=${user.id}`);
      
      // Remove from local state
      setIncomingRequests(prev => prev.filter(r => r.dispatch_id !== dispatchId));
      
      if (!isTimeout) {
        toast.info('Request declined');
      }
    } catch (error) {
      logger.error('Failed to decline request:', error);
      toast.error(error.response?.data?.detail || 'Failed to decline request');
      // Still remove from local state even if API fails
      setIncomingRequests(prev => prev.filter(r => r.dispatch_id !== dispatchId));
    }
  }, [user?.id]);
  
  const handleMarkArrived = async (dispatchId) => {
    try {
      await apiClient.post(`/dispatch/${dispatchId}/arrived?photographer_id=${user.id}`);
      toast.success('Session started! Have fun shooting!');
      fetchActiveSession();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to mark arrival');
    }
  };
  
  const handleCompleteSession = async (dispatchId) => {
    try {
      await apiClient.post(`/dispatch/${dispatchId}/complete?photographer_id=${user.id}`);
      toast.success('Session completed! Gallery created.');
      setActiveSession(null);
      fetchStats();
      fetchSessionHistory();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to complete session');
    }
  };
  
  // Opens the in-app cancel confirmation modal
  const promptCancelSession = (dispatchId) => {
    setCancelTargetId(dispatchId);
    setShowCancelConfirm(true);
  };

  // Executes the cancel after the user confirms via the modal
  const handleConfirmCancel = async () => {
    if (!cancelTargetId) return;
    setIsCancelling(true);
    try {
      await apiClient.post(`/dispatch/${cancelTargetId}/cancel`, {
        reason: 'Photographer cancelled'
      });
      toast.info('Session cancelled');
      setActiveSession(null);
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to cancel session');
    } finally {
      setIsCancelling(false);
      setShowCancelConfirm(false);
      setCancelTargetId(null);
    }
  };
  
  const toggleSpotSelection = (spotId) => {
    setSelectedSpots(prev => 
      prev.includes(spotId) 
        ? prev.filter(id => id !== spotId)
        : [...prev, spotId]
    );
  };
  
  const selectAllSpots = () => {
    setSelectedSpots(nearbySpots.map(s => s.id));
  };
  
  const clearAllSpots = () => {
    setSelectedSpots([]);
  };
  
  const saveSettings = async () => {
    setSaving(true);
    try {
      await apiClient.post(`/photographer/${user.id}/on-demand-settings`, {
        base_rate: baseRate,
        peak_pricing_enabled: peakPricingEnabled,
        peak_multiplier: peakMultiplier,
        claimed_spots: selectedSpots,
        latitude: userLocation?.latitude,
        longitude: userLocation?.longitude,
        on_demand_photos_included: onDemandPhotosIncluded,
        on_demand_full_gallery: onDemandFullGallery,
        on_demand_price_web: odPriceWeb,
        on_demand_price_standard: odPriceStandard,
        on_demand_price_high: odPriceHigh,
        on_demand_video_720p: odVideo720p,
        on_demand_video_1080p: odVideo1080p,
        on_demand_video_4k: odVideo4k,
        on_demand_cancellation_fee_pct: cancellationFeePct,
      });
      
      toast.success('On-Demand settings saved!');
    } catch (error) {
      logger.error('Failed to save settings:', error);
      toast.error('Failed to save settings');
    } finally {
      setSaving(false);
    }
  };
  
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-yellow-400" />
      </div>
    );
  }
  
  return (
    <div className="p-4 max-w-6xl mx-auto pb-24" data-testid="on-demand-session-manager">
      {/* Header with Save Button (Settings tab only) */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className={`text-2xl font-bold ${textPrimary} flex items-center gap-2`}>
            <Zap className="w-7 h-7 text-yellow-400" />
            On-Demand Hub
          </h1>
          <p className={`${textSecondary} text-sm mt-1`}>
            {selectedSpots.length} coverage spots • {geoRadius.min}-{geoRadius.max} mile range
          </p>
        </div>
        
        <div className="flex items-center gap-3">
          <button
            onClick={() => setSoundEnabled(!soundEnabled)}
            className={`p-2 rounded-xl ${sectionBg} hover:opacity-80 transition-opacity`}
            data-testid="sound-toggle-btn"
          >
            {soundEnabled ? (
              <Volume2 className="w-5 h-5 text-cyan-400" />
            ) : (
              <VolumeX className={`w-5 h-5 ${textSecondary}`} />
            )}
          </button>
          
          {activeTab === 'settings' && (
            <Button
              onClick={saveSettings}
              disabled={saving}
              className="bg-gradient-to-r from-green-400 to-cyan-400 text-black font-bold"
              data-testid="save-settings-btn"
            >
              {saving ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Check className="w-4 h-4 mr-2" />}
              {saving ? 'Saving...' : 'Save Settings'}
            </Button>
          )}
        </div>
      </div>
      
      {/* On-Demand Status Toggle Card - Shown on Dashboard */}
      {activeTab === 'dashboard' && (
        <Card className={`mb-6 ${isOnline 
          ? 'bg-gradient-to-r from-yellow-500/20 to-orange-500/20 border-yellow-400/50' 
          : cardBg}`}
          data-testid="on-demand-status-card"
        >
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${
                  isOnline ? 'bg-yellow-500/30' : sectionBg
                }`}>
                  <Zap className={`w-6 h-6 ${isOnline ? 'text-yellow-400' : textSecondary}`} />
                </div>
                <div>
                  <p className={`font-bold ${textPrimary}`}>On-Demand Status</p>
                  <p className={`text-sm ${isOnline ? 'text-yellow-300' : textSecondary}`}>
                    {isOnline 
                      ? `Active at: ${selectedOnDemandSpot?.name || 'Your Area'}` 
                      : selectedSpots.length > 0 
                        ? 'Ready to activate' 
                        : 'Select coverage spots in Settings'}
                  </p>
                </div>
              </div>
              <button
                onClick={handleToggleOnline}
                disabled={isTogglingStatus || (selectedSpots.length === 0 && !isOnline)}
                className={`w-14 h-8 rounded-full transition-colors relative ${
                  isOnline 
                    ? 'bg-yellow-500' 
                    : selectedSpots.length > 0 
                      ? isLight ? 'bg-gray-300 hover:bg-gray-400' : 'bg-zinc-600 hover:bg-zinc-500' 
                      : isLight ? 'bg-gray-200 opacity-50 cursor-not-allowed' : 'bg-zinc-700 opacity-50 cursor-not-allowed'
                }`}
                data-testid="on-demand-status-toggle"
              >
                {isTogglingStatus ? (
                  <Loader2 className="w-5 h-5 animate-spin absolute top-1.5 left-1/2 -translate-x-1/2 text-white" />
                ) : (
                  <span className={`absolute top-1 w-6 h-6 rounded-full bg-white transition-transform shadow-md ${
                    isOnline ? 'right-1' : 'left-1'
                  }`} />
                )}
              </button>
            </div>
            
            {/* Active spot info */}
            {isOnline && selectedOnDemandSpot && (
              <div className="mt-3 pt-3 border-t border-yellow-500/30 flex items-center gap-2">
                <MapPin className="w-4 h-4 text-green-400" />
                <span className="text-sm text-green-300">
                  Accepting requests at {selectedOnDemandSpot.name}
                </span>
              </div>
            )}
          </CardContent>
        </Card>
      )}
      
      {/* Tab Navigation */}
      <div className={`flex rounded-xl ${sectionBg} p-1 mb-6`}>
        {[
          { id: 'dashboard', label: 'Dashboard', icon: Radio },
          { id: 'settings', label: 'Settings', icon: Settings },
          { id: 'history', label: 'History', icon: History }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex-1 py-3 px-4 rounded-lg flex items-center justify-center gap-2 text-sm font-medium transition-all ${
              activeTab === tab.id 
                ? `${cardBg} ${textPrimary} shadow-sm` 
                : `${textSecondary} hover:text-white`
            }`}
            data-testid={`tab-${tab.id}`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>
      
      {/* Main Content */}
      <div className="space-y-6">
        {activeTab === 'dashboard' && (
          <>
            {/* Active Session (top priority) */}
            {activeSession && (
              <ActiveSessionCard
                session={activeSession}
                onMarkArrived={handleMarkArrived}
                onComplete={handleCompleteSession}
                onCancel={promptCancelSession}
                onOpenChat={() => setShowSessionChat(true)}
                cardBg={cardBg}
                textPrimary={textPrimary}
                textSecondary={textSecondary}
                sectionBg={sectionBg}
                chatUnreadCount={chatUnreadCount}
                chatLatestMessage={bgLatestMessage}
              />
            )}
            
            {/* Incoming Requests */}
            {!activeSession && incomingRequests.length > 0 && (
              <div className="space-y-4">
                <div className="flex items-center gap-2">
                  <Bell className="w-5 h-5 text-amber-400 animate-bounce" />
                  <h2 className={`font-bold text-lg ${textPrimary}`}>Incoming Requests</h2>
                  <Badge className="bg-amber-500 text-black">{incomingRequests.length}</Badge>
                </div>
                
                {incomingRequests.map((request) => (
                  <div
                    key={request.dispatch_id}
                    ref={request.dispatch_id === highlightDispatchId ? highlightedRequestRef : null}
                  >
                    <IncomingRequestCard
                      request={request}
                      onAccept={handleAcceptRequest}
                      onDecline={handleDeclineRequest}
                      isAccepting={isAccepting}
                      cardBg={cardBg}
                      textPrimary={textPrimary}
                      textSecondary={textSecondary}
                      sectionBg={sectionBg}
                      isHighlighted={request.dispatch_id === highlightDispatchId}
                      defaultExpanded={request.dispatch_id === expandedRequestId}
                    />
                  </div>
                ))}
              </div>
            )}
            
            {/* Waiting State */}
            {isOnline && !activeSession && incomingRequests.length === 0 && (
              <Card className={`${cardBg} text-center`}>
                <CardContent className="py-12 px-6">
                  <div className="w-20 h-20 mx-auto mb-6 rounded-xl bg-green-500/20 flex items-center justify-center">
                    <Radio className="w-10 h-10 text-green-400 animate-pulse" />
                  </div>
                  <h3 className={`text-xl font-bold ${textPrimary} mb-2`}>Waiting for Requests</h3>
                  <p className={textSecondary}>
                    You'll be notified when a surfer nearby requests a session
                  </p>
                  <div className="mt-4 flex items-center justify-center gap-2 text-sm text-green-400">
                    <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse" />
                    Actively listening...
                  </div>
                </CardContent>
              </Card>
            )}
            
            {/* Offline State */}
            {!isOnline && !activeSession && (
              <Card className={cardBg}>
                <CardContent className="py-12 px-6 text-center">
                  <div className={`w-20 h-20 mx-auto mb-6 rounded-xl ${sectionBg} flex items-center justify-center`}>
                    <Power className={`w-10 h-10 ${textSecondary}`} />
                  </div>
                  <h3 className={`text-xl font-bold ${textPrimary} mb-2`}>You're Offline</h3>
                  <p className={textSecondary}>
                    {selectedSpots.length === 0 
                      ? 'Configure coverage spots in Settings tab first'
                      : 'Toggle the switch above to start receiving requests'}
                  </p>
                </CardContent>
              </Card>
            )}
            
            {/* Earnings Stats */}
            <EarningsStatsCard
              stats={stats}
              cardBg={cardBg}
              textPrimary={textPrimary}
              textSecondary={textSecondary}
              sectionBg={sectionBg}
              borderClass={borderClass}
            />

            {/* ============ EXCEPTION REQUESTS FEED ============ */}
            {exceptionRequests.length > 0 && (
              <Card className={cardBg}>
                <CardHeader>
                  <CardTitle className={`text-lg ${textPrimary} flex items-center gap-2`}>
                    <Bell className="w-5 h-5 text-amber-400" />
                    Fee Waiver Requests
                    <Badge className="bg-amber-500 text-white text-xs">{exceptionRequests.length}</Badge>
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  {exceptionRequests.map(exc => (
                    <div key={exc.id} className={`p-4 rounded-xl border ${isLight ? 'bg-amber-50 border-amber-200' : 'bg-amber-500/10 border-amber-500/30'}`}>
                      <div className="flex items-start justify-between mb-2">
                        <div>
                          <p className={`font-semibold ${textPrimary}`}>{exc.requester_name}</p>
                          <p className={`text-xs ${textSecondary}`}>
                            {exc.category === 'emergency' ? '🚨 Emergency' : exc.category === 'weather' ? '🌧️ Weather' : exc.category === 'injury' ? '🩹 Injury' : '📋 Other'}
                          </p>
                        </div>
                        <p className="text-amber-400 font-bold">${exc.fee_amount?.toFixed(2)}</p>
                      </div>
                      <p className={`text-sm ${textSecondary} mb-3 italic`}>"{exc.reason}"</p>
                      {resolvingExceptionId === exc.id ? (
                        <div className="flex items-center justify-center py-2">
                          <Loader2 className="w-5 h-5 animate-spin text-amber-400" />
                        </div>
                      ) : (
                        <div className="flex gap-2">
                          <Button
                            size="sm"
                            className="flex-1 bg-green-500 hover:bg-green-600 text-white text-xs"
                            onClick={async () => {
                              setResolvingExceptionId(exc.id);
                              try {
                                await apiClient.post(`/dispatch/${exc.dispatch_id}/resolve-exception`, {
                                  approved: true,
                                  resolution_note: 'Approved by photographer'
                                });
                                toast.success('Waiver approved — surfer refunded');
                                setExceptionRequests(prev => prev.filter(e => e.id !== exc.id));
                              } catch (err) {
                                toast.error('Failed to approve waiver');
                              } finally {
                                setResolvingExceptionId(null);
                              }
                            }}
                          >
                            <Check className="w-3 h-3 mr-1" /> Approve
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            className={`flex-1 text-xs ${isLight ? 'border-red-300 text-red-600' : 'border-red-500/50 text-red-400'}`}
                            onClick={async () => {
                              setResolvingExceptionId(exc.id);
                              try {
                                await apiClient.post(`/dispatch/${exc.dispatch_id}/resolve-exception`, {
                                  approved: false,
                                  resolution_note: 'Denied by photographer'
                                });
                                toast.info('Waiver denied');
                                setExceptionRequests(prev => prev.filter(e => e.id !== exc.id));
                              } catch (err) {
                                toast.error('Failed to deny waiver');
                              } finally {
                                setResolvingExceptionId(null);
                              }
                            }}
                          >
                            <X className="w-3 h-3 mr-1" /> Deny
                          </Button>
                        </div>
                      )}
                    </div>
                  ))}
                </CardContent>
              </Card>
            )}
          </>
        )}
        
        {activeTab === 'settings' && (
          <>
            {/* On-Demand Pricing Card */}
            <Card className={cardBg}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className={`text-lg ${textPrimary} flex items-center gap-2`}>
                    <DollarSign className="w-5 h-5 text-green-400" />
                    On-Demand Pricing
                  </CardTitle>
                  <Button 
                    variant="outline" 
                    size="sm"
                    onClick={() => setShowPricingSection(!showPricingSection)}
                    className={borderClass}
                  >
                    <Settings className="w-4 h-4 mr-2" />
                    {showPricingSection ? 'Hide' : 'Show'}
                  </Button>
                </div>
              </CardHeader>
              {showPricingSection && (
                <CardContent className="space-y-6">
                  {/* Preview Grid */}
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div className={`p-3 rounded-xl ${sectionBg}`}>
                      <p className={`text-xs ${textSecondary} mb-1`}>Base Rate</p>
                      <p className="text-xl font-bold text-green-400">${baseRate}/hr</p>
                    </div>
                    <div className={`p-3 rounded-xl ${sectionBg}`}>
                      <p className={`text-xs ${textSecondary} mb-1`}>Peak Rate</p>
                      <p className="text-xl font-bold text-amber-400">
                        {peakPricingEnabled ? `$${(baseRate * peakMultiplier).toFixed(0)}/hr` : 'OFF'}
                      </p>
                    </div>
                    <div className={`p-3 rounded-xl ${sectionBg}`}>
                      <p className={`text-xs ${textSecondary} mb-1`}>Photos Included</p>
                      <p className={`text-xl font-bold ${onDemandFullGallery ? 'text-green-400' : textPrimary}`}>
                        {onDemandFullGallery ? '∞ Full' : onDemandPhotosIncluded}
                      </p>
                    </div>
                    <div className={`p-3 rounded-xl ${sectionBg}`}>
                      <p className={`text-xs ${textSecondary} mb-1`}>Coverage</p>
                      <p className="text-xl font-bold text-cyan-400">{selectedSpots.length} spots</p>
                    </div>
                  </div>
                  
                  {/* Base Rate - NUMERIC STEPPER */}
                  <NumericStepper
                    label="On-Demand Base Rate"
                    value={baseRate}
                    onChange={setBaseRate}
                    min={25}
                    max={300}
                    step={5}
                    prefix="$"
                    suffix="/hr"
                    description="Premium rate for On-Demand requests (above standard bookings)"
                    theme={theme}
                  />
                  
                  {/* Peak/Swell Pricing Toggle */}
                  <div className={`p-4 rounded-xl ${isLight ? 'bg-amber-50 border-amber-200' : 'bg-amber-500/10 border-amber-500/30'} border`}>
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-3">
                        <Waves className="w-5 h-5 text-amber-400" />
                        <div>
                          <p className={`font-medium ${textPrimary}`}>Peak/Swell Pricing</p>
                          <p className={`text-xs ${textSecondary}`}>Auto-increase rate during high demand</p>
                        </div>
                      </div>
                      <Switch
                        checked={peakPricingEnabled}
                        onCheckedChange={setPeakPricingEnabled}
                      />
                    </div>
                    
                    {peakPricingEnabled && (
                      <div className="mt-4">
                        <div className="flex items-center justify-between mb-2">
                          <span className={`text-sm ${textPrimary}`}>Peak Multiplier</span>
                          <span className="text-lg font-bold text-amber-400">{peakMultiplier}x</span>
                        </div>
                        <div className="flex gap-2">
                          {[1.25, 1.5, 1.75, 2.0].map(mult => (
                            <button
                              key={mult}
                              onClick={() => setPeakMultiplier(mult)}
                              className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all ${
                                peakMultiplier === mult
                                  ? 'bg-amber-500 text-black'
                                  : isLight ? 'bg-gray-200 text-gray-700' : 'bg-zinc-700 text-gray-300'
                              }`}
                            >
                              {mult}x
                            </button>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                  
                  {/* Photos Included */}
                  <div>
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-2">
                        <label className={`font-medium ${textPrimary}`}>Photos Included</label>
                        {onDemandFullGallery && (
                          <Badge className="bg-green-500 text-white text-xs">FULL GALLERY</Badge>
                        )}
                      </div>
                    </div>
                    
                    {/* Full Gallery Toggle */}
                    <div className={`p-3 rounded-xl mb-4 ${isLight ? 'bg-green-50 border-green-200' : 'bg-green-500/10 border-green-500/30'} border`}>
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <Zap className="w-5 h-5 text-green-400" />
                          <div>
                            <p className={`font-medium ${textPrimary}`}>Full Gallery Access</p>
                            <p className={`text-xs ${textSecondary}`}>All photos included - unlimited downloads</p>
                          </div>
                        </div>
                        <Switch
                          checked={onDemandFullGallery}
                          onCheckedChange={setOnDemandFullGallery}
                        />
                      </div>
                    </div>
                    
                    {!onDemandFullGallery && (
                      <NumericStepper
                        value={onDemandPhotosIncluded}
                        onChange={setOnDemandPhotosIncluded}
                        min={0}
                        max={999}
                        step={1}
                        description="Photos included free with on-demand buy-in. Additional charged per resolution."
                        theme={theme}
                      />
                    )}

                    {/* Photo Download Prices */}
                    <div className={`mt-4 p-4 rounded-xl border ${isLight ? 'bg-blue-50 border-blue-200' : 'bg-blue-500/10 border-blue-500/20'}`}>
                      <p className={`text-sm font-semibold mb-3 flex items-center gap-2 ${textPrimary}`}>
                        📸 Photo Download Prices
                        <span className={`text-xs font-normal ${textSecondary}`}>(per resolution — independent from Gallery)</span>
                      </p>
                      <div className="grid grid-cols-1 gap-3">
                        <NumericStepper label="Web Quality (800px)" value={odPriceWeb} onChange={setOdPriceWeb} min={0} max={500} step={0.5} prefix="$" theme={theme} />
                        <NumericStepper label="Standard (1920px)" value={odPriceStandard} onChange={setOdPriceStandard} min={0} max={500} step={0.5} prefix="$" theme={theme} />
                        <NumericStepper label="High-Res (Original)" value={odPriceHigh} onChange={setOdPriceHigh} min={0} max={500} step={0.5} prefix="$" theme={theme} />
                      </div>
                    </div>

                    {/* Video Download Prices */}
                    <div className={`mt-4 p-4 rounded-xl border ${isLight ? 'bg-purple-50 border-purple-200' : 'bg-purple-500/10 border-purple-500/20'}`}>
                      <p className={`text-sm font-semibold mb-3 flex items-center gap-2 ${textPrimary}`}>
                        🎬 Video Download Prices
                        <span className={`text-xs font-normal ${textSecondary}`}>(per resolution — independent from Gallery)</span>
                      </p>
                      <div className="grid grid-cols-1 gap-3">
                        <NumericStepper label="720p HD" value={odVideo720p} onChange={setOdVideo720p} min={0} max={500} step={0.5} prefix="$" theme={theme} />
                        <NumericStepper label="1080p Full HD" value={odVideo1080p} onChange={setOdVideo1080p} min={0} max={500} step={0.5} prefix="$" theme={theme} />
                        <NumericStepper label="4K Ultra HD" value={odVideo4k} onChange={setOdVideo4k} min={0} max={500} step={0.5} prefix="$" theme={theme} />
                      </div>
                    </div>

                    {/* Cancellation Fee */}
                    <div className={`mt-4 p-4 rounded-xl border ${isLight ? 'bg-red-50 border-red-200' : 'bg-red-500/10 border-red-500/20'}`}>
                      <p className={`text-sm font-semibold mb-1 flex items-center gap-2 ${textPrimary}`}>
                        🛡️ Cancellation Fee
                      </p>
                      <p className={`text-xs ${textSecondary} mb-3`}>
                        Percentage of deposit kept when a surfer cancels after you accept. 0% = fully refundable.
                      </p>
                      <NumericStepper
                        label="Fee Percentage"
                        value={cancellationFeePct}
                        onChange={setCancellationFeePct}
                        min={0}
                        max={100}
                        step={5}
                        suffix="%"
                        theme={theme}
                      />
                      <div className={`mt-2 text-xs ${textSecondary} flex items-center gap-1`}>
                        <Info className="w-3 h-3" />
                        {cancellationFeePct === 0 ? 'Fully refundable — surfers get full deposit back' :
                         cancellationFeePct === 100 ? 'Non-refundable — you keep the entire deposit' :
                         `Surfer receives ${100 - cancellationFeePct}% refund on cancellation`}
                      </div>
                    </div>
                  </div>
                </CardContent>
              )}
            </Card>
            
            {/* Coverage Spots Card */}
            <Card className={cardBg}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className={`text-lg ${textPrimary} flex items-center gap-2`}>
                    <MapPin className="w-5 h-5 text-cyan-400" />
                    Coverage Spots
                    <Badge className={isPro ? 'bg-purple-500 text-white' : 'bg-cyan-500 text-white'}>
                      {geoRadius.min}-{geoRadius.max} mi
                    </Badge>
                  </CardTitle>
                  <Button 
                    variant="outline" 
                    size="sm"
                    onClick={() => setShowSpotsList(!showSpotsList)}
                    className={borderClass}
                  >
                    {showSpotsList ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                  </Button>
                </div>
              </CardHeader>
              
              {showSpotsList && (
                <CardContent>
                  {/* Location Status */}
                  <div className={`p-3 rounded-xl mb-4 ${sectionBg} flex items-center gap-3`}>
                    <div className={`w-8 h-8 rounded-lg ${userLocation ? 'bg-green-500/20' : 'bg-amber-500/20'} flex items-center justify-center`}>
                      <Navigation className={`w-4 h-4 ${userLocation ? 'text-green-400' : 'text-amber-400'}`} />
                    </div>
                    <div className="flex-1">
                      <p className={`text-sm font-medium ${textPrimary}`}>
                        {userLocation ? 'GPS Active' : 'Location unavailable'}
                      </p>
                    </div>
                    {!userLocation && !locationLoading && (
                      <Button onClick={requestLocation} size="sm" variant="outline">
                        Enable
                      </Button>
                    )}
                    {locationLoading && (
                      <Loader2 className="w-4 h-4 animate-spin text-cyan-400" />
                    )}
                  </div>
                  
                  {/* Quick Actions */}
                  <div className="flex gap-2 mb-4">
                    <Button variant="outline" size="sm" onClick={selectAllSpots} className={`flex-1 ${borderClass}`}>
                      Select All
                    </Button>
                    <Button variant="outline" size="sm" onClick={clearAllSpots} className={`flex-1 ${borderClass}`}>
                      Clear All
                    </Button>
                  </div>
                  
                  {/* Spots List */}
                  <div className="space-y-2 max-h-80 overflow-y-auto pr-1" style={{ WebkitOverflowScrolling: 'touch' }}>
                    {nearbySpots.length === 0 ? (
                      <p className={`text-center py-4 ${textSecondary}`}>
                        {locationLoading ? 'Finding nearby spots...' : 'No spots found nearby'}
                      </p>
                    ) : (
                      nearbySpots.map(spot => (
                        <button
                          key={spot.id}
                          onClick={() => toggleSpotSelection(spot.id)}
                          className={`w-full p-3 rounded-xl flex items-center gap-3 transition-all border-2 ${
                            selectedSpots.includes(spot.id)
                              ? 'bg-cyan-500/20 border-cyan-500'
                              : isLight ? 'bg-white border-gray-200 hover:border-gray-300' : 'bg-zinc-800/50 border-zinc-700 hover:border-zinc-600'
                          }`}
                          data-testid={`spot-${spot.id}`}
                        >
                          {/* Checkbox Style Circle */}
                          <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                            selectedSpots.includes(spot.id) 
                              ? 'border-cyan-500 bg-cyan-500' 
                              : isLight ? 'border-gray-400' : 'border-zinc-500'
                          }`}>
                            {selectedSpots.includes(spot.id) && (
                              <Check className="w-4 h-4 text-white" />
                            )}
                          </div>
                          
                          <div className="flex-1 text-left">
                            <p className={`font-medium ${textPrimary}`}>{spot.name}</p>
                            <p className={`text-xs ${textSecondary}`}>
                              {spot.region || spot.city || 'Florida'}
                              {spot.distance_miles && ` • ${spot.distance_miles.toFixed(1)} mi`}
                            </p>
                          </div>
                          
                          {spot.active_photographers_count > 0 && (
                            <Badge className="bg-green-500/20 text-green-400 text-xs">
                              {spot.active_photographers_count} active
                            </Badge>
                          )}
                        </button>
                      ))
                    )}
                  </div>
                  
                  <p className={`text-xs ${textSecondary} mt-3 flex items-start gap-1`}>
                    <Info className="w-3 h-3 mt-0.5 flex-shrink-0" />
                    Surfers searching at these spots will see you in On-Demand results
                  </p>
                </CardContent>
              )}
            </Card>
          </>
        )}
        
        {activeTab === 'history' && (
          <>
          <Card className={cardBg} data-testid="history-panel">
            <CardContent className="p-4">
              <h3 className={`font-bold text-lg ${textPrimary} flex items-center gap-2 mb-6`}>
                <History className="w-5 h-5 text-purple-400" />
                Session History
              </h3>
              
              {sessionHistory.length === 0 ? (
                <div className="text-center py-12">
                  <Calendar className={`w-12 h-12 mx-auto mb-4 ${textSecondary}`} />
                  <p className={`font-medium ${textPrimary}`}>No sessions yet</p>
                  <p className={`text-sm ${textSecondary}`}>Your completed sessions will appear here</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {sessionHistory.map((session, idx) => {
                    const durationMins = session.duration_hours ? Math.round(session.duration_hours * 60) : 0;
                    return (
                      <div 
                        key={session.id || idx}
                        className={`p-4 rounded-xl ${sectionBg} flex justify-between items-center cursor-pointer transition-all hover:ring-1 ${isLight ? 'hover:ring-purple-300' : 'hover:ring-purple-500/30'}`}
                        onClick={() => {
                          setSelectedHistorySession({
                            ...session,
                            session_type: 'on_demand',
                            location: session.location_name,
                            session_date: session.date,
                            duration_mins: durationMins,
                            total_surfers: session.participant_count || 1,
                            total_earnings: session.earnings || 0,
                            buyin_price: session.hourly_rate || 75,
                            photographer_name: session.requester_name,
                            gallery_photo_count: session.photo_count || 0,
                            gallery_id: session.gallery_id || null,
                            participants: session.participants || [],
                          });
                          setShowHistoryDrawer(true);
                        }}
                      >
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold text-white bg-gradient-to-r from-purple-500 to-indigo-500">
                              <Zap className="w-2.5 h-2.5" /> On-Demand
                            </span>
                          </div>
                          <p className={`font-medium ${textPrimary}`}>{session.location_name}</p>
                          <p className={`text-sm ${textSecondary}`}>
                            {session.date ? new Date(session.date).toLocaleDateString() : 'Unknown'}
                            {session.requester_name && ` • ${session.requester_name}`}
                          </p>
                          <p className={`text-xs ${textSecondary} mt-1`}>
                            {durationMins > 0 ? `${durationMins} min` : ''}
                            {session.hourly_rate ? ` @ $${session.hourly_rate}/hr` : ''}
                          </p>
                        </div>
                        <div className="flex items-center gap-2 flex-shrink-0">
                          <p className="text-green-400 font-bold text-lg">${(session.earnings || 0).toFixed(2)}</p>
                          <ChevronRightIcon className={`w-4 h-4 ${textSecondary}`} />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Session Detail Drawer for On-Demand History */}
          <SessionDetailDrawer
            isOpen={showHistoryDrawer}
            onClose={() => {
              setShowHistoryDrawer(false);
              setSelectedHistorySession(null);
            }}
            session={selectedHistorySession}
            theme={theme}
            userRole="photographer"
            userId={user?.id}
            onNavigateToGallery={(galleryId) => {
              window.location.href = `/gallery/${galleryId}`;
            }}
          />
          </>
        )}
      </div>

      {/* ============ CANCEL CONFIRMATION MODAL ============ */}
      <AlertDialog open={showCancelConfirm} onOpenChange={setShowCancelConfirm}>
        <AlertDialogContent className="bg-zinc-900 border-zinc-700 max-w-md">
          <AlertDialogHeader>
            <div className="flex items-center gap-3 mb-1">
              <div className="w-10 h-10 rounded-full bg-red-500/20 flex items-center justify-center flex-shrink-0">
                <X className="w-5 h-5 text-red-400" />
              </div>
              <AlertDialogTitle className="text-white text-lg">
                Cancel This Session?
              </AlertDialogTitle>
            </div>
            <AlertDialogDescription className="text-gray-400 text-sm leading-relaxed">
              This will end the on-demand session and notify the surfer.
              Any held deposit will be refunded to their account.
              This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>

          {/* Session context summary */}
          {activeSession && (
            <div className="p-3 rounded-xl bg-zinc-800/70 border border-zinc-700 flex items-center gap-3">
              <div className="w-10 h-10 rounded-full overflow-hidden bg-zinc-700 flex-shrink-0">
                {activeSession.requester_selfie ? (
                  <img src={getImageUrl(activeSession.requester_selfie)} alt="" className="w-full h-full object-cover" />
                ) : activeSession.requester_avatar ? (
                  <img src={getFullUrl(getImageUrl(activeSession.requester_avatar))} alt="" className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <User className="w-5 h-5 text-zinc-500" />
                  </div>
                )}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm text-white font-medium truncate">{activeSession.requester_name || 'Surfer'}</p>
                <p className="text-xs text-gray-500 truncate">{activeSession.location_name || 'On-Demand Session'}</p>
              </div>
              <Badge className="bg-red-500/20 text-red-400 border-red-500/30 text-xs flex-shrink-0">
                Cancelling
              </Badge>
            </div>
          )}

          <AlertDialogFooter className="gap-3 sm:gap-2">
            <AlertDialogCancel
              className="flex-1 border-zinc-600 bg-transparent text-white hover:bg-zinc-800 hover:text-white"
              disabled={isCancelling}
            >
              Keep Session
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={(e) => {
                e.preventDefault(); // Prevent auto-close so loading state is visible
                handleConfirmCancel();
              }}
              disabled={isCancelling}
              className="flex-1 bg-red-500 hover:bg-red-600 text-white font-bold border-0"
            >
              {isCancelling ? (
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
              ) : (
                <X className="w-4 h-4 mr-2" />
              )}
              {isCancelling ? 'Cancelling...' : 'Yes, Cancel Session'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* --- Session Chat Drawer --- */}
      {activeSession && (
        <SessionChatDrawer
          isOpen={showSessionChat}
          onClose={() => setShowSessionChat(false)}
          otherUserId={activeSession.requester_id}
          otherUserName={activeSession.requester_name || 'Surfer'}
          otherUserAvatar={activeSession.requester_avatar || activeSession.requester_selfie}
          dispatchId={activeSession.id}
          isLight={false}
          onUnreadChange={setChatUnreadCount}
        />
      )}

      {/* --- Floating Chat FAB --- */}
      {activeSession && !showSessionChat && (
        <div className="fixed bottom-24 right-4 z-40">
          <SessionChatFAB
            unreadCount={chatUnreadCount}
            onClick={() => setShowSessionChat(true)}
            isLight={false}
          />
        </div>
      )}
    </div>
  );
};

export default OnDemandSessionManager;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { 
  MapPin, DollarSign, Zap, Check, Loader2,
  Navigation, Info, Waves, ChevronDown, ChevronUp,
  Settings
} from 'lucide-react';
import { Button } from './ui/button';
import { Switch } from './ui/switch';
import { Badge } from './ui/badge';
import { NumericStepper } from './ui/numeric-stepper';
import { Card, CardHeader, CardTitle, CardContent } from './ui/card';
import { toast } from 'sonner';
import logger from '../utils/logger';
import { ROLES } from '../constants/roles';


/**
 * On-Demand Settings Page - For Pro/Approved Pro photographers
 * 
 * UI STANDARDS (Matches Gallery & Bookings):
 * - NO internal header/footer - matches Gallery content start
 * - Numeric Stepper inputs (no sliders)
 * - Standard content container (p-4 max-w-6xl mx-auto)
 * - Standard Primary Action Button (not full-width bar)
 * - 16px side gutters (p-4)
 * - Bottom safe zone (pb-24)
 */
export const OnDemandSettingsPage = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { theme } = useTheme();
  
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [locationLoading, setLocationLoading] = useState(false);
  const [nearbySpots, setNearbySpots] = useState([]);
  const [selectedSpots, setSelectedSpots] = useState([]);
  const [userLocation, setUserLocation] = useState(null);
  
  // On-Demand Status Toggle
  const [onDemandActive, setOnDemandActive] = useState(false);
  const [selectedOnDemandSpot, setSelectedOnDemandSpot] = useState(null);
  const [togglingStatus, setTogglingStatus] = useState(false);
  const [isLiveShooting, setIsLiveShooting] = useState(false);  // Track if currently live shooting
  
  // Pricing settings (GPS and pricing logic preserved)
  const [baseRate, setBaseRate] = useState(75);
  const [peakPricingEnabled, setPeakPricingEnabled] = useState(false);
  const [peakMultiplier, setPeakMultiplier] = useState(1.5);
  const [onDemandPhotosIncluded, setOnDemandPhotosIncluded] = useState(3);
  const [onDemandFullGallery, setOnDemandFullGallery] = useState(false);

  // On-Demand independent resolution pricing
  const [odPriceWeb, setOdPriceWeb] = useState(5);
  const [odPriceStandard, setOdPriceStandard] = useState(10);
  const [odPriceHigh, setOdPriceHigh] = useState(18);
  const [odVideo720p, setOdVideo720p] = useState(12);
  const [odVideo1080p, setOdVideo1080p] = useState(20);
  const [odVideo4k, setOdVideo4k] = useState(40);
  
  // UI state
  const [showSpotsList, setShowSpotsList] = useState(true);
  const [showPricingSection, setShowPricingSection] = useState(true);
  
  // ============ THEME CLASSES - Beach Mode Support (matches Gallery/Bookings) ============
  const isLight = theme === 'light';
  const isBeach = theme === 'beach';
  const cardBg = isLight ? 'bg-white border-gray-200' : isBeach ? 'bg-zinc-950 border-zinc-800' : 'bg-zinc-900 border-zinc-800';
  const borderClass = isLight ? 'border-gray-200' : 'border-zinc-800';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-500' : 'text-gray-400';
  const sectionBg = isLight ? 'bg-gray-50' : isBeach ? 'bg-zinc-900' : 'bg-zinc-800/50';
  
  // Check if user can access this page (Photographer, Pro, Approved Pro - NOT Hobbyist/Grom Parent)
  const canAccess = ['Photographer', 'Pro', 'Approved Pro'].includes(user?.role);
  
  // Geographic Range Logic (Role-Based) - LOGIC PRESERVED
  const getGeographicRadius = () => {
    if (user?.role === ROLES.APPROVED_PRO) return { min: 30, max: 50, default: 40 };
    if (user?.role === ROLES.PRO) return { min: 30, max: 50, default: 40 };
    return { min: 10, max: 20, default: 15 }; // Standard Photographer
  };
  
  const geoRadius = getGeographicRadius();
  const isPro = ['Approved Pro', 'Pro'].includes(user?.role);
  
  // Check if navigated from Photo Hub init flow
  const searchParams = new URLSearchParams(window.location.search);
  const isInitFlow = searchParams.get('init') === 'true';
  
  useEffect(() => {
    if (!canAccess) {
      toast.error('On-Demand Settings is only available for Pro photographers');
      navigate('/map');
      return;
    }
    
    fetchSettings();
    requestLocation();
  }, [canAccess, navigate]);
  
  const requestLocation = () => {
    setLocationLoading(true);
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const location = {
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          };
          setUserLocation(location);
          fetchNearbySpots(location);
          setLocationLoading(false);
        },
        (error) => {
          logger.error('Geolocation error:', error);
          setLocationLoading(false);
          toast.error('Unable to get location. Please enable GPS.');
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    } else {
      setLocationLoading(false);
      toast.error('Geolocation not supported by your browser');
    }
  };
  
  const fetchNearbySpots = async (location) => {
    try {
      // Use role-based geographic radius - LOGIC PRESERVED
      const response = await apiClient.get(`/surf-spots/nearby`, {
        params: {
          latitude: location.latitude,
          longitude: location.longitude,
          radius_miles: geoRadius.default
        }
      });
      setNearbySpots(response.data || []);
    } catch (error) {
      logger.error('Failed to fetch nearby spots:', error);
      try {
        const fallbackResponse = await apiClient.get(`/surf-spots?limit=30`);
        setNearbySpots(fallbackResponse.data || []);
      } catch (e) {
        logger.error('Fallback also failed:', e);
      }
    }
  };
  
  const fetchSettings = async () => {
    try {
      const response = await apiClient.get(`/photographer/${user?.id}/on-demand-settings`);
      if (response.data) {
        setBaseRate(response.data.base_rate || 75);
        setPeakPricingEnabled(response.data.peak_pricing_enabled || false);
        setPeakMultiplier(response.data.peak_multiplier || 1.5);
        setSelectedSpots(response.data.claimed_spots || []);
        setOnDemandPhotosIncluded(response.data.on_demand_photos_included || 3);
        setOnDemandFullGallery(response.data.on_demand_full_gallery || false);
        // Resolution pricing
        setOdPriceWeb(response.data.on_demand_price_web || 5);
        setOdPriceStandard(response.data.on_demand_price_standard || 10);
        setOdPriceHigh(response.data.on_demand_price_high || 18);
        setOdVideo720p(response.data.on_demand_video_720p || 12);
        setOdVideo1080p(response.data.on_demand_video_1080p || 20);
        setOdVideo4k(response.data.on_demand_video_4k || 40);
      }
      
      // Also fetch on-demand status
      const statusResponse = await apiClient.get(`/photographer/${user?.id}/on-demand-status`);
      if (statusResponse.data) {
        setOnDemandActive(statusResponse.data.is_available || false);
        if (statusResponse.data.spot_name) {
          setSelectedOnDemandSpot({
            id: statusResponse.data.spot_id,
            name: statusResponse.data.spot_name
          });
        }
      }
      
      // Also fetch photographer status to check if live shooting (for mutual exclusivity)
      try {
        const photographerStatusRes = await apiClient.get(`/photographer/${user?.id}/status`);
        setIsLiveShooting(photographerStatusRes.data.is_shooting || false);
      } catch (e) {
        logger.error('Error fetching photographer status:', e);
      }
    } catch (error) {
      logger.error('Failed to fetch settings:', error);
    } finally {
      setLoading(false);
    }
  };
  
  // Toggle On-Demand Status
  const toggleOnDemandStatus = async () => {
    if (togglingStatus) return;
    
    // Check mutual exclusivity: cannot enable On-Demand while live shooting
    if (!onDemandActive && isLiveShooting) {
      toast.error('Cannot enable On-Demand while in an active live session. Please end your session first from Live Sessions.');
      return;
    }
    
    setTogglingStatus(true);
    try {
      if (onDemandActive) {
        // Turn off
        await apiClient.post(`/photographer/${user.id}/on-demand-toggle`, {
          is_available: false
        });
        setOnDemandActive(false);
        setSelectedOnDemandSpot(null);
        toast.success('On-Demand mode deactivated');
      } else {
        // Need a spot to turn on - use first selected spot or first nearby spot
        const spotToUse = selectedSpots.length > 0 
          ? nearbySpots.find(s => selectedSpots.includes(s.id))
          : nearbySpots[0];
          
        if (!spotToUse) {
          toast.error('Please select at least one coverage spot first');
          setTogglingStatus(false);
          return;
        }
        
        await apiClient.post(`/photographer/${user.id}/on-demand-toggle`, {
          is_available: true,
          spot_id: spotToUse.id,
          spot_name: spotToUse.name,
          latitude: spotToUse.latitude,
          longitude: spotToUse.longitude
        });
        setOnDemandActive(true);
        setSelectedOnDemandSpot(spotToUse);
        toast.success(`On-Demand activated at ${spotToUse.name}!`);
      }
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to update On-Demand status');
    } finally {
      setTogglingStatus(false);
    }
  };
  
  // Checkbox selection (multiple spots)
  const toggleSpotSelection = (spotId) => {
    setSelectedSpots(prev => 
      prev.includes(spotId) 
        ? prev.filter(id => id !== spotId)
        : [...prev, spotId]
    );
  };
  
  const selectAllSpots = () => {
    setSelectedSpots(nearbySpots.map(s => s.id));
  };
  
  const clearAllSpots = () => {
    setSelectedSpots([]);
  };
  
  const saveSettings = async () => {
    setSaving(true);
    try {
      await apiClient.post(`/photographer/${user.id}/on-demand-settings`, {
        base_rate: baseRate,
        peak_pricing_enabled: peakPricingEnabled,
        peak_multiplier: peakMultiplier,
        claimed_spots: selectedSpots,
        latitude: userLocation?.latitude,
        longitude: userLocation?.longitude,
        on_demand_photos_included: onDemandPhotosIncluded,
        on_demand_full_gallery: onDemandFullGallery,
        on_demand_price_web: odPriceWeb,
        on_demand_price_standard: odPriceStandard,
        on_demand_price_high: odPriceHigh,
        on_demand_video_720p: odVideo720p,
        on_demand_video_1080p: odVideo1080p,
        on_demand_video_4k: odVideo4k,
      });
      
      toast.success('On-Demand settings saved!');
      
      // If from init flow, navigate back to map
      if (isInitFlow) {
        navigate('/map');
      }
    } catch (error) {
      logger.error('Failed to save settings:', error);
      toast.error('Failed to save settings');
    } finally {
      setSaving(false);
    }
  };
  
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-yellow-400" />
      </div>
    );
  }
  
  return (
    // MATCHES GALLERY STRUCTURE: p-4 max-w-6xl mx-auto, NO internal header/footer
    <div className="p-4 max-w-6xl mx-auto pb-24" data-testid="on-demand-settings-page">
      {/* Header - Same style as Gallery */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className={`text-2xl font-bold ${textPrimary} flex items-center gap-2`}>
            <MapPin className="w-7 h-7 text-green-400" />
            On-Demand Settings
          </h1>
          <p className={`${textSecondary} text-sm mt-1`}>
            {selectedSpots.length} coverage spots • {geoRadius.min}-{geoRadius.max} mile range
          </p>
        </div>
        
        <Button
          onClick={saveSettings}
          disabled={saving}
          className="bg-gradient-to-r from-green-400 to-cyan-400 text-black font-bold"
          data-testid="save-settings-btn"
        >
          {saving ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Check className="w-4 h-4 mr-2" />}
          {saving ? 'Saving...' : 'Save Settings'}
        </Button>
      </div>
      
      {/* On-Demand Status Toggle - Primary Action */}
      <Card className={`mb-6 ${onDemandActive 
        ? 'bg-gradient-to-r from-yellow-500/20 to-orange-500/20 border-yellow-400/50' 
        : cardBg}`}
      >
        <CardContent className="p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${
                onDemandActive ? 'bg-yellow-500/30' : 'bg-zinc-700'
              }`}>
                <Zap className={`w-6 h-6 ${onDemandActive ? 'text-yellow-400' : 'text-gray-400'}`} />
              </div>
              <div>
                <p className={`font-bold ${textPrimary}`}>On-Demand Status</p>
                <p className={`text-sm ${onDemandActive ? 'text-yellow-300' : textSecondary}`}>
                  {onDemandActive 
                    ? `Active at: ${selectedOnDemandSpot?.name || 'Your Area'}` 
                    : selectedSpots.length > 0 
                      ? 'Ready to activate' 
                      : 'Select coverage spots below'}
                </p>
              </div>
            </div>
            <button
              onClick={toggleOnDemandStatus}
              disabled={togglingStatus || (selectedSpots.length === 0 && !onDemandActive)}
              className={`w-14 h-8 rounded-full transition-colors relative ${
                onDemandActive 
                  ? 'bg-yellow-500' 
                  : selectedSpots.length > 0 
                    ? 'bg-zinc-600 hover:bg-zinc-500' 
                    : 'bg-zinc-700 opacity-50 cursor-not-allowed'
              }`}
              data-testid="on-demand-status-toggle"
            >
              {togglingStatus ? (
                <Loader2 className="w-5 h-5 animate-spin absolute top-1.5 left-1/2 -translate-x-1/2 text-white" />
              ) : (
                <span className={`absolute top-1 w-6 h-6 rounded-full bg-white transition-transform shadow-md ${
                  onDemandActive ? 'right-1' : 'left-1'
                }`} />
              )}
            </button>
          </div>
          
          {/* Active spot info */}
          {onDemandActive && selectedOnDemandSpot && (
            <div className="mt-3 pt-3 border-t border-yellow-500/30 flex items-center gap-2">
              <MapPin className="w-4 h-4 text-green-400" />
              <span className={`text-sm text-green-300`}>
                Accepting requests at {selectedOnDemandSpot.name}
              </span>
            </div>
          )}
        </CardContent>
      </Card>
      
      {/* Init Flow Banner */}
      {isInitFlow && (
        <div className={`mb-6 p-4 rounded-2xl bg-gradient-to-r ${isPro ? 'from-purple-500/20 to-cyan-500/20 border-purple-500/30' : 'from-cyan-500/20 to-blue-500/20 border-cyan-500/30'} border`}>
          <div className="flex items-center gap-3">
            <div className={`w-12 h-12 rounded-xl ${isPro ? 'bg-purple-500/30' : 'bg-cyan-500/30'} flex items-center justify-center`}>
              <Zap className={`w-6 h-6 ${isPro ? 'text-purple-400' : 'text-cyan-400'}`} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <p className={`font-bold ${textPrimary}`}>Go On-Demand</p>
                <Badge className={isPro ? 'bg-purple-500 text-white' : 'bg-cyan-500 text-white'}>
                  {geoRadius.min}-{geoRadius.max} mi
                </Badge>
              </div>
              <p className={`text-sm ${textSecondary}`}>
                {isPro 
                  ? 'Pro coverage: Select spots within your extended range'
                  : 'Standard coverage: Select spots within your local range'}
              </p>
            </div>
          </div>
        </div>
      )}
      
      {/* On-Demand Pricing Card - Same style as Gallery Pricing Card */}
      <Card className={`mb-6 ${cardBg}`}>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className={`text-lg ${textPrimary} flex items-center gap-2`}>
              <DollarSign className="w-5 h-5 text-green-400" />
              On-Demand Pricing
            </CardTitle>
            <Button 
              variant="outline" 
              size="sm"
              onClick={() => setShowPricingSection(!showPricingSection)}
              className={borderClass}
            >
              <Settings className="w-4 h-4 mr-2" />
              {showPricingSection ? 'Hide' : 'Show'}
            </Button>
          </div>
        </CardHeader>
        {showPricingSection && (
          <CardContent className="space-y-6">
            {/* Preview Grid */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className={`p-3 rounded-xl ${sectionBg}`}>
                <p className={`text-xs ${textSecondary} mb-1`}>Base Rate</p>
                <p className="text-xl font-bold text-green-400">${baseRate}/hr</p>
              </div>
              <div className={`p-3 rounded-xl ${sectionBg}`}>
                <p className={`text-xs ${textSecondary} mb-1`}>Peak Rate</p>
                <p className="text-xl font-bold text-amber-400">
                  {peakPricingEnabled ? `$${(baseRate * peakMultiplier).toFixed(0)}/hr` : 'OFF'}
                </p>
              </div>
              <div className={`p-3 rounded-xl ${sectionBg}`}>
                <p className={`text-xs ${textSecondary} mb-1`}>Photos Included</p>
                <p className={`text-xl font-bold ${onDemandFullGallery ? 'text-green-400' : textPrimary}`}>
                  {onDemandFullGallery ? '∞ Full' : onDemandPhotosIncluded}
                </p>
              </div>
              <div className={`p-3 rounded-xl ${sectionBg}`}>
                <p className={`text-xs ${textSecondary} mb-1`}>Coverage</p>
                <p className="text-xl font-bold text-cyan-400">{selectedSpots.length} spots</p>
              </div>
            </div>
            
            {/* Base Rate - NUMERIC STEPPER */}
            <NumericStepper
              label="On-Demand Base Rate"
              value={baseRate}
              onChange={setBaseRate}
              min={25}
              max={300}
              step={5}
              prefix="$"
              suffix="/hr"
              description="Premium rate for On-Demand requests (above standard bookings)"
              theme={theme}
            />
            
            {/* Peak/Swell Pricing Toggle */}
            <div className={`p-4 rounded-xl ${isLight ? 'bg-amber-50 border-amber-200' : 'bg-amber-500/10 border-amber-500/30'} border`}>
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-3">
                  <Waves className="w-5 h-5 text-amber-400" />
                  <div>
                    <p className={`font-medium ${textPrimary}`}>Peak/Swell Pricing</p>
                    <p className={`text-xs ${textSecondary}`}>Auto-increase rate during high demand</p>
                  </div>
                </div>
                <Switch
                  checked={peakPricingEnabled}
                  onCheckedChange={setPeakPricingEnabled}
                />
              </div>
              
              {peakPricingEnabled && (
                <div className="mt-4">
                  <div className="flex items-center justify-between mb-2">
                    <span className={`text-sm ${textPrimary}`}>Peak Multiplier</span>
                    <span className="text-lg font-bold text-amber-400">{peakMultiplier}x</span>
                  </div>
                  <div className="flex gap-2">
                    {[1.25, 1.5, 1.75, 2.0].map(mult => (
                      <button
                        key={mult}
                        onClick={() => setPeakMultiplier(mult)}
                        className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all ${
                          peakMultiplier === mult
                            ? 'bg-amber-500 text-black'
                            : isLight ? 'bg-gray-200 text-gray-700' : 'bg-zinc-700 text-gray-300'
                        }`}
                      >
                        {mult}x
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>
            
            {/* Photos Included - NUMERIC STEPPER */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2">
                  <label className={`font-medium ${textPrimary}`}>Photos Included</label>
                  {onDemandFullGallery && (
                    <Badge className="bg-green-500 text-white text-xs">FULL GALLERY</Badge>
                  )}
                </div>
              </div>
              
              {/* Full Gallery Toggle */}
              <div className={`p-3 rounded-xl mb-4 ${isLight ? 'bg-green-50 border-green-200' : 'bg-green-500/10 border-green-500/30'} border`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Zap className="w-5 h-5 text-green-400" />
                    <div>
                      <p className={`font-medium ${textPrimary}`}>Full Gallery Access</p>
                      <p className={`text-xs ${textSecondary}`}>All photos included - unlimited downloads</p>
                    </div>
                  </div>
                  <Switch
                    checked={onDemandFullGallery}
                    onCheckedChange={setOnDemandFullGallery}
                  />
                </div>
              </div>
              
              {!onDemandFullGallery && (
                <NumericStepper
                  value={onDemandPhotosIncluded}
                  onChange={setOnDemandPhotosIncluded}
                  min={0}
                  max={999}
                  step={1}
                  description="Photos included free with on-demand buy-in. Additional charged per resolution."
                  theme={theme}
                />
              )}

              {/* Photo Download Prices */}
              <div className={`mt-4 p-4 rounded-xl border ${isLight ? 'bg-blue-50 border-blue-200' : 'bg-blue-500/10 border-blue-500/20'}`}>
                <p className={`text-sm font-semibold mb-3 flex items-center gap-2 ${textPrimary}`}>
                  📸 Photo Download Prices
                  <span className={`text-xs font-normal ${textSecondary}`}>(per resolution — independent from Gallery)</span>
                </p>
                <div className="grid grid-cols-1 gap-3">
                  <NumericStepper
                    label="Web Quality (800px)"
                    value={odPriceWeb}
                    onChange={setOdPriceWeb}
                    min={0}
                    max={500}
                    step={0.5}
                    prefix="$"
                    theme={theme}
                  />
                  <NumericStepper
                    label="Standard (1920px)"
                    value={odPriceStandard}
                    onChange={setOdPriceStandard}
                    min={0}
                    max={500}
                    step={0.5}
                    prefix="$"
                    theme={theme}
                  />
                  <NumericStepper
                    label="High-Res (Original)"
                    value={odPriceHigh}
                    onChange={setOdPriceHigh}
                    min={0}
                    max={500}
                    step={0.5}
                    prefix="$"
                    theme={theme}
                  />
                </div>
              </div>

              {/* Video Download Prices */}
              <div className={`mt-4 p-4 rounded-xl border ${isLight ? 'bg-purple-50 border-purple-200' : 'bg-purple-500/10 border-purple-500/20'}`}>
                <p className={`text-sm font-semibold mb-3 flex items-center gap-2 ${textPrimary}`}>
                  🎬 Video Download Prices
