            <p className={`text-xs ${textSecondary} mt-3 flex items-start gap-1`}>
              <Info className="w-3 h-3 mt-0.5 flex-shrink-0" />
              Surfers searching at these spots will see you in On-Demand results
            </p>
          </CardContent>
        )}
      </Card>
    </div>
  );
};

