};

export const ResetPassword = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  
  // Extract token with multiple fallback methods to handle URL encoding issues
  const extractToken = () => {
    // Method 1: Standard search params
    let token = searchParams.get('token');
    if (token) {
      // Decode any URL encoding
      try {
        token = decodeURIComponent(token);
      } catch (e) {
        // Already decoded or invalid
      }
      return token;
    }
    
    // Method 2: Parse from full URL (handles double-encoding from email trackers)
    const fullUrl = window.location.href;
    const tokenMatch = fullUrl.match(/[?&]token=([^&]+)/);
    if (tokenMatch) {
      token = tokenMatch[1];
      try {
        // Try double-decode in case of double encoding
        token = decodeURIComponent(decodeURIComponent(token));
      } catch (e) {
        try {
          token = decodeURIComponent(token);
        } catch (e2) {
          // Use as-is
        }
      }
      return token;
    }
    
    // Method 3: Check if token is embedded in a redirect URL (email tracker unwrapping)
    const redirectMatch = fullUrl.match(/token%3D([^&%]+)/i) || fullUrl.match(/token=([^&]+)/i);
    if (redirectMatch) {
      token = redirectMatch[1];
      try {
        token = decodeURIComponent(token);
      } catch (e) {
        // Use as-is
      }
      return token;
    }
    
    return null;
  };
  
  const token = extractToken();
  
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [tokenValid, setTokenValid] = useState(null);
  const [email, setEmail] = useState('');

  // Verify token on mount
  React.useEffect(() => {
    const verifyToken = async () => {
      if (!token) {
        logger.error('[Password Reset] No token found in URL:', window.location.href);
        setTokenValid(false);
        return;
      }

      logger.debug('[Password Reset] Verifying token:', token.substring(0, 10) + '...');

      try {
        const response = await apiClient.post(`/auth/verify-reset-token`, { token });
        setTokenValid(true);
        setEmail(response.data.email || '');
      } catch (error) {
        logger.error('[Password Reset] Token verification failed:', error.response?.data);
        setTokenValid(false);
        toast.error(error.response?.data?.detail || 'Invalid or expired reset link');
      }
    };

    verifyToken();
  }, [token]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (password !== confirmPassword) {
      toast.error('Passwords do not match');
      return;
    }

    if (password.length < 6) {
      toast.error('Password must be at least 6 characters');
      return;
    }

    setLoading(true);

    try {
      await apiClient.post(`/auth/reset-password`, {
        token,
        new_password: password
      });
      setSuccess(true);
      toast.success('Password reset successful!');
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to reset password');
    } finally {
      setLoading(false);
    }
  };

  // Loading state while verifying token
  if (tokenValid === null) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-black">
        <Loader2 className="w-8 h-8 animate-spin text-yellow-400" />
      </div>
    );
  }

  // Invalid token
  if (!tokenValid) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4 bg-black">
        <Card className="w-full max-w-md bg-zinc-900 border-zinc-800 p-8 text-center">
          <div className="w-16 h-16 mx-auto bg-red-500/20 rounded-full flex items-center justify-center mb-4">
            <Lock className="w-8 h-8 text-red-400" />
          </div>
          <h2 className="text-xl font-bold text-white mb-2">Invalid Reset Link</h2>
          <p className="text-gray-400 mb-4">
            This password reset link is invalid or has expired.
          </p>
          {/* Debug info - helps diagnose email tracker issues */}
          {!token && (
            <p className="text-xs text-red-400/70 mb-4 font-mono break-all">
              Debug: No token found in URL. If you clicked a link from email, the URL may have been corrupted by email tracking.
            </p>
          )}
          {token && (
            <p className="text-xs text-yellow-400/70 mb-4 font-mono">
              Debug: Token found but invalid/expired.
            </p>
          )}
          <Button
            onClick={() => navigate('/forgot-password')}
            className="bg-gradient-to-r from-emerald-400 via-yellow-400 to-orange-400 text-black font-bold"
          >
            Request New Link
          </Button>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-black">
      <Card className="w-full max-w-md bg-zinc-900 border-zinc-800 overflow-hidden" data-testid="reset-password-card">
        {/* Header */}
        <div className="text-center pt-8 pb-4">
          <div className="flex items-center justify-center gap-2 mb-6">
            <img
              src="https://customer-assets.emergentagent.com/job_raw-surf-os/artifacts/9llcl5mg_Rawig6-500x500.png"
              alt="Raw Surf"
              className="w-10 h-10"
            />
            <span className="text-2xl font-bold text-white" style={{ fontFamily: 'Oswald' }}>Raw Surf</span>
          </div>
          <h2 className="text-xl font-bold text-white">
            {success ? 'Password Reset!' : 'Create New Password'}
          </h2>
          {email && !success && (
            <p className="text-gray-400 mt-2 text-sm">for {email}</p>
          )}
        </div>

        <div className="px-6 pb-6">
          {!success ? (
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <Input
                  type={showPassword ? 'text' : 'password'}
                  placeholder="New password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="bg-zinc-800 border-zinc-700 text-white h-12 pl-10 pr-10"
                  required
                  minLength={6}
                  data-testid="new-password-input"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-white"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>

              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <Input
                  type={showPassword ? 'text' : 'password'}
                  placeholder="Confirm new password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="bg-zinc-800 border-zinc-700 text-white h-12 pl-10"
                  required
                  minLength={6}
                  data-testid="confirm-password-input"
                />
              </div>

              <p className="text-xs text-gray-500">Password must be at least 6 characters</p>

              <Button
                type="submit"
                disabled={loading}
                className="w-full h-12 bg-gradient-to-r from-emerald-400 via-yellow-400 to-orange-400 hover:from-emerald-500 hover:via-yellow-500 hover:to-orange-500 text-black font-bold"
                data-testid="reset-submit"
              >
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Reset Password'}
              </Button>
            </form>
          ) : (
            <div className="text-center space-y-4">
              <div className="w-16 h-16 mx-auto bg-emerald-500/20 rounded-full flex items-center justify-center">
                <Check className="w-8 h-8 text-emerald-400" />
              </div>
              <p className="text-gray-300">
                Your password has been reset successfully. You can now log in with your new password.
              </p>
              <Button
                onClick={() => navigate('/auth?tab=login')}
                className="w-full h-12 bg-gradient-to-r from-emerald-400 via-yellow-400 to-orange-400 text-black font-bold"
              >
                Go to Login
              </Button>
            </div>
          )}
        </div>
      </Card>
    </div>
  );
};

﻿/**
 * Payment Success Page
 * Polls Stripe for payment status and shows confirmation
 */
import React, { useEffect, useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { CheckCircle, Loader2, XCircle, ArrowLeft } from 'lucide-react';
import { Button } from './ui/button';
import logger from '../utils/logger';


const PaymentSuccess = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const sessionId = searchParams.get('session_id');
  
  const [status, setStatus] = useState('checking');
  const [paymentData, setPaymentData] = useState(null);
  const [pollAttempts, setPollAttempts] = useState(0);
  const maxAttempts = 5;

  useEffect(() => {
    if (!sessionId) {
      setStatus('error');
      return;
    }

    const pollPaymentStatus = async () => {
      try {
        const response = await apiClient.get(`/payments/checkout/status/${sessionId}`);
        const data = response.data;
        
        setPaymentData(data);
        
        if (data.payment_status === 'paid') {
          setStatus('success');
          return;
        } else if (data.status === 'expired') {
          setStatus('expired');
          return;
        }
        
        // Continue polling if not yet paid
        if (pollAttempts < maxAttempts) {
          setPollAttempts(prev => prev + 1);
          setTimeout(pollPaymentStatus, 2000);
        } else {
          setStatus('timeout');
        }
      } catch (error) {
        logger.error('Payment status check error:', error);
        setStatus('error');
      }
    };

    pollPaymentStatus();
  }, [sessionId, pollAttempts]);

  const renderContent = () => {
    switch (status) {
      case 'checking':
        return (
          <div className="text-center">
            <Loader2 className="w-16 h-16 text-cyan-400 animate-spin mx-auto mb-4" />
            <h2 className="text-2xl font-bold text-white mb-2">Processing Payment...</h2>
            <p className="text-gray-400">Please wait while we confirm your payment</p>
          </div>
        );
      
      case 'success':
        return (
          <div className="text-center">
            <div className="w-20 h-20 rounded-full bg-emerald-500/20 flex items-center justify-center mx-auto mb-4">
              <CheckCircle className="w-12 h-12 text-emerald-400" />
            </div>
            <h2 className="text-2xl font-bold text-white mb-2">Payment Successful!</h2>
            <p className="text-gray-400 mb-4">
              Your deposit of ${(paymentData?.amount_total / 100).toFixed(2)} has been received.
            </p>
            <div className="bg-zinc-800/50 rounded-lg p-4 mb-6 text-left">
              <p className="text-sm text-gray-400 mb-1">Amount</p>
              <p className="text-lg text-white font-bold">${(paymentData?.amount_total / 100).toFixed(2)} {paymentData?.currency?.toUpperCase()}</p>
            </div>
            <p className="text-sm text-gray-500 mb-6">
              Credits have been added to your wallet. You can now request a photographer!
            </p>
            <Button 
              onClick={() => navigate('/map')}
              className="w-full bg-gradient-to-r from-cyan-500 to-blue-600 text-white"
            >
              Back to Map
            </Button>
          </div>
        );
      
      case 'expired':
        return (
          <div className="text-center">
            <div className="w-20 h-20 rounded-full bg-yellow-500/20 flex items-center justify-center mx-auto mb-4">
              <XCircle className="w-12 h-12 text-yellow-400" />
            </div>
            <h2 className="text-2xl font-bold text-white mb-2">Session Expired</h2>
            <p className="text-gray-400 mb-6">
              Your payment session has expired. Please try again.
            </p>
            <Button 
              onClick={() => navigate('/map')}
              className="w-full bg-zinc-700 text-white hover:bg-zinc-600"
            >
              Return to Map
            </Button>
          </div>
        );
      
      case 'timeout':
        return (
          <div className="text-center">
            <div className="w-20 h-20 rounded-full bg-yellow-500/20 flex items-center justify-center mx-auto mb-4">
              <Loader2 className="w-12 h-12 text-yellow-400" />
            </div>
            <h2 className="text-2xl font-bold text-white mb-2">Still Processing</h2>
            <p className="text-gray-400 mb-6">
              Payment is taking longer than expected. Please check your email for confirmation.
            </p>
            <Button 
              onClick={() => navigate('/map')}
              className="w-full bg-zinc-700 text-white hover:bg-zinc-600"
            >
              Return to Map
            </Button>
          </div>
        );
      
      case 'error':
      default:
        return (
          <div className="text-center">
            <div className="w-20 h-20 rounded-full bg-red-500/20 flex items-center justify-center mx-auto mb-4">
              <XCircle className="w-12 h-12 text-red-400" />
            </div>
            <h2 className="text-2xl font-bold text-white mb-2">Payment Error</h2>
            <p className="text-gray-400 mb-6">
              There was an error processing your payment. Please try again.
            </p>
            <Button 
              onClick={() => navigate('/map')}
              className="w-full bg-zinc-700 text-white hover:bg-zinc-600"
            >
              Return to Map
            </Button>
          </div>
        );
    }
  };

  return (
    <div className="min-h-screen bg-zinc-900 flex items-center justify-center p-4">
      <div className="max-w-md w-full">
        <button
          onClick={() => navigate('/map')}
          className="flex items-center gap-2 text-gray-400 hover:text-white mb-8 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to Map
        </button>
        
        <div className="bg-zinc-800/50 rounded-2xl p-8 border border-zinc-700">
          {renderContent()}
        </div>
      </div>
    </div>
  );
};

