/**
 * PostCard - Extracted from Feed.js for better maintainability
 * Renders a single post in the feed with all interactions
 */
import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient from '../lib/apiClient';
import { getExpandedRoleInfo } from '../contexts/PersonaContext';
import SessionLogHeader from './SessionLogHeader';
import { CommentInputWithEmoji } from './EmojiPicker';
import WhoReactedModal from './WhoReactedModal';
import SessionJoinCard from './SessionJoinCard';
import { RichText, CommentText } from './RichText';
import { MapPin, MessageCircle, Send, Bookmark, MoreHorizontal, Loader2, Play, Radio, Heart, ShoppingBag, ChevronRight, RefreshCw, Volume2, Volume1, VolumeX, Pause } from 'lucide-react';
import { toast } from 'sonner';
import { getFullUrl } from '../utils/media';
import { formatTimeAgo } from '../utils/formatTime';
import { REACTION_EMOJIS } from '../constants/emojis';


// Comment reaction emojis — imported from centralized constants/emojis.js

/**
 * ReplyItem - Simpler component for reply rendering (non-recursive)
 */
const ReplyItem = ({ reply, userId, _postId, textPrimaryClass, textSecondaryClass, _isLight }) => {
  const navigate = useNavigate();
  const [reactionCount, setReactionCount] = useState(reply.reaction_count || 0);
  const [viewerReaction, setViewerReaction] = useState(reply.viewer_reaction || null);
  const [loading, setLoading] = useState(false);

  const handleReaction = async (emoji = '❤️') => {
    if (!userId) {
      toast.error('Please log in to react');
      return;
    }
    
    setLoading(true);
    try {
      const response = await apiClient.post(
        `/comments/${reply.id}/reactions`,
        { emoji }
      );
      
      if (response.data.action === 'added') {
        setReactionCount(prev => prev + 1);
        setViewerReaction(emoji);
      } else if (response.data.action === 'removed') {
        setReactionCount(prev => Math.max(0, prev - 1));
        setViewerReaction(null);
      } else if (response.data.action === 'updated') {
        setViewerReaction(emoji);
      }
    } catch (err) {
      toast.error('Failed to react');
    } finally {
      setLoading(false);
    }
  };



  return (
    <div className="ml-6 pl-3 border-l-2 border-zinc-700/50">
      <div className="flex items-start gap-2">
        <div className="flex-1 min-w-0">
          <span className={`font-medium ${textPrimaryClass} text-sm cursor-pointer hover:underline`}
            onClick={(e) => { e.stopPropagation(); navigate(`/profile/${reply.author_id}`); }}>
            {reply.author_name}
          </span>
          <CommentText 
            text={reply.content}
            className={`${textSecondaryClass} text-sm ml-1`}
          />
        </div>
      </div>
      <div className={`flex items-center gap-3 mt-1 ${textSecondaryClass} text-xs`}>
        <span className="opacity-70">{formatTimeAgo(reply.created_at)}</span>
        {reactionCount > 0 && (
          <span className="font-medium">{reactionCount} like{reactionCount !== 1 ? 's' : ''}</span>
        )}
        <button
          onClick={() => handleReaction('❤️')}
          disabled={loading}
          className={`ml-auto p-1 rounded transition-all ${
            viewerReaction ? 'text-red-500' : `${textSecondaryClass} hover:text-red-400`
          }`}
        >
          <Heart className="w-3.5 h-3.5" fill={viewerReaction ? 'currentColor' : 'none'} />
        </button>
      </div>
    </div>
  );
};

/**
 * CommentWithReaction - Individual comment with like/reaction button and reply support
 */
const CommentWithReaction = ({ 
  comment, 
  userId, 
  postId,
  textPrimaryClass, 
  textSecondaryClass, 
  isLight,
  onReplyAdded,
  onCommentUpdated
}) => {
  const navigate = useNavigate();
  const [reactionCount, setReactionCount] = useState(comment.reaction_count || 0);
  const [viewerReaction, setViewerReaction] = useState(comment.viewer_reaction || null);
  const [showReactionPicker, setShowReactionPicker] = useState(false);
  const [loading, setLoading] = useState(false);
  const [showReplyInput, setShowReplyInput] = useState(false);
  const [replyContent, setReplyContent] = useState('');
  const [submittingReply, setSubmittingReply] = useState(false);
  const [localReplies, setLocalReplies] = useState(comment.replies || []);
  const [showReplies, setShowReplies] = useState(true);
  
  // Edit state
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState(comment.content);
  const [savingEdit, setSavingEdit] = useState(false);
  const [localContent, setLocalContent] = useState(comment.content);
  const [localIsEdited, setLocalIsEdited] = useState(comment.is_edited || false);
  const [showMenu, setShowMenu] = useState(false);

  const handleReaction = async (emoji = '❤️') => {
    if (!userId) {
      toast.error('Please log in to react');
      return;
    }
    
    setLoading(true);
    try {
      const response = await apiClient.post(
        `/comments/${comment.id}/reactions`,
        { emoji }
      );
      
      if (response.data.action === 'added') {
        setReactionCount(prev => prev + 1);
        setViewerReaction(emoji);
      } else if (response.data.action === 'removed') {
        setReactionCount(prev => Math.max(0, prev - 1));
        setViewerReaction(null);
      } else if (response.data.action === 'updated') {
        setViewerReaction(emoji);
      }
      
      setShowReactionPicker(false);
    } catch (err) {
      toast.error('Failed to react');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitReply = async () => {
    if (!replyContent.trim()) return;
    
    if (!userId) {
      toast.error('Please log in to reply');
      return;
    }
    
    setSubmittingReply(true);
    try {
      const response = await apiClient.post(
        `/posts/${postId}/comments`,
        { 
          content: replyContent.trim(),
          parent_id: comment.id
        }
      );
      
      const newReply = {
        ...response.data,
        reaction_count: 0,
        viewer_reaction: null
      };
      setLocalReplies(prev => [...prev, newReply]);
      setReplyContent('');
      setShowReplyInput(false);
      setShowReplies(true);
      toast.success('Reply added');
      
      if (onReplyAdded) onReplyAdded();
    } catch (err) {
      toast.error('Failed to add reply');
    } finally {
      setSubmittingReply(false);
    }
  };

  const handleSaveEdit = async () => {
    if (!editContent.trim() || editContent.trim() === comment.content) {
      setIsEditing(false);
      setEditContent(localContent);
      return;
    }
    
    setSavingEdit(true);
    try {
      const response = await apiClient.put(
        `/posts/${postId}/comments/${comment.id}`,
        { content: editContent.trim() }
      );
      
      setLocalContent(response.data.content);
      setLocalIsEdited(true);
      setIsEditing(false);
      toast.success('Comment updated');
      
      if (onCommentUpdated) onCommentUpdated(comment.id, response.data);
    } catch (err) {
      toast.error('Failed to update comment');
    } finally {
      setSavingEdit(false);
    }
  };

  const handleCancelEdit = () => {
    setIsEditing(false);
    setEditContent(localContent);
  };



  const replyCount = localReplies.length;
  const isOwner = userId && comment.author_id === userId;

  return (
    <div data-testid={`comment-${comment.id}`}>
      <div className="flex items-start gap-2">
        <div className="flex-1 min-w-0">
          {isEditing ? (
            <div className="flex flex-col gap-2">
              <textarea
                value={editContent}
                onChange={(e) => setEditContent(e.target.value)}
                className={`w-full p-2 rounded-lg text-sm resize-none ${
                  isLight 
                    ? 'bg-gray-100 border border-gray-200 text-gray-900' 
                    : 'bg-zinc-800 border border-zinc-700 text-white'
                } focus:outline-none focus:ring-1 focus:ring-cyan-500`}
                rows={2}
                autoFocus
                data-testid={`edit-comment-input-${comment.id}`}
              />
              <div className="flex gap-2 justify-end">
                <button
                  onClick={handleCancelEdit}
                  className={`px-2 py-1 text-xs rounded ${
                    isLight ? 'text-gray-600 hover:bg-gray-100' : 'text-gray-400 hover:bg-zinc-700'
                  }`}
                  data-testid={`cancel-edit-${comment.id}`}
                >
                  Cancel
                </button>
                <button
                  onClick={handleSaveEdit}
                  disabled={savingEdit || !editContent.trim()}
                  className={`px-2 py-1 text-xs rounded bg-cyan-500 text-white hover:bg-cyan-600 disabled:opacity-50`}
                  data-testid={`save-edit-${comment.id}`}
                >
                  {savingEdit ? 'Saving...' : 'Save'}
                </button>
              </div>
            </div>
          ) : (
            <>
              <span className={`font-medium ${textPrimaryClass} text-sm cursor-pointer hover:underline`}
                onClick={(e) => { e.stopPropagation(); navigate(`/profile/${comment.author_id}`); }}>
                {comment.author_username ? `@${comment.author_username}` : comment.author_name}
              </span>
              <CommentText 
                text={localContent}
                className={`${textSecondaryClass} text-sm ml-1`}
              />
              {localIsEdited && (
                <span className={`${textSecondaryClass} text-xs ml-1 opacity-60`}>(edited)</span>
              )}
            </>
          )}
        </div>
        
        {/* Edit/Delete menu for owner */}
        {isOwner && !isEditing && (
          <div className="relative">
            <button
              onClick={() => setShowMenu(!showMenu)}
              className={`p-1 rounded ${textSecondaryClass} hover:opacity-80`}
              data-testid={`comment-menu-${comment.id}`}
            >
              <MoreHorizontal className="w-4 h-4" />
            </button>
            
            {showMenu && (
              <>
                <div className="fixed inset-0 z-40" onClick={() => setShowMenu(false)} />
                <div className={`absolute right-0 top-full mt-1 py-1 rounded-lg shadow-lg z-50 min-w-[100px] ${
                  isLight ? 'bg-white border border-gray-200' : 'bg-zinc-800 border border-zinc-700'
                }`}>
                  <button
                    onClick={() => { setIsEditing(true); setShowMenu(false); }}
                    className={`w-full px-3 py-1.5 text-left text-sm ${
                      isLight ? 'hover:bg-gray-100 text-gray-700' : 'hover:bg-zinc-700 text-gray-200'
                    }`}
                    data-testid={`edit-comment-btn-${comment.id}`}
                  >
                    Edit
                  </button>
                </div>
              </>
            )}
          </div>
        )}
      </div>
      
      {/* Comment actions row */}
      <div className={`flex items-center gap-3 mt-1 ${textSecondaryClass} text-xs`}>
        <span className="opacity-70">{formatTimeAgo(comment.created_at)}</span>
        
        {reactionCount > 0 && (
          <span className="font-medium">{reactionCount} like{reactionCount !== 1 ? 's' : ''}</span>
        )}
        
        <button 
          onClick={() => setShowReplyInput(!showReplyInput)}
          className="hover:opacity-80 font-medium"
          data-testid={`reply-btn-${comment.id}`}
        >
          Reply
        </button>
        
        <div className="relative ml-auto">
          <button
            onClick={() => viewerReaction ? handleReaction(viewerReaction) : handleReaction('❤️')}
            onContextMenu={(e) => { e.preventDefault(); setShowReactionPicker(true); }}
            disabled={loading}
            className={`p-1 rounded transition-all ${
              viewerReaction ? 'text-red-500' : `${textSecondaryClass} hover:text-red-400`
            } ${loading ? 'opacity-50' : ''}`}
            data-testid={`comment-like-${comment.id}`}
          >
            {viewerReaction && viewerReaction !== '❤️' ? (
              <span className="text-sm">{viewerReaction}</span>
            ) : (
              <Heart className="w-3.5 h-3.5" fill={viewerReaction ? 'currentColor' : 'none'} />
            )}
          </button>
          
          {showReactionPicker && (
            <>
              <div className="fixed inset-0 z-40" onClick={() => setShowReactionPicker(false)} />
              <div 
                className={`absolute bottom-full right-0 mb-1 flex gap-1 p-1.5 rounded-full shadow-lg z-50 ${
                  isLight ? 'bg-white border border-gray-200' : 'bg-zinc-800 border border-zinc-700'
                }`}
                style={{ maxWidth: 'calc(100vw - 32px)', overflowX: 'auto', WebkitOverflowScrolling: 'touch' }}
              >
                {REACTION_EMOJIS.map((emoji) => (
                  <button
                    key={emoji}
                    onClick={() => handleReaction(emoji)}
                    className={`w-7 h-7 flex-shrink-0 flex items-center justify-center text-base hover:scale-125 transition-transform rounded-full ${
                      viewerReaction === emoji ? isLight ? 'bg-blue-100' : 'bg-blue-900/30' : ''
                    }`}
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
      
      {/* Reply Input */}
      {showReplyInput && (
        <div className="mt-2 ml-6 flex gap-2" data-testid={`reply-input-container-${comment.id}`}>
          <input
            type="text"
            value={replyContent}
            onChange={(e) => setReplyContent(e.target.value)}
            placeholder={`Reply to ${comment.author_name}...`}
            className={`flex-1 text-sm px-3 py-1.5 rounded-full ${
              isLight ? 'bg-gray-100 border border-gray-200 text-gray-900' : 'bg-zinc-800 border border-zinc-700 text-white'
            } focus:outline-none focus:ring-1 focus:ring-blue-500`}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey && replyContent.trim()) {
                e.preventDefault();
                handleSubmitReply();
              }
            }}
            data-testid={`reply-input-${comment.id}`}
          />
          <button
            onClick={handleSubmitReply}
            disabled={!replyContent.trim() || submittingReply}
            className={`px-3 py-1.5 text-sm font-medium rounded-full transition-colors ${
              replyContent.trim() ? 'bg-blue-500 text-white hover:bg-blue-600' : 'bg-zinc-700 text-gray-400 cursor-not-allowed'
            }`}
            data-testid={`reply-submit-${comment.id}`}
          >
            {submittingReply ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Post'}
          </button>
        </div>
      )}
      
      {/* View/Hide Replies Toggle */}
      {replyCount > 0 && !showReplies && (
        <button
          onClick={() => setShowReplies(true)}
          className={`mt-2 ml-6 text-xs ${textSecondaryClass} hover:opacity-80 flex items-center gap-1`}
        >
          <span className="w-6 h-px bg-current opacity-50" />
          View {replyCount} {replyCount === 1 ? 'reply' : 'replies'}
        </button>
      )}
      
      {/* Replies - Use simple ReplyItem instead of recursive CommentWithReaction */}
      {showReplies && localReplies.length > 0 && (
        <div className="mt-2 space-y-2">
          {localReplies.length > 0 && (
            <button
              onClick={() => setShowReplies(false)}
              className={`ml-6 text-xs ${textSecondaryClass} hover:opacity-80 flex items-center gap-1`}
            >
              <span className="w-6 h-px bg-current opacity-50" />
              Hide replies
            </button>
          )}
          {localReplies.map((reply) => (
            <ReplyItem
              key={reply.id}
              reply={reply}
              userId={userId}
              postId={postId}
              textPrimaryClass={textPrimaryClass}
              textSecondaryClass={textSecondaryClass}
              isLight={isLight}
            />
          ))}
        </div>
      )}
    </div>
  );
};

// Role badge component for post authors
const RoleBadge = ({ role }) => {
  const roleInfo = getExpandedRoleInfo(role);
  return (
    <span className={`text-sm ${roleInfo.color}`} title={roleInfo.label}>
      {roleInfo.icon}
    </span>
  );
};

// Reaction icon component - Shows user's reaction or default Shaka
const ReactionIcon = ({ post, userId, isLiked, isPressing }) => {
  const userReaction = post.reactions?.find(r => r.user_id === userId);
  const hasNonShakaReaction = userReaction && userReaction.emoji !== '🤙';
  
  // Determine if Shaka should be colored (checked) or grayscale (unchecked)
  // Also show colored when pressing (holding down) for visual feedback
  const shakaIsChecked = (isLiked && !hasNonShakaReaction) || isPressing;
  
  const springTransition = 'all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
  
  // Prevent browser context menu on long-press
  const preventContextMenu = (e) => {
    e.preventDefault();
    e.stopPropagation();
    return false;
  };
  
  return (
    <div 
      className="relative w-7 h-7 flex items-center justify-center overflow-visible"
      style={{ transition: springTransition }}
      onContextMenu={preventContextMenu}
    >
      {hasNonShakaReaction ? (
        <span 
          key={userReaction.emoji}
          className="text-2xl animate-in zoom-in-75 duration-300 select-none"
          style={{ 
            filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.3))',
            transform: 'scale(1.1)',
            transition: springTransition,
            WebkitTouchCallout: 'none',
            WebkitUserSelect: 'none',
            userSelect: 'none',
            pointerEvents: 'none'
          }}
          onContextMenu={preventContextMenu}
        >
          {userReaction.emoji}
        </span>
      ) : (
        <img 
          key={shakaIsChecked ? "shaka-checked" : "shaka-unchecked"}
          src="https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/svg/1f919.svg"
          alt="shaka"
          className="animate-in zoom-in-75 duration-300 select-none"
          style={{ 
            width: '28px', 
            height: '28px',
            filter: shakaIsChecked ? 'none' : 'grayscale(100%) brightness(0.8)',
            opacity: shakaIsChecked ? 1 : 0.7,
            transform: isPressing ? 'scale(1.15)' : 'scale(1)',
            transition: springTransition,
            WebkitTouchCallout: 'none',
            WebkitUserSelect: 'none',
            userSelect: 'none',
            pointerEvents: 'none'
          }}
          draggable={false}
          onContextMenu={preventContextMenu}
          onDragStart={(e) => e.preventDefault()}
        />
      )}
    </div>
  );
};

// Shaka icon using Twemoji image for consistent rendering
const _ShakaIcon = ({ filled }) => (
  <img 
    src="https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/svg/1f919.svg"
    alt="shaka"
    style={{ 
      width: '28px', 
      height: '28px',
      filter: filled ? 'none' : 'grayscale(100%) brightness(0.8)',
      opacity: filled ? 1 : 0.7,
      transition: 'filter 0.2s ease, opacity 0.2s ease'
    }}
    draggable="false"
  />
);



const PostCard = ({
  post,
  user,
  isLight,
  textPrimaryClass,
  textSecondaryClass,
  borderClass,
  postCardBgClass,
  liveUsers,
  connectingToStream,
  followingUsers,
  commentInputs,
  showAllComments,
  allComments,
  loadingComments,
  isPressing,  // Track if shaka is being pressed for visual feedback
  onNavigateProfile,
  onPostMenuOpen,
  onSharePost,
  onSavePost,
  onLikeStart,
  onLikeEnd,
  onLikeLeave,
  onCommentChange,
  onCommentSubmit,
  onLoadAllComments,
  onHideAllComments,
  onJoinLive,
  onIWasThere,
  onViewCollaborators,
  onFollowFromFeed,
  onImageClick  // Opens Instagram-style modal
}) => {
  const navigate = useNavigate();
  
  // Who Reacted Modal state
  const [showWhoReacted, setShowWhoReacted] = useState(false);
  const [detailedReactions, setDetailedReactions] = useState([]);
  const [loadingReactions, setLoadingReactions] = useState(false);

  // Video Autoplay Setup
  const videoRef = useRef(null);
  const programmaticTarget = useRef(false);
  const [userManuallyPaused, setUserManuallyPaused] = useState(false);
  // Track if video source failed to load (dead ephemeral URL or network error)
  const [videoError, setVideoError] = useState(false);
  // Mute state for in-feed video (defaults muted for autoplay)
  const [isMuted, setIsMuted] = useState(true);
  const [videoVolume, setVideoVolume] = useState(0.7);
  const [showVolSlider, setShowVolSlider] = useState(false);
  const volTimerRef = useRef(null);
  // Track if video is currently playing (for play/pause overlay)
  const [isPlaying, setIsPlaying] = useState(false);

  // Double-tap to like state
  const [showDoubleTapHeart, setShowDoubleTapHeart] = useState(false);
  const lastTapRef = useRef(0);
  const singleTapTimerRef = useRef(null);

  const handleMediaTap = useCallback((e) => {
    const now = Date.now();
    if (now - lastTapRef.current < 300) {
      // Double tap detected — cancel pending single tap, trigger like
      if (singleTapTimerRef.current) {
        clearTimeout(singleTapTimerRef.current);
        singleTapTimerRef.current = null;
      }
      e.stopPropagation();
      e.preventDefault();
      if (user?.id && post?.id && onLikeStart) {
        onLikeStart(post, e);
        setTimeout(() => onLikeEnd && onLikeEnd(post, e), 50);
      }
      setShowDoubleTapHeart(true);
      setTimeout(() => setShowDoubleTapHeart(false), 800);
      lastTapRef.current = 0;
    } else {
      lastTapRef.current = now;
      // Delay single tap to allow double tap detection
      singleTapTimerRef.current = setTimeout(() => {
        onImageClick && onImageClick(post);
        singleTapTimerRef.current = null;
      }, 300);
    }
  }, [user?.id, post?.id, onLikeStart, onLikeEnd, onImageClick, post]);

  // Helper to ensure media paths map to backend directly natively preventing Netlify 404 traps
  const _checkMediaUrl = getFullUrl(post?.media_url || post?.image_url);
  const isVideoItem = post?.media_type === 'video' || (typeof _checkMediaUrl === 'string' && _checkMediaUrl.match(/\.(mp4|webm|ogg|mov)(\?.*)?$/i));

  // Local /api/uploads/ paths are served by the backend and are valid during normal operation.
  // Always render the full video player and let the onError handler deal with broken URLs.
  const isDeadLocalVideo = false;

  useEffect(() => {
    if (!isVideoItem || !videoRef.current) return;

    const currentVideo = videoRef.current;
    currentVideo.muted = true; // Secure modern browsers autoplay policy

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            // Autoplay only if user hasn't explicitly disabled playback on this specific video
            if (!userManuallyPaused) {
              programmaticTarget.current = true;
              currentVideo.play().catch(() => {}).finally(() => {
                programmaticTarget.current = false;
              });
            }
          } else {
            // Safely stall video sequentially on viewport exit
            if (!currentVideo.paused) {
              programmaticTarget.current = true;
              currentVideo.pause();
              programmaticTarget.current = false;
            }
          }
        });
      },
      { threshold: 0.6 } // Fire intersection only when heavily visible to avoid buffer overlaps
    );

    observer.observe(currentVideo);
    return () => observer.disconnect();
  }, [isVideoItem, userManuallyPaused]);

  if (!post) return null;
  
  // Fetch detailed reactions when modal opens
  const handleLikesCountClick = async (e) => {
    e.preventDefault();
    e.stopPropagation();
    setShowWhoReacted(true);
    
    // Fetch detailed data
    setLoadingReactions(true);
    try {
      const response = await apiClient.get(`/posts/${post.id}/reactions-detail`);
      // Combine likers and reactors for full list
      const allReactors = [
        ...(response.data.all_reactors || []).map(r => ({
          user_id: r.user_id,
          user_name: r.full_name,
          avatar_url: r.avatar_url,
          user_role: r.role,
          emoji: r.emoji
        })),
        ...(response.data.likers || []).map(l => ({
          user_id: l.user_id,
          user_name: l.full_name,
          avatar_url: l.avatar_url,
          user_role: l.role,
          emoji: '❤️'
        }))
      ];
      setDetailedReactions(allReactors);
    } catch (err) {
      // Fallback to inline data
      setDetailedReactions(post.reactions || []);
    } finally {
      setLoadingReactions(false);
    }
  };

  // Video URL resolution — extracted here to keep JSX clean (no IIFE needed)
  const videoSrc = isVideoItem ? getFullUrl(post.media_url) : null;
  const videoPoster = isVideoItem ? getFullUrl(post.thumbnail_url) : null;
  const videoMimeType = (() => {
    if (!post.media_url) return 'video/mp4';
    const ext = post.media_url.split('?')[0].split('.').pop().toLowerCase();
    return { mp4: 'video/mp4', mov: 'video/mp4', webm: 'video/webm', ogv: 'video/ogg' }[ext] || 'video/mp4';
  })();

  // Determine thumbnail fallback URL (show image instead of broken video player)
  const videoFallbackSrc = getFullUrl(post.thumbnail_url || post.media_url);

  return (
    <>
    <article 
      className={`${postCardBgClass} transition-colors duration-300 ${
        post.is_check_in ? 'border-l-4 border-l-cyan-500' : ''
      }`} 
      data-testid={`post-card-${post.id}`}
    >
      {/* Check-In Banner */}
      {post.is_check_in && (
        <div className="bg-gradient-to-r from-cyan-500/20 via-blue-500/10 to-transparent px-4 py-2 flex items-center gap-2">
          <div className="w-6 h-6 bg-cyan-500 rounded-full flex items-center justify-center">
            <MapPin className="w-3 h-3 text-white" />
          </div>
          <span className="text-cyan-400 font-medium text-sm">Jumped In</span>
          {post.check_in_spot_name && (
            <span className="text-zinc-400 text-sm">at {post.check_in_spot_name}</span>
          )}
          {post.check_in_conditions && (
            <span className="text-zinc-500 text-xs ml-auto">{post.check_in_conditions}</span>
          )}
        </div>
      )}
      
      {/* Post Header */}
      <div className="flex items-center justify-between p-4">
        <div 
          className="flex items-center gap-3 cursor-pointer"
          onClick={() => onNavigateProfile(post.author_id)}
          data-testid={`post-author-${post.id}`}
        >
          {/* Avatar with LIVE ring indicator */}
          <div className="relative">
            <div className={`${liveUsers.includes(post.author_id) ? 'p-[2px] rounded-full bg-gradient-to-r from-red-500 via-red-600 to-red-500 animate-pulse' : ''}`}>
              <div className={`w-10 h-10 rounded-full ${isLight ? 'bg-gray-200' : 'bg-zinc-700'} ${liveUsers.includes(post.author_id) ? 'border-2 border-black' : ''} flex items-center justify-center overflow-hidden`}>
                {post.author_avatar ? (
                  <img 
                    src={getFullUrl(post.author_avatar)} 
                    alt={post.author_name} 
                    className="w-full h-full object-cover"
                    onError={(e) => { e.target.style.display = 'none'; }}
                  />
                ) : (
                  <span className={textSecondaryClass + " font-medium"}>
                    {post.author_name?.charAt(0) || '?'}
                  </span>
                )}
              </div>
            </div>
            {/* LIVE badge */}
            {liveUsers.includes(post.author_id) && (
              <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 bg-red-500 text-white text-[7px] font-bold px-1.5 py-0.5 rounded uppercase">
                LIVE
              </div>
            )}
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              {/* Instagram-style: username primary, real name secondary */}
              {post.author_username ? (
                <span className={`font-semibold ${textPrimaryClass} hover:underline`}>@{post.author_username}</span>
              ) : (
                <span className={`font-medium ${textPrimaryClass} hover:underline`}>{post.author_name || 'Anonymous'}</span>
              )}
              {post.author_role && <RoleBadge role={post.author_role} />}
              {/* Join Live button with connecting pulse */}
              {liveUsers.includes(post.author_id) && (
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onJoinLive(post.author_id, post.author_name, post.author_avatar);
                  }}
                  disabled={connectingToStream === post.author_id}
                  className={`ml-2 flex items-center gap-1 px-2 py-0.5 text-white text-xs font-bold rounded-full transition-all ${
                    connectingToStream === post.author_id 
                      ? 'bg-red-400 scale-105 animate-[pulse_0.5s_ease-in-out_infinite]' 
                      : 'bg-red-500 hover:bg-red-600 animate-pulse'
                  }`}
                  data-testid={`join-live-${post.id}`}
                >
                  <Radio className={`w-3 h-3 ${connectingToStream === post.author_id ? 'animate-spin' : ''}`} />
                  {connectingToStream === post.author_id ? 'Joining...' : 'Join'}
                </button>
              )}
            </div>
          {/* Timestamp + location row */}
          <p className={`text-xs ${textSecondaryClass} flex items-center gap-1`}>
            {post.created_at && (
              <span>{formatTimeAgo(post.created_at)}</span>
            )}
            {post.location && post.created_at && (
              <span className="opacity-50">·</span>
            )}
            {post.location && (
              <span>{post.location}</span>
            )}
          </p>
        </div>
        </div>
        <button 
          onClick={() => onPostMenuOpen(post)}
          className={`${textSecondaryClass} hover:${textPrimaryClass} p-2`}
          data-testid={`post-menu-btn-${post.id}`}
        >
          <MoreHorizontal className="w-5 h-5" />
        </button>
      </div>

      {/* Shop This Photographer's Work CTA - for verified photographers */}
      {['Photographer', 'Approved Pro'].includes(post.author_role) && post.author_id !== user?.id && (
        <div className="px-4 py-2 border-b border-border/50">
          <button
            onClick={() => navigate(`/photographer/${post.author_id}/gallery`)}
            className="w-full flex items-center justify-center gap-2 py-2 px-4 rounded-lg bg-gradient-to-r from-amber-500/10 to-yellow-500/10 hover:from-amber-500/20 hover:to-yellow-500/20 border border-amber-500/30 transition-all group"
            data-testid={`shop-photographer-${post.id}`}
          >
            <ShoppingBag className="w-4 h-4 text-amber-500 group-hover:scale-110 transition-transform" />
            <span className="text-sm font-medium text-amber-600 dark:text-amber-400">
              Shop {post.author_username ? `@${post.author_username}` : post.author_name}'s Gallery
            </span>
            <ChevronRight className="w-4 h-4 text-amber-500/70" />
          </button>
        </div>
      )}

      {/* Post Image/Video - click to open modal, double-tap to like */}
      <div 
        className={`aspect-[4/5] ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} relative select-none cursor-pointer`}
        onClick={handleMediaTap}
        data-testid={`post-image-container-${post.id}`}
      >
        {/* Double-tap shaka animation */}
        {showDoubleTapHeart && (
          <div className="absolute inset-0 flex items-center justify-center z-20 pointer-events-none">
            <img 
              src="https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/svg/1f919.svg"
              alt="shaka"
              className="w-24 h-24 animate-ping"
              style={{ animationDuration: '0.6s', filter: 'drop-shadow(0 4px 12px rgba(234, 179, 8, 0.5))' }}
              draggable={false}
            />
          </div>
        )}
        {isVideoItem ? (
          // If video source errored (404 / network failure), show fallback
          (isDeadLocalVideo || videoError) ? (
            <div className="relative w-full h-full flex flex-col items-center justify-center bg-gradient-to-br from-zinc-800 to-zinc-900">
              <Play className="w-12 h-12 text-zinc-500 mb-2" />
              <span className="text-zinc-400 text-sm font-medium">Video Unavailable</span>
              <span className="text-zinc-500 text-xs mt-1">This video is no longer accessible</span>
              {/* Retry button — clears error to re-attempt load */}
              {videoError && !isDeadLocalVideo && (
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setVideoError(false);
                    // Force a fresh network fetch by appending cache-bust param
                    if (videoRef.current) {
                      const src = videoRef.current.querySelector('source');
                      if (src) {
                        const url = new URL(src.src, window.location.origin);
                        url.searchParams.set('_retry', Date.now());
                        src.src = url.toString();
                      }
                      videoRef.current.load();
                    }
                  }}
                  className="mt-3 flex items-center gap-1.5 px-4 py-2 rounded-lg bg-zinc-700 hover:bg-zinc-600 text-zinc-300 text-sm font-medium transition-colors"
                  data-testid={`video-retry-${post.id}`}
                >
                  <RefreshCw className="w-4 h-4" />
                  Tap to retry
                </button>
              )}
              {/* Video duration badge */}
              <div className="absolute top-2 right-2 bg-black/70 px-2 py-1 rounded text-xs text-white flex items-center gap-1">
                <Play className="w-3 h-3" />
                {post.video_duration ? `${Math.round(post.video_duration)}s` : 'Video'}
              </div>
            </div>
          ) : (
          /* TikTok/Instagram pattern: video plays as muted preview in feed.
             NO native controls — tapping opens PostModal for social interaction.
             Mute toggle is a separate button that stops propagation. */
          <>
          <video
            ref={videoRef}
            poster={videoPoster}
            className="w-full h-full object-cover"
            playsInline
            webkit-playsinline="true"
            preload="none"
            muted={isMuted}
            autoPlay
            loop
            onPlay={() => {
              setIsPlaying(true);
              if (!programmaticTarget.current) setUserManuallyPaused(false);
            }}
            onPause={() => {
              setIsPlaying(false);
              if (!programmaticTarget.current) setUserManuallyPaused(true);
            }}
            onError={() => setVideoError(true)}
          >
            <source src={videoSrc} type={videoMimeType} onError={() => setVideoError(true)} />
            {videoMimeType !== 'video/mp4' && <source src={videoSrc} type="video/mp4" onError={() => setVideoError(true)} />}
          </video>
          {/* Transparent click overlay — ensures tap opens PostModal, not native player */}
          <div className="absolute inset-0 z-[1]" />
          {/* Centered play icon — shows when paused (tap to open modal, not to play) */}
          {!isPlaying && (
            <div className="absolute inset-0 z-[2] flex items-center justify-center pointer-events-none">
              <div className="w-16 h-16 rounded-full bg-black/50 backdrop-blur-sm flex items-center justify-center">
                <Play className="w-8 h-8 text-white ml-1" fill="white" />
              </div>
            </div>
          )}
          {/* Volume control — bottom-right, progressive disclosure (stops propagation so it doesn't open modal) */}
          <div
            className="absolute bottom-3 right-3 z-[3] flex items-center gap-1"
            onClick={(e) => e.stopPropagation()}
            onMouseEnter={() => {
              setShowVolSlider(true);
              if (volTimerRef.current) clearTimeout(volTimerRef.current);
            }}
            onMouseLeave={() => {
              volTimerRef.current = setTimeout(() => setShowVolSlider(false), 1200);
            }}
          >
            {/* Horizontal slider — appears to the left of the icon */}
            <div
              className="overflow-hidden transition-all duration-300 ease-out flex items-center"
              style={{
                width: showVolSlider ? '60px' : '0px',
                opacity: showVolSlider ? 1 : 0,
              }}
            >
              <input
                type="range"
                min="0"
                max="1"
                step="0.05"
                value={isMuted ? 0 : videoVolume}
                onChange={(e) => {
                  e.stopPropagation();
                  const newVol = parseFloat(e.target.value);
                  setVideoVolume(newVol);
                  if (videoRef.current) {
                    videoRef.current.volume = newVol;
                    if (newVol === 0) {
                      setIsMuted(true);
                      videoRef.current.muted = true;
                    } else if (isMuted) {
                      setIsMuted(false);
                      videoRef.current.muted = false;
                    }
                  }
                  if (volTimerRef.current) clearTimeout(volTimerRef.current);
                  volTimerRef.current = setTimeout(() => setShowVolSlider(false), 2000);
                }}
                onClick={(e) => e.stopPropagation()}
                className="w-full h-1 appearance-none rounded-full cursor-pointer"
                aria-label="Volume"
                style={{
                  background: `linear-gradient(to right, rgba(255,255,255,0.9) ${(isMuted ? 0 : videoVolume) * 100}%, rgba(255,255,255,0.25) ${(isMuted ? 0 : videoVolume) * 100}%)`,
                }}
              />
            </div>
            <button
              onClick={(e) => {
                e.stopPropagation();
                const newMuted = !isMuted;
                setIsMuted(newMuted);
                if (videoRef.current) {
                  videoRef.current.muted = newMuted;
                  if (!newMuted) videoRef.current.volume = videoVolume;
                }
                setShowVolSlider(true);
                if (volTimerRef.current) clearTimeout(volTimerRef.current);
                volTimerRef.current = setTimeout(() => setShowVolSlider(false), 2000);
              }}
              className="w-8 h-8 rounded-full bg-black/60 backdrop-blur-sm flex items-center justify-center text-white hover:bg-black/80 transition-colors"
              data-testid={`video-mute-${post.id}`}
              aria-label={isMuted ? 'Unmute' : 'Mute'}
            >
              {isMuted || videoVolume === 0 ? <VolumeX className="w-4 h-4" /> : videoVolume < 0.5 ? <Volume1 className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
            </button>
          </div>
          </>
          )
        ) : (
          <img
            src={getFullUrl(post.media_url || post.image_url)}
            alt={post.caption || 'Surf photo'}
            className="w-full h-full object-cover"
            loading="lazy"
            draggable="false"
            onError={(e) => { e.target.style.display = 'none'; }}
          />
        )}
        {isVideoItem && !(isDeadLocalVideo || videoError) && (
          <div className="absolute top-2 right-2 z-[2] bg-black/60 px-2 py-1 rounded text-xs text-white flex items-center gap-1 pointer-events-none">
            <Play className="w-3 h-3" />
            {post.video_duration ? `${Math.round(post.video_duration)}s` : 'Video'}
          </div>
        )}
      </div>

      {/* Session Log Header - "Strava for Surfing" metadata */}
      {(post.session_date || post.session_start_time || post.location || post.spot || 
        post.wave_height_ft || post.collaborators?.length > 0) && (
        <div className="px-4 pt-2">
          <SessionLogHeader
            post={post}
            collaborators={post.collaborators || []}
            currentUserId={user?.id}
            isOwnPost={post.author_id === user?.id}
            onIWasThere={() => onIWasThere(post.id)}
            onViewCollaborators={() => onViewCollaborators(post.id)}
            showBookCTA={['Photographer', 'Approved Pro'].includes(post.author_role) && post.author_id !== user?.id}
            isFollowingPhotographer={followingUsers.has(post.author_id)}
            photographerId={post.author_id}
            photographerName={post.author_name}
            onFollowPhotographer={onFollowFromFeed}
            onBookPhotographer={(photographerId) => navigate(`/profile/${photographerId}`)}
          />
        </div>
      )}

      {/* Post Actions */}
      <div className="p-4">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-4 relative">
            {/* Shaka Button with count next to it - Instagram style */}
            <div className="flex items-center gap-1.5">
              <button
                onTouchStart={(e) => {
                  e.preventDefault();
                  onLikeStart(post.id, e);
                }}
                onTouchEnd={(e) => {
                  e.preventDefault();
                  onLikeEnd(post.id, e);
                }}
                onTouchCancel={(e) => {
                  e.preventDefault();
                  onLikeLeave();
                }}
                onMouseDown={(e) => onLikeStart(post.id, e)}
                onMouseUp={(e) => onLikeEnd(post.id, e)}
                onMouseLeave={onLikeLeave}
                onClick={(e) => {
                  // Prevent default click - we handle everything via touch/mouse events
                  e.preventDefault();
                  e.stopPropagation();
                }}
                onContextMenu={(e) => {
                  // Prevent browser context menu on long-press
                  e.preventDefault();
                  e.stopPropagation();
                  return false;
                }}
                className={`transition-all duration-300 select-none transform touch-manipulation ${
                  post.liked || post.reactions?.some(r => r.user_id === user?.id) || isPressing
                    ? 'scale-110' 
                    : 'hover:scale-105'
                }`}
                style={{
                  transition: 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)',
                  WebkitTouchCallout: 'none',
                  WebkitUserSelect: 'none',
                  userSelect: 'none',
                  WebkitTapHighlightColor: 'transparent'
                }}
                data-testid={`like-btn-${post.id}`}
                title="Tap to like, hold for reactions"
              >
                <ReactionIcon post={post} userId={user?.id} isLiked={post.liked} isPressing={isPressing} />
              </button>
              {/* Count next to shaka - Click to see who reacted */}
              {!post.hide_like_count && post.likes_count > 0 && (
                <button
                  onClick={handleLikesCountClick}
                  className={`font-semibold ${textPrimaryClass} text-sm hover:opacity-70 transition-opacity select-none cursor-pointer`}
                  data-testid={`likes-count-${post.id}`}
                  title="Click to see who reacted"
                >
                  {post.likes_count.toLocaleString()}
                </button>
              )}
            </div>
            {/* Comment button - hidden if comments are disabled */}
            {!post.comments_disabled && (
              <button 
                className={`${textPrimaryClass} hover:${textSecondaryClass} transition-colors`}
                onClick={() => {
                  const input = document.querySelector(`[data-testid="comment-input-${post.id}"]`);
                  if (input) input.focus();
                }}
                data-testid={`comment-btn-${post.id}`}
              >
                <MessageCircle className="w-6 h-6" />
              </button>
            )}
            <button 
              className={`${textPrimaryClass} hover:${textSecondaryClass} transition-colors`}
              onClick={() => onSharePost(post)}
              data-testid={`share-btn-${post.id}`}
            >
              <Send className="w-6 h-6" />
            </button>
          </div>
          <button 
            onClick={(e) => {
              e.preventDefault();
              onSavePost(post.id, post.saved);
            }}
            className={`transition-colors touch-manipulation ${post.saved ? 'text-yellow-400' : `${textPrimaryClass} hover:${textSecondaryClass}`}`}
            style={{ WebkitTapHighlightColor: 'transparent' }}
            data-testid={`save-btn-${post.id}`}
          >
            <Bookmark className="w-6 h-6" fill={post.saved ? 'currentColor' : 'none'} />
          </button>
        </div>

        {/* Caption */}
        <p className={textPrimaryClass}>
          <span 
            className="font-medium cursor-pointer hover:underline"
            onClick={(e) => {
              e.stopPropagation();
              navigate(`/profile/${post.author_id}`);
            }}
          >
            {post.author_name}
          </span>{' '}
          <RichText 
            text={post.caption}
            className={textSecondaryClass}
            maxLength={150}
            showExpand={true}
          />
        </p>

        {/* Session Join Card - Show if post is a shared session with open spots */}
        {post.is_session_log && post.session_invite_open && post.session_spots_left > 0 && (
          <SessionJoinCard
            post={post}
            user={user}
            isLight={isLight}
          />
        )}

        {/* Comments Section */}
        <div className="mt-3 space-y-2">
          {/* View all comments link */}
          {(post.comments_count > 0) && !showAllComments[post.id] && (
            <button 
              onClick={() => onLoadAllComments(post.id)}
              className={`${textSecondaryClass} text-sm hover:opacity-80`}
              data-testid={`view-comments-${post.id}`}
            >
              {loadingComments[post.id] ? (
                <span className="flex items-center gap-1">
                  <Loader2 className="w-3 h-3 animate-spin" /> Loading...
                </span>
              ) : (
                `View all ${post.comments_count} comment${post.comments_count !== 1 ? 's' : ''}`
              )}
            </button>
          )}

          {/* Show all comments when expanded */}
          {showAllComments[post.id] && allComments[post.id] && (
            <div className="space-y-3">
              <button 
                onClick={() => onHideAllComments(post.id)}
                className={`${textSecondaryClass} text-sm hover:opacity-80`}
              >
                Hide comments
              </button>
              {allComments[post.id].map((comment) => (
                <CommentWithReaction
                  key={comment.id}
                  comment={comment}
                  userId={user?.id}
                  postId={post.id}
                  textPrimaryClass={textPrimaryClass}
                  textSecondaryClass={textSecondaryClass}
                  isLight={isLight}
                />
              ))}
            </div>
          )}

          {/* Show recent comments inline (when not expanded) - click to expand */}
          {!showAllComments[post.id] && post.recent_comments && post.recent_comments.length > 0 && (
            <div className="space-y-1">
              {post.recent_comments.map((comment) => (
                <div 
                  key={comment.id} 
                  className="flex gap-2 cursor-pointer hover:opacity-80"
                  onClick={() => onLoadAllComments(post.id)}
                  title="Click to view all comments and reply"
                >
                  <span className={`font-medium ${textPrimaryClass} text-sm cursor-pointer hover:underline`}
                    onClick={(e) => { e.stopPropagation(); navigate(`/profile/${comment.author_id}`); }}>
                    {comment.author_name}
                  </span>
                  <span className={`${textSecondaryClass} text-sm flex-1 truncate`}>{comment.content}</span>
                </div>
              ))}
              <button 
                onClick={() => onLoadAllComments(post.id)}
                className={`${textSecondaryClass} text-xs hover:opacity-80 mt-1`}
              >
                Click to reply...
              </button>
            </div>
          )}
        </div>

        {/* Comment Input with Emoji Picker - hidden if comments are disabled */}
        {!post.comments_disabled && (
          <div className="mt-3">
            <CommentInputWithEmoji
              value={commentInputs[post.id] || ''}
              onChange={(val) => onCommentChange(post.id, val)}
              onSubmit={() => onCommentSubmit(post.id)}
              placeholder="Add a comment..."
              postId={post.id}
              textClass={textSecondaryClass}
              borderClass={borderClass}
            />
          </div>
        )}
        
        {/* Comments disabled message */}
        {post.comments_disabled && (
          <p className={`text-xs ${textSecondaryClass} mt-3 italic`}>
            Comments are turned off for this post.
          </p>
        )}
      </div>
    </article>
    
    {/* Who Reacted Modal */}
    <WhoReactedModal
      isOpen={showWhoReacted}
      onClose={() => setShowWhoReacted(false)}
      reactions={detailedReactions.length > 0 ? detailedReactions : (post.reactions || [])}
      postAuthorName={post.author_name}
      loading={loadingReactions}
    />
    </>
  );
};

export default PostCard;

/**
 * PostModal - Instagram-style post popup with image on left, details on right
 * Opens when clicking on a post in the feed
 */
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { X, ChevronLeft, ChevronRight, Heart, MessageCircle, Send, Bookmark, MoreHorizontal, Loader2, Calendar, Waves, Play, Pause, Volume2, Volume1, VolumeX, Smile } from 'lucide-react';
import { toast } from 'sonner';
import { RichText, CommentText } from './RichText';
import { SharePostModal } from './PostMenu';
import PostMenu from './PostMenu';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';
import { formatTimeAgo, formatDuration } from '../utils/formatTime';
import { REACTION_EMOJIS } from '../constants/emojis';
import EmojiPicker from './EmojiPicker';


// Reaction emojis — imported from centralized constants/emojis.js

// Shaka Icon Component
const ShakaIcon = ({ filled, size = 28 }) => (
  <img 
    src="https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/svg/1f919.svg"
    alt="shaka"
    style={{ 
      width: `${size}px`, 
      height: `${size}px`,
      filter: filled ? 'none' : 'grayscale(100%) brightness(1.5)',
      transition: 'filter 0.2s ease, transform 0.2s ease'
    }}
    draggable="false"
  />
);



// Custom Video Player for PostModal — TikTok/Instagram style
// Tap to play/pause, custom progress bar, volume slider, no native controls
const ModalVideoPlayer = ({ src, poster, className = '' }) => {
  const videoRef = useRef(null);
  const progressRef = useRef(null);
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(true);
  const [volume, setVolume] = useState(0.7); // 0-1 range
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTimeState] = useState(0);
  const [showControls, setShowControls] = useState(true);
  const hideTimerRef = useRef(null);
  const volumeTimerRef = useRef(null);

  // Auto-play when mounted
  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.muted = true; // Required for autoplay
      videoRef.current.play().then(() => {
        setPlaying(true);
        setMuted(true);
      }).catch(() => {});
    }
    return () => {
      if (hideTimerRef.current) clearTimeout(hideTimerRef.current);
      if (volumeTimerRef.current) clearTimeout(volumeTimerRef.current);
    };
  }, [src]);

  // Update progress bar
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    const onTimeUpdate = () => {
      setProgress(video.duration ? (video.currentTime / video.duration) * 100 : 0);
      setCurrentTimeState(video.currentTime);
    };
    const onLoaded = () => setDuration(video.duration || 0);
    video.addEventListener('timeupdate', onTimeUpdate);
    video.addEventListener('loadedmetadata', onLoaded);
    return () => {
      video.removeEventListener('timeupdate', onTimeUpdate);
      video.removeEventListener('loadedmetadata', onLoaded);
    };
  }, []);

  const togglePlay = (e) => {
    e.stopPropagation();
    if (!videoRef.current) return;
    if (playing) {
      videoRef.current.pause();
      setPlaying(false);
    } else {
      videoRef.current.play().catch(() => {});
      setPlaying(true);
    }
    // Show controls briefly then auto-hide
    setShowControls(true);
    if (hideTimerRef.current) clearTimeout(hideTimerRef.current);
    hideTimerRef.current = setTimeout(() => setShowControls(false), 2500);
  };

  const toggleMute = (e) => {
    e.stopPropagation();
    if (!videoRef.current) return;
    const newMuted = !muted;
    videoRef.current.muted = newMuted;
    if (!newMuted) {
      videoRef.current.volume = volume;
    }
    setMuted(newMuted);
  };

  const handleVolumeChange = (e) => {
    e.stopPropagation();
    const newVolume = parseFloat(e.target.value);
    setVolume(newVolume);
    if (videoRef.current) {
      videoRef.current.volume = newVolume;
      if (newVolume === 0) {
        setMuted(true);
        videoRef.current.muted = true;
      } else if (muted) {
        setMuted(false);
        videoRef.current.muted = false;
      }
    }
    // Keep slider visible while interacting
    if (volumeTimerRef.current) clearTimeout(volumeTimerRef.current);
    volumeTimerRef.current = setTimeout(() => setShowVolumeSlider(false), 2000);
  };

  const handleVolumeAreaEnter = () => {
    setShowVolumeSlider(true);
    if (volumeTimerRef.current) clearTimeout(volumeTimerRef.current);
  };

  const handleVolumeAreaLeave = () => {
    volumeTimerRef.current = setTimeout(() => setShowVolumeSlider(false), 1200);
  };

  // Get appropriate volume icon
  const VolumeIcon = muted || volume === 0 ? VolumeX : volume < 0.5 ? Volume1 : Volume2;

  const handleSeek = (e) => {
    e.stopPropagation();
    if (!videoRef.current || !progressRef.current) return;
    const rect = progressRef.current.getBoundingClientRect();
    const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    videoRef.current.currentTime = ratio * videoRef.current.duration;
  };

  const formatTime = formatDuration;

  return (
    <div
      className={`relative w-full h-full bg-black flex items-center justify-center group ${className}`}
      onClick={togglePlay}
      onMouseMove={() => {
        setShowControls(true);
        if (hideTimerRef.current) clearTimeout(hideTimerRef.current);
        hideTimerRef.current = setTimeout(() => setShowControls(false), 2500);
      }}
    >
      <video
        ref={videoRef}
        src={src}
        poster={poster}
        className="max-w-full max-h-full object-contain"
        playsInline
        webkit-playsinline="true"
        loop
        muted={muted}
        preload="metadata"
      />

      {/* Play/Pause center overlay — fades in/out */}
      <div className={`absolute inset-0 flex items-center justify-center pointer-events-none transition-opacity duration-300 ${showControls || !playing ? 'opacity-100' : 'opacity-0'}`}>
        {!playing && (
          <div className="w-16 h-16 rounded-full bg-black/50 backdrop-blur-sm flex items-center justify-center">
            <Play className="w-8 h-8 text-white ml-1" fill="white" />
          </div>
        )}
      </div>

      {/* Bottom control bar */}
      <div className={`absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-3 flex flex-col gap-2 transition-opacity duration-300 ${showControls || !playing ? 'opacity-100' : 'opacity-0'}`}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Progress bar */}
        <div
          ref={progressRef}
          className="w-full h-1 bg-white/30 rounded-full cursor-pointer relative group/progress"
          onClick={handleSeek}
        >
          <div
            className="h-full bg-white rounded-full transition-all relative"
            style={{ width: `${progress}%` }}
          >
            <div className="absolute right-0 top-1/2 -translate-y-1/2 w-3 h-3 bg-white rounded-full opacity-0 group-hover/progress:opacity-100 transition-opacity" />
          </div>
        </div>
        {/* Time + controls row */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <button
              onClick={togglePlay}
              className="text-white hover:opacity-80 transition-opacity"
              aria-label={playing ? 'Pause' : 'Play'}
            >
              {playing ? <Pause className="w-5 h-5" /> : <Play className="w-5 h-5" fill="white" />}
            </button>
            <span className="text-white/80 text-xs font-mono">
              {formatTime(currentTime)} / {formatTime(duration)}
            </span>
          </div>
          {/* Volume control group */}
          <div
            className="flex items-center gap-1.5"
            onMouseEnter={handleVolumeAreaEnter}
            onMouseLeave={handleVolumeAreaLeave}
            onTouchStart={handleVolumeAreaEnter}
          >
            {/* Volume slider — progressive disclosure */}
            <div
              className="overflow-hidden transition-all duration-300 ease-out flex items-center"
              style={{
                width: showVolumeSlider ? '80px' : '0px',
                opacity: showVolumeSlider ? 1 : 0,
              }}
            >
              <input
                type="range"
                min="0"
                max="1"
                step="0.05"
                value={muted ? 0 : volume}
                onChange={handleVolumeChange}
                onClick={(e) => e.stopPropagation()}
                className="w-full h-1 appearance-none bg-white/30 rounded-full cursor-pointer"
                aria-label="Volume"
                style={{
                  background: `linear-gradient(to right, rgba(255,255,255,0.9) ${(muted ? 0 : volume) * 100}%, rgba(255,255,255,0.2) ${(muted ? 0 : volume) * 100}%)`,
                }}
              />
            </div>
            <button
              onClick={(e) => {
                toggleMute(e);
                setShowVolumeSlider(true);
                if (volumeTimerRef.current) clearTimeout(volumeTimerRef.current);
                volumeTimerRef.current = setTimeout(() => setShowVolumeSlider(false), 2000);
              }}
              className="text-white hover:opacity-80 transition-opacity p-1 min-w-[28px] min-h-[28px] flex items-center justify-center"
              aria-label={muted ? 'Unmute' : 'Mute'}
            >
              <VolumeIcon className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// Image Carousel Component — handles both images and video
const ImageCarousel = ({ images, mediaType }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  
  // Handle single image/video
  const mediaItems = Array.isArray(images) ? images : [images];
  
  const goNext = () => {
    setCurrentIndex((prev) => (prev + 1) % mediaItems.length);
  };
  
  const goPrev = () => {
    setCurrentIndex((prev) => (prev - 1 + mediaItems.length) % mediaItems.length);
  };
  
  if (mediaItems.length === 0) return null;
  
  const currentItem = mediaItems[currentIndex];
  const isVideo = mediaType === 'video' || (typeof currentItem === 'object' && currentItem?.type === 'video');
  const mediaUrl = typeof currentItem === 'string' ? currentItem : currentItem?.url;
  const posterUrl = typeof currentItem === 'object' ? currentItem?.poster : undefined;
  
  return (
    <div className="relative w-full h-full bg-black flex items-center justify-center">
      {isVideo ? (
        <ModalVideoPlayer
          src={mediaUrl}
          poster={posterUrl}
          className="w-full h-full"
        />
      ) : (
        <img
          src={mediaUrl}
          alt="Post media"
          className="max-w-full max-h-full object-contain"
          draggable="false"
        />
      )}
      
      {/* Navigation arrows */}
      {mediaItems.length > 1 && (
        <>
          <button
            onClick={goPrev}
            className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-white/90 rounded-full flex items-center justify-center shadow-lg hover:bg-white transition-colors z-10"
          >
            <ChevronLeft className="w-5 h-5 text-gray-800" />
          </button>
          <button
            onClick={goNext}
            className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-white/90 rounded-full flex items-center justify-center shadow-lg hover:bg-white transition-colors z-10"
          >
            <ChevronRight className="w-5 h-5 text-gray-800" />
          </button>
          
          {/* Dots indicator */}
          <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
            {mediaItems.map((_, idx) => (
              <button
                key={idx}
                onClick={() => setCurrentIndex(idx)}
                className={`w-1.5 h-1.5 rounded-full transition-colors ${
                  idx === currentIndex ? 'bg-blue-500' : 'bg-white/50'
                }`}
              />
            ))}
          </div>
        </>
      )}
    </div>
  );
};

// Comment Item
const CommentItem = ({ comment, userId, _onReact }) => {
  const navigate = useNavigate();
  const [liked, setLiked] = useState(comment.viewer_reaction !== null);
  const [likeCount, setLikeCount] = useState(comment.reaction_count || 0);
  
  const handleLike = async () => {
    if (!userId) {
      toast.error('Please log in to like');
      return;
    }
    
    try {
      const response = await apiClient.post(
        `/comments/${comment.id}/reactions`,
        { emoji: '❤️' }
      );
      
      if (response.data.action === 'added') {
        setLiked(true);
        setLikeCount(prev => prev + 1);
      } else if (response.data.action === 'removed') {
        setLiked(false);
        setLikeCount(prev => Math.max(0, prev - 1));
      }
    } catch (err) {
      toast.error('Failed to like');
    }
  };
  
  return (
    <div className="flex gap-3 py-2">
      <div className="w-8 h-8 rounded-full bg-zinc-700 flex items-center justify-center overflow-hidden flex-shrink-0">
        {comment.author_avatar ? (
          <img src={getFullUrl(comment.author_avatar)} alt="" className="w-full h-full object-cover" />
        ) : (
          <span className="text-xs text-gray-400">{comment.author_name?.charAt(0)}</span>
        )}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm">
          <span className="font-semibold text-white mr-1 cursor-pointer hover:underline" onClick={(e) => { e.stopPropagation(); navigate(`/profile/${comment.author_id}`); }}>{comment.author_name}</span>
          <CommentText 
            text={comment.content}
            className="text-gray-300"
          />
        </p>
        <div className="flex items-center gap-3 mt-1 text-xs text-gray-500">
          <span>{formatTimeAgo(comment.created_at)}</span>
          {likeCount > 0 && <span>{likeCount} like{likeCount !== 1 ? 's' : ''}</span>}
          <button className="hover:text-gray-300">Reply</button>
        </div>
      </div>
      <button
        onClick={handleLike}
        className={`flex-shrink-0 p-1 ${liked ? 'text-red-500' : 'text-gray-500 hover:text-gray-300'}`}
      >
        <Heart className="w-3.5 h-3.5" fill={liked ? 'currentColor' : 'none'} />
      </button>
    </div>
  );
};

const PostModal = ({ post, isOpen, onClose, _onPostUpdated, posts, onNavigatePost }) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  const _isLight = theme === 'light';
  
  const [comments, setComments] = useState([]);
  const [loadingComments, setLoadingComments] = useState(false);
  const [commentInput, setCommentInput] = useState('');
  const [submittingComment, setSubmittingComment] = useState(false);
  const [liked, setLiked] = useState(post?.liked || false);
  const [likeCount, setLikeCount] = useState(post?.likes_count || 0);
  const [saved, setSaved] = useState(post?.saved || post?.is_saved_by_user || false);
  const [captionExpanded, setCaptionExpanded] = useState(false);
  const [showComments, setShowComments] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const [showCommentEmoji, setShowCommentEmoji] = useState(false);
  
  // Shaka reaction state
  const [userReaction, setUserReaction] = useState(null);
  const [showReactionPicker, setShowReactionPicker] = useState(false);
  const [isPressing, setIsPressing] = useState(false);
  const [shareModalOpen, setShareModalOpen] = useState(false);
  const [postMenuOpen, setPostMenuOpen] = useState(false);
  const pressTimerRef = useRef(null);
  const isPressingRef = useRef(false); // Ref for synchronous checking
  const pickerShownRef = useRef(false); // Track if picker was shown during this press
  
  // Double-tap to like state
  const [showDoubleTapHeart, setShowDoubleTapHeart] = useState(false);
  const lastTapRef = useRef(0);
  
  const modalRef = useRef(null);
  
  // Double-tap to like handler
  const handleDoubleTap = useCallback(() => {
    const now = Date.now();
    if (now - lastTapRef.current < 300) {
      // Double tap detected — like the post
      if (!liked && user?.id && post?.id) {
        handleLike();
      }
      // Show heart animation
      setShowDoubleTapHeart(true);
      setTimeout(() => setShowDoubleTapHeart(false), 800);
      lastTapRef.current = 0;
    } else {
      lastTapRef.current = now;
    }
  }, [liked, user?.id, post?.id]);
  
  // Keyboard navigation for swipe between posts
  useEffect(() => {
    if (!isOpen || !posts || !onNavigatePost) return;
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        e.preventDefault();
        const idx = posts.findIndex(p => p.id === post?.id);
        if (idx < posts.length - 1) onNavigatePost(posts[idx + 1]);
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        e.preventDefault();
        const idx = posts.findIndex(p => p.id === post?.id);
        if (idx > 0) onNavigatePost(posts[idx - 1]);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, posts, post?.id, onNavigatePost]);
  
  // Check for mobile viewport
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);
  
  // Load comments when modal opens
  useEffect(() => {
    if (isOpen && post?.id) {
      loadComments();
      setLiked(post.liked || false);
      setLikeCount(post.likes_count || 0);
      setSaved(post.saved || post.is_saved_by_user || false);
      setCaptionExpanded(false);
      // Set initial reaction state from post data
      const existingReaction = post.reactions?.find(r => r.user_id === user?.id);
      setUserReaction(existingReaction || null);
    }
  }, [isOpen, post?.id]);
  
  // Handle browser back button - close modal instead of navigating away
  useEffect(() => {
    if (isOpen) {
      // Push a state to history when modal opens
      window.history.pushState({ modal: 'post' }, '');
      
      const handlePopState = (_e) => {
        // When back is pressed, close the modal
        onClose();
      };
      
      window.addEventListener('popstate', handlePopState);
      
      return () => {
        window.removeEventListener('popstate', handlePopState);
      };
    }
  }, [isOpen, onClose]);
  
  // Handle escape key
  useEffect(() => {
    const handleEscape = (e) => {
      if (e.key === 'Escape') {
        // Go back in history to remove the modal state we pushed
        if (window.history.state?.modal === 'post') {
          window.history.back();
        } else {
          onClose();
        }
      }
    };
    window.addEventListener('keydown', handleEscape);
    return () => window.removeEventListener('keydown', handleEscape);
  }, [onClose]);
  
  // Prevent body scroll when modal is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [isOpen]);
  
  const loadComments = async () => {
    setLoadingComments(true);
    try {
      const response = await apiClient.get(`/posts/${post.id}/comments`, {
        params: { viewer_id: user?.id }
      });
      setComments(response.data || []);
    } catch (err) {
      logger.error('Failed to load comments:', err);
    } finally {
      setLoadingComments(false);
    }
  };
  
  const handleLike = async () => {
    if (!user?.id) {
      toast.error('Please log in to like');
      return;
    }
    
    try {
      if (liked) {
        await apiClient.delete(`/posts/${post.id}/like`, { });
        setLiked(false);
        setLikeCount(prev => Math.max(0, prev - 1));
      } else {
        await apiClient.post(`/posts/${post.id}/like`, null, { });
        setLiked(true);
        setLikeCount(prev => prev + 1);
      }
    } catch (err) {
      toast.error('Failed to update like');
    }
  };
  
  const handleSave = async () => {
    if (!user?.id) {
      toast.error('Please log in to save');
      return;
    }
    
    try {
      if (saved) {
        await apiClient.delete(`/posts/${post.id}/save`);
        setSaved(false);
        toast.success('Removed from saved');
      } else {
        await apiClient.post(`/posts/${post.id}/save`);
        setSaved(true);
        toast.success('Saved!');
      }
    } catch (err) {
      logger.error('Save error:', err);
      toast.error(err.response?.data?.detail || 'Failed to save');
    }
  };
  
  // ============ SHAKA REACTION HANDLERS (copied from Feed.js pattern) ============
  const handleReactionStart = () => {
    // Clear any existing timer first
    if (pressTimerRef.current) {
      clearTimeout(pressTimerRef.current);
      pressTimerRef.current = null;
    }
    
    isPressingRef.current = true;
    pickerShownRef.current = false;
    setIsPressing(true);
    
    // Set timer for long-press (600ms for reliable mobile detection)
    pressTimerRef.current = setTimeout(() => {
      pickerShownRef.current = true;
      // Trigger haptic feedback
      if ('vibrate' in navigator) {
        navigator.vibrate(10);
      }
      setShowReactionPicker(true);
      setIsPressing(false);
    }, 600);
  };
  
  const handleReactionEnd = async () => {
    const wasPressing = isPressingRef.current;
    const pickerWasShown = pickerShownRef.current;
    
    // Clear pressing state
    setIsPressing(false);
    isPressingRef.current = false;
    
    // Always clear the timer
    if (pressTimerRef.current) {
      clearTimeout(pressTimerRef.current);
      pressTimerRef.current = null;
    }
    
    // If long-press triggered the picker, don't do quick tap
    if (pickerWasShown) {
      pickerShownRef.current = false;
      return;
    }
    
    // If picker is showing, don't do anything
    if (showReactionPicker) {
      return;
    }
    
    // Quick tap = toggle shaka
    if (wasPressing) {
      await handleReaction('🤙');
    }
  };
  
  const handleReactionCancel = () => {
    setIsPressing(false);
    isPressingRef.current = false;
    if (pressTimerRef.current) {
      clearTimeout(pressTimerRef.current);
      pressTimerRef.current = null;
    }
  };
  
  const handleReaction = async (emoji) => {
    if (!user?.id) {
      toast.error('Please log in to react');
      return;
    }
    
    setShowReactionPicker(false);
    
    try {
      const isRemovingReaction = userReaction?.emoji === emoji;
      
      const response = await apiClient.post(
        `/posts/${post.id}/reactions`,
        { emoji }
      );
      
      if (response.data.action === 'removed' || isRemovingReaction) {
        setUserReaction(null);
        setLiked(false);
        setLikeCount(prev => Math.max(0, prev - 1));
      } else {
        setUserReaction({ emoji });
        if (!liked && !userReaction) {
          setLikeCount(prev => prev + 1);
        }
        setLiked(true);
      }
    } catch (err) {
      toast.error('Failed to add reaction');
    }
  };
  
  // Cleanup timer on unmount
  useEffect(() => {
    return () => {
      if (pressTimerRef.current) clearTimeout(pressTimerRef.current);
    };
  }, []);
  
  const handleSubmitComment = async () => {
    if (!commentInput.trim() || !user?.id) return;
    
    setSubmittingComment(true);
    try {
      await apiClient.post(`/posts/${post.id}/comments`, {
        content: commentInput.trim()
      });
      setCommentInput('');
      loadComments();
      toast.success('Comment added');
    } catch (err) {
      toast.error('Failed to add comment');
    } finally {
      setSubmittingComment(false);
    }
  };
  
  // Alias for mobile view
  const handleComment = handleSubmitComment;
  
  // Ref for comment input (mobile)
  const mobileCommentInputRef = useRef(null);
  // Ref for comment input (desktop)
  const desktopCommentInputRef = useRef(null);
  
  // Like/unlike a comment
  const handleLikeComment = async (commentId) => {
    if (!user?.id) {
      toast.error('Please log in to like comments');
      return;
    }
    
    try {
      const _response = await apiClient.post(
        `/comments/${commentId}/reactions`,
        { emoji: '❤️' }
      );
      
      // Update comments state with new like
      setComments(prev => prev.map(c => {
        if (c.id === commentId) {
          const wasLiked = c.reactions?.some(r => r.user_id === user.id);
          return {
            ...c,
            likes_count: wasLiked ? (c.likes_count || 1) - 1 : (c.likes_count || 0) + 1,
            reactions: wasLiked 
              ? (c.reactions || []).filter(r => r.user_id !== user.id)
              : [...(c.reactions || []), { user_id: user.id, emoji: '❤️' }]
          };
        }
        return c;
      }));
    } catch (err) {
      toast.error('Failed to like comment');
    }
  };
  
  if (!isOpen || !post) return null;
  
  // Get media items (support for carousel)
  const mediaItems = post.media_urls || [post.media_url || post.image_url];
  
  // Truncated caption for mobile overlay
  const truncatedCaption = post.caption?.length > 100 
    ? post.caption.slice(0, 100) + '...' 
    : post.caption;
  
  // ============ MOBILE VIEW (Instagram-style fullscreen) ============
  if (isMobile) {
    return (
      <div 
        className="fixed inset-0 z-[9999] bg-black"
        data-testid="post-modal-mobile"
      >
        {/* Tap-to-close backdrop - ONLY in the image area, not top bar or bottom */}
        <div 
          className="absolute inset-0 top-[60px] bottom-[200px]"
          onClick={onClose}
          onTouchEnd={(e) => {
            // Only close if tapping the backdrop itself
            if (e.target === e.currentTarget) {
              onClose();
            }
          }}
          style={{ zIndex: 1 }}
        />
        
        {/* Fullscreen Image/Video - no click handler here */}
        <div 
          className="absolute inset-0 flex items-center justify-center pointer-events-none"
          style={{ zIndex: 2 }}
        >
          <div className="pointer-events-auto">
            <ImageCarousel images={mediaItems} mediaType={post.media_type} />
          </div>
        </div>
        
        {/* Top Bar - Close & Author */}
        <div 
          className="absolute top-0 left-0 right-0 bg-gradient-to-b from-black/70 to-transparent pb-12 pt-4"
          style={{ zIndex: 10, pointerEvents: 'none' }}
        >
          <div className="flex items-center justify-between px-4 pt-2" style={{ pointerEvents: 'auto' }}>
            <button
              onClick={onClose}
              className="p-2 text-white touch-manipulation"
              data-testid="close-post-modal"
            >
              <X className="w-6 h-6" />
            </button>
            
            {/* Author Info */}
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-full bg-zinc-700 overflow-hidden ring-2 ring-white/20">
                {post.author_avatar ? (
                  <img src={getFullUrl(post.author_avatar)} alt="" className="w-full h-full object-cover" />
                ) : (
                  <span className="w-full h-full flex items-center justify-center text-sm text-white">
                    {post.author_name?.charAt(0)}
                  </span>
                )}
              </div>
              <div>
                <p className="font-semibold text-white text-sm">{post.author_name}</p>
                {post.location && (
                  <p className="text-xs text-white/70">{post.location}</p>
                )}
              </div>
            </div>
            
            <button 
              className="p-3 text-white touch-manipulation active:bg-white/10 rounded-full"
              onPointerDown={(e) => {
                e.stopPropagation();
              }}
              onClick={(e) => {
                e.stopPropagation();
                e.preventDefault();
                setPostMenuOpen(true);
              }}
              style={{ WebkitTapHighlightColor: 'transparent' }}
              data-testid="post-modal-menu-button"
            >
              <MoreHorizontal className="w-6 h-6" />
            </button>
          </div>
        </div>
        
        {/* Reaction Picker Overlay - highest z-index when visible */}
        {showReactionPicker && (
          <div className="fixed inset-0 z-[200]">
            {/* Backdrop to close picker */}
            <div 
              className="absolute inset-0 bg-black/30"
              onClick={() => setShowReactionPicker(false)}
            />
            {/* Centered Picker - 2-row grid for mobile */}
            <div 
              className="absolute bg-zinc-900/95 backdrop-blur-md border border-zinc-600 rounded-2xl px-3 py-3 shadow-2xl animate-in zoom-in-95 duration-200"
              style={{ 
                left: '50%',
                top: '50%',
                transform: 'translate(-50%, -50%)',
                width: `${Math.min(window.innerWidth - 24, 300)}px`
              }}
              onClick={(e) => e.stopPropagation()}
            >
              <button 
                onClick={() => setShowReactionPicker(false)}
                className="absolute top-1.5 right-1.5 w-6 h-6 flex items-center justify-center text-gray-500 hover:text-white rounded-full hover:bg-zinc-700/50 touch-manipulation"
                style={{ zIndex: 1 }}
              >
                <X className="w-3.5 h-3.5" />
              </button>
              <div className="grid grid-cols-5 gap-1 justify-items-center">
                {REACTION_EMOJIS.map((emoji, _index) => (
                  <button
                    key={emoji}
                    onClick={() => handleReaction(emoji)}
                    className="w-11 h-11 flex items-center justify-center rounded-full hover:bg-zinc-700/60 active:scale-90 transition-transform duration-100 touch-manipulation"
                    style={{ fontSize: '24px' }}
                    data-testid={`post-reaction-${emoji}`}
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
        
        {/* Bottom Overlay - Caption & Actions - highest z-index for touch */}
        <div 
          className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/90 via-black/60 to-transparent pt-20 pb-6"
          style={{ zIndex: 50 }}
        >
          {/* Actions Row */}
          <div className="flex items-center justify-between px-4 mb-3">
            <div className="flex items-center gap-1">
              {/* Shaka Reaction Button - copy exact pattern from PostCard */}
              <button
                onPointerDown={(e) => {
                  e.preventDefault();
                  handleReactionStart();
                }}
                onPointerUp={(e) => {
                  e.preventDefault();
                  handleReactionEnd();
                }}
                onPointerCancel={handleReactionCancel}
                onPointerLeave={handleReactionCancel}
                onContextMenu={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  return false;
                }}
                className={`transition-all duration-300 select-none transform touch-manipulation ${isPressing ? 'scale-125' : 'hover:scale-105'}`}
                style={{
                  transition: 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)',
                  WebkitTouchCallout: 'none',
                  WebkitUserSelect: 'none',
                  userSelect: 'none',
                  WebkitTapHighlightColor: 'transparent'
                }}
                data-testid="reaction-button"
              >
                {userReaction ? (
                  <span className="text-3xl select-none">{userReaction.emoji}</span>
                ) : (
                  <ShakaIcon filled={liked} size={28} />
                )}
              </button>
              
              {/* Like Count */}
              {likeCount > 0 && (
                <span className="text-white font-semibold text-sm ml-1">
                  {likeCount.toLocaleString()}
                </span>
              )}
              
              <button
                className="p-3 text-white ml-2"
                onClick={(e) => {
                  e.stopPropagation();
                  setShowComments(true);
                  // Focus comment input after expanding
                  setTimeout(() => {
                    if (mobileCommentInputRef.current) mobileCommentInputRef.current.focus();
                  }, 100);
                }}
              >
                <MessageCircle className="w-7 h-7" />
              </button>
              <button 
                className="p-3 text-white touch-manipulation"
                onClick={() => setShareModalOpen(true)}
              >
                <Send className="w-7 h-7" />
              </button>
            </div>
            <button
              onClick={(e) => {
                e.stopPropagation();
                handleSave();
              }}
              className={`p-3 active:scale-95 touch-manipulation select-none ${saved ? 'text-yellow-400' : 'text-white'}`}
              style={{ 
                WebkitTapHighlightColor: 'transparent'
              }}
              data-testid="save-button"
            >
              <Bookmark 
                className="w-7 h-7"
                fill={saved ? 'currentColor' : 'none'}
              />
            </button>
          </div>
          
          {/* Caption - Truncated, expand on tap */}
          {post.caption && (
            <div 
              className="px-4 mb-2"
              onClick={() => setCaptionExpanded(!captionExpanded)}
              style={{ pointerEvents: 'auto' }}
            >
              <p className="text-white text-sm">
                <span className="font-semibold mr-1 cursor-pointer hover:underline" onClick={(e) => { e.stopPropagation(); navigate(`/profile/${post.author_id}`); }}>{post.author_name}</span>
                <RichText 
                  text={captionExpanded ? post.caption : truncatedCaption}
                  hashtagClassName="text-cyan-400 hover:text-cyan-300 cursor-pointer"
                  mentionClassName="text-blue-400 hover:text-blue-300 cursor-pointer"
                />
              </p>
              {post.caption?.length > 100 && !captionExpanded && (
                <button className="text-white/60 text-sm mt-1">more</button>
              )}
            </div>
          )}
          
          {/* Comments preview */}
          {comments.length > 0 && !showComments && (
            <button 
              className="text-white/60 text-sm px-4 mb-2" 
              style={{ pointerEvents: 'auto' }}
              onClick={() => setShowComments(true)}
            >
              View all {comments.length} comment{comments.length !== 1 ? 's' : ''}
            </button>
          )}
          
          {/* Expanded Comments Section */}
          {showComments && (
            <div className="px-4 mb-2 max-h-40 overflow-y-auto" style={{ pointerEvents: 'auto' }}>
              <button 
                className="text-white/60 text-sm mb-2"
                onClick={() => setShowComments(false)}
              >
                Hide comments
              </button>
              {comments.map((comment) => {
                const isLiked = comment.reactions?.some(r => r.user_id === user?.id);
                return (
                  <div key={comment.id} className="mb-3 flex items-start gap-2">
                    <div className="flex-1">
                      <p className="text-white text-sm">
                        <span className="font-semibold mr-1 cursor-pointer hover:underline" onClick={(e) => { e.stopPropagation(); navigate(`/profile/${comment.author_id}`); }}>{comment.author_name}</span>
                        <span className="text-white/90">{comment.content}</span>
                      </p>
                      <div className="flex items-center gap-3 mt-1">
                        <span className="text-white/40 text-xs">{formatTimeAgo(comment.created_at)}</span>
                        {(comment.likes_count > 0 || comment.reactions?.length > 0) && (
                          <span className="text-white/40 text-xs">
                            {comment.likes_count || comment.reactions?.length || 0} likes
                          </span>
                        )}
                        <button 
                          className="text-white/40 text-xs font-semibold"
                          onClick={() => {/* Reply functionality */}}
                        >
                          Reply
                        </button>
                      </div>
                    </div>
                    <button 
                      className="p-1 touch-manipulation"
                      onClick={() => handleLikeComment(comment.id)}
                    >
                      <Heart 
                        className={`w-4 h-4 ${isLiked ? 'text-red-500 fill-red-500' : 'text-white/40'}`}
                      />
                    </button>
                  </div>
                );
              })}
            </div>
          )}
          
          {/* Comment Input with Emoji Picker */}
          <div className="relative px-4 pb-2 flex items-center gap-2" style={{ pointerEvents: 'auto' }}>
            <button
              onClick={() => setShowCommentEmoji(!showCommentEmoji)}
              className={`flex-shrink-0 p-1.5 rounded-full transition-colors ${
                showCommentEmoji ? 'bg-yellow-500/20 text-yellow-400' : 'text-white/50 hover:text-white'
              }`}
            >
              <Smile className="w-5 h-5" />
            </button>
            <input
              ref={mobileCommentInputRef}
              type="text"
              placeholder="Add a comment..."
              value={commentInput}
              onChange={(e) => setCommentInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && commentInput.trim()) {
                  handleComment();
                  setShowCommentEmoji(false);
                }
              }}
              className="flex-1 bg-transparent text-white text-sm placeholder-white/40 outline-none"
            />
            {commentInput.trim() && (
              <button
                onClick={() => { handleComment(); setShowCommentEmoji(false); }}
                disabled={submittingComment}
                className="text-cyan-400 font-semibold text-sm"
              >
                {submittingComment ? '...' : 'Post'}
              </button>
            )}
            <EmojiPicker
              isOpen={showCommentEmoji}
              onClose={() => setShowCommentEmoji(false)}
              onSelect={(emoji) => {
                setCommentInput(prev => prev + emoji);
              }}
              position="above"
            />
          </div>
          
          {/* Timestamp */}
          <p className="text-white/40 text-xs uppercase px-4 pb-4">
            {formatTimeAgo(post.created_at)}
          </p>
        </div>
        
        {/* Share Modal */}
        <SharePostModal
          post={post}
          open={shareModalOpen}
          onClose={() => setShareModalOpen(false)}
        />
        
        {/* Post Menu */}
        <PostMenu
          post={post}
          open={postMenuOpen}
          onClose={() => setPostMenuOpen(false)}
          isLight={false}
          onPostUpdated={(_updatedPost) => {
            // Handle post update if needed
          }}
          onPostDeleted={() => {
            onClose();
          }}
        />
      </div>
    );
  }
  
  // ============ DESKTOP VIEW (Side-by-side layout) ============
  return (
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center"
      onClick={onClose}
    >
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/80" />
      
      {/* Close button */}
      <button
        onClick={onClose}
        className="absolute top-4 right-4 z-10 p-2 text-white hover:opacity-80 transition-opacity"
        data-testid="close-post-modal"
      >
        <X className="w-6 h-6" />
      </button>
      
      {/* Modal content */}
      <div 
        ref={modalRef}
        onClick={(e) => e.stopPropagation()}
        className="relative bg-zinc-900 rounded-lg overflow-hidden flex max-w-6xl w-[95vw] max-h-[90vh] shadow-2xl"
        style={{ minHeight: '500px' }}
      >
        {/* Left side - Image/Carousel */}
        <div className="flex-1 bg-black flex items-center justify-center min-w-0 relative" style={{ maxWidth: '60%' }} onClick={handleDoubleTap}>
          {/* Double-tap shaka animation */}
          {showDoubleTapHeart && (
            <div className="absolute inset-0 flex items-center justify-center z-20 pointer-events-none">
              <img 
                src="https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/svg/1f919.svg"
                alt="shaka"
                className="w-24 h-24 animate-ping"
                style={{ animationDuration: '0.6s', filter: 'drop-shadow(0 4px 12px rgba(234, 179, 8, 0.5))' }}
                draggable={false}
              />
            </div>
          )}
          <ImageCarousel images={mediaItems} mediaType={post.media_type} />
        </div>
        
        {/* Right side - Details & Comments */}
        <div className="w-[340px] flex flex-col border-l border-zinc-800 bg-zinc-900">
          {/* Header */}
          <div className="flex items-center gap-3 p-4 border-b border-zinc-800">
            <div className="w-8 h-8 rounded-full bg-zinc-700 overflow-hidden">
              {post.author_avatar ? (
                <img src={getFullUrl(post.author_avatar)} alt="" className="w-full h-full object-cover" />
              ) : (
                <span className="w-full h-full flex items-center justify-center text-sm text-gray-400">
                  {post.author_name?.charAt(0)}
                </span>
              )}
            </div>
            <div className="flex-1 min-w-0">
              <p className="font-semibold text-white text-sm truncate cursor-pointer hover:underline" onClick={(e) => { e.stopPropagation(); navigate(`/profile/${post.author_id}`); }}>{post.author_name}</p>
              {post.location && (
                <p className="text-xs text-gray-400 truncate">{post.location}</p>
              )}
            </div>
            <button className="text-gray-400 hover:text-white p-1" onClick={(e) => { e.stopPropagation(); setPostMenuOpen(true); }}>
              <MoreHorizontal className="w-5 h-5" />
            </button>
          </div>
          
          {/* Session metadata if available */}
          {(post.session_date || post.wave_height_ft) && (
            <div className="px-4 py-2 border-b border-zinc-800 space-y-1">
              {post.session_date && (
                <div className="flex items-center gap-2 text-xs text-gray-400">
                  <Calendar className="w-3.5 h-3.5 text-cyan-400" />
                  <span>{new Date(post.session_date).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}</span>
                </div>
              )}
              {post.wave_height_ft && (
                <div className="flex items-center gap-2 text-xs text-gray-400">
                  <Waves className="w-3.5 h-3.5 text-cyan-400" />
                  <span>{post.wave_height_ft}ft @ {post.wave_period_sec || '?'}s</span>
                </div>
              )}
            </div>
          )}
          
          {/* Caption & Comments scroll area */}
          <div className="flex-1 overflow-y-auto">
            {/* Caption */}
            {post.caption && (
              <div className="flex gap-3 p-4">
                <div className="w-8 h-8 rounded-full bg-zinc-700 overflow-hidden flex-shrink-0">
                  {post.author_avatar ? (
                    <img src={getFullUrl(post.author_avatar)} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <span className="w-full h-full flex items-center justify-center text-sm text-gray-400">
                      {post.author_name?.charAt(0)}
                    </span>
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm">
                    <span className="font-semibold text-white mr-1 cursor-pointer hover:underline" onClick={(e) => { e.stopPropagation(); navigate(`/profile/${post.author_id}`); }}>{post.author_name}</span>
                    <RichText 
                      text={post.caption}
                      className="text-gray-300"
                      hashtagClassName="text-cyan-400 hover:text-cyan-300 cursor-pointer"
                      mentionClassName="text-blue-400 hover:text-blue-300 cursor-pointer"
                    />
                  </p>
                  <p className="text-xs text-gray-500 mt-1">{formatTimeAgo(post.created_at)}</p>
                </div>
              </div>
            )}
            
            {/* Comments */}
            <div className="px-4 pb-4">
              {loadingComments ? (
                <div className="flex justify-center py-4">
                  <Loader2 className="w-5 h-5 animate-spin text-gray-400" />
                </div>
              ) : comments.length > 0 ? (
                <div className="space-y-1">
                  {comments.map((comment) => (
                    <CommentItem 
                      key={comment.id} 
                      comment={comment} 
                      userId={user?.id}
                    />
                  ))}
                </div>
              ) : (
                <p className="text-center text-gray-500 text-sm py-4">
                  No comments yet. Be the first!
                </p>
              )}
            </div>
          </div>
          
          {/* Actions */}
          <div className="border-t border-zinc-800 p-4 space-y-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <button onClick={handleLike} className="hover:opacity-70 transition-opacity">
                  <img 
                    src="https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/svg/1f919.svg"
                    alt="shaka"
                    className="w-6 h-6"
                    style={{ filter: liked ? 'none' : 'grayscale(100%) brightness(1.5)' }}
                  />
                </button>
                <button
                  className="text-white hover:opacity-70 transition-opacity"
                  onClick={() => {
                    if (desktopCommentInputRef.current) desktopCommentInputRef.current.focus();
                  }}
                >
                  <MessageCircle className="w-6 h-6" />
                </button>
                <button 
                  className="text-white hover:opacity-70 transition-opacity"
                  onClick={() => setShareModalOpen(true)}
                >
                  <Send className="w-6 h-6" />
                </button>
              </div>
              <button 
                onClick={(e) => {
                  e.stopPropagation();
                  handleSave();
                }}
                className={`transition-opacity touch-manipulation active:scale-95 ${saved ? 'text-yellow-400' : 'text-white'} hover:opacity-70`}
              >
                <Bookmark className="w-6 h-6" fill={saved ? 'currentColor' : 'none'} />
              </button>
            </div>
            
            {/* Like count */}
            {likeCount > 0 && (
              <p className="text-white text-sm font-semibold">
                {likeCount.toLocaleString()} like{likeCount !== 1 ? 's' : ''}
              </p>
            )}
            
            {/* Timestamp */}
            <p className="text-gray-500 text-xs uppercase">
              {formatTimeAgo(post.created_at)}
            </p>
          </div>
          
          {/* Comment input with Emoji Picker */}
          <div className="border-t border-zinc-800 p-4">
            <div className="relative flex items-center gap-2">
              <button
                onClick={() => setShowCommentEmoji(!showCommentEmoji)}
                className={`flex-shrink-0 p-1.5 rounded-full transition-colors ${
                  showCommentEmoji ? 'bg-yellow-500/20 text-yellow-400' : 'text-gray-400 hover:text-white'
                }`}
              >
                <Smile className="w-5 h-5" />
              </button>
              <input
                ref={desktopCommentInputRef}
                type="text"
                value={commentInput}
                onChange={(e) => setCommentInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && commentInput.trim()) {
                    handleSubmitComment();
                    setShowCommentEmoji(false);
                  }
                }}
                placeholder="Add a comment..."
                className="flex-1 bg-transparent text-white text-sm placeholder-gray-500 focus:outline-none"
                disabled={submittingComment}
              />
              {commentInput.trim() && (
                <button
                  onClick={() => { handleSubmitComment(); setShowCommentEmoji(false); }}
                  disabled={submittingComment}
                  className="text-blue-500 hover:text-blue-400 text-sm font-semibold"
                >
                  {submittingComment ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Post'}
                </button>
              )}
              <EmojiPicker
                isOpen={showCommentEmoji}
                onClose={() => setShowCommentEmoji(false)}
                onSelect={(emoji) => {
                  setCommentInput(prev => prev + emoji);
                }}
                position="above"
              />
            </div>
          </div>
        </div>
      </div>
      
      {/* Share Modal */}
      <SharePostModal
        post={post}
        open={shareModalOpen}
        onClose={() => setShareModalOpen(false)}
      />
      
      {/* Post Menu - Desktop */}
      <PostMenu
        post={post}
        open={postMenuOpen}
        onClose={() => setPostMenuOpen(false)}
        isLight={false}
        onPostUpdated={() => {}}
        onPostDeleted={() => { onClose(); }}
      />
      
      {/* Swipe navigation arrows — positioned on the viewport edges */}
      {!isMobile && posts && onNavigatePost && (() => {
        const idx = posts.findIndex(p => p.id === post?.id);
        if (idx === -1) return null;
        return (
          <>
            {idx > 0 && (
              <button
                onClick={(e) => { e.stopPropagation(); onNavigatePost(posts[idx - 1]); }}
                className="fixed left-3 top-1/2 -translate-y-1/2 z-[60] w-10 h-10 rounded-full bg-white/20 hover:bg-white/40 backdrop-blur-sm flex items-center justify-center text-white transition-all shadow-lg"
                data-testid="post-modal-prev"
              >
                <ChevronLeft className="w-6 h-6" />
              </button>
            )}
            {idx < posts.length - 1 && (
              <button
                onClick={(e) => { e.stopPropagation(); onNavigatePost(posts[idx + 1]); }}
                className="fixed right-3 top-1/2 -translate-y-1/2 z-[60] w-10 h-10 rounded-full bg-white/20 hover:bg-white/40 backdrop-blur-sm flex items-center justify-center text-white transition-all shadow-lg"
                data-testid="post-modal-next"
              >
                <ChevronRight className="w-6 h-6" />
              </button>
            )}
          </>
        );
      })()}
    </div>
  );
};

