export const Profile = () => {
  const { user, logout, updateUser, loading: authLoading } = useAuth();
  const { theme } = useTheme();
  const { getEffectiveRole, _isMasked } = usePersona();
  const navigate = useNavigate();
  const { userId } = useParams(); // Get userId from URL if viewing someone else's profile
  
  // Get effective role for UI rendering (respects God Mode persona masking)
  const effectiveRole = getEffectiveRole(user?.role);
  
  // Determine if viewing own profile or someone else's
  // Wait for auth to load before determining this
  const isOwnProfile = !userId || (user && userId === user.id);
  const profileUserId = userId || user?.id;
  
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [streak, setStreak] = useState({ current_streak: 0, longest_streak: 0, total_check_ins: 0 });
  const [socialStats, setSocialStats] = useState({ followers: 0, following: 0 });
  const [contentStats, setContentStats] = useState({ posts: 0, photos: 0, videos: 0, session_shots: 0, saved: 0, tagged: 0 });
  const [isFollowing, setIsFollowing] = useState(false);
  const [followLoading, setFollowLoading] = useState(false);
  
  // Tab state — read ?tab= param from URL to deep-link to a specific tab (e.g. reviews)
  const [searchParams] = useSearchParams();
  const initialTab = searchParams.get('tab') || 'posts';
  const [activeTab, setActiveTab] = useState(initialTab);
  const [tabContent, setTabContent] = useState([]);
  const [tabLoading, setTabLoading] = useState(false);
  
  // Edit modal
  const [showEditModal, setShowEditModal] = useState(false);
  const [editLoading, setEditLoading] = useState(false);
  const [editData, setEditData] = useState({
    full_name: '', bio: '', location: '', instagram_url: '', website_url: '',
    stance: '', wetsuit_color: '', rash_guard_color: ''
  });
  
  // Avatar upload + crop modal
  const [avatarUploading, setAvatarUploading] = useState(false);
  const [cropFile, setCropFile] = useState(null); // File pending crop
  const fileInputRef = useRef(null);
  
  // Tagged photo modal
  const [showTaggedPhotoModal, setShowTaggedPhotoModal] = useState(false);
  const [selectedTaggedPhoto, setSelectedTaggedPhoto] = useState(null);
  
  // Impact Score
  const [impactScore, setImpactScore] = useState(null);
  
  // Gamification
  const [gamificationStats, setGamificationStats] = useState({ total_xp: 0, badges: [], recent_xp_transactions: [] });

  // Go Live Modal
  const [showGoLiveModal, setShowGoLiveModal] = useState(false);

  // Followers/Following Modal
  const [showFollowersModal, setShowFollowersModal] = useState(false);
  const [followersModalType, setFollowersModalType] = useState('followers'); // 'followers' or 'following'

  // ============ BLOCK USER (extracted hook) ============
  const blockHook = useProfileBlock(user?.id, profileUserId, isOwnProfile, {
    onBlocked: () => {
      if (isFollowing) {
        setIsFollowing(false);
        setSocialStats(prev => ({ ...prev, followers: Math.max(0, prev.followers - 1) }));
      }
    }
  });

  // ============ NOTES (extracted hook) ============
  const notesHook = useProfileNotes(profileUserId, user?.id);

  // ============ QUICK BOOK (extracted hook) ============
  const quickBookHook = useProfileQuickBook(user, profileUserId, profile);

  // Check if profile is on-demand active (for Quick Book feature)
  const isOnDemandActive = profile?.on_demand_active === true;
  // Check if profile is a photographer (for Quick Book - uses actual profile role, not display role)
  const isProfilePhotographer = profile && ['Hobbyist', 'Photographer', 'Approved Pro', 'Pro'].includes(profile.role);

  useEffect(() => {
    // Wait for auth to finish loading before fetching profile data
    if (authLoading) return;
    
    if (profileUserId) {
      fetchProfile();
      fetchStreak();
      fetchSocialStats();
      fetchContentStats();
      fetchImpactScore();
      fetchGamificationStats();
      notesHook.fetchUserNote(); // Fetch the profile user's note
      if (!isOwnProfile && user) {
        checkFollowStatus();
        blockHook.checkBlockStatus();
      }
    }
  }, [profileUserId, isOwnProfile, authLoading, user]);

  useEffect(() => {
    if (authLoading) return;
    if (profileUserId) {
      fetchTabContent(activeTab);
    }
  }, [activeTab, profileUserId, authLoading]);

  const fetchProfile = async () => {
    if (!profileUserId) {
      setLoading(false);
      return;
    }
    
    try {
      const response = await apiClient.get(`/profiles/${profileUserId}`);
      setProfile(response.data);
      if (isOwnProfile && user) {
        setEditData({
          full_name: response.data.full_name || '',
          bio: response.data.bio || '',
          location: response.data.location || '',
          instagram_url: response.data.instagram_url || '',
          website_url: response.data.website_url || '',
          stance: response.data.stance || '',
          wetsuit_color: response.data.wetsuit_color || '',
          rash_guard_color: response.data.rash_guard_color || ''
        });
      }
    } catch (error) {
      logger.error('Failed to load profile:', error);
      // Only show error toast, don't redirect - let user stay on page
      if (error.response?.status === 404) {
        toast.error('User not found');
        navigate('/explore');
      } else {
        toast.error('Failed to load profile');
      }
    } finally {
      setLoading(false);
    }
  };

  const fetchStreak = async () => {
    try {
      const response = await apiClient.get(`/streak/${profileUserId}`);
      setStreak(response.data);
    } catch (error) {
      logger.error('Error fetching streak:', error);
    }
  };

  const fetchSocialStats = async () => {
    try {
      const [followersRes, followingRes] = await Promise.all([
        apiClient.get(`/followers/${profileUserId}`).catch(() => ({ data: [] })),
        apiClient.get(`/following/${profileUserId}`).catch(() => ({ data: [] }))
      ]);
      setSocialStats({
        followers: followersRes.data?.length || 0,
        following: followingRes.data?.length || 0
      });
    } catch (error) {
      logger.error('Error fetching social stats:', error);
    }
  };

  const fetchContentStats = async () => {
    try {
      const response = await apiClient.get(`/profile/${profileUserId}/stats`);
      setContentStats(response.data);
    } catch (error) {
      logger.error('Error fetching content stats:', error);
    }
  };

  const fetchImpactScore = async () => {
    try {
      const response = await apiClient.get(`/impact/public/${profileUserId}`);
      setImpactScore(response.data);
    } catch (error) {
      logger.error('Error fetching impact score:', error);
    }
  };

  const fetchGamificationStats = async () => {
    try {
      const response = await apiClient.get(`/gamification/user/${profileUserId}`);
      setGamificationStats(response.data);
    } catch (error) {
      logger.error('Error fetching gamification stats:', error);
    }
  };

  // Note handlers moved to notesHook (useProfileNotes)

  const checkFollowStatus = async () => {
    if (!user?.id || !profileUserId) return;
    try {
      // Use direct check: GET /follow/check?follower_id=X&following_id=Y
      // Fallback: load the following list and search
      try {
        const response = await apiClient.get(`/follow/check?follower_id=${user.id}&following_id=${profileUserId}`);
        setIsFollowing(response.data?.is_following === true);
        return;
      } catch (checkErr) {
        // Endpoint doesn't exist yet — fall back to list search
      }
      const response = await apiClient.get(`/following/${user.id}`);
      const following = response.data || [];
      // Compare as strings to avoid UUID type mismatch
      setIsFollowing(following.some(f => String(f.id) === String(profileUserId)));
    } catch (error) {
      logger.error('Error checking follow status:', error);
    }
  };

  const handleFollow = async () => {
    if (!user?.id) {
      toast.error('Please log in to follow users');
      return;
    }
    
    setFollowLoading(true);
    try {
      if (isFollowing) {
        await apiClient.delete(`/follow/${profileUserId}?follower_id=${user.id}`);
        setIsFollowing(false);
        setSocialStats(prev => ({ ...prev, followers: Math.max(0, prev.followers - 1) }));
        toast.success(`Unfollowed ${profile.full_name}`);
      } else {
        await apiClient.post(`/follow/${profileUserId}?follower_id=${user.id}`);
        setIsFollowing(true);
        setSocialStats(prev => ({ ...prev, followers: prev.followers + 1 }));
        toast.success(`Following ${profile.full_name}`);
      }
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to update follow status');
    } finally {
      setFollowLoading(false);
    }
  };

  // Block/Notes/QuickBook handlers are now in extracted hooks (blockHook, notesHook, quickBookHook)

  const fetchTabContent = async (tab) => {
    setTabLoading(true);
    try {
      let endpoint = '';
      const qs = user?.id ? `?viewer_id=${user.id}` : '';
      switch (tab) {
        case 'posts':
          endpoint = `/profile/${profileUserId}/posts${qs}`;
          break;
        case 'photos':
          endpoint = `/profile/${profileUserId}/photos${qs}`;
          break;
        case 'session_shots':
          endpoint = `/profile/${profileUserId}/session-shots${qs}`;
          break;
        case 'videos':
          endpoint = `/profile/${profileUserId}/videos${qs}`;
          break;
        case 'saved':
          // Only show saved tab for own profile
          if (!isOwnProfile) {
            setTabContent([]);
            setTabLoading(false);
            return;
          }
          endpoint = `/profile/${profileUserId}/saved${qs}`;
          break;
        case 'tagged':
          endpoint = `/profile/${profileUserId}/tagged${qs}`;
          break;
        default:
          endpoint = `/profile/${profileUserId}/posts${qs}`;
      }
      const response = await apiClient.get(endpoint);
      // Handle both array and object responses (tagged returns {items, new_count})
      // Use the `tab` parameter (not activeTab state) to avoid stale closure issues
      if (tab === 'tagged' && response.data?.items) {
        setTabContent(response.data.items);
      } else {
        setTabContent(response.data);
      }
    } catch (error) {
      logger.error('Error fetching tab content:', error);
      setTabContent([]);
    } finally {
      setTabLoading(false);
    }
  };

  const _handleLogout = () => {
    logout();
    navigate('/auth');
    toast.success('Logged out successfully');
  };

  const toggleLive = async () => {
    if (!profile) return; // Guard against null profile
    if (!profile.is_live) {
      // Open the Go Live modal with camera
      setShowGoLiveModal(true);
    } else {
      // End live broadcast
      try {
        const activeStreams = await apiClient.get(`/social-live/active`);
        const myStream = activeStreams.data.streams?.find(s => s.broadcaster_id === user.id);
        if (myStream) {
          await apiClient.post(`/social-live/${myStream.id}/end?broadcaster_id=${user.id}`);
        }
        setProfile({ ...profile, is_live: false });
        toast.success('Live broadcast ended');
      } catch (error) {
        logger.error('End live error:', error);
        // Fallback: update profile directly
        try {
          await apiClient.patch(`/profiles/${user.id}`, { is_live: false });
          setProfile({ ...profile, is_live: false });
          toast.success('Live broadcast ended');
        } catch (e) {
          toast.error('Failed to end live broadcast');
        }
      }
    }
  };
  
  const handleGoLiveEnded = () => {
    if (!profile) return; // Guard against null profile
    setProfile({ ...profile, is_live: false });
  };

  const handleSaveProfile = async () => {
    setEditLoading(true);
    try {
      const response = await apiClient.patch(`/profiles/${user.id}`, editData);
      setProfile(response.data);
      updateUser({ ...user, full_name: response.data.full_name });
      setShowEditModal(false);
      toast.success('Profile updated!');
    } catch (error) {
      toast.error('Failed to update profile');
    } finally {
      setEditLoading(false);
    }
  };

  // Step 1: User selects file → open crop modal
  const handleAvatarUpload = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Please select an image file');
      return;
    }

    // Open the crop modal instead of uploading directly
    setCropFile(file);
    // Reset file input so the same file can be re-selected
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Step 2: Crop confirmed → upload the cropped base64
  const handleCropConfirm = async (croppedBase64) => {
    setCropFile(null);
    setAvatarUploading(true);

    try {
      const response = await apiClient.patch(`/profiles/${user.id}`, {
        avatar_url: croppedBase64
      });
      setProfile(response.data);
      updateUser({
        avatar_url: response.data.avatar_url,
        updated_at: new Date().toISOString()
      });
      toast.success('Avatar updated!');
    } catch (patchError) {
      toast.error('Failed to upload avatar');
      logger.error(patchError);
    } finally {
      setAvatarUploading(false);
    }
  };

  if (loading || authLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="w-8 h-8 animate-spin text-yellow-400" />
      </div>
    );
  }

  if (!profile) return null;

  // Use effective role when viewing own profile (for God Mode), else use profile.role
  const displayRole = isOwnProfile ? effectiveRole : profile.role;
  const isPhotographer = ['Grom Parent', 'Hobbyist', 'Photographer', 'Approved Pro'].includes(displayRole);
  // Stoked eligible: Grom, Comp Surfer, Pro (NOT regular Surfer - they don't receive donations)
  const isStokedEligible = ['Grom', 'Comp Surfer', 'Pro'].includes(displayRole);
  // Grom Parent gets Grom Overview tab (Shield icon)
  const isGromParent = displayRole === ROLES.GROM_PARENT;

  // Tabs - Saved is only visible on own profile, Stoked for eligible surfers
  // Badges merged into Crew tab, Surfboards tab for all users
  // For photographers: Crew + Impact combined into "Swell" tab
  const tabs = [
    { id: 'posts', icon: Grid3X3, label: 'Posts', count: contentStats.posts },
    { id: 'photos', icon: Image, label: 'Photos', count: contentStats.photos },
    { id: 'videos', icon: Play, label: 'Videos', count: contentStats.videos },
    { id: 'session_shots', icon: Waves, label: 'Sessions', count: contentStats.session_shots },
    ...(isOwnProfile ? [{ id: 'saved', icon: Bookmark, label: 'Saved', count: contentStats.saved }] : []),
    { id: 'tagged', icon: UserSquare2, label: 'Tagged', count: contentStats.tagged },
    // Swell tab for photographers (combines Crew + Impact), Crew tab for non-photographers
    ...(!isGromParent && isPhotographer && impactScore?.is_photographer 
      ? [{ id: 'swell', icon: Waves, label: 'Swell', count: null }]
      : [{ id: 'crew', icon: Users, label: 'Crew', count: null }]
    ),
    // Surfboards tab: Show for all users (custom surfboard icon)
    { id: 'surfboards', icon: SurfboardIcon, label: 'Boards', count: null },
    // Reviews tab: Show on all profiles
    { id: 'reviews', icon: Star, label: 'Reviews', count: null },
    // Grom Overview tab: Only for Grom Parent (Shield icon)
    ...(isGromParent ? [{ id: 'grom_overview', icon: Shield, label: 'Groms', count: null }] : []),
    // Stoked tab: Only show for Grom, Comp Surfer, Pro (NOT regular Surfer, NOT photographers)
    ...(isStokedEligible && !isPhotographer ? [{ id: 'stoked', icon: Zap, label: 'Stoked', count: null }] : []),
  ];

  return (
    <div className="pb-20 bg-background min-h-screen" data-testid="profile-page">
      {/* Back Button for viewing other profiles */}
      {!isOwnProfile && (
        <div className="sticky top-0 z-10 bg-background/90 backdrop-blur-sm border-b border-border px-4 py-3">
          <button
            onClick={() => navigate(-1)}
            className="flex items-center gap-2 text-white hover:text-gray-300"
            data-testid="back-button"
          >
            <ArrowLeft className="w-5 h-5" />
            <span className="font-medium">{profile.full_name}</span>
          </button>
        </div>
      )}

      {/* Profile Header - Centered Magazine Cover Style */}
      <div className="max-w-2xl mx-auto px-4 pt-6">
        
        {/* Blocked Banner - Show when either user has blocked the other */}
        {!isOwnProfile && (blockHook.isBlocked || blockHook.isBlockedByThem) && (
          <div className={`mb-4 p-3 rounded-xl border flex items-center gap-3 ${
            blockHook.isBlockedByThem 
              ? 'bg-zinc-800/50 border-zinc-600' 
              : 'bg-red-500/10 border-red-500/30'
          }`}>
            <Ban className={`w-5 h-5 flex-shrink-0 ${blockHook.isBlockedByThem ? 'text-zinc-400' : 'text-red-400'}`} />
            <div className="flex-1">
              <p className={`text-sm font-medium ${blockHook.isBlockedByThem ? 'text-zinc-300' : 'text-red-400'}`}>
                {blockHook.isBlockedByThem 
                  ? 'This user has restricted their profile' 
                  : `You have blocked ${profile?.full_name || 'this user'}`
                }
              </p>
              <p className="text-xs text-zinc-500">
                {blockHook.isBlockedByThem
                  ? 'You cannot view their posts or send them messages.'
                  : 'They cannot see your posts or contact you.'
                }
              </p>
            </div>
            {blockHook.isBlocked && !blockHook.isBlockedByThem && (
              <Button
                onClick={() => blockHook.handleUnblockUser(profile?.full_name)}
                disabled={blockHook.blockLoading}
                size="sm"
                variant="outline"
                className="border-zinc-600 text-zinc-300 hover:text-white"
              >
                {blockHook.blockLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Unblock'}
              </Button>
            )}
          </div>
        )}
        
        {/* Centered Avatar Section with subtle radial gradient background */}
        <div className="flex flex-col items-center mb-6 relative">
          {/* Radial gradient glow behind avatar */}
          <div 
            className="absolute top-4 left-1/2 -translate-x-1/2 w-64 h-64 rounded-full pointer-events-none"
            style={{
              background: 'radial-gradient(circle, rgba(20, 184, 166, 0.5) 0%, rgba(6, 182, 212, 0.3) 30%, rgba(8, 145, 178, 0.15) 50%, transparent 70%)',
              filter: 'blur(40px)'
            }}
          />
          
          {/* Avatar with Note Bubble, Live/Shooting rings */}
          <div className="relative group mb-2 z-10">
            {/* Note Bubble - positioned ABOVE avatar (only when note exists) */}
            {notesHook.userNote && (
              <button
                onClick={() => notesHook.setShowNoteModal(true)}
                className="absolute -top-4 left-1/2 -translate-x-1/2 z-20 animate-in fade-in zoom-in duration-300"
                data-testid="profile-note-bubble"
              >
                <div className="bg-zinc-900/95 backdrop-blur-sm border border-emerald-400 rounded-full px-3 py-1.5 max-w-[160px] shadow-lg hover:scale-105 transition-transform">
                  <p className="text-xs text-gray-100 truncate text-center font-medium">{notesHook.userNote.content}</p>
                </div>
                <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-2 h-2 bg-zinc-900/95 border-r border-b border-emerald-400 rotate-45" />
              </button>
            )}
            
            {/* Large Centered Avatar with gradient ring */}
            <div 
              className={`p-[4px] rounded-full ${
                profile.is_live 
                  ? 'bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-500 animate-pulse' 
                  : profile.is_shooting
                    ? 'bg-gradient-to-tr from-cyan-400 via-blue-500 to-indigo-500'
                    : notesHook.userNote 
                      ? 'bg-gradient-to-br from-emerald-400 via-green-500 to-teal-500'
                      : 'bg-gradient-to-br from-zinc-700 to-zinc-800'
              }`}
              onClick={() => notesHook.userNote && notesHook.setShowNoteModal(true)}
              style={{ cursor: notesHook.userNote ? 'pointer' : 'default' }}
            >
              <Avatar className={`w-28 h-28 md:w-32 md:h-32 border-4 border-black ${profile.is_logo_avatar ? 'bg-black' : ''}`} data-testid="profile-avatar">
                <AvatarImage 
                  src={getFullUrl(profile.avatar_url)} 
                  objectFit={profile.is_logo_avatar ? 'contain' : 'cover'}
                  className={profile.is_logo_avatar ? 'p-2' : ''}
                />
                <AvatarFallback className="text-4xl bg-zinc-800 text-white">
                  {profile.full_name?.[0] || 'U'}
                </AvatarFallback>
              </Avatar>
            </div>
            
            {/* Avatar upload overlay */}
            {isOwnProfile && (
              <button
                onClick={() => fileInputRef.current?.click()}
                disabled={avatarUploading}
                className="absolute inset-0 flex items-center justify-center bg-black/60 rounded-full opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
                data-testid="avatar-upload-btn"
              >
                {avatarUploading ? (
                  <Loader2 className="w-8 h-8 text-white animate-spin" />
                ) : (
                  <Camera className="w-8 h-8 text-white" />
                )}
              </button>
            )}
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              onChange={handleAvatarUpload}
              className="hidden"
            />

            {/* Logo / Photo Toggle - Only for own profile with avatar */}
            {isOwnProfile && profile.avatar_url && (
              <button
                onClick={async () => {
                  try {
                    const newVal = !profile.is_logo_avatar;
                    await apiClient.patch(`/profiles/${user.id}`, { is_logo_avatar: newVal });
                    setProfile({ ...profile, is_logo_avatar: newVal });
                    toast.success(newVal ? 'Avatar set to Logo mode' : 'Avatar set to Photo mode');
                  } catch (e) {
                    toast.error('Failed to update avatar mode');
                  }
                }}
                className="absolute -bottom-1 -right-1 z-20 w-7 h-7 rounded-full bg-zinc-800 border-2 border-zinc-600 hover:border-cyan-400 flex items-center justify-center transition-all group/logo"
                data-testid="avatar-mode-toggle"
                title={profile.is_logo_avatar ? 'Switch to Photo mode' : 'Switch to Logo mode'}
              >
                <span className="text-[10px] font-bold text-zinc-300 group-hover/logo:text-cyan-400">
                  {profile.is_logo_avatar ? '📷' : '🏷️'}
                </span>
              </button>
            )}
            
            {/* Status Badge: LIVE or SHOOTING */}
            {profile.is_live ? (
              <span className="absolute -bottom-2 left-1/2 -translate-x-1/2 bg-red-500 text-white text-xs font-bold px-3 py-1 rounded-full shadow-lg animate-pulse flex items-center gap-1">
                <Radio className="w-3 h-3" />
                LIVE
              </span>
            ) : profile.is_shooting && (
              <span className="absolute -bottom-2 left-1/2 -translate-x-1/2 bg-cyan-500 text-white text-xs font-bold px-3 py-1 rounded-full shadow-lg flex items-center gap-1">
                <Camera className="w-3 h-3" />
                SHOOTING
              </span>
            )}
          </div>

          {/* Add Note button - BELOW avatar, only when NO note exists */}
          {isOwnProfile && !notesHook.userNote && (
            <button
              onClick={() => {
                notesHook.setNoteText('');
                notesHook.setShowNoteModal(true);
              }}
              className="mb-2"
              data-testid="add-note-btn"
            >
              <div className="bg-zinc-800/80 border border-dashed border-zinc-600 rounded-full px-4 py-1.5 flex items-center gap-1.5 hover:border-emerald-400 hover:bg-zinc-700/80 transition-colors">
                <span className="text-gray-400 text-xs">+ Add note</span>
              </div>
            </button>
          )}

          {/* Username - Instagram style primary display */}
          {profile.username && (
            <p className="text-lg font-medium text-foreground mb-0.5" data-testid="profile-username">
              @{profile.username}
            </p>
          )}

          {/* Name + Verification */}
          <div className="flex items-center gap-2 mb-1">
            <h1 className="text-lg font-semibold text-muted-foreground" data-testid="profile-name" style={{ fontFamily: 'Oswald, sans-serif' }}>
              {profile.full_name || 'Anonymous'}
            </h1>
            {profile.is_verified && (
              <div className="bg-blue-500 rounded-full p-1">
                <Check className="w-3.5 h-3.5 text-white" />
              </div>
            )}
          </div>

          {/* Location */}
          {profile.location && (
            <span className="flex items-center gap-1.5 text-muted-foreground text-sm mb-3">
              <MapPin className="w-4 h-4" />
              {profile.location}
            </span>
          )}

          {/* Stats Row - Horizontal centered */}
          <div className="flex items-center justify-center gap-8 mb-4">
            <div className="text-center">
              <p className="text-xl font-bold text-foreground">{contentStats.posts}</p>
              <p className="text-xs text-muted-foreground uppercase tracking-wider">posts</p>
            </div>
            <div className="w-px h-8 bg-border" />
            <button 
              onClick={() => {
                setFollowersModalType('followers');
                setShowFollowersModal(true);
              }}
              className="text-center cursor-pointer hover:opacity-70 transition-opacity"
              data-testid="followers-count-btn"
            >
              <p className="text-xl font-bold text-foreground">{socialStats.followers}</p>
              <p className="text-xs text-muted-foreground uppercase tracking-wider">followers</p>
            </button>
            <div className="w-px h-8 bg-border" />
            <button 
              onClick={() => {
                setFollowersModalType('following');
                setShowFollowersModal(true);
              }}
              className="text-center cursor-pointer hover:opacity-70 transition-opacity"
              data-testid="following-count-btn"
            >
              <p className="text-xl font-bold text-foreground">{socialStats.following}</p>
              <p className="text-xs text-muted-foreground uppercase tracking-wider">following</p>
            </button>
          </div>

          {/* Role Badges Row */}
          <div className="flex items-center justify-center gap-2 flex-wrap mb-3">
            <ProfileRoleBadge role={displayRole} />
            {profile.subscription_tier && profile.subscription_tier !== 'free' && (
              <Badge variant="outline" className="border-emerald-400 text-emerald-400 text-xs">
                {profile.subscription_tier}
              </Badge>
            )}
            {streak.current_streak > 0 && (
              <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/30 text-xs">
                <Flame className="w-3 h-3 mr-1" />
                {streak.current_streak} day streak
              </Badge>
            )}
            {impactScore?.is_photographer && impactScore?.impact_score?.total_credits_given > 0 && (
              <Badge className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 text-xs">
                <Heart className="w-3 h-3 mr-1" />
                {impactScore.impact_score.level?.emoji} {impactScore.impact_score.total_credits_given.toFixed(0)} given
              </Badge>
            )}
            {gamificationStats.total_xp > 0 && (
              <XPDisplay xp={gamificationStats.total_xp} size="sm" />
            )}
            {profile.elite_tier === 'grom_rising' && (
              <Badge className="bg-yellow-500/20 text-yellow-400 border-yellow-500/30 text-xs" data-testid="grom-competes-badge">
                <Trophy className="w-3 h-3 mr-1" />
                Competes
              </Badge>
            )}
          </div>

          {/* Trust Signal Badges - Photographer social proof */}
          {isProfilePhotographer && profileUserId && (
            <div className="w-full max-w-sm mb-3">
              <TrustSignalBadges profileId={profileUserId} compact />
            </div>
          )}

          {/* Earned Badges */}
          {gamificationStats.badges && gamificationStats.badges.length > 0 && (
            <div className="flex items-center justify-center gap-2 mb-3" data-testid="profile-badges">
              <BadgeRow badges={gamificationStats.badges} size="sm" maxDisplay={4} />
            </div>
          )}

          {/* Bio */}
          {profile.bio && (
            <p className="text-sm text-muted-foreground text-center max-w-sm mb-3" data-testid="profile-bio">
              {profile.bio}
            </p>
          )}

          {/* Social Links - Centered */}
          <div className="flex items-center justify-center gap-4 text-sm mb-4">
            {profile.instagram_url && (
              <a 
                href={`https://instagram.com/${profile.instagram_url.replace('@', '')}`}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1.5 text-blue-400 hover:text-blue-300 transition-colors"
              >
                <Instagram className="w-4 h-4" />
                {profile.instagram_url}
              </a>
            )}
            {profile.website_url && (
              <a 
                href={profile.website_url}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1.5 text-blue-400 hover:text-blue-300 transition-colors"
              >
                <Globe className="w-4 h-4" />
                Website
                <ExternalLink className="w-3 h-3" />
              </a>
            )}
          </div>
        </div>

        {/* Action Buttons - Different for own profile vs others */}
        <div className="flex gap-2 mb-4">
          {isOwnProfile ? (
            <>
              <Button
                onClick={() => setShowEditModal(true)}
                className="flex-1 bg-secondary hover:bg-secondary/80 text-secondary-foreground text-sm h-10"
                data-testid="edit-profile-btn"
              >
                Edit profile
              </Button>
              {/* Social Go Live Button */}
              <Button
                onClick={toggleLive}
                className={`text-sm h-10 px-4 ${
                  profile.is_live
                    ? 'bg-red-500 hover:bg-red-600 text-white animate-pulse'
                    : 'bg-gradient-to-r from-yellow-400 to-amber-500 hover:from-yellow-500 hover:to-amber-600 text-black font-semibold'
                }`}
                data-testid="go-live-btn"
              >
                <Radio className="w-4 h-4 mr-1" />
                {profile.is_live ? 'End Live' : 'Go Live'}
              </Button>
              {profile.is_shooting && !profile.is_live && (
                <div className="flex items-center gap-1 px-3 py-1.5 bg-cyan-500/20 border border-cyan-500/50 rounded-lg">
                  <Camera className="w-4 h-4 text-cyan-400" />
                  <span className="text-xs text-cyan-400 font-medium">Shooting</span>
                </div>
              )}
              {isPhotographer && (
                <Button
                  onClick={() => navigate('/career/stoke-sponsor')}
                  variant="outline"
                  className="h-10 px-3 border-pink-500/50 text-pink-400 hover:bg-pink-500/10"
                  data-testid="stoke-sponsor-button"
                >
                  <Heart className="w-4 h-4 mr-1" />
                  Stoke
                </Button>
              )}
              <Button
                onClick={() => navigate('/settings')}
                variant="outline"
                className="h-10 w-10 p-0 border-border text-foreground hover:bg-accent"
                data-testid="settings-button"
              >
                <Settings className="w-4 h-4 text-foreground" />
              </Button>
            </>
          ) : (
            <>
              <Button
                onClick={handleFollow}
                disabled={followLoading}
                className={`flex-1 text-sm h-10 ${
                  isFollowing
                    ? 'bg-zinc-800 hover:bg-zinc-700 text-white'
                    : 'bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black'
                }`}
                data-testid="follow-button"
              >
                {followLoading ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : isFollowing ? (
                  <>
                    <UserMinus className="w-4 h-4 mr-2" />
                    Following
                  </>
                ) : (
                  <>
                    <UserPlus className="w-4 h-4 mr-2" />
                    Follow
                  </>
                )}
              </Button>
              <Button
                onClick={async () => {
                  // Lazy thread routing: check for existing conversation first
                  try {
                    const response = await apiClient.get(`/messages/check-thread/${user.id}/${profileUserId}`);
                    if (response.data.exists) {
                      // Navigate directly to existing conversation
                      navigate(`/messages/${response.data.conversation_id}`, { 
                        state: { fromProfile: profileUserId } 
                      });
                    } else {
                      // Navigate to new chat view with recipient info
                      navigate(`/messages/new/${profileUserId}`, { 
                        state: { 
                          fromProfile: profileUserId,
                          recipientName: response.data.recipient_name,
                          recipientAvatar: response.data.recipient_avatar
                        } 
                      });
                    }
                  } catch (error) {
                    toast.error('Failed to open chat');
                  }
                }}
                variant="outline"
                className="flex-1 h-10 border-border text-foreground hover:bg-muted"
                data-testid="message-button"
              >
                Message
              </Button>
              {/* View Gallery CTA for Photographers */}
              {['Photographer', 'Approved Pro', 'photographer', 'approved_pro'].includes(profile.role) && (
                <Button
                  onClick={() => navigate(`/photographer/${profileUserId}/gallery`)}
                  className="h-10 px-4 bg-gradient-to-r from-amber-500 to-yellow-500 hover:from-amber-600 hover:to-yellow-600 text-black font-semibold"
                  data-testid="view-gallery-button"
                >
                  <Image className="w-4 h-4 mr-2" />
                  Gallery
                </Button>
              )}
              
              {/* More Options (Block, Report) */}
              <div className="relative">
                <Button
                  onClick={() => blockHook.setShowMoreMenu(!blockHook.showMoreMenu)}
                  variant="outline"
                  className="h-10 w-10 p-0 border-zinc-700"
                  data-testid="more-options-button"
                >
                  <MoreHorizontal className="w-4 h-4 text-white" />
                </Button>
                
                {blockHook.showMoreMenu && (
                  <>
                    {/* Click outside to close */}
                    <div 
                      className="fixed inset-0 z-40" 
                      onClick={() => blockHook.setShowMoreMenu(false)} 
                    />
                    
                    {/* Menu dropdown */}
                    <div className="absolute right-0 top-12 z-50 w-48 bg-zinc-800 border border-zinc-700 rounded-xl shadow-xl py-1">
                      {blockHook.isBlocked ? (
                        <button
                          onClick={() => {
                            blockHook.setShowMoreMenu(false);
                            blockHook.handleUnblockUser(profile?.full_name);
                          }}
                          disabled={blockHook.blockLoading}
                          className="w-full flex items-center gap-3 px-4 py-3 text-sm text-green-400 hover:bg-zinc-700 transition-colors"
                          data-testid="unblock-user-btn"
                        >
                          {blockHook.blockLoading ? (
                            <Loader2 className="w-4 h-4 animate-spin" />
                          ) : (
                            <Ban className="w-4 h-4" />
                          )}
                          Unblock User
                        </button>
                      ) : (
                        <button
                          onClick={() => {
                            blockHook.setShowMoreMenu(false);
                            blockHook.setShowBlockModal(true);
                          }}
                          className="w-full flex items-center gap-3 px-4 py-3 text-sm text-red-400 hover:bg-zinc-700 transition-colors"
                          data-testid="block-user-btn"
                        >
                          <Ban className="w-4 h-4" />
                          Block User
                        </button>
                      )}
                      
                      <button
                        onClick={() => {
                          blockHook.setShowMoreMenu(false);
                          // Could navigate to report page or open report modal
                          toast.info('Report functionality coming soon');
                        }}
                        className="w-full flex items-center gap-3 px-4 py-3 text-sm text-amber-400 hover:bg-zinc-700 transition-colors"
                        data-testid="report-user-btn"
                      >
                        <Flag className="w-4 h-4" />
                        Report User
                      </button>
                    </div>
                  </>
                )}
              </div>
            </>
          )}
        </div>

        {/* ============ PHOTOGRAPHER AVAILABILITY BUTTON ============ */}
        {!isOwnProfile && isProfilePhotographer && (
          <div className="mb-4">
            <PhotographerAvailability
              photographerId={profileUserId}
              photographerName={profile?.full_name || 'Photographer'}
              onWatchLive={() => {
                // Navigate to live stream or open live viewer
                navigate(`/live/${profileUserId}`);
              }}
              onRequestOnDemand={() => quickBookHook.handleQuickBookOpen('on-demand')}
              onBook={() => quickBookHook.handleQuickBookOpen('scheduled')}
              trigger={
                <Button
                  className="w-full h-12 bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white font-bold"
                  data-testid="photographer-availability-btn"
                >
                  <Camera className="w-5 h-5 mr-2" />
                  Check Availability
                  {isOnDemandActive && (
                    <span className="ml-2 flex items-center gap-1">
                      <span className="w-2 h-2 rounded-full bg-green-400 animate-pulse" />
                      <span className="text-xs text-green-300">Available</span>
                    </span>
                  )}
                </Button>
              }
            />
          </div>
        )}

        {/* ============ PHOTOGRAPHER SUBSCRIPTION PLANS ============ */}
        {!isOwnProfile && isProfilePhotographer && (
          <PhotographerSubscriptionPlans
            photographerId={profileUserId}
            photographerName={profile?.full_name || 'Photographer'}
          />
        )}

        {/* Quick Stats Row - Only for own profile */}
        {isOwnProfile && (
          <div className="flex items-center justify-between bg-zinc-900/50 rounded-lg p-3 mb-4">
            <div className="flex items-center gap-2">
              <div className="bg-orange-500/20 p-2 rounded-full">
                <Flame className="w-5 h-5 text-orange-400" />
              </div>
              <div>
                <p className="text-white font-bold">{streak.current_streak}</p>
                <p className="text-[10px] text-gray-400">Day Streak</p>
              </div>
            </div>
            <div className="h-8 w-px bg-zinc-700" />
            <div className="flex items-center gap-2">
              <div className="bg-emerald-500/20 p-2 rounded-full">
                <DollarSign className="w-5 h-5 text-emerald-400" />
              </div>
              <div>
                <p className="text-white font-bold">{(profile.credit_balance || 0).toFixed(0)}</p>
                <p className="text-[10px] text-gray-400">Credits</p>
              </div>
            </div>
            <Button
              onClick={() => navigate('/credits')}
              size="sm"
              className="h-8 text-xs bg-emerald-500 hover:bg-emerald-600 text-white"
            >
              Add Credits
            </Button>
          </div>
        )}

        {/* Tabs */}
        <div className="border-t border-border">
          <div className="flex justify-around">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex-1 py-3 flex flex-col items-center gap-1 relative transition-colors ${
                  activeTab === tab.id
                    ? 'text-foreground'
                    : 'text-muted-foreground hover:text-foreground/70'
                }`}
                data-testid={`tab-${tab.id}`}
              >
                {/* Active indicator bar — rides the border-t of the container */}
                {activeTab === tab.id && (
                  <span className="absolute top-0 left-1/2 -translate-x-1/2 w-8 h-0.5 rounded-b-full bg-foreground" />
                )}
                <tab.icon className="w-5 h-5" />
                <span className="text-[10px]">{tab.label}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Tab Content Grid */}
      <div className="max-w-2xl mx-auto">
        {activeTab === 'swell' && impactScore?.is_photographer ? (
          // Swell Tab - Combined Crew + Impact for photographers
          <div className="p-4 space-y-6">
            {/* Impact Section */}
            <div className="space-y-4">
              {/* Impact Level */}
              <div className="bg-gradient-to-br from-cyan-500/20 to-blue-500/20 rounded-xl p-6 text-center border border-cyan-500/30">
                <div className="text-4xl mb-2">
                  {impactScore.impact_score?.level?.emoji || '🌱'}
                </div>
                <p className="text-white font-bold text-xl mb-1">
                  {impactScore.impact_score?.level?.name || 'Starter'}
                </p>
                <p className="text-cyan-400 text-2xl font-bold">
                  {impactScore.impact_score?.total_credits_given?.toFixed(0) || 0} credits given
                </p>
              </div>
              
              {/* Impact Stats */}
              <div className="grid grid-cols-2 gap-4">
                <div className="bg-zinc-900/60 border border-amber-500/30 rounded-lg p-4 text-center">
                  <p className="text-3xl font-bold text-amber-400">
                    {impactScore.impact_score?.total_groms_supported || 0}
                  </p>
                  <p className="text-zinc-400 text-sm">Groms Supported</p>
                </div>
                <div className="bg-zinc-900/60 border border-blue-500/30 rounded-lg p-4 text-center">
                  <p className="text-3xl font-bold text-blue-400">
                    {impactScore.impact_score?.total_causes_supported || 0}
                  </p>
                  <p className="text-zinc-400 text-sm">Causes Supported</p>
                </div>
              </div>
              
              {/* CTA for own profile */}
              {isOwnProfile && (
                <button
                  onClick={() => navigate('/impact')}
                  className="w-full py-3 bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-semibold rounded-lg transition-all"
                >
                  View Impact Dashboard
                </button>
              )}
            </div>
            
            {/* Divider */}
            <div className="border-t border-zinc-800" />
            
            {/* Badges Section */}
            {(gamificationStats.badges?.length > 0 || gamificationStats.total_xp > 0) && (
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h3 className="text-white font-bold flex items-center gap-2">
                    <Award className="w-5 h-5 text-yellow-400" />
                    Badges
                  </h3>
                  <span className="text-sm text-gray-400">{gamificationStats.badges?.length || 0} earned</span>
                </div>
                
                {/* XP Bar */}
                {gamificationStats.total_xp > 0 && (
                  <div className="bg-zinc-800/50 rounded-xl p-3">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-sm text-gray-400">Level {gamificationStats.level || 1}</span>
                      <span className="text-sm text-yellow-400">{gamificationStats.total_xp} XP</span>
                    </div>
                    <div className="w-full h-2 bg-zinc-700 rounded-full overflow-hidden">
                      <div 
                        className="h-full bg-gradient-to-r from-yellow-500 to-orange-500"
                        style={{ width: `${Math.min(100, (gamificationStats.total_xp % 1000) / 10)}%` }}
                      />
                    </div>
                  </div>
                )}
                
                {/* Badge Grid */}
                {gamificationStats.badges?.length > 0 && (
                  <div className="grid grid-cols-4 sm:grid-cols-6 gap-3">
                    {gamificationStats.badges.map((badge, idx) => (
                      <div 
                        key={badge.id || idx}
                        className="flex flex-col items-center p-2 rounded-xl bg-zinc-800/50 hover:bg-zinc-700/50 transition-colors"
                        title={badge.description}
                      >
                        <div className="w-10 h-10 rounded-full bg-gradient-to-br from-yellow-400 to-orange-500 flex items-center justify-center mb-1">
                          {badge.icon_emoji || '🏆'}
                        </div>
                        <span className="text-[10px] text-gray-400 text-center truncate w-full">{badge.name}</span>
                      </div>
                    ))}
                  </div>
                )}
                
                {/* Divider */}
                <div className="border-t border-zinc-800 pt-3" />
              </div>
            )}
            
            {/* Crew Leaderboard */}
            <CrewLeaderboard 
              userId={profileUserId} 
              variant="profile"
              showPrivacyControls={isOwnProfile}
            />
          </div>
        ) : activeTab === 'grom_overview' && isGromParent ? (
          // Grom Overview Tab - Quick stats for Grom Parent
          <div className="p-4 space-y-4" data-testid="grom-overview-tab">
            {/* Quick Stats */}
            <div className="bg-gradient-to-br from-cyan-500/20 to-blue-500/20 rounded-2xl p-6 border border-cyan-500/30">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-full bg-cyan-500/20 flex items-center justify-center">
                    <Shield className="w-6 h-6 text-cyan-400" />
                  </div>
                  <div>
                    <h3 className="text-white font-bold text-lg">Grom HQ</h3>
                    <p className="text-cyan-400/80 text-sm">Parental Management</p>
                  </div>
                </div>
              </div>
              
              <div className="grid grid-cols-2 gap-4 mb-4">
                <div className="bg-zinc-900/60 rounded-xl p-3 text-center">
                  <div className="text-2xl font-bold text-cyan-400">0</div>
                  <div className="text-xs text-gray-400">Linked Groms</div>
                </div>
                <div className="bg-zinc-900/60 rounded-xl p-3 text-center">
                  <div className="text-2xl font-bold text-emerald-400">$0</div>
                  <div className="text-xs text-gray-400">Total Earnings</div>
                </div>
              </div>
              
              <p className="text-center text-sm text-gray-400 mb-4">
                Manage your linked Grom accounts, monitor activity, and control spending
              </p>
            </div>
            
            {/* View Full Dashboard CTA */}
            {isOwnProfile && (
              <button
                onClick={() => navigate('/grom-hq')}
                className="w-full py-3 bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-semibold rounded-lg transition-all"
                data-testid="view-grom-hq-btn"
              >
                Open Grom HQ Dashboard
              </button>
            )}
          </div>
        ) : activeTab === 'stoked' && isStokedEligible ? (
          // Stoked Tab - Surfer impact/credits received
          <StokedTab userId={profileUserId} isOwnProfile={isOwnProfile} />
        ) : activeTab === 'crew' ? (
          // Crew Tab - Crew stats, leaderboard, AND Badges (merged)
          <div className="p-4 space-y-6">
            {/* Badges Section - Show if user has badges */}
            {(gamificationStats.badges?.length > 0 || gamificationStats.total_xp > 0) && (
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h3 className="text-white font-bold flex items-center gap-2">
                    <Award className="w-5 h-5 text-yellow-400" />
                    Badges
                  </h3>
                  <span className="text-sm text-gray-400">{gamificationStats.badges?.length || 0} earned</span>
                </div>
                
                {/* XP Bar */}
                {gamificationStats.total_xp > 0 && (
                  <div className="bg-zinc-800/50 rounded-xl p-3">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-sm text-gray-400">Level {gamificationStats.level || 1}</span>
                      <span className="text-sm text-yellow-400">{gamificationStats.total_xp} XP</span>
                    </div>
                    <div className="w-full h-2 bg-zinc-700 rounded-full overflow-hidden">
                      <div 
                        className="h-full bg-gradient-to-r from-yellow-500 to-orange-500"
                        style={{ width: `${Math.min(100, (gamificationStats.total_xp % 1000) / 10)}%` }}
                      />
                    </div>
                  </div>
                )}
                
                {/* Badge Grid */}
                {gamificationStats.badges?.length > 0 && (
                  <div className="grid grid-cols-4 sm:grid-cols-6 gap-3">
                    {gamificationStats.badges.map((badge, idx) => (
                      <div 
                        key={badge.id || idx}
                        className="flex flex-col items-center p-2 rounded-xl bg-zinc-800/50 hover:bg-zinc-700/50 transition-colors"
                        title={badge.description}
                      >
                        <div className="w-10 h-10 rounded-full bg-gradient-to-br from-yellow-400 to-orange-500 flex items-center justify-center mb-1">
                          {badge.icon_emoji || '🏆'}
                        </div>
                        <span className="text-[10px] text-gray-400 text-center truncate w-full">{badge.name}</span>
                      </div>
                    ))}
                  </div>
                )}
                
                {/* Divider */}
                <div className="border-t border-zinc-800 pt-3" />
              </div>
            )}
            
            {/* Crew Leaderboard */}
            <CrewLeaderboard 
              userId={profileUserId} 
              variant="profile"
              showPrivacyControls={isOwnProfile}
            />
          </div>
        ) : activeTab === 'surfboards' ? (
          // Surfboards Tab
          <SurfboardsTab userId={profileUserId} isOwnProfile={isOwnProfile} />
        ) : activeTab === 'reviews' ? (
          // Reviews Tab
          <div className="p-4">
            <ProfileReviewsSection
              profileUserId={profileUserId}
              isPhotographer={isPhotographer}
              theme={theme}
            />
          </div>
        ) : tabLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-8 h-8 animate-spin text-yellow-500 dark:text-yellow-400" />
          </div>
        ) : tabContent.length === 0 ? (
          <div className="text-center py-12 px-4">
            <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-muted flex items-center justify-center">
              {activeTab === 'posts' && <Grid3X3 className="w-8 h-8 text-muted-foreground" />}
              {activeTab === 'photos' && <Image className="w-8 h-8 text-muted-foreground" />}
              {activeTab === 'session_shots' && <Waves className="w-8 h-8 text-muted-foreground" />}
              {activeTab === 'videos' && <Play className="w-8 h-8 text-muted-foreground" />}
              {activeTab === 'saved' && <Bookmark className="w-8 h-8 text-muted-foreground" />}
              {activeTab === 'tagged' && <UserSquare2 className="w-8 h-8 text-muted-foreground" />}
            </div>
            <h3 className="text-foreground font-semibold mb-1">
              {activeTab === 'posts' && 'No Posts Yet'}
              {activeTab === 'photos' && 'No Photos Yet'}
              {activeTab === 'session_shots' && 'No Session Shots Yet'}
              {activeTab === 'videos' && 'No Videos Yet'}
              {activeTab === 'saved' && 'No Saved Posts'}
              {activeTab === 'tagged' && 'No Tagged Photos'}
            </h3>
            <p className="text-muted-foreground text-sm">
              {activeTab === 'posts' && (isOwnProfile ? 'Share your surf moments with the community' : 'No posts to show')}
              {activeTab === 'photos' && (isOwnProfile ? 'Your photo posts will appear here' : 'No photos yet')}
              {activeTab === 'session_shots' && (isOwnProfile ? 'Pro shots from photographers will appear here' : 'No session shots yet')}
              {activeTab === 'videos' && (isOwnProfile ? 'Your video posts will show up here' : 'No videos yet')}
              {activeTab === 'saved' && 'Save posts from the feed to view them later'}
              {activeTab === 'tagged' && (isOwnProfile ? 'Photos you\'re tagged in will appear here' : 'No tagged photos')}
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-3 gap-0.5">
            {tabContent
              .filter(item => {
                // Basic existence check — show all posts regardless of media URL type.
                // Previously this filter hid videos with local /api/uploads/ paths, but
                // that caused legitimately stored videos to disappear from profile grids.
                const mediaItem = activeTab === 'saved' ? item?.post : item;
                return !!mediaItem;
              })
              .filter(item => {
                // Filter out items without media (ghost placeholders from deleted posts)
                // But allow check-in posts that might not have media
                const mediaItem = activeTab === 'saved' ? item?.post : item;
                if (!mediaItem) return false;
                
                // Has media - show it
                if (mediaItem.media_url || mediaItem.thumbnail_url || (mediaItem.media_urls && mediaItem.media_urls.length > 0)) {
                  return true;
                }
                
                // Check-in posts without media - show with placeholder
                if (mediaItem.is_check_in && mediaItem.location) {
                  return true;
                }
                
                // Posts with caption but no media (text posts) - show with placeholder
                if (mediaItem.caption && mediaItem.caption.trim().length > 0) {
                  return true;
                }
                
                return false;
              })
              .sort((a, b) => {
                // Sort pinned post to the top (only for posts tab)
                if (activeTab === 'posts' && profile?.pinned_post_id) {
                  if (a.id === profile.pinned_post_id) return -1;
                  if (b.id === profile.pinned_post_id) return 1;
                }
                return 0;
              })
              .map((item) => (
              <MediaGridItem 
                key={item.id} 
                item={activeTab === 'saved' ? item.post : item}
                isPinned={activeTab === 'posts' && profile?.pinned_post_id === item.id}
                onClick={async () => {
                  const mediaItem = activeTab === 'saved' ? item.post : item;
                  
                  // Open tagged photo modal for tagged items on own profile
                  if (activeTab === 'tagged' && isOwnProfile) {
                    setSelectedTaggedPhoto(item);
                    setShowTaggedPhotoModal(true);
                    return;
                  }
                  
                  // For Sessions tab: Photographer's shot sessions link to their gallery
                  if (activeTab === 'session_shots' && mediaItem?.is_photographer_session && mediaItem?.gallery_id) {
                    navigate(`/gallery/${mediaItem.gallery_id}`);
                    return;
                  }
                  
                  // Navigate to single post view for all other content
                  if (mediaItem?.id) {
                    navigate(`/post/${mediaItem.id}`);
                  }
                }}
              />
            ))}
          </div>
        )}
      </div>

      {/* Tagged Photo Modal */}
      {isOwnProfile && (
        <TaggedPhotoModal
          isOpen={showTaggedPhotoModal}
          onClose={() => {
            setShowTaggedPhotoModal(false);
            setSelectedTaggedPhoto(null);
          }}
          photo={selectedTaggedPhoto}
          onPhotoViewed={(photoId) => {
            // Update local state to remove NEW badge
            setTabContent(prev => prev.map(p => 
              p.id === photoId ? { ...p, is_new: false } : p
            ));
          }}
        />
      )}

      {/* Avatar Crop Modal */}
      {cropFile && (
        <AvatarCropModal
          imageFile={cropFile}
          onConfirm={handleCropConfirm}
          onCancel={() => setCropFile(null)}
        />
      )}

      {/* Edit Profile Modal (extracted component) */}
      <ProfileEditModal
        isOpen={showEditModal}
        onClose={setShowEditModal}
        editData={editData}
        setEditData={setEditData}
        onSave={handleSaveProfile}
        editLoading={editLoading}
      />

      {/* ============ SCHEDULED BOOKING DRAWER ============ */}
      <ScheduledBookingDrawer
        isOpen={quickBookHook.showScheduledBookingDrawer}
        onClose={() => quickBookHook.setShowScheduledBookingDrawer(false)}
        photographer={{
          id: profileUserId,
          full_name: profile?.full_name,
          avatar_url: profile?.avatar_url,
          role: profile?.role,
          home_break: profile?.home_break,
          booking_hourly_rate: quickBookHook.photographerPricing?.booking_hourly_rate || profile?.booking_hourly_rate,
          hourly_rate: quickBookHook.photographerPricing?.hourly_rate || profile?.hourly_rate,
          session_price: quickBookHook.photographerPricing?.session_price || profile?.session_price,
          group_discount_2_plus: quickBookHook.photographerPricing?.group_discount_2_plus || profile?.group_discount_2_plus,
          group_discount_3_plus: quickBookHook.photographerPricing?.group_discount_3_plus || profile?.group_discount_3_plus,
          group_discount_5_plus: quickBookHook.photographerPricing?.group_discount_5_plus || profile?.group_discount_5_plus,
          service_radius_miles: profile?.service_radius_miles,
          home_latitude: profile?.home_latitude,
          home_longitude: profile?.home_longitude,
          travel_surcharges: profile?.travel_surcharges,
          charges_travel_fees: profile?.charges_travel_fees
        }}
        onSuccess={(_result) => {
          quickBookHook.setShowScheduledBookingDrawer(false);
          toast.success('Booking submitted successfully!');
        }}
      />

      {/* Go Live Modal with Camera */}
      <GoLiveModal
        isOpen={showGoLiveModal}
        onClose={() => setShowGoLiveModal(false)}
        onStreamEnded={handleGoLiveEnded}
      />

      {/* Note Modal (extracted component) */}
      <ProfileNoteModal
        isOpen={notesHook.showNoteModal}
        onClose={notesHook.setShowNoteModal}
        isOwnProfile={isOwnProfile}
        profileName={profile.full_name}
        userNote={notesHook.userNote}
        noteText={notesHook.noteText}
        setNoteText={notesHook.setNoteText}
        noteSubmitting={notesHook.noteSubmitting}
        onCreateNote={notesHook.handleCreateNote}
        onDeleteNote={notesHook.handleDeleteNote}
      />

      {/* Followers/Following Modal */}
      <FollowersModal
        isOpen={showFollowersModal}
        onClose={() => setShowFollowersModal(false)}
        userId={profileUserId}
        type={followersModalType}
        userName={profile?.username ? `@${profile.username}` : profile?.full_name}
      />
      
      {/* Block User Modal (extracted component) */}
      <ProfileBlockModal
        isOpen={blockHook.showBlockModal}
        onClose={blockHook.setShowBlockModal}
        profileName={profile?.full_name}
        blockReason={blockHook.blockReason}
        setBlockReason={blockHook.setBlockReason}
        blockNotes={blockHook.blockNotes}
        setBlockNotes={blockHook.setBlockNotes}
        blockLoading={blockHook.blockLoading}
        onBlock={() => blockHook.handleBlockUser(profile?.full_name)}
      />
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useSearchParams, useNavigate, useParams } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { 
  Camera, Image, Play, ShoppingCart, Grid, LayoutGrid, MapPin, Check,
  Sparkles, Star, ArrowLeft, User, Lock,
  Zap, Radio, CalendarCheck, Folder, Search, ScanFace
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Card } from './ui/card';
import { Input } from './ui/input';
import { LockerSelfieModal } from './LockerSelfieModal';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { toast } from 'sonner';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';
import { isGrom } from '../lib/roles';


// Gallery View Modes
const VIEW_MODES = {
  GRID: 'grid',
  MASONRY: 'masonry',
  LIST: 'list'
};

// Service Types for filtering
const _SERVICE_TYPES = [
  { id: 'all', label: 'All Photos', icon: Image },
  { id: 'live_session', label: 'Live Sessions', icon: Radio },
  { id: 'booking', label: 'Bookings', icon: CalendarCheck },
  { id: 'on_demand', label: 'On-Demand', icon: Zap },
  { id: 'portfolio', label: 'Portfolio', icon: Star }
];

export const PublicPhotographerGallery = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { photographerId: paramPhotographerId } = useParams();
  
  // Get photographer ID from URL params or query string
  const photographerId = paramPhotographerId || searchParams.get('photographer');
  // Deep-link: ?gallery=<id> auto-selects a specific session gallery tab
  const deepLinkGalleryId = searchParams.get('gallery');
  
  // State
  const [photographer, setPhotographer] = useState(null);
  const [galleries, setGalleries] = useState([]);
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedGallery, setSelectedGallery] = useState(null);
  const [selectedItem, setSelectedItem] = useState(null);
  const [viewMode, setViewMode] = useState(VIEW_MODES.GRID);
  const [serviceFilter, _setServiceFilter] = useState('all');
  const [_showFilters, _setShowFilters] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState('newest');
  const [purchasedIds, setPurchasedIds] = useState(new Set());
  const [showPurchaseModal, setShowPurchaseModal] = useState(false);
  const [purchaseLoading, setPurchaseLoading] = useState(false);
  const [selectedQuality, setSelectedQuality] = useState('standard');
  const [galleriesReady, setGalleriesReady] = useState(false);
  
  // AI Face Match state
  const [showAIMatch, setShowAIMatch] = useState(false);
  const [aiMatchResults, setAIMatchResults] = useState([]);
  const [_aiMatchLoading, setAIMatchLoading] = useState(false);
  
  // New Find Me Selfie Scanner state
  const [scanModalOpen, setScanModalOpen] = useState(false);

  // Swipe-to-navigate state for mobile gallery switching
  const swipeStartXRef = useRef(0);
  const swipeStartYRef = useRef(0);
  const swipeActiveRef = useRef(false);
  const swipeDragRef = useRef(0);
  const swipeLockedRef = useRef(false);
  const galleryContentRef = useRef(null);
  const galleryPillsRef = useRef(null);
  const [isAnimating, setIsAnimating] = useState(false);

  // Theme classes
  const isLight = theme === 'light';
  const isBeach = theme === 'beach';
  const mainBg = isLight ? 'bg-gray-50' : isBeach ? 'bg-black' : 'bg-zinc-950';
  const cardBg = isLight ? 'bg-white border-gray-200' : isBeach ? 'bg-zinc-950 border-zinc-800' : 'bg-zinc-900 border-zinc-800';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-500' : isBeach ? 'text-gray-300' : 'text-zinc-400';
  const borderColor = isLight ? 'border-gray-200' : isBeach ? 'border-zinc-800' : 'border-zinc-700';
  const inputBg = isLight ? 'bg-white border-gray-300 text-gray-900' : 'bg-zinc-900 border-zinc-700 text-white';
  const coverGradient = isLight
    ? 'bg-gradient-to-r from-emerald-100 via-gray-100 to-yellow-100'
    : 'bg-gradient-to-r from-emerald-900/50 via-zinc-900 to-yellow-900/50';
  const avatarBorder = isLight ? 'border-white' : 'border-black';
  const avatarBg = isLight ? 'bg-gray-200' : 'bg-zinc-800';
  const pillActive = isLight ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-black border-white';
  const pillInactive = isLight
    ? 'bg-white text-gray-600 border-gray-300 hover:border-gray-400'
    : 'bg-zinc-900 text-zinc-300 border-zinc-700 hover:border-zinc-500';
  const skeletonBg = isLight ? 'bg-gray-200' : 'bg-zinc-800';
  const cardItemBg = isLight ? 'bg-gray-100' : 'bg-zinc-800';
  const modalBg = isLight ? 'bg-white border-gray-200 text-gray-900' : 'bg-zinc-900 border-zinc-700 text-white';
  const viewToggleBg = isLight ? 'border-gray-300' : 'border-zinc-700';
  const viewToggleActive = isLight ? 'bg-gray-200' : 'bg-zinc-700';
  const viewToggleInactive = isLight ? 'bg-white' : 'bg-zinc-900';

  // Fetch photographer profile
  const fetchPhotographer = useCallback(async () => {
    if (!photographerId) return;
    
    try {
      const res = await apiClient.get(`/profiles/${photographerId}`);
      setPhotographer(res.data);
    } catch (error) {
      logger.error('Failed to fetch photographer:', error);
      toast.error('Photographer not found');
    }
  }, [photographerId]);

  // Fetch photographer's galleries (albums)
  const fetchGalleries = useCallback(async () => {
    if (!photographerId) return;
    
    try {
      const res = await apiClient.get(`/galleries/photographer/${photographerId}`);
      // Only show public galleries, and exclude private sessions (on_demand/booking)
      const PRIVATE_SESSION_TYPES = ['on_demand', 'booking'];
      setGalleries(res.data.filter(g => g.is_public && !PRIVATE_SESSION_TYPES.includes(g.session_type)));
      setGalleriesReady(true);
    } catch (error) {
      logger.error('Failed to fetch galleries:', error);
      setGalleriesReady(true); // Mark ready even on error so UI doesn't hang
    }
  }, [photographerId]);

  // Fetch gallery items
  const fetchItems = useCallback(async () => {
    if (!photographerId) return;
    
    try {
      setLoading(true);
      let url = `/gallery/photographer/${photographerId}?include_in_folders=true&limit=100`;
      if (user?.id) {
        url += `&viewer_id=${user.id}`;
      }
      
      const res = await apiClient.get(url);
      setItems(res.data);
      
      // Track purchased items
      if (user?.id) {
        const purchased = new Set(res.data.filter(i => i.is_purchased).map(i => i.id));
        setPurchasedIds(purchased);
      }
    } catch (error) {
      logger.error('Failed to fetch gallery items:', error);
    } finally {
      setLoading(false);
    }
  }, [photographerId, user?.id]);

  // AI Face Match - Find photos of the current user
  const _runAIFaceMatch = async () => {
    if (!user?.id || !photographerId) {
      toast.error('Please log in to find your photos');
      return;
    }
    
    setAIMatchLoading(true);
    try {
      const res = await apiClient.post(`/ai/face-match`, {
        photographer_id: photographerId,
        surfer_id: user.id
      });
      setAIMatchResults(res.data.matches || []);
      setShowAIMatch(true);
      
      if (res.data.matches?.length > 0) {
        toast.success(`Found ${res.data.matches.length} photos that might be you!`);
      } else {
        toast.info('No matching photos found yet. Check back after your session!');
      }
    } catch (error) {
      logger.error('AI face match failed:', error);
      toast.error('Face matching unavailable');
    } finally {
      setAIMatchLoading(false);
    }
  };

  // Purchase item
  const handlePurchase = async () => {
    if (!user?.id || !selectedItem) {
      toast.error('Please log in to purchase');
      return;
    }
    if (isGrom(user)) {
      toast.info('🤙 Ask your parent to approve this purchase!');
      return;
    }
    
    setPurchaseLoading(true);
    try {
      const _res = await apiClient.post(`/gallery/${selectedItem.id}/purchase`, {
        buyer_id: user.id,
        quality_tier: selectedQuality
      });
      
      toast.success('Purchase successful!');
      setPurchasedIds(prev => new Set([...prev, selectedItem.id]));
      setShowPurchaseModal(false);
      setSelectedItem(null);
      
      // Refresh items to get download URL
      fetchItems();
    } catch (error) {
      logger.error('Purchase failed:', error);
      toast.error(error.response?.data?.detail || 'Purchase failed');
    } finally {
      setPurchaseLoading(false);
    }
  };

  // Filter and sort items
  const filteredItems = items
    .filter(item => {
      // Service type filter
      if (serviceFilter !== 'all') {
        // This would require service_type on items - for now, show all
      }
      
      // Gallery filter
      if (selectedGallery && item.gallery_id !== selectedGallery.id) {
        return false;
      }
      
      // Search filter
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        return (
          item.title?.toLowerCase().includes(query) ||
          item.description?.toLowerCase().includes(query) ||
          item.spot_name?.toLowerCase().includes(query) ||
          item.tags?.some(t => t.toLowerCase().includes(query))
        );
      }
      
      return true;
    })
    .sort((a, b) => {
      switch (sortBy) {
        case 'newest':
          return new Date(b.created_at) - new Date(a.created_at);
        case 'oldest':
          return new Date(a.created_at) - new Date(b.created_at);
        case 'price_low':
          return (a.custom_price || a.price) - (b.custom_price || b.price);
        case 'price_high':
          return (b.custom_price || b.price) - (a.custom_price || a.price);
        case 'popular':
          return b.purchase_count - a.purchase_count;
        default:
          return 0;
      }
    });

  useEffect(() => {
    if (photographerId) {
      fetchPhotographer();
      fetchGalleries();
      fetchItems();
    }
  }, [photographerId, fetchPhotographer, fetchGalleries, fetchItems]);

  // Auto-select gallery tab: deep-link first, then default to first gallery
  useEffect(() => {
    if (galleries.length > 0 && !selectedGallery) {
      if (deepLinkGalleryId) {
        const target = galleries.find(g => g.id === deepLinkGalleryId);
        if (target) {
          setSelectedGallery(target);
          return;
        }
      }
      // No deep-link or target not found — default to first gallery
      setSelectedGallery(galleries[0]);
    }
  }, [deepLinkGalleryId, galleries, selectedGallery]);

  // Auto-scroll active gallery pill into view after swipe or selection change
  useEffect(() => {
    if (!selectedGallery || !galleryPillsRef.current) return;
    const activeBtn = galleryPillsRef.current.querySelector(
      `[data-gallery-id="${selectedGallery.id}"]`
    );
    if (activeBtn) {
      activeBtn.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
    }
  }, [selectedGallery]);

  // Swipe handler: navigate between gallery folders
  const handleSwipeGallery = useCallback((direction) => {
    if (!selectedGallery || galleries.length <= 1) return;
    const currentIdx = galleries.findIndex(g => g.id === selectedGallery.id);
    const nextIdx = direction === 'left' ? currentIdx + 1 : currentIdx - 1;
    if (nextIdx >= 0 && nextIdx < galleries.length) {
      setIsAnimating(true);
      if (galleryContentRef.current) {
        galleryContentRef.current.style.transition = 'transform 0.22s ease-out, opacity 0.22s ease-out';
        galleryContentRef.current.style.transform = `translateX(${direction === 'left' ? '-100%' : '100%'})`;
        galleryContentRef.current.style.opacity = '0';
      }
      setTimeout(() => {
        setSelectedGallery(galleries[nextIdx]);
        if (galleryContentRef.current) {
          galleryContentRef.current.style.transition = 'none';
          galleryContentRef.current.style.transform = `translateX(${direction === 'left' ? '60%' : '-60%'})`;
          galleryContentRef.current.style.opacity = '0.5';
        }
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            if (galleryContentRef.current) {
              galleryContentRef.current.style.transition = 'transform 0.25s ease-out, opacity 0.25s ease-out';
              galleryContentRef.current.style.transform = 'translateX(0)';
              galleryContentRef.current.style.opacity = '1';
            }
            setTimeout(() => {
              setIsAnimating(false);
              if (galleryContentRef.current) {
                galleryContentRef.current.style.transition = '';
                galleryContentRef.current.style.transform = '';
                galleryContentRef.current.style.opacity = '';
              }
            }, 260);
          });
        });
      }, 200);
    }
  }, [selectedGallery, galleries]);

  // Get price for quality tier
  const getQualityPrice = (item, quality) => {
    if (!item) return 5; // Default price if item is null
    
    if (item.media_type === 'video') {
      switch (quality) {
        case '720p': return item.price_720p || item.price || 10;
        case '1080p': return item.price_1080p || (item.price || 10) * 1.5;
        case '4k': return item.price_4k || (item.price || 10) * 2;
        default: return item.price || 10;
      }
    } else {
      switch (quality) {
        case 'web': return item.price_web || (item.price || 5) * 0.5;
        case 'standard': return item.custom_price || item.price || 5;
        case 'high': return item.price_high || (item.price || 5) * 2;
        default: return item.custom_price || item.price || 5;
      }
    }
  };

  if (!photographerId) {
    return (
      <div className={`min-h-screen ${mainBg} flex items-center justify-center`}>
        <div className="text-center">
          <Camera className={`w-16 h-16 ${textSecondary} mx-auto mb-4`} />
          <h2 className={`text-xl ${textPrimary} mb-2`}>No Photographer Selected</h2>
          <p className={`${textSecondary} mb-4`}>Browse our photographer directory to find amazing surf shots</p>
          <Button onClick={() => navigate('/explore')} className="bg-gradient-to-r from-emerald-500 to-yellow-500">
            Find Photographers
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${mainBg}`}>
      {/* Photographer Header */}
      <div className="relative">
        {/* Cover gradient */}
        <div className={`h-32 ${coverGradient}`} />
        
        {/* Profile section */}
        <div className="max-w-7xl mx-auto px-4 -mt-16">
          <div className="flex flex-col md:flex-row items-start md:items-end gap-4 pb-6">
            {/* Back button */}
            <Button 
              variant="ghost" 
              onClick={() => navigate(-1)}
              className={`absolute top-4 left-4 ${isLight ? 'text-gray-500 hover:text-gray-900' : 'text-white/70 hover:text-white'}`}
            >
              <ArrowLeft className="w-5 h-5 mr-2" />
              Back
            </Button>
            
            {/* Avatar */}
            <div className={`w-28 h-28 rounded-full border-4 ${avatarBorder} overflow-hidden ${avatarBg}`}>
              {photographer?.avatar_url ? (
                <img 
                  src={getFullUrl(photographer.avatar_url)}
                  alt={photographer?.full_name}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center">
                  <User className={`w-12 h-12 ${textSecondary}`} />
                </div>
              )}
            </div>
            
            {/* Info */}
            <div className="flex-1">
              <div className="flex items-center gap-2 mb-1">
                <h1 className={`text-2xl font-bold ${textPrimary}`}>{photographer?.full_name || 'Photographer'}</h1>
                {photographer?.is_approved_pro && (
                  <Badge className="bg-gradient-to-r from-emerald-500 to-yellow-500 text-black">
                    <Check className="w-3 h-3 mr-1" />
                    Verified Pro
                  </Badge>
                )}
              </div>
              {photographer?.username && (
                <p 
                  className={`${textSecondary} mb-2 cursor-pointer hover:underline hover:text-cyan-400 transition-colors`}
                  onClick={() => navigate(`/profile/${photographerId}`)}
                >@{photographer.username}</p>
              )}
              {photographer?.bio && (
                <p className={`${isLight ? 'text-gray-600' : 'text-zinc-300'} text-sm max-w-xl`}>{photographer.bio}</p>
              )}
            </div>
            
            {/* Actions */}
            <div className="flex gap-2">
              <Button 
                onClick={() => navigate(`/profile/${photographerId}`)}
                variant="outline"
                className={`${borderColor} ${textPrimary} ${isLight ? 'hover:bg-gray-100' : 'hover:bg-zinc-800'}`}
              >
                View Profile
              </Button>
              <Button 
                onClick={() => navigate(`/profile/${photographerId}`)}
                className="bg-gradient-to-r from-emerald-500 to-yellow-500 text-black font-semibold"
              >
                <CalendarCheck className="w-4 h-4 mr-2" />
                Book Session
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 py-6">
        {/* AI Face Match Banner */}
        {user && (
          <Card className={`${isLight ? 'bg-gradient-to-r from-purple-100 to-pink-100 border-purple-300' : 'bg-gradient-to-r from-purple-900/30 to-pink-900/30 border-purple-500/30'} mb-6 p-4`}>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-purple-500/20 flex items-center justify-center">
                  <Sparkles className="w-5 h-5 text-purple-400" />
                </div>
                <div>
                  <h3 className={`${textPrimary} font-semibold`}>AI Photo Finder</h3>
                  <p className={`${textSecondary} text-sm`}>Let AI find photos of you using facial recognition</p>
                </div>
              </div>
              <Button 
                onClick={() => setScanModalOpen(true)}
                className="bg-cyan-600 hover:bg-cyan-700 text-white font-semibold"
              >
                <ScanFace className="w-4 h-4 mr-2" />
                Find My Photos
              </Button>
            </div>
          </Card>
        )}

        {/* Galleries/Albums Row */}
        {galleries.length > 0 && (
          <div className="mb-6">
            <h2 className={`text-lg font-semibold ${textPrimary} mb-3`}>Session Galleries</h2>
            <div ref={galleryPillsRef} className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
              {galleries.map(gallery => (
                <button
                  key={gallery.id}
                  data-gallery-id={gallery.id}
                  onClick={() => setSelectedGallery(gallery)}
                  className={`flex-shrink-0 px-4 py-2 rounded-full border transition-all flex items-center gap-2 max-w-[75vw] ${
                    selectedGallery?.id === gallery.id 
                      ? pillActive 
                      : pillInactive
                  }`}
                >
                  <Folder className="w-4 h-4 flex-shrink-0" />
                  <span className="truncate">{gallery.title}</span>
                  <span className="text-xs opacity-60 flex-shrink-0">({gallery.item_count})</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Swipeable content area — swipe left/right to switch gallery folders on mobile */}
        <div
          className="relative overflow-hidden"
          onTouchStart={(e) => {
            if (isAnimating) return;
            swipeStartXRef.current = e.touches[0].clientX;
            swipeStartYRef.current = e.touches[0].clientY;
            swipeActiveRef.current = true;
            swipeLockedRef.current = false;
            swipeDragRef.current = 0;
            if (galleryContentRef.current) {
              galleryContentRef.current.style.transition = 'none';
            }
          }}
          onTouchMove={(e) => {
            if (!swipeActiveRef.current || isAnimating) return;
            const dx = e.touches[0].clientX - swipeStartXRef.current;
            const dy = e.touches[0].clientY - swipeStartYRef.current;
            if (!swipeLockedRef.current) {
              // If vertical scroll dominates, cancel swipe
              if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 10) {
                swipeActiveRef.current = false;
                if (galleryContentRef.current) {
                  galleryContentRef.current.style.transform = '';
                  galleryContentRef.current.style.transition = '';
                }
                return;
              }
              if (Math.abs(dx) > 10) {
                swipeLockedRef.current = true;
              } else {
                return;
              }
            }
            e.preventDefault();
            const currentIdx = galleries.findIndex(g => g.id === selectedGallery?.id);
            const atEdge = (dx > 0 && currentIdx === 0) || (dx < 0 && currentIdx === galleries.length - 1);
            const dampened = atEdge ? dx * 0.2 : dx;
            swipeDragRef.current = dampened;
            if (galleryContentRef.current) {
              galleryContentRef.current.style.transform = `translateX(${dampened}px)`;
              const progress = Math.min(Math.abs(dampened) / 200, 1);
              galleryContentRef.current.style.opacity = `${1 - progress * 0.15}`;
            }
          }}
          onTouchEnd={() => {
            if (!swipeActiveRef.current || isAnimating) {
              swipeActiveRef.current = false;
              return;
            }
            swipeActiveRef.current = false;
            const dragX = swipeDragRef.current;
            const MIN_SWIPE = 50;
            if (Math.abs(dragX) >= MIN_SWIPE && swipeLockedRef.current) {
              const goingLeft = dragX < 0;
              handleSwipeGallery(goingLeft ? 'left' : 'right');
              return;
            }
            // Snap back
            if (galleryContentRef.current) {
              galleryContentRef.current.style.transition = 'transform 0.2s ease-out, opacity 0.2s ease-out';
              galleryContentRef.current.style.transform = 'translateX(0)';
              galleryContentRef.current.style.opacity = '1';
              setTimeout(() => {
                if (galleryContentRef.current) {
                  galleryContentRef.current.style.transition = '';
                  galleryContentRef.current.style.transform = '';
                  galleryContentRef.current.style.opacity = '';
                }
              }, 220);
            }
          }}
        >
        <div ref={galleryContentRef} className="will-change-transform">

        {/* Filters Bar */}
        <div className="flex flex-wrap items-center gap-3 mb-6">
          {/* Search */}
          <div className="relative flex-1 min-w-[200px] max-w-md">
            <Search className={`absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 ${textSecondary}`} />
            <Input
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              placeholder="Search photos..."
              className={`pl-10 ${inputBg}`}
            />
          </div>
          
          {/* Sort */}
          <select
            value={sortBy}
            onChange={e => setSortBy(e.target.value)}
            className={`px-3 py-2 ${inputBg} border rounded-md text-sm`}
          >
            <option value="newest">Newest First</option>
            <option value="oldest">Oldest First</option>
            <option value="price_low">Price: Low to High</option>
            <option value="price_high">Price: High to Low</option>
            <option value="popular">Most Popular</option>
          </select>
          
          {/* View Mode */}
          <div className={`flex border ${viewToggleBg} rounded-md overflow-hidden`}>
            <button
              onClick={() => setViewMode(VIEW_MODES.GRID)}
              className={`p-2 ${viewMode === VIEW_MODES.GRID ? viewToggleActive : viewToggleInactive}`}
            >
              <Grid className={`w-4 h-4 ${textPrimary}`} />
            </button>
            <button
              onClick={() => setViewMode(VIEW_MODES.MASONRY)}
              className={`p-2 ${viewMode === VIEW_MODES.MASONRY ? viewToggleActive : viewToggleInactive}`}
            >
              <LayoutGrid className={`w-4 h-4 ${textPrimary}`} />
            </button>
          </div>
          
          {/* Results count */}
          <span className={`${textSecondary} text-sm ml-auto`}>
            {filteredItems.length} {filteredItems.length === 1 ? 'photo' : 'photos'}
          </span>
        </div>

        {/* Gallery Grid */}
        {(loading || (!galleriesReady) || (galleries.length > 0 && !selectedGallery)) ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {[...Array(8)].map((_, i) => (
              <div key={i} className={`aspect-square ${skeletonBg} rounded-lg animate-pulse`} />
            ))}
          </div>
        ) : filteredItems.length === 0 ? (
          <div className="text-center py-20">
            <Image className={`w-16 h-16 ${textSecondary} mx-auto mb-4`} />
            <h3 className={`text-xl ${textPrimary} mb-2`}>No Photos Yet</h3>
            <p className={textSecondary}>Check back after your session with this photographer</p>
          </div>
        ) : (
          <div className={`
            ${viewMode === VIEW_MODES.GRID 
              ? 'grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4' 
              : 'columns-2 md:columns-3 lg:columns-4 gap-4'
            }
          `}>
            {filteredItems.map(item => (
              <GalleryItemCard
                key={item.id}
                item={item}
                isPurchased={purchasedIds.has(item.id)}
                viewMode={viewMode}
                isLight={isLight}
                onClick={() => {
                  setSelectedItem(item);
                  if (!purchasedIds.has(item.id)) {
                    setShowPurchaseModal(true);
                  }
                }}
              />
            ))}
          </div>
        )}

        </div>{/* end galleryContentRef */}
        </div>{/* end swipe container */}
      </div>

      {/* Purchase Modal */}
      <Dialog open={showPurchaseModal} onOpenChange={setShowPurchaseModal}>
        <DialogContent className={`${modalBg} max-w-lg`}>
          <DialogHeader>
            <DialogTitle>Purchase {selectedItem?.media_type === 'video' ? 'Video' : 'Photo'}</DialogTitle>
          </DialogHeader>
          
          {selectedItem && (
            <div className="space-y-4">
              {/* Preview */}
              <div className={`relative aspect-video ${cardItemBg} rounded-lg overflow-hidden`}>
                {selectedItem.media_type === 'video' ? (
                  <video 
                    src={selectedItem.preview_url || selectedItem.thumbnail_url}
                    className="w-full h-full object-contain"
                    muted
                    loop
                    playsInline
                    preload="none"
                    poster={selectedItem.thumbnail_url || undefined}
                  />
                ) : (
                  <img 
                    src={selectedItem.preview_url || selectedItem.thumbnail_url}
                    alt={selectedItem.title || 'Gallery item'}
                    className="w-full h-full object-contain"
                  />
                )}
                <div className="absolute inset-0 flex items-center justify-center bg-black/30">
                  <Lock className="w-8 h-8 text-white/50" />
                </div>
              </div>
              
              {/* Quality Selection */}
              <div>
                <label className={`text-sm ${textSecondary} mb-2 block`}>Select Quality</label>
                <div className="grid grid-cols-3 gap-2">
                  {selectedItem.media_type === 'video' ? (
                    <>
                      <QualityOption
                        label="720p HD"
                        price={getQualityPrice(selectedItem, '720p')}
                        selected={selectedQuality === '720p'}
                        onClick={() => setSelectedQuality('720p')}
                        isLight={isLight}
                      />
                      <QualityOption
                        label="1080p Full HD"
                        price={getQualityPrice(selectedItem, '1080p')}
                        selected={selectedQuality === '1080p'}
                        onClick={() => setSelectedQuality('1080p')}
                        recommended
                        isLight={isLight}
                      />
                      <QualityOption
                        label="4K Ultra HD"
                        price={getQualityPrice(selectedItem, '4k')}
                        selected={selectedQuality === '4k'}
                        onClick={() => setSelectedQuality('4k')}
                        isLight={isLight}
                      />
                    </>
                  ) : (
                    <>
                      <QualityOption
                        label="Web"
                        sublabel="Social media"
                        price={getQualityPrice(selectedItem, 'web')}
                        selected={selectedQuality === 'web'}
                        onClick={() => setSelectedQuality('web')}
                        isLight={isLight}
                      />
                      <QualityOption
                        label="Standard"
                        sublabel="Print ready"
                        price={getQualityPrice(selectedItem, 'standard')}
                        selected={selectedQuality === 'standard'}
                        onClick={() => setSelectedQuality('standard')}
                        recommended
                        isLight={isLight}
                      />
                      <QualityOption
                        label="High Res"
                        sublabel="Full quality"
                        price={getQualityPrice(selectedItem, 'high')}
                        selected={selectedQuality === 'high'}
                        onClick={() => setSelectedQuality('high')}
                        isLight={isLight}
                      />
                    </>
                  )}
                </div>
              </div>
              
              {/* Photographer info */}
              <div className={`flex items-center gap-3 p-3 ${cardItemBg} rounded-lg`}>
                <div className={`w-10 h-10 rounded-full ${isLight ? 'bg-gray-300' : 'bg-zinc-700'} overflow-hidden`}>
                  {selectedItem.photographer_avatar ? (
                    <img src={selectedItem.photographer_avatar} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <User className="w-6 h-6 text-zinc-500 m-auto mt-2" />
                  )}
                </div>
                <div className="flex-1">
                  <p className={`text-sm ${textPrimary} font-medium`}>{selectedItem.photographer_name}</p>
                  <p className={`text-xs ${textSecondary}`}>Photographer</p>
                </div>
                <div className="text-right">
                  <p className="text-lg font-bold text-emerald-400">
                    ${getQualityPrice(selectedItem, selectedQuality).toFixed(2)}
                  </p>
                </div>
              </div>
            </div>
          )}
          
          <DialogFooter className="gap-2">
            <Button variant="outline" onClick={() => setShowPurchaseModal(false)} className={borderColor}>
              Cancel
            </Button>
            <Button 
              onClick={handlePurchase}
              disabled={purchaseLoading}
              className="bg-gradient-to-r from-emerald-500 to-yellow-500 text-black font-semibold"
            >
              {purchaseLoading ? (
                <>
                  <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin mr-2" />
                  Processing...
                </>
              ) : (
                <>
                  <ShoppingCart className="w-4 h-4 mr-2" />
                  Purchase for ${getQualityPrice(selectedItem, selectedQuality).toFixed(2)}
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* AI Match Results Modal */}
      <Dialog open={showAIMatch} onOpenChange={setShowAIMatch}>
        <DialogContent className={`${modalBg} max-w-2xl`}>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-purple-400" />
              AI Found Your Photos
            </DialogTitle>
          </DialogHeader>
          
          {aiMatchResults.length > 0 ? (
            <div className="grid grid-cols-2 gap-4 max-h-96 overflow-y-auto">
              {aiMatchResults.map(match => (
                <div 
                  key={match.id}
                  className={`relative aspect-square ${cardItemBg} rounded-lg overflow-hidden cursor-pointer hover:ring-2 ring-purple-500 transition-all`}
                  onClick={() => {
                    setSelectedItem(items.find(i => i.id === match.id));
                    setShowAIMatch(false);
                    setShowPurchaseModal(true);
                  }}
                >
                  <img 
                    src={match.preview_url || match.thumbnail_url}
                    alt="Matched photo"
                    className="w-full h-full object-cover"
                  />
                  <div className="absolute top-2 right-2">
                    <Badge className="bg-purple-600 text-white text-xs">
                      {Math.round(match.confidence * 100)}% match
                    </Badge>
                  </div>
                  <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/80 to-transparent p-3">
                    <p className="text-white text-sm font-semibold">${match.price || 5}</p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8">
              <Sparkles className={`w-12 h-12 ${textSecondary} mx-auto mb-4`} />
              <p className={textSecondary}>No matching photos found yet</p>
              <p className={`${textSecondary} text-sm mt-2`}>Photos will appear here after your session</p>
            </div>
          )}
        </DialogContent>
      </Dialog>
      
      {/* Targeted Locker Selfie Scanner */}
      <LockerSelfieModal 
        isOpen={scanModalOpen}
        onClose={() => setScanModalOpen(false)}
        user={user}
        photographerId={photographer?.id}
        photographerName={photographer?.full_name}
      />
    </div>
  );
};

// Gallery Item Card Component
const GalleryItemCard = ({ item, isPurchased, viewMode, isLight, onClick }) => {
