      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onClick={onClick}
    >
      {item.media_type === 'video' ? (
        <video 
          className={`
            w-full h-full object-cover transition-transform duration-300
            ${isHovered ? 'scale-105' : 'scale-100'}
