                      <>
                        <Check className="w-4 h-4 mr-2" />
                        Confirm
                      </>
                    )}
                  </Button>
                </>
              )}
            </div>
            
            {/* Skip option */}
            <button
              onClick={skipSelfie}
              className="w-full text-center text-gray-500 text-sm hover:text-gray-300 py-2"
            >
              Skip for now
            </button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

