/**
 * RichText - Renders text with clickable #hashtags and @mentions
 * 
 * Best practices from social media:
 * - Instagram: #hashtags are blue/teal, clickable to hashtag search
 * - Twitter/X: #hashtags and @mentions are blue, clickable
 * - TikTok: #hashtags are bold, clickable
 * 
 * Our implementation:
 * - #hashtags: Cyan color, navigate to /explore?hashtag={tag}
 * - @mentions: Blue color, navigate to /profile/{username}
 */
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient from '../lib/apiClient';
import { toast } from 'sonner';

// Regex patterns for matching
const HASHTAG_REGEX = /#(\w+)/g;
const MENTION_REGEX = /@(\w+)/g;
const URL_REGEX = /(https?:\/\/[^\s]+)/g;

/**
 * Parse text and return array of segments with type information
 */
const parseText = (text) => {
  if (!text) return [];
  
  const segments = [];
  let lastIndex = 0;
  
  // Combine all patterns with their types
  const patterns = [
    { regex: HASHTAG_REGEX, type: 'hashtag' },
    { regex: MENTION_REGEX, type: 'mention' },
    { regex: URL_REGEX, type: 'url' }
  ];
  
  // Find all matches with their positions
  const matches = [];
  
  patterns.forEach(({ regex, type }) => {
    let match;
    const re = new RegExp(regex.source, 'g');
    while ((match = re.exec(text)) !== null) {
      matches.push({
        type,
        match: match[0],
        value: match[1] || match[0], // Captured group or full match
        start: match.index,
        end: match.index + match[0].length
      });
    }
  });
  
  // Sort by position
  matches.sort((a, b) => a.start - b.start);
  
  // Remove overlapping matches (keep first one)
  const filteredMatches = [];
  let lastEnd = 0;
  for (const match of matches) {
    if (match.start >= lastEnd) {
      filteredMatches.push(match);
      lastEnd = match.end;
    }
  }
  
  // Build segments
  for (const match of filteredMatches) {
    // Add text before this match
    if (match.start > lastIndex) {
      segments.push({
        type: 'text',
        content: text.slice(lastIndex, match.start)
      });
    }
    
    // Add the match
    segments.push({
      type: match.type,
      content: match.match,
      value: match.value
    });
    
    lastIndex = match.end;
  }
  
  // Add remaining text
  if (lastIndex < text.length) {
    segments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }
  
  return segments;
};

/**
 * RichText Component
 * Renders text with interactive hashtags and mentions
 */
export const RichText = ({ 
  text, 
  className = '',
  hashtagClassName = 'text-cyan-400 hover:text-cyan-300 hover:underline cursor-pointer',
  mentionClassName = 'text-blue-400 hover:text-blue-300 hover:underline cursor-pointer',
  urlClassName = 'text-cyan-400 hover:underline cursor-pointer',
  onHashtagClick,
  onMentionClick,
  onUrlClick,
  maxLength,
  showExpand = false
}) => {
  const navigate = useNavigate();
  const [expanded, setExpanded] = React.useState(false);
  
  // Truncate if needed
  let displayText = text || '';
  let isTruncated = false;
  
  if (maxLength && !expanded && displayText.length > maxLength) {
    displayText = displayText.slice(0, maxLength);
    isTruncated = true;
  }
  
  const segments = parseText(displayText);
  
  const handleHashtagClick = (e, tag) => {
    e.preventDefault();
    e.stopPropagation();
    
    if (onHashtagClick) {
      onHashtagClick(tag);
    } else {
      navigate(`/explore?hashtag=${encodeURIComponent(tag)}`);
    }
  };
  
  const handleMentionClick = async (e, username) => {
    e.preventDefault();
    e.stopPropagation();
    
    if (onMentionClick) {
      onMentionClick(username);
      return;
    }
    
    // Lookup username to get user ID, then navigate
    try {
      const res = await apiClient.get(`/api/username/lookup/${encodeURIComponent(username)}`);
      navigate(`/profile/${res.data.id}`);
    } catch {
      // Username not found — show toast instead of navigating to a dead route
      toast.error(`User @${username} not found`);
    }
  };
  
  const handleUrlClick = (e, url) => {
    e.preventDefault();
    e.stopPropagation();
    
    if (onUrlClick) {
      onUrlClick(url);
    } else {
      window.open(url, '_blank', 'noopener,noreferrer');
    }
  };
  
  return (
    <span className={className}>
      {segments.map((segment, index) => {
        switch (segment.type) {
          case 'hashtag':
            return (
              <span
                key={index}
                className={hashtagClassName}
                onClick={(e) => handleHashtagClick(e, segment.value)}
                data-testid={`hashtag-${segment.value}`}
                role="link"
                tabIndex={0}
                onKeyDown={(e) => e.key === 'Enter' && handleHashtagClick(e, segment.value)}
              >
                {segment.content}
              </span>
            );
          
          case 'mention':
            return (
              <span
                key={index}
                className={mentionClassName}
                onClick={(e) => handleMentionClick(e, segment.value)}
                data-testid={`mention-${segment.value}`}
                role="link"
                tabIndex={0}
                onKeyDown={(e) => e.key === 'Enter' && handleMentionClick(e, segment.value)}
              >
                {segment.content}
              </span>
            );
          
          case 'url':
            return (
              <span
                key={index}
                className={urlClassName}
                onClick={(e) => handleUrlClick(e, segment.content)}
                data-testid={`url-link`}
                role="link"
                tabIndex={0}
              >
                {segment.content.length > 30 
                  ? segment.content.slice(0, 30) + '...' 
                  : segment.content}
              </span>
            );
          
          default:
            return <span key={index}>{segment.content}</span>;
        }
      })}
      
      {isTruncated && (
        <>
          {'... '}
          {showExpand && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                setExpanded(true);
              }}
              className="text-muted-foreground hover:text-foreground text-sm"
            >
              more
            </button>
          )}
        </>
      )}
    </span>
  );
};

/**
 * Caption Component
 * Pre-styled for post captions with author name
 */
export const Caption = ({
  authorName,
  authorId,
  text,
  maxLength = 150,
  className = '',
  textPrimaryClass = 'text-foreground',
  textSecondaryClass = 'text-muted-foreground'
}) => {
  const navigate = useNavigate();
  
  return (
    <p className={`${textPrimaryClass} ${className}`}>
      <span 
        className="font-medium cursor-pointer hover:underline"
        onClick={(e) => {
          e.stopPropagation();
          if (authorId) navigate(`/profile/${authorId}`);
        }}
      >
        {authorName}
      </span>{' '}
      <RichText 
        text={text}
        className={textSecondaryClass}
        maxLength={maxLength}
        showExpand={true}
      />
    </p>
  );
};

/**
 * CommentText Component
 * For rendering comment text with interactive elements
 */
export const CommentText = ({
  text,
  className = 'text-sm',
  textClass = 'text-foreground'
}) => {
  return (
    <RichText 
      text={text}
      className={`${className} ${textClass}`}
    />
  );
};

export default RichText;

﻿import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { 
  Users, Plus, Star, Check, Trash2, 
  Loader2, ChevronDown, Save
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { toast } from 'sonner';
import logger from '../utils/logger';


/**
 * SavedCrewSelector - Quick-select saved crew presets
 * For Pro/Comp surfers to initiate beach sessions in under 5 seconds
 */

export const SavedCrewSelector = ({ 
  onSelect,
  selectedCrew,
  currentMembers = [],
  compact = false
}) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';
  
  const [savedCrews, setSavedCrews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showDropdown, setShowDropdown] = useState(false);
  const [showSaveDialog, setShowSaveDialog] = useState(false);
  const [savingCrew, setSavingCrew] = useState(false);
  const [newCrewName, setNewCrewName] = useState('');
  const [setAsDefault, setSetAsDefault] = useState(false);

  useEffect(() => {
    if (user?.id) {
      fetchSavedCrews();
    }
  }, [user?.id]);

  const fetchSavedCrews = async () => {
    try {
      const response = await apiClient.get(`/crews/saved`);
      setSavedCrews(response.data.crews || []);
    } catch (error) {
      logger.error('Failed to fetch saved crews:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectCrew = async (crew) => {
    // Mark as used
    try {
      await apiClient.post(`/crews/saved/${crew.id}/use`);
    } catch (error) {
      logger.error('Failed to mark crew as used:', error);
    }
    
    // Convert to member format expected by booking flow
    const members = (crew.members || []).map(m => ({
      type: m.user_id ? 'username' : 'email',
      value: m.username || m.email || m.name,
      user_id: m.user_id,
      name: m.name,
      avatar_url: m.avatar_url
    }));
    
    onSelect?.(members, crew);
    setShowDropdown(false);
    toast.success(`Loaded "${crew.name}"!`);
  };

  const handleSaveCurrentCrew = async () => {
    if (!newCrewName.trim()) {
      toast.error('Please enter a crew name');
      return;
    }
    
    if (currentMembers.length === 0) {
      toast.error('Add crew members first');
      return;
    }
    
    setSavingCrew(true);
    try {
      const membersData = currentMembers.map(m => ({
        user_id: m.user_id || null,
        name: m.name || m.value,
        email: m.type === 'email' ? m.value : null,
        username: m.type === 'username' ? m.value : null,
        avatar_url: m.avatar_url || null
      }));
      
      await apiClient.post(`/crews/saved`, {
        name: newCrewName,
        members: membersData,
        is_default: setAsDefault
      });
      
      toast.success(`Saved "${newCrewName}" as a crew preset!`);
      setShowSaveDialog(false);
      setNewCrewName('');
      setSetAsDefault(false);
      fetchSavedCrews();
    } catch (error) {
      logger.error('Failed to save crew:', error);
      toast.error('Failed to save crew');
    } finally {
      setSavingCrew(false);
    }
  };

  const _handleSetDefault = async (crewId) => {
    try {
      await apiClient.post(`/crews/saved/${crewId}/set-default`);
      toast.success('Default crew updated!');
      fetchSavedCrews();
    } catch (error) {
      toast.error('Failed to set default');
    }
  };

  const handleDeleteCrew = async (crewId, e) => {
    e.stopPropagation();
    if (!window.confirm('Delete this saved crew?')) return;
    
    try {
      await apiClient.delete(`/crews/saved/${crewId}`);
      toast.success('Crew deleted');
      fetchSavedCrews();
    } catch (error) {
      toast.error('Failed to delete');
    }
  };

  // Compact mode for inline use
  if (compact) {
    return (
      <div className="relative" data-testid="saved-crew-selector-compact">
        <Button
          variant="outline"
          size="sm"
          onClick={() => setShowDropdown(!showDropdown)}
          className={`${isLight ? 'border-gray-300' : 'border-zinc-600'} gap-2`}
        >
          <Users className="w-4 h-4" />
          Saved Crews
          <ChevronDown className={`w-3 h-3 transition-transform ${showDropdown ? 'rotate-180' : ''}`} />
        </Button>
        
        {showDropdown && (
          <div className={`absolute top-full left-0 mt-1 w-64 rounded-lg shadow-xl z-50 ${
            isLight ? 'bg-white border border-gray-200' : 'bg-zinc-900 border border-zinc-700'
          }`}>
            {loading ? (
              <div className="p-4 flex justify-center">
                <Loader2 className="w-5 h-5 animate-spin text-cyan-400" />
              </div>
            ) : savedCrews.length === 0 ? (
              <div className="p-4 text-center">
                <p className={`text-sm ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
                  No saved crews yet
                </p>
                {currentMembers.length > 0 && (
                  <Button
                    size="sm"
                    onClick={() => { setShowDropdown(false); setShowSaveDialog(true); }}
                    className="mt-2 bg-cyan-500 hover:bg-cyan-400 text-black"
                  >
                    <Save className="w-3 h-3 mr-1" />
                    Save Current
                  </Button>
                )}
              </div>
            ) : (
              <div className="max-h-64 overflow-y-auto">
                {savedCrews.map((crew) => (
                  <button
                    key={crew.id}
                    onClick={() => handleSelectCrew(crew)}
                    className={`w-full p-3 flex items-center justify-between hover:${isLight ? 'bg-gray-50' : 'bg-zinc-800'} transition-colors ${
                      selectedCrew?.id === crew.id ? (isLight ? 'bg-cyan-50' : 'bg-cyan-500/10') : ''
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      {crew.is_default && <Star className="w-4 h-4 text-yellow-400 fill-yellow-400" />}
                      <div className="text-left">
                        <p className={`text-sm font-medium ${isLight ? 'text-gray-900' : 'text-white'}`}>
                          {crew.name}
                        </p>
                        <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>
                          {crew.member_count} member{crew.member_count !== 1 ? 's' : ''}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-1">
                      {selectedCrew?.id === crew.id && (
                        <Check className="w-4 h-4 text-cyan-400" />
                      )}
                      <button
                        onClick={(e) => handleDeleteCrew(crew.id, e)}
                        className="p-1 hover:bg-red-500/20 rounded"
                      >
                        <Trash2 className="w-3 h-3 text-gray-400 hover:text-red-400" />
                      </button>
                    </div>
                  </button>
                ))}
                
                {currentMembers.length > 0 && (
                  <button
                    onClick={() => { setShowDropdown(false); setShowSaveDialog(true); }}
                    className={`w-full p-3 flex items-center gap-2 ${isLight ? 'border-t border-gray-100 text-cyan-600' : 'border-t border-zinc-700 text-cyan-400'} hover:${isLight ? 'bg-gray-50' : 'bg-zinc-800'}`}
                  >
                    <Plus className="w-4 h-4" />
                    <span className="text-sm">Save Current Crew</span>
                  </button>
                )}
              </div>
            )}
          </div>
        )}
        
        {/* Save Dialog */}
        <Dialog open={showSaveDialog} onOpenChange={setShowSaveDialog}>
          <DialogContent className={isLight ? 'bg-white' : 'bg-zinc-900 border-zinc-800'}>
            <DialogHeader>
              <DialogTitle className={isLight ? 'text-gray-900' : 'text-white'}>
                Save Crew Preset
              </DialogTitle>
            </DialogHeader>
            
            <div className="space-y-4 py-4">
              <div>
                <label className={`text-sm ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>
                  Crew Name
                </label>
                <Input
                  value={newCrewName}
                  onChange={(e) => setNewCrewName(e.target.value)}
                  placeholder="e.g., Dawn Patrol Crew"
                  className={`mt-1 ${isLight ? 'bg-white' : 'bg-zinc-800 border-zinc-700'}`}
                />
              </div>
              
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  id="setDefault"
                  checked={setAsDefault}
                  onChange={(e) => setSetAsDefault(e.target.checked)}
                  className="rounded"
                />
                <label htmlFor="setDefault" className={`text-sm ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>
                  Set as default for On-Demand sessions
                </label>
              </div>
              
              <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-50' : 'bg-zinc-800'}`}>
                <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'} mb-2`}>
                  Members ({currentMembers.length})
                </p>
                <div className="flex flex-wrap gap-1">
                  {currentMembers.map((m, i) => (
                    <Badge key={i} className="bg-cyan-500/20 text-cyan-400">
                      {m.name || m.value}
                    </Badge>
                  ))}
                </div>
              </div>
            </div>
            
            <DialogFooter>
              <Button variant="outline" onClick={() => setShowSaveDialog(false)}>
                Cancel
              </Button>
              <Button 
                onClick={handleSaveCurrentCrew}
                disabled={savingCrew}
                className="bg-cyan-500 hover:bg-cyan-400 text-black"
              >
                {savingCrew ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                Save Crew
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    );
  }

  // Full mode for crew hub
  return (
    <div className={`p-4 rounded-xl ${isLight ? 'bg-gray-50' : 'bg-zinc-800/50'}`} data-testid="saved-crew-selector">
      <div className="flex items-center justify-between mb-3">
        <h4 className={`text-sm font-medium flex items-center gap-2 ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>
          <Users className="w-4 h-4" />
          Saved Crews
