              </div>
            </div>
          )}

          {/* ── Saved Crews ── */}
          <SavedCrewSelector
            onSelect={(members) => {
              onCrewChange(members.map(m => ({
                user_id: m.user_id,
                name: m.name || m.value,
                username: m.value,
                avatar_url: m.avatar_url,
                payment_status: 'Pending',
                share_amount: 0,
                captain_cover_percent: 0
