/**
 * Main Scheduled Booking Drawer Component
 */
export const ScheduledBookingDrawer = ({
  isOpen,
  onClose,
  photographer,
  _onSuccess
}) => {
  const { user, updateUser } = useAuth();
  const { theme } = useTheme();
  
  // Step management: 'time' -> 'location' -> 'crew' -> 'payment' -> 'selfie' -> 'confirm' -> 'success'
  const [step, setStep] = useState('time');
  const [selfieUrl, setSelfieUrl] = useState(null);
  const [loading, setLoading] = useState(false);
  
  // Time slot state
  const [selectedDate, setSelectedDate] = useState(null);
  const [selectedTime, setSelectedTime] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [selectedDuration, setSelectedDuration] = useState(60);
  
  // Location state
  const [impactZone, setImpactZone] = useState(null);
  const [locationValid, setLocationValid] = useState(true);
  const [travelSurcharge, setTravelSurcharge] = useState(0);
  
  // Crew split state
  const [crewSplitEnabled, setCrewSplitEnabled] = useState(false);
  const [crewMembers, setCrewMembers] = useState([]);
  
  // Payment state
  const [appliedCredits, setAppliedCredits] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState('card'); // Default to 'card' to ensure Stripe flow
  
  // Booking result
  const [bookingResult, setBookingResult] = useState(null);
  
  const isLight = theme === 'light';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  const bgCard = isLight ? 'bg-white' : 'bg-zinc-900';
  
  // Calculate pricing - MUST match backend calculation
  // For scheduled bookings: booking_hourly_rate || hourly_rate || session_price || 75
  const baseRate = photographer?.booking_hourly_rate || photographer?.hourly_rate || photographer?.session_price || 75;
  const durationMultiplier = DURATION_PRICES[selectedDuration] || 1;
  const basePrice = baseRate * durationMultiplier;
  
  // Group discounts
  const groupDiscount2 = photographer?.group_discount_2_plus || 0;
  const groupDiscount3 = photographer?.group_discount_3_plus || 0;
  const groupDiscount5 = photographer?.group_discount_5_plus || 0;
  
  // Calculate participants based on crew
  const maxParticipants = crewSplitEnabled ? crewMembers.length + 1 : 1;
  let groupDiscountPercent = 0;
  if (maxParticipants >= 5 && groupDiscount5 > 0) groupDiscountPercent = groupDiscount5;
  else if (maxParticipants >= 3 && groupDiscount3 > 0) groupDiscountPercent = groupDiscount3;
  else if (maxParticipants >= 2 && groupDiscount2 > 0) groupDiscountPercent = groupDiscount2;
  
  const discountAmount = (basePrice * groupDiscountPercent) / 100;
  // Include travel surcharge in total price
  const totalPrice = basePrice - discountAmount + travelSurcharge;
  const pricePerPerson = totalPrice / maxParticipants;
  // Captain covers their own equal share + anything they chose to cover for crew
  const captainCoverageExtra = crewMembers.reduce(
    (sum, m) => sum + (pricePerPerson * ((m.captain_cover_percent || 0) / 100)), 0
  );
  const captainShare = pricePerPerson + captainCoverageExtra;
  const userCredits = user?.credit_balance || 0;
  
  // Check if group discounts are available (for display)
  const _hasGroupDiscounts = groupDiscount2 > 0 || groupDiscount3 > 0 || groupDiscount5 > 0;
  
  // Reset state when drawer opens
  useEffect(() => {
    if (isOpen) {
      setStep('time');
      setSelectedDate(null);
      setSelectedTime(null);
      setSelectedCategory(null);
      setSelectedDuration(60);
      setImpactZone(null);
      setLocationValid(true);
      setTravelSurcharge(0);
      setCrewSplitEnabled(false);
      setCrewMembers([]);
      setAppliedCredits(0);
      setBookingResult(null);
      setSelfieUrl(null);
    }
  }, [isOpen]);
  
  // Auto-apply credits only if payment method is 'credits'
  useEffect(() => {
    if (paymentMethod === 'credits') {
      const amountToPay = crewSplitEnabled ? captainShare : totalPrice;
      if (userCredits > 0 && amountToPay > 0) {
        setAppliedCredits(Math.min(userCredits, amountToPay));
      }
    } else if (paymentMethod === 'card') {
      // For card payment, reset applied credits to 0 (user can manually add via slider)
      setAppliedCredits(0);
    }
  }, [userCredits, totalPrice, captainShare, crewSplitEnabled, paymentMethod]);
  
  const canProceedFromTime = selectedDate && selectedTime && selectedDuration && selectedCategory;
  const canProceedFromLocation = impactZone && impactZone.description && locationValid;
  const canProceedFromCrew = !crewSplitEnabled || crewMembers.length >= 1; // Need at least 1 crew member if split enabled
  
  // Handler for range validation from ImpactZonePicker
  const handleRangeValidation = (isValid, surcharge) => {
    setLocationValid(isValid);
    setTravelSurcharge(surcharge);
  };
  
  const handleBack = () => {
    if (step === 'location') setStep('time');
    else if (step === 'crew') setStep('location');
    else if (step === 'payment') setStep('crew');
    else if (step === 'selfie') setStep('payment');
    else if (step === 'confirm') setStep('selfie');
  };
  
  const handleNext = () => {
    if (step === 'time' && canProceedFromTime) setStep('location');
    else if (step === 'location' && canProceedFromLocation) setStep('crew');
    else if (step === 'crew' && canProceedFromCrew) setStep('payment');
    else if (step === 'payment') setStep('selfie');
    else if (step === 'selfie') setStep('confirm');
  };
  
  // Calculate payment window based on session time
  const calculatePaymentWindow = () => {
    if (!selectedDate || !selectedTime) return null;
    
    const sessionDateTime = new Date(selectedDate);
    const [hours, minutes] = selectedTime.split(':');
    sessionDateTime.setHours(parseInt(hours), parseInt(minutes), 0, 0);
    
    const now = new Date();
    const hoursUntilSession = (sessionDateTime - now) / (1000 * 60 * 60);
    
    // If session is within 72 hours, payment window is 24 hours before session
    // Otherwise, payment window is 72 hours from booking
    if (hoursUntilSession <= 72) {
      // Payment due 24 hours before session
      const paymentDeadline = new Date(sessionDateTime);
      paymentDeadline.setHours(paymentDeadline.getHours() - 24);
      return paymentDeadline;
    } else {
      // Payment due in 72 hours
      const paymentDeadline = new Date(now);
      paymentDeadline.setHours(paymentDeadline.getHours() + 72);
      return paymentDeadline;
    }
  };
  
  const handleSubmitBooking = async () => {
    setLoading(true);
    
    try {
      // Build the exact session datetime
      const sessionDateTime = new Date(selectedDate);
      const [hours, minutes] = selectedTime.split(':');
      sessionDateTime.setHours(parseInt(hours), parseInt(minutes), 0, 0);
      
      // Calculate captain's payment amount
      const captainPaymentAmount = crewSplitEnabled ? captainShare : totalPrice;
      const amountToCharge = Math.max(0, captainPaymentAmount - appliedCredits);
      
      // Calculate payment window for crew
      const paymentWindowExpires = calculatePaymentWindow();
      
      // Prepare crew member data for backend (use actual out-of-pocket per member)
      const crewMemberData = crewMembers.map(m => ({
        user_id: m.user_id,
        name: m.name,
        share_amount: parseFloat((pricePerPerson * (1 - (m.captain_cover_percent || 0) / 100)).toFixed(2))
      }));
      
      // If there's an amount to charge and user selected card payment
      if (amountToCharge > 0 && paymentMethod === 'card') {
        // Create booking with pending payment status and redirect to Stripe
        const response = await apiClient.post(`/bookings/create-with-stripe`, {
          photographer_id: photographer.id,
          location: impactZone.description,
          session_date: sessionDateTime.toISOString(),
          duration: selectedDuration,
          max_participants: maxParticipants,
          allow_splitting: crewSplitEnabled,
          split_mode: 'friends_only',
          crew_members: crewMemberData,
          payment_window_expires: paymentWindowExpires?.toISOString(),
          latitude: impactZone.latitude || null,
          longitude: impactZone.longitude || null,
          description: `${selectedCategory} session`,
          apply_credits: appliedCredits,
          impact_zone_type: impactZone.type,
          impact_zone_preset: impactZone.preset_id || null,
          origin_url: window.location.origin
        });
        
        // Update credits if partially applied
        if (appliedCredits > 0 && response.data.remaining_credits !== undefined) {
          updateUser({ credit_balance: response.data.remaining_credits });
        }
        
        // Redirect to Stripe checkout
        if (response.data.checkout_url) {
          window.location.href = response.data.checkout_url;
          return;
        }
      }
      
      // Full credit payment or credits cover everything
      const response = await apiClient.post(`/bookings/create`, {
        photographer_id: photographer.id,
        location: impactZone.description,
        session_date: sessionDateTime.toISOString(),
        duration: selectedDuration,
        max_participants: maxParticipants,
        allow_splitting: crewSplitEnabled,
        split_mode: 'friends_only',
        crew_members: crewMemberData,
        payment_window_expires: paymentWindowExpires?.toISOString(),
        latitude: impactZone.latitude || null,
        longitude: impactZone.longitude || null,
        description: `${selectedCategory} session`,
        // Credit application
        apply_credits: appliedCredits,
        // Impact zone details
        impact_zone_type: impactZone.type,
        impact_zone_preset: impactZone.preset_id || null
      });
      
      // Update user credits if applied
      if (appliedCredits > 0 && response.data.remaining_credits !== undefined) {
        updateUser({ credit_balance: response.data.remaining_credits });
      }
      
      // If crew split is enabled, send payment requests to crew members
      if (crewSplitEnabled && crewMembers.length > 0 && response.data.booking?.id) {
        try {
          await apiClient.post(`/bookings/${response.data.booking.id}/send-crew-requests`, {
            crew_members: crewMemberData,
            price_per_person: pricePerPerson,
            payment_deadline: paymentWindowExpires?.toISOString(),
            session_date: sessionDateTime.toISOString(),
            photographer_name: photographer.full_name
          });
        } catch (crewError) {
          logger.error('Failed to send crew payment requests:', crewError);
          // Don't fail the booking, just notify
          toast.warning('Booking created but crew notifications may be delayed');
        }
      }
      
      setBookingResult({
        ...response.data,
        session_date: sessionDateTime.toISOString(),
        location: impactZone.description,
        duration: selectedDuration,
        total_paid: crewSplitEnabled ? captainShare : totalPrice,
        credits_applied: appliedCredits,
        crew_split: crewSplitEnabled,
        crew_count: maxParticipants,
        price_per_person: pricePerPerson
      });
      
      // Upload selfie for the booking if captured
      if (selfieUrl && response.data.booking?.id) {
        try {
          await apiClient.patch(`/bookings/${response.data.booking.id}/participant-selfie`, {
            participant_id: user.id,
            selfie_url: selfieUrl
          });
          logger.info('Selfie uploaded for booking');
        } catch (selfieError) {
          logger.error('Failed to upload selfie:', selfieError);
          // Don't fail the booking, selfie can be added later
        }
      }
      
      setStep('success');
      toast.success('Session booked successfully!');
      
    } catch (error) {
      logger.error('Booking error:', error);
      
      // Handle time slot conflict specifically
      if (error.response?.status === 409) {
        toast.error(error.response?.data?.detail || 'This time slot is already booked. Please select a different time.');
      } else {
        toast.error(error.response?.data?.detail || 'Failed to create booking');
      }
    } finally {
      setLoading(false);
    }
  };
  
  const handleCrossSellAction = (action) => {
    if (action === 'live_now') {
      onClose();
      // Navigate to live now tab - will be handled by parent
      window.location.href = '/bookings?tab=live_now';
    }
  };
  
  const isPro = photographer?.role === ROLES.APPROVED_PRO || photographer?.role === ROLES.PRO;
  
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent 
        className={`${bgCard} border-zinc-800 sm:max-w-lg`}
      >
        {/* Fixed Header */}
        <div className="shrink-0 px-4 sm:px-6 pt-4 pb-2 border-b border-zinc-800">
          <DialogHeader>
            <DialogTitle className={`text-base font-bold ${textPrimary} flex items-center gap-2`}>
              <Camera className="w-4 h-4 text-yellow-400" />
              Book Session
            </DialogTitle>
          </DialogHeader>
        </div>
        
        {/* Scrollable Content Area */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden px-4 sm:px-6 py-3"
          style={{ minHeight: 0 }}>
        
        
          {/* Photographer Info Header - Compact */}
          {step !== 'success' && (
            <div className={`p-2 rounded-lg ${isLight ? 'bg-gray-50' : 'bg-zinc-800'} mb-3`}>
              <div className="flex items-center gap-2">
                <div className={`w-8 h-8 rounded-full overflow-hidden flex-shrink-0 ${isPro ? 'ring-2 ring-yellow-400' : 'ring-1 ring-cyan-400/50'}`}>
                  {photographer?.avatar_url ? (
                    <img src={getFullUrl(photographer.avatar_url)} alt={photographer.full_name} className="w-full h-full object-cover" />
                  ) : (
                    <div className={`w-full h-full flex items-center justify-center ${isLight ? 'bg-gray-200' : 'bg-zinc-700'}`}>
                      <Camera className="w-3 h-3 text-gray-400" />
                    </div>
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5">
                    <h3 className={`font-semibold text-xs ${textPrimary} truncate`}>{photographer?.full_name}</h3>
                    {isPro && (
                      <Badge className="bg-yellow-500/20 text-yellow-400 text-[10px] px-1 py-0">PRO</Badge>
                    )}
                  </div>
                  <p className={`text-[10px] ${textSecondary}`}>
                    From <span className="text-yellow-400 font-bold">${baseRate}</span>/session
                  </p>
                </div>
              </div>
            </div>
          )}
        
          {/* Step Progress - Ultra Compact */}
          {step !== 'success' && (
            <div className="flex items-center justify-center gap-0.5 mb-3">
              {['time', 'location', 'crew', 'payment', 'selfie', 'confirm'].map((s, idx) => (
                <React.Fragment key={s}>
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold flex-shrink-0 ${
                    step === s 
                      ? 'bg-yellow-500 text-black' 
                      : idx < ['time', 'location', 'crew', 'payment', 'selfie', 'confirm'].indexOf(step)
                        ? 'bg-green-500 text-white'
                        : 'bg-zinc-700 text-gray-400'
                  }`}>
                    {idx < ['time', 'location', 'crew', 'payment', 'selfie', 'confirm'].indexOf(step) ? (
                      <Check className="w-2.5 h-2.5" />
                    ) : (
                      idx + 1
                    )}
                  </div>
                  {idx < 5 && (
                    <div className={`w-2 h-0.5 flex-shrink-0 ${
                      idx < ['time', 'location', 'crew', 'payment', 'selfie', 'confirm'].indexOf(step) 
                        ? 'bg-green-500' 
                        : 'bg-zinc-700'
                    }`} />
                  )}
                </React.Fragment>
              ))}
            </div>
          )}
        
          {/* Step 1: Time Selection */}
          {step === 'time' && (
            <div className="space-y-3 pb-2">
              <ExactTimeSlotPicker
                selectedDate={selectedDate}
                selectedTime={selectedTime}
                selectedCategory={selectedCategory}
                selectedDuration={selectedDuration}
                onDateChange={setSelectedDate}
                onTimeChange={setSelectedTime}
                onCategoryChange={setSelectedCategory}
                onDurationChange={setSelectedDuration}
              />
              
              {/* Cross-sell - Live Now suggestion - Hidden on mobile to save space */}
              <div className="hidden sm:block">
                <CrossSellSuggestion 
                  type="live_now" 
                  photographerName={photographer?.full_name}
                  onAction={handleCrossSellAction}
                  isLight={isLight}
                />
              </div>
            </div>
          )}
        
          {/* Step 2: Impact Zone Location */}
          {step === 'location' && (
            <div className="space-y-3 pb-2">
              <ImpactZonePicker
                location={impactZone}
                onLocationChange={setImpactZone}
                onRangeValidation={handleRangeValidation}
                photographer={photographer}
                photographerHomeBreak={photographer?.home_break}
                isLight={isLight}
              />
            </div>
          )}
        
          {/* Step 3: Crew Split */}
          {step === 'crew' && (
            <div className="space-y-4 pb-4">
              <div className="text-center mb-2">
                <h3 className={`font-semibold ${textPrimary}`}>Split the Cost?</h3>
                <p className={`text-sm ${textSecondary}`}>Share this session with friends</p>
              </div>
              
              <CrewSplitSection
                user={user}
                enabled={crewSplitEnabled}
                onToggle={setCrewSplitEnabled}
                crewMembers={crewMembers}
                onCrewChange={setCrewMembers}
                totalPrice={totalPrice}
                isLight={isLight}
              />
              
              {/* Group Discount Applied Notice */}
              {crewSplitEnabled && groupDiscountPercent > 0 && (
                <div className={`p-3 rounded-lg bg-gradient-to-r ${isLight ? 'from-green-50 to-emerald-50' : 'from-green-500/10 to-emerald-500/10'} border border-green-500/30`}>
                  <div className="flex items-center gap-2">
                    <Sparkles className="w-4 h-4 text-green-400" />
                    <span className={`text-sm font-medium text-green-400`}>
                      {groupDiscountPercent}% Group Discount Applied!
                    </span>
                  </div>
                  <p className={`text-xs ${textSecondary} mt-1`}>
                    You're saving ${discountAmount.toFixed(2)} with {maxParticipants} surfers
                  </p>
                </div>
              )}
            </div>
          )}
        
          {/* Step 4: Payment */}
          {step === 'payment' && (
            <div className="space-y-4 pb-4">
              {/* Session Summary */}
              <div className={`p-3 rounded-xl ${isLight ? 'bg-gray-100' : 'bg-zinc-800'}`}>
                <h4 className={`font-medium text-sm ${textPrimary} mb-2`}>Session Summary</h4>
                <div className="space-y-1 text-xs">
                  <div className="flex justify-between">
                    <span className={textSecondary}>Date & Time</span>
                    <span className={textPrimary}>
                      {selectedDate?.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })} at {selectedTime}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className={textSecondary}>Duration</span>
                    <span className={textPrimary}>{selectedDuration} min</span>
                  </div>
                  <div className="flex justify-between">
                    <span className={textSecondary}>Location</span>
                    <span className={`${textPrimary} truncate ml-2 max-w-[150px]`}>{impactZone?.description}</span>
                  </div>
                  {crewSplitEnabled && (
                    <>
                      <div className="flex justify-between">
                        <span className={textSecondary}>Crew Size</span>
                        <span className={textPrimary}>{maxParticipants} surfers</span>
                      </div>
                      {groupDiscountPercent > 0 && (
                        <div className="flex justify-between text-green-400">
                          <span>Group Discount ({groupDiscountPercent}%)</span>
                          <span>-${discountAmount.toFixed(2)}</span>
                        </div>
                      )}
                    </>
                  )}
                  <div className={`flex justify-between pt-2 border-t ${isLight ? 'border-gray-200' : 'border-zinc-700'}`}>
                    <span className={`font-bold ${textPrimary}`}>Total</span>
                    <span className="font-bold text-yellow-400">${totalPrice.toFixed(2)}</span>
                  </div>
                  {crewSplitEnabled && (
                    <div className="flex justify-between">
                      <span className={`font-bold ${textPrimary} flex items-center gap-1`}>
                        <Crown className="w-3 h-3 text-yellow-400" />
                        Your Share
                      </span>
                      <span className="font-bold text-cyan-400">${captainShare.toFixed(2)}</span>
                    </div>
                  )}
                </div>
              </div>
              
              {/* Crew Payment Info */}
              {crewSplitEnabled && crewMembers.length > 0 && (
                <div className={`p-2 rounded-lg ${isLight ? 'bg-cyan-50' : 'bg-cyan-500/10'} border ${isLight ? 'border-cyan-200' : 'border-cyan-500/30'}`}>
                  <div className="flex items-center gap-2 mb-1">
                    <Users className="w-3 h-3 text-cyan-400" />
                    <span className={`text-xs font-medium ${textPrimary}`}>Crew Payments</span>
                  </div>
                  <p className={`text-xs ${textSecondary}`}>
                    ${pricePerPerson.toFixed(2)} each sent to crew via Messages.
                  </p>
                </div>
              )}
              
              {/* Payment Method Selection */}
              {(() => {
                const amountToPay = crewSplitEnabled ? captainShare : totalPrice;
                const canPayFullWithCredits = userCredits >= amountToPay;
                
                return (
                  <div className="space-y-2">
                    <Label className={`font-medium text-sm ${textPrimary}`}>Payment Method</Label>
                    
                    {/* Option 1: Pay with Credits */}
                    {userCredits > 0 && (
                      <button
                        onClick={() => {
                          setPaymentMethod('credits');
                          setAppliedCredits(Math.min(userCredits, amountToPay));
                        }}
                        className={`w-full flex items-center gap-3 p-3 rounded-lg border-2 transition-all ${
                          paymentMethod === 'credits'
                            ? 'border-yellow-400 bg-yellow-500/10'
                            : isLight ? 'border-gray-200 bg-white' : 'border-zinc-700 bg-zinc-800/50'
                        }`}
                        data-testid="pay-with-credits-btn"
                      >
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                          paymentMethod === 'credits' ? 'bg-yellow-400 text-black' : 'bg-zinc-700 text-gray-400'
                        }`}>
                          <Wallet className="w-4 h-4" />
                        </div>
                        <div className="flex-1 text-left">
                          <div className={`font-medium text-sm ${textPrimary}`}>Account Credits</div>
                          <div className={`text-xs ${textSecondary}`}>
                            ${userCredits.toFixed(2)} available
                            {canPayFullWithCredits && <span className="text-green-400 ml-1">(covers all!)</span>}
                          </div>
                        </div>
                        {paymentMethod === 'credits' && (
                          <Check className="w-4 h-4 text-yellow-400" />
                        )}
                      </button>
                    )}
                    
                    {/* Option 2: Pay with Card */}
                    <button
                      onClick={() => {
                        setPaymentMethod('card');
                        setAppliedCredits(0);
                      }}
                      className={`w-full flex items-center gap-3 p-3 rounded-lg border-2 transition-all ${
                        paymentMethod === 'card'
                          ? 'border-cyan-400 bg-cyan-500/10'
                          : isLight ? 'border-gray-200 bg-white' : 'border-zinc-700 bg-zinc-800/50'
                      }`}
                      data-testid="pay-with-card-btn"
                    >
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                        paymentMethod === 'card' ? 'bg-cyan-400 text-white' : 'bg-zinc-700 text-gray-400'
                      }`}>
                        <CreditCard className="w-4 h-4" />
                      </div>
                      <div className="flex-1 text-left">
                        <div className={`font-medium text-sm ${textPrimary}`}>Pay with Card</div>
                        <div className={`text-xs ${textSecondary}`}>Secure via Stripe</div>
                      </div>
                      {paymentMethod === 'card' && (
                        <Check className="w-4 h-4 text-cyan-400" />
                      )}
                    </button>
                    
                    {/* Credit Slider for Card */}
                    {paymentMethod === 'card' && userCredits > 0 && (
                      <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-50' : 'bg-zinc-800/50'}`}>
                        <div className="flex items-center justify-between mb-2">
                          <span className={`text-xs ${textSecondary}`}>Also apply credits?</span>
                          <span className="text-xs text-yellow-400">${appliedCredits.toFixed(2)}</span>
                        </div>
                        <Slider
                          value={[appliedCredits]}
                          onValueChange={([value]) => setAppliedCredits(value)}
                          max={Math.min(userCredits, amountToPay)}
                          min={0}
                          step={0.5}
                          className="w-full"
                        />
                      </div>
                    )}
                    
                    {/* Payment Summary */}
                    <div className={`p-3 rounded-lg ${isLight ? 'bg-green-50 border-green-200' : 'bg-green-500/10 border-green-500/30'} border`}>
                      <div className="space-y-1 text-sm">
                        <div className="flex justify-between">
                          <span className={textSecondary}>Session Total</span>
                          <span className={textPrimary}>${amountToPay.toFixed(2)}</span>
                        </div>
                        {appliedCredits > 0 && (
                          <div className="flex justify-between text-yellow-500">
                            <span>Credits Applied</span>
                            <span>-${appliedCredits.toFixed(2)}</span>
                          </div>
                        )}
                        <div className={`flex justify-between pt-1 border-t ${isLight ? 'border-green-200' : 'border-green-500/30'} font-bold`}>
                          <span className={textPrimary}>
                            {paymentMethod === 'credits' && appliedCredits >= amountToPay 
                              ? 'Pay with Credits' 
                              : 'Card Payment via Stripe'}
                          </span>
                          <span className="text-green-400">
                            ${Math.max(0, amountToPay - appliedCredits).toFixed(2)}
                          </span>
                        </div>
                      </div>
                    </div>
                    
                    {/* Compact Protection Notice */}
                    <p className={`text-xs ${textSecondary}`}>
                      <Check className="w-3 h-3 inline mr-1 text-green-400" />
                      Payment held until session complete. Cancel 48hrs+ for 90% refund.
                    </p>
                  </div>
                );
              })()}
            </div>
          )}
        
          {/* Step 5: Selfie for Identification */}
          {step === 'selfie' && (
            <div className="space-y-4 pb-4">
              <div className={`p-4 rounded-xl ${isLight ? 'bg-cyan-50' : 'bg-cyan-500/10'} border border-cyan-500/30`}>
                <h4 className={`font-bold text-sm ${textPrimary} mb-2 flex items-center gap-2`}>
                  <Camera className="w-4 h-4 text-cyan-400" />
                  Help the Photographer Find You!
                </h4>
                <p className={`text-xs ${textSecondary}`}>
                  Take a quick selfie with your board. This helps the photographer identify you in their photos so you don't miss any shots!
                </p>
              </div>
              
              {selfieUrl ? (
                <div className="space-y-3">
                  <div className="relative aspect-[4/3] rounded-xl overflow-hidden">
                    <img src={selfieUrl} alt="Your selfie" className="w-full h-full object-cover" />
                    <Badge className="absolute top-2 right-2 bg-green-500 text-white">
                      <Check className="w-3 h-3 mr-1" /> Saved
                    </Badge>
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      onClick={() => setSelfieUrl(null)}
                      className="flex-1"
                    >
                      <Camera className="w-4 h-4 mr-2" />
                      Retake
                    </Button>
                    <Button
                      onClick={() => setStep('confirm')}
                      className="flex-1 bg-gradient-to-r from-yellow-500 to-orange-500 text-black font-bold"
                    >
                      Continue
                      <ChevronRight className="w-4 h-4 ml-1" />
                    </Button>
                  </div>
                </div>
              ) : (
                <SelfieCapture
                  onCapture={(url) => {
                    setSelfieUrl(url);
                    toast.success('Selfie captured! The photographer will use this to find you.');
                  }}
                  onSkip={() => {
                    setStep('confirm');
                  }}
                  title="Selfie with Your Board"
                  subtitle="Hold your board so the photographer can spot you in the lineup"
                  skipAllowed={true}
                  theme={isLight ? 'light' : 'dark'}
                />
              )}
            </div>
          )}
        
          {/* Step 6: Confirmation */}
          {step === 'confirm' && (
            <div className="space-y-4 pb-4">
              <div className={`p-3 rounded-xl ${isLight ? 'bg-yellow-50' : 'bg-yellow-500/10'} border border-yellow-500/30`}>
                <h4 className={`font-bold text-sm ${textPrimary} mb-2 flex items-center gap-2`}>
                  <CheckCircle2 className="w-4 h-4 text-yellow-400" />
                  Confirm Your Booking
                </h4>
                
                <div className="space-y-2 text-xs">
                  <div className="flex items-center gap-2">
                    <Camera className="w-3 h-3 text-gray-500" />
                    <span className={textPrimary}>{photographer?.full_name}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Clock className="w-3 h-3 text-gray-500" />
                    <span className={textPrimary}>
                      {selectedDate?.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })} at {selectedTime}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <MapPin className="w-3 h-3 text-gray-500" />
                    <span className={`${textPrimary} truncate`}>{impactZone?.description}</span>
                  </div>
                  
                  <div className={`pt-2 border-t ${isLight ? 'border-yellow-200' : 'border-yellow-500/30'}`}>
                    <div className="flex justify-between">
                      <span className={textSecondary}>Total</span>
                      <span className={textPrimary}>${totalPrice.toFixed(2)}</span>
                    </div>
                    {appliedCredits > 0 && (
                      <div className="flex justify-between text-yellow-500">
                        <span>Credits</span>
                        <span>-${appliedCredits.toFixed(2)}</span>
                      </div>
                    )}
                    <div className="flex justify-between font-bold text-sm mt-1">
                      <span className={textPrimary}>Pay Now</span>
                      <span className="text-green-400">${(totalPrice - appliedCredits).toFixed(2)}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
          
          {/* Step 6: Success */}
          {step === 'success' && (
            <div className="pb-4">
              <BookingConfirmation
                booking={bookingResult}
                photographer={photographer}
                onClose={onClose}
                onViewBookings={() => {
                  onClose();
                  // Navigate to scheduled bookings tab with highlight on the new booking
                  const newBookingId = bookingResult?.booking?.id || bookingResult?.id || '';
                  window.location.href = `/bookings?tab=scheduled${newBookingId ? `&highlight=${newBookingId}` : ''}`;
                }}
                onAddAnotherSpot={() => {
                  setStep('time');
                  setSelectedDate(null);
                  setSelectedTime(null);
                  setSelectedCategory(null);
                  setImpactZone(null);
                  setBookingResult(null);
                  toast.info('Select time and location for your next spot!');
                }}
                isLight={isLight}
              />
            </div>
          )}
        </div>
        
        {/* Sticky Footer Navigation */}
        {step !== 'success' && (
          <div className={`flex-shrink-0 px-4 py-2 border-t ${isLight ? 'border-gray-200 bg-white' : 'border-zinc-800 bg-zinc-900'}`}>
            {step === 'time' && (
              <Button
                onClick={handleNext}
                disabled={!canProceedFromTime}
                className="w-full bg-yellow-500 hover:bg-yellow-600 text-black font-bold h-10"
                data-testid="continue-to-location-btn"
              >
                Continue
                <ChevronRight className="w-4 h-4 ml-1" />
              </Button>
            )}
            
            {step === 'location' && (
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={handleBack}
                  className={`flex-1 h-10 ${isLight ? 'border-gray-300' : 'border-zinc-700'}`}
                >
                  <ChevronLeft className="w-4 h-4 mr-1" />
                  Back
                </Button>
                <Button
                  onClick={handleNext}
                  disabled={!canProceedFromLocation}
                  className="flex-1 bg-yellow-500 hover:bg-yellow-600 text-black font-bold h-10"
                  data-testid="continue-to-crew-btn"
                >
                  Continue
                  <ChevronRight className="w-4 h-4 ml-1" />
                </Button>
              </div>
            )}
            
            {step === 'crew' && (
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={handleBack}
                  className={`flex-1 h-10 ${isLight ? 'border-gray-300' : 'border-zinc-700'}`}
                >
                  <ChevronLeft className="w-4 h-4 mr-1" />
                  Back
                </Button>
                <Button
                  onClick={handleNext}
                  disabled={!canProceedFromCrew}
                  className="flex-1 bg-yellow-500 hover:bg-yellow-600 text-black font-bold h-10"
                  data-testid="continue-to-payment-btn"
                >
                  Payment
                  <ChevronRight className="w-4 h-4 ml-1" />
                </Button>
              </div>
            )}
            
            {step === 'payment' && (
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={handleBack}
                  className={`flex-1 h-10 ${isLight ? 'border-gray-300' : 'border-zinc-700'}`}
                >
                  <ChevronLeft className="w-4 h-4 mr-1" />
                  Back
                </Button>
                <Button
                  onClick={handleNext}
                  className="flex-1 bg-yellow-500 hover:bg-yellow-600 text-black font-bold h-10"
                  data-testid="review-booking-btn"
                >
                  Review
                  <ChevronRight className="w-4 h-4 ml-1" />
                </Button>
              </div>
            )}
            
            {step === 'confirm' && (
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={handleBack}
                  className="flex-1 h-10 border-zinc-700"
                >
                  <ChevronLeft className="w-4 h-4 mr-1" />
                  Back
                </Button>
                <Button
                  onClick={handleSubmitBooking}
                  disabled={loading}
                  className="flex-1 bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black font-bold h-10"
                  data-testid="confirm-booking-btn"
                >
                  {loading ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <>
                      <Zap className="w-4 h-4 mr-1" />
                      Confirm & Pay
                    </>
                  )}
                </Button>
              </div>
            )}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};

export default ScheduledBookingDrawer;

﻿/**
 * SessionActionDrawer - Command Center for managing scheduled bookings
 * 
 * Features:
 * - Invite Crew: Launch CrewHub to add friends
 * - Split Payment: Trigger crew-split logic, send payment requests
 * - Modify: Change time slot (subject to availability)
 * - Cancel: Execute cancellation policy logic
 */
import React, { useState } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useNavigate } from 'react-router-dom';
import { 
  Users, DollarSign, Clock, ChevronRight, 
  AlertTriangle, Calendar, MapPin, 
  Send, UserPlus, Settings, Ban, Loader2,
  MessageCircle, Share2, Check
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from './ui/dialog';
import { Textarea } from './ui/textarea';
import { toast } from 'sonner';
import logger from '../utils/logger';


export const SessionActionDrawer = ({
  isOpen,
  onClose,
  booking,
  user,
  theme = 'dark',
  onRefresh,
  onOpenCrewHub,
  onOpenModify,
  onOpenCrewView  // New prop for viewing crew lineup
}) => {
  const navigate = useNavigate();
  const isLight = theme === 'light';
  const [activeAction, setActiveAction] = useState(null); // 'cancel' | 'split' | null
  const [cancellationReason, setCancellationReason] = useState('');
  // Separate loading states for each action to prevent UI bleed
  const [cancelLoading, setCancelLoading] = useState(false);
  const [shareLoading, setShareLoading] = useState(false);
  const [splitLoading, setSplitLoading] = useState(false);
  const [alreadyShared, setAlreadyShared] = useState(false);
  
  const _isHost = booking?.creator_id === user?.id;
  const hoursUntilSession = booking ? 
    (new Date(booking.session_date) - new Date()) / (1000 * 60 * 60) : 0;
  
  // Cancellation policy calculation
  const getRefundInfo = () => {
    if (hoursUntilSession > 24) {
      return { percentage: 100, label: 'Full Refund', color: 'text-green-400' };
    } else if (hoursUntilSession > 0) {
      return { percentage: 50, label: '50% Refund', color: 'text-yellow-400' };
    } else {
      return { percentage: 0, label: 'Credit Only', color: 'text-red-400' };
    }
  };
  
  const refundInfo = getRefundInfo();
  const refundAmount = (booking?.paid_amount || 0) * (refundInfo.percentage / 100);

  // Cancel booking handler
  const handleCancel = async () => {
    if (!booking || !user?.id) return;
    
    setCancelLoading(true);
    try {
      await apiClient.post(`/bookings/${booking.id}/cancel`, {
        reason: cancellationReason || 'Cancelled by user'
      });
      
      toast.success(
        refundInfo.percentage > 0 
          ? `Booking cancelled. $${refundAmount.toFixed(2)} will be refunded.`
          : 'Booking cancelled. Credit added to your account.'
      );
      
      setActiveAction(null);
      onClose();
      onRefresh?.();
    } catch (error) {
      logger.error('Cancel error:', error);
      const errorMessage = error.response?.data?.detail || 'Failed to cancel booking';
      // Handle validation errors that come as array
      const displayMessage = typeof errorMessage === 'object' 
        ? (Array.isArray(errorMessage) ? errorMessage[0]?.msg : errorMessage.msg || 'Failed to cancel booking')
        : errorMessage;
      toast.error(displayMessage);
    } finally {
      setCancelLoading(false);
    }
  };

  // Split payment - send requests to crew via messages
  const handleSplitPayment = async () => {
    if (!booking) return;
    
    setSplitLoading(true);
    try {
      // Create payment split requests for all pending crew members
      await apiClient.post(`/bookings/${booking.id}/send-split-requests`);
      
      toast.success('Payment requests sent to crew members!');
      setActiveAction(null);
      onClose();
      
      // Navigate to messages to see the sent requests
      navigate('/messages');
    } catch (error) {
      logger.error('Split payment error:', error);
      toast.error(error.response?.data?.detail || 'Failed to send payment requests');
    } finally {
      setSplitLoading(false);
    }
  };

  // Share session to feed
  const handleShareToFeed = async () => {
    if (!booking || !user?.id) return;
    
    // Don't allow re-sharing if already shared
    if (alreadyShared) {
      toast.info('This session is already on your feed!');
      return;
    }
    
    setShareLoading(true);
    try {
      const response = await apiClient.post(`/bookings/${booking.id}/share-to-feed`);
      toast.success('Session posted to feed! Friends can join from there.', {
        description: response.data?.spots_left > 0 
          ? `${response.data.spots_left} spot${response.data.spots_left > 1 ? 's' : ''} available for crew` 
          : 'Crew is full!'
      });
      setAlreadyShared(true);
      onClose();
      onRefresh?.(); // Refresh to update any feed-related UI
    } catch (error) {
      logger.error('Share error:', error);
      const errorDetail = error.response?.data?.detail;
      
      // Handle "already shared" case gracefully
      if (errorDetail?.toLowerCase().includes('already posted') || 
          errorDetail?.toLowerCase().includes('already shared')) {
        setAlreadyShared(true);
        toast.info('This session is already on your feed!', {
          description: 'Your friends can see it and join from there.'
        });
      } else if (error.response?.status === 403) {
        toast.error('Only the booking creator can share to feed');
      } else if (error.response?.status === 404) {
        toast.error('Booking not found. It may have been cancelled.');
      } else {
        toast.error(errorDetail || 'Failed to share session. Please try again.');
      }
    } finally {
      setShareLoading(false);
    }
  };

  if (!booking) return null;

  const cardBgClass = isLight ? 'bg-white' : 'bg-zinc-900';
  const textPrimaryClass = isLight ? 'text-gray-900' : 'text-white';
  const textSecondaryClass = isLight ? 'text-gray-600' : 'text-gray-400';
  const actionCardClass = isLight 
    ? 'bg-gray-50 hover:bg-gray-100 border-gray-200' 
    : 'bg-zinc-800/50 hover:bg-zinc-800 border-zinc-700';

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className={`${cardBgClass} border-zinc-700 sm:max-w-[450px]`}>
        <DialogHeader className="shrink-0 border-b border-zinc-700 px-4 sm:px-6 pt-4 pb-3">
          <DialogTitle className={`text-lg font-bold ${textPrimaryClass} flex items-center gap-2`}>
            <Settings className="w-5 h-5 text-yellow-400" />
            Manage Session
          </DialogTitle>
          <DialogDescription className={textSecondaryClass}>
            {booking.location} · {new Date(booking.session_date).toLocaleDateString()}
          </DialogDescription>
        </DialogHeader>
        
        <div className="flex-1 overflow-y-auto px-4 sm:px-6 py-4">
        {/* Session Summary */}
        <div className={`p-3 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800/50'} mb-4`}>
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4 text-cyan-400" />
              <span className={`text-sm ${textPrimaryClass}`}>{booking.location}</span>
            </div>
            <Badge variant={booking.status === 'Confirmed' ? 'default' : 'warning'}>
              {booking.status}
            </Badge>
          </div>
          <div className="flex items-center gap-4 text-sm">
            <div className="flex items-center gap-1">
              <Calendar className="w-3 h-3 text-gray-400" />
              <span className={textSecondaryClass}>
                {new Date(booking.session_date).toLocaleString()}
              </span>
            </div>
            <div className="flex items-center gap-1">
              <Users className="w-3 h-3 text-gray-400" />
              <span className={textSecondaryClass}>
                {booking.current_participants}/{booking.max_participants}
              </span>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="space-y-2 flex-1 overflow-y-auto">
          {/* Invite Crew */}
          <button
            onClick={() => {
              onClose();
              onOpenCrewHub?.(booking);
            }}
            className={`w-full p-4 rounded-lg border ${actionCardClass} flex items-center justify-between transition-colors`}
            data-testid="action-invite-crew"
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-cyan-500/20 flex items-center justify-center">
                <UserPlus className="w-5 h-5 text-cyan-400" />
              </div>
              <div className="text-left">
                <p className={`font-medium ${textPrimaryClass}`}>Invite Crew</p>
                <p className={`text-xs ${textSecondaryClass}`}>Add friends to this session</p>
              </div>
            </div>
            <ChevronRight className={`w-5 h-5 ${textSecondaryClass}`} />
          </button>

          {/* The Crew - View/Manage Crew Lineup with surfboard visualization */}
          <button
            onClick={() => {
              onClose();
              onOpenCrewView?.(booking);
            }}
            className={`w-full p-4 rounded-lg border ${actionCardClass} flex items-center justify-between transition-colors`}
            data-testid="action-view-crew"
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-cyan-500/20 to-blue-500/20 flex items-center justify-center">
                <Users className="w-5 h-5 text-cyan-400" />
              </div>
              <div className="text-left">
                <p className={`font-medium ${textPrimaryClass}`}>The Crew</p>
                <p className={`text-xs ${textSecondaryClass}`}>View lineup & payment status</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Badge className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 text-[10px]">
                {booking.current_participants}/{booking.max_participants}
              </Badge>
              <ChevronRight className={`w-5 h-5 ${textSecondaryClass}`} />
            </div>
          </button>

          {/* Split Payment - Only show if there are crew members */}
          {booking.current_participants > 1 && (
            <button
              onClick={() => setActiveAction('split')}
              className={`w-full p-4 rounded-lg border ${actionCardClass} flex items-center justify-between transition-colors`}
              data-testid="action-split-payment"
            >
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-green-500/20 flex items-center justify-center">
                  <DollarSign className="w-5 h-5 text-green-400" />
                </div>
                <div className="text-left">
                  <p className={`font-medium ${textPrimaryClass}`}>Split Payment</p>
                  <p className={`text-xs ${textSecondaryClass}`}>Send payment requests to crew</p>
                </div>
              </div>
              <ChevronRight className={`w-5 h-5 ${textSecondaryClass}`} />
            </button>
          )}

          {/* Share to Feed */}
          <button
            onClick={handleShareToFeed}
            disabled={shareLoading || alreadyShared}
            className={`w-full p-4 rounded-lg border flex items-center justify-between transition-colors ${
              alreadyShared 
                ? 'border-green-500/50 bg-green-500/10 cursor-default' 
                : actionCardClass
            }`}
            data-testid="action-share-feed"
          >
            <div className="flex items-center gap-3">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                alreadyShared ? 'bg-green-500/20' : 'bg-purple-500/20'
              }`}>
                {alreadyShared ? (
                  <Check className="w-5 h-5 text-green-400" />
                ) : (
                  <Share2 className="w-5 h-5 text-purple-400" />
                )}
              </div>
              <div className="text-left">
                <p className={`font-medium ${alreadyShared ? 'text-green-400' : textPrimaryClass}`}>
                  {alreadyShared ? 'Posted to Feed' : 'Post to Feed'}
                </p>
                <p className={`text-xs ${textSecondaryClass}`}>
                  {alreadyShared ? 'Friends can see and join' : 'Friends can join from feed'}
                </p>
              </div>
            </div>
            {shareLoading ? (
              <Loader2 className="w-5 h-5 animate-spin text-gray-400" />
            ) : alreadyShared ? (
              <Badge className="bg-green-500/20 text-green-400 border-green-500/30 text-[10px]">Shared</Badge>
            ) : (
              <ChevronRight className={`w-5 h-5 ${textSecondaryClass}`} />
            )}
          </button>

          {/* Modify Session */}
          <button
            onClick={() => {
              onClose();
              onOpenModify?.(booking);
            }}
            className={`w-full p-4 rounded-lg border ${actionCardClass} flex items-center justify-between transition-colors`}
            data-testid="action-modify"
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-yellow-500/20 flex items-center justify-center">
                <Clock className="w-5 h-5 text-yellow-400" />
              </div>
              <div className="text-left">
                <p className={`font-medium ${textPrimaryClass}`}>Modify Time</p>
                <p className={`text-xs ${textSecondaryClass}`}>Change session time slot</p>
              </div>
            </div>
            <ChevronRight className={`w-5 h-5 ${textSecondaryClass}`} />
          </button>

          {/* Cancel Session */}
          <button
            onClick={() => setActiveAction('cancel')}
            className={`w-full p-4 rounded-lg border border-red-500/30 bg-red-500/5 hover:bg-red-500/10 flex items-center justify-between transition-colors`}
            data-testid="action-cancel"
          >
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-red-500/20 flex items-center justify-center">
                <Ban className="w-5 h-5 text-red-400" />
              </div>
              <div className="text-left">
                <p className="font-medium text-red-400">Cancel Session</p>
                <p className={`text-xs ${refundInfo.color}`}>
                  {refundInfo.label} ({refundInfo.percentage}%)
                </p>
              </div>
            </div>
            <ChevronRight className="w-5 h-5 text-red-400" />
          </button>
        </div>

        {/* Cancel Confirmation Dialog */}
        {activeAction === 'cancel' && (
          <div className={`p-4 rounded-lg border border-red-500/30 ${isLight ? 'bg-red-50' : 'bg-red-500/10'}`}>
            <div className="flex items-start gap-3 mb-4">
              <AlertTriangle className="w-5 h-5 text-red-400 mt-0.5" />
              <div>
                <h4 className="font-medium text-red-400">Cancel this session?</h4>
                <p className={`text-sm ${textSecondaryClass} mt-1`}>
                  Based on our cancellation policy:
                </p>
                <div className={`mt-2 p-2 rounded ${isLight ? 'bg-white' : 'bg-zinc-900'}`}>
                  <div className="flex items-center justify-between">
                    <span className={`text-sm ${textSecondaryClass}`}>Refund Amount</span>
                    <span className={`font-bold ${refundInfo.color}`}>
                      ${refundAmount.toFixed(2)} ({refundInfo.percentage}%)
                    </span>
                  </div>
                  {refundInfo.percentage < 100 && (
                    <p className="text-xs text-gray-500 mt-1">
                      {hoursUntilSession <= 0 
                        ? 'Session has passed - credit will be added to your account'
                        : `Less than 24 hours until session`}
                    </p>
                  )}
                </div>
              </div>
            </div>
            
            <Textarea
              value={cancellationReason}
              onChange={(e) => setCancellationReason(e.target.value)}
              placeholder="Reason for cancellation (optional)"
              className={`mb-4 ${isLight ? 'bg-white border-gray-300' : 'bg-zinc-900 border-zinc-700'}`}
              rows={2}
            />
            
            <div className="flex gap-2">
              <Button
                variant="outline"
                onClick={() => setActiveAction(null)}
                className="flex-1"
              >
                Keep Session
              </Button>
              <Button
                onClick={handleCancel}
                disabled={cancelLoading}
                className="flex-1 bg-red-500 hover:bg-red-600 text-white"
              >
                {cancelLoading ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  'Confirm Cancel'
                )}
              </Button>
            </div>
          </div>
        )}

        {/* Split Payment Confirmation */}
        {activeAction === 'split' && (
          <div className={`mt-4 p-4 rounded-lg border border-green-500/30 ${isLight ? 'bg-green-50' : 'bg-green-500/10'}`}>
            <div className="flex items-start gap-3 mb-4">
              <MessageCircle className="w-5 h-5 text-green-400 mt-0.5" />
              <div>
                <h4 className="font-medium text-green-400">Send Payment Requests?</h4>
                <p className={`text-sm ${textSecondaryClass} mt-1`}>
                  This will send payment requests to {booking.current_participants - 1} crew member(s) 
                  via Messages. They'll be able to pay their share directly.
                </p>
                <div className={`mt-2 p-2 rounded ${isLight ? 'bg-white' : 'bg-zinc-900'}`}>
                  <div className="flex items-center justify-between">
                    <span className={`text-sm ${textSecondaryClass}`}>Per Person</span>
                    <span className="font-bold text-green-400">
                      ${(booking.total_price / booking.current_participants).toFixed(2)}
                    </span>
                  </div>
                </div>
              </div>
            </div>
            
            <div className="flex gap-2">
              <Button
                variant="outline"
                onClick={() => setActiveAction(null)}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                onClick={handleSplitPayment}
                disabled={splitLoading}
                className="flex-1 bg-green-500 hover:bg-green-600 text-white"
              >
                {splitLoading ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <>
                    <Send className="w-4 h-4 mr-2" />
                    Send Requests
                  </>
                )}
              </Button>
            </div>
          </div>
        )}
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default SessionActionDrawer;

/**
 * SessionChatDrawer.js
 * 
 * Embedded in-session chat drawer for On-Demand dispatch sessions.
 * Used by BOTH surfers (DispatchLobby) and photographers (OnDemandSessionManager).
 * 
 * Features:
 * - Text messaging with quick replies
 * - Voice note recording (30s max)
 * - Real-time delivery via existing DM/conversation system
 * - Typing indicators
 * - Slide-up mobile drawer, side panel on desktop
 * 
 * Architecture:
 * - Leverages the existing /messages/* DM backend (get_or_create_conversation)
 * - Polls for new messages every 3s (aligns with dispatch polling cadence)
 * - Keyed by dispatch_id + both user IDs for deterministic conversation lookup
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';
import apiClient from '../lib/apiClient';
import { getFullUrl } from '../utils/media';
import {
  X, Send, Mic, StopCircle, MessageCircle, ChevronDown,
  Loader2, Check, CheckCheck, Zap
} from 'lucide-react';
import { Badge } from './ui/badge';
import { toast } from 'sonner';
import logger from '../utils/logger';

// Quick replies for on-demand session coordination
const SESSION_QUICK_REPLIES = [
  { id: 'omw', text: "On my way! 🏄", icon: '🚗' },
  { id: 'arrived', text: "Just arrived at the spot 📍", icon: '📍' },
  { id: 'parking', text: "Looking for parking 🅿️", icon: '🅿️' },
  { id: 'ready', text: "Ready when you are! 🤙", icon: '✅' },
  { id: 'where', text: "Where exactly are you?", icon: '📍' },
  { id: 'running_late', text: "Running a few minutes late ⏰", icon: '⏰' },
  { id: 'looking', text: "I'm looking for you 👀", icon: '👀' },
  { id: 'found', text: "Found you! Starting session 📸", icon: '📸' },
  { id: 'waves', text: "Waves are looking good! 🌊", icon: '🌊' },
  { id: 'thanks', text: "Thanks for the session! 🤙", icon: '🙏' },
];

const MAX_VOICE_DURATION = 30; // seconds

// ============ MESSAGE BUBBLE ============
const MessageBubble = ({ message, isMine, isLight }) => {
  const bgMine = isLight
    ? 'bg-gradient-to-r from-cyan-500 to-blue-500 text-white'
    : 'bg-gradient-to-r from-cyan-600 to-blue-600 text-white';
  const bgTheirs = isLight
    ? 'bg-gray-100 text-gray-900'
    : 'bg-zinc-800 text-white';

  const time = new Date(message.created_at).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
  });

  // Voice note rendering
  if (message.message_type === 'voice_note' && message.media_url) {
    return (
      <div className={`flex ${isMine ? 'justify-end' : 'justify-start'} mb-2`}>
        <div
          className={`max-w-[80%] rounded-2xl px-4 py-2.5 ${isMine ? bgMine : bgTheirs}`}
        >
          <audio
            src={getFullUrl(message.media_url)}
            controls
            className="w-full max-w-[200px]"
            style={{ height: 32 }}
          />
          {message.voice_duration_seconds && (
            <p className={`text-[10px] mt-1 ${isMine ? 'text-white/70' : 'text-gray-400'}`}>
              {Math.floor(message.voice_duration_seconds / 60)}:{(message.voice_duration_seconds % 60).toString().padStart(2, '0')}
            </p>
          )}
          <div className={`flex items-center justify-end gap-1 mt-0.5`}>
            <span className={`text-[10px] ${isMine ? 'text-white/60' : 'text-gray-400'}`}>{time}</span>
            {isMine && (
              message.is_read
                ? <CheckCheck className="w-3 h-3 text-cyan-300" />
                : <Check className="w-3 h-3 text-white/50" />
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex ${isMine ? 'justify-end' : 'justify-start'} mb-2`}>
      <div
        className={`max-w-[80%] rounded-2xl px-4 py-2.5 ${isMine ? bgMine : bgTheirs} ${
          isMine ? 'rounded-br-md' : 'rounded-bl-md'
        }`}
      >
        <p className="text-sm whitespace-pre-wrap break-words">{message.content}</p>
        <div className={`flex items-center justify-end gap-1 mt-0.5`}>
          <span className={`text-[10px] ${isMine ? 'text-white/60' : 'text-gray-400'}`}>{time}</span>
          {isMine && (
            message.is_read
              ? <CheckCheck className="w-3 h-3 text-cyan-300" />
              : <Check className="w-3 h-3 text-white/50" />
          )}
        </div>
      </div>
    </div>
  );
};

// ============ MAIN COMPONENT ============
export const SessionChatDrawer = ({
  isOpen,
  onClose,
  otherUserId,
  otherUserName,
  otherUserAvatar,
  _dispatchId,
  isLight = false,
  onUnreadChange,
}) => {
  const { user } = useAuth();
  const [messages, setMessages] = useState([]);
  const [conversationId, setConversationId] = useState(null);
  const [inputValue, setInputValue] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [showQuickReplies, setShowQuickReplies] = useState(false);
  const [_unreadCount, setUnreadCount] = useState(0);

  // Voice recording state
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [isUploadingVoice, setIsUploadingVoice] = useState(false);
  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);
  const recordingIntervalRef = useRef(null);

  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);
  const pollRef = useRef(null);

  const scrollToBottom = useCallback(() => {
    setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  }, []);

  // ============ INITIALIZE CONVERSATION ============
  const initConversation = useCallback(async () => {
    if (!user?.id || !otherUserId) {
      setIsLoading(false);
      return;
    }
    setIsLoading(true);
    try {
      // Check if thread exists
      const checkRes = await apiClient.get(
        `/messages/check-thread/${user.id}/${otherUserId}`
      );
      if (checkRes.data.exists && checkRes.data.conversation_id) {
        setConversationId(checkRes.data.conversation_id);
        // Load messages
        const msgRes = await apiClient.get(
          `/messages/conversation/${checkRes.data.conversation_id}`
        );
        setMessages(msgRes.data.messages || []);
        scrollToBottom();
      } else {
        // No conversation yet — will be created on first message
        setConversationId(null);
        setMessages([]);
      }
    } catch (err) {
      logger.error('[SessionChat] Init error:', err);
    } finally {
      setIsLoading(false);
    }
  }, [user?.id, otherUserId, scrollToBottom]);

  useEffect(() => {
    if (isOpen) {
      initConversation();
    }
  }, [isOpen, initConversation]);

  // ============ POLL FOR NEW MESSAGES ============
  useEffect(() => {
    if (!isOpen || !conversationId || !user?.id) return;

    const pollMessages = async () => {
      try {
        const res = await apiClient.get(
          `/messages/conversation/${conversationId}`
        );
        const newMessages = res.data.messages || [];
        setMessages(prev => {
          // Only update if there are new messages
          if (newMessages.length !== prev.length) {
            const newUnread = newMessages.filter(
              m => !m.is_read && m.sender_id !== user.id
            ).length;
            setUnreadCount(newUnread);
            if (onUnreadChange) onUnreadChange(newUnread);
            scrollToBottom();
            return newMessages;
          }
          return prev;
        });
      } catch (err) {
        logger.debug('[SessionChat] Poll error:', err);
      }
    };

    pollRef.current = setInterval(pollMessages, 3000);
    return () => clearInterval(pollRef.current);
  }, [isOpen, conversationId, user?.id, scrollToBottom]);

  // ============ SEND MESSAGE ============
  const sendMessage = async (content = inputValue) => {
    if (!content.trim() || isSending || !user?.id || !otherUserId) return;

    const messageText = content.trim();
    setInputValue('');
    setIsSending(true);
    setShowQuickReplies(false);

    try {
      const res = await apiClient.post(
        `/messages/send?sender_id=${user.id}`,
        {
          recipient_id: otherUserId,
          content: messageText,
          message_type: 'text',
        }
      );

      // If conversation was just created, save the ID
      if (res.data.conversation_id && !conversationId) {
        setConversationId(res.data.conversation_id);
      }

      // Optimistically add the message
      const optimisticMsg = {
        id: res.data.id || Date.now().toString(),
        sender_id: user.id,
        content: messageText,
        message_type: 'text',
        is_read: false,
        created_at: new Date().toISOString(),
        is_mine: true,
      };
      setMessages(prev => [...prev, optimisticMsg]);
      scrollToBottom();
    } catch (err) {
      logger.error('[SessionChat] Send error:', err);
      toast.error('Failed to send message');
      setInputValue(messageText); // Restore input
    } finally {
      setIsSending(false);
      inputRef.current?.focus();
    }
  };

  // ============ VOICE RECORDING ============
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        stream.getTracks().forEach(track => track.stop());
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        await uploadVoiceNote(audioBlob);
      };

      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);

      recordingIntervalRef.current = setInterval(() => {
        setRecordingTime(prev => {
          if (prev >= MAX_VOICE_DURATION - 1) {
            stopRecording();
            return prev;
          }
          return prev + 1;
        });
      }, 1000);
    } catch (err) {
      logger.error('[SessionChat] Mic error:', err);
      toast.error('Could not access microphone');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (recordingIntervalRef.current) {
        clearInterval(recordingIntervalRef.current);
      }
    }
  };

  const cancelRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
      setIsRecording(false);
      setRecordingTime(0);
      if (recordingIntervalRef.current) {
        clearInterval(recordingIntervalRef.current);
      }
      audioChunksRef.current = [];
    }
  };

  const uploadVoiceNote = async (audioBlob) => {
    if (!otherUserId || !user?.id) return;
    setIsUploadingVoice(true);
    try {
      // If no conversation exists yet, create one first with a placeholder
      let cId = conversationId;
      if (!cId) {
        const initRes = await apiClient.post(
          `/messages/send?sender_id=${user.id}`,
          { recipient_id: otherUserId, content: '', message_type: 'text' }
        );
        cId = initRes.data.conversation_id;
        if (cId) setConversationId(cId);
      }

      if (!cId) {
        toast.error('Could not start conversation');
        return;
      }

      // Upload the actual audio file via the voice-note endpoint
      const formData = new FormData();
      formData.append('file', audioBlob, `voice_${Date.now()}.webm`);
      formData.append('duration', recordingTime.toString());
      formData.append('conversation_id', cId);
      formData.append('sender_id', user.id);

      await apiClient.post('/messages/voice-note', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      toast.success('Voice note sent!');

      // Refresh messages
      const msgRes = await apiClient.get(
        `/messages/conversation/${cId}`
      );
      setMessages(msgRes.data.messages || []);
      scrollToBottom();
    } catch (err) {
      logger.error('[SessionChat] Voice upload error:', err);
      toast.error('Failed to send voice note');
    } finally {
      setIsUploadingVoice(false);
      setRecordingTime(0);
    }
  };

  // ============ THEME CLASSES ============
  const bgDrawer = isLight ? 'bg-white' : 'bg-zinc-950';
  const bgHeader = isLight ? 'bg-white border-gray-200' : 'bg-zinc-900 border-zinc-800';
  const bgInput = isLight ? 'bg-gray-50 border-gray-200' : 'bg-zinc-800 border-zinc-700';
  const bgMessages = isLight ? 'bg-gray-50' : 'bg-zinc-950';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-500' : 'text-gray-400';

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex flex-col" data-testid="session-chat-drawer">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* Drawer Content — full screen on mobile, side panel on desktop */}
      <div
        className={`relative w-full sm:ml-auto sm:w-[420px] h-full sm:h-full flex flex-col ${bgDrawer} sm:rounded-none shadow-2xl animate-in slide-in-from-bottom sm:slide-in-from-right duration-300`}
      >
        {/* ============ HEADER ============ */}
        <div className={`flex items-center gap-3 px-4 py-3 border-b ${bgHeader} flex-shrink-0`}
          style={{ paddingTop: 'max(0.75rem, env(safe-area-inset-top, 0.75rem))' }}
        >
          <button
            onClick={onClose}
            className={`w-8 h-8 rounded-full flex items-center justify-center ${
              isLight ? 'hover:bg-gray-100' : 'hover:bg-zinc-800'
            }`}
          >
            <ChevronDown className={`w-5 h-5 ${textPrimary} sm:hidden`} />
            <X className={`w-5 h-5 ${textPrimary} hidden sm:block`} />
          </button>

          {/* Other user info */}
          <div className="flex items-center gap-3 flex-1">
            <div className="w-9 h-9 rounded-full overflow-hidden ring-2 ring-cyan-400/50 flex-shrink-0">
              {otherUserAvatar ? (
                <img
                  src={getFullUrl(otherUserAvatar)}
                  alt={otherUserName}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full bg-gradient-to-br from-cyan-400 to-blue-500 flex items-center justify-center">
                  <span className="text-white font-bold text-sm">
                    {(otherUserName || '?')[0]?.toUpperCase()}
                  </span>
                </div>
              )}
            </div>
            <div className="min-w-0">
              <p className={`font-semibold text-sm ${textPrimary} truncate`}>
                {otherUserName || 'Session Chat'}
              </p>
              <p className="text-xs text-cyan-400 flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse" />
                In Session
              </p>
            </div>
          </div>

          {/* Session badge */}
          <Badge className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 text-[10px] flex-shrink-0">
            <Zap className="w-3 h-3 mr-0.5" />
            Live
          </Badge>
        </div>

        {/* ============ MESSAGES AREA ============ */}
        <div className={`flex-1 overflow-y-auto px-4 py-3 ${bgMessages}`}>
          {isLoading ? (
            <div className="flex items-center justify-center h-full">
              <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
            </div>
          ) : messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center px-6">
              <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-cyan-500/20 to-blue-500/20 flex items-center justify-center mb-4">
                <MessageCircle className="w-8 h-8 text-cyan-400" />
              </div>
              <p className={`font-semibold ${textPrimary} mb-1`}>Session Chat</p>
              <p className={`text-sm ${textSecondary}`}>
                Coordinate with {otherUserName || 'your partner'} — send a message or quick reply below!
              </p>
            </div>
          ) : (
            <>
              {messages.map((msg) => (
                <MessageBubble
                  key={msg.id}
                  message={msg}
                  isMine={msg.is_mine || msg.sender_id === user?.id}
                  isLight={isLight}
                />
              ))}
              <div ref={messagesEndRef} />
            </>
          )}
        </div>

        {/* ============ QUICK REPLIES ============ */}
        {showQuickReplies && (
          <div className={`px-4 py-2 border-t ${isLight ? 'border-gray-200 bg-white' : 'border-zinc-800 bg-zinc-900'}`}>
            <div className="flex flex-wrap gap-1.5 max-h-[120px] overflow-y-auto">
              {SESSION_QUICK_REPLIES.map((qr) => (
                <button
                  key={qr.id}
                  onClick={() => sendMessage(qr.text)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-all active:scale-95 ${
                    isLight
                      ? 'bg-gray-100 hover:bg-cyan-50 text-gray-700 hover:text-cyan-600 border border-gray-200 hover:border-cyan-300'
                      : 'bg-zinc-800 hover:bg-cyan-500/20 text-gray-300 hover:text-cyan-400 border border-zinc-700 hover:border-cyan-500/40'
                  }`}
                >
                  <span>{qr.icon}</span>
                  <span>{qr.text}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* ============ RECORDING INDICATOR ============ */}
        {isRecording && (
          <div className={`px-4 py-3 border-t ${isLight ? 'border-gray-200 bg-red-50' : 'border-zinc-800 bg-red-500/10'} flex items-center gap-3`}>
            <div className="w-3 h-3 rounded-full bg-red-500 animate-pulse" />
            <span className={`text-sm font-medium ${isLight ? 'text-red-600' : 'text-red-400'} tabular-nums flex-1`}>
              Recording... {Math.floor(recordingTime / 60)}:{(recordingTime % 60).toString().padStart(2, '0')}
            </span>
            <button
              onClick={cancelRecording}
              className="text-red-400 hover:text-red-300 text-xs"
            >
              Cancel
            </button>
            <button
              onClick={stopRecording}
              className="w-9 h-9 rounded-full bg-red-500 hover:bg-red-600 flex items-center justify-center text-white transition-colors"
            >
              <StopCircle className="w-5 h-5" />
            </button>
          </div>
        )}

        {/* ============ INPUT BAR ============ */}
        {!isRecording && (
          <div className={`px-3 py-2.5 border-t ${isLight ? 'border-gray-200 bg-white' : 'border-zinc-800 bg-zinc-900'} flex items-center gap-2 flex-shrink-0`}
            style={{ paddingBottom: 'max(0.625rem, env(safe-area-inset-bottom, 0.625rem))' }}
          >
            {/* Quick reply toggle */}
            <button
              onClick={() => setShowQuickReplies(!showQuickReplies)}
              className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors flex-shrink-0 ${
                showQuickReplies
                  ? 'bg-cyan-500/20 text-cyan-400'
                  : isLight
                  ? 'hover:bg-gray-100 text-gray-400'
                  : 'hover:bg-zinc-800 text-gray-500'
              }`}
              data-testid="quick-reply-toggle"
            >
              <Zap className="w-4 h-4" />
            </button>

            {/* Text input */}
            <div className={`flex-1 flex items-center rounded-full border ${bgInput} px-3`}>
              <input
                ref={inputRef}
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                  }
                }}
                placeholder="Message..."
                className={`flex-1 bg-transparent py-2 text-sm outline-none ${textPrimary} placeholder-gray-400`}
                disabled={isSending || isUploadingVoice}
                data-testid="session-chat-input"
              />
            </div>

            {/* Send or Mic button */}
            {inputValue.trim() ? (
              <button
                onClick={() => sendMessage()}
                disabled={isSending}
                className="w-9 h-9 rounded-full bg-gradient-to-r from-cyan-500 to-blue-500 flex items-center justify-center text-white transition-all hover:scale-105 active:scale-95 flex-shrink-0"
                data-testid="send-message-btn"
              >
                {isSending ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Send className="w-4 h-4" />
                )}
              </button>
            ) : (
              <button
                onClick={startRecording}
                disabled={isUploadingVoice}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-all flex-shrink-0 ${
                  isLight
                    ? 'hover:bg-gray-100 text-gray-500'
                    : 'hover:bg-zinc-800 text-gray-400'
                }`}
                data-testid="voice-note-btn"
              >
                {isUploadingVoice ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Mic className="w-4 h-4" />
                )}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

