import React, { useState, useEffect, useCallback } from 'react';
import { NavLink, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { usePersona, getExpandedRoleInfo } from '../contexts/PersonaContext';
import { Home, Compass, MapPin, Calendar, MessageCircle, Bell, BellRing, User, Settings, LogOut, Camera, Shield, ChevronDown, ChevronRight, Image, CalendarCheck, Radio, ShoppingBag, Heart, Sun, Moon, Waves, Eye, TrendingUp, Zap, Crown, Baby, Lock, Plus, Stamp, Target, Backpack, CreditCard, RefreshCw, BookOpen } from 'lucide-react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { getUnreadCount } from '../services/notificationService';
import { SurfPassport } from './SurfPassport';
import { GlobalSearchBar } from './GlobalSearchBar';
import useActiveSession from '../hooks/useActiveSession';
import logger from '../utils/logger';
import { ROLES } from '../constants/roles';


export const Sidebar = () => {
  const { user, logout } = useAuth();
  const { theme } = useTheme();
  const { getEffectiveRole, isMasked, _activePersona, _isGodMode } = usePersona();
  const navigate = useNavigate();
  const location = useLocation();
  const [unreadCount, setUnreadCount] = useState(0);
  const [unreadMessages, setUnreadMessages] = useState(0);
  const [photoToolsOpen, setPhotoToolsOpen] = useState(false);
  const [backpackOpen, setBackpackOpen] = useState(false);
  const [passportOpen, setPassportOpen] = useState(false);
  const [logoSpinning, setLogoSpinning] = useState(false);
  const { activeSession } = useActiveSession();

  // Logo click: refresh current page in-place
  // On /feed: triggers full feed refresh + scroll to top
  // On any other page: just scrolls to top (universal refresh gesture)
  // The Home nav button is for actually navigating to /feed
  const handleLogoClick = useCallback(() => {
    if (location.pathname === '/feed') {
      window.dispatchEvent(new CustomEvent('feed:refresh'));
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setLogoSpinning(true);
    setTimeout(() => setLogoSpinning(false), 600);
  }, [location.pathname]);
  
  // Get effective role for UI rendering (respects God Mode persona masking)
  const effectiveRole = getEffectiveRole(user?.role);
  const roleInfo = getExpandedRoleInfo(effectiveRole);

  // Dynamic theme icon based on active theme
  const getThemeIcon = () => {
    if (theme === 'light') return Sun;
    if (theme === 'beach') return Waves;
    return Moon; // dark mode
  };
  const ThemeIcon = getThemeIcon();

  // Theme-specific classes
  const isLight = theme === 'light';
  const _isDark = theme === 'dark';
  const isBeach = theme === 'beach';
  
  // Sidebar background: white for light, dark gray for dark, pure black for beach
  const sidebarBgClass = isLight ? 'bg-white border-gray-200' : isBeach ? 'bg-black border-zinc-900' : 'bg-zinc-900 border-zinc-800';
  const textPrimaryClass = isLight ? 'text-gray-900' : isBeach ? 'text-white' : 'text-white';
  // Beach mode gets brighter secondary text for better visibility
  const textSecondaryClass = isLight ? 'text-gray-600' : isBeach ? 'text-gray-300' : 'text-gray-400';
  const hoverBgClass = isLight ? 'hover:bg-gray-100' : 'hover:bg-zinc-800';
  const borderClass = isLight ? 'border-gray-200' : isBeach ? 'border-zinc-900' : 'border-zinc-800';
  
  // Home button highlight: lime-to-yellow for light/beach, yellow-to-orange for dark
  const activeHighlightClass = isLight || isBeach 
    ? 'bg-gradient-to-r from-lime-400 to-yellow-400 text-black font-medium'
    : 'bg-gradient-to-r from-yellow-400 to-orange-400 text-black font-medium';

  // Check if user is a photographer (use effective role for God Mode)
  const isPhotographer = ['Grom Parent', 'Hobbyist', 'Photographer', 'Approved Pro'].includes(effectiveRole);
  
  // Check if user is a surfer (not photographer-only roles)
  const isSurfer = ['Grom', 'Surfer', 'Comp Surfer', 'Pro'].includes(effectiveRole);
  
  // Check if user is a Grom (shows The Inside hub - includes Stoked features)
  const isGrom = effectiveRole === ROLES.GROM;
  
  // Check if user is a Comp Surfer (shows Impact Zone)
  const isCompSurfer = effectiveRole === ROLES.COMP_SURFER;
  
  // Check if user is a Pro (shows The Peak)
  const isPro = effectiveRole === ROLES.PRO;
  
  // Check if user is a regular surfer (role = Surfer, not Comp Surfer/Pro/Grom)
  const isRegularSurfer = effectiveRole === ROLES.SURFER;

  // Check if user qualifies for Stoked tab:
  // - Comp Surfer or Pro role always gets access
  // - Regular Surfer in any competitive/pro surf_mode also gets access
  const isProSurferMode = user?.surf_mode === 'pro';
  const isCompetitiveSurferMode = user?.surf_mode === 'competitive';
  const isCompetitiveSurfer = isCompetitiveSurferMode || isProSurferMode; // used for Stoked access + locking
  const hasStokesAccess = ['Comp Surfer', 'Pro'].includes(effectiveRole) || (isRegularSurfer && isCompetitiveSurfer);
  
  // Locked only if Surfer AND still in casual/non-competitive mode
  const isStokedLocked = isRegularSurfer && !isCompetitiveSurfer;
  
  // Check if user is a hobbyist (shows Gear Hub) - Grom Parent is NOT a hobbyist (gets Grom HQ instead)
  const isHobbyist = effectiveRole === ROLES.HOBBYIST;
  
  // Check if user is a Grom Parent (shows Grom HQ)
  const isGromParent = effectiveRole === ROLES.GROM_PARENT || user?.is_grom_parent === true;
  
  // Check if current path is a photo tools path
  const isPhotoToolsPath = ['/gallery', '/photographer/bookings', '/photographer/sessions', '/photographer/on-demand', '/photographer/earnings', '/photographer/on-demand-settings', '/photographer/subscription-settings'].some(path => 
    location.pathname.startsWith(path)
  );
  
  // Auto-expand photo tools if on a photo tools path
  useEffect(() => {
    if (isPhotoToolsPath) {
      setPhotoToolsOpen(true);
    }
  }, [isPhotoToolsPath]);

  useEffect(() => {
    if (user?.id) {
      fetchUnreadCount();
      fetchUnreadMessages();
      // Poll every 30 seconds for new notifications and messages (sidebar badges)
      const notifInterval = setInterval(() => {
        fetchUnreadCount();
        fetchUnreadMessages();
      }, 30000);
      // Auto-refresh feed every 60 seconds when on /feed (Twitter/Instagram pattern)
      const feedInterval = setInterval(() => {
        if (window.location.pathname === '/feed') {
          window.dispatchEvent(new CustomEvent('feed:refresh', { detail: { silent: true } }));
        }
      }, 60000);
      return () => {
        clearInterval(notifInterval);
        clearInterval(feedInterval);
      };
    }
  }, [user?.id]);

  const fetchUnreadCount = async () => {
    try {
      const response = await getUnreadCount(user.id);
      setUnreadCount(response.data.unread_count || 0);
    } catch (error) {
      logger.error('Failed to fetch notification count:', error);
    }
  };

  const fetchUnreadMessages = async () => {
    try {
      // Use the lightweight unread-counts endpoint instead of downloading
      // the full conversation list (which eagerly loads all messages).
      const response = await apiClient.get(`/messages/unread-counts/${user.id}`);
      setUnreadMessages(response.data.total || 0);
    } catch (error) {
      logger.error('Failed to fetch message count:', error);
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  // Build nav items dynamically based on user role
  const navItems = [
    { path: '/feed', icon: Home, label: 'Home' },
    // Notifications moved up for engagement - right below Home
    { path: '/notifications', icon: Bell, label: 'Notifications', badge: unreadCount },
    { path: '/explore', icon: Compass, label: 'Explore' },
    { path: '/map', icon: MapPin, label: 'Map' },
    // Bookings - Only for surfers. Photographers have their own Bookings Manager under Photo Tools.
    ...(!isPhotographer ? [{ path: '/bookings', icon: Calendar, label: 'Bookings' }] : []),
    // Create button - special handling (not a NavLink)
    { id: 'create', icon: Plus, label: 'Create', isCreateButton: true },
    // Career Hub: The Peak for Pro role OR Surfer in pro surf_mode
    ...(isPro || (isRegularSurfer && isProSurferMode) ? [{ path: '/career/the-peak', icon: Crown, label: 'The Peak', highlight: true, highlightColor: 'amber' }] : []),
    // Career Hub: Impact Zone for Comp Surfers OR Surfers in competitive surf_mode (NOT pro mode - they get The Peak)
    ...(isCompSurfer || (isRegularSurfer && isCompetitiveSurferMode) ? [{ path: '/career/impact-zone', icon: Target, label: 'Impact Zone', highlight: true, highlightColor: 'orange' }] : []),
    // Career Hub: The Inside for Groms (includes Stoked features - no separate Stoked for Groms)
    ...(isGrom ? [{ path: '/career/the-inside', icon: Baby, label: 'The Inside', highlight: true, highlightColor: 'cyan' }] : []),
    // Stoked tab ONLY for Comp Surfer, Pro - Groms use The Inside instead
    ...(hasStokesAccess ? [{ path: '/stoked', icon: Zap, label: 'Stoked', highlight: true, highlightColor: 'yellow' }] : []),
    // Regular Surfers see Locked placeholder only if in casual mode
    ...(isStokedLocked ? [{ path: '/stoked-locked', icon: Zap, label: 'Stoked', isLocked: true }] : []),
    // Impacted tab for ALL photographers (Hobbyist, Photographer, Approved Pro) - NOT Grom Parent
    ...(!isGromParent && isPhotographer ? [{ path: '/impacted', icon: Heart, label: 'Impacted', highlight: true, highlightColor: 'pink' }] : []),
    // Grom HQ for Grom Parents (Shield icon)
    ...(isGromParent ? [{ path: '/grom-hq', icon: Shield, label: 'Grom HQ', highlight: true, highlightColor: 'cyan' }] : []),
    ...(isHobbyist ? [{ path: '/gear-hub', icon: ShoppingBag, label: 'Gear Hub', highlight: true, highlightColor: 'emerald' }] : []),
    { path: '/messages', icon: MessageCircle, label: 'Messages', badge: unreadMessages },
    // My Gallery for Surfers - "The Locker" - positioned after Messages per Master Logic Sync
    ...(isSurfer ? [{ path: '/my-gallery', icon: Lock, label: 'My Gallery', highlight: true, highlightColor: 'cyan' }] : []),
    // Backpack - expandable menu with Passport, Wallet, Surf Alerts
    { id: 'backpack', icon: Backpack, label: 'Backpack', isBackpackMenu: true, highlight: true, highlightColor: 'amber' },
    { path: '/profile', icon: User, label: 'Profile' },
  ];

  // Photo tools sub-items for photographers - ROLE BASED
  // Grom Parent: Gallery ONLY (renamed to "Grom Archive"), NO commerce
  // Hobbyist: Gallery only - can spend but not earn
  // Photographer/Approved Pro: Full access
  const getPhotoToolsItems = () => {
    if (isGromParent) {
      // Grom Parent: Only archive gallery, zero commerce
      return [
        { path: '/gallery', icon: Image, label: 'Grom Archive' },
      ];
    }
    
    if (effectiveRole === ROLES.HOBBYIST) {
      // Hobbyist: Can spend but not earn - no earnings/bookings/sessions
      return [
        { path: '/gallery', icon: Image, label: 'Gallery Hub' },
      ];
    }
    
    // Professional photographers: Full access
    return [
      { path: '/gallery', icon: Image, label: 'Gallery Hub' },
      { path: '/photographer/bookings', icon: CalendarCheck, label: 'Bookings Manager' },
      { path: '/photographer/sessions', icon: Radio, label: 'Live Sessions' },
      { path: '/photographer/on-demand', icon: Zap, label: 'On-Demand Hub' },
      { path: '/photographer/earnings', icon: TrendingUp, label: 'Earnings Dashboard' },
      { path: '/photographer/subscription-settings', icon: RefreshCw, label: 'Subscription Settings' },
    ];
  };
  
  const photoToolsItems = getPhotoToolsItems();
  
  // Backpack sub-items - Surf Log, Passport, Wallet, Surf Alerts
  const backpackItems = [
    { path: '/surf-log', icon: BookOpen, label: 'Surf Log', color: 'text-cyan-400' },
    { id: 'passport', icon: Stamp, label: 'Surf Passport', isPassportButton: true, color: 'text-emerald-400' },
    { path: '/wallet', icon: CreditCard, label: 'Credit Wallet', color: 'text-yellow-400' },
    { path: '/alerts', icon: BellRing, label: 'Surf Alerts', color: 'text-orange-400' },
  ];
  
  // On-Demand Settings - Available for Photographer and Approved Pro (NOT Hobbyist/Grom Parent)
  const canUseOnDemand = ['Photographer', 'Pro', 'Approved Pro'].includes(effectiveRole);
  const onDemandSettingsItem = canUseOnDemand 
    ? { path: '/photographer/on-demand-settings', icon: MapPin, label: 'On-Demand Settings' }
    : null;

  // Get role badge color
  const _getRoleBadgeColor = (role) => {
    const surferRoles = ['Grom', 'Surfer', 'Comp Surfer', 'Pro'];
    const photographerRoles = ['Grom Parent', 'Hobbyist', 'Photographer', 'Approved Pro'];
    
    if (surferRoles.includes(role)) return 'bg-yellow-400';
    if (photographerRoles.includes(role)) return 'bg-cyan-400';
    return 'bg-emerald-400'; // Business
  };

  return (
    <aside className={`fixed left-0 top-0 h-full w-[200px] ${sidebarBgClass} border-r flex flex-col z-[100] hidden md:flex transition-colors duration-300`}>
      {/* Logo - Compact, clickable (Instagram-style refresh) */}
      <div className={`p-3 border-b ${borderClass} flex-shrink-0`}>
        <button
          onClick={handleLogoClick}
          className="flex items-center gap-2 group cursor-pointer"
          title={location.pathname === '/feed' ? 'Refresh feed' : 'Go to Feed'}
          aria-label={location.pathname === '/feed' ? 'Refresh feed' : 'Go to Feed'}
        >
          <img
            src="https://customer-assets.emergentagent.com/job_raw-surf-os/artifacts/9llcl5mg_Rawig6-500x500.png"
            alt="Raw Surf"
            className={`w-7 h-7 transition-transform duration-300 ${
              logoSpinning ? 'rotate-[360deg]' : ''
            } group-hover:scale-110`}
            style={{ transition: logoSpinning ? 'transform 0.6s cubic-bezier(0.34,1.56,0.64,1)' : 'transform 0.2s ease' }}
          />
          <span className={`text-base font-bold ${textPrimaryClass} group-hover:opacity-80 transition-opacity`} style={{ fontFamily: 'Oswald' }}>Raw Surf</span>
        </button>
        
        {/* Role badge - shows actual role or persona when masking */}
        {user && (
          <div className="mt-2">
            {isMasked ? (
              <>
                <span className={`text-[10px] ${textSecondaryClass} flex items-center gap-1`}>
                  <Eye className="w-3 h-3 text-cyan-400" />
                  Testing as
                </span>
                <div className="mt-0.5 flex items-center gap-1">
                  <span className="text-sm">{roleInfo.icon}</span>
                  <span className={`text-[11px] font-medium ${roleInfo.color}`}>
                    {roleInfo.label}
                  </span>
                </div>
                <span className="text-[9px] text-cyan-400 block">
                  (God Mode - Actual: {getExpandedRoleInfo(user.role)?.label || user.role})
                </span>
              </>
            ) : (
              <>
                <span className={`text-[10px] ${textSecondaryClass}`}>Your Role</span>
                <div className="mt-0.5 flex items-center gap-1">
                  <span className="text-sm">{getExpandedRoleInfo(user.role)?.icon || '🏄'}</span>
                  <span className={`text-[11px] font-medium ${getExpandedRoleInfo(user.role)?.color || 'text-cyan-400'}`}>
                    {getExpandedRoleInfo(user.role)?.label || user.role}
                  </span>
                </div>
              </>
            )}
          </div>
        )}
      </div>

      {/* Navigation - Scrollable section with minimum height */}
      <nav className="flex-1 p-2 overflow-y-auto min-h-0 scrollbar-thin scrollbar-thumb-zinc-700 scrollbar-track-transparent">
        {navItems.map((item, _index) => {
          const Icon = item.icon;
          
          // Dynamic highlight colors based on item.highlightColor
          const getHighlightClasses = (color, isActive) => {
            const colors = {
              amber: isActive ? 'bg-amber-500 text-black font-medium' : 'text-amber-400 hover:bg-amber-500/10',
              cyan: isActive ? 'bg-cyan-500 text-black font-medium' : 'text-cyan-400 hover:bg-cyan-500/10',
              yellow: isActive ? 'bg-gradient-to-r from-yellow-400 to-orange-400 text-black font-medium' : 'text-yellow-400 hover:bg-yellow-500/10',
              pink: isActive ? 'bg-pink-500 text-white font-medium' : 'text-pink-400 hover:bg-pink-500/10',
              emerald: isActive ? 'bg-emerald-500 text-black font-medium' : 'text-emerald-400 hover:bg-emerald-500/10',
              red: isActive ? 'bg-red-500 text-white font-medium' : 'text-red-400 hover:bg-red-500/10'
            };
            return colors[color] || colors.red;
          };
          
          // Insert Search Bar after Map item
          const isMapItem = item.path === '/map';
          
          // Locked item - show placeholder instead of NavLink
          if (item.isLocked) {
            return (
              <div
                key={item.path}
                className="flex items-center gap-2 px-3 py-2 rounded-lg mb-0.5 text-gray-600 cursor-not-allowed text-sm"
                data-testid={`nav-${item.label.toLowerCase()}-locked`}
                title="Compete to unlock the Stoked Sponsorship Engine"
              >
                <div className="relative">
                  <Icon className="w-4 h-4 opacity-50" />
                  <Lock className="w-2.5 h-2.5 absolute -bottom-0.5 -right-0.5 text-gray-500" />
                </div>
                <div className="flex flex-col">
                  <span className="opacity-50">{item.label}</span>
                  <span className="text-[9px] text-gray-500">Compete to unlock</span>
                </div>
              </div>
            );
          }

          // Create button - special handling, navigates to /create
          if (item.isCreateButton) {
            return (
              <button
                key="create"
                onClick={() => navigate('/create')}
                className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg mb-0.5 transition-all text-sm ${textSecondaryClass} ${hoverBgClass} hover:${textPrimaryClass}`}
                data-testid="nav-create"
              >
                <Plus className="w-4 h-4" />
                <span>Create</span>
              </button>
            );
          }

          // Backpack menu - expandable with Passport, Wallet, Alerts
          if (item.isBackpackMenu) {
            return (
              <div key="backpack-menu" className="mb-0.5">
                <button
                  onClick={() => setBackpackOpen(!backpackOpen)}
                  className={`w-full flex items-center justify-between px-3 py-2 rounded-lg transition-all text-sm text-amber-400 hover:bg-amber-500/10`}
                  data-testid="nav-backpack"
                >
                  <div className="flex items-center gap-2">
                    <Backpack className="w-4 h-4" />
                    <span>Backpack</span>
                  </div>
                  {backpackOpen ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                </button>
                {backpackOpen && (
                  <div className="ml-3 pl-3 border-l border-amber-500/20 mt-1 space-y-0.5">
                    {backpackItems.map((subItem) => {
                      const SubIcon = subItem.icon;
                      if (subItem.isPassportButton) {
                        return (
                          <button
                            key="passport"
                            onClick={() => setPassportOpen(true)}
                            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg transition-all text-sm ${subItem.color} hover:bg-emerald-500/10`}
                            data-testid="nav-passport"
                          >
                            <SubIcon className="w-4 h-4" />
                            <span>{subItem.label}</span>
                          </button>
                        );
                      }
                      return (
                        <NavLink
                          key={subItem.path}
                          to={subItem.path}
                          className={({ isActive }) =>
                            `flex items-center gap-2 px-3 py-2 rounded-lg transition-all text-sm ${
                              isActive
                                ? `${subItem.color} bg-${subItem.color.split('-')[1]}-500/20`
                                : `${subItem.color} hover:bg-${subItem.color.split('-')[1]}-500/10`
                            }`
                          }
                          data-testid={`nav-${subItem.label.toLowerCase().replace(' ', '-')}`}
                        >
                          <SubIcon className="w-4 h-4" />
                          <span>{subItem.label}</span>
                        </NavLink>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }
          
          return ([
            <NavLink
              key={item.path}
              to={item.path}
              className={({ isActive }) =>
                `flex items-center gap-2 px-3 py-2 rounded-lg mb-0.5 transition-all text-sm ${
                  isActive
                    ? item.highlight 
                      ? getHighlightClasses(item.highlightColor, true)
                      : activeHighlightClass
                    : item.highlight
                      ? getHighlightClasses(item.highlightColor, false)
                      : `${textSecondaryClass} ${hoverBgClass} hover:${textPrimaryClass}`
                }`
              }
              data-testid={`nav-${item.label.toLowerCase().replace(' ', '-')}`}
            >
              <div className="relative">
                <Icon className="w-5 h-5" />
                {item.badge > 0 && (
                  <span className="absolute -top-1.5 -right-1.5 min-w-[18px] h-[18px] px-1 flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full">
                    {item.badge > 99 ? '99+' : item.badge}
                  </span>
                )}
              </div>
              <span>{item.label}</span>
            </NavLink>,
            // Insert search bar after Map item
            isMapItem && (
              <div key="search-bar" className="px-2 py-2">
                <GlobalSearchBar variant="desktop" className="w-full" />
              </div>
            ),
          ].filter(Boolean));
        })}

        {/* Active Session Indicator — standalone, visible to ALL roles */}
        {activeSession && (
          <button
            onClick={() => {
              if (['accepted', 'en_route', 'arrived', 'in_session'].includes(activeSession.status)) {
                navigate(`/dispatch/${activeSession.id}/lobby`);
              } else {
                navigate('/bookings?tab=on_demand');
              }
            }}
            className="w-full px-3 py-1.5 text-left transition-all hover:opacity-80"
            data-testid="sidebar-active-session"
          >
            <span
              className={`text-[11px] font-semibold animate-pulse ${
                activeSession.role === 'crew_member' ? 'text-cyan-400' : 'text-amber-400'
              }`}
            >
              {activeSession.status === 'in_session'
                ? '📸 Live Shooting Session Active'
                : activeSession.status === 'searching_for_pro'
                ? '🔍 On-Demand Session Searching...'
                : activeSession.status === 'en_route'
                ? '🚗 Photographer On The Way'
                : activeSession.status === 'arrived'
                ? '📍 Photographer Arrived'
                : '⚡ On-Demand Session Active'
              }
            </span>
          </button>
        )}

        {/* Photo Tools Section - Only for Photographers */}
        {isPhotographer && (
          <div className="mt-2">
            <button
              onClick={() => setPhotoToolsOpen(!photoToolsOpen)}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-lg mb-1 transition-all ${
                isPhotoToolsPath
                  ? 'bg-gradient-to-r from-cyan-400/20 to-blue-400/20 text-cyan-400'
                  : `${textSecondaryClass} ${hoverBgClass} hover:${textPrimaryClass}`
              }`}
              data-testid="nav-photo-tools"
            >
              <div className="flex items-center gap-3">
                <Camera className="w-5 h-5" />
                <span>Photo Tools</span>
              </div>
              {photoToolsOpen ? (
                <ChevronDown className="w-4 h-4" />
              ) : (
                <ChevronRight className="w-4 h-4" />
              )}
            </button>
            
            {/* Sub-items */}
            {photoToolsOpen && (
              <div className="ml-4 space-y-1">
                {photoToolsItems.map((item) => {
                  const Icon = item.icon;
                  return (
                    <NavLink
                      key={item.path}
                      to={item.path}
                      className={({ isActive }) =>
                        `flex items-center gap-3 px-4 py-2 rounded-lg transition-all text-sm ${
                          isActive
                            ? 'bg-cyan-400/20 text-cyan-400 font-medium'
                            : `${textSecondaryClass} ${hoverBgClass} hover:${textPrimaryClass}`
                        }`
                      }
                      data-testid={`nav-${item.label.toLowerCase().replace(' ', '-')}`}
                    >
                      <Icon className="w-4 h-4" />
                      <span>{item.label}</span>
                    </NavLink>
                  );
                })}
                
                {/* On-Demand Settings - Photographer & Approved Pro */}
                {onDemandSettingsItem && (
                  <NavLink
                    to={onDemandSettingsItem.path}
                    className={({ isActive }) =>
                      `flex items-center gap-3 px-4 py-2 rounded-lg transition-all text-sm ${
                        isActive
                          ? 'bg-amber-400/20 text-amber-400 font-medium'
                          : `text-amber-400 ${hoverBgClass} hover:text-amber-300`
                      }`
                    }
                    data-testid="nav-on-demand-settings"
                  >
                    <onDemandSettingsItem.icon className="w-4 h-4" />
                    <span>{onDemandSettingsItem.label}</span>
                  </NavLink>
                )}
              </div>
            )}
          </div>
        )}
      </nav>

      {/* Bottom actions - Compact for smaller screens */}
      <div className={`p-2 border-t ${borderClass} flex-shrink-0`}>
        {/* Settings - User preferences, notifications, billing */}
        <NavLink
          to="/settings"
          className={({ isActive }) =>
            `flex items-center gap-3 px-4 py-2 rounded-lg mb-0.5 transition-all text-sm ${
              isActive
                ? activeHighlightClass
                : `${textSecondaryClass} ${hoverBgClass} hover:${textPrimaryClass}`
            }`
          }
          data-testid="nav-settings"
        >
          <Settings className="w-4 h-4" />
          <span>Settings</span>
        </NavLink>
        
        {/* Admin Console - Only visible to admins (Unified entry point) */}
        {user?.is_admin && (
          <NavLink
            to="/admin"
            className={({ isActive }) =>
              `flex items-center gap-3 px-4 py-2 rounded-lg mb-0.5 transition-all text-sm ${
                isActive
                  ? 'bg-gradient-to-r from-red-500 to-yellow-500 text-black font-medium'
                  : 'text-red-400 hover:bg-red-500/10 hover:text-red-300'
              }`
            }
            data-testid="nav-admin-console"
          >
            <Shield className="w-4 h-4" />
            <span>Admin Console</span>
          </NavLink>
        )}
        
        {/* Theme & Logout in a row to save space */}
        <div className="flex items-center gap-1 mt-1">
          <NavLink
            to="/theme"
            className={({ isActive }) =>
              `flex-1 flex items-center justify-center gap-2 px-2 py-2 rounded-lg transition-all text-sm ${
                isActive
                  ? activeHighlightClass
                  : `${textSecondaryClass} ${hoverBgClass} hover:${textPrimaryClass}`
              }`
            }
            data-testid="nav-theme"
          >
            <ThemeIcon className="w-4 h-4" />
            <span className="hidden lg:inline">Theme</span>
          </NavLink>
          
          <button
            onClick={handleLogout}
            className={`flex-1 flex items-center justify-center gap-2 px-2 py-2 rounded-lg ${textSecondaryClass} ${hoverBgClass} hover:${textPrimaryClass} transition-all text-sm`}
            data-testid="nav-logout"
          >
            <LogOut className="w-4 h-4" />
            <span className="hidden lg:inline">Log out</span>
          </button>
        </div>
      </div>
      
      {/* Surf Passport Modal */}
      <SurfPassport isOpen={passportOpen} onClose={() => setPassportOpen(false)} />
    </aside>
  );
};

/**
 * SinglePost - View a single post with full details
 * Used when navigating directly to /post/:postId
 */
import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { ArrowLeft, Loader2, X } from 'lucide-react';
import { Button } from './ui/button';
import PostCard from './PostCard';
import PostMenu, { SharePostModal } from './PostMenu';
import { toast } from 'sonner';
import logger from '../utils/logger';
import { REACTION_EMOJIS } from '../constants/emojis';


const SinglePost = () => {
  const { postId } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';
  
  const [post, setPost] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Comment state
  const [commentInputs, setCommentInputs] = useState({});
  const [showAllComments, setShowAllComments] = useState({});
  const [allComments, setAllComments] = useState({});
  const [loadingComments, setLoadingComments] = useState({});
  
  // Following state
  const [followingUsers, setFollowingUsers] = useState(new Set());
  
  // Menu state
  const [postMenuOpen, setPostMenuOpen] = useState(null);
  const [sharePostOpen, setSharePostOpen] = useState(null);
  
  // Live users (empty for single post view)
  const [liveUsers] = useState([]);
  const [connectingToStream] = useState(null);

  // Smart back navigation - uses browser history when available
  const handleBack = () => {
    // If we have history entries beyond the initial page load, go back
    // window.history.length > 1 means there's at least one page to go back to
    if (window.history.length > 1) {
      navigate(-1);
    } else {
      // Only fallback to feed if there's truly no history (e.g., direct URL access)
      navigate('/feed', { replace: true });
    }
  };

  // Theme classes
  const bgClass = isLight ? 'bg-gray-50' : 'bg-black';
  const textPrimaryClass = isLight ? 'text-gray-900' : 'text-white';
  const textSecondaryClass = isLight ? 'text-gray-500' : 'text-gray-400';
  const borderClass = isLight ? 'border-gray-200' : 'border-zinc-800';
  const postCardBgClass = isLight ? 'bg-white' : 'bg-zinc-900/50';


  useEffect(() => {
    fetchPost();
    if (user?.id) {
      fetchFollowing();
    }
  }, [postId, user?.id]);

  // Auto-load all comments when viewing single post
  useEffect(() => {
    if (post?.id && !showAllComments[post.id]) {
      loadAllComments(post.id);
      setShowAllComments(prev => ({ ...prev, [post.id]: true }));
    }
  }, [post?.id]);

  const fetchPost = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(`/posts/${postId}`, {
        params: { viewer_id: user?.id }
      });
      setPost(response.data);
      setError(null);
    } catch (err) {
      logger.error('Error fetching post:', err);
      setError(err.response?.status === 404 ? 'Post not found' : 'Failed to load post');
    } finally {
      setLoading(false);
    }
  };

  const fetchFollowing = async () => {
    try {
      const response = await apiClient.get(`/follows/${user.id}/following`);
      const followingIds = new Set(response.data.map(f => f.following_id));
      setFollowingUsers(followingIds);
    } catch (err) {
      logger.error('Error fetching following:', err);
    }
  };

  // Like/Reaction handlers
  // Shaka reaction handlers with long-press for emoji picker
  const [showReactionPicker, setShowReactionPicker] = useState(false);
  const [isPressing, setIsPressing] = useState(false);
  const pressTimerRef = React.useRef(null);
  const isPressingRef = React.useRef(false);
  const pickerShownRef = React.useRef(false);
  
  const VALID_REACTIONS = REACTION_EMOJIS;
  
  const handleShakaPointerDown = (postId, _e) => {
    if (pressTimerRef.current) {
      clearTimeout(pressTimerRef.current);
      pressTimerRef.current = null;
    }
    
    isPressingRef.current = true;
    pickerShownRef.current = false;
    setIsPressing(true);
    
    // Long press to show picker
    pressTimerRef.current = setTimeout(() => {
      pickerShownRef.current = true;
      if (navigator.vibrate) navigator.vibrate(10);
      setShowReactionPicker(postId);
      setIsPressing(false);
    }, 600);
  };

  const handleShakaPointerUp = async (postId, _e) => {
    const wasPressing = isPressingRef.current;
    const pickerWasShown = pickerShownRef.current;
    
    setIsPressing(false);
    isPressingRef.current = false;
    
    if (pressTimerRef.current) {
      clearTimeout(pressTimerRef.current);
      pressTimerRef.current = null;
    }
    
    // If picker was shown, don't trigger quick tap
    if (pickerWasShown || showReactionPicker) {
      return;
    }
    
    // Quick tap = toggle shaka reaction
    if (wasPressing) {
      await handleReaction(postId, '🤙');
    }
  };
  
  const handleShakaPointerLeave = () => {
    setIsPressing(false);
    isPressingRef.current = false;
    if (pressTimerRef.current) {
      clearTimeout(pressTimerRef.current);
      pressTimerRef.current = null;
    }
  };
  
  const handleReaction = async (postId, emoji) => {
    if (!user?.id) {
      toast.error('Please log in to react');
      return;
    }
    
    setShowReactionPicker(false);
    
    try {
      const response = await apiClient.post(`/posts/${postId}/reactions`, 
        { emoji },
        { }
      );
      
      const action = response.data.action;
      
      if (action === 'added') {
        // New reaction added - increment count
        setPost(prev => {
          const newReactions = [...(prev.reactions || []), { user_id: user.id, emoji }];
          return {
            ...prev,
            liked: true,
            reactions: newReactions,
            likes_count: (prev.likes_count || 0) + 1
          };
        });
        toast.success(`Reacted with ${emoji}`);
      } else if (action === 'changed') {
        // Changed emoji - update reaction but don't change count
        setPost(prev => {
          const filteredReactions = (prev.reactions || []).filter(r => r.user_id !== user.id);
          const newReactions = [...filteredReactions, { user_id: user.id, emoji }];
          return {
            ...prev,
            liked: true,
            reactions: newReactions
            // Don't change likes_count - just swapped emoji
          };
        });
        toast.success(`Changed to ${emoji}`);
      } else if (action === 'removed') {
        // Reaction removed - decrement count
        setPost(prev => {
          const filteredReactions = (prev.reactions || []).filter(r => r.user_id !== user.id);
          return {
            ...prev,
            liked: false,
            reactions: filteredReactions,
            likes_count: Math.max(0, (prev.likes_count || 1) - 1)
          };
        });
      }
    } catch (err) {
      toast.error('Failed to add reaction');
    }
  };

  // Save post
  const handleSavePost = async (postId, isSaved) => {
    if (!user?.id) {
      toast.error('Please log in to save posts');
      return;
    }
    
    try {
      if (isSaved) {
        await apiClient.delete(`/posts/${postId}/save`, {
        });
        setPost(prev => ({ ...prev, saved: false }));
        toast.success('Removed from saved');
      } else {
        await apiClient.post(`/posts/${postId}/save`, null, {
        });
        setPost(prev => ({ ...prev, saved: true }));
        toast.success('Saved!');
      }
    } catch (err) {
      toast.error('Failed to save post');
    }
  };

  // Comment handlers
  const handleCommentSubmit = async (postId) => {
    const content = commentInputs[postId]?.trim();
    if (!content || !user?.id) return;
    
    try {
      await apiClient.post(
        `/posts/${postId}/comments`,
        { content },
        { }
      );
      
      setCommentInputs(prev => ({ ...prev, [postId]: '' }));
      setPost(prev => ({
        ...prev,
        comments_count: (prev.comments_count || 0) + 1
      }));
      
      // Reload comments if showing
      if (showAllComments[postId]) {
        loadAllComments(postId);
      }
      
      toast.success('Comment added');
    } catch (err) {
      toast.error('Failed to add comment');
    }
  };

  const loadAllComments = async (postId) => {
    setLoadingComments(prev => ({ ...prev, [postId]: true }));
    try {
      const response = await apiClient.get(`/posts/${postId}/comments`, {
        params: { viewer_id: user?.id }
      });
      setAllComments(prev => ({ ...prev, [postId]: response.data }));
      setShowAllComments(prev => ({ ...prev, [postId]: true }));
    } catch (err) {
      toast.error('Failed to load comments');
    } finally {
      setLoadingComments(prev => ({ ...prev, [postId]: false }));
    }
  };

  const hideAllComments = (postId) => {
    setShowAllComments(prev => ({ ...prev, [postId]: false }));
  };

  // Follow handlers
  const handleFollowFromFeed = async (userId, userName) => {
    if (!user?.id) return;
    
    try {
      await apiClient.post(`/follows/${user.id}/follow/${userId}`);
      setFollowingUsers(prev => new Set([...prev, userId]));
      toast.success(`Following ${userName}`);
    } catch (err) {
      toast.error('Failed to follow');
    }
  };

  // Collaboration handlers
  const handleIWasThere = async (postId) => {
    if (!user?.id) {
      toast.error('Please log in');
      return;
    }
    
    try {
      await apiClient.post(`/posts/${postId}/collaborators`, null, {
      });
      toast.success("Added you as a collaborator!");
      fetchPost(); // Refresh to show updated collaborators
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to add collaboration');
    }
  };

  const handleViewCollaborators = (_postId) => {
    // Could show a modal, for now just a toast
    const collabs = post?.collaborators || [];
    if (collabs.length === 0) {
      toast.info('No collaborators yet');
    } else {
      toast.info(`${collabs.length} collaborator${collabs.length > 1 ? 's' : ''} in this session`);
    }
  };

  const handleJoinLive = () => {
    // Not applicable for single post view
  };

  // Post menu handlers
  const handlePostUpdated = (updatedPost) => {
    setPost(prev => ({ ...prev, ...updatedPost }));
  };

  const handlePostDeleted = () => {
    toast.success('Post deleted');
    navigate('/feed');
  };

  const handleUnfollowFromMenu = async (userId) => {
    if (!user?.id) return;
    try {
      await apiClient.delete(`/follows/${user.id}/unfollow/${userId}`);
      setFollowingUsers(prev => {
        const next = new Set(prev);
        next.delete(userId);
        return next;
      });
      toast.success('Unfollowed');
    } catch (err) {
      toast.error('Failed to unfollow');
    }
  };

  if (loading) {
    return (
      <div className={`min-h-screen ${bgClass} flex items-center justify-center`}>
        <Loader2 className={`w-8 h-8 animate-spin ${textSecondaryClass}`} />
      </div>
    );
  }

  if (error || !post) {
    return (
      <div className={`min-h-screen ${bgClass} flex flex-col items-center justify-center gap-4`}>
        <p className={textPrimaryClass}>{error || 'Post not found'}</p>
        <Button onClick={() => navigate('/feed')} variant="outline">
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Feed
        </Button>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${bgClass}`}>
      {/* Header — sticky on mobile for easy back navigation, static on desktop (Instagram pattern) */}
      <div className={`sticky md:relative top-0 z-20 ${isLight ? 'bg-white/95 backdrop-blur-sm' : 'bg-zinc-900/95 backdrop-blur-sm'} border-b ${borderClass}`}>
        <div className="max-w-2xl mx-auto flex items-center gap-3 px-4 py-3">
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={handleBack}
            className={textPrimaryClass}
          >
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <h1 className={`font-semibold ${textPrimaryClass}`}>Post</h1>
        </div>
      </div>

      {/* Post */}
      <div className="max-w-2xl mx-auto">
        <PostCard
          post={post}
          user={user}
          isLight={isLight}
          textPrimaryClass={textPrimaryClass}
          textSecondaryClass={textSecondaryClass}
          borderClass={borderClass}
          postCardBgClass={postCardBgClass}
          liveUsers={liveUsers}
          connectingToStream={connectingToStream}
          followingUsers={followingUsers}
          commentInputs={commentInputs}
          showAllComments={showAllComments}
          allComments={allComments}
          loadingComments={loadingComments}
          isPressing={isPressing}
          onNavigateProfile={(authorId) => navigate(`/profile/${authorId}`)}
          onPostMenuOpen={setPostMenuOpen}
          onSharePost={setSharePostOpen}
          onSavePost={handleSavePost}
          onLikeStart={handleShakaPointerDown}
          onLikeEnd={handleShakaPointerUp}
          onLikeLeave={handleShakaPointerLeave}
          onCommentChange={(postId, val) => setCommentInputs(prev => ({ ...prev, [postId]: val }))}
          onCommentSubmit={handleCommentSubmit}
          onLoadAllComments={loadAllComments}
          onHideAllComments={hideAllComments}
          onJoinLive={handleJoinLive}
          onIWasThere={handleIWasThere}
          onViewCollaborators={handleViewCollaborators}
          onFollowFromFeed={handleFollowFromFeed}
        />
      </div>

      {/* Post Menu */}
      <PostMenu
        post={postMenuOpen}
        open={postMenuOpen !== null}
        onClose={() => setPostMenuOpen(null)}
        onPostUpdated={handlePostUpdated}
        onPostDeleted={handlePostDeleted}
        onIWasThere={() => postMenuOpen && handleIWasThere(postMenuOpen.id)}
        isFollowingAuthor={postMenuOpen ? followingUsers.has(postMenuOpen.author_id) : false}
        onFollow={handleFollowFromFeed}
        onUnfollow={handleUnfollowFromMenu}
      />

      {/* Share Modal */}
      <SharePostModal
        post={sharePostOpen}
        open={sharePostOpen !== null}
        onClose={() => setSharePostOpen(null)}
        isLight={isLight}
      />
      
      {/* Reaction Picker Overlay */}
      {showReactionPicker && (
        <div className="fixed inset-0 z-[200]">
          <div 
            className="absolute inset-0 bg-black/30"
            onClick={() => setShowReactionPicker(false)}
          />
          <div 
            className="absolute bg-zinc-900/95 backdrop-blur-sm border border-zinc-600 rounded-full px-2 py-2 flex items-center shadow-2xl"
            style={{ 
              left: '50%',
              top: '50%',
              transform: 'translate(-50%, -50%)'
            }}
            onClick={(e) => e.stopPropagation()}
          >
            {VALID_REACTIONS.map((emoji) => (
              <button
                key={emoji}
                onClick={() => handleReaction(showReactionPicker, emoji)}
                className="w-10 h-10 flex items-center justify-center hover:scale-110 transition-all duration-150 hover:bg-zinc-700/50 rounded-full active:scale-95 touch-manipulation"
                style={{ fontSize: '22px' }}
              >
                {emoji}
              </button>
            ))}
            <button 
              onClick={() => setShowReactionPicker(false)}
              className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-white border-l border-zinc-600 ml-1 hover:bg-zinc-700/50 rounded-full touch-manipulation"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default SinglePost;

import React, { useState, useEffect } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { Waves, Clock, Compass, Users, Star, MessageSquare, ChevronDown, ChevronUp, Loader2, ArrowUp, ArrowDown, Droplets, Calendar, Lock, Crown } from 'lucide-react';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from './ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import { Textarea } from './ui/textarea';
import { toast } from 'sonner';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import logger from '../utils/logger';
import { getThemeTokens } from '../utils/themeTokens';


// Get subscription tier for forecast access
const getForecastDays = (subscriptionTier) => {
  if (!subscriptionTier || subscriptionTier === 'free') return 3;
  if (['basic', 'paid'].includes(subscriptionTier)) return 7;
  if (['premium', 'pro', 'gold'].includes(subscriptionTier)) return 10;
  return 3; // Default fallback for unknown tiers
};

// Check if user has premium forecast access
const hasPremiumForecast = (subscriptionTier) => {
  return subscriptionTier === 'premium' || subscriptionTier === 'pro' || subscriptionTier === 'gold';
};

// Conditions badge colors
const conditionColors = {
  "Flat": "bg-gray-500",
  "Ankle High": "bg-blue-400",
  "Knee High": "bg-blue-500",
  "Waist High": "bg-emerald-400",
  "Chest High": "bg-emerald-500",
  "Head High": "bg-yellow-400",
  "Overhead": "bg-orange-400",
  "Double Overhead": "bg-orange-500",
  "Triple Overhead+": "bg-red-500"
};

export const SpotConditions = ({ spotId, spotName, compact = false }) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const t = getThemeTokens(theme);
  // Theme tokens from shared utility
  const containerBg = t.pageBg;
  const containerBorder = t.border;
  const tPrimary = t.textPrimary;
  const tSecondary = t.textSecondary;
  const tMuted = t.textMuted;
  const cellBg = t.cellBg;
  const cellBgFaded = t.cellBgFaded;
  const hoverBg = t.hoverBg;
  const isLight = t.isLight;
  const [conditions, setConditions] = useState(null);
  const [tideData, setTideData] = useState(null);
  const [reports, setReports] = useState(null);
  const [forecast, setForecast] = useState([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState(false);
  const [forecastExpanded, setForecastExpanded] = useState(false);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportLoading, setReportLoading] = useState(false);
  const [reportData, setReportData] = useState({
    wave_height: '',
    conditions: '',
    wind_direction: '',
    crowd_level: '',
    rating: 0,
    notes: ''
  });
  
  // Get forecast days based on user's subscription
  const forecastDaysAllowed = getForecastDays(user?.subscription_tier);
  const isPremiumUser = hasPremiumForecast(user?.subscription_tier);

  useEffect(() => {
    if (spotId) {
      fetchConditions();
      fetchTideData();
      fetchTodaysReports();
      fetchForecast();
    }
  }, [spotId]);

  const fetchConditions = async () => {
    try {
      const response = await apiClient.get(`/conditions/${spotId}`);
      setConditions(response.data);
    } catch (error) {
      logger.error('Error fetching conditions:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchTideData = async () => {
    try {
      const response = await apiClient.get(`/tides/${spotId}`);
      if (!response.data.error) {
        setTideData(response.data);
      }
    } catch (error) {
      logger.error('Error fetching tide data:', error);
    }
  };

  const fetchTodaysReports = async () => {
    try {
      const response = await apiClient.get(`/surf-reports/today/${spotId}`);
      setReports(response.data);
    } catch (error) {
      logger.error('Error fetching reports:', error);
    }
  };

  const fetchForecast = async () => {
    try {
      const response = await apiClient.get(`/conditions/forecast/${spotId}`);
      if (response.data?.forecast) {
        setForecast(response.data.forecast);
      }
    } catch (error) {
      logger.error('Error fetching forecast:', error);
    }
  };

  const submitReport = async () => {
    if (!user?.id) {
      toast.error('Please login to submit a report');
      return;
    }

    setReportLoading(true);
    try {
      await apiClient.post(`/surf-reports`, {
        spot_id: spotId,
        ...reportData
      });
      toast.success('Report submitted! Thanks for sharing 🤙');
      setShowReportModal(false);
      setReportData({ wave_height: '', conditions: '', wind_direction: '', crowd_level: '', rating: 0, notes: '' });
      fetchTodaysReports();
    } catch (error) {
      toast.error('Failed to submit report');
    } finally {
      setReportLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-4">
        <Loader2 className="w-5 h-5 animate-spin text-yellow-400" />
      </div>
    );
  }

  // Compact view for cards
  if (compact) {
    const waveHeight = conditions?.current?.wave_height_ft || 0;
    const label = conditions?.current ? getConditionsLabel(waveHeight) : "No Data";
    
    return (
      <div className="flex items-center gap-2">
        <Waves className="w-4 h-4 text-blue-400" />
        <span className={`text-sm ${tPrimary} font-medium`}>
          {waveHeight > 0 ? `${waveHeight}ft` : label}
        </span>
        <Badge className={`text-[10px] ${conditionColors[label] || 'bg-gray-500'}`}>
          {label}
        </Badge>
      </div>
    );
  }

  // Full view
  const current = conditions?.current;
  const waveLabel = current ? getConditionsLabel(current.wave_height_ft) : "No Data";

  return (
    <div className={`${containerBg} rounded-xl border ${containerBorder} overflow-hidden`} data-testid="spot-conditions">
      {/* Header with current conditions */}
      <div className="p-4">
        <div className="flex items-center justify-between mb-3">
          <h3 className={`font-bold ${tPrimary} flex items-center gap-2`}>
            <Waves className="w-5 h-5 text-blue-400" />
            Current Conditions
          </h3>
          <Badge className={`${conditionColors[waveLabel] || 'bg-gray-500'}`}>
            {waveLabel}
          </Badge>
        </div>

        {current ? (
          <div className="grid grid-cols-2 gap-4">
            {/* Wave Height */}
            <div className={`${cellBg} rounded-lg p-3 text-center`}>
              <p className={`text-3xl font-bold ${tPrimary}`}>{current.wave_height_ft}<span className="text-lg">ft</span></p>
              <p className={`text-xs ${tSecondary}`}>Wave Height</p>
            </div>
            
            {/* Swell */}
            <div className={`${cellBg} rounded-lg p-3 text-center`}>
              <p className={`text-3xl font-bold ${tPrimary}`}>{current.swell_height_ft || 0}<span className="text-lg">ft</span></p>
              <p className={`text-xs ${tSecondary}`}>Swell</p>
            </div>

            {/* Direction */}
            <div className="flex items-center gap-3 col-span-2">
              <div className="flex items-center gap-2">
                <Compass className="w-4 h-4 text-yellow-400" />
                <span className={`text-sm ${tSecondary}`}>
                  {current.wave_direction ? `${current.wave_direction}°` : 'N/A'}
                </span>
              </div>
              <div className="flex items-center gap-2">
                <Clock className="w-4 h-4 text-yellow-400" />
                <span className={`text-sm ${tSecondary}`}>
                  {current.wave_period ? `${current.wave_period}s period` : 'N/A'}
                </span>
              </div>
            </div>
          </div>
        ) : (
          <p className={`${tSecondary} text-sm`}>Unable to fetch conditions</p>
        )}

        {/* Source attribution */}
        <p className={`text-[10px] ${tMuted} mt-3`}>
          Data from Open-Meteo Marine API • Updated: {current?.updated_at ? new Date(current.updated_at).toLocaleTimeString() : 'N/A'}
        </p>
      </div>

      {/* Tide Data Section */}
      {tideData && tideData.tides && tideData.tides.length > 0 && (
        <div className={`border-t ${containerBorder} p-4`}>
          <div className="flex items-center gap-2 mb-3">
            <Droplets className="w-5 h-5 text-cyan-400" />
            <h4 className={`font-bold ${tPrimary} text-sm`}>Today's Tides</h4>
            {tideData.current_status && (
              <Badge className={`text-[10px] ${
                tideData.current_status === 'Rising' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-orange-500/20 text-orange-400'
              }`}>
                {tideData.current_status === 'Rising' ? (
                  <><ArrowUp className="w-3 h-3 mr-1" /> Rising</>
                ) : (
                  <><ArrowDown className="w-3 h-3 mr-1" /> Falling</>
                )}
              </Badge>
            )}
          </div>
          
          <div className="grid grid-cols-2 gap-2">
            {tideData.tides.slice(0, 4).map((tide, index) => {
              const tideTime = new Date(tide.time);
              const isHigh = tide.type === 'High';
              const isPast = tideTime < new Date();
              
              return (
                <div 
                  key={index} 
                  className={`p-2 rounded-lg ${isPast ? cellBgFaded : cellBg}`}
                >
                  <div className="flex items-center gap-2 mb-1">
                    {isHigh ? (
                      <ArrowUp className="w-4 h-4 text-cyan-400" />
                    ) : (
                      <ArrowDown className="w-4 h-4 text-blue-400" />
                    )}
                    <span className={`text-xs font-medium ${isHigh ? 'text-cyan-400' : 'text-blue-400'}`}>
                      {tide.type} Tide
                    </span>
                  </div>
                  <div className="flex items-baseline gap-2">
                    <span className={`text-lg font-bold ${tPrimary}`}>
                      {tideTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                    <span className={`text-xs ${tSecondary}`}>
                      {parseFloat(tide.height).toFixed(1)}ft
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
          
          <p className={`text-[10px] ${tMuted} mt-2`}>
            Data from NOAA Tides & Currents
          </p>
        </div>
      )}

      {/* Forecast Section - Tiered Access */}
      {forecast.length > 0 && (
        <div className={`border-t ${containerBorder}`}>
          <button
            onClick={() => setForecastExpanded(!forecastExpanded)}
            className={`w-full flex items-center justify-between p-4 ${hoverBg} transition-colors`}
          >
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4 text-purple-400" />
              <span className={`text-sm font-medium ${tPrimary}`}>Surf Forecast</span>
              <Badge className={`text-[10px] ${isPremiumUser ? 'bg-purple-500/20 text-purple-400' : isLight ? 'bg-gray-200 text-gray-500' : 'bg-zinc-700 text-gray-400'}`}>
                {forecastDaysAllowed} Day{forecastDaysAllowed > 1 ? 's' : ''}
              </Badge>
            </div>
            {forecastExpanded ? <ChevronUp className={`w-4 h-4 ${tSecondary}`} /> : <ChevronDown className={`w-4 h-4 ${tSecondary}`} />}
          </button>
          
          {forecastExpanded && (
            <div className="px-4 pb-4 space-y-3">
              {/* Forecast Days Grid */}
              <div className="space-y-2">
                {forecast.slice(0, forecastDaysAllowed).map((day, index) => {
                  const dateObj = new Date(day.date);
                  const dayName = index === 0 ? 'Today' : index === 1 ? 'Tomorrow' : dateObj.toLocaleDateString('en-US', { weekday: 'short' });
                  const dateStr = dateObj.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
                  
                  return (
                    <div key={day.date} className={`flex items-center justify-between p-3 ${cellBg} rounded-lg`}>
                      <div className="flex items-center gap-3">
                        <div className="text-center w-14">
                          <p className={`${tPrimary} font-medium text-sm`}>{dayName}</p>
                          <p className={`${tMuted} text-[10px]`}>{dateStr}</p>
                        </div>
                        <div className="flex items-center gap-2">
                          <Waves className="w-4 h-4 text-blue-400" />
                          <span className={`${tPrimary} font-bold`}>{day.wave_height_min}-{day.wave_height_max}ft</span>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge className={`text-[10px] ${conditionColors[day.label] || 'bg-gray-500'}`}>
                          {day.label}
                        </Badge>
                        {day.swell_period && (
                          <span className={`${tSecondary} text-xs`}>{day.swell_period}s</span>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
              
              {/* Premium Upsell - Show if user doesn't have premium */}
              {!isPremiumUser && forecast.length > forecastDaysAllowed && (
                <div className="p-3 bg-gradient-to-r from-purple-500/10 to-pink-500/10 border border-purple-500/30 rounded-lg">
                  <div className="flex items-center gap-2 mb-2">
                    <Lock className="w-4 h-4 text-purple-400" />
                    <span className={`${tPrimary} font-medium text-sm`}>Unlock 10-Day Forecast</span>
                  </div>
                  <p className={`${tSecondary} text-xs mb-2`}>
                    Premium members get extended 10-day forecasts and priority buoy data.
                  </p>
                  <div className="flex items-center gap-2">
                    <div className="flex -space-x-1">
                      {forecast.slice(forecastDaysAllowed, forecastDaysAllowed + 3).map((day, i) => (
                        <div key={i} className="w-6 h-6 rounded-full bg-zinc-700/80 backdrop-blur flex items-center justify-center border border-purple-500/30">
                          <Lock className="w-3 h-3 text-purple-400" />
                        </div>
                      ))}
                    </div>
                    <span className="text-purple-400 text-xs">+{Math.min(forecast.length - forecastDaysAllowed, 7)} more days locked</span>
                  </div>
                  <Button
                    size="sm"
                    className="w-full mt-2 bg-gradient-to-r from-purple-500 to-pink-500 text-white text-xs"
                    onClick={() => window.location.href = '/settings?tab=billing'}
                    data-testid="upgrade-forecast-btn"
                  >
                    <Crown className="w-3 h-3 mr-1" />
                    Upgrade to Premium
                  </Button>
                </div>
              )}
              
              <p className={`text-[10px] ${tMuted}`}>
                Forecast from Open-Meteo Marine API
              </p>
            </div>
          )}
        </div>
      )}

      {/* Community Reports Section */}
      <div className={`border-t ${containerBorder}`}>
        <button
          onClick={() => setExpanded(!expanded)}
          className={`w-full flex items-center justify-between p-4 ${hoverBg} transition-colors`}
        >
          <div className="flex items-center gap-2">
            <Users className="w-4 h-4 text-emerald-400" />
            <span className={`text-sm font-medium ${tPrimary}`}>Community Reports</span>
            {reports?.report_count > 0 && (
              <Badge variant="outline" className="text-emerald-400 border-emerald-400/30">
                {reports.report_count} today
              </Badge>
            )}
          </div>
          {expanded ? <ChevronUp className={`w-4 h-4 ${tSecondary}`} /> : <ChevronDown className={`w-4 h-4 ${tSecondary}`} />}
        </button>

        {expanded && (
          <div className="px-4 pb-4 space-y-3">
            {/* Consensus */}
            {reports?.consensus_conditions && (
              <div className="flex items-center gap-2 text-sm">
                <span className={tSecondary}>Consensus:</span>
                <Badge className="bg-emerald-500/20 text-emerald-400">{reports.consensus_conditions}</Badge>
                {reports.consensus_crowd && (
                  <Badge className="bg-blue-500/20 text-blue-400">{reports.consensus_crowd}</Badge>
                )}
                {reports.average_rating && (
                  <div className="flex items-center gap-1 text-yellow-400">
                    <Star className="w-3 h-3 fill-current" />
                    {reports.average_rating}
                  </div>
                )}
              </div>
            )}

            {/* Recent Reports */}
            {reports?.reports?.length > 0 ? (
              <div className="space-y-2 max-h-48 overflow-y-auto">
                {reports.reports.slice(0, 5).map((report) => (
                  <div key={report.id} className={`${cellBg} rounded-lg p-3`}>
                    <div className="flex items-center gap-2 mb-2">
                      <div className={`w-6 h-6 rounded-full ${isLight ? 'bg-gray-200' : 'bg-zinc-700'} flex items-center justify-center`}>
                        {report.user_avatar ? (
                          <img src={report.user_avatar} alt="" className="w-full h-full rounded-full object-cover" />
                        ) : (
                          <span className={`text-[10px] ${tSecondary}`}>{report.user_name?.charAt(0)}</span>
                        )}
                      </div>
                      <span className={`text-xs ${tPrimary}`}>{report.user_name}</span>
                      <span className={`text-[10px] ${tMuted} ml-auto`}>
                        {new Date(report.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                    <div className="flex flex-wrap gap-1">
                      {report.wave_height && <Badge className="bg-blue-500/20 text-blue-300 text-[10px]">{report.wave_height}</Badge>}
                      {report.conditions && <Badge className="bg-emerald-500/20 text-emerald-300 text-[10px]">{report.conditions}</Badge>}
                      {report.crowd_level && <Badge className="bg-purple-500/20 text-purple-300 text-[10px]">{report.crowd_level}</Badge>}
                    </div>
                    {report.notes && <p className={`text-xs ${tSecondary} mt-1`}>{report.notes}</p>}
                  </div>
                ))}
              </div>
            ) : (
              <p className={`text-sm ${tSecondary} text-center py-4`}>No reports yet today. Be the first!</p>
            )}

            {/* Submit Report Button */}
            <Button
              onClick={() => setShowReportModal(true)}
              className="w-full bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white"
              data-testid="submit-report-btn"
            >
              <MessageSquare className="w-4 h-4 mr-2" />
              Share Your Report
            </Button>
          </div>
        )}
      </div>

      {/* Submit Report Modal */}
      <Dialog open={showReportModal} onOpenChange={setShowReportModal}>
        <DialogContent className="bg-zinc-900 border-zinc-800 text-white max-w-md">
          <DialogHeader>
            <DialogTitle className="text-xl font-bold flex items-center gap-2">
              <MessageSquare className="w-5 h-5 text-emerald-400" />
              Submit Surf Report
            </DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4 pt-4">
            <p className="text-sm text-gray-400">Share current conditions at {spotName}</p>

            {/* Wave Height */}
            <div>
              <label className="text-sm text-gray-400 mb-2 block">Wave Height</label>
              <Select value={reportData.wave_height} onValueChange={(v) => setReportData(prev => ({ ...prev, wave_height: v }))}>
                <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white">
                  <SelectValue placeholder="Select wave height" />
                </SelectTrigger>
                <SelectContent className="bg-zinc-800 border-zinc-700">
                  <SelectItem value="Flat" className="text-white">Flat</SelectItem>
                  <SelectItem value="1-2ft" className="text-white">1-2ft (Ankle-Knee)</SelectItem>
                  <SelectItem value="2-3ft" className="text-white">2-3ft (Knee-Waist)</SelectItem>
                  <SelectItem value="3-4ft" className="text-white">3-4ft (Waist-Chest)</SelectItem>
                  <SelectItem value="4-5ft" className="text-white">4-5ft (Chest-Head)</SelectItem>
                  <SelectItem value="5-6ft" className="text-white">5-6ft (Head High)</SelectItem>
                  <SelectItem value="6-8ft" className="text-white">6-8ft (Overhead)</SelectItem>
                  <SelectItem value="8ft+" className="text-white">8ft+ (Double OH+)</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Conditions */}
            <div>
              <label className="text-sm text-gray-400 mb-2 block">Conditions</label>
              <Select value={reportData.conditions} onValueChange={(v) => setReportData(prev => ({ ...prev, conditions: v }))}>
                <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white">
                  <SelectValue placeholder="How's it looking?" />
                </SelectTrigger>
                <SelectContent className="bg-zinc-800 border-zinc-700">
                  <SelectItem value="Glassy" className="text-white">🪞 Glassy</SelectItem>
                  <SelectItem value="Clean" className="text-white">✨ Clean</SelectItem>
                  <SelectItem value="Fair" className="text-white">👍 Fair</SelectItem>
                  <SelectItem value="Choppy" className="text-white">🌊 Choppy</SelectItem>
                  <SelectItem value="Messy" className="text-white">💨 Messy</SelectItem>
                  <SelectItem value="Blown Out" className="text-white">🌀 Blown Out</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Wind Direction */}
            <div>
              <label className="text-sm text-gray-400 mb-2 block">Wind</label>
              <Select value={reportData.wind_direction} onValueChange={(v) => setReportData(prev => ({ ...prev, wind_direction: v }))}>
                <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white">
                  <SelectValue placeholder="Wind direction" />
                </SelectTrigger>
                <SelectContent className="bg-zinc-800 border-zinc-700">
                  <SelectItem value="Offshore" className="text-white">🏄 Offshore (Good)</SelectItem>
                  <SelectItem value="Light Onshore" className="text-white">🌬️ Light Onshore</SelectItem>
                  <SelectItem value="Onshore" className="text-white">💨 Onshore</SelectItem>
                  <SelectItem value="Cross-shore" className="text-white">↔️ Cross-shore</SelectItem>
                  <SelectItem value="No Wind" className="text-white">🪶 No Wind</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Crowd Level */}
            <div>
              <label className="text-sm text-gray-400 mb-2 block">Crowd</label>
              <Select value={reportData.crowd_level} onValueChange={(v) => setReportData(prev => ({ ...prev, crowd_level: v }))}>
                <SelectTrigger className="bg-zinc-800 border-zinc-700 text-white">
                  <SelectValue placeholder="How crowded?" />
                </SelectTrigger>
                <SelectContent className="bg-zinc-800 border-zinc-700">
                  <SelectItem value="Empty" className="text-white">🏝️ Empty</SelectItem>
                  <SelectItem value="Light" className="text-white">👤 Light</SelectItem>
                  <SelectItem value="Moderate" className="text-white">👥 Moderate</SelectItem>
                  <SelectItem value="Crowded" className="text-white">👨‍👩‍👧‍👦 Crowded</SelectItem>
                  <SelectItem value="Packed" className="text-white">🚶‍♂️🚶‍♂️🚶 Packed</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Rating */}
            <div>
              <label className="text-sm text-gray-400 mb-2 block">Overall Rating</label>
              <div className="flex gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    onClick={() => setReportData(prev => ({ ...prev, rating: star }))}
                    className={`p-2 rounded-lg transition-colors ${
                      reportData.rating >= star ? 'text-yellow-400' : 'text-gray-600'
                    }`}
                  >
                    <Star className={`w-6 h-6 ${reportData.rating >= star ? 'fill-current' : ''}`} />
                  </button>
                ))}
              </div>
            </div>

            {/* Notes */}
            <div>
              <label className="text-sm text-gray-400 mb-2 block">Notes (optional)</label>
              <Textarea
                value={reportData.notes}
                onChange={(e) => setReportData(prev => ({ ...prev, notes: e.target.value }))}
                placeholder="Any other details..."
                className="bg-zinc-800 border-zinc-700 text-white min-h-[60px]"
              />
            </div>

            <Button
              onClick={submitReport}
              disabled={reportLoading || (!reportData.wave_height && !reportData.conditions)}
              className="w-full h-12 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white font-bold"
            >
              {reportLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Submit Report'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

// Helper function
function getConditionsLabel(waveHeightFt) {
  if (waveHeightFt < 1) return "Flat";
  if (waveHeightFt < 2) return "Ankle High";
  if (waveHeightFt < 3) return "Knee High";
  if (waveHeightFt < 4) return "Waist High";
  if (waveHeightFt < 5) return "Chest High";
  if (waveHeightFt < 6) return "Head High";
  if (waveHeightFt < 8) return "Overhead";
  if (waveHeightFt < 10) return "Double Overhead";
  return "Triple Overhead+";
}

export default SpotConditions;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import {
  MapPin,
  Search,
  Check,
  Loader2,
  Navigation,
  X,
  Globe,
  Map,
  AlertTriangle
} from 'lucide-react';
import { Input } from './ui/input';
import { Badge } from './ui/badge';
import logger from '../utils/logger';
import { ROLES } from '../constants/roles';


/**
 * SpotSelector - In-Drawer Searchable Spot Selection
 * 
 * Used in Active Duty console for On-Demand and Live spot selection
 * 
 * Features:
 * - GPS-based nearby spots (primary — auto-attempts on mount)
 * - Hierarchical browse fallback: Country → State/Province → Spot
 *   (same pattern as ScheduledBookingDrawer & Feed check-in)
 * - Radius filtering based on photographer tier:
 *   - Standard: 10-20 miles
 *   - Verified Pro: 30-50 miles
 * - Searchable spot list
 */

export const SpotSelector = ({ 
  selectedSpot, 
  onSelectSpot, 
  photographerTier = 'standard',
  disabled = false,
  compact = false
}) => {
  const { _user } = useAuth();
  const [spots, setSpots] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [userLocation, setUserLocation] = useState(null);
  const [locationLoading, setLocationLoading] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);

  // GPS fallback: hierarchical browse state
  const [gpsAvailable, setGpsAvailable] = useState(null); // null = not yet attempted
  const [browseMode, setBrowseMode] = useState(false);
  const [locationData, setLocationData] = useState(null); // hierarchy: { countries: [...] }
  const [locationDataLoading, setLocationDataLoading] = useState(false);
  const [selectedCountry, setSelectedCountry] = useState('');
  const [selectedState, setSelectedState] = useState('');

  // Radius limits based on photographer tier
  const radiusConfig = useMemo(() => {
    if (photographerTier === 'pro' || photographerTier === 'verified' || photographerTier === ROLES.APPROVED_PRO) {
      return { min: 30, max: 50, label: 'Pro Range (30-50mi)' };
    }
    return { min: 10, max: 20, label: 'Standard Range (10-20mi)' };
  }, [photographerTier]);

  // Get user's current location
  useEffect(() => {
    getUserLocation();
  }, []);

  // Fetch spots when location is available (GPS mode)
  useEffect(() => {
    if (userLocation) {
      fetchNearbySpots();
    }
  }, [userLocation, radiusConfig]);

  const getUserLocation = () => {
    setLocationLoading(true);
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude
          });
          setGpsAvailable(true);
          setLocationLoading(false);
        },
        (error) => {
          logger.error('Geolocation error:', error);
          setGpsAvailable(false);
          setLocationLoading(false);
          // Auto-open browse mode when GPS fails
          handleOpenBrowseMode();
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    } else {
      setGpsAvailable(false);
      setLocationLoading(false);
      // Auto-open browse mode when GPS not supported
      handleOpenBrowseMode();
    }
  };

  const fetchNearbySpots = async () => {
    if (!userLocation) return;
    
    setLoading(true);
    try {
      const response = await apiClient.get(`/surf-spots/nearby`, {
        params: {
          latitude: userLocation.latitude,
          longitude: userLocation.longitude,
          radius_miles: radiusConfig.max
        }
      });
      
      // Map backend response to frontend format and filter by radius
      const filteredSpots = (response.data || [])
        .filter(spot => {
          const distance = spot.distance_miles || spot.distance || calculateDistance(
            userLocation.latitude,
            userLocation.longitude,
            spot.latitude,
            spot.longitude
          );
          return distance <= radiusConfig.max;
        })
        .map(spot => ({
          ...spot,
          distance: spot.distance_miles || spot.distance
        }))
        .sort((a, b) => (a.distance || 0) - (b.distance || 0));
      
      setSpots(filteredSpots);
    } catch (error) {
      logger.error('Failed to fetch spots:', error);
      setSpots([]);
    } finally {
      setLoading(false);
    }
  };

  // ============ BROWSE MODE (GPS Fallback) ============

  // Open browse mode & fetch the location hierarchy
  const handleOpenBrowseMode = useCallback(async () => {
    setBrowseMode(true);
    if (locationData) return; // Already fetched

    setLocationDataLoading(true);
    try {
      const response = await apiClient.get('/surf-spots/locations');
      setLocationData(response.data);
    } catch (error) {
      logger.error('Failed to fetch location hierarchy:', error);
      setLocationData(null);
    } finally {
      setLocationDataLoading(false);
    }
  }, [locationData]);

  // Fetch spots filtered by country + optional state
  const fetchSpotsByLocation = async (country, state) => {
    setLoading(true);
    try {
      const params = {};
      if (country) params.country = country;
      if (state) params.state_province = state;

      const response = await apiClient.get('/surf-spots', { params });
      const fetchedSpots = (response.data || [])
        .map(spot => ({
          ...spot,
          distance: null // No distance info in browse mode
        }))
        .sort((a, b) => (a.name || '').localeCompare(b.name || ''));

      setSpots(fetchedSpots);
    } catch (error) {
      logger.error('Failed to fetch spots by location:', error);
      setSpots([]);
    } finally {
      setLoading(false);
    }
  };

  const handleCountryChange = (country) => {
    setSelectedCountry(country);
    setSelectedState('');
    if (country) {
      fetchSpotsByLocation(country, '');
    } else {
      setSpots([]);
    }
  };

  const handleStateChange = (state) => {
    setSelectedState(state);
    if (selectedCountry) {
      fetchSpotsByLocation(selectedCountry, state);
    }
  };

  // Back to GPS mode (retry)
  const handleRetryGps = () => {
    setBrowseMode(false);
    setSelectedCountry('');
    setSelectedState('');
    setSpots([]);
    getUserLocation();
  };

  // Simple distance calculation (Haversine formula approximation)
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 3959; // Earth's radius in miles
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = 
      Math.sin(dLat/2) * Math.sin(dLat/2) +
      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
      Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
  };

  // Filter spots by search query
  const filteredSpots = useMemo(() => {
    if (!searchQuery.trim()) return spots;
    const query = searchQuery.toLowerCase();
    return spots.filter(spot => 
      spot.name?.toLowerCase().includes(query) ||
      spot.location?.toLowerCase().includes(query) ||
      spot.region?.toLowerCase().includes(query)
    );
  }, [spots, searchQuery]);

  const handleSelectSpot = (spot) => {
    onSelectSpot({
      id: spot.id,
      name: spot.name,
      latitude: spot.latitude,
      longitude: spot.longitude,
      distance: spot.distance
    });
    setIsExpanded(false);
    setSearchQuery('');
  };

  // Compact view - just shows selected spot with edit option
  if (compact && !isExpanded) {
    return (
      <button
        onClick={() => !disabled && setIsExpanded(true)}
        disabled={disabled}
        className={`w-full flex items-center gap-2 p-3 rounded-xl transition-colors ${
          selectedSpot 
            ? 'bg-green-500/10 border border-green-500/30 hover:bg-green-500/20'
            : 'bg-zinc-800 border border-zinc-700 hover:bg-zinc-700'
        } ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
      >
        <MapPin className={`w-4 h-4 ${selectedSpot ? 'text-green-400' : 'text-gray-400'}`} />
        <span className={`flex-1 text-left text-sm ${selectedSpot ? 'text-green-300' : 'text-gray-400'}`}>
          {selectedSpot?.name || 'Select your spot...'}
        </span>
        {selectedSpot?.distance && (
          <Badge className="bg-green-500/20 text-green-400 text-xs">
            {selectedSpot.distance.toFixed(1)}mi
          </Badge>
        )}
      </button>
    );
  }

  // Helper: get available states for selected country
  const selectedCountryData = locationData?.countries?.find(c => c.name === selectedCountry);
  const availableStates = selectedCountryData?.states || [];

  return (
    <div className="space-y-3">
      {/* Header with mode indicator */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <MapPin className="w-4 h-4 text-cyan-400" />
          <span className="text-foreground text-sm font-medium">Select Spot</span>
        </div>
        {!browseMode && gpsAvailable && (
          <Badge className="bg-cyan-500/20 text-cyan-400 text-xs">
            {radiusConfig.label}
          </Badge>
        )}
        {browseMode && (
          <Badge className="bg-amber-500/20 text-amber-400 text-xs">
            <Globe className="w-3 h-3 mr-1" />
            Browse Mode
          </Badge>
        )}
      </div>

      {/* GPS Status / Mode Switcher */}
      {gpsAvailable === false && !browseMode && (
        <div className="flex items-center gap-2 p-2.5 bg-amber-500/10 border border-amber-500/30 rounded-lg">
          <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0" />
          <p className="text-amber-300 text-xs flex-1">
            GPS unavailable on this device. Browse spots by location instead.
          </p>
        </div>
      )}

      {/* Mode Toggle Buttons */}
      {gpsAvailable !== null && (
        <div className="flex gap-2">
          {/* GPS Mode Button */}
          <button
            onClick={handleRetryGps}
            disabled={locationLoading}
            className={`flex-1 flex items-center justify-center gap-1.5 p-2 rounded-lg text-xs font-medium transition-all ${
              !browseMode
                ? 'bg-green-500/20 border border-green-500/50 text-green-400'
                : 'bg-card border border-border text-muted-foreground hover:text-foreground hover:border-muted-foreground'
            }`}
          >
            {locationLoading ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <Navigation className="w-3.5 h-3.5" />
            )}
            {locationLoading ? 'Getting GPS...' : gpsAvailable ? 'Nearby' : 'Retry GPS'}
          </button>

          {/* Browse Mode Button */}
          <button
            onClick={handleOpenBrowseMode}
            disabled={locationDataLoading}
            className={`flex-1 flex items-center justify-center gap-1.5 p-2 rounded-lg text-xs font-medium transition-all ${
              browseMode
                ? 'bg-cyan-500/20 border border-cyan-500/50 text-cyan-400'
                : 'bg-card border border-border text-muted-foreground hover:text-foreground hover:border-muted-foreground'
            }`}
          >
            {locationDataLoading ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <Globe className="w-3.5 h-3.5" />
            )}
            Browse by Location
          </button>
        </div>
      )}

      {/* ============ BROWSE MODE: Country → State Drill-Down ============ */}
      {browseMode && (
        <div className="p-3 rounded-xl border border-border bg-card/50 space-y-2.5">
          <div className="flex items-center gap-2">
            <MapIcon className="w-4 h-4 text-cyan-400" />
            <span className="text-foreground text-sm font-medium">Find Your Spot</span>
          </div>

          {locationDataLoading ? (
            <div className="flex items-center justify-center py-6">
              <Loader2 className="w-5 h-5 animate-spin text-cyan-400" />
              <span className="ml-2 text-muted-foreground text-xs">Loading locations...</span>
            </div>
          ) : locationData?.countries?.length > 0 ? (
            <div className="space-y-2">
              {/* Country Picker */}
              <div>
                <label className="text-[10px] text-muted-foreground block mb-1">Country</label>
                <select
                  value={selectedCountry}
                  onChange={(e) => handleCountryChange(e.target.value)}
                  className="w-full h-9 px-3 rounded-md text-sm bg-background border border-border text-foreground focus:outline-none focus:ring-2 focus:ring-cyan-500/50 appearance-none"
                >
                  <option value="">Select a country...</option>
                  {locationData.countries.map(country => (
                    <option key={country.name} value={country.name}>
                      {country.name} ({country.spot_count} spots)
                    </option>
                  ))}
                </select>
              </div>

              {/* State/Province Picker — appears when country has states */}
              {selectedCountry && availableStates.length > 0 && (
                <div>
                  <label className="text-[10px] text-muted-foreground block mb-1">State / Province</label>
                  <select
                    value={selectedState}
                    onChange={(e) => handleStateChange(e.target.value)}
                    className="w-full h-9 px-3 rounded-md text-sm bg-background border border-border text-foreground focus:outline-none focus:ring-2 focus:ring-cyan-500/50 appearance-none"
                  >
                    <option value="">All states in {selectedCountry}</option>
                    {availableStates.map(state => (
                      <option key={state.name} value={state.name}>
                        {state.name} ({state.spot_count} spots)
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Selected location breadcrumb */}
              {selectedCountry && (
                <div className="flex items-center gap-1 text-[10px] text-muted-foreground">
                  <Check className="w-3 h-3 text-cyan-400" />
                  <span>
                    Showing spots in {selectedState || selectedCountry}
                    {spots.length > 0 && ` (${spots.length} found)`}
                  </span>
                </div>
              )}
            </div>
          ) : (
            <div className="text-muted-foreground text-xs text-center py-3">
              No locations available. Try retrying GPS.
            </div>
          )}
        </div>
      )}

      {/* ============ SEARCH INPUT (both modes) ============ */}
      {(userLocation || (browseMode && selectedCountry)) && (
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search spots..."
            className="pl-10 bg-card border-border text-foreground placeholder:text-muted-foreground"
            disabled={disabled}
          />
          {searchQuery && (
            <button
              onClick={() => setSearchQuery('')}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      )}

      {/* ============ SPOTS LIST ============ */}
      <div className="max-h-[200px] overflow-y-auto space-y-1 scrollbar-thin scrollbar-thumb-zinc-700">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 text-cyan-400 animate-spin" />
          </div>
        ) : filteredSpots.length > 0 ? (
          filteredSpots.map((spot) => {
            const isSelected = selectedSpot?.id === spot.id;
            return (
              <button
                key={spot.id}
                onClick={() => handleSelectSpot(spot)}
                disabled={disabled}
                className={`w-full flex items-center gap-3 p-3 rounded-lg transition-colors ${
                  isSelected
                    ? 'bg-green-500/20 border border-green-500/50'
                    : 'bg-card/50 hover:bg-muted/50 border border-transparent'
                } ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                  isSelected ? 'bg-green-500/30' : 'bg-cyan-500/20'
                }`}>
                  {isSelected ? (
                    <Check className="w-4 h-4 text-green-400" />
                  ) : (
                    <MapPin className="w-4 h-4 text-cyan-400" />
                  )}
                </div>
                <div className="flex-1 text-left">
                  <p className={`text-sm font-medium ${isSelected ? 'text-green-300' : 'text-foreground'}`}>
                    {spot.name}
                  </p>
                  {(spot.region || spot.location) && (
                    <p className="text-xs text-muted-foreground">{spot.region || spot.location}</p>
                  )}
                </div>
                {spot.distance !== undefined && spot.distance !== null && (
                  <span className={`text-xs ${isSelected ? 'text-green-400' : 'text-muted-foreground'}`}>
                    {spot.distance.toFixed(1)} mi
                  </span>
                )}
              </button>
            );
          })
        ) : (userLocation || (browseMode && selectedCountry)) ? (
          <div className="text-center py-8 text-muted-foreground text-sm">
            {searchQuery ? 'No spots match your search' : 'No spots found in this area'}
          </div>
        ) : !browseMode && !locationLoading ? (
          /* Initial state — GPS hasn't been tried yet or is loading */
          <div className="text-center py-6 space-y-2">
            <Navigation className="w-6 h-6 text-muted-foreground mx-auto opacity-50" />
            <p className="text-muted-foreground text-xs">
              {locationLoading ? 'Getting your location...' : 'Enable GPS or browse by location to see spots'}
            </p>
          </div>
        ) : null}
      </div>

      {/* Close button when expanded from compact mode */}
      {compact && isExpanded && (
        <button
          onClick={() => setIsExpanded(false)}
          className="w-full p-2 text-muted-foreground hover:text-foreground text-sm"
        >
          Cancel
        </button>
      )}
    </div>
  );
};

