                size="sm"
                onClick={() => setTierFilter('competitive')}
                className={tierFilter === 'competitive' ? 'bg-yellow-500 text-black' : 'border-zinc-700'}
              >
                <Trophy className="w-3 h-3 mr-1" /> Competitive
              </Button>
              <Button
                variant={tierFilter === 'pro_elite' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setTierFilter('pro_elite')}
                className={tierFilter === 'pro_elite' ? 'bg-amber-500 text-black' : 'border-zinc-700'}
              >
                <Medal className="w-3 h-3 mr-1" /> Pro
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Eligible Surfers */}
      <Card className={cardBg}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Users className="w-5 h-5 text-pink-400" />
            Surfers to Support ({filteredSurfers.length})
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {filteredSurfers.length > 0 ? (
            filteredSurfers.slice(0, 20).map((surfer) => (
              <div 
                key={surfer.id}
                className="flex items-center gap-3 p-3 bg-zinc-800/50 rounded-lg hover:bg-zinc-800 transition-colors"
              >
                <Avatar 
                  className="w-12 h-12 border-2 border-pink-500/30 cursor-pointer"
                  onClick={() => navigate(`/profile/${surfer.id}`)}
                >
                  <AvatarImage src={getFullUrl(surfer.avatar_url)} />
                  <AvatarFallback className="bg-pink-500/20 text-pink-400">
                    {surfer.full_name?.charAt(0) || 'S'}
                  </AvatarFallback>
                </Avatar>
                <div className="flex-1 min-w-0">
                  <div className={`font-medium ${textPrimary} truncate`}>{surfer.full_name}</div>
                  <div className="flex items-center gap-2 mt-1">
                    {getRoleBadge(surfer.role)}
                    {surfer.home_break && (
                      <span className={`text-xs ${textSecondary}`}>{surfer.home_break}</span>
                    )}
                  </div>
                </div>
                <Button
                  size="sm"
                  onClick={() => {
                    setSelectedSurfer(surfer);
                    setShowContributeModal(true);
                  }}
                  className="bg-pink-500 hover:bg-pink-400 text-white"
                >
                  <Gift className="w-4 h-4 mr-1" />
                  Sponsor
                </Button>
              </div>
            ))
          ) : (
            <p className={`text-center ${textSecondary} py-4`}>
              No surfers found matching your criteria
            </p>
          )}
        </CardContent>
      </Card>

      {/* Recent Contributions */}
      {contributions.list.length > 0 && (
        <Card className={cardBg}>
          <CardHeader>
            <CardTitle className={`${textPrimary} flex items-center gap-2`}>
              <TrendingUp className="w-5 h-5 text-emerald-400" />
              Your Recent Contributions
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {contributions.list.slice(0, 5).map((contrib) => (
              <div 
                key={contrib.id}
                className="flex items-center justify-between p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg"
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-emerald-500/20 flex items-center justify-center">
                    <Heart className="w-5 h-5 text-emerald-400" />
                  </div>
                  <div>
                    <div className={`font-medium ${textPrimary}`}>${contrib.amount.toFixed(2)}</div>
                    <div className={`text-xs ${textSecondary}`}>
                      {new Date(contrib.created_at).toLocaleDateString()}
                    </div>
                  </div>
                </div>
                {contrib.shaka_sent && (
                  <Badge className="bg-yellow-500/20 text-yellow-400 border-0 text-xs">
                    Shaka Received
                  </Badge>
                )}
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      {/* Contribute Modal */}
      <ContributeModal
        isOpen={showContributeModal}
        onClose={() => {
          setShowContributeModal(false);
          setSelectedSurfer(null);
        }}
        surfer={selectedSurfer}
        photographerId={user?.id}
        userCredits={user?.withdrawable_credits || 0}
        onSuccess={() => {
          setShowContributeModal(false);
          setSelectedSurfer(null);
          fetchData();
          toast.success('Stoke Sponsor contribution sent!');
        }}
      />
    </div>
  );
};

// Contribute Modal Component
const ContributeModal = ({ isOpen, onClose, surfer, photographerId, userCredits, onSuccess }) => {
  const [amount, setAmount] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  const presetAmounts = [5, 10, 25, 50, 100];

  const handleSubmit = async () => {
    const numAmount = parseFloat(amount);
    if (!numAmount || numAmount <= 0) {
      toast.error('Please enter a valid amount');
      return;
    }
    if (numAmount > userCredits) {
      toast.error(`Insufficient credits. You have $${userCredits.toFixed(2)} available.`);
      return;
    }

    setLoading(true);
    try {
      await apiClient.post(`/career/stoke-sponsor/contribute?photographer_id=${photographerId}`, {
        surfer_id: surfer.id,
        amount: numAmount,
        message: message || null
      });
      onSuccess();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to send contribution');
    } finally {
      setLoading(false);
    }
  };

  if (!surfer) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-zinc-900 border-zinc-800 text-white max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Heart className="w-5 h-5 text-pink-400" />
            Sponsor {surfer.full_name}
          </DialogTitle>
        </DialogHeader>
        
        <div className="space-y-4">
          {/* Surfer Info */}
          <div className="flex items-center gap-3 p-3 bg-zinc-800 rounded-lg">
            <Avatar className="w-12 h-12">
              <AvatarImage src={getFullUrl(surfer.avatar_url)} />
              <AvatarFallback className="bg-pink-500/20 text-pink-400">
                {surfer.full_name?.charAt(0)}
              </AvatarFallback>
            </Avatar>
            <div>
              <div className="font-medium">{surfer.full_name}</div>
              <div className="text-sm text-gray-400">{surfer.role}</div>
            </div>
          </div>

          {/* Fee Info */}
          <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg text-sm">
            <div className="flex justify-between">
              <span className="text-gray-400">Platform fee:</span>
              <span className="text-emerald-400">{surfer.role === 'Grom' ? '5%' : '10%'}</span>
            </div>
            <div className="text-xs text-gray-500 mt-1">
              Lower fees for supporting young surfers
            </div>
          </div>

          {/* Your Credits */}
          <div className="p-3 bg-zinc-800 rounded-lg">
            <div className="text-sm text-gray-400">Your Available Credits</div>
            <div className="text-xl font-bold text-emerald-400">${userCredits.toFixed(2)}</div>
          </div>

          {/* Preset Amounts */}
          <div className="grid grid-cols-5 gap-2">
            {presetAmounts.map((preset) => (
              <Button
                key={preset}
                variant="outline"
                size="sm"
                onClick={() => setAmount(preset.toString())}
                className={`border-zinc-700 ${amount === preset.toString() ? 'bg-pink-500 text-white border-pink-500' : ''}`}
              >
                ${preset}
              </Button>
            ))}
          </div>

          {/* Custom Amount */}
          <div className="relative">
            <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <Input
              type="number"
              placeholder="Custom amount"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              className="pl-10 bg-zinc-800 border-zinc-700"
            />
          </div>

          {/* Message */}
          <Input
            placeholder="Add a message (optional)"
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            className="bg-zinc-800 border-zinc-700"
          />

          {/* XP Preview */}
          {amount && parseFloat(amount) > 0 && (
            <div className="flex items-center justify-center gap-2 p-2 bg-cyan-500/10 border border-cyan-500/20 rounded-lg">
              <Zap className="w-4 h-4 text-cyan-400" />
              <span className="text-cyan-400 font-medium">
                You'll earn {Math.floor(parseFloat(amount) * 2)} XP!
              </span>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} className="border-zinc-700">
            Cancel
          </Button>
          <Button 
            onClick={handleSubmit} 
            disabled={loading || !amount || parseFloat(amount) <= 0}
            className="bg-pink-500 text-white hover:bg-pink-400"
          >
            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : (
              <>
                <Heart className="w-4 h-4 mr-2" />
                Send ${amount || '0'}
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default StokeSponsorDashboard;

﻿import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTheme } from '../contexts/ThemeContext';
import { 

  Heart, Trophy, Medal, Loader2, 
  Baby, Crown, ChevronRight
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';
import { Badge } from './ui/badge';
import apiClient from '../lib/apiClient';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';



/**
 * Stoke Sponsor Leaderboard - Top photographers supporting surfers
 * Shows rankings, total contributions, and grom support percentages
 */
export const StokeSponsorLeaderboard = ({ compact = false }) => {
  const { theme } = useTheme();
  const navigate = useNavigate();
  
  const [leaderboard, setLeaderboard] = useState([]);
  const [stats, setStats] = useState({ total_contributed: 0, total_to_groms: 0, total_sponsors: 0 });
  const [timeRange, setTimeRange] = useState('all');
  const [loading, setLoading] = useState(true);

  const isLight = theme === 'light';
  const cardBg = isLight ? 'bg-white border-gray-200' : 'bg-card border-border';
  const textPrimary = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  useEffect(() => {
    fetchLeaderboard();
  }, [timeRange]);

  const fetchLeaderboard = async () => {
    setLoading(true);
    try {
      const res = await apiClient.get(`/career/stoke-sponsor/leaderboard?time_range=${timeRange}`);
      setLeaderboard(res.data?.leaderboard || []);
      setStats(res.data?.stats || { total_contributed: 0, total_to_groms: 0, total_sponsors: 0 });
    } catch (error) {
      logger.error('Failed to fetch stoke leaderboard:', error);
    } finally {
      setLoading(false);
    }
  };

  const getRankDisplay = (rank) => {
    if (rank === 1) return <Crown className="w-6 h-6 text-yellow-400" />;
    if (rank === 2) return <Medal className="w-6 h-6 text-gray-300" />;
    if (rank === 3) return <Medal className="w-6 h-6 text-amber-600" />;
    return <span className={`text-lg font-bold ${textSecondary}`}>#{rank}</span>;
  };

  const getRankBg = (rank) => {
    if (rank === 1) return 'bg-gradient-to-r from-yellow-500/20 to-amber-500/20 border-yellow-500/40';
    if (rank === 2) return 'bg-gradient-to-r from-gray-400/10 to-gray-500/10 border-gray-400/30';
    if (rank === 3) return 'bg-gradient-to-r from-amber-600/10 to-orange-600/10 border-amber-600/30';
    return 'bg-zinc-800/50';
  };

  // Compact mode for embedding
  if (compact) {
    return (
      <Card className={`${cardBg} border-2 border-pink-500/30`}>
        <CardHeader className="pb-2">
          <CardTitle className={`${textPrimary} flex items-center gap-2 text-base`}>
            <Heart className="w-5 h-5 text-pink-400" />
            Stoke Sponsors
            <Badge className="ml-auto bg-pink-500/20 text-pink-400 border-0 text-xs">TOP</Badge>
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-2">
          {loading ? (
            <div className="flex justify-center py-4">
              <Loader2 className="w-6 h-6 text-pink-400 animate-spin" />
            </div>
          ) : leaderboard.length > 0 ? (
            <>
              {leaderboard.slice(0, 3).map((sponsor) => (
                <div 
                  key={sponsor.photographer_id}
                  className={`flex items-center gap-2 p-2 rounded-lg border ${getRankBg(sponsor.rank)}`}
                >
                  <div className="w-8 flex justify-center">
                    {getRankDisplay(sponsor.rank)}
                  </div>
                  <Avatar 
                    className="w-8 h-8 cursor-pointer"
                    onClick={() => navigate(`/profile/${sponsor.photographer_id}`)}
                  >
                    <AvatarImage src={getFullUrl(sponsor.avatar_url)} />
                    <AvatarFallback className="bg-pink-500/20 text-pink-400 text-xs">
                      {sponsor.full_name?.charAt(0)}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex-1 min-w-0">
                    <div className={`font-medium ${textPrimary} text-sm truncate`}>{sponsor.full_name}</div>
                  </div>
                  <div className="text-pink-400 font-bold text-sm">${sponsor.total_contributed.toFixed(0)}</div>
                </div>
              ))}
              <Button 
                variant="ghost" 
                size="sm" 
                className="w-full text-pink-400 hover:bg-pink-500/10"
                onClick={() => navigate('/career/stoke-leaderboard')}
              >
                View Full Leaderboard <ChevronRight className="w-4 h-4 ml-1" />
              </Button>
            </>
          ) : (
            <p className={`text-center ${textSecondary} py-4 text-sm`}>
              No stoke sponsors yet. Be the first!
            </p>
          )}
        </CardContent>
      </Card>
    );
  }

  // Full page mode
  return (
    <div 
      className="space-y-6 pb-24 md:pb-6" 
      data-testid="stoke-sponsor-leaderboard"
      style={{ paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) + 80px)' }}
    >
      {/* Header */}
      <div className="text-center">
        <h1 className={`text-3xl font-bold ${textPrimary} flex items-center justify-center gap-2`} style={{ fontFamily: 'Oswald' }}>
          <Heart className="w-8 h-8 text-pink-400" />
          Stoke Sponsor Leaderboard
        </h1>
        <p className={`${textSecondary} mt-1`}>Photographers who give back to the surf community</p>
      </div>

      {/* Community Stats */}
      <Card className={`${cardBg} border-2 border-pink-500/30 bg-gradient-to-br from-pink-500/5 to-red-500/5`}>
        <CardContent className="pt-6">
          <div className="grid grid-cols-3 gap-4 text-center">
            <div>
              <div className="text-2xl font-bold text-pink-400">${stats.total_contributed.toFixed(0)}</div>
              <div className={`text-xs ${textSecondary}`}>Total Given</div>
            </div>
            <div>
              <div className="text-2xl font-bold text-cyan-400">${stats.total_to_groms.toFixed(0)}</div>
              <div className={`text-xs ${textSecondary}`}>To Groms</div>
            </div>
            <div>
              <div className="text-2xl font-bold text-emerald-400">{stats.total_sponsors}</div>
              <div className={`text-xs ${textSecondary}`}>Sponsors</div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Time Range Filter */}
      <div className="flex justify-center gap-2">
        <Button
          variant={timeRange === 'week' ? 'default' : 'outline'}
          size="sm"
          onClick={() => setTimeRange('week')}
          className={timeRange === 'week' ? 'bg-pink-500 text-white' : 'border-zinc-700'}
        >
          This Week
        </Button>
        <Button
          variant={timeRange === 'month' ? 'default' : 'outline'}
          size="sm"
          onClick={() => setTimeRange('month')}
          className={timeRange === 'month' ? 'bg-pink-500 text-white' : 'border-zinc-700'}
        >
          This Month
        </Button>
        <Button
          variant={timeRange === 'all' ? 'default' : 'outline'}
          size="sm"
          onClick={() => setTimeRange('all')}
          className={timeRange === 'all' ? 'bg-pink-500 text-white' : 'border-zinc-700'}
        >
          All Time
        </Button>
      </div>

      {/* Leaderboard */}
      <Card className={cardBg}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Trophy className="w-5 h-5 text-yellow-400" />
            Top Stoke Sponsors
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="w-8 h-8 text-pink-400 animate-spin" />
            </div>
          ) : leaderboard.length > 0 ? (
            leaderboard.map((sponsor) => (
              <div 
                key={sponsor.photographer_id}
                className={`flex items-center gap-3 p-3 rounded-lg border transition-all hover:scale-[1.01] ${getRankBg(sponsor.rank)}`}
              >
                <div className="w-10 flex justify-center">
                  {getRankDisplay(sponsor.rank)}
                </div>
                <Avatar 
                  className="w-12 h-12 border-2 border-pink-500/30 cursor-pointer"
                  onClick={() => navigate(`/profile/${sponsor.photographer_id}`)}
                >
                  <AvatarImage src={getFullUrl(sponsor.avatar_url)} />
                  <AvatarFallback className="bg-pink-500/20 text-pink-400">
                    {sponsor.full_name?.charAt(0)}
                  </AvatarFallback>
                </Avatar>
                <div className="flex-1 min-w-0">
                  <div className={`font-medium ${textPrimary}`}>{sponsor.full_name}</div>
                  <div className="flex items-center gap-3 mt-1">
                    <span className={`text-xs ${textSecondary}`}>
                      {sponsor.contribution_count} contributions
                    </span>
                    {sponsor.grom_percentage > 0 && (
                      <Badge className="bg-cyan-500/20 text-cyan-400 border-0 text-xs">
                        <Baby className="w-3 h-3 mr-1" />
                        {sponsor.grom_percentage}% to groms
                      </Badge>
                    )}
                  </div>
                </div>
                <div className="text-right">
                  <div className="text-xl font-bold text-pink-400">${sponsor.total_contributed.toFixed(0)}</div>
                  <div className={`text-xs ${textSecondary}`}>contributed</div>
                </div>
              </div>
            ))
          ) : (
            <div className="text-center py-8">
              <Heart className="w-12 h-12 text-pink-400/30 mx-auto mb-3" />
              <p className={`${textSecondary}`}>No stoke sponsors yet</p>
              <p className={`text-sm ${textSecondary}`}>Be the first to support the surf community!</p>
              <Button 
                className="mt-4 bg-pink-500 text-white hover:bg-pink-400"
                onClick={() => navigate('/career/stoke-sponsor')}
              >
                <Heart className="w-4 h-4 mr-2" />
                Become a Stoke Sponsor
              </Button>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default StokeSponsorLeaderboard;

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { usePersona } from '../contexts/PersonaContext';
import apiClient from '../lib/apiClient';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from './ui/sheet';
import { Zap, Gift, Plane, ShoppingBag, GraduationCap, ArrowRight, X } from 'lucide-react';
import { Button } from './ui/button';
import { ROLES } from '../constants/roles';

/**
 * Get credit usage options based on role
 */
const getCreditOptions = (effectiveRole) => {
  if (effectiveRole === ROLES.PRO) {
    return [
      { icon: Gift, title: "Pay It Forward", description: "Support other surfers", color: "pink", route: "/stoked" },
      { icon: ShoppingBag, title: "Premium Gear", description: "Top-tier equipment", color: "cyan", route: "/gear-hub" },
    ];
  }
  if (effectiveRole === ROLES.COMP_SURFER) {
    return [
      { icon: Plane, title: "Travel & Contests", description: "Competition expenses", color: "purple", route: "/explore" },
      { icon: ShoppingBag, title: "Pro Equipment", description: "High-performance gear", color: "cyan", route: "/gear-hub" },
    ];
  }
  if (effectiveRole === ROLES.GROM) {
    return [
      { icon: ShoppingBag, title: "Gear & Equipment", description: "Boards and wetsuits", color: "cyan", route: "/gear-hub" },
      { icon: GraduationCap, title: "Surf Lessons", description: "Level up your skills", color: "green", route: "/map" },
    ];
  }
  // Regular Surfer
  return [
    { icon: ShoppingBag, title: "Gear & Equipment", description: "Boards and wetsuits", color: "cyan", route: "/gear-hub" },
    { icon: GraduationCap, title: "Coaching", description: "Level up your skills", color: "green", route: "/map" },
  ];
};

const colorMap = {
  pink: { bg: 'bg-pink-500/20', text: 'text-pink-400', border: 'border-pink-500/30', hover: 'hover:bg-pink-500/10' },
  cyan: { bg: 'bg-cyan-500/20', text: 'text-cyan-400', border: 'border-cyan-500/30', hover: 'hover:bg-cyan-500/10' },
  purple: { bg: 'bg-purple-500/20', text: 'text-purple-400', border: 'border-purple-500/30', hover: 'hover:bg-purple-500/10' },
  green: { bg: 'bg-green-500/20', text: 'text-green-400', border: 'border-green-500/30', hover: 'hover:bg-green-500/10' },
  yellow: { bg: 'bg-yellow-500/20', text: 'text-yellow-400', border: 'border-yellow-500/30', hover: 'hover:bg-yellow-500/10' },
};

export const StokedDrawer = ({ isOpen, onClose }) => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { getEffectiveRole } = usePersona();
  const [creditBalance, setCreditBalance] = useState(user?.credit_balance || 0);
  
  // Fetch fresh balance from API when drawer opens (same source as Credit Wallet)
  useEffect(() => {
    if (isOpen && user?.id) {
      apiClient.get(`/credits/balance/${user.id}`)
        .then(res => setCreditBalance(res.data.balance || 0))
        .catch(() => setCreditBalance(user?.credit_balance || 0));
    }
  }, [isOpen, user?.id]);
  
  const effectiveRole = getEffectiveRole(user?.role);
  const creditOptions = getCreditOptions(effectiveRole);
  
  // Determine title based on role
  const getTitle = () => {
    if (['Comp Surfer', 'Pro'].includes(effectiveRole)) return 'Stoked';
    if (effectiveRole === ROLES.GROM) return 'Grom Stash';
    return 'Surf Credits';
  };

  const handleOptionClick = (route) => {
    onClose();
    navigate(route);
  };

  const handleViewFull = () => {
    onClose();
    navigate('/profile?tab=stoked');
  };

  return (
    <Sheet open={isOpen} modal={false} onOpenChange={(open) => { if (!open) onClose(); }}>
      <SheetContent 
        side="bottom" 
        hideCloseButton
        className="bg-background border-border rounded-t-3xl sheet-safe-bottom overflow-hidden flex flex-col"
      >
        <SheetHeader className="pb-3 shrink-0">
          <div className="flex items-center justify-between">
            <SheetTitle className="text-foreground flex items-center gap-2 text-base">
              <Zap className="w-5 h-5 text-yellow-400" />
              {getTitle()}
            </SheetTitle>
            <button 
              onClick={onClose}
              className="text-muted-foreground hover:text-foreground p-1"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </SheetHeader>
        
        <div className="overflow-y-auto flex-1 pb-6 space-y-4">
