                  </div>
                  <ArrowRight className={`w-4 h-4 ${colors.text}`} />
                </Button>
              );
            })}
          </div>
          
          {/* View Full Dashboard Link */}
          <div className={!['Pro', 'Comp Surfer', 'Grom'].includes(effectiveRole) ? 'hidden md:block' : 'block'}>
            <Button
              variant="ghost"
