        {/* Features Unlocked */}
        <div className="bg-zinc-900 rounded-xl p-6 mb-8 border border-zinc-800 text-left">
          <h3 className="text-sm text-gray-400 uppercase tracking-wider mb-4">What you've unlocked:</h3>
