// Calculate distance between two coordinates
const calculateDistance = (lat1, lon1, lat2, lon2) => {
  const R = 3959; // Earth's radius in miles
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
};

export const SurfAlerts = () => {
  const { user } = useAuth();
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const highlightedAlertRef = useRef(null);
  
  const [alerts, setAlerts] = useState([]);
  const [spots, setSpots] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [createLoading, setCreateLoading] = useState(false);
  const [pushSupported, setPushSupported] = useState(false);
  const [pushEnabled, setPushEnabled] = useState(false);
  const [showAdvanced, setShowAdvanced] = useState(false);
  
  // Highlight state for notification deep linking
  const [highlightedAlertId, setHighlightedAlertId] = useState(null);
  
  // Edit mode state
  const [editingAlert, setEditingAlert] = useState(null);
  const [isEditMode, setIsEditMode] = useState(false);
  
  // GPS and search state
  const [userLocation, setUserLocation] = useState(null);
  const [spotSearchQuery, setSpotSearchQuery] = useState('');
  const [showSpotResults, setShowSpotResults] = useState(false);
  
  // Share alert state
  const [showShareModal, setShowShareModal] = useState(false);
  const [alertToShare, setAlertToShare] = useState(null);
  const [shareRecipient, setShareRecipient] = useState('');
  const [shareLoading, setShareLoading] = useState(false);
  
  // New alert state with enhanced fields
  const [newAlert, setNewAlert] = useState({
    spot_id: '',
    spot_name: '',
    min_wave_height: '',
    max_wave_height: '',
    preferred_conditions: [], // Array of condition IDs
    time_windows: [], // ['dawn', 'morning', 'afternoon', 'evening']
    tide_states: [],  // ['low', 'mid', 'high', 'rising', 'falling']
    notify_push: true
  });

  useEffect(() => {
    if (user?.id) {
      fetchAlerts();
      fetchSpots();
      checkPushSupport();
      requestUserLocation();
    }
  }, [user?.id]);

  // Handle deep link to specific alert from notifications
  useEffect(() => {
    const alertId = searchParams.get('alert_id') || location.state?.alertId;
    if (alertId && alerts.length > 0) {
      setHighlightedAlertId(alertId);
      // Scroll to the alert after a short delay
      setTimeout(() => {
        if (highlightedAlertRef.current) {
          highlightedAlertRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 300);
      // Remove highlight after 3 seconds
      setTimeout(() => setHighlightedAlertId(null), 3000);
    }
  }, [searchParams, location.state, alerts]);

  const requestUserLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
        },
        (error) => {
          logger.warn('Location access denied:', error);
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    }
  };

  const checkPushSupport = () => {
    if ('Notification' in window && 'serviceWorker' in navigator) {
      setPushSupported(true);
      setPushEnabled(Notification.permission === 'granted');
    }
  };

  const fetchAlerts = async () => {
    try {
      const response = await apiClient.get(`/alerts/user/${user.id}`);
      setAlerts(response.data);
    } catch (error) {
      logger.error('Error fetching alerts:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchSpots = async () => {
    try {
      const response = await apiClient.get(`/surf-spots`);
      setSpots(response.data);
    } catch (error) {
      logger.error('Error fetching spots:', error);
    }
  };

  // Filter and sort spots based on search and GPS
  const filteredSpots = useMemo(() => {
    let result = [...spots];
    
    // Add distance if GPS available
    if (userLocation) {
      result = result.map(spot => ({
        ...spot,
        distance: spot.latitude && spot.longitude 
          ? calculateDistance(userLocation.lat, userLocation.lng, spot.latitude, spot.longitude)
          : null
      }));
    }
    
    // Filter by search query
    if (spotSearchQuery.trim()) {
      const query = spotSearchQuery.toLowerCase();
      result = result.filter(spot =>
        spot.name?.toLowerCase().includes(query) ||
        spot.region?.toLowerCase().includes(query) ||
        spot.city?.toLowerCase().includes(query) ||
        spot.country?.toLowerCase().includes(query)
      );
    }
    
    // Sort by distance if GPS available, otherwise alphabetically
    if (userLocation) {
      result.sort((a, b) => (a.distance || 999) - (b.distance || 999));
    } else {
      result.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    }
    
    return result.slice(0, 15); // Limit results
  }, [spots, spotSearchQuery, userLocation]);

  const enablePushNotifications = async () => {
    try {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        setPushEnabled(true);
        toast.success('Push notifications enabled!');
        
        if ('serviceWorker' in navigator) {
          const registration = await navigator.serviceWorker.ready;
          const vapidResponse = await apiClient.get(`/push/vapid-key`);
          
          const subscription = await registration.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey: vapidResponse.data.public_key
          });
          
          const subJson = subscription.toJSON();
          await apiClient.post(`/push/subscribe`, {
            endpoint: subJson.endpoint,
            p256dh_key: subJson.keys?.p256dh || '',
            auth_key: subJson.keys?.auth || '',
            user_agent: navigator.userAgent
          });
        }
      } else {
        toast.error('Please enable notifications in your browser settings');
      }
    } catch (error) {
      logger.error('Error enabling push:', error);
      toast.error('Failed to enable push notifications');
    }
  };

  const selectSpot = (spot) => {
    setNewAlert(prev => ({ 
      ...prev, 
      spot_id: spot.id, 
      spot_name: spot.name 
    }));
    setSpotSearchQuery(spot.name);
    setShowSpotResults(false);
  };

  const toggleTimeWindow = (windowId) => {
    setNewAlert(prev => ({
      ...prev,
      time_windows: prev.time_windows.includes(windowId)
        ? prev.time_windows.filter(w => w !== windowId)
        : [...prev.time_windows, windowId]
    }));
  };

  const toggleTideState = (stateId) => {
    setNewAlert(prev => ({
      ...prev,
      tide_states: prev.tide_states.includes(stateId)
        ? prev.tide_states.filter(s => s !== stateId)
        : [...prev.tide_states, stateId]
    }));
  };

  const toggleCondition = (conditionId) => {
    setNewAlert(prev => ({
      ...prev,
      preferred_conditions: prev.preferred_conditions.includes(conditionId)
        ? prev.preferred_conditions.filter(c => c !== conditionId)
        : [...prev.preferred_conditions, conditionId]
    }));
  };

  const createAlert = async () => {
    if (!newAlert.spot_id) {
      toast.error('Please select a surf spot');
      return;
    }

    setCreateLoading(true);
    try {
      await apiClient.post(`/alerts`, {
        spot_id: newAlert.spot_id,
        min_wave_height: newAlert.min_wave_height ? parseFloat(newAlert.min_wave_height) : null,
        max_wave_height: newAlert.max_wave_height ? parseFloat(newAlert.max_wave_height) : null,
        preferred_conditions: newAlert.preferred_conditions.length > 0 ? newAlert.preferred_conditions : null,
        time_windows: newAlert.time_windows.length > 0 ? newAlert.time_windows : null,
        tide_states: newAlert.tide_states.length > 0 ? newAlert.tide_states : null,
        notify_push: newAlert.notify_push
      });
      
      toast.success('Surf alert created! 🌊');
      setShowCreateModal(false);
      resetNewAlert();
      fetchAlerts();
    } catch (error) {
      if (error.response?.data?.detail === 'Alert already exists for this spot') {
        toast.error('You already have an alert for this spot');
      } else {
        toast.error('Failed to create alert');
      }
    } finally {
      setCreateLoading(false);
    }
  };

  const resetNewAlert = () => {
    setNewAlert({
      spot_id: '',
      spot_name: '',
      min_wave_height: '',
      max_wave_height: '',
      preferred_conditions: [],
      time_windows: [],
      tide_states: [],
      notify_push: true
    });
    setSpotSearchQuery('');
    setShowAdvanced(false);
    setEditingAlert(null);
    setIsEditMode(false);
  };

  const openEditModal = (alert) => {
    setEditingAlert(alert);
    setIsEditMode(true);
    // Handle both array and string formats for backwards compatibility
    const conditions = Array.isArray(alert.preferred_conditions) 
      ? alert.preferred_conditions 
      : (alert.preferred_conditions ? [alert.preferred_conditions] : []);
    setNewAlert({
      spot_id: alert.spot_id,
      spot_name: alert.spot_name,
      min_wave_height: alert.min_wave_height?.toString() || '',
      max_wave_height: alert.max_wave_height?.toString() || '',
      preferred_conditions: conditions,
      time_windows: alert.time_windows || [],
      tide_states: alert.tide_states || [],
      notify_push: alert.notify_push !== false
    });
    setSpotSearchQuery(alert.spot_name);
    // Show advanced if any advanced settings are set
    if ((alert.time_windows && alert.time_windows.length > 0) || 
        (alert.tide_states && alert.tide_states.length > 0) ||
        (conditions.length > 0)) {
      setShowAdvanced(true);
    }
    setShowCreateModal(true);
  };

  const updateAlert = async () => {
    if (!editingAlert) return;

    setCreateLoading(true);
    try {
      await apiClient.put(`/alerts/${editingAlert.id}`, {
        spot_id: newAlert.spot_id,
        min_wave_height: newAlert.min_wave_height ? parseFloat(newAlert.min_wave_height) : null,
        max_wave_height: newAlert.max_wave_height ? parseFloat(newAlert.max_wave_height) : null,
        preferred_conditions: newAlert.preferred_conditions.length > 0 ? newAlert.preferred_conditions : null,
        time_windows: newAlert.time_windows.length > 0 ? newAlert.time_windows : null,
        tide_states: newAlert.tide_states.length > 0 ? newAlert.tide_states : null,
        notify_push: newAlert.notify_push
      });
      
      toast.success('Alert updated! 🌊');
      setShowCreateModal(false);
      resetNewAlert();
      fetchAlerts();
    } catch (error) {
      logger.error('Error updating alert:', error);
      toast.error('Failed to update alert');
    } finally {
      setCreateLoading(false);
    }
  };

  const handleSaveAlert = () => {
    if (isEditMode) {
      updateAlert();
    } else {
      createAlert();
    }
  };

  const toggleAlert = async (alertId, isActive) => {
    try {
      await apiClient.patch(`/alerts/${alertId}`, { is_active: !isActive });
      setAlerts(alerts.map(a => a.id === alertId ? { ...a, is_active: !isActive } : a));
      toast.success(isActive ? 'Alert paused' : 'Alert activated');
    } catch (error) {
      toast.error('Failed to update alert');
    }
  };

  const deleteAlert = async (alertId) => {
    try {
      await apiClient.delete(`/alerts/${alertId}`);
      setAlerts(alerts.filter(a => a.id !== alertId));
      toast.success('Alert deleted');
    } catch (error) {
      toast.error('Failed to delete alert');
    }
  };

  const openShareModal = (alert) => {
    setAlertToShare(alert);
    setShareRecipient('');
    setShowShareModal(true);
  };

  const shareAlert = async () => {
    if (!shareRecipient.trim()) {
      toast.error('Please enter a username or email');
      return;
    }

    setShareLoading(true);
    try {
      await apiClient.post(`/alerts/share`, {
        alert_id: alertToShare.id,
        sender_id: user.id,
        recipient_identifier: shareRecipient.trim()
      });
      
      toast.success(`Alert shared with ${shareRecipient}! 🎉`);
      setShowShareModal(false);
      setAlertToShare(null);
      setShareRecipient('');
    } catch (error) {
      if (error.response?.status === 404) {
        toast.error('User not found');
      } else {
        toast.error('Failed to share alert');
      }
    } finally {
      setShareLoading(false);
    }
  };

  const copyAlertLink = () => {
    const alertConfig = {
      spot_id: alertToShare.spot_id,
      spot_name: alertToShare.spot_name,
      min_wave_height: alertToShare.min_wave_height,
      max_wave_height: alertToShare.max_wave_height,
      preferred_conditions: alertToShare.preferred_conditions,
      time_windows: alertToShare.time_windows,
      tide_states: alertToShare.tide_states
    };
    
    const encoded = btoa(JSON.stringify(alertConfig));
    const link = `${window.location.origin}/alerts?import=${encoded}`;
    
    navigator.clipboard.writeText(link);
    toast.success('Alert link copied to clipboard!');
  };

  // Check for imported alert on mount
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const importData = params.get('import');
    
    if (importData && user?.id) {
      try {
        const alertConfig = JSON.parse(atob(importData));
        setNewAlert({
          spot_id: alertConfig.spot_id || '',
          spot_name: alertConfig.spot_name || '',
          min_wave_height: alertConfig.min_wave_height?.toString() || '',
          max_wave_height: alertConfig.max_wave_height?.toString() || '',
          preferred_conditions: alertConfig.preferred_conditions || '',
          time_windows: alertConfig.time_windows || [],
          tide_states: alertConfig.tide_states || [],
          notify_push: true
        });
        setSpotSearchQuery(alertConfig.spot_name || '');
        setShowCreateModal(true);
        toast.info('Alert configuration loaded! Review and create.');
        
        // Clean URL
        window.history.replaceState({}, '', '/alerts');
      } catch (e) {
        logger.error('Failed to parse imported alert:', e);
      }
    }
  }, [user?.id]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-yellow-400" />
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto p-4 bg-background min-h-screen" data-testid="surf-alerts-page">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-foreground flex items-center gap-2" style={{ fontFamily: 'Oswald' }}>
            <BellRing className="w-6 h-6 text-yellow-500 dark:text-yellow-400" />
            Surf Alerts
          </h1>
          <p className="text-muted-foreground text-sm mt-1">Get notified when conditions are perfect</p>
        </div>
        <Button
          onClick={() => setShowCreateModal(true)}
          className="bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black font-bold"
          data-testid="create-alert-btn"
        >
          <Plus className="w-4 h-4 mr-2" />
          New Alert
        </Button>
      </div>

      {/* Push Notification Banner */}
      {pushSupported && !pushEnabled && (
        <Card className="bg-gradient-to-r from-blue-500/20 to-purple-500/20 border-blue-500/30 mb-6">
          <CardContent className="p-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Bell className="w-8 h-8 text-blue-400" />
              <div>
                <p className="text-white font-medium">Enable Push Notifications</p>
                <p className="text-sm text-gray-400">Get instant alerts when conditions match</p>
              </div>
            </div>
            <Button onClick={enablePushNotifications} className="bg-blue-500 hover:bg-blue-600 text-white">
              Enable
            </Button>
          </CardContent>
        </Card>
      )}

      {pushEnabled && (
        <div className="flex items-center gap-2 mb-4 text-emerald-400 text-sm">
          <Check className="w-4 h-4" />
          Push notifications enabled
        </div>
      )}

      {/* Alerts List */}
      {alerts.length === 0 ? (
        <Card className="bg-card border-border">
          <CardContent className="p-8 text-center">
            <BellOff className="w-16 h-16 text-muted-foreground mx-auto mb-4" />
            <h3 className="text-xl font-bold text-foreground mb-2">No Alerts Yet</h3>
            <p className="text-muted-foreground mb-4">Create an alert to get notified when your favorite spot is firing!</p>
            <Button
              onClick={() => setShowCreateModal(true)}
              className="bg-gradient-to-r from-yellow-400 to-orange-400 text-black font-bold"
            >
              Create Your First Alert
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {alerts.map((alert) => (
            <Card 
              key={alert.id}
              ref={alert.id === highlightedAlertId ? highlightedAlertRef : null}
              className={`bg-card border-border transition-all duration-500 ${
                !alert.is_active ? 'opacity-50' : ''
              } ${
                alert.id === highlightedAlertId 
                  ? 'ring-2 ring-yellow-400 ring-offset-2 ring-offset-background animate-pulse' 
                  : ''
              }`}
              data-testid={`alert-card-${alert.id}`}
            >
              <CardContent className="p-4">
                <div className="flex items-start gap-4">
                  {/* Spot Image */}
                  <div className="w-20 h-20 rounded-lg overflow-hidden flex-shrink-0 bg-muted">
                    {alert.spot_image ? (
                      <img src={alert.spot_image} alt={alert.spot_name} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <MapPin className="w-8 h-8 text-muted-foreground" />
                      </div>
                    )}
                  </div>

                  {/* Alert Details */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-2">
                      <h3 className="font-bold text-foreground truncate">{alert.spot_name}</h3>
                      <div className="flex items-center gap-2">
                        <button
                          onClick={() => openEditModal(alert)}
                          className="p-1 text-gray-400 hover:text-yellow-400 transition-colors"
                          title="Edit alert"
                          data-testid={`edit-alert-${alert.id}`}
                        >
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => openShareModal(alert)}
                          className="p-1 text-gray-400 hover:text-blue-400 transition-colors"
                          title="Share alert"
                        >
                          <Share2 className="w-4 h-4" />
                        </button>
                        <Switch
                          checked={alert.is_active}
                          onCheckedChange={() => toggleAlert(alert.id, alert.is_active)}
                        />
                        <button
                          onClick={() => deleteAlert(alert.id)}
                          className="p-1 text-gray-400 hover:text-red-400 transition-colors"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>

                    <div className="flex flex-wrap gap-2 mb-2">
                      {alert.min_wave_height && (
                        <Badge className="bg-blue-500/20 text-blue-400">
                          <Waves className="w-3 h-3 mr-1" />
                          {alert.min_wave_height}ft+
                        </Badge>
                      )}
                      {alert.max_wave_height && (
                        <Badge className="bg-blue-500/20 text-blue-400">
                          Max {alert.max_wave_height}ft
                        </Badge>
                      )}
                      {alert.preferred_conditions && (
                        <>
                          {(Array.isArray(alert.preferred_conditions) ? alert.preferred_conditions : [alert.preferred_conditions]).map(condId => {
                            const condition = SURF_CONDITIONS.find(c => c.id === condId);
                            if (!condition) {
                              // Fallback for legacy string values
                              return (
                                <Badge key={condId} className="bg-emerald-500/20 text-emerald-400">
                                  {condId}
                                </Badge>
                              );
                            }
                            return (
                              <Badge key={condId} className="bg-emerald-500/20 text-emerald-400 text-xs">
                                <span className="mr-1">{condition.emoji}</span>
                                {condition.label}
                              </Badge>
                            );
                          })}
                        </>
                      )}
                    </div>
                    
                    {/* Time Windows & Tide States */}
                    <div className="flex flex-wrap gap-1.5 mb-2">
                      {alert.time_windows?.map(tw => {
                        const window = TIME_WINDOWS.find(w => w.id === tw);
                        if (!window) return null;
                        const Icon = window.icon;
                        return (
                          <Badge key={tw} className="bg-purple-500/20 text-purple-400 text-xs">
                            <Icon className="w-3 h-3 mr-1" />
                            {window.label}
                          </Badge>
                        );
                      })}
                      {alert.tide_states?.map(ts => {
                        const state = TIDE_STATES.find(s => s.id === ts);
                        if (!state) return null;
                        const Icon = state.icon;
                        return (
                          <Badge key={ts} className="bg-cyan-500/20 text-cyan-400 text-xs">
                            <Icon className="w-3 h-3 mr-1" />
                            {state.label}
                          </Badge>
                        );
                      })}
                    </div>

                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
                      <span>Triggered {alert.trigger_count || 0} times</span>
                      {alert.last_triggered && (
                        <span>Last: {new Date(alert.last_triggered).toLocaleDateString()}</span>
                      )}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Create/Edit Alert Modal */}
      <Dialog open={showCreateModal} onOpenChange={(open) => { setShowCreateModal(open); if (!open) resetNewAlert(); }}>
        <DialogContent className="bg-zinc-900 border-zinc-800 text-white w-[95vw] sm:w-full max-w-md max-h-[85vh] sm:max-h-[90vh] overflow-hidden flex flex-col p-0 sm:rounded-2xl gap-0">
          <DialogHeader className="px-5 py-4 border-b border-zinc-800 bg-zinc-900/95 sticky top-0 z-10 shrink-0">
            <DialogTitle className="text-xl font-bold flex items-center gap-2">
              <BellRing className="w-5 h-5 text-yellow-400" />
              {isEditMode ? 'Edit Surf Alert' : 'Create Surf Alert'}
            </DialogTitle>
          </DialogHeader>
          
          <div className="flex-1 overflow-y-auto p-5 space-y-5 overscroll-contain">
            {/* Spot Selection with Search & GPS */}
            <div>
              <label className="text-sm font-medium text-gray-300 mb-2 flex items-center gap-2">
                <MapPin className="w-4 h-4 text-emerald-400" />
                Surf Spot *
                {userLocation && (
                  <Badge className="bg-green-500/20 text-green-400 text-[10px] px-1.5 py-0 border-green-500/30">
                    <Target className="w-3 h-3 mr-1" />
                    GPS Active
                  </Badge>
                )}
              </label>
              
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                <Input
                  type="text"
                  placeholder={userLocation ? "Search or pick nearby spot..." : "Search for a spot..."}
                  value={spotSearchQuery}
                  onChange={(e) => {
                     setSpotSearchQuery(e.target.value);
                    setShowSpotResults(true);
                    if (!e.target.value) {
                      setNewAlert(prev => ({ ...prev, spot_id: '', spot_name: '' }));
                    }
                  }}
                  onFocus={() => setShowSpotResults(true)}
                  className="pl-10 pr-10 bg-zinc-950 border-zinc-800 text-white focus:ring-yellow-500/50 rounded-xl rounded-b-xl" // Added rounded-b-xl
                  data-testid="spot-search-input"
                />
                {spotSearchQuery && (
                  <button
                    onClick={() => {
                      setSpotSearchQuery('');
                      setNewAlert(prev => ({ ...prev, spot_id: '', spot_name: '' }));
                    }}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1 hover:bg-zinc-800 rounded-full transition-colors"
                  >
                    <X className="w-4 h-4 text-gray-400 hover:text-white" />
                  </button>
                )}
              </div>
              
              {/* Spot Results Dropdown */}
              {showSpotResults && (spotSearchQuery || userLocation) && (
                <div className="mt-2 bg-zinc-950 border border-zinc-800 rounded-xl overflow-hidden max-h-56 overflow-y-auto shadow-2xl">
                  {filteredSpots.length === 0 ? (
                    <div className="p-4 text-center text-gray-500 text-sm">
                      {spotSearchQuery ? 'No spots found' : 'Start typing to search'}
                    </div>
                  ) : (
                    filteredSpots.map((spot) => (
                      <button
                        key={spot.id}
                        onClick={() => selectSpot(spot)}
                        className={`w-full flex items-center gap-3 p-3 hover:bg-zinc-800 transition-colors text-left border-b border-zinc-800/50 last:border-0 ${
                          newAlert.spot_id === spot.id ? 'bg-yellow-500/10' : ''
                        }`}
                        data-testid={`spot-option-${spot.id}`}
                      >
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${newAlert.spot_id === spot.id ? 'bg-yellow-500/20' : 'bg-zinc-800'}`}>
                          <MapPin className={`w-4 h-4 ${newAlert.spot_id === spot.id ? 'text-yellow-400' : 'text-gray-400'}`} />
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className={`font-medium truncate text-sm flex items-center gap-2 ${newAlert.spot_id === spot.id ? 'text-yellow-400' : 'text-white'}`}>
                            {spot.name}
                            {newAlert.spot_id === spot.id && <Check className="w-3.5 h-3.5 text-yellow-400 flex-shrink-0" />}
                          </p>
                          <p className="text-xs text-gray-500 truncate mt-0.5">
                            {spot.region || spot.city || spot.country || 'Unknown location'}
                          </p>
                        </div>
                        {spot.distance !== null && spot.distance !== undefined && (
                          <div className={`text-xs font-medium px-2 py-1 rounded-md flex-shrink-0 tracking-wide ${spot.distance < 5 ? 'bg-green-500/10 text-green-400' : 'bg-zinc-800 text-gray-400'}`}>
                            {spot.distance < 0.1 ? '<0.1' : spot.distance.toFixed(1)} mi
                          </div>
                        )}
                      </button>
                    ))
                  )}
                </div>
              )}
            </div>

            {/* Wave Height Range */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">Min Wave Height</label>
                <Select value={newAlert.min_wave_height} onValueChange={(v) => setNewAlert(prev => ({ ...prev, min_wave_height: v }))}>
                  <SelectTrigger className="bg-zinc-950 border-zinc-800 text-white rounded-xl">
                    <SelectValue placeholder="Any" />
                  </SelectTrigger>
                  <SelectContent className="bg-zinc-950 border-zinc-800 rounded-xl">
                    <SelectItem value="2" className="text-white">2ft+</SelectItem>
                    <SelectItem value="3" className="text-white">3ft+</SelectItem>
                    <SelectItem value="4" className="text-white">4ft+</SelectItem>
                    <SelectItem value="5" className="text-white">5ft+</SelectItem>
                    <SelectItem value="6" className="text-white">6ft+ (OH)</SelectItem>
                    <SelectItem value="8" className="text-white">8ft+ (DOH)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300">Max Wave Height</label>
                <Select value={newAlert.max_wave_height} onValueChange={(v) => setNewAlert(prev => ({ ...prev, max_wave_height: v }))}>
                  <SelectTrigger className="bg-zinc-950 border-zinc-800 text-white rounded-xl">
                    <SelectValue placeholder="Any" />
                  </SelectTrigger>
                  <SelectContent className="bg-zinc-950 border-zinc-800 rounded-xl">
                    <SelectItem value="4" className="text-white">Up to 4ft</SelectItem>
                    <SelectItem value="6" className="text-white">Up to 6ft</SelectItem>
                    <SelectItem value="8" className="text-white">Up to 8ft</SelectItem>
                    <SelectItem value="10" className="text-white">Up to 10ft</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            {/* Time Window Preference */}
            <div>
              <label className="text-sm font-medium text-gray-300 mb-2 flex items-center gap-2">
                <Clock className="w-4 h-4 text-purple-400" />
                Preferred Time Windows
              </label>
              <div className="grid grid-cols-2 gap-2">
                {TIME_WINDOWS.map((window) => {
                  const Icon = window.icon;
                  const isSelected = newAlert.time_windows.includes(window.id);
                  return (
                    <button
                      key={window.id}
                      onClick={() => toggleTimeWindow(window.id)}
                      className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${
                        isSelected
                          ? 'bg-purple-500/10 border-purple-500/40 shadow-[inset_0_0_12px_rgba(168,85,247,0.15)]'
                          : 'bg-zinc-950 border-zinc-800 hover:border-zinc-700 hover:bg-zinc-900'
                      }`}
                      data-testid={`time-window-${window.id}`}
                    >
                      <div className={`p-1.5 rounded-md ${isSelected ? 'bg-purple-500/20' : 'bg-transparent'}`}>
                        <Icon className={`w-4 h-4 ${isSelected ? 'text-purple-400' : 'text-gray-500'}`} />
                      </div>
                      <div className="text-left flex-1">
                        <p className={`text-sm font-medium ${isSelected ? 'text-purple-300' : 'text-gray-300'}`}>{window.label}</p>
                        <p className={`text-[10px] ${isSelected ? 'text-purple-400/70' : 'text-gray-500'}`}>{window.time}</p>
                      </div>
                      {isSelected && <Check className="w-4 h-4 text-purple-400 flex-shrink-0" />}
                    </button>
                  );
                })}
              </div>
              <p className="text-[11px] text-gray-500 mt-2 px-1">Leave empty for any time</p>
            </div>

            {/* Tide State Preference */}
            <div>
              <label className="text-sm font-medium text-gray-300 mb-2 flex items-center gap-2">
                <Droplets className="w-4 h-4 text-cyan-400" />
                Preferred Tide
              </label>
              <div className="flex flex-wrap gap-2">
                {TIDE_STATES.map((state) => {
                  const Icon = state.icon;
                  const isSelected = newAlert.tide_states.includes(state.id);
                  return (
                    <button
                      key={state.id}
                      onClick={() => toggleTideState(state.id)}
                      className={`flex items-center gap-2 px-4 py-2.5 rounded-xl border transition-all ${
                        isSelected
                          ? 'bg-cyan-500/10 border-cyan-500/40 shadow-[inset_0_0_12px_rgba(6,182,212,0.15)] text-cyan-300'
                          : 'bg-zinc-950 border-zinc-800 text-gray-400 hover:border-zinc-700 hover:bg-zinc-900'
                      }`}
                      data-testid={`tide-state-${state.id}`}
                    >
                      <Icon className={`w-4 h-4 ${isSelected ? 'text-cyan-400' : 'text-gray-500'}`} />
                      <span className="text-sm font-medium">{state.label}</span>
                      {isSelected && <Check className="w-3.5 h-3.5 ml-1 text-cyan-400" />}
                    </button>
                  );
                })}
              </div>
              <p className="text-[11px] text-gray-500 mt-2 px-1">Leave empty for any tide</p>
            </div>

            {/* Advanced Options Toggle */}
            <div className="pt-2">
              <button
                onClick={() => setShowAdvanced(!showAdvanced)}
                className="flex items-center justify-between w-full p-4 bg-zinc-900 rounded-xl border border-zinc-800 hover:bg-zinc-800 transition-colors"
              >
                <div className="flex items-center gap-2 font-medium text-sm text-gray-300">
                  <Settings className="w-4 h-4 text-yellow-500/70" />
                  Advanced Conditions
                </div>
                {showAdvanced ? <ChevronUp className="w-4 h-4 text-gray-500" /> : <ChevronDown className="w-4 h-4 text-gray-500" />}
              </button>
            </div>

            {showAdvanced && (
              <div className="space-y-5 px-1 animate-in slide-in-from-top-1 fade-in duration-200 block">
                <div className="bg-zinc-950/50 rounded-2xl p-4 border border-zinc-800/50">
                  <label className="text-sm font-bold text-white mb-1 flex items-center gap-2">
                    <Waves className="w-4 h-4 text-blue-400" />
                    Specific Conditions
                  </label>
                  <p className="text-xs text-gray-400 mb-5">Select all specific traits you require. Leave blank if you don't care.</p>
                  
                  {/* Surface Conditions */}
                  <div className="mb-4">
                    <p className="text-[11px] text-blue-400/80 font-semibold mb-2 uppercase tracking-wider">Surface</p>
                    <div className="flex flex-wrap gap-2">
                      {SURF_CONDITIONS.filter(c => c.category === 'surface').map((condition) => (
                        <button
                          key={condition.id}
                          type="button"
                          onClick={() => toggleCondition(condition.id)}
                          className={`px-4 py-2 rounded-xl text-sm font-medium transition-all flex items-center gap-2 ${
                            newAlert.preferred_conditions.includes(condition.id)
                              ? 'bg-blue-500/20 text-blue-300 border border-blue-500/40 shadow-sm'
                              : 'bg-zinc-900 border border-zinc-800/80 text-gray-300 hover:border-zinc-700 hover:bg-zinc-800 hover:text-white'
                          }`}
                        >
                          <span className="text-base leading-none">{condition.emoji}</span>
                          {condition.label}
                        </button>
                      ))}
                    </div>
                  </div>
                  
                  {/* Wind Conditions */}
                  <div className="mb-4">
                    <p className="text-[11px] text-emerald-400/80 font-semibold mb-2 uppercase tracking-wider">Wind</p>
                    <div className="flex flex-wrap gap-2">
                      {SURF_CONDITIONS.filter(c => c.category === 'wind').map((condition) => (
                        <button
                          key={condition.id}
                          type="button"
                          onClick={() => toggleCondition(condition.id)}
                          className={`px-4 py-2 rounded-xl text-sm font-medium transition-all flex items-center gap-2 ${
                            newAlert.preferred_conditions.includes(condition.id)
                              ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 shadow-sm'
                              : 'bg-zinc-900 border border-zinc-800/80 text-gray-300 hover:border-zinc-700 hover:bg-zinc-800 hover:text-white'
                          }`}
                        >
                          <span className="text-base leading-none">{condition.emoji}</span>
                          {condition.label}
                        </button>
                      ))}
                    </div>
                  </div>
                  
                  {/* Wave Quality */}
                  <div className="mb-4">
                    <p className="text-[11px] text-purple-400/80 font-semibold mb-2 uppercase tracking-wider">Wave Quality</p>
                    <div className="flex flex-wrap gap-2">
                      {SURF_CONDITIONS.filter(c => c.category === 'quality').map((condition) => (
                        <button
                          key={condition.id}
                          type="button"
                          onClick={() => toggleCondition(condition.id)}
                          className={`px-4 py-2 rounded-xl text-sm font-medium transition-all flex items-center gap-2 ${
                            newAlert.preferred_conditions.includes(condition.id)
                              ? 'bg-purple-500/20 text-purple-300 border border-purple-500/40 shadow-sm'
                              : 'bg-zinc-900 border border-zinc-800/80 text-gray-300 hover:border-zinc-700 hover:bg-zinc-800 hover:text-white'
                          }`}
                        >
                          <span className="text-base leading-none">{condition.emoji}</span>
                          {condition.label}
                        </button>
                      ))}
                    </div>
                  </div>
                  
                  {/* Crowd */}
                  <div>
                    <p className="text-[11px] text-amber-400/80 font-semibold mb-2 uppercase tracking-wider">Other / Vibe</p>
                    <div className="flex flex-wrap gap-2">
                      {SURF_CONDITIONS.filter(c => c.category === 'crowd').map((condition) => (
                        <button
                          key={condition.id}
                          type="button"
                          onClick={() => toggleCondition(condition.id)}
                          className={`px-4 py-2 rounded-xl text-sm font-medium transition-all flex items-center gap-2 ${
                            newAlert.preferred_conditions.includes(condition.id)
                              ? 'bg-amber-500/20 text-amber-300 border border-amber-500/40 shadow-sm'
                              : 'bg-zinc-900 border border-zinc-800/80 text-gray-300 hover:border-zinc-700 hover:bg-zinc-800 hover:text-white'
                          }`}
                        >
                          <span className="text-base leading-none">{condition.emoji}</span>
                          {condition.label}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Push Toggle & Actions */}
            <div className="pt-2 pb-6 space-y-4">
              <div className="flex items-center justify-between p-4 bg-zinc-900 border border-zinc-800 rounded-xl hover:border-zinc-700 transition-colors">
                <div className="flex items-center gap-3">
                  <div className="bg-yellow-500/10 p-2 rounded-lg">
                    <Bell className="w-5 h-5 text-yellow-400" />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-white">Push Notifications</p>
                    <p className="text-[11px] text-gray-400">Get instant alerts on your phone</p>
                  </div>
                </div>
                <Switch
                  checked={newAlert.notify_push}
                  onCheckedChange={(checked) => setNewAlert(prev => ({ ...prev, notify_push: checked }))}
                  className="data-[state=checked]:bg-yellow-500"
                />
              </div>

              <Button
                onClick={handleSaveAlert}
                disabled={createLoading || !newAlert.spot_id}
                className="w-full h-14 rounded-xl bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black font-bold shadow-lg shadow-yellow-500/20 text-base"
                data-testid={isEditMode ? "update-alert-submit" : "create-alert-submit"}
              >
                {createLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : (isEditMode ? 'Update Alert Configuration' : 'Create Surf Alert')}
              </Button>
            </div>

          </div>
        </DialogContent>
      </Dialog>

      {/* Share Alert Modal */}
      <Dialog open={showShareModal} onOpenChange={setShowShareModal}>
        <DialogContent className="bg-zinc-900 border-zinc-800 text-white w-[95vw] sm:w-full max-w-sm max-h-[85vh] sm:max-h-[90vh] overflow-hidden flex flex-col p-0 sm:rounded-2xl gap-0">
          <DialogHeader className="px-5 py-4 border-b border-zinc-800 bg-zinc-900/95 sticky top-0 z-10 shrink-0">
            <DialogTitle className="text-lg font-bold flex items-center gap-2">
              <Share2 className="w-5 h-5 text-blue-400" />
              Share Alert
            </DialogTitle>
          </DialogHeader>
          
          {alertToShare && (
            <div className="flex-1 overflow-y-auto p-5 space-y-5">
              <div className="p-4 bg-zinc-950 border border-zinc-800 rounded-xl">
                <p className="text-white font-medium">{alertToShare.spot_name}</p>
                <div className="flex flex-wrap gap-1 mt-2">
                  {alertToShare.min_wave_height && (
                    <Badge className="bg-blue-500/20 text-blue-400 text-xs px-2 py-0.5 border-blue-500/30">{alertToShare.min_wave_height}ft+</Badge>
                  )}
                  {alertToShare.time_windows?.map(tw => (
                    <Badge key={tw} className="bg-purple-500/20 text-purple-400 text-xs px-2 py-0.5 border-purple-500/30">{tw}</Badge>
                  ))}
                  {alertToShare.tide_states?.map(ts => (
                    <Badge key={ts} className="bg-cyan-500/20 text-cyan-400 text-xs px-2 py-0.5 border-cyan-500/30">{ts}</Badge>
                  ))}
                </div>
              </div>
              
              {/* Share with user */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-300 block">Share with user</label>
                <Input
                  type="text"
                  placeholder="Username or email"
                  value={shareRecipient}
                  onChange={(e) => setShareRecipient(e.target.value)}
                  className="bg-zinc-950 border-zinc-800 text-white h-11 rounded-xl focus:ring-blue-500/50"
                  data-testid="share-recipient-input"
                />
              </div>
              
              <Button
                onClick={shareAlert}
                disabled={shareLoading || !shareRecipient.trim()}
                className="w-full h-12 rounded-xl bg-blue-500 hover:bg-blue-600 text-white font-semibold shadow-lg shadow-blue-500/20"
              >
                {shareLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Send Alert Directly'}
              </Button>
              
              <div className="relative py-2">
                <div className="absolute inset-0 flex items-center">
                  <span className="w-full border-t border-zinc-800" />
                </div>
                <div className="relative flex justify-center text-xs uppercase tracking-wider font-semibold">
                  <span className="bg-zinc-900 px-3 text-gray-500">or link</span>
                </div>
              </div>
              
              {/* Copy link */}
              <Button
                onClick={copyAlertLink}
                variant="outline"
                className="w-full h-12 rounded-xl border-zinc-700 bg-zinc-950 text-white hover:bg-zinc-800 hover:text-white"
              >
                <Copy className="w-4 h-4 mr-2" />
                Copy Alert Link
              </Button>
              
              <p className="text-xs text-gray-500 text-center px-4 leading-relaxed">
                Anyone with the link can import this alert configuration to their profile
              </p>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  BookOpen, Plus, Waves, Clock, MapPin, Star, Trash2, Edit3,
  ChevronLeft, Loader2, Calendar, Thermometer, Wind, Users,
  X, Save, Smile, Frown, Meh, Heart, Zap, Sun, CloudRain
} from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from './ui/dialog';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import apiClient from '../lib/apiClient';
import { toast } from 'sonner';
import logger from '../utils/logger';
import { getThemeTokens } from '../utils/themeTokens';

const MOODS = [
  { id: 'stoked', label: 'Stoked', icon: '🤙', color: 'text-green-400' },
  { id: 'happy', label: 'Happy', icon: '😄', color: 'text-yellow-400' },
  { id: 'mellow', label: 'Mellow', icon: '😌', color: 'text-blue-400' },
  { id: 'frustrated', label: 'Frustrated', icon: '😤', color: 'text-orange-400' },
  { id: 'exhausted', label: 'Exhausted', icon: '😩', color: 'text-red-400' },
];

const CROWD_LEVELS = ['Empty', 'Light', 'Moderate', 'Crowded', 'Packed'];
const TIDE_OPTIONS = ['Low', 'Rising', 'High', 'Falling'];
const WIND_OPTIONS = ['Offshore', 'Cross-offshore', 'Cross-shore', 'Cross-onshore', 'Onshore', 'Calm'];
const TIME_OPTIONS = ['Dawn Patrol', 'Morning', 'Midday', 'Afternoon', 'Sunset', 'Night'];

/* ─── Stats Banner ──────────────────────────────────────────── */
const StatsBanner = ({ stats, isLight }) => {
  if (!stats || stats.total_sessions === 0) return null;
  const items = [
    { label: 'Sessions', value: stats.total_sessions, icon: Waves, gradient: 'from-cyan-500/20 to-blue-500/20', border: 'border-cyan-500/30' },
    { label: 'Hours', value: stats.total_hours, icon: Clock, gradient: 'from-purple-500/20 to-pink-500/20', border: 'border-purple-500/30' },
    { label: 'Avg Rating', value: stats.avg_personal_rating ?? '—', icon: Star, gradient: 'from-yellow-500/20 to-orange-500/20', border: 'border-yellow-500/30' },
  ];
  return (
    <div className="px-4 md:px-0 mb-4">
      <div className="grid grid-cols-3 gap-3">
        {items.map(s => (
          <div key={s.label} className={`p-3 md:p-4 rounded-xl border text-center bg-gradient-to-br ${s.gradient} ${s.border} transition-all hover:scale-[1.02]`}>
            <s.icon className="w-4 h-4 md:w-5 md:h-5 mx-auto mb-1.5 text-cyan-400" />
            <p className={`text-xl md:text-2xl font-bold ${isLight ? 'text-gray-900' : 'text-white'}`}>{s.value}</p>
            <p className={`text-[10px] md:text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>{s.label}</p>
          </div>
        ))}
      </div>
      {stats.favourite_spot && (
        <div className={`mt-3 p-3 rounded-xl border ${isLight ? 'bg-white/80 border-gray-200' : 'bg-zinc-800/60 border-zinc-700'} flex items-center gap-2`}>
          <MapPin className="w-3.5 h-3.5 text-cyan-400 shrink-0" />
          <span className={`text-xs ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>
            Favourite: <span className={`font-medium ${isLight ? 'text-gray-900' : 'text-white'}`}>{stats.favourite_spot}</span> ({stats.favourite_spot_count}x)
          </span>
        </div>
      )}
    </div>
  );
};

/* ─── Entry Card ────────────────────────────────────────────── */
const EntryCard = ({ entry, isLight, onEdit, onDelete }) => {
  const mood = MOODS.find(m => m.id === entry.mood);
  return (
    <div className={`p-4 rounded-xl border transition-all hover:scale-[1.01] hover:shadow-lg ${isLight ? 'bg-white border-gray-200 shadow-sm hover:shadow-gray-200/50' : 'bg-zinc-800/60 border-zinc-700 hover:border-zinc-600 hover:shadow-cyan-500/5'}`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex items-center gap-2">
          <Calendar className="w-4 h-4 text-cyan-400" />
          <span className={`text-sm font-semibold ${isLight ? 'text-gray-900' : 'text-white'}`}>
            {new Date(entry.session_date + 'T12:00:00').toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
          </span>
          {entry.session_time && <Badge variant="outline" className="text-[10px] py-0">{entry.session_time}</Badge>}
          {mood && <span title={mood.label}>{mood.icon}</span>}
        </div>
        <div className="flex items-center gap-1">
          <button onClick={() => onEdit(entry)} className={`p-1.5 rounded-lg ${isLight ? 'hover:bg-gray-100' : 'hover:bg-zinc-700'}`}><Edit3 className="w-3.5 h-3.5 text-gray-400" /></button>
          <button onClick={() => onDelete(entry.id)} className={`p-1.5 rounded-lg ${isLight ? 'hover:bg-red-50' : 'hover:bg-red-500/10'}`}><Trash2 className="w-3.5 h-3.5 text-red-400" /></button>
        </div>
      </div>

      {entry.spot_name && (
        <div className="flex items-center gap-1.5 mb-2">
          <MapPin className="w-3 h-3 text-cyan-400" />
          <span className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>{entry.spot_name}</span>
        </div>
      )}

      <div className="flex flex-wrap gap-1.5 mb-2">
        {entry.wave_height && <Badge className="bg-blue-500/20 text-blue-400 border-blue-500/30 text-[10px]"><Waves className="w-2.5 h-2.5 mr-0.5" />{entry.wave_height}</Badge>}
        {entry.duration_minutes && <Badge className="bg-purple-500/20 text-purple-400 border-purple-500/30 text-[10px]"><Clock className="w-2.5 h-2.5 mr-0.5" />{entry.duration_minutes}min</Badge>}
        {entry.wind_direction && <Badge className="bg-teal-500/20 text-teal-400 border-teal-500/30 text-[10px]"><Wind className="w-2.5 h-2.5 mr-0.5" />{entry.wind_direction}</Badge>}
        {entry.crowd_level && <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/30 text-[10px]"><Users className="w-2.5 h-2.5 mr-0.5" />{entry.crowd_level}</Badge>}
        {entry.water_temp && <Badge className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 text-[10px]"><Thermometer className="w-2.5 h-2.5 mr-0.5" />{entry.water_temp}</Badge>}
        {entry.board_model && <Badge className="bg-yellow-500/20 text-yellow-400 border-yellow-500/30 text-[10px]">🏄 {entry.board_model}</Badge>}
      </div>

      {entry.personal_rating && (
        <div className="flex items-center gap-0.5 mb-1">
          {[1,2,3,4,5].map(s => <Star key={s} className={`w-3 h-3 ${s <= entry.personal_rating ? 'text-yellow-400 fill-yellow-400' : 'text-gray-600'}`} />)}
        </div>
      )}

      {entry.notes && <p className={`text-xs mt-1 ${isLight ? 'text-gray-600' : 'text-gray-400'} line-clamp-2`}>{entry.notes}</p>}
      {entry.source !== 'manual' && <Badge variant="outline" className="text-[9px] mt-1 py-0">auto: {entry.source}</Badge>}
    </div>
  );
};

/* ─── Create / Edit Modal ───────────────────────────────────── */
const EntryModal = ({ isOpen, onClose, entry, userId, onSaved }) => {
  const { theme } = useTheme();
  const isLight = theme === 'light';
  const bg = isLight ? 'bg-white' : 'bg-zinc-900';
  const inputCls = `w-full px-3 py-2 rounded-lg border text-sm ${isLight ? 'bg-white border-gray-300 text-gray-900' : 'bg-zinc-800 border-zinc-700 text-white'}`;

  const [form, setForm] = useState({
    session_date: new Date().toISOString().split('T')[0],
    session_time: '', duration_minutes: '', spot_name: '',
    wave_height: '', wind_direction: '', tide_status: '', water_temp: '', crowd_level: '',
    board_model: '', wetsuit: '', fin_setup: '',
    notes: '', mood: '', personal_rating: 0, conditions_rating: 0,
  });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (entry) {
      setForm({
        session_date: entry.session_date || new Date().toISOString().split('T')[0],
        session_time: entry.session_time || '', duration_minutes: entry.duration_minutes || '',
        spot_name: entry.spot_name || '', wave_height: entry.wave_height || '',
        wind_direction: entry.wind_direction || '', tide_status: entry.tide_status || '',
        water_temp: entry.water_temp || '', crowd_level: entry.crowd_level || '',
        board_model: entry.board_model || '', wetsuit: entry.wetsuit || '', fin_setup: entry.fin_setup || '',
        notes: entry.notes || '', mood: entry.mood || '',
        personal_rating: entry.personal_rating || 0, conditions_rating: entry.conditions_rating || 0,
      });
    } else {
      setForm(f => ({ ...f, session_date: new Date().toISOString().split('T')[0] }));
    }
  }, [entry, isOpen]);

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handleSave = async () => {
    if (!form.session_date) { toast.error('Session date is required'); return; }
    setSaving(true);
    try {
      const payload = { ...form, duration_minutes: form.duration_minutes ? parseInt(form.duration_minutes, 10) : null };
      if (entry?.id) {
        await apiClient.patch(`/surf-log/${userId}/${entry.id}`, payload);
        toast.success('Entry updated');
      } else {
        await apiClient.post(`/surf-log/${userId}`, payload);
        toast.success('Session logged! 🤙');
      }
      onSaved();
      onClose();
    } catch (err) {
      logger.error('Save surf log entry failed:', err);
      toast.error(err.response?.data?.detail || 'Failed to save entry');
    } finally { setSaving(false); }
  };

  const ChipSelect = ({ options, value, onChange, label }) => (
    <div className="space-y-1">
      <label className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>{label}</label>
      <div className="flex flex-wrap gap-1.5">
        {options.map(o => (
          <button key={o} type="button" onClick={() => onChange(value === o ? '' : o)}
            className={`px-2.5 py-1 rounded-full text-[11px] transition-all ${value === o ? 'bg-cyan-500 text-white' : isLight ? 'bg-gray-100 text-gray-700 hover:bg-gray-200' : 'bg-zinc-800 text-gray-300 hover:bg-zinc-700'}`}>
            {o}
          </button>
        ))}
      </div>
    </div>
  );

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className={`${bg} border-zinc-800 max-w-md md:max-w-lg max-h-[85vh] overflow-y-auto`}>
        <DialogHeader>
          <DialogTitle className={`text-lg font-bold ${isLight ? 'text-gray-900' : 'text-white'} flex items-center gap-2`}>
            <BookOpen className="w-5 h-5 text-cyan-400" />
            {entry ? 'Edit Session' : 'Log a Session'}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Date & Time */}
          <div className="grid grid-cols-2 gap-3">
            <div><label className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>Date *</label><input type="date" value={form.session_date} onChange={e => set('session_date', e.target.value)} className={inputCls} /></div>
            <div>
              <label className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>Time of Day</label>
              <select value={form.session_time} onChange={e => set('session_time', e.target.value)} className={inputCls}>
                <option value="">Select...</option>
                {TIME_OPTIONS.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
          </div>

          {/* Duration & Spot */}
          <div className="grid grid-cols-2 gap-3">
            <div><label className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>Duration (min)</label><input type="number" value={form.duration_minutes} onChange={e => set('duration_minutes', e.target.value)} placeholder="90" className={inputCls} /></div>
            <div><label className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>Spot Name</label><input type="text" value={form.spot_name} onChange={e => set('spot_name', e.target.value)} placeholder="Pipeline" className={inputCls} /></div>
          </div>

          {/* Conditions */}
          <div className={`p-3 rounded-xl ${isLight ? 'bg-blue-50' : 'bg-blue-500/10'} space-y-3`}>
            <p className={`text-xs font-semibold ${isLight ? 'text-blue-700' : 'text-blue-300'} flex items-center gap-1`}><Waves className="w-3.5 h-3.5" /> Conditions</p>
            <div className="grid grid-cols-2 gap-3">
              <div><label className={`text-xs ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>Wave Height</label><input type="text" value={form.wave_height} onChange={e => set('wave_height', e.target.value)} placeholder="3-5ft" className={inputCls} /></div>
              <div><label className={`text-xs ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>Water Temp</label><input type="text" value={form.water_temp} onChange={e => set('water_temp', e.target.value)} placeholder="72°F" className={inputCls} /></div>
            </div>
            <ChipSelect label="Wind" options={WIND_OPTIONS} value={form.wind_direction} onChange={v => set('wind_direction', v)} />
            <ChipSelect label="Tide" options={TIDE_OPTIONS} value={form.tide_status} onChange={v => set('tide_status', v)} />
            <ChipSelect label="Crowd" options={CROWD_LEVELS} value={form.crowd_level} onChange={v => set('crowd_level', v)} />
            <div>
              <label className={`text-xs ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>Conditions Rating</label>
              <div className="flex gap-1 mt-1">{[1,2,3,4,5].map(s => <button key={s} type="button" onClick={() => set('conditions_rating', s)}><Star className={`w-5 h-5 ${s <= form.conditions_rating ? 'text-cyan-400 fill-cyan-400' : 'text-gray-600'}`} /></button>)}</div>
            </div>
          </div>

          {/* Gear */}
          <div className={`p-3 rounded-xl ${isLight ? 'bg-yellow-50' : 'bg-yellow-500/10'} space-y-3`}>
            <p className={`text-xs font-semibold ${isLight ? 'text-yellow-700' : 'text-yellow-300'}`}>🏄 Gear</p>
            <div className="grid grid-cols-2 gap-3">
              <div><label className={`text-xs ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>Board</label><input type="text" value={form.board_model} onChange={e => set('board_model', e.target.value)} placeholder="6'2 shortboard" className={inputCls} /></div>
              <div><label className={`text-xs ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>Wetsuit</label><input type="text" value={form.wetsuit} onChange={e => set('wetsuit', e.target.value)} placeholder="3/2mm" className={inputCls} /></div>
            </div>
          </div>

          {/* Mood & Rating */}
          <div>
            <label className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>Mood</label>
            <div className="flex gap-2 mt-1">
              {MOODS.map(m => (
                <button key={m.id} type="button" onClick={() => set('mood', form.mood === m.id ? '' : m.id)}
                  className={`flex flex-col items-center p-2 rounded-xl transition-all ${form.mood === m.id ? 'bg-cyan-500/20 ring-1 ring-cyan-500' : isLight ? 'hover:bg-gray-100' : 'hover:bg-zinc-800'}`}>
                  <span className="text-lg">{m.icon}</span>
                  <span className={`text-[9px] ${isLight ? 'text-gray-600' : 'text-gray-400'}`}>{m.label}</span>
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>Session Rating</label>
            <div className="flex gap-1 mt-1">{[1,2,3,4,5].map(s => <button key={s} type="button" onClick={() => set('personal_rating', s)}><Star className={`w-6 h-6 ${s <= form.personal_rating ? 'text-yellow-400 fill-yellow-400' : 'text-gray-600'}`} /></button>)}</div>
          </div>

          {/* Notes */}
          <div>
            <label className={`text-xs font-medium ${isLight ? 'text-gray-700' : 'text-gray-300'}`}>Notes</label>
            <textarea value={form.notes} onChange={e => set('notes', e.target.value)} placeholder="How was the session..." rows={3}
              className={`${inputCls} mt-1`} maxLength={1000} />
          </div>

          <Button onClick={handleSave} disabled={saving} className="w-full bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-bold py-3">
            {saving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
            {entry ? 'Update Session' : 'Log Session'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

/* ─── Main SurfLog Page ─────────────────────────────────────── */
const SurfLog = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { theme } = useTheme();
  const t = getThemeTokens(theme);
  const isLight = t.isLight;

  const [entries, setEntries] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editEntry, setEditEntry] = useState(null);

  const fetchData = useCallback(async () => {
    if (!user?.id) return;
    setLoading(true);
    try {
      const [entriesRes, statsRes] = await Promise.allSettled([
        apiClient.get(`/surf-log/${user.id}?limit=100`),
        apiClient.get(`/surf-log/${user.id}/stats`),
      ]);
      if (entriesRes.status === 'fulfilled') setEntries(entriesRes.value.data.entries || []);
      if (statsRes.status === 'fulfilled') setStats(statsRes.value.data);
    } catch (err) {
      logger.error('Failed to fetch surf log:', err);
    } finally { setLoading(false); }
  }, [user?.id]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleDelete = async (entryId) => {
    if (!window.confirm('Delete this session?')) return;
    try {
      await apiClient.delete(`/surf-log/${user.id}/${entryId}`);
      toast.success('Entry deleted');
      fetchData();
    } catch (err) {
      toast.error('Failed to delete');
    }
  };

  const handleEdit = (entry) => { setEditEntry(entry); setModalOpen(true); };
  const handleCreate = () => { setEditEntry(null); setModalOpen(true); };

  return (
    <div className={`max-w-2xl mx-auto pb-24 ${isLight ? 'bg-gray-50/50 min-h-screen' : 'min-h-screen'}`}>
      {/* Header */}
      <div className={`sticky top-0 z-40 backdrop-blur-xl border-b ${isLight ? 'bg-white/90 border-gray-200' : 'bg-zinc-900/95 border-zinc-800'}`}>
        <div className="flex items-center justify-between px-4 py-3">
          <div className="flex items-center gap-3">
            <button onClick={() => navigate(-1)} className={`p-1.5 rounded-full ${isLight ? 'hover:bg-gray-100' : 'hover:bg-zinc-800'} transition-colors md:hidden`}>
              <ChevronLeft className="w-5 h-5" />
            </button>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-cyan-500/20 to-blue-500/20 flex items-center justify-center">
                <BookOpen className="w-4 h-4 text-cyan-400" />
              </div>
              <div>
                <h1 className={`text-lg font-bold ${isLight ? 'text-gray-900' : 'text-white'}`}>Surf Log</h1>
                <p className={`text-[10px] hidden md:block ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>Track your sessions & progress</p>
              </div>
            </div>
          </div>
          <Button size="sm" onClick={handleCreate} className="bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white shadow-lg shadow-cyan-500/20 transition-all hover:shadow-cyan-500/40">
            <Plus className="w-4 h-4 mr-1" /> Log Session
          </Button>
        </div>
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 gap-3">
          <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
          <p className={`text-sm ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>Loading your sessions...</p>
        </div>
      ) : (
        <>
          <div className="mt-4">
            <StatsBanner stats={stats} isLight={isLight} />
          </div>

          {entries.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 px-4 text-center">
              <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-cyan-500/20 to-blue-500/20 flex items-center justify-center mb-5 animate-pulse">
                <BookOpen className="w-10 h-10 text-cyan-400" />
              </div>
              <h3 className={`font-bold text-xl mb-2 ${isLight ? 'text-gray-900' : 'text-white'}`}>No sessions yet</h3>
              <p className={`text-sm mb-6 max-w-xs ${isLight ? 'text-gray-500' : 'text-gray-400'}`}>Start logging your surf sessions to track your progress, conditions, and stoke level.</p>
              <Button onClick={handleCreate} className="bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white px-6 py-3 shadow-lg shadow-cyan-500/20">
                <Plus className="w-4 h-4 mr-1" /> Log Your First Session
              </Button>
            </div>
          ) : (
            <div className="mt-2 px-4 md:px-0">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {entries.map(e => <EntryCard key={e.id} entry={e} isLight={isLight} onEdit={handleEdit} onDelete={handleDelete} />)}
              </div>
            </div>
          )}
        </>
      )}

      <EntryModal isOpen={modalOpen} onClose={() => { setModalOpen(false); setEditEntry(null); }} entry={editEntry} userId={user?.id} onSaved={fetchData} />
    </div>
  );
};

export default SurfLog;

﻿import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  Stamp, Trophy, MapPin, Globe, Calendar, Flame, Award, ChevronRight, 
  X, Users, Target, Sparkles, Navigation, CheckCircle2, AlertCircle,
  Plane, Hotel
} from 'lucide-react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';


// Badge definitions with icons and descriptions
const BADGE_INFO = {
  first_checkin: { icon: '🎯', name: 'First Wave', description: 'Your first check-in!' },
  explorer_10: { icon: '🗺️', name: 'Explorer', description: 'Visited 10 unique spots' },
  globetrotter_5: { icon: '🌍', name: 'Globetrotter', description: 'Surfed in 5 countries' },
  streak_7: { icon: '🔥', name: 'On Fire', description: '7-day check-in streak' },
  dawn_patrol: { icon: '🌅', name: 'Dawn Patrol', description: 'Check-in before 7am' },
  storm_chaser: { icon: '⛈️', name: 'Storm Chaser', description: 'Surfed during large swell' },
};

// Level names
const LEVEL_NAMES = [
  '', 'Grommet', 'Wave Rider', 'Swell Seeker', 'Barrel Hunter', 
  'Reef Master', 'Point Captain', 'Tube Legend', 'Ocean Sage', 
  'Surf Oracle', 'Wave God'
];

export const SurfPassport = ({ isOpen, onClose }) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  
  const [activeTab, setActiveTab] = useState('stamps');
  const [stats, setStats] = useState(null);
  const [visitedSpots, setVisitedSpots] = useState([]);
  const [leaderboard, setLeaderboard] = useState([]);
  const [leaderboardCategory, setLeaderboardCategory] = useState('spots');
  const [loading, setLoading] = useState(true);
  const [checkingIn, setCheckingIn] = useState(false);
  const [nearbySpot, setNearbySpot] = useState(null);
  const [userLocation, setUserLocation] = useState(null);
  const [locationError, setLocationError] = useState(null);

  // Theme classes
  const isLight = theme === 'light';
  const bgClass = isLight ? 'bg-white' : 'bg-zinc-900';
  const textClass = isLight ? 'text-gray-900' : 'text-white';
  const textSecondaryClass = isLight ? 'text-gray-600' : 'text-gray-400';
  const borderClass = isLight ? 'border-gray-200' : 'border-zinc-800';
  const cardBgClass = isLight ? 'bg-gray-50' : 'bg-zinc-800';

  // Fetch passport stats
  const fetchStats = useCallback(async () => {
    if (!user?.id) return;
    try {
      const response = await apiClient.get(`/passport/stats`);
      setStats(response.data);
    } catch (error) {
      logger.error('Failed to fetch passport stats:', error);
    }
  }, [user?.id]);

  // Fetch visited spots
  const fetchVisitedSpots = useCallback(async () => {
    if (!user?.id) return;
    try {
      const response = await apiClient.get(`/passport/visited-spots`);
      setVisitedSpots(response.data.visited_spots || []);
    } catch (error) {
      logger.error('Failed to fetch visited spots:', error);
    }
  }, [user?.id]);

  // Fetch leaderboard
  const fetchLeaderboard = useCallback(async () => {
    try {
      const response = await apiClient.get(`/passport/leaderboard?category=${leaderboardCategory}&limit=20`);
      setLeaderboard(response.data.leaderboard || []);
    } catch (error) {
      logger.error('Failed to fetch leaderboard:', error);
    }
  }, [leaderboardCategory]);

  // Get user's current location
  const getUserLocation = useCallback(() => {
    if (!navigator.geolocation) {
      setLocationError('Geolocation not supported');
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setUserLocation({
          latitude: position.coords.latitude,
          longitude: position.coords.longitude
        });
        setLocationError(null);
      },
      (error) => {
        setLocationError('Unable to get location. Please enable GPS.');
        logger.error('Geolocation error:', error);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, []);

  // Check for nearby spots
  const checkNearbySpots = useCallback(async () => {
    if (!userLocation) return;
    
    try {
      // Get all spots and find the closest one
      const response = await apiClient.get(`/surf-spots`);
      const spots = response.data;
      
      let closestSpot = null;
      let minDistance = Infinity;
      
      for (const spot of spots) {
        const distance = calculateDistance(
          userLocation.latitude, userLocation.longitude,
          parseFloat(spot.latitude), parseFloat(spot.longitude)
        );
        
        if (distance < minDistance) {
          minDistance = distance;
          closestSpot = { ...spot, distance: Math.round(distance) };
        }
      }
      
      if (closestSpot && closestSpot.distance <= 500) {
        setNearbySpot(closestSpot);
      } else if (closestSpot) {
        setNearbySpot({ ...closestSpot, tooFar: true });
      }
    } catch (error) {
      logger.error('Failed to check nearby spots:', error);
    }
  }, [userLocation]);

  // Calculate distance using Haversine formula
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371000; // Earth's radius in meters
    const phi1 = lat1 * Math.PI / 180;
    const phi2 = lat2 * Math.PI / 180;
    const deltaPhi = (lat2 - lat1) * Math.PI / 180;
    const deltaLambda = (lon2 - lon1) * Math.PI / 180;
    
    const a = Math.sin(deltaPhi/2) * Math.sin(deltaPhi/2) +
              Math.cos(phi1) * Math.cos(phi2) *
              Math.sin(deltaLambda/2) * Math.sin(deltaLambda/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    
    return R * c;
  };

  // Handle check-in
  const handleCheckIn = async () => {
    if (!nearbySpot || nearbySpot.tooFar || !userLocation || !user?.id) return;
    
    setCheckingIn(true);
    try {
      const response = await apiClient.post(`/passport/checkin`, {
        spot_id: nearbySpot.id,
        latitude: userLocation.latitude,
        longitude: userLocation.longitude
      });
      
      if (response.data.success) {
        // Refresh stats
        await fetchStats();
        await fetchVisitedSpots();
        
        // Show success message (could use toast)
        alert(`${response.data.message}\n\n+${response.data.xp_earned} XP earned!${response.data.badge_earned ? `\n\nBadge earned: ${BADGE_INFO[response.data.badge_earned]?.name || response.data.badge_earned}` : ''}`);
      }
    } catch (error) {
      logger.error('Check-in failed:', error);
      alert('Check-in failed. Please try again.');
    } finally {
      setCheckingIn(false);
    }
  };

  // Initial data fetch
  useEffect(() => {
    if (isOpen && user?.id) {
      setLoading(true);
      Promise.all([fetchStats(), fetchVisitedSpots(), fetchLeaderboard()])
        .finally(() => setLoading(false));
      getUserLocation();
    }
  }, [isOpen, user?.id, fetchStats, fetchVisitedSpots, fetchLeaderboard, getUserLocation]);

  // Check nearby spots when location updates
  useEffect(() => {
    if (userLocation) {
      checkNearbySpots();
    }
  }, [userLocation, checkNearbySpots]);

  // Refetch leaderboard when category changes
  useEffect(() => {
    if (isOpen) {
      fetchLeaderboard();
    }
  }, [leaderboardCategory, isOpen, fetchLeaderboard]);

  if (!isOpen) return null;

  const xpProgress = stats ? (stats.total_xp_earned / (stats.total_xp_earned + (stats.xp_to_next_level || 1))) * 100 : 0;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 pb-24 md:pb-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />
      
      {/* Modal */}
      <div className={`relative w-full max-w-2xl max-h-[85vh] md:max-h-[90vh] ${bgClass} rounded-2xl shadow-2xl overflow-hidden flex flex-col`}>
        {/* Header */}
        <div className={`p-6 border-b ${borderClass} bg-gradient-to-r from-emerald-500/20 to-yellow-500/20`}>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-full bg-gradient-to-r from-emerald-400 to-yellow-400 flex items-center justify-center">
                <Stamp className="w-6 h-6 text-black" />
              </div>
              <div>
                <h2 className={`text-xl font-bold ${textClass}`}>Surf Passport</h2>
                <p className={`text-sm ${textSecondaryClass}`}>Collect stamps from spots around the world</p>
              </div>
            </div>
            <button 
              onClick={onClose}
              className={`p-2 rounded-lg ${isLight ? 'hover:bg-gray-100' : 'hover:bg-zinc-800'} transition-colors`}
            >
              <X className="w-5 h-5" />
            </button>
          </div>
          
          {/* Level & XP Bar */}
          {stats && (
            <div className="mt-4">
              <div className="flex items-center justify-between mb-2">
                <span className={`text-sm font-medium ${textClass}`}>
                  Level {stats.passport_level}: {LEVEL_NAMES[stats.passport_level] || 'Legend'}
                </span>
                <span className={`text-sm ${textSecondaryClass}`}>
                  {stats.total_xp_earned.toLocaleString()} XP
                </span>
              </div>
              <div className={`h-2 rounded-full ${isLight ? 'bg-gray-200' : 'bg-zinc-700'}`}>
                <div 
                  className="h-full rounded-full bg-gradient-to-r from-emerald-400 to-yellow-400 transition-all duration-500"
                  style={{ width: `${xpProgress}%` }}
                />
              </div>
              <p className={`text-xs ${textSecondaryClass} mt-1`}>
                {stats.xp_to_next_level?.toLocaleString() || 0} XP to next level
              </p>
            </div>
          )}
        </div>

        {/* GPS Check-In Banner */}
        <div className={`px-6 py-4 border-b ${borderClass} ${cardBgClass}`}>
          {locationError ? (
            <div className="flex items-center gap-3 text-amber-500">
              <AlertCircle className="w-5 h-5" />
              <span className="text-sm">{locationError}</span>
              <button 
                onClick={getUserLocation}
                className="ml-auto text-xs bg-amber-500/20 px-3 py-1 rounded-full hover:bg-amber-500/30"
              >
                Retry
              </button>
            </div>
          ) : nearbySpot ? (
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${nearbySpot.tooFar ? 'bg-amber-500/20' : 'bg-emerald-500/20'}`}>
                  <Navigation className={`w-5 h-5 ${nearbySpot.tooFar ? 'text-amber-500' : 'text-emerald-500'}`} />
                </div>
                <div>
                  <p className={`text-sm font-medium ${textClass}`}>{nearbySpot.name}</p>
                  <p className={`text-xs ${textSecondaryClass}`}>
                    {nearbySpot.distance}m away • {nearbySpot.country}
                  </p>
                </div>
              </div>
              {nearbySpot.tooFar ? (
                <span className="text-xs text-amber-500 bg-amber-500/20 px-3 py-1.5 rounded-full">
                  Get within 500m
                </span>
              ) : (
                <button
                  onClick={handleCheckIn}
                  disabled={checkingIn}
                  className="flex items-center gap-2 bg-gradient-to-r from-emerald-400 to-yellow-400 text-black text-sm font-medium px-4 py-2 rounded-full hover:opacity-90 transition-opacity disabled:opacity-50"
                >
                  <CheckCircle2 className="w-4 h-4" />
                  {checkingIn ? 'Checking in...' : 'Check In'}
                </button>
              )}
            </div>
          ) : (
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-blue-500/20 flex items-center justify-center animate-pulse">
                <Navigation className="w-5 h-5 text-blue-500" />
              </div>
              <span className={`text-sm ${textSecondaryClass}`}>Scanning for nearby surf spots...</span>
            </div>
          )}
        </div>

        {/* Tabs */}
        <div className={`flex border-b ${borderClass}`}>
          {[
            { id: 'stamps', label: 'My Stamps', icon: Stamp },
            { id: 'leaderboard', label: 'Leaderboard', icon: Trophy },
            { id: 'travel', label: 'Travel', icon: Plane },
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-1 flex items-center justify-center gap-2 py-3 text-sm font-medium transition-colors ${
                activeTab === tab.id 
                  ? 'text-emerald-500 border-b-2 border-emerald-500' 
                  : `${textSecondaryClass} hover:text-emerald-400`
              }`}
            >
              <tab.icon className="w-4 h-4" />
              {tab.label}
            </button>
          ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : activeTab === 'stamps' ? (
            <div className="space-y-6">
              {/* Stats Grid */}
              {stats && (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className={`${cardBgClass} rounded-xl p-4 text-center`}>
                    <MapPin className="w-6 h-6 mx-auto mb-2 text-emerald-400" />
                    <p className={`text-2xl font-bold ${textClass}`}>{stats.unique_spots_visited}</p>
                    <p className={`text-xs ${textSecondaryClass}`}>Spots Visited</p>
                  </div>
                  <div className={`${cardBgClass} rounded-xl p-4 text-center`}>
                    <Globe className="w-6 h-6 mx-auto mb-2 text-blue-400" />
                    <p className={`text-2xl font-bold ${textClass}`}>{stats.unique_countries_visited}</p>
                    <p className={`text-xs ${textSecondaryClass}`}>Countries</p>
                  </div>
                  <div className={`${cardBgClass} rounded-xl p-4 text-center`}>
                    <Calendar className="w-6 h-6 mx-auto mb-2 text-purple-400" />
                    <p className={`text-2xl font-bold ${textClass}`}>{stats.total_checkins}</p>
                    <p className={`text-xs ${textSecondaryClass}`}>Total Check-ins</p>
                  </div>
                  <div className={`${cardBgClass} rounded-xl p-4 text-center`}>
                    <Flame className="w-6 h-6 mx-auto mb-2 text-orange-400" />
                    <p className={`text-2xl font-bold ${textClass}`}>{stats.current_streak_days}</p>
                    <p className={`text-xs ${textSecondaryClass}`}>Day Streak</p>
                  </div>
                </div>
              )}

              {/* Badges */}
              {stats?.badges_earned?.length > 0 && (
                <div>
                  <h3 className={`text-sm font-medium ${textClass} mb-3 flex items-center gap-2`}>
                    <Award className="w-4 h-4 text-yellow-400" />
                    Badges Earned
                  </h3>
                  <div className="flex flex-wrap gap-2">
                    {stats.badges_earned.map(badge => (
                      <div 
                        key={badge}
                        className={`${cardBgClass} px-3 py-2 rounded-lg flex items-center gap-2`}
                        title={BADGE_INFO[badge]?.description}
                      >
                        <span className="text-xl">{BADGE_INFO[badge]?.icon || '🏅'}</span>
                        <span className={`text-sm ${textClass}`}>{BADGE_INFO[badge]?.name || badge}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Recent Stamps */}
              <div>
                <h3 className={`text-sm font-medium ${textClass} mb-3 flex items-center gap-2`}>
                  <Stamp className="w-4 h-4 text-emerald-400" />
                  Recent Stamps ({visitedSpots.length} spots)
                </h3>
                {visitedSpots.length > 0 ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    {visitedSpots.slice(0, 10).map(spot => (
                      <div 
                        key={spot.spot_id}
                        className={`${cardBgClass} rounded-xl p-4 flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity`}
                        onClick={() => {
                          onClose();
                          navigate(`/map?spot=${spot.spot_id}`);
                        }}
                      >
                        <div className="w-12 h-12 rounded-full bg-gradient-to-br from-emerald-400/30 to-yellow-400/30 flex items-center justify-center flex-shrink-0">
                          <span className="text-2xl">🏄</span>
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className={`text-sm font-medium ${textClass} truncate`}>{spot.spot_name}</p>
                          <p className={`text-xs ${textSecondaryClass}`}>{spot.country} • {spot.region}</p>
                          <p className={`text-xs text-emerald-500`}>
                            {spot.visit_count}x visited • +{spot.total_xp_earned} XP
                          </p>
                        </div>
                        <ChevronRight className={`w-4 h-4 ${textSecondaryClass}`} />
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className={`${cardBgClass} rounded-xl p-8 text-center`}>
                    <Stamp className={`w-12 h-12 mx-auto mb-3 ${textSecondaryClass}`} />
                    <p className={`${textClass} font-medium`}>No stamps yet</p>
                    <p className={`text-sm ${textSecondaryClass} mt-1`}>
                      Visit a surf spot and check in to collect your first stamp!
                    </p>
                  </div>
                )}
              </div>

              {/* Country Breakdown */}
              {stats?.countries_breakdown && Object.keys(stats.countries_breakdown).length > 0 && (
                <div>
                  <h3 className={`text-sm font-medium ${textClass} mb-3 flex items-center gap-2`}>
                    <Globe className="w-4 h-4 text-blue-400" />
                    Countries Visited
                  </h3>
                  <div className="flex flex-wrap gap-2">
                    {Object.entries(stats.countries_breakdown)
                      .sort((a, b) => b[1] - a[1])
                      .map(([country, count]) => (
                        <div 
                          key={country}
                          className={`${cardBgClass} px-3 py-1.5 rounded-full flex items-center gap-2`}
                        >
                          <span className={`text-sm ${textClass}`}>{country}</span>
                          <span className={`text-xs ${textSecondaryClass}`}>({count})</span>
                        </div>
                      ))}
                  </div>
                </div>
              )}
            </div>
          ) : activeTab === 'leaderboard' ? (
            <div className="space-y-4">
              {/* Category Tabs */}
              <div className={`flex gap-2 p-1 rounded-lg ${cardBgClass}`}>
                {[
                  { id: 'spots', label: 'Spots' },
                  { id: 'countries', label: 'Countries' },
                  { id: 'xp', label: 'XP' },
                  { id: 'streak', label: 'Streak' },
                ].map(cat => (
                  <button
                    key={cat.id}
                    onClick={() => setLeaderboardCategory(cat.id)}
                    className={`flex-1 py-2 text-sm font-medium rounded-md transition-colors ${
                      leaderboardCategory === cat.id 
                        ? 'bg-emerald-500 text-black' 
                        : `${textSecondaryClass} hover:text-emerald-400`
                    }`}
                  >
                    {cat.label}
                  </button>
                ))}
              </div>

              {/* Leaderboard List */}
              <div className="space-y-2">
                {leaderboard.length > 0 ? (
                  leaderboard.map((entry, index) => (
                    <div 
                      key={entry.user_id}
                      className={`${cardBgClass} rounded-xl p-4 flex items-center gap-4 ${entry.user_id === user?.id ? 'ring-2 ring-emerald-500' : ''}`}
                    >
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold ${
                        index === 0 ? 'bg-yellow-500 text-black' :
                        index === 1 ? 'bg-gray-400 text-black' :
                        index === 2 ? 'bg-amber-600 text-white' :
                        `${isLight ? 'bg-gray-200 text-gray-600' : 'bg-zinc-700 text-gray-400'}`
                      }`}>
                        {index + 1}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className={`text-sm font-medium ${textClass} truncate`}>{entry.full_name}</p>
                        <p className={`text-xs ${textSecondaryClass}`}>
                          Level {entry.passport_level} • {entry.unique_spots_visited} spots • {entry.unique_countries_visited} countries
                        </p>
                      </div>
                      <div className="text-right">
                        <p className={`text-lg font-bold ${textClass}`}>
                          {leaderboardCategory === 'spots' && entry.unique_spots_visited}
                          {leaderboardCategory === 'countries' && entry.unique_countries_visited}
                          {leaderboardCategory === 'xp' && entry.total_xp_earned.toLocaleString()}
                          {leaderboardCategory === 'streak' && entry.longest_streak_days}
                        </p>
                        <p className={`text-xs ${textSecondaryClass}`}>
                          {leaderboardCategory === 'spots' && 'spots'}
                          {leaderboardCategory === 'countries' && 'countries'}
                          {leaderboardCategory === 'xp' && 'XP'}
                          {leaderboardCategory === 'streak' && 'days'}
                        </p>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className={`${cardBgClass} rounded-xl p-8 text-center`}>
                    <Trophy className={`w-12 h-12 mx-auto mb-3 ${textSecondaryClass}`} />
                    <p className={`${textClass} font-medium`}>No rankings yet</p>
                    <p className={`text-sm ${textSecondaryClass} mt-1`}>
                      Be the first to check in and claim the top spot!
                    </p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            /* Travel Tab - Coming Soon */
            <div className={`${cardBgClass} rounded-xl p-8 text-center`}>
              <div className="w-16 h-16 rounded-full bg-gradient-to-r from-emerald-400/20 to-yellow-400/20 mx-auto mb-4 flex items-center justify-center">
                <Plane className="w-8 h-8 text-emerald-400" />
              </div>
              <h3 className={`text-lg font-bold ${textClass} mb-2`}>Surf Travel Hub</h3>
              <p className={`text-sm ${textSecondaryClass} mb-4`}>
                Book surf retreats, lodges, and guided trips from verified hosts around the world.
              </p>
              <div className="flex flex-wrap justify-center gap-3">
                <div className={`flex items-center gap-2 px-4 py-2 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-700'}`}>
                  <Hotel className="w-4 h-4 text-emerald-400" />
                  <span className={`text-sm ${textSecondaryClass}`}>Surf Lodges</span>
                </div>
                <div className={`flex items-center gap-2 px-4 py-2 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-700'}`}>
                  <Users className="w-4 h-4 text-blue-400" />
                  <span className={`text-sm ${textSecondaryClass}`}>Group Retreats</span>
                </div>
                <div className={`flex items-center gap-2 px-4 py-2 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-700'}`}>
                  <Target className="w-4 h-4 text-purple-400" />
                  <span className={`text-sm ${textSecondaryClass}`}>Guided Trips</span>
                </div>
              </div>
              <p className={`text-xs ${textSecondaryClass} mt-6`}>
                <Sparkles className="w-3 h-3 inline mr-1" />
                Coming Soon
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SurfPassport;

﻿/**
 * SurfboardsTab - Display and manage user's surfboard quiver
 * Features:
 * - Grid display of surfboards with photos
 * - Add/Edit surfboard modal
 * - Photo upload (up to 5 per board)
 * - Dimensions, brand, condition tracking
 * - Future: Marketplace listing integration
 */

import React, { useState, useEffect } from 'react';
import { useTheme } from '../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import {
  Plus, Edit2, Trash2, X, Loader2, ChevronLeft, ChevronRight,
  Ruler, Calendar, Waves
} from 'lucide-react';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Textarea } from './ui/textarea';
import { Label } from './ui/label';
import { Badge } from './ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import { toast } from 'sonner';
import logger from '../utils/logger';


// Board type options
const BOARD_TYPES = [
  { value: 'shortboard', label: 'Shortboard' },
  { value: 'longboard', label: 'Longboard' },
  { value: 'funboard', label: 'Funboard' },
  { value: 'fish', label: 'Fish' },
  { value: 'gun', label: 'Gun' },
  { value: 'hybrid', label: 'Hybrid' },
  { value: 'mini_mal', label: 'Mini Mal' },
  { value: 'foamie', label: 'Soft Top / Foamie' },
  { value: 'sup', label: 'SUP' },
  { value: 'other', label: 'Other' }
];

// Fin setup options
const FIN_SETUPS = [
  { value: 'thruster', label: 'Thruster (3 fin)' },
  { value: 'quad', label: 'Quad (4 fin)' },
  { value: 'twin', label: 'Twin Fin' },
  { value: 'single', label: 'Single Fin' },
  { value: '2_plus_1', label: '2+1' },
  { value: 'five', label: '5 Fin' },
  { value: 'finless', label: 'Finless' }
];

// Condition options
const CONDITIONS = [
  { value: 'mint', label: 'Mint', color: 'text-green-400' },
  { value: 'excellent', label: 'Excellent', color: 'text-cyan-400' },
  { value: 'good', label: 'Good', color: 'text-blue-400' },
  { value: 'fair', label: 'Fair', color: 'text-yellow-400' },
  { value: 'needs_repair', label: 'Needs Repair', color: 'text-red-400' }
];

// Surfboard Card Component
const SurfboardCard = ({ board, onClick, isLight }) => {
  const primaryPhoto = board.photo_urls?.[board.primary_photo_index || 0];
  const conditionInfo = CONDITIONS.find(c => c.value === board.condition);
  
  return (
    <div 
      onClick={onClick}
      className={`relative aspect-[3/4] rounded-xl overflow-hidden cursor-pointer group transition-all hover:scale-[1.02] ${
        isLight ? 'bg-gray-100' : 'bg-zinc-800'
      }`}
    >
      {primaryPhoto ? (
        <img 
          src={primaryPhoto} 
          alt={board.name || 'Surfboard'} 
          className="w-full h-full object-cover"
        />
      ) : (
        <div className="w-full h-full flex items-center justify-center">
          <Waves className={`w-12 h-12 ${isLight ? 'text-gray-300' : 'text-zinc-600'}`} />
        </div>
      )}
      
      {/* Overlay */}
      <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
      
      {/* Info overlay */}
      <div className="absolute bottom-0 left-0 right-0 p-3 translate-y-full group-hover:translate-y-0 transition-transform">
        <p className="text-white font-medium text-sm truncate">
          {board.brand || 'Unknown'} {board.model || ''}
        </p>
        {board.dimensions_display && (
          <p className="text-gray-300 text-xs">{board.dimensions_display}</p>
        )}
        {conditionInfo && (
          <Badge className={`mt-1 ${conditionInfo.color} bg-black/50 text-xs`}>
            {conditionInfo.label}
          </Badge>
        )}
      </div>
      
      {/* Photo count badge */}
      {board.photo_urls?.length > 1 && (
        <div className="absolute top-2 right-2 bg-black/60 px-2 py-0.5 rounded-full">
          <span className="text-white text-xs">{board.photo_urls.length}</span>
        </div>
      )}
    </div>
  );
};

// Add/Edit Surfboard Modal
const SurfboardModal = ({ isOpen, onClose, board, onSave, userId }) => {
  const { theme } = useTheme();
  const isLight = theme === 'light';
  const isEditing = !!board?.id;
  
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    brand: '',
    model: '',
    length_feet: '',
    length_inches: '',
    width_inches: '',
    thickness_inches: '',
    volume_liters: '',
    board_type: '',
    fin_setup: '',
    condition: '',
    description: '',
    year_acquired: '',
    photo_urls: []
  });
  
  // Reset form when modal opens
  useEffect(() => {
    if (isOpen) {
      if (board) {
        setFormData({
          name: board.name || '',
          brand: board.brand || '',
          model: board.model || '',
          length_feet: board.length_feet || '',
          length_inches: board.length_inches || '',
          width_inches: board.width_inches || '',
          thickness_inches: board.thickness_inches || '',
          volume_liters: board.volume_liters || '',
          board_type: board.board_type || '',
          fin_setup: board.fin_setup || '',
          condition: board.condition || '',
          description: board.description || '',
          year_acquired: board.year_acquired || '',
          photo_urls: board.photo_urls || []
        });
      } else {
        setFormData({
          name: '', brand: '', model: '', length_feet: '', length_inches: '',
          width_inches: '', thickness_inches: '', volume_liters: '', board_type: '',
          fin_setup: '', condition: '', description: '', year_acquired: '', photo_urls: []
        });
      }
    }
  }, [isOpen, board]);
  
  const handlePhotoUpload = async (e) => {
    const files = Array.from(e.target.files);
    if (formData.photo_urls.length + files.length > 5) {
      toast.error('Maximum 5 photos allowed');
      return;
    }
    
    setUploading(true);
    try {
      for (const file of files) {
        const uploadFormData = new FormData();
        uploadFormData.append('file', file);
        
        const response = await apiClient.post(`/upload`, uploadFormData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        
        if (response.data.url) {
          setFormData(prev => ({
            ...prev,
            photo_urls: [...prev.photo_urls, response.data.url]
          }));
        }
      }
      toast.success('Photo uploaded!');
    } catch (error) {
      toast.error('Failed to upload photo');
    } finally {
      setUploading(false);
    }
  };
  
  const handleRemovePhoto = (index) => {
    setFormData(prev => ({
      ...prev,
      photo_urls: prev.photo_urls.filter((_, i) => i !== index)
    }));
  };
  
  const handleSubmit = async () => {
    setLoading(true);
    try {
      const payload = {
        ...formData,
        length_feet: formData.length_feet ? parseInt(formData.length_feet) : null,
        length_inches: formData.length_inches ? parseInt(formData.length_inches) : null,
        width_inches: formData.width_inches ? parseFloat(formData.width_inches) : null,
        thickness_inches: formData.thickness_inches ? parseFloat(formData.thickness_inches) : null,
        volume_liters: formData.volume_liters ? parseFloat(formData.volume_liters) : null,
        year_acquired: formData.year_acquired ? parseInt(formData.year_acquired) : null
      };
      
      if (isEditing) {
        await apiClient.patch(`/surfboards/${board.id}`, payload);
        toast.success('Surfboard updated!');
      } else {
        await apiClient.post(`/surfboards/`, payload);
        toast.success('Surfboard added to your quiver!');
      }
      
      onSave();
      onClose();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to save surfboard');
    } finally {
      setLoading(false);
    }
  };
  
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const inputBg = isLight ? 'bg-white border-gray-300' : 'bg-zinc-800 border-zinc-700';
  
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className={`${isLight ? 'bg-white' : 'bg-zinc-900'} border-zinc-800 max-w-lg p-0 flex flex-col`}>
        {/* Fixed Header */}
        <DialogHeader className="p-4 pb-2 border-b border-zinc-800 flex-shrink-0">
          <DialogTitle className={`text-xl font-bold ${textPrimary} flex items-center gap-2`}>
            <Waves className="w-5 h-5 text-cyan-400" />
            {isEditing ? 'Edit Surfboard' : 'Add to Quiver'}
          </DialogTitle>
        </DialogHeader>
        
        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 min-h-0">
          {/* Photo Upload Section */}
          <div>
            <Label className={textPrimary}>Photos (up to 5)</Label>
            <div className="grid grid-cols-5 gap-2 mt-2">
              {formData.photo_urls.map((url, idx) => (
                <div key={idx} className="relative aspect-square rounded-lg overflow-hidden group">
                  <img src={url} alt="" className="w-full h-full object-cover" />
                  <button
                    onClick={() => handleRemovePhoto(idx)}
                    className="absolute top-1 right-1 w-5 h-5 rounded-full bg-red-500 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </div>
              ))}
              {formData.photo_urls.length < 5 && (
                <label className={`aspect-square rounded-lg border-2 border-dashed ${isLight ? 'border-gray-300 hover:border-cyan-400' : 'border-zinc-700 hover:border-cyan-500'} flex items-center justify-center cursor-pointer transition-colors`}>
                  {uploading ? (
                    <Loader2 className="w-6 h-6 animate-spin text-cyan-400" />
                  ) : (
                    <Plus className={`w-6 h-6 ${isLight ? 'text-gray-400' : 'text-zinc-500'}`} />
                  )}
                  <input
                    type="file"
                    accept="image/*"
                    multiple
                    onChange={handlePhotoUpload}
                    className="hidden"
                    disabled={uploading}
                  />
                </label>
              )}
            </div>
          </div>
          
          {/* Brand & Model */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <Label className={textPrimary}>Brand / Shaper</Label>
              <Input
                value={formData.brand}
                onChange={(e) => setFormData(p => ({ ...p, brand: e.target.value }))}
                placeholder="e.g. Channel Islands"
                className={inputBg}
              />
            </div>
            <div>
              <Label className={textPrimary}>Model</Label>
              <Input
                value={formData.model}
                onChange={(e) => setFormData(p => ({ ...p, model: e.target.value }))}
                placeholder="e.g. Sampler"
                className={inputBg}
              />
            </div>
          </div>
          
          {/* Dimensions */}
          <div>
            <Label className={textPrimary}>Dimensions</Label>
            <div className="grid grid-cols-5 gap-2 mt-2">
              <div className="col-span-1">
                <Input
                  type="number"
                  value={formData.length_feet}
                  onChange={(e) => setFormData(p => ({ ...p, length_feet: e.target.value }))}
                  placeholder="5"
                  className={inputBg}
                />
                <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'} text-center mt-1`}>ft</p>
              </div>
              <div className="col-span-1">
                <Input
                  type="number"
                  value={formData.length_inches}
                  onChange={(e) => setFormData(p => ({ ...p, length_inches: e.target.value }))}
                  placeholder="10"
                  className={inputBg}
                />
                <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'} text-center mt-1`}>in</p>
              </div>
              <div className="col-span-1">
                <Input
                  type="number"
                  step="0.25"
                  value={formData.width_inches}
                  onChange={(e) => setFormData(p => ({ ...p, width_inches: e.target.value }))}
                  placeholder="19.5"
                  className={inputBg}
                />
                <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'} text-center mt-1`}>width</p>
              </div>
              <div className="col-span-1">
                <Input
                  type="number"
                  step="0.125"
                  value={formData.thickness_inches}
                  onChange={(e) => setFormData(p => ({ ...p, thickness_inches: e.target.value }))}
                  placeholder="2.5"
                  className={inputBg}
                />
                <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'} text-center mt-1`}>thick</p>
              </div>
              <div className="col-span-1">
                <Input
                  type="number"
                  step="0.1"
                  value={formData.volume_liters}
                  onChange={(e) => setFormData(p => ({ ...p, volume_liters: e.target.value }))}
                  placeholder="28.5"
                  className={inputBg}
                />
                <p className={`text-xs ${isLight ? 'text-gray-500' : 'text-gray-400'} text-center mt-1`}>liters</p>
              </div>
            </div>
          </div>
          
          {/* Board Type & Fin Setup */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <Label className={textPrimary}>Board Type</Label>
              <Select value={formData.board_type} onValueChange={(v) => setFormData(p => ({ ...p, board_type: v }))}>
                <SelectTrigger className={inputBg}>
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent className={isLight ? 'bg-white' : 'bg-zinc-900'}>
                  {BOARD_TYPES.map(t => (
                    <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className={textPrimary}>Fin Setup</Label>
              <Select value={formData.fin_setup} onValueChange={(v) => setFormData(p => ({ ...p, fin_setup: v }))}>
                <SelectTrigger className={inputBg}>
                  <SelectValue placeholder="Select fins" />
                </SelectTrigger>
                <SelectContent className={isLight ? 'bg-white' : 'bg-zinc-900'}>
                  {FIN_SETUPS.map(f => (
                    <SelectItem key={f.value} value={f.value}>{f.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          
          {/* Condition */}
          <div>
            <Label className={textPrimary}>Condition</Label>
            <Select value={formData.condition} onValueChange={(v) => setFormData(p => ({ ...p, condition: v }))}>
              <SelectTrigger className={inputBg}>
                <SelectValue placeholder="Select condition" />
              </SelectTrigger>
              <SelectContent className={isLight ? 'bg-white' : 'bg-zinc-900'}>
                {CONDITIONS.map(c => (
                  <SelectItem key={c.value} value={c.value}>
                    <span className={c.color}>{c.label}</span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          
          {/* Description */}
          <div>
            <Label className={textPrimary}>Notes / Description</Label>
            <Textarea
              value={formData.description}
              onChange={(e) => setFormData(p => ({ ...p, description: e.target.value }))}
              placeholder="Any notes about this board..."
              className={inputBg}
              rows={2}
            />
          </div>
          
          {/* Year */}
          <div>
            <Label className={textPrimary}>Year Acquired</Label>
            <Input
              type="number"
              value={formData.year_acquired}
              onChange={(e) => setFormData(p => ({ ...p, year_acquired: e.target.value }))}
              placeholder="2024"
              className={`${inputBg} w-24`}
            />
          </div>
        </div>
        
        {/* Fixed Footer */}
        <DialogFooter className="p-4 pt-2 border-t border-zinc-800 flex-shrink-0 gap-2">
          <Button variant="outline" onClick={onClose} className="flex-1 sm:flex-none">Cancel</Button>
          <Button 
            onClick={handleSubmit}
            disabled={loading}
            className="flex-1 sm:flex-none bg-gradient-to-r from-cyan-500 to-blue-600"
          >
            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : isEditing ? 'Save Changes' : 'Add Board'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

// View Surfboard Detail Modal
const SurfboardDetailModal = ({ isOpen, onClose, board, onEdit, onDelete, isOwnProfile, userId }) => {
  const { theme } = useTheme();
  const isLight = theme === 'light';
  const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);
  const [deleteConfirm, setDeleteConfirm] = useState(false);
  const [deleting, setDeleting] = useState(false);
  
  useEffect(() => {
    if (isOpen) {
      setCurrentPhotoIndex(board?.primary_photo_index || 0);
      setDeleteConfirm(false);
    }
  }, [isOpen, board]);
  
  const handleDelete = async () => {
    setDeleting(true);
    try {
      await apiClient.delete(`/surfboards/${board.id}`);
      toast.success('Surfboard removed from quiver');
      onDelete();
      onClose();
    } catch (error) {
      toast.error('Failed to delete surfboard');
    } finally {
      setDeleting(false);
    }
  };
  
  const photos = board?.photo_urls || [];
  const conditionInfo = CONDITIONS.find(c => c.value === board?.condition);
  const boardTypeInfo = BOARD_TYPES.find(t => t.value === board?.board_type);
  const finInfo = FIN_SETUPS.find(f => f.value === board?.fin_setup);
  
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-500' : 'text-gray-400';
  
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className={`${isLight ? 'bg-white' : 'bg-zinc-900'} border-zinc-800 max-w-lg p-0 overflow-hidden`}>
        <DialogTitle className="sr-only">Surfboard Detail</DialogTitle>
        {/* Photo Gallery */}
        <div className="relative aspect-[4/3] bg-black">
          {photos.length > 0 ? (
            <img 
              src={photos[currentPhotoIndex]} 
              alt="" 
              className="w-full h-full object-contain"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center">
              <Waves className="w-16 h-16 text-zinc-700" />
            </div>
          )}
          
          {/* Photo Navigation */}
          {photos.length > 1 && (
            <>
              <button
                onClick={() => setCurrentPhotoIndex(i => (i - 1 + photos.length) % photos.length)}
                className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-black/50 text-white flex items-center justify-center"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <button
                onClick={() => setCurrentPhotoIndex(i => (i + 1) % photos.length)}
                className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-black/50 text-white flex items-center justify-center"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
              <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex gap-1">
                {photos.map((_, idx) => (
                  <button
                    key={idx}
                    onClick={() => setCurrentPhotoIndex(idx)}
                    className={`w-2 h-2 rounded-full ${currentPhotoIndex === idx ? 'bg-white' : 'bg-white/50'}`}
                  />
                ))}
              </div>
            </>
          )}
          
          {/* Close button */}
          <button
            onClick={onClose}
            className="absolute top-2 right-2 w-8 h-8 rounded-full bg-black/50 text-white flex items-center justify-center"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
        
        {/* Board Info */}
        <div className="p-4 space-y-4">
          {/* Header */}
          <div>
            <h3 className={`text-xl font-bold ${textPrimary}`}>
              {board?.brand || 'Unknown Brand'} {board?.model || ''}
            </h3>
            {board?.dimensions_display && (
              <p className={`${textSecondary} flex items-center gap-1`}>
                <Ruler className="w-4 h-4" />
                {board.dimensions_display}
              </p>
            )}
          </div>
          
          {/* Tags */}
          <div className="flex flex-wrap gap-2">
            {boardTypeInfo && (
              <Badge className="bg-cyan-500/20 text-cyan-400">{boardTypeInfo.label}</Badge>
            )}
            {finInfo && (
              <Badge className="bg-purple-500/20 text-purple-400">{finInfo.label}</Badge>
            )}
            {conditionInfo && (
              <Badge className={`bg-zinc-800 ${conditionInfo.color}`}>{conditionInfo.label}</Badge>
            )}
            {board?.year_acquired && (
              <Badge className="bg-zinc-800 text-gray-400">
                <Calendar className="w-3 h-3 mr-1" />
                {board.year_acquired}
              </Badge>
            )}
          </div>
          
          {/* Description */}
          {board?.description && (
            <p className={`text-sm ${textSecondary}`}>{board.description}</p>
          )}
          
          {/* Actions */}
          {isOwnProfile && (
            <div className="flex gap-2 pt-2 border-t border-zinc-800">
              <Button
                variant="outline"
                onClick={() => {
                  onClose();
                  onEdit(board);
                }}
                className="flex-1"
              >
                <Edit2 className="w-4 h-4 mr-2" />
                Edit
              </Button>
              {deleteConfirm ? (
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    onClick={() => setDeleteConfirm(false)}
                    size="sm"
                  >
                    Cancel
                  </Button>
                  <Button
                    onClick={handleDelete}
                    disabled={deleting}
                    className="bg-red-500 hover:bg-red-600"
                    size="sm"
                  >
                    {deleting ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Confirm'}
                  </Button>
                </div>
              ) : (
                <Button
                  variant="outline"
                  onClick={() => setDeleteConfirm(true)}
                  className="text-red-400 hover:text-red-300"
                >
                  <Trash2 className="w-4 h-4" />
                </Button>
              )}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
};

// Main SurfboardsTab Component
export const SurfboardsTab = ({ userId, isOwnProfile }) => {
  const { theme } = useTheme();
  const isLight = theme === 'light';
  
  const [boards, setBoards] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedBoard, setSelectedBoard] = useState(null);
  const [editingBoard, setEditingBoard] = useState(null);
  
  const fetchBoards = async () => {
    try {
      const response = await apiClient.get(`/surfboards/user/${userId}`);
      setBoards(response.data.boards || []);
    } catch (error) {
      logger.error('Error fetching surfboards:', error);
    } finally {
      setLoading(false);
    }
  };
  
  useEffect(() => {
    if (userId) {
      fetchBoards();
    }
  }, [userId]);
  
  const handleBoardClick = (board) => {
    setSelectedBoard(board);
    setShowDetailModal(true);
  };
  
  const handleEdit = (board) => {
    setEditingBoard(board);
    setShowAddModal(true);
  };
  
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-500' : 'text-gray-400';
  
  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
      </div>
    );
  }
  
  return (
    <div className="p-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className={`font-bold ${textPrimary}`}>
            {isOwnProfile ? 'My Quiver' : 'Quiver'}
          </h3>
          <p className={`text-sm ${textSecondary}`}>
            {boards.length} board{boards.length !== 1 ? 's' : ''}
          </p>
        </div>
        {isOwnProfile && (
          <Button
            onClick={() => {
              setEditingBoard(null);
              setShowAddModal(true);
            }}
            size="sm"
            className="bg-gradient-to-r from-cyan-500 to-blue-600"
          >
            <Plus className="w-4 h-4 mr-1" />
            Add Board
          </Button>
        )}
      </div>
      
      {/* Grid */}
      {boards.length === 0 ? (
        <div className="text-center py-12">
          <div className={`w-16 h-16 mx-auto mb-4 rounded-full ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} flex items-center justify-center`}>
            <Waves className={`w-8 h-8 ${isLight ? 'text-gray-400' : 'text-gray-500'}`} />
          </div>
          <h4 className={`font-semibold ${textPrimary} mb-1`}>No Boards Yet</h4>
          <p className={`text-sm ${textSecondary} mb-4`}>
            {isOwnProfile 
              ? 'Add your surfboards to build your quiver' 
              : 'No surfboards in this quiver yet'}
          </p>
          {isOwnProfile && (
            <Button
              onClick={() => {
                setEditingBoard(null);
                setShowAddModal(true);
              }}
              className="bg-gradient-to-r from-cyan-500 to-blue-600"
            >
              <Plus className="w-4 h-4 mr-2" />
              Add Your First Board
            </Button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {boards.map((board) => (
            <SurfboardCard
              key={board.id}
              board={board}
              onClick={() => handleBoardClick(board)}
              isLight={isLight}
            />
          ))}
          {/* Add board placeholder */}
          {isOwnProfile && (
            <div
              onClick={() => {
                setEditingBoard(null);
                setShowAddModal(true);
              }}
              className={`aspect-[3/4] rounded-xl border-2 border-dashed ${
                isLight ? 'border-gray-300 hover:border-cyan-400' : 'border-zinc-700 hover:border-cyan-500'
              } flex flex-col items-center justify-center cursor-pointer transition-colors`}
            >
              <Plus className={`w-8 h-8 ${isLight ? 'text-gray-400' : 'text-zinc-500'} mb-2`} />
              <span className={`text-sm ${textSecondary}`}>Add Board</span>
            </div>
          )}
        </div>
      )}
      
      {/* Modals */}
      <SurfboardModal
        isOpen={showAddModal}
        onClose={() => {
          setShowAddModal(false);
          setEditingBoard(null);
        }}
        board={editingBoard}
        onSave={fetchBoards}
        userId={userId}
      />
      
      <SurfboardDetailModal
        isOpen={showDetailModal}
        onClose={() => {
          setShowDetailModal(false);
          setSelectedBoard(null);
        }}
        board={selectedBoard}
        onEdit={handleEdit}
        onDelete={fetchBoards}
        isOwnProfile={isOwnProfile}
        userId={userId}
      />
    </div>
  );
};

export default SurfboardsTab;

/**
 * SurferGallery - "My Gallery" / "The Locker"
 * Private media collection for surfers with full controls
 * 
 * Features:
 * - Responsive desktop/mobile layout
 * - Favorites system
 * - Search, sort, and filter
 * - Grid/List view modes
 * - Bulk download
 * - Social sharing
 * - Purchase history
 * - Album/folder organization
 */
import React, { useState, useEffect, useMemo } from 'react';
import { 
  Lock, Download, Eye, EyeOff, CheckCircle, XCircle,
  Image as ImageIcon, Video, Sparkles, Filter, Crown, Gift, Heart,
  Search, Grid, List, Share2, Calendar, SortDesc, Camera, MapPin, History, X,
  MoreHorizontal, MessageSquare, Check,
  ChevronLeft, ChevronRight, Loader2, ScanFace
} from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { Card, CardContent } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Tabs, TabsList, TabsTrigger } from './ui/tabs';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from './ui/dropdown-menu';
import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import PhotoSelectionQueue from './PhotoSelectionQueue';
import AIProposedMatches from './AIProposedMatches';
import { LockerSelfieModal } from './LockerSelfieModal';
import { BulkPurchaseBar, MultiSelectToggle } from './gallery/BulkPurchaseBar';
import { VisibilityOnboarding } from './gallery/DownloadVisibility';
import { GalleryLightbox } from './gallery/GalleryLightbox';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';
import { isGrom } from '../lib/roles';

/**
 * Gallery Item Card Component - Enhanced with favorites and sharing
 */
const GalleryItemCard = ({ 
  item, 
  onVisibilityToggle, 
  onDownload, 
  onFavoriteToggle,
  onShare,
  onRequestEdit,
  onImageClick,
  onMessage,
  _userId,
  viewMode = 'grid',
  isSelected,
  onSelect
}) => {
  const isPro = item.gallery_tier === 'pro';
  const isAccessible = item.is_paid || ['included', 'gifted'].includes(item.access_type);
  const isFavorite = item.is_favorite;
  
  // List view
  if (viewMode === 'list') {
    return (
      <div 
        className={`flex items-center gap-4 p-3 rounded-lg border transition-all ${
          isSelected 
            ? 'bg-cyan-500/10 border-cyan-500/50' 
            : 'bg-card border-border hover:bg-muted/50'
        }`}
        data-testid={`gallery-item-${item.id}`}
      >
        {/* Selection checkbox */}
        <button
          onClick={() => onSelect?.(item.id)}
          className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all ${
            isSelected ? 'bg-cyan-500 border-cyan-500' : 'border-zinc-600 hover:border-cyan-400'
          }`}
        >
          {isSelected && <Check className="w-3 h-3 text-foreground" />}
        </button>
        
        {/* Thumbnail */}
        <div className="relative w-16 h-16 rounded-lg overflow-hidden flex-shrink-0">
          <img 
            src={item.thumbnail_url || item.url} 
            alt=""
            className="w-full h-full object-cover"
          />
          {item.media_type === 'video' && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/30">
              <Video className="w-5 h-5 text-foreground" />
            </div>
          )}
        </div>
        
        {/* Info */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="font-medium text-foreground truncate">
              {item.title || `Photo ${item.id?.slice(-6)}`}
            </span>
            {isFavorite && <Heart className="w-4 h-4 text-red-400 fill-red-400" />}
            {isPro && <Badge className="bg-amber-500/20 text-amber-400 text-[10px]">PRO</Badge>}
          </div>
          <div className="flex items-center gap-3 text-xs text-muted-foreground mt-1">
            <span className="flex items-center gap-1">
              <Camera className="w-3 h-3" />
              {item.photographer_name || 'Unknown'}
            </span>
            <span className="flex items-center gap-1">
              <Calendar className="w-3 h-3" />
              {new Date(item.created_at).toLocaleDateString()}
            </span>
            {item.spot_name && (
              <span className="flex items-center gap-1">
                <MapPin className="w-3 h-3" />
                {item.spot_name}
              </span>
            )}
          </div>
        </div>
        
        {/* Status */}
        <div className="flex items-center gap-2">
          {item.is_public ? (
            <Badge className="bg-green-500/20 text-green-400 text-xs">Public</Badge>
          ) : (
            <Badge className="bg-zinc-700 text-muted-foreground text-xs">Private</Badge>
          )}
        </div>
        
        {/* Actions */}
        <div className="flex items-center gap-1">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => onFavoriteToggle?.(item.id)}
            className={isFavorite ? 'text-red-400' : 'text-muted-foreground'}
          >
            <Heart className={`w-4 h-4 ${isFavorite ? 'fill-current' : ''}`} />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => onDownload?.(item)}
            disabled={!isAccessible}
            className="text-muted-foreground"
          >
            <Download className="w-4 h-4" />
          </Button>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button size="sm" variant="ghost" className="text-muted-foreground">
                <MoreHorizontal className="w-4 h-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="bg-card border-border">
              <DropdownMenuItem onClick={() => onVisibilityToggle?.(item.id, !item.is_public)}>
                {item.is_public ? <EyeOff className="w-4 h-4 mr-2" /> : <Eye className="w-4 h-4 mr-2" />}
                Make {item.is_public ? 'Private' : 'Public'}
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => onShare?.(item)}>
                <Share2 className="w-4 h-4 mr-2" />
                Share
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => onRequestEdit?.(item)}>
                <MessageSquare className="w-4 h-4 mr-2" />
                Request Edit
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    );
  }
  
  // Grid view (default)
  return (
    <div 
      className={`group relative rounded-xl overflow-hidden border-2 transition-all ${
        isSelected 
          ? 'border-cyan-500 ring-2 ring-cyan-500/30' 
          : 'border-transparent hover:border-zinc-600'
      }`}
      data-testid={`gallery-item-${item.id}`}
    >
      {/* Selection checkbox */}
      <button
        onClick={() => onSelect?.(item.id)}
        className={`absolute top-2 left-2 z-10 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
          isSelected 
            ? 'bg-cyan-500 border-cyan-500' 
            : 'bg-black/50 border-white/50 opacity-0 group-hover:opacity-100'
        }`}
      >
        {isSelected && <Check className="w-4 h-4 text-foreground" />}
      </button>
      
      {/* Favorite button */}
      <button
        onClick={() => onFavoriteToggle?.(item.id)}
        className={`absolute top-2 right-2 z-10 p-1.5 rounded-full transition-all ${
          isFavorite 
            ? 'bg-red-500/80 text-foreground' 
            : 'bg-black/50 text-foreground opacity-0 group-hover:opacity-100 hover:bg-red-500/80'
        }`}
      >
        <Heart className={`w-4 h-4 ${isFavorite ? 'fill-current' : ''}`} />
      </button>
      
      {/* Image */}
      <div className="aspect-square bg-muted cursor-pointer" onClick={() => onImageClick?.(item)}>
        <img 
          src={item.thumbnail_url || item.url} 
          alt=""
          className={`w-full h-full object-cover transition-all ${
            !isAccessible ? 'blur-sm' : ''
          }`}
        />
        
        {/* Video indicator */}
        {item.media_type === 'video' && (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-12 h-12 rounded-full bg-black/60 flex items-center justify-center">
              <Video className="w-6 h-6 text-foreground" />
            </div>
          </div>
        )}
        
        {/* Pro tier badge */}
        {isPro && (
          <div className="absolute top-2 left-10 px-2 py-0.5 rounded bg-gradient-to-r from-amber-500 to-yellow-500 text-black text-xs font-bold">
            PRO
          </div>
        )}
        
        {/* Locked overlay */}
        {!isAccessible && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60">
            <Lock className="w-8 h-8 text-amber-400 mb-2" />
            <span className="text-foreground text-sm font-medium">Purchase to unlock</span>
          </div>
        )}
      </div>
      
      {/* Info overlay on hover */}
      <div className="absolute inset-x-0 bottom-0 p-3 bg-gradient-to-t from-black/90 via-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
        <div className="flex items-center justify-between">
          <div className="flex-1 min-w-0">
            <p className="text-foreground text-sm font-medium truncate">
              {item.photographer_name || 'Unknown'}
            </p>
            <p className="text-muted-foreground text-xs">
              {new Date(item.created_at).toLocaleDateString()}
            </p>
          </div>
          <div className="flex items-center gap-1">
            {/* Quick Message to Photographer */}
            {item.photographer_id && (
              <Button
                size="sm"
                variant="ghost"
                onClick={() => onMessage?.(item.photographer_id, item.photographer_name)}
                className="text-foreground hover:bg-cyan-500/20 h-8 w-8 p-0"
                title="Message photographer"
              >
                <MessageSquare className="w-4 h-4" />
              </Button>
            )}
            <Button
              size="sm"
              variant="ghost"
              onClick={() => onShare?.(item)}
              className="text-foreground hover:bg-white/20 h-8 w-8 p-0"
            >
              <Share2 className="w-4 h-4" />
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => onDownload?.(item)}
              disabled={!isAccessible}
              className="text-foreground hover:bg-white/20 h-8 w-8 p-0"
            >
              <Download className="w-4 h-4" />
            </Button>
          </div>
        </div>
      </div>
      
      {/* Visibility indicator */}
      <div className="absolute bottom-2 left-2 opacity-0 group-hover:opacity-100 transition-opacity">
        <button
          onClick={() => onVisibilityToggle?.(item.id, !item.is_public)}
          className={`p-1.5 rounded-full ${
            item.is_public ? 'bg-green-500/80' : 'bg-zinc-700/80'
          }`}
        >
          {item.is_public ? <Eye className="w-3 h-3 text-foreground" /> : <EyeOff className="w-3 h-3 text-foreground" />}
        </button>
      </div>
    </div>
  );
};

/**
 * Claim Queue Item Component
 */
const ClaimQueueItem = ({ item, onAction }) => (
  <div className="p-3 bg-muted rounded-xl border border-purple-500/20">
    <div className="flex gap-3">
      <div className="w-20 h-20 rounded-lg overflow-hidden flex-shrink-0">
        <img 
          src={item.thumbnail_url || item.url} 
          alt=""
          className="w-full h-full object-cover"
        />
      </div>
      <div className="flex-1">
        <div className="flex items-center gap-2 mb-1">
          <Badge className="bg-purple-500/20 text-purple-400 text-xs">
            {Math.round(item.confidence * 100)}% match
          </Badge>
          <span className="text-xs text-muted-foreground">
            by {item.photographer_name}
          </span>
        </div>
        <p className="text-sm text-muted-foreground line-clamp-2">
          {item.session_date ? new Date(item.session_date).toLocaleDateString() : 'Recent session'}
          {item.spot_name && ` at ${item.spot_name}`}
        </p>
        <div className="flex gap-2 mt-2">
          <Button
            size="sm"
            onClick={() => onAction(item.id, 'claim')}
            className="bg-green-500 hover:bg-green-600 text-foreground h-7 text-xs"
          >
            <CheckCircle className="w-3 h-3 mr-1" />
            That's me!
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => onAction(item.id, 'reject')}
            className="h-7 text-xs border-zinc-600"
          >
            <XCircle className="w-3 h-3 mr-1" />
            Not me
          </Button>
        </div>
      </div>
    </div>
  </div>
);

/**
 * Download Modal Component
 */
const DownloadModal = ({ item, isOpen, onClose, onDownload, onPurchase }) => {
  if (!item) return null;
  
  const tiers = [
    { id: 'web', label: 'Web Quality', desc: '1200px - Social media', price: item.price !== undefined ? item.price : 3.0 },
    { id: 'standard', label: 'Standard', desc: '2400px - Prints up to 8x10', price: item.price !== undefined ? item.price : 5.0 },
    { id: 'high', label: 'High Resolution', desc: 'Full size - Large prints', price: item.price !== undefined ? item.price : 10.0 },
  ];
  
  const isAccessible = item.is_paid || ['included', 'gifted'].includes(item.access_type);
  const isFreeFromSession = item.price === 0.0 && item.price_source === 'included';
  
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-card border-border text-foreground max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Download className="w-5 h-5 text-cyan-400" />
            Download Options
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          {tiers.map(tier => (
            <button
              key={tier.id}
              onClick={() => onDownload(item.id, tier.id)}
              disabled={!isAccessible}
              className={`w-full p-3 rounded-lg border text-left transition-all ${
                isAccessible 
                  ? 'border-zinc-700 hover:border-cyan-500/50 hover:bg-cyan-500/10' 
                  : 'border-border opacity-50 cursor-not-allowed'
              }`}
            >
              <div className="flex justify-between items-center">
                <div>
                  <p className="font-medium">{tier.label}</p>
                  <p className="text-sm text-muted-foreground">{tier.desc}</p>
                </div>
                {isAccessible ? (
                  <Download className="w-5 h-5 text-cyan-400" />
                ) : (
                  <span className="text-amber-400">${tier.price.toFixed(2)}</span>
                )}
              </div>
            </button>
          ))}
        </div>
        {!isAccessible && (
          <div className="p-3 bg-amber-500/10 border border-amber-500/30 rounded-lg flex flex-col gap-3">
            <p className="text-sm text-amber-400">
              {isFreeFromSession 
                ? "This photo is included in your session package! Click below to unlock." 
                : "Purchase this photo to unlock downloads"}
            </p>
            <Button
              className="w-full bg-cyan-500 hover:bg-cyan-600 text-black font-semibold"
              onClick={() => onPurchase(item.id, 'high')} // Defaulting to high quality purchase
            >
               {isFreeFromSession ? "Unlock Included Photo" : `Buy Now ($${tiers[2].price.toFixed(2)})`}
            </Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};

/**
 * Share Modal Component
 */
const ShareModal = ({ item, isOpen, onClose }) => {
  const [copied, setCopied] = useState(false);
  
  if (!item) return null;
  
  const shareUrl = `${window.location.origin}/gallery/item/${item.id}`;
  
  const handleCopy = () => {
    navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    toast.success('Link copied!');
  };
  
  const handleSocialShare = (platform) => {
    const text = `Check out this surf photo!`;
    const urls = {
      twitter: `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(shareUrl)}`,
      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`,
      instagram: shareUrl, // Instagram doesn't have direct share URL, just copy
    };
    if (platform === 'instagram') {
      handleCopy();
      toast.info('Link copied! Paste in Instagram');
    } else {
      window.open(urls[platform], '_blank', 'width=600,height=400');
    }
    onClose();
  };
  
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-card border-border text-foreground max-w-sm">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Share2 className="w-5 h-5 text-cyan-400" />
            Share Photo
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          {/* Preview */}
          <div className="aspect-video rounded-lg overflow-hidden bg-muted">
            <img src={item.thumbnail_url || item.url} alt="" className="w-full h-full object-cover" />
          </div>
          
          {/* Copy link */}
          <div className="flex gap-2">
            <Input 
              value={shareUrl} 
              readOnly 
              className="bg-muted border-zinc-700 text-sm"
            />
            <Button onClick={handleCopy} className="bg-cyan-500 hover:bg-cyan-600">
              {copied ? <Check className="w-4 h-4" /> : 'Copy'}
            </Button>
          </div>
          
          {/* Social buttons */}
          <div className="flex gap-2 justify-center">
            <Button
              variant="outline"
              onClick={() => handleSocialShare('twitter')}
              className="flex-1 border-zinc-700"
            >
              𝕏 Twitter
            </Button>
            <Button
              variant="outline"
              onClick={() => handleSocialShare('facebook')}
              className="flex-1 border-zinc-700"
            >
              Facebook
            </Button>
            <Button
              variant="outline"
              onClick={() => handleSocialShare('instagram')}
              className="flex-1 border-zinc-700"
            >
              Instagram
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

/**
 * Request Edit Modal Component
 */
const RequestEditModal = ({ item, isOpen, onClose, onSubmit }) => {
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  
  if (!item) return null;
  
  const handleSubmit = async () => {
    if (!message.trim()) {
      toast.error('Please describe your edit request');
      return;
    }
    setLoading(true);
    try {
      await onSubmit(item.id, message);
      toast.success('Edit request sent to photographer');
      setMessage('');
      onClose();
    } catch (error) {
      toast.error('Failed to send request');
    } finally {
      setLoading(false);
    }
  };
  
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-card border-border text-foreground max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MessageSquare className="w-5 h-5 text-cyan-400" />
            Request Edit
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <p className="text-sm text-muted-foreground">
            Send a message to <span className="text-foreground">{item.photographer_name}</span> requesting edits to this photo.
          </p>
          <textarea
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder="E.g., Could you crop tighter on the wave? Or add a slight color boost?"
            className="w-full h-24 p-3 bg-muted border border-zinc-700 rounded-lg text-foreground placeholder:text-muted-foreground resize-none"
          />
          <p className="text-xs text-muted-foreground">
            Common requests: cropping, color correction, remove watermark (for purchased photos)
          </p>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button onClick={handleSubmit} disabled={loading} className="bg-cyan-500 hover:bg-cyan-600">
            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Send Request'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

/**
 * Purchase History Modal Component
 */
const PurchaseHistoryModal = ({ isOpen, onClose, userId }) => {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  
  useEffect(() => {
    if (isOpen && userId) {
      fetchHistory();
    }
  }, [isOpen, userId]);
  
  const fetchHistory = async () => {
    try {
      const response = await apiClient.get(`/surfer-gallery/purchase-history?surfer_id=${userId}`);
      setHistory(response.data.purchases || []);
    } catch (error) {
      logger.error('Failed to fetch purchase history:', error);
    } finally {
      setLoading(false);
    }
  };
  
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-card border-border text-foreground max-w-lg max-h-[80vh] overflow-hidden">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <History className="w-5 h-5 text-cyan-400" />
            Purchase History
          </DialogTitle>
        </DialogHeader>
        <div className="overflow-y-auto max-h-[60vh]">
          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-cyan-400" />
