                    )}
                    {tier.savings && (
                      <div className="mt-1 text-xs text-emerald-400">
                        Save {tier.savings}/year
                      </div>
                    )}
                  </div>
                </div>

                <ul className="space-y-3 mb-6">
                  {tier.features.map((feature, idx) => (
                    <li key={idx} className="flex items-start gap-3">
                      {feature.included ? (
                        <Check className={`w-5 h-5 flex-shrink-0 mt-0.5 ${
                          feature.highlight ? 'text-yellow-400' : 
                          feature.negative ? 'text-orange-400' : 'text-emerald-400'
                        }`} />
                      ) : (
                        <X className="w-5 h-5 flex-shrink-0 mt-0.5 text-zinc-600" />
                      )}
                      <span className={`text-sm ${
                        feature.included 
                          ? feature.highlight ? 'text-yellow-400 font-medium' : 'text-gray-300'
                          : 'text-zinc-600'
                      }`}>
                        {feature.text}
                      </span>
                    </li>
                  ))}
                </ul>

                <Button
                  onClick={() => handleSelectTier(tier)}
                  disabled={loading && selectedTier === tier.id}
                  className={`w-full min-h-[48px] font-bold ${
                    tier.popular
                      ? 'bg-gradient-to-r from-emerald-400 via-yellow-400 to-orange-400 hover:from-emerald-500 hover:via-yellow-500 hover:to-orange-500 text-black'
                      : 'bg-zinc-800 hover:bg-zinc-700 text-white border border-zinc-600'
                  }`}
                  data-testid={`select-tier-${tier.id}`}
                >
                  {loading && selectedTier === tier.id ? (
                    <Loader2 className="w-5 h-5 animate-spin" />
                  ) : (
                    tier.cta
                  )}
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Benefits Section */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-12">
          {[
            { icon: MapPin, label: 'Live Tracking', desc: 'Find photographers near you' },
            { icon: Zap, label: 'Instant Delivery', desc: 'Get photos same day' },
            { icon: Bell, label: 'Smart Alerts', desc: 'Never miss a session' },
            { icon: Shield, label: 'Secure Payments', desc: 'Safe & protected' }
          ].map((benefit, idx) => (
            <div key={idx} className="text-center p-4">
              <div className="w-12 h-12 mx-auto mb-3 rounded-full bg-zinc-800 flex items-center justify-center">
                <benefit.icon className="w-6 h-6 text-yellow-400" />
              </div>
              <h4 className="font-bold text-white mb-1">{benefit.label}</h4>
              <p className="text-xs text-gray-400">{benefit.desc}</p>
            </div>
          ))}
        </div>

        {/* Skip Link */}
        <div className="text-center mt-8">
          <button
            onClick={() => handleSelectTier(SURFER_TIERS[0])}
            className="text-gray-500 hover:text-gray-300 text-sm underline"
            data-testid="skip-subscription"
          >
            Continue with Free tier
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { sendNotification } from '../services/notificationService';
import { 
  X, Heart, Download, Calendar, Camera, Check, Lock, Sparkles, CreditCard, Gift
} from 'lucide-react';
import { Dialog, DialogContent, DialogTitle } from './ui/dialog';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Avatar, AvatarImage, AvatarFallback } from './ui/avatar';
import { toast } from 'sonner';
import logger from '../utils/logger';
import { isGrom } from '../lib/roles';
import { submitPurchaseRequest } from '../utils/gromPurchase';


export const TaggedPhotoModal = ({ 
  isOpen, 
  onClose, 
  photo,  // The tagged photo item
  onPhotoViewed,  // Callback when photo is marked as viewed
  onPurchaseComplete  // Callback when purchase completes
}) => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  
  const [purchasing, setPurchasing] = useState(false);
  const [thankSent, setThankSent] = useState(false);
  const [selectedTier, setSelectedTier] = useState('standard');
  const [galleryPricing, setGalleryPricing] = useState(null);
  const [hasPurchased, setHasPurchased] = useState(false);
  const [subscriptionInfo, setSubscriptionInfo] = useState(null);

  // Theme classes
  const isLight = theme === 'light';
  const bgClass = isLight ? 'bg-white' : 'bg-zinc-900';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  const borderClass = isLight ? 'border-gray-200' : 'border-zinc-700';

  useEffect(() => {
    if (isOpen && photo) {
      // Mark as viewed when modal opens
      markAsViewed();
      // Fetch gallery pricing if needed
      if (!photo.access_granted && !photo.is_gift) {
        fetchGalleryPricing();
        fetchSubscriptionQuota();
      }
    }
  }, [isOpen, photo]);

  const markAsViewed = async () => {
    if (photo?.is_new && photo?.tag_id) {
      try {
        await apiClient.post(`/ai/mark-photo-viewed?tag_id=${photo.tag_id}`);
        onPhotoViewed?.(photo.id);
      } catch (e) {
        logger.error('Failed to mark as viewed:', e);
      }
    }
  };

  const fetchGalleryPricing = async () => {
    // If we have session pricing, use that for participants
    if (photo.was_session_participant && photo.session_photo_price !== null) {
      return; // Use session pricing
    }
    
    // Default gallery pricing (can be fetched from API if needed)
    setGalleryPricing({
      photo: { web: 3, standard: 5, high: 10 },
      video: { '720p': 8, '1080p': 15, '4k': 30 }
    });
  };

  const fetchSubscriptionQuota = async () => {
    if (!user?.id || !photo?.photographer_id) return;
    try {
      const quotaType = photo.media_type === 'video' ? 'video' : 'photo';
      const res = await apiClient.get(
        `/photo-subscriptions/check-quota?surfer_id=${user.id}&photographer_id=${photo.photographer_id}&quota_type=${quotaType}`
      );
      setSubscriptionInfo(res.data);
    } catch {
      setSubscriptionInfo(null);
    }
  };

  const handleThankPhotographer = async () => {
    try {
      await sendNotification({
        recipient_id: photo.photographer_id,
        sender_id: user?.id,
        type: 'thank_you',
        title: 'Thanks for the photo!',
        body: `${user?.full_name || 'A surfer'} thanked you for tagging them in a photo`
      });
      setThankSent(true);
      toast.success('Thank you sent to photographer!');
    } catch (e) {
      toast.error('Failed to send thank you');
    }
  };

  const handleSuggestBooking = () => {
    // Navigate to photographer's profile with booking intent
    navigate(`/profile/${photo.photographer_id}?action=book`);
    onClose();
  };

  const handlePurchase = async () => {
    if (isGrom(user)) {
      const tierPrice = galleryPricing?.photo?.[selectedTier] || 5;
      await submitPurchaseRequest({
        gromId: user.id,
        itemType: 'gallery_photo',
        itemId: photo.id,
        itemName: photo.title || 'Session Photo',
        amount: photo.was_session_participant ? (photo.session_photo_price || tierPrice) : tierPrice,
        qualityTier: selectedTier
      });
      return;
    }
    setPurchasing(true);
    try {
      // Determine price based on user status
      let price;
      let quality = selectedTier;
      
      if (photo.was_session_participant && photo.session_photo_price !== null) {
        // Session participant - use session price
        price = photo.session_photo_price;
        quality = 'session'; // Special quality tier for session purchases
      } else {
        // Non-participant - use gallery pricing
        price = galleryPricing?.photo?.[selectedTier] || 5;
      }

      // Purchase photo - this moves it to user's personal gallery
      const response = await apiClient.post(`/gallery/items/${photo.id}/purchase`, {
        buyer_id: user?.id,
        quality_tier: quality,
        amount: price
      });

      if (response.data.success) {
        setHasPurchased(true);
        if (response.data.subscription_covered) {
          toast.success('Included with your subscription! 🎉 Added to gallery.');
        } else {
          toast.success('Photo added to your gallery! You can now download it.');
        }
        onPurchaseComplete?.(photo.id);
      }
    } catch (e) {
      toast.error(e.response?.data?.detail || 'Purchase failed. Check your credit balance.');
    } finally {
      setPurchasing(false);
    }
  };

  const handleClaimFreePhoto = async () => {
    if (isGrom(user)) {
      await submitPurchaseRequest({
        gromId: user.id,
        itemType: 'gallery_photo',
        itemId: photo.id,
        itemName: photo.title || 'Session Photo (Free Claim)',
        amount: 0,
        qualityTier: 'session'
      });
      return;
    }
    // For session participants with $0 price - claim without payment
    try {
      const response = await apiClient.post(`/gallery/items/${photo.id}/claim`, {
        user_id: user?.id,
        tag_id: photo.tag_id
      });
      
      if (response.data.success) {
        setHasPurchased(true);
        toast.success('Photo claimed! It\'s now in your gallery.');
        onPurchaseComplete?.(photo.id);
      }
    } catch (e) {
      toast.error('Failed to claim photo');
    }
  };

  if (!photo) return null;

  // Determine what the user can see
  const canViewFull = photo.access_granted || photo.is_gift || hasPurchased;
  const isSessionParticipant = photo.was_session_participant;
  const sessionPrice = photo.session_photo_price;
  const isGift = photo.is_gift;
  const needsToPay = !canViewFull;

  // Check subscription coverage
  const hasSubscriptionQuota = subscriptionInfo?.has_quota && subscriptionInfo?.subscription_active;

  // Determine pricing to show
  const getPriceDisplay = () => {
    if (canViewFull) return null;

    // Subscription covers this item — show "Included" path
    if (hasSubscriptionQuota) {
      return {
        type: 'subscription',
        message: `Included with your subscription! (${subscriptionInfo.remaining} remaining)`,
      };
    }
    
    if (isSessionParticipant && sessionPrice !== null) {
      if (sessionPrice === 0) {
        return { type: 'included', message: 'Included with your session - no extra charge!' };
      }
      return { 
        type: 'session', 
        price: sessionPrice, 
        message: `Session rate: ${sessionPrice} credits` 
      };
    }
    
    // Gallery pricing for non-participants
    return { type: 'gallery', message: 'Choose quality to add to your gallery:' };
  };

  const priceInfo = getPriceDisplay();

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className={`${bgClass} border ${borderClass} max-w-2xl p-0 overflow-hidden`} aria-describedby="tagged-photo-description">
        <DialogTitle className="sr-only">Tagged Photo from {photo.tagged_by || 'Photographer'}</DialogTitle>
        {/* Header */}
        <div className={`flex items-center justify-between p-4 border-b ${borderClass}`}>
          <div className="flex items-center gap-3">
            <Avatar className="w-10 h-10">
              <AvatarImage src={photo.photographer_avatar} />
              <AvatarFallback className="bg-gradient-to-br from-cyan-400 to-blue-500 text-white">
                <Camera className="w-5 h-5" />
              </AvatarFallback>
            </Avatar>
            <div>
              <p className={`font-medium ${textPrimary}`}>{photo.tagged_by || 'Photographer'}</p>
              <p className={`text-xs ${textSecondary}`}>
                {isGift ? 'Gifted you this photo' : 'Tagged you in this photo'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {isGift && (
              <Badge className="bg-pink-500/20 text-pink-400">
                <Gift className="w-3 h-3 mr-1" /> Gift
              </Badge>
            )}
            <Button variant="ghost" size="icon" onClick={onClose}>
              <X className="w-5 h-5" />
            </Button>
          </div>
        </div>

        {/* Photo */}
        <div className="relative aspect-video bg-black flex items-center justify-center">
          <img 
            src={photo.preview_url || photo.media_url} 
            alt="Tagged photo"
            className={`max-w-full max-h-full object-contain ${needsToPay ? 'blur-md' : ''}`}
          />
          
          {/* Lock overlay for unpurchased photos */}
          {needsToPay && (
            <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center">
              <Lock className="w-12 h-12 text-white/80 mb-4" />
              <p className={`text-white text-lg font-medium mb-2`}>
                {isSessionParticipant ? 'Session Photo' : 'Purchase to Add to Gallery'}
              </p>
              {priceInfo?.type === 'session' && priceInfo.price > 0 && (
                <Badge className="bg-cyan-500/20 text-cyan-400 text-lg px-4 py-1">
                  {priceInfo.price} credits
                </Badge>
              )}
            </div>
          )}
          
          {/* Access granted badge */}
          {canViewFull && (
            <div className="absolute top-4 right-4">
              <Badge className="bg-green-500/90 text-white">
                <Check className="w-3 h-3 mr-1" /> 
                {isGift ? 'Gift' : hasPurchased ? 'In Your Gallery' : 'No Extra Charge'}
              </Badge>
            </div>
          )}
        </div>

        {/* Actions & Pricing */}
        <div className="p-4 space-y-4">
          {/* Pricing Section - Only show if needs to pay */}
          {needsToPay && (
            <div className={`p-4 rounded-lg ${isLight ? 'bg-gray-100' : 'bg-zinc-800'}`}>
              {priceInfo?.type === 'subscription' ? (
                /* ── Subscription covers this item ── */
                <div className="text-center">
                  <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-purple-500/20 text-purple-400 text-xs font-semibold mb-3">
                    <Sparkles className="w-3.5 h-3.5" /> SUBSCRIBER PERK
                  </div>
                  <p className={`${textPrimary} font-medium`}>{priceInfo.message}</p>
                  <Button
                    onClick={handlePurchase}
                    disabled={purchasing}
                    className="mt-3 bg-gradient-to-r from-purple-400 to-pink-500 text-white"
                  >
                    {purchasing ? 'Processing...' : (
                      <>
                        <Check className="w-4 h-4 mr-2" /> Add to My Gallery — Free
                      </>
                    )}
                  </Button>
                </div>
              ) : priceInfo?.type === 'included' ? (
                <div className="text-center">
                  <Sparkles className="w-8 h-8 mx-auto mb-2 text-green-400" />
                  <p className={`${textPrimary} font-medium`}>{priceInfo.message}</p>
                  <Button
                    onClick={handleClaimFreePhoto}
                    className="mt-3 bg-gradient-to-r from-green-400 to-emerald-500 text-black"
                  >
                    <Check className="w-4 h-4 mr-2" /> Add to My Gallery
                  </Button>
                </div>
              ) : priceInfo?.type === 'session' ? (
                <div className="text-center">
                  <p className={`${textSecondary} mb-2`}>You were in this session!</p>
                  {/* Show subscriber discount hint if active but no quota */}
                  {subscriptionInfo?.subscription_active && !hasSubscriptionQuota && (
                    <div className="mb-2">
                      <Badge className="bg-purple-500/20 text-purple-400 text-xs">
                        <Sparkles className="w-3 h-3 mr-1" /> Subscription quota used up
                      </Badge>
                    </div>
                  )}
                  <p className={`${textPrimary} text-xl font-bold mb-3`}>
                    {priceInfo.price} <span className="text-sm font-normal">credits</span>
                  </p>
                  <Button
                    onClick={handlePurchase}
                    disabled={purchasing}
                    className="bg-gradient-to-r from-cyan-400 to-blue-500 text-black"
                  >
                    {purchasing ? 'Processing...' : (
                      <>
                        <CreditCard className="w-4 h-4 mr-2" /> Add to My Gallery
                      </>
                    )}
                  </Button>
                </div>
              ) : (
                // Gallery pricing tiers - photo gets added to user's personal gallery
                <div>
                  {/* Show subscriber discount hint if active but no quota */}
                  {subscriptionInfo?.subscription_active && !hasSubscriptionQuota && (
                    <div className="text-center mb-3">
                      <Badge className="bg-purple-500/20 text-purple-400 text-xs">
                        <Sparkles className="w-3 h-3 mr-1" /> Subscription quota used up — regular pricing applies
                      </Badge>
                    </div>
                  )}
                  <p className={`${textSecondary} mb-3 text-center`}>{priceInfo?.message}</p>
                  <div className="grid grid-cols-3 gap-2 mb-4">
                    {[
                      { id: 'web', label: 'Web', price: galleryPricing?.photo?.web || 3, desc: '800px' },
                      { id: 'standard', label: 'HD', price: galleryPricing?.photo?.standard || 5, desc: '1920px' },
                      { id: 'high', label: '4K', price: galleryPricing?.photo?.high || 10, desc: 'Full res' }
                    ].map(tier => (
                      <button
                        key={tier.id}
                        onClick={() => setSelectedTier(tier.id)}
                        className={`p-3 rounded-lg border-2 transition-colors ${
                          selectedTier === tier.id 
                            ? 'border-cyan-400 bg-cyan-400/10' 
                            : `border-transparent ${isLight ? 'bg-white' : 'bg-zinc-700'}`
                        }`}
                      >
                        <p className={`font-medium ${textPrimary}`}>{tier.label}</p>
                        <p className="text-cyan-400 font-bold">{tier.price}c</p>
                        <p className={`text-xs ${textSecondary}`}>{tier.desc}</p>
                      </button>
                    ))}
                  </div>
                  <Button
                    onClick={handlePurchase}
                    disabled={purchasing}
                    className="w-full bg-gradient-to-r from-cyan-400 to-blue-500 text-black"
                  >
                    {purchasing ? 'Processing...' : (
                      <>
                        <CreditCard className="w-4 h-4 mr-2" /> 
                        Add to My Gallery ({galleryPricing?.photo?.[selectedTier] || 5}c)
                      </>
                    )}
                  </Button>
                </div>
              )}
            </div>
          )}

          {/* CTA Buttons - Always show */}
          <div className="flex gap-3">
            <Button
              variant="outline"
              onClick={handleThankPhotographer}
              disabled={thankSent}
              className={`flex-1 ${borderClass}`}
            >
              {thankSent ? (
                <>
                  <Check className="w-4 h-4 mr-2 text-green-400" /> Thanks Sent!
                </>
              ) : (
                <>
                  <Heart className="w-4 h-4 mr-2" /> Thank Photographer
                </>
              )}
            </Button>
            <Button
              onClick={handleSuggestBooking}
              className="flex-1 bg-gradient-to-r from-purple-400 to-pink-500 text-black"
            >
              <Calendar className="w-4 h-4 mr-2" /> Suggest a Booking
            </Button>
          </div>

          {/* Download button - Only when in user's gallery */}
          {canViewFull && (
            <Button
              variant="outline"
              className={`w-full ${borderClass}`}
              onClick={() => {
                // Open original image in new tab for download
                window.open(photo.media_url || photo.preview_url, '_blank');
              }}
            >
              <Download className="w-4 h-4 mr-2" /> Download Photo
            </Button>
          )}

          {/* Info footer */}
          <div className={`flex items-center justify-between text-xs ${textSecondary} pt-2 border-t ${borderClass}`}>
            <span>Tagged {new Date(photo.created_at).toLocaleDateString()}</span>
            <div className="flex gap-2">
              {isGift && (
                <Badge variant="outline" className="text-xs text-pink-400 border-pink-400/50">
                  <Gift className="w-3 h-3 mr-1" /> Gift
                </Badge>
              )}
              {photo.was_session_participant && (
                <Badge variant="outline" className="text-xs">
                  Session Participant
                </Badge>
              )}
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

﻿import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  Trophy, Star, Users, Loader2, Plus, CheckCircle, Clock, Medal,
  Target, Sparkles, Rocket, Baby, Heart, Zap, DollarSign
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';
import { Badge } from './ui/badge';
import { Progress } from './ui/progress';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { Input } from './ui/input';
import { toast } from 'sonner';
import { CrewLeaderboard } from './CrewLeaderboard';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';


/**
 * The Inside - Career Hub for Grom (🍼) surfers
 * Features: Road to the Peak progress, Grom Series results, Stoke Sponsors, Grom-Friendly coaches
 */
export const TheInsideHub = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  
  const [careerStats, setCareerStats] = useState(null);
  const [sponsorships, setSponsorships] = useState([]);
  const [competitionResults, setCompetitionResults] = useState([]);
  const [gromCoaches, setGromCoaches] = useState([]);
  const [stokeIncome, setStokeIncome] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showAddResultModal, setShowAddResultModal] = useState(false);
  const [showAddSponsorModal, setShowAddSponsorModal] = useState(false);

  const isLight = theme === 'light';
  const cardBg = isLight ? 'bg-white border-gray-200' : 'bg-card border-border';
  const textPrimary = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  useEffect(() => {
    if (user?.id) {
      fetchGromData();
    }
  }, [user?.id]);

  const fetchGromData = async () => {
    setLoading(true);
    try {
      const [statsRes, sponsorsRes, resultsRes, stokeRes] = await Promise.all([
        apiClient.get(`/career/stats/${user.id}`).catch(() => ({ data: null })),
        apiClient.get(`/career/sponsorships/${user.id}`).catch(() => ({ data: { sponsorships: [] } })),
        apiClient.get(`/career/competition-results/${user.id}`).catch(() => ({ data: { results: [] } })),
        apiClient.get(`/career/stoke-sponsor/income/${user.id}`).catch(() => ({ data: null }))
      ]);
      
      setCareerStats(statsRes.data);
      setSponsorships(sponsorsRes.data?.sponsorships || []);
      setCompetitionResults(resultsRes.data?.results || []);
      setStokeIncome(stokeRes.data);
      
      // Mock grom-friendly coaches for now
      setGromCoaches([
        { id: '1', name: 'Coach Mike', specialty: 'Grom Development', avatar: null },
        { id: '2', name: 'Sarah Surf School', specialty: 'Beginner Friendly', avatar: null },
      ]);
    } catch (error) {
      logger.error('Failed to fetch grom data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getVerificationBadge = (status) => {
    if (status === 'community_verified') {
      return <CheckCircle className="w-4 h-4 text-emerald-400" title="Community Verified" />;
    }
    if (status === 'api_synced') {
      return <CheckCircle className="w-4 h-4 text-cyan-400" title="Verified Sync" />;
    }
    return <Clock className="w-4 h-4 text-yellow-400" title="Pending Verification" />;
  };

  // Calculate Road to the Peak milestones
  const roadToThePeakProgress = careerStats?.road_to_peak_progress || 0;
  const getMilestoneStatus = (threshold) => {
    if (roadToThePeakProgress >= threshold) return 'completed';
    if (roadToThePeakProgress >= threshold - 20) return 'in_progress';
    return 'locked';
  };

  const milestones = [
    { threshold: 25, label: 'Rising Grom', icon: Star, reward: '+50 XP' },
    { threshold: 50, label: 'Wave Warrior', icon: Trophy, reward: '+100 XP' },
    { threshold: 75, label: 'Junior Champion', icon: Medal, reward: '+150 XP' },
    { threshold: 100, label: 'Ready to Level Up!', icon: Rocket, reward: 'Pro Access' },
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
      </div>
    );
  }

  return (
    <div 
      className="space-y-6 pb-24 md:pb-6" 
      data-testid="the-inside-hub"
      style={{ paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) + 80px)' }}
    >
      {/* Header */}
      <div className="text-center">
        <h1 className={`text-3xl font-bold ${textPrimary} flex items-center justify-center gap-2`} style={{ fontFamily: 'Oswald' }}>
          <Baby className="w-8 h-8 text-cyan-400" />
          The Inside
        </h1>
        <p className={`${textSecondary} mt-1`}>Your Grom Career Journey</p>
        <Badge className="mt-2 bg-cyan-500/20 text-cyan-400 border-cyan-500/30">
          🍼 Grom Rising
        </Badge>
      </div>

      {/* Road to the Peak - Progress Bar */}
      <Card className={`${cardBg} border-2 border-cyan-500/30 bg-gradient-to-br from-cyan-500/5 to-blue-500/5`}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Rocket className="w-5 h-5 text-cyan-400" />
            Road to The Peak
          </CardTitle>
        </CardHeader>
        <CardContent>
          {/* Progress Bar */}
          <div className="relative mb-6">
            <Progress value={roadToThePeakProgress} className="h-4 bg-zinc-800" />
            <div className="absolute -top-1 left-0 right-0 flex justify-between px-1">
              {milestones.map((milestone, idx) => (
                <div
                  key={idx}
                  className={`w-6 h-6 rounded-full flex items-center justify-center text-xs ${
                    getMilestoneStatus(milestone.threshold) === 'completed'
                      ? 'bg-cyan-400 text-black'
                      : getMilestoneStatus(milestone.threshold) === 'in_progress'
                      ? 'bg-yellow-400 text-black animate-pulse'
                      : 'bg-zinc-700 text-gray-400'
                  }`}
                  style={{ marginLeft: idx === 0 ? '0' : 'auto', marginRight: idx === milestones.length - 1 ? '0' : 'auto' }}
                >
                  {getMilestoneStatus(milestone.threshold) === 'completed' ? '✓' : milestone.threshold}
                </div>
              ))}
            </div>
          </div>

          {/* Milestone Cards */}
          <div className="grid grid-cols-2 gap-3">
            {milestones.map((milestone, idx) => {
              const status = getMilestoneStatus(milestone.threshold);
              const MilestoneIcon = milestone.icon;
              
              return (
                <div
                  key={idx}
                  className={`p-3 rounded-lg text-center ${
                    status === 'completed'
                      ? 'bg-cyan-500/20 border border-cyan-500/30'
                      : status === 'in_progress'
                      ? 'bg-yellow-500/20 border border-yellow-500/30'
                      : 'bg-zinc-800/50 border border-zinc-700'
                  }`}
                >
                  <MilestoneIcon className={`w-6 h-6 mx-auto mb-1 ${
                    status === 'completed' ? 'text-cyan-400' :
                    status === 'in_progress' ? 'text-yellow-400' : 'text-gray-500'
                  }`} />
                  <div className={`text-sm font-medium ${status === 'locked' ? 'text-gray-500' : textPrimary}`}>
                    {milestone.label}
                  </div>
                  <div className={`text-xs ${status === 'locked' ? 'text-gray-600' : 'text-cyan-400'}`}>
                    {milestone.reward}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Level Up Alert */}
          {roadToThePeakProgress >= 100 && (
            <div className="mt-4 p-4 bg-gradient-to-r from-cyan-500/20 to-blue-500/20 border border-cyan-500/30 rounded-lg text-center">
              <Sparkles className="w-8 h-8 text-cyan-400 mx-auto mb-2" />
              <div className={`font-bold ${textPrimary}`}>Ready to Level Up!</div>
              <p className={`text-sm ${textSecondary}`}>
                You've completed The Road to The Peak! Contact your manager to transition to Competitive status.
              </p>
              <Button className="mt-3 bg-cyan-500 text-black hover:bg-cyan-400">
                <Zap className="w-4 h-4 mr-2" />
                Request Promotion
              </Button>
            </div>
          )}

          {/* Current Progress */}
          <div className="mt-4 text-center">
            <div className="text-3xl font-bold text-cyan-400">{roadToThePeakProgress}%</div>
            <div className={`text-sm ${textSecondary}`}>
              {careerStats?.total_xp || 0} XP earned • {careerStats?.verified_results_count || 0} verified results
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Gear Purchase Goal Tracker - NEW */}
      <Card className={`${cardBg} border-2 border-emerald-500/30 bg-gradient-to-br from-emerald-500/5 to-cyan-500/5`}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Target className="w-5 h-5 text-emerald-400" />
            Gear Goal Tracker
            <Badge className="ml-auto bg-emerald-500/20 text-emerald-400 border-0 text-xs">SAVE</Badge>
          </CardTitle>
        </CardHeader>
        <CardContent>
          {/* Example Goal: New Shortboard */}
          <div className="mb-4">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <span className="text-xl">🏄</span>
                <div>
                  <div className={`font-medium ${textPrimary}`}>New Shortboard</div>
                  <div className={`text-xs ${textSecondary}`}>Target: $450</div>
                </div>
              </div>
              <div className="text-right">
                <div className="text-emerald-400 font-bold">
                  ${(stokeIncome?.total_received || 0).toFixed(0)}
                </div>
                <div className={`text-xs ${textSecondary}`}>saved</div>
              </div>
            </div>
            <Progress 
              value={Math.min(((stokeIncome?.total_received || 0) / 450) * 100, 100)} 
              className="h-3 bg-zinc-800" 
            />
            <div className="flex justify-between mt-1">
              <span className={`text-xs ${textSecondary}`}>
                {Math.round(((stokeIncome?.total_received || 0) / 450) * 100)}% Complete
              </span>
              <span className={`text-xs text-emerald-400`}>
                ${Math.max(450 - (stokeIncome?.total_received || 0), 0).toFixed(0)} to go
              </span>
            </div>
          </div>

          {/* Credit Sources */}
          <div className="p-3 bg-zinc-800/50 rounded-lg mb-4">
            <div className={`text-xs font-medium ${textSecondary} mb-2`}>Credits from:</div>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Heart className="w-4 h-4 text-pink-400" />
                <span className={`text-sm ${textPrimary}`}>Photographer Sponsors</span>
              </div>
              <span className="text-pink-400 font-medium">
                ${(stokeIncome?.total_received || 0).toFixed(2)}
              </span>
            </div>
          </div>

          <div className="text-center">
            <p className={`text-xs ${textSecondary}`}>
              Complete events and get sponsored to reach your gear goals!
            </p>
            <Button 
              variant="outline"
              size="sm"
              className="mt-2 border-emerald-500/50 text-emerald-400 hover:bg-emerald-500/10"
              onClick={() => navigate('/gear-hub')}
            >
              Browse Gear Hub
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Grom Series Results */}
      <Card className={cardBg}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Trophy className="w-5 h-5 text-yellow-400" />
            Grom Series Results
          </CardTitle>
        </CardHeader>
        <CardContent>
          {competitionResults.length > 0 ? (
            <div className="space-y-3">
              {competitionResults.slice(0, 5).map((result) => (
                <div 
                  key={result.id}
                  className={`flex items-center justify-between p-3 rounded-lg ${
                    result.placing <= 3 
                      ? 'bg-gradient-to-r from-yellow-500/10 to-amber-500/10 border border-yellow-500/20'
                      : 'bg-zinc-800/50'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                      result.placing === 1 ? 'bg-yellow-500 text-black' :
                      result.placing === 2 ? 'bg-gray-300 text-black' :
                      result.placing === 3 ? 'bg-amber-600 text-white' :
                      'bg-zinc-700 text-white'
                    }`}>
                      {result.placing === 1 ? '🥇' : result.placing === 2 ? '🥈' : result.placing === 3 ? '🥉' : result.placing}
                    </div>
                    <div>
                      <div className={`font-medium ${textPrimary}`}>{result.event_name}</div>
                      <div className={`text-xs ${textSecondary}`}>{result.event_date}</div>
                    </div>
                  </div>
                  {getVerificationBadge(result.verification_status)}
                </div>
              ))}
            </div>
          ) : (
            <p className={`text-center ${textSecondary} py-4`}>No competition results yet. Start competing!</p>
          )}
          <Button 
            onClick={() => setShowAddResultModal(true)}
            className="w-full mt-4 bg-zinc-800 hover:bg-zinc-700 text-white"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Competition Result
          </Button>
        </CardContent>
      </Card>

      {/* Stoke Sponsors */}
      <Card className={cardBg}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Heart className="w-5 h-5 text-pink-400" />
            Stoke Sponsors
            <span className={`text-xs ${textSecondary} ml-2`}>(Parents, Local Shops)</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          {sponsorships.length > 0 ? (
            <div className="space-y-3">
              {sponsorships.map((sponsor) => (
                <div key={sponsor.id} className="flex items-center gap-3 p-3 bg-zinc-800/50 rounded-lg">
                  <div className="w-10 h-10 rounded-full bg-pink-500/20 flex items-center justify-center">
                    <Heart className="w-5 h-5 text-pink-400" />
                  </div>
                  <div className="flex-1">
                    <div className={`font-medium ${textPrimary}`}>{sponsor.sponsor_name}</div>
                    <div className={`text-xs ${textSecondary}`}>{sponsor.sponsor_type === 'parent' ? 'Family Support' : 'Local Stoke'}</div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p className={`text-center ${textSecondary} py-4`}>Add your supporters!</p>
          )}
          <Button 
            onClick={() => setShowAddSponsorModal(true)}
            variant="outline" 
            className="w-full mt-4 border-zinc-700"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Stoke Sponsor
          </Button>
        </CardContent>
      </Card>

      {/* Photographer Support Income */}
      {stokeIncome && stokeIncome.total_received > 0 && (
        <Card className={`${cardBg} border-2 border-pink-500/30 bg-gradient-to-br from-pink-500/5 to-purple-500/5`}>
          <CardHeader>
            <CardTitle className={`${textPrimary} flex items-center gap-2`}>
              <DollarSign className="w-5 h-5 text-emerald-400" />
              Photographer Support Funds
              <Badge className="ml-auto bg-emerald-500/20 text-emerald-400 border-0 text-xs">5% Fee Only</Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div className="text-center p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
                <div className="text-2xl font-bold text-emerald-400">${stokeIncome.total_received.toFixed(2)}</div>
                <div className={`text-xs ${textSecondary}`}>Funds Received</div>
              </div>
              <div className="text-center p-3 bg-pink-500/10 border border-pink-500/20 rounded-lg">
                <div className="text-2xl font-bold text-pink-400">{stokeIncome.supporter_count}</div>
                <div className={`text-xs ${textSecondary}`}>Pro Supporters</div>
              </div>
            </div>
            
            {stokeIncome.income_records?.length > 0 && (
              <div className="space-y-2">
                <div className={`text-sm font-medium ${textSecondary} mb-2`}>Recent Support from Pros</div>
                {stokeIncome.income_records.slice(0, 3).map((record) => (
                  <div 
                    key={record.id}
                    className="flex items-center gap-3 p-2 bg-gradient-to-r from-emerald-500/10 to-pink-500/10 border border-emerald-500/20 rounded-lg"
                  >
                    <Avatar className="w-8 h-8">
                      <AvatarImage src={record.donor_avatar} />
                      <AvatarFallback className="bg-emerald-500/20 text-emerald-400 text-xs">
                        {record.donor_name?.charAt(0) || 'P'}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 min-w-0">
                      <div className={`text-sm font-medium ${textPrimary} truncate`}>{record.donor_name}</div>
                      <div className={`text-xs ${textSecondary}`}>
                        {new Date(record.created_at).toLocaleDateString()}
                      </div>
                    </div>
                    <div className="text-emerald-400 font-bold">+${record.net_amount.toFixed(2)}</div>
                  </div>
                ))}
              </div>
            )}
            
            <div className="mt-4 p-3 bg-cyan-500/10 border border-cyan-500/20 rounded-lg text-center">
              <Heart className="w-6 h-6 text-pink-400 mx-auto mb-1" />
              <p className={`text-xs ${textSecondary}`}>
                Pro photographers in your community are helping fund your surf journey! 
                Groms pay only 5% platform fee (vs 10% for others).
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Grom-Friendly Coaches & Photographers */}
      <Card className={cardBg}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Users className="w-5 h-5 text-emerald-400" />
            Grom-Friendly Mentors
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className={`text-sm ${textSecondary} mb-3`}>
            Coaches and photographers experienced with young surfers
          </p>
          <div className="space-y-3">
            {gromCoaches.map((coach) => (
              <div 
                key={coach.id}
                className="flex items-center gap-3 p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg"
              >
                <Avatar className="w-10 h-10 border-2 border-emerald-500/50">
                  <AvatarImage src={coach.avatar} />
                  <AvatarFallback className="bg-emerald-500/20 text-emerald-400">
                    {coach.name?.charAt(0)}
                  </AvatarFallback>
                </Avatar>
                <div className="flex-1">
                  <div className={`font-medium ${textPrimary}`}>{coach.name}</div>
                  <div className={`text-xs ${textSecondary}`}>{coach.specialty}</div>
                </div>
                <Badge className="bg-emerald-500/20 text-emerald-400 border-0 text-xs">Grom Friendly</Badge>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Crew Stats for The Inside */}
      <Card className={cardBg} data-testid="inside-crew-stats">
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Users className="w-5 h-5 text-cyan-400" />
            Your Crew Stats
          </CardTitle>
        </CardHeader>
        <CardContent>
          <CrewLeaderboard 
            userId={user?.id} 
            variant="profile"
            showPrivacyControls={true}
          />
        </CardContent>
      </Card>

      {/* Add Competition Result Modal - Reusing from ThePeakHub pattern */}
      <Dialog open={showAddResultModal} onOpenChange={setShowAddResultModal}>
        <DialogContent className="bg-zinc-900 border-zinc-800 text-white max-w-md">
          <DialogHeader>
            <DialogTitle>Add Grom Series Result</DialogTitle>
          </DialogHeader>
          <AddResultForm
            userId={user?.id}
            defaultTier="Grom_Series"
            onSuccess={() => {
              setShowAddResultModal(false);
              fetchGromData();
              toast.success('Result added!');
            }}
          />
        </DialogContent>
      </Dialog>

      {/* Add Sponsor Modal */}
      <Dialog open={showAddSponsorModal} onOpenChange={setShowAddSponsorModal}>
        <DialogContent className="bg-zinc-900 border-zinc-800 text-white max-w-md">
          <DialogHeader>
            <DialogTitle>Add Stoke Sponsor</DialogTitle>
          </DialogHeader>
          <AddStokeSponsorForm
            userId={user?.id}
            onSuccess={() => {
              setShowAddSponsorModal(false);
              fetchGromData();
              toast.success('Sponsor added!');
            }}
          />
        </DialogContent>
      </Dialog>
    </div>
  );
};

// Add Result Form Component
const AddResultForm = ({ userId, defaultTier, onSuccess }) => {
  const [formData, setFormData] = useState({
    event_name: '',
    event_date: '',
    placing: '',
    heat_wins: '',
    proof_image_url: ''
  });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!formData.event_name || !formData.event_date || !formData.placing) {
      toast.error('Please fill required fields');
      return;
    }

    setLoading(true);
    try {
      await apiClient.post(`/career/competition-results?surfer_id=${userId}`, {
        ...formData,
        event_tier: defaultTier,
        placing: parseInt(formData.placing),
        heat_wins: formData.heat_wins ? parseInt(formData.heat_wins) : 0
      });
      onSuccess();
    } catch (error) {
      toast.error('Failed to add result');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4">
      <Input
        placeholder="Event Name *"
        value={formData.event_name}
        onChange={(e) => setFormData({ ...formData, event_name: e.target.value })}
        className="bg-zinc-800 border-zinc-700"
      />
      <Input
        type="date"
        value={formData.event_date}
        onChange={(e) => setFormData({ ...formData, event_date: e.target.value })}
        className="bg-zinc-800 border-zinc-700"
      />
      <div className="grid grid-cols-2 gap-3">
        <Input
          type="number"
          placeholder="Your Placing *"
          value={formData.placing}
          onChange={(e) => setFormData({ ...formData, placing: e.target.value })}
          className="bg-zinc-800 border-zinc-700"
        />
        <Input
          type="number"
          placeholder="Heat Wins"
          value={formData.heat_wins}
          onChange={(e) => setFormData({ ...formData, heat_wins: e.target.value })}
          className="bg-zinc-800 border-zinc-700"
        />
      </div>
      <Input
        placeholder="Proof Image URL (optional)"
        value={formData.proof_image_url}
        onChange={(e) => setFormData({ ...formData, proof_image_url: e.target.value })}
        className="bg-zinc-800 border-zinc-700"
      />
      <DialogFooter>
        <Button onClick={handleSubmit} disabled={loading} className="w-full bg-cyan-500 text-black hover:bg-cyan-400">
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Add Result'}
        </Button>
      </DialogFooter>
    </div>
  );
};

// Add Stoke Sponsor Form
const AddStokeSponsorForm = ({ userId, onSuccess }) => {
  const [formData, setFormData] = useState({
    sponsor_name: '',
    sponsor_type: 'stoke_sponsor'
  });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!formData.sponsor_name) {
      toast.error('Please enter sponsor name');
      return;
    }

    setLoading(true);
    try {
      await apiClient.post(`/career/sponsorships?surfer_id=${userId}`, {
        ...formData,
        sponsorship_tier: 'stoke'
      });
      onSuccess();
    } catch (error) {
      toast.error('Failed to add sponsor');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4">
      <Input
        placeholder="Sponsor Name *"
        value={formData.sponsor_name}
        onChange={(e) => setFormData({ ...formData, sponsor_name: e.target.value })}
        className="bg-zinc-800 border-zinc-700"
      />
      <select
        value={formData.sponsor_type}
        onChange={(e) => setFormData({ ...formData, sponsor_type: e.target.value })}
        className="w-full p-2 rounded-lg bg-zinc-800 border border-zinc-700 text-white"
      >
        <option value="parent">Family Support</option>
        <option value="local_shop">Local Surf Shop</option>
        <option value="stoke_sponsor">Stoke Sponsor</option>
      </select>
      <DialogFooter>
        <Button onClick={handleSubmit} disabled={loading} className="w-full bg-pink-500 text-black hover:bg-pink-400">
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Add Sponsor'}
        </Button>
      </DialogFooter>
    </div>
  );
};

export default TheInsideHub;

﻿import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { 
  Trophy, Star, Award, 
  ChevronRight, Loader2, Plus, CheckCircle, Clock, Medal, Sparkles, Crown, Waves, Heart
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';
import { Badge } from './ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from './ui/dialog';
import { Input } from './ui/input';
import { toast } from 'sonner';
import apiClient from '../lib/apiClient';
import { GoldPassSlotCard } from './GoldPassSlotCard';
import logger from '../utils/logger';
import { getFullUrl } from '../utils/media';

/**
 * The Peak - Career Hub for Pro-Elite (⭐+) and Competitive (🏄) surfers
 * Features: Competition Stats, Sponsorship Manager, Gold-Pass Booking, Elite Talent Feed
 */
export const ThePeakHub = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const navigate = useNavigate();
  
  const [careerStats, setCareerStats] = useState(null);
  const [sponsorships, setSponsorships] = useState([]);
  const [competitionResults, setCompetitionResults] = useState([]);
  const [elitePhotographers, setElitePhotographers] = useState([]);
  const [goldPassSlots, setGoldPassSlots] = useState([]);
  const [stokeIncome, setStokeIncome] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showAddResultModal, setShowAddResultModal] = useState(false);
  const [showAddSponsorModal, setShowAddSponsorModal] = useState(false);

  const isLight = theme === 'light';
  const cardBg = isLight ? 'bg-white border-gray-200' : 'bg-card border-border';
  const textPrimary = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  useEffect(() => {
    if (user?.id) {
      fetchCareerData();
    }
  }, [user?.id]);

  const fetchCareerData = async () => {
    setLoading(true);
    try {
      const [statsRes, sponsorsRes, resultsRes, photographersRes, slotsRes, stokeRes] = await Promise.all([
        apiClient.get(`/career/stats/${user.id}`).catch(() => ({ data: null })),
        apiClient.get(`/career/sponsorships/${user.id}`).catch(() => ({ data: { sponsorships: [] } })),
        apiClient.get(`/career/competition-results/${user.id}`).catch(() => ({ data: { results: [] } })),
        apiClient.get(`/career/elite-photographers`).catch(() => ({ data: { elite_photographers: [] } })),
        apiClient.get(`/career/gold-pass/available?surfer_id=${user.id}`).catch(() => ({ data: { slots: [] } })),
        apiClient.get(`/career/stoke-sponsor/income/${user.id}`).catch(() => ({ data: null }))
      ]);
      
      setCareerStats(statsRes.data);
      setSponsorships(sponsorsRes.data?.sponsorships || []);
      setCompetitionResults(resultsRes.data?.results || []);
      setElitePhotographers(photographersRes.data?.elite_photographers || []);
      setGoldPassSlots(slotsRes.data?.slots || []);
      setStokeIncome(stokeRes.data);
    } catch (error) {
      logger.error('Failed to fetch career data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getTierBadge = (tier) => {
    if (tier === 'pro_elite') {
      return (
        <Badge className="bg-gradient-to-r from-yellow-400 to-amber-500 text-black border-0">
          <Star className="w-3 h-3 mr-1" /> Pro-Elite
        </Badge>
      );
    }
    if (tier === 'competitive') {
      return (
        <Badge className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30">
          <Waves className="w-3 h-3 mr-1" /> Competitive
        </Badge>
      );
    }
    return null;
  };

  const getVerificationBadge = (status) => {
    if (status === 'community_verified') {
      return <CheckCircle className="w-4 h-4 text-emerald-400" title="Community Verified" />;
    }
    if (status === 'api_synced') {
      return <CheckCircle className="w-4 h-4 text-cyan-400" title="Verified Sync" />;
    }
    return <Clock className="w-4 h-4 text-yellow-400" title="Pending Verification" />;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 text-yellow-400 animate-spin" />
      </div>
    );
  }

  return (
    <div 
      className="space-y-6 pb-24 md:pb-6" 
      data-testid="the-peak-hub"
      style={{ paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) + 80px)' }}
    >
      {/* Header */}
      <div className="text-center">
        <h1 className={`text-3xl font-bold ${textPrimary} flex items-center justify-center gap-2`} style={{ fontFamily: 'Oswald' }}>
          <Crown className="w-8 h-8 text-yellow-400" />
          The Peak
        </h1>
        <p className={`${textSecondary} mt-1`}>Your Pro Career Dashboard</p>
        {careerStats?.elite_tier && (
          <div className="mt-2">{getTierBadge(careerStats.elite_tier)}</div>
        )}
      </div>

      {/* Career Stats Card */}
      <Card className={`${cardBg} border-2 border-yellow-500/30 bg-gradient-to-br from-yellow-500/5 to-orange-500/5`}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Trophy className="w-5 h-5 text-yellow-400" />
            Competition Stats
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="text-center p-3 bg-zinc-800/50 rounded-lg">
              <div className="text-2xl font-bold text-yellow-400">{careerStats?.stats?.event_wins || 0}</div>
              <div className={`text-xs ${textSecondary}`}>Event Wins</div>
            </div>
            <div className="text-center p-3 bg-zinc-800/50 rounded-lg">
              <div className="text-2xl font-bold text-amber-400">{careerStats?.stats?.podium_finishes || 0}</div>
              <div className={`text-xs ${textSecondary}`}>Podiums</div>
            </div>
            <div className="text-center p-3 bg-zinc-800/50 rounded-lg">
              <div className="text-2xl font-bold text-cyan-400">{careerStats?.stats?.total_heat_wins || 0}</div>
              <div className={`text-xs ${textSecondary}`}>Heat Wins</div>
            </div>
            <div className="text-center p-3 bg-zinc-800/50 rounded-lg">
              <div className="text-2xl font-bold text-emerald-400">{careerStats?.stats?.avg_wave_score || '-'}</div>
              <div className={`text-xs ${textSecondary}`}>Avg Score</div>
            </div>
          </div>
          
          {careerStats?.world_ranking && (
            <div className="mt-4 p-3 bg-gradient-to-r from-yellow-500/20 to-amber-500/20 rounded-lg text-center">
              <div className="text-sm text-yellow-400">World Ranking</div>
              <div className="text-3xl font-bold text-white">#{careerStats.world_ranking}</div>
            </div>
          )}

          <Button 
            onClick={() => setShowAddResultModal(true)}
            className="w-full mt-4 bg-zinc-800 hover:bg-zinc-700 text-white"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Competition Result
          </Button>
        </CardContent>
      </Card>

      {/* Recent Results */}
      {competitionResults.length > 0 && (
        <Card className={cardBg}>
          <CardHeader>
            <CardTitle className={`${textPrimary} flex items-center gap-2`}>
              <Medal className="w-5 h-5 text-amber-400" />
              Recent Results
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {competitionResults.slice(0, 5).map((result) => (
              <div 
                key={result.id}
                className={`flex items-center justify-between p-3 rounded-lg ${
                  result.placing <= 3 
                    ? 'bg-gradient-to-r from-yellow-500/10 to-amber-500/10 border border-yellow-500/20'
                    : 'bg-zinc-800/50'
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                    result.placing === 1 ? 'bg-yellow-500 text-black' :
                    result.placing === 2 ? 'bg-gray-300 text-black' :
                    result.placing === 3 ? 'bg-amber-600 text-white' :
                    'bg-zinc-700 text-white'
                  }`}>
                    {result.placing === 1 ? '🥇' : result.placing === 2 ? '🥈' : result.placing === 3 ? '🥉' : result.placing}
                  </div>
                  <div>
                    <div className={`font-medium ${textPrimary}`}>{result.event_name}</div>
                    <div className={`text-xs ${textSecondary}`}>{result.event_date} • {result.event_location}</div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  {getVerificationBadge(result.verification_status)}
                  {result.xp_awarded > 0 && (
                    <Badge className="bg-cyan-500/20 text-cyan-400 border-0 text-xs">
                      +{result.xp_awarded} XP
                    </Badge>
                  )}
                </div>
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      {/* Sponsorship Manager */}
      <Card className={cardBg}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Award className="w-5 h-5 text-emerald-400" />
            Sponsorship Manager
          </CardTitle>
        </CardHeader>
        <CardContent>
          {sponsorships.length > 0 ? (
            <div className="space-y-3">
              {sponsorships.map((sponsor) => (
                <div key={sponsor.id} className="flex items-center gap-3 p-3 bg-zinc-800/50 rounded-lg">
                  {sponsor.sponsor_logo_url ? (
                    <img src={sponsor.sponsor_logo_url} alt={sponsor.sponsor_name} className="w-12 h-12 rounded-lg object-contain bg-white p-1" />
                  ) : (
                    <div className="w-12 h-12 rounded-lg bg-emerald-500/20 flex items-center justify-center">
                      <Award className="w-6 h-6 text-emerald-400" />
                    </div>
                  )}
                  <div className="flex-1">
                    <div className={`font-medium ${textPrimary}`}>{sponsor.sponsor_name}</div>
                    <div className={`text-xs ${textSecondary}`}>{sponsor.sponsorship_tier || 'Sponsor'}</div>
                  </div>
                  {sponsor.auto_pay_enabled && (
                    <Badge className="bg-emerald-500/20 text-emerald-400 border-0 text-xs">Auto-Pay</Badge>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <p className={`text-center ${textSecondary} py-4`}>No sponsorships yet</p>
          )}
          <Button 
            onClick={() => setShowAddSponsorModal(true)}
            variant="outline" 
            className="w-full mt-4 border-zinc-700"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Sponsor
          </Button>
        </CardContent>
      </Card>

      {/* Stoke Sponsor Income - Money from Photographers */}
      {stokeIncome && stokeIncome.total_received > 0 && (
        <Card className={`${cardBg} border-2 border-pink-500/30 bg-gradient-to-br from-pink-500/5 to-red-500/5`}>
          <CardHeader>
            <CardTitle className={`${textPrimary} flex items-center gap-2`}>
              <Heart className="w-5 h-5 text-pink-400" />
              Stoke Sponsor Income
              <Badge className="ml-auto bg-pink-500/20 text-pink-400 border-0 text-xs">NEW</Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div className="text-center p-3 bg-zinc-800/50 rounded-lg">
                <div className="text-2xl font-bold text-pink-400">${stokeIncome.total_received.toFixed(2)}</div>
                <div className={`text-xs ${textSecondary}`}>Total Received</div>
              </div>
              <div className="text-center p-3 bg-zinc-800/50 rounded-lg">
                <div className="text-2xl font-bold text-emerald-400">{stokeIncome.supporter_count}</div>
                <div className={`text-xs ${textSecondary}`}>Supporters</div>
              </div>
            </div>
            
            {stokeIncome.income_records?.length > 0 && (
              <div className="space-y-2">
                <div className={`text-sm font-medium ${textSecondary} mb-2`}>Recent Support</div>
                {stokeIncome.income_records.slice(0, 3).map((record) => (
                  <div 
                    key={record.id}
                    className="flex items-center gap-3 p-2 bg-pink-500/10 border border-pink-500/20 rounded-lg"
                  >
                    <Avatar className="w-8 h-8">
                      <AvatarImage src={record.donor_avatar} />
                      <AvatarFallback className="bg-pink-500/20 text-pink-400 text-xs">
                        {record.donor_name?.charAt(0) || 'P'}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 min-w-0">
                      <div className={`text-sm font-medium ${textPrimary} truncate`}>{record.donor_name}</div>
                      <div className={`text-xs ${textSecondary}`}>
                        {new Date(record.created_at).toLocaleDateString()}
                      </div>
                    </div>
                    <div className="text-pink-400 font-medium">+${record.net_amount.toFixed(2)}</div>
                  </div>
                ))}
              </div>
            )}
            
            <p className={`text-xs ${textSecondary} mt-3 text-center`}>
              Photographers in the ecosystem are supporting your surf career!
            </p>
          </CardContent>
        </Card>
      )}

      {/* Gold-Pass Booking Slots - Using the proper component */}
      {goldPassSlots.length > 0 && (
        <Card className={`${cardBg} border-2 border-yellow-500/30`}>
          <CardHeader>
            <CardTitle className={`${textPrimary} flex items-center gap-2`}>
              <Crown className="w-5 h-5 text-yellow-400" />
              Gold Pass Bookings
              <Badge className="ml-auto bg-gradient-to-r from-yellow-400 to-amber-500 text-black border-0 text-xs">
                {user?.subscription_tier === 'tier_3' ? 'ACTIVE' : 'LOCKED'}
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className={`text-sm ${textSecondary} mb-3`}>
              {user?.subscription_tier === 'tier_3'
                ? `${goldPassSlots.length} exclusive slots available for early booking`
                : 'Upgrade to Premium for 2-hour early access to all slots'}
            </p>
            <div className="space-y-3">
              {goldPassSlots.slice(0, 3).map((slot) => (
                <GoldPassSlotCard
                  key={slot.id}
                  slot={slot}
                  hasGoldPass={user?.subscription_tier === 'tier_3'}
                  onBook={async (s) => {
                    try {
                      await apiClient.post(`/career/gold-pass/${s.id}/book?surfer_id=${user.id}`);
                      toast.success('Slot booked successfully!');
                      fetchCareerData();
                    } catch (error) {
                      toast.error(error.response?.data?.detail || 'Failed to book slot');
                    }
                  }}
                  showPhotographer={true}
                />
              ))}
            </div>
            {goldPassSlots.length > 3 && (
              <Button 
                variant="ghost" 
                className="w-full mt-3 text-yellow-400 hover:bg-yellow-500/10"
                onClick={() => navigate('/bookings')}
              >
                View All {goldPassSlots.length} Slots
                <ChevronRight className="w-4 h-4 ml-1" />
              </Button>
            )}
          </CardContent>
        </Card>
      )}

      {/* Elite Photographers Directory */}
      <Card className={`${cardBg} border-2 border-yellow-500/30`}>
        <CardHeader>
          <CardTitle className={`${textPrimary} flex items-center gap-2`}>
            <Sparkles className="w-5 h-5 text-yellow-400" />
            Elite Talent Feed
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className={`text-sm ${textSecondary} mb-3`}>
            Vetted photographers who shoot world-class talent
          </p>
          <div className="space-y-3">
            {elitePhotographers.slice(0, 3).map((photographer) => (
              <div 
                key={photographer.id}
                className="flex items-center gap-3 p-3 bg-gradient-to-r from-yellow-500/10 to-amber-500/10 border border-yellow-500/20 rounded-lg cursor-pointer hover:border-yellow-500/50 transition-colors"
                onClick={() => navigate(`/profile/${photographer.id}`)}
              >
                <Avatar className="w-12 h-12 border-2 border-yellow-500/50">
                  <AvatarImage src={getFullUrl(photographer.avatar_url)} />
                  <AvatarFallback className="bg-yellow-500/20 text-yellow-400">
                    {photographer.full_name?.charAt(0) || 'P'}
                  </AvatarFallback>
                </Avatar>
                <div className="flex-1">
                  <div className={`font-medium ${textPrimary}`}>{photographer.full_name}</div>
                  <div className={`text-xs ${textSecondary}`}>
                    {photographer.is_verified && <CheckCircle className="w-3 h-3 inline mr-1 text-cyan-400" />}
                    Elite Photographer
                  </div>
                </div>
                <ChevronRight className="w-5 h-5 text-yellow-400" />
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Add Competition Result Modal */}
      <AddCompetitionResultModal
        isOpen={showAddResultModal}
        onClose={() => setShowAddResultModal(false)}
        userId={user?.id}
        onSuccess={() => {
          setShowAddResultModal(false);
          fetchCareerData();
          toast.success('Competition result added!');
        }}
      />

      {/* Add Sponsor Modal */}
      <AddSponsorModal
        isOpen={showAddSponsorModal}
        onClose={() => setShowAddSponsorModal(false)}
        userId={user?.id}
        onSuccess={() => {
          setShowAddSponsorModal(false);
          fetchCareerData();
          toast.success('Sponsor added!');
        }}
      />
    </div>
  );
};

// Add Competition Result Modal
const AddCompetitionResultModal = ({ isOpen, onClose, userId, onSuccess }) => {
  const [formData, setFormData] = useState({
    event_name: '',
    event_date: '',
    event_location: '',
    event_tier: 'Local',
    placing: '',
    total_competitors: '',
    heat_wins: '',
    avg_wave_score: '',
    proof_image_url: ''
  });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!formData.event_name || !formData.event_date || !formData.placing) {
      toast.error('Please fill required fields');
      return;
    }

    setLoading(true);
    try {
      await apiClient.post(`/career/competition-results?surfer_id=${userId}`, {
        ...formData,
        placing: parseInt(formData.placing),
        total_competitors: formData.total_competitors ? parseInt(formData.total_competitors) : null,
        heat_wins: formData.heat_wins ? parseInt(formData.heat_wins) : 0,
        avg_wave_score: formData.avg_wave_score ? parseFloat(formData.avg_wave_score) : null
      });
      onSuccess();
    } catch (error) {
      toast.error('Failed to add result');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-zinc-900 border-zinc-800 text-white max-w-md">
        <DialogHeader>
          <DialogTitle>Add Competition Result</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <Input
            placeholder="Event Name *"
            value={formData.event_name}
            onChange={(e) => setFormData({ ...formData, event_name: e.target.value })}
            className="bg-zinc-800 border-zinc-700"
          />
          <Input
            type="date"
            placeholder="Event Date *"
            value={formData.event_date}
            onChange={(e) => setFormData({ ...formData, event_date: e.target.value })}
            className="bg-zinc-800 border-zinc-700"
          />
          <Input
            placeholder="Location"
            value={formData.event_location}
            onChange={(e) => setFormData({ ...formData, event_location: e.target.value })}
            className="bg-zinc-800 border-zinc-700"
          />
          <select
            value={formData.event_tier}
            onChange={(e) => setFormData({ ...formData, event_tier: e.target.value })}
            className="w-full p-2 rounded-lg bg-zinc-800 border border-zinc-700 text-white"
          >
            <option value="WSL_CT">WSL Championship Tour</option>
            <option value="WSL_QS">WSL Qualifying Series</option>
            <option value="Regional">Regional</option>
            <option value="Local">Local</option>
            <option value="Grom_Series">Grom Series</option>
          </select>
          <div className="grid grid-cols-2 gap-3">
            <Input
              type="number"
              placeholder="Your Placing *"
              value={formData.placing}
              onChange={(e) => setFormData({ ...formData, placing: e.target.value })}
              className="bg-zinc-800 border-zinc-700"
            />
            <Input
              type="number"
              placeholder="Total Competitors"
              value={formData.total_competitors}
              onChange={(e) => setFormData({ ...formData, total_competitors: e.target.value })}
              className="bg-zinc-800 border-zinc-700"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Input
              type="number"
              placeholder="Heat Wins"
              value={formData.heat_wins}
              onChange={(e) => setFormData({ ...formData, heat_wins: e.target.value })}
              className="bg-zinc-800 border-zinc-700"
            />
            <Input
              type="number"
              step="0.1"
              placeholder="Avg Wave Score"
              value={formData.avg_wave_score}
              onChange={(e) => setFormData({ ...formData, avg_wave_score: e.target.value })}
              className="bg-zinc-800 border-zinc-700"
            />
          </div>
          <Input
            placeholder="Proof Image URL (trophy/bracket photo)"
            value={formData.proof_image_url}
            onChange={(e) => setFormData({ ...formData, proof_image_url: e.target.value })}
            className="bg-zinc-800 border-zinc-700"
          />
          <p className="text-xs text-gray-400">Upload a photo of your trophy or bracket to earn "Community Verified" badge</p>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose} className="border-zinc-700">Cancel</Button>
          <Button onClick={handleSubmit} disabled={loading} className="bg-yellow-500 text-black hover:bg-yellow-400">
            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Add Result'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

// Add Sponsor Modal
const AddSponsorModal = ({ isOpen, onClose, userId, onSuccess }) => {
  const [formData, setFormData] = useState({
    sponsor_name: '',
    sponsor_type: 'brand',
    sponsor_logo_url: '',
    sponsor_website: '',
    sponsorship_tier: 'supporting'
  });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!formData.sponsor_name) {
      toast.error('Please enter sponsor name');
      return;
    }

    setLoading(true);
    try {
      await apiClient.post(`/career/sponsorships?surfer_id=${userId}`, formData);
      onSuccess();
    } catch (error) {
      toast.error('Failed to add sponsor');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-zinc-900 border-zinc-800 text-white max-w-md">
        <DialogHeader>
          <DialogTitle>Add Sponsor</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <Input
            placeholder="Sponsor Name *"
            value={formData.sponsor_name}
            onChange={(e) => setFormData({ ...formData, sponsor_name: e.target.value })}
            className="bg-zinc-800 border-zinc-700"
          />
          <select
            value={formData.sponsor_type}
            onChange={(e) => setFormData({ ...formData, sponsor_type: e.target.value })}
            className="w-full p-2 rounded-lg bg-zinc-800 border border-zinc-700 text-white"
          >
            <option value="brand">Brand</option>
            <option value="local_shop">Local Shop</option>
            <option value="stoke_sponsor">Stoke Sponsor</option>
          </select>
          <select
            value={formData.sponsorship_tier}
            onChange={(e) => setFormData({ ...formData, sponsorship_tier: e.target.value })}
            className="w-full p-2 rounded-lg bg-zinc-800 border border-zinc-700 text-white"
          >
            <option value="title">Title Sponsor</option>
            <option value="major">Major Sponsor</option>
            <option value="supporting">Supporting Sponsor</option>
            <option value="stoke">Stoke Sponsor</option>
          </select>
          <Input
            placeholder="Logo URL"
            value={formData.sponsor_logo_url}
            onChange={(e) => setFormData({ ...formData, sponsor_logo_url: e.target.value })}
            className="bg-zinc-800 border-zinc-700"
          />
          <Input
            placeholder="Website URL"
            value={formData.sponsor_website}
            onChange={(e) => setFormData({ ...formData, sponsor_website: e.target.value })}
            className="bg-zinc-800 border-zinc-700"
          />
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose} className="border-zinc-700">Cancel</Button>
          <Button onClick={handleSubmit} disabled={loading} className="bg-emerald-500 text-black hover:bg-emerald-400">
            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Add Sponsor'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default ThePeakHub;

import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { usePersona } from '../contexts/PersonaContext';
import { MapPin, Search, Bell, Settings, ShoppingBag, Zap, Heart, Shield, Users, Compass, Backpack } from 'lucide-react';
import { SurferSessionHub } from './SurferSessionHub';
import { DutyStationIcon } from './DutyStationDrawer';
import { BackpackDrawer } from './BackpackDrawer';
import { StokedDrawer } from './StokedDrawer';
import { NotificationsDrawer } from './NotificationsDrawer';
import { ExclusiveAreaDrawer, hasExclusiveArea, getAreaType, getAreaIcon, getAreaColor } from './ExclusiveAreaDrawer';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { getUnreadCount } from '../services/notificationService';
import logger from '../utils/logger';
import { ROLES } from '../constants/roles';


/**
 * TopNav - Global Header Navigation (Restructured April 2026)
 * 
 * NEW LAYOUT - Map-First with Backpack & Dynamic Persona Icon:
 * 
 * PHOTOGRAPHERS (Hobbyist/Photographer/Approved Pro) - 8 Icons:
 * 1. Duty Station Icon (Far Left) - Unified Live/On-Demand Drawer
 * 2. Map Icon - Primary navigation
 * 3. Backpack Icon - Opens drawer with Passport, Wallet, Surf Alerts
 * 4. Explore Icon - Browse trending, spots, broadcasts
 * 5. Session Hub Icon - Sessions drawer
 * 6. Search Icon
 * 7. Notification Bell
 * 8. Settings Icon (Far Right)
 * 
 * GROM PARENTS - 7 Icons:
 * 1. Map Icon (Far Left) - Primary navigation
 * 2. Backpack Icon - Opens drawer with Passport, Wallet, Surf Alerts
 * 3. Explore Icon - Browse trending, spots, broadcasts
 * 4. Dynamic Persona Icon - Opens Grom HQ
 * 5. Search Icon
 * 6. Notification Bell
 * 7. Settings Icon (Far Right)
 * 
 * SURFERS - 6 Icons:
 * 1. Map Icon (Far Left) - Primary navigation
 * 2. Backpack Icon - Opens drawer with Passport, Wallet, Surf Alerts
 * 3. Dynamic Persona Icon - Opens StokedDrawer or exclusive area
 * 4. Search Icon
 * 5. Notification Bell
 * 6. Settings Icon (Far Right)
 * 
 * Dynamic Persona Icon Logic:
 * - Groms: Waves Icon -> The Inside (ExclusiveAreaDrawer)
 * - Regular Surfers: Gear Icon -> StokedDrawer
 * - Competitive Surfers (Comp/Pro): Stoked Icon (Zap) -> StokedDrawer
 * - Photographers: Heart Icon -> /impacted (Impact Dashboard)
 * - Grom Parents: Shield Icon -> /grom-hq
 * 
 * NOTE: Messages moved to BottomNav for thumb-zone accessibility
 * NOTE: Explore added to TopNav for photographers/grom parents (not in their BottomNav)
 */
export const TopNav = () => {
  const { user } = useAuth();
  const { getEffectiveRole, isGodMode, isPersonaBarActive } = usePersona();
  const navigate = useNavigate();
  const location = useLocation();
  const [unreadCount, setUnreadCount] = useState(0);
  const [backpackOpen, setBackpackOpen] = useState(false);
  const [stokedOpen, setStokedOpen] = useState(false);
  const [exclusiveAreaOpen, setExclusiveAreaOpen] = useState(false);
  const [gromHQDrawerOpen, setGromHQDrawerOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [logoSpinning, setLogoSpinning] = useState(false);

  // Logo click: refresh current page in-place (same as Sidebar)
  const handleLogoClick = useCallback(() => {
    if (location.pathname === '/feed') {
      window.dispatchEvent(new CustomEvent('feed:refresh'));
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setLogoSpinning(true);
    setTimeout(() => setLogoSpinning(false), 600);
  }, [location.pathname]);

  // Close all drawers when route changes (e.g., when BottomNav item is clicked)
  useEffect(() => {
    setBackpackOpen(false);
    setStokedOpen(false);
    setExclusiveAreaOpen(false);
    setGromHQDrawerOpen(false);
    setNotificationsOpen(false);
  }, [location.pathname]);

  // Check if God Mode banner is active (need to shift TopNav down)
  const _isGodModeBannerVisible = user?.is_admin && isGodMode && isPersonaBarActive;

  // Get effective role (respects God Mode persona masking)
  const effectiveRole = getEffectiveRole(user?.role);
  
  // All photographer roles get the Duty Station icon (Hobbyist, Photographer, Approved Pro)
  const isPhotographer = ['Hobbyist', 'Photographer', 'Approved Pro'].includes(effectiveRole);
  
  // Check if user has exclusive area access (Grom, Comp Surfer, Pro)
  // Surfers in competitive/pro surf_mode get the matching exclusive area
  const isProSurferMode = user?.surf_mode === 'pro';
  const isCompetitiveSurferMode = user?.surf_mode === 'competitive';
  const isCompetitiveSurfer = isCompetitiveSurferMode || isProSurferMode;
  // Map surf_mode to the equivalent role for icon/drawer resolution
  const resolvedRole = effectiveRole === ROLES.SURFER
    ? (isProSurferMode ? 'Pro' : isCompetitiveSurferMode ? 'Comp Surfer' : effectiveRole)
    : effectiveRole;
  const hasExclusiveAccess = hasExclusiveArea(resolvedRole);
  const exclusiveAreaType = getAreaType(resolvedRole);
  const ExclusiveIcon = getAreaIcon(resolvedRole);
  const exclusiveIconColor = getAreaColor(resolvedRole);
  
  // Role categorization for Dynamic Persona Icon
  const isGromParent = effectiveRole === ROLES.GROM_PARENT || user?.is_grom_parent === true;
  // isCompetitive: true for Comp Surfer/Pro roles OR regular Surfer in competitive/pro surf_mode
  const isCompetitive = ['Comp Surfer', 'Pro'].includes(effectiveRole) || (effectiveRole === ROLES.SURFER && isCompetitiveSurfer);
  // Note: isPhotographer already defined above for Duty Station icon
  const _isGromOrRegularSurfer = ['Grom', 'Surfer'].includes(effectiveRole);

  // Get Dynamic Persona Icon configuration based on role
  const getPersonaIconConfig = () => {
    if (isPhotographer) {
      return {
        icon: Heart,
        label: 'Impact',
        color: 'text-pink-400',
        hoverColor: 'hover:text-pink-300'
      };
    }
    if (isCompetitive) {
      return {
        icon: Zap,
        label: 'Stoked',
        color: 'text-yellow-400',
        hoverColor: 'hover:text-yellow-300'
      };
    }
    if (effectiveRole === ROLES.GROM) {
      return {
        icon: null,  // Groms use ExclusiveArea button, no separate persona icon needed
        label: null,
        color: '',
        hoverColor: ''
      };
    }
    // Default: Regular Surfers get Gear
    return {
      icon: ShoppingBag,
      label: 'Gear',
      color: 'text-emerald-400',
      hoverColor: 'hover:text-emerald-300'
    };
  };

  const personaConfig = getPersonaIconConfig();
  const PersonaIcon = personaConfig.icon;

  const fetchUnreadCount = useCallback(async () => {
    if (!user?.id) return;
    try {
      const response = await getUnreadCount(user.id);
      setUnreadCount(response.data.unread_count || 0);
    } catch (error) {
      logger.error('Failed to fetch notification count:', error);
    }
  }, [user?.id]);

  useEffect(() => {
    if (user?.id) {
      fetchUnreadCount();
      // Poll every 30 seconds for new notifications
      const interval = setInterval(() => {
        fetchUnreadCount();
      }, 30000);
      return () => clearInterval(interval);
    }
  }, [user?.id, fetchUnreadCount]);

  return (
    <>
      <header 
        className="fixed left-0 right-0 z-[100] bg-background border-b border-border md:hidden transition-all duration-200 top-0"
        style={{ 
          paddingTop: 'env(safe-area-inset-top, 0px)',
          paddingLeft: 'env(safe-area-inset-left, 0px)',
          paddingRight: 'env(safe-area-inset-right, 0px)'
        }}
        data-testid="top-nav"
      >
        <div className="flex items-center justify-between px-3 py-2.5">
          {/* Left Side - Logo (tap = refresh feed or go to feed) */}
          <div className="flex items-center shrink-0">
            <button
              onClick={handleLogoClick}
              className="group p-0.5"
              title={location.pathname === '/feed' ? 'Refresh feed' : 'Go to Feed'}
              aria-label={location.pathname === '/feed' ? 'Refresh feed' : 'Go to Feed'}
            >
              <img
                src="https://customer-assets.emergentagent.com/job_raw-surf-os/artifacts/9llcl5mg_Rawig6-500x500.png"
                alt="Raw Surf"
                className="w-7 h-7 group-hover:scale-110"
                style={{
                  transition: logoSpinning
                    ? 'transform 0.6s cubic-bezier(0.34,1.56,0.64,1)'
                    : 'transform 0.2s ease',
                  transform: logoSpinning ? 'rotate(360deg)' : 'rotate(0deg)'
                }}
              />
            </button>
          </div>

          {/* Icon Layout - Search First, then Map-First with Passport & Persona */}
          <div className="flex items-center gap-2.5">
            
            {/* Position 0: Search Icon - First in the row */}
            <button 
              onClick={() => navigate('/search')}
              className="text-muted-foreground hover:text-foreground transition-colors p-1"
              data-testid="topnav-search"
              aria-label="Search"
            >
              <Search className="w-5 h-5" />
            </button>
            
            {/* Position 1: Duty Station Icon (PHOTOGRAPHERS ONLY) */}
            {isPhotographer && (
              <DutyStationIcon />
            )}
            
            {/* Position 2 (or 1): Map Icon - PRIMARY NAVIGATION */}
            <button 
              onClick={() => navigate('/map')}
              className="text-yellow-400 hover:text-yellow-300 transition-colors p-1"
              data-testid="topnav-map"
              aria-label="Map"
            >
              <MapPin className="w-5 h-5" />
            </button>
            
            {/* Position 3 (or 2): Exclusive Area Icon - Grom/Grom Parent/Comp/Pro only */}
            {hasExclusiveAccess && ExclusiveIcon && (
              <button 
                onClick={() => {
                  setBackpackOpen(false);
                  setStokedOpen(false);
                  setGromHQDrawerOpen(false);
                  setNotificationsOpen(false);
                  setExclusiveAreaOpen(prev => !prev);
                }}
                className={`${exclusiveIconColor} hover:opacity-80 transition-colors p-1`}
                data-testid="topnav-exclusive-area"
                aria-label={
                  exclusiveAreaType === 'grom' ? 'The Inside' :
                  exclusiveAreaType === 'comp' ? 'The Impact Zone' :
                  exclusiveAreaType === 'pro' ? 'The Peak' : 'Exclusive Area'
                }
              >
                <ExclusiveIcon className="w-5 h-5" />
              </button>
            )}
            
            {/* Position 4 (or 3): Backpack Icon - Opens Backpack Drawer (Passport, Wallet, Alerts) */}
            <button 
              onClick={() => setBackpackOpen(!backpackOpen)}
              className="text-amber-400 hover:text-amber-300 transition-colors p-1"
              data-testid="topnav-backpack"
              aria-label="Backpack"
            >
              <Backpack className="w-5 h-5" />
            </button>
            
            {/* Position 4.5: Explore Icon - For PHOTOGRAPHERS & GROM PARENTS (they don't have it in BottomNav) */}
            {(isPhotographer || isGromParent) && (
              <button 
                onClick={() => navigate('/explore')}
                className="text-orange-400 hover:text-orange-300 transition-colors p-1"
                data-testid="topnav-explore"
                aria-label="Explore"
              >
                <Compass className="w-5 h-5" />
              </button>
            )}
            
            {/* Position 5 (or 4): Session Hub Icon - For SURFERS only (Photographers use Duty Station) */}
            {!isPhotographer && (
              <SurferSessionHub isPhotographer={false}>
                <button 
                  className="text-cyan-400 hover:text-cyan-300 transition-colors p-1"
                  data-testid="topnav-sessions"
                  aria-label="Session Hub"
                >
                  <Users className="w-5 h-5" />
                </button>
              </SurferSessionHub>
            )}
            
            {/* Position 5.5: Grom HQ Shield Icon - for Grom Parents */}
            {isGromParent && (
              <button 
                onClick={() => {
                  setBackpackOpen(false);
                  setStokedOpen(false);
                  setExclusiveAreaOpen(false);
                  setNotificationsOpen(false);
                  setGromHQDrawerOpen(prev => !prev);
                }}
                className="text-cyan-400 hover:text-cyan-300 transition-colors p-1"
                data-testid="topnav-grom-hq"
                aria-label="Grom HQ"
              >
                <Shield className="w-5 h-5" />
              </button>
            )}

            {/* Position 6 (or 5): Stoked/Persona Icon - Role-Based Navigation */}
            {/* Note: Groms skip this - they use the ExclusiveArea button instead */}
            {effectiveRole !== ROLES.GROM && (
              <button 
                onClick={() => {
                  if (effectiveRole === ROLES.GROM_PARENT) {
                    // Fallback for purely dedicated Grom Parents if they tap Gear
                    setStokedOpen(!stokedOpen);
                  } else if (isPhotographer) {
                    navigate('/impacted');  // Photographers → Impact Dashboard
                  } else if (isCompetitive) {
                    setStokedOpen(!stokedOpen);  // Comp/Pro → Stoked Drawer
                  } else {
                    setStokedOpen(!stokedOpen);  // Regular Surfers → Stoked/Gear Drawer
                  }
                }}
                className={`${personaConfig.color} ${personaConfig.hoverColor} transition-colors p-1`}
                data-testid="topnav-stoked"
                aria-label={personaConfig.label}
              >
                <PersonaIcon className="w-5 h-5" />
              </button>
            )}
            
            {/* Position 6 (or 5): Notifications Bell - Toggles Drawer */}
            <button 
              onClick={() => setNotificationsOpen(!notificationsOpen)}
              className={`transition-colors relative p-1 ${notificationsOpen ? 'text-yellow-400' : 'text-gray-400 hover:text-white'}`}
              data-testid="topnav-notifications"
              aria-label="Notifications"
            >
              <Bell className="w-5 h-5" />
              {unreadCount > 0 && (
                <span className="absolute -top-0.5 -right-0.5 min-w-[16px] h-[16px] px-0.5 flex items-center justify-center bg-red-500 text-white text-[9px] font-bold rounded-full">
                  {unreadCount > 99 ? '99+' : unreadCount}
                </span>
              )}
            </button>
            
            {/* Position 7 (or 6): Settings Icon */}
            <button 
              onClick={() => navigate('/settings')}
              className="text-gray-400 hover:text-white transition-colors p-1"
              data-testid="topnav-settings"
              aria-label="Settings"
            >
              <Settings className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      {/* Backpack Drawer - Contains Passport, Wallet, Surf Alerts */}
      <BackpackDrawer 
        isOpen={backpackOpen} 
        onClose={() => setBackpackOpen(false)}
        onReopen={() => setBackpackOpen(true)}
      />
      
      {/* Notifications Drawer */}
      <NotificationsDrawer
        isOpen={notificationsOpen}
        onClose={() => setNotificationsOpen(false)}
        onCountUpdate={fetchUnreadCount}
      />
      
      {/* Stoked Drawer */}
      <StokedDrawer
        isOpen={stokedOpen}
        onClose={() => setStokedOpen(false)}
      />
      
      {/* Exclusive Area Drawer - Grom (The Inside) / Comp (The Impact Zone) / Pro (The Peak) */}
      {hasExclusiveAccess && (
        <ExclusiveAreaDrawer
          isOpen={exclusiveAreaOpen}
          onClose={() => setExclusiveAreaOpen(false)}
          onOpenChange={setExclusiveAreaOpen}
          areaType={exclusiveAreaType}
        />
      )}

      {/* Grom HQ Drawer - always available if isGromParent is true */}
      {isGromParent && (
        <ExclusiveAreaDrawer
          isOpen={gromHQDrawerOpen}
          onClose={() => setGromHQDrawerOpen(false)}
          onOpenChange={setGromHQDrawerOpen}
          areaType="grom_parent"
        />
      )}
    </>
  );
};

export default TopNav;

import React, { useState, useEffect, useRef, useCallback } from 'react';

import { useNavigate } from 'react-router-dom';

import { useAuth } from '../contexts/AuthContext';

import { usePersona, ALL_PERSONAS, getExpandedRoleInfo } from '../contexts/PersonaContext';

import { useTheme } from '../contexts/ThemeContext';

import apiClient from '../lib/apiClient';

import {

  Shield, Zap, Users, DollarSign, Search, Ban, CheckCircle, 
  Loader2, ChevronDown, ChevronLeft, ChevronRight, Eye, Trash2, UserX, UserCheck, 
  Crown, Trophy, Radio, MapPin, Camera, Play, Square, Image, Video, 
  Upload, X, Check, User, FileText, ArrowLeft, Settings, Activity,
  Megaphone, History, RefreshCw, TrendingUp, PieChart, BarChart3, Wallet, AlertCircle, Edit, BarChart2,
  Headphones, Server, Flag, Mail, Layout, Lock, KeyRound
} from 'lucide-react';
