      setRecentBookings(sessionsRes.data || []);
    } catch (e) {
      logger.error('Error fetching photographer data:', e);
    } finally {
      setLoading(false);
    }
  };
  
  const avgRating = reviews.length > 0 
    ? (reviews.reduce((acc, r) => acc + (r.rating || 0), 0) / reviews.length).toFixed(1)
