/**
 * WavesFeed - Full-screen vertical video feed (TikTok/Reels style)
 * Swipe up/down to navigate, double-tap to like
 */
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { Heart, MessageCircle, Share2, Volume2, Volume1, VolumeX, Play, ChevronUp, ChevronDown, MapPin, Plus, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { Button } from './ui/button';
import logger from '../utils/logger';


/**
 * Single Wave Card - Full screen vertical video
 */
const WaveCard = ({ 
  wave, 
  isActive, 
  isMuted, 
  volume,
  onToggleMute, 
  onVolumeChange,
  onLike, 
  onComment, 
  onShare,
  onViewProfile,
  _userId
}) => {
  const videoRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showHeart, setShowHeart] = useState(false);
  const [localLiked, setLocalLiked] = useState(wave.is_liked);
  const [localLikes, setLocalLikes] = useState(wave.likes_count);
  const lastTapRef = useRef(0);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);
  const volumeTimerRef = useRef(null);
  
  // Auto-play when active
  useEffect(() => {
    if (videoRef.current) {
      if (isActive) {
        videoRef.current.play().catch(() => {});
        setIsPlaying(true);
        // Record view
        apiClient.post(`/waves/${wave.id}/view`).catch(() => {});
      } else {
        videoRef.current.pause();
        videoRef.current.currentTime = 0;
        setIsPlaying(false);
      }
    }
  }, [isActive, wave.id]);
  
  // Sync mute + volume state
  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.muted = isMuted;
      videoRef.current.volume = volume;
    }
  }, [isMuted, volume]);
  
  // Cleanup volume timer
  useEffect(() => {
    return () => {
      if (volumeTimerRef.current) clearTimeout(volumeTimerRef.current);
    };
  }, []);
  
  // Get appropriate volume icon
  const VolumeIcon = isMuted || volume === 0 ? VolumeX : volume < 0.5 ? Volume1 : Volume2;
  
  // Handle tap - single tap = play/pause, double tap = like
  const handleTap = useCallback((e) => {
    const now = Date.now();
    const DOUBLE_TAP_DELAY = 300;
    
    if (now - lastTapRef.current < DOUBLE_TAP_DELAY) {
      // Double tap - like
      e.preventDefault();
      handleDoubleTapLike();
    } else {
      // Single tap - toggle play/pause (delayed to check for double tap)
      setTimeout(() => {
        if (Date.now() - lastTapRef.current >= DOUBLE_TAP_DELAY) {
          if (videoRef.current) {
            if (videoRef.current.paused) {
              videoRef.current.play();
              setIsPlaying(true);
            } else {
              videoRef.current.pause();
              setIsPlaying(false);
            }
          }
        }
      }, DOUBLE_TAP_DELAY);
    }
    lastTapRef.current = now;
  }, []);
  
  const handleDoubleTapLike = async () => {
    // Show heart animation
    setShowHeart(true);
    setTimeout(() => setShowHeart(false), 800);
    
    // Like if not already liked
    if (!localLiked) {
      setLocalLiked(true);
      setLocalLikes(prev => prev + 1);
      onLike(wave.id);
    }
  };
  
  const handleLikeButton = async () => {
    if (localLiked) {
      setLocalLiked(false);
      setLocalLikes(prev => Math.max(0, prev - 1));
    } else {
      setLocalLiked(true);
      setLocalLikes(prev => prev + 1);
    }
    onLike(wave.id);
  };
  
  const formatCount = (count) => {
    if (count >= 1000000) return `${(count / 1000000).toFixed(1)}M`;
    if (count >= 1000) return `${(count / 1000).toFixed(1)}K`;
    return count?.toString() || '0';
  };
  
  const formatDuration = (seconds) => {
    if (!seconds) return '';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };
  
  return (
    <div 
      className="relative w-full h-full bg-black flex items-center justify-center snap-start snap-always"
      onClick={handleTap}
