// src/components/WebGLBroadcastController.js
import React, { useEffect, useRef } from 'react';
import { useRoomContext, useLocalParticipant } from '@livekit/components-react';
import { Track } from 'livekit-client';
import { WebGLVideoProcessor } from '../utils/WebGLFilterEngine';
import logger from '../utils/logger';

export const WebGLBroadcastController = ({ activeFilter, isCameraOff, isFrontCamera }) => {
  const room = useRoomContext();
  const { localParticipant } = useLocalParticipant();
  
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const processorRef = useRef(null);
  const publishedTrackRef = useRef(null);
  
  // Setup the hardware pipeline
  useEffect(() => {
    // Break off early if room hasn't hooked or the user muted their camera completely
    if (!room || !localParticipant || isCameraOff) return;

    let mediaStream = null;
    let isActive = true;

    const startPipeline = async () => {
      try {
        // Step 1: Hijack the raw hardware camera stream natively bypassing LiveKit defaults
        mediaStream = await navigator.mediaDevices.getUserMedia({ 
            video: { facingMode: isFrontCamera ? 'user' : 'environment' },
            audio: false // Audio is handled independently by the LiveKitRoom audio={true}
        });
        
        if (!isActive) return;

        // Step 2: Feed byte layers to invisible buffer video
        const video = videoRef.current;
        video.srcObject = mediaStream;
        video.muted = true;
        await video.play();

        // Step 3: Initiate the GPU Engine Matrix
        const canvas = canvasRef.current;
        // Dynamically scale the Canvas drawing buffer cleanly matching source resolution bounds
        canvas.width = video.videoWidth || 1280;
        canvas.height = video.videoHeight || 720;
        
        processorRef.current = new WebGLVideoProcessor(canvas);
        
        // Map the incoming react-state filter string to the shader program key safely
        let filterKey = 'none';
        if (activeFilter.includes('Cyber-Surf')) filterKey = 'cyber';
        if (activeFilter.includes('Golden Hour')) filterKey = 'goldenhour';
        if (activeFilter.includes('Bio-Lum')) filterKey = 'bioluminescence';
        if (activeFilter.includes('Pipeline')) filterKey = 'gopro';
        if (activeFilter.includes('Night Vision')) filterKey = 'nightvision';
        if (activeFilter.includes('Pixelate')) filterKey = 'pixelate';
        
        processorRef.current.setFilter(filterKey);
        processorRef.current.start(video);

        // Step 4: Extract mutated graphical canvas structure wrapping it into WebRTC MediaTrack
        const canvasStream = canvas.captureStream(30); // Request 30 FPS steady
        const customTrack = canvasStream.getVideoTracks()[0];

        // Step 5: Force manual publishing hook deep into peer data channel
        if (isActive) {
           const publication = await localParticipant.publishTrack(customTrack, {
               name: 'webgl-filtered-video',
               source: Track.Source.Camera
           });
           publishedTrackRef.current = publication;
           logger.info('[WebGL] Successfully published raw custom processed GPU track into LiveKit.');
        }

      } catch(err) {
        logger.error('[WebGL] Pipeline failure, hardware crashed:', err);
      }
    };

    startPipeline();

    // Deep Teardown Lifecycle
    return () => {
       isActive = false;
       if (processorRef.current) {
           processorRef.current.stop();
       }
       if (mediaStream) {
           mediaStream.getTracks().forEach(t => t.stop());
       }
       if (publishedTrackRef.current && localParticipant) {
           localParticipant.unpublishTrack(publishedTrackRef.current.track, true);
       }
    };
  }, [room, localParticipant, isCameraOff, isFrontCamera]);

  // Update matrix map dynamically reacting to UI button selections
  useEffect(() => {
     if (processorRef.current) {
        let filterKey = 'none';
        if (activeFilter.includes('Cyber-Surf')) filterKey = 'cyber';
        if (activeFilter.includes('Bio-Lum')) filterKey = 'bioluminescence';
        if (activeFilter.includes('Pipeline')) filterKey = 'gopro';
        if (activeFilter.includes('Night Vision')) filterKey = 'nightvision';
        if (activeFilter.includes('Pixelate')) filterKey = 'pixelate';
        processorRef.current.setFilter(filterKey);
     }
  }, [activeFilter]);

  // We explicitly return the canvas node replacing the original <VideoTrack />
  // This visually displays exactly what the Streamer is broadcasting.
  return (
    <>
      <video ref={videoRef} style={{ display: 'none' }} playsInline muted autoPlay />
      <canvas 
        ref={canvasRef} 
        className={`w-full h-full object-cover ${isFrontCamera ? 'scale-x-[-1]' : ''}`} 
      />
    </>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { 
  Camera, X, Loader2, RefreshCcw, Sparkles, SlidersHorizontal, 
  CircleDot, Eye, Grid, Sunset, Waves, Moon, Zap, 
  Sun, Contrast, Droplets, Thermometer, RotateCcw, Scissors
} from 'lucide-react';
import { Button } from './ui/button';
import { toast } from 'sonner';
import { motion, AnimatePresence } from 'framer-motion';
import { WebGLVideoProcessor } from '../utils/WebGLFilterEngine';
import { HairFilterEngine } from '../utils/HairFilterEngine';
import { HairFilterPicker } from './HairFilterPicker';
import logger from '../utils/logger';
import { formatDurationPadded } from '../utils/formatTime';

export default function WebcamCaptureModal({ isOpen, onClose, onCapture, maxLength = null }) {
  const [stream, setStream] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [facingMode, setFacingMode] = useState('user'); 
  
  // Filtering Hooks
  const [showPresets, setShowPresets] = useState(false);
  const [showSliders, setShowSliders] = useState(false);
  const [showHairPicker, setShowHairPicker] = useState(false);
  const [activeHairStyle, setActiveHairStyle] = useState(null);
  const [videoFilters, setVideoFilters] = useState({ 
    brightness: 100, contrast: 100, saturation: 100, warmth: 100, vignette: 0, presetName: 'None'
  });
  
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const hairCanvasRef = useRef(null);
  const hairEngineRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const chunksRef = useRef([]);
  const timerRef = useRef(null);
  const timerStartRef = useRef(null); // Track timer start time for accurate counting
  const processorRef = useRef(null);
  const streamRef = useRef(null); // REF mirror of stream — avoids stale closures on iOS
  const compositeCanvasRef = useRef(null); // Hidden 2D canvas for compositing WebGL + hair for recording
  const compositeRafRef = useRef(null); // rAF ID for composite render loop

  // ── Reliable track cleanup via refs (avoids iOS stale closure bugs) ──
  const killAllTracks = useCallback(() => {
    // 1. Stop the ref-tracked stream (always current)
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => { t.stop(); t.enabled = false; });
      streamRef.current = null;
    }
    // 2. Stop whatever the video element is showing
    if (videoRef.current && videoRef.current.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(t => { t.stop(); t.enabled = false; });
      videoRef.current.srcObject = null;
    }
    // 3. Destroy WebGL processor (must recreate for new stream dimensions)
    if (processorRef.current) {
      try { processorRef.current.stop(); } catch (_) { /* ignore */ }
      processorRef.current = null;
    }
    // 4. Clear timer
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    setStream(null);
  }, []);

  const startCamera = useCallback(async () => {
    try {
      // CRITICAL: Kill ALL existing tracks before requesting new hardware access
      // iOS Safari will NOT release the camera unless every track is explicitly stopped
      killAllTracks();
      
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error('Camera API not accessible.');
      }

      // iOS Safari needs 300ms+ to fully release camera hardware between switches
      await new Promise(r => setTimeout(r, 350));

      let newStream;
      try {
        // Try exact facingMode first (reliable on most devices)
        newStream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: { exact: facingMode }, width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: true
        });
      } catch (exactErr) {
        // Fallback: use 'ideal' (soft hint) — works better on some iPhones
        logger.warn('Exact facingMode failed, falling back to ideal:', exactErr.message);
        try {
          newStream = await navigator.mediaDevices.getUserMedia({
            video: { facingMode: { ideal: facingMode }, width: { ideal: 1280 }, height: { ideal: 720 } },
            audio: true
          });
        } catch (idealErr) {
          // Last resort: any camera, any config
          newStream = await navigator.mediaDevices.getUserMedia({
            video: true,
            audio: true
          });
        }
      }
      
      // Store in both state and ref
      streamRef.current = newStream;
      setStream(newStream);
      
      if (videoRef.current) {
        videoRef.current.srcObject = newStream;
        await videoRef.current.play().catch(() => { /* ignore */ });
      }
    } catch (err) {
      logger.error('Camera access error:', err);
      toast.error('Could not access camera/microphone. Please check permissions.');
      killAllTracks();
      onClose();
    }
  }, [facingMode, onClose, killAllTracks]);

  // Open/close + camera switch effect
  useEffect(() => {
    if (isOpen) {
      startCamera();
    } else {
      killAllTracks();
    }
    
    return () => {
      // Unmount safety net — uses refs so never stale
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(t => t.stop());
        streamRef.current = null;
      }
      if (videoRef.current && videoRef.current.srcObject) {
        videoRef.current.srcObject.getTracks().forEach(t => t.stop());
        videoRef.current.srcObject = null;
      }
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        try { mediaRecorderRef.current.stop(); } catch (_) { /* ignore */ }
      }
      if (processorRef.current) {
        try { processorRef.current.stop(); } catch (_) { /* ignore */ }
        processorRef.current = null;
      }
      if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    };
  }, [isOpen, facingMode]);

  // Utilize the exact identical hardware shader mapped in the Live broadcast resolving highest tier filter deployments
  const initProcessor = useCallback((video) => {
    if (!video || !canvasRef.current) return;
    try {
      if (!processorRef.current) {
        canvasRef.current.width = video.videoWidth || 1080;
        canvasRef.current.height = video.videoHeight || 1920;
        processorRef.current = new WebGLVideoProcessor(canvasRef.current);
      }
      
      let filterKey = 'none';
      if (videoFilters.presetName.includes('Cyber-Surf')) filterKey = 'cyber';
      else if (videoFilters.presetName.includes('Golden Hour')) filterKey = 'goldenhour';
      else if (videoFilters.presetName.includes('Bio-Lum')) filterKey = 'bioluminescence';
      else if (videoFilters.presetName.includes('Pipeline')) filterKey = 'gopro';
      else if (videoFilters.presetName.includes('Night Vision')) filterKey = 'nightvision';
      else if (videoFilters.presetName.includes('Pixelate')) filterKey = 'pixelate';
      else filterKey = 'none';

      processorRef.current.setFilter(filterKey);
      processorRef.current.start(video);
    } catch (e) {
      logger.warn("WebGL Shader instantiation crashed - falling back silently.", e);
    }
  }, [videoFilters.presetName]);

  useEffect(() => {
    if (stream && videoRef.current && videoRef.current.readyState >= 2) {
      initProcessor(videoRef.current);
    }
  }, [stream, videoFilters.presetName, initProcessor]);

  const toggleCamera = useCallback(() => {
    // Kill processor before switching — iOS needs full hardware release
    if (processorRef.current) {
      try { processorRef.current.stop(); } catch (_) { /* ignore */ }
      processorRef.current = null;
    }
    setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
  }, []);

  const takePhoto = () => {
    // If our invisible canvas stalled drawing (e.g. 1x1 width or missing dimensions), forcefully execute raw hardware buffer snapshot to secure fallback reliability ensuring no Black Photos
    if (videoRef.current && (!canvasRef.current || canvasRef.current.width === 0 || canvasRef.current.width === 300)) {
       const vRef = videoRef.current;
       const fallbackCanvas = document.createElement('canvas');
       fallbackCanvas.width = vRef.videoWidth || 1080;
       fallbackCanvas.height = vRef.videoHeight || 1920;
       const fallbackCtx = fallbackCanvas.getContext('2d');
       
       if (facingMode === 'user') {
         fallbackCtx.translate(fallbackCanvas.width, 0);
         fallbackCtx.scale(-1, 1);
       }
       fallbackCtx.drawImage(vRef, 0, 0, fallbackCanvas.width, fallbackCanvas.height);
       fallbackCanvas.toBlob((blob) => {
         if (blob) {
           onCapture([new File([blob], `photo_${Date.now()}.jpg`, { type: 'image/jpeg' })]);
           onClose();
         }
       }, 'image/jpeg', 0.9);
       return;
    }

    if (!canvasRef.current) return;
    
    // Composite WebGL + hair filter onto a temporary 2D canvas for photo capture
    const webglCanvas = canvasRef.current;
    const hairCanvas = hairCanvasRef.current;
    const compositeCanvas = document.createElement('canvas');
    compositeCanvas.width = webglCanvas.width || 1080;
    compositeCanvas.height = webglCanvas.height || 1920;
    const ctx = compositeCanvas.getContext('2d');
    ctx.drawImage(webglCanvas, 0, 0, compositeCanvas.width, compositeCanvas.height);
    if (hairCanvas && hairCanvas.width > 0 && hairCanvas.height > 0) {
      ctx.drawImage(hairCanvas, 0, 0, compositeCanvas.width, compositeCanvas.height);
    }
    
    compositeCanvas.toBlob((blob) => {
      if (blob) {
        const file = new File([blob], `photo_${Date.now()}.jpg`, { type: 'image/jpeg' });
        onCapture([file]);
        onClose();
      }
    }, 'image/jpeg', 0.9);
  };

  const startRecording = () => {
    const currentStream = streamRef.current;
    if (!currentStream || !canvasRef.current) return;
    
    // Kill any stale timer FIRST
    if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    
    chunksRef.current = [];
    setRecordingTime(0);
    
    const mimeType = MediaRecorder.isTypeSupported('video/mp4') ? 'video/mp4' : 'video/webm;codecs=vp8,opus';
    
    // ── Composite Canvas Approach ──
    // iOS Safari's captureStream() on WebGL canvases is unreliable.
    // Also, hair filters live on a separate canvas overlay and aren't captured.
    // Solution: Create a hidden 2D canvas, composite both layers each frame,
    // and record from that 2D canvas instead.
    const webglCanvas = canvasRef.current;
    const hairCanvas = hairCanvasRef.current;
    
    // Create or reuse the composite canvas
    if (!compositeCanvasRef.current) {
      compositeCanvasRef.current = document.createElement('canvas');
    }
    const compositeCanvas = compositeCanvasRef.current;
    compositeCanvas.width = webglCanvas.width || 1080;
    compositeCanvas.height = webglCanvas.height || 1920;
    const ctx = compositeCanvas.getContext('2d');
    
    // Start a composite render loop that draws WebGL + hair onto the 2D canvas
    const compositeLoop = () => {
      ctx.clearRect(0, 0, compositeCanvas.width, compositeCanvas.height);
      // Layer 1: WebGL filtered video
      ctx.drawImage(webglCanvas, 0, 0, compositeCanvas.width, compositeCanvas.height);
      // Layer 2: Hair filter overlay (if active)
      if (hairCanvas && hairCanvas.width > 0 && hairCanvas.height > 0) {
        ctx.drawImage(hairCanvas, 0, 0, compositeCanvas.width, compositeCanvas.height);
      }
      compositeRafRef.current = requestAnimationFrame(compositeLoop);
    };
    compositeRafRef.current = requestAnimationFrame(compositeLoop);
    
    // Capture from the composite 2D canvas (reliable on all platforms)
    const capturedStream = compositeCanvas.captureStream(30);
    
    // Attach audio track from camera stream
    const audioTracks = currentStream.getAudioTracks();
    if (audioTracks.length > 0) {
      capturedStream.addTrack(audioTracks[0]);
    }

    const mediaRecorder = new MediaRecorder(capturedStream, { mimeType });
    mediaRecorderRef.current = mediaRecorder;
    
    mediaRecorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunksRef.current.push(e.data);
    };
    
    mediaRecorder.onstop = () => {
      // 1. Kill composite render loop
      if (compositeRafRef.current) {
        cancelAnimationFrame(compositeRafRef.current);
        compositeRafRef.current = null;
      }
      
      // 2. Kill timer immediately
      if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
      
      // 3. Build file from chunks
      const blob = new Blob(chunksRef.current, { type: mimeType });
      const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';
      const file = new File([blob], `video_${Date.now()}.${extension}`, { type: mimeType });
      
      // 4. CRITICAL: Kill all hardware tracks via ref (never stale)
      killAllTracks();
      
      // 5. Deliver file + close modal
      onCapture([file]);
      onClose();
    };
    
    mediaRecorder.start(100);
    setIsRecording(true);
    
    // Simple, reliable timer using Date.now() — immune to iOS Safari setInterval throttling
    timerStartRef.current = Date.now();
    timerRef.current = setInterval(() => {
      const elapsed = Math.floor((Date.now() - timerStartRef.current) / 1000);
      setRecordingTime(elapsed);
      
      if (maxLength && elapsed >= maxLength) {
        if (mediaRecorder.state !== 'inactive') mediaRecorder.stop();
        setIsRecording(false);
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }, 500); // 500ms intervals for smoother updates + iOS throttle resistance
  };

  const stopRecording = useCallback(() => {
    // Kill composite render loop
    if (compositeRafRef.current) {
      cancelAnimationFrame(compositeRafRef.current);
      compositeRafRef.current = null;
    }
    
    // Kill timer
    if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop(); // triggers onstop → killAllTracks → onCapture → onClose
    }
    setIsRecording(false);
  }, []);

  const formatTime = formatDurationPadded;

  const handleFilterChange = (key, val) => setVideoFilters(p => ({ ...p, [key]: val }));
  const handlePresetSelect = (preset) => {
    setVideoFilters({ ...preset.values, presetName: preset.name });
    setShowPresets(false); // Auto-close panel on selection
    toast.success('Filter active');
  };

  // ── Hair Filter Engine lifecycle ──
  useEffect(() => {
    const engine = new HairFilterEngine();
    hairEngineRef.current = engine;
    engine.init().catch(() => { /* ignore */ });
    return () => {
      engine.dispose();
      hairEngineRef.current = null;
    };
  }, []);

  // Start/stop hair engine when camera stream changes
  useEffect(() => {
    const engine = hairEngineRef.current;
    if (!engine || !stream) return;
    
    const videoEl = videoRef.current;
    const hairCanvas = hairCanvasRef.current;
    
    if (videoEl && hairCanvas) {
      // Retry pattern: video may not be ready immediately on mobile
      const tryStart = () => {
        if (videoEl.readyState >= 1) {
          engine.start(videoEl, hairCanvas); // start() awaits init internally
          return true;
        }
        return false;
      };
      
      if (!tryStart()) {
        const timer = setInterval(() => {
          if (tryStart()) clearInterval(timer);
        }, 500);
        const timeout = setTimeout(() => clearInterval(timer), 5000);
        return () => { clearInterval(timer); clearTimeout(timeout); engine.stop(); };
      }
      
      return () => { engine.stop(); };
    }
  }, [stream]);
  
  // Update hair style when selection changes
  useEffect(() => {
    const engine = hairEngineRef.current;
    if (engine) engine.setHairStyle(activeHairStyle);
  }, [activeHairStyle]);
  
  const handleSelectHairStyle = useCallback((styleId) => {
    setActiveHairStyle(styleId);
    setShowHairPicker(false); // Auto-close picker on selection
    if (styleId) toast.success('Hair filter applied! 💇');
  }, []);

  if (!isOpen) return null;

  const presets = [
    { name: 'None', icon: CircleDot, values: { brightness: 100, contrast: 100, saturation: 100, warmth: 100, vignette: 0 } },
    { name: 'AI Night Vision', icon: Eye, values: { brightness: 100, contrast: 100, saturation: 100, warmth: 100, vignette: 0 } },
    { name: 'AI Pixelate', icon: Grid, values: { brightness: 100, contrast: 100, saturation: 100, warmth: 100, vignette: 0 } },
    { name: 'Golden Hour', icon: Sunset, values: { brightness: 105, contrast: 110, saturation: 120, warmth: 120, vignette: 20 } },
    { name: 'AI Pipeline', icon: Waves, values: { brightness: 90, contrast: 130, saturation: 90, warmth: 110, vignette: 40 } },
    { name: 'AI Bio-Lum', icon: Moon, values: { brightness: 85, contrast: 140, saturation: 150, warmth: 160, vignette: 30 } },
    { name: 'AI Cyber-Surf', icon: Zap, values: { brightness: 110, contrast: 125, saturation: 140, warmth: 40, vignette: 0 } }
  ];

  return (
    <div className="fixed inset-0 z-[99999] flex items-center justify-center p-0 sm:p-6">
      <div className="fixed inset-0 bg-black/80 backdrop-blur-sm hidden sm:block" onClick={onClose} />
      
      <div className="relative w-full h-full sm:w-[1100px] sm:h-[720px] sm:max-h-[90vh] sm:rounded-2xl sm:overflow-hidden bg-black shadow-2xl flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 bg-gradient-to-b from-black/80 to-transparent absolute top-0 left-0 right-0 z-20 pointer-events-none">
          <button onClick={onClose} className="p-2 bg-black/50 rounded-full text-white hover:bg-zinc-800 transition-colors pointer-events-auto">
            <X className="w-6 h-6" />
          </button>
          
          <div className="flex gap-2 pointer-events-auto">
            {isRecording ? (
              <div className="bg-black/50 backdrop-blur text-white px-3 py-1 rounded-full text-sm font-medium flex items-center gap-2">
                <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                <span className={maxLength && recordingTime >= maxLength - 5 ? 'text-red-400 font-bold' : ''}>
                  {formatTime(recordingTime)} {maxLength ? `/ ${formatTime(maxLength)}` : ''}
                </span>
              </div>
            ) : (
              <div className="bg-black/50 backdrop-blur text-white px-3 py-1 rounded-full text-sm font-medium flex items-center gap-2">
                <Camera className="w-4 h-4" />
                <span>Camera</span>
              </div>
            )}
          </div>

          <button onClick={toggleCamera} disabled={isRecording} className={`p-2 bg-black/50 rounded-full text-white hover:bg-zinc-800 transition-colors ${isRecording ? 'opacity-50' : ''} pointer-events-auto`}>
            <RefreshCcw className="w-5 h-5" />
          </button>
        </div>

        {/* Floating Side Tools (Exactly like GoLiveModal transparent buttons) */}
        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex flex-col gap-3 z-[60] pointer-events-auto">
          <button
            onClick={() => { setShowPresets(!showPresets); setShowSliders(false); setShowHairPicker(false); }}
            className={`p-3 rounded-full bg-black/40 backdrop-blur border border-white/20 transition-all active:scale-95 shadow-md ${showPresets ? 'bg-cyan-500 text-white border-transparent' : 'text-white'}`}
            title="Surf Filters"
          >
            <Sparkles className="w-5 h-5" />
          </button>
          <button
            onClick={() => { setShowSliders(!showSliders); setShowPresets(false); setShowHairPicker(false); }}
            className={`p-3 rounded-full bg-black/40 backdrop-blur border border-white/20 transition-all active:scale-95 shadow-md ${showSliders ? 'bg-cyan-500 text-white border-transparent' : 'text-white'}`}
            title="Filter Adjustments"
          >
            <SlidersHorizontal className="w-5 h-5" />
          </button>
          <button
            onClick={() => { setShowHairPicker(!showHairPicker); setShowPresets(false); setShowSliders(false); }}
            className={`p-3 rounded-full bg-black/40 backdrop-blur border border-white/20 transition-all active:scale-95 shadow-md ${showHairPicker ? 'bg-yellow-500 text-white border-transparent' : activeHairStyle ? 'bg-yellow-500/30 border-yellow-500/50 text-white' : 'text-white'}`}
            title="Hair Filters"
          >
            <Scissors className="w-5 h-5" />
          </button>
        </div>

        {/* Filter Popups */}
        <AnimatePresence>
          {showPresets && (
            <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }}
              className="absolute right-16 top-1/4 w-60 max-h-[50vh] overflow-y-auto bg-black/70 backdrop-blur-md border border-zinc-700 p-3 rounded-xl z-[60]"
            >
              <div className="flex items-center justify-between mb-3 border-b border-zinc-700 pb-2">
                <span className="text-white text-sm font-bold">Presets</span>
                <X className="w-4 h-4 text-zinc-400 cursor-pointer" onClick={() => setShowPresets(false)} />
              </div>
              <div className="grid grid-cols-2 gap-2">
                {presets.map(preset => {
                  const Icon = preset.icon;
                  return (
                    <button key={preset.name} onClick={() => handlePresetSelect(preset)}
                      className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-transform hover:scale-105 ${videoFilters.presetName === preset.name ? 'bg-cyan-500/30 border border-cyan-500' : 'bg-zinc-800/60'}`}
                    >
                      <Icon className="w-4 h-4 text-cyan-400" />
                      <span className="text-white text-[10px] text-center">{preset.name}</span>
                    </button>
                  );
                })}
              </div>
            </motion.div>
          )}

          {showSliders && (
            <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }}
              className="absolute right-16 top-1/4 w-60 max-h-[50vh] overflow-y-auto bg-black/70 backdrop-blur-md border border-zinc-700 p-4 rounded-xl z-[60]"
            >
              <div className="flex items-center justify-between mb-3 border-b border-zinc-700 pb-2">
                <span className="text-white text-sm font-bold">Adjustments</span>
                <X className="w-4 h-4 text-zinc-400 cursor-pointer" onClick={() => setShowSliders(false)} />
              </div>
              
              {/* Sliders */}
              {[
                { key: 'brightness', label: 'Brightness', icon: Sun, min: 50, max: 150 },
                { key: 'contrast', label: 'Contrast', icon: Contrast, min: 50, max: 150 },
                { key: 'saturation', label: 'Saturation', icon: Droplets, min: 50, max: 150 },
                { key: 'warmth', label: 'Warmth', icon: Thermometer, min: 50, max: 150 },
                { key: 'vignette', label: 'Vignette', icon: CircleDot, min: 0, max: 50 }
              ].map(slider => (
                <div key={slider.key} className="mb-3">
                  <div className="flex items-center justify-between pointer-events-none mb-1">
                    <div className="flex items-center gap-1.5"><slider.icon className="w-3 h-3 text-zinc-300" /><span className="text-xs text-zinc-300">{slider.label}</span></div>
                    <span className="text-[10px] text-white font-mono">{videoFilters[slider.key]}%</span>
                  </div>
                  <input type="range" min={slider.min} max={slider.max} value={videoFilters[slider.key]} onChange={(e) => handleFilterChange(slider.key, parseInt(e.target.value))} className="w-full h-1.5 rounded-full appearance-none accent-cyan-500 cursor-pointer" />
                </div>
              ))}
              <Button onClick={() => setVideoFilters({ brightness: 100, contrast: 100, saturation: 100, warmth: 100, vignette: 0, presetName: 'None' })} size="sm" variant="outline" className="w-full bg-zinc-800 text-white border-zinc-700 mt-2 hover:bg-zinc-700 hover:text-white">
                <RotateCcw className="w-3 h-3 mr-2" /> Reset
              </Button>
            </motion.div>
          )}

          {/* Hair Filter Picker */}
          {showHairPicker && (
            <HairFilterPicker
              isOpen={showHairPicker}
              onClose={() => setShowHairPicker(false)}
              activeStyleId={activeHairStyle}
              onSelectHair={handleSelectHairStyle}
              colors={{
                overlayBg: 'bg-black/70 backdrop-blur-md',
                primaryText: 'text-white',
                secondaryText: 'text-zinc-400',
                accentText: 'text-cyan-400',
                buttonBg: 'bg-white/10 hover:bg-white/20',
                border: 'border-zinc-700',
              }}
            />
          )}
        </AnimatePresence>

        {/* Viewfinder block physically tracking canvas structure for recording */}
        <div className="flex-1 relative bg-zinc-900 flex items-center justify-center overflow-hidden">
          {!stream && (
            <div className="flex flex-col items-center text-zinc-500">
              <Loader2 className="w-8 h-8 animate-spin mb-2" />
              <p>Accessing camera...</p>
            </div>
          )}
          {/* 
            Video element: shown as VISIBLE fallback when WebGL canvas isn't rendering (iPhone front camera).
            Front camera ('user') is mirrored via scaleX(-1) for natural selfie view.
          */}
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            onLoadedMetadata={(e) => { 
              if (e.target) {
                e.target.play().catch(() => { /* ignore */ });
                initProcessor(e.target);
              }
            }} 
            className="absolute inset-0 w-full h-full object-cover z-0" 
            style={{ 
              transform: facingMode === 'user' ? 'scaleX(-1)' : 'none',
              opacity: 1,
            }}
          />
          {/* WebGL filtered canvas sits on top — if it renders, it covers the raw video */}
          <canvas 
            ref={canvasRef} 
            className="absolute inset-0 w-full h-full object-cover z-10" 
            style={{ transform: facingMode === 'user' ? 'scaleX(-1)' : 'none' }}
          />
          {/* Hair filter canvas overlay — must mirror when front camera is active (matching GoLiveModal) */}
          <canvas 
            ref={hairCanvasRef} 
            className="absolute inset-0 w-full h-full object-cover pointer-events-none z-[15]" 
            style={{ transform: facingMode === 'user' ? 'scaleX(-1)' : 'none' }}
          />
        </div>

        {/* Rule of Thirds */}
        <div className="absolute inset-x-0 bottom-[160px] top-[72px] pointer-events-none z-[5] opacity-20 flex flex-col justify-center items-center mix-blend-overlay hidden sm:flex">
          <div className="w-full h-1/3 border-b border-t border-white" />
          <div className="absolute top-0 bottom-0 left-1/3 right-1/3 border-l border-r border-white" />
        </div>

        {/* Controls */}
        <div className="absolute bottom-0 left-0 right-0 h-40 bg-gradient-to-t from-black/95 via-black/50 to-transparent flex items-center justify-center gap-12 pb-6 z-20 pointer-events-auto">
          <Button
            onClick={takePhoto}
            disabled={isRecording}
            variant="ghost"
            className={`flex flex-col items-center gap-2 hover:bg-transparent ${isRecording ? 'opacity-30' : 'opacity-100'} transition-opacity`}
          >
            <div className="w-12 h-12 rounded-full border-2 border-white flex items-center justify-center">
              <Camera className="w-5 h-5 text-white" />
            </div>
            <span className="text-white font-medium text-xs">Photo</span>
          </Button>

          <div className="relative">
            <button
              onClick={isRecording ? stopRecording : startRecording}
              className={`w-20 h-20 rounded-full border-4 flex items-center justify-center transition-colors ${isRecording ? 'border-red-500' : 'border-white'}`}
            >
              <div className={`transition-all duration-300 ${isRecording ? 'w-8 h-8 rounded-md bg-red-500' : 'w-16 h-16 rounded-full bg-red-500'}`} />
            </button>
          </div>

          <Button disabled variant="ghost" className="flex flex-col items-center gap-2 hover:bg-transparent opacity-0 pointer-events-none">
            <div className="w-12 h-12 rounded-full border-2 border-transparent" />
            <span className="text-transparent font-medium text-xs">Blank</span>
          </Button>
        </div>
      </div>
    </div>
  );
}

﻿import React, { useState, useEffect } from 'react';
import { Trophy, Medal, Crown, Star, ChevronRight, Users, Camera, Waves } from 'lucide-react';
import { Button } from './ui/button';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';
import { useTheme } from '../contexts/ThemeContext';
import { useNavigate } from 'react-router-dom';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';


/**
 * XP Leaderboard Component
 * Shows top XP earners in the community
 */
export const XPLeaderboard = ({ compact = false, limit = 10 }) => {
  const { theme } = useTheme();
  const navigate = useNavigate();
  const [leaderboard, setLeaderboard] = useState([]);
  const [loading, setLoading] = useState(true);
  const [timeRange, setTimeRange] = useState('all'); // 'week', 'month', 'all'
  const [category, setCategory] = useState('all'); // 'all', 'patrons', 'workhorses'

  const isLight = theme === 'light';
  const cardBg = isLight ? 'bg-white border-gray-200' : 'bg-card border-border';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';

  useEffect(() => {
    fetchLeaderboard();
  }, [timeRange, category, limit]);

  const fetchLeaderboard = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/gamification/leaderboard`, {
        params: { time_range: timeRange, category, limit }
      });
      setLeaderboard(response.data.leaderboard || []);
    } catch (error) {
      logger.error('Failed to fetch leaderboard:', error);
      // Use mock data if API fails
      setLeaderboard(getMockLeaderboard());
    } finally {
      setLoading(false);
    }
  };

  // Mock data for development/fallback
  const getMockLeaderboard = () => [
    { id: '1', name: 'Kelly Waters', avatar: null, xp: 2450, rank: 1, badge: 'the_patron', badge_tier: 'gold' },
    { id: '2', name: 'Sarah Waves', avatar: null, xp: 1890, rank: 2, badge: 'the_workhorse', badge_tier: 'silver' },
    { id: '3', name: 'Mike Shooter', avatar: null, xp: 1560, rank: 3, badge: 'the_patron', badge_tier: 'silver' },
    { id: '4', name: 'Lisa Surf', avatar: null, xp: 1230, rank: 4, badge: null, badge_tier: null },
    { id: '5', name: 'Tom Tube', avatar: null, xp: 980, rank: 5, badge: null, badge_tier: null },
  ];

  const getRankIcon = (rank) => {
    switch (rank) {
      case 1:
        return <Crown className="w-6 h-6 text-yellow-400" />;
      case 2:
        return <Medal className="w-5 h-5 text-gray-300" />;
      case 3:
        return <Medal className="w-5 h-5 text-amber-600" />;
      default:
        return <span className={`w-6 text-center font-bold ${textSecondary}`}>#{rank}</span>;
    }
  };

  const getRankBg = (rank) => {
    switch (rank) {
      case 1:
        return 'bg-gradient-to-r from-yellow-500/20 to-amber-500/20 border-yellow-500/30';
      case 2:
        return 'bg-gradient-to-r from-gray-400/20 to-gray-500/20 border-gray-400/30';
      case 3:
        return 'bg-gradient-to-r from-amber-600/20 to-orange-600/20 border-amber-600/30';
      default:
        return isLight ? 'bg-gray-50' : 'bg-zinc-800/50';
    }
  };

  const getBadgeInfo = (badge, _tier) => {
    const badges = {
      'the_patron': { label: 'Patron', icon: Users, color: 'cyan' },
      'the_workhorse': { label: 'Workhorse', icon: Camera, color: 'orange' },
      'the_benefactor': { label: 'Benefactor', icon: Star, color: 'emerald' },
      'sharpshooter': { label: 'Sharpshooter', icon: Waves, color: 'blue' }
    };
    return badges[badge] || null;
  };

  if (compact) {
    // Compact view for sidebar or widget
    return (
      <Card className={cardBg}>
        <CardHeader className="pb-2">
          <CardTitle className={`${textPrimary} text-sm flex items-center gap-2`}>
            <Trophy className="w-4 h-4 text-yellow-400" />
            Top Earners
          </CardTitle>
        </CardHeader>
        <CardContent className="pt-0">
          <div className="space-y-2">
            {(loading ? Array(3).fill({}) : leaderboard.slice(0, 3)).map((user, index) => (
              <div key={user.id || index} className="flex items-center gap-2">
                {getRankIcon(index + 1)}
                <Avatar className="w-6 h-6">
                  <AvatarImage src={user.avatar} />
                  <AvatarFallback className="text-xs bg-zinc-700 text-cyan-400">
                    {user.name?.charAt(0) || '?'}
                  </AvatarFallback>
                </Avatar>
                <span className={`text-sm flex-1 truncate ${textPrimary}`}>
                  {user.name || 'Loading...'}
                </span>
                <span className="text-xs text-cyan-400 font-bold">{user.xp || 0} XP</span>
              </div>
            ))}
          </div>
          <Button 
            variant="ghost" 
            size="sm" 
            className="w-full mt-2 text-cyan-400"
            onClick={() => navigate('/leaderboard')}
          >
            View All <ChevronRight className="w-4 h-4 ml-1" />
          </Button>
        </CardContent>
      </Card>
    );
  }

  // Full leaderboard view
  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h2 className={`text-2xl font-bold ${textPrimary} flex items-center gap-2`}>
          <Trophy className="w-7 h-7 text-yellow-400" />
          XP Leaderboard
        </h2>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-2">
        {/* Time Range */}
        <div className="flex gap-1 bg-zinc-800/50 rounded-lg p-1">
          {[
            { value: 'week', label: 'This Week' },
            { value: 'month', label: 'This Month' },
            { value: 'all', label: 'All Time' }
          ].map(opt => (
            <button
              key={opt.value}
              onClick={() => setTimeRange(opt.value)}
              className={`px-3 py-1 rounded-md text-sm font-medium transition-colors ${
                timeRange === opt.value
                  ? 'bg-cyan-400 text-black'
                  : `${textSecondary} hover:text-white`
              }`}
            >
              {opt.label}
            </button>
          ))}
        </div>

        {/* Category */}
        <div className="flex gap-1 bg-zinc-800/50 rounded-lg p-1">
          {[
            { value: 'all', label: 'All', icon: Trophy },
            { value: 'patrons', label: 'Patrons', icon: Users },
            { value: 'workhorses', label: 'Workhorses', icon: Camera }
          ].map(opt => (
            <button
              key={opt.value}
              onClick={() => setCategory(opt.value)}
              className={`px-3 py-1 rounded-md text-sm font-medium transition-colors flex items-center gap-1 ${
                category === opt.value
                  ? 'bg-cyan-400 text-black'
                  : `${textSecondary} hover:text-white`
              }`}
            >
              <opt.icon className="w-4 h-4" />
              {opt.label}
            </button>
          ))}
        </div>
      </div>

      {/* Leaderboard List */}
      <div className="space-y-2">
        {(loading ? Array(limit).fill({}) : leaderboard).map((user, index) => {
          const badgeInfo = getBadgeInfo(user.badge, user.badge_tier);
          
          return (
            <div
              key={user.id || index}
              onClick={() => user.id && navigate(`/profile/${user.id}`)}
              className={`flex items-center gap-4 p-4 rounded-xl border transition-all cursor-pointer hover:scale-[1.01] ${getRankBg(user.rank || index + 1)}`}
            >
              {/* Rank */}
              <div className="w-8 flex justify-center">
                {getRankIcon(user.rank || index + 1)}
              </div>

              {/* Avatar */}
              <Avatar className="w-12 h-12 border-2 border-zinc-700">
                <AvatarImage src={user.avatar} />
                <AvatarFallback className="bg-zinc-800 text-cyan-400 text-lg">
                  {user.name?.charAt(0) || '?'}
                </AvatarFallback>
              </Avatar>

              {/* Name & Badge */}
              <div className="flex-1">
                <div className={`font-bold ${textPrimary}`}>
                  {user.name || 'Loading...'}
                </div>
                {badgeInfo && (
                  <div className={`flex items-center gap-1 text-xs text-${badgeInfo.color}-400`}>
                    <badgeInfo.icon className="w-3 h-3" />
                    {badgeInfo.label} ({user.badge_tier})
                  </div>
                )}
              </div>

              {/* XP */}
              <div className="text-right">
                <div className="text-xl font-bold text-cyan-400">
                  {user.xp?.toLocaleString() || 0}
                </div>
                <div className={`text-xs ${textSecondary}`}>XP</div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Empty State */}
      {!loading && leaderboard.length === 0 && (
        <div className="text-center py-12">
          <Trophy className="w-16 h-16 mx-auto text-zinc-600 mb-4" />
          <p className={textSecondary}>No rankings yet. Be the first to earn XP!</p>
        </div>
      )}
    </div>
  );
};

