            );
          })}
        </div>

        {/* Quick Actions */}
        <Card className={cardBgClass}>
          <CardHeader>
            <CardTitle className={`${textClass} text-sm`}>Quick Navigation</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-2 gap-2">
            <Button 
              variant="outline" 
              size="sm"
              onClick={() => navigate('/map')}
