            >
              Test Map
            </Button>
            <Button 
              variant="outline" 
              size="sm"
              onClick={() => navigate('/bookings')}
              className="border-zinc-700"
            >
              Test Bookings
            </Button>
            <Button 
              variant="outline" 
              size="sm"
              onClick={() => navigate('/gallery')}
              className="border-zinc-700"
            >
              Test Gallery
            </Button>
            <Button 
              variant="outline" 
              size="sm"
              onClick={() => navigate('/profile')}
