            </p>
          </CardHeader>
          <CardContent className="space-y-4">
            {loadingPhotographers ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-cyan-400" />
                <span className={`ml-2 text-sm ${textSecondary}`}>Loading data...</span>
              </div>
            ) : (
              <>
                {/* Force Start Section */}
                <div className="p-4 rounded-lg border border-zinc-700 bg-zinc-800/50 space-y-4">
                  <h3 className={`font-bold text-sm ${textClass} flex items-center gap-2`}>
                    <Play className="w-4 h-4 text-green-500" />
                    Force Start Session
                  </h3>
                  
                  {/* Photographer Selector with Search */}
                  <div>
                    <label className={`text-xs ${textSecondary} mb-1 block`}>Photographer</label>
                    <Input
                      placeholder="Search photographers..."
                      value={photographerSearch}
                      onChange={(e) => setPhotographerSearch(e.target.value)}
                      className="mb-2 bg-zinc-900 border-zinc-600 h-9 text-sm"
                    />
                    <select
                      value={selectedPhotographer}
                      onChange={(e) => setSelectedPhotographer(e.target.value)}
                      className="w-full h-10 px-3 rounded-md bg-zinc-900 border border-zinc-600 text-white text-sm focus:outline-none focus:ring-2 focus:ring-cyan-500"
                    >
                      <option value="">Select photographer...</option>
                      {filteredPhotographers.map((p) => (
                        <option key={p.id} value={p.id} disabled={p.is_shooting}>
                          {p.full_name} {p.is_shooting ? '(LIVE)' : ''} - {p.role}
                        </option>
                      ))}
                    </select>
                  </div>
                  
                  {/* Location Selector with Search */}
                  <div>
                    <label className={`text-xs ${textSecondary} mb-1 block`}>Surf Spot Location</label>
                    <Input
                      placeholder="Search spots..."
                      value={spotSearch}
                      onChange={(e) => setSpotSearch(e.target.value)}
                      className="mb-2 bg-zinc-900 border-zinc-600 h-9 text-sm"
                    />
                    <select
                      value={selectedSpot}
                      onChange={(e) => setSelectedSpot(e.target.value)}
                      className="w-full h-10 px-3 rounded-md bg-zinc-900 border border-zinc-600 text-white text-sm focus:outline-none focus:ring-2 focus:ring-cyan-500"
                    >
                      <option value="">Select surf spot...</option>
                      {filteredSpots.map((s) => (
                        <option key={s.id} value={s.id}>
                          {s.name} - {s.region}
                        </option>
                      ))}
                    </select>
                  </div>
                  
                  {/* Session Price */}
                  <div>
                    <label className={`text-xs ${textSecondary} mb-1 block`}>Buy-in Price ($)</label>
                    <Input
                      type="number"
                      value={sessionPrice}
                      onChange={(e) => setSessionPrice(e.target.value)}
                      className="bg-zinc-900 border-zinc-600 h-9 text-sm w-24"
                      min="0"
                    />
                  </div>
                  
                  {/* Conditions Media Upload */}
                  <div>
                    <label className={`text-xs ${textSecondary} mb-1 block`}>Conditions Media (Optional)</label>
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept="image/*,video/*"
                      onChange={handleMediaSelect}
                      className="hidden"
                    />
                    {mediaPreview ? (
                      <div className="relative">
                        {conditionMediaType === 'video' ? (
                          <video src={mediaPreview} className="w-full h-32 object-cover rounded-lg" controls />
                        ) : (
                          <img src={mediaPreview} alt="Conditions" className="w-full h-32 object-cover rounded-lg" />
                        )}
                        <button
                          onClick={clearMedia}
                          className="absolute top-1 right-1 p-1 bg-black/60 rounded-full hover:bg-black/80"
                        >
                          <X className="w-4 h-4 text-white" />
                        </button>
                        <div className="absolute bottom-1 left-1 px-2 py-0.5 bg-black/60 rounded text-xs text-white flex items-center gap-1">
                          {conditionMediaType === 'video' ? <Video className="w-3 h-3" /> : <Image className="w-3 h-3" />}
                          {conditionMediaType}
                        </div>
                      </div>
                    ) : (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => fileInputRef.current?.click()}
                        className="w-full border-dashed border-zinc-600 h-20"
                      >
                        <Upload className="w-4 h-4 mr-2" />
                        Upload Photo/Video
                      </Button>
                    )}
                  </div>
                  
                  {/* Spot Notes */}
                  <div>
                    <label className={`text-xs ${textSecondary} mb-1 block`}>Spot Notes (Optional)</label>
                    <Textarea
                      placeholder="e.g., 3-4ft, glassy, offshore winds..."
                      value={spotNotes}
                      onChange={(e) => setSpotNotes(e.target.value)}
                      className="bg-zinc-900 border-zinc-600 text-sm h-16 resize-none"
                    />
                  </div>
                  
                  {/* Force Start Button */}
                  <Button
                    onClick={handleForceStart}
                    disabled={forceStartLoading || !selectedPhotographer || !selectedSpot}
                    className="w-full bg-green-600 hover:bg-green-700 text-white font-bold"
                  >
                    {forceStartLoading ? (
                      <Loader2 className="w-4 h-4 animate-spin mr-2" />
                    ) : (
                      <Play className="w-4 h-4 mr-2" />
                    )}
                    Force Start Session
                  </Button>
                </div>
                
                {/* Active Sessions / Force End Section */}
                <div className="p-4 rounded-lg border border-zinc-700 bg-zinc-800/50 space-y-3">
                  <h3 className={`font-bold text-sm ${textClass} flex items-center gap-2`}>
                    <Square className="w-4 h-4 text-red-500" />
                    Active Sessions ({activeSessions.length})
                  </h3>
                  
                  {activeSessions.length === 0 ? (
                    <p className={`text-sm ${textSecondary} text-center py-4`}>
                      No active sessions
                    </p>
                  ) : (
                    activeSessions.map((session) => (
                      <div 
                        key={session.id}
                        className="p-3 rounded-lg border border-red-500/30 bg-red-500/5 flex items-center gap-3"
                      >
                        <Avatar className="w-10 h-10">
                          <AvatarImage src={session.photographer_avatar} />
                          <AvatarFallback className="bg-zinc-700">
                            <Camera className="w-4 h-4" />
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex-1 min-w-0">
                          <p className={`font-medium text-sm ${textClass} truncate flex items-center gap-2`}>
                            {session.photographer_name}
                            <span className="px-1.5 py-0.5 bg-red-500 text-white text-xs font-bold rounded animate-pulse">
                              LIVE
                            </span>
                          </p>
                          <p className={`text-xs ${textSecondary} flex items-center gap-1`}>
                            <MapPin className="w-3 h-3" />
                            {session.spot_name}
                          </p>
                        </div>
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => handleForceEnd(session.photographer_id, session.photographer_name)}
                          disabled={forceEndLoading === session.photographer_id}
                          className="bg-red-600 hover:bg-red-700"
                        >
                          {forceEndLoading === session.photographer_id ? (
                            <Loader2 className="w-4 h-4 animate-spin" />
                          ) : (
                            <>
                              <Square className="w-3 h-3 mr-1" />
                              Force End
                            </>
                          )}
                        </Button>
                      </div>
                    ))
                  )}
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default GodModePage;

﻿/**
 * InviteNearbyCrewModal - Popup for inviting nearby friends to split a booking
 * 
 * Appears when creating a NEW booking (scheduled or on-demand) to offer splitting costs
 * NOT for active live shooting sessions - this is for booking together before the session
 */
import React, { useState, useEffect } from 'react';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { 

  Users, MapPin, 
  Loader2, UserPlus, Check, Calendar, Waves,
  Navigation, UserCheck
} from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from './ui/dialog';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Avatar, AvatarImage, AvatarFallback } from './ui/avatar';
import { Checkbox } from './ui/checkbox';
import { toast } from 'sonner';

const getFullUrl = (url) => {
  if (!url) return url;
  if (url.startsWith('data:') || url.startsWith('blob:') || url.startsWith('http')) return url;
  return `\\`;
};



export const InviteNearbyCrewModal = ({
  isOpen,
  onClose,
  booking,
  user,
  onInvitesSent,
  theme = 'dark'
}) => {
  const [nearbyFriends, setNearbyFriends] = useState([]);
  const [selectedFriends, setSelectedFriends] = useState([]);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  
  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white' : 'bg-zinc-900';
  const textPrimaryClass = isLight ? 'text-gray-900' : 'text-white';
  const textSecondaryClass = isLight ? 'text-gray-600' : 'text-gray-400';
  const itemBgClass = isLight ? 'bg-gray-50 hover:bg-gray-100' : 'bg-zinc-800/50 hover:bg-zinc-800';

  // Calculate per-person price based on selected crew
  const totalCrew = selectedFriends.length + 1; // +1 for current user
  const pricePerPerson = booking?.total_price ? (booking.total_price / totalCrew).toFixed(2) : '0.00';
  const originalPrice = booking?.total_price?.toFixed(2) || '0.00';
  const savings = booking?.total_price ? (booking.total_price - (booking.total_price / totalCrew)).toFixed(2) : '0.00';

  // Fetch nearby friends on mount
  useEffect(() => {
    const fetchNearbyFriends = async () => {
      if (!user?.id || !isOpen) return;
      
      setLoading(true);
      try {
        // Get user's current location
        let lat, lon;
        if (navigator.geolocation) {
          try {
            const position = await new Promise((resolve, reject) => {
              navigator.geolocation.getCurrentPosition(resolve, reject, {
                enableHighAccuracy: true,
                timeout: 5000
              });
            });
            lat = position.coords.latitude;
            lon = position.coords.longitude;
          } catch (e) {
            console.log('Geolocation failed, using profile location');
          }
        }
        
        // Fetch nearby friends from API
        const response = await apiClient.get(`/friends/nearby`, {
          params: {
            user_id: user.id,
            latitude: lat,
            longitude: lon,
            radius_miles: 10
          }
        });
        
        setNearbyFriends(response.data || []);
      } catch (error) {
        console.error('Failed to fetch nearby friends:', error);
        // Show empty state instead of error
        setNearbyFriends([]);
      } finally {
        setLoading(false);
      }
    };
    
    fetchNearbyFriends();
  }, [user?.id, isOpen]);

  const toggleFriend = (friendId) => {
    setSelectedFriends(prev => 
      prev.includes(friendId) 
        ? prev.filter(id => id !== friendId)
        : [...prev, friendId]
    );
  };

  const handleSendInvites = async () => {
    if (selectedFriends.length === 0) {
      toast.error('Select at least one friend to invite');
      return;
    }
    
    setSending(true);
    try {
      // Send invites to selected friends
      await apiClient.post(`/bookings/${booking.id}/invite-crew`, {
        friend_ids: selectedFriends,
        share_amount: parseFloat(pricePerPerson),
        message: `Join my surf session! Split cost: $${pricePerPerson}/person`
      }, {
        params: { user_id: user.id }
      });
      
      toast.success(`Invites sent to ${selectedFriends.length} friend${selectedFriends.length > 1 ? 's' : ''}!`);
      onInvitesSent?.(selectedFriends);
      onClose();
    } catch (error) {
      console.error('Invite error:', error);
      toast.error(error.response?.data?.detail || 'Failed to send invites');
    } finally {
      setSending(false);
    }
  };

  const handleSkip = () => {
    onClose();
  };

  // Format session date
  const sessionDate = booking?.session_date 
    ? new Date(booking.session_date).toLocaleDateString('en-US', {
        weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'
      })
    : 'TBD';

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className={`${cardBgClass} border-zinc-700 max-w-md max-h-[80vh] flex flex-col`}>
        <DialogHeader>
          <DialogTitle className={`text-lg font-bold ${textPrimaryClass} flex items-center gap-2`}>
            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-cyan-500 to-blue-500 flex items-center justify-center">
              <Users className="w-5 h-5 text-white" />
            </div>
            Invite Nearby Crew
          </DialogTitle>
          <DialogDescription className={textSecondaryClass}>
            Split the cost of your session booking with friends nearby!
          </DialogDescription>
        </DialogHeader>

        {/* Booking Info */}
        <div className={`p-3 rounded-lg ${isLight ? 'bg-gradient-to-r from-cyan-50 to-blue-50 border border-cyan-200' : 'bg-gradient-to-r from-cyan-500/10 to-blue-500/10 border border-cyan-500/30'} mb-4`}>
          <div className="flex items-center gap-2 mb-2">
            <Waves className="w-4 h-4 text-cyan-400" />
            <span className="text-sm font-medium text-cyan-400">Surf Session Booking</span>
          </div>
          <div className="flex items-center justify-between">
            <div>
              <p className={`font-medium ${textPrimaryClass}`}>{booking?.photographer_name || 'Photographer'}</p>
              <p className={`text-sm ${textSecondaryClass} flex items-center gap-1`}>
                <MapPin className="w-3 h-3" />
                {booking?.location || 'Location TBD'}
              </p>
              <p className={`text-xs ${textSecondaryClass} flex items-center gap-1 mt-1`}>
                <Calendar className="w-3 h-3" />
                {sessionDate}
              </p>
            </div>
            <div className="text-right">
              <p className={`text-sm ${textSecondaryClass} line-through`}>${originalPrice}</p>
              <p className="text-lg font-bold text-green-400">${pricePerPerson}/person</p>
            </div>
          </div>
        </div>

        {/* Savings Banner */}
        {selectedFriends.length > 0 && (
          <div className="bg-green-500/10 border border-green-500/30 rounded-lg p-3 mb-4 flex items-center gap-2">
            <Check className="w-5 h-5 text-green-400" />
            <span className="text-green-400 font-medium">
              You'll save ${savings} by splitting with {selectedFriends.length} friend{selectedFriends.length > 1 ? 's' : ''}!
            </span>
          </div>
        )}

        {/* Nearby Friends List */}
        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-cyan-400" />
              <span className={`ml-2 ${textSecondaryClass}`}>Finding nearby friends...</span>
            </div>
          ) : nearbyFriends.length === 0 ? (
            <div className="text-center py-8">
              <div className={`w-16 h-16 mx-auto mb-4 rounded-full ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} flex items-center justify-center`}>
                <Navigation className={`w-8 h-8 ${textSecondaryClass}`} />
              </div>
              <p className={`font-medium ${textPrimaryClass} mb-2`}>No friends nearby</p>
              <p className={`text-sm ${textSecondaryClass}`}>
                Your friends aren't currently in the area, but you can still book solo or open a Lineup!
              </p>
            </div>
          ) : (
            <div className="space-y-2">
              <p className={`text-sm ${textSecondaryClass} mb-2`}>
                {nearbyFriends.length} friend{nearbyFriends.length > 1 ? 's' : ''} nearby
              </p>
              {nearbyFriends.map((friend) => (
                <button
                  key={friend.id}
                  onClick={() => toggleFriend(friend.id)}
                  className={`w-full flex items-center gap-3 p-3 rounded-lg ${itemBgClass} transition-colors ${
                    selectedFriends.includes(friend.id) ? 'ring-2 ring-cyan-500' : ''
                  }`}
                  data-testid={`invite-friend-${friend.id}`}
                >
                  <Checkbox 
                    checked={selectedFriends.includes(friend.id)}
                    className="border-cyan-500 data-[state=checked]:bg-cyan-500"
                  />
                  <Avatar className="w-10 h-10">
                    <AvatarImage src={getFullUrl(friend.avatar_url)} />
                    <AvatarFallback className="bg-cyan-500/20 text-cyan-400">
                      {(friend.full_name || 'F').charAt(0).toUpperCase()}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex-1 text-left">
                    <p className={`font-medium ${textPrimaryClass}`}>{friend.full_name}</p>
                    <p className={`text-sm ${textSecondaryClass} flex items-center gap-1`}>
                      <MapPin className="w-3 h-3" />
                      {friend.distance_miles?.toFixed(1) || '?'} mi away
                    </p>
                  </div>
                  {selectedFriends.includes(friend.id) && (
                    <Badge className="bg-cyan-500/20 text-cyan-400">
                      <UserCheck className="w-3 h-3 mr-1" />
                      Selected
                    </Badge>
                  )}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex gap-3 mt-4 pt-4 border-t border-zinc-700">
          <Button
            onClick={handleSkip}
            variant="outline"
            className="flex-1 border-zinc-600"
          >
            Book Solo
          </Button>
          <Button
            onClick={handleSendInvites}
            disabled={sending || selectedFriends.length === 0}
            className="flex-1 bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white"
            data-testid="send-crew-invites-btn"
          >
            {sending ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <>
                <UserPlus className="w-4 h-4 mr-2" />
                Invite {selectedFriends.length > 0 ? `(${selectedFriends.length})` : 'Crew'}
              </>
            )}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default InviteNearbyCrewModal;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { getFullUrl } from '../../utils/media';
import { toast } from 'sonner';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Dialog, DialogContent, DialogTitle } from './ui/dialog';
import { 
  Send, 
  ArrowLeft, 
  MoreVertical, 
  Image as ImageIcon, 
  Mic, 
  Smile,
  Reply,
  Check,
  CheckCheck,
  X,
  Search,
  Plus,
  Phone,
  Video
} from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL;

// Quick emoji picker
const QUICK_EMOJIS = ['❤️', '😂', '😮', '😢', '😡', '👍', '🔥', '🎉'];

const Messenger = ({ isOpen, onClose }) => {
  const { user } = useAuth();
  const [conversations, setConversations] = useState([]);
  const [activeConversation, setActiveConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [replyTo, setReplyTo] = useState(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(null); // message id or 'input'
  const [typingUsers, setTypingUsers] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);
  const typingTimeoutRef = useRef(null);

  // Fetch conversations
  const fetchConversations = useCallback(async () => {
    if (!user?.id) return;
    try {
      const response = await apiClient.get(`/messages/conversations/${user.id}`);
      setConversations(response.data.conversations || response.data || []);
    } catch (error) {
      console.error('Failed to fetch conversations:', error);
    }
  }, [user?.id]);

  // Fetch messages for active conversation
  const fetchMessages = useCallback(async () => {
    if (!activeConversation || !user?.id) return;
    setLoading(true);
    try {
      const response = await apiClient.get(
        `/messages/conversation/${activeConversation.id}?user_id=${user.id}`
      );
      setMessages(response.data.messages || []);
    } catch (error) {
      console.error('Failed to fetch messages:', error);
    } finally {
      setLoading(false);
    }
  }, [activeConversation, user?.id]);

  // Poll for typing indicators
  const fetchTypingUsers = useCallback(async () => {
    if (!activeConversation || !user?.id) return;
    try {
      const response = await apiClient.get(
        `/messages/typing/${activeConversation.id}?user_id=${user.id}`
      );
      setTypingUsers(response.data.typing_users || []);
    } catch (error) {
      console.error('Failed to fetch typing:', error);
    }
  }, [activeConversation, user?.id]);

  useEffect(() => {
    if (isOpen) {
      fetchConversations();
    }
  }, [isOpen, fetchConversations]);

  useEffect(() => {
    if (activeConversation) {
      fetchMessages();
      // Poll for new messages and typing every 3 seconds
      const interval = setInterval(() => {
        fetchMessages();
        fetchTypingUsers();
      }, 3000);
      return () => clearInterval(interval);
    }
  }, [activeConversation, fetchMessages, fetchTypingUsers]);

  // Scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Send typing indicator
  const sendTypingIndicator = useCallback(async (isTyping) => {
    if (!activeConversation || !user?.id) return;
    try {
      await apiClient.post(
        `/messages/typing/${activeConversation.id}?user_id=${user.id}`,
        { is_typing: isTyping }
      );
    } catch (error) {
      console.error('Failed to send typing indicator:', error);
    }
  }, [activeConversation, user?.id]);

  // Handle input change with typing indicator
  const handleInputChange = (e) => {
    setNewMessage(e.target.value);
    
    // Send typing indicator
    sendTypingIndicator(true);
    
    // Clear previous timeout
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }
    
    // Stop typing after 2 seconds of inactivity
    typingTimeoutRef.current = setTimeout(() => {
      sendTypingIndicator(false);
    }, 2000);
  };

  // Send message
  const handleSendMessage = async () => {
    if (!newMessage.trim() || !activeConversation || !user?.id) return;
    
    setSending(true);
    try {
      await apiClient.post(
        `/messages/send/${activeConversation.id}?sender_id=${user.id}`,
        {
          content: newMessage,
          message_type: 'text',
          reply_to_id: replyTo?.id || null
        }
      );
      
      setNewMessage('');
      setReplyTo(null);
      sendTypingIndicator(false);
      fetchMessages();
    } catch (error) {
      toast.error('Failed to send message');
    } finally {
      setSending(false);
    }
  };

  // Add reaction to message
  const handleAddReaction = async (messageId, emoji) => {
    if (!user?.id) return;
    try {
      await apiClient.post(
        `/messages/react/${messageId}?user_id=${user.id}`,
        { emoji }
      );
      setShowEmojiPicker(null);
      fetchMessages();
    } catch (error) {
      toast.error('Failed to add reaction');
    }
  };

  // Format timestamp
  const formatTime = (isoString) => {
    const date = new Date(isoString);
    const now = new Date();
    const diff = now - date;
    
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 86400000) return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    return date.toLocaleDateString();
  };

  if (!isOpen) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-zinc-900 border-zinc-800 text-white max-w-lg h-[80vh] p-0 flex flex-col">
        {/* Header with blur effect */}
        <div className="p-4 border-b border-zinc-800 backdrop-blur-xl bg-zinc-900/80 sticky top-0 z-10">
          {activeConversation ? (
            <div className="flex items-center gap-3">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setActiveConversation(null)}
                className="text-white hover:bg-zinc-800 p-1"
              >
                <ArrowLeft className="w-5 h-5" />
              </Button>
              
              <div className="w-10 h-10 rounded-full bg-gradient-to-r from-cyan-400 to-blue-500 flex items-center justify-center overflow-hidden">
                {activeConversation.other_user?.avatar_url ? (
                  <img src={getFullUrl(activeConversation.other_user.avatar_url)} 
                    alt="" 
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <span className="text-black font-bold">
                    {activeConversation.other_user?.full_name?.charAt(0) || '?'}
                  </span>
                )}
              </div>
              
              <div className="flex-1">
                <h3 className="font-bold text-white">{activeConversation.other_user?.full_name}</h3>
                {typingUsers.length > 0 && (
                  <p className="text-xs text-cyan-400 animate-pulse">typing...</p>
                )}
              </div>
              
              <div className="flex items-center gap-1">
                <Button variant="ghost" size="sm" className="text-gray-400 hover:text-white p-2">
                  <Phone className="w-4 h-4" />
                </Button>
                <Button variant="ghost" size="sm" className="text-gray-400 hover:text-white p-2">
                  <Video className="w-4 h-4" />
                </Button>
                <Button variant="ghost" size="sm" className="text-gray-400 hover:text-white p-2">
                  <MoreVertical className="w-4 h-4" />
                </Button>
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-between">
              <DialogTitle className="text-xl font-bold">Messages</DialogTitle>
              <Button variant="ghost" size="sm" className="text-gray-400 hover:text-white">
                <Plus className="w-5 h-5" />
              </Button>
            </div>
          )}
        </div>

        {/* Content */}
        {!activeConversation ? (
          // Conversations List
          <div className="flex-1 overflow-y-auto">
            {/* Search */}
            <div className="p-3 sticky top-0 bg-zinc-900/80 backdrop-blur-sm">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                <Input
                  placeholder="Search conversations..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-10 bg-zinc-800 border-zinc-700 text-white"
                />
              </div>
            </div>

            {conversations.length === 0 ? (
              <div className="p-8 text-center text-gray-500">
                <p>No conversations yet</p>
                <p className="text-sm mt-2">Start a conversation with a surfer or photographer!</p>
              </div>
            ) : (
              <div className="divide-y divide-zinc-800">
                {conversations
                  .filter(c => 
                    !searchQuery || 
                    c.other_user?.full_name?.toLowerCase().includes(searchQuery.toLowerCase())
                  )
                  .map(conv => (
                    <button
                      key={conv.id}
                      onClick={() => setActiveConversation(conv)}
                      className="w-full p-4 flex items-center gap-3 hover:bg-zinc-800/50 transition-colors text-left"
                    >
                      <div className="relative">
                        <div className="w-12 h-12 rounded-full bg-gradient-to-r from-cyan-400 to-blue-500 flex items-center justify-center overflow-hidden">
                          {conv.other_user?.avatar_url ? (
                            <img src={getFullUrl(conv.other_user.avatar_url)} alt="" className="w-full h-full object-cover" />
                          ) : (
                            <span className="text-black font-bold text-lg">
                              {conv.other_user?.full_name?.charAt(0) || '?'}
                            </span>
                          )}
                        </div>
                        {conv.unread_count > 0 && (
                          <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 rounded-full flex items-center justify-center text-xs font-bold">
                            {conv.unread_count}
                          </div>
                        )}
                      </div>
                      
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between">
                          <span className="font-medium text-white">{conv.other_user?.full_name}</span>
                          <span className="text-xs text-gray-500">
                            {conv.last_message_at ? formatTime(conv.last_message_at) : ''}
                          </span>
                        </div>
                        <p className="text-sm text-gray-400 truncate">{conv.last_message || 'No messages yet'}</p>
                      </div>
                    </button>
                  ))}
              </div>
            )}
          </div>
        ) : (
          // Messages View
          <>
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {loading ? (
                <div className="flex justify-center py-8">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-400"></div>
                </div>
              ) : messages.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  <p>No messages yet</p>
                  <p className="text-sm mt-2">Say hello! 👋</p>
                </div>
              ) : (
                messages.map((msg, index) => {
                  const isOwn = msg.sender?.id === user?.id;
                  const showAvatar = !isOwn && (index === 0 || messages[index - 1]?.sender?.id !== msg.sender?.id);
                  
                  return (
                    <div 
                      key={msg.id}
                      className={`flex ${isOwn ? 'justify-end' : 'justify-start'} group`}
                    >
                      {/* Avatar for other user */}
                      {!isOwn && showAvatar && (
                        <div className="w-8 h-8 rounded-full bg-zinc-700 flex items-center justify-center mr-2 flex-shrink-0">
                          {msg.sender?.avatar_url ? (
                            <img src={getFullUrl(msg.sender.avatar_url)} alt="" className="w-full h-full rounded-full object-cover" />
                          ) : (
                            <span className="text-xs text-gray-400">{msg.sender?.full_name?.charAt(0)}</span>
                          )}
                        </div>
                      )}
                      {!isOwn && !showAvatar && <div className="w-8 mr-2" />}
                      
                      <div className={`max-w-[70%] ${isOwn ? 'order-1' : ''}`}>
                        {/* Reply preview */}
                        {msg.reply_to && (
                          <div className={`mb-1 p-2 rounded-lg text-xs ${isOwn ? 'bg-cyan-900/30 text-cyan-300' : 'bg-zinc-800 text-gray-400'}`}>
                            <span className="font-medium">{msg.reply_to.sender_name}</span>
                            <p className="truncate">{msg.reply_to.content}</p>
                          </div>
                        )}
                        
                        {/* Message bubble */}
                        <div 
                          className={`relative p-3 rounded-2xl ${
                            isOwn 
                              ? 'bg-gradient-to-r from-cyan-500 to-blue-500 text-white rounded-tr-sm' 
                              : 'bg-zinc-800 text-white rounded-tl-sm'
                          }`}
                        >
                          <p className="break-words">{msg.content}</p>
                          
                          {/* Time and read status */}
                          <div className={`flex items-center gap-1 mt-1 text-[10px] ${isOwn ? 'text-white/70 justify-end' : 'text-gray-500'}`}>
                            <span>{formatTime(msg.created_at)}</span>
                            {isOwn && (
                              msg.is_read 
                                ? <CheckCheck className="w-3 h-3" /> 
                                : <Check className="w-3 h-3" />
                            )}
                          </div>
                          
                          {/* Reactions */}
                          {msg.reactions && msg.reactions.length > 0 && (
                            <div className="absolute -bottom-3 left-2 flex -space-x-1">
                              {[...new Set(msg.reactions.map(r => r.emoji))].slice(0, 3).map((emoji, i) => (
                                <span key={i} className="text-sm bg-zinc-700 rounded-full px-1">{emoji}</span>
                              ))}
                              {msg.reactions.length > 3 && (
                                <span className="text-xs bg-zinc-700 rounded-full px-1.5 py-0.5">+{msg.reactions.length - 3}</span>
                              )}
                            </div>
                          )}
                        </div>
                        
                        {/* Action buttons (visible on hover) */}
                        <div className={`opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-1 mt-1 ${isOwn ? 'justify-end' : ''}`}>
                          <button 
                            onClick={() => setReplyTo(msg)}
                            className="p-1 text-gray-500 hover:text-white rounded"
                          >
                            <Reply className="w-3 h-3" />
                          </button>
                          <button 
                            onClick={() => setShowEmojiPicker(showEmojiPicker === msg.id ? null : msg.id)}
                            className="p-1 text-gray-500 hover:text-white rounded"
                          >
                            <Smile className="w-3 h-3" />
                          </button>
                        </div>
                        
                        {/* Emoji picker for this message */}
                        {showEmojiPicker === msg.id && (
                          <div className={`absolute mt-1 p-2 bg-zinc-800 rounded-lg shadow-xl flex gap-1 z-20 ${isOwn ? 'right-0' : 'left-0'}`}>
                            {QUICK_EMOJIS.map(emoji => (
                              <button
                                key={emoji}
                                onClick={() => handleAddReaction(msg.id, emoji)}
                                className="text-lg hover:scale-125 transition-transform p-1"
                              >
                                {emoji}
                              </button>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Reply preview */}
            {replyTo && (
              <div className="mx-4 mb-2 p-2 bg-zinc-800 rounded-lg flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Reply className="w-4 h-4 text-cyan-400" />
                  <div>
                    <p className="text-xs text-cyan-400 font-medium">Replying to {replyTo.sender?.full_name}</p>
                    <p className="text-xs text-gray-400 truncate max-w-[200px]">{replyTo.content}</p>
                  </div>
                </div>
                <button onClick={() => setReplyTo(null)} className="text-gray-500 hover:text-white">
                  <X className="w-4 h-4" />
                </button>
              </div>
            )}

            {/* Input area */}
            <div className="p-4 border-t border-zinc-800 bg-zinc-900/80 backdrop-blur-sm">
              <div className="flex items-center gap-2">
                <Button variant="ghost" size="sm" className="text-gray-400 hover:text-white p-2">
                  <ImageIcon className="w-5 h-5" />
                </Button>
                <Button variant="ghost" size="sm" className="text-gray-400 hover:text-white p-2">
                  <Mic className="w-5 h-5" />
                </Button>
                
                <div className="flex-1 relative">
                  <Input
                    ref={inputRef}
                    value={newMessage}
                    onChange={handleInputChange}
                    onKeyPress={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage()}
                    placeholder="Message..."
                    className="bg-zinc-800 border-zinc-700 text-white pr-10"
                  />
                  <button 
                    onClick={() => setShowEmojiPicker(showEmojiPicker === 'input' ? null : 'input')}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-white"
                  >
                    <Smile className="w-4 h-4" />
                  </button>
                  
                  {showEmojiPicker === 'input' && (
                    <div className="absolute bottom-full right-0 mb-2 p-2 bg-zinc-800 rounded-lg shadow-xl flex gap-1 z-20">
                      {QUICK_EMOJIS.map(emoji => (
                        <button
                          key={emoji}
                          onClick={() => {
                            setNewMessage(prev => prev + emoji);
                            setShowEmojiPicker(null);
                            inputRef.current?.focus();
                          }}
                          className="text-lg hover:scale-125 transition-transform p-1"
                        >
                          {emoji}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
                
                <Button
                  onClick={handleSendMessage}
                  disabled={!newMessage.trim() || sending}
                  className="bg-gradient-to-r from-cyan-400 to-blue-500 text-black font-bold p-2"
                >
                  {sending ? (
                    <div className="w-5 h-5 animate-spin rounded-full border-2 border-black border-t-transparent" />
                  ) : (
                    <Send className="w-5 h-5" />
                  )}
                </Button>
              </div>
            </div>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
};

export default Messenger;

import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { Zap, Settings, MapPin, Users, ChevronRight, Loader2 } from 'lucide-react';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from './ui/sheet';
import { Popover, PopoverContent, PopoverTrigger } from './ui/popover';
import { Badge } from './ui/badge';
import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { SpotSelector } from './SpotSelector';
import logger from '../utils/logger';
import { ROLES } from '../constants/roles';


/**
 * OnDemandDutyIcon - On-Demand Duty Access for Photographers (Lightning Bolt)
 * 
 * Features:
 * - Searchable spot selection with radius filtering
 * - Toggle DISABLED until spot is selected
 * - Mutual exclusion with Live mode
 * - GPS status in header (fades when loaded)
 * - "Active at: [Spot Name]" display
 */

const OnDemandMenuContent = ({ 
  onClose, 
  navigate, 
  onDemandActive, 
  selectedSpot,
  onSelectSpot,
  showSpotSelector,
  setShowSpotSelector,
  onToggle, 
  onConfirmActivate,
  nearbyShooters, 
  loading,
  photographerTier
}) => {
  // Toggle is DISABLED until a spot is selected
  const canToggle = onDemandActive || selectedSpot;

  return (
    <div className="space-y-3">
      {/* On-Demand Status Toggle - Primary (Unified UI matching Active Duty) */}
      <div className={`p-4 rounded-xl border-2 transition-all ${
        onDemandActive 
          ? 'bg-gradient-to-r from-yellow-500/20 to-orange-500/20 border-yellow-400/50' 
          : 'bg-zinc-800/50 border-zinc-700'
      }`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={`w-11 h-11 rounded-xl flex items-center justify-center ${
              onDemandActive ? 'bg-yellow-500/30' : 'bg-zinc-700'
            }`}>
              <Zap className={`w-5 h-5 ${onDemandActive ? 'text-yellow-400' : 'text-gray-400'}`} />
            </div>
            <div>
              <p className="text-white font-medium text-sm">Go On-Demand</p>
              <p className={`text-xs ${onDemandActive ? 'text-yellow-300' : 'text-gray-400'}`}>
                {onDemandActive ? 'Accepting requests' : selectedSpot ? 'Ready to activate' : 'Select spot to enable'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {/* Settings shortcut arrow */}
            <button
              onClick={(e) => {
                e.stopPropagation();
                navigate('/photographer/on-demand-settings');
                onClose?.();
              }}
              className="p-1.5 rounded-lg hover:bg-zinc-700/50 text-gray-400 hover:text-yellow-400 transition-colors"
              title="On-Demand Settings"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
            {/* Toggle switch */}
            <button
              onClick={() => {
                if (onDemandActive) {
                  onToggle(); // Turn off
                } else if (selectedSpot) {
                  onConfirmActivate(); // Activate with spot
                } else {
                  setShowSpotSelector(true); // Show spot selector
                }
              }}
              disabled={loading || (!canToggle && !onDemandActive)}
              className={`w-12 h-6 rounded-full transition-colors relative flex-shrink-0 ${
                onDemandActive 
                  ? 'bg-yellow-500' 
                  : canToggle 
                    ? 'bg-zinc-600' 
                    : 'bg-zinc-700 opacity-50 cursor-not-allowed'
              }`}
              data-testid="on-demand-toggle"
            >
              {loading ? (
                <Loader2 className="w-4 h-4 animate-spin absolute top-1 left-1/2 -translate-x-1/2 text-white" />
              ) : (
                <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow transition-all ${
                  onDemandActive ? 'left-[calc(100%-22px)]' : 'left-0.5'
                }`} />
              )}
            </button>
          </div>
        </div>
        
        {/* SpotSelector - Shows when selecting or no spot selected */}
        {(showSpotSelector || (!onDemandActive && !selectedSpot)) && !onDemandActive && (
          <div className="mt-3 pt-3 border-t border-zinc-700">
            <SpotSelector
              selectedSpot={selectedSpot}
              onSelectSpot={(spot) => {
                onSelectSpot(spot);
                setShowSpotSelector(false);
              }}
              photographerTier={photographerTier}
              disabled={false}
              compact={false}
            />
            {/* Activate button after spot selection */}
            {selectedSpot && (
              <button
                onClick={onConfirmActivate}
                disabled={loading}
                className="w-full mt-3 py-2.5 rounded-xl bg-yellow-500 hover:bg-yellow-400 text-black font-medium text-sm flex items-center justify-center gap-2"
                data-testid="activate-on-demand-btn"
              >
                {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4" />}
                Activate On-Demand
              </button>
            )}
          </div>
        )}
        
        {/* Show selected spot when on-demand is active */}
        {onDemandActive && selectedSpot && (
          <div className="mt-3 pt-3 border-t border-yellow-500/30 flex items-center gap-2">
            <MapPin className="w-4 h-4 text-green-400" />
            <span className="text-sm text-green-300">Active at: {typeof selectedSpot === 'object' ? selectedSpot.name : selectedSpot}</span>
          </div>
        )}
        
        {/* Change spot option when active */}
        {onDemandActive && (
          <button
            onClick={() => setShowSpotSelector(true)}
            className="mt-2 text-xs text-yellow-400 hover:text-yellow-300 underline"
          >
            Change spot
          </button>
        )}
      </div>

      {/* Other Shooters Nearby */}
      <button
        onClick={() => {
          navigate('/map?view=photographers');
          onClose?.();
        }}
        className="w-full flex items-center gap-3 p-3 bg-zinc-800/50 hover:bg-zinc-700/50 rounded-xl transition-colors"
        data-testid="on-demand-nearby-shooters"
      >
        <div className="w-10 h-10 rounded-full bg-cyan-500/20 flex items-center justify-center">
          <Users className="w-5 h-5 text-cyan-400" />
        </div>
        <div className="flex-1 text-left">
          <p className="text-white font-medium text-sm">Other Shooters Nearby</p>
          <p className="text-gray-400 text-xs">See who's active in your area</p>
        </div>
        {nearbyShooters > 0 && (
          <Badge className="bg-cyan-500/20 text-cyan-400 border-0">
            {nearbyShooters}
          </Badge>
        )}
        <ChevronRight className="w-4 h-4 text-gray-500" />
      </button>

      {/* On-Demand Settings */}
      <button
        onClick={() => {
          navigate('/photographer/on-demand-settings');
          onClose?.();
        }}
        className="w-full flex items-center gap-3 p-3 bg-zinc-800/50 hover:bg-zinc-700/50 rounded-xl transition-colors"
        data-testid="on-demand-settings"
      >
        <div className="w-10 h-10 rounded-full bg-purple-500/20 flex items-center justify-center">
          <Settings className="w-5 h-5 text-purple-400" />
        </div>
        <div className="flex-1 text-left">
          <p className="text-white font-medium text-sm">On-Demand Settings</p>
          <p className="text-gray-400 text-xs">Pricing, radius, preferences</p>
        </div>
        <ChevronRight className="w-4 h-4 text-gray-500" />
      </button>
    </div>
  );
};

