import React, { useState, useEffect, useRef, useCallback } from 'react';
import apiClient from '../../lib/apiClient';
import {
  Shield, Zap, Users, DollarSign, Search, Ban, CheckCircle,
  Loader2, ChevronDown, ChevronLeft, ChevronRight, Eye, Trash2, UserX, UserCheck,
  Crown, Trophy, Radio, MapPin, Camera, Play, Square, Image, Video,
  Upload, X, Check, User, FileText, ArrowLeft, Settings, Activity,
  Megaphone, History, RefreshCw, TrendingUp, PieChart, BarChart3, Wallet, AlertCircle, Edit, BarChart2,
  Headphones, Server, Flag, Mail, Layout, Lock
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { Badge } from '../ui/badge';
import { toast } from 'sonner';
import { getFullUrl } from '../../utils/media';
import logger from '../../utils/logger';
import { AdminPrecisionQueue } from './AdminPrecisionQueue';

/**
 * AdControlsPanel — Extracted from UnifiedAdminConsole
 * Admin control for ad frequency, approval queue, and variant management.
 */
// Ad Controls Panel Component with Approval Queue
const AdControlsPanel = ({ user }) => {
  const [config, setConfig] = useState(null);
  const [analytics, setAnalytics] = useState(null);
  const [queue, setQueue] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [activeSubTab, setActiveSubTab] = useState('overview'); // 'overview', 'queue', 'variants'
  const [processingAd, setProcessingAd] = useState(null);
  const [editingAd, setEditingAd] = useState(null);
  const [editForm, setEditForm] = useState({});

  useEffect(() => {
    fetchAdData();
  }, [user?.id]);

  const fetchAdData = async () => {
    try {
      const [configRes, analyticsRes, queueRes] = await Promise.all([
        apiClient.get(`/admin/ads/config`).catch(() => ({ data: { config: null } })),
        apiClient.get(`/admin/ads/analytics`).catch(() => ({ data: null })),
        apiClient.get(`/admin/ads/queue?status=pending`).catch(() => ({ data: { queue: [], counts: {} } }))
      ]);
      setConfig(configRes.data?.config);
      setAnalytics(analyticsRes.data);
      setQueue(queueRes.data);
    } catch (error) {
      logger.error('Failed to fetch ad config:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleFrequencyChange = async (newFreq) => {
    setSaving(true);
    try {
      await apiClient.patch(`/admin/ads/frequency?frequency=${newFreq}`);
      setConfig(prev => ({ ...prev, frequency: newFreq }));
      toast.success(`Ad frequency updated to 1 per ${newFreq} posts`);
    } catch (error) {
      toast.error('Failed to update frequency');
    } finally {
      setSaving(false);
    }
  };

  const toggleVariant = async (variantId, isActive) => {
    try {
      await apiClient.patch(`/admin/ads/variant/${variantId}/toggle?is_active=${isActive}`);
      setConfig(prev => ({
        ...prev,
        variants: prev.variants.map(v => v.id === variantId ? { ...v, is_active: isActive } : v)
      }));
      toast.success(`Variant ${isActive ? 'enabled' : 'disabled'}`);
    } catch (error) {
      toast.error('Failed to toggle variant');
    }
  };

  const handleApproveAd = async (adId) => {
    setProcessingAd(adId);
    try {
      await apiClient.post(`/admin/ads/queue/${adId}/action`, {
        action: 'approve'
      });
      toast.success('Ad approved and activated!');
      fetchAdData();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to approve ad');
    } finally {
      setProcessingAd(null);
    }
  };

  const handleRejectAd = async (adId, reason) => {
    setProcessingAd(adId);
    try {
      await apiClient.post(`/admin/ads/queue/${adId}/action`, {
        action: 'reject',
        reason: reason || 'Does not meet advertising guidelines'
      });
      toast.success('Ad rejected');
      fetchAdData();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to reject ad');
    } finally {
      setProcessingAd(null);
    }
  };

  const handleEditAd = async (adId) => {
    setProcessingAd(adId);
    try {
      await apiClient.post(`/admin/ads/queue/${adId}/action`, {
        action: 'edit',
        edited_content: editForm
      });
      toast.success('Ad content updated');
      setEditingAd(null);
      setEditForm({});
      fetchAdData();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to edit ad');
    } finally {
      setProcessingAd(null);
    }
  };

  const startEditing = (ad) => {
    setEditingAd(ad.id);
    setEditForm({
      headline: ad.headline,
      description: ad.description || ad.body,
      cta: ad.cta,
      cta_link: ad.cta_link
    });
  };

  if (loading) {
    return (
      <div className="flex justify-center py-8">
        <Loader2 className="w-6 h-6 animate-spin text-cyan-400" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Sub-tabs */}
      <div className="flex border-b border-border">
        <button
          onClick={() => setActiveSubTab('overview')}
          className={`flex-1 py-2 text-sm font-medium transition-colors ${
            activeSubTab === 'overview' 
              ? 'text-foreground border-b-2 border-cyan-400' 
              : 'text-muted-foreground hover:text-foreground'
          }`}
        >
          Overview
        </button>
        <button
          onClick={() => setActiveSubTab('queue')}
          className={`flex-1 py-2 text-sm font-medium transition-colors relative ${
            activeSubTab === 'queue' 
              ? 'text-foreground border-b-2 border-cyan-400' 
              : 'text-muted-foreground hover:text-foreground'
          }`}
        >
          Approval Queue
          {queue?.counts?.pending > 0 && (
            <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
              {queue.counts.pending}
            </span>
          )}
        </button>
        <button
          onClick={() => setActiveSubTab('variants')}
          className={`flex-1 py-2 text-sm font-medium transition-colors ${
            activeSubTab === 'variants' 
              ? 'text-foreground border-b-2 border-cyan-400' 
              : 'text-muted-foreground hover:text-foreground'
          }`}
        >
          All Variants
        </button>
      </div>

      {/* Overview Sub-Tab */}
      {activeSubTab === 'overview' && (
        <>
          {/* Analytics */}
          {analytics && (
            <Card className="bg-card border-border">
              <CardHeader>
                <CardTitle className="text-foreground text-sm">Ad Performance</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-3 gap-2">
                  <div className="bg-muted rounded-lg p-2 text-center">
                    <p className="text-muted-foreground text-xs">Impressions</p>
                    <p className="text-foreground font-bold">{analytics.analytics?.total_impressions || 0}</p>
                  </div>
                  <div className="bg-muted rounded-lg p-2 text-center">
                    <p className="text-muted-foreground text-xs">Clicks</p>
                    <p className="text-foreground font-bold">{analytics.analytics?.total_clicks || 0}</p>
                  </div>
                  <div className="bg-muted rounded-lg p-2 text-center">
                    <p className="text-muted-foreground text-xs">Ad-Free Users</p>
                    <p className="text-green-400 font-bold">{analytics.ad_free_users || 0}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Frequency Control */}
          {config && (
            <Card className="bg-card border-border">
              <CardHeader>
                <CardTitle className="text-foreground text-sm">Ad Frequency</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-center gap-4">
                  <p className="text-muted-foreground text-sm flex-1">
                    Show 1 ad every <span className="text-cyan-400 font-bold">{config.frequency}</span> posts
                  </p>
                  <div className="flex items-center gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handleFrequencyChange(Math.max(3, (config.frequency || 6) - 1))}
                      disabled={saving || config.frequency <= 3}
                      className="border-border w-8 h-8 p-0"
                    >
                      -
                    </Button>
                    <span className="text-foreground font-bold w-8 text-center">{config.frequency}</span>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handleFrequencyChange(Math.min(20, (config.frequency || 6) + 1))}
                      disabled={saving || config.frequency >= 20}
                      className="border-border w-8 h-8 p-0"
                    >
                      +
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Queue Summary */}
          <Card className="bg-card border-border">
            <CardHeader>
              <CardTitle className="text-foreground text-sm">Approval Queue Summary</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-3 gap-2">
                <div className="bg-yellow-500/10 border border-yellow-500/30 rounded-lg p-3 text-center">
                  <p className="text-yellow-400 text-xs">Pending</p>
                  <p className="text-foreground font-bold text-xl">{queue?.counts?.pending || 0}</p>
                </div>
                <div className="bg-green-500/10 border border-green-500/30 rounded-lg p-3 text-center">
                  <p className="text-green-400 text-xs">Approved</p>
                  <p className="text-foreground font-bold text-xl">{queue?.counts?.approved || 0}</p>
                </div>
                <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-3 text-center">
                  <p className="text-red-400 text-xs">Rejected</p>
                  <p className="text-foreground font-bold text-xl">{queue?.counts?.rejected || 0}</p>
                </div>
              </div>
              {queue?.counts?.pending > 0 && (
                <Button 
                  onClick={() => setActiveSubTab('queue')}
                  className="w-full mt-3 bg-yellow-500 hover:bg-yellow-600 text-black"
                >
                  Review {queue.counts.pending} Pending Ad{queue.counts.pending > 1 ? 's' : ''}
                </Button>
              )}
            </CardContent>
          </Card>
        </>
      )}

      {/* Approval Queue Sub-Tab */}
      {activeSubTab === 'queue' && (
        <div className="space-y-3">
          {(!queue?.pending || queue?.pending?.length === 0) ? (
            <Card className="bg-card border-border">
              <CardContent className="py-8 text-center">
                <Megaphone className="w-12 h-12 text-gray-600 mx-auto mb-3" />
                <p className="text-muted-foreground">No pending ads to review</p>
                <p className="text-gray-500 text-sm mt-1">
                  User-submitted ads will appear here for approval
                </p>
              </CardContent>
            </Card>
          ) : (
            queue?.pending?.map((ad) => (
              <Card key={ad.id} className="bg-card border-yellow-500/30">
                <CardContent className="p-4">
                  {editingAd === ad.id ? (
                    // Edit Mode
                    <div className="space-y-3">
                      <Input
                        value={editForm.headline}
                        onChange={(e) => setEditForm(prev => ({ ...prev, headline: e.target.value }))}
                        placeholder="Headline"
                        className="bg-muted border-border text-foreground"
                      />
                      <Textarea
                        value={editForm.description}
                        onChange={(e) => setEditForm(prev => ({ ...prev, description: e.target.value }))}
                        placeholder="Description"
                        className="bg-muted border-border text-foreground"
                        rows={2}
                      />
                      <div className="grid grid-cols-2 gap-2">
                        <Input
                          value={editForm.cta}
                          onChange={(e) => setEditForm(prev => ({ ...prev, cta: e.target.value }))}
                          placeholder="CTA Text"
                          className="bg-muted border-border text-foreground"
                        />
                        <Input
                          value={editForm.cta_link}
                          onChange={(e) => setEditForm(prev => ({ ...prev, cta_link: e.target.value }))}
                          placeholder="CTA Link"
                          className="bg-muted border-border text-foreground"
                        />
                      </div>
                      <div className="flex gap-2">
                        <Button
                          onClick={() => handleEditAd(ad.id)}
                          disabled={processingAd === ad.id}
                          className="flex-1 bg-cyan-500 hover:bg-cyan-600"
                        >
                          {processingAd === ad.id ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Save Changes'}
                        </Button>
                        <Button
                          variant="outline"
                          onClick={() => { setEditingAd(null); setEditForm({}); }}
                          className="border-border"
                        >
                          Cancel
                        </Button>
                      </div>
                    </div>
                  ) : (
                    // View Mode
                    <>
                      <div className="flex items-start justify-between mb-3">
                        <div>
                          <p className="text-foreground font-medium">{ad.headline}</p>
                          <p className="text-muted-foreground text-sm">{ad.description || ad.body}</p>
                        </div>
                        <Badge className="bg-yellow-500/20 text-yellow-400">
                          {ad.approval_status || 'pending'}
                        </Badge>
                      </div>
                      
                      <div className="flex items-center gap-4 text-xs text-gray-500 mb-3">
                        <span>By: {ad.submitted_by_name || 'Unknown'}</span>
                        <span>Budget: ${ad.budget_credits || 0}</span>
                        <span>CTA: {ad.cta}</span>
                      </div>
                      
                      {/* Media Preview - Support for both images and videos */}
                      {(ad.image_url || ad.video_url) && (
                        <div className="mb-3 relative rounded-lg overflow-hidden">
                          {ad.media_type === 'video' || ad.video_url ? (
                            <>
                              <video 
                                src={ad.video_url || ad.image_url} 
                                poster={ad.thumbnail_url}
                                className="w-full h-32 object-cover" 
                                controls
                              />
                              <div className="absolute top-2 left-2">
                                <Badge className="bg-red-500/90 text-foreground text-xs">
                                  <Video className="w-3 h-3 mr-1" />
                                  Video
                                </Badge>
                              </div>
                            </>
                          ) : (
                            <>
                              <img 
                                src={getFullUrl(ad.image_url)} 
                                alt="Ad preview" 
                                className="w-full h-32 object-cover" 
                              />
                              <div className="absolute top-2 left-2">
                                <Badge className="bg-blue-500/90 text-foreground text-xs">
                                  <Image className="w-3 h-3 mr-1" />
                                  Image
                                </Badge>
                              </div>
                            </>
                          )}
                        </div>
                      )}
                      
                      <div className="flex gap-2">
                        <Button
                          onClick={() => handleApproveAd(ad.id)}
                          disabled={processingAd === ad.id}
                          className="flex-1 bg-green-500 hover:bg-green-600"
                        >
                          {processingAd === ad.id ? <Loader2 className="w-4 h-4 animate-spin" /> : (
                            <>
                              <Check className="w-4 h-4 mr-1" />
                              Approve
                            </>
                          )}
                        </Button>
                        <Button
                          onClick={() => handleRejectAd(ad.id)}
                          disabled={processingAd === ad.id}
                          className="flex-1 bg-red-500 hover:bg-red-600"
                        >
                          <X className="w-4 h-4 mr-1" />
                          Reject
                        </Button>
                        <Button
                          variant="outline"
                          onClick={() => startEditing(ad)}
                          className="border-border"
                        >
                          <FileText className="w-4 h-4" />
                        </Button>
                      </div>
                    </>
                  )}
                </CardContent>
              </Card>
            ))
          )}
        </div>
      )}

      {/* All Variants Sub-Tab */}
      {activeSubTab === 'variants' && config?.variants && (
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground text-sm">All Ad Variants ({config.variants.length})</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {config.variants.map((variant) => (
                <div key={variant.id} className="flex items-center justify-between p-3 bg-muted rounded-lg">
                  <div className="flex-1">
                    <p className="text-foreground font-medium text-sm">{variant.headline}</p>
                    <p className="text-muted-foreground text-xs">
                      {variant.type} • {variant.cta}
                      {variant.submitted_by_name && (
                        <span className="text-cyan-400 ml-2">by {variant.submitted_by_name}</span>
                      )}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    {variant.approval_status && (
                      <Badge className={
                        variant.approval_status === 'approved' ? 'bg-green-500/20 text-green-400' :
                        variant.approval_status === 'rejected' ? 'bg-red-500/20 text-red-400' :
                        'bg-yellow-500/20 text-yellow-400'
                      }>
                        {variant.approval_status}
                      </Badge>
                    )}
                    <Button
                      size="sm"
                      variant={variant.is_active ? 'default' : 'outline'}
                      onClick={() => toggleVariant(variant.id, !variant.is_active)}
                      className={variant.is_active ? 'bg-green-500 hover:bg-green-600' : 'border-input'}
                    >
                      {variant.is_active ? 'Active' : 'Disabled'}
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};



export { AdControlsPanel };

import React, { useState, useEffect, useCallback } from 'react';
import { DollarSign, ShoppingCart, 
  Target, BarChart3, PieChart, RefreshCw, Loader2, Calendar,
  ArrowUpRight, ArrowDownRight, Eye, MousePointer, CreditCard
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { useAuth } from '../../contexts/AuthContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import logger from '../../utils/logger';


/**
 * AdminAnalyticsDashboard - A/B Testing & Booking Conversion Analytics
 * 
 * Features:
 * - Conversion funnel tracking (Views → Bookings → Completed)
 * - A/B test variant comparison
 * - Revenue metrics by source
 * - User segment analysis
 */
export const AdminAnalyticsDashboard = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [timeRange, setTimeRange] = useState('7d');
  const [metrics, setMetrics] = useState(null);
  const [funnelData, setFunnelData] = useState(null);
  const [abTests, setAbTests] = useState([]);

  // Fetch analytics data
  const fetchAnalytics = useCallback(async () => {
    setLoading(true);
    try {
      const [metricsRes, funnelRes] = await Promise.all([
        apiClient.get(`/admin/analytics/metrics`, { params: { range: timeRange } }),
        apiClient.get(`/admin/analytics/funnel`, { params: { range: timeRange } })
      ]);
      
      setMetrics(metricsRes.data);
      setFunnelData(funnelRes.data);
      
      // Mock A/B test data for now
      setAbTests([
        {
          id: 'ab_001',
          name: 'Booking CTA Color',
          status: 'running',
          variants: [
            { name: 'Control (Orange)', conversions: 234, views: 1850, rate: 12.6 },
            { name: 'Variant A (Green)', conversions: 287, views: 1820, rate: 15.8 }
          ],
          winner: 'Variant A',
          confidence: 94.5,
          startDate: '2026-03-28'
        },
        {
          id: 'ab_002',
          name: 'Pricing Display',
          status: 'running',
          variants: [
            { name: 'Control (Per Photo)', conversions: 156, views: 1200, rate: 13.0 },
            { name: 'Variant A (Package)', conversions: 189, views: 1180, rate: 16.0 }
          ],
          winner: 'Variant A',
          confidence: 89.2,
          startDate: '2026-03-30'
        }
      ]);
      
    } catch (error) {
      logger.error('Failed to fetch analytics:', error);
      // Use mock data on error
      setMetrics({
        totalRevenue: 24580,
        revenueChange: 12.5,
        totalBookings: 347,
        bookingsChange: 8.3,
        avgOrderValue: 70.84,
        aovChange: 3.8,
        conversionRate: 4.2,
        conversionChange: 0.5
      });
      setFunnelData({
        spotViews: 15420,
        drawerOpens: 8750,
        bookingClicks: 1245,
        checkoutStarts: 892,
        completedBookings: 347
      });
    } finally {
      setLoading(false);
    }
  }, [user?.id, timeRange]);

  useEffect(() => {
    if (user?.id) {
      fetchAnalytics();
    }
  }, [user?.id, fetchAnalytics]);

  // Calculate funnel percentages
  const calculateFunnelRate = (current, previous) => {
    if (!previous || previous === 0) return 0;
    return ((current / previous) * 100).toFixed(1);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-foreground">Analytics & A/B Testing</h2>
          <p className="text-muted-foreground text-sm">Track booking conversions and test optimizations</p>
        </div>
        <div className="flex items-center gap-3">
          <Select value={timeRange} onValueChange={setTimeRange}>
            <SelectTrigger className="w-32 bg-muted border-border">
              <SelectValue placeholder="Time Range" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="24h">Last 24h</SelectItem>
              <SelectItem value="7d">Last 7 days</SelectItem>
              <SelectItem value="30d">Last 30 days</SelectItem>
              <SelectItem value="90d">Last 90 days</SelectItem>
            </SelectContent>
          </Select>
          <Button variant="outline" onClick={fetchAnalytics} className="border-input">
            <RefreshCw className="w-4 h-4" />
          </Button>
        </div>
      </div>

      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Revenue */}
        <Card className="bg-muted border-border">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-muted-foreground text-sm">Total Revenue</p>
                <p className="text-2xl font-bold text-foreground">${metrics?.totalRevenue?.toLocaleString() || 0}</p>
              </div>
              <div className="w-12 h-12 rounded-full bg-emerald-500/20 flex items-center justify-center">
                <DollarSign className="w-6 h-6 text-emerald-400" />
              </div>
            </div>
            <div className="flex items-center gap-1 mt-2">
              {metrics?.revenueChange >= 0 ? (
                <ArrowUpRight className="w-4 h-4 text-emerald-400" />
              ) : (
                <ArrowDownRight className="w-4 h-4 text-red-400" />
              )}
              <span className={`text-sm ${metrics?.revenueChange >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                {Math.abs(metrics?.revenueChange || 0)}%
              </span>
              <span className="text-gray-500 text-sm">vs last period</span>
            </div>
          </CardContent>
        </Card>

        {/* Bookings */}
        <Card className="bg-muted border-border">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-muted-foreground text-sm">Total Bookings</p>
                <p className="text-2xl font-bold text-foreground">{metrics?.totalBookings || 0}</p>
              </div>
              <div className="w-12 h-12 rounded-full bg-blue-500/20 flex items-center justify-center">
                <ShoppingCart className="w-6 h-6 text-blue-400" />
              </div>
            </div>
            <div className="flex items-center gap-1 mt-2">
              {metrics?.bookingsChange >= 0 ? (
                <ArrowUpRight className="w-4 h-4 text-emerald-400" />
              ) : (
                <ArrowDownRight className="w-4 h-4 text-red-400" />
              )}
              <span className={`text-sm ${metrics?.bookingsChange >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                {Math.abs(metrics?.bookingsChange || 0)}%
              </span>
              <span className="text-gray-500 text-sm">vs last period</span>
            </div>
          </CardContent>
        </Card>

        {/* AOV */}
        <Card className="bg-muted border-border">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-muted-foreground text-sm">Avg Order Value</p>
                <p className="text-2xl font-bold text-foreground">${metrics?.avgOrderValue?.toFixed(2) || 0}</p>
              </div>
              <div className="w-12 h-12 rounded-full bg-yellow-500/20 flex items-center justify-center">
                <CreditCard className="w-6 h-6 text-yellow-400" />
              </div>
            </div>
            <div className="flex items-center gap-1 mt-2">
              {metrics?.aovChange >= 0 ? (
                <ArrowUpRight className="w-4 h-4 text-emerald-400" />
              ) : (
                <ArrowDownRight className="w-4 h-4 text-red-400" />
              )}
              <span className={`text-sm ${metrics?.aovChange >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                {Math.abs(metrics?.aovChange || 0)}%
              </span>
              <span className="text-gray-500 text-sm">vs last period</span>
            </div>
          </CardContent>
        </Card>

        {/* Conversion Rate */}
        <Card className="bg-muted border-border">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-muted-foreground text-sm">Conversion Rate</p>
                <p className="text-2xl font-bold text-foreground">{metrics?.conversionRate || 0}%</p>
              </div>
              <div className="w-12 h-12 rounded-full bg-purple-500/20 flex items-center justify-center">
                <Target className="w-6 h-6 text-purple-400" />
              </div>
            </div>
            <div className="flex items-center gap-1 mt-2">
              {metrics?.conversionChange >= 0 ? (
                <ArrowUpRight className="w-4 h-4 text-emerald-400" />
              ) : (
                <ArrowDownRight className="w-4 h-4 text-red-400" />
              )}
              <span className={`text-sm ${metrics?.conversionChange >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                {Math.abs(metrics?.conversionChange || 0)}pp
              </span>
              <span className="text-gray-500 text-sm">vs last period</span>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Conversion Funnel */}
      <Card className="bg-muted border-border">
        <CardHeader>
          <CardTitle className="text-foreground flex items-center gap-2">
            <BarChart3 className="w-5 h-5 text-cyan-400" />
            Booking Conversion Funnel
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* Funnel Steps */}
            {[
              { label: 'Spot Views', value: funnelData?.spotViews || 0, icon: Eye, color: 'cyan' },
              { label: 'Drawer Opens', value: funnelData?.drawerOpens || 0, icon: MousePointer, color: 'blue' },
              { label: 'Booking Clicks', value: funnelData?.bookingClicks || 0, icon: ShoppingCart, color: 'purple' },
              { label: 'Checkout Starts', value: funnelData?.checkoutStarts || 0, icon: CreditCard, color: 'yellow' },
              { label: 'Completed', value: funnelData?.completedBookings || 0, icon: Target, color: 'emerald' }
            ].map((step, index, arr) => {
              const prevValue = index > 0 ? arr[index - 1].value : step.value;
              const dropRate = index > 0 ? calculateFunnelRate(step.value, prevValue) : 100;
              const Icon = step.icon;
              
              return (
                <div key={step.label} className="flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-lg bg-${step.color}-500/20 flex items-center justify-center flex-shrink-0`}>
                    <Icon className={`w-5 h-5 text-${step.color}-400`} />
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-gray-300 text-sm">{step.label}</span>
                      <span className="text-foreground font-medium">{step.value.toLocaleString()}</span>
                    </div>
                    <div className="w-full bg-input rounded-full h-2">
                      <div 
                        className={`bg-${step.color}-500 h-2 rounded-full transition-all`}
                        style={{ width: `${Math.min(dropRate, 100)}%` }}
                      />
                    </div>
                    {index > 0 && (
                      <p className="text-gray-500 text-xs mt-1">
                        {dropRate}% from previous step
                      </p>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* A/B Tests */}
      <Card className="bg-muted border-border">
        <CardHeader>
          <CardTitle className="text-foreground flex items-center gap-2">
            <PieChart className="w-5 h-5 text-purple-400" />
            Active A/B Tests
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-6">
            {abTests.map(test => (
              <div key={test.id} className="bg-input/50 rounded-xl p-4">
                <div className="flex items-center justify-between mb-4">
                  <div>
                    <h4 className="text-foreground font-medium">{test.name}</h4>
                    <p className="text-muted-foreground text-sm flex items-center gap-2">
                      <Calendar className="w-3 h-3" />
                      Started: {test.startDate}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge className={`${test.confidence >= 95 ? 'bg-emerald-500' : 'bg-yellow-500'} text-foreground`}>
                      {test.confidence}% confidence
                    </Badge>
                    <Badge className="bg-blue-500 text-white">
                      {test.status}
                    </Badge>
                  </div>
                </div>
                
                {/* Variants */}
                <div className="grid grid-cols-2 gap-4">
                  {test.variants.map((variant, idx) => (
                    <div 
                      key={idx}
                      className={`p-3 rounded-lg ${
                        variant.name === test.winner 
                          ? 'bg-emerald-500/10 border border-emerald-500/30' 
                          : 'bg-muted'
                      }`}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-300 text-sm">{variant.name}</span>
                        {variant.name === test.winner && (
                          <Badge className="bg-emerald-500 text-white text-xs">Winner</Badge>
                        )}
                      </div>
                      <div className="grid grid-cols-3 gap-2 text-center">
                        <div>
                          <p className="text-foreground font-bold">{variant.views.toLocaleString()}</p>
                          <p className="text-gray-500 text-xs">Views</p>
                        </div>
                        <div>
                          <p className="text-foreground font-bold">{variant.conversions}</p>
                          <p className="text-gray-500 text-xs">Conversions</p>
                        </div>
                        <div>
                          <p className={`font-bold ${variant.name === test.winner ? 'text-emerald-400' : 'text-foreground'}`}>
                            {variant.rate}%
                          </p>
                          <p className="text-gray-500 text-xs">Rate</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

