﻿import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import {
  Megaphone, Mail, Send, Search,
  Loader2, Plus, Copy
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { Badge } from '../ui/badge';
import { Switch } from '../ui/switch';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { toast } from 'sonner';
import logger from '../../utils/logger';


/**
 * Admin Communications Dashboard
 * - Announcements management
 * - Message templates
 * - Bulk email/notification campaigns
 */
export const AdminCommunicationsDashboard = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [activeTab, setActiveTab] = useState('announcements');
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState(null);
  
  // Announcements
  const [announcements, setAnnouncements] = useState([]);
  const [showAnnouncementForm, setShowAnnouncementForm] = useState(false);
  const [announcementForm, setAnnouncementForm] = useState({
    title: '', content: '', type: 'info', target_audience: 'all', priority: 1
  });
  
  // Templates
  const [templates, setTemplates] = useState([]);
  const [showTemplateForm, setShowTemplateForm] = useState(false);
  const [templateForm, setTemplateForm] = useState({
    name: '', subject: '', body: '', template_type: 'email', category: 'general'
  });
  
  // Campaigns
  const [campaigns, setCampaigns] = useState([]);
  const [showCampaignForm, setShowCampaignForm] = useState(false);
  const [campaignForm, setCampaignForm] = useState({
    name: '', subject: '', body: '', channel: 'email', target_audience: 'all', template_id: ''
  });

  // Search
  const [searchQuery, setSearchQuery] = useState('');

  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';

  useEffect(() => {
    if (user?.id) {
      fetchStats();
      fetchDataForTab();
    }
  }, [user?.id, activeTab]);

  const fetchStats = async () => {
    try {
      const response = await apiClient.get(`/admin/communication/stats?days=30`);
      setStats(response.data);
    } catch (error) {
      logger.error('Failed to load stats:', error);
    }
  };

  const fetchDataForTab = async () => {
    setLoading(true);
    try {
      if (activeTab === 'announcements') {
        const response = await apiClient.get(`/admin/announcements`);
        setAnnouncements(response.data.announcements || []);
      } else if (activeTab === 'templates') {
        const response = await apiClient.get(`/admin/message-templates`);
        setTemplates(response.data.templates || []);
      } else if (activeTab === 'campaigns') {
        const response = await apiClient.get(`/admin/bulk-campaigns`);
        setCampaigns(response.data.campaigns || []);
      }
    } catch (error) {
      logger.error('Failed to load data:', error);
    } finally {
      setLoading(false);
    }
  };

  // Announcements handlers
  const handleCreateAnnouncement = async () => {
    if (!announcementForm.title || !announcementForm.content) {
      toast.error('Please fill required fields');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/announcements`, announcementForm);
      toast.success('Announcement created');
      setShowAnnouncementForm(false);
      setAnnouncementForm({ title: '', content: '', type: 'info', target_audience: 'all', priority: 1 });
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to create announcement');
    } finally {
      setActionLoading(false);
    }
  };

  const handleToggleAnnouncement = async (id) => {
    try {
      await apiClient.put(`/admin/announcements/${id}/toggle`);
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to toggle announcement');
    }
  };

  // Template handlers
  const handleCreateTemplate = async () => {
    if (!templateForm.name || !templateForm.body) {
      toast.error('Please fill required fields');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/message-templates`, templateForm);
      toast.success('Template created');
      setShowTemplateForm(false);
      setTemplateForm({ name: '', subject: '', body: '', template_type: 'email', category: 'general' });
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to create template');
    } finally {
      setActionLoading(false);
    }
  };

  // Campaign handlers
  const handleCreateCampaign = async () => {
    if (!campaignForm.name || !campaignForm.subject) {
      toast.error('Please fill required fields');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/bulk-campaigns`, campaignForm);
      toast.success('Campaign created');
      setShowCampaignForm(false);
      setCampaignForm({ name: '', subject: '', body: '', channel: 'email', target_audience: 'all', template_id: '' });
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to create campaign');
    } finally {
      setActionLoading(false);
    }
  };

  const handleSendCampaign = async (campaignId) => {
    if (!confirm('Send this campaign to all target users?')) return;
    setActionLoading(true);
    try {
      const response = await apiClient.post(`/admin/bulk-campaigns/${campaignId}/send`);
      toast.success(`Sent to ${response.data.total_sent} users`);
      fetchDataForTab();
      fetchStats();
    } catch (error) {
      toast.error('Failed to send campaign');
    } finally {
      setActionLoading(false);
    }
  };

  const getTypeColor = (type) => {
    switch (type) {
      case 'info': return 'bg-blue-500/20 text-blue-400';
      case 'warning': return 'bg-yellow-500/20 text-yellow-400';
      case 'success': return 'bg-green-500/20 text-green-400';
      case 'urgent': return 'bg-red-500/20 text-red-400';
      default: return 'bg-gray-500/20 text-muted-foreground';
    }
  };

  // Filtered data based on search
  const filteredAnnouncements = useMemo(() => {
    if (!searchQuery) return announcements;
    const q = searchQuery.toLowerCase();
    return announcements.filter(a => 
      a.title?.toLowerCase().includes(q) || 
      a.content?.toLowerCase().includes(q)
    );
  }, [announcements, searchQuery]);

  const filteredTemplates = useMemo(() => {
    if (!searchQuery) return templates;
    const q = searchQuery.toLowerCase();
    return templates.filter(t => 
      t.name?.toLowerCase().includes(q) || 
      t.subject?.toLowerCase().includes(q)
    );
  }, [templates, searchQuery]);

  const filteredCampaigns = useMemo(() => {
    if (!searchQuery) return campaigns;
    const q = searchQuery.toLowerCase();
    return campaigns.filter(c => 
      c.name?.toLowerCase().includes(q) || 
      c.subject?.toLowerCase().includes(q)
    );
  }, [campaigns, searchQuery]);

  return (
    <div className="space-y-4" data-testid="admin-communications-dashboard">
      {/* Stats Row */}
      {stats && (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
          <Card className={`${cardBgClass} border-blue-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Active Announcements</p>
              <p className="text-2xl font-bold text-blue-400">{stats.active_announcements}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-green-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Emails Sent (30d)</p>
              <p className="text-2xl font-bold text-green-400">{stats.emails_sent}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-purple-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Avg Open Rate</p>
              <p className="text-2xl font-bold text-purple-400">{stats.avg_open_rate}%</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-cyan-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Templates</p>
              <p className="text-2xl font-bold text-cyan-400">{stats.total_templates}</p>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Tab Navigation */}
      <div className="flex flex-col sm:flex-row gap-2 justify-between">
        <div className="flex gap-2">
          {[
            { id: 'announcements', label: 'Announcements', icon: Megaphone },
            { id: 'templates', label: 'Templates', icon: Mail },
            { id: 'campaigns', label: 'Campaigns', icon: Send }
          ].map(tab => (
            <Button
              key={tab.id}
              variant={activeTab === tab.id ? 'default' : 'outline'}
              size="sm"
              onClick={() => { setActiveTab(tab.id); setSearchQuery(''); }}
              className={activeTab === tab.id ? 'bg-cyan-500 hover:bg-cyan-600' : ''}
            >
              <tab.icon className="w-4 h-4 mr-1" />
              {tab.label}
            </Button>
          ))}
        </div>
        <div className="relative w-full sm:w-64">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-500" />
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder={`Search ${activeTab}...`}
            className="pl-9 bg-muted border-border"
          />
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
        </div>
      ) : (
        <>
          {/* ANNOUNCEMENTS TAB */}
          {activeTab === 'announcements' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>System Announcements ({filteredAnnouncements.length})</CardTitle>
                <Button size="sm" onClick={() => setShowAnnouncementForm(true)} className="bg-blue-500 hover:bg-blue-600">
                  <Plus className="w-4 h-4 mr-1" /> New
                </Button>
              </CardHeader>
              <CardContent>
                {filteredAnnouncements.length === 0 ? (
                  <div className="text-center py-8">
                    <Megaphone className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                    <p className="text-gray-500">{searchQuery ? 'No matches found' : 'No announcements'}</p>
                  </div>
                ) : (
                  <div className="space-y-2 max-h-[400px] overflow-y-auto">
                    {filteredAnnouncements.map(ann => (
                      <div key={ann.id} className="p-3 bg-muted/50 rounded-lg">
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-1">
                              <Badge className={`text-[10px] ${getTypeColor(ann.type)}`}>{ann.type}</Badge>
                              <Badge variant="outline" className="text-[10px]">{ann.target_audience}</Badge>
                            </div>
                            <h4 className={`font-medium ${textClass}`}>{ann.title}</h4>
                            <p className="text-sm text-muted-foreground mt-1 line-clamp-2">{ann.content}</p>
                          </div>
                          <Switch checked={ann.is_active} onCheckedChange={() => handleToggleAnnouncement(ann.id)} />
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* TEMPLATES TAB */}
          {activeTab === 'templates' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>Message Templates ({filteredTemplates.length})</CardTitle>
                <Button size="sm" onClick={() => setShowTemplateForm(true)} className="bg-purple-500 hover:bg-purple-600">
                  <Plus className="w-4 h-4 mr-1" /> New
                </Button>
              </CardHeader>
              <CardContent>
                {filteredTemplates.length === 0 ? (
                  <div className="text-center py-8">
                    <Mail className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                    <p className="text-gray-500">{searchQuery ? 'No matches found' : 'No templates'}</p>
                  </div>
                ) : (
                  <div className="space-y-2 max-h-[400px] overflow-y-auto">
                    {filteredTemplates.map(tpl => (
                      <div key={tpl.id} className="p-3 bg-muted/50 rounded-lg">
                        <div className="flex items-start justify-between">
                          <div>
                            <div className="flex items-center gap-2 mb-1">
                              <Badge variant="outline" className="text-[10px]">{tpl.template_type}</Badge>
                              <Badge className="text-[10px] bg-input">{tpl.category}</Badge>
                            </div>
                            <h4 className={`font-medium ${textClass}`}>{tpl.name}</h4>
                            {tpl.subject && <p className="text-xs text-gray-500">{tpl.subject}</p>}
                          </div>
                          <Button size="sm" variant="ghost" onClick={() => { navigator.clipboard.writeText(tpl.body); toast.success('Copied!'); }}>
                            <Copy className="w-4 h-4" />
                          </Button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* CAMPAIGNS TAB */}
          {activeTab === 'campaigns' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>Bulk Campaigns ({filteredCampaigns.length})</CardTitle>
                <Button size="sm" onClick={() => setShowCampaignForm(true)} className="bg-green-500 hover:bg-green-600">
                  <Plus className="w-4 h-4 mr-1" /> New
                </Button>
              </CardHeader>
              <CardContent>
                {filteredCampaigns.length === 0 ? (
                  <div className="text-center py-8">
                    <Send className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                    <p className="text-gray-500">{searchQuery ? 'No matches found' : 'No campaigns'}</p>
                  </div>
                ) : (
                  <div className="space-y-2 max-h-[400px] overflow-y-auto">
                    {filteredCampaigns.map(camp => (
                      <div key={camp.id} className="p-3 bg-muted/50 rounded-lg">
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-1">
                              <Badge className={`text-[10px] ${
                                camp.status === 'sent' ? 'bg-green-500/20 text-green-400' :
                                camp.status === 'draft' ? 'bg-yellow-500/20 text-yellow-400' :
                                'bg-gray-500/20 text-muted-foreground'
                              }`}>{camp.status}</Badge>
                              <Badge variant="outline" className="text-[10px]">{camp.channel}</Badge>
                            </div>
                            <h4 className={`font-medium ${textClass}`}>{camp.name}</h4>
                            <p className="text-xs text-gray-500 mt-1">{camp.subject}</p>
                            {camp.total_sent > 0 && (
                              <p className="text-xs text-muted-foreground mt-1">
                                Sent: {camp.total_sent} • Open: {camp.total_opened} ({camp.open_rate}%)
                              </p>
                            )}
                          </div>
                          {camp.status === 'draft' && (
                            <Button size="sm" onClick={() => handleSendCampaign(camp.id)} disabled={actionLoading} className="bg-green-500 hover:bg-green-600">
                              <Send className="w-4 h-4 mr-1" /> Send
                            </Button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* Announcement Form Modal */}
      <Dialog open={showAnnouncementForm} onOpenChange={setShowAnnouncementForm}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Create Announcement</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-xs text-gray-500">Title</label>
              <Input value={announcementForm.title} onChange={(e) => setAnnouncementForm({...announcementForm, title: e.target.value})} className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-xs text-gray-500">Content</label>
              <Textarea value={announcementForm.content} onChange={(e) => setAnnouncementForm({...announcementForm, content: e.target.value})} className="bg-muted border-border mt-1" rows={3} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Type</label>
                <Select value={announcementForm.type} onValueChange={(v) => setAnnouncementForm({...announcementForm, type: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="info">Info</SelectItem>
                    <SelectItem value="warning">Warning</SelectItem>
                    <SelectItem value="success">Success</SelectItem>
                    <SelectItem value="urgent">Urgent</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-xs text-gray-500">Audience</label>
                <Select value={announcementForm.target_audience} onValueChange={(v) => setAnnouncementForm({...announcementForm, target_audience: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Users</SelectItem>
                    <SelectItem value="photographers">Photographers</SelectItem>
                    <SelectItem value="surfers">Surfers</SelectItem>
                    <SelectItem value="premium">Premium</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAnnouncementForm(false)}>Cancel</Button>
            <Button onClick={handleCreateAnnouncement} disabled={actionLoading} className="bg-blue-500">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Template Form Modal */}
      <Dialog open={showTemplateForm} onOpenChange={setShowTemplateForm}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Create Template</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-xs text-gray-500">Name</label>
              <Input value={templateForm.name} onChange={(e) => setTemplateForm({...templateForm, name: e.target.value})} placeholder="Welcome Email" className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-xs text-gray-500">Subject</label>
              <Input value={templateForm.subject} onChange={(e) => setTemplateForm({...templateForm, subject: e.target.value})} className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-xs text-gray-500">Body</label>
              <Textarea value={templateForm.body} onChange={(e) => setTemplateForm({...templateForm, body: e.target.value})} className="bg-muted border-border mt-1" rows={4} placeholder="Use {{name}}, {{email}} for placeholders" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Type</label>
                <Select value={templateForm.template_type} onValueChange={(v) => setTemplateForm({...templateForm, template_type: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="email">Email</SelectItem>
                    <SelectItem value="push">Push Notification</SelectItem>
                    <SelectItem value="sms">SMS</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-xs text-gray-500">Category</label>
                <Select value={templateForm.category} onValueChange={(v) => setTemplateForm({...templateForm, category: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="general">General</SelectItem>
                    <SelectItem value="marketing">Marketing</SelectItem>
                    <SelectItem value="transactional">Transactional</SelectItem>
                    <SelectItem value="support">Support</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowTemplateForm(false)}>Cancel</Button>
            <Button onClick={handleCreateTemplate} disabled={actionLoading} className="bg-purple-500">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Campaign Form Modal */}
      <Dialog open={showCampaignForm} onOpenChange={setShowCampaignForm}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Create Campaign</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-xs text-gray-500">Campaign Name</label>
              <Input value={campaignForm.name} onChange={(e) => setCampaignForm({...campaignForm, name: e.target.value})} className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-xs text-gray-500">Subject</label>
              <Input value={campaignForm.subject} onChange={(e) => setCampaignForm({...campaignForm, subject: e.target.value})} className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-xs text-gray-500">Body</label>
              <Textarea value={campaignForm.body} onChange={(e) => setCampaignForm({...campaignForm, body: e.target.value})} className="bg-muted border-border mt-1" rows={3} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Channel</label>
                <Select value={campaignForm.channel} onValueChange={(v) => setCampaignForm({...campaignForm, channel: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="email">Email</SelectItem>
                    <SelectItem value="push">Push</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-xs text-gray-500">Audience</label>
                <Select value={campaignForm.target_audience} onValueChange={(v) => setCampaignForm({...campaignForm, target_audience: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Users</SelectItem>
                    <SelectItem value="active">Active Users</SelectItem>
                    <SelectItem value="photographers">Photographers</SelectItem>
                    <SelectItem value="premium">Premium</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowCampaignForm(false)}>Cancel</Button>
            <Button onClick={handleCreateCampaign} disabled={actionLoading} className="bg-green-500">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AdminCommunicationsDashboard;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { Image, Key, Star, Newspaper, Search,
  Loader2, Plus, Edit2, Globe,
  ChevronLeft, ChevronRight
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { Badge } from '../ui/badge';
import { Switch } from '../ui/switch';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { toast } from 'sonner';
import logger from '../../utils/logger';
import { getFullUrl } from '../../utils/media';


/**
 * Admin Content Management Dashboard
 * - Featured content curation
 * - Banner management
 * - SEO settings for spots
 * - API key management
 * - Scheduled reports
 * - Changelog
 */
export const AdminContentMgmtDashboard = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [activeTab, setActiveTab] = useState('featured');
  const [loading, setLoading] = useState(true);
  
  // Featured Content
  const [featuredContent, setFeaturedContent] = useState([]);
  const [showFeaturedForm, setShowFeaturedForm] = useState(false);
  const [featuredForm, setFeaturedForm] = useState({
    content_type: 'post', content_id: '', display_position: 'homepage', priority: 1
  });
  
  // Banners
  const [banners, setBanners] = useState([]);
  const [showBannerForm, setShowBannerForm] = useState(false);
  const [bannerForm, setBannerForm] = useState({
    title: '', image_url: '', link_url: '', position: 'top', target_audience: 'all'
  });
  
  // SEO
  const [seoSpots, setSeoSpots] = useState([]);
  const [seoTotal, setSeoTotal] = useState(0);
  const [seoPage, setSeoPage] = useState(0);
  const [seoSearch, setSeoSearch] = useState('');
  const [selectedSeoSpot, setSelectedSeoSpot] = useState(null);
  const [seoForm, setSeoForm] = useState({ meta_title: '', meta_description: '', slug: '' });
  const SEO_PAGE_SIZE = 15;
  
  // API Keys
  const [apiKeys, setApiKeys] = useState([]);
  const [showApiKeyForm, setShowApiKeyForm] = useState(false);
  const [apiKeyForm, setApiKeyForm] = useState({ name: '', permissions: 'read', rate_limit: 1000 });
  
  // Changelog
  const [changelog, setChangelog] = useState([]);
  const [showChangelogForm, setShowChangelogForm] = useState(false);
  const [changelogForm, setChangelogForm] = useState({
    version: '', title: '', description: '', change_type: 'feature'
  });

  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';

  useEffect(() => {
    if (user?.id) {
      fetchDataForTab();
    }
  }, [user?.id, activeTab, seoPage, seoSearch]);

  const fetchDataForTab = async () => {
    setLoading(true);
    try {
      if (activeTab === 'featured') {
        const response = await apiClient.get(`/admin/content/featured`);
        setFeaturedContent(response.data.items || []);
      } else if (activeTab === 'banners') {
        const response = await apiClient.get(`/admin/content/banners`);
        setBanners(response.data.banners || []);
      } else if (activeTab === 'seo') {
        const response = await apiClient.get(`/admin/content/seo/spots?limit=${SEO_PAGE_SIZE}&offset=${seoPage * SEO_PAGE_SIZE}${seoSearch ? `&search=${encodeURIComponent(seoSearch)}` : ''}`);
        setSeoSpots(response.data.spots || []);
        setSeoTotal(response.data.total || 0);
      } else if (activeTab === 'api-keys') {
        const response = await apiClient.get(`/admin/tools/api-keys`);
        setApiKeys(response.data.api_keys || []);
      } else if (activeTab === 'changelog') {
        const response = await apiClient.get(`/admin/tools/changelog`);
        setChangelog(response.data.entries || []);
      }
    } catch (error) {
      logger.error('Failed to load data:', error);
    } finally {
      setLoading(false);
    }
  };

  // Featured Content handlers
  const handleCreateFeatured = async () => {
    if (!featuredForm.content_id) {
      toast.error('Please provide content ID');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/content/featured`, featuredForm);
      toast.success('Featured content added');
      setShowFeaturedForm(false);
      setFeaturedForm({ content_type: 'post', content_id: '', display_position: 'homepage', priority: 1 });
      fetchDataForTab();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to add featured content');
    } finally {
      setActionLoading(false);
    }
  };

  // Banner handlers
  const handleCreateBanner = async () => {
    if (!bannerForm.title || !bannerForm.image_url) {
      toast.error('Please fill required fields');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/content/banners`, bannerForm);
      toast.success('Banner created');
      setShowBannerForm(false);
      setBannerForm({ title: '', image_url: '', link_url: '', position: 'top', target_audience: 'all' });
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to create banner');
    } finally {
      setActionLoading(false);
    }
  };

  const handleToggleBanner = async (bannerId) => {
    try {
      await apiClient.put(`/admin/content/banners/${bannerId}/toggle`);
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to toggle banner');
    }
  };

  // SEO handlers
  const handleUpdateSeo = async () => {
    if (!selectedSeoSpot) return;
    setActionLoading(true);
    try {
      await apiClient.put(`/admin/content/seo/spots/${selectedSeoSpot.id}`, seoForm);
      toast.success('SEO updated');
      setSelectedSeoSpot(null);
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to update SEO');
    } finally {
      setActionLoading(false);
    }
  };

  // API Key handlers
  const handleCreateApiKey = async () => {
    if (!apiKeyForm.name) {
      toast.error('Please provide a name');
      return;
    }
    setActionLoading(true);
    try {
      const response = await apiClient.post(`/admin/tools/api-keys`, apiKeyForm);
      toast.success('API key created');
      // Show the key once
      navigator.clipboard.writeText(response.data.key);
      toast.info('Key copied to clipboard');
      setShowApiKeyForm(false);
      setApiKeyForm({ name: '', permissions: 'read', rate_limit: 1000 });
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to create API key');
    } finally {
      setActionLoading(false);
    }
  };

  // Changelog handlers
  const handleCreateChangelog = async () => {
    if (!changelogForm.version || !changelogForm.title) {
      toast.error('Please fill required fields');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/tools/changelog`, changelogForm);
      toast.success('Changelog entry created');
      setShowChangelogForm(false);
      setChangelogForm({ version: '', title: '', description: '', change_type: 'feature' });
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to create changelog');
    } finally {
      setActionLoading(false);
    }
  };

  const handlePublishChangelog = async (entryId) => {
    try {
      await apiClient.put(`/admin/tools/changelog/${entryId}/publish`);
      toast.success('Published');
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to publish');
    }
  };

  const getChangeTypeColor = (type) => {
    switch (type) {
      case 'feature': return 'bg-green-500/20 text-green-400';
      case 'improvement': return 'bg-blue-500/20 text-blue-400';
      case 'bugfix': return 'bg-yellow-500/20 text-yellow-400';
      case 'breaking': return 'bg-red-500/20 text-red-400';
      default: return 'bg-gray-500/20 text-muted-foreground';
    }
  };

  return (
    <div className="space-y-4" data-testid="admin-content-mgmt-dashboard">
      {/* Tab Navigation */}
      <div className="flex gap-2 overflow-x-auto pb-1">
        {[
          { id: 'featured', label: 'Featured', icon: Star },
          { id: 'banners', label: 'Banners', icon: Image },
          { id: 'seo', label: 'SEO', icon: Globe },
          { id: 'api-keys', label: 'API Keys', icon: Key },
          { id: 'changelog', label: 'Changelog', icon: Newspaper }
        ].map(tab => (
          <Button
            key={tab.id}
            variant={activeTab === tab.id ? 'default' : 'outline'}
            size="sm"
            onClick={() => setActiveTab(tab.id)}
            className={activeTab === tab.id ? 'bg-cyan-500 hover:bg-cyan-600' : ''}
          >
            <tab.icon className="w-4 h-4 mr-1" />
            {tab.label}
          </Button>
        ))}
      </div>

      {loading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
        </div>
      ) : (
        <>
          {/* FEATURED TAB */}
          {activeTab === 'featured' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>Featured Content</CardTitle>
                <Button size="sm" onClick={() => setShowFeaturedForm(true)} className="bg-yellow-500 hover:bg-yellow-600">
                  <Plus className="w-4 h-4 mr-1" /> Add
                </Button>
              </CardHeader>
              <CardContent>
                {featuredContent.length === 0 ? (
                  <div className="text-center py-8">
                    <Star className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                    <p className="text-gray-500">No featured content</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {featuredContent.map(item => (
                      <div key={item.id} className="p-3 bg-muted/50 rounded-lg flex items-center justify-between">
                        <div>
                          <div className="flex items-center gap-2 mb-1">
                            <Badge variant="outline" className="text-[10px]">{item.content_type}</Badge>
                            <Badge className="text-[10px] bg-input">{item.display_position}</Badge>
                          </div>
                          <p className={`text-sm ${textClass}`}>ID: {item.content_id}</p>
                          <p className="text-xs text-gray-500">Priority: {item.priority}</p>
                        </div>
                        <Switch checked={item.is_active} />
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* BANNERS TAB */}
          {activeTab === 'banners' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>Promotional Banners</CardTitle>
                <Button size="sm" onClick={() => setShowBannerForm(true)} className="bg-purple-500 hover:bg-purple-600">
                  <Plus className="w-4 h-4 mr-1" /> Add
                </Button>
              </CardHeader>
              <CardContent>
                {banners.length === 0 ? (
                  <div className="text-center py-8">
                    <Image className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                    <p className="text-gray-500">No banners</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {banners.map(banner => (
                      <div key={banner.id} className="p-3 bg-muted/50 rounded-lg">
                        <div className="flex items-start justify-between">
                          <div className="flex gap-3">
                            {banner.image_url && (
                              <img src={getFullUrl(banner.image_url)} alt={banner.title} className="w-20 h-12 object-cover rounded" />
                            )}
                            <div>
                              <p className={`font-medium ${textClass}`}>{banner.title}</p>
                              <div className="flex items-center gap-2 mt-1">
                                <Badge variant="outline" className="text-[10px]">{banner.position}</Badge>
                                <Badge className="text-[10px] bg-input">{banner.target_audience}</Badge>
                              </div>
                            </div>
                          </div>
                          <Switch checked={banner.is_active} onCheckedChange={() => handleToggleBanner(banner.id)} />
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* SEO TAB */}
          {activeTab === 'seo' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                  <CardTitle className={`text-sm ${textClass}`}>Spot SEO Settings ({seoTotal} spots)</CardTitle>
                  <div className="relative w-full sm:w-64">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-500" />
                    <Input
                      value={seoSearch}
                      onChange={(e) => { setSeoSearch(e.target.value); setSeoPage(0); }}
                      placeholder="Search spots..."
                      className="pl-9 bg-muted border-border"
                    />
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                {seoSpots.length === 0 ? (
                  <div className="text-center py-8">
                    <Globe className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                    <p className="text-gray-500">{seoSearch ? 'No spots match your search' : 'No spots to configure'}</p>
                  </div>
                ) : (
                  <>
                    <div className="space-y-2 max-h-[400px] overflow-y-auto">
                      {seoSpots.map(spot => (
                        <div key={spot.id} className="p-3 bg-muted/50 rounded-lg flex items-center justify-between">
                          <div>
                            <p className={`font-medium ${textClass}`}>{spot.name}</p>
                            <p className="text-xs text-gray-500">{spot.region}, {spot.country}</p>
                            {spot.seo_score !== undefined && (
                              <Badge className={`text-[10px] mt-1 ${
                                spot.seo_score >= 80 ? 'bg-green-500/20 text-green-400' :
                                spot.seo_score >= 50 ? 'bg-yellow-500/20 text-yellow-400' :
                                'bg-red-500/20 text-red-400'
                              }`}>SEO: {spot.seo_score}</Badge>
                            )}
                          </div>
                          <Button size="sm" variant="outline" onClick={() => {
                            setSelectedSeoSpot(spot);
                            setSeoForm({
                              meta_title: spot.meta_title || '',
                              meta_description: spot.meta_description || '',
                              slug: spot.slug || ''
                            });
                          }}>
                            <Edit2 className="w-4 h-4" />
                          </Button>
                        </div>
                      ))}
                    </div>
                    {/* Pagination */}
                    {seoTotal > SEO_PAGE_SIZE && (
                      <div className="flex items-center justify-between mt-4 pt-4 border-t border-border">
                        <p className="text-xs text-gray-500">
                          Showing {seoPage * SEO_PAGE_SIZE + 1}-{Math.min((seoPage + 1) * SEO_PAGE_SIZE, seoTotal)} of {seoTotal}
                        </p>
                        <div className="flex gap-2">
                          <Button
                            size="sm"
                            variant="outline"
                            disabled={seoPage === 0}
                            onClick={() => setSeoPage(p => Math.max(0, p - 1))}
                          >
                            <ChevronLeft className="w-4 h-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            disabled={(seoPage + 1) * SEO_PAGE_SIZE >= seoTotal}
                            onClick={() => setSeoPage(p => p + 1)}
                          >
                            <ChevronRight className="w-4 h-4" />
                          </Button>
                        </div>
                      </div>
                    )}
                  </>
                )}
              </CardContent>
            </Card>
          )}

          {/* API KEYS TAB */}
          {activeTab === 'api-keys' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>API Keys</CardTitle>
                <Button size="sm" onClick={() => setShowApiKeyForm(true)} className="bg-green-500 hover:bg-green-600">
                  <Plus className="w-4 h-4 mr-1" /> Generate
                </Button>
              </CardHeader>
              <CardContent>
                {apiKeys.length === 0 ? (
                  <div className="text-center py-8">
                    <Key className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                    <p className="text-gray-500">No API keys</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {apiKeys.map(key => (
                      <div key={key.id} className="p-3 bg-muted/50 rounded-lg flex items-center justify-between">
                        <div>
                          <p className={`font-medium ${textClass}`}>{key.name}</p>
                          <div className="flex items-center gap-2 mt-1">
                            <code className="text-xs text-gray-500 bg-card px-2 py-0.5 rounded">{key.key_prefix}...</code>
                            <Badge variant="outline" className="text-[10px]">{key.permissions}</Badge>
                          </div>
                          <p className="text-xs text-gray-500 mt-1">
                            Calls: {key.total_calls} • Limit: {key.rate_limit}/day
                          </p>
                        </div>
                        <Switch checked={key.is_active} />
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* CHANGELOG TAB */}
          {activeTab === 'changelog' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>Changelog</CardTitle>
                <Button size="sm" onClick={() => setShowChangelogForm(true)} className="bg-blue-500 hover:bg-blue-600">
                  <Plus className="w-4 h-4 mr-1" /> Add Entry
                </Button>
              </CardHeader>
              <CardContent>
                {changelog.length === 0 ? (
                  <div className="text-center py-8">
                    <Newspaper className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                    <p className="text-gray-500">No changelog entries</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {changelog.map(entry => (
                      <div key={entry.id} className="p-3 bg-muted/50 rounded-lg">
                        <div className="flex items-start justify-between">
                          <div>
                            <div className="flex items-center gap-2 mb-1">
                              <Badge className="text-[10px] bg-input">v{entry.version}</Badge>
                              <Badge className={`text-[10px] ${getChangeTypeColor(entry.change_type)}`}>
                                {entry.change_type}
                              </Badge>
                              {!entry.is_published && (
                                <Badge className="text-[10px] bg-yellow-500/20 text-yellow-400">Draft</Badge>
                              )}
                            </div>
                            <p className={`font-medium ${textClass}`}>{entry.title}</p>
                            <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{entry.description}</p>
                          </div>
                          {!entry.is_published && (
                            <Button size="sm" variant="outline" onClick={() => handlePublishChangelog(entry.id)}>
                              Publish
                            </Button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* Featured Form Modal */}
      <Dialog open={showFeaturedForm} onOpenChange={setShowFeaturedForm}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Add Featured Content</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-xs text-gray-500">Content Type</label>
              <Select value={featuredForm.content_type} onValueChange={(v) => setFeaturedForm({...featuredForm, content_type: v})}>
                <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="post">Post</SelectItem>
                  <SelectItem value="spot">Spot</SelectItem>
                  <SelectItem value="photographer">Photographer</SelectItem>
                  <SelectItem value="gallery">Gallery Item</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-xs text-gray-500">Content ID</label>
              <Input value={featuredForm.content_id} onChange={(e) => setFeaturedForm({...featuredForm, content_id: e.target.value})} className="bg-muted border-border mt-1" placeholder="UUID of the content" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Position</label>
                <Select value={featuredForm.display_position} onValueChange={(v) => setFeaturedForm({...featuredForm, display_position: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="homepage">Homepage</SelectItem>
                    <SelectItem value="explore">Explore</SelectItem>
                    <SelectItem value="sidebar">Sidebar</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-xs text-gray-500">Priority</label>
                <Input type="number" value={featuredForm.priority} onChange={(e) => setFeaturedForm({...featuredForm, priority: parseInt(e.target.value) || 1})} className="bg-muted border-border mt-1" min={1} max={100} />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowFeaturedForm(false)}>Cancel</Button>
            <Button onClick={handleCreateFeatured} disabled={actionLoading} className="bg-yellow-500">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Add'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Banner Form Modal */}
      <Dialog open={showBannerForm} onOpenChange={setShowBannerForm}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Create Banner</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-xs text-gray-500">Title</label>
              <Input value={bannerForm.title} onChange={(e) => setBannerForm({...bannerForm, title: e.target.value})} className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-xs text-gray-500">Image URL</label>
              <Input value={bannerForm.image_url} onChange={(e) => setBannerForm({...bannerForm, image_url: e.target.value})} className="bg-muted border-border mt-1" placeholder="https://..." />
            </div>
            <div>
              <label className="text-xs text-gray-500">Link URL (optional)</label>
              <Input value={bannerForm.link_url} onChange={(e) => setBannerForm({...bannerForm, link_url: e.target.value})} className="bg-muted border-border mt-1" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Position</label>
                <Select value={bannerForm.position} onValueChange={(v) => setBannerForm({...bannerForm, position: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="top">Top</SelectItem>
                    <SelectItem value="sidebar">Sidebar</SelectItem>
                    <SelectItem value="bottom">Bottom</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-xs text-gray-500">Audience</label>
                <Select value={bannerForm.target_audience} onValueChange={(v) => setBannerForm({...bannerForm, target_audience: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Users</SelectItem>
                    <SelectItem value="free">Free Users</SelectItem>
                    <SelectItem value="premium">Premium</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowBannerForm(false)}>Cancel</Button>
            <Button onClick={handleCreateBanner} disabled={actionLoading} className="bg-purple-500">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* SEO Edit Modal */}
      <Dialog open={!!selectedSeoSpot} onOpenChange={() => setSelectedSeoSpot(null)}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Edit SEO - {selectedSeoSpot?.name}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-xs text-gray-500">Meta Title</label>
              <Input value={seoForm.meta_title} onChange={(e) => setSeoForm({...seoForm, meta_title: e.target.value})} className="bg-muted border-border mt-1" placeholder="Max 60 characters" />
            </div>
            <div>
              <label className="text-xs text-gray-500">Meta Description</label>
              <Textarea value={seoForm.meta_description} onChange={(e) => setSeoForm({...seoForm, meta_description: e.target.value})} className="bg-muted border-border mt-1" rows={3} placeholder="Max 160 characters" />
            </div>
            <div>
              <label className="text-xs text-gray-500">URL Slug</label>
              <Input value={seoForm.slug} onChange={(e) => setSeoForm({...seoForm, slug: e.target.value})} className="bg-muted border-border mt-1" placeholder="pipeline-banzai" />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setSelectedSeoSpot(null)}>Cancel</Button>
            <Button onClick={handleUpdateSeo} disabled={actionLoading} className="bg-green-500">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Save'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* API Key Form Modal */}
      <Dialog open={showApiKeyForm} onOpenChange={setShowApiKeyForm}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Generate API Key</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-xs text-gray-500">Name</label>
              <Input value={apiKeyForm.name} onChange={(e) => setApiKeyForm({...apiKeyForm, name: e.target.value})} className="bg-muted border-border mt-1" placeholder="My App" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Permissions</label>
                <Select value={apiKeyForm.permissions} onValueChange={(v) => setApiKeyForm({...apiKeyForm, permissions: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="read">Read Only</SelectItem>
                    <SelectItem value="write">Read/Write</SelectItem>
                    <SelectItem value="admin">Admin</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-xs text-gray-500">Rate Limit (calls/day)</label>
                <Input type="number" value={apiKeyForm.rate_limit} onChange={(e) => setApiKeyForm({...apiKeyForm, rate_limit: parseInt(e.target.value) || 1000})} className="bg-muted border-border mt-1" />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowApiKeyForm(false)}>Cancel</Button>
            <Button onClick={handleCreateApiKey} disabled={actionLoading} className="bg-green-500">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Generate'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Changelog Form Modal */}
      <Dialog open={showChangelogForm} onOpenChange={setShowChangelogForm}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Add Changelog Entry</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-gray-500">Version</label>
                <Input value={changelogForm.version} onChange={(e) => setChangelogForm({...changelogForm, version: e.target.value})} className="bg-muted border-border mt-1" placeholder="1.2.0" />
              </div>
              <div>
                <label className="text-xs text-gray-500">Type</label>
                <Select value={changelogForm.change_type} onValueChange={(v) => setChangelogForm({...changelogForm, change_type: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="feature">Feature</SelectItem>
                    <SelectItem value="improvement">Improvement</SelectItem>
                    <SelectItem value="bugfix">Bug Fix</SelectItem>
                    <SelectItem value="breaking">Breaking Change</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div>
              <label className="text-xs text-gray-500">Title</label>
              <Input value={changelogForm.title} onChange={(e) => setChangelogForm({...changelogForm, title: e.target.value})} className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-xs text-gray-500">Description</label>
              <Textarea value={changelogForm.description} onChange={(e) => setChangelogForm({...changelogForm, description: e.target.value})} className="bg-muted border-border mt-1" rows={3} />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowChangelogForm(false)}>Cancel</Button>
            <Button onClick={handleCreateChangelog} disabled={actionLoading} className="bg-blue-500">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AdminContentMgmtDashboard;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient from '../../lib/apiClient';
import {
  Shield, Image, MessageSquare, Check, X,
  Loader2, RefreshCw, Eye, Flag, Trash2, Radio
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';
import { Textarea } from '../ui/textarea';
import { toast } from 'sonner';
import logger from '../../utils/logger';
import { getFullUrl } from '../../utils/media';

/**
 * Admin Content Moderation Dashboard
 * - Review flagged content (posts, comments, images)
 * - Approve, reject, or escalate content
 * - Bulk moderation actions
 */
export const AdminContentModDashboard = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [loading, setLoading] = useState(true);
  const [items, setItems] = useState([]);
  const [stats, setStats] = useState(null);
  const [selectedItems, setSelectedItems] = useState(new Set());
  
  // Filters
  const [contentType, setContentType] = useState('all');
  const [status, setStatus] = useState('pending');
  
  // Preview
  const [selectedItem, setSelectedItem] = useState(null);
  const [moderationNote, setModerationNote] = useState('');
  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';

  useEffect(() => {
    if (user?.id) {
      fetchQueue();
      fetchStats();
    }
  }, [user?.id, contentType, status]);

  const fetchQueue = async () => {
    setLoading(true);
    try {
      let url = `/admin/content-moderation/queue?status=${status}&limit=50`;
      if (contentType && contentType !== 'all') url += `&content_type=${contentType}`;
      const response = await apiClient.get(url);
      setItems(response.data.items || []);
    } catch (error) {
      logger.error('Failed to load queue:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const response = await apiClient.get(`/admin/content-moderation/stats?days=30`);
      setStats(response.data);
    } catch (error) {
      logger.error('Failed to load stats:', error);
    }
  };

  const handleModerate = async (itemId, action) => {
    setActionLoading(true);
    try {
      // For condition reports, use 'delete' action to ensure hard-deletion
      const item = items.find(i => i.id === itemId);
      const effectiveAction = (action === 'reject' && item?.content_type === 'condition_report') ? 'delete' : action;
      
      await apiClient.post(`/admin/content-moderation/${itemId}/moderate`, {
        action: effectiveAction,
        rejection_reason: action === 'reject' ? moderationNote : null
      });
      toast.success(effectiveAction === 'delete' ? 'Content permanently deleted' : `Content ${action}ed`);
      setSelectedItem(null);
      setModerationNote('');
      fetchQueue();
      fetchStats();
    } catch (error) {
      toast.error('Failed to moderate content');
    } finally {
      setActionLoading(false);
    }
  };

  const handlePurgeOrphans = async () => {
    if (!window.confirm('This will permanently delete ALL condition reports with no linked sessions. Continue?')) return;
    setActionLoading(true);
    try {
      const response = await apiClient.post('/admin/condition-reports/purge-orphans');
      toast.success(response.data.message || `Purged ${response.data.purged} orphan reports`);
      fetchQueue();
      fetchStats();
    } catch (error) {
      toast.error('Failed to purge orphan reports');
    } finally {
      setActionLoading(false);
    }
  };

  const handleBulkModerate = async (action) => {
    if (selectedItems.size === 0) return;
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/content-moderation/bulk-moderate`, {
        item_ids: Array.from(selectedItems),
        action
      });
      toast.success(`${selectedItems.size} items ${action}ed`);
      setSelectedItems(new Set());
      fetchQueue();
      fetchStats();
    } catch (error) {
      toast.error('Bulk moderation failed');
    } finally {
      setActionLoading(false);
    }
  };

  const toggleSelect = (id) => {
    setSelectedItems(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const getContentIcon = (type) => {
    switch (type) {
      case 'gallery_item': return <Image className="w-4 h-4 text-purple-400" />;
      case 'post': return <MessageSquare className="w-4 h-4 text-blue-400" />;
      case 'condition_report': return <Radio className="w-4 h-4 text-orange-400" />;
      default: return <Flag className="w-4 h-4 text-muted-foreground" />;
    }
  };

  const getReasonColor = (reason) => {
    switch (reason) {
      case 'spam': return 'bg-orange-500/20 text-orange-400';
      case 'harassment': return 'bg-red-500/20 text-red-400';
      case 'inappropriate': return 'bg-pink-500/20 text-pink-400';
      case 'copyright': return 'bg-purple-500/20 text-purple-400';
      case 'violence': return 'bg-red-500/20 text-red-400';
      default: return 'bg-gray-500/20 text-muted-foreground';
    }
  };

  return (
    <div className="space-y-4" data-testid="admin-content-mod-dashboard">
      {/* Stats Row */}
      {stats && (
        <div className="grid grid-cols-2 lg:grid-cols-5 gap-3">
          <Card className={`${cardBgClass} border-yellow-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Pending Review</p>
              <p className="text-2xl font-bold text-yellow-400">{stats.pending_count}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-green-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Approved (30d)</p>
              <p className="text-2xl font-bold text-green-400">{stats.approved_count}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-red-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Rejected (30d)</p>
              <p className="text-2xl font-bold text-red-400">{stats.rejected_count}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-cyan-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Approval Rate</p>
              <p className="text-2xl font-bold text-cyan-400">{stats.approval_rate}%</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-purple-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">AI Accuracy</p>
              <p className="text-2xl font-bold text-purple-400">{stats.ai_accuracy}%</p>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Filters & Bulk Actions */}
      <div className="flex flex-wrap gap-2 items-center justify-between">
        <div className="flex gap-2">
          <Select value={status} onValueChange={setStatus}>
            <SelectTrigger className="w-32 bg-muted border-border">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="pending">Pending</SelectItem>
              <SelectItem value="approved">Approved</SelectItem>
              <SelectItem value="rejected">Rejected</SelectItem>
            </SelectContent>
          </Select>
          <Select value={contentType} onValueChange={setContentType}>
            <SelectTrigger className="w-40 bg-muted border-border">
              <SelectValue placeholder="All Types" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Types</SelectItem>
              <SelectItem value="post">Posts</SelectItem>
              <SelectItem value="gallery_item">Gallery Items</SelectItem>
              <SelectItem value="condition_report">Condition Reports</SelectItem>
            </SelectContent>
          </Select>
          <Button size="sm" variant="outline" onClick={() => { fetchQueue(); fetchStats(); }}>
            <RefreshCw className="w-4 h-4" />
          </Button>
          <Button 
            size="sm" 
            variant="outline" 
            onClick={handlePurgeOrphans} 
            disabled={actionLoading}
            className="text-orange-400 border-orange-500/30 hover:bg-orange-500/10"
            data-testid="purge-orphans-btn"
          >
            <Trash2 className="w-4 h-4 mr-1" />
            Purge Ghost Reports
          </Button>
        </div>

        {selectedItems.size > 0 && (
          <div className="flex gap-2 items-center">
            <Badge className="bg-cyan-500/20 text-cyan-400">{selectedItems.size} selected</Badge>
            <Button size="sm" onClick={() => handleBulkModerate('approve')} disabled={actionLoading} className="bg-green-500 hover:bg-green-600">
              <Check className="w-4 h-4 mr-1" /> Approve All
            </Button>
            <Button size="sm" onClick={() => handleBulkModerate('reject')} disabled={actionLoading} className="bg-red-500 hover:bg-red-600">
              <Trash2 className="w-4 h-4 mr-1" /> Remove All
            </Button>
          </div>
        )}
      </div>

      {/* Queue */}
      <Card className={cardBgClass}>
        <CardHeader className="pb-2">
          <CardTitle className={`text-sm ${textClass}`}>
            Moderation Queue ({items.length})
          </CardTitle>
        </CardHeader>
        <CardContent className="max-h-[500px] overflow-y-auto">
          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
            </div>
          ) : items.length === 0 ? (
            <div className="text-center py-8">
              <Shield className="w-10 h-10 mx-auto text-gray-500 mb-2" />
              <p className="text-gray-500">No items in queue</p>
            </div>
          ) : (
            <div className="space-y-2">
              {items.map(item => (
                <div
                  key={item.id}
                  className={`p-3 rounded-lg border transition-all ${
                    selectedItems.has(item.id)
                      ? 'bg-cyan-500/10 border-cyan-500/50'
                      : 'bg-muted/50 border-transparent hover:bg-muted'
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <input
                      type="checkbox"
                      checked={selectedItems.has(item.id)}
                      onChange={() => toggleSelect(item.id)}
                      className="mt-1 rounded border-input"
                    />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        {getContentIcon(item.content_type)}
                        <span className="text-xs text-gray-500">{item.content_type?.replace('_', ' ')}</span>
                        <Badge className={`text-[10px] ${getReasonColor(item.flagged_by)}`}>
                          {item.flagged_by || 'flagged'}
                        </Badge>
                        <span className="text-xs text-gray-500">{item.flag_count || 1} flags</span>
                      </div>
                      <p className={`text-sm ${textClass} line-clamp-2`}>{item.content_preview}</p>
                      <p className="text-xs text-gray-500 mt-1">
                        By: {item.user_name || 'Unknown'} • {item.created_at ? new Date(item.created_at).toLocaleDateString() : ''}
                      </p>
                    </div>
                    <div className="flex gap-1">
                      <Button size="sm" variant="ghost" onClick={() => setSelectedItem(item)}>
                        <Eye className="w-4 h-4" />
                      </Button>
                      {status === 'pending' && (
                        <>
                          <Button size="sm" variant="ghost" onClick={() => handleModerate(item.id, 'approve')} className="text-green-400 hover:bg-green-500/20">
                            <Check className="w-4 h-4" />
                          </Button>
                          <Button size="sm" variant="ghost" onClick={() => handleModerate(item.id, 'reject')} className="text-red-400 hover:bg-red-500/20">
                            <X className="w-4 h-4" />
                          </Button>
                        </>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Detail Modal */}
      <Dialog open={!!selectedItem} onOpenChange={() => setSelectedItem(null)}>
        <DialogContent className="bg-card border-border text-foreground max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              {selectedItem && getContentIcon(selectedItem.content_type)}
              Review Content
            </DialogTitle>
          </DialogHeader>
          {selectedItem && (
            <div className="space-y-4">
              {/* Content Preview */}
              <div className="p-3 bg-muted rounded-lg">
                {selectedItem.content_url && (
                  <img src={getFullUrl(selectedItem.content_url)} alt="Content" className="w-full rounded mb-2 max-h-48 object-cover" />
                )}
                <p className="text-sm text-gray-300">{selectedItem.content_preview}</p>
              </div>

              {/* Metadata */}
              <div className="grid grid-cols-2 gap-2 text-xs">
                <div className="p-2 bg-muted/50 rounded">
                  <span className="text-gray-500">Author:</span>
                  <span className="text-foreground ml-1">{selectedItem.user_name || 'Unknown'}</span>
                </div>
                <div className="p-2 bg-muted/50 rounded">
                  <span className="text-gray-500">Flags:</span>
                  <span className="text-red-400 ml-1">{selectedItem.flag_count || 1}</span>
                </div>
                <div className="p-2 bg-muted/50 rounded">
                  <span className="text-gray-500">Source:</span>
                  <Badge className={`ml-1 text-[10px] ${getReasonColor(selectedItem.flagged_by)}`}>
                    {selectedItem.flagged_by || 'flagged'}
                  </Badge>
                </div>
                <div className="p-2 bg-muted/50 rounded">
                  <span className="text-gray-500">Created:</span>
                  <span className="text-foreground ml-1">{selectedItem.created_at ? new Date(selectedItem.created_at).toLocaleDateString() : ''}</span>
                </div>
              </div>

              {/* Moderation Note */}
              {status === 'pending' && (
                <div>
                  <label className="text-xs text-gray-500">Moderation Note (optional)</label>
                  <Textarea
                    value={moderationNote}
                    onChange={(e) => setModerationNote(e.target.value)}
                    placeholder="Add a note about this decision..."
                    className="bg-muted border-border mt-1"
                  />
                </div>
              )}
            </div>
          )}
          {status === 'pending' && selectedItem && (
            <DialogFooter className="gap-2">
              <Button variant="outline" onClick={() => setSelectedItem(null)}>Cancel</Button>
              <Button onClick={() => handleModerate(selectedItem.id, 'approve')} disabled={actionLoading} className="bg-green-500 hover:bg-green-600">
                <Check className="w-4 h-4 mr-1" /> Approve
              </Button>
              <Button onClick={() => handleModerate(selectedItem.id, 'reject')} disabled={actionLoading} className="bg-red-500 hover:bg-red-600">
                <Trash2 className="w-4 h-4 mr-1" /> Reject
              </Button>
            </DialogFooter>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AdminContentModDashboard;

﻿import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import {
  Loader2, RefreshCw, Check, X,
  Receipt, Wallet, TrendingDown, FileText
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';
import { Textarea } from '../ui/textarea';
import { toast } from 'sonner';
import logger from '../../utils/logger';


/**
 * Admin Finance Dashboard
 * - Refund processing
 * - Payout batch management
 * - Failed payment recovery
 * - Tax reporting
 */
export const AdminFinanceDashboard = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [activeTab, setActiveTab] = useState('refunds');
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState(null);
  
  // Refunds
  const [refunds, setRefunds] = useState([]);
  const [refundFilter, setRefundFilter] = useState('pending');
  const [selectedRefund, setSelectedRefund] = useState(null);
  const [rejectionReason, setRejectionReason] = useState('');
  const [showRejectDialog, setShowRejectDialog] = useState(false);
  
  // Payouts
  const [payoutBatches, setPayoutBatches] = useState([]);
  const [pendingPayouts, setPendingPayouts] = useState(null);
  
  // Failed Payments
  const [failedPayments, setFailedPayments] = useState([]);
  
  // Tax Report
  const [taxYear, setTaxYear] = useState(new Date().getFullYear());
  const [taxReport, setTaxReport] = useState(null);

  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';
  const _textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  useEffect(() => {
    if (user?.id) {
      fetchStats();
      fetchDataForTab();
    }
  }, [user?.id, activeTab, refundFilter, taxYear]);

  const fetchStats = async () => {
    try {
      const response = await apiClient.get(`/admin/finance/stats?days=30`);
      setStats(response.data);
    } catch (error) {
      logger.error('Failed to load stats:', error);
    }
  };

  const fetchDataForTab = async () => {
    setLoading(true);
    try {
      if (activeTab === 'refunds') {
        const response = await apiClient.get(`/admin/finance/refunds?status=${refundFilter}&limit=50`);
        setRefunds(response.data.refunds || []);
      } else if (activeTab === 'payouts') {
        const [batchesRes, pendingRes] = await Promise.all([
          apiClient.get(`/admin/finance/payouts?limit=20`),
          apiClient.get(`/admin/finance/payouts/pending`)
        ]);
        setPayoutBatches(batchesRes.data.batches || []);
        setPendingPayouts(pendingRes.data);
      } else if (activeTab === 'failed') {
        const response = await apiClient.get(`/admin/finance/failed-payments?limit=50`);
        setFailedPayments(response.data.failed_payments || []);
      } else if (activeTab === 'tax') {
        const response = await apiClient.get(`/admin/finance/tax-report?year=${taxYear}`);
        setTaxReport(response.data);
      }
    } catch (error) {
      logger.error('Failed to load data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleProcessRefund = async (refundId, action) => {
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/finance/refunds/${refundId}/process`, {
        action,
        rejection_reason: action === 'reject' ? rejectionReason : null
      });
      toast.success(`Refund ${action}d`);
      setShowRejectDialog(false);
      setRejectionReason('');
      setSelectedRefund(null);
      fetchDataForTab();
      fetchStats();
    } catch (error) {
      toast.error(`Failed to ${action} refund`);
    } finally {
      setActionLoading(false);
    }
  };

  const handleCreatePayoutBatch = async () => {
    setActionLoading(true);
    try {
      const response = await apiClient.post(`/admin/finance/payouts/create-batch`, {});
      toast.success(`Batch ${response.data.batch_number} created`);
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to create batch');
    } finally {
      setActionLoading(false);
    }
  };

  const handleProcessBatch = async (batchId) => {
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/finance/payouts/${batchId}/process`);
      toast.success('Batch processed');
      fetchDataForTab();
    } catch (error) {
      toast.error('Failed to process batch');
    } finally {
      setActionLoading(false);
    }
  };

  const handleRetryPayment = async (paymentId) => {
    setActionLoading(true);
    try {
      const response = await apiClient.post(`/admin/finance/failed-payments/${paymentId}/retry`);
      toast.success(response.data.recovered ? 'Payment recovered!' : 'Retry failed');
      fetchDataForTab();
      fetchStats();
    } catch (error) {
      toast.error('Failed to retry payment');
    } finally {
      setActionLoading(false);
    }
  };

  const formatCurrency = (amount) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount || 0);
  const formatDate = (dateStr) => dateStr ? new Date(dateStr).toLocaleDateString() : '-';

  return (
    <div className="space-y-4" data-testid="admin-finance-dashboard">
      {/* Stats Row */}
      {stats && (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
          <Card className={`${cardBgClass} border-yellow-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Pending Refunds</p>
              <p className="text-xl font-bold text-yellow-400">{stats.pending_refunds.count}</p>
              <p className="text-xs text-gray-500">{formatCurrency(stats.pending_refunds.amount)}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-green-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Processed (30d)</p>
              <p className="text-xl font-bold text-green-400">{stats.processed_refunds.count}</p>
              <p className="text-xs text-gray-500">{formatCurrency(stats.processed_refunds.amount)}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-red-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Failed Payments</p>
              <p className="text-xl font-bold text-red-400">{stats.failed_payments.count}</p>
              <p className="text-xs text-gray-500">{formatCurrency(stats.failed_payments.amount)}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-cyan-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Recovery Rate</p>
              <p className="text-xl font-bold text-cyan-400">{stats.recovery_rate}%</p>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Tab Navigation */}
      <div className="flex gap-2">
        {[
          { id: 'refunds', label: 'Refunds', icon: Receipt },
          { id: 'payouts', label: 'Payouts', icon: Wallet },
          { id: 'failed', label: 'Failed Payments', icon: TrendingDown },
          { id: 'tax', label: 'Tax Report', icon: FileText }
        ].map(tab => (
          <Button
            key={tab.id}
            variant={activeTab === tab.id ? 'default' : 'outline'}
            size="sm"
            onClick={() => setActiveTab(tab.id)}
            className={activeTab === tab.id ? 'bg-cyan-500 hover:bg-cyan-600' : ''}
          >
            <tab.icon className="w-4 h-4 mr-1" />
            {tab.label}
          </Button>
        ))}
      </div>

      {loading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
        </div>
      ) : (
        <>
          {/* REFUNDS TAB */}
          {activeTab === 'refunds' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>Refund Requests</CardTitle>
                <Select value={refundFilter} onValueChange={setRefundFilter}>
                  <SelectTrigger className="w-32 h-8 text-xs bg-muted border-border">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="pending">Pending</SelectItem>
                    <SelectItem value="completed">Completed</SelectItem>
                    <SelectItem value="rejected">Rejected</SelectItem>
                  </SelectContent>
                </Select>
              </CardHeader>
              <CardContent>
                {refunds.length === 0 ? (
                  <p className="text-center text-gray-500 py-8">No refund requests</p>
                ) : (
                  <div className="space-y-2">
                    {refunds.map(refund => (
                      <div key={refund.id} className="p-3 bg-muted/50 rounded-lg">
                        <div className="flex items-start justify-between">
                          <div>
                            <p className={`font-medium ${textClass}`}>{refund.user_name}</p>
                            <p className="text-xs text-gray-500">{refund.user_email}</p>
                            <p className="text-sm text-muted-foreground mt-1">{refund.reason}</p>
                            {refund.reason_category && (
                              <Badge variant="outline" className="text-xs mt-1">{refund.reason_category}</Badge>
                            )}
                          </div>
                          <div className="text-right">
                            <p className="text-lg font-bold text-foreground">{formatCurrency(refund.amount)}</p>
                            <Badge className={`text-xs ${
                              refund.status === 'pending' ? 'bg-yellow-500/20 text-yellow-400' :
                              refund.status === 'completed' ? 'bg-green-500/20 text-green-400' :
                              'bg-red-500/20 text-red-400'
                            }`}>{refund.status}</Badge>
                          </div>
                        </div>
                        {refund.status === 'pending' && (
                          <div className="flex gap-2 mt-3 pt-3 border-t border-border">
                            <Button 
                              size="sm" 
                              onClick={() => handleProcessRefund(refund.id, 'approve')}
                              disabled={actionLoading}
                              className="bg-green-500 hover:bg-green-600"
                            >
                              <Check className="w-4 h-4 mr-1" /> Approve
                            </Button>
                            <Button 
                              size="sm" 
                              variant="outline"
                              onClick={() => { setSelectedRefund(refund); setShowRejectDialog(true); }}
                            >
                              <X className="w-4 h-4 mr-1" /> Reject
                            </Button>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* PAYOUTS TAB */}
          {activeTab === 'payouts' && (
            <div className="space-y-4">
              {pendingPayouts && (
                <Card className={`${cardBgClass} border-green-500/30`}>
                  <CardHeader className="pb-2 flex flex-row items-center justify-between">
                    <CardTitle className={`text-sm ${textClass}`}>Pending Payouts</CardTitle>
                    <Button size="sm" onClick={handleCreatePayoutBatch} disabled={actionLoading} className="bg-green-500 hover:bg-green-600">
                      Create Batch
                    </Button>
                  </CardHeader>
                  <CardContent>
                    <div className="flex items-center justify-between p-3 bg-muted/50 rounded-lg">
                      <div>
                        <p className={`text-lg font-bold ${textClass}`}>{formatCurrency(pendingPayouts.total_pending_amount)}</p>
                        <p className="text-xs text-gray-500">{pendingPayouts.total_recipients} recipients</p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              )}

              <Card className={cardBgClass}>
                <CardHeader className="pb-2">
                  <CardTitle className={`text-sm ${textClass}`}>Payout Batches</CardTitle>
                </CardHeader>
                <CardContent>
                  {payoutBatches.length === 0 ? (
                    <p className="text-center text-gray-500 py-8">No payout batches</p>
                  ) : (
                    <div className="space-y-2">
                      {payoutBatches.map(batch => (
                        <div key={batch.id} className="p-3 bg-muted/50 rounded-lg flex items-center justify-between">
                          <div>
                            <p className={`font-medium ${textClass}`}>{batch.batch_number}</p>
                            <p className="text-xs text-gray-500">{batch.total_recipients} recipients • {formatDate(batch.created_at)}</p>
                          </div>
                          <div className="flex items-center gap-3">
                            <p className="text-lg font-bold text-foreground">{formatCurrency(batch.total_amount)}</p>
                            <Badge className={`text-xs ${
                              batch.status === 'completed' ? 'bg-green-500/20 text-green-400' :
                              batch.status === 'pending' ? 'bg-yellow-500/20 text-yellow-400' :
                              'bg-gray-500/20 text-muted-foreground'
                            }`}>{batch.status}</Badge>
                            {batch.status === 'pending' && (
                              <Button size="sm" onClick={() => handleProcessBatch(batch.id)} disabled={actionLoading}>
                                Process
                              </Button>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          )}

          {/* FAILED PAYMENTS TAB */}
          {activeTab === 'failed' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2">
                <CardTitle className={`text-sm ${textClass}`}>Failed Payments</CardTitle>
              </CardHeader>
              <CardContent>
                {failedPayments.length === 0 ? (
                  <p className="text-center text-gray-500 py-8">No failed payments</p>
                ) : (
                  <div className="space-y-2">
                    {failedPayments.map(payment => (
                      <div key={payment.id} className="p-3 bg-muted/50 rounded-lg">
                        <div className="flex items-start justify-between">
                          <div>
                            <p className={`font-medium ${textClass}`}>{payment.user_name}</p>
                            <p className="text-xs text-gray-500">{payment.user_email}</p>
                            <p className="text-xs text-red-400 mt-1">{payment.failure_message}</p>
                            <Badge variant="outline" className="text-xs mt-1">{payment.payment_type}</Badge>
                          </div>
                          <div className="text-right">
                            <p className="text-lg font-bold text-foreground">{formatCurrency(payment.amount)}</p>
                            <p className="text-xs text-gray-500">{payment.recovery_attempts} attempts</p>
                          </div>
                        </div>
                        {!payment.recovered && (
                          <div className="mt-3 pt-3 border-t border-border">
                            <Button 
                              size="sm" 
                              onClick={() => handleRetryPayment(payment.id)}
                              disabled={actionLoading}
                            >
                              <RefreshCw className="w-4 h-4 mr-1" /> Retry Payment
                            </Button>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* TAX REPORT TAB */}
          {activeTab === 'tax' && (
            <Card className={cardBgClass}>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className={`text-sm ${textClass}`}>Tax Report (1099 Recipients)</CardTitle>
                <Select value={taxYear.toString()} onValueChange={(v) => setTaxYear(parseInt(v))}>
                  <SelectTrigger className="w-24 h-8 text-xs bg-muted border-border">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="2026">2026</SelectItem>
                    <SelectItem value="2025">2025</SelectItem>
                    <SelectItem value="2024">2024</SelectItem>
                  </SelectContent>
                </Select>
              </CardHeader>
              <CardContent>
                {taxReport && (
                  <>
                    <div className="p-3 bg-muted/50 rounded-lg mb-4">
                      <p className="text-xs text-gray-500">Earnings ≥ ${taxReport.threshold} threshold</p>
                      <p className={`text-lg font-bold ${textClass}`}>{taxReport.total_recipients} recipients</p>
                      <p className="text-sm text-muted-foreground">{formatCurrency(taxReport.total_reportable_amount)} total</p>
                    </div>
                    {taxReport.recipients.length === 0 ? (
                      <p className="text-center text-gray-500 py-4">No recipients above threshold</p>
                    ) : (
                      <div className="space-y-2">
                        {taxReport.recipients.map(r => (
                          <div key={r.user_id} className="p-2 bg-muted/30 rounded flex items-center justify-between">
                            <div>
                              <p className={`text-sm font-medium ${textClass}`}>{r.name}</p>
                              <p className="text-xs text-gray-500">{r.email}</p>
                            </div>
                            <p className="text-sm font-bold text-green-400">{formatCurrency(r.total_earnings)}</p>
                          </div>
                        ))}
                      </div>
                    )}
                  </>
                )}
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* Reject Dialog */}
      <Dialog open={showRejectDialog} onOpenChange={setShowRejectDialog}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Reject Refund</DialogTitle>
          </DialogHeader>
          <div>
            <p className="text-sm text-muted-foreground mb-2">Reason for rejection:</p>
            <Textarea
              value={rejectionReason}
              onChange={(e) => setRejectionReason(e.target.value)}
              placeholder="Explain why this refund is being rejected..."
              className="bg-muted border-border"
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowRejectDialog(false)}>Cancel</Button>
            <Button 
              onClick={() => handleProcessRefund(selectedRefund?.id, 'reject')}
              disabled={actionLoading || !rejectionReason.trim()}
              className="bg-red-500 hover:bg-red-600"
            >
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Reject Refund'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AdminFinanceDashboard;

import React, { useState, useEffect } from 'react';

import { useAuth } from '../../contexts/AuthContext';

import { useTheme } from '../../contexts/ThemeContext';

import apiClient from '../../lib/apiClient';

import { MessageSquare, FileText,

  Loader2, RefreshCw, Flag, Scale, Wallet,
  Send
} from 'lucide-react';
import { Card, CardContent } from '../ui/card';

import { Button } from '../ui/button';

import { Input } from '../ui/input';

import { Textarea } from '../ui/textarea';

import { Badge } from '../ui/badge';

import { Avatar, AvatarFallback, AvatarImage } from '../ui/avatar';

import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';

import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';

import { toast } from 'sonner';
import { getFullUrl } from '../../utils/media';



// Status badge component
const StatusBadge = ({ status }) => {
  const statusStyles = {
    // Disputes
    open: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    under_review: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    awaiting_response: 'bg-orange-500/20 text-orange-400 border-orange-500/30',
    resolved_refund: 'bg-green-500/20 text-green-400 border-green-500/30',
    resolved_no_action: 'bg-gray-500/20 text-muted-foreground border-gray-500/30',
    resolved_partial: 'bg-teal-500/20 text-teal-400 border-teal-500/30',
    escalated: 'bg-red-500/20 text-red-400 border-red-500/30',
    closed: 'bg-zinc-500/20 text-zinc-400 border-zinc-500/30',
    // Reports
    pending: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    action_taken: 'bg-green-500/20 text-green-400 border-green-500/30',
    no_violation: 'bg-gray-500/20 text-muted-foreground border-gray-500/30',
    dismissed: 'bg-zinc-500/20 text-zinc-400 border-zinc-500/30',
  };

  return (
    <Badge className={`text-xs ${statusStyles[status] || 'bg-zinc-500/20 text-zinc-400'}`}>
      {status?.replace(/_/g, ' ')}
    </Badge>
  );
};

// Priority badge
const PriorityBadge = ({ priority }) => {
  const styles = {
    low: 'bg-gray-500/20 text-muted-foreground',
    normal: 'bg-blue-500/20 text-blue-400',
    high: 'bg-orange-500/20 text-orange-400',
    urgent: 'bg-red-500/20 text-red-400 animate-pulse',
  };
  return <Badge className={`text-xs ${styles[priority] || styles.normal}`}>{priority}</Badge>;
};

export const AdminModerationDashboard = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [activeSubTab, setActiveSubTab] = useState('disputes');
  const [loading, setLoading] = useState(true);
  
  // Disputes state
  const [disputes, setDisputes] = useState([]);
  const [disputesTotal, setDisputesTotal] = useState(0);
  const [selectedDispute, setSelectedDispute] = useState(null);
  const [showDisputeDetail, setShowDisputeDetail] = useState(false);
  const [disputeFilter, setDisputeFilter] = useState({ status: '', type: '' });
  
  // Reports state
  const [reports, setReports] = useState([]);
  const [pendingReportsCount, setPendingReportsCount] = useState(0);
  const [selectedReport, setSelectedReport] = useState(null);
  const [showReportReview, setShowReportReview] = useState(false);
  const [reportFilter, setReportFilter] = useState({ status: '', reason: '' });
  
  // Payout Holds state
  const [payoutHolds, setPayoutHolds] = useState([]);
  const [totalHeldAmount, setTotalHeldAmount] = useState(0);
  const [_showCreateHold, setShowCreateHold] = useState(false);
  
  // Audit Logs state
  const [auditLogs, setAuditLogs] = useState([]);
  const [auditFilter, setAuditFilter] = useState({ category: '' });
  
  // Form states
  const [newMessage, setNewMessage] = useState('');
  const [reviewAction, setReviewAction] = useState('');
  const [adminNotes, setAdminNotes] = useState('');
  const [refundAmount, setRefundAmount] = useState('');
  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  // Fetch data based on active tab
  useEffect(() => {
    if (user?.id) {
      if (activeSubTab === 'disputes') fetchDisputes();
      else if (activeSubTab === 'reports') fetchReports();
      else if (activeSubTab === 'holds') fetchPayoutHolds();
      else if (activeSubTab === 'audit') fetchAuditLogs();
    }
  }, [user?.id, activeSubTab, disputeFilter, reportFilter, auditFilter]);

  const fetchDisputes = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (disputeFilter.status) params.append('status', disputeFilter.status);
      if (disputeFilter.type) params.append('dispute_type', disputeFilter.type);
      
      const response = await apiClient.get(`/admin/disputes?${params}`);
      setDisputes(response.data.disputes || []);
      setDisputesTotal(response.data.total || 0);
    } catch (error) {
      toast.error('Failed to load disputes');
    } finally {
      setLoading(false);
    }
  };

  const fetchReports = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (reportFilter.status) params.append('status', reportFilter.status);
      if (reportFilter.reason) params.append('reason', reportFilter.reason);
      
      const response = await apiClient.get(`/admin/reports?${params}`);
      setReports(response.data.reports || []);
      setPendingReportsCount(response.data.pending_count || 0);
    } catch (error) {
      toast.error('Failed to load reports');
    } finally {
      setLoading(false);
    }
  };

  const fetchPayoutHolds = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/admin/payout-holds`);
      setPayoutHolds(response.data.holds || []);
      setTotalHeldAmount(response.data.total_held_amount || 0);
    } catch (error) {
      toast.error('Failed to load payout holds');
    } finally {
      setLoading(false);
    }
  };

  const fetchAuditLogs = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({ limit: '100' });
      if (auditFilter.category) params.append('category', auditFilter.category);
      
      const response = await apiClient.get(`/admin/audit-logs?${params}`);
      setAuditLogs(response.data.logs || []);
    } catch (error) {
      toast.error('Failed to load audit logs');
    } finally {
      setLoading(false);
    }
  };

  const fetchDisputeDetail = async (disputeId) => {
    try {
      const response = await apiClient.get(`/admin/disputes/${disputeId}`);
      setSelectedDispute(response.data);
      setShowDisputeDetail(true);
    } catch (error) {
      toast.error('Failed to load dispute details');
    }
  };

  const handleUpdateDispute = async (disputeId, updates) => {
    setActionLoading(true);
    try {
      await apiClient.put(`/admin/disputes/${disputeId}`, updates);
      toast.success('Dispute updated');
      fetchDisputes();
      if (selectedDispute?.id === disputeId) {
        fetchDisputeDetail(disputeId);
      }
    } catch (error) {
      toast.error('Failed to update dispute');
    } finally {
      setActionLoading(false);
    }
  };

  const handleAddDisputeMessage = async (disputeId) => {
    if (!newMessage.trim()) return;
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/disputes/${disputeId}/messages`, {
        message: newMessage,
        is_internal: false
      });
      toast.success('Message sent');
      setNewMessage('');
      fetchDisputeDetail(disputeId);
    } catch (error) {
      toast.error('Failed to send message');
    } finally {
      setActionLoading(false);
    }
  };

  const handleReviewReport = async (reportId) => {
    if (!reviewAction) {
      toast.error('Please select an action');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.put(`/admin/reports/${reportId}/review`, {
        action_taken: reviewAction,
        admin_notes: adminNotes,
        escalate_to_dispute: reviewAction === 'escalate'
      });
      toast.success('Report reviewed');
      setShowReportReview(false);
      setReviewAction('');
      setAdminNotes('');
      fetchReports();
    } catch (error) {
      toast.error('Failed to review report');
    } finally {
      setActionLoading(false);
    }
  };

  const handleReleaseHold = async (holdId) => {
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/payout-holds/${holdId}/release`, {
        release_notes: 'Admin released hold'
      });
      toast.success('Hold released');
      fetchPayoutHolds();
    } catch (error) {
      toast.error('Failed to release hold');
    } finally {
      setActionLoading(false);
    }
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="space-y-4" data-testid="admin-moderation-dashboard">
      {/* Sub-tabs */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {[
          { id: 'disputes', label: 'Disputes', icon: Scale, count: disputesTotal },
          { id: 'reports', label: 'Reports', icon: Flag, count: pendingReportsCount },
          { id: 'holds', label: 'Payout Holds', icon: Wallet, count: payoutHolds.filter(h => h.is_active).length },
          { id: 'audit', label: 'Audit Logs', icon: FileText },
        ].map(tab => (
          <Button
            key={tab.id}
            variant={activeSubTab === tab.id ? 'default' : 'outline'}
            size="sm"
            onClick={() => setActiveSubTab(tab.id)}
            className={activeSubTab === tab.id ? 'bg-red-500 hover:bg-red-600' : ''}
            data-testid={`moderation-tab-${tab.id}`}
          >
            <tab.icon className="w-4 h-4 mr-1.5" />
            {tab.label}
            {tab.count > 0 && (
              <Badge className="ml-1.5 bg-white/20 text-foreground">{tab.count}</Badge>
            )}
          </Button>
        ))}
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
        </div>
      ) : (
        <>
          {/* DISPUTES TAB */}
          {activeSubTab === 'disputes' && (
            <div className="space-y-3">
              {/* Filters */}
              <div className="flex gap-2 flex-wrap">
                <Select value={disputeFilter.status || "all"} onValueChange={(v) => setDisputeFilter(f => ({ ...f, status: v === "all" ? "" : v }))}>
                  <SelectTrigger className="w-40 bg-muted border-border">
                    <SelectValue placeholder="Status" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Status</SelectItem>
                    <SelectItem value="open">Open</SelectItem>
                    <SelectItem value="under_review">Under Review</SelectItem>
                    <SelectItem value="escalated">Escalated</SelectItem>
                    <SelectItem value="resolved_refund">Resolved (Refund)</SelectItem>
                    <SelectItem value="closed">Closed</SelectItem>
                  </SelectContent>
                </Select>
                <Select value={disputeFilter.type || "all"} onValueChange={(v) => setDisputeFilter(f => ({ ...f, type: v === "all" ? "" : v }))}>
                  <SelectTrigger className="w-40 bg-muted border-border">
                    <SelectValue placeholder="Type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Types</SelectItem>
                    <SelectItem value="payment">Payment</SelectItem>
                    <SelectItem value="service_quality">Service Quality</SelectItem>
                    <SelectItem value="no_show">No Show</SelectItem>
                    <SelectItem value="harassment">Harassment</SelectItem>
                    <SelectItem value="fraud">Fraud</SelectItem>
                  </SelectContent>
                </Select>
                <Button variant="outline" size="sm" onClick={fetchDisputes}>
                  <RefreshCw className="w-4 h-4" />
                </Button>
              </div>

              {/* Disputes List */}
              {disputes.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <Scale className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No disputes found</p>
                  </CardContent>
                </Card>
              ) : (
                disputes.map(dispute => (
                  <Card 
                    key={dispute.id} 
                    className={`${cardBgClass} cursor-pointer hover:border-input transition-colors`}
                    onClick={() => fetchDisputeDetail(dispute.id)}
                  >
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <StatusBadge status={dispute.status} />
                            <PriorityBadge priority={dispute.priority} />
                            <Badge variant="outline" className="text-xs">
                              {dispute.dispute_type?.replace(/_/g, ' ')}
                            </Badge>
                          </div>
                          <h4 className={`font-medium ${textClass} truncate`}>{dispute.subject}</h4>
                          <p className={`text-sm ${textSecondary} line-clamp-2 mt-1`}>{dispute.description}</p>
                          
                          <div className="flex items-center gap-4 mt-3 text-xs">
                            <div className="flex items-center gap-1.5">
                              <Avatar className="w-5 h-5">
                                <AvatarImage src={getFullUrl(dispute.complainant?.avatar_url)} />
                                <AvatarFallback className="text-xs">{dispute.complainant?.full_name?.[0]}</AvatarFallback>
                              </Avatar>
                              <span className={textSecondary}>{dispute.complainant?.full_name}</span>
                              <span className="text-gray-600">vs</span>
                              <Avatar className="w-5 h-5">
                                <AvatarImage src={getFullUrl(dispute.respondent?.avatar_url)} />
                                <AvatarFallback className="text-xs">{dispute.respondent?.full_name?.[0]}</AvatarFallback>
                              </Avatar>
                              <span className={textSecondary}>{dispute.respondent?.full_name}</span>
                            </div>
                          </div>
                        </div>
                        
                        <div className="text-right shrink-0">
                          {dispute.amount_disputed && (
                            <p className="text-lg font-bold text-red-400">${dispute.amount_disputed}</p>
                          )}
                          <p className={`text-xs ${textSecondary}`}>{formatDate(dispute.created_at)}</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          )}

          {/* REPORTS TAB */}
          {activeSubTab === 'reports' && (
            <div className="space-y-3">
              {/* Filters */}
              <div className="flex gap-2 flex-wrap">
                <Select value={reportFilter.status || "all"} onValueChange={(v) => setReportFilter(f => ({ ...f, status: v === "all" ? "" : v }))}>
                  <SelectTrigger className="w-40 bg-muted border-border">
                    <SelectValue placeholder="Status" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Status</SelectItem>
                    <SelectItem value="pending">Pending</SelectItem>
                    <SelectItem value="under_review">Under Review</SelectItem>
                    <SelectItem value="action_taken">Action Taken</SelectItem>
                    <SelectItem value="no_violation">No Violation</SelectItem>
                  </SelectContent>
                </Select>
                <Select value={reportFilter.reason || "all"} onValueChange={(v) => setReportFilter(f => ({ ...f, reason: v === "all" ? "" : v }))}>
                  <SelectTrigger className="w-40 bg-muted border-border">
                    <SelectValue placeholder="Reason" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Reasons</SelectItem>
                    <SelectItem value="spam">Spam</SelectItem>
                    <SelectItem value="inappropriate_content">Inappropriate</SelectItem>
                    <SelectItem value="harassment">Harassment</SelectItem>
                    <SelectItem value="fraud">Fraud</SelectItem>
                    <SelectItem value="fake_profile">Fake Profile</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Reports List */}
              {reports.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <Flag className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No reports found</p>
                  </CardContent>
                </Card>
              ) : (
                reports.map(report => (
                  <Card key={report.id} className={`${cardBgClass}`}>
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <StatusBadge status={report.status} />
                            <PriorityBadge priority={report.priority} />
                            <Badge variant="outline" className="text-xs capitalize">
                              {report.report_type}
                            </Badge>
                          </div>
                          
                          <div className="flex items-center gap-2 mb-2">
                            <span className={`text-sm ${textSecondary}`}>Reason:</span>
                            <Badge className="bg-red-500/20 text-red-400 border-red-500/30 capitalize">
                              {report.reason?.replace(/_/g, ' ')}
                            </Badge>
                          </div>
                          
                          {report.description && (
                            <p className={`text-sm ${textSecondary} line-clamp-2`}>{report.description}</p>
                          )}
                          
                          <div className="flex items-center gap-4 mt-3 text-xs">
                            <div className="flex items-center gap-1.5">
                              <span className="text-gray-500">Reporter:</span>
                              <Avatar className="w-5 h-5">
                                <AvatarImage src={getFullUrl(report.reporter?.avatar_url)} />
                                <AvatarFallback>{report.reporter?.full_name?.[0]}</AvatarFallback>
                              </Avatar>
                              <span className={textSecondary}>{report.reporter?.full_name}</span>
                            </div>
                            {report.reported_user && (
                              <div className="flex items-center gap-1.5">
                                <span className="text-gray-500">Reported:</span>
                                <Avatar className="w-5 h-5">
                                  <AvatarImage src={getFullUrl(report.reported_user?.avatar_url)} />
                                  <AvatarFallback>{report.reported_user?.full_name?.[0]}</AvatarFallback>
                                </Avatar>
                                <span className={textSecondary}>{report.reported_user?.full_name}</span>
                              </div>
                            )}
                          </div>
                        </div>
                        
                        <div className="shrink-0 flex flex-col gap-2 items-end">
                          <p className={`text-xs ${textSecondary}`}>{formatDate(report.created_at)}</p>
                          {report.status === 'pending' && (
                            <Button
                              size="sm"
                              onClick={(e) => {
                                e.stopPropagation();
                                setSelectedReport(report);
                                setShowReportReview(true);
                              }}
                              className="bg-blue-500 hover:bg-blue-600"
                            >
                              Review
                            </Button>
                          )}
                          {report.action_taken && (
                            <Badge className="bg-green-500/20 text-green-400 text-xs capitalize">
                              {report.action_taken?.replace(/_/g, ' ')}
                            </Badge>
                          )}
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          )}

          {/* PAYOUT HOLDS TAB */}
          {activeSubTab === 'holds' && (
            <div className="space-y-3">
              {/* Summary Card */}
              <Card className={`${cardBgClass} border-orange-500/30`}>
                <CardContent className="p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-orange-500/20 rounded-lg">
                        <Wallet className="w-6 h-6 text-orange-400" />
                      </div>
                      <div>
                        <p className={textSecondary}>Total Amount Held</p>
                        <p className="text-2xl font-bold text-orange-400">${totalHeldAmount.toFixed(2)}</p>
                      </div>
                    </div>
                    <Button size="sm" onClick={() => setShowCreateHold(true)} className="bg-orange-500 hover:bg-orange-600">
                      Create Hold
                    </Button>
                  </div>
                </CardContent>
              </Card>

              {/* Holds List */}
              {payoutHolds.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <Wallet className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No active payout holds</p>
                  </CardContent>
                </Card>
              ) : (
                payoutHolds.map(hold => (
                  <Card key={hold.id} className={`${cardBgClass} ${hold.is_active ? 'border-orange-500/30' : ''}`}>
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex items-center gap-3">
                          <Avatar>
                            <AvatarImage src={getFullUrl(hold.photographer?.avatar_url)} />
                            <AvatarFallback>{hold.photographer?.full_name?.[0]}</AvatarFallback>
                          </Avatar>
                          <div>
                            <p className={`font-medium ${textClass}`}>{hold.photographer?.full_name}</p>
                            <p className={`text-sm ${textSecondary}`}>{hold.photographer?.email}</p>
                            <div className="flex items-center gap-2 mt-1">
                              <Badge 
                                className={hold.is_active ? 'bg-orange-500/20 text-orange-400' : 'bg-gray-500/20 text-muted-foreground'}
                              >
                                {hold.is_active ? 'Active' : 'Released'}
                              </Badge>
                              <Badge variant="outline" className="capitalize text-xs">
                                {hold.reason?.replace(/_/g, ' ')}
                              </Badge>
                            </div>
                          </div>
                        </div>
                        
                        <div className="text-right">
                          <p className="text-xl font-bold text-orange-400">${hold.amount}</p>
                          <p className={`text-xs ${textSecondary}`}>{formatDate(hold.created_at)}</p>
                          {hold.is_active && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => handleReleaseHold(hold.id)}
                              disabled={actionLoading}
                              className="mt-2 border-green-500 text-green-400 hover:bg-green-500/10"
                            >
                              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Release'}
                            </Button>
                          )}
                        </div>
                      </div>
                      {hold.description && (
                        <p className={`text-sm ${textSecondary} mt-2 pl-12`}>{hold.description}</p>
                      )}
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          )}

          {/* AUDIT LOGS TAB */}
          {activeSubTab === 'audit' && (
            <div className="space-y-3">
              {/* Filters */}
              <div className="flex gap-2">
                <Select value={auditFilter.category || "all"} onValueChange={(v) => setAuditFilter(f => ({ ...f, category: v === "all" ? "" : v }))}>
                  <SelectTrigger className="w-40 bg-muted border-border">
                    <SelectValue placeholder="Category" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Categories</SelectItem>
                    <SelectItem value="auth">Auth</SelectItem>
                    <SelectItem value="user_mgmt">User Management</SelectItem>
                    <SelectItem value="financial">Financial</SelectItem>
                    <SelectItem value="content">Content</SelectItem>
                    <SelectItem value="dispute">Dispute</SelectItem>
                    <SelectItem value="report">Report</SelectItem>
                    <SelectItem value="admin">Admin</SelectItem>
                  </SelectContent>
                </Select>
                <Button variant="outline" size="sm" onClick={fetchAuditLogs}>
                  <RefreshCw className="w-4 h-4" />
                </Button>
              </div>

              {/* Logs List */}
              {auditLogs.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <FileText className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No audit logs found</p>
                  </CardContent>
                </Card>
              ) : (
                <Card className={cardBgClass}>
                  <CardContent className="p-0">
                    <div className="divide-y divide-zinc-800">
                      {auditLogs.map(log => (
                        <div key={log.id} className="p-3 hover:bg-muted/50 transition-colors">
                          <div className="flex items-start justify-between gap-4">
                            <div className="flex-1">
                              <div className="flex items-center gap-2 mb-1">
                                <Badge 
                                  className={`text-xs ${
                                    log.is_admin_action ? 'bg-red-500/20 text-red-400' : 
                                    log.is_system_action ? 'bg-blue-500/20 text-blue-400' : 
                                    'bg-gray-500/20 text-muted-foreground'
                                  }`}
                                >
                                  {log.is_admin_action ? 'Admin' : log.is_system_action ? 'System' : 'User'}
                                </Badge>
                                <Badge variant="outline" className="text-xs capitalize">
                                  {log.category}
                                </Badge>
                              </div>
                              <p className={`font-medium ${textClass}`}>{log.action?.replace(/_/g, ' ')}</p>
                              {log.description && (
                                <p className={`text-sm ${textSecondary}`}>{log.description}</p>
                              )}
                              <div className="flex items-center gap-2 mt-1 text-xs text-gray-500">
                                {log.actor && (
                                  <span>By: {log.actor?.full_name || log.actor_email}</span>
                                )}
                                {log.target_email && (
                                  <span>• Target: {log.target_email}</span>
                                )}
                              </div>
                            </div>
                            <p className={`text-xs ${textSecondary} shrink-0`}>{formatDate(log.created_at)}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>
          )}
        </>
      )}

      {/* Dispute Detail Modal */}
      <Dialog open={showDisputeDetail} onOpenChange={setShowDisputeDetail}>
        <DialogContent className="bg-card border-border text-foreground max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Scale className="w-5 h-5 text-red-400" />
              Dispute Details
            </DialogTitle>
          </DialogHeader>
          
          {selectedDispute && (
            <div className="space-y-4">
              {/* Status & Actions */}
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <StatusBadge status={selectedDispute.status} />
                  <PriorityBadge priority={selectedDispute.priority} />
                </div>
                <div className="flex gap-2">
                  <Select
                    value={selectedDispute.status}
                    onValueChange={(v) => handleUpdateDispute(selectedDispute.id, { status: v })}
                  >
                    <SelectTrigger className="w-40 bg-muted border-border">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="open">Open</SelectItem>
                      <SelectItem value="under_review">Under Review</SelectItem>
                      <SelectItem value="awaiting_response">Awaiting Response</SelectItem>
                      <SelectItem value="escalated">Escalate</SelectItem>
                      <SelectItem value="resolved_refund">Resolve (Refund)</SelectItem>
                      <SelectItem value="resolved_no_action">Resolve (No Action)</SelectItem>
                      <SelectItem value="closed">Close</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              {/* Subject & Description */}
              <div>
                <h3 className="font-semibold text-lg">{selectedDispute.subject}</h3>
                <p className="text-muted-foreground mt-1">{selectedDispute.description}</p>
              </div>

              {/* Parties */}
              <div className="grid grid-cols-2 gap-4">
                <div className="p-3 bg-muted rounded-lg">
                  <p className="text-xs text-gray-500 mb-2">Complainant</p>
                  <div className="flex items-center gap-2">
                    <Avatar>
                      <AvatarImage src={getFullUrl(selectedDispute.complainant?.avatar_url)} />
                      <AvatarFallback>{selectedDispute.complainant?.full_name?.[0]}</AvatarFallback>
                    </Avatar>
                    <div>
                      <p className="font-medium">{selectedDispute.complainant?.full_name}</p>
                      <p className="text-xs text-muted-foreground">{selectedDispute.complainant?.email}</p>
                    </div>
                  </div>
                </div>
                <div className="p-3 bg-muted rounded-lg">
                  <p className="text-xs text-gray-500 mb-2">Respondent</p>
                  <div className="flex items-center gap-2">
                    <Avatar>
                      <AvatarImage src={getFullUrl(selectedDispute.respondent?.avatar_url)} />
                      <AvatarFallback>{selectedDispute.respondent?.full_name?.[0]}</AvatarFallback>
                    </Avatar>
                    <div>
                      <p className="font-medium">{selectedDispute.respondent?.full_name}</p>
                      <p className="text-xs text-muted-foreground">{selectedDispute.respondent?.email}</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Amount */}
              {selectedDispute.amount_disputed && (
                <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg">
                  <div className="flex items-center justify-between">
                    <span className="text-muted-foreground">Amount Disputed</span>
                    <span className="text-xl font-bold text-red-400">${selectedDispute.amount_disputed}</span>
                  </div>
                  {selectedDispute.amount_refunded && (
                    <div className="flex items-center justify-between mt-2 pt-2 border-t border-red-500/20">
                      <span className="text-muted-foreground">Amount Refunded (Credit)</span>
                      <span className="text-green-400">${selectedDispute.amount_refunded}</span>
                    </div>
                  )}
                </div>
              )}

              {/* Refund Input */}
              {['open', 'under_review', 'escalated'].includes(selectedDispute.status) && selectedDispute.amount_disputed && (
                <div className="flex items-center gap-2">
                  <Input
                    type="number"
                    placeholder="Refund amount"
                    value={refundAmount}
                    onChange={(e) => setRefundAmount(e.target.value)}
                    className="bg-muted border-border w-32"
                  />
                  <Button
                    onClick={() => handleUpdateDispute(selectedDispute.id, {
                      status: 'resolved_refund',
                      amount_refunded: parseFloat(refundAmount)
                    })}
                    disabled={!refundAmount || actionLoading}
                    className="bg-green-500 hover:bg-green-600"
                  >
                    Issue Credit Refund
                  </Button>
                </div>
              )}

              {/* Messages Thread */}
              <div>
                <h4 className="font-medium mb-2 flex items-center gap-2">
                  <MessageSquare className="w-4 h-4" />
                  Messages ({selectedDispute.messages?.length || 0})
                </h4>
                <div className="space-y-2 max-h-48 overflow-y-auto">
                  {selectedDispute.messages?.map(msg => (
                    <div 
                      key={msg.id} 
                      className={`p-2 rounded-lg ${msg.is_admin ? 'bg-red-500/10 border border-red-500/30' : 'bg-muted'}`}
                    >
                      <div className="flex items-center gap-2 mb-1">
                        <Avatar className="w-5 h-5">
                          <AvatarImage src={getFullUrl(msg.sender?.avatar_url)} />
                          <AvatarFallback className="text-xs">{msg.sender?.full_name?.[0]}</AvatarFallback>
                        </Avatar>
                        <span className="text-sm font-medium">{msg.sender?.full_name}</span>
                        {msg.is_admin && <Badge className="text-xs bg-red-500/20 text-red-400">Admin</Badge>}
                        <span className="text-xs text-gray-500">{formatDate(msg.created_at)}</span>
                      </div>
                      <p className="text-sm text-gray-300">{msg.message}</p>
                    </div>
                  ))}
                </div>
                
                {/* New Message */}
                <div className="flex gap-2 mt-3">
                  <Input
                    placeholder="Type a message..."
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    className="bg-muted border-border"
                    onKeyPress={(e) => e.key === 'Enter' && handleAddDisputeMessage(selectedDispute.id)}
                  />
                  <Button
                    onClick={() => handleAddDisputeMessage(selectedDispute.id)}
                    disabled={!newMessage.trim() || actionLoading}
                    className="bg-blue-500 hover:bg-blue-600"
                  >
                    {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                  </Button>
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Report Review Modal */}
      <Dialog open={showReportReview} onOpenChange={setShowReportReview}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Flag className="w-5 h-5 text-orange-400" />
              Review Report
            </DialogTitle>
          </DialogHeader>
          
          {selectedReport && (
            <div className="space-y-4">
              <div>
                <p className="text-sm text-muted-foreground mb-1">Report Type</p>
                <Badge variant="outline" className="capitalize">{selectedReport.report_type}</Badge>
              </div>
              
              <div>
                <p className="text-sm text-muted-foreground mb-1">Reason</p>
                <Badge className="bg-red-500/20 text-red-400 capitalize">
                  {selectedReport.reason?.replace(/_/g, ' ')}
                </Badge>
              </div>
              
              {selectedReport.description && (
                <div>
                  <p className="text-sm text-muted-foreground mb-1">Description</p>
                  <p className="text-foreground">{selectedReport.description}</p>
                </div>
              )}
              
              <div>
                <p className="text-sm text-muted-foreground mb-2">Take Action</p>
                <Select value={reviewAction} onValueChange={setReviewAction}>
                  <SelectTrigger className="bg-muted border-border">
                    <SelectValue placeholder="Select action..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="no_action">No Action Needed</SelectItem>
                    <SelectItem value="warning_sent">Send Warning</SelectItem>
                    <SelectItem value="content_removed">Remove Content</SelectItem>
                    <SelectItem value="user_suspended">Suspend User</SelectItem>
                    <SelectItem value="user_banned">Ban User</SelectItem>
                    <SelectItem value="escalate">Escalate to Dispute</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              
              <div>
                <p className="text-sm text-muted-foreground mb-2">Admin Notes</p>
                <Textarea
                  value={adminNotes}
                  onChange={(e) => setAdminNotes(e.target.value)}
                  placeholder="Add notes about this decision..."
                  className="bg-muted border-border"
                />
              </div>
            </div>
          )}
          
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowReportReview(false)}>
              Cancel
            </Button>
            <Button
              onClick={() => handleReviewReport(selectedReport?.id)}
              disabled={!reviewAction || actionLoading}
              className="bg-blue-500 hover:bg-blue-600"
            >
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
              Submit Review
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AdminModerationDashboard;

import React, { useState, useEffect } from 'react';

import { useAuth } from '../../contexts/AuthContext';

import { useTheme } from '../../contexts/ThemeContext';

import { useLocation } from 'react-router-dom';

import apiClient from '../../lib/apiClient';

import { UserCheck, Eye, AlertTriangle, Search,

  Loader2, ChevronRight, ExternalLink, Instagram, Globe, FileText, Camera, Award, Link2, RefreshCw, Activity, Calendar, DollarSign, MessageSquare,
  Flag, Gavel, Ban, Scale, MapPin, ThumbsUp, ThumbsDown, Users, Copy
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';

import { Button } from '../ui/button';

import { Input } from '../ui/input';

import { Textarea } from '../ui/textarea';

import { Badge } from '../ui/badge';

import { Avatar, AvatarFallback, AvatarImage } from '../ui/avatar';

import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';

import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';

import { toast } from 'sonner';

import logger from '../../utils/logger';
import { getFullUrl } from '../../utils/media';



// Status badge component
const StatusBadge = ({ status }) => {
  const styles = {
    pending: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    under_review: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    approved: 'bg-green-500/20 text-green-400 border-green-500/30',
    rejected: 'bg-red-500/20 text-red-400 border-red-500/30',
    more_info_needed: 'bg-orange-500/20 text-orange-400 border-orange-500/30',
    open: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    investigating: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    resolved: 'bg-green-500/20 text-green-400 border-green-500/30',
    false_positive: 'bg-gray-500/20 text-muted-foreground border-gray-500/30',
  };
  return (
    <Badge className={`text-xs ${styles[status] || 'bg-zinc-500/20 text-zinc-400'}`}>
      {status?.replace(/_/g, ' ')}
    </Badge>
  );
};

// Severity badge
const SeverityBadge = ({ severity }) => {
  const styles = {
    low: 'bg-gray-500/20 text-muted-foreground',
    medium: 'bg-yellow-500/20 text-yellow-400',
    high: 'bg-orange-500/20 text-orange-400',
    critical: 'bg-red-500/20 text-red-400 animate-pulse',
  };
  return <Badge className={`text-xs ${styles[severity] || styles.medium}`}>{severity}</Badge>;
};

export const AdminP1Dashboard = () => {
  const { user, startImpersonation: authStartImpersonation, impersonation: authImpersonation, endImpersonation: authEndImpersonation } = useAuth();
  const { theme } = useTheme();
  const location = useLocation();
  const [activeSubTab, setActiveSubTab] = useState('verification');
  const [loading, setLoading] = useState(true);
  
  // Verification Queue state
  const [verificationQueue, setVerificationQueue] = useState([]);
  const [pendingVerifications, setPendingVerifications] = useState(0);
  const [selectedVerification, setSelectedVerification] = useState(null);
  const [showVerificationDetail, setShowVerificationDetail] = useState(false);
  const [verificationFilter, setVerificationFilter] = useState({ type: 'all' });
  
  // Handle navigation state from notification click
  useEffect(() => {
    if (location.state?.tab) {
      setActiveSubTab(location.state.tab);
    }
  }, [location.state]);
  
  // Auto-open specific application when navigating from notification
  useEffect(() => {
    const applicantId = location.state?.applicantId;
    const verificationRequestId = location.state?.verificationRequestId;
    
    if ((applicantId || verificationRequestId) && verificationQueue.length > 0) {
      const targetApplication = verificationQueue.find(
        v => v.id === verificationRequestId || v.user?.id === applicantId
      );
      if (targetApplication) {
        setSelectedVerification(targetApplication);
        setShowVerificationDetail(true);
        // Clear the state so it doesn't re-open on subsequent renders
        window.history.replaceState({}, document.title);
      }
    }
  }, [location.state?.applicantId, location.state?.verificationRequestId, verificationQueue]);
  
  
  // Impersonation state
  const [impersonationHistory, setImpersonationHistory] = useState([]);
  const [searchUserQuery, setSearchUserQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [activeImpersonation, setActiveImpersonation] = useState(authImpersonation);
  const [impersonationReason, setImpersonationReason] = useState('');
  
  // Fraud Detection state
  const [fraudAlerts, setFraudAlerts] = useState([]);
  const [severityCounts, setSeverityCounts] = useState({});
  const [selectedAlert, setSelectedAlert] = useState(null);
  const [showAlertDetail, setShowAlertDetail] = useState(false);
  const [fraudFilter, setFraudFilter] = useState({ severity: 'all' });
  
  // User Journey state
  const [journeyUser, setJourneyUser] = useState(null);
  const [journeyActivities, setJourneyActivities] = useState([]);
  const [journeySummary, setJourneySummary] = useState(null);
  
  // Compliance (ToS Violations) state
  const [complianceStats, setComplianceStats] = useState(null);
  const [recentViolations, setRecentViolations] = useState([]);
  const [pendingAppeals, setPendingAppeals] = useState([]);
  const [selectedViolation, setSelectedViolation] = useState(null);
  const [showViolationDetail, setShowViolationDetail] = useState(false);
  const [appealNotes, setAppealNotes] = useState('');
  const [complianceFilter, setComplianceFilter] = useState({ type: 'all' });
  const [locationFraudMapData, setLocationFraudMapData] = useState([]);
  const [selectedAppeals, setSelectedAppeals] = useState(new Set());
  const [bulkProcessing, setBulkProcessing] = useState(false);
  
  // Test Accounts state
  const [testAccounts, setTestAccounts] = useState([]);
  const [seedingAccounts, setSeedingAccounts] = useState(false);
  const [testAccountPassword, setTestAccountPassword] = useState('Test123!');
  
  // Form states
  const [reviewStatus, setReviewStatus] = useState('');
  const [adminNotes, setAdminNotes] = useState('');
  const [rejectionReason, setRejectionReason] = useState('');
  const [resolutionNotes, setResolutionNotes] = useState('');
  const [actionTaken, setActionTaken] = useState('');
  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  useEffect(() => {
    if (user?.id) {
      if (activeSubTab === 'verification') fetchVerificationQueue();
      else if (activeSubTab === 'impersonation') fetchImpersonationHistory();
      else if (activeSubTab === 'fraud') fetchFraudAlerts();
      else if (activeSubTab === 'compliance') fetchComplianceData();
      else if (activeSubTab === 'test_accounts') fetchTestAccounts();
    }
  }, [user?.id, activeSubTab, verificationFilter, fraudFilter, complianceFilter]);

  const fetchVerificationQueue = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (verificationFilter.type && verificationFilter.type !== 'all') {
        params.append('verification_type', verificationFilter.type);
      }
      
      const response = await apiClient.get(`/admin/verification/queue?${params}`);
      setVerificationQueue(response.data.requests || []);
      setPendingVerifications(response.data.pending_count || 0);
    } catch (error) {
      toast.error('Failed to load verification queue');
    } finally {
      setLoading(false);
    }
  };

  const fetchImpersonationHistory = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/admin/impersonate/history`);
      setImpersonationHistory(response.data || []);
    } catch (error) {
      toast.error('Failed to load impersonation history');
    } finally {
      setLoading(false);
    }
  };

  const fetchFraudAlerts = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (fraudFilter.severity && fraudFilter.severity !== 'all') {
        params.append('severity', fraudFilter.severity);
      }
      
      const response = await apiClient.get(`/admin/fraud/alerts?${params}`);
      setFraudAlerts(response.data.alerts || []);
      setSeverityCounts(response.data.severity_counts || {});
    } catch (error) {
      toast.error('Failed to load fraud alerts');
    } finally {
      setLoading(false);
    }
  };

  const fetchComplianceData = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/compliance/dashboard`);
      setComplianceStats(response.data.stats);
      setRecentViolations(response.data.recent_violations || []);
      setLocationFraudMapData(response.data.location_fraud_map_data || []);
      
      // Filter for pending appeals
      const appeals = response.data.recent_violations?.filter(v => v.appeal_status === 'pending') || [];
      setPendingAppeals(appeals);
      setSelectedAppeals(new Set()); // Reset selection
    } catch (error) {
      logger.error('Failed to load compliance data:', error);
      toast.error('Failed to load compliance data');
    } finally {
      setLoading(false);
    }
  };

  const handleReviewAppeal = async (violationId, approved) => {
    setActionLoading(true);
    try {
      await apiClient.put(`/compliance/violations/${violationId}/appeal/review`, {
        approved,
        notes: appealNotes
      });
      toast.success(approved ? 'Appeal approved - strike removed' : 'Appeal denied');
      setShowViolationDetail(false);
      setAppealNotes('');
      fetchComplianceData();
    } catch (error) {
      toast.error('Failed to review appeal');
    } finally {
      setActionLoading(false);
    }
  };

  const handleBulkReviewAppeals = async (approved) => {
    if (selectedAppeals.size === 0) {
      toast.error('No appeals selected');
      return;
    }
    
    setBulkProcessing(true);
    try {
      const response = await apiClient.post(
        `/compliance/violations/bulk-review-appeals`,
        {
          violation_ids: Array.from(selectedAppeals),
          approved,
          notes: `Bulk ${approved ? 'approved' : 'denied'} by admin`
        }
      );
      
      toast.success(`${response.data.processed} appeals ${approved ? 'approved' : 'denied'}`);
      setSelectedAppeals(new Set());
      fetchComplianceData();
    } catch (error) {
      toast.error('Failed to process bulk appeals');
    } finally {
      setBulkProcessing(false);
    }
  };

  const toggleAppealSelection = (violationId) => {
    setSelectedAppeals(prev => {
      const next = new Set(prev);
      if (next.has(violationId)) {
        next.delete(violationId);
      } else {
        next.add(violationId);
      }
      return next;
    });
  };

  const selectAllAppeals = () => {
    if (selectedAppeals.size === pendingAppeals.length) {
      setSelectedAppeals(new Set());
    } else {
      setSelectedAppeals(new Set(pendingAppeals.map(a => a.id)));
    }
  };

  // ============ TEST ACCOUNTS ============
  
  const fetchTestAccounts = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/admin/test-accounts`);
      setTestAccounts(response.data.accounts || []);
    } catch (error) {
      toast.error('Failed to load test accounts');
    } finally {
      setLoading(false);
    }
  };

  const seedAllRoleAccounts = async () => {
    setSeedingAccounts(true);
    try {
      const response = await apiClient.post(`/admin/seed-test-accounts`, {
        seed_all_roles: true,
        password: testAccountPassword
      });
      toast.success(response.data.message);
      fetchTestAccounts();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to seed test accounts');
    } finally {
      setSeedingAccounts(false);
    }
  };

  const cleanupOldTestAccounts = async () => {
    setActionLoading(true);
    try {
      const response = await apiClient.delete(`/admin/test-accounts/cleanup?older_than_days=7`);
      toast.success(response.data.message);
      fetchTestAccounts();
    } catch (error) {
      toast.error('Failed to cleanup test accounts');
    } finally {
      setActionLoading(false);
    }
  };

  const copyCredentials = (account) => {
    const text = `Email: ${account.email}\nPassword: ${testAccountPassword}\nRole: ${account.role}`;
    navigator.clipboard.writeText(text);
    toast.success('Credentials copied to clipboard');
  };

  const searchUsers = async (query) => {
    if (!query || query.length < 2) {
      setSearchResults([]);
      return;
    }
    try {
      const response = await apiClient.get(`/admin/users/search?q=${query}&limit=10`);
      setSearchResults(response.data.users || []);
    } catch (error) {
      logger.error('Search failed:', error);
    }
  };

  const handleReviewVerification = async (requestId) => {
    if (!reviewStatus) {
      toast.error('Please select a status');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.put(`/admin/verification/${requestId}/review`, {
        status: reviewStatus,
        admin_notes: adminNotes,
        rejection_reason: rejectionReason
      });
      toast.success(`Verification ${reviewStatus}`);
      setShowVerificationDetail(false);
      setReviewStatus('');
      setAdminNotes('');
      setRejectionReason('');
      fetchVerificationQueue();
    } catch (error) {
      toast.error('Failed to review verification');
    } finally {
      setActionLoading(false);
    }
  };

  const startImpersonation = async (targetUserId) => {
    setActionLoading(true);
    try {
      const response = await apiClient.post(`/admin/impersonate/start`, {
        target_user_id: targetUserId,
        reason: impersonationReason,
        is_read_only: true
      });
      
      // Use AuthContext to switch user view
      authStartImpersonation(response.data);
      setActiveImpersonation(response.data);
      
      toast.success(`Now viewing as ${response.data.target_user.full_name || response.data.target_user.email}`);
      setSearchUserQuery('');
      setSearchResults([]);
      setImpersonationReason('');
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to start impersonation');
    } finally {
      setActionLoading(false);
    }
  };

  const endImpersonation = async () => {
    if (!activeImpersonation && !authImpersonation) return;
    setActionLoading(true);
    try {
      // Use AuthContext to restore admin view
      await authEndImpersonation();
      setActiveImpersonation(null);
      toast.success('Impersonation ended - restored admin view');
      fetchImpersonationHistory();
    } catch (error) {
      toast.error('Failed to end impersonation');
    } finally {
      setActionLoading(false);
    }
  };

  const handleResolveFraudAlert = async (alertId) => {
    if (!actionTaken) {
      toast.error('Please select an action');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.put(`/admin/fraud/alerts/${alertId}/resolve`, {
        resolution_notes: resolutionNotes,
        action_taken: actionTaken
      });
      toast.success('Alert resolved');
      setShowAlertDetail(false);
      setResolutionNotes('');
      setActionTaken('');
      fetchFraudAlerts();
    } catch (error) {
      toast.error('Failed to resolve alert');
    } finally {
      setActionLoading(false);
    }
  };

  const fetchUserJourney = async (userId) => {
    setLoading(true);
    try {
      const [summaryRes, activitiesRes] = await Promise.all([
        apiClient.get(`/admin/user-journey/${userId}/summary`),
        apiClient.get(`/admin/user-journey/${userId}?limit=50`)
      ]);
      setJourneySummary(summaryRes.data);
      setJourneyUser(summaryRes.data.user);
      setJourneyActivities(activitiesRes.data.activities || []);
    } catch (error) {
      toast.error('Failed to load user journey');
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="space-y-4" data-testid="admin-p1-dashboard">
      {/* Sub-tabs */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {[
          { id: 'verification', label: 'Verification Queue', icon: UserCheck, count: pendingVerifications },
          { id: 'impersonation', label: 'Impersonation', icon: Eye },
          { id: 'fraud', label: 'Fraud Detection', icon: AlertTriangle, count: severityCounts.critical || 0 },
          { id: 'compliance', label: 'Compliance', icon: Gavel, count: complianceStats?.pending_appeals || 0 },
          { id: 'journey', label: 'User Journey', icon: Activity },
          { id: 'test_accounts', label: 'Test Accounts', icon: Users },
        ].map(tab => (
          <Button
            key={tab.id}
            variant={activeSubTab === tab.id ? 'default' : 'outline'}
            size="sm"
            onClick={() => setActiveSubTab(tab.id)}
            className={activeSubTab === tab.id ? 'bg-purple-500 hover:bg-purple-600' : ''}
            data-testid={`p1-tab-${tab.id}`}
          >
            <tab.icon className="w-4 h-4 mr-1.5" />
            {tab.label}
            {tab.count > 0 && (
              <Badge className="ml-1.5 bg-white/20 text-foreground">{tab.count}</Badge>
            )}
          </Button>
        ))}
      </div>

      {/* Active Impersonation Banner */}
      {activeImpersonation && (
        <Card className="bg-purple-500/20 border-purple-500/50">
          <CardContent className="p-3 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Eye className="w-5 h-5 text-purple-400" />
              <div>
                <p className="text-foreground font-medium">
                  Viewing as: {activeImpersonation.target_user.full_name}
                </p>
                <p className="text-purple-300 text-xs">
                  {activeImpersonation.target_user.email} • {activeImpersonation.is_read_only ? 'Read-only' : 'Full access'}
                </p>
              </div>
            </div>
            <Button
              size="sm"
              variant="destructive"
              onClick={endImpersonation}
              disabled={actionLoading}
            >
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'End Session'}
            </Button>
          </CardContent>
        </Card>
      )}

      {loading && activeSubTab !== 'journey' ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
        </div>
      ) : (
        <>
          {/* VERIFICATION QUEUE TAB */}
          {activeSubTab === 'verification' && (
            <div className="space-y-3">
              {/* Filters */}
              <div className="flex gap-2">
                <Select value={verificationFilter.type} onValueChange={(v) => setVerificationFilter({ type: v })}>
                  <SelectTrigger className="w-48 bg-muted border-border">
                    <SelectValue placeholder="Verification Type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Types</SelectItem>
                    <SelectItem value="pro_surfer">Pro Surfer (WSL)</SelectItem>
                    <SelectItem value="approved_pro_photographer">Approved Pro Photographer</SelectItem>
                  </SelectContent>
                </Select>
                <Button variant="outline" size="sm" onClick={fetchVerificationQueue}>
                  <RefreshCw className="w-4 h-4" />
                </Button>
              </div>

              {/* Verification List */}
              {verificationQueue.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <UserCheck className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No pending verification requests</p>
                  </CardContent>
                </Card>
              ) : (
                verificationQueue.map(req => (
                  <Card 
                    key={req.id} 
                    className={`${cardBgClass} cursor-pointer hover:border-purple-500/50 transition-colors`}
                    onClick={() => { setSelectedVerification(req); setShowVerificationDetail(true); }}
                  >
                    <CardContent className="p-4">
                      <div className="flex items-start gap-4">
                        <Avatar className="w-12 h-12">
                          <AvatarImage src={getFullUrl(req.user?.avatar_url)} />
                          <AvatarFallback>{req.user?.full_name?.[0]}</AvatarFallback>
                        </Avatar>
                        
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <p className={`font-medium ${textClass}`}>{req.user?.full_name}</p>
                            <StatusBadge status={req.status} />
                          </div>
                          <p className={`text-sm ${textSecondary}`}>{req.user?.email}</p>
                          
                          <div className="flex items-center gap-2 mt-2">
                            <Badge variant="outline" className={`text-xs ${
                              req.verification_type === 'pro_surfer' 
                                ? 'border-cyan-500 text-cyan-400' 
                                : 'border-purple-500 text-purple-400'
                            }`}>
                              {req.verification_type === 'pro_surfer' ? (
                                <><Award className="w-3 h-3 mr-1" /> Pro Surfer (WSL)</>
                              ) : (
                                <><Camera className="w-3 h-3 mr-1" /> Approved Pro Photographer</>
                              )}
                            </Badge>
                          </div>
                          
                          {/* Quick preview of verification data */}
                          <div className="mt-2 flex flex-wrap gap-2 text-xs">
                            {req.wsl_profile_url && (
                              <a 
                                href={req.wsl_profile_url} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="flex items-center gap-1 text-cyan-400 hover:underline"
                              >
                                <Globe className="w-3 h-3" /> WSL Profile
                              </a>
                            )}
                            {req.instagram_url && (
                              <a 
                                href={req.instagram_url} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="flex items-center gap-1 text-pink-400 hover:underline"
                              >
                                <Instagram className="w-3 h-3" /> Instagram
                              </a>
                            )}
                            {req.portfolio_website && (
                              <a 
                                href={req.portfolio_website} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="flex items-center gap-1 text-blue-400 hover:underline"
                              >
                                <Globe className="w-3 h-3" /> Portfolio
                              </a>
                            )}
                          </div>
                        </div>
                        
                        <div className="text-right shrink-0">
                          <p className={`text-xs ${textSecondary}`}>{formatDate(req.created_at)}</p>
                          <ChevronRight className="w-5 h-5 text-gray-500 mt-2" />
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          )}

          {/* IMPERSONATION TAB */}
          {activeSubTab === 'impersonation' && (
            <div className="space-y-4">
              {/* Search User */}
              <Card className={cardBgClass}>
                <CardHeader className="pb-2">
                  <CardTitle className={`text-sm ${textClass}`}>
                    <Eye className="w-4 h-4 inline mr-2" />
                    Start Impersonation Session
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                    <Input
                      placeholder="Search user by name or email..."
                      value={searchUserQuery}
                      onChange={(e) => {
                        setSearchUserQuery(e.target.value);
                        searchUsers(e.target.value);
                      }}
                      className="pl-10 bg-muted border-border"
                    />
                  </div>
                  
                  <Input
                    placeholder="Reason for impersonation (optional)"
                    value={impersonationReason}
                    onChange={(e) => setImpersonationReason(e.target.value)}
                    className="bg-muted border-border"
                  />
                  
                  {/* Search Results */}
                  {searchResults.length > 0 && (
                    <div className="bg-muted rounded-lg divide-y divide-zinc-700 max-h-60 overflow-y-auto">
                      {searchResults.map(u => (
                        <div 
                          key={u.id}
                          className="p-3 flex items-center justify-between hover:bg-input cursor-pointer"
                          onClick={() => startImpersonation(u.id)}
                        >
                          <div className="flex items-center gap-3">
                            <Avatar className="w-8 h-8">
                              <AvatarImage src={getFullUrl(u.avatar_url)} />
                              <AvatarFallback>{u.full_name?.[0]}</AvatarFallback>
                            </Avatar>
                            <div>
                              <p className="text-foreground text-sm">{u.full_name}</p>
                              <p className="text-muted-foreground text-xs">{u.email}</p>
                            </div>
                          </div>
                          <Button size="sm" className="bg-purple-500 hover:bg-purple-600">
                            <Eye className="w-3 h-3 mr-1" /> View As
                          </Button>
                        </div>
                      ))}
                    </div>
                  )}
                </CardContent>
              </Card>

              {/* Impersonation History */}
              <Card className={cardBgClass}>
                <CardHeader className="pb-2">
                  <CardTitle className={`text-sm ${textClass}`}>Recent Impersonation Sessions</CardTitle>
                </CardHeader>
                <CardContent>
                  {impersonationHistory.length === 0 ? (
                    <p className={`text-sm ${textSecondary} text-center py-4`}>No impersonation history</p>
                  ) : (
                    <div className="space-y-2">
                      {impersonationHistory.map(session => (
                        <div key={session.id} className="p-2 bg-muted rounded-lg flex items-center justify-between">
                          <div className="flex items-center gap-3">
                            <Avatar className="w-8 h-8">
                              <AvatarFallback>{session.target_user?.full_name?.[0]}</AvatarFallback>
                            </Avatar>
                            <div>
                              <p className="text-foreground text-sm">{session.target_user?.full_name}</p>
                              <p className="text-muted-foreground text-xs">
                                {session.reason || 'No reason provided'}
                              </p>
                            </div>
                          </div>
                          <div className="text-right">
                            <p className="text-xs text-muted-foreground">{formatDate(session.started_at)}</p>
                            <p className="text-xs text-gray-500">
                              {session.duration_minutes ? `${Math.round(session.duration_minutes)} min` : 'Active'}
                            </p>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          )}

          {/* FRAUD DETECTION TAB */}
          {activeSubTab === 'fraud' && (
            <div className="space-y-3">
              {/* Severity Summary */}
              <div className="grid grid-cols-4 gap-2">
                {['critical', 'high', 'medium', 'low'].map(severity => (
                  <Card key={severity} className={`${cardBgClass} ${
                    severity === 'critical' ? 'border-red-500/50' :
                    severity === 'high' ? 'border-orange-500/50' :
                    severity === 'medium' ? 'border-yellow-500/50' : ''
                  }`}>
                    <CardContent className="p-3 text-center">
                      <p className="text-2xl font-bold text-foreground">{severityCounts[severity] || 0}</p>
                      <p className={`text-xs capitalize ${textSecondary}`}>{severity}</p>
                    </CardContent>
                  </Card>
                ))}
              </div>

              {/* Filters */}
              <div className="flex gap-2">
                <Select value={fraudFilter.severity} onValueChange={(v) => setFraudFilter({ severity: v })}>
                  <SelectTrigger className="w-40 bg-muted border-border">
                    <SelectValue placeholder="Severity" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Severity</SelectItem>
                    <SelectItem value="critical">Critical</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                    <SelectItem value="medium">Medium</SelectItem>
                    <SelectItem value="low">Low</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Alerts List */}
              {fraudAlerts.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <AlertTriangle className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No active fraud alerts</p>
                  </CardContent>
                </Card>
              ) : (
                fraudAlerts.map(alert => (
                  <Card 
                    key={alert.id} 
                    className={`${cardBgClass} cursor-pointer hover:border-red-500/50 transition-colors ${
                      alert.severity === 'critical' ? 'border-red-500/30' : ''
                    }`}
                    onClick={() => { setSelectedAlert(alert); setShowAlertDetail(true); }}
                  >
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-1">
                            <SeverityBadge severity={alert.severity} />
                            <StatusBadge status={alert.status} />
                            <Badge variant="outline" className="text-xs capitalize">
                              {alert.alert_type?.replace(/_/g, ' ')}
                            </Badge>
                          </div>
                          <p className={`font-medium ${textClass}`}>{alert.title}</p>
                          <p className={`text-sm ${textSecondary} line-clamp-2 mt-1`}>{alert.description}</p>
                          
                          <div className="flex items-center gap-2 mt-2">
                            <Avatar className="w-5 h-5">
                              <AvatarImage src={getFullUrl(alert.user?.avatar_url)} />
                              <AvatarFallback className="text-xs">{alert.user?.full_name?.[0]}</AvatarFallback>
                            </Avatar>
                            <span className={`text-xs ${textSecondary}`}>{alert.user?.full_name}</span>
                          </div>
                        </div>
                        
                        <div className="text-right shrink-0">
                          <div className="flex items-center gap-1 mb-1">
                            <span className="text-xs text-gray-500">Risk Score:</span>
                            <span className={`font-bold ${
                              alert.risk_score >= 80 ? 'text-red-400' :
                              alert.risk_score >= 50 ? 'text-orange-400' :
                              'text-yellow-400'
                            }`}>{alert.risk_score}</span>
                          </div>
                          <p className={`text-xs ${textSecondary}`}>{formatDate(alert.created_at)}</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          )}

          {/* COMPLIANCE (TOS VIOLATIONS) TAB */}
          {activeSubTab === 'compliance' && (
            <div className="space-y-4" data-testid="compliance-tab">
              {/* Stats Cards */}
              {complianceStats && (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  <Card className={`${cardBgClass} border`}>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-3">
                        <div className="p-2 rounded-lg bg-yellow-500/20">
                          <AlertTriangle className="w-5 h-5 text-yellow-400" />
                        </div>
                        <div>
                          <p className={`text-2xl font-bold ${textClass}`}>{complianceStats.total_violations}</p>
                          <p className={`text-xs ${textSecondary}`}>Total Violations</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                  
                  <Card className={`${cardBgClass} border`}>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-3">
                        <div className="p-2 rounded-lg bg-red-500/20">
                          <MapPin className="w-5 h-5 text-red-400" />
                        </div>
                        <div>
                          <p className={`text-2xl font-bold ${textClass}`}>{complianceStats.location_fraud_count}</p>
                          <p className={`text-xs ${textSecondary}`}>Location Fraud</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                  
                  <Card className={`${cardBgClass} border`}>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-3">
                        <div className="p-2 rounded-lg bg-orange-500/20">
                          <Scale className="w-5 h-5 text-orange-400" />
                        </div>
                        <div>
                          <p className={`text-2xl font-bold ${textClass}`}>{complianceStats.pending_appeals}</p>
                          <p className={`text-xs ${textSecondary}`}>Pending Appeals</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                  
                  <Card className={`${cardBgClass} border`}>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-3">
                        <div className="p-2 rounded-lg bg-purple-500/20">
                          <Ban className="w-5 h-5 text-purple-400" />
                        </div>
                        <div>
                          <p className={`text-2xl font-bold ${textClass}`}>{complianceStats.suspended_users + complianceStats.banned_users}</p>
                          <p className={`text-xs ${textSecondary}`}>Suspended/Banned</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </div>
              )}

              {/* Week Summary */}
              {complianceStats && (
                <Card className={`${cardBgClass} border border-blue-500/30`}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <Calendar className="w-5 h-5 text-blue-400" />
                        <span className={textClass}>This Week: <strong>{complianceStats.violations_this_week}</strong> new violations</span>
                      </div>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={fetchComplianceData}
                        className="gap-1"
                      >
                        <RefreshCw className="w-3 h-3" />
                        Refresh
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              )}

              {/* Location Fraud Map Visualization */}
              {locationFraudMapData.length > 0 && (
                <Card className={`${cardBgClass} border border-red-500/30`}>
                  <CardHeader className="pb-2">
                    <CardTitle className={`text-sm ${textClass} flex items-center gap-2`}>
                      <MapPin className="w-4 h-4 text-red-400" />
                      Location Fraud Map ({locationFraudMapData.length} incidents)
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-3">
                      {/* Legend */}
                      <div className="flex gap-4 text-xs">
                        <div className="flex items-center gap-1">
                          <div className="w-3 h-3 rounded-full bg-blue-500"></div>
                          <span className={textSecondary}>Claimed Location</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <div className="w-3 h-3 rounded-full bg-red-500"></div>
                          <span className={textSecondary}>Actual Location</span>
                        </div>
                      </div>
                      
                      {/* Fraud Incidents List */}
                      <div className="max-h-60 overflow-y-auto space-y-2">
                        {locationFraudMapData.map((fraud, _idx) => (
                          <div 
                            key={fraud.id}
                            className="p-3 rounded-lg bg-muted/50 border border-border"
                          >
                            <div className="flex items-center justify-between mb-2">
                              <Badge className={`text-[10px] ${
                                fraud.severity === 'critical' ? 'bg-red-500/20 text-red-400' :
                                fraud.severity === 'severe' ? 'bg-orange-500/20 text-orange-400' :
                                'bg-yellow-500/20 text-yellow-400'
                              }`}>
                                {fraud.severity} • {fraud.distance_miles?.toFixed(1)} mi
                              </Badge>
                              <span className={`text-[10px] ${textSecondary}`}>
                                {formatDate(fraud.created_at)}
                              </span>
                            </div>
                            <div className="grid grid-cols-2 gap-2 text-xs">
                              <div className="flex items-center gap-1">
                                <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                                <span className={textSecondary}>
                                  Claimed: {fraud.claimed[0]?.toFixed(4)}, {fraud.claimed[1]?.toFixed(4)}
                                </span>
                              </div>
                              <div className="flex items-center gap-1">
                                <div className="w-2 h-2 rounded-full bg-red-500"></div>
                                <span className={textSecondary}>
                                  Actual: {fraud.actual[0]?.toFixed(4)}, {fraud.actual[1]?.toFixed(4)}
                                </span>
                              </div>
                            </div>
                            {/* Visual Distance Bar */}
                            <div className="mt-2 h-1.5 bg-input rounded-full overflow-hidden">
                              <div 
                                className={`h-full ${
                                  fraud.distance_miles > 50 ? 'bg-red-500' :
                                  fraud.distance_miles > 10 ? 'bg-orange-500' :
                                  'bg-yellow-500'
                                }`}
                                style={{ width: `${Math.min((fraud.distance_miles / 100) * 100, 100)}%` }}
                              ></div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </CardContent>
                </Card>
              )}

              {/* Pending Appeals Section with Bulk Actions */}
              {pendingAppeals.length > 0 && (
                <Card className={`${cardBgClass} border border-orange-500/30`}>
                  <CardHeader className="pb-2">
                    <div className="flex items-center justify-between">
                      <CardTitle className={`text-sm ${textClass} flex items-center gap-2`}>
                        <Scale className="w-4 h-4 text-orange-400" />
                        Pending Appeals ({pendingAppeals.length})
                      </CardTitle>
                      
                      {/* Bulk Actions */}
                      <div className="flex items-center gap-2">
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={selectAllAppeals}
                          className="h-7 text-xs"
                        >
                          {selectedAppeals.size === pendingAppeals.length ? 'Deselect All' : 'Select All'}
                        </Button>
                        
                        {selectedAppeals.size > 0 && (
                          <>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => handleBulkReviewAppeals(true)}
                              disabled={bulkProcessing}
                              className="h-7 text-xs border-green-500 text-green-400 hover:bg-green-500/20"
                            >
                              {bulkProcessing ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <ThumbsUp className="w-3 h-3 mr-1" />}
                              Approve ({selectedAppeals.size})
                            </Button>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => handleBulkReviewAppeals(false)}
                              disabled={bulkProcessing}
                              className="h-7 text-xs border-red-500 text-red-400 hover:bg-red-500/20"
                            >
                              {bulkProcessing ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <ThumbsDown className="w-3 h-3 mr-1" />}
                              Deny ({selectedAppeals.size})
                            </Button>
                          </>
                        )}
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-2">
                    {pendingAppeals.map(violation => (
                      <div
                        key={violation.id}
                        className={`p-3 rounded-lg border transition-colors ${
                          selectedAppeals.has(violation.id) 
                            ? 'bg-orange-500/20 border-orange-500' 
                            : 'bg-orange-500/10 border-orange-500/20 hover:bg-orange-500/20'
                        }`}
                        data-testid={`appeal-${violation.id}`}
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-3">
                            <input
                              type="checkbox"
                              checked={selectedAppeals.has(violation.id)}
                              onChange={() => toggleAppealSelection(violation.id)}
                              className="w-4 h-4 rounded border-orange-500 bg-muted text-orange-500 focus:ring-orange-500"
                              onClick={(e) => e.stopPropagation()}
                            />
                            <div 
                              className="cursor-pointer"
                              onClick={() => {
                                setSelectedViolation(violation);
                                setShowViolationDetail(true);
                              }}
                            >
                              <p className={`font-medium ${textClass}`}>{violation.title}</p>
                              <p className={`text-xs ${textSecondary}`}>
                                {violation.violation_type.replace(/_/g, ' ')} • User: {violation.user_id.slice(0, 8)}...
                              </p>
                            </div>
                          </div>
                          <Badge className="bg-orange-500/20 text-orange-400">Appeal Pending</Badge>
                        </div>
                      </div>
                    ))}
                  </CardContent>
                </Card>
              )}

              {/* Recent Violations List */}
              <Card className={cardBgClass}>
                <CardHeader className="pb-2">
                  <div className="flex items-center justify-between">
                    <CardTitle className={`text-sm ${textClass}`}>
                      <Flag className="w-4 h-4 inline mr-2" />
                      Recent Violations
                    </CardTitle>
                    <Select value={complianceFilter.type} onValueChange={(v) => setComplianceFilter({ type: v })}>
                      <SelectTrigger className="w-[140px] h-8 bg-muted border-border">
                        <SelectValue placeholder="Filter" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="all">All Types</SelectItem>
                        <SelectItem value="location_fraud">Location Fraud</SelectItem>
                        <SelectItem value="harassment">Harassment</SelectItem>
                        <SelectItem value="scam">Scam</SelectItem>
                        <SelectItem value="spam">Spam</SelectItem>
                        <SelectItem value="other">Other</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </CardHeader>
                <CardContent className="space-y-2">
                  {recentViolations.length === 0 ? (
                    <p className={`text-center py-8 ${textSecondary}`}>No violations recorded</p>
                  ) : (
                    recentViolations
                      .filter(v => complianceFilter.type === 'all' || v.violation_type === complianceFilter.type)
                      .map(violation => (
                        <div
                          key={violation.id}
                          className={`p-3 rounded-lg ${cardBgClass} border cursor-pointer hover:bg-muted/50 transition-colors`}
                          onClick={() => {
                            setSelectedViolation(violation);
                            setShowViolationDetail(true);
                          }}
                          data-testid={`violation-${violation.id}`}
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                              <div className={`p-1.5 rounded-full ${
                                violation.severity === 'critical' ? 'bg-red-500/20' :
                                violation.severity === 'severe' ? 'bg-orange-500/20' :
                                violation.severity === 'moderate' ? 'bg-yellow-500/20' :
                                'bg-gray-500/20'
                              }`}>
                                {violation.violation_type === 'location_fraud' ? (
                                  <MapPin className={`w-4 h-4 ${
                                    violation.severity === 'critical' ? 'text-red-400' :
                                    violation.severity === 'severe' ? 'text-orange-400' :
                                    'text-yellow-400'
                                  }`} />
                                ) : (
                                  <Flag className="w-4 h-4 text-muted-foreground" />
                                )}
                              </div>
                              <div>
                                <p className={`font-medium ${textClass}`}>{violation.title}</p>
                                <div className="flex items-center gap-2 mt-0.5">
                                  <Badge className={`text-[10px] ${
                                    violation.severity === 'critical' ? 'bg-red-500/20 text-red-400' :
                                    violation.severity === 'severe' ? 'bg-orange-500/20 text-orange-400' :
                                    violation.severity === 'moderate' ? 'bg-yellow-500/20 text-yellow-400' :
                                    'bg-gray-500/20 text-muted-foreground'
                                  }`}>
                                    {violation.severity}
                                  </Badge>
                                  <span className={`text-xs ${textSecondary}`}>
                                    {violation.action_taken.replace(/_/g, ' ')}
                                  </span>
                                </div>
                              </div>
                            </div>
                            <div className="text-right">
                              <p className={`text-xs ${textSecondary}`}>{formatDate(violation.created_at)}</p>
                              {violation.appeal_status && (
                                <Badge className={`mt-1 text-[10px] ${
                                  violation.appeal_status === 'pending' ? 'bg-orange-500/20 text-orange-400' :
                                  violation.appeal_status === 'approved' ? 'bg-green-500/20 text-green-400' :
                                  'bg-red-500/20 text-red-400'
                                }`}>
                                  Appeal: {violation.appeal_status}
                                </Badge>
                              )}
                            </div>
                          </div>
                        </div>
                      ))
                  )}
                </CardContent>
              </Card>
            </div>
          )}

          {/* USER JOURNEY TAB */}
          {activeSubTab === 'journey' && (
            <div className="space-y-4">
              {/* Search User */}
              <Card className={cardBgClass}>
                <CardHeader className="pb-2">
                  <CardTitle className={`text-sm ${textClass}`}>
                    <Activity className="w-4 h-4 inline mr-2" />
                    View User Journey
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                    <Input
                      placeholder="Search user by name or email..."
                      value={searchUserQuery}
                      onChange={(e) => {
                        setSearchUserQuery(e.target.value);
                        searchUsers(e.target.value);
                      }}
                      className="pl-10 bg-muted border-border"
                    />
                  </div>
                  
                  {/* Search Results */}
                  {searchResults.length > 0 && !journeyUser && (
                    <div className="mt-2 bg-muted rounded-lg divide-y divide-zinc-700 max-h-40 overflow-y-auto">
                      {searchResults.map(u => (
                        <div 
                          key={u.id}
                          className="p-3 flex items-center justify-between hover:bg-input cursor-pointer"
                          onClick={() => { fetchUserJourney(u.id); setSearchResults([]); }}
                        >
                          <div className="flex items-center gap-3">
                            <Avatar className="w-8 h-8">
                              <AvatarImage src={getFullUrl(u.avatar_url)} />
                              <AvatarFallback>{u.full_name?.[0]}</AvatarFallback>
                            </Avatar>
                            <div>
                              <p className="text-foreground text-sm">{u.full_name}</p>
                              <p className="text-muted-foreground text-xs">{u.email}</p>
                            </div>
                          </div>
                          <ChevronRight className="w-4 h-4 text-gray-500" />
                        </div>
                      ))}
                    </div>
                  )}
                </CardContent>
              </Card>

              {/* User Journey Display */}
              {journeyUser && journeySummary && (
                <>
                  {/* User Summary */}
                  <Card className={cardBgClass}>
                    <CardContent className="p-4">
                      <div className="flex items-start gap-4">
                        <Avatar className="w-16 h-16">
                          <AvatarImage src={getFullUrl(journeyUser.avatar_url)} />
                          <AvatarFallback className="text-xl">{journeyUser.full_name?.[0]}</AvatarFallback>
                        </Avatar>
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <p className={`text-lg font-bold ${textClass}`}>{journeyUser.full_name}</p>
                            {journeyUser.is_suspended && (
                              <Badge className="bg-red-500/20 text-red-400">Suspended</Badge>
                            )}
                          </div>
                          <p className={textSecondary}>{journeyUser.email}</p>
                          <div className="flex items-center gap-2 mt-1">
                            <Badge variant="outline">{journeyUser.role || 'User'}</Badge>
                            <span className={`text-xs ${textSecondary}`}>
                              Joined {formatDate(journeyUser.created_at)}
                            </span>
                          </div>
                        </div>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => { setJourneyUser(null); setJourneySummary(null); }}
                        >
                          Clear
                        </Button>
                      </div>
                      
                      {/* Stats Grid */}
                      <div className="grid grid-cols-5 gap-2 mt-4">
                        {[
                          { label: 'Posts', value: journeySummary.stats?.posts || 0, icon: FileText },
                          { label: 'Bookings', value: journeySummary.stats?.bookings || 0, icon: Calendar },
                          { label: 'Transactions', value: journeySummary.stats?.transactions || 0, icon: DollarSign },
                          { label: 'Disputes', value: journeySummary.stats?.disputes || 0, icon: MessageSquare },
                          { label: 'Reports', value: journeySummary.stats?.reports_against || 0, icon: Flag },
                        ].map(stat => (
                          <div key={stat.label} className="p-2 bg-muted rounded-lg text-center">
                            <stat.icon className="w-4 h-4 mx-auto text-gray-500 mb-1" />
                            <p className="text-lg font-bold text-foreground">{stat.value}</p>
                            <p className="text-xs text-muted-foreground">{stat.label}</p>
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>

                  {/* Activity Timeline */}
                  <Card className={cardBgClass}>
                    <CardHeader className="pb-2">
                      <CardTitle className={`text-sm ${textClass}`}>Activity Timeline</CardTitle>
                    </CardHeader>
                    <CardContent>
                      {loading ? (
                        <div className="flex justify-center py-8">
                          <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
                        </div>
                      ) : journeyActivities.length === 0 ? (
                        <p className={`text-sm ${textSecondary} text-center py-4`}>No activity recorded</p>
                      ) : (
                        <div className="space-y-2 max-h-96 overflow-y-auto">
                          {journeyActivities.map((activity, _idx) => (
                            <div key={activity.id} className="flex gap-3 p-2 hover:bg-muted rounded-lg">
                              <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center shrink-0">
                                <Activity className="w-4 h-4 text-gray-500" />
                              </div>
                              <div className="flex-1 min-w-0">
                                <p className={`text-sm ${textClass}`}>{activity.description}</p>
                                <div className="flex items-center gap-2 mt-1">
                                  <Badge variant="outline" className="text-xs capitalize">
                                    {activity.activity_category}
                                  </Badge>
                                  <span className={`text-xs ${textSecondary}`}>
                                    {formatDate(activity.created_at)}
                                  </span>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </CardContent>
                  </Card>
                </>
              )}
            </div>
          )}

          {/* TEST ACCOUNTS TAB */}
          {activeSubTab === 'test_accounts' && (
            <div className="space-y-4">
              {/* Seed Accounts Card */}
              <Card className={cardBgClass}>
                <CardHeader>
                  <CardTitle className={`flex items-center gap-2 ${textClass}`}>
                    <Users className="w-5 h-5 text-green-400" />
                    Seed Test Accounts
                  </CardTitle>
                  <p className={`text-sm ${textSecondary}`}>
                    Create test accounts for QA testing. All accounts use @test.rawsurf.io email domain.
                  </p>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center gap-4">
                    <div className="flex-1">
                      <label className={`text-xs ${textSecondary}`}>Password for new accounts</label>
                      <Input
                        value={testAccountPassword}
                        onChange={(e) => setTestAccountPassword(e.target.value)}
                        className="bg-muted border-border"
                        placeholder="Test123!"
                      />
                    </div>
                    <Button
                      onClick={seedAllRoleAccounts}
                      disabled={seedingAccounts}
                      className="bg-green-500 hover:bg-green-600 text-white"
                      data-testid="seed-all-roles-btn"
                    >
                      {seedingAccounts ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                      Seed All Roles
                    </Button>
                    <Button
                      onClick={cleanupOldTestAccounts}
                      disabled={actionLoading}
                      variant="outline"
                      className="border-red-500/50 text-red-400 hover:bg-red-500/10"
                      data-testid="cleanup-test-accounts-btn"
                    >
                      Cleanup Old (&gt;7 days)
                    </Button>
                  </div>
                  
                  <div className="p-3 bg-green-500/10 border border-green-500/30 rounded-lg">
                    <p className={`text-sm ${textClass}`}>
                      <strong>Seed All Roles</strong> creates one account for each role type:
                    </p>
                    <div className="flex flex-wrap gap-2 mt-2">
                      {['Surfer', 'Photographer', 'Approved Pro', 'Grom', 'GromParent', 'Competitive Surfer'].map(role => (
                        <Badge key={role} variant="outline" className="text-green-400 border-green-500/50">
                          {role}
                        </Badge>
                      ))}
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Existing Test Accounts */}
              <Card className={cardBgClass}>
                <CardHeader>
                  <CardTitle className={`flex items-center gap-2 ${textClass}`}>
                    <Users className="w-5 h-5 text-blue-400" />
                    Existing Test Accounts
                    <Badge className="ml-2 bg-blue-500/20 text-blue-400">{testAccounts.length}</Badge>
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  {testAccounts.length === 0 ? (
                    <p className={`text-center py-8 ${textSecondary}`}>
                      No test accounts found. Click "Seed All Roles" to create test accounts.
                    </p>
                  ) : (
                    <div className="space-y-2 max-h-[400px] overflow-y-auto">
                      {testAccounts.map(account => (
                        <div 
                          key={account.id}
                          className="flex items-center gap-3 p-3 bg-muted rounded-lg hover:bg-input transition-colors"
                          data-testid={`test-account-${account.id}`}
                        >
                          <Avatar>
                            <AvatarFallback className="bg-blue-500/20 text-blue-400">
                              {account.full_name?.[0] || '?'}
                            </AvatarFallback>
                          </Avatar>
                          <div className="flex-1 min-w-0">
                            <p className={`font-medium ${textClass} truncate`}>{account.full_name}</p>
                            <p className={`text-sm ${textSecondary} truncate`}>{account.email}</p>
                          </div>
                          <Badge variant="outline" className="shrink-0">{account.role}</Badge>
                          {account.is_verified && (
                            <Badge className="bg-cyan-500/20 text-cyan-400 shrink-0">Verified</Badge>
                          )}
                          {account.is_approved_pro && (
                            <Badge className="bg-purple-500/20 text-purple-400 shrink-0">Pro</Badge>
                          )}
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => copyCredentials(account)}
                            className="shrink-0"
                          >
                            <Copy className="w-4 h-4" />
                          </Button>
                          <Button
                            size="sm"
                            onClick={() => {
                              setSearchUserQuery('');
                              setSearchResults([]);
                              setImpersonationReason('QA testing');
                              startImpersonation(account.id);
                            }}
                            className="bg-purple-500 hover:bg-purple-600 shrink-0"
                          >
                            <Eye className="w-4 h-4 mr-1" />
                            View As
                          </Button>
                        </div>
                      ))}
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          )}
        </>
      )}

      {/* Verification Detail Modal */}
      <Dialog open={showVerificationDetail} onOpenChange={setShowVerificationDetail}>
        <DialogContent className="bg-card border-border text-foreground max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <UserCheck className="w-5 h-5 text-purple-400" />
              Verification Request
            </DialogTitle>
          </DialogHeader>
          
          {selectedVerification && (
            <div className="space-y-4">
              {/* User Info */}
              <div className="flex items-center gap-4 p-3 bg-muted rounded-lg">
                <Avatar className="w-12 h-12">
                  <AvatarImage src={getFullUrl(selectedVerification.user?.avatar_url)} />
                  <AvatarFallback>{selectedVerification.user?.full_name?.[0]}</AvatarFallback>
                </Avatar>
                <div>
                  <p className="font-medium">{selectedVerification.user?.full_name}</p>
                  <p className="text-sm text-muted-foreground">{selectedVerification.user?.email}</p>
                </div>
                <Badge variant="outline" className="ml-auto">
                  {selectedVerification.user?.role || 'User'}
                </Badge>
              </div>

              {/* Verification Type */}
              <div className="flex items-center gap-2">
                <Badge className={`${
                  selectedVerification.verification_type === 'pro_surfer'
                    ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/30'
                    : 'bg-purple-500/20 text-purple-400 border-purple-500/30'
                }`}>
                  {selectedVerification.verification_type === 'pro_surfer' 
                    ? 'Pro Surfer (WSL) Verification' 
                    : 'Approved Pro Photographer Verification'}
                </Badge>
                <StatusBadge status={selectedVerification.status} />
              </div>

              {/* Pro Surfer Fields */}
              {selectedVerification.verification_type === 'pro_surfer' && (
                <div className="space-y-3">
                  <h4 className="font-medium text-cyan-400">WSL Information</h4>
                  
                  {selectedVerification.wsl_athlete_id && (
                    <div className="p-3 bg-muted rounded-lg">
                      <p className="text-xs text-gray-500">WSL Athlete ID</p>
                      <p className="text-foreground font-mono">{selectedVerification.wsl_athlete_id}</p>
                    </div>
                  )}
                  
                  {selectedVerification.wsl_profile_url && (
                    <a 
                      href={selectedVerification.wsl_profile_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-2 p-3 bg-cyan-500/10 border border-cyan-500/30 rounded-lg hover:bg-cyan-500/20 transition-colors"
                    >
                      <Globe className="w-5 h-5 text-cyan-400" />
                      <span className="text-cyan-400">View WSL Profile</span>
                      <ExternalLink className="w-4 h-4 text-cyan-400 ml-auto" />
                    </a>
                  )}
                  
                  {selectedVerification.competition_history_urls?.length > 0 && (
                    <div>
                      <p className="text-xs text-gray-500 mb-2">Competition History</p>
                      <div className="space-y-1">
                        {selectedVerification.competition_history_urls.map((url, idx) => (
                          <a 
                            key={idx}
                            href={url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-2 text-sm text-blue-400 hover:underline"
                          >
                            <Link2 className="w-3 h-3" /> {url}
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}

              {/* Pro Photographer Fields */}
              {selectedVerification.verification_type === 'approved_pro_photographer' && (
                <div className="space-y-3">
                  <h4 className="font-medium text-purple-400">Professional Information</h4>
                  
                  <div className="grid grid-cols-2 gap-2">
                    {selectedVerification.instagram_url && (
                      <a 
                        href={selectedVerification.instagram_url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-2 p-3 bg-pink-500/10 border border-pink-500/30 rounded-lg hover:bg-pink-500/20"
                      >
                        <Instagram className="w-5 h-5 text-pink-400" />
                        <span className="text-pink-400 text-sm">Instagram</span>
                        <ExternalLink className="w-3 h-3 text-pink-400 ml-auto" />
                      </a>
                    )}
                    
                    {selectedVerification.portfolio_website && (
                      <a 
                        href={selectedVerification.portfolio_website}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-2 p-3 bg-blue-500/10 border border-blue-500/30 rounded-lg hover:bg-blue-500/20"
                      >
                        <Globe className="w-5 h-5 text-blue-400" />
                        <span className="text-blue-400 text-sm">Portfolio</span>
                        <ExternalLink className="w-3 h-3 text-blue-400 ml-auto" />
                      </a>
                    )}
                  </div>
                  
                  {selectedVerification.years_experience && (
                    <div className="p-3 bg-muted rounded-lg">
                      <p className="text-xs text-gray-500">Years of Experience</p>
                      <p className="text-foreground">{selectedVerification.years_experience} years</p>
                    </div>
                  )}
                  
                  {selectedVerification.professional_equipment && (
                    <div className="p-3 bg-muted rounded-lg">
                      <p className="text-xs text-gray-500">Professional Equipment</p>
                      <p className="text-foreground text-sm">{selectedVerification.professional_equipment}</p>
                    </div>
                  )}
                  
                  {selectedVerification.media_mentions?.length > 0 && (
                    <div>
                      <p className="text-xs text-gray-500 mb-2">Media Mentions / Features</p>
                      <div className="space-y-1">
                        {selectedVerification.media_mentions.map((url, idx) => (
                          <a 
                            key={idx}
                            href={url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-2 text-sm text-green-400 hover:underline"
                          >
                            <FileText className="w-3 h-3" /> {url}
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                  
                  {selectedVerification.sample_work_urls?.length > 0 && (
                    <div>
                      <p className="text-xs text-gray-500 mb-2">Sample Work</p>
                      <div className="grid grid-cols-3 gap-2">
                        {selectedVerification.sample_work_urls.slice(0, 6).map((url, idx) => (
                          <a 
                            key={idx}
                            href={url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="aspect-square bg-muted rounded-lg overflow-hidden hover:ring-2 ring-purple-500"
                          >
                            <img src={url} alt={`Sample ${idx + 1}`} className="w-full h-full object-cover" />
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}

              {/* Photo ID */}
              {selectedVerification.photo_id_url && (
                <div>
                  <p className="text-xs text-gray-500 mb-2">Photo ID</p>
                  <a 
                    href={selectedVerification.photo_id_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-2 p-3 bg-muted rounded-lg hover:bg-input"
                  >
                    <FileText className="w-5 h-5 text-muted-foreground" />
                    <span className="text-foreground">View Photo ID</span>
                    <ExternalLink className="w-4 h-4 text-muted-foreground ml-auto" />
                  </a>
                </div>
              )}

              {/* Additional Notes */}
              {selectedVerification.additional_notes && (
                <div className="p-3 bg-muted rounded-lg">
                  <p className="text-xs text-gray-500">Additional Notes from User</p>
                  <p className="text-foreground text-sm mt-1">{selectedVerification.additional_notes}</p>
                </div>
              )}

              {/* Review Form */}
              {selectedVerification.status === 'pending' && (
                <div className="border-t border-border pt-4 space-y-3">
                  <h4 className="font-medium">Review Decision</h4>
                  
                  <Select value={reviewStatus} onValueChange={setReviewStatus}>
                    <SelectTrigger className="bg-muted border-border">
                      <SelectValue placeholder="Select decision..." />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="approved">Approve</SelectItem>
                      <SelectItem value="rejected">Reject</SelectItem>
                      <SelectItem value="more_info_needed">Request More Info</SelectItem>
                    </SelectContent>
                  </Select>
                  
                  {reviewStatus === 'rejected' && (
                    <Textarea
                      placeholder="Reason for rejection (shown to user)..."
                      value={rejectionReason}
                      onChange={(e) => setRejectionReason(e.target.value)}
                      className="bg-muted border-border"
                    />
                  )}
                  
                  <Textarea
                    placeholder="Internal admin notes..."
                    value={adminNotes}
                    onChange={(e) => setAdminNotes(e.target.value)}
                    className="bg-muted border-border"
                  />
                  
                  <Button
                    onClick={() => handleReviewVerification(selectedVerification.id)}
                    disabled={!reviewStatus || actionLoading}
                    className={`w-full ${
                      reviewStatus === 'approved' ? 'bg-green-500 hover:bg-green-600' :
                      reviewStatus === 'rejected' ? 'bg-red-500 hover:bg-red-600' :
                      'bg-blue-500 hover:bg-blue-600'
                    }`}
                  >
                    {actionLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                    {reviewStatus === 'approved' ? 'Approve Verification' :
                     reviewStatus === 'rejected' ? 'Reject Verification' :
                     reviewStatus === 'more_info_needed' ? 'Request More Info' :
                     'Submit Review'}
                  </Button>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Fraud Alert Detail Modal */}
      <Dialog open={showAlertDetail} onOpenChange={setShowAlertDetail}>
        <DialogContent className="bg-card border-border text-foreground max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <AlertTriangle className="w-5 h-5 text-red-400" />
              Fraud Alert Details
            </DialogTitle>
          </DialogHeader>
          
          {selectedAlert && (
            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <SeverityBadge severity={selectedAlert.severity} />
                <StatusBadge status={selectedAlert.status} />
                <Badge variant="outline" className="capitalize">
                  {selectedAlert.alert_type?.replace(/_/g, ' ')}
                </Badge>
              </div>
              
              <div>
                <p className="font-medium text-lg">{selectedAlert.title}</p>
                <p className="text-muted-foreground mt-1">{selectedAlert.description}</p>
              </div>
              
              <div className="flex items-center gap-3 p-3 bg-muted rounded-lg">
                <Avatar>
                  <AvatarImage src={getFullUrl(selectedAlert.user?.avatar_url)} />
                  <AvatarFallback>{selectedAlert.user?.full_name?.[0]}</AvatarFallback>
                </Avatar>
                <div>
                  <p className="font-medium">{selectedAlert.user?.full_name}</p>
                  <p className="text-sm text-muted-foreground">{selectedAlert.user?.email}</p>
                </div>
                <div className="ml-auto text-right">
                  <p className="text-sm text-gray-500">Risk Score</p>
                  <p className={`text-xl font-bold ${
                    selectedAlert.risk_score >= 80 ? 'text-red-400' :
                    selectedAlert.risk_score >= 50 ? 'text-orange-400' :
                    'text-yellow-400'
                  }`}>{selectedAlert.risk_score}</p>
                </div>
              </div>
              
              {selectedAlert.status === 'open' && (
                <div className="space-y-3 border-t border-border pt-4">
                  <Select value={actionTaken} onValueChange={setActionTaken}>
                    <SelectTrigger className="bg-muted border-border">
                      <SelectValue placeholder="Select action..." />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">No Action</SelectItem>
                      <SelectItem value="warning">Send Warning</SelectItem>
                      <SelectItem value="suspended">Suspend User</SelectItem>
                      <SelectItem value="banned">Ban User</SelectItem>
                    </SelectContent>
                  </Select>
                  
                  <Textarea
                    placeholder="Resolution notes..."
                    value={resolutionNotes}
                    onChange={(e) => setResolutionNotes(e.target.value)}
                    className="bg-muted border-border"
                  />
                  
                  <Button
                    onClick={() => handleResolveFraudAlert(selectedAlert.id)}
                    disabled={!actionTaken || actionLoading}
                    className="w-full bg-red-500 hover:bg-red-600"
                  >
                    {actionLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                    Resolve Alert
                  </Button>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Violation Detail Dialog */}
      <Dialog open={showViolationDetail} onOpenChange={setShowViolationDetail}>
        <DialogContent className="bg-card border-border max-w-lg" data-testid="violation-detail-dialog">
          {selectedViolation && (
            <div className="space-y-4">
              <DialogHeader>
                <DialogTitle className="flex items-center gap-2 text-foreground">
                  <Gavel className="w-5 h-5 text-orange-400" />
                  Violation Details
                </DialogTitle>
              </DialogHeader>
              
              {/* Violation Info */}
              <div className="p-4 rounded-lg bg-muted space-y-3">
                <div className="flex items-center justify-between">
                  <Badge className={`${
                    selectedViolation.severity === 'critical' ? 'bg-red-500/20 text-red-400' :
                    selectedViolation.severity === 'severe' ? 'bg-orange-500/20 text-orange-400' :
                    selectedViolation.severity === 'moderate' ? 'bg-yellow-500/20 text-yellow-400' :
                    'bg-gray-500/20 text-muted-foreground'
                  }`}>
                    {selectedViolation.severity?.toUpperCase()}
                  </Badge>
                  <span className="text-xs text-muted-foreground">{formatDate(selectedViolation.created_at)}</span>
                </div>
                
                <h3 className="text-lg font-semibold text-foreground">{selectedViolation.title}</h3>
                
                <div className="grid grid-cols-2 gap-3 text-sm">
                  <div>
                    <p className="text-muted-foreground">Type</p>
                    <p className="text-foreground capitalize">{selectedViolation.violation_type?.replace(/_/g, ' ')}</p>
                  </div>
                  <div>
                    <p className="text-muted-foreground">Action Taken</p>
                    <p className="text-foreground capitalize">{selectedViolation.action_taken?.replace(/_/g, ' ')}</p>
                  </div>
                  <div>
                    <p className="text-muted-foreground">User ID</p>
                    <p className="text-foreground font-mono text-xs">{selectedViolation.user_id}</p>
                  </div>
                  {selectedViolation.distance_discrepancy_miles && (
                    <div>
                      <p className="text-muted-foreground">Distance Discrepancy</p>
                      <p className="text-red-400 font-bold">{selectedViolation.distance_discrepancy_miles} miles</p>
                    </div>
                  )}
                </div>
              </div>

              {/* Appeal Section */}
              {selectedViolation.appeal_status === 'pending' && (
                <div className="p-4 rounded-lg bg-orange-500/10 border border-orange-500/30 space-y-3">
                  <div className="flex items-center gap-2">
                    <Scale className="w-5 h-5 text-orange-400" />
                    <span className="font-medium text-orange-400">Appeal Pending Review</span>
                  </div>
                  
                  <Textarea
                    placeholder="Add notes for this appeal review..."
                    value={appealNotes}
                    onChange={(e) => setAppealNotes(e.target.value)}
                    className="bg-muted border-border text-foreground"
                    rows={3}
                  />
                  
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      className="flex-1 border-green-500 text-green-400 hover:bg-green-500/20"
                      onClick={() => handleReviewAppeal(selectedViolation.id, true)}
                      disabled={actionLoading}
                    >
                      {actionLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <ThumbsUp className="w-4 h-4 mr-2" />}
                      Approve Appeal
                    </Button>
                    <Button
                      variant="outline"
                      className="flex-1 border-red-500 text-red-400 hover:bg-red-500/20"
                      onClick={() => handleReviewAppeal(selectedViolation.id, false)}
                      disabled={actionLoading}
                    >
                      {actionLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <ThumbsDown className="w-4 h-4 mr-2" />}
                      Deny Appeal
                    </Button>
                  </div>
                </div>
              )}

              {/* Already Reviewed */}
              {selectedViolation.appeal_status && selectedViolation.appeal_status !== 'pending' && (
                <div className={`p-4 rounded-lg ${
                  selectedViolation.appeal_status === 'approved' ? 'bg-green-500/10 border border-green-500/30' : 'bg-red-500/10 border border-red-500/30'
                }`}>
                  <p className={selectedViolation.appeal_status === 'approved' ? 'text-green-400' : 'text-red-400'}>
                    Appeal {selectedViolation.appeal_status === 'approved' ? 'Approved' : 'Denied'}
                  </p>
                </div>
              )}

              <DialogFooter>
                <Button variant="outline" onClick={() => setShowViolationDetail(false)}>
                  Close
                </Button>
              </DialogFooter>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AdminP1Dashboard;

﻿import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import {
  DollarSign, TrendingUp, Percent, Gift, Flag as FlagIcon, Bell, BarChart3,
  Loader2, Plus, Check, Copy, Send,
  Users, Eye
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { Badge } from '../ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { Switch } from '../ui/switch';
import { toast } from 'sonner';
import logger from '../../utils/logger';


export const AdminP2Dashboard = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [activeSubTab, setActiveSubTab] = useState('revenue');
  const [loading, setLoading] = useState(true);
  
  // Revenue state
  const [revenueData, setRevenueData] = useState(null);
  const [cohortData, setCohortData] = useState(null);
  const [funnelData, setFunnelData] = useState(null);
  
  // Promo Codes state
  const [promoCodes, setPromoCodes] = useState([]);
  const [showCreatePromo, setShowCreatePromo] = useState(false);
  const [newPromo, setNewPromo] = useState({
    code: '',
    code_type: 'percentage',
    discount_value: 10,
    max_uses: null,
    campaign_name: ''
  });
  
  // Feature Flags state
  const [featureFlags, setFeatureFlags] = useState([]);
  const [showCreateFlag, setShowCreateFlag] = useState(false);
  const [newFlag, setNewFlag] = useState({
    key: '',
    name: '',
    description: '',
    rollout_percentage: 0,
    category: 'general'
  });
  
  // Notification Campaigns state
  const [campaigns, setCampaigns] = useState([]);
  const [showCreateCampaign, setShowCreateCampaign] = useState(false);
  const [newCampaign, setNewCampaign] = useState({
    name: '',
    title: '',
    body: '',
    target_all_users: false,
    target_roles: []
  });
  
  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  useEffect(() => {
    if (user?.id) {
      if (activeSubTab === 'revenue') {
        fetchRevenueData();
        fetchCohortData();
        fetchFunnelData();
      } else if (activeSubTab === 'promo') {
        fetchPromoCodes();
      } else if (activeSubTab === 'flags') {
        fetchFeatureFlags();
      } else if (activeSubTab === 'campaigns') {
        fetchCampaigns();
      }
    }
  }, [user?.id, activeSubTab]);

  const fetchRevenueData = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/admin/revenue/overview?days=30`);
      setRevenueData(response.data);
    } catch (error) {
      logger.error('Failed to load revenue data:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchCohortData = async () => {
    try {
      const response = await apiClient.get(`/admin/revenue/cohort?months=6`);
      setCohortData(response.data);
    } catch (error) {
      logger.error('Failed to load cohort data:', error);
    }
  };

  const fetchFunnelData = async () => {
    try {
      const response = await apiClient.get(`/admin/funnel/detailed?days=30`);
      setFunnelData(response.data);
    } catch (error) {
      logger.error('Failed to load funnel data:', error);
    }
  };

  const fetchPromoCodes = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/admin/promo-codes`);
      setPromoCodes(response.data.promo_codes || []);
    } catch (error) {
      toast.error('Failed to load promo codes');
    } finally {
      setLoading(false);
    }
  };

  const fetchFeatureFlags = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/admin/feature-flags`);
      setFeatureFlags(response.data.feature_flags || []);
    } catch (error) {
      toast.error('Failed to load feature flags');
    } finally {
      setLoading(false);
    }
  };

  const fetchCampaigns = async () => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/admin/notification-campaigns`);
      setCampaigns(response.data.campaigns || []);
    } catch (error) {
      toast.error('Failed to load campaigns');
    } finally {
      setLoading(false);
    }
  };

  const handleCreatePromo = async () => {
    if (!newPromo.code || !newPromo.discount_value) {
      toast.error('Please fill in required fields');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/promo-codes`, newPromo);
      toast.success('Promo code created');
      setShowCreatePromo(false);
      setNewPromo({ code: '', code_type: 'percentage', discount_value: 10, max_uses: null, campaign_name: '' });
      fetchPromoCodes();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to create promo code');
    } finally {
      setActionLoading(false);
    }
  };

  const handleTogglePromo = async (codeId) => {
    try {
      await apiClient.put(`/admin/promo-codes/${codeId}/toggle`);
      toast.success('Promo code updated');
      fetchPromoCodes();
    } catch (error) {
      toast.error('Failed to toggle promo code');
    }
  };

  const handleCreateFlag = async () => {
    if (!newFlag.key || !newFlag.name) {
      toast.error('Please fill in required fields');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/feature-flags`, newFlag);
      toast.success('Feature flag created');
      setShowCreateFlag(false);
      setNewFlag({ key: '', name: '', description: '', rollout_percentage: 0, category: 'general' });
      fetchFeatureFlags();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to create feature flag');
    } finally {
      setActionLoading(false);
    }
  };

  const handleToggleFlag = async (flagId, currentState) => {
    try {
      await apiClient.put(`/admin/feature-flags/${flagId}?is_enabled=${!currentState}`);
      toast.success('Feature flag updated');
      fetchFeatureFlags();
    } catch (error) {
      toast.error('Failed to toggle feature flag');
    }
  };

  const handleUpdateRollout = async (flagId, percentage) => {
    try {
      await apiClient.put(`/admin/feature-flags/${flagId}?rollout_percentage=${percentage}`);
      toast.success('Rollout updated');
      fetchFeatureFlags();
    } catch (error) {
      toast.error('Failed to update rollout');
    }
  };

  const handleCreateCampaign = async () => {
    if (!newCampaign.name || !newCampaign.title || !newCampaign.body) {
      toast.error('Please fill in required fields');
      return;
    }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/notification-campaigns`, newCampaign);
      toast.success('Campaign created');
      setShowCreateCampaign(false);
      setNewCampaign({ name: '', title: '', body: '', target_all_users: false, target_roles: [] });
      fetchCampaigns();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to create campaign');
    } finally {
      setActionLoading(false);
    }
  };

  const handleSendCampaign = async (campaignId) => {
    if (!confirm('Are you sure you want to send this campaign now?')) return;
    setActionLoading(true);
    try {
      const response = await apiClient.post(`/admin/notification-campaigns/${campaignId}/send`);
      toast.success(`Sent to ${response.data.total_sent} users`);
      fetchCampaigns();
    } catch (error) {
      toast.error('Failed to send campaign');
    } finally {
      setActionLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('en-US', {
      month: 'short', day: 'numeric', year: 'numeric'
    });
  };

  return (
    <div className="space-y-4" data-testid="admin-p2-dashboard">
      {/* Sub-tabs */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {[
          { id: 'revenue', label: 'Revenue & Cohorts', icon: DollarSign },
          { id: 'promo', label: 'Promo Codes', icon: Gift },
          { id: 'flags', label: 'Feature Flags', icon: FlagIcon },
          { id: 'campaigns', label: 'Push Campaigns', icon: Bell },
        ].map(tab => (
          <Button
            key={tab.id}
            variant={activeSubTab === tab.id ? 'default' : 'outline'}
            size="sm"
            onClick={() => setActiveSubTab(tab.id)}
            className={activeSubTab === tab.id ? 'bg-green-500 hover:bg-green-600' : ''}
            data-testid={`p2-tab-${tab.id}`}
          >
            <tab.icon className="w-4 h-4 mr-1.5" />
            {tab.label}
          </Button>
        ))}
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
        </div>
      ) : (
        <>
          {/* REVENUE TAB */}
          {activeSubTab === 'revenue' && revenueData && (
            <div className="space-y-4">
              {/* Key Metrics */}
              <div className="grid grid-cols-4 gap-3">
                <Card className={`${cardBgClass} border-green-500/30`}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className={`text-xs ${textSecondary}`}>GMV (30d)</p>
                        <p className="text-2xl font-bold text-green-400">
                          {formatCurrency(revenueData.gmv)}
                        </p>
                        <p className={`text-xs ${revenueData.gmv_change >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                          {revenueData.gmv_change >= 0 ? '+' : ''}{revenueData.gmv_change}% vs prev
                        </p>
                      </div>
                      <TrendingUp className="w-8 h-8 text-green-500/50" />
                    </div>
                  </CardContent>
                </Card>

                <Card className={`${cardBgClass} border-blue-500/30`}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className={`text-xs ${textSecondary}`}>Platform Revenue</p>
                        <p className="text-2xl font-bold text-blue-400">
                          {formatCurrency(revenueData.platform_revenue)}
                        </p>
                        <p className="text-xs text-gray-500">
                          {revenueData.take_rate}% take rate
                        </p>
                      </div>
                      <DollarSign className="w-8 h-8 text-blue-500/50" />
                    </div>
                  </CardContent>
                </Card>

                <Card className={`${cardBgClass} border-purple-500/30`}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className={`text-xs ${textSecondary}`}>MRR</p>
                        <p className="text-2xl font-bold text-purple-400">
                          {formatCurrency(revenueData.mrr)}
                        </p>
                        <p className="text-xs text-gray-500">Subscriptions</p>
                      </div>
                      <BarChart3 className="w-8 h-8 text-purple-500/50" />
                    </div>
                  </CardContent>
                </Card>

                <Card className={`${cardBgClass} border-orange-500/30`}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className={`text-xs ${textSecondary}`}>Conversion Rate</p>
                        <p className="text-2xl font-bold text-orange-400">
                          {funnelData?.overall_conversion_rate || 0}%
                        </p>
                        <p className="text-xs text-gray-500">Booking funnel</p>
                      </div>
                      <Percent className="w-8 h-8 text-orange-500/50" />
                    </div>
                  </CardContent>
                </Card>
              </div>

              {/* Revenue by Type */}
              <Card className={cardBgClass}>
                <CardHeader className="pb-2">
                  <CardTitle className={`text-sm ${textClass}`}>Revenue by Type</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-4 gap-2">
                    {Object.entries(revenueData.breakdown_by_type || {}).map(([type, data]) => (
                      <div key={type} className="p-3 bg-muted rounded-lg">
                        <p className="text-xs text-gray-500 capitalize">{type.replace(/_/g, ' ')}</p>
                        <p className="text-lg font-bold text-foreground">{formatCurrency(data.revenue)}</p>
                        <p className="text-xs text-muted-foreground">{data.transactions} txns</p>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              {/* Funnel */}
              {funnelData && (
                <Card className={cardBgClass}>
                  <CardHeader className="pb-2">
                    <CardTitle className={`text-sm ${textClass}`}>Booking Funnel</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-2">
                      {funnelData.funnel?.map((stage, _idx) => (
                        <div key={stage.stage} className="flex items-center gap-3">
                          <div className="w-32 text-xs text-muted-foreground">{stage.stage}</div>
                          <div className="flex-1 relative h-6 bg-muted rounded-full overflow-hidden">
                            <div 
                              className="absolute inset-y-0 left-0 bg-gradient-to-r from-green-500 to-teal-500 rounded-full transition-all"
                              style={{ width: `${stage.conversion_rate}%` }}
                            />
                            <span className="absolute inset-0 flex items-center justify-center text-xs text-foreground font-medium">
                              {stage.count} ({stage.conversion_rate}%)
                            </span>
                          </div>
                          {stage.drop_off > 0 && (
                            <div className="text-xs text-red-400">-{stage.drop_off}</div>
                          )}
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}

              {/* Cohort Analysis */}
              {cohortData?.cohorts && cohortData.cohorts.length > 0 && (
                <Card className={cardBgClass}>
                  <CardHeader className="pb-2">
                    <CardTitle className={`text-sm ${textClass}`}>Cohort Retention</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="overflow-x-auto">
                      <table className="w-full text-xs">
                        <thead>
                          <tr className="text-gray-500">
                            <th className="text-left p-2">Cohort</th>
                            <th className="text-center p-2">Size</th>
                            {[0,1,2,3,4,5].map(m => (
                              <th key={m} className="text-center p-2">M{m}</th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {cohortData.cohorts.slice(0, 6).map(cohort => (
                            <tr key={cohort.cohort_month} className="border-t border-border">
                              <td className="p-2 text-foreground">{cohort.cohort_month}</td>
                              <td className="p-2 text-center text-muted-foreground">{cohort.cohort_size}</td>
                              {[0,1,2,3,4,5].map(m => {
                                const retention = cohort.retention[`month_${m}`];
                                return (
                                  <td key={m} className="p-2 text-center">
                                    {retention !== undefined ? (
                                      <span className={`px-2 py-0.5 rounded ${
                                        retention >= 50 ? 'bg-green-500/20 text-green-400' :
                                        retention >= 25 ? 'bg-yellow-500/20 text-yellow-400' :
                                        'bg-red-500/20 text-red-400'
                                      }`}>
                                        {retention}%
                                      </span>
                                    ) : '-'}
                                  </td>
                                );
                              })}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>
          )}

          {/* PROMO CODES TAB */}
          {activeSubTab === 'promo' && (
            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <h3 className={`font-medium ${textClass}`}>Promo Codes</h3>
                <Button size="sm" onClick={() => setShowCreatePromo(true)} className="bg-green-500 hover:bg-green-600">
                  <Plus className="w-4 h-4 mr-1" /> Create Code
                </Button>
              </div>

              {promoCodes.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <Gift className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No promo codes yet</p>
                  </CardContent>
                </Card>
              ) : (
                promoCodes.map(promo => (
                  <Card key={promo.id} className={cardBgClass}>
                    <CardContent className="p-4">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                          <div className="p-2 bg-green-500/20 rounded-lg">
                            <Gift className="w-6 h-6 text-green-400" />
                          </div>
                          <div>
                            <div className="flex items-center gap-2">
                              <code className="text-lg font-bold text-foreground bg-muted px-2 py-0.5 rounded">
                                {promo.code}
                              </code>
                              <Button 
                                size="sm" 
                                variant="ghost" 
                                className="h-6 w-6 p-0"
                                onClick={() => { navigator.clipboard.writeText(promo.code); toast.success('Copied!'); }}
                              >
                                <Copy className="w-3 h-3" />
                              </Button>
                            </div>
                            <p className={`text-sm ${textSecondary}`}>
                              {promo.code_type === 'percentage' ? `${promo.discount_value}% off` :
                               promo.code_type === 'fixed_amount' ? `$${promo.discount_value} off` :
                               `${promo.discount_value} free credits`}
                              {promo.campaign_name && ` • ${promo.campaign_name}`}
                            </p>
                          </div>
                        </div>
                        
                        <div className="flex items-center gap-4">
                          <div className="text-right">
                            <p className="text-sm text-foreground">
                              {promo.current_uses} / {promo.max_uses || '∞'} uses
                            </p>
                            {promo.valid_until && (
                              <p className="text-xs text-gray-500">
                                Expires {formatDate(promo.valid_until)}
                              </p>
                            )}
                          </div>
                          <Switch
                            checked={promo.is_active}
                            onCheckedChange={() => handleTogglePromo(promo.id)}
                          />
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          )}

          {/* FEATURE FLAGS TAB */}
          {activeSubTab === 'flags' && (
            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <h3 className={`font-medium ${textClass}`}>Feature Flags</h3>
                <Button size="sm" onClick={() => setShowCreateFlag(true)} className="bg-blue-500 hover:bg-blue-600">
                  <Plus className="w-4 h-4 mr-1" /> Create Flag
                </Button>
              </div>

              {featureFlags.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <FlagIcon className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No feature flags yet</p>
                  </CardContent>
                </Card>
              ) : (
                featureFlags.map(flag => (
                  <Card key={flag.id} className={`${cardBgClass} ${flag.kill_switch_enabled ? 'border-red-500/50' : ''}`}>
                    <CardContent className="p-4">
                      <div className="flex items-center justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <code className="text-sm font-mono text-foreground bg-muted px-2 py-0.5 rounded">
                              {flag.key}
                            </code>
                            {flag.is_experiment && (
                              <Badge className="bg-purple-500/20 text-purple-400">Experiment</Badge>
                            )}
                            {flag.kill_switch_enabled && (
                              <Badge className="bg-red-500/20 text-red-400">Kill Switch ON</Badge>
                            )}
                          </div>
                          <p className={`text-sm ${textClass} mt-1`}>{flag.name}</p>
                          {flag.description && (
                            <p className={`text-xs ${textSecondary}`}>{flag.description}</p>
                          )}
                        </div>
                        
                        <div className="flex items-center gap-4">
                          {/* Rollout slider */}
                          <div className="flex items-center gap-2">
                            <span className="text-xs text-gray-500">Rollout:</span>
                            <input
                              type="range"
                              min="0"
                              max="100"
                              value={flag.rollout_percentage}
                              onChange={(e) => handleUpdateRollout(flag.id, parseInt(e.target.value))}
                              className="w-20 h-2 bg-input rounded-lg appearance-none cursor-pointer"
                            />
                            <span className="text-xs text-foreground w-8">{flag.rollout_percentage}%</span>
                          </div>
                          
                          <Switch
                            checked={flag.is_enabled}
                            onCheckedChange={() => handleToggleFlag(flag.id, flag.is_enabled)}
                          />
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          )}

          {/* PUSH CAMPAIGNS TAB */}
          {activeSubTab === 'campaigns' && (
            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <h3 className={`font-medium ${textClass}`}>Push Notification Campaigns</h3>
                <Button size="sm" onClick={() => setShowCreateCampaign(true)} className="bg-purple-500 hover:bg-purple-600">
                  <Plus className="w-4 h-4 mr-1" /> Create Campaign
                </Button>
              </div>

              {campaigns.length === 0 ? (
                <Card className={cardBgClass}>
                  <CardContent className="py-12 text-center">
                    <Bell className="w-12 h-12 mx-auto text-gray-500 mb-3" />
                    <p className={textSecondary}>No campaigns yet</p>
                  </CardContent>
                </Card>
              ) : (
                campaigns.map(campaign => (
                  <Card key={campaign.id} className={cardBgClass}>
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-1">
                            <p className={`font-medium ${textClass}`}>{campaign.name}</p>
                            <Badge className={`text-xs ${
                              campaign.status === 'sent' ? 'bg-green-500/20 text-green-400' :
                              campaign.status === 'scheduled' ? 'bg-blue-500/20 text-blue-400' :
                              campaign.status === 'cancelled' ? 'bg-gray-500/20 text-muted-foreground' :
                              'bg-yellow-500/20 text-yellow-400'
                            }`}>
                              {campaign.status}
                            </Badge>
                          </div>
                          <p className={`text-sm ${textSecondary}`}>
                            <strong>{campaign.title}</strong>: {campaign.body}
                          </p>
                          
                          {campaign.status === 'sent' && (
                            <div className="flex gap-4 mt-2 text-xs">
                              <span className="text-muted-foreground">
                                <Users className="w-3 h-3 inline mr-1" />
                                {campaign.stats.targeted} targeted
                              </span>
                              <span className="text-green-400">
                                <Check className="w-3 h-3 inline mr-1" />
                                {campaign.stats.delivered} delivered
                              </span>
                              <span className="text-blue-400">
                                <Eye className="w-3 h-3 inline mr-1" />
                                {campaign.stats.open_rate}% opened
                              </span>
                            </div>
                          )}
                        </div>
                        
                        <div className="shrink-0 flex flex-col items-end gap-2">
                          <p className={`text-xs ${textSecondary}`}>
                            {campaign.sent_at ? `Sent ${formatDate(campaign.sent_at)}` : 
                             campaign.scheduled_at ? `Scheduled ${formatDate(campaign.scheduled_at)}` :
                             formatDate(campaign.created_at)}
                          </p>
                          {campaign.status === 'draft' && (
                            <Button
                              size="sm"
                              onClick={() => handleSendCampaign(campaign.id)}
                              disabled={actionLoading}
                              className="bg-green-500 hover:bg-green-600"
                            >
                              <Send className="w-3 h-3 mr-1" /> Send Now
                            </Button>
                          )}
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          )}
        </>
      )}

      {/* Create Promo Code Modal */}
      <Dialog open={showCreatePromo} onOpenChange={setShowCreatePromo}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Create Promo Code</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm text-muted-foreground">Code</label>
              <Input
                value={newPromo.code}
                onChange={(e) => setNewPromo({ ...newPromo, code: e.target.value.toUpperCase() })}
                placeholder="SUMMER2026"
                className="bg-muted border-border mt-1"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm text-muted-foreground">Type</label>
                <Select value={newPromo.code_type} onValueChange={(v) => setNewPromo({ ...newPromo, code_type: v })}>
                  <SelectTrigger className="bg-muted border-border mt-1">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="percentage">Percentage Off</SelectItem>
                    <SelectItem value="fixed_amount">Fixed Amount</SelectItem>
                    <SelectItem value="free_credits">Free Credits</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-sm text-muted-foreground">
                  {newPromo.code_type === 'percentage' ? 'Percentage' : 'Amount'}
                </label>
                <Input
                  type="number"
                  value={newPromo.discount_value}
                  onChange={(e) => setNewPromo({ ...newPromo, discount_value: parseFloat(e.target.value) })}
                  className="bg-muted border-border mt-1"
                />
              </div>
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Max Uses (optional)</label>
              <Input
                type="number"
                value={newPromo.max_uses || ''}
                onChange={(e) => setNewPromo({ ...newPromo, max_uses: e.target.value ? parseInt(e.target.value) : null })}
                placeholder="Unlimited"
                className="bg-muted border-border mt-1"
              />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Campaign Name (optional)</label>
              <Input
                value={newPromo.campaign_name}
                onChange={(e) => setNewPromo({ ...newPromo, campaign_name: e.target.value })}
                placeholder="Summer Sale 2026"
                className="bg-muted border-border mt-1"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowCreatePromo(false)}>Cancel</Button>
            <Button onClick={handleCreatePromo} disabled={actionLoading} className="bg-green-500 hover:bg-green-600">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Create Feature Flag Modal */}
      <Dialog open={showCreateFlag} onOpenChange={setShowCreateFlag}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Create Feature Flag</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm text-muted-foreground">Key (snake_case)</label>
              <Input
                value={newFlag.key}
                onChange={(e) => setNewFlag({ ...newFlag, key: e.target.value.toLowerCase().replace(/\s/g, '_') })}
                placeholder="new_booking_flow"
                className="bg-muted border-border mt-1 font-mono"
              />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Name</label>
              <Input
                value={newFlag.name}
                onChange={(e) => setNewFlag({ ...newFlag, name: e.target.value })}
                placeholder="New Booking Flow"
                className="bg-muted border-border mt-1"
              />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Description</label>
              <Textarea
                value={newFlag.description}
                onChange={(e) => setNewFlag({ ...newFlag, description: e.target.value })}
                placeholder="What does this flag control?"
                className="bg-muted border-border mt-1"
              />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Initial Rollout %</label>
              <Input
                type="number"
                min="0"
                max="100"
                value={newFlag.rollout_percentage}
                onChange={(e) => setNewFlag({ ...newFlag, rollout_percentage: parseInt(e.target.value) })}
                className="bg-muted border-border mt-1"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowCreateFlag(false)}>Cancel</Button>
            <Button onClick={handleCreateFlag} disabled={actionLoading} className="bg-blue-500 hover:bg-blue-600">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Create Campaign Modal */}
      <Dialog open={showCreateCampaign} onOpenChange={setShowCreateCampaign}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Create Push Campaign</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm text-muted-foreground">Campaign Name</label>
              <Input
                value={newCampaign.name}
                onChange={(e) => setNewCampaign({ ...newCampaign, name: e.target.value })}
                placeholder="Summer Promo Announcement"
                className="bg-muted border-border mt-1"
              />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Notification Title</label>
              <Input
                value={newCampaign.title}
                onChange={(e) => setNewCampaign({ ...newCampaign, title: e.target.value })}
                placeholder="🏄 Don't miss out!"
                className="bg-muted border-border mt-1"
              />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Notification Body</label>
              <Textarea
                value={newCampaign.body}
                onChange={(e) => setNewCampaign({ ...newCampaign, body: e.target.value })}
                placeholder="Book your next session and get 20% off..."
                className="bg-muted border-border mt-1"
              />
            </div>
            <div className="flex items-center gap-2">
              <Switch
                checked={newCampaign.target_all_users}
                onCheckedChange={(v) => setNewCampaign({ ...newCampaign, target_all_users: v })}
              />
              <label className="text-sm text-muted-foreground">Send to all users</label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowCreateCampaign(false)}>Cancel</Button>
            <Button onClick={handleCreateCampaign} disabled={actionLoading} className="bg-purple-500 hover:bg-purple-600">
              {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AdminP2Dashboard;

import React, { useState, useEffect, useCallback } from 'react';
import { AlertTriangle, MapPin, Check, X, Loader2, RefreshCw, ExternalLink, MessageSquare } from 'lucide-react';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { useAuth } from '../../contexts/AuthContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { toast } from 'sonner';


/**
 * AdminPrecisionQueue - Queue of spots flagged for review
 * 
 * Features:
 * - List spots with >150m inland flag or unverified accuracy
 * - One-by-one review workflow
 * - Quick "Snap Offshore" action
 * - Photographer relocation suggestions
 */
export const AdminPrecisionQueue = () => {
  const { user } = useAuth();
  const [queue, setQueue] = useState([]);
  const [suggestions, setSuggestions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('queue'); // 'queue' | 'suggestions'
  const [processing, setProcessing] = useState(null);

  // Fetch queue
  const fetchQueue = useCallback(async () => {
    try {
      setLoading(true);
      const [queueRes, suggestionsRes] = await Promise.all([
        apiClient.get(`/admin/spots/queue`),
        apiClient.get(`/admin/spots/suggestions`)
      ]);
      setQueue(queueRes.data.queue);
      setSuggestions(suggestionsRes.data.suggestions);
    } catch (error) {
      toast.error('Failed to load queue');
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  useEffect(() => {
    if (user?.id) {
      fetchQueue();
    }
  }, [user?.id, fetchQueue]);

  // Quick move spot offshore (estimate 150m towards water)
  const handleSnapOffshore = async (spot) => {
    setProcessing(spot.id);
    try {
      // Calculate offshore direction (simple: move towards lower longitude for US East Coast)
      // This is a rough estimate - admin should refine manually
      const offsetLat = -0.001; // ~111m south (towards water for most US spots)
      const offsetLng = -0.001; // ~85m west
      
      await apiClient.put(
        `/admin/spots/${spot.id}/move`,
        { 
          latitude: spot.latitude + offsetLat, 
          longitude: spot.longitude + offsetLng,
          override_land_warning: true 
        }
      );
      
      toast.success(`Snapped ${spot.name} offshore`);
      fetchQueue();
    } catch (error) {
      toast.error('Failed to move spot');
    } finally {
      setProcessing(null);
    }
  };

  // Apply photographer suggestion
  const handleApplySuggestion = async (suggestion) => {
    setProcessing(suggestion.id);
    try {
      await apiClient.put(
        `/admin/spots/${suggestion.spot_id}/move`,
        { 
          latitude: suggestion.suggested_coords.latitude, 
          longitude: suggestion.suggested_coords.longitude,
          override_land_warning: true 
        }
      );
      
      toast.success(`Applied suggestion for ${suggestion.spot_name}`);
      fetchQueue();
    } catch (error) {
      toast.error('Failed to apply suggestion');
    } finally {
      setProcessing(null);
    }
  };

  // Dismiss suggestion (keep current location)
  const handleDismissSuggestion = async (suggestion) => {
    setProcessing(suggestion.id);
    // For now, just remove from local state (could add API endpoint to mark as dismissed)
    setSuggestions(prev => prev.filter(s => s.id !== suggestion.id));
    setProcessing(null);
    toast.success('Suggestion dismissed');
  };

  // Open in map editor
  const openInEditor = (spot) => {
    // Navigate to spots tab with spot selected
    window.location.hash = `#spots?selected=${spot.id}`;
    toast.info(`Go to Spots tab to edit ${spot.name}`);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-bold text-foreground flex items-center gap-2">
            <AlertTriangle className="w-5 h-5 text-orange-400" />
            Precision Queue
          </h3>
          <p className="text-muted-foreground text-sm">Spots requiring coordinate verification</p>
        </div>
        <Button variant="outline" onClick={fetchQueue} className="border-input">
          <RefreshCw className="w-4 h-4 mr-2" />
          Refresh
        </Button>
      </div>

      {/* Tabs */}
      <div className="flex gap-2">
        <button
          onClick={() => setActiveTab('queue')}
          className={`px-4 py-2 rounded-lg font-medium transition-colors ${
            activeTab === 'queue'
              ? 'bg-orange-500 text-white'
              : 'bg-muted text-muted-foreground hover:text-foreground'
          }`}
        >
          Flagged ({queue.length})
        </button>
        <button
          onClick={() => setActiveTab('suggestions')}
          className={`px-4 py-2 rounded-lg font-medium transition-colors ${
            activeTab === 'suggestions'
              ? 'bg-cyan-500 text-white'
              : 'bg-muted text-muted-foreground hover:text-foreground'
          }`}
        >
          Suggestions ({suggestions.length})
        </button>
      </div>

      {/* Queue Tab */}
      {activeTab === 'queue' && (
        <div className="space-y-3">
          {queue.length === 0 ? (
            <div className="text-center py-12 bg-muted rounded-xl">
              <Check className="w-12 h-12 text-emerald-400 mx-auto mb-3" />
              <p className="text-foreground font-medium">All Clear!</p>
              <p className="text-muted-foreground text-sm">No spots require review</p>
            </div>
          ) : (
            queue.map((spot, index) => (
              <div
                key={spot.id}
                className="bg-muted rounded-xl p-4 flex items-center justify-between"
              >
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-full bg-orange-500/20 flex items-center justify-center text-orange-400 font-bold">
                    {index + 1}
                  </div>
                  <div>
                    <h4 className="text-foreground font-medium">{spot.name}</h4>
                    <p className="text-muted-foreground text-sm">{spot.region} • {spot.country}</p>
                    <p className="text-gray-500 text-xs">
                      ({spot.latitude.toFixed(4)}, {spot.longitude.toFixed(4)})
                    </p>
                  </div>
                </div>
                
                <div className="flex items-center gap-2">
                  <Badge className={`
                    ${spot.accuracy_flag === 'unverified' ? 'bg-gray-500' : ''}
                    ${spot.accuracy_flag === 'low_accuracy' ? 'bg-orange-500' : ''}
                    ${spot.flagged_for_review ? 'bg-red-500' : ''}
                  `}>
                    {spot.accuracy_flag || 'Flagged'}
                  </Badge>
                  
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleSnapOffshore(spot)}
                    disabled={processing === spot.id}
                    className="border-cyan-500 text-cyan-400"
                  >
                    {processing === spot.id ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <>
                        <MapPin className="w-4 h-4 mr-1" />
                        Snap Offshore
                      </>
                    )}
                  </Button>
                  
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => openInEditor(spot)}
                    className="border-input"
                  >
                    <ExternalLink className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {/* Suggestions Tab */}
      {activeTab === 'suggestions' && (
        <div className="space-y-3">
          {suggestions.length === 0 ? (
            <div className="text-center py-12 bg-muted rounded-xl">
              <MessageSquare className="w-12 h-12 text-muted-foreground mx-auto mb-3" />
              <p className="text-foreground font-medium">No Suggestions</p>
              <p className="text-muted-foreground text-sm">Photographers haven't submitted relocation suggestions yet</p>
            </div>
          ) : (
            suggestions.map((suggestion) => (
              <div
                key={suggestion.id}
                className="bg-muted rounded-xl p-4"
              >
                <div className="flex items-start justify-between">
                  <div>
                    <h4 className="text-foreground font-medium">{suggestion.spot_name}</h4>
                    <p className="text-muted-foreground text-sm">
                      Suggested by: {suggestion.photographer_name}
                    </p>
                    
                    <div className="mt-2 grid grid-cols-2 gap-4 text-xs">
                      <div className="bg-input/50 p-2 rounded">
                        <p className="text-gray-500">Current</p>
                        <p className="text-gray-300">
                          ({suggestion.current_coords.latitude.toFixed(4)}, {suggestion.current_coords.longitude.toFixed(4)})
                        </p>
                      </div>
                      <div className="bg-cyan-500/10 p-2 rounded border border-cyan-500/30">
                        <p className="text-cyan-400">Suggested</p>
                        <p className="text-foreground">
                          ({suggestion.suggested_coords.latitude.toFixed(4)}, {suggestion.suggested_coords.longitude.toFixed(4)})
                        </p>
                      </div>
                    </div>
                    
                    {suggestion.suggestion_note && (
                      <p className="text-muted-foreground text-sm mt-2 italic">
                        "{suggestion.suggestion_note}"
                      </p>
                    )}
                  </div>
                  
                  <div className="flex flex-col gap-2">
                    <Button
                      size="sm"
                      onClick={() => handleApplySuggestion(suggestion)}
                      disabled={processing === suggestion.id}
                      className="bg-emerald-500 hover:bg-emerald-600"
                    >
                      {processing === suggestion.id ? (
                        <Loader2 className="w-4 h-4 animate-spin" />
                      ) : (
                        <>
                          <Check className="w-4 h-4 mr-1" />
                          Apply
                        </>
                      )}
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleDismissSuggestion(suggestion)}
                      className="border-input text-muted-foreground"
                    >
                      <X className="w-4 h-4 mr-1" />
                      Dismiss
                    </Button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

export default AdminPrecisionQueue;

import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { 
  DollarSign, 
  Save, 
  RefreshCw, 
  Loader2, 
  Check, 
  X, 
  Edit2, 
  History,
  AlertCircle,
  ChevronDown,
  ChevronUp,
  Percent,
  Tag
} from 'lucide-react';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Badge } from '../ui/badge';
import { toast } from 'sonner';
import logger from '../../utils/logger';


// Role display config - matches all RoleEnum values
const ROLE_CONFIG = {
  surfer: { label: 'Surfer', color: 'bg-cyan-500/20 text-cyan-400', icon: '🏄' },
  grom: { label: 'Grom', color: 'bg-yellow-500/20 text-yellow-400', icon: '🐣' },
  photographer: { label: 'Photographer', color: 'bg-purple-500/20 text-purple-400', icon: '📷' },
  grom_parent: { label: 'Grom Parent', color: 'bg-blue-500/20 text-blue-400', icon: '👨‍👧' },
  hobbyist: { label: 'Hobbyist', color: 'bg-indigo-500/20 text-indigo-400', icon: '🔍' },
  comp_surfer: { label: 'Competition Surfer', color: 'bg-amber-500/20 text-amber-400', icon: '🏆' },
  pro_surfer: { label: 'Pro Surfer', color: 'bg-gold-500/20 text-yellow-400', icon: '⭐' },
  approved_pro_photographer: { label: 'Verified Pro Photographer', color: 'bg-blue-500/20 text-blue-400', icon: '📸' },
  surf_school: { label: 'Surf School / Coach', color: 'bg-teal-500/20 text-teal-400', icon: '🌬️' },
  shop: { label: 'Surf Shop', color: 'bg-pink-500/20 text-pink-400', icon: '🛍️' },
  shaper: { label: 'Shaper', color: 'bg-orange-500/20 text-orange-400', icon: '🛠️' },
  resort: { label: 'Resort / Retreat', color: 'bg-emerald-500/20 text-emerald-400', icon: '🌴' },
  wave_pool: { label: 'Wave Pool', color: 'bg-sky-500/20 text-sky-400', icon: '🌊' },
  destination: { label: 'Surf Destination', color: 'bg-rose-500/20 text-rose-400', icon: '📍' }
};

const TIER_LABELS = {
  tier_1: 'Free',
  tier_2: 'Basic',
  tier_3: 'Premium'
};

export const AdminPricingEditor = () => {
  const { user } = useAuth();
  const [pricing, setPricing] = useState(null);
  const [originalPricing, setOriginalPricing] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [version, setVersion] = useState(0);
  const [updatedAt, setUpdatedAt] = useState(null);
  const [isFromDb, setIsFromDb] = useState(false);
  const [expandedRoles, setExpandedRoles] = useState({});
  const [editingCell, setEditingCell] = useState(null);
  const [hasChanges, setHasChanges] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [history, setHistory] = useState([]);
  
  // Commission rates state
  const [commissionRates, setCommissionRates] = useState({
    free: 25,      // Free tier - 25% (Hobbyists)
    tier_1: 25,    // Same as free
    tier_2: 20,    // Basic - 20%
    tier_3: 15,    // Premium - 15%
  });
  const [_originalCommissionRates, setOriginalCommissionRates] = useState(null);
  const [commissionHasChanges, setCommissionHasChanges] = useState(false);

  // Surfer subscription discount rates state
  const [surferDiscountRates, setSurferDiscountRates] = useState({
    free: 0,       // Free tier - no discount
    tier_2: 10,    // Basic subscribers - 10% off media purchases
    tier_3: 20,    // Premium subscribers - 20% off media purchases
  });
  const [_originalSurferDiscountRates, setOriginalSurferDiscountRates] = useState(null);
  const [surferDiscountHasChanges, setSurferDiscountHasChanges] = useState(false);

  const fetchPricing = useCallback(async () => {
    try {
      const response = await apiClient.get(`/admin/pricing/config`);
      setPricing(response.data.pricing);
      setOriginalPricing(JSON.parse(JSON.stringify(response.data.pricing)));
      setVersion(response.data.version);
      setUpdatedAt(response.data.updated_at);
      setIsFromDb(response.data.is_from_db);
      setHasChanges(false);
    } catch (error) {
      logger.error('Failed to fetch pricing:', error);
      toast.error('Failed to load pricing configuration');
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  const fetchHistory = async () => {
    try {
      const response = await apiClient.get(`/admin/pricing/history?limit=10`);
      setHistory(response.data.history);
    } catch (error) {
      logger.error('Failed to fetch history:', error);
    }
  };

  useEffect(() => {
    if (user?.id) {
      fetchPricing();
    }
  }, [user?.id, fetchPricing]);

  const toggleRoleExpand = (roleKey) => {
    setExpandedRoles(prev => ({
      ...prev,
      [roleKey]: !prev[roleKey]
    }));
  };

  const handlePriceChange = (roleKey, tierKey, newPrice) => {
    // Ensure whole dollar only
    const price = Math.max(0, Math.floor(parseInt(newPrice) || 0));
    
    setPricing(prev => ({
      ...prev,
      [roleKey]: {
        ...prev[roleKey],
        tiers: {
          ...prev[roleKey].tiers,
          [tierKey]: {
            ...prev[roleKey].tiers[tierKey],
            price: price
          }
        }
      }
    }));
    setHasChanges(true);
  };

  const handleNameChange = (roleKey, tierKey, newName) => {
    setPricing(prev => ({
      ...prev,
      [roleKey]: {
        ...prev[roleKey],
        tiers: {
          ...prev[roleKey].tiers,
          [tierKey]: {
            ...prev[roleKey].tiers[tierKey],
            name: newName
          }
        }
      }
    }));
    setHasChanges(true);
  };

  const handleFeatureChange = (roleKey, tierKey, featureIndex, newFeature) => {
    setPricing(prev => {
      const newFeatures = [...prev[roleKey].tiers[tierKey].features];
      newFeatures[featureIndex] = newFeature;
      return {
        ...prev,
        [roleKey]: {
          ...prev[roleKey],
          tiers: {
            ...prev[roleKey].tiers,
            [tierKey]: {
              ...prev[roleKey].tiers[tierKey],
              features: newFeatures
            }
          }
        }
      };
    });
    setHasChanges(true);
  };
  
  // Commission rate change handler
  const handleCommissionRateChange = (tierKey, newRate) => {
    const rate = Math.min(100, Math.max(0, parseInt(newRate) || 0));
    setCommissionRates(prev => ({
      ...prev,
      [tierKey]: rate
    }));
    setCommissionHasChanges(true);
    setHasChanges(true);
  };

  // Surfer discount rate change handler
  const handleSurferDiscountChange = (tierKey, newRate) => {
    const rate = Math.min(100, Math.max(0, parseInt(newRate) || 0));
    setSurferDiscountRates(prev => ({
      ...prev,
      [tierKey]: rate
    }));
    setSurferDiscountHasChanges(true);
    setHasChanges(true);
  };
  
  // Save commission rates to localStorage (for now - can be migrated to DB later)
  const saveCommissionRates = () => {
    localStorage.setItem('admin_commission_rates', JSON.stringify(commissionRates));
    setOriginalCommissionRates({ ...commissionRates });
    setCommissionHasChanges(false);
  };

  // Save surfer discount rates to localStorage
  const saveSurferDiscountRates = () => {
    localStorage.setItem('admin_surfer_discount_rates', JSON.stringify(surferDiscountRates));
    setOriginalSurferDiscountRates({ ...surferDiscountRates });
    setSurferDiscountHasChanges(false);
  };
  
  // Load commission + surfer discount rates from localStorage
  useEffect(() => {
    const savedRates = localStorage.getItem('admin_commission_rates');
    if (savedRates) {
      const parsed = JSON.parse(savedRates);
      setCommissionRates(parsed);
      setOriginalCommissionRates(parsed);
    } else {
      setOriginalCommissionRates({ ...commissionRates });
    }
    const savedDiscounts = localStorage.getItem('admin_surfer_discount_rates');
    if (savedDiscounts) {
      const parsed = JSON.parse(savedDiscounts);
      setSurferDiscountRates(parsed);
      setOriginalSurferDiscountRates(parsed);
    } else {
      setOriginalSurferDiscountRates({ ...surferDiscountRates });
    }
  }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      const response = await apiClient.post(
        `/admin/pricing/update`,
        pricing
      );
      
      setPricing(response.data.pricing);
      setOriginalPricing(JSON.parse(JSON.stringify(response.data.pricing)));
      setVersion(response.data.version);
      setUpdatedAt(new Date().toISOString());
      setIsFromDb(true);
      setHasChanges(false);
      
      // Also save commission + surfer discount rates
      if (commissionHasChanges) {
        saveCommissionRates();
      }
      if (surferDiscountHasChanges) {
        saveSurferDiscountRates();
      }
      
      toast.success(`Pricing saved (v${response.data.version})`);
    } catch (error) {
      logger.error('Failed to save pricing:', error);
      toast.error('Failed to save pricing');
    } finally {
      setSaving(false);
    }
  };

  const handleReset = async () => {
    if (!window.confirm('Reset all pricing to default values? This cannot be undone.')) {
      return;
    }
    
    setSaving(true);
    try {
      const response = await apiClient.post(`/admin/pricing/reset`);
      
      setPricing(response.data.pricing);
      setOriginalPricing(JSON.parse(JSON.stringify(response.data.pricing)));
      setVersion(response.data.version);
      setUpdatedAt(new Date().toISOString());
      setIsFromDb(true);
      setHasChanges(false);
      
      toast.success('Pricing reset to defaults');
    } catch (error) {
      logger.error('Failed to reset pricing:', error);
      toast.error('Failed to reset pricing');
    } finally {
      setSaving(false);
    }
  };

  const handleDiscard = () => {
    setPricing(JSON.parse(JSON.stringify(originalPricing)));
    setHasChanges(false);
    setEditingCell(null);
    toast.info('Changes discarded');
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-yellow-400" />
      </div>
    );
  }

  return (
    <div className="space-y-6" data-testid="admin-pricing-editor">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
            <DollarSign className="w-6 h-6 text-green-400" />
            Pricing Configuration
          </h2>
          <p className="text-muted-foreground text-sm mt-1">
            Edit subscription prices in real-time. Changes apply immediately.
          </p>
        </div>
        
        <div className="flex items-center gap-2">
          <Badge className={isFromDb ? 'bg-green-500/20 text-green-400' : 'bg-yellow-500/20 text-yellow-400'}>
            {isFromDb ? `v${version}` : 'Default'}
          </Badge>
          {updatedAt && (
            <span className="text-xs text-muted-foreground">
              Updated: {new Date(updatedAt).toLocaleDateString()}
            </span>
          )}
        </div>
      </div>

      {/* Warning Banner */}
      {hasChanges && (
        <div className="bg-yellow-500/10 border border-yellow-500/30 rounded-lg p-4 flex items-center gap-3">
          <AlertCircle className="w-5 h-5 text-yellow-400 flex-shrink-0" />
          <div className="flex-1">
            <p className="text-yellow-400 font-medium">Unsaved Changes</p>
            <p className="text-muted-foreground text-sm">You have unsaved changes to the pricing configuration.</p>
          </div>
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="outline"
              onClick={handleDiscard}
              className="border-border text-muted-foreground"
            >
              <X className="w-4 h-4 mr-1" />
              Discard
            </Button>
            <Button
