                  onClick={() => setImportTier(tier.value)}
                  className={`p-3 rounded-lg border cursor-pointer transition-all ${
                    importTier === tier.value 
                      ? 'border-green-500 bg-green-500/10' 
                      : 'border-border bg-muted hover:border-input'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <div className={`flex-shrink-0 w-4 h-4 rounded-full border-2 flex items-center justify-center ${
                      importTier === tier.value ? 'border-green-500' : 'border-zinc-500'
                    }`}>
                      {importTier === tier.value && <div className="w-2 h-2 rounded-full bg-green-500" />}
                    </div>
                    <div>
                      <p className="text-foreground font-medium text-sm sm:text-base">{tier.label}</p>
                      <p className="text-xs text-muted-foreground">{tier.desc}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            
            <div className="flex items-start gap-2 p-3 bg-muted rounded-lg border border-border">
              <input
                type="checkbox"
                id="include-osm"
                checked={includeOSM}
                onChange={(e) => setIncludeOSM(e.target.checked)}
                className="mt-0.5 w-4 h-4 rounded border-input flex-shrink-0"
              />
              <label htmlFor="include-osm" className="text-sm text-gray-300 leading-tight">
                Also fetch from OSM Overpass API (slower, more spots)
              </label>
            </div>
          </div>
          
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowImportDialog(false)}
              className="border-input text-gray-300 hover:text-foreground"
            >
              Cancel
            </Button>
            <Button
              onClick={handleImport}
              disabled={importLoading}
              className="bg-green-600 hover:bg-green-700 text-white"
            >
              {importLoading ? (
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              ) : (
                <Upload className="w-4 h-4 mr-2" />
              )}
              Start Import
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Search & Filter */}
      <Card className="bg-card border-border">
        <CardContent className="pt-4">
          <div className="flex gap-2 mb-4">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search spots..."
                className="pl-10 bg-muted border-border text-foreground"
              />
            </div>
            <select
              value={filterCountry}
              onChange={(e) => setFilterCountry(e.target.value)}
              className="bg-muted border border-border rounded-lg px-3 text-foreground"
            >
              <option value="">All Countries</option>
              {countries.map(c => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>
          </div>

          {/* Spots List */}
          <div className="space-y-2 max-h-[500px] overflow-y-auto">
            {filteredSpots.slice(0, 50).map((spot) => (
              <div 
                key={spot.id} 
                className="flex items-center justify-between p-3 bg-muted rounded-lg hover:bg-input transition-colors"
              >
                <div className="flex-1">
                  <p className="text-foreground font-medium">{spot.name}</p>
                  <div className="flex items-center gap-2 text-xs text-muted-foreground">
                    <span>{spot.country || 'Unknown'}</span>
                    {spot.state_province && <span>• {spot.state_province}</span>}
                    {spot.region && <span>• {spot.region}</span>}
                    {spot.wave_type && (
                      <Badge className="bg-blue-500/20 text-blue-400 text-[10px]">
                        {spot.wave_type}
                      </Badge>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  {spot.is_verified_peak && (
                    <Badge className="bg-cyan-500/20 text-cyan-400 text-[10px]">
                      Verified
                    </Badge>
                  )}
                  <Badge className={spot.is_active ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}>
                    {spot.is_active ? 'Active' : 'Inactive'}
                  </Badge>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => openPrecisionPinMap(spot)}
                    className="text-cyan-400 hover:text-cyan-300"
                    title="Precision Pin - Drag to exact peak location"
                  >
                    <MapPin className="w-4 h-4" />
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => setEditingSpot(spot)}
                    className="text-muted-foreground hover:text-foreground"
                  >
                    <Settings className="w-4 h-4" />
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => handleDeleteSpot(spot.id, spot.name)}
                    className="text-red-400 hover:text-red-300"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            ))}
            {filteredSpots.length > 50 && (
              <p className="text-center text-gray-500 text-sm py-2">
                Showing 50 of {filteredSpots.length} spots
              </p>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Edit Spot Dialog */}
      <Dialog open={!!editingSpot} onOpenChange={() => setEditingSpot(null)}>
        <DialogContent className="bg-card border-border">
          <DialogHeader>
            <DialogTitle className="text-foreground">Edit Spot: {editingSpot?.name}</DialogTitle>
          </DialogHeader>
          {editingSpot && (
            <div className="modal-body px-4 sm:px-6 py-4 space-y-4">
              <div>
                <label className="text-sm text-muted-foreground">Name</label>
                <Input
                  value={editingSpot.name}
                  onChange={(e) => setEditingSpot({...editingSpot, name: e.target.value})}
                  className="bg-muted border-border text-foreground"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm text-muted-foreground">Country</label>
                  <Input
                    value={editingSpot.country || ''}
                    onChange={(e) => setEditingSpot({...editingSpot, country: e.target.value})}
                    className="bg-muted border-border text-foreground"
                  />
                </div>
                <div>
                  <label className="text-sm text-muted-foreground">State/Province</label>
                  <Input
                    value={editingSpot.state_province || ''}
                    onChange={(e) => setEditingSpot({...editingSpot, state_province: e.target.value})}
                    className="bg-muted border-border text-foreground"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm text-muted-foreground">Region</label>
                  <Input
                    value={editingSpot.region || ''}
                    onChange={(e) => setEditingSpot({...editingSpot, region: e.target.value})}
                    className="bg-muted border-border text-foreground"
                  />
                </div>
                <div>
                  <label className="text-sm text-muted-foreground">Wave Type</label>
                  <Input
                    value={editingSpot.wave_type || ''}
                    onChange={(e) => setEditingSpot({...editingSpot, wave_type: e.target.value})}
                    className="bg-muted border-border text-foreground"
                    placeholder="Beach Break, Point Break..."
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm text-muted-foreground">Latitude</label>
                  <Input
                    type="number"
                    step="0.0001"
                    value={editingSpot.latitude || ''}
                    onChange={(e) => setEditingSpot({...editingSpot, latitude: parseFloat(e.target.value)})}
                    className="bg-muted border-border text-foreground"
                  />
                </div>
                <div>
                  <label className="text-sm text-muted-foreground">Longitude</label>
                  <Input
                    type="number"
                    step="0.0001"
                    value={editingSpot.longitude || ''}
                    onChange={(e) => setEditingSpot({...editingSpot, longitude: parseFloat(e.target.value)})}
                    className="bg-muted border-border text-foreground"
                  />
                </div>
              </div>
              <div className="flex items-center justify-between">
                <label className="text-sm text-muted-foreground">Active</label>
                <Button
                  variant={editingSpot.is_active ? 'default' : 'outline'}
                  onClick={() => setEditingSpot({...editingSpot, is_active: !editingSpot.is_active})}
                  className={editingSpot.is_active ? 'bg-green-600' : 'border-input'}
                >
                  {editingSpot.is_active ? 'Active' : 'Inactive'}
                </Button>
              </div>
              <div className="flex gap-2 pt-2">
                <Button
                  onClick={() => handleUpdateSpot(editingSpot.id, editingSpot)}
                  className="flex-1 bg-cyan-600 hover:bg-cyan-700"
                >
                  Save Changes
                </Button>
                <Button
                  variant="outline"
                  onClick={() => setEditingSpot(null)}
                  className="border-input"
                >
                  Cancel
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Precision Pin Map Modal */}
      <Dialog open={precisionPinOpen} onOpenChange={() => { setPrecisionPinOpen(false); setPinMapSpot(null); }}>
        <DialogContent className="bg-card border-border max-w-3xl">
          <DialogHeader>
            <DialogTitle className="text-foreground flex items-center gap-2">
              <MapPin className="w-5 h-5 text-cyan-400" />
              Precision Pin: {pinMapSpot?.name}
            </DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4">
            {/* Instructions */}
            <div className="bg-cyan-500/10 border border-cyan-500/30 rounded-lg p-3">
              <p className="text-sm text-cyan-300">
                Drag the red pin to the exact peak location in the water. The satellite view helps you identify where waves actually break.
              </p>
            </div>
            
            {/* Map Layer Toggle */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Button
                  size="sm"
                  variant={mapLayer === 'satellite' ? 'default' : 'outline'}
                  onClick={() => mapLayer !== 'satellite' && toggleMapLayer()}
                  className={mapLayer === 'satellite' ? 'bg-cyan-600' : 'border-input'}
                >
                  Satellite
                </Button>
                <Button
                  size="sm"
                  variant={mapLayer === 'street' ? 'default' : 'outline'}
                  onClick={() => mapLayer !== 'street' && toggleMapLayer()}
                  className={mapLayer === 'street' ? 'bg-cyan-600' : 'border-input'}
                >
                  Street
                </Button>
              </div>
              
              {draggedPosition && (
                <div className="text-xs text-muted-foreground">
                  {draggedPosition.lat.toFixed(6)}, {draggedPosition.lng.toFixed(6)}
                </div>
              )}
            </div>
            
            {/* Map Container */}
            <div 
              ref={pinMapRef} 
              className="w-full h-[400px] rounded-lg border border-border overflow-hidden"
              style={{ background: '#1a1a1a' }}
            />
            
            {/* Original vs New Coordinates */}
            {pinMapSpot && draggedPosition && (
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div className="bg-muted rounded-lg p-3">
                  <p className="text-muted-foreground text-xs mb-1">Original Location</p>
                  <p className="text-foreground font-mono">
                    {pinMapSpot.latitude.toFixed(6)}, {pinMapSpot.longitude.toFixed(6)}
                  </p>
                </div>
                <div className="bg-cyan-500/10 border border-cyan-500/30 rounded-lg p-3">
                  <p className="text-cyan-400 text-xs mb-1">New Peak Location</p>
                  <p className="text-foreground font-mono">
                    {draggedPosition.lat.toFixed(6)}, {draggedPosition.lng.toFixed(6)}
                  </p>
                </div>
              </div>
            )}
            
            {/* Action Buttons */}
            <div className="flex gap-2 pt-2">
              <Button
                onClick={savePrecisionPin}
                className="flex-1 bg-gradient-to-r from-cyan-500 to-green-500 hover:from-cyan-600 hover:to-green-600"
              >
                <CheckCircle className="w-4 h-4 mr-2" />
                Verify & Save Peak Location
              </Button>
              <Button
                variant="outline"
                onClick={() => { setPrecisionPinOpen(false); setPinMapSpot(null); }}
                className="border-input"
              >
                Cancel
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};



export { AdminSpotsPanel };

﻿import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { Send, AlertTriangle,
  Loader2, RefreshCw, Search
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { Badge } from '../ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { toast } from 'sonner';
import logger from '../../utils/logger';


/**
 * Admin Support Dashboard - Ticketing System
 * - Centralized ticket management
 * - Ticket routing, prioritization, SLA tracking
 * - Response time metrics and CSAT tracking
 */
export const AdminSupportDashboard = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [loading, setLoading] = useState(true);
  const [tickets, setTickets] = useState([]);
  const [metrics, setMetrics] = useState(null);
  const [selectedTicket, setSelectedTicket] = useState(null);
  const [ticketDetail, setTicketDetail] = useState(null);
  
  // Filters
  const [statusFilter, setStatusFilter] = useState('all');
  const [priorityFilter, setPriorityFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  
  // Reply
  const [replyText, setReplyText] = useState('');
  const [isInternalNote, setIsInternalNote] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';
  const _textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  useEffect(() => {
    if (user?.id) {
      fetchTickets();
      fetchMetrics();
    }
  }, [user?.id, statusFilter, priorityFilter]);

  const fetchTickets = async () => {
    setLoading(true);
    try {
      let url = `/admin/support/tickets?limit=50`;
      if (statusFilter) url += `&status=${statusFilter}`;
      if (priorityFilter) url += `&priority=${priorityFilter}`;
      if (searchQuery) url += `&search=${encodeURIComponent(searchQuery)}`;
      
      const response = await apiClient.get(url);
      setTickets(response.data.tickets || []);
    } catch (error) {
      logger.error('Failed to load tickets:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchMetrics = async () => {
    try {
      const response = await apiClient.get(`/admin/support/metrics?days=30`);
      setMetrics(response.data);
    } catch (error) {
      logger.error('Failed to load metrics:', error);
    }
  };

  const fetchTicketDetail = async (ticketId) => {
    try {
      const response = await apiClient.get(`/admin/support/tickets/${ticketId}`);
      setTicketDetail(response.data);
    } catch (error) {
      toast.error('Failed to load ticket details');
    }
  };

  const handleUpdateTicket = async (ticketId, updates) => {
    setActionLoading(true);
    try {
      await apiClient.put(`/admin/support/tickets/${ticketId}`, updates);
      toast.success('Ticket updated');
      fetchTickets();
      if (ticketDetail?.id === ticketId) {
        fetchTicketDetail(ticketId);
      }
    } catch (error) {
      toast.error('Failed to update ticket');
    } finally {
      setActionLoading(false);
    }
  };

  const handleReply = async () => {
    if (!replyText.trim() || !ticketDetail) return;
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/support/tickets/${ticketDetail.id}/reply`, {
        message: replyText,
        is_internal_note: isInternalNote
      });
      toast.success(isInternalNote ? 'Note added' : 'Reply sent');
      setReplyText('');
      setIsInternalNote(false);
      fetchTicketDetail(ticketDetail.id);
    } catch (error) {
      toast.error('Failed to send reply');
    } finally {
      setActionLoading(false);
    }
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'urgent': return 'bg-red-500/20 text-red-400 border-red-500/50';
      case 'high': return 'bg-orange-500/20 text-orange-400 border-orange-500/50';
      case 'medium': return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/50';
      case 'low': return 'bg-green-500/20 text-green-400 border-green-500/50';
      default: return 'bg-gray-500/20 text-muted-foreground border-gray-500/50';
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'open': return 'bg-blue-500/20 text-blue-400';
      case 'in_progress': return 'bg-purple-500/20 text-purple-400';
      case 'waiting_user': return 'bg-yellow-500/20 text-yellow-400';
      case 'resolved': return 'bg-green-500/20 text-green-400';
      case 'closed': return 'bg-gray-500/20 text-muted-foreground';
      default: return 'bg-gray-500/20 text-muted-foreground';
    }
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('en-US', { 
      month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' 
    });
  };

  return (
    <div className="space-y-4" data-testid="admin-support-dashboard">
      {/* Metrics Row */}
      {metrics && (
        <div className="grid grid-cols-2 lg:grid-cols-5 gap-3">
          <Card className={`${cardBgClass} border-blue-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Open Tickets</p>
              <p className="text-2xl font-bold text-blue-400">{metrics.open_tickets}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-green-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Resolved ({`30d`})</p>
              <p className="text-2xl font-bold text-green-400">{metrics.resolved_tickets}</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-cyan-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Avg Response</p>
              <p className="text-2xl font-bold text-cyan-400">{metrics.avg_first_response_hours}h</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} border-purple-500/30`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">Avg Resolution</p>
              <p className="text-2xl font-bold text-purple-400">{metrics.avg_resolution_hours}h</p>
            </CardContent>
          </Card>
          <Card className={`${cardBgClass} ${metrics.sla_breached_count > 0 ? 'border-red-500/30' : 'border-green-500/30'}`}>
            <CardContent className="p-3">
              <p className="text-xs text-gray-500">SLA Breached</p>
              <p className={`text-2xl font-bold ${metrics.sla_breached_count > 0 ? 'text-red-400' : 'text-green-400'}`}>
                {metrics.sla_breached_count}
              </p>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-wrap gap-2 items-center">
        <div className="flex-1 min-w-[200px]">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
            <Input
              placeholder="Search tickets..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && fetchTickets()}
              className="pl-9 bg-muted border-border"
            />
          </div>
        </div>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-32 bg-muted border-border">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Status</SelectItem>
            <SelectItem value="open">Open</SelectItem>
            <SelectItem value="in_progress">In Progress</SelectItem>
            <SelectItem value="waiting_user">Waiting User</SelectItem>
            <SelectItem value="resolved">Resolved</SelectItem>
          </SelectContent>
        </Select>
        <Select value={priorityFilter} onValueChange={setPriorityFilter}>
          <SelectTrigger className="w-32 bg-muted border-border">
            <SelectValue placeholder="Priority" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Priority</SelectItem>
            <SelectItem value="urgent">Urgent</SelectItem>
            <SelectItem value="high">High</SelectItem>
            <SelectItem value="medium">Medium</SelectItem>
            <SelectItem value="low">Low</SelectItem>
          </SelectContent>
        </Select>
        <Button size="sm" variant="outline" onClick={fetchTickets}>
          <RefreshCw className="w-4 h-4" />
        </Button>
      </div>

      {/* Ticket List & Detail */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Ticket List */}
        <Card className={cardBgClass}>
          <CardHeader className="pb-2">
            <CardTitle className={`text-sm ${textClass}`}>
              Tickets ({tickets.length})
            </CardTitle>
          </CardHeader>
          <CardContent className="max-h-[500px] overflow-y-auto">
            {loading ? (
              <div className="flex justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
              </div>
            ) : tickets.length === 0 ? (
              <p className="text-center text-gray-500 py-8">No tickets found</p>
            ) : (
              <div className="space-y-2">
                {tickets.map(ticket => (
                  <div
                    key={ticket.id}
                    onClick={() => { setSelectedTicket(ticket.id); fetchTicketDetail(ticket.id); }}
                    className={`p-3 rounded-lg cursor-pointer transition-all ${
                      selectedTicket === ticket.id 
                        ? 'bg-cyan-500/10 border border-cyan-500/50' 
                        : 'bg-muted/50 hover:bg-muted border border-transparent'
                    }`}
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xs text-gray-500 font-mono">{ticket.ticket_number}</span>
                          <Badge className={`text-[10px] ${getPriorityColor(ticket.priority)}`}>
                            {ticket.priority}
                          </Badge>
                          {ticket.is_sla_breached && (
                            <AlertTriangle className="w-3 h-3 text-red-400" />
                          )}
                        </div>
                        <p className={`text-sm font-medium ${textClass} truncate`}>{ticket.subject}</p>
                        <p className="text-xs text-gray-500 truncate">{ticket.user_name} • {ticket.user_email}</p>
                      </div>
                      <Badge className={`text-[10px] ${getStatusColor(ticket.status)}`}>
                        {ticket.status?.replace('_', ' ')}
                      </Badge>
                    </div>
                    <p className="text-[10px] text-gray-500 mt-1">{formatDate(ticket.created_at)}</p>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Ticket Detail */}
        <Card className={cardBgClass}>
          <CardHeader className="pb-2">
            <CardTitle className={`text-sm ${textClass}`}>
              {ticketDetail ? `Ticket: ${ticketDetail.ticket_number}` : 'Select a Ticket'}
            </CardTitle>
          </CardHeader>
          <CardContent className="max-h-[500px] overflow-y-auto">
            {!ticketDetail ? (
              <p className="text-center text-gray-500 py-8">Select a ticket to view details</p>
            ) : (
              <div className="space-y-4">
                {/* Ticket Info */}
                <div className="p-3 bg-muted/50 rounded-lg">
                  <h4 className={`font-medium ${textClass}`}>{ticketDetail.subject}</h4>
                  <p className="text-sm text-muted-foreground mt-1">{ticketDetail.description}</p>
                  <div className="flex flex-wrap gap-2 mt-2">
                    <Badge className={getPriorityColor(ticketDetail.priority)}>{ticketDetail.priority}</Badge>
                    <Badge className={getStatusColor(ticketDetail.status)}>{ticketDetail.status?.replace('_', ' ')}</Badge>
                    <Badge variant="outline" className="text-xs">{ticketDetail.category}</Badge>
                  </div>
                </div>

                {/* Quick Actions */}
                <div className="flex flex-wrap gap-2">
                  <Select
                    value={ticketDetail.status}
                    onValueChange={(v) => handleUpdateTicket(ticketDetail.id, { status: v })}
                  >
                    <SelectTrigger className="w-28 h-8 text-xs bg-muted border-border">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="open">Open</SelectItem>
                      <SelectItem value="in_progress">In Progress</SelectItem>
                      <SelectItem value="waiting_user">Waiting User</SelectItem>
                      <SelectItem value="resolved">Resolved</SelectItem>
                      <SelectItem value="closed">Closed</SelectItem>
                    </SelectContent>
                  </Select>
                  <Select
                    value={ticketDetail.priority}
                    onValueChange={(v) => handleUpdateTicket(ticketDetail.id, { priority: v })}
                  >
                    <SelectTrigger className="w-24 h-8 text-xs bg-muted border-border">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="low">Low</SelectItem>
                      <SelectItem value="medium">Medium</SelectItem>
                      <SelectItem value="high">High</SelectItem>
                      <SelectItem value="urgent">Urgent</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                {/* Messages */}
                <div className="space-y-2">
                  <p className="text-xs text-gray-500">Conversation</p>
                  {ticketDetail.messages?.map(msg => (
                    <div
                      key={msg.id}
                      className={`p-2 rounded-lg ${
                        msg.is_internal_note 
                          ? 'bg-yellow-500/10 border border-yellow-500/30' 
                          : msg.sender_id === ticketDetail.user?.id
                            ? 'bg-muted'
                            : 'bg-cyan-500/10'
                      }`}
                    >
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-xs font-medium text-foreground">{msg.sender_name}</span>
                        {msg.is_internal_note && <Badge className="text-[10px] bg-yellow-500/20 text-yellow-400">Internal</Badge>}
                        <span className="text-[10px] text-gray-500">{formatDate(msg.created_at)}</span>
                      </div>
                      <p className="text-sm text-gray-300">{msg.message}</p>
                    </div>
                  ))}
                </div>

                {/* Reply */}
                <div className="space-y-2 pt-2 border-t border-border">
                  <Textarea
                    placeholder="Type your reply..."
                    value={replyText}
                    onChange={(e) => setReplyText(e.target.value)}
                    className="bg-muted border-border min-h-[80px]"
                  />
                  <div className="flex items-center justify-between">
                    <label className="flex items-center gap-2 text-xs text-muted-foreground cursor-pointer">
                      <input
                        type="checkbox"
                        checked={isInternalNote}
                        onChange={(e) => setIsInternalNote(e.target.checked)}
                        className="rounded border-input"
                      />
                      Internal note
                    </label>
                    <Button
                      size="sm"
                      onClick={handleReply}
                      disabled={actionLoading || !replyText.trim()}
                      className="bg-cyan-500 hover:bg-cyan-600"
                    >
                      {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4 mr-1" />}
                      {isInternalNote ? 'Add Note' : 'Send Reply'}
                    </Button>
                  </div>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default AdminSupportDashboard;

﻿import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import {
  Activity, Server, Database, Cpu, HardDrive,
  Loader2, RefreshCw, Check, X, AlertTriangle, Bell, CheckCircle, XCircle, AlertCircle
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Switch } from '../ui/switch';
import { toast } from 'sonner';
import logger from '../../utils/logger';


/**
 * Admin System Health Dashboard
 * - CPU, Memory, Disk usage
 * - Database performance
 * - Background job status
 * - System alerts
 */
export const AdminSystemDashboard = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [loading, setLoading] = useState(true);
  const [healthData, setHealthData] = useState(null);
  const [jobs, setJobs] = useState([]);
  const [alerts, setAlerts] = useState([]);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';

  useEffect(() => {
    if (user?.id) {
      fetchAllData();
      // Auto-refresh every 30 seconds
      const interval = setInterval(fetchAllData, 30000);
      return () => clearInterval(interval);
    }
  }, [user?.id]);

  const fetchAllData = async () => {
    try {
      const [healthRes, jobsRes, alertsRes] = await Promise.all([
        apiClient.get(`/admin/system/health`),
        apiClient.get(`/admin/system/jobs`),
        apiClient.get(`/admin/system/alerts`)
      ]);
      setHealthData(healthRes.data);
      setJobs(jobsRes.data.jobs || []);
      setAlerts(alertsRes.data.alerts || []);
    } catch (error) {
      logger.error('Failed to load system data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleToggleJob = async (jobName, currentState) => {
    try {
      await apiClient.put(`/admin/system/jobs/${jobName}/toggle`);
      toast.success(`Job ${currentState ? 'disabled' : 'enabled'}`);
      fetchAllData();
    } catch (error) {
      toast.error('Failed to toggle job');
    }
  };

  const handleAcknowledgeAlert = async (alertId) => {
    try {
      await apiClient.post(`/admin/system/alerts/acknowledge`, {
        alert_ids: [alertId]
      });
      toast.success('Alert acknowledged');
      fetchAllData();
    } catch (error) {
      toast.error('Failed to acknowledge alert');
    }
  };

  const handleResolveAlert = async (alertId) => {
    try {
      await apiClient.post(`/admin/system/alerts/${alertId}/resolve`);
      toast.success('Alert resolved');
      fetchAllData();
    } catch (error) {
      toast.error('Failed to resolve alert');
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'healthy': return 'text-green-400 bg-green-500/20';
      case 'warning': return 'text-yellow-400 bg-yellow-500/20';
      case 'critical': return 'text-red-400 bg-red-500/20';
      default: return 'text-muted-foreground bg-gray-500/20';
    }
  };

  const getJobStatusIcon = (status) => {
    switch (status) {
      case 'success': return <CheckCircle className="w-4 h-4 text-green-400" />;
      case 'failed': return <XCircle className="w-4 h-4 text-red-400" />;
      case 'running': return <Loader2 className="w-4 h-4 text-blue-400 animate-spin" />;
      default: return <AlertCircle className="w-4 h-4 text-muted-foreground" />;
    }
  };

  const formatBytes = (gb) => gb?.toFixed(1) + ' GB';

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
      </div>
    );
  }

  return (
    <div className="space-y-4" data-testid="admin-system-dashboard">
      {/* Overall Status */}
      {healthData && (
        <>
          <Card className={`${cardBgClass} border-l-4 ${
            healthData.overall_status === 'healthy' ? 'border-l-green-500' :
            healthData.overall_status === 'warning' ? 'border-l-yellow-500' : 'border-l-red-500'
          }`}>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Activity className={`w-8 h-8 ${
                    healthData.overall_status === 'healthy' ? 'text-green-400' :
                    healthData.overall_status === 'warning' ? 'text-yellow-400' : 'text-red-400'
                  }`} />
                  <div>
                    <p className="text-xs text-gray-500">System Status</p>
                    <p className={`text-2xl font-bold capitalize ${
                      healthData.overall_status === 'healthy' ? 'text-green-400' :
                      healthData.overall_status === 'warning' ? 'text-yellow-400' : 'text-red-400'
                    }`}>
                      {healthData.overall_status}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  {healthData.unacknowledged_alerts > 0 && (
                    <Badge className="bg-red-500/20 text-red-400">
                      <Bell className="w-3 h-3 mr-1" />
                      {healthData.unacknowledged_alerts} Alerts
                    </Badge>
                  )}
                  <Button size="sm" variant="outline" onClick={fetchAllData}>
                    <RefreshCw className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Resource Cards */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
            {healthData.components.map(comp => (
              <Card key={comp.name} className={`${cardBgClass} ${
                comp.status === 'healthy' ? 'border-green-500/30' :
                comp.status === 'warning' ? 'border-yellow-500/30' : 'border-red-500/30'
              }`}>
                <CardContent className="p-3">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-xs text-gray-500">{comp.name}</span>
                    {comp.name === 'CPU' && <Cpu className="w-4 h-4 text-gray-500" />}
                    {comp.name === 'Memory' && <Server className="w-4 h-4 text-gray-500" />}
                    {comp.name === 'Disk' && <HardDrive className="w-4 h-4 text-gray-500" />}
                    {comp.name === 'Database' && <Database className="w-4 h-4 text-gray-500" />}
                  </div>
                  <p className={`text-xl font-bold ${
                    comp.status === 'healthy' ? 'text-green-400' :
                    comp.status === 'warning' ? 'text-yellow-400' : 'text-red-400'
                  }`}>
                    {comp.value !== null ? `${comp.value}${comp.unit}` : 'N/A'}
                  </p>
                  <Badge className={`text-[10px] mt-1 ${getStatusColor(comp.status)}`}>
                    {comp.status}
                  </Badge>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Detailed System Info */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <Card className={cardBgClass}>
              <CardHeader className="pb-2">
                <CardTitle className={`text-sm ${textClass}`}>Memory Usage</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <div className="flex justify-between text-xs">
                    <span className="text-muted-foreground">Used</span>
                    <span className="text-foreground">{formatBytes(healthData.system.memory_used_gb)}</span>
                  </div>
                  <div className="h-2 bg-muted rounded-full overflow-hidden">
                    <div 
                      className={`h-full ${
                        healthData.system.memory_percent < 70 ? 'bg-green-500' :
                        healthData.system.memory_percent < 90 ? 'bg-yellow-500' : 'bg-red-500'
                      }`}
                      style={{ width: `${healthData.system.memory_percent}%` }}
                    />
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-muted-foreground">Total</span>
                    <span className="text-gray-500">{formatBytes(healthData.system.memory_total_gb)}</span>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className={cardBgClass}>
              <CardHeader className="pb-2">
                <CardTitle className={`text-sm ${textClass}`}>Disk Usage</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <div className="flex justify-between text-xs">
                    <span className="text-muted-foreground">Used</span>
                    <span className="text-foreground">{formatBytes(healthData.system.disk_used_gb)}</span>
                  </div>
                  <div className="h-2 bg-muted rounded-full overflow-hidden">
                    <div 
                      className={`h-full ${
                        healthData.system.disk_percent < 70 ? 'bg-green-500' :
                        healthData.system.disk_percent < 90 ? 'bg-yellow-500' : 'bg-red-500'
                      }`}
                      style={{ width: `${healthData.system.disk_percent}%` }}
                    />
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-muted-foreground">Total</span>
                    <span className="text-gray-500">{formatBytes(healthData.system.disk_total_gb)}</span>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </>
      )}

      {/* Background Jobs */}
      <Card className={cardBgClass}>
        <CardHeader className="pb-2">
          <CardTitle className={`text-sm ${textClass}`}>Background Jobs</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {jobs.map(job => (
              <div key={job.id} className="flex items-center justify-between p-2 bg-muted/50 rounded-lg">
                <div className="flex items-center gap-3">
                  {getJobStatusIcon(job.last_run_status)}
                  <div>
                    <p className={`text-sm font-medium ${textClass}`}>{job.job_name.replace(/_/g, ' ')}</p>
                    <p className="text-xs text-gray-500">{job.description}</p>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <div className="text-right">
                    <p className="text-xs text-muted-foreground">{job.schedule}</p>
                    {job.last_run_at && (
                      <p className="text-[10px] text-gray-500">
                        Last: {new Date(job.last_run_at).toLocaleString()}
                      </p>
                    )}
                  </div>
                  <Badge className={`text-[10px] ${
                    job.success_rate >= 90 ? 'bg-green-500/20 text-green-400' :
                    job.success_rate >= 70 ? 'bg-yellow-500/20 text-yellow-400' :
                    'bg-red-500/20 text-red-400'
                  }`}>
                    {job.success_rate}%
                  </Badge>
                  <Switch
                    checked={job.is_enabled}
                    onCheckedChange={() => handleToggleJob(job.job_name, job.is_enabled)}
                  />
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* System Alerts */}
      {alerts.length > 0 && (
        <Card className={`${cardBgClass} border-red-500/30`}>
          <CardHeader className="pb-2">
            <CardTitle className={`text-sm ${textClass} flex items-center gap-2`}>
              <AlertTriangle className="w-4 h-4 text-red-400" />
              System Alerts ({alerts.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {alerts.map(alert => (
                <div key={alert.id} className={`p-3 rounded-lg border ${
                  alert.severity === 'critical' ? 'bg-red-500/10 border-red-500/30' :
                  alert.severity === 'warning' ? 'bg-yellow-500/10 border-yellow-500/30' :
                  'bg-blue-500/10 border-blue-500/30'
                }`}>
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="flex items-center gap-2">
                        <Badge className={`text-[10px] ${
                          alert.severity === 'critical' ? 'bg-red-500/20 text-red-400' :
                          alert.severity === 'warning' ? 'bg-yellow-500/20 text-yellow-400' :
                          'bg-blue-500/20 text-blue-400'
                        }`}>
                          {alert.severity}
                        </Badge>
                        <span className="text-xs text-gray-500">{alert.alert_type}</span>
                      </div>
                      <p className={`text-sm font-medium ${textClass} mt-1`}>{alert.title}</p>
                      <p className="text-xs text-muted-foreground mt-0.5">{alert.message}</p>
                    </div>
                    <div className="flex gap-1">
                      {!alert.is_acknowledged && (
                        <Button size="sm" variant="outline" onClick={() => handleAcknowledgeAlert(alert.id)}>
                          <Check className="w-3 h-3" />
                        </Button>
                      )}
                      {!alert.is_resolved && (
                        <Button size="sm" variant="outline" onClick={() => handleResolveAlert(alert.id)}>
                          <X className="w-3 h-3" />
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default AdminSystemDashboard;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import {
  DollarSign, TrendingUp, Gift, Flag as FlagIcon, Bell, BarChart3,
  Loader2, Plus, RefreshCw, Send, Activity, Target, Zap,
  ArrowUpRight, ArrowDownRight, MapPin, Star, Clock, Heart
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { Badge } from '../ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { Switch } from '../ui/switch';
import { toast } from 'sonner';
import logger from '../../utils/logger';


/**
 * AdminUnifiedAnalytics - Enhanced Analytics Dashboard
 * Based on marketplace best practices research:
 * - LTV/CAC metrics
 * - Marketplace liquidity & health
 * - Supply/Demand balance
 * - Top performers
 * - Growth tools (promo codes, campaigns, feature flags)
 */
export const AdminUnifiedAnalytics = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const [activeSubTab, setActiveSubTab] = useState('overview');
  const [loading, setLoading] = useState(true);
  const [timeRange, setTimeRange] = useState('30d');
  
  // Overview/Metrics state
  const [revenueData, setRevenueData] = useState(null);
  const [ltvCacData, setLtvCacData] = useState(null);
  const [healthScore, setHealthScore] = useState(null);
  
  // Marketplace Health state
  const [liquidityData, setLiquidityData] = useState(null);
  const [supplyDemandData, setSupplyDemandData] = useState(null);
  const [topPerformers, setTopPerformers] = useState(null);
  
  // Funnel & Cohorts state
  const [funnelData, setFunnelData] = useState(null);
  const [cohortData, setCohortData] = useState(null);
  
  // Growth Tools state
  const [promoCodes, setPromoCodes] = useState([]);
  const [featureFlags, setFeatureFlags] = useState([]);
  const [campaigns, setCampaigns] = useState([]);
  
  // Modals
  const [showCreatePromo, setShowCreatePromo] = useState(false);
  const [showCreateFlag, setShowCreateFlag] = useState(false);
  const [showCreateCampaign, setShowCreateCampaign] = useState(false);
  
  const [newPromo, setNewPromo] = useState({ code: '', code_type: 'percentage', discount_value: 10, max_uses: null, campaign_name: '' });
  const [newFlag, setNewFlag] = useState({ key: '', name: '', description: '', rollout_percentage: 0, is_experiment: false });
  const [newCampaign, setNewCampaign] = useState({ name: '', title: '', body: '', target_all_users: true });
  
  const [actionLoading, setActionLoading] = useState(false);

  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-card/50 border-border';
  const textClass = isLight ? 'text-gray-900' : 'text-foreground';
  const textSecondary = isLight ? 'text-gray-600' : 'text-muted-foreground';

  const getDays = () => {
    switch(timeRange) {
      case '7d': return 7;
      case '90d': return 90;
      default: return 30;
    }
  };

  useEffect(() => {
    if (user?.id) {
      fetchDataForTab();
    }
  }, [user?.id, activeSubTab, timeRange]);

  const fetchDataForTab = async () => {
    setLoading(true);
    try {
      if (activeSubTab === 'overview') {
        await Promise.all([fetchOverviewData(), fetchHealthScore()]);
      } else if (activeSubTab === 'health') {
        await Promise.all([fetchLiquidityData(), fetchSupplyDemandData(), fetchTopPerformers()]);
      } else if (activeSubTab === 'funnel') {
        await Promise.all([fetchFunnelData(), fetchCohortData()]);
      } else if (activeSubTab === 'growth') {
        await Promise.all([fetchPromoCodes(), fetchFeatureFlags(), fetchCampaigns()]);
      }
    } catch (error) {
      logger.error('Failed to fetch data:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchOverviewData = async () => {
    const [revenueRes, ltvCacRes] = await Promise.all([
      apiClient.get(`/admin/revenue/overview?days=${getDays()}`),
      apiClient.get(`/admin/analytics/ltv-cac?days=${getDays() * 3}`)
    ]);
    setRevenueData(revenueRes.data);
    setLtvCacData(ltvCacRes.data);
  };

  const fetchHealthScore = async () => {
    const res = await apiClient.get(`/admin/analytics/health-score`);
    setHealthScore(res.data);
  };

  const fetchLiquidityData = async () => {
    const res = await apiClient.get(`/admin/analytics/liquidity?days=${getDays()}`);
    setLiquidityData(res.data);
  };

  const fetchSupplyDemandData = async () => {
    const res = await apiClient.get(`/admin/analytics/supply-demand?days=${getDays()}&limit=8`);
    setSupplyDemandData(res.data);
  };

  const fetchTopPerformers = async () => {
    const res = await apiClient.get(`/admin/analytics/top-performers?days=${getDays()}&limit=5`);
    setTopPerformers(res.data);
  };

  const fetchFunnelData = async () => {
    const res = await apiClient.get(`/admin/funnel/detailed?days=${getDays()}`);
    setFunnelData(res.data);
  };

  const fetchCohortData = async () => {
    const res = await apiClient.get(`/admin/revenue/cohort?months=6`);
    setCohortData(res.data);
  };

  const fetchPromoCodes = async () => {
    const res = await apiClient.get(`/admin/promo-codes`);
    setPromoCodes(res.data.promo_codes || []);
  };

  const fetchFeatureFlags = async () => {
    const res = await apiClient.get(`/admin/feature-flags`);
    setFeatureFlags(res.data.feature_flags || []);
  };

  const fetchCampaigns = async () => {
    const res = await apiClient.get(`/admin/notification-campaigns`);
    setCampaigns(res.data.campaigns || []);
  };

  // CRUD handlers
  const handleCreatePromo = async () => {
    if (!newPromo.code) { toast.error('Please enter a code'); return; }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/promo-codes`, newPromo);
      toast.success('Promo code created');
      setShowCreatePromo(false);
      setNewPromo({ code: '', code_type: 'percentage', discount_value: 10, max_uses: null, campaign_name: '' });
      fetchPromoCodes();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to create promo code');
    } finally {
      setActionLoading(false);
    }
  };

  const handleTogglePromo = async (codeId) => {
    try {
      await apiClient.put(`/admin/promo-codes/${codeId}/toggle`);
      fetchPromoCodes();
    } catch (error) {
      toast.error('Failed to toggle');
    }
  };

  const handleCreateFlag = async () => {
    if (!newFlag.key || !newFlag.name) { toast.error('Please fill required fields'); return; }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/feature-flags`, newFlag);
      toast.success('Feature flag created');
      setShowCreateFlag(false);
      setNewFlag({ key: '', name: '', description: '', rollout_percentage: 0, is_experiment: false });
      fetchFeatureFlags();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to create flag');
    } finally {
      setActionLoading(false);
    }
  };

  const handleToggleFlag = async (flagId, currentState) => {
    try {
      await apiClient.put(`/admin/feature-flags/${flagId}?is_enabled=${!currentState}`);
      fetchFeatureFlags();
    } catch (error) {
      toast.error('Failed to toggle');
    }
  };

  const handleCreateCampaign = async () => {
    if (!newCampaign.name || !newCampaign.title) { toast.error('Please fill required fields'); return; }
    setActionLoading(true);
    try {
      await apiClient.post(`/admin/notification-campaigns`, newCampaign);
      toast.success('Campaign created');
      setShowCreateCampaign(false);
      setNewCampaign({ name: '', title: '', body: '', target_all_users: true });
      fetchCampaigns();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to create campaign');
    } finally {
      setActionLoading(false);
    }
  };

  const handleSendCampaign = async (campaignId) => {
    if (!confirm('Send this campaign now?')) return;
    try {
      const res = await apiClient.post(`/admin/notification-campaigns/${campaignId}/send`);
      toast.success(`Sent to ${res.data.total_sent} users`);
      fetchCampaigns();
    } catch (error) {
      toast.error('Failed to send');
    }
  };

  const formatCurrency = (amount) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount || 0);
  const formatPercent = (value) => `${(value || 0).toFixed(1)}%`;

  const getStatusColor = (status) => {
    switch(status) {
      case 'healthy': case 'excellent': case 'good': return 'text-green-400 bg-green-500/20';
      case 'warning': case 'needs_attention': return 'text-yellow-400 bg-yellow-500/20';
      case 'critical': return 'text-red-400 bg-red-500/20';
      default: return 'text-muted-foreground bg-gray-500/20';
    }
  };

  const HealthIndicator = ({ score, status, label }) => (
    <div className="flex items-center gap-2">
      <div className={`w-2 h-2 rounded-full ${
        status === 'healthy' || status === 'excellent' || status === 'good' ? 'bg-green-400' :
        status === 'warning' || status === 'needs_attention' ? 'bg-yellow-400' : 'bg-red-400'
      }`} />
      <span className="text-xs text-muted-foreground">{label}</span>
      <span className={`text-xs font-medium ${
        status === 'healthy' || status === 'excellent' || status === 'good' ? 'text-green-400' :
        status === 'warning' || status === 'needs_attention' ? 'text-yellow-400' : 'text-red-400'
      }`}>{score}</span>
    </div>
  );

  return (
    <div className="space-y-4" data-testid="admin-unified-analytics">
      {/* Header with tabs and time range */}
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div className="flex gap-1.5 overflow-x-auto pb-1">
          {[
            { id: 'overview', label: 'Overview', icon: Activity },
            { id: 'health', label: 'Marketplace Health', icon: Heart },
            { id: 'funnel', label: 'Funnel & Retention', icon: BarChart3 },
            { id: 'growth', label: 'Growth Tools', icon: Zap },
          ].map(tab => (
            <Button
              key={tab.id}
              variant={activeSubTab === tab.id ? 'default' : 'outline'}
              size="sm"
              onClick={() => setActiveSubTab(tab.id)}
              className={`text-xs ${activeSubTab === tab.id ? 'bg-gradient-to-r from-cyan-500 to-teal-500 border-0' : ''}`}
              data-testid={`analytics-tab-${tab.id}`}
            >
              <tab.icon className="w-3.5 h-3.5 mr-1" />
              {tab.label}
            </Button>
          ))}
        </div>
        <div className="flex items-center gap-2">
          <Select value={timeRange} onValueChange={setTimeRange}>
            <SelectTrigger className="w-24 bg-muted border-border h-8 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="7d">7 days</SelectItem>
              <SelectItem value="30d">30 days</SelectItem>
              <SelectItem value="90d">90 days</SelectItem>
            </SelectContent>
          </Select>
          <Button size="sm" variant="outline" onClick={fetchDataForTab} className="h-8">
            <RefreshCw className="w-3.5 h-3.5" />
          </Button>
        </div>
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
        </div>
      ) : (
        <>
          {/* OVERVIEW TAB - Key KPIs + LTV/CAC + Health Score */}
          {activeSubTab === 'overview' && (
            <div className="space-y-4">
              {/* Health Score Card */}
              {healthScore && (
                <Card className={`${cardBgClass} border-l-4 ${
                  healthScore.status === 'excellent' || healthScore.status === 'good' ? 'border-l-green-500' :
                  healthScore.status === 'needs_attention' ? 'border-l-yellow-500' : 'border-l-red-500'
                }`}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="text-xs text-gray-500">Platform Health Score</p>
                        <div className="flex items-baseline gap-2">
                          <span className={`text-3xl font-bold ${
                            healthScore.status === 'excellent' || healthScore.status === 'good' ? 'text-green-400' :
                            healthScore.status === 'needs_attention' ? 'text-yellow-400' : 'text-red-400'
                          }`}>{healthScore.overall_score}</span>
                          <span className="text-sm text-gray-500">/ 100</span>
                          <Badge className={`ml-2 ${getStatusColor(healthScore.status)}`}>
                            {healthScore.status.replace('_', ' ')}
                          </Badge>
                        </div>
                      </div>
                      <div className="grid grid-cols-2 gap-x-6 gap-y-1">
                        <HealthIndicator 
                          score={healthScore.components.unit_economics.ltv_cac_ratio.toFixed(1) + ':1'} 
                          status={healthScore.components.unit_economics.status} 
                          label="LTV/CAC" 
                        />
                        <HealthIndicator 
                          score={formatPercent(healthScore.components.liquidity.match_rate)} 
                          status={healthScore.components.liquidity.status} 
                          label="Match Rate" 
                        />
                        <HealthIndicator 
                          score={healthScore.components.satisfaction.avg_rating.toFixed(1) + '?'} 
                          status={healthScore.components.satisfaction.status} 
                          label="Satisfaction" 
                        />
                        <HealthIndicator 
                          score={formatPercent(healthScore.components.retention.repeat_booking_rate)} 
                          status={healthScore.components.retention.status} 
                          label="Repeat Rate" 
                        />
                      </div>
                    </div>
                  </CardContent>
                </Card>
              )}

              {/* Key Metrics */}
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                {revenueData && (
                  <>
                    <Card className={`${cardBgClass} border-green-500/30`}>
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                          <div>
                            <p className={`text-xs ${textSecondary}`}>GMV ({timeRange})</p>
                            <p className="text-2xl font-bold text-green-400">{formatCurrency(revenueData.gmv)}</p>
                            <p className={`text-xs ${revenueData.gmv_change >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                              {revenueData.gmv_change >= 0 ? <ArrowUpRight className="inline w-3 h-3" /> : <ArrowDownRight className="inline w-3 h-3" />}
                              {Math.abs(revenueData.gmv_change)}% vs prev
                            </p>
                          </div>
                          <DollarSign className="w-8 h-8 text-green-500/30" />
                        </div>
                      </CardContent>
                    </Card>

                    <Card className={`${cardBgClass} border-blue-500/30`}>
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                          <div>
                            <p className={`text-xs ${textSecondary}`}>Platform Revenue</p>
                            <p className="text-2xl font-bold text-blue-400">{formatCurrency(revenueData.platform_revenue)}</p>
                            <p className="text-xs text-gray-500">{revenueData.take_rate}% take rate</p>
                          </div>
                          <TrendingUp className="w-8 h-8 text-blue-500/30" />
                        </div>
                      </CardContent>
                    </Card>
                  </>
                )}

                {ltvCacData && (
                  <>
                    <Card className={`${cardBgClass} ${ltvCacData.ltv_cac_ratio >= 3 ? 'border-green-500/30' : ltvCacData.ltv_cac_ratio >= 1 ? 'border-yellow-500/30' : 'border-red-500/30'}`}>
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                          <div>
                            <p className={`text-xs ${textSecondary}`}>LTV/CAC Ratio</p>
                            <p className={`text-2xl font-bold ${ltvCacData.ltv_cac_ratio >= 3 ? 'text-green-400' : ltvCacData.ltv_cac_ratio >= 1 ? 'text-yellow-400' : 'text-red-400'}`}>
                              {ltvCacData.ltv_cac_ratio.toFixed(1)}:1
                            </p>
                            <p className="text-xs text-gray-500">Target: 3:1+</p>
                          </div>
                          <Target className="w-8 h-8 text-purple-500/30" />
                        </div>
                      </CardContent>
                    </Card>

                    <Card className={`${cardBgClass} border-cyan-500/30`}>
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                          <div>
                            <p className={`text-xs ${textSecondary}`}>CAC Payback</p>
                            <p className="text-2xl font-bold text-cyan-400">{ltvCacData.cac_payback_months.toFixed(1)}mo</p>
                            <p className="text-xs text-gray-500">CAC: {formatCurrency(ltvCacData.cac)}</p>
                          </div>
                          <Clock className="w-8 h-8 text-cyan-500/30" />
                        </div>
                      </CardContent>
                    </Card>
                  </>
                )}
              </div>

              {/* LTV/CAC Details + Revenue Breakdown */}
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                {ltvCacData && (
                  <Card className={cardBgClass}>
                    <CardHeader className="pb-2">
                      <CardTitle className={`text-sm ${textClass}`}>Unit Economics</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="grid grid-cols-2 gap-3">
                        <div className="p-3 bg-muted/50 rounded-lg">
                          <p className="text-xs text-gray-500">Lifetime Value (LTV)</p>
                          <p className="text-xl font-bold text-foreground">{formatCurrency(ltvCacData.ltv)}</p>
                        </div>
                        <div className="p-3 bg-muted/50 rounded-lg">
                          <p className="text-xs text-gray-500">Acquisition Cost (CAC)</p>
                          <p className="text-xl font-bold text-foreground">{formatCurrency(ltvCacData.cac)}</p>
                        </div>
                        <div className="p-3 bg-muted/50 rounded-lg">
                          <p className="text-xs text-gray-500">ARPU</p>
                          <p className="text-lg font-bold text-foreground">{formatCurrency(ltvCacData.arpu)}</p>
                        </div>
                        <div className="p-3 bg-muted/50 rounded-lg">
                          <p className="text-xs text-gray-500">Churn Rate</p>
                          <p className="text-lg font-bold text-foreground">{ltvCacData.churn_rate}%</p>
                        </div>
                      </div>
                      <div className="mt-3 flex items-center justify-between text-xs">
                        <span className="text-gray-500">Active Users: {ltvCacData.active_users}</span>
                        <span className="text-gray-500">New Users: {ltvCacData.new_users}</span>
                      </div>
                    </CardContent>
                  </Card>
                )}

                {revenueData?.breakdown_by_type && (
                  <Card className={cardBgClass}>
                    <CardHeader className="pb-2">
                      <CardTitle className={`text-sm ${textClass}`}>Revenue by Type</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-2">
                        {Object.entries(revenueData.breakdown_by_type).slice(0, 6).map(([type, data]) => (
                          <div key={type} className="flex items-center justify-between p-2 bg-muted/50 rounded">
                            <span className="text-xs text-muted-foreground capitalize">{type.replace(/_/g, ' ')}</span>
                            <div className="text-right">
                              <span className="text-sm font-medium text-foreground">{formatCurrency(data.revenue)}</span>
                              <span className="text-xs text-gray-500 ml-2">({data.transactions} txns)</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>
                )}
              </div>
            </div>
          )}

          {/* MARKETPLACE HEALTH TAB */}
          {activeSubTab === 'health' && (
            <div className="space-y-4">
              {/* Liquidity Metrics */}
              {liquidityData && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
                  <Card className={`${cardBgClass} border-l-4 ${
                    liquidityData.health_status === 'healthy' ? 'border-l-green-500' :
                    liquidityData.health_status === 'warning' ? 'border-l-yellow-500' : 'border-l-red-500'
                  }`}>
                    <CardContent className="p-4">
                      <div className="flex items-center gap-3">
                        <div className="p-3 bg-gradient-to-br from-cyan-500/20 to-teal-500/20 rounded-lg">
                          <Activity className="w-6 h-6 text-cyan-400" />
                        </div>
                        <div>
                          <p className="text-xs text-gray-500">Liquidity Score</p>
                          <p className="text-2xl font-bold text-foreground">{liquidityData.liquidity_score}</p>
                          <Badge className={getStatusColor(liquidityData.health_status)}>
                            {liquidityData.health_status.replace('_', ' ')}
                          </Badge>
                        </div>
                      </div>
                    </CardContent>
                  </Card>

                  <Card className={cardBgClass}>
                    <CardContent className="p-4">
                      <p className="text-xs text-gray-500 mb-3">Supply Side</p>
                      <div className="space-y-2">
                        <div className="flex justify-between">
                          <span className="text-xs text-muted-foreground">Total Photographers</span>
                          <span className="text-sm font-medium text-foreground">{liquidityData.supply.total_photographers}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-xs text-muted-foreground">Active ({timeRange})</span>
                          <span className="text-sm font-medium text-green-400">{liquidityData.supply.active_photographers}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-xs text-muted-foreground">Utilization Rate</span>
                          <span className="text-sm font-medium text-cyan-400">{liquidityData.supply.utilization_rate}%</span>
                        </div>
                      </div>
                    </CardContent>
                  </Card>

                  <Card className={cardBgClass}>
                    <CardContent className="p-4">
                      <p className="text-xs text-gray-500 mb-3">Demand Side</p>
                      <div className="space-y-2">
                        <div className="flex justify-between">
                          <span className="text-xs text-muted-foreground">Total Bookings</span>
                          <span className="text-sm font-medium text-foreground">{liquidityData.demand.total_bookings}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-xs text-muted-foreground">Match Rate</span>
                          <span className="text-sm font-medium text-green-400">{liquidityData.demand.match_rate}%</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-xs text-muted-foreground">Completion Rate</span>
                          <span className="text-sm font-medium text-cyan-400">{liquidityData.demand.completion_rate}%</span>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </div>
              )}

              {/* Top Performers */}
              {topPerformers && (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                  <Card className={cardBgClass}>
                    <CardHeader className="pb-2">
                      <CardTitle className={`text-sm ${textClass} flex items-center gap-2`}>
                        <Star className="w-4 h-4 text-yellow-400" />
                        Top Photographers
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      {topPerformers.top_photographers.length === 0 ? (
                        <p className="text-xs text-gray-500 text-center py-4">No data for this period</p>
                      ) : (
                        <div className="space-y-2">
                          {topPerformers.top_photographers.map((p, idx) => (
                            <div key={p.id} className="flex items-center gap-3 p-2 bg-muted/50 rounded">
                              <span className={`w-5 h-5 flex items-center justify-center rounded-full text-xs font-bold ${
                                idx === 0 ? 'bg-yellow-500 text-black' : idx === 1 ? 'bg-gray-400 text-black' : idx === 2 ? 'bg-orange-600 text-white' : 'bg-input text-gray-300'
                              }`}>{idx + 1}</span>
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-foreground truncate">{p.name}</p>
                                <p className="text-xs text-gray-500">{p.bookings} bookings</p>
                              </div>
                              <span className="text-sm font-bold text-green-400">{formatCurrency(p.revenue)}</span>
                            </div>
                          ))}
                        </div>
                      )}
                    </CardContent>
                  </Card>

                  <Card className={cardBgClass}>
                    <CardHeader className="pb-2">
                      <CardTitle className={`text-sm ${textClass} flex items-center gap-2`}>
                        <MapPin className="w-4 h-4 text-blue-400" />
                        Top Spots
                      </CardTitle>
                    </CardHeader>
                    <CardContent>
                      {topPerformers.top_spots.length === 0 ? (
                        <p className="text-xs text-gray-500 text-center py-4">No data for this period</p>
                      ) : (
                        <div className="space-y-2">
                          {topPerformers.top_spots.map((s, idx) => (
                            <div key={s.id} className="flex items-center gap-3 p-2 bg-muted/50 rounded">
                              <span className={`w-5 h-5 flex items-center justify-center rounded-full text-xs font-bold ${
                                idx === 0 ? 'bg-blue-500 text-white' : 'bg-input text-gray-300'
                              }`}>{idx + 1}</span>
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-foreground truncate">{s.name}</p>
                                <p className="text-xs text-gray-500">{s.location}</p>
                              </div>
                              <span className="text-sm font-bold text-green-400">{formatCurrency(s.revenue)}</span>
                            </div>
                          ))}
                        </div>
                      )}
                    </CardContent>
                  </Card>
                </div>
              )}

              {/* Supply/Demand by Location */}
              {supplyDemandData && (
                <Card className={cardBgClass}>
                  <CardHeader className="pb-2">
                    <CardTitle className={`text-sm ${textClass}`}>Supply/Demand by Location</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex gap-4 mb-3 text-xs">
                      <span className="flex items-center gap-1">
                        <div className="w-2 h-2 rounded-full bg-green-400" /> Balanced
                      </span>
                      <span className="flex items-center gap-1">
                        <div className="w-2 h-2 rounded-full bg-yellow-400" /> Underserved
                      </span>
                      <span className="flex items-center gap-1">
                        <div className="w-2 h-2 rounded-full bg-blue-400" /> Oversupplied
                      </span>
                    </div>
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-2">
                      {supplyDemandData.spots.slice(0, 8).map(spot => (
                        <div key={spot.spot_id} className={`p-2 rounded border ${
                          spot.status === 'balanced' ? 'border-green-500/30 bg-green-500/5' :
                          spot.status === 'underserved' ? 'border-yellow-500/30 bg-yellow-500/5' :
                          spot.status === 'oversupplied' ? 'border-blue-500/30 bg-blue-500/5' :
                          'border-border bg-muted/50'
                        }`}>
                          <p className="text-xs font-medium text-foreground truncate">{spot.name}</p>
                          <p className="text-[10px] text-gray-500">{spot.country}</p>
                          <div className="flex justify-between mt-1 text-[10px]">
                            <span className="text-muted-foreground">D: {spot.demand}</span>
                            <span className="text-muted-foreground">S: {spot.supply}</span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>
          )}

          {/* FUNNEL & RETENTION TAB */}
          {activeSubTab === 'funnel' && (
            <div className="space-y-4">
              {/* Conversion Funnel */}
              {funnelData && (
                <Card className={cardBgClass}>
                  <CardHeader className="pb-2">
                    <CardTitle className={`text-sm ${textClass}`}>Booking Conversion Funnel</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-3">
                      {funnelData.funnel?.map((stage, _idx) => (
                        <div key={stage.stage} className="flex items-center gap-3">
                          <div className="w-32 text-xs text-muted-foreground">{stage.stage}</div>
                          <div className="flex-1 relative h-8 bg-muted rounded-full overflow-hidden">
                            <div 
                              className="absolute inset-y-0 left-0 bg-gradient-to-r from-cyan-500 to-teal-500 rounded-full transition-all"
                              style={{ width: `${stage.conversion_rate}%` }}
                            />
                            <span className="absolute inset-0 flex items-center justify-center text-xs text-foreground font-medium">
                              {stage.count} ({stage.conversion_rate}%)
                            </span>
                          </div>
                          {stage.drop_off > 0 && (
                            <div className="w-14 text-xs text-red-400 text-right">
                              <ArrowDownRight className="inline w-3 h-3" /> {stage.drop_off}
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}

              {/* Cohort Retention Heatmap */}
              {cohortData?.cohorts?.length > 0 && (
                <Card className={cardBgClass}>
                  <CardHeader className="pb-2">
                    <CardTitle className={`text-sm ${textClass}`}>Cohort Retention</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="overflow-x-auto">
                      <table className="w-full text-xs">
                        <thead>
                          <tr className="text-gray-500">
                            <th className="text-left p-2">Cohort</th>
                            <th className="text-center p-2">Size</th>
                            {[0,1,2,3,4,5].map(m => (
                              <th key={m} className="text-center p-2">M{m}</th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {cohortData.cohorts.slice(0, 6).map(cohort => (
                            <tr key={cohort.cohort_month} className="border-t border-border">
                              <td className="p-2 text-foreground font-medium">{cohort.cohort_month}</td>
                              <td className="p-2 text-center text-muted-foreground">{cohort.cohort_size}</td>
                              {[0,1,2,3,4,5].map(m => {
                                const retention = cohort.retention[`month_${m}`];
                                const bgOpacity = retention !== undefined ? Math.min(retention / 100, 1) : 0;
                                return (
                                  <td key={m} className="p-2 text-center">
                                    {retention !== undefined ? (
                                      <span 
                                        className="px-2 py-1 rounded text-foreground font-medium"
                                        style={{ 
                                          backgroundColor: `rgba(34, 211, 238, ${bgOpacity * 0.5})`,
                                          color: retention >= 50 ? '#fff' : retention >= 25 ? '#d1d5db' : '#9ca3af'
                                        }}
                                      >
                                        {retention}%
                                      </span>
                                    ) : <span className="text-gray-600">-</span>}
                                  </td>
                                );
                              })}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>
          )}

          {/* GROWTH TOOLS TAB */}
          {activeSubTab === 'growth' && (
            <div className="space-y-6">
              {/* Promo Codes */}
              <div>
                <div className="flex justify-between items-center mb-3">
                  <h3 className={`font-medium ${textClass}`}>Promo Codes</h3>
                  <Button size="sm" onClick={() => setShowCreatePromo(true)} className="bg-green-500 hover:bg-green-600">
                    <Plus className="w-4 h-4 mr-1" /> Create Code
                  </Button>
                </div>
                {promoCodes.length === 0 ? (
                  <Card className={cardBgClass}>
                    <CardContent className="py-8 text-center">
                      <Gift className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                      <p className={textSecondary}>No promo codes</p>
                    </CardContent>
                  </Card>
                ) : (
                  <div className="grid gap-2">
                    {promoCodes.map(p => (
                      <Card key={p.id} className={cardBgClass}>
                        <CardContent className="p-3 flex items-center justify-between">
                          <div className="flex items-center gap-3">
                            <Gift className="w-5 h-5 text-green-400" />
                            <div>
                              <code className="font-bold text-foreground bg-muted px-2 py-0.5 rounded text-sm">{p.code}</code>
                              <p className="text-xs text-gray-500 mt-0.5">
                                {p.code_type === 'percentage' ? `${p.discount_value}% off` : `$${p.discount_value} off`}
                                {p.campaign_name && ` � ${p.campaign_name}`}
                              </p>
                            </div>
                          </div>
                          <div className="flex items-center gap-3">
                            <span className="text-xs text-muted-foreground">{p.current_uses}/{p.max_uses || '8'}</span>
                            <Switch checked={p.is_active} onCheckedChange={() => handleTogglePromo(p.id)} />
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </div>

              {/* Feature Flags */}
              <div>
                <div className="flex justify-between items-center mb-3">
                  <h3 className={`font-medium ${textClass}`}>Feature Flags</h3>
                  <Button size="sm" onClick={() => setShowCreateFlag(true)} className="bg-blue-500 hover:bg-blue-600">
                    <Plus className="w-4 h-4 mr-1" /> Create Flag
                  </Button>
                </div>
                {featureFlags.length === 0 ? (
                  <Card className={cardBgClass}>
                    <CardContent className="py-8 text-center">
                      <FlagIcon className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                      <p className={textSecondary}>No feature flags</p>
                    </CardContent>
                  </Card>
                ) : (
                  <div className="grid gap-2">
                    {featureFlags.map(f => (
                      <Card key={f.id} className={cardBgClass}>
                        <CardContent className="p-3 flex items-center justify-between">
                          <div>
                            <code className="text-sm font-mono text-foreground bg-muted px-2 py-0.5 rounded">{f.key}</code>
                            <p className="text-sm text-gray-300 mt-1">{f.name}</p>
                            <p className="text-xs text-gray-500">Rollout: {f.rollout_percentage}%</p>
                          </div>
                          <Switch checked={f.is_enabled} onCheckedChange={() => handleToggleFlag(f.id, f.is_enabled)} />
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </div>

              {/* Push Campaigns */}
              <div>
                <div className="flex justify-between items-center mb-3">
                  <h3 className={`font-medium ${textClass}`}>Push Campaigns</h3>
                  <Button size="sm" onClick={() => setShowCreateCampaign(true)} className="bg-purple-500 hover:bg-purple-600">
                    <Plus className="w-4 h-4 mr-1" /> Create Campaign
                  </Button>
                </div>
                {campaigns.length === 0 ? (
                  <Card className={cardBgClass}>
                    <CardContent className="py-8 text-center">
                      <Bell className="w-10 h-10 mx-auto text-gray-500 mb-2" />
                      <p className={textSecondary}>No campaigns</p>
                    </CardContent>
                  </Card>
                ) : (
                  <div className="grid gap-2">
                    {campaigns.map(c => (
                      <Card key={c.id} className={cardBgClass}>
                        <CardContent className="p-3 flex items-center justify-between">
                          <div>
                            <div className="flex items-center gap-2">
                              <p className="font-medium text-foreground">{c.name}</p>
                              <Badge className={`text-xs ${
                                c.status === 'sent' ? 'bg-green-500/20 text-green-400' : 'bg-yellow-500/20 text-yellow-400'
                              }`}>{c.status}</Badge>
                            </div>
                            <p className="text-xs text-gray-500">{c.title}</p>
                          </div>
                          {c.status === 'draft' && (
                            <Button size="sm" onClick={() => handleSendCampaign(c.id)} className="bg-green-500 hover:bg-green-600">
                              <Send className="w-3 h-3 mr-1" /> Send
                            </Button>
                          )}
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}
        </>
      )}

      {/* Create Promo Modal */}
      <Dialog open={showCreatePromo} onOpenChange={setShowCreatePromo}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader><DialogTitle>Create Promo Code</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm text-muted-foreground">Code</label>
              <Input value={newPromo.code} onChange={(e) => setNewPromo({...newPromo, code: e.target.value.toUpperCase()})} placeholder="SUMMER2026" className="bg-muted border-border mt-1" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm text-muted-foreground">Type</label>
                <Select value={newPromo.code_type} onValueChange={(v) => setNewPromo({...newPromo, code_type: v})}>
                  <SelectTrigger className="bg-muted border-border mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="percentage">Percentage Off</SelectItem>
                    <SelectItem value="fixed_amount">Fixed Amount</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <label className="text-sm text-muted-foreground">{newPromo.code_type === 'percentage' ? 'Percentage' : 'Amount'}</label>
                <Input type="number" value={newPromo.discount_value} onChange={(e) => setNewPromo({...newPromo, discount_value: parseFloat(e.target.value) || 0})} className="bg-muted border-border mt-1" />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowCreatePromo(false)}>Cancel</Button>
            <Button onClick={handleCreatePromo} disabled={actionLoading} className="bg-green-500">{actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Create Flag Modal */}
      <Dialog open={showCreateFlag} onOpenChange={setShowCreateFlag}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader><DialogTitle>Create Feature Flag</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm text-muted-foreground">Key (snake_case)</label>
              <Input value={newFlag.key} onChange={(e) => setNewFlag({...newFlag, key: e.target.value.toLowerCase().replace(/\s/g, '_')})} placeholder="new_feature" className="bg-muted border-border mt-1 font-mono" />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Name</label>
              <Input value={newFlag.name} onChange={(e) => setNewFlag({...newFlag, name: e.target.value})} placeholder="New Feature" className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Rollout %</label>
              <Input type="number" min="0" max="100" value={newFlag.rollout_percentage} onChange={(e) => setNewFlag({...newFlag, rollout_percentage: parseInt(e.target.value) || 0})} className="bg-muted border-border mt-1" />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowCreateFlag(false)}>Cancel</Button>
            <Button onClick={handleCreateFlag} disabled={actionLoading} className="bg-blue-500">{actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Create'}</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Create Campaign Modal */}
      <Dialog open={showCreateCampaign} onOpenChange={setShowCreateCampaign}>
        <DialogContent className="bg-card border-border text-foreground">
          <DialogHeader><DialogTitle>Create Push Campaign</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm text-muted-foreground">Campaign Name</label>
              <Input value={newCampaign.name} onChange={(e) => setNewCampaign({...newCampaign, name: e.target.value})} placeholder="Summer Promo" className="bg-muted border-border mt-1" />
            </div>
            <div>
              <label className="text-sm text-muted-foreground">Notification Title</label>
              <Input value={newCampaign.title} onChange={(e) => setNewCampaign({...newCampaign, title: e.target.value})} placeholder="Don't miss out!" className="bg-muted border-border mt-1" />
            </div>
