import React, { useState } from 'react';
import { Calendar, Radio, LogOut, Loader2 } from 'lucide-react';
import { Card, CardContent } from '../ui/card';
import { Button } from '../ui/button';
import { useAuth } from '../../contexts/AuthContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { toast } from 'sonner';


export const LiveSessionsTab = ({
  liveSessions,
  onGoToLiveNow,
  onSessionLeft,
  userId,
  theme
}) => {
  const [leavingSession, setLeavingSession] = useState(null);
  const { updateUser } = useAuth();
  const isLight = theme === 'light';
  const cardBgClass = isLight ? 'bg-white border-gray-200' : 'bg-zinc-800/50 border-zinc-700';
  const textPrimaryClass = isLight ? 'text-gray-900' : 'text-white';
  const textSecondaryClass = isLight ? 'text-gray-600' : 'text-gray-400';

  const handleLeaveSession = async (sessionId) => {
    setLeavingSession(sessionId);
    try {
      const response = await apiClient.post(`/sessions/leave/${sessionId}`);
      
      // Check if refund was applied
      if (response.data.refunded) {
        toast.success(`Left early - $${response.data.refund_amount.toFixed(2)} refunded to credits!`, {
          duration: 5000
        });
        // Update user's credit balance in context
        if (response.data.new_balance !== undefined) {
          updateUser({ credit_balance: response.data.new_balance });
        }
      } else {
        toast.success('Left the session');
      }
      
      if (onSessionLeft) onSessionLeft(sessionId);
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to leave session');
    } finally {
      setLeavingSession(null);
    }
  };

  if (liveSessions.length === 0) {
    return (
      <Card className={`${cardBgClass} transition-colors duration-300`}>
        <CardContent className="py-12 text-center">
          <div className={`w-16 h-16 mx-auto mb-4 rounded-full ${isLight ? 'bg-gray-100' : 'bg-zinc-800'} flex items-center justify-center`}>
            <Calendar className={`w-8 h-8 ${textSecondaryClass}`} />
          </div>
          <h3 className={`text-lg font-medium ${textPrimaryClass} mb-2`}>No Live Sessions</h3>
          <p className={`${textSecondaryClass} mb-6`}>
            Jump into a live session from the Live Now tab.
          </p>
          <Button
            onClick={onGoToLiveNow}
            className="bg-gradient-to-r from-emerald-400 to-green-500 hover:from-emerald-500 hover:to-green-600 text-black font-medium"
            data-testid="see-live-photographers-btn"
          >
            See Live Photographers
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-3">
      {/* Refund policy note */}
      <p className={`text-xs ${textSecondaryClass} text-center`}>
        Leave within 10 min for automatic refund
      </p>
      
      {liveSessions.map((session) => (
        <Card key={session.id} className={`${cardBgClass} transition-colors duration-300`}>
          <CardContent className="p-4">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-green-500/20 flex items-center justify-center">
                <Radio className="w-6 h-6 text-green-400 animate-pulse" />
              </div>
              <div className="flex-1 min-w-0">
                <h3 className={`font-medium ${textPrimaryClass} truncate`}>
                  @{session.photographer_username || session.photographer_name || 'photographer'}
                </h3>
                <p className={`text-sm ${textSecondaryClass} truncate`}>{session.location}</p>
              </div>
              
              {/* Leave Session Button */}
              <Button
                onClick={() => handleLeaveSession(session.id)}
                disabled={leavingSession === session.id}
                variant="outline"
                size="sm"
                className="border-red-500/50 text-red-400 hover:bg-red-500/10 hover:text-red-300 shrink-0"
              >
                {leavingSession === session.id ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <>
                    <LogOut className="w-4 h-4 mr-1" />
                    Leave
                  </>
                )}
              </Button>
              
              <div className="text-right shrink-0">
                <p className="text-green-400 font-bold">${session.amount_paid}</p>
                <p className={`text-xs ${textSecondaryClass}`}>paid</p>
              </div>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
};

export default LiveSessionsTab;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  RefreshCw, Camera, Video, Zap, Calendar, Loader2, Check, 
  CreditCard, Coins, Percent, Clock, X, ChevronRight
} from 'lucide-react';
import { Button } from '../ui/button';
import { useAuth } from '../../contexts/AuthContext';
import apiClient from '../../lib/apiClient';
import { toast } from 'sonner';
import { getFullUrl } from '../../utils/media';
import logger from '../../utils/logger';
import { useSearchParams } from 'react-router-dom';

export const SubscriptionsTab = () => {
  const { user, updateUser } = useAuth();
  const [searchParams] = useSearchParams();
  const [subscriptions, setSubscriptions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [cancelling, setCancelling] = useState(null);

  // Handle card payment return
  useEffect(() => {
    const subPayment = searchParams.get('sub_payment');
    const checkoutId = searchParams.get('checkout_session_id');
    if (subPayment === 'success' && checkoutId) {
      const completePayment = async () => {
        try {
          await apiClient.post(`/photo-subscriptions/complete-card-payment?checkout_session_id=${checkoutId}`);
          toast.success('Subscription activated!');
        } catch (err) {
          if (!err.response?.data?.detail?.includes('Already')) {
            toast.error('Failed to activate subscription');
          }
        }
      };
      completePayment();
    }
  }, [searchParams]);

  const fetchSubscriptions = useCallback(async () => {
    if (!user?.id) return;
    setLoading(true);
    try {
      const res = await apiClient.get(`/photo-subscriptions/my-subscriptions/${user.id}`);
      setSubscriptions(res.data || []);
    } catch (err) { logger.error('Failed to fetch subscriptions:', err); }
    finally { setLoading(false); }
  }, [user?.id]);

  useEffect(() => { fetchSubscriptions(); }, [fetchSubscriptions]);

  const handleCancel = async (subId) => {
    setCancelling(subId);
    try {
      await apiClient.post(`/photo-subscriptions/cancel/${subId}?surfer_id=${user.id}`);
      toast.success('Subscription cancelled. Access continues until expiry.');
      fetchSubscriptions();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to cancel');
    } finally { setCancelling(null); }
  };

  const handleRenew = async (sub) => {
    // Navigate to photographer's plans to re-subscribe
    // For now, call subscribe endpoint directly with credits if available
    if (!sub.plan_id) { toast.error('Plan no longer available'); return; }
    
    try {
      const res = await apiClient.post(
        `/photo-subscriptions/subscribe?surfer_id=${user.id}`,
        { plan_id: sub.plan_id, payment_method: 'credits', origin_url: window.location.origin }
      );
      if (res.data?.success) {
        if (res.data.remaining_credits !== undefined) {
          updateUser({ credit_balance: res.data.remaining_credits });
        }
        toast.success('Subscription renewed!');
        fetchSubscriptions();
      }
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to renew');
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-48">
        <Loader2 className="w-6 h-6 animate-spin text-violet-400" />
      </div>
    );
  }

  const activeSubs = subscriptions.filter(s => s.status === 'active');
  const expiredSubs = subscriptions.filter(s => s.status !== 'active').slice(0, 5);

  const QuotaBar = ({ icon: Icon, label, remaining, total, color }) => {
    const pct = total > 0 ? Math.max(0, (remaining / total) * 100) : 0;
    return (
      <div className="flex items-center gap-2">
        <Icon className="w-3.5 h-3.5 shrink-0" style={{ color }} />
        <div className="flex-1 min-w-0">
          <div className="flex justify-between items-center mb-0.5">
            <span className="text-[10px] text-muted-foreground">{label}</span>
            <span className="text-[10px] font-semibold" style={{ color }}>{remaining}/{total}</span>
          </div>
          <div className="w-full h-1.5 rounded-full bg-zinc-800 overflow-hidden">
            <div className="h-full rounded-full transition-all duration-500" style={{ width: `${pct}%`, background: color }} />
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-4">
      {/* Active Subscriptions */}
      {activeSubs.length > 0 ? (
        <div className="space-y-3">
          {activeSubs.map(sub => {
            const expiresAt = new Date(sub.expires_at);
            const now = new Date();
            const daysLeft = Math.max(0, Math.ceil((expiresAt - now) / (1000 * 60 * 60 * 24)));
            const isExpiringSoon = daysLeft <= 2;

            return (
              <div key={sub.id} className="rounded-xl overflow-hidden" style={{ background: 'rgba(39,39,42,0.6)', border: '1px solid rgba(139,92,246,0.3)' }}>
                {/* Photographer Header */}
                <div className="p-4 flex items-center gap-3" style={{ background: 'linear-gradient(135deg, rgba(139,92,246,0.1), rgba(6,182,212,0.05))' }}>
                  <div className="w-11 h-11 rounded-full bg-gradient-to-br from-violet-400 to-cyan-500 p-0.5">
                    <div className="w-full h-full rounded-full bg-zinc-900 flex items-center justify-center overflow-hidden">
                      {sub.photographer_avatar ? (
                        <img src={getFullUrl(sub.photographer_avatar)} className="w-full h-full object-cover" alt="" />
                      ) : (
                        <span className="text-violet-400 font-bold">{sub.photographer_name?.[0]}</span>
                      )}
                    </div>
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-semibold text-foreground truncate">{sub.photographer_name}</p>
                    <p className="text-xs text-muted-foreground">{sub.plan_name} • ${sub.plan_price}/{sub.plan_interval === 'weekly' ? 'wk' : 'mo'}</p>
                  </div>
                  <div className={`px-2 py-1 rounded-full text-[10px] font-bold ${isExpiringSoon ? 'bg-amber-500/20 text-amber-400' : 'bg-emerald-500/20 text-emerald-400'}`}>
                    {daysLeft}d left
                  </div>
                </div>

                {/* Quota Bars */}
                <div className="p-4 space-y-2.5">
                  {sub.photos_remaining > 0 ? (
                    <QuotaBar icon={Camera} label="Photos" remaining={sub.photos_remaining} total={sub.plan_price ? Math.max(sub.photos_remaining, 1) : 0} color="#06b6d4" />
                  ) : null}
                  {sub.videos_remaining > 0 && (
                    <QuotaBar icon={Video} label="Videos" remaining={sub.videos_remaining} total={Math.max(sub.videos_remaining, 1)} color="#a855f7" />
                  )}
                  {sub.live_session_buyins_remaining > 0 && (
                    <QuotaBar icon={Zap} label="Live Jump-Ins" remaining={sub.live_session_buyins_remaining} total={Math.max(sub.live_session_buyins_remaining, 1)} color="#ef4444" />
                  )}
                  {sub.sessions_remaining > 0 && (
                    <QuotaBar icon={Calendar} label="Sessions" remaining={sub.sessions_remaining} total={Math.max(sub.sessions_remaining, 1)} color="#3b82f6" />
                  )}

                  {/* Discounts */}
                  {(sub.booking_discount_pct > 0 || sub.on_demand_discount_pct > 0) && (
                    <div className="flex flex-wrap gap-1.5 pt-1">
                      {sub.booking_discount_pct > 0 && (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] bg-blue-500/10 text-blue-400 border border-blue-500/20">
                          <Percent className="w-2.5 h-2.5" /> {sub.booking_discount_pct}% off bookings
                        </span>
                      )}
                      {sub.on_demand_discount_pct > 0 && (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                          <Percent className="w-2.5 h-2.5" /> {sub.on_demand_discount_pct}% off on-demand
                        </span>
                      )}
                    </div>
                  )}
                </div>

                {/* Actions */}
                <div className="px-4 pb-4 flex gap-2">
                  {isExpiringSoon && (
                    <Button onClick={() => handleRenew(sub)} size="sm" className="flex-1 bg-gradient-to-r from-violet-500 to-cyan-500 text-white text-xs font-bold">
                      <RefreshCw className="w-3.5 h-3.5 mr-1" /> Renew
                    </Button>
                  )}
                  <button onClick={() => handleCancel(sub.id)} disabled={cancelling === sub.id} className="px-3 py-1.5 rounded-lg text-xs text-muted-foreground hover:text-red-400 hover:bg-red-500/10 transition-colors">
                    {cancelling === sub.id ? <Loader2 className="w-3 h-3 animate-spin" /> : 'Cancel'}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="text-center py-12 px-4">
          <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-violet-500/10 flex items-center justify-center">
            <RefreshCw className="w-8 h-8 text-violet-400" />
          </div>
          <h3 className="text-lg font-bold text-foreground mb-2">No Active Subscriptions</h3>
          <p className="text-muted-foreground text-sm mb-4 max-w-xs mx-auto">
            Subscribe to your favorite photographers for weekly or monthly bundles of photos, videos, and sessions at discounted rates.
          </p>
          <p className="text-xs text-muted-foreground">
            Visit a photographer's profile to see their available plans
          </p>
        </div>
      )}

      {/* Expired Subscriptions */}
      {expiredSubs.length > 0 && (
        <div>
          <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Past Subscriptions</h3>
          <div className="space-y-2">
            {expiredSubs.map(sub => (
              <div key={sub.id} className="flex items-center gap-3 p-3 rounded-lg bg-zinc-800/30 border border-zinc-800 opacity-60">
                <div className="w-9 h-9 rounded-full bg-zinc-700 flex items-center justify-center">
                  {sub.photographer_avatar ? (
                    <img src={getFullUrl(sub.photographer_avatar)} className="w-full h-full rounded-full object-cover" alt="" />
                  ) : (
                    <span className="text-xs text-muted-foreground font-bold">{sub.photographer_name?.[0]}</span>
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm text-foreground truncate">{sub.photographer_name}</p>
                  <p className="text-[10px] text-muted-foreground">{sub.plan_name} • {sub.status}</p>
                </div>
                <Button onClick={() => handleRenew(sub)} size="sm" variant="outline" className="text-xs border-zinc-700 text-muted-foreground hover:text-violet-400">
                  Resubscribe
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default SubscriptionsTab;

/**
 * CrewPaymentProgress - TICKET-003
 * Shows individual payment status per crew member
 * Allows captain to cover remaining shares to unlock media immediately
 */
import React, { useState, useEffect } from 'react';
import { 

  Check, Users, Loader2, 
  Send, AlertCircle, ChevronDown, ChevronUp, Shield
} from 'lucide-react';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Progress } from '../ui/progress';
import {

  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '../ui/tooltip';
import {

  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '../ui/collapsible';
import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { getFullUrl } from '../../utils/media';
import logger from '../../utils/logger';



/**
 * Individual crew member chip showing payment status
 */
const CrewMemberChip = ({ member, _isLight }) => {
  const isPaid = member.paid;
  
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <div 
            className={`
              flex items-center gap-2 px-2 py-1 rounded-full transition-all
              ${isPaid 
                ? 'bg-green-500/20 border border-green-500/30' 
                : 'bg-amber-500/20 border border-amber-500/30'
              }
            `}
            data-testid={`crew-member-${member.user_id}`}
          >
            {/* Avatar */}
            <div className="relative">
              <div className="w-6 h-6 rounded-full overflow-hidden bg-zinc-700">
                {member.avatar_url ? (
                  <img src={getFullUrl(member.avatar_url)} alt="" className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-xs text-zinc-400">
                    {member.name?.charAt(0) || '?'}
                  </div>
                )}
              </div>
              {/* Status indicator */}
              <div className={`absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-zinc-900 ${
                isPaid ? 'bg-green-500' : 'bg-amber-500'
              }`}>
                {isPaid && <Check className="w-2 h-2 text-white" />}
              </div>
            </div>
            
            {/* Name */}
            <span className={`text-xs font-medium ${isPaid ? 'text-green-400' : 'text-amber-400'}`}>
              {member.name?.split(' ')[0] || member.username || 'Crew'}
            </span>
          </div>
        </TooltipTrigger>
        <TooltipContent className="bg-zinc-800 border-zinc-700">
          <div className="text-xs">
            <p className="font-medium text-white">{member.name || member.username}</p>
            <p className={isPaid ? 'text-green-400' : 'text-amber-400'}>
              {isPaid ? `Paid $${member.share_amount?.toFixed(2) || '0.00'}` : `Owes $${member.share_amount?.toFixed(2) || '0.00'}`}
            </p>
            {isPaid && member.paid_at && (
              <p className="text-zinc-400 mt-1">
                {new Date(member.paid_at).toLocaleString()}
              </p>
            )}
          </div>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

/**
 * Main CrewPaymentProgress component
 */
export const CrewPaymentProgress = ({ 
  dispatchId,
  bookingId,
  serviceType = 'dispatch', // 'dispatch' or 'booking'
  currentUserId,
  isCaptain = false,
  onAllPaid,
  onRefresh,
  theme = 'dark',
  compact = false
}) => {
  const isLight = theme === 'light';
  const [crewMembers, setCrewMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [covering, setCovering] = useState(false);
  const [sendingReminder, setSendingReminder] = useState(null);
  const [isExpanded, setIsExpanded] = useState(!compact);
  
  const textPrimaryClass = isLight ? 'text-gray-900' : 'text-white';
  const textSecondaryClass = isLight ? 'text-gray-600' : 'text-zinc-400';
  const bgCardClass = isLight ? 'bg-gray-100' : 'bg-zinc-800';
  
  // Fetch crew payment status
  const fetchCrewStatus = async () => {
    try {
      const endpoint = serviceType === 'dispatch' 
        ? `/dispatch/${dispatchId}/crew-status`
        : `/bookings/${bookingId}/crew-status`;
      
      const response = await apiClient.get(endpoint);
      setCrewMembers(response.data.crew || response.data.participants || []);
      
      // Check if all paid
      const allPaid = response.data.all_participants_paid || 
        (response.data.crew?.every(m => m.paid) ?? false);
      if (allPaid && onAllPaid) {
        onAllPaid();
      }
    } catch (error) {
      logger.error('Failed to fetch crew status:', error);
    } finally {
      setLoading(false);
    }
  };
  
  useEffect(() => {
    if (dispatchId || bookingId) {
      fetchCrewStatus();
      // Poll every 10 seconds
      const interval = setInterval(fetchCrewStatus, 10000);
      return () => clearInterval(interval);
    }
  }, [dispatchId, bookingId]);
  
  // Calculate totals
  const paidCount = crewMembers.filter(m => m.paid).length;
  const totalCount = crewMembers.length;
  const paidAmount = crewMembers.filter(m => m.paid).reduce((sum, m) => sum + (m.share_amount || 0), 0);
  const totalAmount = crewMembers.reduce((sum, m) => sum + (m.share_amount || 0), 0);
  const unpaidAmount = totalAmount - paidAmount;
  const unpaidMembers = crewMembers.filter(m => !m.paid);
  const progressPercent = totalCount > 0 ? (paidCount / totalCount) * 100 : 0;
  
  // Cover remaining shares (captain only)
  const handleCoverRemaining = async () => {
    if (!isCaptain || unpaidAmount <= 0) return;
    
    setCovering(true);
    try {
      const endpoint = serviceType === 'dispatch'
        ? `/dispatch/${dispatchId}/cover-remaining`
        : `/bookings/${bookingId}/cover-remaining`;
      
      await apiClient.post(endpoint, { captain_id: currentUserId });
      
      toast.success(`Covered $${unpaidAmount.toFixed(2)} for your crew!`);
      await fetchCrewStatus();
      onRefresh?.();
    } catch (error) {
      const msg = error.response?.data?.detail || 'Failed to cover remaining amount';
      toast.error(msg);
    } finally {
      setCovering(false);
    }
  };
  
  // Send reminder to unpaid crew member
  const handleSendReminder = async (memberId) => {
    setSendingReminder(memberId);
    try {
      const endpoint = serviceType === 'dispatch'
        ? `/dispatch/${dispatchId}/remind-crew`
        : `/bookings/${bookingId}/remind-crew`;
      
      await apiClient.post(endpoint, { 
        captain_id: currentUserId,
        member_id: memberId 
      });
      
      toast.success('Reminder sent!');
    } catch (error) {
      toast.error('Failed to send reminder');
    } finally {
      setSendingReminder(null);
    }
  };
  
  if (loading) {
    return (
      <div className={`p-4 rounded-lg ${bgCardClass} flex items-center justify-center`}>
        <Loader2 className="w-5 h-5 animate-spin text-cyan-400" />
      </div>
    );
  }
  
  if (crewMembers.length === 0) {
    return null;
  }
  
  // All paid state
  if (paidCount === totalCount) {
    return (
      <div 
        className="p-3 rounded-lg bg-green-500/10 border border-green-500/30"
        data-testid="crew-payment-complete"
      >
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-full bg-green-500/20">
            <Check className="w-5 h-5 text-green-400" />
          </div>
          <div>
            <p className={`font-medium ${textPrimaryClass}`}>All Crew Paid!</p>
            <p className={`text-sm ${textSecondaryClass}`}>
              {totalCount} members � ${totalAmount.toFixed(2)} total
            </p>
          </div>
        </div>
      </div>
    );
  }
  
  // Compact mode for smaller UIs
  if (compact) {
    return (
      <Collapsible open={isExpanded} onOpenChange={setIsExpanded}>
        <CollapsibleTrigger asChild>
          <button 
            className={`w-full p-3 rounded-lg ${bgCardClass} hover:bg-opacity-80 transition-all`}
            data-testid="crew-payment-progress-compact"
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Users className="w-5 h-5 text-cyan-400" />
                <div className="text-left">
                  <p className={`text-sm font-medium ${textPrimaryClass}`}>
                    Crew Payment: {paidCount}/{totalCount}
                  </p>
                  <Progress value={progressPercent} className="w-24 h-1.5 mt-1" />
                </div>
              </div>
              <div className="flex items-center gap-2">
                {unpaidAmount > 0 && (
                  <Badge className="bg-amber-500/20 text-amber-400">
                    ${unpaidAmount.toFixed(2)} pending
                  </Badge>
                )}
                {isExpanded ? <ChevronUp className="w-4 h-4 text-zinc-400" /> : <ChevronDown className="w-4 h-4 text-zinc-400" />}
              </div>
            </div>
          </button>
        </CollapsibleTrigger>
        
        <CollapsibleContent className="mt-2">
          <CrewPaymentDetails 
            crewMembers={crewMembers}
            unpaidMembers={unpaidMembers}
            unpaidAmount={unpaidAmount}
            isCaptain={isCaptain}
            covering={covering}
            sendingReminder={sendingReminder}
            onCoverRemaining={handleCoverRemaining}
            onSendReminder={handleSendReminder}
            isLight={isLight}
            textPrimaryClass={textPrimaryClass}
            textSecondaryClass={textSecondaryClass}
            bgCardClass={bgCardClass}
          />
        </CollapsibleContent>
      </Collapsible>
    );
  }
  
  // Full mode
  return (
    <div 
      className={`p-4 rounded-lg ${bgCardClass}`}
      data-testid="crew-payment-progress"
    >
      {/* Header with progress */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-full bg-cyan-500/20">
            <Users className="w-5 h-5 text-cyan-400" />
          </div>
          <div>
            <p className={`font-medium ${textPrimaryClass}`}>Crew Payment Status</p>
            <p className={`text-sm ${textSecondaryClass}`}>
              {paidCount} of {totalCount} paid
            </p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-lg font-bold text-green-400">${paidAmount.toFixed(2)}</p>
          <p className={`text-xs ${textSecondaryClass}`}>of ${totalAmount.toFixed(2)}</p>
        </div>
      </div>
      
      {/* Progress bar */}
      <Progress value={progressPercent} className="h-2 mb-4" />
      
      <CrewPaymentDetails 
        crewMembers={crewMembers}
        unpaidMembers={unpaidMembers}
        unpaidAmount={unpaidAmount}
        isCaptain={isCaptain}
        covering={covering}
        sendingReminder={sendingReminder}
        onCoverRemaining={handleCoverRemaining}
        onSendReminder={handleSendReminder}
        isLight={isLight}
        textPrimaryClass={textPrimaryClass}
        textSecondaryClass={textSecondaryClass}
        bgCardClass={bgCardClass}
      />
    </div>
  );
};

/**
 * Crew payment details (member list + actions)
 */
const CrewPaymentDetails = ({
  crewMembers,
  unpaidMembers,
  unpaidAmount,
  isCaptain,
  covering,
  sendingReminder,
  onCoverRemaining,
  onSendReminder,
  isLight,
  textPrimaryClass,
  textSecondaryClass,
  _bgCardClass
}) => {
  return (
    <>
      {/* Crew member chips */}
      <div className="flex flex-wrap gap-2 mb-4">
        {crewMembers.map(member => (
          <CrewMemberChip key={member.user_id} member={member} isLight={isLight} />
        ))}
      </div>
      
      {/* Captain actions */}
      {isCaptain && unpaidMembers.length > 0 && (
        <div className={`pt-4 border-t ${isLight ? 'border-gray-200' : 'border-zinc-700'}`}>
          {/* Cover remaining button */}
          <Button
            onClick={onCoverRemaining}
            disabled={covering}
            className="w-full bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-black font-medium mb-3"
            data-testid="cover-remaining-btn"
          >
            {covering ? (
              <>
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                Processing...
              </>
            ) : (
              <>
                <Shield className="w-4 h-4 mr-2" />
                Cover ${unpaidAmount.toFixed(2)} to Unlock Now
              </>
            )}
          </Button>
          
          {/* Send reminders */}
          <div className="space-y-2">
            <p className={`text-xs ${textSecondaryClass} mb-2`}>
              Or send a payment reminder:
            </p>
            {unpaidMembers.map(member => (
              <div 
                key={member.user_id}
                className={`flex items-center justify-between p-2 rounded-lg ${isLight ? 'bg-white' : 'bg-zinc-900'}`}
              >
                <div className="flex items-center gap-2">
                  <div className="w-8 h-8 rounded-full overflow-hidden bg-zinc-700">
                    {member.avatar_url ? (
                      <img src={getFullUrl(member.avatar_url)} alt="" className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-sm text-zinc-400">
                        {member.name?.charAt(0) || '?'}
                      </div>
                    )}
                  </div>
                  <div>
                    <p className={`text-sm font-medium ${textPrimaryClass}`}>
                      {member.name || member.username}
                    </p>
                    <p className="text-xs text-amber-400">
                      Owes ${member.share_amount?.toFixed(2) || '0.00'}
                    </p>
                  </div>
                </div>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => onSendReminder(member.user_id)}
                  disabled={sendingReminder === member.user_id}
                  className="border-zinc-600"
                  data-testid={`remind-${member.user_id}`}
                >
                  {sendingReminder === member.user_id ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <>
                      <Send className="w-3 h-3 mr-1" />
                      Remind
                    </>
                  )}
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}
      
      {/* Non-captain waiting message */}
      {!isCaptain && unpaidMembers.length > 0 && (
        <div className={`p-3 rounded-lg ${isLight ? 'bg-amber-50' : 'bg-amber-500/10'} border ${isLight ? 'border-amber-200' : 'border-amber-500/30'}`}>
          <div className="flex items-start gap-2">
            <AlertCircle className="w-4 h-4 text-amber-400 mt-0.5 flex-shrink-0" />
            <p className={`text-sm ${textSecondaryClass}`}>
              Waiting for {unpaidMembers.length} crew member{unpaidMembers.length > 1 ? 's' : ''} to complete payment.
              Media will unlock once everyone has paid.
            </p>
          </div>
        </div>
      )}
    </>
  );
};

export default CrewPaymentProgress;

﻿/**
 * BulkPurchaseBar - TICKET-005
 * Floating action bar for bulk photo/video purchases with volume discounts
 * Shows running total and applies automatic tier-based discounts
 */
import React, { useState, useMemo } from 'react';
import { 
  ShoppingCart, X, Loader2, Check, Tag, 
  ChevronUp, ChevronDown, Sparkles, Gift
} from 'lucide-react';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Progress } from '../ui/progress';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '../ui/tooltip';


import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';


// Default discount tiers (can be overridden by photographer settings)
const DEFAULT_DISCOUNT_TIERS = [
  { minItems: 3, discount: 0.10, label: '10% off' },
  { minItems: 5, discount: 0.15, label: '15% off' },
  { minItems: 10, discount: 0.20, label: '20% off' }
];

/**
 * Calculate discount based on item count and tiers
 */
const calculateDiscount = (itemCount, tiers = DEFAULT_DISCOUNT_TIERS) => {
  // Sort tiers by minItems descending to find the highest applicable tier
  const sortedTiers = [...tiers].sort((a, b) => b.minItems - a.minItems);
  
  for (const tier of sortedTiers) {
    if (itemCount >= tier.minItems) {
      return tier;
    }
  }
  
  return null;
};

/**
 * Get next discount tier hint
 */
const getNextTierHint = (itemCount, tiers = DEFAULT_DISCOUNT_TIERS) => {
  const sortedTiers = [...tiers].sort((a, b) => a.minItems - b.minItems);
  
  for (const tier of sortedTiers) {
    if (itemCount < tier.minItems) {
      return {
        itemsNeeded: tier.minItems - itemCount,
        discount: tier.discount,
        label: tier.label
      };
    }
  }
  
  return null; // Already at max tier
};

/**
 * Selected item thumbnail chip
 */
const SelectedItemChip = ({ item, onRemove }) => (
  <div className="relative group">
    <div className="w-12 h-12 rounded-lg overflow-hidden border border-zinc-700">
      <img 
        src={item.thumbnail_url || item.url} 
        alt="" 
        className="w-full h-full object-cover"
      />
    </div>
    <button
      onClick={() => onRemove(item.id)}
      className="absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full bg-red-500 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
    >
      <X className="w-3 h-3" />
    </button>
  </div>
);

/**
 * Main BulkPurchaseBar component
 */
export const BulkPurchaseBar = ({
  selectedItems = [],
  onRemoveItem,
  onClearAll,
  onPurchase,
  photographerDiscountTiers = null,
  qualityTier = 'standard',
  userId,
  disabled = false
}) => {
  const [purchasing, setPurchasing] = useState(false);
  const [expanded, setExpanded] = useState(false);
  
  const discountTiers = photographerDiscountTiers || DEFAULT_DISCOUNT_TIERS;
  
  // Calculate totals and discount
  const totals = useMemo(() => {
    const baseTotal = selectedItems.reduce((sum, item) => {
      const price = item.price || item.custom_price || 5;
      return sum + price;
    }, 0);
    
    const appliedTier = calculateDiscount(selectedItems.length, discountTiers);
    const discountAmount = appliedTier ? baseTotal * appliedTier.discount : 0;
    const finalTotal = baseTotal - discountAmount;
    
    return {
      baseTotal,
      discountAmount,
      finalTotal,
      appliedTier,
      itemCount: selectedItems.length
    };
  }, [selectedItems, discountTiers]);
  
  const nextTier = getNextTierHint(selectedItems.length, discountTiers);
  
  // Handle bulk purchase
  const handlePurchase = async () => {
    if (selectedItems.length === 0 || purchasing) return;
    
    setPurchasing(true);
    try {
      // Build purchase request
      const itemIds = selectedItems.map(item => item.id);
      const qualityTiers = selectedItems.reduce((acc, item) => {
        acc[item.id] = qualityTier;
        return acc;
      }, {});
      
      const response = await apiClient.post(`/gallery/bulk-purchase`, {
        item_ids: itemIds,
        quality_tiers: qualityTiers,
        buyer_id: userId
      });
      
      if (response.data.stripe_checkout_url) {
        window.location.href = response.data.stripe_checkout_url;
      } else {
        toast.success(`Purchased ${selectedItems.length} items for $${totals.finalTotal.toFixed(2)}!`);
        onPurchase?.(response.data);
        onClearAll?.();
      }
    } catch (error) {
      const msg = error.response?.data?.detail || 'Purchase failed';
      toast.error(msg);
      
      if (typeof msg === 'string' && msg.toLowerCase().includes('credit')) {
        setTimeout(() => {
          window.location.href = '/wallet';
        }, 1500);
      }
    } finally {
      setPurchasing(false);
    }
  };
  
  // Don't render if no items selected
  if (selectedItems.length === 0) {
    return null;
  }
  
  return (
    <div 
      className="fixed bottom-0 left-0 right-0 z-50 bg-zinc-900/95 backdrop-blur-sm border-t border-zinc-800 safe-area-bottom"
      data-testid="bulk-purchase-bar"
    >
      {/* Next tier hint banner */}
      {nextTier && (
        <div className="bg-gradient-to-r from-amber-500/10 to-orange-500/10 border-b border-amber-500/20 px-4 py-2">
          <div className="flex items-center justify-center gap-2 text-sm">
            <Gift className="w-4 h-4 text-amber-400" />
            <span className="text-amber-400">
              Add <span className="font-bold">{nextTier.itemsNeeded} more</span> for <span className="font-bold">{nextTier.label}</span>!
            </span>
            <Progress 
              value={(selectedItems.length / (selectedItems.length + nextTier.itemsNeeded)) * 100} 
              className="w-20 h-1.5 bg-zinc-700"
            />
          </div>
        </div>
      )}
      
      {/* Main bar */}
      <div className="px-4 py-3">
        <div className="max-w-screen-lg mx-auto">
          {/* Expandable header */}
          <div className="flex items-center justify-between">
            {/* Left: Item count and expand toggle */}
            <button 
              onClick={() => setExpanded(!expanded)}
              className="flex items-center gap-3 hover:opacity-80 transition-opacity"
            >
              <div className="relative">
                <ShoppingCart className="w-6 h-6 text-cyan-400" />
                <Badge className="absolute -top-2 -right-2 bg-cyan-500 text-white text-[10px] px-1.5 min-w-[20px]">
                  {selectedItems.length}
                </Badge>
              </div>
              <div className="text-left">
                <p className="text-white font-medium">
                  {selectedItems.length} item{selectedItems.length !== 1 ? 's' : ''} selected
                </p>
                {totals.appliedTier && (
                  <Badge className="bg-green-500/20 text-green-400 text-[10px] mt-0.5">
                    <Sparkles className="w-3 h-3 mr-1" />
                    {totals.appliedTier.label} applied!
                  </Badge>
                )}
              </div>
              {expanded ? (
                <ChevronDown className="w-5 h-5 text-zinc-400" />
              ) : (
                <ChevronUp className="w-5 h-5 text-zinc-400" />
              )}
            </button>
            
            {/* Right: Price and purchase button */}
            <div className="flex items-center gap-4">
              {/* Price display */}
              <div className="text-right">
                {totals.discountAmount > 0 && (
                  <div className="flex items-center gap-2 justify-end">
                    <span className="text-sm text-zinc-500 line-through">
                      ${totals.baseTotal.toFixed(2)}
                    </span>
                    <Badge className="bg-green-500/20 text-green-400 text-xs">
                      -{totals.appliedTier?.label}
                    </Badge>
                  </div>
                )}
                <p className="text-xl font-bold text-white">
                  ${totals.finalTotal.toFixed(2)}
                </p>
              </div>
              
              {/* Action buttons */}
              <div className="flex items-center gap-2">
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={onClearAll}
                        className="text-zinc-400 hover:text-red-400"
                      >
                        <X className="w-4 h-4" />
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Clear selection</TooltipContent>
                  </Tooltip>
                </TooltipProvider>
                
                <Button
                  onClick={handlePurchase}
                  disabled={purchasing || disabled}
                  className="bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-medium px-6"
                  data-testid="bulk-purchase-btn"
                >
                  {purchasing ? (
                    <>
                      <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                      Processing...
                    </>
                  ) : (
                    <>
                      <Check className="w-4 h-4 mr-2" />
                      Purchase All
                    </>
                  )}
                </Button>
              </div>
            </div>
          </div>
          
          {/* Expanded: Show selected items */}
          {expanded && (
            <div className="mt-4 pt-4 border-t border-zinc-800">
              <div className="flex items-center justify-between mb-3">
                <p className="text-sm text-zinc-400">Selected items:</p>
                <button 
                  onClick={onClearAll}
                  className="text-xs text-red-400 hover:text-red-300 transition-colors"
                >
                  Clear all
                </button>
              </div>
              
              <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                {selectedItems.map(item => (
                  <SelectedItemChip 
                    key={item.id} 
                    item={item} 
                    onRemove={onRemoveItem}
                  />
                ))}
              </div>
              
              {/* Discount tiers info */}
              <div className="mt-4 p-3 rounded-lg bg-zinc-800/50">
                <p className="text-xs text-zinc-400 mb-2 flex items-center gap-1">
                  <Tag className="w-3 h-3" />
                  Volume discounts:
                </p>
                <div className="flex gap-3">
                  {discountTiers.map((tier, idx) => {
                    const isActive = selectedItems.length >= tier.minItems;
                    const isNext = !isActive && 
                      (idx === 0 || selectedItems.length >= discountTiers[idx - 1].minItems);
                    
                    return (
                      <div 
                        key={tier.minItems}
                        className={`
                          text-center px-3 py-1.5 rounded-lg transition-all
                          ${isActive 
                            ? 'bg-green-500/20 border border-green-500/30' 
                            : isNext
                              ? 'bg-amber-500/10 border border-amber-500/30 animate-pulse'
                              : 'bg-zinc-800 border border-zinc-700'
                          }
                        `}
                      >
                        <p className={`text-xs font-medium ${
                          isActive ? 'text-green-400' : isNext ? 'text-amber-400' : 'text-zinc-400'
                        }`}>
                          {tier.minItems}+ items
                        </p>
                        <p className={`text-sm font-bold ${
                          isActive ? 'text-green-400' : isNext ? 'text-amber-400' : 'text-zinc-500'
                        }`}>
                          {tier.label}
                        </p>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

/**
 * Multi-select mode toggle button
 * Shows in gallery header to enable/disable bulk selection
 */
export const MultiSelectToggle = ({ 
  isActive, 
  onToggle, 
  selectedCount = 0 
}) => {
  return (
    <Button
      variant={isActive ? 'default' : 'outline'}
      size="sm"
      onClick={onToggle}
      className={isActive 
        ? 'bg-cyan-500 hover:bg-cyan-600 text-white' 
        : 'border-zinc-600 text-zinc-300 hover:bg-zinc-800'
      }
      data-testid="multi-select-toggle"
    >
      {isActive ? (
        <>
          <Check className="w-4 h-4 mr-1" />
          {selectedCount > 0 ? `${selectedCount} selected` : 'Selecting...'}
        </>
      ) : (
        <>
          <ShoppingCart className="w-4 h-4 mr-1" />
          Select Multiple
        </>
      )}
    </Button>
  );
};

export default BulkPurchaseBar;

import React, { useState } from 'react';
import { Sparkles, Camera, X, Loader2, Search, ShieldCheck, ChevronDown } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '../ui/dialog';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Badge } from '../ui/badge';
import { toast } from 'sonner';
import apiClient from '../../lib/apiClient';
import { getErrorMessage } from '../../utils/errors';
import logger from '../../utils/logger';

/**
 * FindMeModal — AI-powered surfer identification in a gallery.
 * Lets surfers upload a selfie + optional board/wetsuit details,
 * then scans the gallery using the POST /gallery/{id}/find-me endpoint.
 *
 * Props:
 *   open      — boolean controlling visibility
 *   onClose   — callback to close the modal
 *   galleryId — the gallery to scan
 *   userId    — the requesting user's ID
 */
export const FindMeModal = ({ open, onClose, galleryId, userId }) => {
  const [selfieUrl, setSelfieUrl] = useState('');
  const [selfieFile, setSelfieFile] = useState(null);
  const [selfiePreview, setSelfiePreview] = useState(null);
  const [boardDescription, setBoardDescription] = useState('');
  const [wetsuitDescription, setWetsuitDescription] = useState('');
  const [stance, setStance] = useState('');
  const [scanning, setScanning] = useState(false);
  const [matches, setMatches] = useState(null);
  const [scanMeta, setScanMeta] = useState(null);
  const [showAdvanced, setShowAdvanced] = useState(false);

  // Handle selfie file selection
  const handleSelfieSelect = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('Please select an image file');
      return;
    }
    setSelfieFile(file);
    setSelfiePreview(URL.createObjectURL(file));
    setSelfieUrl(''); // clear URL if a file is picked
  };

  // Upload selfie and get back URL, or use the pasted URL
  const getSelfieUrl = async () => {
    if (selfieUrl) return selfieUrl;
    if (!selfieFile) return null;

    // Upload selfie to backend for temporary storage
    const formData = new FormData();
    formData.append('file', selfieFile);
    formData.append('purpose', 'find_me_selfie');
    try {
      const res = await apiClient.post('/upload/temp', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      return res.data.url;
    } catch (err) {
      // Fallback: convert to base64 data URL
      return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.readAsDataURL(selfieFile);
      });
    }
  };

  // Execute the AI scan
  const handleScan = async () => {
    const url = await getSelfieUrl();
    if (!url) {
      toast.error('Please upload a selfie or paste a selfie URL');
      return;
    }
    setScanning(true);
    setMatches(null);
    setScanMeta(null);

    try {
      const response = await apiClient.post(
        `/gallery/${galleryId}/find-me`,
        {
          selfie_url: url,
          board_description: boardDescription || undefined,
          wetsuit_description: wetsuitDescription || undefined,
          stance: stance || undefined,
        }
      );
      const data = response.data;
      setMatches(data.matches || []);
      setScanMeta({
        totalScanned: data.total_photos_scanned,
        matchesFound: data.matches_found,
        scansRemaining: data.scans_remaining_today,
        maxPhotos: data.max_photos_per_scan,
        tier: data.subscription_tier,
      });

      if (data.matches_found > 0) {
        toast.success(`🤖 Found ${data.matches_found} match${data.matches_found > 1 ? 'es' : ''}!`);
      } else {
        toast.info('No matches found — try adjusting your details.');
      }
    } catch (error) {
      if (error.response?.status === 429) {
        toast.error(error.response.data?.detail || 'Daily scan limit reached');
      } else {
        toast.error(getErrorMessage(error, 'AI scan failed'));
      }
      logger.error('Find Me scan error:', error);
    } finally {
      setScanning(false);
    }
  };

  // Reset form
  const handleReset = () => {
    setMatches(null);
    setScanMeta(null);
    setSelfieFile(null);
    setSelfiePreview(null);
    setSelfieUrl('');
    setBoardDescription('');
    setWetsuitDescription('');
    setStance('');
    setShowAdvanced(false);
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-cyan-400" />
            AI Find Me
          </DialogTitle>
        </DialogHeader>

        {/* Pre-scan form */}
        {!matches && (
          <div className="space-y-4">
            <p className="text-sm text-muted-foreground">
              Upload a selfie and we'll scan this gallery to find photos of you using AI recognition.
            </p>

            {/* Selfie upload area */}
            <div className="space-y-2">
              <label className="text-sm font-medium text-foreground">Your Selfie *</label>
              {selfiePreview ? (
                <div className="relative w-24 h-24 rounded-xl overflow-hidden border-2 border-cyan-500/40">
                  <img src={selfiePreview} alt="Selfie" className="w-full h-full object-cover" />
                  <button
                    onClick={() => {
                      setSelfieFile(null);
                      setSelfiePreview(null);
                    }}
                    className="absolute top-0.5 right-0.5 w-5 h-5 bg-black/60 rounded-full flex items-center justify-center"
                  >
                    <X className="w-3 h-3 text-white" />
                  </button>
                </div>
              ) : (
                <label className="flex flex-col items-center justify-center w-full h-28 border-2 border-dashed border-zinc-600 rounded-xl cursor-pointer hover:border-cyan-500/50 transition-colors bg-muted/30">
                  <Camera className="w-8 h-8 text-zinc-500 mb-1" />
                  <span className="text-xs text-zinc-400">Tap to upload selfie</span>
                  <input
                    type="file"
                    accept="image/*"
                    capture="user"
                    className="hidden"
                    onChange={handleSelfieSelect}
                  />
                </label>
              )}
              {!selfieFile && (
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-zinc-500 uppercase">or paste URL</span>
                  <Input
                    placeholder="https://..."
                    value={selfieUrl}
                    onChange={(e) => setSelfieUrl(e.target.value)}
                    className="text-xs h-8"
                  />
                </div>
              )}
            </div>

            {/* Advanced options toggle */}
            <button
              onClick={() => setShowAdvanced(!showAdvanced)}
              className="flex items-center gap-1 text-xs text-cyan-400 hover:text-cyan-300 transition-colors"
            >
              <ChevronDown className={`w-3 h-3 transition-transform ${showAdvanced ? 'rotate-180' : ''}`} />
              {showAdvanced ? 'Hide' : 'Show'} Advanced Options
            </button>

            {showAdvanced && (
              <div className="space-y-3 pl-2 border-l-2 border-cyan-500/20">
                <div>
                  <label className="text-xs font-medium text-gray-400">Board Description</label>
                  <Input
                    placeholder="e.g., white 6'2 shortboard with blue fins"
                    value={boardDescription}
                    onChange={(e) => setBoardDescription(e.target.value)}
                    className="text-xs h-8 mt-1"
                  />
                </div>
                <div>
                  <label className="text-xs font-medium text-gray-400">Wetsuit / Rash Guard</label>
                  <Input
                    placeholder="e.g., black full suit, red rash guard"
                    value={wetsuitDescription}
                    onChange={(e) => setWetsuitDescription(e.target.value)}
                    className="text-xs h-8 mt-1"
                  />
                </div>
                <div>
                  <label className="text-xs font-medium text-gray-400">Stance</label>
                  <div className="flex gap-2 mt-1">
                    {['regular', 'goofy'].map((s) => (
                      <button
                        key={s}
                        onClick={() => setStance(stance === s ? '' : s)}
                        className={`px-3 py-1 rounded-full text-xs font-medium transition-colors ${
                          stance === s
                            ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/40'
                            : 'bg-muted text-gray-400 hover:bg-zinc-700 border border-transparent'
                        }`}
                      >
                        {s.charAt(0).toUpperCase() + s.slice(1)}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Privacy note */}
            <div className="flex items-start gap-2 p-2 bg-muted/50 rounded-lg">
              <ShieldCheck className="w-4 h-4 text-green-400 flex-shrink-0 mt-0.5" />
              <p className="text-[10px] text-gray-500 leading-relaxed">
                Your selfie is only used for this scan and is not stored permanently.
                AI matching uses visual pattern recognition — no facial data is retained.
              </p>
            </div>
          </div>
        )}

        {/* Scan results */}
        {matches && (
          <div className="space-y-4">
            {/* Summary */}
            <div className="flex items-center justify-between p-3 bg-muted/50 rounded-lg">
              <div>
                <p className="text-sm font-medium text-foreground">
                  {matches.length > 0
                    ? `🎯 ${matches.length} match${matches.length > 1 ? 'es' : ''} found`
                    : '😔 No matches found'}
                </p>
                <p className="text-[10px] text-gray-500">
                  Scanned {scanMeta?.totalScanned || 0} photos • {scanMeta?.scansRemaining ?? '?'} scans left today
                </p>
              </div>
              <Button size="sm" variant="outline" onClick={handleReset} className="text-xs">
                New Scan
              </Button>
            </div>

            {/* Match grid */}
            {matches.length > 0 && (
              <div className="grid grid-cols-2 gap-2">
                {matches.map((match, i) => (
                  <div
                    key={match.gallery_item_id}
                    className="relative rounded-xl overflow-hidden bg-zinc-800 group cursor-pointer"
                  >
                    <img
                      src={match.preview_url || match.thumbnail_url}
                      alt={`Match ${i + 1}`}
                      className="w-full aspect-square object-cover group-hover:scale-105 transition-transform"
                    />
                    {/* Confidence badge */}
                    <div className="absolute top-1 right-1">
                      <Badge
                        className={`text-[10px] py-0 ${
                          match.confidence >= 0.7
                            ? 'bg-green-500/80 text-white'
                            : match.confidence >= 0.5
                            ? 'bg-yellow-500/80 text-black'
                            : 'bg-orange-500/80 text-white'
                        }`}
                      >
                        {Math.round(match.confidence * 100)}%
                      </Badge>
                    </div>
                    {/* Price badge */}
                    {match.is_for_sale && match.price && (
                      <div className="absolute bottom-1 left-1 bg-black/70 backdrop-blur-sm rounded px-1.5 py-0.5">
                        <span className="text-[10px] font-bold text-green-400">${match.price}</span>
                      </div>
                    )}
                    {/* Match rank */}
                    <div className="absolute top-1 left-1 w-5 h-5 bg-cyan-500/90 rounded-full flex items-center justify-center">
                      <span className="text-[10px] font-bold text-white">{i + 1}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        <DialogFooter>
          {!matches ? (
            <div className="flex gap-2 w-full">
              <Button variant="outline" onClick={onClose} className="flex-1">
                Cancel
              </Button>
              <Button
                onClick={handleScan}
                disabled={scanning || (!selfieFile && !selfieUrl)}
                className="flex-1 bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600"
              >
                {scanning ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-1 animate-spin" />
                    Scanning...
                  </>
                ) : (
                  <>
                    <Search className="w-4 h-4 mr-1" />
                    Find Me
                  </>
                )}
              </Button>
            </div>
          ) : (
            <Button onClick={onClose} className="w-full">
              Done
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default FindMeModal;

/**
 * GalleryLightbox — Fullscreen immersive photo/video viewer
 * 
 * Features:
 * - Swipe-to-navigate (touch + keyboard arrows)
 * - Pinch-to-zoom on mobile (two-finger)
 * - Scroll-wheel zoom on desktop
 * - Download, favorite, share actions in bottom bar
 * - Purchase CTA for locked/unpurchased items
 * - Photo counter "3 of 24"
 * - Unlock animation after purchase
 * - Auto-navigates through filtered gallery items
 */
import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  X, ChevronLeft, ChevronRight, Heart, Download, Share2,
  ShoppingCart, Lock, Loader2, ZoomIn, ZoomOut, Camera,
  MapPin, Calendar, Check, Maximize2
} from 'lucide-react';
import { Button } from '../ui/button';
import { toast } from 'sonner';
import { getFullUrl } from '../../utils/media';

export const GalleryLightbox = ({
  item,
  items = [],
  onClose,
  onNavigate,
  onFavoriteToggle,
  onDownload,
  onShare,
  onPurchase,
  onMessage,
  isGromUser = false,
}) => {
  const [zoom, setZoom] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [swipeStartX, setSwipeStartX] = useState(null);
  const [unlocking, setUnlocking] = useState(false);
  const [unlocked, setUnlocked] = useState(false);
  const [purchasing, setPurchasing] = useState(false);
  const [imgLoaded, setImgLoaded] = useState(false);
  const containerRef = useRef(null);
  const imgRef = useRef(null);

  const currentIndex = item ? items.findIndex(i => i.id === item.id) : -1;
  const hasPrev = currentIndex > 0;
  const hasNext = currentIndex < items.length - 1;
  const isAccessible = item ? (item.is_paid || ['included', 'gifted'].includes(item.access_type)) : false;
  const isFavorite = item?.is_favorite;

  // Reset zoom when navigating
  useEffect(() => {
    setZoom(1);
    setPanOffset({ x: 0, y: 0 });
    setImgLoaded(false);
    setUnlocked(false);
  }, [item?.id]);

  // Keyboard navigation
  useEffect(() => {
    const handleKey = (e) => {
      if (e.key === 'Escape') onClose?.();
      else if (e.key === 'ArrowRight' && hasNext) onNavigate?.(items[currentIndex + 1]);
      else if (e.key === 'ArrowLeft' && hasPrev) onNavigate?.(items[currentIndex - 1]);
      else if (e.key === 'f' || e.key === 'F') onFavoriteToggle?.(item.id);
      else if (e.key === '+' || e.key === '=') setZoom(z => Math.min(z + 0.25, 5));
      else if (e.key === '-') setZoom(z => Math.max(z - 0.25, 1));
      else if (e.key === '0') { setZoom(1); setPanOffset({ x: 0, y: 0 }); }
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [item, currentIndex, hasNext, hasPrev, items, onClose, onNavigate, onFavoriteToggle]);

  // Mouse wheel zoom
  const handleWheel = useCallback((e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.15 : 0.15;
    setZoom(z => {
      const newZ = Math.max(1, Math.min(z + delta, 5));
      if (newZ <= 1) setPanOffset({ x: 0, y: 0 });
      return newZ;
    });
  }, []);

  // Touch swipe
  const handleTouchStart = (e) => {
    if (e.touches.length === 1 && zoom <= 1) {
      setSwipeStartX(e.touches[0].clientX);
    }
  };

  const handleTouchEnd = (e) => {
    if (swipeStartX !== null && zoom <= 1) {
      const diff = e.changedTouches[0].clientX - swipeStartX;
      if (Math.abs(diff) > 60) {
        if (diff < 0 && hasNext) onNavigate?.(items[currentIndex + 1]);
        else if (diff > 0 && hasPrev) onNavigate?.(items[currentIndex - 1]);
      }
    }
    setSwipeStartX(null);
  };

  // Mouse pan when zoomed
  const handleMouseDown = (e) => {
    if (zoom > 1) {
      setIsDragging(true);
      setDragStart({ x: e.clientX - panOffset.x, y: e.clientY - panOffset.y });
    }
  };

  const handleMouseMove = (e) => {
    if (isDragging && zoom > 1) {
      setPanOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    }
  };

  const handleMouseUp = () => setIsDragging(false);

  // Handle purchase with unlock animation
  const handlePurchaseClick = async () => {
    if (isGromUser) {
      toast.info('🤙 Ask your parent to approve this purchase!');
      return;
    }
    if (!onPurchase) return;
    setPurchasing(true);
    try {
      await onPurchase(item.id, 'high');
      setUnlocking(true);
      setTimeout(() => {
        setUnlocked(true);
        setUnlocking(false);
      }, 1200);
    } catch {
      // Error handled by parent
    } finally {
      setPurchasing(false);
    }
  };

  if (!item) return null;

  // Native download
  const handleNativeDownload = () => {
    const url = getFullUrl(item.original_url || item.url);
    const link = document.createElement('a');
    link.href = url;
    link.download = `rawsurf_${item.id?.slice(-8) || 'photo'}.jpg`;
    link.target = '_blank';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success('📸 Saved to device!');
  };

  const mediaUrl = getFullUrl(
    isAccessible || unlocked
      ? (item.original_url || item.url)
      : (item.thumbnail_url || item.url)
  );

  return (
    <div
      ref={containerRef}
      className="fixed inset-0 z-[200] bg-black flex flex-col select-none"
      onClick={(e) => { if (e.target === containerRef.current) onClose?.(); }}
      onWheel={handleWheel}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      style={{ cursor: zoom > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default' }}
    >
      {/* Top bar */}
      <div className="absolute top-0 left-0 right-0 z-10 flex items-center justify-between p-4 bg-gradient-to-b from-black/80 to-transparent">
        <div className="flex items-center gap-3">
          <button
            onClick={onClose}
            className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-sm flex items-center justify-center text-white hover:bg-white/20 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
          {items.length > 1 && (
            <span className="text-white/70 text-sm font-medium">
              {currentIndex + 1} of {items.length}
            </span>
          )}
        </div>

        {/* Zoom controls */}
        <div className="flex items-center gap-1">
          <button
            onClick={() => setZoom(z => Math.max(z - 0.5, 1))}
            disabled={zoom <= 1}
            className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-white hover:bg-white/20 disabled:opacity-30 transition"
          >
            <ZoomOut className="w-4 h-4" />
          </button>
          <span className="text-white/60 text-xs w-10 text-center">{Math.round(zoom * 100)}%</span>
          <button
            onClick={() => setZoom(z => Math.min(z + 0.5, 5))}
            disabled={zoom >= 5}
            className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-white hover:bg-white/20 disabled:opacity-30 transition"
          >
            <ZoomIn className="w-4 h-4" />
          </button>
          {zoom > 1 && (
            <button
              onClick={() => { setZoom(1); setPanOffset({ x: 0, y: 0 }); }}
              className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-white hover:bg-white/20 transition"
            >
              <Maximize2 className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      {/* Navigation arrows */}
      {hasPrev && (
        <button
          className="absolute left-4 top-1/2 -translate-y-1/2 z-10 w-12 h-12 rounded-full bg-white/10 backdrop-blur-sm flex items-center justify-center text-white hover:bg-white/20 transition-all"
          onClick={(e) => { e.stopPropagation(); onNavigate?.(items[currentIndex - 1]); }}
        >
          <ChevronLeft className="w-6 h-6" />
        </button>
      )}
      {hasNext && (
        <button
          className="absolute right-4 top-1/2 -translate-y-1/2 z-10 w-12 h-12 rounded-full bg-white/10 backdrop-blur-sm flex items-center justify-center text-white hover:bg-white/20 transition-all"
          onClick={(e) => { e.stopPropagation(); onNavigate?.(items[currentIndex + 1]); }}
        >
          <ChevronRight className="w-6 h-6" />
        </button>
      )}

      {/* Main image area */}
      <div className="flex-1 flex items-center justify-center overflow-hidden relative">
        {/* Unlock animation overlay */}
        {unlocking && (
          <div className="absolute inset-0 z-20 flex items-center justify-center">
            <div className="text-center animate-bounce">
              <div className="w-20 h-20 rounded-full bg-gradient-to-r from-emerald-400 to-cyan-400 flex items-center justify-center mx-auto mb-3 shadow-lg shadow-emerald-500/50">
                <Check className="w-10 h-10 text-white" />
              </div>
              <p className="text-white text-xl font-bold">🎉 Unlocked!</p>
              <p className="text-emerald-400 text-sm mt-1">Full resolution available</p>
            </div>
          </div>
        )}

        {item.media_type === 'video' ? (
          <video
            src={mediaUrl}
            controls={isAccessible || unlocked}
            autoPlay
            muted={!isAccessible && !unlocked}
            loop={!isAccessible && !unlocked}
            playsInline
            className={`max-w-[90vw] max-h-[75vh] object-contain ${!isAccessible && !unlocked ? 'blur-sm' : ''}`}
            poster={getFullUrl(item.thumbnail_url)}
          />
        ) : (
          <>
            {!imgLoaded && (
              <div className="absolute inset-0 flex items-center justify-center">
                <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
              </div>
            )}
            <img
              ref={imgRef}
              src={mediaUrl}
              alt={item.title || 'Gallery photo'}
              className={`max-w-[90vw] max-h-[75vh] object-contain transition-all duration-200 ${
                !isAccessible && !unlocked ? 'blur-sm' : ''
              } ${imgLoaded ? 'opacity-100' : 'opacity-0'}`}
              style={{
                transform: `scale(${zoom}) translate(${panOffset.x / zoom}px, ${panOffset.y / zoom}px)`,
                transition: isDragging ? 'none' : 'transform 0.2s ease-out'
              }}
              onLoad={() => setImgLoaded(true)}
              onClick={(e) => e.stopPropagation()}
              draggable={false}
            />
          </>
        )}

        {/* Lock overlay for unpurchased items */}
        {!isAccessible && !unlocked && !unlocking && (
          <div
            className="absolute inset-0 flex flex-col items-center justify-center"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="bg-black/60 backdrop-blur-md rounded-2xl p-8 text-center max-w-sm mx-4">
              <div className="w-16 h-16 rounded-full bg-gradient-to-r from-amber-400 to-orange-500 flex items-center justify-center mx-auto mb-4">
                <Lock className="w-8 h-8 text-white" />
              </div>
              <h3 className="text-white text-lg font-bold mb-2">Unlock Full Resolution</h3>
              <p className="text-zinc-400 text-sm mb-4">
                Purchase this {item.media_type === 'video' ? 'video' : 'photo'} to download in full quality
              </p>
              <Button
                onClick={handlePurchaseClick}
                disabled={purchasing}
                className={`w-full font-bold py-3 ${
                  isGromUser
                    ? 'bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 text-white'
                    : 'bg-gradient-to-r from-yellow-400 to-orange-400 hover:from-yellow-500 hover:to-orange-500 text-black'
                }`}
              >
                {purchasing ? (
                  <Loader2 className="w-5 h-5 animate-spin" />
                ) : isGromUser ? (
                  <>👨‍👧 Ask Parent to Approve</>
                ) : (
                  <>
                    <ShoppingCart className="w-4 h-4 mr-2" />
                    Buy for ${item.price || item.custom_price || 5}
                  </>
                )}
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* Bottom info bar */}
      <div className="absolute bottom-0 left-0 right-0 z-10 bg-gradient-to-t from-black/90 via-black/60 to-transparent">
        <div className="max-w-4xl mx-auto px-4 pb-6 pt-12">
          {/* Photo metadata */}
          <div className="flex items-center gap-4 mb-4">
            <div className="flex-1 min-w-0">
              <p className="text-white font-semibold text-lg truncate">
                {item.photographer_name || 'Photographer'}
              </p>
              <div className="flex items-center gap-3 text-zinc-400 text-sm mt-1">
                {item.spot_name && (
                  <span className="flex items-center gap-1">
                    <MapPin className="w-3.5 h-3.5" />
                    {item.spot_name}
                  </span>
                )}
                <span className="flex items-center gap-1">
                  <Calendar className="w-3.5 h-3.5" />
                  {new Date(item.created_at).toLocaleDateString()}
                </span>
              </div>
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {/* Favorite */}
              <button
                onClick={(e) => { e.stopPropagation(); onFavoriteToggle?.(item.id); }}
                className={`w-11 h-11 rounded-full flex items-center justify-center transition-all ${
                  isFavorite
                    ? 'bg-red-500/30 text-red-400 ring-1 ring-red-500/50'
                    : 'bg-white/10 text-white hover:bg-white/20'
                }`}
              >
                <Heart className={`w-5 h-5 ${isFavorite ? 'fill-current' : ''}`} />
              </button>

              {/* Share */}
              <button
                onClick={(e) => { e.stopPropagation(); onShare?.(item); }}
                className="w-11 h-11 rounded-full bg-white/10 text-white hover:bg-white/20 flex items-center justify-center transition-all"
              >
                <Share2 className="w-5 h-5" />
              </button>

              {/* Message photographer */}
              {item.photographer_id && onMessage && (
                <button
                  onClick={(e) => { e.stopPropagation(); onMessage?.(item.photographer_id, item.photographer_name); }}
                  className="w-11 h-11 rounded-full bg-white/10 text-white hover:bg-cyan-500/30 flex items-center justify-center transition-all"
                  title="Message photographer"
                >
                  <Camera className="w-5 h-5" />
                </button>
              )}
            </div>

            <div className="flex items-center gap-2">
              {/* Download — only for accessible items */}
              {(isAccessible || unlocked) && (
                <Button
                  onClick={(e) => { e.stopPropagation(); handleNativeDownload(); }}
                  className="bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-semibold px-5"
                >
                  <Download className="w-4 h-4 mr-2" />
                  Save to Device
                </Button>
              )}
            </div>
          </div>

          {/* Keyboard hints (desktop only) */}
          <p className="text-center text-white/25 text-xs mt-3 hidden md:block">
            ← → Navigate • F Favorite • +/− Zoom • 0 Reset • Esc Close
          </p>
        </div>
      </div>
    </div>
  );
};

export default GalleryLightbox;

/**
 * PostSessionSummary — Photographer post-session action dashboard
 * 
 * Shows for session galleries that ended recently (< 48 hours).
 * One-click distribute, AI match status, and distribution progress.
 */
import React, { useState, useMemo } from 'react';
import {
  Camera, MapPin, Calendar, Users, Sparkles, Send,
  CheckCircle, AlertTriangle, Loader2, ChevronDown, ChevronUp,
  Image as ImageIcon
} from 'lucide-react';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Progress } from '../ui/progress';

export const PostSessionSummary = ({
  gallery,
  participants = [],
  onDistributeAll,
  onOpenTagAssign,
  onAiAutoTag,
  isDistributing = false,
  distributeProgress = null, // { current, total }
  isAiTagging = false,
}) => {
  const [collapsed, setCollapsed] = useState(false);

  // Don't show if gallery is older than 48 hours
  const isRecent = useMemo(() => {
    if (!gallery?.created_at) return false;
    const age = Date.now() - new Date(gallery.created_at).getTime();
    return age < 48 * 60 * 60 * 1000; // 48 hours
  }, [gallery?.created_at]);

  // Calculate stats
  const stats = useMemo(() => {
    const totalItems = gallery?.item_count || 0;
    const totalSurfers = participants.length;
    const aiMatched = participants.filter(p => p.items_distributed > 0).length;
    const totalDistributed = participants.reduce((sum, p) => sum + (p.items_distributed || 0), 0);
    const needsTagging = totalItems > 0 && totalDistributed === 0;

    return { totalItems, totalSurfers, aiMatched, totalDistributed, needsTagging };
  }, [gallery, participants]);

  if (!isRecent || !gallery) return null;

  const progressPercent = distributeProgress
    ? Math.round((distributeProgress.current / distributeProgress.total) * 100)
    : 0;

  return (
    <div className="mb-6 overflow-hidden rounded-xl border border-emerald-500/30 bg-gradient-to-r from-emerald-900/20 via-zinc-900/80 to-cyan-900/20">
      {/* Header */}
      <button
        onClick={() => setCollapsed(!collapsed)}
        className="w-full flex items-center justify-between p-4 hover:bg-white/5 transition-colors"
      >
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-emerald-500/20 flex items-center justify-center">
            <Camera className="w-5 h-5 text-emerald-400" />
          </div>
          <div className="text-left">
            <h3 className="text-white font-semibold flex items-center gap-2">
              Session Complete
              {stats.needsTagging && (
                <Badge className="bg-amber-500/20 text-amber-400 text-[10px]">
                  <AlertTriangle className="w-3 h-3 mr-1" />
                  Needs Distribution
                </Badge>
              )}
              {!stats.needsTagging && stats.totalDistributed > 0 && (
                <Badge className="bg-emerald-500/20 text-emerald-400 text-[10px]">
                  <CheckCircle className="w-3 h-3 mr-1" />
                  Distributed
                </Badge>
              )}
            </h3>
            <p className="text-zinc-400 text-sm flex items-center gap-2">
              {gallery.title || 'Session'} 
              {gallery.spot_name && (
                <span className="flex items-center gap-1">
                  <MapPin className="w-3 h-3" />
                  {gallery.spot_name}
                </span>
              )}
            </p>
          </div>
        </div>
        {collapsed ? (
          <ChevronDown className="w-5 h-5 text-zinc-400" />
        ) : (
          <ChevronUp className="w-5 h-5 text-zinc-400" />
        )}
      </button>

      {/* Expandable content */}
      {!collapsed && (
        <div className="px-4 pb-4 space-y-4">
          {/* Stats row */}
          <div className="grid grid-cols-4 gap-3">
            <div className="text-center p-3 rounded-lg bg-zinc-800/50">
              <ImageIcon className="w-5 h-5 text-cyan-400 mx-auto mb-1" />
              <p className="text-xl font-bold text-white">{stats.totalItems}</p>
              <p className="text-[10px] text-zinc-400">Photos</p>
            </div>
            <div className="text-center p-3 rounded-lg bg-zinc-800/50">
              <Users className="w-5 h-5 text-purple-400 mx-auto mb-1" />
              <p className="text-xl font-bold text-white">{stats.totalSurfers}</p>
              <p className="text-[10px] text-zinc-400">Surfers</p>
            </div>
            <div className="text-center p-3 rounded-lg bg-zinc-800/50">
              <Sparkles className="w-5 h-5 text-emerald-400 mx-auto mb-1" />
              <p className="text-xl font-bold text-white">{stats.aiMatched}</p>
              <p className="text-[10px] text-zinc-400">AI Matched</p>
            </div>
            <div className="text-center p-3 rounded-lg bg-zinc-800/50">
              <Send className="w-5 h-5 text-amber-400 mx-auto mb-1" />
              <p className="text-xl font-bold text-white">{stats.totalDistributed}</p>
              <p className="text-[10px] text-zinc-400">Delivered</p>
            </div>
          </div>

          {/* Distribution progress bar (when actively distributing) */}
          {isDistributing && distributeProgress && (
            <div className="p-3 bg-cyan-500/10 border border-cyan-500/30 rounded-lg">
              <div className="flex items-center justify-between mb-2">
                <span className="text-cyan-400 text-sm font-medium flex items-center gap-2">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Distributing...
                </span>
                <span className="text-cyan-400 text-sm font-mono">
                  {distributeProgress.current}/{distributeProgress.total}
                </span>
              </div>
              <Progress value={progressPercent} className="h-2 bg-zinc-700" />
            </div>
          )}

          {/* Action buttons */}
          <div className="flex flex-wrap gap-2">
            <Button
              onClick={onDistributeAll}
              disabled={isDistributing || stats.totalSurfers === 0}
              className="flex-1 bg-gradient-to-r from-emerald-500 to-cyan-500 hover:from-emerald-600 hover:to-cyan-600 text-white font-semibold"
            >
              {isDistributing ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Distributing...
                </>
              ) : (
                <>
                  <Send className="w-4 h-4 mr-2" />
                  Distribute All to Lockers
                </>
              )}
            </Button>

            <Button
              onClick={onAiAutoTag}
              disabled={isAiTagging}
              variant="outline"
              className="border-purple-500/50 text-purple-400 hover:bg-purple-500/10"
            >
              {isAiTagging ? (
                <Loader2 className="w-4 h-4 mr-1 animate-spin" />
              ) : (
                <Sparkles className="w-4 h-4 mr-1" />
              )}
              AI Tag
            </Button>

            <Button
              onClick={onOpenTagAssign}
              variant="outline"
              className="border-zinc-600 text-zinc-300 hover:bg-zinc-800"
            >
              <Users className="w-4 h-4 mr-1" />
              Manual Tag
            </Button>
          </div>
        </div>
      )}
    </div>
  );
};

export default PostSessionSummary;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import {
  Users,
  ChevronDown,
  ChevronUp,
  CheckCircle2,
  ImageIcon,
  Video,
  X,
  ZoomIn,
  Tag,
  Minus,
  Shield,
  Camera,
  Film,
  Bot,
  Hand
} from 'lucide-react';
import apiClient from '../../lib/apiClient';
import { getFullUrl } from '../../utils/media';
import { toast } from 'sonner';
import logger from '../../utils/logger';

/**
 * SessionRosterCard — Enhanced Surfer Delivery Tracker
 * 
 * Features:
 *   - Expandable surfer panels with selfie reference photo (zoomable)
 *   - Tagged item thumbnails with untag capability
 *   - Separate photo/video credit tracking
 *   - AI vs Manual tagging indicators
 *   - Video autoplay (muted) in thumbnails
 */
export const SessionRosterCard = ({ 
  roster = [], sessionType, itemCount = 0, compact = false,
  galleryId, photographerId, onRosterUpdate
}) => {
  const [expanded, setExpanded] = useState(false);
  if (!roster || roster.length === 0) return null;

  const sessionLabel = {
    live: { text: 'Live Session', color: '#10b981', emoji: '🟢' },
    booking: { text: 'Booking', color: '#3b82f6', emoji: '📅' },
    on_demand: { text: 'On-Demand', color: '#f59e0b', emoji: '⚡' },
    manual: { text: 'Manual', color: '#6b7280', emoji: '📁' }
  }[sessionType] || { text: 'Session', color: '#6b7280', emoji: '📸' };

  // ── COMPACT MODE ──
  if (compact) {
    const totalDelivered = roster.reduce((s, r) => s + (r.items_delivered || 0), 0);
    const totalSlots = roster.reduce((s, r) => s + (r.photos_included || 0) + (r.videos_included || 0), 0);
    const allDone = totalDelivered >= totalSlots && totalSlots > 0;
    return (
      <div className="flex items-center gap-1.5 px-3 pb-2" onClick={e => e.stopPropagation()}>
        <div className="flex -space-x-2">
          {roster.slice(0, 4).map((surfer, i) => (
            <div key={surfer.surfer_id} className="relative" style={{ zIndex: 4 - i }}>
              {surfer.avatar_url ? (
                <img src={surfer.avatar_url} alt="" className="w-6 h-6 rounded-full border-2 object-cover"
                  style={{ borderColor: (surfer.credits_remaining || 0) > 0 ? '#f59e0b' : '#10b981' }} />
              ) : (
                <div className="w-6 h-6 rounded-full border-2 flex items-center justify-center text-[8px] font-bold text-white"
                  style={{ borderColor: (surfer.credits_remaining || 0) > 0 ? '#f59e0b' : '#10b981', background: 'linear-gradient(135deg, #06b6d4, #3b82f6)' }}>
                  {(surfer.full_name || '?')[0]}
                </div>
              )}
            </div>
          ))}
          {roster.length > 4 && (
            <div className="w-6 h-6 rounded-full border-2 border-muted bg-muted flex items-center justify-center text-[8px] font-bold text-muted-foreground">+{roster.length - 4}</div>
          )}
        </div>
        <span className="text-[10px] text-muted-foreground font-medium ml-1">
          {allDone ? <span className="text-emerald-500">✓ All delivered</span> : <span>{totalDelivered}/{totalSlots} sent</span>}
        </span>
      </div>
    );
  }

  // ── EXPANDED MODE ──
  const totalDelivered = roster.reduce((s, r) => s + (r.items_delivered || 0), 0);
  const totalSlots = roster.reduce((s, r) => s + (r.photos_included || 0) + (r.videos_included || 0), 0);
  const allComplete = totalDelivered >= totalSlots && totalSlots > 0;

  return (
    <div className="rounded-xl overflow-hidden" style={{
      background: 'linear-gradient(135deg, rgba(6,182,212,0.06), rgba(59,130,246,0.04))',
      border: '1px solid rgba(6,182,212,0.15)'
    }}>
      <button onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-white/5 transition-colors">
        <div className="flex items-center gap-2.5">
          <div className="w-8 h-8 rounded-lg flex items-center justify-center" style={{ background: `${sessionLabel.color}20` }}>
            <Users className="w-4 h-4" style={{ color: sessionLabel.color }} />
          </div>
          <div className="text-left">
            <h4 className="text-sm font-semibold text-foreground">Session Roster</h4>
            <p className="text-[11px] text-muted-foreground">
              {roster.length} surfer{roster.length !== 1 ? 's' : ''} • {sessionLabel.emoji} {sessionLabel.text}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full" style={{
            background: allComplete ? 'rgba(16,185,129,0.15)' : 'rgba(245,158,11,0.15)',
            color: allComplete ? '#10b981' : '#f59e0b'
          }}>{totalDelivered}/{totalSlots} delivered</span>
          {expanded ? <ChevronUp className="w-4 h-4 text-muted-foreground" /> : <ChevronDown className="w-4 h-4 text-muted-foreground" />}
        </div>
      </button>
      {expanded && (
        <div className="px-3 pb-3 space-y-2">
          {roster.map(surfer => (
            <SurferPanel key={surfer.surfer_id} surfer={surfer} itemCount={itemCount}
              galleryId={galleryId} photographerId={photographerId} onRosterUpdate={onRosterUpdate} />
          ))}
        </div>
      )}
    </div>
  );
};

// ── SURFER PANEL ──
const SurferPanel = ({ surfer, galleryId, photographerId, onRosterUpdate }) => {
  const [panelOpen, setPanelOpen] = useState(false);
  const [selfieZoom, setSelfieZoom] = useState(false);
  const [taggedItems, setTaggedItems] = useState([]);
  const [loadingItems, setLoadingItems] = useState(false);
  const [itemsLoaded, setItemsLoaded] = useState(false);
  const [untagging, setUntagging] = useState(null);

  const {
    full_name, username, avatar_url, selfie_url, amount_paid,
    photos_included = 3, videos_included = 0,
    photos_delivered = 0, videos_delivered = 0,
    photos_credits_remaining = 0, videos_credits_remaining = 0,
    items_delivered = 0, credits_remaining = 0, progress_pct = 0, payment_method
  } = surfer;

  const totalSlots = photos_included + videos_included;
  const isComplete = credits_remaining === 0 && items_delivered >= totalSlots && totalSlots > 0;
  const hasCredits = credits_remaining > 0;
  const displayPhoto = selfie_url || avatar_url;

  const loadTaggedItems = useCallback(async () => {
    if (!galleryId || !photographerId || itemsLoaded) return;
    setLoadingItems(true);
    try {
      const resp = await apiClient.get(
        `/gallery/${galleryId}/surfer-items/${surfer.surfer_id}?photographer_id=${photographerId}`
      );
      setTaggedItems(resp.data.tagged_items || []);
      setItemsLoaded(true);
    } catch (err) {
      logger.error('Failed to load tagged items:', err);
    } finally {
      setLoadingItems(false);
    }
  }, [galleryId, photographerId, surfer.surfer_id, itemsLoaded]);

  const togglePanel = () => {
    const willOpen = !panelOpen;
    setPanelOpen(willOpen);
    if (willOpen && !itemsLoaded) loadTaggedItems();
  };

  const handleUntag = async (item) => {
    if (untagging) return;
    setUntagging(item.gallery_item_id);
    try {
      await apiClient.post(
        `/gallery/${galleryId}/untag-item?photographer_id=${photographerId}`,
        { surfer_id: surfer.surfer_id, item_id: item.gallery_item_id }
      );
      setTaggedItems(prev => prev.filter(i => i.gallery_item_id !== item.gallery_item_id));
      const type = item.media_type === 'video' ? 'video' : 'photo';
      toast.success(`Untagged ${type} from ${full_name}${item.access_type === 'included' ? ' — credit restored' : ''}`);
      if (onRosterUpdate) onRosterUpdate();
    } catch (err) {
      toast.error('Failed to untag item');
    } finally {
      setUntagging(null);
    }
  };

  // Count AI vs manual from loaded items
  const aiCount = taggedItems.filter(i => i.ai_suggested).length;
  const manualCount = taggedItems.filter(i => !i.ai_suggested).length;

  return (
    <>
      <div className="rounded-xl overflow-hidden transition-all" style={{
        background: isComplete ? 'rgba(16,185,129,0.06)' : 'rgba(255,255,255,0.03)',
        border: `1px solid ${isComplete ? 'rgba(16,185,129,0.2)' : 'rgba(255,255,255,0.08)'}`
      }}>
        {/* Header */}
        <button onClick={togglePanel} className="w-full flex items-center gap-3 p-3 hover:bg-white/5 transition-colors">
          <div className="relative flex-shrink-0">
            {displayPhoto ? (
              <img src={displayPhoto} alt={full_name}
                className="w-11 h-11 rounded-xl object-cover"
                style={{ border: `2px solid ${isComplete ? '#10b981' : hasCredits ? '#f59e0b' : '#6b7280'}` }} />
            ) : (
              <div className="w-11 h-11 rounded-xl flex items-center justify-center text-sm font-bold text-white"
                style={{ background: 'linear-gradient(135deg, #06b6d4, #3b82f6)', border: `2px solid ${isComplete ? '#10b981' : hasCredits ? '#f59e0b' : '#6b7280'}` }}>
                {(full_name || '?')[0]}
              </div>
            )}
            {isComplete && (
              <div className="absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-emerald-500 flex items-center justify-center shadow-sm">
                <CheckCircle2 className="w-2.5 h-2.5 text-white" />
              </div>
            )}
          </div>
          <div className="flex-1 min-w-0 text-left">
            <div className="flex items-center gap-1.5">
              <span className="text-sm font-semibold text-foreground truncate">{full_name || 'Unknown'}</span>
              {username && <span className="text-[10px] text-muted-foreground">@{username}</span>}
            </div>
            <div className="mt-1.5 flex items-center gap-2">
              <div className="flex-1 h-1.5 rounded-full overflow-hidden" style={{ background: 'rgba(255,255,255,0.1)' }}>
                <div className="h-full rounded-full transition-all duration-500" style={{
                  width: `${Math.min(100, progress_pct || 0)}%`,
                  background: isComplete ? 'linear-gradient(90deg, #10b981, #34d399)' : 'linear-gradient(90deg, #06b6d4, #3b82f6)'
                }} />
              </div>
              <span className="text-[10px] font-mono text-muted-foreground flex-shrink-0">{items_delivered}/{totalSlots}</span>
            </div>
          </div>
          <div className="flex items-center gap-2 flex-shrink-0">
            {isComplete ? (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full" style={{ background: 'rgba(16,185,129,0.15)', color: '#10b981' }}>✓ Done</span>
            ) : hasCredits ? (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full" style={{ background: 'rgba(245,158,11,0.15)', color: '#f59e0b' }}>🎟️ {credits_remaining} left</span>
            ) : items_delivered === 0 ? (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full" style={{ background: 'rgba(107,114,128,0.15)', color: '#9ca3af' }}>Waiting</span>
            ) : null}
            {panelOpen ? <ChevronUp className="w-3.5 h-3.5 text-muted-foreground" /> : <ChevronDown className="w-3.5 h-3.5 text-muted-foreground" />}
          </div>
        </button>

        {/* ── Expanded Panel ── */}
        {panelOpen && (
          <div className="px-3 pb-3 space-y-3" style={{ borderTop: '1px solid rgba(255,255,255,0.06)' }}>
            {/* Row 1: Selfie + Credits */}
            <div className="flex gap-3 pt-3">
              {(selfie_url || avatar_url) && (
                <div className="flex-shrink-0 relative group cursor-pointer" onClick={() => setSelfieZoom(true)}>
                  <img src={selfie_url || avatar_url} alt={`${full_name} reference`}
                    className="w-20 h-20 rounded-xl object-cover shadow-lg"
                    style={{ border: '2px solid rgba(6,182,212,0.3)' }} />
                  <div className="absolute inset-0 rounded-xl bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <ZoomIn className="w-5 h-5 text-white" />
                  </div>
                  <div className="absolute -bottom-1.5 left-1/2 -translate-x-1/2 text-[8px] font-semibold px-1.5 py-0.5 rounded-full bg-cyan-500/20 text-cyan-400 whitespace-nowrap">
                    {selfie_url ? '📷 Selfie' : '👤 Avatar'}
                  </div>
                </div>
              )}
              <div className="flex-1 space-y-1.5">
                {videos_included > 0 ? (
                  <>
                    <CreditRow icon={<Camera className="w-3 h-3" />} label="Photos"
                      delivered={photos_delivered} included={photos_included} remaining={photos_credits_remaining} color="#06b6d4" />
                    <CreditRow icon={<Film className="w-3 h-3" />} label="Videos"
                      delivered={videos_delivered} included={videos_included} remaining={videos_credits_remaining} color="#8b5cf6" />
                  </>
                ) : (
                  <CreditRow icon={<Camera className="w-3 h-3" />} label="Content"
                    delivered={items_delivered} included={photos_included} remaining={credits_remaining} color="#06b6d4" />
                )}
                <div className="flex items-center gap-2 mt-1 flex-wrap">
                  <MiniPill icon={payment_method === 'credits' ? '✨' : '💳'}
                    text={amount_paid > 0 ? `$${amount_paid} paid` : 'Free'} />
                  <MiniPill icon={<Shield className="w-3 h-3" style={{ color: isComplete ? '#10b981' : '#f59e0b' }} />}
                    text={isComplete ? 'Fully delivered' : hasCredits ? `${credits_remaining} left` : 'Awaiting'} />
                  {/* AI vs Manual indicator (only show when items loaded) */}
                  {itemsLoaded && taggedItems.length > 0 && (
                    <>
                      {aiCount > 0 && (
                        <MiniPill icon={<Bot className="w-3 h-3 text-purple-400" />} text={`${aiCount} AI`} highlight="purple" />
                      )}
                      {manualCount > 0 && (
                        <MiniPill icon={<Hand className="w-3 h-3 text-cyan-400" />} text={`${manualCount} Manual`} highlight="cyan" />
                      )}
                    </>
                  )}
                </div>
              </div>
            </div>

            {/* Row 2: Tagged Items */}
            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[11px] font-semibold text-muted-foreground flex items-center gap-1">
                  <Tag className="w-3 h-3" /> Tagged Items
                </span>
                {taggedItems.length > 0 && (
                  <span className="text-[10px] text-muted-foreground">
                    {taggedItems.filter(i => i.media_type !== 'video').length} 📷 • {taggedItems.filter(i => i.media_type === 'video').length} 🎬
                  </span>
                )}
              </div>
              {loadingItems ? (
                <div className="flex gap-2">
                  {[1,2,3].map(i => <div key={i} className="w-16 h-16 rounded-lg animate-pulse" style={{ background: 'rgba(255,255,255,0.06)' }} />)}
                </div>
              ) : taggedItems.length > 0 ? (
                <div className="flex gap-2 overflow-x-auto pb-1" style={{ scrollbarWidth: 'none' }}>
                  {taggedItems.map(item => (
                    <TaggedItemThumb key={item.gallery_item_id} item={item}
                      onUntag={() => handleUntag(item)} isUntagging={untagging === item.gallery_item_id} />
                  ))}
                </div>
              ) : (
                <div className="text-center py-4 rounded-lg" style={{ background: 'rgba(255,255,255,0.03)', border: '1px dashed rgba(255,255,255,0.1)' }}>
                  <ImageIcon className="w-5 h-5 text-muted-foreground/40 mx-auto mb-1" />
                  <p className="text-[10px] text-muted-foreground">No items tagged yet</p>
                  <p className="text-[9px] text-muted-foreground/60 mt-0.5">Use "Tag to Surfer" on photos to assign</p>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* ── Selfie Zoom Modal ── */}
      {selfieZoom && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-sm" onClick={() => setSelfieZoom(false)}>
          <div className="relative max-w-sm w-full mx-4" onClick={e => e.stopPropagation()}>
            <button onClick={() => setSelfieZoom(false)}
              className="absolute -top-3 -right-3 w-8 h-8 rounded-full bg-black/60 border border-white/20 flex items-center justify-center z-10 hover:bg-white/20 transition-colors">
              <X className="w-4 h-4 text-white" />
            </button>
            <img src={selfie_url || avatar_url} alt={`${full_name}`}
              className="w-full rounded-2xl shadow-2xl object-cover" style={{ maxHeight: '70vh' }} />
            <div className="absolute bottom-0 left-0 right-0 p-4 rounded-b-2xl" style={{ background: 'linear-gradient(transparent, rgba(0,0,0,0.8))' }}>
              <p className="text-white font-semibold text-base">{full_name}</p>
              {username && <p className="text-white/60 text-xs">@{username}</p>}
              <div className="flex items-center gap-2 mt-1.5">
                <span className="text-[10px] px-2 py-0.5 rounded-full font-medium" style={{ background: 'rgba(6,182,212,0.3)', color: '#67e8f9' }}>
                  {selfie_url ? '📷 Session Selfie' : '👤 Profile Photo'}
                </span>
                <span className="text-[10px] text-white/50">
                  📷 {photos_delivered}/{photos_included}{videos_included > 0 ? ` • 🎬 ${videos_delivered}/${videos_included}` : ''}
                </span>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

// ── CREDIT ROW ──
const CreditRow = ({ icon, label, delivered, included, remaining, color }) => {
  const pct = included > 0 ? Math.min(100, (delivered / included) * 100) : 0;
  const isDone = remaining === 0 && delivered > 0;
  return (
    <div className="flex items-center gap-2 px-2 py-1.5 rounded-lg" style={{ background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.06)' }}>
      <div className="flex-shrink-0" style={{ color }}>{icon}</div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between">
          <span className="text-[10px] font-semibold text-foreground">{label}</span>
          <span className="text-[10px] font-mono" style={{ color: isDone ? '#10b981' : color }}>
            {delivered}/{included}
            {remaining > 0 && <span className="text-muted-foreground ml-1">({remaining} left)</span>}
            {isDone && ' ✓'}
          </span>
        </div>
        <div className="mt-0.5 h-1 rounded-full overflow-hidden" style={{ background: 'rgba(255,255,255,0.08)' }}>
          <div className="h-full rounded-full transition-all duration-500" style={{ width: `${pct}%`, background: isDone ? '#10b981' : color }} />
        </div>
      </div>
    </div>
  );
};

// ── MINI PILL ──
const MiniPill = ({ icon, text, highlight }) => (
  <div className="flex items-center gap-1 px-2 py-1 rounded-lg" style={{
    background: highlight ? `rgba(${highlight === 'purple' ? '139,92,246' : '6,182,212'},0.1)` : 'rgba(255,255,255,0.04)',
    border: `1px solid ${highlight ? `rgba(${highlight === 'purple' ? '139,92,246' : '6,182,212'},0.2)` : 'rgba(255,255,255,0.06)'}`
  }}>
    {typeof icon === 'string' ? <span className="text-[10px]">{icon}</span> : icon}
    <span className="text-[10px] text-muted-foreground">{text}</span>
  </div>
);

// ── TAGGED ITEM THUMBNAIL (with video autoplay) ──
const TaggedItemThumb = ({ item, onUntag, isUntagging }) => {
  const videoRef = useRef(null);
  const isVideo = item.media_type === 'video';
  const thumbUrl = getFullUrl(item.thumbnail_url || item.preview_url);
  const videoUrl = isVideo ? getFullUrl(item.preview_url || item.original_url) : null;
  const accessColor = item.access_type === 'included' ? '#10b981' : item.access_type === 'pending_selection' ? '#f59e0b' : '#6b7280';

  // Thumbnail-only in grid — no video autoplay to save bandwidth

  return (
    <div className="relative flex-shrink-0 group">
      <div className="w-16 h-16 rounded-lg overflow-hidden relative" style={{ border: `2px solid ${accessColor}30` }}>
        {thumbUrl ? (
          <img src={thumbUrl} alt="Tagged" className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full flex items-center justify-center" style={{ background: 'rgba(255,255,255,0.06)' }}>
            {isVideo ? <Video className="w-4 h-4 text-muted-foreground" /> : <ImageIcon className="w-4 h-4 text-muted-foreground" />}
          </div>
        )}
        {/* Media type badge */}
        <div className="absolute bottom-0.5 left-0.5 text-[7px] px-1 py-0.5 rounded font-semibold"
          style={{ background: isVideo ? 'rgba(139,92,246,0.85)' : 'rgba(6,182,212,0.85)', color: 'white' }}>
          {isVideo ? '🎬 Vid' : '📷'}
        </div>
        {/* Access indicator dot */}
        <div className="absolute top-0.5 right-0.5 w-2.5 h-2.5 rounded-full" style={{ background: accessColor, boxShadow: `0 0 4px ${accessColor}` }} />
        {/* AI indicator */}
        {item.ai_suggested ? (
          <div className="absolute top-0.5 left-0.5 flex items-center gap-0.5 px-1 py-0.5 rounded text-[7px] font-semibold" style={{ background: 'rgba(139,92,246,0.8)', color: 'white' }}>
            <Bot className="w-2 h-2" /> AI
          </div>
        ) : (
          <div className="absolute top-0.5 left-0.5 flex items-center gap-0.5 px-1 py-0.5 rounded text-[7px] font-semibold" style={{ background: 'rgba(6,182,212,0.8)', color: 'white' }}>
            <Hand className="w-2 h-2" /> 👤
          </div>
        )}
      </div>
      {/* Untag overlay */}
      <button onClick={e => { e.stopPropagation(); onUntag(); }} disabled={isUntagging}
        className="absolute inset-0 rounded-lg bg-red-500/70 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center cursor-pointer gap-0.5"
        title={`Untag ${isVideo ? 'video' : 'photo'}`}>
        {isUntagging ? (
          <div className="w-4 h-4 border-2 border-white/60 border-t-white rounded-full animate-spin" />
        ) : (
          <>
            <Minus className="w-4 h-4 text-white" />
            <span className="text-[7px] text-white font-semibold">Untag</span>
          </>
        )}
      </button>
    </div>
  );
};

export default SessionRosterCard;

/**
 * UploadPhotoModal - Bulk Photo/Video upload for photographers
 * 
 * Best practices implemented:
 * - Multi-file selection with native file picker (mobile-friendly)
 * - Drag-and-drop on desktop
 * - Sequential upload with per-file progress + global progress bar
 * - Session-aware auto-pricing (no manual price/caption fields)
 * - Per-file retry on failure with specific error messages
 * - Dropdown folder selector (not inline buttons)
 * - Client-side pre-validation (type, size) before upload starts
 */
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  X, Image, Loader2, Folder, Upload, CheckCircle2, 
  AlertCircle, Camera, Film, Info, ChevronDown, RotateCcw, Plus
} from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../ui/dialog';
import { Button } from '../ui/button';
import { useAuth } from '../../contexts/AuthContext';
import { toast } from 'sonner';
import apiClient from '../../lib/apiClient';
import logger from '../../utils/logger';


const STATUS = {
  QUEUED: 'queued',
  UPLOADING: 'uploading',
  DONE: 'done',
  ERROR: 'error'
};

// Max sizes
const MAX_VIDEO_SIZE = 100 * 1024 * 1024; // 100MB
const MAX_IMAGE_SIZE = 50 * 1024 * 1024;  // 50MB

// Accepted MIME types matching backend ALLOWED_VIDEO_TYPES / ALLOWED_IMAGE_TYPES
const ACCEPTED_VIDEO = ['video/mp4', 'video/quicktime', 'video/webm', 'video/mpeg', 'video/x-m4v'];
const ACCEPTED_IMAGE = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];

/**
 * Resolve the BASE price stored on each uploaded gallery item.
 * 
 * IMPORTANT: This always uses the photographer's General Gallery Pricing
 * (photo_price_standard / video_price_1080p). Session-specific discounts
 * (live session jump-in rates, booking rates) are applied at PURCHASE TIME
 * by the backend based on participant status — NOT baked into the item here.
 * 
 * This ensures that anonymous gallery visitors who weren't part of a session
 * see the photographer's intended standard rates.
 */
function resolveUploadPricing(_gallery, galleryPricing) {
  const defaults = { photoPrice: 5, videoPrice: 15, source: 'Gallery Default' };
  if (!galleryPricing) return defaults;

  return {
    photoPrice: galleryPricing.photo_price_standard || 5,
    videoPrice: galleryPricing.video_price_1080p || 15,
    source: 'Gallery Default'
  };
}

function formatFileSize(bytes) {
  if (bytes < 1024) return `${bytes}B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)}KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
}

/**
 * Detect non-human-readable filenames (Instagram hashes, UUIDs, numeric strings)
 * and replace with clean sequential titles like "Surf Photo 1".
 * Human-readable filenames are preserved as-is.
 */
function isHumanReadableFilename(name) {
  if (!name) return false;
  const base = name.replace(/\.[^/.]+$/, '').trim(); // strip extension
  // UUID pattern
  if (/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}/i.test(base)) return false;
  // UUID without dashes (32+ hex chars)
  if (/^[a-f0-9]{32}/i.test(base)) return false;
  // Strip common system suffixes
  const cleaned = base.replace(/_(original|preview|thumb|thumbnail)$/i, '');
  // All digits + underscores, at least 10 chars (Instagram-style)
  if (/^[\d_]+$/.test(cleaned) && cleaned.length >= 10) return false;
  // Mostly non-alpha characters in a long string (hex hashes, etc.)
  const alphaCount = (cleaned.match(/[g-zG-Z]/g) || []).length; // letters beyond hex
  if (cleaned.length > 15 && alphaCount < cleaned.length * 0.3) return false;
  return true;
}

function sanitizeItemTitle(fileName, mediaType, sequenceIndex) {
  const baseName = fileName.replace(/\.[^/.]+$/, ''); // strip extension
  if (isHumanReadableFilename(fileName)) {
    return baseName;
  }
  // Generate clean sequential title
  const label = mediaType === 'video' ? 'Surf Video' : 'Surf Photo';
  return `${label} ${sequenceIndex}`;
}

function validateFile(file) {
  const isVideo = file.type.startsWith('video/') || ACCEPTED_VIDEO.includes(file.type);
  const isImage = file.type.startsWith('image/') || ACCEPTED_IMAGE.includes(file.type);

  if (!isVideo && !isImage) {
    return { valid: false, error: `Unsupported format: ${file.type || 'unknown'}` };
  }

  const maxSize = isVideo ? MAX_VIDEO_SIZE : MAX_IMAGE_SIZE;
  if (file.size > maxSize) {
    return { valid: false, error: `Too large (${formatFileSize(file.size)}, max ${formatFileSize(maxSize)})` };
  }

  return { valid: true, type: isVideo ? 'video' : 'image' };
}


export const UploadPhotoModal = ({ 
  isOpen, 
  onClose, 
  onUploaded, 
  targetFolderId = null, 
  _targetFolderName = null, 
  galleries = [],
  galleryPricing = null,
  selectedGallery = null
}) => {
  const { user } = useAuth();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [_currentUploadId, setCurrentUploadId] = useState(null);
  const [selectedFolderId, setSelectedFolderId] = useState(targetFolderId);
  const [dragOver, setDragOver] = useState(false);
  const [uploadComplete, setUploadComplete] = useState(false);
  const [folderDropdownOpen, setFolderDropdownOpen] = useState(false);
  const fileInputRef = useRef(null);
  const abortRef = useRef(false);

  const isPaidPhotographer = user?.subscription_tier && ['basic', 'premium'].includes(user.subscription_tier);
  const pricing = resolveUploadPricing(selectedGallery, galleryPricing);

  // Reset state when modal opens
  useEffect(() => {
    if (isOpen) {
      setFiles([]);
      setUploading(false);
      setCurrentUploadId(null);
      setUploadComplete(false);
      // Default to targetFolderId if provided, otherwise first available gallery
      setSelectedFolderId(targetFolderId || (galleries.length > 0 ? galleries[0].id : null));
      setFolderDropdownOpen(false);
      abortRef.current = false;
    }
  }, [isOpen, targetFolderId, galleries]);

  // Cleanup previews on unmount
  useEffect(() => {
    return () => files.forEach(f => f.preview && URL.revokeObjectURL(f.preview));
  }, [files]);

  // Get selected folder name for dropdown label
  const selectedFolderLabel = selectedFolderId 
    ? galleries.find(g => g.id === selectedFolderId)?.title || 'Selected Folder'
    : 'Select a folder…';

  const addFiles = useCallback((newFiles) => {
    const entries = [];
    const errors = [];
    
    for (const file of newFiles) {
      const validation = validateFile(file);
      if (validation.valid) {
        entries.push({
          id: `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
          file,
          name: file.name,
          size: file.size,
          preview: validation.type === 'image' ? URL.createObjectURL(file) : null,
          type: validation.type,
          status: STATUS.QUEUED,
          progress: 0,
          error: null
        });
      } else {
        errors.push(`${file.name}: ${validation.error}`);
      }
    }

    if (errors.length > 0) {
      toast.error(`${errors.length} file${errors.length > 1 ? 's' : ''} rejected`, {
        description: errors.slice(0, 3).join('\n')
      });
    }

    if (entries.length > 0) {
      setFiles(prev => [...prev, ...entries]);
      setUploadComplete(false);
    }
  }, []);

  const removeFile = useCallback((id) => {
    setFiles(prev => {
      const file = prev.find(f => f.id === id);
      if (file?.preview) URL.revokeObjectURL(file.preview);
      return prev.filter(f => f.id !== id);
    });
  }, []);

  const handleFileSelect = (e) => {
    if (e.target.files?.length) addFiles(Array.from(e.target.files));
    e.target.value = '';
  };

  const handleDragOver = (e) => { e.preventDefault(); e.stopPropagation(); setDragOver(true); };
  const handleDragLeave = (e) => { e.preventDefault(); e.stopPropagation(); setDragOver(false); };
  const handleDrop = (e) => {
    e.preventDefault(); e.stopPropagation(); setDragOver(false);
    if (e.dataTransfer.files?.length) addFiles(Array.from(e.dataTransfer.files));
  };

  // Retry a single failed file
  const retryFile = useCallback((id) => {
    setFiles(prev => prev.map(f => 
      f.id === id ? { ...f, status: STATUS.QUEUED, progress: 0, error: null } : f
    ));
    setUploadComplete(false);
  }, []);

  // Upload single file
  const uploadSingleFile = async (fileEntry) => {
    setCurrentUploadId(fileEntry.id);
    setFiles(prev => prev.map(f => 
      f.id === fileEntry.id ? { ...f, status: STATUS.UPLOADING, progress: 0 } : f
    ));

    try {
      // Step 1: Upload file to storage
      const formData = new FormData();
      formData.append('file', fileEntry.file);
      formData.append('user_id', user.id);
      formData.append('add_watermark_preview', 'true');

      const uploadResponse = await apiClient.post('/upload/photographer-gallery', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
        timeout: fileEntry.type === 'video' ? 300000 : 120000, // 5min for video, 2min for image
        onUploadProgress: (evt) => {
          const pct = Math.round((evt.loaded * 100) / evt.total);
          setFiles(prev => prev.map(f => 
            f.id === fileEntry.id ? { ...f, progress: Math.min(pct, 95) } : f // cap at 95% until server responds
          ));
        }
      });

      // Step 2: Create gallery item with auto pricing + sanitized title
      const filePrice = fileEntry.type === 'video' ? pricing.videoPrice : pricing.photoPrice;
      const itemTitle = sanitizeItemTitle(fileEntry.name, fileEntry.type, fileEntry.batchIndex || 1);
      const createRes = await apiClient.post(`/gallery?photographer_id=${encodeURIComponent(user.id)}`, {
        title: itemTitle,
        description: '',
        media_type: fileEntry.type,
        original_url: uploadResponse.data.original_url,
        preview_url: uploadResponse.data.preview_url || uploadResponse.data.original_url,
        thumbnail_url: uploadResponse.data.thumbnail_url || uploadResponse.data.preview_url,
        price: filePrice,
        is_for_sale: true
      });

      // Step 3: Move item to selected folder if one is chosen
      if (selectedFolderId && createRes.data?.id) {
        try {
          await apiClient.patch(`/gallery/item/${createRes.data.id}/move?photographer_id=${encodeURIComponent(user.id)}`, {
            target_gallery_id: selectedFolderId
          });
        } catch (moveErr) {
          logger.warn('Could not move item to folder:', moveErr);
        }
      }

      setFiles(prev => prev.map(f => 
        f.id === fileEntry.id ? { ...f, status: STATUS.DONE, progress: 100 } : f
      ));
      return true;

    } catch (error) {
      logger.error('Upload error:', error);
      const detail = error.response?.data?.detail;
      const status = error.response?.status;
      let msg = 'Upload failed';
      if (typeof detail === 'string') msg = detail;
      else if (detail?.msg) msg = detail.msg;
      else if (status === 503) msg = 'Server starting up — tap retry in 30s';
      else if (status === 413) msg = 'File too large for server';
      else if (error.code === 'ECONNABORTED') msg = 'Upload timed out — try a smaller file or retry';
      else if (!error.response && error.message?.includes('Network')) msg = 'Server may be restarting — tap retry in 30s';
      else if (!error.response) msg = `Connection failed (${error.code || 'network'}) — retry shortly`;

      setFiles(prev => prev.map(f => 
        f.id === fileEntry.id ? { ...f, status: STATUS.ERROR, error: msg } : f
      ));
      return false;
    }
  };

  // Upload all queued files
  const handleUploadAll = async () => {
    const queued = files.filter(f => f.status === STATUS.QUEUED);
    if (queued.length === 0) return;

    setUploading(true);
    abortRef.current = false;
    let successCount = 0;

    // Assign sequential batch indices for clean title generation
    let photoIdx = 0;
    let videoIdx = 0;
    const indexedQueue = queued.map(f => {
      if (f.type === 'video') {
        videoIdx++;
        return { ...f, batchIndex: videoIdx };
      } else {
        photoIdx++;
        return { ...f, batchIndex: photoIdx };
      }
    });

    for (const fileEntry of indexedQueue) {
      if (abortRef.current) break;
      const ok = await uploadSingleFile(fileEntry);
      if (ok) successCount++;
    }

    setUploading(false);
    setCurrentUploadId(null);
    setUploadComplete(true);

    if (successCount > 0) {
      onUploaded();
    }
  };

  // Counts
  const queuedFiles = files.filter(f => f.status === STATUS.QUEUED);
  const doneFiles = files.filter(f => f.status === STATUS.DONE);
  const errorFiles = files.filter(f => f.status === STATUS.ERROR);
  const totalCount = files.length;

  const globalProgress = totalCount > 0 
    ? Math.round(files.reduce((sum, f) => sum + (f.status === STATUS.DONE ? 100 : f.progress), 0) / totalCount)
    : 0;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!uploading && !open) onClose(); }}>
      <DialogContent className="bg-background border-border text-foreground max-w-lg max-h-[92vh] overflow-y-auto p-0">
        
        {/* Header */}
        <DialogHeader className="px-4 pt-4 pb-2">
          <DialogTitle className="flex items-center gap-2 text-base">
            <Upload className="w-5 h-5 text-cyan-400" />
            Upload to Gallery
          </DialogTitle>
        </DialogHeader>

        <div className="px-4 pb-4 space-y-3">

          {/* ── Folder Dropdown ── */}
          {galleries && galleries.length > 0 && (
            <div className="relative">
              <button
                onClick={() => setFolderDropdownOpen(!folderDropdownOpen)}
                disabled={uploading}
                className="w-full flex items-center justify-between px-3 py-2.5 rounded-lg bg-card border border-border text-sm text-foreground hover:border-cyan-500/40 transition-colors"
              >
                <span className="flex items-center gap-2">
                  <Folder className="w-4 h-4 text-yellow-400" />
                  {selectedFolderLabel}
                </span>
                <ChevronDown className={`w-4 h-4 text-muted-foreground transition-transform ${folderDropdownOpen ? 'rotate-180' : ''}`} />
              </button>

              {folderDropdownOpen && (
                <>
                  {/* Invisible overlay to close dropdown */}
                  <div className="fixed inset-0 z-10" onClick={() => setFolderDropdownOpen(false)} />
                  
                  <div className="absolute z-20 mt-1 w-full bg-card border border-border rounded-lg shadow-xl max-h-48 overflow-y-auto">
                    {galleries.map((folder) => (
                      <button
                        key={folder.id}
                        onClick={() => { setSelectedFolderId(folder.id); setFolderDropdownOpen(false); }}
                        className={`w-full text-left px-3 py-2.5 text-sm hover:bg-muted/60 transition-colors flex items-center gap-2 border-b border-border/30 last:border-0 ${
                          selectedFolderId === folder.id ? 'text-cyan-400 bg-cyan-500/5' : 'text-foreground'
                        }`}
                      >
                        <Folder className="w-4 h-4 text-yellow-400 flex-shrink-0" />
                        <span className="truncate">{folder.title}</span>
                      </button>
                    ))}
                  </div>
                </>
              )}
            </div>
          )}

          {/* ── Pricing Banner ── */}
          <div className="flex items-center gap-3 px-3 py-2.5 rounded-lg bg-gradient-to-r from-cyan-500/8 to-blue-500/8 border border-cyan-500/15">
            <Info className="w-4 h-4 text-cyan-400 shrink-0" />
            <div className="flex items-center gap-3 text-xs flex-wrap">
              <span className="flex items-center gap-1 text-muted-foreground">
                <Camera className="w-3.5 h-3.5 text-cyan-400" />
                Photo: <strong className="text-foreground">${pricing.photoPrice.toFixed(2)}</strong>
              </span>
              <span className="flex items-center gap-1 text-muted-foreground">
                <Film className="w-3.5 h-3.5 text-purple-400" />
                Video: <strong className="text-foreground">${pricing.videoPrice.toFixed(2)}</strong>
              </span>
              <span className="text-muted-foreground/60">
                ({pricing.source})
              </span>
            </div>
          </div>

          {/* ── Hidden File Input ── */}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*,video/*,.mp4,.mov,.webm,.m4v,.mpeg,.jpg,.jpeg,.png,.gif,.webp"
            multiple
            onChange={handleFileSelect}
            className="hidden"
          />

          {/* ── Empty State / Drop Zone ── */}
          {files.length === 0 ? (
            <button
              onClick={() => fileInputRef.current?.click()}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              className={`w-full py-12 rounded-xl border-2 border-dashed flex flex-col items-center justify-center gap-3 transition-all active:scale-[0.98] ${
                dragOver 
                  ? 'border-cyan-400 bg-cyan-500/10' 
                  : 'border-border hover:border-cyan-400/40 bg-card'
              }`}
            >
              <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-cyan-500/20 to-purple-500/20 flex items-center justify-center">
                <Upload className="w-7 h-7 text-cyan-400" />
              </div>
              <div className="text-center px-4">
                <p className="text-foreground font-semibold text-sm">Select photos & videos</p>
                <p className="text-xs text-muted-foreground mt-1">
                  Select multiple files • Images up to 50MB • Videos up to 100MB ({isPaidPhotographer ? '4K' : '1080p'})
                </p>
              </div>
            </button>
          ) : (
            <>
              {/* ── File Count + Add More ── */}
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-1.5 text-xs">
                  {files.filter(f => f.type === 'image').length > 0 && (
                    <span className="flex items-center gap-1 bg-cyan-500/10 text-cyan-400 px-2 py-0.5 rounded-full font-medium">
                      <Camera className="w-3 h-3" /> {files.filter(f => f.type === 'image').length}
                    </span>
                  )}
                  {files.filter(f => f.type === 'video').length > 0 && (
                    <span className="flex items-center gap-1 bg-purple-500/10 text-purple-400 px-2 py-0.5 rounded-full font-medium">
                      <Film className="w-3 h-3" /> {files.filter(f => f.type === 'video').length}
                    </span>
                  )}
                  {doneFiles.length > 0 && (
                    <span className="flex items-center gap-1 bg-green-500/10 text-green-400 px-2 py-0.5 rounded-full font-medium">
                      <CheckCircle2 className="w-3 h-3" /> {doneFiles.length}
                    </span>
                  )}
                </div>
                {!uploading && (
                  <button
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-1 text-xs text-cyan-400 hover:text-cyan-300 font-medium px-2 py-1 rounded-md hover:bg-cyan-500/10 transition-colors"
                  >
                    <Plus className="w-3.5 h-3.5" /> Add more
                  </button>
                )}
              </div>

              {/* ── File List ── */}
              <div className="space-y-1.5 max-h-56 overflow-y-auto rounded-lg">
                {files.map((f) => (
                  <div
                    key={f.id}
                    className={`flex items-center gap-2.5 p-2 rounded-lg border transition-colors ${
                      f.status === STATUS.ERROR ? 'bg-red-500/5 border-red-500/20' :
                      f.status === STATUS.DONE ? 'bg-green-500/5 border-green-500/20' :
                      f.status === STATUS.UPLOADING ? 'bg-cyan-500/5 border-cyan-500/20' :
                      'bg-card border-border'
                    }`}
                  >
                    {/* Thumbnail */}
                    <div className="w-10 h-10 rounded-md overflow-hidden bg-muted shrink-0 flex items-center justify-center">
                      {f.type === 'video' ? (
                        <Film className="w-5 h-5 text-purple-400" />
                      ) : f.preview ? (
                        <img src={f.preview} alt="" className="w-full h-full object-cover" />
                      ) : (
                        <Camera className="w-5 h-5 text-cyan-400" />
                      )}
                    </div>

                    {/* Name + Status */}
                    <div className="flex-1 min-w-0">
                      <p className="text-xs text-foreground truncate font-medium">
                        {f.name}
                      </p>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className="text-[10px] text-muted-foreground">
                          {formatFileSize(f.size)} • {f.type === 'video' ? 'Video' : 'Photo'}
                        </span>
                        {f.status === STATUS.UPLOADING && (
                          <span className="text-[10px] text-cyan-400 font-medium">{f.progress}%</span>
                        )}
                        {f.status === STATUS.ERROR && (
                          <span className="text-[10px] text-red-400 truncate max-w-[140px]">{f.error}</span>
                        )}
                      </div>
                      {/* Progress bar for uploading */}
                      {f.status === STATUS.UPLOADING && (
                        <div className="h-1 bg-muted rounded-full mt-1 overflow-hidden">
                          <div className="h-full bg-cyan-400 transition-all duration-300 rounded-full" style={{ width: `${f.progress}%` }} />
                        </div>
                      )}
                    </div>

                    {/* Action */}
                    <div className="shrink-0">
                      {f.status === STATUS.QUEUED && !uploading && (
                        <button onClick={() => removeFile(f.id)} className="p-1 hover:bg-muted rounded-md transition-colors">
                          <X className="w-4 h-4 text-muted-foreground" />
                        </button>
                      )}
                      {f.status === STATUS.UPLOADING && (
                        <Loader2 className="w-4 h-4 text-cyan-400 animate-spin" />
                      )}
                      {f.status === STATUS.DONE && (
                        <CheckCircle2 className="w-4 h-4 text-green-400" />
                      )}
                      {f.status === STATUS.ERROR && (
                        <button onClick={() => retryFile(f.id)} className="p-1 hover:bg-muted rounded-md transition-colors" title="Retry">
                          <RotateCcw className="w-4 h-4 text-red-400" />
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>

              {/* ── Global Progress ── */}
              {uploading && (
                <div className="space-y-1.5">
                  <div className="h-2 bg-muted rounded-full overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-cyan-400 to-blue-500 transition-all duration-300 rounded-full"
                      style={{ width: `${globalProgress}%` }}
                    />
                  </div>
                  <p className="text-xs text-muted-foreground text-center">
                    Uploading… {globalProgress}%
                  </p>
                </div>
              )}

              {/* ── Upload Complete Summary ── */}
              {uploadComplete && (
                <div className={`flex items-center gap-2 p-3 rounded-lg border ${
                  errorFiles.length > 0 && doneFiles.length > 0 
                    ? 'bg-yellow-500/5 border-yellow-500/20' 
                    : errorFiles.length > 0 
                      ? 'bg-red-500/5 border-red-500/20' 
                      : 'bg-green-500/5 border-green-500/20'
                }`}>
                  {doneFiles.length > 0 ? (
                    <CheckCircle2 className="w-4 h-4 text-green-400 shrink-0" />
                  ) : (
                    <AlertCircle className="w-4 h-4 text-red-400 shrink-0" />
                  )}
                  <p className="text-xs text-foreground">
                    {doneFiles.length > 0 && `${doneFiles.length} uploaded`}
                    {doneFiles.length > 0 && errorFiles.length > 0 && ' • '}
                    {errorFiles.length > 0 && (
                      <span className="text-red-400">{errorFiles.length} failed — tap <RotateCcw className="w-3 h-3 inline" /> to retry</span>
                    )}
                  </p>
                </div>
              )}
            </>
          )}

          {/* ── Actions ── */}
          <div className="flex gap-2 pt-1">
            {!uploadComplete ? (
              <Button
                onClick={handleUploadAll}
                disabled={uploading || queuedFiles.length === 0 || !selectedFolderId}
                className="flex-1 h-12 bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white font-bold rounded-xl disabled:opacity-50"
                data-testid="upload-submit"
              >
                {uploading ? (
                  <span className="flex items-center gap-2">
                    <Loader2 className="w-5 h-5 animate-spin" />
                    Uploading…
                  </span>
                ) : (
                  `Upload ${queuedFiles.length} file${queuedFiles.length !== 1 ? 's' : ''}`
                )}
              </Button>
            ) : (
              <div className="flex gap-2 flex-1">
                {errorFiles.length > 0 && queuedFiles.length > 0 && (
                  <Button
                    onClick={handleUploadAll}
                    className="flex-1 h-12 bg-gradient-to-r from-yellow-500 to-orange-500 hover:from-yellow-600 hover:to-orange-600 text-black font-bold rounded-xl"
                  >
                    Retry {queuedFiles.length}
                  </Button>
                )}
                <Button
                  onClick={onClose}
                  className="flex-1 h-12 bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 text-white font-bold rounded-xl"
                >
                  Done
                </Button>
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default UploadPhotoModal;

import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Avatar, AvatarImage, AvatarFallback } from '../ui/avatar';
import { Input } from '../ui/input';
import { toast } from 'sonner';
import apiClient from '../../lib/apiClient';
import { getFullUrl } from '../../utils/media';
import {
  ShoppingCart, CheckCircle, XCircle, Clock, DollarSign,
  Loader2, Camera, Package, CreditCard, RefreshCw,
  ChevronDown
} from 'lucide-react';
import logger from '../../utils/logger';

/**
 * PurchaseRequestsPanel — GromHQ sub-component
 * Shows pending purchase requests from linked Groms for parent approval/denial.
 */
export const PurchaseRequestsPanel = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const isLight = theme === 'light';

  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('pending'); // pending | approved | denied | all
  const [processingId, setProcessingId] = useState(null);
  const [denyReason, setDenyReason] = useState('');
  const [showDenyInput, setShowDenyInput] = useState(null);
  const [pendingCount, setPendingCount] = useState(0);

  // Theme tokens
  const cardBg = isLight ? 'bg-white' : 'bg-zinc-900';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-500' : 'text-zinc-400';
  const borderColor = isLight ? 'border-gray-200' : 'border-zinc-800';

  const ITEM_TYPE_ICONS = {
    gallery_photo: Camera,
    credit_pack: CreditCard,
    gear_item: Package
  };

  const ITEM_TYPE_LABELS = {
    gallery_photo: 'Photo',
    credit_pack: 'Credits',
    gear_item: 'Gear'
  };

  const fetchRequests = useCallback(async () => {
    if (!user?.id) return;
    setLoading(true);
    try {
      const res = await apiClient.get(`/grom-hq/purchase-requests/${user.id}?status=${filter}`);
      setRequests(res.data.requests || []);
      setPendingCount(res.data.pending_count || 0);
    } catch (err) {
      logger.error('Failed to fetch purchase requests:', err);
      setRequests([]);
    } finally {
      setLoading(false);
    }
  }, [user?.id, filter]);

  useEffect(() => { fetchRequests(); }, [fetchRequests]);

  const handleApprove = async (requestId) => {
    setProcessingId(requestId);
    try {
      const res = await apiClient.post(
        `/grom-hq/purchase-requests/${requestId}/approve?parent_id=${user.id}`
      );
      toast.success(res.data.message || 'Approved!');
      // Remove from list
      setRequests(prev => prev.filter(r => r.id !== requestId));
      setPendingCount(prev => Math.max(0, prev - 1));
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to approve');
    } finally {
      setProcessingId(null);
    }
  };

  const handleDeny = async (requestId) => {
    setProcessingId(requestId);
    try {
      const res = await apiClient.post(
        `/grom-hq/purchase-requests/${requestId}/deny?parent_id=${user.id}&reason=${encodeURIComponent(denyReason)}`
      );
      toast.success(res.data.message || 'Denied');
      setRequests(prev => prev.filter(r => r.id !== requestId));
      setPendingCount(prev => Math.max(0, prev - 1));
      setShowDenyInput(null);
      setDenyReason('');
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to deny');
    } finally {
      setProcessingId(null);
    }
  };

  const getStatusBadge = (status) => {
    switch (status) {
      case 'pending':
        return <Badge className="bg-yellow-500/20 text-yellow-400 border-0"><Clock className="w-3 h-3 mr-1" /> Pending</Badge>;
      case 'approved':
        return <Badge className="bg-emerald-500/20 text-emerald-400 border-0"><CheckCircle className="w-3 h-3 mr-1" /> Approved</Badge>;
      case 'denied':
        return <Badge className="bg-red-500/20 text-red-400 border-0"><XCircle className="w-3 h-3 mr-1" /> Denied</Badge>;
      default:
        return null;
    }
  };

  return (
    <Card className={`${cardBg} border-2 border-amber-500/30`} data-testid="purchase-requests-panel">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className={`${textPrimary} flex items-center gap-2 text-base`}>
            <ShoppingCart className="w-5 h-5 text-amber-400" />
            Purchase Requests
            {pendingCount > 0 && (
              <Badge className="ml-2 bg-amber-500/20 text-amber-400 border-0 animate-pulse">
                {pendingCount} PENDING
              </Badge>
            )}
          </CardTitle>
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={fetchRequests}
              className="text-amber-400 hover:text-amber-300"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            </Button>
            {/* Filter dropdown */}
            <select
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              className={`text-xs rounded-md px-2 py-1 ${isLight ? 'bg-gray-100 text-gray-700' : 'bg-zinc-800 text-zinc-300'} border ${borderColor}`}
            >
              <option value="pending">Pending</option>
              <option value="approved">Approved</option>
              <option value="denied">Denied</option>
              <option value="all">All</option>
            </select>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-3">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 text-amber-400 animate-spin" />
          </div>
        ) : requests.length === 0 ? (
          <div className="text-center py-8">
            <ShoppingCart className={`w-10 h-10 mx-auto mb-2 ${isLight ? 'text-gray-300' : 'text-zinc-700'}`} />
            <p className={`text-sm ${textSecondary}`}>
              {filter === 'pending' ? 'No pending requests' : `No ${filter} requests`}
            </p>
            <p className={`text-xs ${textSecondary} mt-1`}>
              When your Grom tries to buy something, it will appear here for your approval.
            </p>
          </div>
        ) : (
          requests.map((req) => {
            const Icon = ITEM_TYPE_ICONS[req.item_type] || Package;
            const typeLabel = ITEM_TYPE_LABELS[req.item_type] || req.item_type;
            const isProcessing = processingId === req.id;

            return (
              <div
                key={req.id}
                className={`p-4 rounded-xl transition-all ${
                  isLight ? 'bg-gray-50' : 'bg-zinc-800/50'
                } ${req.status === 'pending' ? `border-l-4 border-amber-500` : ''}`}
                data-testid={`purchase-request-${req.id}`}
              >
                {/* Header row */}
                <div className="flex items-center gap-3 mb-3">
                  <Avatar className="w-10 h-10 border border-amber-500/30">
                    <AvatarImage src={getFullUrl(req.grom_avatar)} />
                    <AvatarFallback className="bg-amber-500/20 text-amber-400">
                      {req.grom_name?.[0] || 'G'}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex-1 min-w-0">
                    <p className={`font-medium text-sm ${textPrimary}`}>{req.grom_name}</p>
                    <p className={`text-xs ${textSecondary}`}>
                      {req.created_at ? new Date(req.created_at).toLocaleDateString('en-US', {
                        month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'
                      }) : ''}
                    </p>
                  </div>
                  {getStatusBadge(req.status)}
                </div>

                {/* Item details */}
                <div className={`flex items-center gap-3 p-3 rounded-lg ${isLight ? 'bg-white' : 'bg-zinc-900'} mb-3`}>
                  <div className="w-10 h-10 rounded-lg bg-amber-500/10 flex items-center justify-center">
                    <Icon className="w-5 h-5 text-amber-400" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={`font-medium text-sm ${textPrimary} truncate`}>{req.item_name}</p>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className={`text-xs ${textSecondary}`}>{typeLabel}</span>
                      {req.quality_tier && (
                        <Badge variant="outline" className={`text-xs ${borderColor} ${textSecondary}`}>
                          {req.quality_tier}
                        </Badge>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-lg font-bold text-amber-400 flex items-center gap-1">
                      <DollarSign className="w-4 h-4" />
                      {req.amount?.toFixed(2)}
                    </p>
                  </div>
                </div>

                {/* Action buttons (only for pending) */}
                {req.status === 'pending' && (
                  <>
                    {showDenyInput === req.id ? (
                      <div className="space-y-2">
                        <Input
                          placeholder="Reason (optional)..."
                          value={denyReason}
                          onChange={(e) => setDenyReason(e.target.value)}
                          className={`${isLight ? 'bg-white' : 'bg-zinc-800'} ${borderColor} text-sm`}
                        />
                        <div className="flex gap-2">
                          <Button
                            size="sm"
                            className="flex-1 bg-red-500 hover:bg-red-600 text-white"
                            onClick={() => handleDeny(req.id)}
                            disabled={isProcessing}
                          >
                            {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Confirm Deny'}
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            className={`${borderColor} ${textSecondary}`}
                            onClick={() => { setShowDenyInput(null); setDenyReason(''); }}
                          >
                            Cancel
                          </Button>
                        </div>
                      </div>
                    ) : (
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          className="flex-1 bg-emerald-500 hover:bg-emerald-600 text-white"
                          onClick={() => handleApprove(req.id)}
                          disabled={isProcessing}
                          data-testid={`approve-request-${req.id}`}
                        >
                          {isProcessing ? (
                            <Loader2 className="w-4 h-4 animate-spin mr-1" />
                          ) : (
                            <CheckCircle className="w-4 h-4 mr-1" />
                          )}
                          Approve
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          className="flex-1 border-red-500/50 text-red-400 hover:bg-red-500/10"
                          onClick={() => setShowDenyInput(req.id)}
                          disabled={isProcessing}
                          data-testid={`deny-request-${req.id}`}
                        >
                          <XCircle className="w-4 h-4 mr-1" />
                          Deny
                        </Button>
                      </div>
                    )}
                  </>
                )}
              </div>
            );
          })
        )}
      </CardContent>
    </Card>
  );
};

export default PurchaseRequestsPanel;

import React, { useState, useEffect, useRef } from 'react';
import apiClient from '../../lib/apiClient';
import { isProLevelRole, isBusinessRole } from '../../contexts/PersonaContext';
import { Check, X, Search, Users, Star, Camera, Briefcase, Store, Shield } from 'lucide-react';
import { Button } from '../ui/button';
import logger from '../../utils/logger';

// Alias for compatibility with internal code
const isProRole = isProLevelRole;

// Role icon helper (inline since it uses MessagesPage internal logic)
const getRoleIcon = (role, isAdmin = false) => {
  if (isAdmin) return { icon: Shield, color: 'text-red-500', label: 'God Mode', emoji: '🔴' };
  switch (role) {
    case 'Pro': case 'Comp Surfer': return { icon: Star, color: 'text-amber-400', label: 'Pro', emoji: '⭐' };
    case 'Approved Pro': return { icon: Camera, color: 'text-blue-400', label: 'Pro Photographer', emoji: '📸' };
    case 'Photographer': return { icon: Camera, color: 'text-purple-400', label: 'Photographer', emoji: '📷' };
    case 'Shop': return { icon: Store, color: 'text-pink-400', label: 'Surf Shop', emoji: '🛍️' };
    case 'Surf School': return { icon: Users, color: 'text-teal-400', label: 'Surf School', emoji: '🌬️' };
    case 'Shaper': return { icon: Briefcase, color: 'text-orange-400', label: 'Shaper', emoji: '🛠️' };
    case 'Resort': return { icon: Store, color: 'text-emerald-400', label: 'Resort', emoji: '🌴' };
    default: return { icon: null, color: 'text-cyan-400', label: 'Surfer', emoji: '🏄' };
  }
};

const ComposeModal = ({ isOpen, onClose, onSelectUser, currentUserId }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [_suggestedUsers, setSuggestedUsers] = useState([]);
  const [searchResults, setSearchResults] = useState([]);
  const [recentContacts, setRecentContacts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedUsers, setSelectedUsers] = useState([]);
  const inputRef = useRef(null);

  // Fetch suggested users on mount
  useEffect(() => {
    if (isOpen && currentUserId) {
      fetchSuggestedUsers();
      // Focus input on open
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isOpen, currentUserId]);

  // Search users when term changes
  useEffect(() => {
    if (searchTerm.trim()) {
      searchUsers(searchTerm);
    } else {
      setSearchResults([]);
    }
  }, [searchTerm]);

  const fetchSuggestedUsers = async () => {
    setLoading(true);
    try {
      // Fetch recent conversations for frequent contacts
      const convResponse = await apiClient.get(`/messages/conversations/${currentUserId}?inbox_type=all`);
      const recentUsers = convResponse.data.slice(0, 10).map(c => ({
        id: c.other_user_id,
        name: c.other_user_name,
        username: c.other_username,  // Use actual username from API
        avatar: c.other_user_avatar,
        role: c.other_user_role,
        isRecent: true
      }));
      setRecentContacts(recentUsers);

      // Top 3 frequent contacts for horizontal row
      setSuggestedUsers(recentUsers.slice(0, 3));
    } catch (error) {
      logger.error('Failed to fetch suggested users:', error);
    } finally {
      setLoading(false);
    }
  };

  const searchUsers = async (term) => {
    setLoading(true);
    try {
      const response = await apiClient.get(`/profiles/search?q=${encodeURIComponent(term)}&limit=20`);
      
      // Results are already sorted by backend: God Mode > Pros > Photographers > Businesses > Users
      setSearchResults(response.data.map(u => ({
        id: u.id,
        name: u.full_name,
        username: u.username,  // Use actual username from API (no fallback)
        avatar: u.avatar_url,
        role: u.role,
        isAdmin: u.is_admin,
        isPro: isProRole(u.role),
        isBusiness: isBusinessRole(u.role),
        isFollowing: u.is_following,
        followsYou: u.follows_you,
        isMutual: u.is_mutual
      })));
    } catch (error) {
      logger.error('Search failed:', error);
    } finally {
      setLoading(false);
    }
  };

  const _handleSelectUser = (user) => {
    setSelectedUsers([user]);
  };

  const handleStartChat = () => {
    if (selectedUsers.length > 0) {
      onSelectUser(selectedUsers[0]);
      onClose();
    }
  };

  const handleUserClick = (user) => {
    // Direct navigation to chat
    onSelectUser(user);
    onClose();
  };

  const clearSearch = () => {
    setSearchTerm('');
    setSearchResults([]);
    inputRef.current?.focus();
  };

  if (!isOpen) return null;

  const displayUsers = searchTerm.trim() ? searchResults : recentContacts;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm" onClick={onClose}>
      <div 
        className="w-full max-w-md mx-4 bg-card rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-4 border-b border-border">
          <div className="w-6" />
          <h2 className="text-lg font-semibold text-foreground">New message</h2>
          <button onClick={onClose} className="text-muted-foreground hover:text-foreground">
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Search Input */}
        <div className="px-4 py-3 border-b border-border">
          <div className="flex items-center gap-2">
            <span className="text-muted-foreground text-sm">To:</span>
            <div className="flex-1 relative">
              <input
                ref={inputRef}
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Search..."
                className="w-full bg-transparent text-foreground placeholder-muted-foreground text-sm focus:outline-none"
                data-testid="compose-search-input"
              />
              {searchTerm && (
                <button 
                  onClick={clearSearch}
                  className="absolute right-0 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>
          </div>
        </div>

        {/* User List */}
        <div className="max-h-[400px] overflow-y-auto">
          {/* Suggested Label */}
          {!searchTerm.trim() && (
            <div className="px-4 py-2">
              <span className="text-sm font-semibold text-foreground">Suggested</span>
            </div>
          )}

          {/* Loading State */}
          {loading && (
            <div className="flex items-center justify-center py-8">
              <div className="w-6 h-6 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin" />
            </div>
          )}

          {/* User List */}
          {!loading && displayUsers.map((user) => {
            const roleInfo = getRoleIcon(user.role, user.isAdmin);
            const RoleIcon = roleInfo.icon;
            
            return (
              <button
                key={user.id}
                onClick={() => handleUserClick(user)}
                className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-muted transition-colors ${
                  selectedUsers.some(u => u.id === user.id) ? 'bg-muted' : ''
                }`}
                data-testid={`compose-user-${user.id}`}
              >
                {/* Avatar */}
                <div className="relative">
                  <div className={`w-12 h-12 rounded-full overflow-hidden ${
                    user.isAdmin ? 'ring-2 ring-red-500/50' :
                    user.isPro ? 'ring-2 ring-amber-400/50' : 
                    user.isBusiness ? 'ring-2 ring-purple-400/50' : ''
                  }`}>
                    {user.avatar ? (
                      <img src={user.avatar} alt="" className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center text-white text-lg font-semibold">
                        {user.name?.charAt(0)}
                      </div>
                    )}
                  </div>
                  {/* Mutual Follow Badge */}
                  {user.isMutual && (
                    <div className="absolute -bottom-0.5 -right-0.5 w-5 h-5 bg-emerald-500 rounded-full flex items-center justify-center border-2 border-card" title="Mutual Follow">
                      <Users className="w-3 h-3 text-white" />
                    </div>
                  )}
                </div>

                {/* User Info */}
                <div className="flex-1 text-left">
                  <div className="flex items-center gap-1.5">
                    <span className="font-medium text-foreground">{user.name}</span>
                    {RoleIcon ? (
                      <RoleIcon className={`w-4 h-4 ${roleInfo.color}`} />
                    ) : (
                      <span className="text-sm">🏄</span>
                    )}
                  </div>
                  <div className="flex items-center gap-1">
                    {user.username && (
                      <span className="text-sm text-muted-foreground">@{user.username}</span>
                    )}
                    <span className="text-xs text-muted-foreground/70">{user.username ? '·' : ''} {roleInfo.label}</span>
                    {/* Follow status indicator */}
                    {user.isMutual && (
                      <span className="text-xs text-emerald-400 ml-1">· Mutuals</span>
                    )}
                    {!user.isMutual && user.followsYou && (
                      <span className="text-xs text-cyan-400 ml-1">· Follows you</span>
                    )}
                  </div>
                </div>

                {/* Selection Circle */}
                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${
                  selectedUsers.some(u => u.id === user.id) 
                    ? 'border-cyan-400 bg-cyan-400' 
                    : 'border-muted-foreground/50'
                }`}>
                  {selectedUsers.some(u => u.id === user.id) && (
                    <Check className="w-4 h-4 text-black" />
                  )}
                </div>
              </button>
            );
          })}

          {/* Empty State */}
          {!loading && displayUsers.length === 0 && searchTerm.trim() && (
            <div className="flex flex-col items-center justify-center py-8 text-muted-foreground">
              <p>No users found</p>
            </div>
          )}
        </div>

        {/* Chat Button */}
        <div className="p-4 border-t border-border">
          <Button
            onClick={handleStartChat}
            disabled={selectedUsers.length === 0}
            className="w-full bg-gradient-to-r from-cyan-500 to-blue-600 text-white font-semibold py-3 rounded-xl disabled:opacity-50"
            data-testid="compose-chat-button"
          >
            Chat
          </Button>
        </div>
      </div>
    </div>
  );
};

export default ComposeModal;

/**
 * GifPicker.js — Tenor API-powered GIF picker for MessagesPage.
 *
 * Fully self-contained: no backend calls, no auth context.
 * Uses Tenor v2 API (Google) with free public key.
 *
 * Props:
 *   show     {boolean}   Whether the picker is visible
 *   onSelect {function}  Called with (gifUrl: string) when user picks a GIF
 *   onClose  {function}  Called when user closes the picker
 */
import React, { useState, useEffect, useRef } from 'react';
import { Search, X } from 'lucide-react';

// Tenor API key - Google free tier (replace with env var if needed)
const TENOR_API_KEY = process.env.REACT_APP_TENOR_API_KEY || 'AIzaSyAyimkuYQYF_FXVALexPuGQctUWRURdCYQ';
const TENOR_BASE = 'https://tenor.googleapis.com/v2';
const GIF_LIMIT = 20;
const MEDIA_FILTERS = 'gif,tinygif';

/** Map a Tenor v2 result to a consistent GIF shape */
const mapTenorResult = (g) => ({
  id: g.id,
  title: g.content_description || 'GIF',
  images: {
    fixed_height: {
      url: g.media_formats?.gif?.url || g.media_formats?.mediumgif?.url || g.media_formats?.tinygif?.url,
    },
    fixed_height_small: {
      url: g.media_formats?.tinygif?.url || g.media_formats?.nanogif?.url,
    },
    original: {
      url: g.media_formats?.gif?.url,
    },
  },
});

const GifPicker = ({ show, onSelect, onClose }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [gifs, setGifs] = useState([]);
  const [trendingGifs, setTrendingGifs] = useState([]);
  const [loading, setLoading] = useState(false);
  const pickerRef = useRef(null);
  const isScrollingRef = useRef(false);

  // Load trending GIFs once when picker first opens
  useEffect(() => {
    if (show && trendingGifs.length === 0) {
      fetchTrending();
    }
  }, [show]); // intentionally omits fetchTrending from deps — only run once on first open


  // Click-outside to close (respects scroll vs click distinction)
  useEffect(() => {
    if (!show) return;
    const handleClickOutside = (e) => {
      if (isScrollingRef.current) return;
      if (pickerRef.current && !pickerRef.current.contains(e.target)) onClose();
    };
    // Delay to prevent immediate close when the picker is opened from a button click
    const id = setTimeout(() => document.addEventListener('mousedown', handleClickOutside), 150);
    return () => {
      clearTimeout(id);
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [show, onClose]);

  // Debounced search
  useEffect(() => {
    const id = setTimeout(() => {
      if (searchTerm.trim()) {
        searchGifs(searchTerm.trim());
      } else {
        setGifs([]);
      }
    }, 300);
    return () => clearTimeout(id);
  }, [searchTerm]);

  const fetchTrending = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${TENOR_BASE}/featured?key=${TENOR_API_KEY}&limit=${GIF_LIMIT}&media_filter=${MEDIA_FILTERS}`);
      const data = await res.json();
      setTrendingGifs((data.results || []).map(mapTenorResult));
    } catch (err) {
      // Silent — picker just shows empty state
    } finally {
      setLoading(false);
    }
  };

  const searchGifs = async (query) => {
    setLoading(true);
    try {
      const res = await fetch(`${TENOR_BASE}/search?key=${TENOR_API_KEY}&q=${encodeURIComponent(query)}&limit=${GIF_LIMIT}&media_filter=${MEDIA_FILTERS}`);
      const data = await res.json();
      setGifs((data.results || []).map(mapTenorResult));
    } catch (err) {
      // Silent
    } finally {
      setLoading(false);
    }
  };

  const handleGifSelect = (gifUrl, e) => {
    e.preventDefault();
    e.stopPropagation();
    if (gifUrl) onSelect(gifUrl);
  };

  const displayGifs = searchTerm ? gifs : trendingGifs;

  if (!show) return null;

  return (
    <div
      ref={pickerRef}
      className="absolute left-0 w-[320px] max-w-[calc(100vw-32px)] bottom-full mb-2 h-[420px] max-h-[60vh] flex flex-col bg-card rounded-xl shadow-2xl border border-border overflow-hidden z-[100]"
    >
      {/* Header */}
      <div className="p-3 border-b border-border">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-foreground">GIF Picker</span>
          <button onClick={onClose} className="p-1 rounded-full hover:bg-muted" type="button">
            <X className="w-5 h-5 text-muted-foreground" />
          </button>
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search GIFs..."
            className="w-full bg-muted rounded-full pl-10 pr-4 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-cyan-500"
          />
        </div>
        <div className="flex items-center justify-between mt-2">
          <span className="text-xs text-muted-foreground">
            {searchTerm ? `Results for "${searchTerm}"` : 'Trending GIFs'}
          </span>
          <span className="text-[10px] text-muted-foreground opacity-50">Powered by Tenor</span>
        </div>
      </div>

      {/* GIF Grid */}
      <div
        className="p-2 overflow-y-auto flex-1 grid grid-cols-3 gap-2 overscroll-contain"
        onTouchStart={() => { isScrollingRef.current = false; }}
        onTouchMove={() => { isScrollingRef.current = true; }}
        onTouchEnd={() => { setTimeout(() => { isScrollingRef.current = false; }, 100); }}
      >
        {loading ? (
          <div className="col-span-3 flex items-center justify-center py-8">
            <div className="w-6 h-6 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : displayGifs.length === 0 ? (
          <div className="col-span-3 text-center py-8 text-muted-foreground text-sm">
            {searchTerm ? 'No GIFs found' : 'Loading...'}
          </div>
        ) : (
          displayGifs.map((gif) => {
            const gifUrl = gif.images?.fixed_height?.url || gif.images?.original?.url;
            const previewUrl = gif.images?.fixed_height_small?.url || gifUrl;
            if (!gifUrl) return null;
            return (
              <button
                type="button"
                key={gif.id}
                onMouseDown={(e) => { e.preventDefault(); e.stopPropagation(); }}
                onClick={(e) => handleGifSelect(gifUrl, e)}
                onTouchEnd={(e) => { if (!isScrollingRef.current) handleGifSelect(gifUrl, e); }}
                className="relative rounded-lg overflow-hidden hover:ring-2 hover:ring-cyan-500 transition-all aspect-square cursor-pointer bg-zinc-800 touch-manipulation"
                data-testid="gif-item"
              >
                <img
                  src={previewUrl}
                  alt={gif.title || 'GIF'}
                  className="w-full h-full object-cover pointer-events-none select-none"
                  loading="lazy"
                  draggable={false}
                />
              </button>
            );
          })
        )}
      </div>
    </div>
  );
};

export default GifPicker;

/**
 * InCallView — Premium active call overlay.
 * 
 * FILTER IMPLEMENTATION — Uses the SAME WebGL GPU shader pipeline as GoLive:
 *   - WebGLVideoProcessor from WebGLFilterEngine.js
 *   - Real GLSL fragment shaders running on the GPU
 *   - Hidden <video> feeds into WebGL <canvas> for filtered display
 *   - Works reliably on all platforms including mobile (bypasses CSS filter limitations)
 *
 * REMOTE VIDEO:
 *   - object-contain to prevent face cropping
 *   - Dark background for letterboxing
 * 
 * HAIR FILTERS:
 *   - Uses HairFilterPicker component (same as GoLive)
 */

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { 
  Mic, MicOff, Video, VideoOff, PhoneOff, 
  Volume2, VolumeX, Maximize2, Minimize2, Signal, SignalLow, SignalZero,
  Sparkles, X, Scissors, SwitchCamera,
  Sunset, Waves, Moon, Zap, Eye, Grid, CircleDot
} from 'lucide-react';
import { HairFilterPicker } from '../HairFilterPicker';
import { WebGLVideoProcessor } from '../../utils/WebGLFilterEngine';
import { HairFilterEngine } from '../../utils/HairFilterEngine';

// ── Duration formatter ──────────────────────────────────────────────
function formatDuration(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
}

// ── Connection Quality Badge ────────────────────────────────────────
function ConnectionQualityBadge({ quality }) {
  const config = {
    good: { icon: Signal, color: 'text-green-400', bg: 'bg-green-500/20', label: 'Strong' },
    fair: { icon: SignalLow, color: 'text-yellow-400', bg: 'bg-yellow-500/20', label: 'Fair' },
    poor: { icon: SignalZero, color: 'text-red-400', bg: 'bg-red-500/20', label: 'Weak' },
  };
  const info = config[quality] || config.good;
  const Icon = info.icon;
  return (
    <div className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full ${info.bg} backdrop-blur-md`}>
      <Icon className={`w-3.5 h-3.5 ${info.color}`} />
      <span className={`text-[10px] font-medium ${info.color}`}>{info.label}</span>
    </div>
  );
}

// ── Filter Presets — maps to WebGL shader keys in WebGLFilterEngine ──
const FILTER_PRESETS = [
  { name: 'None',         key: 'none',             icon: CircleDot, description: 'Original camera' },
  { name: 'Golden Hour',  key: 'goldenhour',        icon: Sunset,    description: 'Warm sunset vibes' },
  { name: 'Pipeline',     key: 'gopro',             icon: Waves,     description: 'Deep barrel shadows' },
  { name: 'Night Vision', key: 'nightvision',        icon: Eye,       description: 'Tactical green overlay' },
  { name: 'Pixelate',     key: 'pixelate',           icon: Grid,      description: 'Retro lo-fi aesthetic' },
  { name: 'Bio-Lum',      key: 'bioluminescence',    icon: Moon,      description: 'Neon glowing edges' },
  { name: 'Cyber-Surf',   key: 'cyber',              icon: Zap,       description: 'Hyper-cold glitch lens' },
];

// ── Theme colors for HairFilterPicker ───────────────────────────────
const CALL_COLORS = {
  overlayBg: 'bg-black/80 backdrop-blur-xl',
  border: 'border-white/10',
  buttonBg: 'bg-white/5 hover:bg-white/10',
  primaryText: 'text-white/90',
  secondaryText: 'text-white/50',
  accentText: 'text-cyan-400',
  accentBg: 'bg-cyan-500/20',
};

// ── Filter Picker panel ─────────────────────────────────────────────
const FilterPicker = ({ isOpen, onClose, activeFilter, onSelectFilter }) => {
  if (!isOpen) return null;
  return (
    <div 
      className="fixed left-3 top-20 w-60 max-h-[55vh] overflow-y-auto p-3 rounded-2xl bg-black/80 backdrop-blur-xl border border-white/10 z-[9999]"
      style={{ animation: 'slideInLeft 0.25s ease-out' }}
      onClick={(e) => e.stopPropagation()}
    >
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <Sparkles className="w-4 h-4 text-cyan-400" />
          <span className="text-sm font-medium text-white">Surf Filters</span>
        </div>
        <button onClick={onClose} className="p-1.5 rounded-full bg-white/10 hover:bg-white/20 transition-colors">
          <X className="w-4 h-4 text-white/70" />
        </button>
      </div>
      <div className="space-y-1">
        {FILTER_PRESETS.map((preset) => {
          const Icon = preset.icon;
          const isActive = activeFilter === preset.key;
          return (
            <button
              key={preset.key}
              onClick={() => onSelectFilter(preset.key)}
              className={`w-full flex items-center gap-3 p-2.5 rounded-xl transition-all ${
                isActive 
                  ? 'bg-gradient-to-r from-cyan-500/30 to-blue-500/20 border border-cyan-500/50 shadow-lg shadow-cyan-500/10' 
                  : 'bg-white/5 hover:bg-white/10 border border-transparent'
              }`}
            >
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${isActive ? 'bg-cyan-500/30' : 'bg-white/5'}`}>
                <Icon className={`w-4 h-4 ${isActive ? 'text-cyan-300' : 'text-white/60'}`} />
              </div>
              <div className="text-left">
                <span className={`text-xs font-medium block ${isActive ? 'text-cyan-300' : 'text-white/90'}`}>{preset.name}</span>
                <span className="text-[10px] text-white/40">{preset.description}</span>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

// ═══════════════════════════════════════════════════════════════════════
// MAIN COMPONENT
// ═══════════════════════════════════════════════════════════════════════
export default function InCallView({
  callType = 'audio',
  localStream,
  remoteStream,
  isMuted = false,
  isCameraOff = false,
  callDuration = 0,
  remoteUserInfo = {},
  connectionQuality = 'good',
  onToggleMute,
  onToggleCamera,
  onFlipCamera,
  facingMode = 'user',
  onEndCall,
  onReplaceVideoTrack,
}) {
  const localVideoRef = useRef(null);
  const remoteVideoRef = useRef(null);
  const webglCanvasRef = useRef(null);
  const webglProcessorRef = useRef(null);
  const hairCanvasRef = useRef(null);
  const hairEngineRef = useRef(null);
  const compositeCanvasRef = useRef(null);
  const compositeRafRef = useRef(null);

  const [isPipExpanded, setIsPipExpanded] = useState(true);
  const [showFilters, setShowFilters] = useState(false);
  const [showHairPicker, setShowHairPicker] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [activeFilter, setActiveFilter] = useState('none');
  const [activeHairStyle, setActiveHairStyle] = useState(null);
  const [speakerOff, setSpeakerOff] = useState(false);
  const speakerOffRef = useRef(false); // ref for use in effects without re-triggering
  const controlsTimeoutRef = useRef(null);

  // ── Attach local stream to hidden video element ───────────────────
  useEffect(() => {
    if (localVideoRef.current && localStream) {
      localVideoRef.current.srcObject = localStream;
      localVideoRef.current.play().catch(() => {});
    }
  }, [localStream]);

  // ── Attach remote stream to video element ─────────────────────────
  // iOS Safari CRITICAL FIX:
  //   1. Start the video element `muted` — iOS always allows muted autoplay
  //   2. Call play() — succeeds because muted
  //   3. Unmute AFTER play() resolves — audio now flows through WebRTC
  //   Without this sequence, iOS Safari blocks play() with NotAllowedError
  //   because the user gesture context from answerCall() has expired by the
  //   time the remote stream arrives via ICE negotiation.
  useEffect(() => {
    const videoEl = remoteVideoRef.current;
    if (!videoEl || !remoteStream) return;

    // Only re-set srcObject if the stream actually changed
    // (prevents iOS from interrupting playback on duplicate ontrack events)
    if (videoEl.srcObject !== remoteStream) {
      console.log('[InCallView] Attaching remote stream to video element');
      videoEl.srcObject = remoteStream;
    }

    // iOS Safari muted-autoplay-then-unmute pattern
    videoEl.muted = true;

    let retries = 0;
    const maxRetries = 8;
    const tryPlay = () => {
      videoEl.play().then(() => {
        console.log('[InCallView] ✅ Remote video playing (muted)');
        // Now unmute to hear audio — this works even outside user gesture
        // because the element is already playing
        setTimeout(() => {
          videoEl.muted = speakerOffRef.current;
          console.log('[InCallView] ✅ Remote audio unmuted, speakerOff:', speakerOffRef.current);
        }, 100); // Small delay ensures iOS processes the play state first
      }).catch((err) => {
        console.warn(`[InCallView] play() attempt ${retries + 1} failed:`, err.name, err.message);
        if (retries < maxRetries) {
          retries++;
          // Exponential backoff: 300, 600, 1200, 2400...
          setTimeout(tryPlay, Math.min(300 * Math.pow(2, retries - 1), 5000));
        } else {
          console.error('[InCallView] ❌ All play() retries exhausted — user may need to tap');
          // Last resort: unmute anyway, some browsers will start playing
          // when the user next interacts with the page
          videoEl.muted = speakerOffRef.current;
        }
      });
    };
    tryPlay();

    // When remote replaces their video track (camera toggle), nudge playback
    const handleTrackAdded = () => {
      console.log('[InCallView] Remote track added, nudging play()');
      videoEl.play().catch(() => {});
    };
    remoteStream.addEventListener('addtrack', handleTrackAdded);

    return () => {
      remoteStream.removeEventListener('addtrack', handleTrackAdded);
    };
  }, [remoteStream]);

  // ── Auto-hide controls after 4s ───────────────────────────────────
  const resetControlsTimer = useCallback(() => {
    setShowControls(true);
    clearTimeout(controlsTimeoutRef.current);
    controlsTimeoutRef.current = setTimeout(() => {
      if (!showFilters && !showHairPicker) setShowControls(false);
    }, 4000);
  }, [showFilters, showHairPicker]);

  useEffect(() => {
    resetControlsTimer();
    return () => clearTimeout(controlsTimeoutRef.current);
  }, []);

  // ── WebGL Filter Engine Lifecycle (same as GoLive) ────────────────
  // Initialize WebGL processor when local stream is available
  useEffect(() => {
    if (!localVideoRef.current || !webglCanvasRef.current || !localStream) return;

    const video = localVideoRef.current;
    const canvas = webglCanvasRef.current;

    // Wait for video metadata to load so we know dimensions
    const initWebGL = () => {
      canvas.width = video.videoWidth || 640;
      canvas.height = video.videoHeight || 480;

      try {
        const processor = new WebGLVideoProcessor(canvas);
        processor.setFilter(activeFilter === 'none' ? 'none' : activeFilter);
        processor.start(video);
        webglProcessorRef.current = processor;

        // Start a composite canvas that merges WebGL + hair, then send over WebRTC
        if (onReplaceVideoTrack) {
          try {
            if (!compositeCanvasRef.current) {
              compositeCanvasRef.current = document.createElement('canvas');
            }
            const comp = compositeCanvasRef.current;
            comp.width = canvas.width;
            comp.height = canvas.height;
            const ctx = comp.getContext('2d');

            // Composite render loop: WebGL canvas + hair canvas → 2D composite
            const compositeLoop = () => {
              ctx.clearRect(0, 0, comp.width, comp.height);
              ctx.drawImage(canvas, 0, 0, comp.width, comp.height);
              const hc = hairCanvasRef.current;
              if (hc && hc.width > 0 && hc.height > 0) {
                ctx.drawImage(hc, 0, 0, comp.width, comp.height);
              }
              compositeRafRef.current = requestAnimationFrame(compositeLoop);
            };
            compositeRafRef.current = requestAnimationFrame(compositeLoop);

            const compStream = comp.captureStream(30);
            const filteredTrack = compStream.getVideoTracks()[0];
            if (filteredTrack) {
              onReplaceVideoTrack(filteredTrack);
            }
          } catch (capErr) {
            console.warn('[InCallView] composite captureStream failed:', capErr);
          }
        }
      } catch (err) {
        console.error('[InCallView] WebGL init failed:', err);
      }
    };

    if (video.readyState >= 2) {
      initWebGL();
    } else {
      video.addEventListener('loadeddata', initWebGL, { once: true });
    }

    return () => {
      if (compositeRafRef.current) {
        cancelAnimationFrame(compositeRafRef.current);
        compositeRafRef.current = null;
      }
      if (webglProcessorRef.current) {
        webglProcessorRef.current.stop();
        webglProcessorRef.current = null;
      }
    };
  }, [localStream, onReplaceVideoTrack]); // Re-init when stream changes

  // ── Hair Filter Engine Lifecycle ──────────────────────────────────
  useEffect(() => {
    const engine = new HairFilterEngine();
    hairEngineRef.current = engine;
    engine.init().catch(() => {});
    return () => {
      engine.dispose();
      hairEngineRef.current = null;
    };
  }, []);

  // Start hair engine when local stream is available
  useEffect(() => {
    const engine = hairEngineRef.current;
    if (!engine || !localStream) return;
    const videoEl = localVideoRef.current;
    const hairCanvas = hairCanvasRef.current;
    if (videoEl && hairCanvas) {
      const tryStart = () => {
        if (videoEl.readyState >= 1) {
          engine.start(videoEl, hairCanvas);
          return true;
        }
        return false;
      };
      if (!tryStart()) {
        const timer = setInterval(() => {
          if (tryStart()) clearInterval(timer);
        }, 500);
        const timeout = setTimeout(() => clearInterval(timer), 5000);
        return () => { clearInterval(timer); clearTimeout(timeout); engine.stop(); };
      }
      return () => { engine.stop(); };
    }
  }, [localStream]);

  // Update hair style when selection changes
  useEffect(() => {
    const engine = hairEngineRef.current;
    if (engine) engine.setHairStyle(activeHairStyle);
  }, [activeHairStyle]);

  // ── Update WebGL filter when user selects a new one ───────────────
  useEffect(() => {
    if (webglProcessorRef.current) {
      webglProcessorRef.current.setFilter(activeFilter === 'none' ? 'none' : activeFilter);
    }
  }, [activeFilter]);

  // ── Filter selection handler (auto-closes picker) ─────────────────
  const handleSelectFilter = useCallback((key) => {
    setActiveFilter(key);
    setShowFilters(false);
  }, []);

  // ── Hair selection handler (auto-closes picker) ───────────────────
  const handleSelectHairStyle = useCallback((styleId) => {
    setActiveHairStyle(styleId);
    setShowHairPicker(false);
  }, []);

  // ── Control Button Component ──────────────────────────────────────
  const ControlButton = ({ onClick, active, danger, icon: Icon, label, size = 'normal' }) => {
    const sizeClass = size === 'large' ? 'w-14 h-14 md:w-16 md:h-16' : 'w-11 h-11 md:w-12 md:h-12';
    const iconSize = size === 'large' ? 'w-6 h-6 md:w-7 md:h-7' : 'w-5 h-5';
    return (
      <div className="flex flex-col items-center gap-1">
        <button
          onClick={onClick}
          className={`${sizeClass} rounded-full flex items-center justify-center transition-all duration-200 hover:scale-110 active:scale-95 ${
            danger 
              ? 'bg-red-500 hover:bg-red-400 shadow-lg shadow-red-500/30' 
              : active 
                ? 'bg-cyan-500/20 ring-2 ring-cyan-500/50 backdrop-blur-md' 
                : 'bg-white/10 hover:bg-white/20 backdrop-blur-md'
          }`}
        >
          <Icon className={`${iconSize} ${active ? 'text-cyan-400' : danger ? 'text-white' : 'text-white'}`} />
        </button>
        {label && <span className="text-[9px] md:text-[10px] text-white/50 font-medium">{label}</span>}
      </div>
    );
  };

  return (
    <div 
      className="fixed inset-0 z-[9998] flex items-center justify-center bg-zinc-950 select-none"
      onClick={resetControlsTimer}
    >

      <div className="relative w-full h-full md:w-[calc(100%-48px)] md:h-[calc(100%-48px)] md:max-w-[1100px] md:max-h-[700px] md:rounded-2xl overflow-hidden flex flex-col shadow-2xl shadow-black/50">

        {/* ── Video Area ── */}
        <div className="flex-1 relative overflow-hidden bg-black">
          {/* Remote video — ALWAYS rendered and "playing" so audio works.
              For audio-only calls: element is tiny/invisible but still decodes audio.
              display:none would stop audio playback in most browsers. */}
          <video
            ref={remoteVideoRef}
            autoPlay
            playsInline
            webkit-playsinline=""
            x-webkit-airplay="allow"
            className={`${(callType === 'video' && remoteStream) ? 'w-full h-full object-contain bg-zinc-950' : 'absolute'}`}
            style={(callType === 'video' && remoteStream) ? {} : {
              width: 1, height: 1, opacity: 0, pointerEvents: 'none',
              position: 'absolute', top: 0, left: 0,
            }}
          />
          {/* Audio-only fallback or waiting state */}
          {!(callType === 'video' && remoteStream) && (
            /* Audio-only: avatar + waveform */
            <div className="w-full h-full flex flex-col items-center justify-center"
              style={{
                background: 'radial-gradient(ellipse at 30% 20%, rgba(6,182,212,0.08) 0%, transparent 50%), radial-gradient(ellipse at 70% 80%, rgba(99,102,241,0.06) 0%, transparent 50%), linear-gradient(135deg, #0a0e1a 0%, #0d1f3c 40%, #0a1628 100%)',
              }}
            >
              <div className="relative">
                <div className="absolute inset-0 -m-4 rounded-full border-2 border-cyan-400/20 animate-ping" style={{ animationDuration: '2s' }} />
                <div className="absolute inset-0 -m-2 rounded-full border border-cyan-400/10" />
                <div className="w-28 h-28 md:w-32 md:h-32 rounded-full overflow-hidden ring-4 ring-cyan-400/30 shadow-[0_0_60px_rgba(6,182,212,0.2)]">
                  {remoteUserInfo.avatar ? (
                    <img src={remoteUserInfo.avatar} className="w-full h-full object-cover" alt="" />
                  ) : (
                    <div className="w-full h-full bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center">
                      <span className="text-3xl md:text-4xl text-white font-bold">
                        {remoteUserInfo.name?.charAt(0)?.toUpperCase() || '?'}
                      </span>
                    </div>
                  )}
                </div>
              </div>
              <h3 className="text-white text-lg md:text-xl font-semibold mt-5 mb-1">{remoteUserInfo.name || 'User'}</h3>
              <p className="text-white/40 text-sm mb-4">{callType === 'video' ? 'Connecting video…' : 'Audio Call'}</p>
              <div className="flex items-end gap-[3px] h-8">
                {[...Array(9)].map((_, i) => (
                  <div
                    key={i}
                    className="w-[3px] bg-gradient-to-t from-cyan-500 to-cyan-300 rounded-full"
                    style={{
                      height: `${8 + Math.random() * 24}px`,
                      animation: `waveform 0.6s ease-in-out ${i * 0.08}s infinite alternate`,
                    }}
                  />
                ))}
              </div>
            </div>
          )}

          {/* ── Top Overlay ── */}
          <div 
            className={`absolute top-0 left-0 right-0 transition-opacity duration-300 ${showControls ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
            style={{ background: 'linear-gradient(to bottom, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0.3) 60%, transparent 100%)' }}
          >
            <div className="flex items-center justify-between px-3 md:px-4 py-2.5 md:py-3">
              <div className="flex items-center gap-2 md:gap-3">
                <div className="flex items-center gap-1.5 px-2.5 py-1 md:px-3 md:py-1.5 rounded-full bg-white/10 backdrop-blur-md">
                  <div className="w-2 h-2 rounded-full bg-green-400 animate-pulse" />
                  <span className="text-white text-[11px] md:text-xs font-mono tabular-nums">
                    {formatDuration(callDuration)}
                  </span>
                </div>
                <ConnectionQualityBadge quality={connectionQuality} />
              </div>
              <span className="text-white/60 text-[11px] md:text-xs px-2 py-1 rounded-full bg-white/5 backdrop-blur-md">
                {callType === 'video' ? '📹 Video' : '🎙️ Audio'}
              </span>
            </div>

            {/* Remote user name bar */}
            <div className="px-3 md:px-4 pb-2">
              <div className="flex items-center gap-2">
                <div className="w-7 h-7 md:w-8 md:h-8 rounded-full overflow-hidden ring-2 ring-white/20">
                  {remoteUserInfo.avatar ? (
                    <img src={remoteUserInfo.avatar} className="w-full h-full object-cover" alt="" />
                  ) : (
                    <div className="w-full h-full bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center">
                      <span className="text-[10px] md:text-xs text-white font-bold">
                        {remoteUserInfo.name?.charAt(0)?.toUpperCase() || '?'}
                      </span>
                    </div>
                  )}
                </div>
                <span className="text-white text-sm font-medium">{remoteUserInfo.name || 'User'}</span>
              </div>
            </div>
          </div>

          {/* Side buttons removed — filter/hair toggles moved to bottom bar for always-visible access */}

          {/* ── Local Video PIP — positioned top-right to avoid overlap with controls on iPhone 16 ── */}
          {callType === 'video' && localStream && (
            <div 
              className={`absolute transition-all duration-300 overflow-hidden shadow-2xl cursor-pointer z-10 ${
                showControls ? 'opacity-100' : 'opacity-70'
