  const [expandedGrom, setExpandedGrom] = useState(null);
  const [_showCreditPayment, setShowCreditPayment] = useState(null); // tier_id or 'grom-{id}-{tier}'
  const [_creditPaymentInfo, setCreditPaymentInfo] = useState(null);

  useEffect(() => {
    if (user?.id) {
      fetchAccountBilling();
    }
  }, [user?.id]);

  const fetchAccountBilling = async () => {
    try {
      const response = await apiClient.get(`/subscriptions/account-billing/${user.id}`);
      setAccountData(response.data);
    } catch (error) {
      logger.error('Failed to fetch account billing:', error);
      toast.error('Failed to load account settings');
    } finally {
      setLoading(false);
    }
  };

  const handleStatusToggle = async (newStatus) => {
    setToggling(true);
    try {
      await apiClient.post(`/subscriptions/toggle-status/${user.id}`, {
        status: newStatus
      });
      toast.success(`Status changed to ${newStatus === 'competitive' ? 'Competitive' : 'Regular'} Surfer`);
      await fetchAccountBilling();
      if (refreshUser) refreshUser();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to update status');
    } finally {
      setToggling(false);
    }
  };

  const handleTierUpgrade = async (tierId, useCredits = false) => {
    // If using credits, first check if user can afford it
    if (useCredits) {
      setUpgrading(tierId);
      try {
        const response = await apiClient.post(`/subscriptions/pay-with-credits/${user.id}`, {
          tier_id: tierId,
          use_credits: true
        });
        
        if (response.data.insufficient_credits) {
          // Show insufficient credits dialog
          setCreditPaymentInfo(response.data);
          setShowCreditPayment(tierId);
          return;
        }
        
        toast.success(response.data.message);
        await fetchAccountBilling();
        if (refreshUser) refreshUser();
      } catch (error) {
        toast.error(error.response?.data?.detail || 'Failed to process credit payment');
      } finally {
        setUpgrading(null);
      }
      return;
    }
    
    // Standard Stripe checkout
    setUpgrading(tierId);
    try {
      const response = await apiClient.post(`/subscriptions/upgrade-tier/${user.id}`, {
        tier_id: tierId,
        origin_url: window.location.origin
      });
      
      if (response.data.checkout_url) {
        window.location.href = response.data.checkout_url;
      } else {
        toast.success(response.data.message);
        await fetchAccountBilling();
        if (refreshUser) refreshUser();
      }
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to process upgrade');
    } finally {
      setUpgrading(null);
    }
  };

  const handleGromTierChange = async (gromId, tierId, useCredits = false) => {
    const upgradeKey = `grom-${gromId}-${tierId}`;
    
    // If using credits for Grom subscription
    if (useCredits) {
      setUpgrading(upgradeKey);
      try {
        const response = await apiClient.post(`/subscriptions/grom-pay-with-credits/${user.id}`, {
          grom_id: gromId,
          tier_id: tierId,
          use_credits: true
        });
        
        if (response.data.insufficient_credits) {
          setCreditPaymentInfo(response.data);
          setShowCreditPayment(upgradeKey);
          return;
        }
        
        toast.success(response.data.message);
        await fetchAccountBilling();
      } catch (error) {
        toast.error(error.response?.data?.detail || 'Failed to process credit payment');
      } finally {
        setUpgrading(null);
      }
      return;
    }
    
    // Standard Stripe checkout for Grom
    setUpgrading(upgradeKey);
    try {
      const response = await apiClient.post(`/subscriptions/grom-tier/${user.id}`, {
        grom_id: gromId,
        tier_id: tierId,
        origin_url: window.location.origin
      });
      
      if (response.data.checkout_url) {
        window.location.href = response.data.checkout_url;
      } else {
        toast.success(response.data.message);
        await fetchAccountBilling();
      }
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to update Grom subscription');
    } finally {
      setUpgrading(null);
    }
  };

  const handleApplyForPro = async () => {
    setToggling(true);
    try {
      const response = await apiClient.post(`/subscriptions/apply-pro/${user.id}`);
      toast.success(response.data.message);
      await fetchAccountBilling();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to apply for Pro status');
    } finally {
      setToggling(false);
    }
  };

  const handleParentSurferMode = async (enabled) => {
    setToggling(true);
    try {
      await apiClient.post(`/subscriptions/parent-surfer-mode/${user.id}`, {
        active_surfer_mode: enabled
      });
      toast.success(`Active Surfer Mode ${enabled ? 'enabled' : 'disabled'}`);
      await fetchAccountBilling();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Failed to update mode');
    } finally {
      setToggling(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-cyan-400" />
      </div>
    );
  }

  if (!accountData) {
    return (
      <div className="text-center py-8 text-gray-400">
        <AlertCircle className="w-12 h-12 mx-auto mb-4" />
        <p>Failed to load account settings</p>
      </div>
    );
  }

  const isSurfer = ['Surfer', 'Comp Surfer', 'Pro'].includes(accountData.role);
  const isGromParent = accountData.role === ROLES.GROM_PARENT;
  const isPhotographer = ['Photographer', 'Hobbyist', 'Approved Pro'].includes(accountData.role);
  const isCompetitive = accountData.current_status === 'competitive';

  return (
    <div className="space-y-4" data-testid="account-billing-hub">
      {/* Surfer Status Toggle - Only for 18+ Surfers */}
      {isSurfer && (
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground flex items-center gap-2">
              <Trophy className="w-5 h-5 text-yellow-400" />
              Surfer Status
              {accountData.is_pending_pro && (
                <Badge className="ml-auto bg-yellow-500/20 text-yellow-400 border-yellow-500/30">
                  <Clock className="w-3 h-3 mr-1" />
                  Pro Pending
                </Badge>
              )}
              {accountData.is_approved_pro && (
                <Badge className="ml-auto bg-purple-500/20 text-purple-400 border-purple-500/30">
                  <Crown className="w-3 h-3 mr-1" />
                  Pro Verified
                </Badge>
              )}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-muted-foreground">
              Your identity in the surf community. Competitive status unlocks Tips, Sponsorship tabs, and Leaderboard placement.
            </p>
            
            <div className="flex items-center justify-between p-4 bg-muted rounded-lg">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-full ${isCompetitive ? 'bg-yellow-500/20' : 'bg-gray-500/20'}`}>
                  {isCompetitive ? (
                    <Trophy className="w-5 h-5 text-yellow-400" />
                  ) : (
                    <Waves className="w-5 h-5 text-gray-400" />
                  )}
                </div>
                <div>
                  <p className="font-medium text-foreground">
                    {isCompetitive ? 'Competitive Surfer' : 'Regular Surfer'}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {isCompetitive ? 'Tips, Sponsorship, Leaderboards active' : 'Standard surf experience'}
                  </p>
                </div>
              </div>
              <Switch
                checked={isCompetitive}
                onCheckedChange={(checked) => handleStatusToggle(checked ? 'competitive' : 'regular')}
                disabled={toggling || accountData.is_approved_pro}
                data-testid="surfer-status-toggle"
              />
            </div>

            {/* Apply for Pro - Only for Competitive Surfers not yet approved */}
            {isCompetitive && !accountData.is_approved_pro && !accountData.is_pending_pro && (
              <Button
                onClick={handleApplyForPro}
                disabled={toggling}
                className="w-full bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 text-white"
                data-testid="apply-pro-btn"
              >
                {toggling ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Crown className="w-4 h-4 mr-2" />}
                Apply for Pro Surfer Vetting
              </Button>
            )}

            {accountData.is_pending_pro && (
              <div className="p-3 bg-yellow-500/10 border border-yellow-500/30 rounded-lg">
                <p className="text-sm text-yellow-400">
                  <Clock className="w-4 h-4 inline mr-1" />
                  Your Pro application is under review. You have full Competitive access while pending.
                </p>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Parent-Surfer Hybrid Toggle */}
      {isGromParent && (
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground flex items-center gap-2">
              <Waves className="w-5 h-5 text-cyan-400" />
              Active Surfer Mode
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-muted-foreground">
              Enable to add your own surfer stats and athletic tracking to your profile. You can still manage your Grom's activities.
            </p>
            
            <div className="flex items-center justify-between p-4 bg-muted rounded-lg">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-full bg-cyan-500/20">
                  <Waves className="w-5 h-5 text-cyan-400" />
                </div>
                <div>
                  <p className="font-medium text-foreground">Active Surfer Mode</p>
                  <p className="text-xs text-muted-foreground">Track your own sessions & stats</p>
                </div>
              </div>
              <Switch
                checked={accountData.is_active_surfer}
                onCheckedChange={handleParentSurferMode}
                disabled={toggling}
                data-testid="parent-surfer-mode-toggle"
              />
            </div>
          </CardContent>
        </Card>
      )}

      {/* Plan Management - Uses centralized config as SINGLE SOURCE OF TRUTH */}
      <Card className="bg-card border-border overflow-hidden">
        <CardHeader>
          <CardTitle className="text-foreground flex items-center gap-2">
            <CreditCard className="w-5 h-5 text-green-400" />
            Your Plan
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4 overflow-hidden">
          <p className="text-sm text-muted-foreground">
            Manage your subscription tier. Higher tiers unlock more storage, lower commission rates, and Gold-Pass booking access.
          </p>

          {/* Current Plan Badge - from centralized config */}
          {(() => {
            const currentTierId = subscriptionTierToTierId(accountData.subscription_tier);
            const currentPlan = getPlanByTierId(currentTierId, isPhotographer ? 'photographer' : 'surfer');
            const TierIcon = currentPlan?.icon || CreditCard;
            
            return (
              <div className="p-4 bg-muted rounded-lg">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-full ${currentPlan?.bgColor || 'bg-gray-500/20'}`}>
                    <TierIcon className={`w-6 h-6 ${currentPlan?.iconColor || 'text-gray-400'}`} />
                  </div>
                  <div>
                    <p className="font-medium text-foreground">
                      {currentPlan?.name || 'Free'} Plan
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {currentPlan?.description}
                    </p>
                  </div>
                </div>
              </div>
            );
          })()}

          {/* Tier Options - from centralized config (mirrors Signup exactly) */}
          <div className="grid gap-3 w-full">
            {getPlansForRole(accountData.role).map((plan) => {
              const currentTierId = subscriptionTierToTierId(accountData.subscription_tier);
              const isCurrentTier = plan.tier_id === currentTierId;
              const TierIcon = plan.icon || CreditCard;
              const creditsRequired = Math.ceil(plan.price); // 1:1 ratio - 1 credit = $1
              const canAffordWithCredits = (user?.credit_balance || 0) >= creditsRequired;
              
              return (
                <div
                  key={plan.tier_id}
                  className={`p-3 rounded-lg border transition-all overflow-hidden ${
                    isCurrentTier 
                      ? 'border-cyan-500 bg-cyan-500/10' 
                      : 'border-border hover:border-cyan-500/50'
                  }`}
                  data-testid={`tier-option-${plan.tier_id}`}
                >
                  <div className="flex items-start justify-between gap-2 w-full">
                    <div className="flex items-start gap-2 min-w-0 flex-1">
                      <div className={`p-2 rounded-full flex-shrink-0 ${plan.bgColor}`}>
                        <TierIcon className={`w-4 h-4 ${plan.iconColor}`} />
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-1.5 flex-wrap">
                          <p className="font-medium text-foreground text-sm">{plan.name}</p>
                          {plan.badge && (
                            <Badge className="bg-yellow-500/20 text-yellow-400 text-[10px] px-1.5 py-0">
                              {plan.badge}
                            </Badge>
                          )}
                        </div>
                        <p className="text-[11px] text-muted-foreground truncate">
                          {plan.storage_gb === -1 ? 'Unlimited' : plan.storage_gb ? `${plan.storage_gb}GB` : '5GB'}
                          {plan.commission_rate && ` • ${Math.round(plan.commission_rate * 100)}%`}
                          {plan.gold_pass && ' • Gold'}
                        </p>
                      </div>
                    </div>
                    <div className="text-right flex-shrink-0 whitespace-nowrap">
                      {plan.price === 0 ? (
                        <span className="text-green-400 font-bold text-sm">Free</span>
                      ) : (
                        <>
                          <p className="text-foreground font-bold text-sm">${plan.price}/mo</p>
                          <p className="text-[11px] text-muted-foreground">{creditsRequired} cr</p>
                        </>
                      )}
                    </div>
                  </div>
                  
                  {/* Payment Options - only for non-current paid tiers */}
                  {!isCurrentTier && plan.price > 0 && (
                    <div className="mt-2 pt-2 border-t border-border flex gap-2 w-full">
                      <Button
                        onClick={() => handleTierUpgrade(plan.tier_id, false)}
                        disabled={upgrading === plan.tier_id}
                        className="flex-1 bg-cyan-500 hover:bg-cyan-600 text-black text-xs px-2"
                        size="sm"
                      >
                        {upgrading === plan.tier_id ? (
                          <Loader2 className="w-3 h-3 animate-spin" />
                        ) : (
                          <>
                            <CreditCard className="w-3 h-3 mr-1" />
                            Card
                          </>
                        )}
                      </Button>
                      <Button
                        onClick={() => handleTierUpgrade(plan.tier_id, true)}
                        disabled={upgrading === plan.tier_id}
                        variant="outline"
                        className={`flex-1 text-xs px-2 ${
                          canAffordWithCredits 
                            ? 'border-yellow-500/50 text-yellow-400 hover:bg-yellow-500/10' 
                            : 'border-border text-muted-foreground'
                        }`}
                        size="sm"
                      >
                        <Coins className="w-3 h-3 mr-1" />
                        {canAffordWithCredits ? 'Credits' : `+${creditsRequired - (user?.credit_balance || 0)}`}
                      </Button>
                    </div>
                  )}

                  {/* Free tier - instant switch */}
                  {!isCurrentTier && plan.price === 0 && (
                    <div className="mt-2 pt-2 border-t border-border">
                      <Button
                        onClick={() => handleTierUpgrade(plan.tier_id, false)}
                        disabled={upgrading === plan.tier_id}
                        className="w-full bg-green-500 hover:bg-green-600 text-white text-xs"
                        size="sm"
                      >
                        {upgrading === plan.tier_id ? (
                          <Loader2 className="w-3 h-3 animate-spin" />
                        ) : (
                          'Switch to Free'
                        )}
                      </Button>
                    </div>
                  )}

                  {/* Current tier indicator */}
                  {isCurrentTier && (
                    <div className="mt-2 pt-2 border-t border-border">
                      <Badge className="bg-cyan-500/20 text-cyan-400 w-full justify-center py-1 text-xs">
                        <Check className="w-3 h-3 mr-1" />
                        Current Plan
                      </Badge>
                    </div>
                  )}
                  
                  {/* Feature list - matches Signup exactly */}
                  {plan.popular && !isCurrentTier && (
                    <div className="mt-3 pt-3 border-t border-border">
                      <div className="flex flex-wrap gap-2">
                        {plan.features.filter(f => f.included && f.highlight).slice(0, 3).map((feature, idx) => (
                          <span key={idx} className="text-xs text-cyan-400 flex items-center gap-1">
                            <Check className="w-3 h-3" />
                            {feature.text}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          {/* Credit Balance Display */}
          <div className="p-3 bg-yellow-500/10 border border-yellow-500/30 rounded-lg">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-yellow-400">
                <Coins className="w-5 h-5" />
                <span className="font-medium">Stoked Credits</span>
              </div>
              <div className="text-right">
                <p className="font-bold text-yellow-400">{user?.credit_balance || 0} credits</p>
                <p className="text-xs text-muted-foreground">${(user?.credit_balance || 0).toFixed(2)} value</p>
              </div>
            </div>
            <Button
              variant="outline"
              size="sm"
              className="w-full mt-2 border-yellow-500/50 text-yellow-400 hover:bg-yellow-500/10"
              onClick={() => window.location.href = '/wallet'}
            >
              <Plus className="w-4 h-4 mr-1" />
              Add Credits
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Grom Management - Parent Only */}
      {isGromParent && accountData.linked_groms?.length > 0 && (
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground flex items-center gap-2">
              <Users className="w-5 h-5 text-purple-400" />
              Manage Grom Plans
              <Badge className="ml-auto bg-purple-500/20 text-purple-400">
                {accountData.linked_groms.length} Grom{accountData.linked_groms.length > 1 ? 's' : ''}
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-muted-foreground">
              Manage subscription plans for your linked Groms. You control their billing.
            </p>

            {accountData.linked_groms.map((grom) => (
              <div 
                key={grom.id} 
                className="p-4 bg-muted rounded-lg space-y-3"
                data-testid={`grom-card-${grom.id}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    {grom.avatar_url ? (
                      <img 
                        src={getFullUrl(grom.avatar_url)} 
                        alt={grom.full_name}
                        className="w-10 h-10 rounded-full object-cover"
                      />
                    ) : (
                      <div className="w-10 h-10 rounded-full bg-purple-500/20 flex items-center justify-center">
                        <UserPlus className="w-5 h-5 text-purple-400" />
                      </div>
                    )}
                    <div>
                      <p className="font-medium text-foreground">{grom.full_name}</p>
                      <div className="flex items-center gap-2">
                        <Badge variant="outline" className="text-xs">
                          {grom.subscription_tier || 'Free'}
                        </Badge>
                        {grom.elite_tier === 'grom_rising' && (
                          <Badge className="bg-yellow-500/20 text-yellow-400 text-xs">
                            <Trophy className="w-3 h-3 mr-1" />
                            Competes
                          </Badge>
                        )}
                      </div>
                    </div>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setExpandedGrom(expandedGrom === grom.id ? null : grom.id)}
                    className="border-border"
                  >
                    {expandedGrom === grom.id ? 'Close' : 'Change Plan'}
                  </Button>
                </div>

                {/* Expanded Tier Selection - Uses GROM_PLANS from config */}
                {expandedGrom === grom.id && (
                  <div className="grid gap-2 mt-3 pt-3 border-t border-border">
                    {GROM_PLANS.monthly.map((plan) => {
                      const gromTierId = subscriptionTierToTierId(grom.subscription_tier);
                      const isCurrentTier = plan.tier_id === gromTierId;
                      const isUpgrading = upgrading === `grom-${grom.id}-${plan.tier_id}`;
                      const TierIcon = plan.icon || CreditCard;
                      
                      return (
                        <button
                          key={plan.tier_id}
                          onClick={() => !isCurrentTier && handleGromTierChange(grom.id, plan.tier_id)}
                          disabled={isCurrentTier || isUpgrading}
                          className={`w-full p-3 rounded-lg border transition-all text-left flex items-center justify-between ${
                            isCurrentTier 
                              ? 'border-cyan-500 bg-cyan-500/10' 
                              : 'border-border hover:border-cyan-500/50'
                          }`}
                        >
                          <div className="flex items-center gap-2">
                            <TierIcon className={`w-4 h-4 ${plan.iconColor}`} />
                            <span className="text-foreground text-sm">{plan.name}</span>
                            {plan.badge && (
                              <Badge className="bg-purple-500/20 text-purple-400 text-xs">{plan.badge}</Badge>
                            )}
                          </div>
                          <div className="flex items-center gap-2">
                            {plan.price === 0 ? (
                              <span className="text-green-400 text-sm">Free</span>
                            ) : (
                              <span className="text-foreground text-sm">${plan.price}/mo</span>
                            )}
                            {isCurrentTier && <Check className="w-4 h-4 text-cyan-400" />}
                            {isUpgrading && <Loader2 className="w-4 h-4 animate-spin" />}
                          </div>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      {/* Photographer Status - For photographers */}
      {isPhotographer && (
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground flex items-center gap-2">
              <Trophy className="w-5 h-5 text-orange-400" />
              Photographer Status
              {accountData.is_approved_pro && (
                <Badge className="ml-auto bg-purple-500/20 text-purple-400 border-purple-500/30">
                  <Crown className="w-3 h-3 mr-1" />
                  Vetted Pro
                </Badge>
              )}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="p-4 bg-muted rounded-lg">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-full ${accountData.role === 'Hobbyist' ? 'bg-blue-500/20' : accountData.is_approved_pro ? 'bg-purple-500/20' : 'bg-orange-500/20'}`}>
                  {accountData.role === ROLES.HOBBYIST ? (
                    <Shield className="w-5 h-5 text-blue-400" />
                  ) : accountData.is_approved_pro ? (
                    <Crown className="w-5 h-5 text-purple-400" />
                  ) : (
                    <Trophy className="w-5 h-5 text-orange-400" />
                  )}
                </div>
                <div>
                  <p className="font-medium text-foreground">{accountData.role}</p>
                  <p className="text-xs text-muted-foreground">
                    {accountData.role === ROLES.HOBBYIST 
                      ? 'Earnings locked to Contribution Only (Groms, Gear, Causes)' 
                      : accountData.is_approved_pro 
                        ? 'Full Pro features with Bank Transfer enabled'
                        : 'Bank Transfer enabled. Apply for Pro vetting to unlock premium features'}
                  </p>
                </div>
              </div>
            </div>

            {/* Apply for Vetted Pro - Only for Working Photographers */}
            {accountData.role === ROLES.PHOTOGRAPHER && !accountData.is_approved_pro && (
              <Button
                onClick={handleApplyForPro}
                disabled={toggling}
                className="w-full bg-gradient-to-r from-orange-500 to-red-500 hover:from-orange-600 hover:to-red-600 text-white"
                data-testid="apply-pro-photographer-btn"
              >
                {toggling ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Crown className="w-4 h-4 mr-2" />}
                Apply for Vetted Pro Photographer
              </Button>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default AccountBillingHub;

﻿/**
 * AdCenterPanel - User's Ad Management Hub in Settings
 * - Create new ads
 * - View ad activity (submissions with status)
 * - View ad analytics (impressions, clicks, CTR)
 */
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import { 
  Megaphone, Plus, Activity, BarChart2, 
  Loader2, CheckCircle, Clock, XCircle, Eye, MousePointer, TrendingUp
} from 'lucide-react';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { CreateAdModal } from '../CreateAdModal';
import logger from '../../utils/logger';


export const AdCenterPanel = () => {
  const { user } = useAuth();
  const { theme } = useTheme();
  const _navigate = useNavigate();
  
  const [loading, setLoading] = useState(true);
  const [myAds, setMyAds] = useState({ ads: [], counts: {} });
  const [analytics, setAnalytics] = useState(null);
  const [showCreateAdModal, setShowCreateAdModal] = useState(false);
  const [activeTab, setActiveTab] = useState('overview'); // 'overview', 'activity', 'analytics'
  
  const isLight = theme === 'light';
  const textPrimary = isLight ? 'text-gray-900' : 'text-white';
  const textSecondary = isLight ? 'text-gray-600' : 'text-gray-400';
  const bgSecondary = isLight ? 'bg-gray-100' : 'bg-zinc-800';
  const borderClass = isLight ? 'border-gray-200' : 'border-zinc-700';

  useEffect(() => {
    if (user?.id) {
      fetchAdData();
    }
  }, [user?.id]);

  const fetchAdData = async () => {
    setLoading(true);
    try {
      // Fetch user's ads
      const adsRes = await apiClient.get(`/ads/my-submissions`);
      setMyAds(adsRes.data);
      
      // Fetch analytics
      try {
        const analyticsRes = await apiClient.get(`/ads/my-analytics`);
        setAnalytics(analyticsRes.data);
      } catch (e) {
        setAnalytics(null);
      }
    } catch (error) {
      logger.error('Failed to fetch ad data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    switch (status) {
      case 'pending':
        return <Badge className="bg-yellow-500/20 text-yellow-400"><Clock className="w-3 h-3 mr-1" /> Pending</Badge>;
      case 'approved':
        return <Badge className="bg-green-500/20 text-green-400"><CheckCircle className="w-3 h-3 mr-1" /> Active</Badge>;
      case 'rejected':
        return <Badge className="bg-red-500/20 text-red-400"><XCircle className="w-3 h-3 mr-1" /> Rejected</Badge>;
      default:
        return <Badge className="bg-zinc-500/20 text-zinc-400">{status}</Badge>;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="w-6 h-6 animate-spin text-purple-400" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Tab Buttons */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {[
          { id: 'overview', label: 'Overview', icon: Megaphone },
          { id: 'activity', label: 'Activity', icon: Activity },
          { id: 'analytics', label: 'Analytics', icon: BarChart2 },
        ].map((tab) => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg whitespace-nowrap transition-colors ${
                activeTab === tab.id
                  ? 'bg-purple-500/20 text-purple-400'
                  : `${bgSecondary} ${textSecondary} hover:text-purple-400`
              }`}
            >
              <Icon className="w-4 h-4" />
              {tab.label}
            </button>
          );
        })}
      </div>

      {/* Overview Tab */}
      {activeTab === 'overview' && (
        <div className="space-y-4">
          {/* Create Ad Button */}
          <Button
            onClick={() => setShowCreateAdModal(true)}
            className="w-full bg-purple-600 hover:bg-purple-700 h-12"
            data-testid="create-ad-btn"
          >
            <Plus className="w-5 h-5 mr-2" />
            Create New Ad
          </Button>

          {/* Ad Stats Summary */}
          <div className="grid grid-cols-3 gap-3">
            <div className={`${bgSecondary} rounded-xl p-3 text-center`}>
              <p className={`text-2xl font-bold ${textPrimary}`}>{myAds.counts?.pending || 0}</p>
              <p className={`text-xs ${textSecondary}`}>Pending</p>
            </div>
            <div className={`${bgSecondary} rounded-xl p-3 text-center`}>
              <p className={`text-2xl font-bold text-green-400`}>{myAds.counts?.approved || 0}</p>
              <p className={`text-xs ${textSecondary}`}>Active</p>
            </div>
            <div className={`${bgSecondary} rounded-xl p-3 text-center`}>
              <p className={`text-2xl font-bold text-red-400`}>{myAds.counts?.rejected || 0}</p>
              <p className={`text-xs ${textSecondary}`}>Rejected</p>
            </div>
          </div>

          {/* Quick Analytics */}
          {analytics && (
            <div className={`${bgSecondary} rounded-xl p-4`}>
              <h3 className={`font-medium ${textPrimary} mb-3 flex items-center gap-2`}>
                <TrendingUp className="w-4 h-4 text-purple-400" />
                Performance Overview
              </h3>
              <div className="grid grid-cols-3 gap-3">
                <div className="text-center">
                  <div className="flex items-center justify-center gap-1 mb-1">
                    <Eye className="w-4 h-4 text-blue-400" />
                    <span className={`text-lg font-bold ${textPrimary}`}>
                      {analytics.total_impressions?.toLocaleString() || 0}
                    </span>
                  </div>
                  <p className={`text-xs ${textSecondary}`}>Impressions</p>
                </div>
                <div className="text-center">
                  <div className="flex items-center justify-center gap-1 mb-1">
                    <MousePointer className="w-4 h-4 text-green-400" />
                    <span className={`text-lg font-bold ${textPrimary}`}>
                      {analytics.total_clicks?.toLocaleString() || 0}
                    </span>
                  </div>
                  <p className={`text-xs ${textSecondary}`}>Clicks</p>
                </div>
                <div className="text-center">
                  <div className="flex items-center justify-center gap-1 mb-1">
                    <TrendingUp className="w-4 h-4 text-purple-400" />
                    <span className={`text-lg font-bold ${textPrimary}`}>
                      {analytics.ctr?.toFixed(2) || 0}%
                    </span>
                  </div>
                  <p className={`text-xs ${textSecondary}`}>CTR</p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Activity Tab */}
      {activeTab === 'activity' && (
        <div className="space-y-3">
          {myAds.ads?.length === 0 ? (
            <div className={`text-center py-8 ${textSecondary}`}>
              <Megaphone className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p>No ads yet</p>
              <p className="text-sm">Create your first ad to get started</p>
            </div>
          ) : (
            myAds.ads.map((ad) => (
              <div 
                key={ad.id} 
                className={`${bgSecondary} rounded-xl p-4 border ${borderClass}`}
              >
                <div className="flex items-start justify-between mb-2">
                  <div className="flex-1">
                    <h4 className={`font-medium ${textPrimary}`}>{ad.headline}</h4>
                    <p className={`text-sm ${textSecondary} line-clamp-1`}>{ad.description}</p>
                  </div>
                  {getStatusBadge(ad.approval_status)}
                </div>
                <div className={`flex items-center gap-4 text-xs ${textSecondary}`}>
                  <span>Budget: ${ad.budget_credits || 0}</span>
                  <span>Impressions: {ad.impressions || 0}</span>
                  <span>Clicks: {ad.clicks || 0}</span>
                </div>
                {ad.rejection_reason && (
                  <p className="text-xs text-red-400 mt-2">
                    Reason: {ad.rejection_reason}
                  </p>
                )}
              </div>
            ))
          )}
        </div>
      )}

      {/* Analytics Tab */}
      {activeTab === 'analytics' && (
        <div className="space-y-4">
          {analytics ? (
            <>
              {/* Overall Stats */}
              <div className={`${bgSecondary} rounded-xl p-4`}>
                <h3 className={`font-medium ${textPrimary} mb-4`}>Overall Performance</h3>
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <Eye className="w-5 h-5 text-blue-400" />
                      <span className={textSecondary}>Total Impressions</span>
                    </div>
                    <span className={`font-bold ${textPrimary}`}>
                      {analytics.total_impressions?.toLocaleString() || 0}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <MousePointer className="w-5 h-5 text-green-400" />
                      <span className={textSecondary}>Total Clicks</span>
                    </div>
                    <span className={`font-bold ${textPrimary}`}>
                      {analytics.total_clicks?.toLocaleString() || 0}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <TrendingUp className="w-5 h-5 text-purple-400" />
                      <span className={textSecondary}>Click-Through Rate</span>
                    </div>
                    <span className={`font-bold ${textPrimary}`}>
                      {analytics.ctr?.toFixed(2) || 0}%
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <Megaphone className="w-5 h-5 text-yellow-400" />
                      <span className={textSecondary}>Total Spent</span>
                    </div>
                    <span className={`font-bold ${textPrimary}`}>
                      ${analytics.total_spent?.toFixed(2) || 0}
                    </span>
                  </div>
                </div>
              </div>

              {/* Per-Ad Performance */}
              {analytics.per_ad_stats?.length > 0 && (
                <div>
                  <h3 className={`font-medium ${textPrimary} mb-3`}>Per-Ad Performance</h3>
                  <div className="space-y-3">
                    {analytics.per_ad_stats.map((stat) => (
                      <div 
                        key={stat.id}
                        className={`${bgSecondary} rounded-lg p-3`}
                      >
                        <p className={`font-medium ${textPrimary} text-sm mb-2`}>{stat.headline}</p>
                        <div className="grid grid-cols-3 gap-2 text-xs">
                          <div>
                            <span className={textSecondary}>Views: </span>
                            <span className={textPrimary}>{stat.impressions || 0}</span>
                          </div>
                          <div>
                            <span className={textSecondary}>Clicks: </span>
                            <span className={textPrimary}>{stat.clicks || 0}</span>
                          </div>
                          <div>
                            <span className={textSecondary}>CTR: </span>
                            <span className={textPrimary}>{stat.ctr?.toFixed(2) || 0}%</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </>
          ) : (
            <div className={`text-center py-8 ${textSecondary}`}>
              <BarChart2 className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p>No analytics data yet</p>
              <p className="text-sm">Create and run ads to see performance metrics</p>
            </div>
          )}
        </div>
      )}

      {/* Create Ad Modal */}
      <CreateAdModal
        isOpen={showCreateAdModal}
        onClose={() => setShowCreateAdModal(false)}
        onSuccess={() => {
          setShowCreateAdModal(false);
          fetchAdData();
        }}
      />
    </div>
  );
};

export default AdCenterPanel;

﻿import React, { useState, useEffect } from 'react';
import { Bell, BellOff, Volume2, VolumeX, Mail, Clock, Loader2, Smartphone, MessageSquare, Heart, Camera, AlertTriangle, CheckCircle } from 'lucide-react';
import { Switch } from '../ui/switch';
import { Label } from '../ui/label';
import { toast } from 'sonner';
import apiClient, { BACKEND_URL } from '../../lib/apiClient';
import logger from '../../utils/logger';


/**
 * NotificationPreferences - Manage all notification settings
 * Features:
 * - Push notification type toggles (likes, comments, follows, etc.)
 * - In-app sound settings
 * - Digest mode (batch notifications)
 * - Email notification preferences
 */
export const NotificationPreferences = ({ userId, textPrimaryClass, textSecondaryClass, borderClass, _cardBgClass }) => {
  const [loading, setLoading] = useState(true);
  const [_saving, setSaving] = useState(false);
  const [preferences, setPreferences] = useState({
    // Push notification types
    push_enabled: true,
    push_likes: true,
    push_comments: true,
    push_follows: true,
    push_mentions: true,
    push_tags: true,
    push_messages: true,
    push_bookings: true,
    push_purchases: true,
    push_live: true,
    push_alerts: true,
    // Sound settings
    sound_enabled: true,
    vibration_enabled: true,
    // Digest mode
    digest_enabled: false,
    digest_frequency: 'daily', // 'hourly', 'daily', 'weekly'
    digest_time: '09:00',
    // Email preferences
    email_digest: false,
    email_marketing: false,
    email_updates: true
  });
  
  useEffect(() => {
    if (userId) {
      fetchPreferences();
    }
  }, [userId]);
  
  const fetchPreferences = async () => {
    try {
      const response = await apiClient.get(`/notifications/preferences`);
      if (response.data) {
        setPreferences(prev => ({ ...prev, ...response.data }));
      }
    } catch (error) {
      // Default preferences if none exist
      logger.debug('Using default notification preferences');
    } finally {
      setLoading(false);
    }
  };
  
  const updatePreference = async (key, value) => {
    const updated = { ...preferences, [key]: value };
    setPreferences(updated);
    
    try {
      await apiClient.put(`/notifications/preferences`, {
        [key]: value
      });
    } catch (error) {
      // Revert on error
      setPreferences(preferences);
      toast.error('Failed to save preference');
    }
  };
  
  const _saveAllPreferences = async () => {
    setSaving(true);
    try {
      await apiClient.put(`/notifications/preferences`, preferences);
      toast.success('Notification preferences saved');
    } catch (error) {
      toast.error('Failed to save preferences');
    } finally {
      setSaving(false);
    }
  };
  
  // Group toggle - toggle all in a category
  const toggleCategory = (keys, value) => {
    const updated = { ...preferences };
    keys.forEach(key => {
      updated[key] = value;
    });
    setPreferences(updated);
  };
  
  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="w-6 h-6 animate-spin text-cyan-400" />
      </div>
    );
  }
  
  // Notification type categories
  const pushCategories = [
    {
      title: 'Social',
      icon: Heart,
      color: 'text-pink-400',
      items: [
        { key: 'push_likes', label: 'Likes', desc: 'When someone likes your content' },
        { key: 'push_comments', label: 'Comments', desc: 'New comments on your posts' },
        { key: 'push_follows', label: 'Follows', desc: 'New followers' },
        { key: 'push_mentions', label: 'Mentions', desc: 'When you\'re mentioned' },
        { key: 'push_tags', label: 'Photo Tags', desc: 'When you\'re tagged in photos' }
      ]
    },
    {
      title: 'Messaging',
      icon: MessageSquare,
      color: 'text-blue-400',
      items: [
        { key: 'push_messages', label: 'Direct Messages', desc: 'New messages from friends' }
      ]
    },
    {
      title: 'Activity',
      icon: Camera,
      color: 'text-cyan-400',
      items: [
        { key: 'push_bookings', label: 'Bookings', desc: 'Session bookings and updates' },
        { key: 'push_purchases', label: 'Purchases', desc: 'Photo purchases and credits' },
        { key: 'push_live', label: 'Live Sessions', desc: 'When photographers go live' }
      ]
    },
    {
      title: 'Alerts',
      icon: AlertTriangle,
      color: 'text-yellow-400',
      items: [
        { key: 'push_alerts', label: 'Surf Alerts', desc: 'Surf condition alerts for saved spots' }
      ]
    }
  ];
  
  return (
    <div className="space-y-4">
      {/* Master Push Toggle */}
      <div className={`flex items-center justify-between p-4 rounded-lg bg-muted`}>
        <div className="flex items-center gap-3">
          {preferences.push_enabled ? (
            <Bell className="w-5 h-5 text-cyan-400" />
          ) : (
            <BellOff className="w-5 h-5 text-muted-foreground" />
          )}
          <div>
            <p className={textPrimaryClass}>Push Notifications</p>
            <p className={`text-xs ${textSecondaryClass}`}>
              {preferences.push_enabled ? 'Receiving notifications' : 'All notifications paused'}
            </p>
          </div>
        </div>
        <Switch
          checked={preferences.push_enabled}
          onCheckedChange={(checked) => updatePreference('push_enabled', checked)}
          data-testid="push-master-toggle"
        />
      </div>
      
      {/* Sound & Vibration */}
      <div className={`border ${borderClass} rounded-lg overflow-hidden`}>
        <div className={`px-4 py-3 bg-muted/50 ${borderClass} border-b`}>
          <p className={`font-medium ${textPrimaryClass}`}>Sound & Haptics</p>
        </div>
        <div className="p-4 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {preferences.sound_enabled ? (
                <Volume2 className="w-4 h-4 text-emerald-400" />
              ) : (
                <VolumeX className="w-4 h-4 text-muted-foreground" />
              )}
              <Label>Notification Sounds</Label>
            </div>
            <Switch
              checked={preferences.sound_enabled}
              onCheckedChange={(checked) => updatePreference('sound_enabled', checked)}
              data-testid="sound-toggle"
            />
          </div>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Smartphone className="w-4 h-4 text-purple-400" />
              <Label>Vibration</Label>
            </div>
            <Switch
              checked={preferences.vibration_enabled}
              onCheckedChange={(checked) => updatePreference('vibration_enabled', checked)}
              data-testid="vibration-toggle"
            />
          </div>
        </div>
      </div>
      
      {/* Push Notification Categories */}
      {preferences.push_enabled && (
        <div className="space-y-3">
          {pushCategories.map((category) => {
            const CategoryIcon = category.icon;
            const allEnabled = category.items.every(item => preferences[item.key]);
            
            return (
              <div key={category.title} className={`border ${borderClass} rounded-lg overflow-hidden`}>
                <button
                  onClick={() => toggleCategory(category.items.map(i => i.key), !allEnabled)}
                  className={`w-full px-4 py-3 flex items-center justify-between bg-muted/50 ${borderClass} border-b hover:bg-muted transition-colors`}
                >
                  <div className="flex items-center gap-2">
                    <CategoryIcon className={`w-4 h-4 ${category.color}`} />
                    <span className={`font-medium ${textPrimaryClass}`}>{category.title}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className={`text-xs ${textSecondaryClass}`}>
                      {allEnabled ? 'All on' : 'Some off'}
                    </span>
                    {allEnabled && <CheckCircle className="w-4 h-4 text-emerald-400" />}
                  </div>
                </button>
                <div className="p-4 space-y-3">
                  {category.items.map((item) => (
                    <div key={item.key} className="flex items-center justify-between">
                      <div>
                        <Label className="text-sm">{item.label}</Label>
                        <p className={`text-xs ${textSecondaryClass}`}>{item.desc}</p>
                      </div>
                      <Switch
                        checked={preferences[item.key]}
                        onCheckedChange={(checked) => updatePreference(item.key, checked)}
                        data-testid={`${item.key}-toggle`}
                      />
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
      
      {/* Digest Mode */}
      <div className={`border ${borderClass} rounded-lg overflow-hidden`}>
        <div className={`px-4 py-3 bg-muted/50 ${borderClass} border-b`}>
          <div className="flex items-center gap-2">
            <Clock className="w-4 h-4 text-orange-400" />
            <p className={`font-medium ${textPrimaryClass}`}>Digest Mode</p>
          </div>
          <p className={`text-xs ${textSecondaryClass} mt-1`}>
            Batch notifications instead of instant delivery
          </p>
        </div>
        <div className="p-4 space-y-4">
          <div className="flex items-center justify-between">
            <Label>Enable Digest</Label>
            <Switch
              checked={preferences.digest_enabled}
              onCheckedChange={(checked) => updatePreference('digest_enabled', checked)}
              data-testid="digest-toggle"
            />
          </div>
          
          {preferences.digest_enabled && (
            <>
              <div className="space-y-2">
                <Label className="text-sm">Frequency</Label>
                <div className="flex gap-2">
                  {['hourly', 'daily', 'weekly'].map((freq) => (
                    <button
                      key={freq}
                      onClick={() => updatePreference('digest_frequency', freq)}
                      className={`flex-1 py-2 rounded-lg text-sm capitalize transition-colors ${
                        preferences.digest_frequency === freq
                          ? 'bg-cyan-500 text-black'
                          : 'bg-muted hover:bg-muted/80'
                      }`}
                      data-testid={`digest-${freq}`}
                    >
                      {freq}
                    </button>
                  ))}
                </div>
              </div>
              
              {preferences.digest_frequency !== 'hourly' && (
                <div className="space-y-2">
                  <Label className="text-sm">Delivery Time</Label>
                  <select
                    value={preferences.digest_time}
                    onChange={(e) => updatePreference('digest_time', e.target.value)}
                    className="w-full p-2 rounded-lg bg-muted border border-border text-foreground"
                    data-testid="digest-time"
                  >
                    {['06:00', '09:00', '12:00', '15:00', '18:00', '21:00'].map((time) => (
                      <option key={time} value={time}>{time}</option>
                    ))}
                  </select>
                </div>
              )}
            </>
          )}
        </div>
      </div>
      
      {/* Email Preferences */}
      <div className={`border ${borderClass} rounded-lg overflow-hidden`}>
        <div className={`px-4 py-3 bg-muted/50 ${borderClass} border-b`}>
          <div className="flex items-center gap-2">
            <Mail className="w-4 h-4 text-blue-400" />
            <p className={`font-medium ${textPrimaryClass}`}>Email Notifications</p>
          </div>
        </div>
        <div className="p-4 space-y-3">
          <div className="flex items-center justify-between">
            <div>
              <Label className="text-sm">Daily Digest Email</Label>
              <p className={`text-xs ${textSecondaryClass}`}>Summary of your activity</p>
            </div>
            <Switch
              checked={preferences.email_digest}
              onCheckedChange={(checked) => updatePreference('email_digest', checked)}
              data-testid="email-digest-toggle"
            />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <Label className="text-sm">Product Updates</Label>
              <p className={`text-xs ${textSecondaryClass}`}>New features and improvements</p>
            </div>
            <Switch
              checked={preferences.email_updates}
              onCheckedChange={(checked) => updatePreference('email_updates', checked)}
              data-testid="email-updates-toggle"
            />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <Label className="text-sm">Marketing</Label>
              <p className={`text-xs ${textSecondaryClass}`}>Promotions and offers</p>
            </div>
            <Switch
              checked={preferences.email_marketing}
              onCheckedChange={(checked) => updatePreference('email_marketing', checked)}
              data-testid="email-marketing-toggle"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default NotificationPreferences;

/**
 * AuthContext.test.js
 * Tests for the AuthProvider and useAuth hook.
 * Covers: login, signup, logout, updateUser, refreshUser, token storage, impersonation.
 */

jest.mock('../lib/apiClient', () => ({
  get: jest.fn(),
  post: jest.fn(),
  put: jest.fn(),
  delete: jest.fn(),
  interceptors: {
    request: { use: jest.fn() },
    response: { use: jest.fn() },
  },
  defaults: { baseURL: 'http://test' },
}));

import React from 'react';
import { act, waitFor } from '@testing-library/react';
import { renderHook } from '@testing-library/react';
import { AuthProvider, useAuth } from './AuthContext';
import apiClient from '../lib/apiClient';

// Helper: wrap with AuthProvider
const wrapper = ({ children }) => <AuthProvider>{children}</AuthProvider>;

describe('AuthContext', () => {
  beforeEach(() => {
    localStorage.clear();
    jest.clearAllMocks();
  });

  // ── Initial state ────────────────────────────────────────────────────────────

  describe('initial state', () => {
    it('starts with user=null and loading=false when no localStorage', async () => {
      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));
      expect(result.current.user).toBeNull();
    });

    it('rehydrates user from localStorage on mount', async () => {
      const storedUser = { id: 'u1', email: 'test@test.com', access_token: 'tok123' };
      localStorage.setItem('raw-surf-user', JSON.stringify(storedUser));
      
      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));
      expect(result.current.user?.id).toBe('u1');
      expect(result.current.user?.access_token).toBe('tok123');
    });
  });

  // ── Login ────────────────────────────────────────────────────────────────────

  describe('login', () => {
    it('stores user + token in localStorage after successful login', async () => {
      const mockUser = { id: 'u1', email: 'test@test.com', access_token: 'jwt.signed.token', role: 'Surfer' };
      apiClient.post.mockResolvedValue({ data: mockUser });

      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));

      await act(async () => {
        await result.current.login('test@test.com', 'Password123!');
      });

      expect(result.current.user?.id).toBe('u1');
      expect(result.current.user?.access_token).toBe('jwt.signed.token');

      const stored = JSON.parse(localStorage.getItem('raw-surf-user'));
      expect(stored?.access_token).toBe('jwt.signed.token');
    });

    it('calls /auth/login with correct credentials', async () => {
      apiClient.post.mockResolvedValue({ data: { id: 'u1', access_token: 'tok' } });
      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));

      await act(async () => {
        await result.current.login('surfer@rawsurf.com', 'secret');
      });

      expect(apiClient.post).toHaveBeenCalledWith('/auth/login', {
        email: 'surfer@rawsurf.com',
        password: 'secret',
      });
    });
  });

  // ── Signup ───────────────────────────────────────────────────────────────────

  describe('signup', () => {
    it('stores user in localStorage and sets user state', async () => {
      const mockUser = { id: 'u2', email: 'new@rawsurf.com', role: 'Photographer', access_token: 'new.jwt' };
      apiClient.post.mockResolvedValue({ data: mockUser });

      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));

      await act(async () => {
        await result.current.signup('new@rawsurf.com', 'pass', 'New User', 'newuser', 'Photographer');
      });

      expect(result.current.user?.role).toBe('Photographer');
      const stored = JSON.parse(localStorage.getItem('raw-surf-user'));
      expect(stored?.email).toBe('new@rawsurf.com');
    });
  });

  // ── Logout ───────────────────────────────────────────────────────────────────

  describe('logout', () => {
    it('clears user state and removes all localStorage keys', async () => {
      const storedUser = { id: 'u1', access_token: 'tok' };
      localStorage.setItem('raw-surf-user', JSON.stringify(storedUser));
      localStorage.setItem('isGodMode', 'true');
      localStorage.setItem('impersonation_session', '{}');

      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));

      act(() => { result.current.logout(); });

      expect(result.current.user).toBeNull();
      expect(localStorage.getItem('raw-surf-user')).toBeNull();
      expect(localStorage.getItem('isGodMode')).toBeNull();
      expect(localStorage.getItem('impersonation_session')).toBeNull();
    });
  });

  // ── updateUser ───────────────────────────────────────────────────────────────

  describe('updateUser', () => {
    it('merges updates into user state and localStorage', async () => {
      const storedUser = { id: 'u1', username: 'old', access_token: 'tok' };
      localStorage.setItem('raw-surf-user', JSON.stringify(storedUser));

      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));

      act(() => { result.current.updateUser({ username: 'newusername', avatar_url: 'https://cdn.img/pic.jpg' }); });

      expect(result.current.user?.username).toBe('newusername');
      // Token must be preserved after update
      expect(result.current.user?.access_token).toBe('tok');
      const stored = JSON.parse(localStorage.getItem('raw-surf-user'));
      expect(stored?.username).toBe('newusername');
    });
  });

  // ── refreshUser ──────────────────────────────────────────────────────────────

  describe('refreshUser', () => {
    it('fetches fresh profile and merges into user without losing token', async () => {
      const storedUser = { id: 'u1', username: 'old', access_token: 'my.token' };
      localStorage.setItem('raw-surf-user', JSON.stringify(storedUser));
      apiClient.get.mockResolvedValue({ data: { id: 'u1', username: 'refreshed', avatar_url: 'http://img' } });

      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));

      await act(async () => { await result.current.refreshUser(); });

      expect(result.current.user?.username).toBe('refreshed');
      // Token must survive the refresh
      expect(result.current.user?.access_token).toBe('my.token');
    });

    it('returns null and does not crash if no user id', async () => {
      const { result } = renderHook(() => useAuth(), { wrapper });
      await waitFor(() => expect(result.current.loading).toBe(false));

      let res;
      await act(async () => { res = await result.current.refreshUser(); });
      expect(res).toBeNull();
      expect(apiClient.get).not.toHaveBeenCalled();
    });
  });

  // ── useAuth guard ──────────────────────────────────────────────────────────

  describe('useAuth guard', () => {
    it('throws if useAuth is called outside AuthProvider', () => {
      const spy = jest.spyOn(console, 'error').mockImplementation(() => {});
      expect(() => renderHook(() => useAuth())).toThrow('useAuth must be used within AuthProvider');
      spy.mockRestore();
    });
  });
});

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useAuth } from './AuthContext';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';


// Pricing Context for dynamic, reactive gallery pricing
const PricingContext = createContext(null);

export const usePricing = () => {
  const context = useContext(PricingContext);
  if (!context) {
    throw new Error('usePricing must be used within a PricingProvider');
  }
  return context;
};

/**
 * Smart Price Calculation Function
 * Priority order:
 * 1. Custom price (manual override on the item)
 * 2. Session price (if viewing items from an active session)
 * 3. Base price (photographer's general gallery pricing)
 */
export const calculateDisplayPrice = (mediaItem, sessionPricing, generalSettings, qualityTier = 'standard') => {
  // Rule 1: Custom price override takes priority
  if (mediaItem?.custom_price !== null && mediaItem?.custom_price !== undefined && mediaItem.custom_price > 0) {
    return {
      price: mediaItem.custom_price,
      source: 'custom',
      label: 'Fixed Price'
    };
  }

  // Rule 2: Session-specific pricing (for items from live sessions)
  if (sessionPricing?.is_active) {
    const isVideo = mediaItem?.media_type === 'video';
    const sessionPrice = isVideo ? sessionPricing.session_video_price : sessionPricing.session_photo_price;
    if (sessionPrice !== null && sessionPrice !== undefined) {
      return {
        price: sessionPrice,
        source: 'session',
        label: 'Session Price'
      };
    }
  }

  // Rule 3: Base price from general settings
  if (generalSettings) {
    const isVideo = mediaItem?.media_type === 'video';
    let basePrice;
    
    if (isVideo) {
      switch (qualityTier) {
        case '720p':
          basePrice = generalSettings.video_price_720p;
          break;
        case '1080p':
          basePrice = generalSettings.video_price_1080p;
          break;
        case '4k':
          basePrice = generalSettings.video_price_4k;
          break;
        default:
          basePrice = generalSettings.video_price_1080p;
      }
    } else {
      switch (qualityTier) {
        case 'web':
          basePrice = generalSettings.photo_price_web;
          break;
        case 'standard':
          basePrice = generalSettings.photo_price_standard;
          break;
        case 'high':
          basePrice = generalSettings.photo_price_high;
          break;
        default:
          basePrice = generalSettings.photo_price_standard;
      }
    }
    
    return {
      price: basePrice || mediaItem?.price || 5,
      source: 'base',
      label: 'Gallery Price'
    };
  }

  // Fallback to item's default price
  return {
    price: mediaItem?.price || 5,
    source: 'default',
    label: 'Default'
  };
};

export const PricingProvider = ({ children }) => {
  const { user } = useAuth();
  const [generalSettings, setGeneralSettings] = useState(null);
  const [sessionPricing, setSessionPricing] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lastUpdated, setLastUpdated] = useState(Date.now());

  // Fetch photographer's general pricing settings
  const fetchGeneralSettings = useCallback(async () => {
    if (!user?.id) return;
    
    const isPhotographer = ['Grom Parent', 'Hobbyist', 'Photographer', 'Approved Pro'].includes(user?.role);
    if (!isPhotographer) {
      setLoading(false);
      return;
    }

    try {
      const res = await apiClient.get(`/photographer/${user.id}/gallery-pricing`);
      const sp = res.data.session_pricing || {};
      const od = res.data.on_demand_pricing || {};
      const ls = res.data.live_session_pricing || {};
      const bk = res.data.booking_pricing || {};

      setGeneralSettings({
        // ── Gallery (general) pricing ──
        photo_price_web: res.data.photo_pricing?.web || 3,
        photo_price_standard: res.data.photo_pricing?.standard || 5,
        photo_price_high: res.data.photo_pricing?.high || 10,
        video_price_720p: res.data.video_pricing?.['720p'] || 8,
        video_price_1080p: res.data.video_pricing?.['1080p'] || 15,
        video_price_4k: res.data.video_pricing?.['4k'] || 30,

        // ── Session-level metadata (included counts, buy-in, etc.) ──
        on_demand_photo_price: sp.on_demand_photo_price || 10,
        on_demand_photos_included: sp.on_demand_photos_included || 3,
        on_demand_videos_included: sp.on_demand_videos_included || 0,
        on_demand_full_gallery: sp.on_demand_full_gallery || false,
        live_session_photo_price: sp.live_session_photo_price || 5,
        live_session_photos_included: sp.live_session_photos_included || 3,
        live_session_videos_included: sp.live_session_videos_included || 0,
        live_session_full_gallery: sp.live_session_full_gallery || false,
        live_buyin_price: sp.live_buyin_price || 25,
        booking_hourly_rate: sp.booking_hourly_rate || 50,
        booking_photos_included: sp.booking_photos_included || 3,
        booking_videos_included: sp.booking_videos_included || 0,
        booking_full_gallery: sp.booking_full_gallery || false,
        on_demand_hourly_rate: sp.on_demand_hourly_rate || 75,
        // Booking advanced settings (display-only in Gallery Hub)
        booking_min_hours: sp.booking_min_hours || 1,
        charges_travel_fees: sp.charges_travel_fees || false,
        service_radius_miles: sp.service_radius_miles || 25,
        group_discount_2_plus: sp.group_discount_2_plus || 0,
        group_discount_3_plus: sp.group_discount_3_plus || 0,
        group_discount_5_plus: sp.group_discount_5_plus || 0,

        // ── On-Demand independent resolution pricing ──
        on_demand_price_web: od.photo_web || 5,
        on_demand_price_standard: od.photo_standard || 10,
        on_demand_price_high: od.photo_high || 18,
        on_demand_video_720p: od.video_720p || 12,
        on_demand_video_1080p: od.video_1080p || 20,
        on_demand_video_4k: od.video_4k || 40,

        // ── Live Session independent resolution pricing ──
        live_price_web: ls.photo_web || 3,
        live_price_standard: ls.photo_standard || 6,
        live_price_high: ls.photo_high || 12,
        live_video_720p: ls.video_720p || 8,
        live_video_1080p: ls.video_1080p || 15,
        live_video_4k: ls.video_4k || 30,

        // ── Booking independent resolution pricing ──
        booking_price_web: bk.photo_web || 3,
        booking_price_standard: bk.photo_standard || 5,
        booking_price_high: bk.photo_high || 10,
        booking_video_720p: bk.video_720p || 8,
        booking_video_1080p: bk.video_1080p || 15,
        booking_video_4k: bk.video_4k || 30,
      });
      setLastUpdated(Date.now());
    } catch (e) {
      logger.error('Error fetching gallery pricing:', e);
    } finally {
      setLoading(false);
    }
  }, [user?.id, user?.role]);

  // Fetch active session pricing if photographer is live
  const fetchSessionPricing = useCallback(async () => {
    if (!user?.id) return;
    
    try {
      const res = await apiClient.get(`/photographer/${user.id}/active-session`);
      if (res.data && res.data.id) {
        setSessionPricing({
          is_active: true,
          session_id: res.data.id,
          session_photo_price: res.data.session_photo_price,
          session_video_price: res.data.session_video_price
        });
      } else {
        setSessionPricing({ is_active: false });
      }
    } catch (e) {
      setSessionPricing({ is_active: false });
    }
  }, [user?.id]);

  useEffect(() => {
    fetchGeneralSettings();
    fetchSessionPricing();
  }, [fetchGeneralSettings, fetchSessionPricing]);

  // Update pricing settings (called after photographer saves new prices)
  const updateGeneralSettings = useCallback(async (newSettings) => {
    try {
      await apiClient.put(`/photographer/${user.id}/gallery-pricing`, newSettings);
      // Merge new settings into existing state
      setGeneralSettings(prev => ({ ...prev, ...newSettings }));
      setLastUpdated(Date.now());
      return { success: true };
    } catch (error) {
      return { success: false, error: error.response?.data?.detail || 'Failed to update pricing' };
    }
  }, [user?.id]);

  // Set custom price for a single item
  const setItemCustomPrice = useCallback(async (itemId, customPrice) => {
    try {
      const res = await apiClient.patch(
        `/gallery/item/${itemId}/custom-price?photographer_id=${user.id}`,
        { custom_price: customPrice }
      );
      setLastUpdated(Date.now());
      return { success: true, data: res.data };
    } catch (error) {
      return { success: false, error: error.response?.data?.detail || 'Failed to set custom price' };
    }
  }, [user?.id]);

  // Clear custom price (revert to general pricing)
  const clearItemCustomPrice = useCallback(async (itemId) => {
    return setItemCustomPrice(itemId, 0);
  }, [setItemCustomPrice]);

  // Calculate display price for an item
  const getDisplayPrice = useCallback((mediaItem, qualityTier = 'standard') => {
    return calculateDisplayPrice(mediaItem, sessionPricing, generalSettings, qualityTier);
  }, [sessionPricing, generalSettings]);

  // Force refresh all pricing
  const refreshPricing = useCallback(() => {
    fetchGeneralSettings();
    fetchSessionPricing();
  }, [fetchGeneralSettings, fetchSessionPricing]);

  const value = {
    generalSettings,
    sessionPricing,
    loading,
    lastUpdated,
    updateGeneralSettings,
    setItemCustomPrice,
    clearItemCustomPrice,
    getDisplayPrice,
    refreshPricing,
    _refreshPricing: refreshPricing,
    calculateDisplayPrice: (item, tier) => calculateDisplayPrice(item, sessionPricing, generalSettings, tier)
  };

  return (
    <PricingContext.Provider value={value}>
      {children}
    </PricingContext.Provider>
  );
};

export default PricingContext;

import { useState, useCallback } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import { toast } from 'sonner';
import logger from '../utils/logger';


// Permission status enum
const PermissionStatus = {
  PENDING: 'PENDING',
  REQUESTING: 'REQUESTING',
  GRANTED: 'GRANTED',
  DENIED: 'DENIED',
  ERROR: 'ERROR'
};

import { getErrorMessage } from '../utils/errors';

/**
 * useGoLiveFlow - Custom hook for photographer go-live workflow
 * 
 * Manages:
 * - Permission flow (location → conditions modal)
 * - Session settings storage
 * - Go live API calls
 * - End session flow
 */
export const useGoLiveFlow = ({ userId, onGoLiveSuccess, onEndSessionSuccess }) => {
  // State
  const [goLiveSpotId, setGoLiveSpotId] = useState(null);
  const [goLiveSessionSettings, setGoLiveSessionSettings] = useState({});
  const [goLiveLoading, setGoLiveLoading] = useState(false);
  const [permissionStep, setPermissionStep] = useState(0);
  const [locationPermission, setLocationPermission] = useState(PermissionStatus.PENDING);
  const [userLocation, setUserLocation] = useState(null);
  
  // Modals
  const [showConditionsModal, setShowConditionsModal] = useState(false);
  const [showEndSessionModal, setShowEndSessionModal] = useState(false);
  const [endSessionLoading, setEndSessionLoading] = useState(false);
  const [currentLiveSession, setCurrentLiveSession] = useState(null);
  const [currentLiveSpot, setCurrentLiveSpot] = useState(null);

  // Debug logger
  const logPermissionStatus = useCallback((step, status, details = '') => {
    const timestamp = new Date().toISOString();
    logger.debug(`[GO_LIVE_FLOW ${timestamp}] Step: ${step}, Status: ${status}${details ? `, Details: ${details}` : ''}`);
  }, []);

  // Step 1: Request Location Permission
  const requestLocationPermission = useCallback(async () => {
    logPermissionStatus('LOCATION', PermissionStatus.REQUESTING);
    setPermissionStep(1);
    setLocationPermission(PermissionStatus.REQUESTING);
    
    try {
      if (!navigator.geolocation) {
        throw new Error('Geolocation not supported by browser');
      }
      
      const position = await new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: true,
          timeout: 10000,
          maximumAge: 0
        });
      });
      
      const { latitude, longitude } = position.coords;
      setUserLocation({ lat: latitude, lng: longitude });
      setLocationPermission(PermissionStatus.GRANTED);
      logPermissionStatus('LOCATION', PermissionStatus.GRANTED, `lat: ${latitude}, lng: ${longitude}`);
      
      return { lat: latitude, lng: longitude };
    } catch (error) {
      setLocationPermission(PermissionStatus.DENIED);
      logPermissionStatus('LOCATION', PermissionStatus.DENIED, error.message);
      
      if (error.code === 1) {
        toast.error('Location Access Required', {
          description: 'Please enable location in your browser settings to go live.'
        });
      } else {
        toast.error('Location Error', {
          description: error.message || 'Could not get your location'
        });
      }
      throw error;
    }
  }, [logPermissionStatus]);

  // Start Go Live Flow - Sequential permissions
  const startGoLiveFlow = useCallback(async (spotId, sessionSettings = {}) => {
    logPermissionStatus('GO_LIVE_FLOW', 'STARTED', `spotId: ${spotId}`);
    setGoLiveSpotId(spotId);
    setGoLiveSessionSettings(sessionSettings);
    setPermissionStep(0);
    
    try {
      // Step 1: Request Location
      await requestLocationPermission();
      
      // Step 2: Show the ConditionsModal (handles camera internally)
      setShowConditionsModal(true);
      logPermissionStatus('GO_LIVE_FLOW', 'CONDITIONS_MODAL_OPENED');
      
    } catch (error) {
      logPermissionStatus('GO_LIVE_FLOW', PermissionStatus.ERROR, error.message);
      setPermissionStep(0);
    }
  }, [requestLocationPermission, logPermissionStatus]);

  // Handle ConditionsModal confirm - convert media to base64 string
  const handleConditionsConfirm = useCallback(async ({ media, mediaType, spotNotes }, surfSpots = []) => {
    setGoLiveLoading(true);
    logPermissionStatus('CONDITIONS_CONFIRM', 'STARTING');
    
    try {
      // Convert media to base64 string for API - MUST be a string, not an object
      let mediaBase64 = null;
      
      if (media instanceof Blob) {
        // Convert Blob to base64 data URL
        mediaBase64 = await new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result);
          reader.onerror = () => reject(new Error('Failed to read media file'));
          reader.readAsDataURL(media);
        });
      } else if (typeof media === 'string') {
        // Already a string (e.g., data URL from previous capture)
        mediaBase64 = media;
      } else if (media && typeof media === 'object') {
        // Handle edge case where media might be an object with a URL
        // Try to extract a string value
        if (media.url && typeof media.url === 'string') {
          mediaBase64 = media.url;
        } else if (media.data && typeof media.data === 'string') {
          mediaBase64 = media.data;
        } else {
          logger.error('Media is an object but no valid string found:', media);
          throw new Error('Invalid media format - expected string or Blob');
        }
      }
      
      // Validate that we have a string
      if (mediaBase64 && typeof mediaBase64 !== 'string') {
        logger.error('Media conversion failed - result is not a string:', typeof mediaBase64);
        throw new Error('Media conversion failed');
      }
      
      // Go live at the spot with session settings and condition media
      const response = await apiClient.post(`/photographers/${userId}/go-live`, {
        spot_id: goLiveSpotId,
        is_streaming: false,
        condition_media: mediaBase64, // Now guaranteed to be a string
        condition_media_type: mediaType,
        spot_notes: spotNotes,
        // Include session settings
        price_per_join: goLiveSessionSettings.price_per_join || 25,
        max_surfers: goLiveSessionSettings.max_surfers || 10,
        auto_accept: goLiveSessionSettings.auto_accept !== false,
        estimated_duration: goLiveSessionSettings.estimated_duration || 2,
        live_photo_price: goLiveSessionSettings.live_photo_price || 5,
        photos_included: goLiveSessionSettings.photos_included || 3,
        general_photo_price: goLiveSessionSettings.general_photo_price || 10,
        // Resolution-based pricing (MANDATORY for all workflows)
        photo_price_web: goLiveSessionSettings.photo_price_web || 3,
        photo_price_standard: goLiveSessionSettings.photo_price_standard || 5,
        photo_price_high: goLiveSessionSettings.photo_price_high || 10
      });
      
      logPermissionStatus('CONDITIONS_CONFIRM', 'SUCCESS', response.data.message);
      toast.success(response.data.message);
      
      // Track current live spot
      const liveSpot = surfSpots.find(s => s.id === goLiveSpotId);
      setCurrentLiveSpot(liveSpot);
      
      // Cleanup
      setShowConditionsModal(false);
      setPermissionStep(0);
      setGoLiveSessionSettings({});
      
      // Callback
      onGoLiveSuccess?.(response.data);
      
    } catch (error) {
      logPermissionStatus('CONDITIONS_CONFIRM', PermissionStatus.ERROR, error.message);
      toast.error(getErrorMessage(error, 'Failed to go live'));
    } finally {
      setGoLiveLoading(false);
    }
  }, [goLiveSpotId, goLiveSessionSettings, userId, logPermissionStatus, onGoLiveSuccess]);

  // Show end session confirmation modal
  const handleStopLive = useCallback((currentUserShooting) => {
    const sessionData = currentUserShooting ? {
      location: currentUserShooting.current_spot_name || currentUserShooting.location,
      started_at: currentUserShooting.started_at || new Date().toISOString(),
      active_surfers: currentUserShooting.active_surfers || 0,
      participants: currentUserShooting.participants || [],
      earnings: currentUserShooting.earnings || 0
    } : null;
    
    setCurrentLiveSession(sessionData);
    setShowEndSessionModal(true);
  }, []);

  // Actual end session logic after confirmation
  const handleEndSessionConfirmed = useCallback(async () => {
    setEndSessionLoading(true);
    try {
      const response = await apiClient.post(`/photographers/${userId}/stop-live`, {});
      toast.success('Session ended! Check your Impacted dashboard for summary.');
      setShowEndSessionModal(false);
      
      // Pass session data to callback for review prompt
      const sessionData = {
        live_session_id: response.data?.live_session_id,
        total_surfers: response.data?.total_surfers || 0,
        gallery_id: response.data?.gallery_id,
        participants: currentLiveSession?.participants || [],
        duration_mins: response.data?.duration_mins || 0
      };
      
      setCurrentLiveSession(null);
      setCurrentLiveSpot(null);
      
      // Callback with session data (parent can show ReviewModal if duration >= 20 mins)
      onEndSessionSuccess?.(sessionData);
      
    } catch (error) {
      toast.error('Failed to end session');
    } finally {
      setEndSessionLoading(false);
    }
  }, [userId, onEndSessionSuccess, currentLiveSession]);

