  const closeConditionsModal = useCallback(() => {
    setShowConditionsModal(false);
    setGoLiveLoading(false);
  }, []);

  const closeEndSessionModal = useCallback(() => {
    setShowEndSessionModal(false);
  }, []);

  return {
    // State
    goLiveSpotId,
    goLiveLoading,
    permissionStep,
    locationPermission,
    userLocation,
    currentLiveSpot,
    currentLiveSession,
    
    // Modal visibility
    showConditionsModal,
    showEndSessionModal,
    endSessionLoading,
    
    // Actions
    startGoLiveFlow,
    handleConditionsConfirm,
    handleStopLive,
    handleEndSessionConfirmed,
    closeConditionsModal,
    closeEndSessionModal,
    setUserLocation,
    setCurrentLiveSpot,
  };
};

export default useGoLiveFlow;

﻿/**
 * useIPGeolocation - IP-based location fallback when GPS is denied
 * Features:
 * - Coastal Snap: Snaps inland IP locations to nearest coastline
 * - City Migration: Detects when user moves to a new city
 * - Session Persistence: Stores last known city for comparison
 */
import { useState, useEffect, useCallback } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';

const LAST_CITY_KEY = 'rawsurf_last_known_city';
const LAST_COORDS_KEY = 'rawsurf_last_known_coords';

export const useIPGeolocation = () => {
  const [ipLocation, setIpLocation] = useState(null);
  const [ipLoading, setIpLoading] = useState(false);
  const [ipError, setIpError] = useState(null);
  const [cityChanged, setCityChanged] = useState(false);
  const [coastalSnapped, setCoastalSnapped] = useState(false);

  /**
   * Get stored last known city from localStorage
   */
  const getLastKnownCity = useCallback(() => {
    try {
      return localStorage.getItem(LAST_CITY_KEY);
    } catch {
      return null;
    }
  }, []);

  /**
   * Store current city to localStorage
   */
  const storeCity = useCallback((city, lat, lng) => {
    try {
      localStorage.setItem(LAST_CITY_KEY, city);
      localStorage.setItem(LAST_COORDS_KEY, JSON.stringify({ lat, lng }));
    } catch (e) {
      logger.warn('Could not store city to localStorage:', e);
    }
  }, []);

  /**
   * Fetch IP-based geolocation with coastal snap support
   * @param {boolean} forceRefresh - Force recalibration even if cached
   */
  const fetchIPLocation = useCallback(async (forceRefresh = false) => {
    setIpLoading(true);
    setIpError(null);
    
    try {
      const lastCity = forceRefresh ? null : getLastKnownCity();
      
      const response = await apiClient.get(`/location/ip-geolocation`, {
        params: {
          coastal_snap: true,
          last_city: lastCity
        }
      });
      
      if (response.data.success && response.data.latitude && response.data.longitude) {
        const data = response.data;
        
        // CRITICAL: Validate coordinates are valid numbers
        const lat = parseFloat(data.latitude);
        const lng = parseFloat(data.longitude);
        
        if (isNaN(lat) || isNaN(lng) || !isFinite(lat) || !isFinite(lng)) {
          logger.error('[IP-GEO] Invalid coordinates from API:', data.latitude, data.longitude);
          setIpError('Invalid coordinates from IP geolocation');
          return null;
        }
        
        // Validate coordinate ranges
        if (lat < -90 || lat > 90 || lng < -180 || lng > 180) {
          logger.error('[IP-GEO] Coordinates out of range:', lat, lng);
          setIpError('Coordinates out of valid range');
          return null;
        }
        
        const location = {
          lat: lat,
          lng: lng,
          originalLat: parseFloat(data.original_latitude) || lat,
          originalLng: parseFloat(data.original_longitude) || lng,
          city: data.city,
          region: data.region,
          country: data.country,
          accuracy: data.accuracy || 'city',
          source: 'ip',
          isCoastal: data.is_coastal,
          coastalSnapped: data.coastal_snapped,
          snapInfo: data.snap_info,
          cityChanged: data.city_changed,
          previousCity: data.previous_city,
          migrationDetected: data.migration_detected
        };
        
        logger.debug(`[IP-GEO] Valid location: ${lat.toFixed(4)}, ${lng.toFixed(4)} (${data.city})`);
        
        setIpLocation(location);
        setCityChanged(data.city_changed || false);
        setCoastalSnapped(data.coastal_snapped || false);
        
        // CACHE PURGE: If city changed, clear all location-based caches
        // This prevents "Ghost Activity" from previous location
        if (data.city_changed || data.migration_detected) {
          logger.debug(`[IP-SYNC] City migration detected: ${data.previous_city} -> ${data.city}`);
          purgeLocationCache();
        }
        
        // Store current city for future migration detection
        if (data.city) {
          storeCity(data.city, data.latitude, data.longitude);
        }
        
        return location;
      } else {
        setIpError('IP geolocation unavailable');
        return null;
      }
    } catch (error) {
      logger.error('IP geolocation error:', error);
      setIpError(error.message);
      return null;
    } finally {
      setIpLoading(false);
    }
  }, [getLastKnownCity, storeCity]);

  /**
   * Force recalibration - used when user manually requests location update
   * (e.g., "Use Current IP Location" button)
   */
  const forceRecalibrate = useCallback(async () => {
    return fetchIPLocation(true);
  }, [fetchIPLocation]);

  /**
   * Clear stored city data
   */
  const clearStoredCity = useCallback(() => {
    try {
      localStorage.removeItem(LAST_CITY_KEY);
      localStorage.removeItem(LAST_COORDS_KEY);
    } catch {
      // Ignore errors
    }
  }, []);

  /**
   * Purge all location-based caches when city changes
   * Prevents "Ghost Activity" from previous location showing in drawer
   */
  const purgeLocationCache = useCallback(() => {
    try {
      // Clear spot-related caches
      const keysToRemove = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && (
          key.includes('spot_') ||
          key.includes('nearby_') ||
          key.includes('activity_') ||
          key.includes('photographer_') ||
          key.includes('geofence_')
        )) {
          keysToRemove.push(key);
        }
      }
      keysToRemove.forEach(key => localStorage.removeItem(key));
      
      // Also clear session storage
      sessionStorage.clear();
      
      logger.debug(`[CACHE-PURGE] Cleared ${keysToRemove.length} location cache entries`);
    } catch (e) {
      logger.warn('Cache purge error:', e);
    }
  }, []);

  // Auto-fetch on mount (Session Geo-Sync)
  useEffect(() => {
    fetchIPLocation();
  }, [fetchIPLocation]);

  return {
    // Location data
    ipLocation,
    ipLoading,
    ipError,
    
    // Coastal snap info
    coastalSnapped,
    
    // City migration
    cityChanged,
    
    // Actions
    refetchIPLocation: fetchIPLocation,
    forceRecalibrate,
    clearStoredCity
  };
};

export default useIPGeolocation;

/**
 * useLineupWebSocket - Real-time lineup updates hook
 * 
 * Connects to lineup WebSocket for real-time crew changes:
 * - crew_joined: New crew member joined
 * - crew_left: Crew member dropped out
 * - lineup_locked: Captain locked the lineup
 * - lineup_cancelled: Lineup was cancelled
 * - payment_received: Crew member paid their share
 * - lineup_status_changed: Session opened/closed
 */
import { useState, useEffect, useCallback, useRef } from 'react';
import { handleLineupNotification, processLineupWebSocketEvent } from '../services/LineupNotifications';
import logger from '../utils/logger';

const WS_BASE = process.env.REACT_APP_BACKEND_URL?.replace('https://', 'wss://').replace('http://', 'ws://');

export const useLineupWebSocket = (lineupId, userId, onUpdate) => {
  const [isConnected, setIsConnected] = useState(false);
  const wsRef = useRef(null);
  const reconnectTimeoutRef = useRef(null);
  const reconnectAttempts = useRef(0);
  const maxReconnectAttempts = 5;

  const connect = useCallback(() => {
    if (!lineupId || !userId || !WS_BASE) return;

    try {
      const wsUrl = `${WS_BASE}/api/ws/lineup/${lineupId}`;
      wsRef.current = new WebSocket(wsUrl);

      wsRef.current.onopen = () => {
        setIsConnected(true);
        reconnectAttempts.current = 0;
        logger.debug(`[LineupWS] Connected to lineup ${lineupId}`);
      };

      wsRef.current.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data);
          handleLineupUpdate(message);
        } catch (e) {
          logger.error('[LineupWS] Error parsing message:', e);
        }
      };

      wsRef.current.onclose = () => {
        setIsConnected(false);
        logger.debug(`[LineupWS] Disconnected from lineup ${lineupId}`);

        // Attempt reconnection
        if (reconnectAttempts.current < maxReconnectAttempts) {
          reconnectAttempts.current += 1;
          const delay = Math.min(1000 * Math.pow(2, reconnectAttempts.current), 30000);
          reconnectTimeoutRef.current = setTimeout(connect, delay);
        }
      };

      wsRef.current.onerror = (error) => {
        logger.error('[LineupWS] Error:', error);
      };
    } catch (e) {
      logger.error('[LineupWS] Connection error:', e);
    }
  }, [lineupId, userId]);

  const handleLineupUpdate = useCallback((message) => {
    if (message.type !== 'lineup_update') return;

    const { update_type, ...data } = message.data;

    // Process through the enhanced notification service
    const notificationEvent = processLineupWebSocketEvent(
      { type: mapUpdateTypeToEventType(update_type), data },
      userId
    );

    if (notificationEvent) {
      handleLineupNotification(notificationEvent.type, notificationEvent.data, {
        soundEnabled: true,
        pushEnabled: true
      });
    }

    // Call the update callback to refresh lineup data
    if (onUpdate) {
      onUpdate(message.data);
    }
  }, [onUpdate, userId]);

  // Map old update types to new event types
  const mapUpdateTypeToEventType = (updateType) => {
    const mapping = {
      'crew_joined': 'member_joined',
      'crew_left': 'member_left',
      'lineup_locked': 'lineup_status_changed',
      'lineup_cancelled': 'session_cancelled',
      'payment_received': 'payment_received',
      'status_changed': 'lineup_status_changed'
    };
    return mapping[updateType] || updateType;
  };

  // Ping to keep connection alive
  useEffect(() => {
    if (!isConnected || !wsRef.current) return;

    const pingInterval = setInterval(() => {
      if (wsRef.current?.readyState === WebSocket.OPEN) {
        wsRef.current.send('ping');
      }
    }, 30000);

    return () => clearInterval(pingInterval);
  }, [isConnected]);

  // Connect/disconnect based on lineupId
  useEffect(() => {
    connect();

    return () => {
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, [connect]);

  return { isConnected };
};


/**
 * useUserWebSocket - Personal user notifications hook
 * 
 * Receives personal notifications like:
 * - crew_dropout: A crew member left your lineup
 * - lineup_invite: You've been invited to a lineup
 * - status_changed: Session status changed
 */
export const useUserWebSocket = (userId, onNotification) => {
  const [isConnected, setIsConnected] = useState(false);
  const wsRef = useRef(null);

  useEffect(() => {
    if (!userId || !WS_BASE) return;

    try {
      const wsUrl = `${WS_BASE}/api/ws/user/${userId}`;
      wsRef.current = new WebSocket(wsUrl);

      wsRef.current.onopen = () => {
        setIsConnected(true);
        logger.debug(`[UserWS] Connected for user ${userId}`);
      };

      wsRef.current.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data);

          if (message.type === 'lineup_notification') {
            const { notification_type, ...data } = message.data;

            // Use enhanced notification service
            const notificationEvent = processLineupWebSocketEvent(
              { type: notification_type, data },
              userId
            );

            if (notificationEvent) {
              handleLineupNotification(notificationEvent.type, notificationEvent.data, {
                soundEnabled: true,
                pushEnabled: true
              });
            }

            if (onNotification) {
              onNotification(message.data);
            }
          }
        } catch (e) {
          logger.error('[UserWS] Error parsing message:', e);
        }
      };

      wsRef.current.onclose = () => {
        setIsConnected(false);
      };

      // Ping to keep alive
      const pingInterval = setInterval(() => {
        if (wsRef.current?.readyState === WebSocket.OPEN) {
          wsRef.current.send('ping');
        }
      }, 30000);

      return () => {
        clearInterval(pingInterval);
        if (wsRef.current) {
          wsRef.current.close();
        }
      };
    } catch (e) {
      logger.error('[UserWS] Connection error:', e);
    }
  }, [userId, onNotification]);

  return { isConnected };
};

export default useLineupWebSocket;

﻿import { useState, useCallback, useEffect } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';


/**
 * useMapData - Custom hook for fetching map data with Privacy Shield support
 * 
 * Manages:
 * - Surf spots with geofencing
 * - Live photographers
 * - Featured photographers
 * - Auto-refresh polling
 */
export const useMapData = (userId = null, userLocation = null) => {
  const [surfSpots, setSurfSpots] = useState([]);
  const [livePhotographers, setLivePhotographers] = useState([]);
  const [featuredPhotographers, setFeaturedPhotographers] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchSurfSpots = useCallback(async (viewport = null) => {
    try {
      // Build query params for Privacy Shield geofencing
      const params = new URLSearchParams();
      
      if (userId) {
        params.append('user_id', userId);
      }
      
      if (userLocation?.lat && userLocation?.lng) {
        params.append('user_lat', userLocation.lat);
        params.append('user_lon', userLocation.lng);
      }
      
      // Viewport filtering for performance
      if (viewport) {
        params.append('viewport_only', 'true');
        params.append('min_lat', viewport.minLat);
        params.append('max_lat', viewport.maxLat);
        params.append('min_lon', viewport.minLng);
        params.append('max_lon', viewport.maxLng);
      }
      
      const url = `/surf-spots${params.toString() ? '?' + params.toString() : ''}`;
      const response = await apiClient.get(url);
      setSurfSpots(response.data);
    } catch (error) {
      logger.error('Error fetching surf spots:', error);
    }
  }, [userId, userLocation]);

  const fetchLivePhotographers = useCallback(async () => {
    try {
      const response = await apiClient.get(`/live-photographers`);
      setLivePhotographers(response.data);
    } catch (error) {
      logger.error('Error fetching live photographers:', error);
    }
  }, []);

  const fetchFeaturedPhotographers = useCallback(async () => {
    try {
      const response = await apiClient.get(`/photographers/featured`);
      setFeaturedPhotographers(response.data);
    } catch (error) {
      logger.error('Error fetching featured photographers:', error);
    }
  }, []);

  const loadMapData = useCallback(async (viewport = null) => {
    setLoading(true);
    await Promise.all([
      fetchSurfSpots(viewport),
      fetchLivePhotographers(),
      fetchFeaturedPhotographers()
    ]);
    setLoading(false);
  }, [fetchSurfSpots, fetchLivePhotographers, fetchFeaturedPhotographers]);

  // Initial load and auto-refresh
  useEffect(() => {
    loadMapData();
    
    // Refresh live photographers and surf spots every 30 seconds
    const interval = setInterval(() => {
      fetchLivePhotographers();
      fetchSurfSpots();
    }, 30000);
    
    return () => clearInterval(interval);
  }, [loadMapData, fetchLivePhotographers, fetchSurfSpots]);

  return {
    surfSpots,
    livePhotographers,
    featuredPhotographers,
    loading,
    refreshData: loadMapData,
    fetchLivePhotographers,
    fetchSurfSpots,
  };
};

export default useMapData;

﻿/**
 * useOfflineMode - React hook for managing offline spot data
 * 
 * Features:
 * - Detect online/offline status
 * - Cache spot data for offline access
 * - Auto-sync based on location and favorite spots
 * - Sync when back online
 * - LocalStorage fallback for older browsers
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import apiClient, { BACKEND_URL } from '../lib/apiClient';
import logger from '../utils/logger';

const SPOTS_STORAGE_KEY = 'rawsurf_cached_spots';
const NEARBY_SPOTS_KEY = 'rawsurf_nearby_spots';
const FAVORITE_SPOTS_KEY = 'rawsurf_favorite_spots';
const CACHE_TIMESTAMP_KEY = 'rawsurf_spots_cache_time';
const AUTO_SYNC_KEY = 'rawsurf_auto_sync_enabled';

export const useOfflineMode = () => {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [spotsCached, setSpotsCached] = useState(false);
  const [nearbyCached, setNearbyCached] = useState(false);
  const [cacheTimestamp, setCacheTimestamp] = useState(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [autoSyncEnabled, setAutoSyncEnabled] = useState(false);
  const [lastSyncLocation, setLastSyncLocation] = useState(null);
  const locationWatchRef = useRef(null);

  // Listen for online/offline events
  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      logger.debug('[OfflineMode] Back online');
      // Auto-sync when back online if enabled
      if (autoSyncEnabled) {
        syncNearbySpots();
      }
    };
    
    const handleOffline = () => {
      setIsOnline(false);
      logger.debug('[OfflineMode] Gone offline');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Check existing cache and settings
    checkCacheStatus();
    loadAutoSyncSetting();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      if (locationWatchRef.current) {
        navigator.geolocation.clearWatch(locationWatchRef.current);
      }
    };
  }, []);

  // Load auto-sync setting from localStorage
  const loadAutoSyncSetting = useCallback(() => {
    const saved = localStorage.getItem(AUTO_SYNC_KEY);
    if (saved === 'true') {
      setAutoSyncEnabled(true);
      startLocationTracking();
    }
  }, []);

  // Check if spots are cached in localStorage
  const checkCacheStatus = useCallback(() => {
    const cachedSpots = localStorage.getItem(SPOTS_STORAGE_KEY);
    const nearbySpots = localStorage.getItem(NEARBY_SPOTS_KEY);
    const timestamp = localStorage.getItem(CACHE_TIMESTAMP_KEY);
    
    if (cachedSpots && timestamp) {
      setSpotsCached(true);
      setCacheTimestamp(new Date(parseInt(timestamp)));
    } else {
      setSpotsCached(false);
      setCacheTimestamp(null);
    }
    
    setNearbyCached(!!nearbySpots);
