      startLocationTracking();
      // Immediately sync if online
      if (isOnline) {
        syncNearbySpots();
      }
    } else {
      if (locationWatchRef.current) {
        navigator.geolocation.clearWatch(locationWatchRef.current);
        locationWatchRef.current = null;
      }
    }
    
