          }
        });
      } catch { /* stats collection is non-critical */ }
    }, 5000);
  };

  // ── Cleanup ──────────────────────────────────────────────────────
  const cleanup = useCallback(() => {
    // Stop local media tracks
    localStreamRef.current?.getTracks().forEach(track => track.stop());
    localStreamRef.current = null;
    remoteStreamRef.current = null;

    // Close peer connection
    if (peerConnection.current?.close) {
      peerConnection.current.close();
    }
    peerConnection.current = null;

    // Clear timers
    clearInterval(callTimerRef.current);
    clearInterval(statsIntervalRef.current);
    if (callRetryRef.current) { clearTimeout(callRetryRef.current); callRetryRef.current = null; }
    pendingOfferRef.current = null;
    callRetryCountRef.current = 0;
    earlyIceCandidatesRef.current = [];

    // Reset state
    setCallState(CALL_STATE.IDLE);
    setCallType(null);
    setLocalStream(null);
    setRemoteStream(null);
    setIsMuted(false);
    setIsCameraOff(false);
    setCallDuration(0);
    setRemoteUserInfo(null);
    setConnectionQuality('good');
  }, []);

  // Replace the video track on the peer connection (for WebGL filtered canvas stream)
  const replaceVideoTrack = useCallback((newVideoTrack) => {
    const pc = peerConnection.current;
    if (!pc || !newVideoTrack) return;
    
    const senders = pc.getSenders();
    const videoSender = senders.find(s => s.track && s.track.kind === 'video');
    if (videoSender) {
      videoSender.replaceTrack(newVideoTrack)
        .then(() => console.log('[WebRTC] ✅ Video track replaced with filtered canvas track'))
        .catch(err => console.error('[WebRTC] Failed to replace video track:', err));
    } else {
      console.warn('[WebRTC] No video sender found to replace track on');
    }
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  // Listen for custom events from MessagesPage call buttons
  useEffect(() => {
    const handleStartCall = (e) => {
      const { targetUserId, callType: type, targetUserName, targetUserAvatar } = e.detail;
      startCall(targetUserId, type, { name: targetUserName, avatar: targetUserAvatar });
    };
    window.addEventListener('rawsurf:startCall', handleStartCall);
    return () => window.removeEventListener('rawsurf:startCall', handleStartCall);
  }, [startCall]);

  return {
    // State
    callState,
    callType,
    localStream,
    remoteStream,
    isMuted,
    isCameraOff,
    callDuration,
    remoteUserInfo,
    connectionQuality,
    permissionDenied,
    // Actions
    startCall,
    answerCall,
    declineCall,
    endCall,
    toggleMute,
    toggleCamera,
    flipCamera,
    facingMode,
    replaceVideoTrack,
    dismissPermissionModal: () => setPermissionDenied(false),
    retryAfterPermission: () => {
      setPermissionDenied(false);
      toast.success('Permissions updated! Try your call again.', { duration: 3000 });
    },
  };
}

/**
 * apiClient.test.js
 * Tests for the shared Axios instance: Bearer token injection, error handling.
 */
import axios from 'axios';

// We test the interceptor behavior by mocking localStorage and checking requests
describe('apiClient', () => {
  const BACKEND_URL = 'https://api.rawsurf.com';

  beforeEach(() => {
    // Set the env var
    process.env.REACT_APP_BACKEND_URL = BACKEND_URL;
    // Clear localStorage before each test
    localStorage.clear();
    // Clear module cache so interceptors are fresh
    jest.resetModules();
  });

  describe('BACKEND_URL and API_BASE exports', () => {
    it('exports BACKEND_URL from env var', () => {
      const { BACKEND_URL: url } = require('./apiClient');
      expect(url).toBe(BACKEND_URL);
    });

    it('exports API_BASE as BACKEND_URL + /api', () => {
      const { API_BASE } = require('./apiClient');
      expect(API_BASE).toBe(`${BACKEND_URL}/api`);
    });
  });

  describe('Bearer token injection', () => {
    it('injects Authorization header when user has access_token in localStorage', async () => {
      const mockUser = {
        id: 'user-123',
        email: 'test@example.com',
        access_token: 'eyJhbGciOiJIUzI1NiJ9.test.token',
      };
      localStorage.setItem('raw-surf-user', JSON.stringify(mockUser));

      // Re-import to get fresh interceptors
      const { default: client } = require('./apiClient');

      // Mock the actual HTTP call
      const mockAdapter = jest.fn().mockResolvedValue({
        status: 200,
        data: {},
        headers: {},
        config: {},
      });

      // Intercept the request config before it goes out
      let capturedConfig = null;
      client.interceptors.request.use((config) => {
        capturedConfig = config;
        throw new axios.Cancel('stop'); // Short-circuit the request
      });

      try {
        await client.get('/test');
      } catch (e) {
        // Expected cancel
      }

      if (capturedConfig) {
        expect(capturedConfig.headers['Authorization']).toMatch(/^Bearer /);
      }
    });

    it('does not inject Authorization header when no user in localStorage', async () => {
      // No user stored
      const { default: client } = require('./apiClient');

      let capturedConfig = null;
      client.interceptors.request.use((config) => {
        capturedConfig = config;
        throw new axios.Cancel('stop');
      });

      try {
        await client.get('/test');
      } catch (e) {
        // Expected cancel
      }

      if (capturedConfig) {
        expect(capturedConfig.headers['Authorization']).toBeUndefined();
      }
    });

    it('silently skips malformed localStorage JSON', async () => {
      localStorage.setItem('raw-surf-user', 'NOT_VALID_JSON{{{{');
      const { default: client } = require('./apiClient');

      let error = null;
      client.interceptors.request.use(
        (config) => { throw new axios.Cancel('stop'); },
        (err) => { error = err; }
      );

      try {
        await client.get('/test');
      } catch (e) {
        // Expected cancel
      }

      // Should not throw a JSON parse error
      expect(error).toBeNull();
    });
  });

  describe('baseURL config', () => {
    it('uses REACT_APP_BACKEND_URL + /api as base', () => {
      const { default: client } = require('./apiClient');
      expect(client.defaults.baseURL).toBe(`${BACKEND_URL}/api`);
    });

    it('has 30s timeout configured', () => {
      const { default: client } = require('./apiClient');
      expect(client.defaults.timeout).toBe(30000);
    });
  });
});

